def _parse_debug_args() -> None:
    """Parst Kommandozeilenargumente für Debug‑Level und Quiet‑Mode."""
    global DEBUG_LEVEL, QUIET_MODE
    for arg in sys.argv[1:]:
        if arg in ("--quiet", "-q"):
            QUIET_MODE = True
            continue
        if arg == "--debug":
            DEBUG_LEVEL = max(DEBUG_LEVEL, 1)
            continue
        if arg.startswith("--debug="):
            value = arg.split("=", 1)[1]
            if not value:
                continue
            if value.isdigit():
                DEBUG_LEVEL = max(DEBUG_LEVEL, int(value))
                continue
            if value == "all":
                DEBUG_LEVEL = max(DEBUG_LEVEL, 3)
                if "all" not in DEBUG_COMPONENTS:
                    DEBUG_COMPONENTS.append("all")
                continue
            parts = [p.strip() for p in value.split(",") if p.strip()]
            for comp in parts:
                if comp not in DEBUG_COMPONENTS:
                    DEBUG_COMPONENTS.append(comp)


_parse_debug_args()


def _safe_kill(proc, name: str) -> None:
    """Sicherer Prozess-Kill mit Fehlerbehandlung.

    Args:
        proc: subprocess.Popen-Objekt oder None
        name: Name des Prozesses für Logging

    """
    if proc is None:
        return
    try:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=2.0)
            except subprocess.TimeoutExpired:
                proc.kill()
    except Exception as e:
        try:
            logger.debug("Fehler beim Beenden von %s: %s", name, e)
        except Exception:
            print(f"Fehler beim Beenden von {name}: {e}", file=sys.stderr)


def _log_stderr(proc, name: str) -> str:
    """Liest und loggt die stderr-Ausgabe eines Prozesses."""
    if proc is None or proc.stderr is None:
        return ""
    try:
        stderr = proc.stderr.read().decode("utf-8", errors="replace")
        if stderr:
            logger.debug("%s stderr: %s", name, stderr[:500])
        return stderr
    except Exception as e:
        logger.debug("Fehler beim Lesen von %s stderr: %s", name, e)
        return ""


class SafeComponentFormatter(logging.Formatter):
    """Formatter, der sicherstellt, dass 'component' immer existiert."""

    def format(self, record: logging.LogRecord) -> str:
        if not hasattr(record, "component"):
            record.component = ""
        return super().format(record)


