def _is_containerized() -> bool:
    """Erkennt, ob wir in einem Container laufen."""
    if os.path.exists("/.dockerenv"):
        return True
    if "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ:
        return True
    if "SNAP" in os.environ or "SNAP_NAME" in os.environ:
        return True
    try:
        with open("/proc/1/cgroup") as f:
            for line in f:
                if "docker" in line or "lxc" in line:
                    return True
    except (OSError, PermissionError) as e:
        logger.debug("Container-Erkennung fehlgeschlagen (cgroup nicht lesbar): %s", e)
    except Exception as e:
        logger.debug("Unerwarteter Fehler bei Container-Erkennung: %s", e)
    return False


