def _normalize_int(
    value: Any,
    min_val: int = 0,
    max_val: int = 86400,
    default: int = 30,
) -> int:
    """Normalisiert einen Integer-Wert mit Bereichsprüfung."""
    try:
        val = int(value)
    except (ValueError, TypeError):
        return default
    return max(min_val, min(val, max_val))


def _normalize_float(
    value: Any,
    min_val: float | None = 0.0,
    max_val: float | None = 1.0,
    default: float = 0.0,
) -> float:
    """Normalisiert einen beliebigen Wert zu einem Float mit Bereichsprüfung."""
    if value is None:
        return default
    if isinstance(value, str) and value.strip() == "":
        return default
    try:
        val = float(value)
    except (ValueError, TypeError):
        return default
    if min_val is not None and val < min_val:
        return min_val
    if max_val is not None and val > max_val:
        return max_val
    return val


def _normalize_str(value: str) -> str:
    return " ".join(str(value).strip().split())


