_CACHE_TTL: float = 300.0

_fallback_cache: dict[str, str] = {}
_fallback_cache_lock = threading.RLock()


@functools.lru_cache(maxsize=128)
def normalize_model_name(name: str | None = None) -> str:
    """Normalisiert einen Whisper-Modellnamen für die interne Verwendung."""
    if DEBUG_LEVEL >= 5:
        logger.log(5, "normalize_model_name called with: %r", name)

    if not isinstance(name, str):
        logger.warning(
            "normalize_model_name: name ist kein String (%r, Typ=%s) – verwende 'base'",
            name,
            type(name).__name__,
        )
        return "base"

    stripped = name.strip()
    if not stripped:
        return "base"

    try:
        normalized_str = unicodedata.normalize("NFKC", stripped)
    except (TypeError, ValueError) as e:
        logger.debug(
            "normalize_model_name: NFKC-Normalisierung fehlgeschlagen für %r: %s",
            stripped,
            e,
        )
        normalized_str = stripped

    normalized_str = normalized_str.replace("–", "-").replace("—", "-")
    normalized_str = " ".join(normalized_str.split())
    normalized = normalized_str.lower()

    try:
        known_models = globals().get("WHISPER_MODELS")
        if known_models is not None and normalized not in known_models:
            logger.warning(
                "normalize_model_name: unbekanntes Modell '%s' "
                "(Original: %r) – verwende trotzdem wie eingegeben",
                normalized,
                name,
            )
    except Exception as e:
        if DEBUG_LEVEL >= 4:
            logger.log(
                4,
                "normalize_model_name: WHISPER_MODELS-Check fehlgeschlagen: %s",
                e,
            )

    return normalized


def resolve_alias(name: str) -> str:
    """Löst einen Alias in den kanonischen Namen auf."""
    normalized = normalize_model_name(name)
    return MODEL_ALIASES.get(normalized, normalized)


def get_available_whisper_models(force_refresh: bool = False) -> set[str]:
    """Liefert die Menge aller bekannten Whisper-Modelle (mit Caching, thread-safe)."""
    global _available_models_cache, _available_models_cache_time
    with _models_cache_lock:
        if not force_refresh and _available_models_cache is not None:
            if time.time() - _available_models_cache_time < _CACHE_TTL:
                return _available_models_cache

    models = {normalize_model_name(m) for m in WHISPER_MODELS_BASE}
    try:
        import whisper

        if hasattr(whisper, "available_models"):
            whisper_models = {
                normalize_model_name(m) for m in whisper.available_models()
            }
            models.update(whisper_models)
    except ImportError:
        pass
    except Exception as e:
        logger.warning(
            f"Fehler beim Laden der Whisper-Modelle: {e} – verwende statische Liste",
        )

    models.update(normalize_model_name(alias) for alias in MODEL_ALIASES)
    with _models_cache_lock:
        _available_models_cache = models
        _available_models_cache_time = time.time()
    return models


def _resolve_fallback(
    fallback: str | None,
    fallback_chain: list[str] | None,
    use_dynamic_list: bool,
    force_refresh: bool = False,
) -> str:
    """Interne Hilfsfunktion zur Fallback‑Auflösung (mit einfachem Cache)."""
    cache_key = f"{fallback}_{fallback_chain}_{use_dynamic_list}_{force_refresh}"
    with _fallback_cache_lock:
        if cache_key in _fallback_cache:
            return _fallback_cache[cache_key]

    if fallback:
        result = get_valid_model(
            fallback,
            fallback_chain=None,
            use_dynamic_list=use_dynamic_list,
            force_refresh=force_refresh,
        )
    else:
        chain = fallback_chain if fallback_chain is not None else DEFAULT_FALLBACK_CHAIN
        valid_models = (
            get_available_whisper_models(force_refresh=force_refresh)
            if use_dynamic_list
            else WHISPER_MODELS_BASE
        )
        result = "base"
        for candidate in chain:
            normalized = normalize_model_name(candidate)
            canonical = resolve_alias(normalized)
            if canonical in valid_models:
                result = canonical
                break
        else:
            logger.error("❌ Kein Fallback-Modell gefunden – verwende 'base'")

    with _fallback_cache_lock:
        _fallback_cache[cache_key] = result
    return result


def get_valid_model(
    model_name: str,
    fallback: str | None = None,
    fallback_chain: list[str] | None = None,
    use_dynamic_list: bool = True,
    force_refresh: bool = False,
) -> str:
    """Gibt einen gültigen, normalisierten Modellnamen zurück."""
    if model_name is None:
        model_name = ""

    normalized = normalize_model_name(model_name)
    if not normalized:
        return _resolve_fallback(
            fallback,
            fallback_chain,
            use_dynamic_list,
            force_refresh,
        )

    canonical = resolve_alias(normalized)

    if use_dynamic_list:
        valid_models = get_available_whisper_models(force_refresh=force_refresh)
    else:
        valid_models = WHISPER_MODELS_BASE

    if canonical in valid_models:
        return canonical

    logger.warning(
        f"⚠️ Unbekanntes Modell '{model_name}' (normalisiert: '{normalized}') – verwende Fallback",
    )
    return _resolve_fallback(fallback, fallback_chain, use_dynamic_list, force_refresh)


def add_model_alias(alias: str, canonical: str) -> None:
    """Fügt einen neuen Alias hinzu."""
    MODEL_ALIASES[normalize_model_name(alias)] = canonical


def add_model_name(model: str) -> None:
    """Fügt einen neuen Modellnamen zur Basis-Liste hinzu."""
    WHISPER_MODELS_BASE.add(normalize_model_name(model))


def set_fallback_chain(chain: list[str]) -> None:
    """Setzt die globale Fallback-Kette."""
    global DEFAULT_FALLBACK_CHAIN
    DEFAULT_FALLBACK_CHAIN = chain


def get_model_info(model_name: str) -> dict[str, Any]:
    """Gibt Metadaten zu einem Modell zurück."""
    canonical = resolve_alias(model_name)
    return {
        "name": model_name,
        "normalized": normalize_model_name(model_name),
        "canonical": canonical,
        "is_valid": canonical in get_available_whisper_models(),
    }


_model_manager: ModelManager | None = None


def get_model_manager() -> ModelManager:
    """Liefert die zentrale ModelManager-Instanz."""
    global _model_manager
    if _model_manager is None:
        _model_manager = ModelManager()
    return _model_manager


_ALLOWED_KEYS_CACHE: dict[int, set[str]] = {}
_CACHE_LOCK = threading.RLock()
_CACHE_MAXSIZE = 1000


def _get_allowed_keys_for_func(func: Any) -> set[str]:
    """Extrahiert die Parameternamen einer Funktion (für Whitelist)."""
    try:
        sig = inspect.signature(func)
        return {
            p.name
            for p in sig.parameters.values()
            if p.kind
            not in (inspect.Parameter.VAR_KEYWORD, inspect.Parameter.VAR_POSITIONAL)
        }
    except (ValueError, TypeError, AttributeError) as e:
        logger.debug("Konnte Signatur für %s nicht extrahieren: %s", func, e)
        return set()
    except Exception as e:
        logger.exception("Unerwarteter Fehler beim Extrahieren der Signatur: %s", e)
        return set()


def _deep_filter_kwargs(
    kwargs: Any,
    *,
    allowed_keys: set[str] | None = None,
    forbidden_patterns: list[str] | None = None,
    max_depth: int = 3,
    _depth: int = 0,
    _path: str = "",
) -> Any:
    """Rekursive, extrem robuste Filterung von kwargs."""
    if _depth > max_depth:
        logger.debug(
            "[_deep_filter_kwargs] Max depth reached at %s – returning original",
            _path,
            extra={"component": "filter"},
        )
        return kwargs
    if not isinstance(kwargs, (dict, Mapping)):
        return kwargs
    try:
        if isinstance(kwargs, Mapping) and not isinstance(kwargs, dict):
            kwargs = dict(kwargs)
        else:
            kwargs = kwargs.copy()
    except (TypeError, ValueError, AttributeError) as e:
        logger.warning(
            "[_deep_filter_kwargs] Could not copy kwargs: %s – returning original",
            e,
            extra={"component": "filter"},
        )
        return kwargs
    except Exception as e:
        logger.exception(
            "[_deep_filter_kwargs] Unexpected error copying kwargs: %s",
            e,
            extra={"component": "filter"},
        )
        return kwargs
    try:
        keys = list(kwargs.keys())
    except (AttributeError, TypeError) as e:
        logger.debug(
            "[_deep_filter_kwargs] Could not get keys: %s – returning original",
            e,
            extra={"component": "filter"},
        )
        return kwargs
    except Exception as e:
        logger.exception(
            "[_deep_filter_kwargs] Unexpected error getting keys: %s",
            e,
            extra={"component": "filter"},
        )
        return kwargs
    removed_keys = []
    for key in keys:
        keep = True
        if allowed_keys is not None and key not in allowed_keys:
            keep = False
            removed_keys.append(key)
        if keep and forbidden_patterns:
            key_lower = key.lower()
            for pattern in forbidden_patterns:
                if pattern.lower() in key_lower:
                    keep = False
                    removed_keys.append(key)
                    break
        if not keep:
            del kwargs[key]
            continue
        value = kwargs[key]
        if isinstance(value, (dict, Mapping, list, tuple)):
            try:
                filtered_value = _deep_filter_kwargs(
                    value,
                    allowed_keys=allowed_keys,
                    forbidden_patterns=forbidden_patterns,
                    max_depth=max_depth,
                    _depth=_depth + 1,
                    _path=f"{_path}.{key}" if _path else key,
                )
                kwargs[key] = filtered_value
            except (TypeError, ValueError, AttributeError, RecursionError) as e:
                logger.warning(
                    "[_deep_filter_kwargs] Recursion error at %s.%s: %s – keeping original value",
                    _path,
                    key,
                    e,
                    extra={"component": "filter"},
                )
            except Exception as e:
                logger.exception(
                    "[_deep_filter_kwargs] Unexpected recursion error at %s.%s: %s",
                    _path,
                    key,
                    e,
                    extra={"component": "filter"},
                )
    if removed_keys and logger.isEnabledFor(logging.DEBUG):
        logger.debug(
            "[_deep_filter_kwargs] Removed keys at %s: %s",
            _path or "root",
            removed_keys,
            extra={"component": "filter"},
        )
    return kwargs


def _safe_log_debug(component: str, msg: str, *args: Any, **kwargs: Any) -> None:
    """Protokolliert eine Debug-Meldung mit optionalem Komponenten-Kontext."""
    global _DRAGON_LOGGER, _DEBUG_LEVEL

    if _DEBUG_LEVEL == 0:
        try:
            _DEBUG_LEVEL = globals().get("DEBUG_LEVEL", 0)
        except Exception:
            _DEBUG_LEVEL = 0

    if _DEBUG_LEVEL < 1:
        return

    if _DRAGON_LOGGER is None:
        try:
            _DRAGON_LOGGER = logging.getLogger("dragon")
        except Exception:
            _DRAGON_LOGGER = None

    try:
        formatted_msg = msg % args if args else msg
    except Exception:
        formatted_msg = msg if isinstance(msg, str) else str(msg)

    try:
        if _DRAGON_LOGGER is not None and _DRAGON_LOGGER.isEnabledFor(logging.DEBUG):
            _DRAGON_LOGGER.debug(
                f"[{component}] {formatted_msg}",
                extra={"component": component},
                **kwargs,
            )
        elif _DEBUG_LEVEL >= 2:
            print(f"[DEBUG][{component}] {formatted_msg}", file=sys.stderr)
    except Exception as e:
        if _DEBUG_LEVEL >= 4:
            with contextlib.suppress(Exception):
                print(f"[DEBUG][{component}] Fehler beim Logging: {e}", file=sys.stderr)


def _safe_log_exception(
    component: str,
    msg: str,
    exc: Exception | None = None,
    level: str = "error",
    **kwargs: Any,
) -> None:
    """Protokolliert eine Exception mit optionalem Komponenten-Kontext."""
    try:
        global _DRAGON_LOGGER
        if _DRAGON_LOGGER is None:
            _DRAGON_LOGGER = logging.getLogger("dragon")
        log_method = getattr(_DRAGON_LOGGER, level.lower(), _DRAGON_LOGGER.error)
        extra = {"component": component}
        if exc:
            log_method(msg, exc_info=exc, extra=extra, **kwargs)
        else:
            log_method(msg, extra=extra, **kwargs)
    except Exception:
        with contextlib.suppress(Exception):
            print(f"[{level.upper()}][{component}] {msg}", file=sys.stderr)
            if exc:
                print(f"Exception: {exc}", file=sys.stderr)


def filter_kwargs(
    kwargs: dict[str, Any],
    *,
    func: Any = None,
    forbidden_patterns: list[str] | None = None,
    max_depth: int = 3,
    use_whitelist: bool = True,
    debug: bool = False,
) -> dict[str, Any]:
    """Hauptfunktion: Filtert kwargs sicher."""
    if forbidden_patterns is None:
        forbidden_patterns = ["threadpool", "key_threadpool", "_pool"]
    allowed_keys = None
    if func is not None and use_whitelist:
        func_id = id(func)
        with _CACHE_LOCK:
            if func_id in _ALLOWED_KEYS_CACHE:
                allowed_keys = _ALLOWED_KEYS_CACHE[func_id]
            else:
                allowed_keys = _get_allowed_keys_for_func(func)
                if len(_ALLOWED_KEYS_CACHE) >= _CACHE_MAXSIZE:
                    _ALLOWED_KEYS_CACHE.pop(next(iter(_ALLOWED_KEYS_CACHE)))
                _ALLOWED_KEYS_CACHE[func_id] = allowed_keys
    try:
        result = _deep_filter_kwargs(
            kwargs,
            allowed_keys=allowed_keys,
            forbidden_patterns=forbidden_patterns,
            max_depth=max_depth,
        )
        if not isinstance(result, dict):
            return dict(kwargs)
        return result
    except Exception as e:
        if debug or logger.isEnabledFor(logging.DEBUG):
            import traceback

            logger.error(
                f"[filter_kwargs] CRITICAL error while filtering: {e}\n{
                    traceback.format_exc()
                }",
                extra={"component": "filter"},
            )
        return dict(kwargs)


