def _should_patch() -> bool:
    """Prüft, ob der Patch notwendig ist."""
    if not urllib3_available:
        return False
    try:
        import urllib3.connectionpool

        if not hasattr(urllib3.connectionpool, "PoolKey"):
            return False
        urllib3.connectionpool.PoolKey(
            host="localhost",
            port=80,
            request_context={},
            key_threadpool="dummy",
        )
        return False
    except TypeError as e:
        return "key_threadpool" in str(e)
    except AttributeError:
        return False


def apply() -> None:
    """Wendet den urllib3-Monkey-Patch an – mit garantierter Entfernung von
    'key_threadpool', 'threadpool' und anderen unerwarteten Parametern.
    Verwendet eine rekursive Filterfunktion für maximale Robustheit.
    """
    global _patch_applied, _original_methods

    with _patch_lock:
        if _patch_applied:
            logger.debug("ℹ️ Patch already applied – skipping")
            return

        if not urllib3_available:
            logger.warning("⚠️ urllib3 not available – cannot apply patch")
            _patch_applied = True
            return
        try:
            import urllib3.connectionpool

            if not hasattr(urllib3.connectionpool, "PoolKey"):
                logger.debug(
                    "ℹ️ urllib3.connectionpool.PoolKey not found – no patch needed",
                )
                _patch_applied = True
                return
        except (ImportError, AttributeError) as e:
            logger.debug(f"ℹ️ urllib3 not fully available: {e} – skipping patch")
            _patch_applied = True
            return
        try:
            urllib3.connectionpool.PoolKey(
                host="localhost",
                port=80,
                request_context={},
                key_threadpool="dummy",
            )
            logger.debug("ℹ️ No patch needed – urllib3 already compatible")
            _patch_applied = True
            return
        except TypeError as e:
            if "key_threadpool" not in str(e):
                logger.warning(f"⚠️ Unexpected TypeError: {e} – skipping patch")
                _patch_applied = True
                return
            logger.info("🔧 Applying urllib3 monkey-patch (key_threadpool fix)...")

        def _deep_filter_kwargs(
            obj: Any,
            forbidden: set[str] | None = None,
            max_depth: int = 5,
            _depth: int = 0,
        ) -> Any:
            """Rekursive Filterung von Dictionaries, Listen und Tupeln.
            Entfernt alle Schlüssel, die in `forbidden` enthalten sind.
            """
            if forbidden is None:
                forbidden = {"key_threadpool", "threadpool", "_pool", "thread_pool"}

            if _depth > max_depth:
                return obj

            if isinstance(obj, dict):
                filtered = {}
                for key, value in obj.items():
                    if key in forbidden:
                        continue
                    filtered[key] = _deep_filter_kwargs(
                        value,
                        forbidden,
                        max_depth,
                        _depth + 1,
                    )
                return filtered
            if isinstance(obj, list):
                return [
                    _deep_filter_kwargs(item, forbidden, max_depth, _depth + 1)
                    for item in obj
                ]
            if isinstance(obj, tuple):
                return tuple(
                    _deep_filter_kwargs(item, forbidden, max_depth, _depth + 1)
                    for item in obj
                )
            return obj

        def _filter_kwargs(kwargs: dict) -> dict:
            """Wrapper für die rekursive Filterung."""
            if not kwargs:
                return {}
            return _deep_filter_kwargs(kwargs)

        def _safe_patch(module: Any, attr: str, new_func: Callable) -> bool:
            """Patcht eine Methode sicher und speichert das Original.
            Gibt True bei Erfolg zurück.
            """
            try:
                obj = module
                parts = attr.split(".")
                for part in parts[:-1]:
                    obj = getattr(obj, part)
                original = getattr(obj, parts[-1])
                setattr(obj, parts[-1], new_func)
                _original_methods[f"{module.__name__}.{attr}"] = original
                return True
            except (AttributeError, TypeError) as e:
                logger.debug(f"Could not patch {attr}: {e}")
                return False

        try:
            import urllib3.connectionpool
            import urllib3.poolmanager

            if hasattr(urllib3.connectionpool.PoolKey, "__new__"):
                orig_poolkey_new = urllib3.connectionpool.PoolKey.__new__
                _original_methods["urllib3.connectionpool.PoolKey.__new__"] = (
                    orig_poolkey_new
                )

                @staticmethod
                def _patched_poolkey_new(cls, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    return orig_poolkey_new(cls, *args, **filtered)

                urllib3.connectionpool.PoolKey.__new__ = _patched_poolkey_new

            if hasattr(urllib3.connectionpool.PoolKey, "__init__"):
                orig_poolkey_init = urllib3.connectionpool.PoolKey.__init__
                _original_methods["urllib3.connectionpool.PoolKey.__init__"] = (
                    orig_poolkey_init
                )

                def _patched_poolkey_init(self, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    orig_poolkey_init(self, *args, **filtered)

                urllib3.connectionpool.PoolKey.__init__ = _patched_poolkey_init

            orig_pool_init = urllib3.poolmanager.PoolManager.__init__
            _original_methods["urllib3.poolmanager.PoolManager.__init__"] = (
                orig_pool_init
            )

            def _patched_pool_init(self, *args, **kwargs):
                filtered = _filter_kwargs(kwargs)
                orig_pool_init(self, *args, **filtered)

            urllib3.poolmanager.PoolManager.__init__ = _patched_pool_init

            if hasattr(urllib3.poolmanager, "ProxyManager"):
                orig_proxy_init = urllib3.poolmanager.ProxyManager.__init__
                _original_methods["urllib3.poolmanager.ProxyManager.__init__"] = (
                    orig_proxy_init
                )

                def _patched_proxy_init(self, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    orig_proxy_init(self, *args, **filtered)

                urllib3.poolmanager.ProxyManager.__init__ = _patched_proxy_init

            if hasattr(urllib3.connectionpool, "ConnectionPool"):
                orig_conn_init = urllib3.connectionpool.ConnectionPool.__init__
                _original_methods["urllib3.connectionpool.ConnectionPool.__init__"] = (
                    orig_conn_init
                )

                def _patched_conn_init(self, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    orig_conn_init(self, *args, **filtered)

                urllib3.connectionpool.ConnectionPool.__init__ = _patched_conn_init

            if hasattr(urllib3.connectionpool, "HTTPSConnectionPool"):
                orig_https_init = urllib3.connectionpool.HTTPSConnectionPool.__init__
                _original_methods[
                    "urllib3.connectionpool.HTTPSConnectionPool.__init__"
                ] = orig_https_init

                def _patched_https_init(self, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    orig_https_init(self, *args, **filtered)

                urllib3.connectionpool.HTTPSConnectionPool.__init__ = (
                    _patched_https_init
                )

            if hasattr(urllib3.connectionpool, "HTTPConnectionPool"):
                orig_http_init = urllib3.connectionpool.HTTPConnectionPool.__init__
                _original_methods[
                    "urllib3.connectionpool.HTTPConnectionPool.__init__"
                ] = orig_http_init

                def _patched_http_init(self, *args, **kwargs):
                    filtered = _filter_kwargs(kwargs)
                    orig_http_init(self, *args, **filtered)

                urllib3.connectionpool.HTTPConnectionPool.__init__ = _patched_http_init

            if hasattr(urllib3.poolmanager.PoolManager, "connection_from_pool_key"):
                orig_conn_from_pool = (
                    urllib3.poolmanager.PoolManager.connection_from_pool_key
                )
                _original_methods[
                    "urllib3.poolmanager.PoolManager.connection_from_pool_key"
                ] = orig_conn_from_pool

                def _patched_connection_from_pool_key(
                    self,
                    pool_key,
                    request_context=None,
                ):
                    return orig_conn_from_pool(self, pool_key, request_context)

                urllib3.poolmanager.PoolManager.connection_from_pool_key = (
                    _patched_connection_from_pool_key
                )

            _patch_applied = True
            logger.info(
                "✅ urllib3 monkey-patch applied successfully (key_threadpool removed)",
            )

        except Exception as e:
            logger.error(f"❌ Failed to apply urllib3 monkey-patch: {e}", exc_info=True)
            unpatch()
            _patch_applied = True
            raise


def unpatch() -> None:
    """Entfernt den Monkey-Patch."""
    global _patch_applied, _original_methods

    with _patch_lock:
        if not _patch_applied:
            return

        if not urllib3_available:
            _patch_applied = False
            return

        logger.info("🔧 Removing urllib3 monkey-patch...")

        try:
            if _original_methods.get("urlopen") is not None:
                urllib3.connectionpool.ConnectionPool.urlopen = _original_methods[
                    "urlopen"
                ]
            if _original_methods.get("container_init") is not None:
                urllib3._collections.RecentlyUsedContainer.__init__ = _original_methods[
                    "container_init"
                ]
            if _original_methods.get("connection_from_pool_key") is not None:
                urllib3.poolmanager.PoolManager.connection_from_pool_key = (
                    _original_methods["connection_from_pool_key"]
                )
            if _original_methods.get("poolkey_init") is not None:
                urllib3.connectionpool.PoolKey.__init__ = _original_methods[
                    "poolkey_init"
                ]
            if _original_methods.get("poolkey_new") is not None:
                urllib3.connectionpool.PoolKey.__new__ = _original_methods[
                    "poolkey_new"
                ]
            if _original_methods.get("proxy_init") is not None:
                urllib3.poolmanager.ProxyManager.__init__ = _original_methods[
                    "proxy_init"
                ]
            if _original_methods.get("pool_init") is not None:
                urllib3.poolmanager.PoolManager.__init__ = _original_methods[
                    "pool_init"
                ]

            _original_methods.clear()
            _patch_applied = False
            logger.info("✅ urllib3 monkey-patch removed")

        except Exception as e:
            logger.error(f"❌ Error while unpatching: {e}", exc_info=True)
            raise


if requests is not None:
    from requests.adapters import HTTPAdapter

    class NamedHTTPAdapter(HTTPAdapter):
        """HTTPAdapter mit benanntem Thread-Pool für besseres Monitoring."""

        def __init__(self, pool_name: str = "DW-Requests", *args, **kwargs):
            self.pool_name = pool_name
            kwargs.pop("pool_name", None)
            kwargs.pop("key_threadpool", None)
            super().__init__(*args, **kwargs)
            logger.debug(
                f"🔧 NamedHTTPAdapter initialized with pool_name='{pool_name}'",
            )

        def init_poolmanager(self, *args, **kwargs):
            kwargs.pop("key_threadpool", None)
            max_workers = kwargs.get("num_pools", 10)
            threadpool = ThreadPoolExecutor(
                max_workers=max_workers,
                thread_name_prefix=self.pool_name,
            )
            kwargs["threadpool"] = threadpool
            try:
                super().init_poolmanager(*args, **kwargs)
            except TypeError as e:
                if "threadpool" in str(e):
                    kwargs.pop("threadpool", None)
                    super().init_poolmanager(*args, **kwargs)
                    logger.debug(f"ℹ️ init_poolmanager fallback for {self.pool_name}")
                else:
                    logger.error(f"❌ init_poolmanager error: {e}")
                    raise
            except Exception as e:
                logger.error(f"❌ Unexpected error in init_poolmanager: {e}")
                raise

        def proxy_manager_for(self, *args, **kwargs):
            kwargs.pop("key_threadpool", None)
            max_workers = kwargs.get("num_pools", 10)
            threadpool = ThreadPoolExecutor(
                max_workers=max_workers,
                thread_name_prefix=f"{self.pool_name}-Proxy",
            )
            kwargs["threadpool"] = threadpool
            try:
                return super().proxy_manager_for(*args, **kwargs)
            except TypeError as e:
                if "threadpool" in str(e):
                    kwargs.pop("threadpool", None)
                    return super().proxy_manager_for(*args, **kwargs)
                logger.error(f"❌ proxy_manager_for error: {e}")
                raise
            except Exception as e:
                logger.error(f"❌ Unexpected error in proxy_manager_for: {e}")
                raise

    logger.debug("✅ NamedHTTPAdapter defined")
else:

    class NamedHTTPAdapter:  # type: ignore[no-redef]
        """Dummy, wenn requests nicht verfügbar ist."""

        def __init__(self, *args, **kwargs):
            raise RuntimeError("requests not installed")


