def _global_exception_handler(exc_type, exc_value, exc_tb):
    """Behandelt unbehandelte Exceptions im Hauptthread."""
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_tb)
        return

    try:
        logger.critical(
            "Unhandled exception in main thread",
            exc_info=(exc_type, exc_value, exc_tb),
        )
    except Exception:
        print("❌ CRITICAL: Unhandled exception in main thread", file=sys.stderr)
        traceback.print_exception(exc_type, exc_value, exc_tb, file=sys.stderr)

    if GUI_AVAILABLE:
        try:
            import tkinter as tk

            root = tk._default_root if hasattr(tk, "_default_root") else None

            error_msg = (
                "Ein schwerwiegender Fehler ist aufgetreten:\n"
                f"{exc_value}\n\nDetails in der Logdatei."
            )

            if root is not None and root.winfo_exists():
                tk.messagebox.showerror(
                    "Dragon Whisperer - Critical Error",
                    error_msg,
                    parent=root,
                )
            else:
                tk.messagebox.showerror(
                    "Dragon Whisperer - Critical Error",
                    error_msg,
                )
        except (tk.TclError, AttributeError, RuntimeError) as e:
            logger.debug(
                "Ignored exception while showing GUI error: %s",
                e,
                exc_info=True,
            )
        except Exception as e:
            logger.exception("Unexpected error in GUI error handler: %s", e)


def _thread_exception_handler(args: threading.ExceptHookArgs) -> None:
    """Behandelt unbehandelte Exceptions in Threads."""
    try:
        thread = getattr(args, "thread", None)
        if thread is None:
            thread_name = "unknown (args.thread is None)"
        elif isinstance(thread, threading.Thread):
            thread_name = thread.name
        elif isinstance(thread, str):
            thread_name = thread
        else:
            thread_name = f"unknown type {type(thread).__name__}"
        exc_type = getattr(args, "exc_type", None)
        exc_value = getattr(args, "exc_value", None)
        exc_tb = getattr(args, "exc_traceback", None)
        logger.critical(
            "Unhandled exception in thread '%s': %s",
            thread_name,
            exc_value,
            exc_info=(exc_type, exc_value, exc_tb),
        )
    except Exception as e:
        with contextlib.suppress(Exception):
            print(
                f"CRITICAL: Exception in thread exception handler: {e}",
                file=sys.stderr,
            )


sys.excepthook = _global_exception_handler
threading.excepthook = _thread_exception_handler


def safe_shutdown_executor(
    executor,
    wait: bool = True,
    cancel_futures: bool = False,
    timeout: float | None = None,
    log_context: str = "",
) -> bool:
    """Sicherer Shutdown eines Executors (ThreadPoolExecutor/ProcessPoolExecutor).

    Args:
        wait:
            True  → cancel_futures wird gesendet, dann wird aktiv bis
                    `timeout` (Default 5s) auf den Join der Worker-Threads
                    gewartet. Log zeigt `mode=joined`. Wenn ein Worker
                    nicht innerhalb des Timeouts beendet ist, wird eine
                    WARNING-Zeile mit Namen und TID geloggt.

            False → nur shutdown(wait=False) + Queue-Drain, KEIN Join.
                    Worker bleiben als Daemon-Threads für bis zu
                    `queue_poll_interval` (typisch 100ms) am Leben und
                    beenden sich dann selbst. Log zeigt `mode=no-join`.
                    `workers_after_alive > 0` ist in diesem Modus ERWARTET
                    und KEIN Leak oder Fehler.

        cancel_futures:
            True  → pending und aktive Tasks werden abgebrochen; die
                    Work-Queue wird zusätzlich manuell gedrained.
            False → nur shutdown(wait=False), kein Drain.

        timeout:
            Maximalzeit für den Worker-Join bei `wait=True`.
            Default 5.0s wenn nicht gesetzt.

        log_context:
            Optionaler Präfix für Log-Zeilen (z. B. "[timeout_executor]").

    Returns:
        True wenn der Executor als beendet markiert wurde oder bereits
        beendet war. False bei Timeout während `wait=True` oder bei
        einem unerwarteten Fehler.

    Hinweis für Reviewer und Analyse-Tools:
        Diese Funktion hat zwei klar getrennte Betriebsmodi. Bei
        `wait=False` ist `workers_after_alive > 0` in der Abschluss-
        Log-Zeile ein SNAPSHOT, kein Fehlerzustand. Verantwortlich ist die
        Entscheidung des Aufrufers, z. B.:
            - _replace_executor(force=True)       → sofortiger Abbruch
            - _force_shutdown_executor            → sofortiger Abbruch
            - finale Prozess-Shutdown-Pfade       → os._exit(0) folgt
        Die Worker-Threads sind daemon=True und sterben nach spätestens
        `queue_poll_interval` Sekunden (typisch 100 ms) von selbst.
    """
    import contextlib
    import logging
    import queue as _queue_mod
    import time

    _LOG_LEVEL_TRACE = 5

    if executor is None:
        return True

    logger = logging.getLogger("dragon")
    context = f"[{log_context}] " if log_context else ""
    start_time = time.monotonic()
    executor_type = type(executor).__name__
    executor_id = id(executor)

    def _discover_workers(only_alive: bool = True) -> list:
        """Findet alle Worker-Threads/-Prozesse eines Executors."""
        candidates: list = []

        getter = getattr(executor, "get_worker_threads", None)
        if getter is not None and callable(getter):
            try:
                result = getter()
                if result:
                    candidates = list(result)
            except Exception as exc:
                logger.log(
                    _LOG_LEVEL_TRACE,
                    f"{context}get_worker_threads() Fehler: {exc}",
                )

        if not candidates:
            wt = getattr(executor, "_worker_threads", None)
            if wt is not None and not callable(wt):
                try:
                    result = list(wt)
                    if result:
                        candidates = result
                except Exception:
                    pass

        if not candidates:
            wr = getattr(executor, "_workers", None)
            if wr is not None and not callable(wr):
                try:
                    result = list(wr)
                    if result:
                        candidates = result
                except Exception:
                    pass

        if not candidates:
            th = getattr(executor, "_threads", None)
            if th is not None:
                with contextlib.suppress(Exception):
                    candidates = list(th)

        if not candidates:
            pr = getattr(executor, "_processes", None)
            if pr is not None:
                with contextlib.suppress(Exception):
                    candidates = (
                        list(pr.values()) if hasattr(pr, "values") else list(pr)
                    )

        if only_alive:
            candidates = [
                w for w in candidates if hasattr(w, "is_alive") and w.is_alive()
            ]

        return candidates

    def _describe_executor_state() -> str:
        """Beschreibt den Shutdown-Zustand des Executors möglichst genau.

        Reihenfolge:
          1. `_state`-Enum mit `.name`  → z.B. "SHUTDOWN", "SHUTTING_DOWN"
          2. `_state`-String            → direkt
          3. `_shutdown`-Bool           → "shutdown=True" / "shutdown=False"
          4. "unknown"                  → kein bekanntes Attribut
        """
        try:
            _st = getattr(executor, "_state", None)
            if _st is not None:
                name = getattr(_st, "name", None)
                if name:
                    return str(name)
                s = str(_st)
                if "." in s:
                    return s.rsplit(".", 1)[-1]
                return s
        except Exception:
            pass

        try:
            _sd = getattr(executor, "_shutdown", None)
            if isinstance(_sd, bool):
                return f"shutdown={_sd}"
        except Exception:
            pass

        return "unknown"

    def _describe_queue_before(size: int) -> str:
        """Erklärt den Sentinel-Wert -1 für Executor ohne _work_queue."""
        if size == -1:
            return "-1 (no _work_queue attr)"
        return str(size)

    def _describe_poll_interval() -> str:
        """Liefert die echte Poll-Intervall-Zahl, wenn verfügbar."""
        try:
            pi = getattr(executor, "_queue_poll_interval", None)
            if isinstance(pi, (int, float)) and pi > 0:
                return f"{pi * 1000:.0f}ms"
        except Exception:
            pass
        return "typically 100ms"

    queue_obj = getattr(executor, "_work_queue", None)
    queue_size_before: int = -1
    if queue_obj is not None:
        try:
            queue_size_before = queue_obj.qsize()
        except Exception:
            queue_size_before = -1

    workers_before = _discover_workers(only_alive=True)

    logger.debug(
        f"{context}Executor-Shutdown START: "
        f"type={executor_type}, id={executor_id}, "
        f"wait={wait}, cancel_futures={cancel_futures}, "
        f"timeout={timeout if timeout is not None else 'auto'}, "
        f"queue_before={_describe_queue_before(queue_size_before)}, "
        f"workers_before={len(workers_before)}"
    )

    try:
        already_shutdown = False
        if hasattr(executor, "_shutdown"):
            try:
                already_shutdown = bool(executor._shutdown)
            except Exception:
                already_shutdown = False
        if already_shutdown:
            logger.debug(
                f"{context}Executor bereits beendet (idempotent) – "
                f"kein erneuter Shutdown nötig"
            )
            return True

        if not hasattr(executor, "shutdown") or not callable(executor.shutdown):
            logger.warning(
                f"{context}Executor unterstützt kein shutdown() – überspringe"
            )
            return False

        effective_timeout: float | None = None
        if wait:
            if timeout is not None and timeout > 0:
                effective_timeout = timeout
            else:
                effective_timeout = 5.0

        cancel_accepted = False
        if cancel_futures:
            try:
                executor.shutdown(wait=False, cancel_futures=True)
                cancel_accepted = True
                logger.debug(
                    f"{context}shutdown(wait=False, cancel_futures=True) erfolgreich"
                )
            except TypeError:
                logger.log(
                    _LOG_LEVEL_TRACE,
                    f"{context}cancel_futures Parameter nicht unterstützt – "
                    f"verwende manuellen Queue-Drain",
                )
                try:
                    executor.shutdown(wait=False)
                except Exception as exc:
                    logger.debug(
                        f"{context}shutdown(wait=False) Fallback-Fehler: {exc}"
                    )

            queue_obj_post = getattr(executor, "_work_queue", None)
            if queue_obj_post is not None:
                post_size = -1
                try:
                    post_size = queue_obj_post.qsize()
                except Exception:
                    post_size = -1

                if post_size != 0:
                    drained_pending = 0
                    drain_errors = 0
                    while True:
                        try:
                            item = queue_obj_post.get_nowait()
                        except _queue_mod.Empty:
                            break
                        except Exception as exc:
                            drain_errors += 1
                            logger.debug(f"{context}Queue-Drain-Fehler: {exc}")
                            break

                        if hasattr(item, "cancel"):
                            with contextlib.suppress(Exception):
                                item.cancel()
                        drained_pending += 1

                    if drained_pending > 0:
                        logger.debug(
                            f"{context}Queue-Drain: {drained_pending} "
                            f"pending Task(s) verworfen "
                            f"(cancel_accepted={cancel_accepted}, "
                            f"post_size={post_size}, "
                            f"drain_errors={drain_errors})"
                        )
                    elif post_size > 0 and drain_errors > 0:
                        logger.warning(
                            f"{context}Queue-Drain teilweise fehlgeschlagen: "
                            f"post_size={post_size}, "
                            f"drain_errors={drain_errors}"
                        )
        else:
            try:
                executor.shutdown(wait=False)
                logger.debug(
                    f"{context}shutdown(wait=False) erfolgreich (cancel_futures=False)"
                )
            except Exception as exc:
                logger.debug(f"{context}shutdown(wait=False) Fehler: {exc}")

        if wait and effective_timeout is not None:
            workers = _discover_workers(only_alive=True)

            if workers:
                logger.debug(
                    f"{context}Warte auf {len(workers)} Worker "
                    f"(timeout={effective_timeout:.1f}s)"
                )
                deadline = time.monotonic() + effective_timeout
                still_alive = []

                for w in workers:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        still_alive.append(w)
                        continue

                    if hasattr(w, "is_alive") and w.is_alive():
                        with contextlib.suppress(Exception):
                            w.join(timeout=remaining)
                        if hasattr(w, "is_alive") and w.is_alive():
                            still_alive.append(w)

                if still_alive:
                    details = []
                    for w in still_alive[:5]:
                        name = getattr(w, "name", f"<{type(w).__name__}>")
                        ident = getattr(w, "ident", None)
                        details.append(
                            f"{name}" + (f"@tid={ident}" if ident is not None else "")
                        )
                    extra = (
                        f" (+{len(still_alive) - 5} weitere)"
                        if len(still_alive) > 5
                        else ""
                    )
                    logger.warning(
                        f"{context}Timeout beim Warten auf Worker "
                        f"({effective_timeout:.1f}s) – "
                        f"{len(still_alive)} noch aktiv: "
                        f"{', '.join(details)}{extra}"
                    )
                else:
                    elapsed_join = effective_timeout - max(
                        deadline - time.monotonic(), 0.0
                    )
                    logger.debug(
                        f"{context}Alle {len(workers)} Worker sauber beendet "
                        f"(join_dauer={elapsed_join * 1000:.1f}ms)"
                    )
            else:
                logger.log(
                    _LOG_LEVEL_TRACE,
                    f"{context}Keine Worker gefunden "
                    f"(type={executor_type}) – kurze Wartezeit (max 50ms)",
                )
                time.sleep(0.05)

        elapsed_ms = (time.monotonic() - start_time) * 1000.0

        queue_size_after: int = -1
        queue_obj_final = getattr(executor, "_work_queue", None)
        if queue_obj_final is not None:
            try:
                queue_size_after = queue_obj_final.qsize()
            except Exception:
                queue_size_after = -1

        workers_after = _discover_workers(only_alive=True)
        state_desc = _describe_executor_state()

        if wait and effective_timeout is not None:
            _mode = f"joined(timeout={effective_timeout:.1f}s)"
        elif wait:
            _mode = "joined(auto-timeout)"
        else:
            _mode = "no-join"

        _workers_hint = ""
        if not wait and len(workers_after) > 0:
            _workers_hint = (
                f" (workers still exiting as daemons, "
                f"poll_interval={_describe_poll_interval()})"
            )

        logger.debug(
            f"{context}Executor-Shutdown abgeschlossen in "
            f"{elapsed_ms:.2f} ms "
            f"(mode={_mode}, "
            f"type={executor_type}, "
            f"cancel_accepted={cancel_accepted}, "
            f"queue_before={_describe_queue_before(queue_size_before)}, "
            f"queue_after={_describe_queue_before(queue_size_after)}, "
            f"workers_before={len(workers_before)}, "
            f"workers_after_alive={len(workers_after)}"
            f"{_workers_hint}, "
            f"executor_state={state_desc})"
        )

        if queue_size_after > 0:
            if cancel_futures:
                logger.warning(
                    f"{context}Nach Shutdown noch {queue_size_after} "
                    f"Task(s) in Queue – Drain war unvollständig"
                )
            else:
                logger.log(
                    _LOG_LEVEL_TRACE,
                    f"{context}Nach Shutdown {queue_size_after} "
                    f"Task(s) in Queue (cancel_futures=False → "
                    f"kein Drain erwartet)",
                )

        return True

    except Exception as e:
        elapsed_ms = (time.monotonic() - start_time) * 1000.0
        logger.error(
            f"{context}Unerwarteter Fehler beim Shutdown "
            f"(type={executor_type}, id={executor_id}, "
            f"nach {elapsed_ms:.2f} ms): {type(e).__name__}: {e}",
            exc_info=True,
        )
        return False


def _cleanup_loky_on_startup() -> None:
    """Beendet den Loky-Executor beim Start, um Ressourcen freizugeben."""
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
            logger.debug("🧹 Loky-Executor beim Start bereinigt")
    except Exception as e:
        logger.debug("🧹 Loky-Start-Cleanup fehlgeschlagen: %s", e, exc_info=True)


_cleanup_loky_on_startup()

