class SimpleEventBus:
    """Minimaler EventBus für Notfälle (wenn kein richtiger verfügbar ist).
    Unterstützt jetzt auch 'once'-Callbacks.
    """

    def __init__(self):
        self._subscribers: dict[str, list[tuple[Callable, bool]]] = {}
        self._lock = threading.RLock()

    def subscribe(
        self,
        event_type: str,
        callback: Callable,
        once: bool = False,
    ) -> None:
        with self._lock:
            if event_type not in self._subscribers:
                self._subscribers[event_type] = []
            self._subscribers[event_type].append((callback, once))

    def emit(self, event_type: str, data: Any = None) -> None:
        with self._lock:
            callbacks = self._subscribers.get(event_type, []).copy()

        for cb, once in callbacks:
            with contextlib.suppress(Exception):
                cb(data)

        if any(once for _, once in callbacks):
            with self._lock:
                self._subscribers[event_type] = [
                    (cb, once)
                    for cb, once in self._subscribers.get(event_type, [])
                    if not once
                ]

    def unsubscribe(self, event_type: str, callback: Callable) -> None:
        with self._lock:
            if event_type in self._subscribers:
                self._subscribers[event_type] = [
                    (cb, once)
                    for cb, once in self._subscribers[event_type]
                    if cb != callback
                ]

    def clear(self) -> None:
        with self._lock:
            self._subscribers.clear()

    def dispose(self) -> None:
        self.clear()


class ModelManager:
    """Singleton- und thread-sichere Verwaltung aller Whisper-Modelle."""

    _instance: ModelManager | None = None
    _lock = threading.Lock()

    def __new__(cls) -> ModelManager:
        with cls._lock:
            if cls._instance is None:
                cls._instance = super().__new__(cls)
                cls._instance._initialized = False
            return cls._instance

    def __init__(self) -> None:
        with self._lock:
            if self._initialized:
                return
            self._initialized = True

        self._available_models_cache: set[str] | None = None
        self._cache_time: float = 0.0
        self._cache_ttl: float = 300.0
        self._cache_lock = threading.RLock()
        self._aliases: dict[str, str] = {
            normalize_model_name(alias): normalize_model_name(canonical)
            for alias, canonical in MODEL_ALIASES.items()
        }
        self._fallback_chain: list[str] = [
            normalize_model_name(model) for model in DEFAULT_FALLBACK_CHAIN.copy()
        ]

    def normalize(self, name: str) -> str:
        return normalize_model_name(name)

    def resolve_alias(self, name: str) -> str:
        normalized = self.normalize(name)
        return self._aliases.get(normalized, normalized)

    def get_available_models(self, force_refresh: bool = False) -> set[str]:
        return get_available_whisper_models(force_refresh)

    def is_valid(self, name: str) -> bool:
        canonical = self.resolve_alias(name)
        return canonical in self.get_available_models()

    def get_valid(
        self,
        name: str,
        fallback: str | None = None,
        fallback_chain: list[str] | None = None,
    ) -> str:
        if fallback_chain is not None:
            fallback_chain = [self.normalize(m) for m in fallback_chain]
        return get_valid_model(
            name,
            fallback,
            fallback_chain or self._fallback_chain,
            use_dynamic_list=True,
        )

    def add_alias(self, alias: str, canonical: str) -> None:
        key = self.normalize(alias)
        value = self.normalize(canonical)
        self._aliases[key] = value

    def set_fallback_chain(self, chain: list[str]) -> None:
        self._fallback_chain = [self.normalize(m) for m in chain]

    def get_fallback_chain(self) -> list[str]:
        return self._fallback_chain.copy()

    def get_info(self, name: str) -> dict[str, Any]:
        return get_model_info(name)

    def clear_cache(self) -> None:
        with self._cache_lock:
            self._available_models_cache = None
            self._cache_time = 0.0


class StreamError(Exception):
    """Erweiterte Exception für Fehler während der Stream‑Verarbeitung."""

    def __init__(
        self,
        message: str = "Stream processing error",
        *,
        details: str | None = None,
        code: int | None = None,
        original_exception: BaseException | None = None,
    ) -> None:
        """Initialisiert die Exception und protokolliert sie optional."""
        self.message = message
        self.details = details
        self.code = code
        self.timestamp = datetime.now()
        if original_exception is not None:
            self.__cause__ = original_exception
        super().__init__(self.message)
        self._log_creation()

    def _log_creation(self) -> None:
        """Protokolliert die Erzeugung der Exception, wenn Debug‑Logging verfügbar ist."""
        try:
            debug_level = globals().get("DEBUG_LEVEL", 0)
        except Exception:
            debug_level = 0
        if debug_level < 3:
            return
        try:
            log_debug_func = globals().get("log_debug")
            if not callable(log_debug_func):
                import logging

                logger = logging.getLogger("dragon")
                logger.debug("log_debug nicht aufrufbar – verwende logger.debug")
                return
        except Exception as e:
            import logging

            logging.getLogger("dragon").debug(
                "Fehler beim Zugriff auf globals() in _log_creation: %s",
                e,
            )
            return
        try:
            log_msg = f"StreamError erzeugt: {self.message}"
            if self.details:
                log_msg += f" | Details: {self.details}"
            if self.code is not None:
                log_msg += f" | Code: {self.code}"
            if self.__cause__ is not None:
                log_msg += f" | Verursacht durch: {type(self.__cause__).__name__}"
            log_debug_func("stream", log_msg)
        except Exception as e:
            import logging

            logging.getLogger("dragon").debug(
                "Fehler in _log_creation beim Aufruf von log_debug: %s",
                e,
                exc_info=True,
            )

    def __str__(self) -> str:
        """Formatierte Fehlermeldung."""
        parts = [self.message]
        if self.code is not None:
            parts.append(f"[Code {self.code}]")
        if self.details:
            parts.append(f"({self.details})")
        return " ".join(parts)

    def to_dict(self) -> dict[str, Any]:
        """Konvertiert die Exception in ein Dictionary (z.B. für Logging oder JSON)."""
        return {
            "type": self.__class__.__name__,
            "message": self.message,
            "details": self.details,
            "code": self.code,
            "timestamp": self.timestamp.isoformat(),
            "cause": str(self.__cause__) if self.__cause__ else None,
        }


class TaskDelta(IntEnum):
    INCREMENT = 1
    DECREMENT = -1
    NOTIFY = 0


class TranscriptionError(Exception):
    """Hochoptimierte Exception für Fehler während der Transkription."""

    _error_count: int = 0
    _error_lock = threading.RLock()
    _last_errors: ClassVar[deque[TranscriptionError]] = deque(maxlen=10)

    def __init__(
        self,
        message: str = "Transcription error",
        *,
        details: str | None = None,
        code: int | None = None,
        original_exception: BaseException | None = None,
        notify_eventbus: bool = False,
    ) -> None:
        """Args:
        message: Fehlermeldung.
        details: Zusätzliche Detailinformationen.
        """
        self.message = message
        self.details = details
        self.code = code
        self.timestamp = datetime.now()
        self.original_exception = original_exception
        if original_exception is not None:
            self.__cause__ = original_exception
        super().__init__(self.message)
        with self._error_lock:
            TranscriptionError._error_count += 1
            TranscriptionError._last_errors.append(self)
        self._log_creation()

        if notify_eventbus:
            self._notify_eventbus()

    def _log_creation(self) -> None:
        """Protokolliert die Erzeugung der Exception im Debug‑Level."""
        try:
            import logging

            debug_level = getattr(self, "debug_level", 0) or getattr(
                self,
                "DEBUG_LEVEL",
                0,
            )
            if debug_level >= 3:
                log_parts = [f"TranscriptionError erzeugt: {self.message}"]
                if self.details:
                    log_parts.append(f"Details: {self.details}")
                if self.code is not None:
                    log_parts.append(f"Code: {self.code}")
                if self.__cause__ is not None:
                    cause_name = type(self.__cause__).__name__
                    log_parts.append(f"Verursacht durch: {cause_name}")
                log_msg = " | ".join(log_parts)
                _safe_log_debug("transcription", log_msg)
        except Exception as e:
            try:
                logger = logging.getLogger("dragon")
                logger.debug(f"[transcription] Fehler beim Loggen der Exception: {e}")
            except Exception:
                pass

    def _notify_eventbus(self) -> None:
        """Versucht, den Fehler über den EventBus zu versenden."""
        try:
            bus = globals().get("event_bus") or globals().get("EventBus")
            if bus is not None and hasattr(bus, "emit"):
                bus.emit("transcription_error", self.to_dict())
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

    def __str__(self) -> str:
        """Formatierte Fehlermeldung."""
        parts = [self.message]
        if self.code is not None:
            parts.append(f"[Code {self.code}]")
        if self.details:
            parts.append(f"({self.details})")
        return " ".join(parts)

    def to_dict(self) -> dict[str, Any]:
        """Konvertiert die Exception in ein Dictionary (z. B. für Logging oder JSON)."""
        return {
            "type": self.__class__.__name__,
            "message": self.message,
            "details": self.details,
            "code": self.code,
            "timestamp": self.timestamp.isoformat(),
            "cause": str(self.__cause__) if self.__cause__ else None,
        }

    @classmethod
    def get_error_count(cls) -> int:
        """Gibt die Gesamtzahl der aufgetretenen TranscriptionErrors zurück."""
        with cls._error_lock:
            return cls._error_count

    @classmethod
    def get_last_errors(cls, n: int = 10) -> list[TranscriptionError]:
        """Gibt eine Liste der letzten N Fehler zurück."""
        with cls._error_lock:
            return list(cls._last_errors)[-n:]

    @classmethod
    def reset_error_count(cls) -> None:
        """Setzt den globalen Fehlerzähler zurück."""
        with cls._error_lock:
            cls._error_count = 0
            cls._last_errors.clear()


