LANGUAGE_CODE_MAPPING: dict[str, str] = {
    "yue": "zh-TW",
    "tl": "fil",
    "he": "iw",
    "zh": "zh-CN",
}
WHISPER_SUPPORTED_LANGUAGES: set[str] = {
    code for code in BASE_LANGUAGES if code != "auto"
}
SUPPORTED_LANGUAGES: dict[str, str] = BASE_LANGUAGES.copy()
SORTED_LANGUAGES: list[tuple[str, str]] = sorted(
    ((name, code) for code, name in BASE_LANGUAGES.items()),
    key=lambda x: x[0],
)
LANGUAGE_SHORT_CODES: dict[str, str] = {
    code: name[:3] for code, name in BASE_LANGUAGES.items()
}
DISPLAY_NAME_TO_CODE: dict[str, str] = {
    name: code for code, name in BASE_LANGUAGES.items()
}


def get_whisper_language_code(display_name: str) -> str | None:
    """Gibt den Whisper‑Code für einen Anzeigenamen zurück."""
    return DISPLAY_NAME_TO_CODE.get(display_name)


def get_display_name(code: str) -> str:
    """Gibt den lesbaren Namen für einen Sprachcode zurück."""
    return BASE_LANGUAGES.get(code, code)


def map_to_google_code(whisper_code: str) -> str:
    """Konvertiert einen Whisper‑Sprachcode in den von Google Translate erwarteten Code."""
    if whisper_code == "auto":
        return "auto"
    return LANGUAGE_CODE_MAPPING.get(whisper_code, whisper_code)


def is_whisper_language_code(code: str) -> bool:
    """Prüft, ob ein gegebener Code von Whisper direkt unterstützt wird."""
    return code in WHISPER_SUPPORTED_LANGUAGES


def is_valid_source_language(display_name: str) -> bool:
    """Prüft, ob ein Anzeigename eine gültige Quellsprache für Whisper ist."""
    return display_name in DISPLAY_NAME_TO_CODE


COMMON_LANGUAGE_CODES: list[str] = [
    "de",
    "en",
    "fr",
    "es",
    "it",
    "pt",
    "nl",
    "pl",
    "ru",
]
ASIAN_LANGUAGE_CODES: list[str] = [
    "ja",
    "zh",
    "ko",
    "vi",
    "th",
    "id",
    "tl",
    "hi",
    "ar",
    "fa",
    "tr",
]

_COMMON_NAMES: list[str] | None = None
_ASIAN_NAMES: list[str] | None = None
_OTHER_NAMES: list[str] | None = None


def get_common_language_names() -> list[str]:
    """Gibt die lesbaren Namen der häufigsten Sprachen zurück (mit Caching)."""
    global _COMMON_NAMES
    if _COMMON_NAMES is None:
        _COMMON_NAMES = [
            BASE_LANGUAGES[code]
            for code in COMMON_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _COMMON_NAMES.copy()


def get_asian_language_names() -> list[str]:
    """Gibt die lesbaren Namen asiatischer / nahöstlicher Sprachen zurück (mit Caching)."""
    global _ASIAN_NAMES
    if _ASIAN_NAMES is None:
        _ASIAN_NAMES = [
            BASE_LANGUAGES[code]
            for code in ASIAN_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _ASIAN_NAMES.copy()


def get_other_language_names() -> list[str]:
    """Gibt alle übrigen lesbaren Sprachnamen zurück, die nicht in den
    vordefinierten Gruppen sind (mit Caching).
    """
    global _OTHER_NAMES
    if _OTHER_NAMES is None:
        excluded = set(COMMON_LANGUAGE_CODES + ASIAN_LANGUAGE_CODES)
        _OTHER_NAMES = [
            name
            for name, code in SORTED_LANGUAGES
            if code not in excluded and code != "auto"
        ]
    return _OTHER_NAMES.copy()


_DRAGON_LOGGER = None


def _get_dragon_logger() -> logging.Logger:
    """Liefert den zentralen Dragon-Logger (lazy initialisiert)."""
    global _DRAGON_LOGGER
    if _DRAGON_LOGGER is None:
        _DRAGON_LOGGER = logging.getLogger("dragon")
    return _DRAGON_LOGGER


def log_warning(component: str, message: str, level: int = 3) -> None:
    """Loggt eine Warnung mit Komponenten-Kontext."""
    if level <= DEBUG_LEVEL:
        logger.warning(f"[{component.upper()}] {message}")

_AI_LOG_ENABLED = False
try:
    import os as _os_ai

    _AI_LOG_ENABLED = _os_ai.environ.get("DW_AI_LOG", "0").lower() in (
        "1",
        "true",
        "yes",
        "on",
    )
except Exception:
    pass


_DW_USER_STOP_AT: float = 0.0
_DW_TARGET_LANG: str = "de"
_RE_PYERR = re.compile(r"^[A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception):")


def _mark_user_stop() -> None:
    """Markiert einen User-Stop modulweit mit Zeitstempel."""
    global _DW_USER_STOP_AT
    try:
        import time as _t

        _DW_USER_STOP_AT = _t.time()
    except Exception:
        pass


def _set_target_lang(lang: str | None) -> None:
    """Setzt die modulweite Ziel-Sprache (durch Init aufgerufen)."""
    global _DW_TARGET_LANG
    if lang:
        _DW_TARGET_LANG = str(lang).strip() or "de"


def _get_target_lang() -> str:
    """Liefert die modulweite Ziel-Sprache."""
    return _DW_TARGET_LANG


def _was_user_stop(window_s: float = 15.0) -> bool:
    """True, wenn innerhalb der letzten `window_s` Sekunden ein User-Stop war."""
    if _DW_USER_STOP_AT <= 0.0:
        return False
    try:
        import time as _t

        return (_t.time() - _DW_USER_STOP_AT) < window_s
    except Exception:
        return False


def log_ai(tag: str, **fields: Any) -> None:
    """Schreibt eine strukturierte AI-Marker-Zeile nach stderr.

    Format: [AI-<TAG>] key=value key=value ...

    Aktiv nur bei DW_AI_LOG=1. Kein Overhead wenn deaktiviert.
    Fehler werden geschluckt - Logging darf nie crashen.
    """
    if not _AI_LOG_ENABLED:
        return
    try:
        if fields:
            parts = " ".join(f"{k}={v}" for k, v in fields.items())
            line = f"[AI-{tag}] {parts}"
        else:
            line = f"[AI-{tag}]"
        sys.stderr.write(line + "\n")
        sys.stderr.flush()
    except Exception:
        pass


def log_debug(
    component: str,
    msg: str,
    *args: Any,
    exc_info: Exception | None = None,
    stacklevel: int = 2,
    **kwargs: Any,
) -> bool:
    """Schreibt eine Debug-Meldung mit Komponenten-Kontext."""
    try:
        testing = globals().get("_TESTING", False)
        debug_level = globals().get("DEBUG_LEVEL", 0)
    except Exception:
        testing = False
        debug_level = 0

    if not testing and debug_level < 1:
        return False

    if not component or not isinstance(component, str):
        component = "general"
    else:
        component = component.strip() or "general"

    extra = kwargs.pop("extra", {})
    if not isinstance(extra, dict):
        extra = {}
    extra.setdefault("component", component)

    try:
        log = _get_dragon_logger()
    except Exception:
        with contextlib.suppress(Exception):
            print(f"[DEBUG][{component}] {msg}", file=sys.stderr)
        return False

    try:
        if not log.isEnabledFor(logging.DEBUG):
            return True
    except Exception:
        pass

    formatted_msg: str
    formatted_args: tuple = ()

    try:
        if not args:
            formatted_msg = msg
            formatted_args = ()

        else:
            formatted_msg = None  # type: ignore[assignment]

            if "%" in msg:
                try:
                    _ = msg % args
                    formatted_msg = msg
                    formatted_args = args
                except (TypeError, ValueError, KeyError):
                    formatted_msg = None  # type: ignore[assignment]

            if formatted_msg is None and "{" in msg:
                try:
                    formatted_msg = msg.format(*args)
                except (IndexError, KeyError, TypeError, ValueError):
                    formatted_msg = None  # type: ignore[assignment]

            if formatted_msg is None:
                try:
                    _joined = " ".join(str(a) for a in args)
                    formatted_msg = f"{msg} {_joined}" if _joined else str(msg)
                except Exception:
                    formatted_msg = str(msg)

    except Exception as fmt_exc:
        with contextlib.suppress(Exception):
            log.warning(
                "[log_debug] Formatierung fehlgeschlagen (msg=%r): %s",
                str(msg)[:120],
                fmt_exc,
                extra={"component": "log_debug"},
            )
        formatted_msg = str(msg)
        formatted_args = ()

    try:
        emit_kwargs: dict = {
            "extra": extra,
            "stacklevel": stacklevel,
            **kwargs,
        }
        if exc_info is not None:
            emit_kwargs["exc_info"] = exc_info

        if formatted_args:
            log.debug(formatted_msg, *formatted_args, **emit_kwargs)
        else:
            log.debug(formatted_msg, **emit_kwargs)
        return True

    except Exception as emit_exc:
        try:
            print(
                f"[DEBUG][{component}] {formatted_msg}",
                file=sys.stderr,
            )
            if exc_info is not None:
                traceback.print_exception(
                    type(exc_info),
                    exc_info,
                    exc_info.__traceback__,
                    file=sys.stderr,
                )
            print(
                f"[log_debug] Emission fehlgeschlagen: {emit_exc}",
                file=sys.stderr,
            )
        except Exception:
            pass
        return False


def get_log_debug_stats() -> dict:
    """Liefert die Diagnose-Statistik von log_debug.

    Beispiel-Ausgabe:
        {'calls': 4521, 'passthrough': 380, 'c_style_lazy': 4100,
         'format_style': 40, 'mixed_style': 1, 'fallback_concat': 0,
         'errors': 0, 'suppressed': 80}
    """
    stats = getattr(log_debug, "_stats", None)
    return dict(stats) if stats else {}


def reset_log_debug_stats() -> None:
    """Setzt die Diagnose-Statistik zurück."""
    if hasattr(log_debug, "_stats"):
        for k in log_debug._stats:  # type: ignore[attr-defined]
            log_debug._stats[k] = 0  # type: ignore[attr-defined]


def log_info(component: str, message: str) -> None:
    """Loggt eine Info-Nachricht mit Komponenten-Kontext."""
    logger.info(f"[{component.upper()}] {message}")


def log_error(component: str, message: str) -> None:
    """Loggt eine Fehler-Nachricht mit Komponenten-Kontext."""
    logger.error(f"[{component.upper()}] ❌ {message}")


def log_exception(
    component: str,
    msg: str,
    exc: Exception,
    level: str = "error",
    *,
    stacklevel: int = 2,
    extra: dict[str, Any] | None = None,
    **kwargs: Any,
) -> None:
    """Protokolliert eine Exception mit Komponenten‑Kontext."""
    if not component or not isinstance(component, str):
        component = "general"
    else:
        component = component.strip()

    if not msg or not isinstance(msg, str):
        msg = "No message"

    level_lower = level.lower() if isinstance(level, str) else "error"
    if level_lower not in ("error", "warning", "info", "debug"):
        level_lower = "error"

    formatted_msg = f"[{component}] {msg}"
    extra_dict = extra.copy() if extra and isinstance(extra, dict) else {}
    extra_dict["component"] = component
    log = _get_dragon_logger()

    try:
        if level_lower == "error":
            if log.isEnabledFor(logging.ERROR):
                log.error(
                    formatted_msg,
                    exc_info=exc,
                    extra=extra_dict,
                    stacklevel=stacklevel,
                    **kwargs,
                )
        elif level_lower == "warning":
            if log.isEnabledFor(logging.WARNING):
                log.warning(
                    formatted_msg,
                    exc_info=exc,
                    extra=extra_dict,
                    stacklevel=stacklevel,
                    **kwargs,
                )
        elif level_lower == "info":
            if log.isEnabledFor(logging.INFO):
                log.info(
                    formatted_msg,
                    exc_info=exc,
                    extra=extra_dict,
                    stacklevel=stacklevel,
                    **kwargs,
                )
        elif log.isEnabledFor(logging.DEBUG):
            log.debug(
                formatted_msg,
                exc_info=exc,
                extra=extra_dict,
                stacklevel=stacklevel,
                **kwargs,
            )
    except Exception:
        try:
            print(f"[{level_lower.upper()}][{component}] {msg}: {exc}", file=sys.stderr)
            if globals().get("DEBUG_LEVEL", 0) >= 3:
                traceback.print_exc(file=sys.stderr)
        except Exception:
            pass


class _TokenBucket:
    """Thread-sicherer Token-Bucket für Rate-Limiting."""

    __slots__ = ("_lock", "capacity", "last_refill", "rate", "tokens")

    def __init__(self, rate: float, capacity: float) -> None:
        """Args:
        rate: Nachfüllrate in Tokens pro Sekunde (muss > 0 sein).
        capacity: Maximale Anzahl an Tokens im Bucket (muss > 0 sein).

        """
        if rate <= 0:
            raise ValueError("rate must be positive")
        if capacity <= 0:
            raise ValueError("capacity must be positive")

        self.rate = float(rate)
        self.capacity = float(capacity)
        self.tokens = float(capacity)
        self.last_refill = time.monotonic()
        self._lock = threading.Lock()

    def consume(self, tokens: float = 1.0) -> bool:
        """Versucht, eine bestimmte Anzahl Tokens zu konsumieren."""
        if tokens <= 0:
            return True

        with self._lock:
            now = time.monotonic()
            elapsed = now - self.last_refill
            self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
            self.last_refill = now

            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            return False

    def set_rate(self, rate: float) -> None:
        """Ändert die Nachfüllrate zur Laufzeit (adaptiv).

        ★ v2.1: Wird vom Circuit-Breaker genutzt, um Google bei
        Fehlern zu drosseln und bei Erfolg wieder zu beschleunigen.
        """
        if rate <= 0:
            raise ValueError("rate must be positive")
        with self._lock:
            self.rate = float(rate)

    def available_tokens(self) -> float:
        """Gibt die aktuelle Anzahl verfügbarer Tokens zurück (ohne zu konsumieren)."""
        with self._lock:
            now = time.monotonic()
            elapsed = now - self.last_refill
            current = min(self.capacity, self.tokens + elapsed * self.rate)
            return current

    def reset(self) -> None:
        """Setzt den Bucket auf volle Kapazität zurück."""
        with self._lock:
            self.tokens = self.capacity
            self.last_refill = time.monotonic()


class EventBus:
    """Hochoptimierter, thread-sicherer Event-Bus."""

    def __init__(
        self,
        debug: bool = False,
        scheduler: Callable[..., None] | None = None,
        use_weakref: bool = False,
        executor: ThreadPoolExecutor | None = None,
        max_pattern_cache: int = 512,
        max_rate_buckets: int = 256,
        enable_metrics: bool | None = None,
        error_handler: Callable[[str, Exception, Any], None] | None = None,
        rate_limit_capacity: float = 1.0,
    ) -> None:
        self._debug = debug
        self._use_weakref = use_weakref
        self._scheduler = scheduler
        self._executor = executor
        self._queue_manager = None
        self._global_error_handler = error_handler

        self._lock = threading.RLock()
        self._pattern_cache_lock = threading.Lock()
        self._rate_lock = threading.Lock()
        self._metrics_lock = threading.Lock()

        self._exact: dict[str, list[Any]] = defaultdict(list)
        self._patterns: list[tuple[str, Any]] = []

        self._pattern_cache: OrderedDict[tuple[str, str], bool] = OrderedDict()
        self._pattern_cache_max = max_pattern_cache

        self._rate_limit: float | None = None
        self._rate_limit_capacity = rate_limit_capacity
        self._rate_buckets: dict[str, _TokenBucket] = {}
        self._rate_buckets_max = max_rate_buckets

        self._metrics_enabled = enable_metrics if enable_metrics is not None else debug
        self._metrics: dict[str, Any] = {
            "total_events": 0,
            "events_per_type": defaultdict(int),
            "errors": 0,
            "dropped_events": 0,
            "callback_executions": 0,
            "callback_total_time": 0.0,
            "start_time": time.time(),
            "last_event_time": None,
        }

        if debug:
            logger.debug(
                "EventBus initialisiert (debug=True, weakref=%s, executor=%s, scheduler=%s)",
                use_weakref,
                executor is not None,
                scheduler is not None,
            )

    def _store_callback(self, callback: Callable) -> Any:
        """Speichert den Callback (stark oder als WeakRef) und gibt den gespeicherten Wert zurück."""
        if not callable(callback):
            raise TypeError("callback must be callable")
        if self._use_weakref:
            if hasattr(callback, "__self__") and hasattr(callback, "__func__"):
                return weakref.WeakMethod(callback)
            return weakref.ref(callback)
        return callback

    def _call_stored(self, stored: Any) -> Callable | None:
        """Löst den tatsächlichen Callback aus dem gespeicherten Wert auf (oder None)."""
        if stored is None:
            return None
        if self._use_weakref and isinstance(stored, (weakref.ref, weakref.WeakMethod)):
            return stored()
        return stored

    def _cleanup_dead_weakrefs(self) -> None:
        """Entfernt tote WeakRefs aus den Subscription-Listen (nur bei WeakRefs sinnvoll)."""
        if not self._use_weakref:
            return
        with self._lock:
            for event_type in list(self._exact.keys()):
                self._exact[event_type] = [
                    cb
                    for cb in self._exact[event_type]
                    if self._call_stored(cb) is not None
                ]
                if not self._exact[event_type]:
                    del self._exact[event_type]
            self._patterns = [
                (p, cb) for p, cb in self._patterns if self._call_stored(cb) is not None
            ]

    def _matches_pattern_cached(self, pattern: str, event_type: str) -> bool:
        """Thread-sicherer Pattern-Check mit LRU-Cache."""
        key = (pattern, event_type)
        with self._pattern_cache_lock:
            if key in self._pattern_cache:
                self._pattern_cache.move_to_end(key)
                return self._pattern_cache[key]

            result = fnmatch.fnmatch(event_type, pattern)
            self._pattern_cache[key] = result
            if len(self._pattern_cache) > self._pattern_cache_max:
                self._pattern_cache.popitem(last=False)
            return result

    def _get_rate_bucket(self, event_type: str) -> _TokenBucket | None:
        """Holt oder erstellt den Token-Bucket für einen Event-Typ (mit Begrenzung)."""
        with self._rate_lock:
            bucket = self._rate_buckets.get(event_type)
            if bucket is None:
                if self._rate_limit is None:
                    return None
                if len(self._rate_buckets) >= self._rate_buckets_max:
                    oldest = next(iter(self._rate_buckets))
                    del self._rate_buckets[oldest]
                bucket = _TokenBucket(self._rate_limit, self._rate_limit_capacity)
                self._rate_buckets[event_type] = bucket
            return bucket

    def _check_rate_limit(self, event_type: str) -> bool:
        """Prüft, ob ein Event aufgrund von Rate-Limiting erlaubt ist."""
        if self._rate_limit is None:
            return True
        bucket = self._get_rate_bucket(event_type)
        if bucket is None:
            return True
        return bucket.consume()

    def set_global_error_handler(
        self,
        handler: Callable[[str, Exception, Any], None],
    ) -> None:
        """Registriert einen globalen Error-Handler für Callback-Fehler."""
        with self._lock:
            self._global_error_handler = handler

    def set_queue_manager(self, qm: Any) -> None:
        """Setzt einen QueueManager für asynchrone Ausführung über eine GUI-Queue."""
        with self._lock:
            self._queue_manager = qm

    def set_scheduler(self, scheduler: Callable[[Callable, int], None]) -> None:
        """Setzt einen externen Scheduler (z.B. für GUI-Threads)."""
        with self._lock:
            self._scheduler = scheduler
        if self._debug:
            log_debug("eventbus", "Scheduler gesetzt")

    def subscribe(self, event_type: str, callback: Callable[[Any], None]) -> None:
        """Abonniert einen Callback für einen exakten Event-Typ.
        Duplikate sind erlaubt (gleicher Callback kann mehrfach registriert werden).
        """
        if not callable(callback):
            raise TypeError("callback must be callable")
        with self._lock:
            stored = self._store_callback(callback)
            self._exact[event_type].append(stored)
        if self._debug:
            log_debug("eventbus", "Subscribed exact '%s'", event_type)

    def subscribe_pattern(self, pattern: str, callback: Callable[[Any], None]) -> None:
        """Abonniert einen Callback für alle Event-Typen, die dem Pattern (fnmatch) entsprechen."""
        if not callable(callback):
            raise TypeError("callback must be callable")
        with self._lock:
            stored = self._store_callback(callback)
            self._patterns.append((pattern, stored))
        if self._debug:
            log_debug("eventbus", "Subscribed pattern '%s'", pattern)

    def subscribe_once(self, event_type: str, callback: Callable[[Any], None]) -> None:
        """Abonniert einen Callback, der nach dem ersten Aufruf automatisch entfernt wird."""

        def _once_wrapper(data: Any, _cb=callback, _ev=event_type, _self=self):
            try:
                _cb(data)
            finally:
                _self.unsubscribe(_ev, _once_wrapper)

        self.subscribe(event_type, _once_wrapper)

    def unsubscribe(self, event_type: str, callback: Callable) -> bool:
        """Entfernt alle Vorkommen eines Callbacks für einen exakten Event-Typ.
        Gibt True zurück, wenn mindestens eine Subscription entfernt wurde.
        """
        with self._lock:
            if event_type not in self._exact:
                return False
            original_len = len(self._exact[event_type])
            self._exact[event_type] = [
                stored
                for stored in self._exact[event_type]
                if self._call_stored(stored) is not callback
            ]
            if not self._exact[event_type]:
                del self._exact[event_type]
            removed = original_len - len(self._exact.get(event_type, []))
            if removed > 0:
                if self._debug:
                    log_debug(
                        "eventbus",
                        "Unsubscribed exact '%s' (%d removed)",
                        event_type,
                        removed,
                    )
                return True
            return False

    def unsubscribe_pattern(self, pattern: str, callback: Callable) -> bool:
        """Entfernt alle Vorkommen eines Callbacks für ein bestimmtes Pattern."""
        with self._lock:
            original_len = len(self._patterns)
            self._patterns = [
                (p, stored)
                for p, stored in self._patterns
                if not (p == pattern and self._call_stored(stored) is callback)
            ]
            removed = original_len - len(self._patterns)
            if removed > 0:
                if self._debug:
                    log_debug(
                        "eventbus",
                        "Unsubscribed pattern '%s' (%d removed)",
                        pattern,
                        removed,
                    )
                return True
            return False

    def unsubscribe_all(self, event_type: str | None = None) -> None:
        """Entfernt alle Subscriptions. Wenn event_type angegeben, nur für diesen Typ."""
        with self._lock:
            if event_type is None:
                self._exact.clear()
                self._patterns.clear()
                if self._debug:
                    log_debug("eventbus", "Alle Subscriptions entfernt")
            elif event_type in self._exact:
                del self._exact[event_type]
                if self._debug:
                    log_debug(
                        "eventbus",
                        "Alle exact-Subscriptions für '%s' entfernt",
                        event_type,
                    )

    def set_rate_limit(
        self,
        events_per_second: float | None,
        capacity: float | None = None,
    ) -> None:
        """Setzt ein Rate-Limit (Events pro Sekunde) für alle Event-Typen.
        None deaktiviert das Limit. Optional kann die Bucket-Kapazität angepasst werden.
        """
        with self._rate_lock:
            self._rate_limit = events_per_second
            if capacity is not None:
                self._rate_limit_capacity = capacity
            self._rate_buckets.clear()
        if self._debug:
            log_debug(
                "eventbus",
                "Rate-Limit gesetzt auf %s events/sec (capacity=%s)",
                events_per_second,
                self._rate_limit_capacity,
            )

    def emit(self, event_type: str, data: Any = None) -> None:
        """Emittiert ein Event an alle passenden Subscriber."""
        if self._metrics_enabled:
            with self._metrics_lock:
                self._metrics["total_events"] += 1
                self._metrics["events_per_type"][event_type] += 1
                self._metrics["last_event_time"] = time.time()

        if not self._check_rate_limit(event_type):
            if self._debug:
                log_debug(
                    "eventbus",
                    "Rate-Limit für '%s' erreicht – Event unterdrückt",
                    event_type,
                )
            if self._metrics_enabled:
                with self._metrics_lock:
                    self._metrics["dropped_events"] += 1
            return

        if self._debug:
            log_debug("eventbus", "Emitting '%s'", event_type)

        with self._lock:
            exact_stored = list(self._exact.get(event_type, []))
            pattern_items = list(self._patterns)

        exact_callbacks = []
        for stored in exact_stored:
            cb = self._call_stored(stored)
            if cb is not None:
                exact_callbacks.append(cb)

        pattern_callbacks = []
        for pattern, stored in pattern_items:
            if self._matches_pattern_cached(pattern, event_type):
                cb = self._call_stored(stored)
                if cb is not None:
                    pattern_callbacks.append(cb)

        all_callbacks = exact_callbacks + pattern_callbacks
        if not all_callbacks:
            return

        def _invoke(cb: Callable) -> None:
            start = time.time()
            try:
                cb(data)
            except Exception as e:
                logger.error(
                    "EventBus callback error for '%s': %s",
                    event_type,
                    e,
                    exc_info=True,
                )
                if self._metrics_enabled:
                    with self._metrics_lock:
                        self._metrics["errors"] += 1
                if self._global_error_handler:
                    try:
                        self._global_error_handler(event_type, e, data)
                    except Exception:
                        logger.exception("Error in global error handler")
            finally:
                if self._metrics_enabled:
                    dur = time.time() - start
                    with self._metrics_lock:
                        self._metrics["callback_executions"] += 1
                        self._metrics["callback_total_time"] += dur

        is_main_thread = threading.current_thread() is threading.main_thread()
        use_queue = self._queue_manager is not None and (
            not is_main_thread or getattr(self, "_force_queue", False)
        )

        if self._executor is not None:
            for cb in all_callbacks:
                self._executor.submit(_invoke, cb)
        elif use_queue:
            qm = self._queue_manager
            for cb in all_callbacks:

                def _wrapper(cb=cb, data=data):
                    _invoke(cb)

                qm.safe_put("gui", ("callback", _wrapper, True))
        else:
            for cb in all_callbacks:
                if is_main_thread and self._scheduler is not None:
                    self._scheduler(lambda _cb=cb: _invoke(_cb), 0)
                else:
                    _invoke(cb)

    def get_metrics(self) -> dict[str, Any]:
        """Gibt gesammelte Metriken zurück (nur wenn aktiviert, sonst leeres Dict)."""
        if not self._metrics_enabled:
            return {}
        with self._metrics_lock:
            metrics = self._metrics.copy()
            metrics["uptime"] = time.time() - metrics["start_time"]
            metrics["events_per_type"] = dict(metrics["events_per_type"])
            return metrics

    def get_debug_info(self) -> dict[str, Any]:
        """Gibt detaillierte Debug-Informationen zurück."""
        if not self._debug:
            return {"debug_enabled": False}
        with self._lock:
            exact_counts = {k: len(v) for k, v in self._exact.items()}
            pattern_count = len(self._patterns)
        return {
            "debug_enabled": True,
            "exact_subscriptions": exact_counts,
            "pattern_subscriptions": pattern_count,
            "has_scheduler": self._scheduler is not None,
            "has_executor": self._executor is not None,
            "has_queue_manager": self._queue_manager is not None,
            "metrics": self.get_metrics(),
            "pattern_cache_size": len(self._pattern_cache),
            "rate_buckets": len(self._rate_buckets),
        }

    def clear(self) -> None:
        """Entfernt alle Subscriptions und leert den Pattern-Cache."""
        with self._lock:
            self._exact.clear()
            self._patterns.clear()
        with self._pattern_cache_lock:
            self._pattern_cache.clear()
        if self._debug:
            log_debug("eventbus", "All subscriptions and pattern cache cleared")

    @contextlib.contextmanager
    def subscription_context(self, event_type: str, callback: Callable[[Any], None]):
        """Context-Manager, der die Subscription für die Dauer des Blocks aufrechterhält."""
        self.subscribe(event_type, callback)
        try:
            yield
        finally:
            self.unsubscribe(event_type, callback)

    @contextlib.contextmanager
    def pattern_subscription_context(
        self,
        pattern: str,
        callback: Callable[[Any], None],
    ):
        """Context-Manager für Pattern-Subscriptions."""
        self.subscribe_pattern(pattern, callback)
        try:
            yield
        finally:
            self.unsubscribe_pattern(pattern, callback)

    def __repr__(self) -> str:
        with self._lock:
            exact_count = sum(len(v) for v in self._exact.values())
            pattern_count = len(self._patterns)
        return (
            f"<EventBus exact={exact_count} patterns={pattern_count} "
            f"scheduler={self._scheduler is not None} executor={self._executor is not None}>"
        )


class PeriodicTaskMixin:
    """Basisklasse für periodische Hintergrundaufgaben in einem eigenen Thread.
    Bietet unterbrechbaren Schlaf, Fehlerzählung und sauberen Shutdown.
    """

    SLEEP_CHUNK_SIZE = 0.5

    __slots__ = (
        "_error_count",
        "_initial_delay",
        "_interval",
        "_max_errors",
        "_on_error",
        "_started",
        "_stop_event",
        "_task",
        "_task_args",
        "_task_kwargs",
        "_thread",
    )

    def __init__(
        self,
        interval: float,
        task: Callable[..., Any],
        *args: Any,
        thread_name: str | None = None,
        initial_delay: float = 0.0,
        max_errors: int = 0,
        on_error: Callable[[Exception], None] | None = None,
        **kwargs: Any,
    ) -> None:
        """Args:
        interval: Wartezeit in Sekunden zwischen zwei Ausführungen.
        task: Die auszuführende Funktion.
        thread_name: Name des Hintergrundthreads.
        initial_delay: Verzögerung vor der ersten Ausführung (in Sekunden).
        max_errors: Maximale Anzahl aufeinanderfolgender Fehler, bevor der Thread stoppt (0 = unbegrenzt).
        on_error: Callback, der bei jedem Fehler aufgerufen wird.
        """
        self._interval = float(interval)
        self._task = task
        self._task_args = args
        self._task_kwargs = kwargs
        self._max_errors = max_errors
        self._on_error = on_error
        self._error_count = 0
        self._initial_delay = float(initial_delay)
        self._stop_event = threading.Event()
        self._started = False

        self._thread = threading.Thread(
            target=self._run,
            daemon=True,
            name=thread_name or f"Periodic-{id(self)}",
        )

        self._thread.start()
        self._started = True

    def _run(self) -> None:
        """Hauptschleife des Hintergrundthreads."""
        if self._initial_delay > 0:
            if self._sleep_with_stop(self._initial_delay):
                return

        while not self._stop_event.is_set():
            if self._sleep_with_stop(self._interval):
                break

            try:
                self._task(*self._task_args, **self._task_kwargs)
                self._error_count = 0
            except Exception as e:
                self._error_count += 1
                if self._on_error is not None:
                    try:
                        self._on_error(e)
                    except Exception as callback_err:
                        logger.error(
                            "Fehler im on_error-Callback von PeriodicTaskMixin: %s",
                            callback_err,
                            exc_info=DEBUG_LEVEL >= 3,
                        )
                if self._max_errors > 0 and self._error_count >= self._max_errors:
                    logger.warning(
                        "PeriodicTaskMixin: Maximale Fehleranzahl (%d) erreicht – Thread wird beendet.",
                        self._max_errors,
                    )
                    self._stop_event.set()
                    break

    def _sleep_with_stop(self, duration: float) -> bool:
        """Schlafe für `duration` Sekunden, unterbreche aber sofort,
        wenn das Stop‑Event gesetzt wird.
        Gibt True zurück, wenn das Stop‑Event während des Schlafs gesetzt wurde, sonst False.
        """
        if duration <= 0:
            return self._stop_event.is_set()

        chunk = self.SLEEP_CHUNK_SIZE
        while duration > 0 and not self._stop_event.is_set():
            sleep_time = min(chunk, duration)
            time.sleep(sleep_time)
            duration -= sleep_time

        return self._stop_event.is_set()

    def stop(self, timeout: float = 2.0) -> bool:
        """Stoppt den periodischen Thread und wartet auf seine Beendigung.
        Gibt True zurück, wenn der Thread innerhalb des Timeouts beendet wurde, sonst False.
        """
        self._stop_event.set()
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)
            return not self._thread.is_alive()
        return True

    def wait_for_stop(self, timeout: float = 2.0) -> bool:
        """Wartet auf das Ende des Threads (ohne das Stop‑Event zu setzen)."""
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)
            return not self._thread.is_alive()
        return True

    def is_running(self) -> bool:
        """Gibt zurück, ob der Hintergrundthread noch läuft."""
        return self._started and self._thread.is_alive()

    def join(self, timeout: float = 2.0) -> bool:
        """Alias für wait_for_stop (Kompatibilität)."""
        return self.wait_for_stop(timeout)


class BaseDialog:
    """BASISKLASSE für alle modalen Dialoge in Dragon Whisperer."""

    _LEVEL_LABELS: dict[int, str] = {
        0: "TRACE",
        1: "DEBUG",
        2: "INFO",
        3: "DEBUG",
        4: "DEBUG",
        5: "TRACE",
    }

    _ERROR_LEVEL_THRESHOLD: int = 3

    def __init__(
        self,
        parent: tk.Widget | tk.Tk,
        title: str,
        width: int = 600,
        height: int = 400,
        timeout: int | None = None,
        modal: bool = True,
        close_on_escape: bool = True,
        resizable: bool = False,
        on_close_callback: Callable[[], None] | None = None,
    ) -> None:
        """Initialisiert den Dialog und erstellt das Fenster."""
        self._logger = logging.getLogger("dragon")
        self.parent = parent
        self.title = title
        self._close_lock = threading.RLock()
        self._log_lock = threading.RLock()

        self._closed = False
        self._closing_in_progress = False
        self._init_done = False
        self._theme_applied = False
        self._safe_parent_cache: tk.Widget | None = None

        raw_debug = self._get_debug_level()
        try:
            self._debug_level = int(raw_debug)
        except (ValueError, TypeError):
            self._debug_level = 0

        self.width = max(100, int(width))
        self.height = max(100, int(height))
        self.timeout = int(timeout) if (timeout is not None and timeout > 0) else None
        self.modal = bool(modal)
        self.close_on_escape = bool(close_on_escape)
        self.resizable = bool(resizable)
        self._on_close_callback = on_close_callback

        self._theme = self._get_theme_safe()
        self.dialog: tk.Toplevel | None = None
        self.main: tk.Frame | None = None
        self._log_debug(
            3,
            f"[BASEDIALOG] __init__ start: title='{title}', modal={modal}",
        )

        if self._on_close_callback is not None:
            self._log_debug(
                2,
                f"[BASEDIALOG] ⚠️ on_close_callback gesetzt: "
                f"{self._on_close_callback.__name__} "
                "(Achtung: darf kein root.quit() enthalten!)",
            )

        try:
            self.dialog = self._create_dialog()
            if self.dialog is None:
                raise RuntimeError("Dialogfenster konnte nicht erstellt werden")

            self.main = tk.Frame(
                self.dialog,
                bg=self._theme.BG_PRIMARY,
                padx=15,
                pady=15,
            )
            self.main.pack(fill="both", expand=True)
            self._register_in_parent()
            self._center_dialog()
            if self.close_on_escape:
                self.dialog.bind("<Escape>", lambda _e: self.close())

            if self.timeout is not None:
                self._timeout_id = self._safe_after(
                    int(self.timeout * 1000),
                    self._timeout_close,
                )
                self._log_debug(
                    3,
                    f"[BASEDIALOG] Timeout gestartet: {self.timeout}s",
                )

            if self.modal:
                self._make_modal()

            self.dialog.resizable(self.resizable, self.resizable)

            self._logger.debug("[BASEDIALOG] Rufe build_ui() auf...")
            try:
                self.build_ui()
            except Exception as exc:
                self._log_error(
                    f"[BASEDIALOG] build_ui() in "
                    f"{self.__class__.__name__} fehlgeschlagen",
                    exc,
                )
                try:
                    self.on_init_error(exc)
                except Exception as hook_exc:
                    self._log_error(
                        "[BASEDIALOG] on_init_error-Hook fehlgeschlagen",
                        hook_exc,
                    )
                raise
            self._logger.debug("[BASEDIALOG] build_ui() abgeschlossen")
            self._log_debug(3, "[BASEDIALOG] __init__ abgeschlossen")
            self._logger.debug(f"[BASEDIALOG] Theme: {self._theme.__class__.__name__}")
            self._logger.debug(f"[BASEDIALOG] BG_PRIMARY: {self._theme.BG_PRIMARY}")
            self._logger.debug(f"[BASEDIALOG] TEXT_PRIMARY: {self._theme.TEXT_PRIMARY}")

            self._init_done = True

        except Exception as exc:
            self._log_error(
                f"[BASEDIALOG] __init__ in {self.__class__.__name__} fehlgeschlagen",
                exc,
            )
            self._cleanup_on_init_failure()
            raise

    @property
    def is_closed(self) -> bool:
        """True, wenn der Dialog bereits geschlossen wurde."""
        return self._closed

    @property
    def is_visible(self) -> bool:
        """True, wenn der Dialog existiert und noch nicht geschlossen ist."""
        if self._closed or self.dialog is None:
            return False
        try:
            return bool(self.dialog.winfo_exists())
        except Exception:
            return False

    @property
    def is_initialized(self) -> bool:
        """True, wenn __init__ vollständig durchgelaufen ist."""
        return self._init_done

    def _get_debug_level(self) -> int:
        """Ermittelt das aktuelle Debug-Level aus verschiedenen Quellen."""
        debug_level = globals().get("DEBUG_LEVEL", 0)
        if debug_level > 0:
            return debug_level
        if hasattr(self, "debug_level"):
            return self.debug_level
        if hasattr(self.parent, "debug_level"):
            return self.parent.debug_level
        return 0

    def _log_debug(self, *args, **kwargs) -> None:
        """Flexible, crashsichere Debug-Methode für BaseDialog und Subklassen."""
        _guard_set = False
        try:
            if getattr(self, "_in_log_debug", False):
                return
            self._in_log_debug = True
            _guard_set = True
        except Exception:
            _guard_set = False

        try:
            level = 1
            message = ""
            exc_info = False
            component = None

            try:
                exc_info = bool(kwargs.pop("exc_info", False))
                component = kwargs.pop("component", None)

                if kwargs:
                    if "level" in kwargs:
                        try:
                            level = int(kwargs["level"])
                        except (ValueError, TypeError):
                            level = 1
                    if "message" in kwargs:
                        message = str(kwargs["message"])
                    elif "msg" in kwargs:
                        message = str(kwargs["msg"])
                elif len(args) == 1:
                    message = str(args[0])
                elif len(args) >= 2:
                    try:
                        level = int(args[0])
                    except (ValueError, TypeError):
                        level = 1
                    message = str(args[1]) if len(args) > 1 else ""
            except Exception:
                level = 1
                message = "<_log_debug: Argument-Parsing fehlgeschlagen>"

            try:
                debug_level = int(getattr(self, "_debug_level", 0))
            except (ValueError, TypeError):
                debug_level = 0

            try:
                error_threshold = int(getattr(self, "_ERROR_LEVEL_THRESHOLD", 3))
            except (ValueError, TypeError):
                error_threshold = 3

            if level < error_threshold and debug_level < level:
                return

            filename = "<unknown>"
            lineno = 0
            func_name = "<unknown>"

            frame = None
            try:
                frame = inspect.currentframe()
                caller_frame = frame.f_back if frame is not None else None
                internal_names = (
                    "_log_debug",
                    "_log_error",
                    "_log_info",
                    "_log_warning",
                )
                depth = 0
                while (
                    caller_frame is not None
                    and depth < 8
                    and caller_frame.f_code.co_name in internal_names
                ):
                    caller_frame = caller_frame.f_back
                    depth += 1

                if caller_frame is not None:
                    filename = caller_frame.f_code.co_filename
                    lineno = caller_frame.f_lineno
                    func_name = caller_frame.f_code.co_name
            except Exception:
                pass
            finally:
                with contextlib.suppress(Exception):
                    del frame

            try:
                now = datetime.now().astimezone()
                timestamp = (
                    now.strftime("%Y-%m-%d %H:%M:%S")
                    + f".{now.microsecond // 1000:03d}"
                    + now.strftime("%z")
                )
            except Exception:
                timestamp = "0000-00-00 00:00:00.000 +0000"

            try:
                level_labels = getattr(self, "_LEVEL_LABELS", None)
                if isinstance(level_labels, dict):
                    level_name = level_labels.get(level, f"L{level}")
                else:
                    level_name = f"L{level}"
            except Exception:
                level_name = f"L{level}"

            try:
                class_name = self.__class__.__name__
            except Exception:
                class_name = "<unknown>"
            try:
                module_name = self.__class__.__module__
            except Exception:
                module_name = "<unknown>"

            try:
                short_filename = filename.rsplit("/", 1)[-1].rsplit("\\", 1)[-1]
            except Exception:
                short_filename = filename

            try:
                log_line = (
                    f"[{timestamp}] [{level_name}]"
                    f"[{module_name}.{class_name}] {func_name}()"
                    f"({short_filename}:{lineno}) - {message}"
                )
            except Exception:
                log_line = f"[{timestamp}] [L{level}] {message!r}"

            logger = getattr(self, "_logger", None)
            if logger is not None:
                try:
                    extra = {"component": component or "basedialog"}
                    logger.debug(log_line, exc_info=exc_info, extra=extra)
                    return
                except Exception:
                    pass

            try:
                target = sys.stderr if level >= error_threshold else sys.stdout
                if target is None:
                    return
                target.write(log_line + "\n")
                with contextlib.suppress(Exception):
                    target.flush()
            except Exception:
                pass

        finally:
            if _guard_set:
                with contextlib.suppress(Exception):
                    self._in_log_debug = False

    def _log_error(
        self,
        message: str,
        exc: BaseException | None = None,
    ) -> None:
        """Konsistente Fehlerausgabe."""
        full = message
        if exc is not None:
            full = f"{message}: {type(exc).__name__}: {exc}"

        self._log_debug(
            4,
            f"[BASEDIALOG] ❌ {full}",
            exc_info=exc is not None,
            component="basedialog",
        )

        logger = getattr(self, "_logger", None)
        if logger is not None:
            with contextlib.suppress(Exception):
                logger.error(
                    f"[BASEDIALOG] ❌ {full}",
                    exc_info=exc is not None,
                    extra={"component": "basedialog"},
                )

    @staticmethod
    def _get_theme_safe() -> Any:
        """Liefert ein gültiges Theme-Objekt (niemals None)."""
        theme = globals().get("CURRENT_THEME")
        if theme is not None:
            return theme
        return DarkTheme()

    def _get_safe_parent(self) -> tk.Widget:
        """Ermittelt ein garantiert existierendes Eltern-Widget.

        Das Ergebnis wird gecacht, solange das Widget existiert –
        mehrfache Aufrufe während `__init__` werden so auf einen
        einzigen Tk-Call reduziert.
        """
        cached = self._safe_parent_cache
        if cached is not None:
            try:
                if cached.winfo_exists():
                    return cached
            except Exception:
                pass
            self._safe_parent_cache = None

        try:
            if self.parent.winfo_exists():
                self._safe_parent_cache = self.parent
                return self.parent
        except Exception as e:
            self._log_debug(
                4,
                f"[BASEDIALOG] _get_safe_parent: parent nicht verfügbar: {e}",
            )

        root = tk._default_root
        if root is not None and root.winfo_exists():
            self._safe_parent_cache = root
            return root

        raise RuntimeError("Kein gültiges Eltern-Fenster verfügbar")

    def _register_in_parent(self) -> None:
        """Registriert den Dialog in der Parent-Liste (falls vorhanden)."""
        try:
            if (
                hasattr(self.parent, "_open_dialogs")
                and self.dialog not in self.parent._open_dialogs
            ):
                self.parent._open_dialogs.append(self.dialog)
                self._log_debug(
                    4,
                    "[BASEDIALOG] Dialog in parent._open_dialogs registriert",
                )
        except Exception as e:
            self._log_debug(
                4,
                f"[BASEDIALOG] Registrierung fehlgeschlagen: {e}",
            )

    def _unregister_from_parent(self) -> None:
        """Entfernt den Dialog aus der Parent-Liste (falls vorhanden)."""
        try:
            if (
                hasattr(self.parent, "_open_dialogs")
                and self.dialog in self.parent._open_dialogs
            ):
                self.parent._open_dialogs.remove(self.dialog)
                self._log_debug(
                    4,
                    "[BASEDIALOG] Dialog aus parent._open_dialogs entfernt",
                )
        except Exception as e:
            self._log_debug(
                4,
                f"[BASEDIALOG] Unregister fehlgeschlagen: {e}",
            )

    def _create_dialog(self) -> tk.Toplevel | None:
        """Erstellt das Toplevel-Fenster mit robuster Parent-Prüfung."""
        try:
            parent_widget = self._get_safe_parent()
            dlg = tk.Toplevel(parent_widget)

            display_title = (
                f"🐉 {self.title}" if not self.title.startswith("🐉") else self.title
            )
            dlg.title(display_title)
            dlg.configure(bg=self._theme.BG_PRIMARY)
            dlg.geometry(f"{self.width}x{self.height}")
            dlg.protocol("WM_DELETE_WINDOW", self.close)

            self._log_debug(
                3,
                f"[BASEDIALOG] Dialog erstellt: '{display_title}'",
            )
            return dlg

        except (tk.TclError, RuntimeError) as e:
            self._log_error(
                "[BASEDIALOG] Fehler beim Erstellen des Dialogs",
                e,
            )
            return None

    def _center_dialog(self) -> None:
        """Zentriert den Dialog relativ zum Parent (oder Bildschirm)."""
        if not self.dialog or not self.dialog.winfo_exists():
            return

        try:
            self.dialog.update_idletasks()
            dlg_w = self.dialog.winfo_width()
            dlg_h = self.dialog.winfo_height()
            if dlg_w <= 1 or dlg_h <= 1:
                dlg_w = self.width
                dlg_h = self.height

            x, y = None, None

            try:
                if self.parent.winfo_exists():
                    parent_x = self.parent.winfo_rootx()
                    parent_y = self.parent.winfo_rooty()
                    parent_w = self.parent.winfo_width()
                    parent_h = self.parent.winfo_height()
                    x = parent_x + (parent_w - dlg_w) // 2
                    y = parent_y + (parent_h - dlg_h) // 2
            except Exception as e:
                self._log_debug(
                    4,
                    f"[BASEDIALOG] Parent-Positionierung fehlgeschlagen: {e}",
                )

            if x is None or y is None:
                screen_w = self.dialog.winfo_screenwidth()
                screen_h = self.dialog.winfo_screenheight()
                x = (screen_w - dlg_w) // 2
                y = (screen_h - dlg_h) // 2
            else:
                screen_w = self.dialog.winfo_screenwidth()
                screen_h = self.dialog.winfo_screenheight()
                x = max(0, min(x, screen_w - dlg_w))
                y = max(0, min(y, screen_h - dlg_h))

            self.dialog.geometry(f"+{x}+{y}")
            self.dialog.lift()

        except Exception as e:
            self._log_error("[BASEDIALOG] Zentrierung fehlgeschlagen", e)

    def _make_modal(self) -> None:
        """Macht den Dialog modal (transient + grab_set)."""
        if not self.dialog or not self.dialog.winfo_exists():
            self._log_debug(
                3,
                "[BASEDIALOG] Dialog existiert nicht – überspringe modal",
            )
            return

        try:
            if self.parent and not self.parent.winfo_exists():
                self._log_debug(
                    3,
                    "[BASEDIALOG] Elternfenster existiert nicht – überspringe modal",
                )
                return

            self.dialog.transient(self.parent)
            self._log_debug(4, "[BASEDIALOG] transient gesetzt")

            self.dialog.update_idletasks()
            self._log_debug(
                4,
                "[BASEDIALOG] update_idletasks() durchgeführt",
            )

            try:
                current_grab = self.dialog.tk.call("grab", "current")
                if current_grab:
                    self._log_debug(
                        4,
                        f"[BASEDIALOG] grab_set bereits aktiv für {current_grab}",
                    )
            except Exception:
                pass

            self.dialog.grab_set()
            self._log_debug(4, "[BASEDIALOG] grab_set() erfolgreich")
            self.dialog.after(10, self._after_grab_focus)

        except tk.TclError as e:
            self._log_error("[BASEDIALOG] TclError in _make_modal", e)
        except Exception as e:
            self._log_error("[BASEDIALOG] Fehler in _make_modal", e)

    def _after_grab_focus(self) -> None:
        """Wird nach grab_set() aufgerufen, um den Fokus zu setzen."""
        try:
            if self.dialog and self.dialog.winfo_exists():
                if self.dialog.winfo_viewable():
                    self.dialog.focus_force()
                    self._log_debug(
                        4,
                        "[BASEDIALOG] focus_force() erfolgreich",
                    )
                else:
                    self._log_debug(
                        4,
                        "[BASEDIALOG] Fenster nicht sichtbar – "
                        "focus_force übersprungen",
                    )
        except Exception as e:
            self._log_error("[BASEDIALOG] Fehler in _after_grab_focus", e)

    def _release_modal(self) -> None:
        """Gibt den modal-Grab frei – nur wenn WIR ihn halten.

        Verhindert, dass ein zwischenzeitlich geöffneter anderer Dialog
        seinen Grab verliert.
        """
        if not self.dialog or not self.dialog.winfo_exists():
            return

        try:
            current = self.dialog.grab_current()
            if current is self.dialog:
                self.dialog.grab_release()
                self._log_debug(4, "[BASEDIALOG] Grab freigegeben")
            elif current is not None:
                self._log_debug(
                    4,
                    f"[BASEDIALOG] Grab wird von {current} gehalten – "
                    "nicht freigegeben",
                )
        except Exception as e:
            self._log_error(
                "[BASEDIALOG] Grab-Freigabe fehlgeschlagen",
                e,
            )

    def _safe_after(
        self,
        delay_ms: int,
        callback: Callable,
        *args: Any,
        **kwargs: Any,
    ) -> str | None:
        """Führt callback nach delay_ms aus, falls Dialog noch existiert."""
        if not self.dialog or not self.dialog.winfo_exists():
            return None
        try:
            return self.dialog.after(delay_ms, callback, *args, **kwargs)
        except tk.TclError as e:
            self._log_error("[BASEDIALOG] _safe_after fehlgeschlagen", e)
            return None

    def _safe_after_cancel(self, after_id: str | None) -> None:
        """Bricht einen after-Aufruf ab, falls möglich (idempotent)."""
        if after_id is None:
            return
        if not self.dialog or not self.dialog.winfo_exists():
            return
        try:
            self.dialog.after_cancel(after_id)
        except Exception as e:
            self._log_debug(
                4,
                f"[BASEDIALOG] after_cancel fehlgeschlagen: {e}",
            )

    def _timeout_close(self) -> None:
        """Wird nach Timeout aufgerufen – schließt den Dialog."""
        if self.dialog and self.dialog.winfo_exists() and not self._closed:
            self._log_debug(
                2,
                f"[BASEDIALOG] Timeout ({self.timeout}s) – schließe Dialog",
            )
            self.close()

    def build_ui(self) -> None:
        """Wird von Unterklassen überschrieben, um die GUI aufzubauen.
        Diese Basisimplementierung tut nichts.
        """

    def update_status(self, message: str) -> None:
        """Wird von Unterklassen überschrieben, um Statusmeldungen
        anzuzeigen. Standard: nichts tun.
        """

    def on_init_error(self, exc: BaseException) -> None:
        """Hook: wird aufgerufen, wenn `build_ui()` (oder ein späterer
        Init-Schritt) fehlschlägt.
        """

    def apply_theme(self) -> None:
        """Wendet das aktuelle Theme rekursiv auf alle tk-Widgets an."""
        if self._theme_applied:
            return
        if not self.dialog or not self.dialog.winfo_exists():
            return

        try:
            theme = self._get_theme_safe()
            platform_utils = globals().get("PlatformUtils")
            if platform_utils is not None and hasattr(
                platform_utils,
                "apply_theme_to_widget_tree",
            ):
                platform_utils.apply_theme_to_widget_tree(self.dialog, theme)
            else:
                self._apply_theme_recursive(self.dialog, theme)
            self._theme = theme
            self._theme_applied = True
            self._log_debug(4, "[BASEDIALOG] Theme angewendet")
        except Exception as e:
            self._log_error(
                "[BASEDIALOG] Theme-Anwendung fehlgeschlagen",
                e,
            )

    def _apply_theme_recursive(self, widget: tk.Widget, theme: Any) -> None:
        """Einfache rekursive Theme-Anwendung (Fallback, falls PlatformUtils fehlt)."""
        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return

        if not isinstance(widget, ttk.Widget):
            try:
                if isinstance(widget, (tk.Frame, tk.LabelFrame, tk.Toplevel)):
                    widget.configure(bg=theme.BG_PRIMARY)
                elif isinstance(widget, tk.Label):
                    widget.configure(
                        bg=theme.BG_PRIMARY,
                        fg=theme.TEXT_PRIMARY,
                    )
                elif isinstance(widget, tk.Button):
                    widget.configure(
                        bg=theme.BG_TERTIARY,
                        fg=theme.TEXT_PRIMARY,
                        activebackground=theme.BG_HOVER,
                        activeforeground=theme.TEXT_ACCENT,
                    )
                elif isinstance(widget, (tk.Entry, tk.Text, tk.Spinbox)):
                    widget.configure(
                        bg=theme.INPUT_BG,
                        fg=theme.TEXT_PRIMARY,
                        insertbackground=theme.TEXT_PRIMARY,
                        selectbackground=theme.COMBO_SELECTION,
                        selectforeground=theme.TEXT_PRIMARY,
                    )
            except Exception as e:
                self._log_debug(
                    4,
                    f"[BASEDIALOG] Theme-Fehler bei {type(widget).__name__}: {e}",
                )

        try:
            for child in widget.winfo_children():
                self._apply_theme_recursive(child, theme)
        except Exception as e:
            self._log_debug(
                4,
                f"[BASEDIALOG] Rekursive Theme-Anwendung fehlgeschlagen: {e}",
            )

    def reset(self) -> None:
        """Setzt den Dialog zurück, damit er nach close() erneut geöffnet
        werden kann. Normalerweise nicht nötig – besser neue Instanz.
        """
        if not self._closed:
            raise RuntimeError("Reset nur auf geschlossenem Dialog möglich")
        if self.dialog is not None:
            raise RuntimeError(
                "Dialog wurde noch nicht vollständig geschlossen",
            )

        self._log_debug(2, "[BASEDIALOG] Reset wird ausgeführt")

        self._theme_applied = False
        self._safe_parent_cache = None

        self.dialog = self._create_dialog()
        if self.dialog is None:
            raise RuntimeError(
                "Reset fehlgeschlagen: Dialog konnte nicht neu erstellt werden",
            )

        self.main = tk.Frame(
            self.dialog,
            bg=self._theme.BG_PRIMARY,
            padx=15,
            pady=15,
        )
        self.main.pack(fill="both", expand=True)

        self._register_in_parent()
        self._center_dialog()

        if self.close_on_escape:
            self.dialog.bind("<Escape>", lambda _e: self.close())

        if self.modal:
            self._make_modal()

        try:
            self.build_ui()
        except Exception as exc:
            self._log_error(
                f"[BASEDIALOG] build_ui() in Reset von "
                f"{self.__class__.__name__} fehlgeschlagen",
                exc,
            )
            with contextlib.suppress(Exception):
                self.on_init_error(exc)
            raise

        if self.timeout is not None:
            self._timeout_id = self._safe_after(
                int(self.timeout * 1000),
                self._timeout_close,
            )

        self._closed = False
        self._log_debug(2, "[BASEDIALOG] Reset abgeschlossen")

    def focus(self) -> None:
        """Setzt den Fokus auf den Dialog (falls sichtbar)."""
        if self.dialog and self.dialog.winfo_exists():
            try:
                self.dialog.focus_force()
            except Exception as e:
                self._log_debug(
                    4,
                    f"[BASEDIALOG] focus_force fehlgeschlagen: {e}",
                )

    def close(self) -> None:
        """Schließt den Dialog und räumt Ressourcen auf."""
        with self._close_lock:
            if self._closed:
                self._log_debug(
                    4,
                    "[BASEDIALOG] close() bereits ausgeführt – überspringe",
                )
                return
            if self._closing_in_progress:
                self._log_debug(
                    3,
                    "[BASEDIALOG] close() bereits im Gange – überspringe",
                )
                return
            self._closing_in_progress = True

        self._log_debug(2, "[BASEDIALOG] 🔴 close() AUFRUFEN!")

        try:
            if self._on_close_callback is not None:
                self._log_debug(
                    3,
                    "[BASEDIALOG] Führe on_close_callback aus",
                )
                try:
                    self._on_close_callback()
                    self._log_debug(
                        3,
                        "[BASEDIALOG] on_close_callback erfolgreich",
                    )
                except Exception as e:
                    self._log_error(
                        "[BASEDIALOG] on_close_callback fehlgeschlagen",
                        e,
                    )

            timeout_id = getattr(self, "_timeout_id", None)
            if timeout_id is not None:
                self._safe_after_cancel(timeout_id)
                self._timeout_id = None

            if self.modal:
                self._release_modal()
            self._unregister_from_parent()

            if self.dialog is not None:
                try:
                    if self.dialog.winfo_exists():
                        self.dialog.destroy()
                        self._log_debug(
                            3,
                            "[BASEDIALOG] dialog.destroy() erfolgreich",
                        )
                    else:
                        self._log_debug(
                            3,
                            "[BASEDIALOG] dialog existiert nicht mehr – "
                            "überspringe destroy",
                        )
                except Exception as e:
                    self._log_error(
                        "[BASEDIALOG] Fehler beim Zerstören des Dialogs",
                        e,
                    )

                self.dialog = None
                self.main = None

            self._closed = True
            self._log_debug(
                2,
                "[BASEDIALOG] close() abgeschlossen (closed=True)",
            )

        except Exception as e:
            self._log_error(
                "[BASEDIALOG] Schwerer Fehler in close()",
                e,
            )
            self._closed = True
            self.dialog = None
            self.main = None
        finally:
            with self._close_lock:
                self._closing_in_progress = False

    def _cleanup_on_init_failure(self) -> None:
        """Räumt nach einer fehlgeschlagenen Initialisierung auf."""
        try:
            if self.modal and self.dialog is not None:
                try:
                    current = self.dialog.grab_current()
                    if current is self.dialog:
                        self.dialog.grab_release()
                except Exception:
                    pass
        except Exception:
            pass

        with contextlib.suppress(Exception):
            self._unregister_from_parent()

        try:
            if self.dialog is not None and self.dialog.winfo_exists():
                self.dialog.destroy()
        except Exception:
            pass

        self.dialog = None
        self.main = None
        self._closed = True

    @contextmanager
    def temporary_subscription(
        self,
        event_bus: Any,
        event_type: str,
        callback: Callable,
    ):
        """Kontextmanager für temporäre Event-Bus-Abonnements."""
        if not hasattr(event_bus, "subscribe") or not hasattr(
            event_bus,
            "unsubscribe",
        ):
            raise TypeError(
                "event_bus muss subscribe- und unsubscribe-Methoden haben",
            )

        self._log_debug(
            4,
            f"[BASEDIALOG] Temporäres Abo für {event_type}",
        )

        event_bus.subscribe(event_type, callback)
        try:
            yield
        finally:
            try:
                event_bus.unsubscribe(event_type, callback)
                self._log_debug(
                    4,
                    f"[BASEDIALOG] Temporäres Abo für {event_type} beendet",
                )
            except Exception as e:
                self._log_error(
                    f"[BASEDIALOG] Unsubscribe für {event_type} fehlgeschlagen",
                    e,
                )

    def __repr__(self) -> str:
        return (
            f"<BaseDialog title='{self.title}' "
            f"closed={self._closed} visible={self.is_visible} "
            f"init_done={self._init_done}>"
        )


class ContextMenuMixin:
    """Einheitliches, robustes Kontextmenü für Text- und Entry-Widgets."""

    def __init__(
        self,
        widget: tk.Text | tk.Entry | ttk.Entry,
        use_copy_cut_paste: bool = True,
    ) -> None:
        """Initialisiert das Kontextmenü für das angegebene Widget."""
        self.widget = widget
        self._debug = getattr(globals(), "DEBUG_LEVEL", 0) >= 3
        self._widget_type = self._get_widget_type()

        theme = getattr(globals(), "CURRENT_THEME", DarkTheme())

        self.menu = tk.Menu(
            widget,
            tearoff=0,
            bg=theme.BG_TERTIARY,
            fg=theme.TEXT_PRIMARY,
            activebackground=theme.BG_HOVER,
            activeforeground=theme.TEXT_ACCENT,
            borderwidth=1,
            relief="solid",
        )

        if use_copy_cut_paste:
            if self._widget_type == "text":
                self.menu.add_command(
                    label="Undo",
                    command=self.undo,
                    accelerator="Ctrl+Z",
                )
                self.menu.add_command(
                    label="Redo",
                    command=self.redo,
                    accelerator="Ctrl+Y",
                )
                self.menu.add_separator()

            self.menu.add_command(label="Cut", command=self.cut, accelerator="Ctrl+X")
            self.menu.add_command(label="Copy", command=self.copy, accelerator="Ctrl+C")
            self.menu.add_command(
                label="Paste",
                command=self.paste,
                accelerator="Ctrl+V",
            )
            self.menu.add_separator()

        self.menu.add_command(
            label="Select All",
            command=self.select_all,
            accelerator="Ctrl+A",
        )
        if self._widget_type == "text":
            self.menu.add_command(label="Delete", command=self.clear)

        self.menu.bind("<Escape>", lambda e: self.menu.unpost())
        widget.bind("<Button-3>", self.show_menu)

        if self._debug:
            log_debug(
                "gui",
                f"ContextMenuMixin initialized for {self._widget_type} widget: {
                    widget
                }",
            )

    def _get_widget_type(self) -> str:
        """Ermittelt den Widget-Typ (text, entry, unknown)."""
        if isinstance(self.widget, tk.Text):
            return "text"
        if isinstance(self.widget, (tk.Entry, ttk.Entry)):
            return "entry"
        return "unknown"

    def _has_selection(self) -> bool:
        """Prüft, ob im Widget Text ausgewählt ist (robust)."""
        try:
            if self._widget_type == "text":
                return bool(self.widget.tag_ranges(tk.SEL))

            if hasattr(self.widget, "selection_present"):
                return self.widget.selection_present()
            return False
        except tk.TclError:
            return False

    def _get_selected_text(self) -> str:
        """Gibt den selektierten Text zurück oder einen leeren String."""
        try:
            if self._widget_type == "text":
                if self.widget.tag_ranges(tk.SEL):
                    return self.widget.get(tk.SEL_FIRST, tk.SEL_LAST)
            elif (
                hasattr(self.widget, "selection_present")
                and self.widget.selection_present()
            ):
                try:
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    return self.widget.get()[start:end]
                except tk.TclError:
                    return self.widget.get()
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Error getting selected text: {e}")
        return ""

    def show_menu(self, event: tk.Event) -> str:
        """Zeigt das Kontextmenü an der Mausposition an."""
        try:
            self.menu.tk_popup(event.x_root, event.y_root)
            if self._debug:
                log_debug(
                    "gui",
                    f"Context menu shown at ({event.x_root}, {event.y_root})",
                )
        except Exception as e:
            if self._debug:
                log_debug("gui", f"Failed to show context menu: {e}")
        finally:
            self.menu.grab_release()
        return "break"

    def copy(self) -> None:
        """Kopiert den selektierten Text in die Zwischenablage."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Copy called but no selection")
            return

        text = self._get_selected_text()
        if not text:
            return

        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            if self._debug:
                log_debug("gui", f"Copied {len(text)} chars to clipboard")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Copy failed: {e}")

    def cut(self) -> None:
        """Ausschneiden: Kopieren und Löschen des selektierten Texts."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Cut called but no selection")
            return
        text = self._get_selected_text()
        if not text:
            return
        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            if self._widget_type == "text":
                self.widget.delete(tk.SEL_FIRST, tk.SEL_LAST)
            else:
                start = self.widget.index(tk.SEL_FIRST)
                end = self.widget.index(tk.SEL_LAST)
                self.widget.delete(start, end)
            if self._debug:
                log_debug("gui", f"Cut {len(text)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Cut failed: {e}")

    def paste(self) -> None:
        """Fügt Text aus der Zwischenablage ein."""
        try:
            clipboard = self.widget.clipboard_get()
            if not clipboard:
                return

            if self._widget_type == "text":
                self.widget.insert(tk.INSERT, clipboard)
            else:
                if self._has_selection():
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    self.widget.delete(start, end)
                self.widget.insert(tk.INSERT, clipboard)

            if self._debug:
                log_debug("gui", f"Pasted {len(clipboard)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Paste failed: {e}")

    def select_all(self) -> None:
        """Markiert den gesamten Text im Widget."""
        try:
            if self._widget_type == "text":
                self.widget.tag_add(tk.SEL, "1.0", tk.END)
                self.widget.mark_set(tk.INSERT, "1.0")
            else:
                self.widget.select_range(0, tk.END)
                self.widget.icursor(tk.END)
            if self._debug:
                log_debug("gui", "Select all executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Select all failed: {e}")

    def clear(self) -> None:
        """Löscht den gesamten Inhalt (nur für Text-Widgets)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.delete("1.0", tk.END)
            if self._debug:
                log_debug("gui", "Cleared text widget")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Clear failed: {e}")

    def undo(self) -> None:
        """Macht die letzte Änderung rückgängig (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            if hasattr(self.widget, "edit_undo"):
                self.widget.edit_undo()
                if self._debug:
                    log_debug("gui", "Undo executed")
            elif self._debug:
                log_debug("gui", "Undo not available for this widget")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Undo failed: {e}")

    def redo(self) -> None:
        """Stellt die letzte rückgängig gemachte Änderung wieder her (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            if hasattr(self.widget, "edit_redo"):
                self.widget.edit_redo()
                if self._debug:
                    log_debug("gui", "Redo executed")
            elif self._debug:
                log_debug("gui", "Redo not available for this widget")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Redo failed: {e}")


