    STOP_BUTTON_HOVER: Final[str] = "#f06060"

    @classmethod
    def to_dict(cls) -> dict[str, str]:
        """Gibt alle Farbwerte als Dictionary zurück.

        ★ v2.4: Nützlich für Debug-Ausgabe, Snapshot-Vergleich oder
        um das Theme in eine JSON-Config zu serialisieren.

        Beispiel:
            >>> DarkTheme.to_dict()["BG_PRIMARY"]
            '#0f1419'
        """
        return {
            name: value
            for name, value in vars(cls).items()
            if (not name.startswith("_") and isinstance(value, str))
        }

    @classmethod
    def missing_attrs(cls, required: set[str]) -> set[str]:
        """Prüft, welche Attribute aus *required* im Theme fehlen."""
        return {name for name in required if not hasattr(cls, name)}


