class Fonts:
    """Plattformunabhängige Schriftart‑Konfiguration mit dynamischer
    Erkennung der verfügbaren Schriftarten.
    """

    _SANS_CANDIDATES: ClassVar[tuple[str, ...]] = (
        "Segoe UI",
        "Noto Sans",
        "DejaVu Sans",
        "Helvetica Neue",
        "Arial",
        "Ubuntu",
        "Liberation Sans",
        "FreeSans",
        "sans-serif",
    )

    _MONO_CANDIDATES: ClassVar[tuple[str, ...]] = (
        "Cascadia Code",
        "Noto Mono",
        "DejaVu Sans Mono",
        "Liberation Mono",
        "Courier New",
        "Courier",
        "monospace",
    )

    _SANS: str = "sans-serif"
    _MONO: str = "monospace"

    TITLE: ClassVar[tuple[str, int, str]] = ("sans-serif", 12, "bold")
    SUBTITLE: ClassVar[tuple[str, int, str]] = ("sans-serif", 10, "bold")
    PRIMARY: ClassVar[tuple[str, int, str]] = ("sans-serif", 9)
    SECONDARY: ClassVar[tuple[str, int, str]] = ("sans-serif", 8)
    MONOSPACE: ClassVar[tuple[str, int, str]] = ("monospace", 9)
    BUTTON: ClassVar[tuple[str, int, str]] = ("sans-serif", 9, "bold")
    STATUS: ClassVar[tuple[str, int, str]] = ("sans-serif", 8)
    SMALL: ClassVar[tuple[str, int, str]] = ("sans-serif", 7)

    _initialized: ClassVar[bool] = False
    _init_lock: ClassVar[threading.Lock] = threading.Lock()

    @classmethod
    def _select_family(cls, candidates: tuple[str, ...], available: set[str]) -> str:
        """Wählt die erste in *available* vorhandene Schriftfamilie aus
        *candidates* aus.  Ist keine verfügbar, wird der letzte Eintrag
        (die generische Familie) zurückgegeben.
        """
        for fam in candidates:
            if fam in available:
                return fam
        return candidates[-1]

    @classmethod
    def init_fonts(cls) -> None:
        """Ermittelt die tatsächlich installierten Schriftfamilien und
        überschreibt die Klassenattribute mit den bestmöglichen Werten.
        """
        if cls._initialized:
            return

        with cls._init_lock:
            if cls._initialized:
                return

            try:
                available = set(tk.font.families())
            except Exception:
                logger.warning("Fonts.init_fonts: tk.font.families() nicht verfügbar")
                return

            cls._SANS = cls._select_family(cls._SANS_CANDIDATES, available)
            cls._MONO = cls._select_family(cls._MONO_CANDIDATES, available)

            cls.TITLE = (cls._SANS, 12, "bold")
            cls.SUBTITLE = (cls._SANS, 10, "bold")
            cls.PRIMARY = (cls._SANS, 9)
            cls.SECONDARY = (cls._SANS, 8)
            cls.MONOSPACE = (cls._MONO, 9)
            cls.BUTTON = (cls._SANS, 9, "bold")
            cls.STATUS = (cls._SANS, 8)
            cls.SMALL = (cls._SANS, 7)

            cls._initialized = True

            logger.debug(
                "Fonts initialisiert: SANS=%r, MONO=%r",
                cls._SANS,
                cls._MONO,
            )


