class HighAccuracyConfig(Config):
    """Konfiguration für maximale Transkriptionsgenauigkeit bei geringem Zeitdruck."""

    CHUNK_DURATION: float = 30.0
    CHUNK_OVERLAP: float = 0.8
    AUDIO_FILTER: str = (
        "aresample=16000,"
        "volume=1.8,"
        "highpass=f=80,"
        "lowpass=f=3800,"
        "dynaudnorm=p=0.3:s=3:g=20,"
        "afftdn=tn=1:nf=-25"
    )

    AUDIO_ENHANCEMENT_ENABLED: bool = True
    BEAM_SIZE: int = 10
    TEMPERATURE: float = 0.0
    BEST_OF: int = 5
    CONDITION_ON_PREVIOUS_TEXT: bool = True
    VAD_FILTER: bool = True
    DUPLICATE_CHECK_ENABLED: bool = True
    MAX_CONSECUTIVE_ERRORS: int = 10
    FFMPEG_BUFSIZE: str = "4096k"
    STREAM_TIMEOUT: int = 120
    CACHE_MAXSIZE_TRANSCRIPTION: int = 2000
    CACHE_MAXSIZE_TRANSLATION: int = 4000
    CACHE_MAXSIZE_AUDIO: int = 1024

    def __init__(self) -> None:
        """Initialisiert die Konfiguration und setzt alle Parameter."""
        super().__init__()
        self.CHUNK_DURATION = self.CHUNK_DURATION
        self.CHUNK_OVERLAP = self.CHUNK_OVERLAP
        self.AUDIO_FILTER = self.AUDIO_FILTER
        self.AUDIO_ENHANCEMENT_ENABLED = self.AUDIO_ENHANCEMENT_ENABLED
        self.BEAM_SIZE = self.BEAM_SIZE
        self.TEMPERATURE = self.TEMPERATURE
        self.BEST_OF = self.BEST_OF
        self.CONDITION_ON_PREVIOUS_TEXT = self.CONDITION_ON_PREVIOUS_TEXT
        self.VAD_FILTER = self.VAD_FILTER
        self.DUPLICATE_CHECK_ENABLED = self.DUPLICATE_CHECK_ENABLED
        self.MAX_CONSECUTIVE_ERRORS = self.MAX_CONSECUTIVE_ERRORS
        self.FFMPEG_BUFSIZE = self.FFMPEG_BUFSIZE
        self.STREAM_TIMEOUT = self.STREAM_TIMEOUT
        self.CACHE_MAXSIZE_TRANSCRIPTION = self.CACHE_MAXSIZE_TRANSCRIPTION
        self.CACHE_MAXSIZE_TRANSLATION = self.CACHE_MAXSIZE_TRANSLATION
        self.CACHE_MAXSIZE_AUDIO = self.CACHE_MAXSIZE_AUDIO

    def apply_to_settings(self, settings: AdvancedSettings) -> None:
        """Wendet die High‑Accuracy‑Parameter auf ein AdvancedSettings‑Objekt an."""
        settings.chunk_duration = self.CHUNK_DURATION
        settings.chunk_overlap = self.CHUNK_OVERLAP
        settings.audio_filter = self.AUDIO_FILTER
        settings.audio_enhancement_enabled = self.AUDIO_ENHANCEMENT_ENABLED
        settings.beam_size = self.BEAM_SIZE
        settings.temperature = self.TEMPERATURE
        settings.best_of = self.BEST_OF
        settings.condition_on_previous_text = self.CONDITION_ON_PREVIOUS_TEXT
        settings.vad_filter = self.VAD_FILTER
        settings.duplicate_check_enabled = self.DUPLICATE_CHECK_ENABLED
        settings.max_consecutive_errors = self.MAX_CONSECUTIVE_ERRORS
        settings.ffmpeg_bufsize = self.FFMPEG_BUFSIZE
        settings.stream_timeout = self.STREAM_TIMEOUT
        settings.cache_maxsize_transcription = self.CACHE_MAXSIZE_TRANSCRIPTION
        settings.cache_maxsize_translation = self.CACHE_MAXSIZE_TRANSLATION
        settings.cache_maxsize_audio = self.CACHE_MAXSIZE_AUDIO

    @classmethod
    def from_base_config(cls, base_config: Config) -> HighAccuracyConfig:
        """Erzeugt eine HighAccuracyConfig, die von einer bestehenden Config erbt."""
        config = cls()
        for key, value in base_config.__dict__.items():
            if not hasattr(config, key):
                setattr(config, key, value)
        return config


