def get_config(config_type: str = "default") -> Config:
    """Erzeugt und liefert eine Config‑Instanz für den angegebenen Konfigurationstyp."""
    configs = {
        "default": Config,
        "realtime": RealtimeConfig,
        "high_accuracy": HighAccuracyConfig,
        "youtube": YouTubeOptimizedConfig,
    }

    config_class = configs.get(config_type)
    if config_class is None:
        logger.warning(
            "⚠️ Unbekannter config_type '%s' – verwende 'default'.",
            config_type,
        )
        config_class = Config

    try:
        config = config_class()
    except Exception as exc:
        logger.error(
            "❌ Fehler beim Erstellen der Konfiguration '%s': %s – "
            "verwende Standard‑Config.",
            config_type,
            exc,
        )
        config = Config()

    if not config.validate_config():
        logger.warning(
            "Config '%s' ist inkonsistent – versuche Reparatur …",
            config_class.__name__,
        )
        config.CHUNK_DURATION = max(config.CHUNK_DURATION, config.MIN_CHUNK_DURATION)
        config.CHUNK_DURATION = min(config.CHUNK_DURATION, config.MAX_CHUNK_DURATION)
        if config.CHUNK_OVERLAP >= config.CHUNK_DURATION:
            config.CHUNK_OVERLAP = max(0.0, config.CHUNK_DURATION * 0.1)
        if config.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            config.SAMPLE_RATE = 16000
        if config.CHANNELS not in (1, 2):
            config.CHANNELS = 1

        if not config.validate_config():
            logger.error(
                "❌ Konnte Config '%s' nicht reparieren – verwende "
                "absolute Notfall‑Defaults.",
                config_class.__name__,
            )
            config = Config()
    elif getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
        _safe_log_debug(
            "config",
            f"Config '{config_class.__name__}' erfolgreich erstellt und validiert "
            f"(chunk={config.CHUNK_DURATION:.1f}s, sr={config.SAMPLE_RATE}Hz, "
            f"ch={config.CHANNELS})",
        )
    return config


class FastLazyLoader:
    """Thread‑sicherer Lazy‑Loader für Module mit Caching, TTL, LRU-Eviction,
    Timeout‑Schutz, Abbruchunterstützung und erweitertem Mocking.
    """

    _loaded_modules: ClassVar[dict[str, Any]] = {}
    _module_locks: ClassVar[dict[str, threading.Lock]] = {}
    _global_lock: ClassVar[threading.Lock] = threading.Lock()
    _availability_cache: ClassVar[dict[str, tuple[bool, float]]] = {}
    _availability_cache_ttl: ClassVar[float] = 60.0
    _availability_cache_maxsize: ClassVar[int] = 200
    _cache_lock: ClassVar[threading.RLock] = threading.RLock()
    _metrics_enabled: ClassVar[bool] = False
    _metrics: ClassVar[dict[str, Any]] = {
        "load_attempts": 0,
        "load_success": 0,
        "load_failures": 0,
        "cache_hits": 0,
        "availability_checks": 0,
    }
    _metrics_lock: ClassVar[threading.RLock] = threading.RLock()
    _logger: ClassVar[logging.Logger] = logging.getLogger("dragon")

    DEFAULT_IMPORT_TIMEOUT: ClassVar[float] = 10.0

    @classmethod
    def configure(
        cls,
        *,
        availability_cache_ttl: float | None = None,
        enable_metrics: bool = False,
        availability_cache_maxsize: int | None = None,
    ) -> None:
        """Konfiguriert globale Parameter der Klasse."""
        if availability_cache_ttl is not None:
            cls._availability_cache_ttl = max(1.0, availability_cache_ttl)
        if availability_cache_maxsize is not None:
            cls._availability_cache_maxsize = max(10, availability_cache_maxsize)
        cls._metrics_enabled = enable_metrics
        cls._logger.debug(
            "FastLazyLoader configured: ttl=%ss, maxsize=%d, metrics=%s",
            cls._availability_cache_ttl,
            cls._availability_cache_maxsize,
            enable_metrics,
            extra={"component": "loader"},
        )

    @classmethod
    def _get_lock(cls, module_name: str) -> threading.Lock:
        """Gibt ein Lock für das Modul zurück (erzeugt eines, falls nicht vorhanden)."""
        with cls._global_lock:
            if module_name not in cls._module_locks:
                cls._module_locks[module_name] = threading.Lock()
            return cls._module_locks[module_name]

    @classmethod
    def _cleanup_availability_cache(cls, force: bool = False) -> None:
        """Entfernt abgelaufene Einträge aus dem Verfügbarkeits‑Cache."""
        with cls._cache_lock:
            now = time.monotonic()
            expired = [
                key
                for key, (_, ts) in cls._availability_cache.items()
                if now - ts > cls._availability_cache_ttl
            ]
            for key in expired:
                del cls._availability_cache[key]

            if len(cls._availability_cache) > cls._availability_cache_maxsize:
                sorted_items = sorted(
                    cls._availability_cache.items(),
                    key=lambda x: x[1][1],
                )
                to_remove = (
                    len(cls._availability_cache) - cls._availability_cache_maxsize
                )
                for key, _ in sorted_items[:to_remove]:
                    del cls._availability_cache[key]

    @classmethod
    def _set_availability_cache(cls, module_name: str, available: bool) -> None:
        """Fügt einen Eintrag in den Verfügbarkeits‑Cache ein (mit LRU)."""
        with cls._cache_lock:
            if module_name in cls._availability_cache:
                _, existing_ts = cls._availability_cache[module_name]
                if existing_ts > time.monotonic() - cls._availability_cache_ttl:
                    return

            cls._availability_cache[module_name] = (available, time.monotonic())
            if len(cls._availability_cache) > cls._availability_cache_maxsize:
                oldest_key = min(
                    cls._availability_cache.keys(),
                    key=lambda k: cls._availability_cache[k][1],
                )
                del cls._availability_cache[oldest_key]

    @classmethod
    def load(
        cls,
        module_name: str,
        import_paths: str | list[str] | None = None,
        *,
        timeout: float | None = None,
        cancel_event: threading.Event | None = None,
    ) -> Any:
        """Lädt ein Modul (lazy) und gibt es zurück."""
        effective_timeout = (
            timeout if timeout is not None else cls.DEFAULT_IMPORT_TIMEOUT
        )

        with cls._global_lock:
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                cls._logger.debug(
                    "Cache-Hit (global) für %s",
                    module_name,
                    extra={"component": "loader"},
                )
                return cls._loaded_modules[module_name]

        lock = cls._get_lock(module_name)
        with lock:
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                cls._logger.debug(
                    "Cache-Hit (per-module lock) für %s",
                    module_name,
                    extra={"component": "loader"},
                )
                return cls._loaded_modules[module_name]

            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_attempts"] += 1

            if cancel_event is not None and cancel_event.is_set():
                cls._logger.debug(
                    "Load von %s abgebrochen (cancel_event gesetzt)",
                    module_name,
                    extra={"component": "loader"},
                )
                raise TimeoutError(f"Load von {module_name} abgebrochen")

            special_handlers = {
                "torch": cls._load_torch,
                "faster_whisper": cls._load_faster_whisper,
                "numpy": cls._load_numpy,
                "deep_translator": cls._load_deep_translator,
                "scipy.signal": cls._load_scipy_signal,
            }

            if module_name in special_handlers:
                _t0 = time.perf_counter()
                try:
                    module = cls._run_with_timeout(
                        special_handlers[module_name],
                        timeout=effective_timeout,
                        cancel_event=cancel_event,
                    )
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s via special handler (%.0f ms)",
                        module_name,
                        (time.perf_counter() - _t0) * 1000,
                        extra={"component": "loader"},
                    )
                    return module
                except (ImportError, TimeoutError) as e:
                    cls._logger.debug(
                        "Special handler for %s failed "
                        "(%s: %s) – versuche Standard-Import",
                        module_name,
                        type(e).__name__,
                        e,
                        extra={"component": "loader"},
                    )

            if import_paths is None:
                paths = [module_name]
            elif isinstance(import_paths, str):
                paths = [import_paths]
            else:
                paths = import_paths

            last_error: Exception | None = None
            for path in paths:
                if cancel_event is not None and cancel_event.is_set():
                    cls._logger.debug(
                        "Import-Pfad-Schleife für %s abgebrochen (cancel_event)",
                        module_name,
                        extra={"component": "loader"},
                    )
                    raise TimeoutError(f"Import von {module_name} abgebrochen")

                _t0 = time.perf_counter()
                try:
                    module = cls._run_with_timeout(
                        lambda _p=path: importlib.import_module(_p),
                        timeout=effective_timeout,
                        cancel_event=cancel_event,
                    )
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s from %s (%.0f ms)",
                        module_name,
                        path,
                        (time.perf_counter() - _t0) * 1000,
                        extra={"component": "loader"},
                    )
                    return module
                except ImportError as e:
                    last_error = e
                    cls._logger.debug(
                        "Import-Pfad %s für %s fehlgeschlagen (%s, %.0f ms)",
                        path,
                        module_name,
                        e,
                        (time.perf_counter() - _t0) * 1000,
                        extra={"component": "loader"},
                    )
                    continue
                except TimeoutError as e:
                    last_error = e
                    cls._logger.warning(
                        "Import of %s from %s timed out after %.1fs",
                        module_name,
                        path,
                        effective_timeout,
                        extra={"component": "loader"},
                    )
                    raise

            cls._logger.debug(
                "Module %s not available (letzter Fehler: %s)",
                module_name,
                last_error,
                extra={"component": "loader"},
            )
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_failures"] += 1

            class MockModule:
                __name__ = module_name
                _is_mock = True
                _warned: ClassVar[bool] = False

                def __getattr__(self, name: str) -> Any:
                    if not MockModule._warned:
                        MockModule._warned = True
                        cls._logger.warning(
                            "⚠️ Zugriff auf Mock-Modul '%s' – "
                            "die eigentliche Bibliothek ist nicht "
                            "installiert. Funktionen werden fehlschlagen.",
                            module_name,
                        )
                    raise ImportError(
                        f"Module '{module_name}' is not available. "
                        f"Please install it via pip "
                        f"(e.g. 'pip install {module_name}').",
                    )

            mock = MockModule()
            cls._loaded_modules[module_name] = mock
            return mock

    @classmethod
    def _run_with_timeout(
        cls,
        func: Callable[[], Any],
        timeout: float,
        cancel_event: threading.Event | None = None,
    ) -> Any:
        """Führt eine Funktion mit Timeout und Abbruchunterstützung aus."""
        result: list[Any] = []
        exception: list[Exception] = []
        done = threading.Event()

        def _target() -> None:
            try:
                result.append(func())
            except Exception as e:
                exception.append(e)
            finally:
                done.set()

        thread = threading.Thread(target=_target, daemon=True)
        thread.start()

        start = time.monotonic()
        while not done.is_set():
            if cancel_event and cancel_event.is_set():
                raise RuntimeError("Operation cancelled by user")
            remaining = timeout - (time.monotonic() - start)
            if remaining <= 0:
                raise TimeoutError(f"Operation timed out after {timeout}s")
            done.wait(timeout=min(0.1, remaining))

        if exception:
            raise exception[0]
        return result[0] if result else None

    @classmethod
    def _load_torch(cls) -> Any:
        import torch

        try:
            import torch._logging

            torch._logging.set_logs(all=logging.ERROR)
        except Exception:
            pass
        return torch

    @classmethod
    def _load_faster_whisper(cls) -> Any:
        os.environ.setdefault("CT2_VERBOSE", "0")
        from faster_whisper import WhisperModel

        if cls._logger.isEnabledFor(logging.DEBUG):
            try:
                import faster_whisper

                version = getattr(faster_whisper, "__version__", "unknown")
                cls._logger.debug(
                    "faster-whisper version %s geladen",
                    version,
                    extra={"component": "loader"},
                )
            except Exception:
                pass
        return WhisperModel

    @classmethod
    def _load_numpy(cls) -> Any:
        import numpy as np

        return np

    @classmethod
    def _load_deep_translator(cls) -> Any:
        from deep_translator import GoogleTranslator

        return GoogleTranslator

    @classmethod
    def _load_scipy_signal(cls) -> Any:
        import scipy.signal

        return scipy.signal

    @classmethod
    def is_available(cls, module_name: str, use_cache: bool = True) -> bool:
        """Prüft, ob ein Modul verfügbar ist (mit Cache und Exception-Handling)."""
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics["availability_checks"] += 1

        if module_name in cls._loaded_modules:
            mod = cls._loaded_modules[module_name]
            return not getattr(mod, "_is_mock", False)

        if use_cache:
            with cls._cache_lock:
                cached = cls._availability_cache.get(module_name)
                if cached is not None:
                    available, timestamp = cached
                    if time.monotonic() - timestamp <= cls._availability_cache_ttl:
                        return available
                    del cls._availability_cache[module_name]

        available = False
        try:
            spec = importlib.util.find_spec(module_name)
            available = spec is not None
        except (ImportError, ModuleNotFoundError):
            available = False
        except Exception as e:
            cls._logger.debug(
                "Unexpected error in availability check for %s: %s",
                module_name,
                e,
                exc_info=True,
            )
            available = False

        if use_cache:
            cls._set_availability_cache(module_name, available)

        if cls._logger.isEnabledFor(logging.DEBUG):
            cls._logger.debug(
                "Availability check for %s: %s",
                module_name,
                available,
                extra={"component": "loader"},
            )
        return available

    @classmethod
    def clear_cache(cls, module_name: str | None = None) -> None:
        """Leert den Modul‑Cache und den Verfügbarkeits‑Cache."""
        with cls._global_lock:
            if module_name is None:
                cls._loaded_modules.clear()
                cls._module_locks.clear()
                with cls._cache_lock:
                    cls._availability_cache.clear()
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics = {
                            "load_attempts": 0,
                            "load_success": 0,
                            "load_failures": 0,
                            "cache_hits": 0,
                            "availability_checks": 0,
                        }
                cls._logger.debug("All caches cleared", extra={"component": "loader"})
            else:
                if module_name in cls._loaded_modules:
                    del cls._loaded_modules[module_name]
                if module_name in cls._module_locks:
                    del cls._module_locks[module_name]
                with cls._cache_lock:
                    if module_name in cls._availability_cache:
                        del cls._availability_cache[module_name]
                cls._logger.debug(
                    "Cache cleared for module %s",
                    module_name,
                    extra={"component": "loader"},
                )

    @classmethod
    def get_metrics(cls) -> dict[str, Any]:
        """Gibt die gesammelten Metriken zurück."""
        if not cls._metrics_enabled:
            return {"metrics_disabled": True}
        with cls._metrics_lock:
            return cls._metrics.copy()

    @classmethod
    def reset_metrics(cls) -> None:
        """Setzt die Metriken zurück."""
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics = {
                    "load_attempts": 0,
                    "load_success": 0,
                    "load_failures": 0,
                    "cache_hits": 0,
                    "availability_checks": 0,
                }
            cls._logger.debug("Metrics reset", extra={"component": "loader"})

    @classmethod
    def export_metrics(cls) -> str:
        """Exportiert die Metriken als JSON-String."""
        import json

        return json.dumps(cls.get_metrics(), indent=2)

    def __repr__(self) -> str:
        return (
            f"<FastLazyLoader loaded={len(self._loaded_modules)} "
            f"cache={len(self._availability_cache)} "
            f"metrics={self._metrics_enabled}>"
        )


class GPUStats:
    """Singleton‑artige Hilfsklasse für einmalige Initialisierung von pynvml.
    Stellt den GPU‑Handle und grundlegende Funktionen bereit.
    """

    _initialized = False
    _nvml_handle = None
    _nvml_available = False
    _lock = threading.Lock()

    @classmethod
    def _ensure_initialized(cls):
        """Initialisiert pynvml genau einmal (threadsicher)."""
        if cls._initialized:
            return
        with cls._lock:
            if cls._initialized:
                return
            try:
                import pynvml

                pynvml.nvmlInit()
                cls._nvml_handle = pynvml.nvmlDeviceGetHandleByIndex(0)
                cls._nvml_available = True
            except (ImportError, pynvml.NVMLError) as e:
                _safe_log_debug("gpu", f"pynvml nicht verfügbar: {e}")
                cls._nvml_available = False
            finally:
                cls._initialized = True

    @classmethod
    def is_available(cls) -> bool:
        """Gibt zurück, ob pynvml erfolgreich initialisiert wurde."""
        cls._ensure_initialized()
        return cls._nvml_available

    @classmethod
    def get_temperature(cls) -> int | None:
        """Aktuelle GPU‑Temperatur in °C oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetTemperature(
                cls._nvml_handle,
                pynvml.NVML_TEMPERATURE_GPU,
            )
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_utilization(cls) -> int | None:
        """GPU‑Auslastung in Prozent oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetUtilizationRates(cls._nvml_handle).gpu
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_memory_info(cls) -> dict[str, int] | None:
        """Gibt ein Dictionary mit Informationen über den GPU‑Speicher zurück.
        Enthält 'total', 'free' und 'used' in Bytes, oder None bei Fehler.
        """
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            mem = pynvml.nvmlDeviceGetMemoryInfo(cls._nvml_handle)
            return {
                "total": mem.total,
                "free": mem.free,
                "used": mem.used,
            }
        except pynvml.NVMLError:
            return None


from pathlib import Path

logger = logging.getLogger("dragon")
_COMPONENT = "stderr_filter"


class PlatformStderrFilter:
    """Filtert unerwünschte Zeilen aus dem stderr‑Stream, die von
    Plattform‑Bibliotheken (Rockchip, GPU‑Treibern, Windows‑Console)
    stammen und im normalen Betrieb keine relevante Information liefern.
    """

    def __init__(self, original_stderr: Any, use_regex: bool = False) -> None:
        """Initialisiert den Filter."""
        if not hasattr(original_stderr, "write") or not hasattr(
            original_stderr,
            "flush",
        ):
            raise ValueError("original_stderr muss write() und flush() unterstützen")

        self.original_stderr = original_stderr
        self._use_regex = use_regex
        self._lock = threading.RLock()
        self._enabled = True
        self._raw_patterns: list[str] = [
            "mpp_soc:",
            "mpp_platform:",
            "can not found match soc name",
            "/proc/device-tree/compatible",
            "rockchip",
            "ffmpeg",
            "TORCH_NCCL",
        ]

        try:
            if IS_WINDOWS:
                self._raw_patterns.extend(
                    [
                        "Failed to set direct console mode",
                        "Console code page",
                        "chcp",
                        "win32api",
                    ],
                )
        except NameError:
            pass

        self._compiled_patterns: list[re.Pattern] = []
        self._rebuild_patterns()

        self._stats: dict[str, int] = {
            "total_lines": 0,
            "filtered_lines": 0,
            "forwarded_lines": 0,
            "errors": 0,
        }
        self._stats_lock = threading.RLock()

    def _rebuild_patterns(self) -> None:
        """(Neu‑)Kompilierung der Muster, wenn use_regex=True."""
        if self._use_regex:
            self._compiled_patterns = []
            for pattern in self._raw_patterns:
                try:
                    self._compiled_patterns.append(re.compile(pattern, re.IGNORECASE))
                except re.error as e:
                    logger.warning(
                        "Ungültiges Regex‑Muster '%s': %s – ignoriert",
                        pattern,
                        e,
                        extra={"component": _COMPONENT},
                    )
        else:
            self._compiled_patterns = []

    def add_pattern(self, pattern: str) -> None:
        """Fügt ein neues Filtermuster hinzu.

        Args:
            pattern: Ein Teilstring oder ein regulärer Ausdruck (abhängig von use_regex).

        """
        if not pattern or not isinstance(pattern, str):
            logger.warning(
                "add_pattern: ungültiges Muster '%s' ignoriert",
                pattern,
                extra={"component": _COMPONENT},
            )
            return

        with self._lock:
            if pattern not in self._raw_patterns:
                self._raw_patterns.append(pattern)
                if self._use_regex:
                    try:
                        self._compiled_patterns.append(
                            re.compile(pattern, re.IGNORECASE),
                        )
                    except re.error as e:
                        logger.warning(
                            "Regex‑Fehler für '%s': %s – Muster wird nicht hinzugefügt",
                            pattern,
                            e,
                            extra={"component": _COMPONENT},
                        )
                        self._raw_patterns.pop()
                        return
                logger.debug(
                    "Muster hinzugefügt: '%s'",
                    pattern,
                    extra={"component": _COMPONENT},
                )

    def remove_pattern(self, pattern: str) -> bool:
        """Entfernt ein Filtermuster."""
        with self._lock:
            if pattern in self._raw_patterns:
                self._raw_patterns.remove(pattern)
                if self._use_regex:
                    self._rebuild_patterns()
                logger.debug(
                    "Muster entfernt: '%s'",
                    pattern,
                    extra={"component": _COMPONENT},
                )
                return True
            return False

    def clear_patterns(self) -> None:
        """Entfernt alle Filtermuster."""
        with self._lock:
            self._raw_patterns.clear()
            self._compiled_patterns.clear()
            logger.debug(
                "Alle Muster entfernt",
                extra={"component": _COMPONENT},
            )

    def set_patterns(self, patterns: list[str]) -> None:
        """Ersetzt die gesamte Musterliste durch eine neue Liste."""
        with self._lock:
            self._raw_patterns = list(patterns)
            self._rebuild_patterns()
            logger.debug(
                "Musterliste ersetzt (%d Einträge)",
                len(patterns),
                extra={"component": _COMPONENT},
            )

    def get_patterns(self) -> list[str]:
        """Gibt eine Kopie der aktuellen Musterliste zurück."""
        with self._lock:
            return self._raw_patterns.copy()

    def load_from_config(self, config_file: str | None = None) -> int:
        """Lädt zusätzliche Filter‑Muster aus einer Textdatei."""
        resolved_path = self._resolve_config_path(config_file)
        if resolved_path is None:
            logger.debug(
                "Kein gültiger Konfigurationspfad – überspringe.",
                extra={"component": _COMPONENT},
            )
            return 0

        cache_key = str(resolved_path)
        if hasattr(self, "_config_cache") and cache_key in self._config_cache:
            cached_patterns, cached_mtime = self._config_cache[cache_key]
            try:
                current_mtime = resolved_path.stat().st_mtime
            except OSError:
                current_mtime = 0
            if current_mtime == cached_mtime:
                logger.debug(
                    "Verwende gecachte Muster aus '%s'",
                    resolved_path,
                    extra={"component": _COMPONENT},
                )
                return len(cached_patterns)

        lines = self._read_config_file(resolved_path)
        if lines is None:
            return 0

        new_patterns = []
        for line in lines:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            normalized = re.sub(r"\s+", " ", line).strip()
            if normalized and normalized not in self._raw_patterns:
                new_patterns.append(normalized)

        if not new_patterns:
            logger.debug(
                "Keine neuen Muster in '%s' gefunden.",
                resolved_path,
                extra={"component": _COMPONENT},
            )
            return 0

        with self._lock:
            added = 0
            for pattern in new_patterns:
                self._raw_patterns.append(pattern)
                added += 1
            if self._use_regex:
                self._rebuild_patterns()

        if hasattr(self, "_config_cache"):
            try:
                mtime = resolved_path.stat().st_mtime
            except OSError:
                mtime = 0
            self._config_cache[cache_key] = (new_patterns, mtime)

        logger.info(
            "%d neue Muster aus '%s' geladen.",
            added,
            resolved_path,
            extra={"component": _COMPONENT},
        )
        return added

    def _resolve_config_path(self, config_file: str | None) -> Path | None:
        """Ermittelt den absoluten Pfad der Konfigurationsdatei."""
        if config_file is not None:
            path = Path(config_file)
            if path.is_absolute():
                return path if path.exists() else None

            resolved = Path.cwd() / path
            return resolved if resolved.exists() else None

        env_path = os.environ.get("DRAGON_STDERR_FILTER_FILE", "").strip()
        if env_path:
            path = Path(env_path)
            return path if path.exists() else None

        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            default_path = config_dir / "stderr_filters.txt"
            return default_path if default_path.exists() else None
        except Exception as e:
            logger.debug(
                "Konfigurationsverzeichnis nicht ermittelbar: %s",
                e,
                extra={"component": _COMPONENT},
            )
            return None

    def _read_config_file(self, path: Path) -> list[str] | None:
        """Liest eine Textdatei mit mehreren Encoding-Fallbacks ein."""
        encodings = ["utf-8", "utf-8-sig", "latin-1", "cp1252"]
        last_error = None

        for encoding in encodings:
            try:
                with open(path, encoding=encoding) as f:
                    return f.readlines()
            except UnicodeDecodeError as e:
                last_error = e
                continue
            except (PermissionError, OSError) as e:
                logger.warning(
                    "Fehler beim Lesen von '%s': %s",
                    path,
                    e,
                    extra={"component": _COMPONENT},
                )
                return None
            except Exception as e:
                logger.warning(
                    "Unerwarteter Fehler beim Lesen von '%s': %s",
                    path,
                    e,
                    extra={"component": _COMPONENT},
                )
                return None

        logger.warning(
            "Konnte Datei '%s' mit keinem der Encodings (%s) lesen. Letzter Fehler: %s",
            path,
            ", ".join(encodings),
            last_error,
            extra={"component": _COMPONENT},
        )
        return None

    @property
    def enabled(self) -> bool:
        """Gibt zurück, ob die Filterung aktiv ist."""
        with self._lock:
            return self._enabled

    @enabled.setter
    def enabled(self, value: bool) -> None:
        """Aktiviert oder deaktiviert die Filterung."""
        with self._lock:
            self._enabled = bool(value)

    def write(self, text: str) -> None:
        """Schreibt *text* nur dann nach stderr, wenn er kein Filter‑Muster enthält."""
        if not text:
            return

        with self._stats_lock:
            self._stats["total_lines"] += 1

        if not self._enabled:
            self._forward(text)
            return

        with self._lock:
            patterns = self._raw_patterns
            compiled = self._compiled_patterns

        if self._use_regex:
            matched = any(p.search(text) for p in compiled)
        else:
            matched = any(p in text for p in patterns)

        if matched:
            with self._stats_lock:
                self._stats["filtered_lines"] += 1
            return

        self._forward(text)

    def _forward(self, text: str) -> None:
        """Leitet den Text ungefiltert an das originale stderr weiter."""
        try:
            self.original_stderr.write(text)
            with self._stats_lock:
                self._stats["forwarded_lines"] += 1
        except Exception as e:
            with self._stats_lock:
                self._stats["errors"] += 1
            logger.warning(
                "Fehler beim Weiterleiten an stderr: %s",
                e,
                extra={"component": _COMPONENT},
            )

    def flush(self) -> None:
        """Leitet flush() an das originale stderr‑Objekt weiter."""
        self.original_stderr.flush()

    def get_stats(self) -> dict[str, int]:
        """Gibt eine Kopie der aktuellen Statistiken zurück."""
        with self._stats_lock:
            return self._stats.copy()

    def reset_stats(self) -> None:
        """Setzt alle Statistik‑Zähler auf Null zurück."""
        with self._stats_lock:
            for key in self._stats:
                self._stats[key] = 0

    @contextlib.contextmanager
    def disabled(self):
        """Kontextmanager, der die Filterung temporär deaktiviert."""
        old = self.enabled
        self.enabled = False
        try:
            yield
        finally:
            self.enabled = old

    def __repr__(self) -> str:
        with self._lock:
            patterns_count = len(self._raw_patterns)
        with self._stats_lock:
            filtered = self._stats.get("filtered_lines", 0)
        return (
            f"<PlatformStderrFilter patterns={patterns_count} "
            f"enabled={self._enabled} filtered={filtered}>"
        )


class PlatformUtils:
    """Plattformunabhängige Hilfsfunktionen für Dragon Whisperer."""

    _environment_setup_done: ClassVar[bool] = False
    _environment_setup_lock: ClassVar[threading.RLock] = threading.RLock()

    _dependencies_checked: ClassVar[bool] = False
    _dependencies_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache: ClassVar[dict[str, tuple[bool, float]]] = {}
    _dependencies_cache_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache_ttl: ClassVar[float] = 60.0

    _ffmpeg_path: ClassVar[str | None] = None
    _ffmpeg_path_lock: ClassVar[threading.RLock] = threading.RLock()

    _terminal_settings_saved: ClassVar[bool] = False
    _original_stty_settings: ClassVar[str | None] = None
    _terminal_lock: ClassVar[threading.Lock] = threading.Lock()

    _base_dirs: ClassVar[list[Path] | None] = None
    _user_dirs: ClassVar[list[Path]] = []
    _allowed_dirs_lock: ClassVar[threading.RLock] = threading.RLock()

    _test_home: ClassVar[Path | None] = None
    _test_cwd: ClassVar[Path | None] = None

    _DEBUG_COMPONENT: ClassVar[str] = "platform"
    logger: ClassVar[logging.Logger] = logging.getLogger("dragon")

    _config_dir_logged: ClassVar[bool] = False

    _executable_cache: ClassVar[dict[str, str | None]] = {}
    _executable_cache_lock: ClassVar[threading.RLock] = threading.RLock()

    _console_configured: ClassVar[bool] = False
    _original_console_codepage_in: ClassVar[int | None] = None
    _original_console_codepage_out: ClassVar[int | None] = None
    _original_console_mode: ClassVar[int | None] = None

    _is_container: ClassVar[bool | None] = None
    _container_type: ClassVar[str | None] = None

    _browser_cache: ClassVar[str | None] = None
    _browser_cache_lock: ClassVar[threading.Lock] = threading.Lock()

    @classmethod
    def resolve_browser(
        cls,
        settings: AppSettings | None = None,
        *,
        force_refresh: bool = False,
        fallback_order: list[str] | None = None,
    ) -> str:
        """Ermittelt den zu verwendenden Browser für Cookie‑Extraktion."""
        if not force_refresh and cls._browser_cache is not None:
            return cls._browser_cache

        with cls._browser_cache_lock:
            if not force_refresh and cls._browser_cache is not None:
                return cls._browser_cache

            if fallback_order is None:
                fallback_order = cls._get_default_fallback_order()

            if settings is None:
                app_settings_cls = globals().get("AppSettings")
                if app_settings_cls is not None:
                    try:
                        settings = app_settings_cls.load_from_file()
                    except Exception:
                        settings = None

            saved_browser = None
            if settings is not None:
                saved_browser = getattr(settings, "cookies_browser", None)

            candidates = []
            env_browser = os.environ.get("DRAGON_BROWSER")
            if env_browser and shutil.which(env_browser):
                candidates.append(env_browser)

            if saved_browser and shutil.which(saved_browser):
                candidates.append(saved_browser)

            for browser in fallback_order:
                if browser not in candidates and shutil.which(browser):
                    candidates.append(browser)

            if candidates:
                result = candidates[0]
            else:
                result = "firefox"
                logger.warning(
                    "Kein Browser gefunden – verwende Fallback 'firefox'. "
                    "Installieren Sie Firefox, Chromium oder setzen Sie DRAGON_BROWSER.",
                )

            cls._browser_cache = result
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "platform",
                    f"resolve_browser: {result} (candidates={candidates}, "
                    f"saved={saved_browser}, env={env_browser})",
                )
            return result

    @classmethod
    def _get_default_fallback_order(cls) -> list[str]:
        """Liefert die plattformspezifische Fallback‑Reihenfolge."""
        if IS_LINUX:
            return ["chromium", "chrome", "firefox", "brave", "edge"]
        if IS_MACOS:
            return ["safari", "firefox", "chrome", "chromium"]
        if IS_WINDOWS:
            return ["edge", "chrome", "firefox", "chromium", "brave"]
        return ["firefox", "chromium", "chrome"]

    @classmethod
    def clear_browser_cache(cls) -> None:
        """Leert den Browser‑Cache (z. B. nach Änderung der Einstellungen)."""
        with cls._browser_cache_lock:
            cls._browser_cache = None
            if DEBUG_LEVEL >= 3:
                log_debug("platform", "Browser‑Cache geleert")

    @classmethod
    def is_wsl(cls) -> bool:
        """Erkennt, ob das System unter WSL (Windows Subsystem for Linux) läuft."""
        if not IS_LINUX:
            return False
        try:
            with open("/proc/version", encoding="utf-8") as f:
                version = f.read().lower()
                return "microsoft" in version or "wsl" in version
        except FileNotFoundError:
            return False
        except OSError as e:
            cls.logger.debug("Fehler beim Lesen von /proc/version: %s", e)
            return False
        except Exception as e:
            cls.logger.exception("Unerwarteter Fehler in is_wsl: %s", e)
            return False

    @classmethod
    def is_docker(cls) -> bool:
        """Erkennt, ob das System in einem Docker-Container läuft."""
        if not IS_LINUX:
            return False
        if os.path.exists("/.dockerenv"):
            return True
        try:
            with open("/proc/1/cgroup", encoding="utf-8") as f:
                return any("docker" in line for line in f)
        except FileNotFoundError:
            return False
        except OSError as e:
            cls.logger.debug("Fehler beim Lesen von /proc/1/cgroup: %s", e)
            return False
        except Exception as e:
            cls.logger.exception("Unerwarteter Fehler in is_docker: %s", e)
            return False

    @classmethod
    def is_flatpak(cls) -> bool:
        """Erkennt, ob das Programm als Flatpak läuft."""
        return "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ

    @classmethod
    def is_snap(cls) -> bool:
        """Erkennt, ob das Programm als Snap läuft."""
        return "SNAP" in os.environ or "SNAP_NAME" in os.environ

    @classmethod
    def get_container_type(cls) -> str:
        """Gibt den Containertyp zurück ('docker', 'wsl', 'flatpak', 'snap', 'none')."""
        if cls._container_type is None:
            if cls.is_docker():
                cls._container_type = "docker"
            elif cls.is_wsl():
                cls._container_type = "wsl"
            elif cls.is_flatpak():
                cls._container_type = "flatpak"
            elif cls.is_snap():
                cls._container_type = "snap"
            else:
                cls._container_type = "none"
        return cls._container_type

    @classmethod
    def is_containerized(cls) -> bool:
        """True, wenn das System in einer Container-Umgebung läuft."""
        return cls.get_container_type() != "none"

    @classmethod
    def is_headless(cls) -> bool:
        """Prüft, ob die Umgebung keine GUI unterstützt (kein DISPLAY, kein Wayland)."""
        if IS_WINDOWS:
            return False
        if IS_MACOS:
            return False
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            return False
        try:
            import tkinter

            root = tkinter.Tk()
            root.destroy()
            return False
        except ImportError:
            return True
        except tkinter.TclError as e:
            cls.logger.debug("Kein Display (TclError): %s", e)
            return True
        except Exception as e:
            cls.logger.exception("Unerwarteter Fehler in is_headless: %s", e)
            return True

    @classmethod
    def set_allowed_dirs(cls, dirs: list[str]) -> None:
        """Setzt die Liste der zusätzlich erlaubten Benutzerverzeichnisse."""
        if not dirs:
            cls.logger.debug(
                "set_allowed_dirs: Leere Liste – keine Änderungen.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return

        cls.logger.debug(
            f"Setting user dirs: {dirs}",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        with cls._allowed_dirs_lock:
            resolved = []
            for d in dirs:
                if not d or not isinstance(d, str):
                    cls.logger.debug(
                        f"  → Skipped (invalid entry): {d!r}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                d = d.strip()
                if not d:
                    continue

                try:
                    p = Path(d).resolve()
                except (OSError, ValueError, RuntimeError) as e:
                    cls.logger.debug(
                        f"  → Skipped (resolution error): {d} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                except Exception as e:
                    cls.logger.exception(
                        f"  → Skipped (unexpected resolution error): {d} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue

                try:
                    if not p.exists():
                        cls.logger.debug(
                            f"  → Skipped (does not exist): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not p.is_dir():
                        cls.logger.debug(
                            f"  → Skipped (not a directory): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not os.access(p, os.R_OK):
                        cls.logger.warning(
                            f"Verzeichnis {p} ist nicht lesbar – "
                            "Dateien darin können nicht geöffnet werden.",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                    resolved.append(p)
                    cls.logger.debug(
                        f"  → Resolved: {p}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except (PermissionError, OSError) as e:
                    cls.logger.debug(
                        f"  → Skipped (access error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                except Exception as e:
                    cls.logger.exception(
                        f"  → Skipped (unexpected error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue

            cls._user_dirs = resolved
            cls._base_dirs = None
            cls.logger.debug(
                f"Final user dirs: {[str(p) for p in resolved]}",
                extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def add_allowed_dir(cls, dir_path: str) -> bool:
        """Fügt ein einzelnes Verzeichnis zur Whitelist hinzu."""
        if not dir_path:
            return False
        current = cls.get_allowed_dirs()
        if dir_path in current:
            return True
        new_list = [*current, dir_path]
        cls.set_allowed_dirs(new_list)
        return dir_path in cls.get_allowed_dirs()

    @classmethod
    def get_allowed_dirs(cls) -> list[str]:
        """Gibt die Liste der aktuell erlaubten Benutzerverzeichnisse als Strings zurück."""
        with cls._allowed_dirs_lock:
            return [str(p) for p in cls._user_dirs]

    @classmethod
    def reset_allowed_dirs(cls) -> None:
        """Setzt die Whitelist auf die Standard-Basisverzeichnisse zurück."""
        with cls._allowed_dirs_lock:
            cls._user_dirs = []
            cls._base_dirs = None

    @classmethod
    def is_path_allowed(cls, path: str) -> bool:
        """Prüft, ob ein gegebener Pfad innerhalb der erlaubten Verzeichnisse liegt."""
        try:
            Path(path).resolve()
        except (OSError, ValueError, RuntimeError) as e:
            cls.logger.debug("Pfad konnte nicht aufgelöst werden: %s – %s", path, e)
            return False
        except Exception as e:
            cls.logger.exception("Unerwarteter Fehler in is_path_allowed: %s", e)
            return False

    @classmethod
    def get_platform_config_dir(cls) -> Path:
        """Gibt das plattformspezifische Konfigurationsverzeichnis zurück."""
        if IS_WINDOWS:
            appdata = os.environ.get("APPDATA")
            if not appdata:
                appdata = str(Path.home() / "AppData" / "Roaming")
                cls.logger.debug(
                    "APPDATA not set, fallback to: %s",
                    appdata,
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            config_dir = Path(appdata) / "DragonWhisperer"
        elif IS_MACOS:
            config_dir = (
                Path.home() / "Library" / "Application Support" / "DragonWhisperer"
            )
        else:
            xdg_config = os.environ.get("XDG_CONFIG_HOME")
            if xdg_config:
                config_dir = Path(xdg_config) / "dragonwhisperer"
            else:
                config_dir = Path.home() / ".config" / "dragonwhisperer"

            if cls.is_flatpak():
                config_dir = (
                    Path.home()
                    / ".var/app/com.dragonwhisperer/config"
                    / "dragonwhisperer"
                )
            elif cls.is_snap():
                config_dir = (
                    Path.home() / "snap/dragonwhisperer/current/.config/dragonwhisperer"
                )

        if not cls._config_dir_logged:
            cls.logger.debug(
                f"Config directory: {config_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            cls._config_dir_logged = True
        return config_dir

    @classmethod
    def ensure_platform_config_dir(cls) -> Path:
        """Stellt sicher, dass das Konfigurationsverzeichnis existiert."""
        config_dir = cls.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
        cls.logger.debug(
            f"Ensured config directory exists: {config_dir}",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        return config_dir

    @classmethod
    def kill_process_tree(cls, pid: int, timeout: float = 5.0) -> bool:
        """Beendet einen Prozess und alle seine Kindprozesse."""
        import signal
        import subprocess

        cls.logger.debug(
            f"Killing process tree for PID {pid} (timeout={timeout}s)",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        start_time = time.monotonic()

        try:
            import psutil
        except ImportError:
            psutil = None

        if psutil is not None:
            try:
                parent = psutil.Process(pid)
                children = parent.children(recursive=True)
                if children:
                    cls.logger.debug(
                        f"  psutil: Found {len(children)} child processes",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    for child in children:
                        with contextlib.suppress(
                            psutil.NoSuchProcess,
                            psutil.AccessDenied,
                        ):
                            child.terminate()
                    remaining = max(0.1, timeout - (time.monotonic() - start_time))
                    _, alive = psutil.wait_procs(children, timeout=min(2.0, remaining))
                    for child in alive:
                        with contextlib.suppress(
                            psutil.NoSuchProcess,
                            psutil.AccessDenied,
                        ):
                            child.kill()

                remaining = max(0.1, timeout - (time.monotonic() - start_time))
                parent.terminate()
                parent.wait(timeout=min(2.0, remaining))
                cls.logger.debug(
                    f"  Terminated parent {pid}",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return True

            except psutil.NoSuchProcess:
                cls.logger.debug(
                    f"  Process {pid} does not exist",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return True
            except psutil.TimeoutExpired:
                try:
                    parent.kill()
                    parent.wait(timeout=1.0)
                    return True
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    return True
            except Exception as e:
                cls.logger.exception(
                    f"  psutil error: {e}",
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        def process_exists(p: int) -> bool:
            try:
                os.kill(p, 0)
                return True
            except (ProcessLookupError, OSError):
                return False

        try:
            if IS_WINDOWS:
                remaining = max(0.1, timeout - (time.monotonic() - start_time))
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=remaining,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                time.sleep(0.5)
                return not process_exists(pid)
            try:
                pgid = os.getpgid(pid)
                os.killpg(pgid, signal.SIGKILL)
                time.sleep(0.2)
                if not process_exists(pid):
                    return True
            except (ProcessLookupError, PermissionError, OSError):
                pass

            subprocess.run(
                ["pkill", "-9", "-P", str(pid)],
                capture_output=True,
                timeout=2.0,
                check=False,
            )
            time.sleep(0.2)
            return not process_exists(pid)

        except subprocess.TimeoutExpired:
            cls.logger.warning(
                f"  Timeout killing process tree {pid}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return False
        except Exception as e:
            cls.logger.exception(
                f"  Fallback error: {e}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return False

    @classmethod
    def terminate_process(
        cls,
        proc: subprocess.Popen,
        *,
        child_terminate_timeout: float = 2.0,
        child_kill_wait: float = 0.5,
        parent_terminate_timeout: float = 3.0,
        parent_kill_wait: float = 1.5,
        fallback_terminate_timeout: float = 2.0,
        fallback_kill_wait: float = 1.0,
        stats_callback: Callable[[str], None] | None = None,
        force: bool = False,
        close_pipes: bool = True,
        log_level: int = logging.DEBUG,
        component: str = "process",
    ) -> bool:
        """Beendet einen Prozess und alle seine Kindprozesse robust."""
        import logging as _logging
        import os as _os
        import signal as _signal
        import subprocess as _subprocess
        import time as _time

        import psutil

        logger = _logging.getLogger("dragon")
        debug_level = getattr(cls, "debug_level", 0)
        method_start = _time.perf_counter()
        is_windows = sys.platform == "win32"

        def _dbg(level: int, msg: str) -> None:
            if level <= debug_level:
                logger.debug(msg)

        def _stat(name: str) -> None:
            if stats_callback is not None:
                with contextlib.suppress(Exception):
                    stats_callback(name)

        if proc is None:
            _dbg(4, f"[{component}] ⏭️ terminate_process: proc ist None – überspringe")
            return True

        try:
            if proc.poll() is not None:
                _dbg(4, f"[{component}] ✅ Prozess bereits beendet (PID={proc.pid})")
                _stat("already_dead")
                return True
        except Exception as e:
            _dbg(4, f"[{component}] ⚠️ poll() fehlgeschlagen: {e}")
            return True

        pid = proc.pid
        _dbg(3, f"[{component}] 🚀 terminate_process: PID={pid}, force={force}")

        if close_pipes:
            for pipe_name in ("stdout", "stderr", "stdin"):
                pipe = getattr(proc, pipe_name, None)
                if pipe is None or pipe.closed:
                    continue
                try:
                    pipe.close()
                    _dbg(
                        4,
                        f"[{component}] 🔒 Pipe '{pipe_name}' geschlossen (PID={pid})",
                    )
                except Exception as e:
                    logger.log(
                        log_level,
                        f"[{component}] ⚠️ Fehler beim Schließen von Pipe "
                        f"'{pipe_name}': {e}",
                    )

        if not is_windows:
            try:
                _os.kill(pid, _signal.SIGCONT)
                _dbg(4, f"[{component}] 🔔 SIGCONT an PID {pid} gesendet")
            except (ProcessLookupError, PermissionError, OSError):
                pass
            except Exception:
                pass
            try:
                _pgid = _os.getpgid(pid)
                if _pgid > 0:
                    _os.killpg(_pgid, _signal.SIGCONT)
                    _dbg(
                        4, f"[{component}] 🔔 SIGCONT an Prozessgruppe {_pgid} gesendet"
                    )
            except (ProcessLookupError, PermissionError, OSError):
                pass
            except Exception:
                pass

        if not force:
            try:
                parent = psutil.Process(pid)
                children = parent.children(recursive=True)

                if children:
                    _dbg(
                        3,
                        f"[{component}] 👶 {len(children)} Kindprozesse von PID={pid}",
                    )

                    for child in children:
                        try:
                            if child.is_running():
                                child.terminate()
                                _dbg(4, f"[{component}] 👶 Kind {child.pid} SIGTERM")
                        except (psutil.NoSuchProcess, psutil.AccessDenied):
                            pass
                        except Exception as e:
                            logger.log(
                                log_level,
                                f"[{component}] ⚠️ Fehler Terminate Kind "
                                f"{child.pid}: {e}",
                            )

                    _, alive = psutil.wait_procs(
                        children, timeout=child_terminate_timeout
                    )
                    for child in alive:
                        try:
                            child.kill()
                            _dbg(4, f"[{component}] 👶 Kind {child.pid} SIGKILL")
                        except (psutil.NoSuchProcess, psutil.AccessDenied):
                            pass
                        except Exception as e:
                            logger.log(
                                log_level,
                                f"[{component}] ⚠️ Fehler Kill Kind {child.pid}: {e}",
                            )
                    if alive:
                        with contextlib.suppress(Exception):
                            psutil.wait_procs(alive, timeout=child_terminate_timeout)

                try:
                    parent.terminate()
                    parent.wait(timeout=parent_terminate_timeout)
                    _dbg(
                        3, f"[{component}] ✅ PID={pid} via psutil.terminate() beendet"
                    )
                    _stat("psutil_terminate")
                    return True
                except psutil.TimeoutExpired:
                    _dbg(
                        3, f"[{component}] ⏰ psutil.terminate() Timeout für PID={pid}"
                    )
                    try:
                        parent.kill()
                        parent.wait(timeout=parent_kill_wait)
                        _dbg(3, f"[{component}] ✅ PID={pid} via psutil.kill() beendet")
                        _stat("psutil_kill")
                        return True
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        return True
                    except Exception as e:
                        logger.log(
                            log_level,
                            f"[{component}] ⚠️ psutil.kill() PID={pid}: {e}",
                        )
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    return True
                except Exception as e:
                    logger.log(
                        log_level,
                        f"[{component}] ⚠️ Unerwarteter psutil-Fehler PID={pid}: {e}",
                    )

            except psutil.NoSuchProcess:
                _dbg(3, f"[{component}] ℹ️ PID={pid} nicht mehr vorhanden")
                return True
            except psutil.AccessDenied:
                logger.warning(
                    f"[{component}] ⚠️ Keine Berechtigung für psutil auf PID={pid}"
                )
            except Exception as e:
                logger.log(
                    log_level, f"[{component}] ⚠️ Unerwarteter psutil-Fehler: {e}"
                )

        if not force:
            try:
                proc.terminate()
                _dbg(3, f"[{component}] 📤 SIGTERM an PID={pid} gesendet")
                try:
                    proc.wait(timeout=parent_terminate_timeout)
                    _dbg(3, f"[{component}] ✅ PID={pid} via SIGTERM beendet")
                    _stat("terminate")
                    return True
                except _subprocess.TimeoutExpired:
                    _dbg(3, f"[{component}] ⏰ SIGTERM für PID={pid} timeout")
            except ProcessLookupError:
                return True
            except Exception as e:
                logger.log(log_level, f"[{component}] ⚠️ SIGTERM PID={pid}: {e}")

        try:
            proc.kill()
            _dbg(3, f"[{component}] 💀 SIGKILL an PID={pid} gesendet")
            try:
                proc.wait(timeout=parent_kill_wait)
                _dbg(3, f"[{component}] ✅ PID={pid} via SIGKILL beendet")
                _stat("kill")
                return True
            except _subprocess.TimeoutExpired:
                _dbg(3, f"[{component}] ⏰ SIGKILL für PID={pid} timeout")
        except ProcessLookupError:
            return True
        except Exception as e:
            logger.log(log_level, f"[{component}] ⚠️ SIGKILL PID={pid}: {e}")

        if is_windows:
            try:
                _dbg(3, f"[{component}] 🪟 taskkill für PID={pid}")
                _subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=_subprocess.CREATE_NO_WINDOW,
                )
                _time.sleep(0.2)
                if proc.poll() is not None:
                    _dbg(3, f"[{component}] ✅ PID={pid} via taskkill beendet")
                    _stat("taskkill")
                    return True

                _dbg(3, f"[{component}] 🪟 wmic für PID={pid}")
                _subprocess.run(
                    [
                        "wmic",
                        "process",
                        "where",
                        f"ParentProcessId={pid}",
                        "call",
                        "terminate",
                    ],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=_subprocess.CREATE_NO_WINDOW,
                )
                _time.sleep(0.2)
                if proc.poll() is not None:
                    _dbg(3, f"[{component}] ✅ PID={pid} via wmic beendet")
                    _stat("wmic")
                    return True
            except _subprocess.TimeoutExpired:
                logger.log(
                    log_level, f"[{component}] ⏰ taskkill/wmic timeout PID={pid}"
                )
            except FileNotFoundError:
                _dbg(4, f"[{component}] ⚠️ taskkill/wmic nicht gefunden")
            except Exception as e:
                logger.log(log_level, f"[{component}] ⚠️ taskkill/wmic: {e}")
        else:
            try:
                pgid = _os.getpgid(pid)
                _dbg(3, f"[{component}] 🐧 killpg (PGID={pgid}) für PID={pid}")
                _os.killpg(pgid, _signal.SIGKILL)
                _time.sleep(0.2)
                if proc.poll() is not None:
                    _dbg(3, f"[{component}] ✅ PID={pid} via killpg beendet")
                    _stat("killpg")
                    return True
            except ProcessLookupError:
                return True
            except PermissionError:
                _dbg(3, f"[{component}] ⚠️ Keine Berechtigung für killpg PID={pid}")
            except OSError as e:
                logger.log(log_level, f"[{component}] ⚠️ killpg: {e}")

            try:
                _dbg(3, f"[{component}] 🐧 pkill für PID={pid}")
                _subprocess.run(
                    ["pkill", "-9", "-P", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                )
                _time.sleep(0.2)
                try:
                    _os.kill(pid, _signal.SIGKILL)
                    _time.sleep(0.2)
                    if proc.poll() is not None:
                        _dbg(3, f"[{component}] ✅ PID={pid} via pkill/os.kill beendet")
                        _stat("pkill")
                        return True
                except ProcessLookupError:
                    return True
                except PermissionError:
                    _dbg(3, f"[{component}] ⚠️ Keine Berechtigung für kill PID={pid}")
                except OSError as e:
                    logger.log(log_level, f"[{component}] ⚠️ os.kill: {e}")
            except _subprocess.TimeoutExpired:
                logger.log(log_level, f"[{component}] ⏰ pkill timeout PID={pid}")
            except FileNotFoundError:
                _dbg(4, f"[{component}] ⚠️ pkill nicht gefunden")
            except Exception as e:
                logger.log(log_level, f"[{component}] ⚠️ pkill: {e}")

        try:
            _dbg(3, f"[{component}] 💀 Finaler SIGKILL für PID={pid}")
            proc.kill()
            try:
                proc.wait(timeout=fallback_kill_wait)
                _dbg(3, f"[{component}] ✅ PID={pid} via finalem kill beendet")
                _stat("final_kill")
                return True
            except _subprocess.TimeoutExpired:
                logger.log(
                    log_level,
                    f"[{component}] ⏰ Finaler SIGKILL timeout PID={pid}",
                )
        except ProcessLookupError:
            return True
        except Exception as e:
            logger.log(log_level, f"[{component}] ⚠️ Finaler kill PID={pid}: {e}")

        elapsed_ms = (_time.perf_counter() - method_start) * 1000
        logger.warning(
            f"[{component}] ❌ Prozess PID={pid} konnte nicht beendet werden "
            f"(Dauer: {elapsed_ms:.2f}ms, force={force})"
        )
        _stat("failed")
        return False

    @classmethod
    def check_platform_dependencies(cls, force: bool = False) -> bool:
        """Prüft, ob alle kritischen und optionalen Abhängigkeiten vorhanden sind."""
        with cls._dependencies_lock:
            if not force and cls._dependencies_checked:
                cls.logger.debug(
                    "Dependencies already checked, skipping",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return True

            if force:
                cls.logger.info("🔄 Forced dependency re-check requested")
                cls._dependencies_checked = False
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache.clear()

            missing_critical: list[str] = []
            issues: list[str] = []

            cls.logger.info("🔍 Checking platform dependencies...")
            cls.logger.debug(
                "Starting dependency check",
                extra={"component": cls._DEBUG_COMPONENT},
            )

            def check_tool(name: str) -> bool:
                with cls._dependencies_cache_lock:
                    now = time.monotonic()
                    entry = cls._dependencies_cache.get(f"tool_{name}")
                    if entry and now - entry[1] < cls._dependencies_cache_ttl:
                        return entry[0]
                found = cls._find_executable(name) is not None
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache[f"tool_{name}"] = (found, time.monotonic())
                return found

            cls._check_critical_tools(check_tool, missing_critical, issues)
            cls._check_optional_python_packages(issues)
            cls._check_optional_system_tools(check_tool, issues)
            cls._check_tts_components(check_tool, issues)
            cls._check_audio_players(check_tool, issues)

            if missing_critical:
                error_msg = cls._build_missing_critical_message(
                    missing_critical,
                    issues,
                )
                cls._dependencies_checked = False
                raise RuntimeError(error_msg)

            if issues:
                for issue in issues:
                    cls.logger.warning(f"⚠️ {issue}")

            cls.logger.info("✅ Alle kritischen Abhängigkeiten gefunden")
            cls._dependencies_checked = True
            return True

    @classmethod
    def _check_critical_tools(
        cls,
        check_tool,
        missing: list[str],
        issues: list[str],
    ) -> None:
        """Prüft ffmpeg und yt-dlp (kritische externe Tools)."""
        if not check_tool("ffmpeg"):
            missing.append("ffmpeg")
            issues.append("FFmpeg not found in PATH or standard locations")
            cls.logger.debug("  ✗ ffmpeg missing")
        else:
            cls.logger.debug("  ✓ ffmpeg found")

        if not check_tool("yt-dlp"):
            missing.append("yt-dlp")
            issues.append("yt-dlp not found in PATH")
            cls.logger.debug("  ✗ yt-dlp missing")
        else:
            cls.logger.debug("  ✓ yt-dlp found")

    @classmethod
    def _check_optional_python_packages(cls, issues: list[str]) -> None:
        """Prüft optionale Python-Pakete und fügt Warnungen zur `issues`-Liste hinzu."""

        def _is_module_available(
            module_name: str,
            package_name: str | None = None,
        ) -> bool:
            """Prüft, ob ein Python-Modul verfügbar ist."""
            try:
                __import__(module_name)
                return True
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            try:
                if importlib.util.find_spec(module_name) is not None:
                    return True
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            if package_name:
                try:
                    result = subprocess.run(
                        [sys.executable, "-m", "pip", "show", package_name],
                        capture_output=True,
                        text=True,
                        timeout=5,
                        check=False,
                    )
                    if result.returncode == 0:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "platform",
                                f"Paket {package_name} via pip show gefunden",
                            )
                        return True
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            return False

        openai_available = _is_module_available("whisper", "openai-whisper")
        faster_available = _is_module_available("faster_whisper", "faster-whisper")

        if not faster_available and not openai_available:
            log_debug(
                "platform",
                "Kein Whisper-Backend gefunden – wird später im Demo-Modus behandelt",
            )
        elif DEBUG_LEVEL >= 3:
            log_debug(
                "platform",
                f"Whisper-Backends: faster-whisper={faster_available}, openai-whisper={openai_available}",
            )

        if not _is_module_available("deep_translator", "deep-translator"):
            log_debug(
                "platform",
                "deep-translator nicht verfügbar (Übersetzung wird später ggf. eingeschränkt)",
            )

        if not _is_module_available("torch", "torch"):
            log_debug(
                "platform",
                "PyTorch nicht verfügbar – GPU-Beschleunigung deaktiviert",
            )

        if not _is_module_available("numpy", "numpy"):
            log_debug(
                "platform",
                "numpy nicht verfügbar – Audio-Verbesserungen eingeschränkt",
            )

        if not _is_module_available("scipy", "scipy"):
            log_debug(
                "platform",
                "scipy nicht verfügbar – Signalverarbeitung eingeschränkt",
            )

        if not _is_module_available("argostranslate", "argostranslate"):
            issues.append("argos-translate not available (offline translation limited)")

        if not _is_module_available("psutil", "psutil"):
            issues.append("psutil not available (system monitoring limited)")

        if not _is_module_available("pynvml", "pynvml"):
            log_debug("platform", "pynvml not available (detailed GPU stats limited)")

        if not _is_module_available("noisereduce", "noisereduce"):
            issues.append("noisereduce not available (audio enhancement limited)")

        if not _is_module_available("rapidfuzz", "rapidfuzz"):
            issues.append("rapidfuzz not available (duplicate detection slower)")

        if not _is_module_available("docx", "python-docx"):
            issues.append("python-docx not available (Word export disabled)")

        if not _is_module_available("tiktoken", "tiktoken"):
            issues.append("tiktoken not available (token estimation for LLM limited)")

        if not _is_module_available("spellchecker", "pyspellchecker"):
            issues.append("pyspellchecker not available (hotword filtering limited)")

        if not _is_module_available("keyring", "keyring"):
            issues.append("keyring not available (secure password storage disabled)")

        if IS_WINDOWS and not _is_module_available("win10toast", "win10toast"):
            issues.append("win10toast not installed (desktop notifications disabled)")

        if IS_MACOS and not _is_module_available("Foundation", "pyobjc"):
            issues.append("pyobjc not installed (macOS notifications disabled)")

        if GUI_AVAILABLE and not _is_module_available("tkinterdnd2", "tkinterdnd2"):
            log_debug("platform", "tkinterdnd2 not available (drag & drop disabled)")

        optional_packages = [
            ("langdetect", "langdetect", "language detection"),
            ("dimits", "dimits", "Piper TTS support"),
            ("pathvalidate", "pathvalidate", "Piper dependency"),
        ]
        for mod_name, pkg_name, description in optional_packages:
            if not _is_module_available(mod_name, pkg_name):
                log_debug("platform", f"{description} not available ({pkg_name})")

        if DEBUG_LEVEL >= 3:
            log_debug("platform", "Optionale Python-Pakete vollständig geprüft")

    @classmethod
    def _check_optional_system_tools(cls, check_tool, issues: list[str]) -> None:
        """Prüft optionale System-Tools (VLC, …)."""
        vlc_found = check_tool("vlc")
        if not vlc_found and IS_WINDOWS:
            for p in [
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]:
                if os.path.exists(p):
                    vlc_found = True
                    break
        if not vlc_found:
            issues.append("vlc not found (DVB‑S streams will not work)")

    @classmethod
    def _check_tts_components(cls, check_tool, issues: list[str]) -> None:
        """Prüft TTS‑Komponenten (espeak, piper)."""
        if not check_tool("espeak"):
            issues.append("espeak not found (lightweight TTS fallback unavailable)")

        piper_found = check_tool("piper")
        if not piper_found:
            try:
                cache_dir = cls.get_piper_cache_dir()
                if os.path.isdir(cache_dir):
                    for f in os.listdir(cache_dir):
                        if (
                            f.endswith(".onnx")
                            and os.path.getsize(os.path.join(cache_dir, f)) > 0
                        ):
                            piper_found = True
                            break
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
        if not piper_found:
            issues.append("piper not found (high‑quality TTS will be unavailable)")

    @classmethod
    def _check_audio_players(cls, check_tool, issues: list[str]) -> None:
        """Prüft, ob mindestens ein Audio-Player verfügbar ist."""
        players = [
            name for name in ["ffplay", "aplay", "paplay", "sox"] if check_tool(name)
        ]
        if not players:
            issues.append("No audio player found – TTS will not produce sound")

    @classmethod
    def _build_missing_critical_message(
        cls,
        missing: list[str],
        issues: list[str],
    ) -> str:
        """Erstellt eine detaillierte Fehlermeldung für fehlende kritische Abhängigkeiten."""
        msg = f"❌ Fehlende kritische Abhängigkeiten: {', '.join(missing)}\n\n"
        msg += "\n".join(issues) + "\n"

        if "ffmpeg" in missing:
            msg += "\nFFmpeg Installation:\n"
            if IS_WINDOWS:
                msg += "  • Ausführen: winget install --source winget Gyan.FFmpeg\n"
            elif IS_MACOS:
                msg += "  • brew install ffmpeg\n"
            else:
                msg += "  • sudo apt install ffmpeg\n"
        if "yt-dlp" in missing:
            msg += "\nyt-dlp Installation:\n"
            msg += "  • pip install yt-dlp\n"
        if "tkinter" in missing:
            msg += "\nTkinter Installation:\n"
            msg += "  • Usually included with Python. On Linux: sudo apt-get install python3-tk\n"
        if "numpy" in missing:
            msg += "\nnumpy Installation:\n"
            msg += "  • pip install numpy\n"
        msg += "\n💡 Nach der Installation starten Sie Dragon Whisperer neu."
        return msg

    @classmethod
    def _find_executable(cls, name: str) -> str | None:
        """Findet eine ausführbare Datei (mit Cache). Threadsicher."""
        with cls._executable_cache_lock:
            if name in cls._executable_cache:
                return cls._executable_cache[name]

        exe = shutil.which(name)
        if exe:
            with cls._executable_cache_lock:
                cls._executable_cache[name] = exe
            if cls.logger.isEnabledFor(logging.DEBUG):
                cls.logger.debug(f"  → {name} gefunden im PATH: {exe}")
            return exe

        scripts_dir = os.path.dirname(sys.executable)
        candidate = os.path.join(scripts_dir, f"{name}{'.exe' if IS_WINDOWS else ''}")
        if os.path.isfile(candidate) and os.access(
            candidate,
            os.X_OK if not IS_WINDOWS else os.R_OK,
        ):
            with cls._executable_cache_lock:
                cls._executable_cache[name] = candidate
            if cls.logger.isEnabledFor(logging.DEBUG):
                cls.logger.debug(
                    f"  → {name} gefunden unter {candidate} (venv‑Fallback)",
                )
            return candidate

        with cls._executable_cache_lock:
            cls._executable_cache[name] = None
        return None

    @classmethod
    def get_executable_path(cls, name: str) -> str | None:
        """Öffentliche Methode zum Abrufen des Pfads einer ausführbaren Datei."""
        return cls._find_executable(name)

    @classmethod
    def get_ffmpeg_path(cls) -> str | None:
        """Ermittelt den Pfad zur FFmpeg‑Executable (gecached, threadsicher)."""
        with cls._ffmpeg_path_lock:
            if cls._ffmpeg_path is not None:
                return cls._ffmpeg_path

            env_path = os.environ.get("FFMPEG_PATH")
            if env_path and os.path.exists(env_path):
                cls._ffmpeg_path = env_path
                return cls._ffmpeg_path

            ffmpeg_path = cls._find_executable("ffmpeg")
            if ffmpeg_path:
                cls._ffmpeg_path = ffmpeg_path
                return cls._ffmpeg_path

            if IS_WINDOWS:
                paths = [
                    "C:\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files (x86)\\ffmpeg\\bin\\ffmpeg.exe",
                ]
            elif IS_MACOS:
                paths = [
                    "/usr/local/bin/ffmpeg",
                    "/opt/homebrew/bin/ffmpeg",
                    "/usr/bin/ffmpeg",
                ]
            else:
                paths = [
                    "/usr/bin/ffmpeg",
                    "/usr/local/bin/ffmpeg",
                ]
            for path in paths:
                if os.path.exists(path):
                    cls._ffmpeg_path = path
                    return cls._ffmpeg_path

            cls._ffmpeg_path = None
            return None

    @classmethod
    def get_platform_info(cls) -> dict[str, Any]:
        """Liefert ein Dictionary mit detaillierten Plattforminformationen.

        Returns:
            Dict mit Schlüsseln wie 'system', 'is_windows', 'cpu_count', etc.

        """
        info: dict[str, Any] = {
            "system": SYSTEM,
            "is_windows": IS_WINDOWS,
            "is_macos": IS_MACOS,
            "is_linux": IS_LINUX,
            "is_arm": IS_ARM,
            "is_x86": IS_X86,
            "is_wsl": cls.is_wsl(),
            "is_docker": cls.is_docker(),
            "is_flatpak": cls.is_flatpak(),
            "is_snap": cls.is_snap(),
            "is_containerized": cls.is_containerized(),
            "container_type": cls.get_container_type(),
            "is_headless": cls.is_headless(),
            "python_version": sys.version,
            "python_executable": sys.executable,
            "current_directory": os.getcwd(),
            "environment_setup": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "cpu_model": cls.get_cpu_model(),
            "total_ram_gb": cls.get_total_ram_gb(),
            "username": cls.get_username(),
            "hostname": cls.get_hostname(),
            "timezone": cls.get_timezone(),
            "desktop_environment": cls.get_desktop_environment(),
        }
        try:
            import psutil

            info["cpu_count"] = psutil.cpu_count()
            info["cpu_count_logical"] = psutil.cpu_count(logical=True)
            freq = psutil.cpu_freq()
            info["cpu_freq_current_mhz"] = freq.current if freq else None
            mem = psutil.virtual_memory()
            info["memory_total_gb"] = mem.total / (1024**3)
            info["memory_available_gb"] = mem.available / (1024**3)
            info["memory_percent"] = mem.percent
            disk = psutil.disk_usage(os.getcwd())
            info["disk_free_gb"] = disk.free / (1024**3)
            info["disk_total_gb"] = disk.total / (1024**3)
        except ImportError:
            info["cpu_count"] = os.cpu_count()
            info["memory_total_gb"] = cls.get_total_ram_gb()
        except Exception as e:
            cls.logger.debug(f"psutil info error: {e}")

        try:
            import pynvml

            pynvml.nvmlInit()
            handle = pynvml.nvmlDeviceGetHandleByIndex(0)
            mem = pynvml.nvmlDeviceGetMemoryInfo(handle)
            info["gpu_name"] = pynvml.nvmlDeviceGetName(handle).decode()
            info["gpu_memory_total_gb"] = mem.total / (1024**3)
            info["gpu_memory_used_gb"] = mem.used / (1024**3)
            info["gpu_temperature_c"] = pynvml.nvmlDeviceGetTemperature(
                handle,
                pynvml.NVML_TEMPERATURE_GPU,
            )
            info["gpu_utilization_percent"] = pynvml.nvmlDeviceGetUtilizationRates(
                handle,
            ).gpu
            pynvml.nvmlShutdown()
        except Exception as e:
            cls.logger.debug(f"pynvml error: {e}")
        return info

    @classmethod
    def print_platform_info(cls) -> None:
        """Gibt die Plattforminformationen übersichtlich im Log aus."""
        info = cls.get_platform_info()
        cls.logger.info("\n" + "=" * 60)
        cls.logger.info("🐉 PLATFORM INFORMATION")
        cls.logger.info("=" * 60)
        for key, value in info.items():
            if key not in ["environment_setup", "dependencies_checked"]:
                cls.logger.info(f"{key:25} {value}")
        cls.logger.info("-" * 60)
        cls.logger.info(
            f"{'Environment Setup':25} {'✅' if info['environment_setup'] else '❌'}",
        )
        cls.logger.info(
            f"{'Dependencies Checked':25} {'✅' if info['dependencies_checked'] else '❌'}",
        )
        cls.logger.info("=" * 60)

    @classmethod
    def get_debug_info(cls, refresh: bool = False) -> dict[str, Any]:
        """Liefert detaillierte Debug‑Informationen über den internen Zustand.
        Bei refresh=True wird der Cache invalidiert und neu aufgebaut.
        """
        if (
            not refresh
            and hasattr(cls, "_cached_debug_info")
            and cls._cached_debug_info is not None
        ):
            return cls._cached_debug_info

        with cls._allowed_dirs_lock:
            user_dirs = [str(p) for p in cls._user_dirs]
            base_dirs = (
                [str(p) for p in cls._get_base_dirs()]
                if cls._base_dirs is not None
                else []
            )

        platform_info = {
            "user_dirs": user_dirs,
            "base_dirs": base_dirs,
            "ffmpeg_path": cls._ffmpeg_path,
            "terminal_settings_saved": cls._terminal_settings_saved,
            "original_stty_settings": cls._original_stty_settings,
            "environment_setup_done": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "test_home_override": str(cls._test_home) if cls._test_home else None,
            "test_cwd_override": str(cls._test_cwd) if cls._test_cwd else None,
            "console_configured": cls._console_configured,
            "container_type": cls.get_container_type(),
        }

        import os
        import platform
        import sys

        system_info = {
            "system": platform.system(),
            "release": platform.release(),
            "version": platform.version(),
            "machine": platform.machine(),
            "processor": platform.processor(),
            "python_version": sys.version,
            "python_executable": sys.executable,
            "os_encoding": sys.getfilesystemencoding(),
            "current_working_dir": os.getcwd(),
            "environment_utf8": os.environ.get("PYTHONUTF8", "not set"),
            "locale": os.environ.get("LANG", os.environ.get("LC_ALL", "not set")),
        }

        memory_info = {}
        try:
            import psutil

            mem = psutil.virtual_memory()
            memory_info = {
                "total_ram_gb": mem.total / (1024**3),
                "available_ram_gb": mem.available / (1024**3),
                "used_ram_gb": mem.used / (1024**3),
                "ram_percent": mem.percent,
                "swap_total_gb": (
                    (mem.swap_total if hasattr(mem, "swap_total") else 0) / (1024**3)
                    if hasattr(mem, "swap_total")
                    else 0
                ),
            }
        except ImportError:
            memory_info = {"error": "psutil not installed"}

        gpu_info = {}
        try:
            import pynvml

            pynvml.nvmlInit()
            handle = pynvml.nvmlDeviceGetHandleByIndex(0)
            mem = pynvml.nvmlDeviceGetMemoryInfo(handle)
            gpu_info = {
                "gpu_name": pynvml.nvmlDeviceGetName(handle).decode("utf-8"),
                "gpu_memory_total_gb": mem.total / (1024**3),
                "gpu_memory_used_gb": mem.used / (1024**3),
                "gpu_memory_free_gb": mem.free / (1024**3),
                "gpu_utilization": pynvml.nvmlDeviceGetUtilizationRates(handle).gpu,
                "memory_utilization": pynvml.nvmlDeviceGetUtilizationRates(
                    handle
                ).memory,
            }
            pynvml.nvmlShutdown()
        except ImportError:
            gpu_info = {"error": "pynvml not installed"}
        except Exception as e:
            gpu_info = {"error": f"NVML error: {e}"}

        process_info = {}
        if cls._get_debug_level() >= 4:
            import threading

            process_info = {
                "active_threads": threading.active_count(),
                "thread_names": [t.name for t in threading.enumerate() if t.is_alive()],
                "daemon_threads": sum(1 for t in threading.enumerate() if t.daemon),
            }
            try:
                import psutil

                proc = psutil.Process()
                process_info.update(
                    {
                        "pid": proc.pid,
                        "cpu_percent": proc.cpu_percent(interval=0.1),
                        "memory_rss_mb": proc.memory_info().rss / (1024**2),
                        "memory_vms_mb": proc.memory_info().vms / (1024**2),
                        "num_fds": (
                            proc.num_fds() if hasattr(proc, "num_fds") else "N/A"
                        ),
                        "open_files": len(proc.open_files()),
                        "connections": len(proc.connections()),
                    }
                )
            except (ImportError, psutil.NoSuchProcess, psutil.AccessDenied):
                pass

        result = {
            "platform_utils": platform_info,
            "system": system_info,
            "memory": memory_info,
            "gpu": gpu_info,
            "process": process_info,
            "timestamp": __import__("time").time(),
            "debug_level": cls._get_debug_level(),
        }

        try:
            from dragonwhisperer.config import get_config

            result["config"] = get_config().get_debug_info()
        except (ImportError, AttributeError):
            pass

        cls._cached_debug_info = result
        return result

    @classmethod
    def setup_platform_environment(cls) -> None:
        """Richtet plattformspezifische Umgebungsvariablen und Konsolen ein."""
        with cls._environment_setup_lock:
            if cls._environment_setup_done:
                cls.logger.debug(
                    "Environment already set up",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return

            cls.logger.info("🔧 Setting up platform environment...")
            cls.logger.debug(
                "Starting environment setup",
                extra={"component": cls._DEBUG_COMPONENT},
            )

            cls._save_terminal_settings()
            atexit.register(cls._restore_terminal_settings)

            if IS_WINDOWS:
                cls._setup_windows_console()
                atexit.register(cls._restore_windows_console)
                cls.logger.debug(
                    "Windows console setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            elif IS_MACOS:
                cls._setup_macos_temp_dir()
                cls.logger.debug(
                    "macOS temp dir setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            else:
                cls.logger.debug(
                    "Linux: no extra setup needed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                if cls.is_containerized():
                    cls.logger.info(
                        f"🐳 Running in container: {cls.get_container_type()}",
                    )

            cls._add_scripts_to_path()

            if IS_WINDOWS:
                os.environ["PYTHONIOENCODING"] = "utf-8"
            os.environ["PYTHONUTF8"] = "1"

            cls._environment_setup_done = True
            cls.logger.info("✅ Platform environment setup complete")
            cls.logger.debug(
                "Environment setup finished",
                extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def _add_scripts_to_path(cls) -> None:
        """Fügt die Scripts‑Verzeichnisse der aktuellen Python‑Umgebung zum PATH hinzu."""
        path_env = os.environ.get("PATH", "")
        paths_to_add: list[str] = []

        try:
            import sysconfig

            scripts_dir = sysconfig.get_path("scripts")
            if scripts_dir and os.path.isdir(scripts_dir):
                paths_to_add.append(scripts_dir)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls.logger.debug(
                    "Konnte Scripts‑Pfad (sysconfig) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        try:
            import site

            user_base = site.getuserbase()
            if IS_WINDOWS:
                user_scripts = os.path.join(user_base, "Scripts")
            else:
                user_scripts = os.path.join(user_base, "bin")
            if os.path.isdir(user_scripts):
                paths_to_add.append(user_scripts)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls.logger.debug(
                    "Konnte Benutzer‑Scripts‑Pfad (site) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        scripts_dir = os.path.dirname(sys.executable)
        if os.path.isdir(scripts_dir) and scripts_dir not in paths_to_add:
            paths_to_add.append(scripts_dir)

        for p in paths_to_add:
            if p not in path_env.split(os.pathsep):
                path_env = p + os.pathsep + path_env
                if DEBUG_LEVEL >= 2:
                    cls.logger.debug(
                        "Scripts‑Pfad zum PATH hinzugefügt: %s",
                        p,
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        os.environ["PATH"] = path_env

    @classmethod
    def _get_windows_version(cls) -> tuple[int, int, int]:
        """Gibt Windows-Version als Tupel (major, minor, build) zurück."""
        if not IS_WINDOWS:
            return (0, 0, 0)
        try:
            import ctypes

            class OSVERSIONINFOEXW(ctypes.Structure):
                _fields_ = [
                    ("dwOSVersionInfoSize", ctypes.c_ulong),
                    ("dwMajorVersion", ctypes.c_ulong),
                    ("dwMinorVersion", ctypes.c_ulong),
                    ("dwBuildNumber", ctypes.c_ulong),
                    ("dwPlatformId", ctypes.c_ulong),
                    ("szCSDVersion", ctypes.c_wchar * 128),
                    ("wServicePackMajor", ctypes.c_ushort),
                    ("wServicePackMinor", ctypes.c_ushort),
                    ("wSuiteMask", ctypes.c_ushort),
                    ("wProductType", ctypes.c_ubyte),
                    ("wReserved", ctypes.c_ubyte),
                ]

            kernel32 = ctypes.windll.kernel32
            ver = OSVERSIONINFOEXW()
            ver.dwOSVersionInfoSize = ctypes.sizeof(ver)
            if kernel32.RtlGetVersion(ctypes.byref(ver)) == 0:
                return (ver.dwMajorVersion, ver.dwMinorVersion, ver.dwBuildNumber)
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        try:
            import platform

            ver = platform.version().split(".")
            if len(ver) >= 3:
                try:
                    return (int(ver[0]), int(ver[1]), int(ver[2]))
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        return (0, 0, 0)

    @classmethod
    def _setup_windows_console(cls) -> bool:
        """Aktiviert UTF‑8 und virtuelle Terminal‑Sequenzen unter Windows,
        sofern die Windows‑Version dies unterstützt (mindestens Windows 10
        Build 10586).  Die Konfiguration wird nur einmal durchgeführt.
        """
        if not IS_WINDOWS or cls._console_configured:
            return cls._console_configured

        try:
            import ctypes
            from ctypes import wintypes
        except ImportError:
            cls.logger.warning(
                "ctypes nicht verfügbar – Windows‑Konsolen‑Setup nicht möglich.",
            )
            return False

        kernel32 = ctypes.windll.kernel32
        kernel32.SetConsoleCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleCP.restype = wintypes.BOOL
        kernel32.SetConsoleOutputCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleOutputCP.restype = wintypes.BOOL
        kernel32.GetConsoleMode.argtypes = [
            wintypes.HANDLE,
            ctypes.POINTER(wintypes.DWORD),
        ]
        kernel32.GetConsoleMode.restype = wintypes.BOOL
        kernel32.SetConsoleMode.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetConsoleMode.restype = wintypes.BOOL

        STD_OUTPUT_HANDLE = -11
        hOut = kernel32.GetStdHandle(STD_OUTPUT_HANDLE)
        if hOut is None or hOut == ctypes.c_void_p(-1).value:
            cls.logger.warning(
                "Standard‑Ausgabe‑Handle nicht verfügbar – Konsolen‑Setup fehlgeschlagen.",
            )
            return False

        mode_out = wintypes.DWORD()
        if not kernel32.GetConsoleMode(hOut, ctypes.byref(mode_out)):
            cls.logger.warning(
                "GetConsoleMode für Ausgabe fehlgeschlagen – Kann Konsolen‑Modus nicht ändern.",
            )
            return False

        cls._original_console_mode = mode_out.value
        cls._original_console_codepage_in = kernel32.GetConsoleCP()
        cls._original_console_codepage_out = kernel32.GetConsoleOutputCP()

        if cls._original_console_codepage_in != 65001 and not kernel32.SetConsoleCP(
            65001,
        ):
            cls.logger.warning(
                "SetConsoleCP(65001) fehlgeschlagen – Eingabe‑Codepage nicht geändert.",
            )
        if cls._original_console_codepage_out != 65001:
            if not kernel32.SetConsoleOutputCP(65001):
                cls.logger.warning(
                    "SetConsoleOutputCP(65001) fehlgeschlagen – Ausgabe‑Codepage nicht geändert.",
                )

        major, _minor, build = cls._get_windows_version()
        if major >= 10 and build >= 10586:
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            ENABLE_PROCESSED_OUTPUT = 0x0001
            new_mode = (
                mode_out.value
                | ENABLE_VIRTUAL_TERMINAL_PROCESSING
                | ENABLE_PROCESSED_OUTPUT
            )
            if (mode_out.value & ENABLE_VIRTUAL_TERMINAL_PROCESSING) == 0:
                if kernel32.SetConsoleMode(hOut, new_mode):
                    cls.logger.debug(
                        "Windows console: VT‑Verarbeitung aktiviert (Ausgabe).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                else:
                    cls.logger.debug(
                        f"VT‑Aktivierung fehlgeschlagen – wird ignoriert (Build {build}).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        else:
            cls.logger.debug(
                f"VT processing not supported on this Windows version (build {build})",
                extra={"component": cls._DEBUG_COMPONENT},
            )

        if major >= 10 and build >= 10586:
            STD_INPUT_HANDLE = -10
            hIn = kernel32.GetStdHandle(STD_INPUT_HANDLE)
            if hIn not in (None, ctypes.c_void_p(-1).value):
                mode_in = wintypes.DWORD()
                if kernel32.GetConsoleMode(hIn, ctypes.byref(mode_in)):
                    ENABLE_VIRTUAL_TERMINAL_INPUT = 0x0200
                    if (mode_in.value & ENABLE_VIRTUAL_TERMINAL_INPUT) == 0:
                        kernel32.SetConsoleMode(
                            hIn,
                            mode_in.value | ENABLE_VIRTUAL_TERMINAL_INPUT,
                        )
                        if DEBUG_LEVEL >= 4:
                            _safe_log_debug("console", "VT‑Eingabe aktiviert.")

        cls._console_configured = True
        return True

    @classmethod
    def _restore_windows_console(cls) -> None:
        """Stellt die ursprünglichen Konsolen‑Einstellungen wieder her."""
        if not IS_WINDOWS or not cls._console_configured:
            return
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            if cls._original_console_codepage_out is not None:
                kernel32.SetConsoleOutputCP(cls._original_console_codepage_out)
            if cls._original_console_codepage_in is not None:
                kernel32.SetConsoleCP(cls._original_console_codepage_in)
            if cls._original_console_mode is not None:
                hOut = kernel32.GetStdHandle(-11)
                if hOut not in (None, ctypes.c_void_p(-1).value):
                    kernel32.SetConsoleMode(hOut, cls._original_console_mode)
            cls.logger.debug(
                "Windows‑Konsolen‑Einstellungen wiederhergestellt.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except Exception as e:
            cls.logger.debug(f"Fehler beim Wiederherstellen der Konsole: {e}")
        finally:
            cls._console_configured = False

    @classmethod
    def _setup_macos_temp_dir(cls) -> None:
        """Erstellt ein temporäres Verzeichnis für Dragon Whisperer unter macOS."""
        temp_dir = Path(tempfile.gettempdir()) / "dragonwhisperer"
        try:
            temp_dir.mkdir(parents=True, exist_ok=True)
            cls.logger.debug(
                f"macOS temp dir ensured: {temp_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except (OSError, PermissionError) as e:
            cls.logger.warning(f"⚠️ macOS temp dir creation failed: {e}")

    @classmethod
    def _save_terminal_settings(cls) -> None:
        """Speichert die aktuellen Terminal‑Einstellungen (Linux/macOS) für die spätere Wiederherstellung.
        Auf Windows wird nichts gespeichert (Terminal-Steuerung nicht nötig).
        Die Methode ist thread-sicher und fängt alle Fehler ab.

        Version 2.0 – mit erweitertem Debug, robusterem Logger und besserer Fehlerbehandlung.
        """
        import logging
        import shutil
        import subprocess
        import time

        logger = getattr(cls, "logger", None)
        if logger is None:
            logger = logging.getLogger(cls.__name__)
            with contextlib.suppress(AttributeError):
                cls.logger = logger

        component = getattr(cls, "_DEBUG_COMPONENT", "terminal")

        if not IS_LINUX and not IS_MACOS:
            logger.debug(
                f"[{component}] Terminal settings not saved (non-Unix platform)",
            )
            return

        if getattr(cls, "_terminal_settings_saved", False):
            logger.debug(f"[{component}] Terminal settings already saved – skipping")
            return

        if not shutil.which("stty"):
            logger.warning(
                f"[{component}] stty not found in PATH – cannot save terminal settings",
            )
            cls._terminal_settings_saved = True
            return

        lock = getattr(cls, "_terminal_lock", None)
        if lock is None:
            import threading

            lock = threading.RLock()
            with contextlib.suppress(AttributeError):
                cls._terminal_lock = lock

        with lock:
            if getattr(cls, "_terminal_settings_saved", False):
                return

            try:
                logger.debug(f"[{component}] Saving terminal settings via stty -g...")
                start_time = time.perf_counter()
                result = subprocess.run(
                    ["stty", "-g"],
                    capture_output=True,
                    text=True,
                    timeout=5,
                    check=False,
                )

                elapsed_ms = (time.perf_counter() - start_time) * 1000

                if result.returncode == 0 and result.stdout.strip():
                    cls._original_stty_settings = result.stdout.strip()
                    cls._terminal_settings_saved = True
                    logger.debug(
                        f"[{component}] Terminal settings saved (stty -g) in {elapsed_ms:.2f}ms: "
                        f"{cls._original_stty_settings[:50]}...",
                    )

                    if getattr(cls, "DEBUG_LEVEL", 0) >= 3:
                        mode_flags = cls._get_terminal_mode_flags()
                        if mode_flags:
                            cls._terminal_mode_flags = mode_flags
                            logger.debug(
                                f"[{component}] Terminal mode flags: {mode_flags}",
                            )
                else:
                    logger.warning(
                        f"[{component}] stty -g failed (returncode {result.returncode}) "
                        f"in {elapsed_ms:.2f}ms: {result.stderr.strip() if result.stderr else 'no stderr output'}",
                    )
                    fallback_settings = cls._try_stty_a_fallback()
                    if fallback_settings:
                        cls._original_stty_settings = fallback_settings
                        cls._terminal_settings_saved = True
                        logger.info(
                            f"[{component}] Terminal settings saved via stty -a fallback: "
                            f"{fallback_settings[:50]}...",
                        )
                    else:
                        logger.warning(
                            f"[{component}] Could not save terminal settings – fallback failed",
                        )
                        cls._terminal_settings_saved = True

            except subprocess.TimeoutExpired:
                logger.error(
                    f"[{component}] stty -g timeout after 5s – cannot save terminal settings",
                )
                cls._terminal_settings_saved = True
            except Exception as e:
                logger.exception(
                    f"[{component}] Unexpected error saving terminal settings: {e}",
                )
                cls._terminal_settings_saved = True

    @classmethod
    def _try_stty_a_fallback(cls) -> str | None:
        """Versucht, die Terminal-Einstellungen über `stty -a` zu extrahieren.
        Gibt einen String im stty -g-Format zurück oder None bei Fehler.
        """
        import logging
        import shutil
        import subprocess

        logger = getattr(cls, "logger", logging.getLogger(cls.__name__))
        component = getattr(cls, "_DEBUG_COMPONENT", "terminal")

        if not shutil.which("stty"):
            return None

        try:
            result = subprocess.run(
                ["stty", "-a"],
                capture_output=True,
                text=True,
                timeout=3,
                check=False,
            )
            if result.returncode != 0 or not result.stdout:
                return None
            logger.debug(
                f"[{component}] Fallback via stty -a: could not parse to stty -g format, "
                f"but raw output available.",
            )
            return None
        except Exception as e:
            logger.debug(f"[{component}] Fallback via stty -a failed: {e}")
            return None

    @classmethod
    def _get_terminal_mode_flags(cls) -> dict[str, bool] | None:
        """(Optional) Liest die aktuellen Terminal-Modus-Flags (z. B. echo, icanon) aus.
        Gibt ein Dictionary zurück oder None bei Fehler.
        """
        import shutil
        import subprocess

        logger = getattr(cls, "logger", None)
        component = getattr(cls, "_DEBUG_COMPONENT", "terminal")

        if not shutil.which("stty"):
            return None

        try:
            result = subprocess.run(
                ["stty", "-a"],
                capture_output=True,
                text=True,
                timeout=3,
                check=False,
            )
            if result.returncode != 0:
                return None

            flags = {}
            for flag in ["echo", "icanon", "isig", "iexten", "echoctl", "echoke"]:
                if f" {flag}" in result.stdout or f"-{flag}" not in result.stdout:
                    flags[flag] = True
                else:
                    flags[flag] = False
            return flags
        except Exception as e:
            if logger:
                logger.debug(f"[{component}] _get_terminal_mode_flags failed: {e}")
            return None

    @classmethod
    def _restore_terminal_settings(cls) -> None:
        """Stellt die ursprünglichen Terminal‑Einstellungen wieder her (Linux/macOS).
        Wird beim Programmende aufgerufen, um das Terminal in einen sichtbaren Zustand zu versetzen.
        Die Methode ist thread-sicher und fängt alle Fehler ab.
        """
        import logging
        import shutil
        import subprocess
        import time

        logger = getattr(cls, "logger", None)
        if logger is None:
            logger = logging.getLogger(cls.__name__)
            with contextlib.suppress(AttributeError):
                cls.logger = logger

        component = getattr(cls, "_DEBUG_COMPONENT", "terminal")

        if not IS_LINUX and not IS_MACOS:
            logger.debug(
                f"[{component}] Terminal settings not restored (non-Unix platform)",
            )
            return

        if getattr(cls, "_terminal_restored", False):
            logger.debug(f"[{component}] Terminal settings already restored – skipping")
            return

        if not shutil.which("stty"):
            logger.warning(
                f"[{component}] stty not found in PATH – cannot restore terminal settings",
            )
            cls._reset_terminal_fallback()
            return

        lock = getattr(cls, "_terminal_lock", None)
        if lock is None:
            import threading

            lock = threading.RLock()
            with contextlib.suppress(AttributeError):
                cls._terminal_lock = lock

        with lock:
            if getattr(cls, "_terminal_restored", False):
                return

            start_time = time.perf_counter()
            saved_settings = getattr(cls, "_original_stty_settings", None)

            if saved_settings is not None:
                try:
                    logger.debug(
                        f"[{component}] Restoring terminal settings: {saved_settings[:50]}...",
                    )
                    result = subprocess.run(
                        ["stty", saved_settings],
                        capture_output=True,
                        text=True,
                        timeout=3,
                        check=False,
                    )

                    elapsed_ms = (time.perf_counter() - start_time) * 1000

                    if result.returncode == 0:
                        logger.debug(
                            f"[{component}] Terminal settings restored successfully "
                            f"in {elapsed_ms:.2f}ms",
                        )
                        cls._terminal_restored = True
                        return
                    logger.warning(
                        f"[{component}] stty restore failed (returncode {result.returncode}) "
                        f"in {elapsed_ms:.2f}ms: {result.stderr.strip() if result.stderr else 'no stderr'}",
                    )
                except subprocess.TimeoutExpired:
                    logger.error(f"[{component}] stty restore timeout after 3s")
                except Exception as e:
                    logger.exception(
                        f"[{component}] Unexpected error restoring terminal settings: {e}",
                    )
            else:
                logger.debug(f"[{component}] No saved terminal settings to restore")

            logger.warning(
                f"[{component}] Using fallback to reset terminal to default state",
            )
            cls._reset_terminal_fallback()

    @classmethod
    def _reset_terminal_fallback(cls) -> None:
        """Letzte Rettung: Setzt das Terminal auf Standardeinstellungen zurück.
        Wird verwendet, wenn die gespeicherten Einstellungen nicht wiederhergestellt werden können.
        Verbessert: Mehrere Ansätze, um das Terminal in einen sichtbaren Zustand zu versetzen.
        """
        import logging
        import shutil
        import subprocess

        logger = getattr(cls, "logger", None)
        if logger is None:
            logger = logging.getLogger(cls.__name__)
            with contextlib.suppress(AttributeError):
                cls.logger = logger

        component = getattr(cls, "_DEBUG_COMPONENT", "terminal")

        def _log(msg: str, level: str = "debug") -> None:
            getattr(logger, level)(f"[{component}] {msg}")

        if not shutil.which("stty"):
            _log("stty not found – cannot reset terminal", "warning")
            try:
                import sys

                sys.stdout.write("\033[0m")
                sys.stdout.flush()
            except Exception:
                pass
            cls._terminal_restored = True
            return

        try:
            _log("Trying `stty sane`...")
            result = subprocess.run(
                ["stty", "sane"],
                capture_output=True,
                timeout=2,
                check=False,
            )
            if result.returncode == 0:
                _log("`stty sane` succeeded")
                cls._terminal_restored = True
                return
            _log(f"`stty sane` failed (exit {result.returncode})", "warning")

            _log("Trying to reset individual flags...")
            flags = ["echo", "icanon", "isig", "iexten", "echoctl", "echoke"]
            for flag in flags:
                subprocess.run(
                    ["stty", flag],
                    capture_output=True,
                    timeout=1,
                    check=False,
                )
            try:
                import sys

                sys.stdout.write("\033[0m")
                sys.stdout.flush()
            except Exception:
                pass
            _log("Terminal reset via individual flags")
            cls._terminal_restored = True
            return

        except subprocess.TimeoutExpired:
            _log("stty fallback timeout", "error")
        except Exception as e:
            _log(f"stty fallback exception: {e}", "error")

        try:
            _log("Trying `os.system('stty sane')`...", "warning")
            import os

            os.system("stty sane 2>/dev/null")
            cls._terminal_restored = True
        except Exception as e:
            _log(f"os.system fallback failed: {e}", "error")
            cls._terminal_restored = True

    @classmethod
    def apply_theme_to_widget_tree(
        cls,
        root_widget: tk.Widget,
        theme: Any,
        update_idletasks: bool = True,
        include_ttk: bool = True,
        ttk_styles: dict[str, dict[str, str]] | None = None,
    ) -> None:
        """Wendet das übergebene Theme rekursiv auf alle tk‑Widgets im Teilbaum an."""
        if not GUI_AVAILABLE or root_widget is None:
            return

        def _get_theme_attr(attr: str, fallback: str) -> str:
            try:
                return getattr(theme, attr, fallback)
            except Exception:
                try:
                    return getattr(DarkTheme(), attr, fallback)
                except Exception:
                    return fallback

        def _safe_configure(widget: tk.Widget, **kwargs: Any) -> None:
            if not kwargs:
                return
            clean = {
                k: v for k, v in kwargs.items() if isinstance(k, str) and k.strip()
            }
            if not clean:
                return
            try:
                widget.configure(**clean)
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug(
                        "theme",
                        f"_safe_configure({widget}) TclError: {e}",
                    )
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        def _apply_ttk_style(widget: ttk.Widget, style_name: str) -> None:
            if not include_ttk:
                return
            try:
                style = ttk.Style()
                base_style: dict[str, str] = {}
                if ttk_styles is not None and style_name in ttk_styles:
                    base_style.update(ttk_styles[style_name])
                base_style.setdefault(
                    "fieldbackground",
                    _get_theme_attr(
                        "INPUT_BG",
                        _get_theme_attr("BG_TERTIARY", "#242d38"),
                    ),
                )
                base_style.setdefault(
                    "background",
                    _get_theme_attr("BG_TERTIARY", "#242d38"),
                )
                base_style.setdefault(
                    "foreground",
                    _get_theme_attr("TEXT_PRIMARY", "#e6edf3"),
                )
                base_style.setdefault(
                    "selectbackground",
                    _get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                )
                base_style.setdefault(
                    "selectforeground",
                    _get_theme_attr("TEXT_PRIMARY", "#e6edf3"),
                )
                style.configure(style_name, **base_style)
                widget.configure(style=style_name)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        stack: list[tk.Widget | tk.Toplevel] = [root_widget]
        total_updated = 0
        total_skipped_ttk = 0
        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue
            w_class = widget.__class__
            if issubclass(w_class, ttk.Widget):
                if not include_ttk:
                    total_skipped_ttk += 1
                    try:
                        stack.extend(widget.winfo_children())
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
                    continue

                style_name = None
                if isinstance(widget, ttk.Combobox):
                    style_name = "Dark.TCombobox"
                elif isinstance(widget, ttk.Progressbar):
                    style_name = "Dark.Horizontal.TProgressbar"
                elif isinstance(widget, ttk.Entry):
                    style_name = "Dark.TEntry"
                elif isinstance(widget, ttk.Label):
                    style_name = "Dark.TLabel"
                elif isinstance(widget, ttk.Button):
                    style_name = "Dark.TButton"
                if style_name:
                    _apply_ttk_style(widget, style_name)

                try:
                    stack.extend(widget.winfo_children())
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                continue

            if w_class == scrolledtext.ScrolledText:
                try:
                    inner = widget
                    if inner and inner.winfo_exists():
                        _safe_configure(
                            inner,
                            bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                            fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            selectbackground=_get_theme_attr(
                                "COMBO_SELECTION",
                                "#1f6feb",
                            ),
                            selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        )
                        total_updated += 1
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                try:
                    vbar = widget.vbar
                    if vbar and vbar.winfo_exists():
                        _safe_configure(
                            vbar,
                            bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                            activebackground=_get_theme_attr(
                                "SCROLLBAR_HOVER",
                                "#999999",
                            ),
                            troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                        total_updated += 1
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                try:
                    stack.extend(widget.winfo_children())
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                continue

            if w_class == tk.PanedWindow:
                try:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        sashrelief="raised",
                        sashwidth=4,
                    )
                    total_updated += 1
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                try:
                    stack.extend(widget.winfo_children())
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                continue

            try:
                if w_class in (tk.Label,):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_PRIMARY", "#ffffff"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1

                elif w_class in (tk.Button,):
                    _is_exit_button = getattr(
                        widget,
                        "_is_exit_button",
                        False,
                    )
                    if _is_exit_button:
                        _safe_configure(
                            widget,
                            fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            activeforeground=_get_theme_attr(
                                "TEXT_ACCENT",
                                "#1f6feb",
                            ),
                        )
                    else:
                        _safe_configure(
                            widget,
                            bg=_get_theme_attr("BG_TERTIARY", "#cccccc"),
                            fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            activebackground=_get_theme_attr(
                                "BG_HOVER",
                                "#dddddd",
                            ),
                            activeforeground=_get_theme_attr(
                                "TEXT_ACCENT",
                                "#1f6feb",
                            ),
                        )
                    total_updated += 1

                elif w_class in (tk.Checkbutton, tk.Radiobutton):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        activebackground=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        activeforeground=_get_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    total_updated += 1
                elif w_class in (tk.Entry, tk.Spinbox, tk.Text):
                    input_bg = _get_theme_attr(
                        "INPUT_BG",
                        _get_theme_attr("BG_TERTIARY", "#ffffff"),
                    )
                    _safe_configure(
                        widget,
                        bg=input_bg,
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    if w_class == tk.Spinbox:
                        _safe_configure(
                            widget,
                            buttonbackground=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                    total_updated += 1
                elif w_class == tk.Frame:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                elif w_class == tk.LabelFrame:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scale:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Listbox:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scrollbar:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                        activebackground=_get_theme_attr("SCROLLBAR_HOVER", "#999999"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Canvas:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                else:
                    try:
                        widget.configure(bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                        total_updated += 1

                    except tk.TclError as e:
                        if DEBUG_LEVEL >= 3:
                            _safe_log_debug(
                                "theme",
                                f"Fehler bei {w_class.__name__}: {e}",
                            )
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug(
                        "theme",
                        f"Fehler bei {w_class.__name__}: {e}",
                    )
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            try:
                stack.extend(widget.winfo_children())
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        if update_idletasks:
            try:
                root_widget.update_idletasks()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        if DEBUG_LEVEL >= 3:
            _safe_log_debug(
                "theme",
                f"apply_theme_to_widget_tree: {total_updated} tk-Widgets aktualisiert, "
                f"{total_skipped_ttk} ttk-Widgets übersprungen (include_ttk={include_ttk})",
            )

    @classmethod
    def sanitize_url(cls, url: str) -> str:
        """Entfernt überflüssige Whitespaces und bereinigt die URL."""
        return url.strip() if url else ""

    @classmethod
    def validate_file_path(
        cls,
        file_url: str,
        allowed_dirs: list[str] | None = None,
    ) -> tuple[bool, str]:
        """Validiert eine file://‑URL."""
        cls.logger.debug(
            f"Validating file URL: {file_url}",
            extra={"component": cls._DEBUG_COMPONENT},
        )

        if not file_url.startswith("file://"):
            return False, "Keine file://-URL"

        try:
            if IS_WINDOWS and file_url.startswith("file:///"):
                path_part = file_url[8:]
            else:
                path_part = file_url[len("file://") :]
            path_part = urllib.request.url2pathname(path_part)
        except Exception as e:
            return False, f"Pfad kann nicht extrahiert werden: {e}"

        try:
            real_path = Path(path_part).resolve()
        except Exception as e:
            return False, f"Pfad kann nicht normalisiert werden: {e}"

        if not real_path.exists():
            return False, f"Datei existiert nicht: {real_path}"
        if not real_path.is_file():
            return False, "Keine gültige Datei (möglicherweise ein Verzeichnis)"

        allowed_bases = cls._get_allowed_dirs()
        if allowed_dirs:
            for d in allowed_dirs:
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                    if p.exists():
                        allowed_bases.append(p)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

        if not allowed_bases:
            return False, "Keine erlaubten Verzeichnisse definiert"

        for base in allowed_bases:
            try:
                real_path.relative_to(base)
                return True, str(real_path)
            except ValueError:
                continue

        return False, "Datei außerhalb der erlaubten Verzeichnisse"

    @classmethod
    def validate_url(cls, url: str) -> tuple[bool, str]:
        """Validiert eine beliebige URL (http, https, file, dvb, ...)."""
        if not url:
            return False, "URL is empty"
        url = cls.sanitize_url(url)
        cls.logger.debug(
            f"Validating URL: {url}",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        if url.startswith(("dvb://", "dvb-s://")):
            return cls._validate_dvb_url(url)
        if url.startswith("file://"):
            return cls.validate_file_path(url)

        if not url.startswith(("http://", "https://")):
            return False, f"Nicht unterstütztes URL-Schema: {url[:50]}"
        try:
            parsed = urllib.parse.urlparse(url)
            if not parsed.netloc:
                return False, "Keine Netzwerkadresse in URL"
            allowed_chars = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
            components = parsed.path + parsed.query + parsed.fragment + parsed.params
            if not re.match(f"^[{allowed_chars}]*$", components):
                return False, f"URL enthält nicht erlaubte Zeichen: {components[:50]}"
            return True, "ok"
        except Exception as e:
            return False, f"URL-Parsing fehlgeschlagen: {e}"

    @classmethod
    def _validate_dvb_url(cls, url: str) -> tuple[bool, str]:
        """Validiert eine DVB‑URL (dvb:// oder dvb-s://)."""
        params_part = url[8:] if url.startswith("dvb-s://") else url[6:]
        allowed = r"a-zA-Z0-9=&\-_.+"
        if not re.match(f"^[{allowed}]*$", params_part):
            return (
                False,
                f"DVB-Parameter enthalten ungültige Zeichen: {params_part[:50]}",
            )
        if "frequency=" not in params_part:
            return False, "DVB-URL muss 'frequency=' enthalten"
        return True, "ok"

    @classmethod
    def set_test_home(cls, path: Path | None) -> None:
        """Überschreibt das Home‑Verzeichnis für Tests. Nur zu Testzwecken."""
        cls._test_home = path
        cls.logger.debug(
            f"Test home set to: {path}",
            extra={"component": cls._DEBUG_COMPONENT},
        )

    @classmethod
    def set_test_cwd(cls, path: Path | None) -> None:
        """Überschreibt das aktuelle Arbeitsverzeichnis für Tests."""
        cls._test_cwd = path
        cls.logger.debug(
            f"Test cwd set to: {path}",
            extra={"component": cls._DEBUG_COMPONENT},
        )

    @classmethod
    def _get_base_dirs(cls) -> list[Path]:
        """Liefert die immer erlaubten Basisverzeichnisse (Home, CWD, tmp, Cache)."""
        with cls._allowed_dirs_lock:
            if cls._base_dirs is None:
                cls._base_dirs = [
                    cls._get_home().resolve(),
                    cls._get_cwd().resolve(),
                    Path(tempfile.gettempdir()).resolve(),
                ]
                cache_dir = cls._get_home() / ".cache" / "dragonwhisperer"
                if cache_dir.exists():
                    cls._base_dirs.append(cache_dir.resolve())
            return cls._base_dirs

    @classmethod
    def _get_allowed_dirs(cls) -> list[Path]:
        """Gibt die Vereinigung von Basis- und Benutzerverzeichnissen zurück."""
        base = cls._get_base_dirs()
        with cls._allowed_dirs_lock:
            return base + cls._user_dirs

    @classmethod
    def _get_home(cls) -> Path:
        """Gibt das Home‑Verzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_home:
            return cls._test_home
        return Path.home()

    @classmethod
    def _get_cwd(cls) -> Path:
        """Gibt das aktuelle Arbeitsverzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_cwd:
            return cls._test_cwd
        return Path.cwd()

    @classmethod
    def get_temp_dir(cls, subfolder: str | None = None) -> Path:
        """Gibt ein plattformunabhängiges temporäres Verzeichnis für Dragon Whisperer zurück."""
        base = Path(tempfile.gettempdir()) / "dragonwhisperer"
        base.mkdir(parents=True, exist_ok=True)
        if subfolder:
            target = base / subfolder
            target.mkdir(parents=True, exist_ok=True)
            return target
        return base

    @classmethod
    @contextmanager
    def temporary_directory(
        cls,
        prefix: str = "dw_temp_",
        keep: bool = False,
        cleanup_on_exit: bool = True,
    ) -> Iterator[Path]:
        """Kontextmanager für ein temporäres Verzeichnis, das nach Verlassen gelöscht wird."""
        import atexit
        import shutil
        import tempfile
        from pathlib import Path

        temp_dir = Path(tempfile.mkdtemp(prefix=prefix))
        log_debug("platform", f"Temporäres Verzeichnis erstellt: {temp_dir}")

        def _cleanup() -> None:
            """Löscht das temporäre Verzeichnis, falls es noch existiert."""
            if not temp_dir.exists():
                return
            try:
                shutil.rmtree(temp_dir, ignore_errors=False)
                log_debug("platform", f"Temporäres Verzeichnis gelöscht: {temp_dir}")
            except PermissionError as e:
                log_debug(
                    "platform",
                    f"Keine Berechtigung zum Löschen von {temp_dir}: {e}",
                )
            except OSError as e:
                log_debug("platform", f"OS-Fehler beim Löschen von {temp_dir}: {e}")
            except Exception as e:
                log_debug(
                    "platform",
                    f"Unerwarteter Fehler beim Löschen von {temp_dir}: {e}",
                )

        if cleanup_on_exit and not keep:
            atexit.register(_cleanup)

        try:
            yield temp_dir
        finally:
            if not keep:
                if cleanup_on_exit:
                    try:
                        atexit.unregister(_cleanup)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
                _cleanup()

    @classmethod
    @contextmanager
    def temporary_file(
        cls,
        suffix: str = ".tmp",
        prefix: str = "dw_",
        dir: Path | None = None,
        text_mode: bool = False,
        encoding: str = "utf-8",
        keep: bool = False,
        cleanup_on_exit: bool = True,
    ) -> Iterator[Path]:
        """Kontextmanager für eine temporäre Datei, die nach Verlassen gelöscht wird."""
        import atexit
        import tempfile
        from pathlib import Path

        if text_mode:
            fd, path = tempfile.mkstemp(
                suffix=suffix,
                prefix=prefix,
                dir=dir,
                text=text_mode,
            )
            os.close(fd)
        else:
            fd, path = tempfile.mkstemp(suffix=suffix, prefix=prefix, dir=dir)
            os.close(fd)

        temp_path = Path(path)
        log_debug("platform", f"Temporäre Datei erstellt: {temp_path}")

        def _cleanup() -> None:
            """Löscht die temporäre Datei, falls sie noch existiert."""
            if not temp_path.exists():
                return
            try:
                temp_path.unlink()
                log_debug("platform", f"Temporäre Datei gelöscht: {temp_path}")
            except PermissionError as e:
                log_debug(
                    "platform",
                    f"Keine Berechtigung zum Löschen von {temp_path}: {e}",
                )
            except OSError as e:
                log_debug("platform", f"OS-Fehler beim Löschen von {temp_path}: {e}")
            except Exception as e:
                log_debug(
                    "platform",
                    f"Unerwarteter Fehler beim Löschen von {temp_path}: {e}",
                )

        if cleanup_on_exit and not keep:
            atexit.register(_cleanup)

        try:
            yield temp_path
        finally:
            if not keep:
                if cleanup_on_exit:
                    try:
                        atexit.unregister(_cleanup)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
                _cleanup()

    @classmethod
    def open_file_explorer(cls, path: Path) -> bool:
        """Öffnet den systemeigenen Datei-Explorer (Windows) / Finder (macOS) / Nautilus (Linux)
        am angegebenen Pfad.
        """
        if not path.exists():
            cls.logger.warning(f"open_file_explorer: Pfad existiert nicht: {path}")
            return False
        try:
            if IS_WINDOWS:
                os.startfile(str(path))
            elif IS_MACOS:
                subprocess.run(["open", str(path)], check=True)
            else:
                for cmd in ["xdg-open", "nautilus", "dolphin", "thunar"]:
                    if shutil.which(cmd):
                        subprocess.run([cmd, str(path)], check=False)
                        break
                else:
                    cls.logger.warning("Kein Dateimanager gefunden.")
                    return False
            cls.logger.debug(f"Datei-Explorer geöffnet: {path}")
            return True
        except Exception as e:
            cls.logger.error(f"Fehler beim Öffnen des Datei-Explorers: {e}")
            return False

    @classmethod
    def get_system_encoding(cls) -> str:
        """Liefert die vom System bevorzugte Kodierung (für Textdateien etc.).

        Returns:
            String wie 'utf-8', 'cp1252', etc.

        """
        encoding = sys.getfilesystemencoding()
        if not encoding or encoding.lower() in ("ascii", "ansi"):
            return "utf-8"
        return encoding

    @classmethod
    def get_network_interfaces(cls) -> dict[str, dict[str, Any]]:
        """Gibt Informationen zu den verfügbaren Netzwerkschnittstellen zurück.

        Returns:
            Dict mit Schnittstellennamen als Schlüssel und Details (IP, MAC, etc.).

        """
        interfaces = {}
        try:
            import netifaces

            for iface in netifaces.interfaces():
                addrs = netifaces.ifaddresses(iface)
                interfaces[iface] = {
                    "ipv4": addrs.get(netifaces.AF_INET, [{}])[0].get("addr"),
                    "ipv6": addrs.get(netifaces.AF_INET6, [{}])[0].get("addr"),
                    "mac": addrs.get(netifaces.AF_LINK, [{}])[0].get("addr"),
                }
        except ImportError:
            cls.logger.debug("netifaces not installed – network info limited")
        return interfaces

    _PUBLIC_IP_CACHE_TTL: float = 60.0
    _DEFAULT_IP_SERVICES: ClassVar[list[str]] = [
        "https://api.ipify.org",
        "https://icanhazip.com",
        "https://ifconfig.me/ip",
        "https://checkip.amazonaws.com",
        "https://ipv4.icanhazip.com",
    ]

    @classmethod
    def _fetch_ip_from_service(cls, url: str, timeout: float) -> str | None:
        """Fragt einen einzelnen Dienst ab und gibt die IPv4-Adresse zurück."""
        import urllib.parse

        parsed = urllib.parse.urlparse(url)

        if parsed.scheme not in ("http", "https"):
            cls.logger.debug(
                "Überspringe nicht-http/s URL: %s",
                url,
                extra={"component": "platform"},
            )
            return None

        try:
            import requests

            response = requests.get(
                url,
                timeout=timeout,
                headers={"User-Agent": "DragonWhisperer/4.0"},
            )
            if response.status_code == 200:
                ip = response.text.strip()
                if ip and all(c.isdigit() or c == "." for c in ip):
                    return ip
            return None

        except ImportError:
            import urllib.request

            req = urllib.request.Request(
                url,
                headers={"User-Agent": "DragonWhisperer/4.0"},
            )
            with urllib.request.urlopen(req, timeout=timeout) as resp:  # nosec B310
                if resp.status == 200:
                    ip = resp.read().decode("utf-8").strip()
                    if ip and all(c.isdigit() or c == "." for c in ip):
                        return ip
            return None

        except Exception as e:
            cls.logger.debug(
                "Fehler bei %s: %s",
                url,
                e,
                extra={"component": "platform"},
            )
            return None

    @classmethod
    def get_public_ip(
        cls,
        timeout: float = 5.0,
        use_cache: bool = True,
        services: list[str] | None = None,
        max_workers: int | None = None,
    ) -> str | None:
        """Ermittelt die öffentliche IPv4-Adresse über externe Dienste (parallel)."""
        if use_cache:
            now = time.monotonic()
            if hasattr(cls, "_public_ip_cache") and hasattr(
                cls,
                "_public_ip_cache_time",
            ):
                if (
                    cls._public_ip_cache is not None
                    and (now - cls._public_ip_cache_time) < cls._PUBLIC_IP_CACHE_TTL
                ):
                    cls.logger.debug(
                        "get_public_ip: Cache-Treffer (IP=%s, age=%.1fs)",
                        cls._public_ip_cache,
                        now - cls._public_ip_cache_time,
                        extra={"component": "platform"},
                    )
                    return cls._public_ip_cache
            else:
                cls._public_ip_cache = None
                cls._public_ip_cache_time = 0.0

        services_to_try = services or cls._DEFAULT_IP_SERVICES
        if not services_to_try:
            cls.logger.warning(
                "get_public_ip: Keine Dienste zum Abfragen.",
                extra={"component": "platform"},
            )
            return None

        max_workers = max_workers or min(len(services_to_try), 4)
        cls.logger.debug(
            "get_public_ip: Starte parallele Abfrage von %d Diensten (max_workers=%d)",
            len(services_to_try),
            max_workers,
            extra={"component": "platform"},
        )

        from concurrent.futures import ThreadPoolExecutor, as_completed

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_url = {
                executor.submit(cls._fetch_ip_from_service, url, timeout): url
                for url in services_to_try
            }

            for future in as_completed(future_to_url):
                url = future_to_url[future]
                try:
                    ip = future.result(timeout=timeout + 1.0)
                    if ip:
                        cls.logger.debug(
                            "get_public_ip: Erfolg über %s (IP=%s)",
                            url,
                            ip,
                            extra={"component": "platform"},
                        )
                        if use_cache:
                            cls._public_ip_cache = ip
                            cls._public_ip_cache_time = time.monotonic()
                        return ip
                    cls.logger.debug(
                        "get_public_ip: %s lieferte keine gültige IP",
                        url,
                        extra={"component": "platform"},
                    )
                except Exception as e:
                    cls.logger.debug(
                        "get_public_ip: Fehler bei %s – %s",
                        url,
                        e,
                        extra={"component": "platform"},
                    )

        cls.logger.warning(
            "get_public_ip: Alle Dienste fehlgeschlagen.",
            extra={"component": "platform"},
        )
        return None

    @classmethod
    def safe_exec(
        cls,
        cmd: list[str] | str,
        timeout: float = 30.0,
        env: dict[str, str] | None = None,
        sanitize_env: bool = True,
        input_data: str | None = None,
        cancel_event: threading.Event | None = None,
    ) -> tuple[int, str, str]:
        """Führt einen externen Befehl sicher aus, ohne Risiko von Shell‑Injection."""
        import shlex
        import time

        if isinstance(cmd, str):
            logger.warning(
                "safe_exec: cmd als String übergeben – dies wird nicht empfohlen. "
                "Verwenden Sie stattdessen eine Liste von Argumenten.",
            )
            cmd = shlex.split(cmd)
        elif not isinstance(cmd, (list, tuple)):
            raise TypeError("cmd muss eine Liste oder ein String sein")

        if not cmd:
            raise ValueError("cmd darf nicht leer sein")

        effective_env = env if env is not None else os.environ.copy()
        if sanitize_env:
            dangerous_vars = [
                "PYTHONPATH",
                "PYTHONHOME",
                "LD_PRELOAD",
                "LD_LIBRARY_PATH",
                "PYTHONWARNINGS",
                "PYTHONHASHSEED",
            ]
            for var in dangerous_vars:
                if var in effective_env and var not in (env or {}):
                    log_debug("safe_exec", f"Entferne gefährliche Variable: {var}")
                    del effective_env[var]

        creationflags, start_new_session = cls._get_subprocess_flags()

        cmd_str = " ".join(cmd) if isinstance(cmd, list) else cmd
        log_debug("safe_exec", f"Befehl: {cmd_str}")

        start_time = time.perf_counter()
        proc = None

        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                stdin=subprocess.PIPE if input_data is not None else subprocess.DEVNULL,
                text=True,
                encoding="utf-8",
                errors="replace",
                env=effective_env,
                creationflags=creationflags,
                start_new_session=start_new_session,
                shell=False,
            )

            deadline = time.time() + timeout if timeout > 0 else float("inf")
            poll_interval = 0.2
            stdout_parts: list[str] = []
            stderr_parts: list[str] = []

            if input_data is not None and proc.stdin is not None:
                try:
                    proc.stdin.write(input_data)
                    proc.stdin.close()
                except (BrokenPipeError, OSError) as e:
                    log_debug("safe_exec", f"stdin write failed: {e}")

            while True:
                if cancel_event is not None and cancel_event.is_set():
                    log_debug("safe_exec", "Abbruch durch cancel_event")
                    if proc.poll() is None:
                        proc.terminate()
                        try:
                            proc.wait(timeout=1.0)
                        except subprocess.TimeoutExpired:
                            proc.kill()
                            proc.wait(timeout=0.5)
                    return -1, "", "Cancelled by user"

                if timeout > 0 and time.time() >= deadline:
                    log_debug("safe_exec", f"Timeout nach {timeout}s")
                    if proc.poll() is None:
                        proc.terminate()
                        try:
                            proc.wait(timeout=1.0)
                        except subprocess.TimeoutExpired:
                            proc.kill()
                            proc.wait(timeout=0.5)
                    return -1, "", f"Timeout after {timeout}s"

                if proc.poll() is not None:
                    stdout, stderr = proc.communicate(timeout=1.0)
                    if stdout:
                        stdout_parts.append(stdout)
                    if stderr:
                        stderr_parts.append(stderr)
                    break

                time.sleep(poll_interval)

            elapsed_ms = (time.perf_counter() - start_time) * 1000
            log_debug(
                "safe_exec",
                f"Beendet in {elapsed_ms:.1f} ms, Rückgabewert {proc.returncode}",
            )

            stdout_str = "".join(stdout_parts).strip()
            stderr_str = "".join(stderr_parts).strip()
            return proc.returncode, stdout_str, stderr_str

        except FileNotFoundError as e:
            log_debug("safe_exec", f"Datei nicht gefunden: {e}")
            return -1, "", f"File not found: {e}"
        except PermissionError as e:
            log_debug("safe_exec", f"Keine Ausführungsberechtigung: {e}")
            return -1, "", f"Permission denied: {e}"
        except Exception as e:
            log_debug("safe_exec", f"Unerwarteter Fehler: {e}")
            return -1, "", str(e)
        finally:
            if proc is not None and proc.poll() is None:
                try:
                    proc.kill()
                    proc.wait(timeout=0.5)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

    @classmethod
    def _get_subprocess_flags(cls) -> tuple[int, bool]:
        """Gibt plattformspezifische Flags für subprocess.Popen zurück.

        Returns:
            Tuple[int, bool]: (creationflags, start_new_session)

        """
        if IS_WINDOWS:
            return subprocess.CREATE_NO_WINDOW, False
        return 0, True

    @classmethod
    def sanitize_environment(cls, keep_vars: list[str] | None = None) -> None:
        """Entfernt potenziell gefährliche Umgebungsvariablen (z. B. PYTHONPATH, LD_PRELOAD).
        Kann vor dem Start von Subprozessen aufgerufen werden.

        Args:
            keep_vars: Liste von Variablen, die erhalten bleiben sollen.

        """
        dangerous = [
            "PYTHONPATH",
            "PYTHONHOME",
            "LD_PRELOAD",
            "LD_LIBRARY_PATH",
            "PYTHONWARNINGS",
            "PYTHONHASHSEED",
        ]
        keep = set(keep_vars or [])
        for var in dangerous:
            if var in os.environ and var not in keep:
                cls.logger.debug(f"Removing dangerous env var: {var}")
                del os.environ[var]

    @classmethod
    def is_admin(cls) -> bool:
        """Prüft, ob das Programm mit Administratorrechten (Windows) / root (Linux/macOS) läuft."""
        try:
            if IS_WINDOWS:
                import ctypes

                return ctypes.windll.shell32.IsUserAnAdmin() != 0
            return os.geteuid() == 0
        except Exception as e:
            _safe_log_debug("platform", f"is_admin() failed: {e}")
            return False

    @classmethod
    def restart_as_admin(cls, args: list[str] | None = None) -> None:
        """Startet das Programm mit Administratorrechten neu (nur Windows)."""
        import shlex

        if not IS_WINDOWS:
            logger.info("restart_as_admin: Nur unter Windows verfügbar – überspringe.")
            return

        if (
            hasattr(cls, "_admin_restart_in_progress")
            and cls._admin_restart_in_progress
        ):
            logger.warning(
                "restart_as_admin: Ein Neustart ist bereits im Gange – "
                "überspringe, um eine Schleife zu vermeiden.",
            )
            return

        script = os.path.abspath(sys.argv[0])
        params = sys.argv[1:] if args is None else args

        param_str = shlex.join(params) if params else ""

        command_line = f'"{script}" {param_str}'.strip()

        try:
            import ctypes

            ctypes.windll.shell32.ShellExecuteW(
                None,
                "runas",
                sys.executable,
                command_line,
                None,
                1,
            )
            cls._admin_restart_in_progress = True
            logger.info(
                "✅ Neustart mit Adminrechten angefordert (ShellExecuteW). "
                "Beende aktuellen Prozess in 0,5 s...",
            )
            time.sleep(0.5)
            sys.exit(0)

        except AttributeError:
            logger.error(
                "restart_as_admin: ShellExecuteW nicht verfügbar – "
                "ctypes möglicherweise fehlerhaft.",
            )
        except Exception as e:
            logger.warning(
                f"restart_as_admin: ShellExecuteW fehlgeschlagen: {e}. "
                "Versuche PowerShell‑Fallback...",
            )

        try:
            import tempfile

            ps_script_content = f"""
            Start-Process -FilePath '{sys.executable}' `
                -ArgumentList '{command_line}' `
                -Verb RunAs -WindowStyle Normal
            """
            with tempfile.NamedTemporaryFile(
                mode="w",
                suffix=".ps1",
                delete=False,
                encoding="utf-8",
            ) as f:
                f.write(ps_script_content)
                ps_script_path = f.name
            subprocess.run(
                ["powershell", "-ExecutionPolicy", "Bypass", "-File", ps_script_path],
                check=False,
                capture_output=True,
                timeout=10,
            )
            time.sleep(0.3)
            try:
                os.unlink(ps_script_path)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            cls._admin_restart_in_progress = True
            logger.info(
                "✅ Neustart mit Adminrechten angefordert (PowerShell). "
                "Beende aktuellen Prozess in 0,5 s...",
            )
            time.sleep(0.5)
            sys.exit(0)

        except Exception as e:
            logger.error(
                f"restart_as_admin: Auch PowerShell‑Fallback fehlgeschlagen: {e}",
            )
            try:
                import ctypes

                ctypes.windll.user32.MessageBoxW(
                    0,
                    f"Neustart mit Administratorrechten fehlgeschlagen:\n{e}\n\n"
                    "Bitte starten Sie das Programm manuell als Administrator.",
                    "Neustart fehlgeschlagen",
                    0x10,
                )
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    @classmethod
    def get_desktop_environment(cls) -> str:
        """Ermittelt die aktuelle Desktop‑Umgebung (Linux, macOS, Windows).

        Returns:
            String mit dem Namen der Desktop-Umgebung (klein geschrieben) oder
            "unknown" (Linux), "macos", "windows".

        """
        if IS_WINDOWS:
            return "windows"
        if IS_MACOS:
            return "macos"
        if not IS_LINUX:
            return "unknown"
        de = os.environ.get("XDG_CURRENT_DESKTOP", "")
        if de:
            first = de.split(":", 1)[0].strip().lower()
            if first:
                return first
        de = os.environ.get("DESKTOP_SESSION", "")
        if de:
            return os.path.basename(de).lower()
        if "GNOME_DESKTOP_SESSION_ID" in os.environ:
            return "gnome"
        if "KDE_FULL_SESSION" in os.environ:
            return "kde"
        if "XFCE_VERSION" in os.environ:
            return "xfce"
        if "LXQT_SESSION_CONFIG" in os.environ:
            return "lxqt"
        if "LXDE_SESSION" in os.environ:
            return "lxde"
        if "MATE_DESKTOP_SESSION_ID" in os.environ:
            return "mate"
        if "CINNAMON_VERSION" in os.environ:
            return "cinnamon"
        if "BUDGIE_DESKTOP" in os.environ:
            return "budgie"
        if "SWAYSOCK" in os.environ:
            return "sway"
        if "HYPRLAND_INSTANCE_SIGNATURE" in os.environ:
            return "hyprland"
        if "I3SOCK" in os.environ or "I3_CONFIG_FILE" in os.environ:
            return "i3"
        session_type = os.environ.get("XDG_SESSION_TYPE", "").lower()
        if session_type in ("x11", "wayland"):
            return session_type
        return "unknown"

    @classmethod
    def get_cpu_model(cls) -> str:
        """Ermittelt das CPU‑Modell (ohne psutil, nur Standardbibliothek)."""
        if IS_WINDOWS:
            try:
                import winreg

                key = winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"HARDWARE\DESCRIPTION\System\CentralProcessor\0",
                )
                name, _ = winreg.QueryValueEx(key, "ProcessorNameString")
                return name.strip()
            except Exception as e:
                log_debug(
                    "platform",
                    f"Windows Registry CPU-Abfrage fehlgeschlagen: {e}",
                )

                try:
                    import platform

                    return platform.processor() or "unknown"
                except Exception:
                    return "unknown"

        if IS_MACOS:
            try:
                result = subprocess.run(
                    ["sysctl", "-n", "machdep.cpu.brand_string"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                    check=False,
                )
                if result.returncode == 0 and result.stdout.strip():
                    return result.stdout.strip()
            except Exception as e:
                log_debug("platform", f"macOS sysctl CPU-Abfrage fehlgeschlagen: {e}")

            return "Apple" if IS_ARM else "Intel Mac"

        try:
            with open("/proc/cpuinfo") as f:
                for line in f:
                    if "model name" in line:
                        return line.split(":", 1)[1].strip()
        except Exception as e:
            log_debug("platform", f"/proc/cpuinfo Abfrage fehlgeschlagen: {e}")

        try:
            import json

            result = subprocess.run(
                ["lscpu", "-J"],
                capture_output=True,
                text=True,
                timeout=2,
                check=False,
            )
            if result.returncode == 0:
                data = json.loads(result.stdout)
                for item in data.get("lscpu", []):
                    if item.get("field", "") == "Model name":
                        return item.get("data", "unknown")
        except Exception as e:
            log_debug("platform", f"lscpu -J Abfrage fehlgeschlagen: {e}")

        try:
            import platform

            return platform.processor() or "unknown"
        except Exception:
            return "unknown"

    @classmethod
    def get_total_ram_gb(cls) -> float:
        """Ermittelt den gesamten Arbeitsspeicher in Gigabyte (ohne psutil)."""
        try:
            if IS_WINDOWS:
                import ctypes

                kernel32 = ctypes.windll.kernel32

                class MEMORYSTATUSEX(ctypes.Structure):
                    _fields_ = [
                        ("dwLength", ctypes.c_ulong),
                        ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong),
                        ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong),
                        ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong),
                        ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                    ]

                mem = MEMORYSTATUSEX()
                mem.dwLength = ctypes.sizeof(mem)
                if kernel32.GlobalMemoryStatusEx(ctypes.byref(mem)):
                    return mem.ullTotalPhys / (1024**3)
            elif IS_MACOS:
                result = subprocess.run(
                    ["sysctl", "-n", "hw.memsize"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                    check=False,
                )
                if result.returncode == 0:
                    return int(result.stdout.strip()) / (1024**3)
            else:
                with open("/proc/meminfo") as f:
                    for line in f:
                        if "MemTotal" in line:
                            kb = int(line.split()[1])
                            return kb / (1024 * 1024)
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        return 0.0

    @classmethod
    def get_free_disk_gb(cls, path: str = "/") -> float:
        """Ermittelt den freien Speicherplatz auf einem Laufwerk in GB."""
        try:
            usage = shutil.disk_usage(path)
            return usage.free / (1024**3)
        except Exception:
            return 0.0

    @classmethod
    def get_username(cls) -> str:
        """Gibt den aktuellen Benutzernamen zurück."""
        try:
            return os.getlogin()
        except Exception:
            return os.environ.get("USER", os.environ.get("USERNAME", "unknown"))

    @classmethod
    def get_hostname(cls) -> str:
        """Gibt den Hostnamen des Systems zurück."""
        try:
            return socket.gethostname()
        except Exception:
            return "unknown"

    @classmethod
    def get_timezone(cls) -> str:
        """Ermittelt die aktuelle Zeitzone (als IANA‑Name oder UTC±Offset)."""
        try:
            import time

            offset = time.altzone if time.daylight else time.timezone
            return f"UTC{offset // 3600:+d}"
        except Exception:
            return "unknown"

    @classmethod
    def open_url(cls, url: str) -> bool:
        """Öffnet eine URL im Standardbrowser."""
        try:
            import webbrowser

            webbrowser.open(url)
            return True
        except Exception as e:
            cls.logger.warning(f"Failed to open URL {url}: {e}")
            return False

    @classmethod
    def show_notification(
        cls,
        title: str,
        message: str,
        timeout: int = 5,
        parent: tk.Tk | None = None,
    ) -> bool:
        """Zeigt eine Desktop‑Benachrichtigung an (falls möglich)."""
        if not title or not message:
            log_debug("notify", "show_notification: title oder message leer")
            return False

        if IS_WINDOWS:
            try:
                from win10toast import ToastNotifier

                toaster = ToastNotifier()

                toaster.show_toast(
                    title,
                    message,
                    duration=timeout,
                    threaded=True,
                )
                log_debug("notify", "Windows‑Benachrichtigung gesendet")
                return True
            except ImportError:
                log_debug("notify", "win10toast nicht installiert")
            except Exception as e:
                log_debug("notify", f"win10toast Fehler: {e}")

        elif IS_MACOS:
            try:
                from Foundation import NSUserNotification, NSUserNotificationCenter

                notification = NSUserNotification.alloc().init()
                notification.setTitle_(title)
                notification.setInformativeText_(message)

                notification.setDeliveryDate_(None)

                NSUserNotificationCenter.defaultUserNotificationCenter().scheduleNotification_(
                    notification,
                )
                log_debug("notify", "macOS‑Benachrichtigung gesendet")
                return True
            except ImportError:
                log_debug("notify", "pyobjc (Foundation) nicht installiert")
            except Exception as e:
                log_debug("notify", f"macOS‑Benachrichtigungsfehler: {e}")

        elif shutil.which("notify-send") is None:
            log_debug("notify", "notify-send nicht im PATH")
        else:
            try:
                timeout_ms = int(timeout * 1000)

                subprocess.run(
                    [
                        "notify-send",
                        "-t",
                        str(timeout_ms),
                        title,
                        message,
                    ],
                    check=False,
                    capture_output=True,
                    timeout=timeout + 2,
                )
                log_debug("notify", "Linux‑Benachrichtigung gesendet")
                return True
            except Exception as e:
                log_debug("notify", f"notify-send Fehler: {e}")

        if DEBUG_LEVEL >= 1 or "notify" in DEBUG_COMPONENTS:
            log_debug(
                "notify",
                f"Desktop‑Benachrichtigung nicht möglich – "
                f"Konsole: [{title}] {message}",
            )

        return False

    @classmethod
    def get_installed_fonts(cls) -> list[str]:
        """Gibt eine Liste der systemweit installierten Schriftarten zurück (Caching empfohlen)."""
        fonts = set()

        try:
            if IS_WINDOWS:
                import winreg

                key = winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts",
                )
                i = 0
                while True:
                    try:
                        name, _, _ = winreg.EnumValue(key, i)
                        if name.lower().endswith((".ttf", ".otf")):
                            family = name.rsplit("(", 1)[0].strip()
                            if family:
                                fonts.add(family)
                        i += 1
                    except OSError:
                        break

            elif IS_MACOS:
                font_dirs = [
                    Path("/System/Library/Fonts/"),
                    Path("/Library/Fonts/"),
                    Path.home() / "Library/Fonts/",
                ]
                for font_dir in font_dirs:
                    if font_dir.exists():
                        fonts.update(f.stem for f in font_dir.glob("*.ttf"))
                        fonts.update(f.stem for f in font_dir.glob("*.otf"))

            elif shutil.which("fc-list"):
                result = subprocess.run(
                    ["fc-list", ":", "family"],
                    capture_output=True,
                    text=True,
                    timeout=5,
                    check=False,
                )
                if result.returncode == 0:
                    for line in result.stdout.splitlines():
                        line = line.strip()
                        if not line:
                            continue

                        families = [f.strip() for f in line.split(",")]
                        for family in families:
                            if family:
                                fonts.add(family)
                else:
                    cls._scan_font_dirs(fonts)
            else:
                cls._scan_font_dirs(fonts)

        except Exception as e:
            cls.logger.debug(f"Font detection failed: {e}")

        return sorted(fonts)

    @classmethod
    def _scan_font_dirs(cls, fonts: set[str]) -> None:
        """Durchsucht typische Font-Verzeichnisse und fügt Dateinamen (ohne Erweiterung) hinzu."""
        font_dirs = [
            Path("/usr/share/fonts"),
            Path("/usr/local/share/fonts"),
            Path.home() / ".fonts",
            Path.home() / ".local/share/fonts",
        ]
        for font_dir in font_dirs:
            if font_dir.exists():
                for ext in ("*.ttf", "*.otf", "*.ttc"):
                    for f in font_dir.rglob(ext):
                        fonts.add(f.stem)

    @classmethod
    def is_internet_available(
        cls,
        test_url: str = "https://1.1.1.1",
        timeout: float = 3.0,
        use_cache: bool = True,
        cache_ttl: float = 10.0,
    ) -> bool:
        """Prüft, ob eine Internetverbindung besteht, indem eine HTTP‑Anfrage an einen
        zuverlässigen Server gesendet wird.
        """
        import urllib.error
        import urllib.parse
        import urllib.request

        parsed = urllib.parse.urlparse(test_url)
        if parsed.scheme not in ("http", "https"):
            cls.logger.warning(
                "is_internet_available: Nicht-HTTP/HTTPS-URL abgelehnt: %s",
                test_url,
                extra={"component": "platform"},
            )
            return False

        if use_cache:
            now = time.monotonic()
            if hasattr(cls, "_internet_cache") and hasattr(cls, "_internet_cache_time"):
                if (now - cls._internet_cache_time) < cache_ttl:
                    cls.logger.debug(
                        "is_internet_available: Cache‑Treffer (available=%s, age=%.1fs)",
                        cls._internet_cache,
                        now - cls._internet_cache_time,
                        extra={"component": "platform"},
                    )
                    return cls._internet_cache
            else:
                cls._internet_cache = None
                cls._internet_cache_time = 0.0

        try:
            import requests

            _requests_available = True
        except ImportError:
            _requests_available = False
            cls.logger.debug(
                "is_internet_available: requests nicht installiert – verwende urllib",
                extra={"component": "platform"},
            )

        available = False
        try:
            if _requests_available:
                response = requests.get(test_url, timeout=timeout)
                available = response.status_code == 200
                if available:
                    cls.logger.debug(
                        "is_internet_available: erfolgreich über requests (HTTP %d)",
                        response.status_code,
                        extra={"component": "platform"},
                    )
                else:
                    cls.logger.debug(
                        "is_internet_available: requests lieferte HTTP %d",
                        response.status_code,
                        extra={"component": "platform"},
                    )
            else:
                import urllib.request

                req = urllib.request.Request(
                    test_url,
                    headers={"User-Agent": "DragonWhisperer/4.0"},
                )
                with urllib.request.urlopen(req, timeout=timeout) as resp:  # nosec B310
                    available = resp.status == 200
                    cls.logger.debug(
                        "is_internet_available (urllib): HTTP %d",
                        resp.status,
                        extra={"component": "platform"},
                    )
        except (urllib.error.URLError, urllib.error.HTTPError) as e:
            cls.logger.debug(
                "is_internet_available: urllib‑Fehler – %s",
                str(e),
                extra={"component": "platform"},
            )
        except Exception as e:
            cls.logger.debug(
                "is_internet_available: unerwarteter Fehler – %s",
                str(e),
                extra={"component": "platform"},
            )

        if use_cache:
            cls._internet_cache = available
            cls._internet_cache_time = time.monotonic()

        return available

    @classmethod
    def save_password(cls, service: str, username: str, password: str) -> bool:
        """Speichert ein Passwort sicher im systeminternen Schlüsselbund (erfordert 'keyring')."""
        try:
            import keyring

            keyring.set_password(service, username, password)
            return True
        except ImportError:
            cls.logger.debug("keyring not installed – password not saved")
            return False
        except Exception as e:
            cls.logger.warning(f"Failed to save password: {e}")
            return False

    @classmethod
    def get_password(cls, service: str, username: str) -> str | None:
        """Ruft ein Passwort aus dem Schlüsselbund ab."""
        try:
            import keyring

            return keyring.get_password(service, username)
        except ImportError:
            cls.logger.debug("keyring not installed – cannot retrieve password")
            return None
        except Exception as e:
            cls.logger.warning(f"Failed to get password: {e}")
            return None

    @classmethod
    def delete_password(cls, service: str, username: str) -> bool:
        """Löscht ein Passwort aus dem Schlüsselbund."""
        try:
            import keyring

            keyring.delete_password(service, username)
            return True
        except ImportError:
            cls.logger.debug("keyring not installed – password not deleted")
            return False
        except Exception as e:
            cls.logger.warning(f"Failed to delete password: {e}")
            return False

    @classmethod
    def create_shortcut(
        cls,
        target: Path,
        link_path: Path,
        description: str = "",
        arguments: str = "",
        working_dir: Path | None = None,
        icon_path: Path | None = None,
        use_terminal: bool = False,
        overwrite: bool = True,
        as_url: bool = False,
    ) -> tuple[bool, str]:
        """Erstellt eine plattformspezifische Verknüpfung.

        Returns:
            tuple[bool, str]: (Erfolg, Pfad der erstellten Verknüpfung oder Fehlermeldung)

        """
        log_debug(
            "platform",
            f"create_shortcut: target={target}, link_path={link_path}",
        )

        if not target.exists():
            msg = f"Ziel existiert nicht: {target}"
            cls.logger.warning(msg, extra={"component": "platform"})
            return False, msg

        try:
            link_path.parent.mkdir(parents=True, exist_ok=True)
            log_debug("platform", f"Verzeichnis erstellt/gesichert: {link_path.parent}")
        except OSError as e:
            msg = f"Verzeichnis für Verknüpfung konnte nicht erstellt werden: {e}"
            cls.logger.error(msg, extra={"component": "platform"})
            return False, msg

        if link_path.exists() and not overwrite:
            msg = f"Verknüpfung existiert bereits: {link_path} (überschreiben deaktiviert)"
            cls.logger.warning(msg, extra={"component": "platform"})
            return False, msg
        if link_path.exists() and overwrite:
            try:
                if not IS_WINDOWS:
                    link_path.unlink()
                    log_debug("platform", f"Alte Verknüpfung gelöscht: {link_path}")
            except OSError as e:
                msg = f"Alte Verknüpfung konnte nicht gelöscht werden: {e}"
                cls.logger.error(msg, extra={"component": "platform"})
                return False, msg

        try:
            if IS_WINDOWS:
                return cls._create_windows_shortcut(
                    target,
                    link_path,
                    description,
                    arguments,
                    working_dir,
                    icon_path,
                    use_terminal,
                    overwrite,
                )
            if IS_MACOS:
                if as_url and str(target).startswith(("http://", "https://")):
                    return cls._create_macos_webloc(target, link_path)
                return cls._create_macos_command_shortcut(
                    target,
                    link_path,
                    description,
                    arguments,
                    working_dir,
                    icon_path,
                    use_terminal,
                )
            return cls._create_linux_desktop_shortcut(
                target,
                link_path,
                description,
                arguments,
                working_dir,
                icon_path,
                use_terminal,
            )
        except Exception as e:
            msg = f"Unerwarteter Fehler beim Erstellen der Verknüpfung: {e}"
            cls.logger.error(msg, exc_info=True, extra={"component": "platform"})
            return False, msg

    @classmethod
    def _create_windows_shortcut(
        cls,
        target: Path,
        link_path: Path,
        description: str,
        arguments: str,
        working_dir: Path | None,
        icon_path: Path | None,
        use_terminal: bool,
        overwrite: bool,
    ) -> tuple[bool, str]:
        """Erstellt eine Windows .lnk-Verknüpfung (zuerst win32com, dann ctypes)."""
        try:
            from win32com.client import Dispatch

            shell = Dispatch("WScript.Shell")
            shortcut = shell.CreateShortCut(str(link_path))

            shortcut.Targetpath = str(target)
            if arguments:
                shortcut.Arguments = arguments
            if working_dir:
                shortcut.WorkingDirectory = str(working_dir)
            if icon_path and icon_path.exists():
                shortcut.IconLocation = str(icon_path)
            if description:
                shortcut.Description = description

            shortcut.save()
            log_debug(
                "platform",
                f"Windows-Verknüpfung erstellt (win32com): {link_path}",
            )
            return True, str(link_path)

        except ImportError:
            log_debug("platform", "win32com nicht verfügbar, versuche ctypes...")
            return cls._create_windows_shortcut_ctypes(
                target,
                link_path,
                description,
                arguments,
                working_dir,
                icon_path,
            )

    @classmethod
    def _create_windows_shortcut_ctypes(
        cls,
        target: Path,
        link_path: Path,
        description: str,
        arguments: str,
        working_dir: Path | None,
        icon_path: Path | None,
    ) -> tuple[bool, str]:
        """Erstellt eine Windows .lnk-Verknüpfung mit ctypes (IShellLink).
        Vereinfachte Implementierung – für Produktion sollte man die vollständige
        COM-Initialisierung durchführen. Diese Methode dient als Notfall‑Fallback.
        """
        try:
            raise NotImplementedError(
                "ctypes-Implementierung für Windows-Verknüpfungen ist nicht vollständig implementiert. "
                "Bitte installieren Sie pywin32: pip install pywin32",
            )
        except Exception as e:
            msg = f"Windows-Verknüpfung mit ctypes fehlgeschlagen: {e}"
            cls.logger.error(msg, extra={"component": "platform"})
            return False, msg

    @classmethod
    def _create_linux_desktop_shortcut(
        cls,
        target: Path,
        link_path: Path,
        description: str,
        arguments: str,
        working_dir: Path | None,
        icon_path: Path | None,
        use_terminal: bool,
    ) -> tuple[bool, str]:
        """Erstellt eine Linux .desktop-Datei."""
        import shlex

        quoted_target = shlex.quote(str(target))
        quoted_args = shlex.quote(arguments) if arguments else ""
        exec_line = f"{quoted_target} {quoted_args}".strip()

        work_dir = str(working_dir) if working_dir else str(target.parent)
        icon_line = str(icon_path) if icon_path and icon_path.exists() else ""
        name = description or target.stem
        terminal_setting = "true" if use_terminal else "false"

        desktop_entry = f"""[Desktop Entry]
Version=1.0
Type=Application
Name={name}
Comment={description}
Exec={exec_line}
Path={work_dir}
Icon={icon_line}
Terminal={terminal_setting}
StartupNotify=true
Categories=Utility;
"""

        try:
            with open(link_path, "w", encoding="utf-8") as f:
                f.write(desktop_entry)
            os.chmod(link_path, 0o755)  # nosec B103
            log_debug("platform", f"Linux .desktop-Datei erstellt: {link_path}")
            return True, str(link_path)
        except OSError as e:
            msg = f"Fehler beim Schreiben der .desktop-Datei: {e}"
            cls.logger.error(msg, extra={"component": "platform"})
            return False, msg

    @classmethod
    def _create_macos_command_shortcut(
        cls,
        target: Path,
        link_path: Path,
        description: str,
        arguments: str,
        working_dir: Path | None,
        icon_path: Path | None,
        use_terminal: bool,
    ) -> tuple[bool, str]:
        """Erstellt ein macOS .command-Skript als Fallback."""
        import shlex

        work_dir = str(working_dir) if working_dir else str(target.parent)

        script_content = f"""#!/bin/bash
cd "{work_dir}"
"{target!s}" {shlex.quote(arguments) if arguments else ""}
"""
        script_path = link_path.with_suffix(".command")
        try:
            with open(script_path, "w", encoding="utf-8") as f:
                f.write(script_content)
            os.chmod(script_path, 0o755)  # nosec B103
            log_debug("platform", f"macOS .command-Skript erstellt: {script_path}")
            return True, str(script_path)
        except OSError as e:
            msg = f"Fehler beim Erstellen des .command-Skripts: {e}"
            cls.logger.error(msg, extra={"component": "platform"})
            return False, msg

    @classmethod
    def _create_macos_webloc(cls, target: Path, link_path: Path) -> tuple[bool, str]:
        """Erstellt eine macOS .webloc-Datei für URLs."""
        webloc_content = f"""<?xml version="1.0" encoding="UTF-8"?>
    <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
    <plist version="1.0">
    <dict>
        <key>URL</key>
        <string>{target!s}</string>
    </dict>
    </plist>"""
        try:
            webloc_path = link_path.with_suffix(".webloc")
            with open(webloc_path, "w", encoding="utf-8") as f:
                f.write(webloc_content)
            log_debug("platform", f"macOS .webloc erstellt: {webloc_path}")
            return True, str(webloc_path)
        except OSError as e:
            msg = f"Fehler beim Erstellen der .webloc-Datei: {e}"
            cls.logger.error(msg, extra={"component": "platform"})
            return False, msg

    @classmethod
    def get_process_list(cls, include_cmdline: bool = True) -> list[dict[str, Any]]:
        """Gibt eine Liste aller laufenden Prozesse zurück (PID, Name, evtl. CommandLine).
        Ohne psutil wird eine einfachere Liste zurückgegeben.

        """
        processes: list[dict[str, Any]] = []

        try:
            import psutil

            attrs = ["pid", "name"]
            if include_cmdline:
                attrs.append("cmdline")

            for proc in psutil.process_iter(attrs):
                try:
                    info = proc.info
                    entry: dict[str, Any] = {
                        "pid": info["pid"],
                        "name": info["name"],
                    }
                    if include_cmdline:
                        cmdline = info.get("cmdline")
                        entry["cmdline"] = " ".join(cmdline) if cmdline else ""
                    processes.append(entry)
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    continue
            return processes

        except ImportError:
            logger.debug("psutil not available, using fallback process listing")

        if IS_WINDOWS:
            try:
                result = subprocess.run(
                    ["tasklist", "/FO", "CSV", "/NH"],
                    capture_output=True,
                    text=True,
                    timeout=10,
                    check=False,
                )
                if result.returncode == 0 and result.stdout:
                    for line in result.stdout.strip().splitlines():
                        if not line:
                            continue
                        parts = line.strip('"').split('","')
                        if len(parts) >= 2:
                            try:
                                pid = int(parts[1])
                            except ValueError:
                                continue
                            processes.append(
                                {
                                    "pid": pid,
                                    "name": parts[0],
                                    "cmdline": "",
                                },
                            )
            except subprocess.TimeoutExpired:
                logger.warning("tasklist timed out")
            except Exception as e:
                logger.debug(f"tasklist fallback error: {e}")

            return processes

        try:
            proc_path = Path("/proc")
            if proc_path.exists() and proc_path.is_dir():
                for proc_dir in proc_path.iterdir():
                    if proc_dir.is_dir() and proc_dir.name.isdigit():
                        try:
                            pid = int(proc_dir.name)

                            comm_file = proc_dir / "comm"
                            if comm_file.exists():
                                with open(comm_file) as f:
                                    name = f.read().strip()
                            else:
                                name = "unknown"
                            processes.append({"pid": pid, "name": name, "cmdline": ""})
                        except (ValueError, OSError, PermissionError):
                            continue
                if processes:
                    return processes
        except Exception as e:
            logger.debug(f"/proc fallback error: {e}")

        try:
            if include_cmdline:
                cmd = ["ps", "-eo", "pid,comm,args", "--no-headers"]
            else:
                cmd = ["ps", "-eo", "pid,comm", "--no-headers"]

            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                for line in result.stdout.strip().splitlines():
                    parts = line.strip().split(None, 2 if include_cmdline else 1)
                    if not parts:
                        continue
                    try:
                        pid = int(parts[0])
                        name = parts[1] if len(parts) > 1 else "unknown"
                        cmdline = parts[2] if len(parts) > 2 else ""
                        processes.append(
                            {
                                "pid": pid,
                                "name": name,
                                "cmdline": cmdline if include_cmdline else "",
                            },
                        )
                    except (ValueError, IndexError):
                        continue
        except subprocess.TimeoutExpired:
            logger.warning("ps command timed out")
        except Exception as e:
            logger.debug(f"ps fallback error: {e}")

        return processes

    @classmethod
    def find_process_by_name(cls, name: str) -> int | None:
        """Findet die erste PID eines Prozesses mit dem gegebenen Namen."""
        for proc in cls.get_process_list():
            if proc.get("name", "").lower() == name.lower():
                return proc.get("pid")
        return None

    @classmethod
    def kill_process(cls, pid: int, force: bool = True) -> bool:
        """Beendet einen einzelnen Prozess (ohne Kindprozesse)."""
        try:
            import psutil

            proc = psutil.Process(pid)
            if force:
                proc.kill()
            else:
                proc.terminate()
            proc.wait(timeout=2.0)
            return True
        except ImportError:
            try:
                if force:
                    os.kill(pid, py_signal.SIGKILL)
                else:
                    os.kill(pid, py_signal.SIGTERM)
                time.sleep(0.2)
                os.kill(pid, 0)
                return False
            except ProcessLookupError:
                return True
            except Exception:
                return False
        except Exception:
            return False

    @classmethod
    def get_piper_cache_dir(cls) -> str:
        """Plattformübergreifendes Piper‑Cache‑Verzeichnis."""
        if IS_WINDOWS:
            base = os.environ.get("APPDATA", os.path.expanduser("~\\AppData\\Roaming"))
            return os.path.join(base, "piper")
        base = os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache"))
        return os.path.join(base, "piper")


