@dataclass
class CacheEntry:
    """Cache-Eintrag mit Metadaten für ultimative Kontrolle."""

    value: Any
    timestamp: float = field(default_factory=time.time)
    ttl: float | None = None
    access_count: int = 0
    last_access: float = field(default_factory=time.time)
    created_at: float = field(default_factory=time.time)

    def is_expired(self, default_ttl: float = 300.0) -> bool:
        """Prüft, ob der Eintrag abgelaufen ist."""
        ttl = self.ttl if self.ttl is not None else default_ttl
        return time.time() - self.timestamp > ttl

    def touch(self) -> None:
        """Aktualisiert den Zugriffszeitpunkt."""
        self.access_count += 1
        self.last_access = time.time()

    def get_age(self) -> float:
        """Gibt das Alter des Eintrags in Sekunden zurück."""
        return time.time() - self.timestamp

    def to_dict(self) -> dict[str, Any]:
        """Konvertiert den Eintrag in ein Dictionary."""
        return {
            "value": self.value,
            "timestamp": self.timestamp,
            "ttl": self.ttl,
            "access_count": self.access_count,
            "last_access": self.last_access,
            "created_at": self.created_at,
        }


@dataclass
class ExtractionResult:
    """Ergebnis einer Extraktion mit Metadaten."""

    url: str | None = None
    method: str = ""
    success: bool = False
    duration: float = 0.0
    attempts: int = 0
    error: str | None = None
    error_code: ErrorCode | None = None
    cache_hit: bool = False
    fail_cache_hit: bool = False
    platform: str = "unknown"
    is_live: bool = False
    yt_dlp_version: str | None = None
    strategies_tried: list[str] = field(default_factory=list)
    browser_used: str | None = None
    cookies_used: bool = False
    timestamp: float = field(default_factory=time.time)
    retries: int = 0


@dataclass
class CookieInfo:
    """Informationen über Cookies eines Browsers."""

    browser: str
    status: BrowserStatus
    cookie_count: int = 0
    cookie_string: str | None = None
    cookie_file: str | None = None
    error: str | None = None
    error_code: ErrorCode | None = None
    timestamp: float = field(default_factory=time.time)
    valid: bool = False
    live_test_passed: bool = False
    expires_at: float | None = None


