    def _run_ytdlp_json(
        self,
        url: str,
        format_str: str | None = None,
    ) -> StreamInfo | None:
        """Führt einen yt-dlp --dump-json Aufruf durch und parst das Ergebnis."""
        import asyncio
        import json

        try:
            asyncio.get_running_loop()
            logger.warning(
                "_run_ytdlp_json läuft in einer Event‑Loop – "
                "dies kann zu Blockierungen führen! (URL: {url[:60]}...)",
            )
        except RuntimeError:
            pass

        if not url:
            if self._debug:
                logger.debug("_run_ytdlp_json: Leere URL – Abbruch")
            return None

        fail_entry = self._get_fail_cache(url)
        if fail_entry is not None:
            fail_type = fail_entry[1] if len(fail_entry) > 1 else "unknown"
            if self._debug:
                log_debug(
                    "streaminfo",
                    f"⛔ Negativ-Cache-Treffer für {url[:60]}... ({fail_type})",
                )
            return None

        if self._debug:
            log_debug("streaminfo", f"🔍 Extrahiere JSON für: {url[:60]}...")

        raw_output = self._run_json_command(
            url=url,
            use_cookies=self.use_browser_cookies,
            browser=self.cookies_browser,
            timeout=self.json_timeout,
            extra_debug=(self._debug or DEBUG_LEVEL >= 3),
            flat_playlist=False,
            info_callback=None,
        )

        if not raw_output:
            if self._debug:
                logger.debug("⚠️ yt-dlp JSON gab keine Daten zurück für %s", url[:60])
            return None

        try:
            data = json.loads(raw_output)
        except json.JSONDecodeError as e:
            if self._debug:
                logger.debug("⚠️ JSON-Parsing fehlgeschlagen für %s: %s", url[:60], e)
            return None

        if not data:
            if self._debug:
                logger.debug("⚠️ JSON-Daten leer für %s", url[:60])
            return None

        stream_info = self._build_stream_info_from_json(data)

        if stream_info is not None:
            self._cache_fail(url, None)

        return stream_info

    def _build_stream_info_from_json(self, data: dict[str, Any]) -> StreamInfo:
        """Erstellt ein StreamInfo-Objekt aus den JSON-Metadaten."""
        title = data.get("title", "Unknown Stream")
        uploader = data.get(
            "uploader",
            data.get("channel", data.get("creator", "Unknown")),
        )
        duration = data.get("duration_string", "")
        if not duration and data.get("duration"):
            secs = data["duration"]
            hours = int(secs // 3600)
            minutes = int((secs % 3600) // 60)
            secs = int(secs % 60)
            if hours:
                duration = f"{hours}:{minutes:02d}:{secs:02d}"
            else:
                duration = f"{minutes}:{secs:02d}"
        view_count = data.get("view_count", 0)
        platform = data.get("extractor", "unknown")
        description = data.get("description", "")
        if len(description) > 500:
            description = description[:497] + "..."
        is_live = data.get("is_live", False)
        thumbnail = data.get("thumbnail", "")
        webpage_url = data.get("webpage_url", data.get("original_url", ""))
        channel_id = data.get("channel_id", data.get("uploader_id"))
        uploader_url = data.get("channel_url", data.get("uploader_url"))
        stream_url = data.get("url", data.get("manifest_url"))

        return StreamInfo(
            title=title,
            uploader=uploader,
            duration=duration,
            view_count=view_count,
            platform=platform,
            description=description,
            duration_seconds=data.get("duration"),
            is_live=is_live,
            thumbnail=thumbnail,
            original_url=webpage_url,
            stream_url=stream_url,
            channel_id=channel_id,
            uploader_url=uploader_url,
        )

    @staticmethod
    def _run_subprocess_with_timeout(
        cmd: list[str],
        timeout_sec: int,
        cancel_event: threading.Event | None,
    ) -> tuple[str | None, str, int, float]:
        """Führt einen Subprozess mit Timeout und Abbruchunterstützung aus.
        Gibt (stdout, stderr, returncode, duration) zurück.
        """
        proc = None
        start_time = time.monotonic()
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                shell=False,
                start_new_session=True,
            )
            deadline = time.time() + timeout_sec
            poll_interval = 0.2
            while time.time() < deadline:
                if cancel_event and cancel_event.is_set():
                    proc.terminate()
                    proc.wait(timeout=0.5)
                    raise RuntimeError("Cancelled by user")
                try:
                    proc.wait(timeout=poll_interval)
                    break
                except subprocess.TimeoutExpired:
                    continue
            else:
                PlatformUtils.terminate_process(
                    proc,
                    child_terminate_timeout=1.0,
                    child_kill_wait=0.5,
                    parent_terminate_timeout=1.0,
                    parent_kill_wait=0.5,
                    fallback_terminate_timeout=1.0,
                    fallback_kill_wait=0.5,
                )
                raise subprocess.TimeoutExpired(" ".join(cmd), timeout_sec)

            stdout, stderr = proc.communicate(timeout=0.5)
            duration = time.monotonic() - start_time
            return (
                stdout.strip() if stdout else None,
                stderr.strip() if stderr else "",
                proc.returncode,
                duration,
            )

        except subprocess.TimeoutExpired:
            return None, f"Timeout after {timeout_sec}s", -1, timeout_sec
        except RuntimeError as e:
            if "Cancelled by user" in str(e):
                return None, "Cancelled", -3, time.monotonic() - start_time
            return None, str(e), -2, time.monotonic() - start_time
        except Exception as e:
            return None, str(e), -2, time.monotonic() - start_time
        finally:
            if proc is not None and proc.poll() is None:
                try:
                    proc.kill()
                    proc.wait(timeout=0.5)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

    @classmethod
    def _is_permanent_error(cls, stderr: str) -> bool:
        """Entscheidet, ob ein Fehler permanent ist (keine Wiederholung sinnvoll)."""
        if not stderr:
            return False
        error_lower = stderr.lower()
        if "shorts" in error_lower:
            return False

        temporary_patterns = (
            "429",
            "rate limit",
            "timeout",
            "connection",
            "reset",
            "requested format is not available",
            "unable to download",
            "temporary failure",
            "retry",
            "try again",
        )
        if any(p in error_lower for p in temporary_patterns):
            return False

        permanent_patterns = (
            "403",
            "404",
            "410",
            "not found",
            "unavailable",
            "private video",
            "sign in to confirm your age",
            "video is private",
            "video has been removed",
            "content is not available",
            "uploader has not made this video available",
            "this video is not available",
            "geo-restricted",
            "blocked in your country",
            "the uploader has not made this video available in your country",
            "no video formats found",
            "requested format not found",
            "unable to extract",
            "failed to parse",
            "malformed",
            "invalid",
            "not supported",
            "premium",
            "members only",
            "only images are available",
        )
        return any(p in error_lower for p in permanent_patterns)

    @classmethod
    def _get_available_browsers(cls) -> list[str]:
        """Ermittelt die auf dem System installierten Browser und gibt sie als Liste
        von Namen zurück (z. B. ['firefox', 'chrome', 'chromium', ...]).
        Die Reihenfolge ist nach Wahrscheinlichkeit der Verfügbarkeit sortiert.
        """
        import os
        import shutil
        import sys

        available = []
        system = sys.platform

        if system.startswith("win"):
            candidates = [
                ("edge", "msedge.exe"),
                ("chrome", "chrome.exe"),
                ("firefox", "firefox.exe"),
                ("brave", "brave.exe"),
                ("chromium", "chromium.exe"),
                ("opera", "opera.exe"),
                ("vivaldi", "vivaldi.exe"),
            ]
            for name, exe in candidates:
                if shutil.which(exe):
                    available.append(name)
                    continue
                for base in [
                    os.environ.get("ProgramFiles", ""),
                    os.environ.get("ProgramFiles(x86)", ""),
                ]:
                    if not base:
                        continue
                    possible_paths = [
                        os.path.join(base, "Microsoft", "Edge", "Application", exe),
                        os.path.join(base, "Google", "Chrome", "Application", exe),
                        os.path.join(base, "Mozilla Firefox", exe),
                        os.path.join(
                            base,
                            "BraveSoftware",
                            "Brave-Browser",
                            "Application",
                            exe,
                        ),
                        os.path.join(base, "Chromium", "Application", exe),
                        os.path.join(base, "Opera", exe),
                        os.path.join(base, "Vivaldi", "Application", exe),
                    ]
                    for path in possible_paths:
                        if os.path.isfile(path):
                            available.append(name)
                            break
                    if name in available:
                        break
        elif system.startswith("darwin"):
            candidates = [
                ("safari", "Safari"),
                ("chrome", "Google Chrome"),
                ("firefox", "Firefox"),
                ("brave", "Brave Browser"),
                ("chromium", "Chromium"),
                ("edge", "Microsoft Edge"),
                ("opera", "Opera"),
                ("vivaldi", "Vivaldi"),
            ]
            app_dirs = ["/Applications", os.path.expanduser("~/Applications")]
            for name, app_name in candidates:
                if name == "safari":
                    if os.path.exists("/Applications/Safari.app"):
                        available.append(name)
                    continue
                found = False
                for base in app_dirs:
                    if os.path.exists(os.path.join(base, f"{app_name}.app")):
                        found = True
                        break
                if found:
                    available.append(name)
        else:
            candidates = [
                ("firefox", "firefox"),
                ("chromium", "chromium-browser"),
                ("chrome", "google-chrome"),
                ("brave", "brave-browser"),
                ("edge", "microsoft-edge"),
                ("opera", "opera"),
                ("vivaldi", "vivaldi"),
            ]
            for name, cmd in candidates:
                if shutil.which(cmd):
                    available.append(name)
                else:
                    alt = cmd.replace("-browser", "").replace("google-", "")
                    if alt != cmd and shutil.which(alt):
                        available.append(name)

        seen = set()
        result = []
        for b in available:
            if b not in seen:
                seen.add(b)
                result.append(b)
        return result

    def _get_cookie_file_for_ytdlp(self, browser: str | None) -> str | None:
        """Holt die Cookies über YtDlpHelper (mit browser-cookie3-Fallback)
        und schreibt sie in eine temporäre Netscape-Format-Datei.
        Gibt den Dateipfad zurück oder None bei Fehler.
        """
        cookie_str = YtDlpHelper.get_cookies_string(browser=browser, use_cache=True)
        if not cookie_str:
            return None

        import tempfile

        fd, path = tempfile.mkstemp(suffix=".txt", prefix="cookies_")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write("# Netscape HTTP Cookie File\n")
            for pair in cookie_str.split("; "):
                if "=" not in pair:
                    continue
                name, value = pair.split("=", 1)
                f.write(f".youtube.com\tTRUE\t/\tFALSE\t0\t{name}\t{value}\n")
        return path

    @classmethod
    def _resolve_browser(
        cls,
        requested: str | None,
        available: list[str],
    ) -> str | None:
        """Ermittelt den verfügbaren Browser für Cookies.
        Gibt den ersten gefundenen oder den angefragten zurück.
        Bevorzugte Reihenfolge: Firefox, Chromium, Chrome, Brave, Edge, Vivaldi, Opera, Safari.
        """
        if cls._debug:
            log_debug("ytdlp", f"Verfügbare Browser: {available}")
            log_debug("ytdlp", f"Angefragter Browser: {requested}")

        if not available:
            if cls._debug:
                log_debug("ytdlp", "Keine Browser verfügbar – verwende None")
            return None

        if requested and requested in available:
            if cls._debug:
                log_debug("ytdlp", f"✅ Verwende angefragten Browser: '{requested}'")
            return requested

        preferred_order = (
            "firefox",
            "chromium",
            "chrome",
            "brave",
            "edge",
            "vivaldi",
            "opera",
            "safari",
        )
        for browser in preferred_order:
            if browser in available:
                if cls._debug:
                    log_debug(
                        "ytdlp",
                        f"✅ Verwende bevorzugten Browser: '{browser}' (Reihenfolge)",
                    )
                return browser

        fallback = available[0]
        if cls._debug:
            log_debug(
                "ytdlp",
                f"⚠️ Verwende Fallback-Browser: '{fallback}' (kein bevorzugter verfügbar)",
            )

        if requested:
            logger.warning(
                f"⚠️ Browser '{requested}' nicht verfügbar – verwende '{fallback}'",
            )
        else:
            logger.info(f"ℹ️ Kein Browser angefordert – verwende '{fallback}'")
        return fallback

    def _extract_youtube_info_optimized(self, url: str) -> StreamInfo | None:
        """Optimierte Extraktion für YouTube‑Inhalte – jetzt auch für Shorts."""
        debug = self._debug
        overall_start = time.perf_counter()

        if "/shorts/" in url:
            match = re.search(
                r"(?:youtube\.com/shorts/|youtu\.be/)([a-zA-Z0-9_-]{11})",
                url,
            )
            if match:
                video_id = match.group(1)
                url = f"https://www.youtube.com/watch?v={video_id}"
                if debug:
                    log_debug("streaminfo", f"Normalized shorts URL to: {url}")
            else:
                if debug:
                    log_debug(
                        "streaminfo",
                        f"Could not extract video ID from shorts URL: {url}",
                    )
                return None

        cache_key = self._get_cache_key(url)
        cached = self._get_cached(cache_key)
        if cached:
            if debug:
                log_debug("streaminfo", f"Cache‑Treffer für {url[:60]}...")
            with self._stats_lock:
                self._stats["cache_hits"] += 1
            return cached

        with self._stats_lock:
            self._stats["cache_misses"] += 1

        fail_entry = self._get_fail_cache(url)
        if fail_entry is not None:
            _fail_time, fail_type = fail_entry
            if fail_type not in ("403", "429"):
                if debug:
                    log_debug(
                        "streaminfo",
                        f"⛔ Negativ‑Cache (permanent): {url[:60]}...",
                    )
                return None

        def direct_task() -> StreamInfo | None:
            """Schnelle Direkt-Extraktion mit --get-title etc."""
            if debug:
                log_debug("streaminfo", "Starte direkte Extraktion (Timeout 8s)...")
            t0 = time.perf_counter()
            try:
                info = self._direct_youtube_fallback(url)
                dt = (time.perf_counter() - t0) * 1000
                if debug:
                    if info:
                        log_debug(
                            "streaminfo",
                            f"Direkte Extraktion erfolgreich in {dt:.0f}ms",
                        )
                    else:
                        log_debug(
                            "streaminfo",
                            f"Direkte Extraktion fehlgeschlagen in {dt:.0f}ms",
                        )
                return info
            except Exception as exc:
                if debug:
                    log_debug("streaminfo", f"Direkte Extraktion Exception: {exc}")
                return None

        def json_task(
            use_cookies: bool,
            browser: str,
            attempt: int = 1,
        ) -> StreamInfo | None:
            """JSON-Extraktion mit der NEUEN eigenständigen _run_json_command."""
            timeout_map = {
                1: self.json_timeout,
                2: self.json_timeout + 5,
                3: self.json_timeout + 10,
            }
            timeout = timeout_map.get(attempt, self.json_timeout + 5)

            if debug:
                log_debug(
                    "streaminfo",
                    f"Starte JSON‑Extraktion (Cookies={use_cookies}, "
                    f"Browser={browser}, Versuch {attempt}, Timeout {timeout}s)...",
                )
            t0 = time.perf_counter()

            raw = self._run_json_command(
                url=url,
                use_cookies=use_cookies,
                browser=browser if use_cookies else None,
                timeout=timeout,
                extra_debug=(debug or DEBUG_LEVEL >= 3),
                flat_playlist=False,
                info_callback=None,
            )

            if raw:
                try:
                    import json

                    data = json.loads(raw)
                    info = self._build_stream_info_from_json(data)
                    dt = (time.perf_counter() - t0) * 1000
                    if info and debug:
                        log_debug(
                            "streaminfo",
                            f"JSON‑Extraktion erfolgreich in {dt:.0f}ms",
                        )
                    return info
                except json.JSONDecodeError:
                    info = self._parse_youtube_output(
                        raw,
                        f"JSON ({'mit' if use_cookies else 'ohne'} Cookies, Versuch {attempt})",
                    )
                    dt = (time.perf_counter() - t0) * 1000
                    if info and debug:
                        log_debug(
                            "streaminfo",
                            f"JSON‑Extraktion (Fallback) erfolgreich in {dt:.0f}ms",
                        )
                    return info

            return None

        result: StreamInfo | None = None
        try:
            with ThreadPoolExecutor(
                max_workers=self.parallel_workers,
                thread_name_prefix="YouTubeInfo",
            ) as executor:
                direct_future = executor.submit(direct_task)
                json_no_cookies_future = executor.submit(json_task, False, "", 1)
                json_cookies_future = None
                if self.use_browser_cookies:
                    browser = self.cookies_browser
                    json_cookies_future = executor.submit(json_task, True, browser, 1)

                try:
                    result = direct_future.result(timeout=self.direct_timeout)
                    if result:
                        if debug:
                            log_debug(
                                "streaminfo",
                                "✅ Direkte Extraktion lieferte Ergebnis",
                            )
                        for f in (json_no_cookies_future, json_cookies_future):
                            if f and not f.done():
                                f.cancel()
                        self._cache_result(cache_key, result)
                        with self._stats_lock:
                            self._stats["direct_extractions"] += 1
                        return result
                except TimeoutError:
                    if debug:
                        log_debug("streaminfo", "⏰ Direkte Extraktion Timeout nach 8s")
                except Exception as exc:
                    if debug:
                        log_debug("streaminfo", f"Direkte Extraktion Fehler: {exc}")

                futures = [json_no_cookies_future]
                if json_cookies_future:
                    futures.append(json_cookies_future)

                json_success = False
                try:
                    for future in as_completed(futures, timeout=20.0):
                        try:
                            info = future.result()
                            if info:
                                result = info
                                json_success = True
                                with self._stats_lock:
                                    self._stats["json_extractions"] += 1
                                for f in futures:
                                    if not f.done():
                                        f.cancel()
                                break
                        except Exception as exc:
                            if debug:
                                log_debug("streaminfo", f"JSON‑Task Fehler: {exc}")
                            continue
                except TimeoutError:
                    if debug:
                        log_debug(
                            "streaminfo",
                            "⏰ JSON‑Extraktion Gesamt‑Timeout nach 20s",
                        )
                except Exception as exc:
                    if debug:
                        log_debug(
                            "streaminfo",
                            f"Unerwarteter Fehler in as_completed: {exc}",
                        )

                if not json_success and debug:
                    log_debug("streaminfo", "⚠️ Alle JSON‑Extraktionen fehlgeschlagen")

        except Exception as bpe:
            if debug:
                log_debug("streaminfo", f"Executor‑Fehler: {bpe}")
            result = direct_task()
            if not result:
                result = json_task(False, "", 1)
            if not result and self.use_browser_cookies:
                result = json_task(True, self.cookies_browser, 1)

        if not result:
            fail_entry = self._get_fail_cache(url)
            if fail_entry is not None and fail_entry[1] not in ("403", "429"):
                if debug:
                    log_debug(
                        "streaminfo",
                        "⛔ Permanenter Fehler – keine weitere Extraktion",
                    )
                return None

            if debug:
                log_debug(
                    "streaminfo",
                    "Alle Extraktionsmethoden fehlgeschlagen – verwende URL-Fallback",
                )
            result = self._fallback_from_url(url)
            if result:
                with self._stats_lock:
                    self._stats["fallback_extractions"] += 1
                self._cache_result(cache_key, result)

        if debug and result:
            overall_ms = (time.perf_counter() - overall_start) * 1000
            log_debug("streaminfo", f"Gesamtdauer: {overall_ms:.0f}ms")

        return result

    def _parse_youtube_output(self, output: str, source: str) -> StreamInfo | None:
        data = self._parse_partial_json(output)
        if data:
            return self._build_stream_info_from_json(data)

        lines = output.split("\n")
        title = None
        for line in lines:
            if line.strip() and not line.startswith("{"):
                possible_title = line.strip()
                if 20 < len(possible_title) < 200:
                    title = possible_title
                    break
        if title:
            if self._debug:
                log_debug("streaminfo", f"✅ Extracted title from output: {title}")
            return StreamInfo(
                title=title,
                uploader="YouTube",
                duration="Live",
                view_count=0,
                platform="youtube",
                description="",
                duration_seconds=None,
                is_live=False,
                thumbnail="",
                original_url="",
                stream_url=None,
            )

        return None

    def _direct_youtube_fallback(self, url: str) -> StreamInfo | None:
        try:
            cmd_title = [
                "yt-dlp",
                "--get-title",
                "--no-warnings",
                "--no-check-certificate",
                "--quiet",
                "--",
                url,
            ]
            cmd_uploader = [
                "yt-dlp",
                "--get-filename",
                "-o",
                "%(uploader)s",
                "--no-warnings",
                "--no-check-certificate",
                "--quiet",
                "--",
                url,
            ]
            cmd_duration = [
                "yt-dlp",
                "--print",
                "duration",
                "--no-warnings",
                "--no-check-certificate",
                "--quiet",
                "--",
                url,
            ]

            with ThreadPoolExecutor(max_workers=3) as executor:
                title_future = executor.submit(
                    YtDlpHelper.run_command,
                    cmd_title,
                    10,
                    "direct_title",
                )
                uploader_future = executor.submit(
                    YtDlpHelper.run_command,
                    cmd_uploader,
                    10,
                    "direct_uploader",
                )

                duration_seconds: float | None = None
                duration_str: str = "Live"
                for attempt in range(1, self.max_retries + 1):
                    if attempt > 1:
                        time.sleep(min(0.5 * (2 ** (attempt - 1)), 2.0))
                    timeout = 10 + (attempt - 1) * 5
                    dur_future = executor.submit(
                        YtDlpHelper.run_command,
                        cmd_duration,
                        timeout,
                        "direct_duration",
                    )
                    try:
                        dur_result = dur_future.result(timeout=timeout + 2)
                        if dur_result and dur_result.strip():
                            first_line = dur_result.strip().split("\n")[0]
                            if first_line == "NA":
                                break
                            try:
                                duration_seconds = float(first_line)
                                hours = int(duration_seconds // 3600)
                                minutes = int((duration_seconds % 3600) // 60)
                                seconds = duration_seconds % 60
                                if hours:
                                    duration_str = (
                                        f"{hours}:{minutes:02d}:{int(seconds):02d}"
                                    )
                                else:
                                    duration_str = f"{minutes}:{int(seconds):02d}"
                                break
                            except Exception as e:
                                logger.debug("Ignored exception: %s", e, exc_info=True)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)

                title_result = None
                uploader_result = None
                try:
                    title_result = title_future.result(timeout=10)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                try:
                    uploader_result = uploader_future.result(timeout=10)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            title = "YouTube Stream"
            uploader = "YouTube"
            if title_result and title_result.strip():
                title = title_result.strip().split("\n")[0]
            if uploader_result and uploader_result.strip():
                uploader = uploader_result.strip().split("\n")[0]

            if self._debug:
                log_debug(
                    "streaminfo",
                    f"✅ Direct extraction: title='{title}', uploader='{uploader}'",
                )
            return StreamInfo(
                title=title[:100],
                uploader=uploader,
                duration=duration_str,
                view_count=0,
                platform="youtube",
                description="",
                duration_seconds=duration_seconds,
                is_live=(duration_seconds is None or duration_seconds == 0),
                thumbnail="",
                original_url=url,
                stream_url=None,
            )
        except Exception as e:
            if self._debug:
                log_debug("streaminfo", f"⚠️ Direct extraction failed: {e}")
            return None

    def _extract_twitch_info_optimized(self, url: str) -> StreamInfo | None:
        if self._debug:
            log_debug(
                "streaminfo",
                "🎯 Twitch detected, trying optimized extraction...",
            )

        raw = self._run_json_command(
            url=url,
            use_cookies=False,
            browser=None,
            timeout=self.json_timeout,
            is_live=True,
            is_youtube=False,
            extra_debug=(self._debug or DEBUG_LEVEL >= 3),
            flat_playlist=False,
            force_generic_extractor=False,
            prefer_web_client=False,
            info_callback=None,
            cancel_event=None,
        )
        if raw:
            info = self._parse_twitch_output(raw, "No Cookies")
            if info:
                return info

        browser = self.cookies_browser
        if self._debug:
            log_debug(
                "streaminfo",
                f"    🧪 Versuche mit {browser.capitalize()} Cookies...",
            )
        raw = self._run_json_command(
            url=url,
            use_cookies=True,
            browser=browser,
            timeout=self.json_timeout + 5,
            is_live=True,
            is_youtube=False,
            extra_debug=(self._debug or DEBUG_LEVEL >= 3),
            flat_playlist=False,
            force_generic_extractor=False,
            prefer_web_client=False,
            info_callback=None,
            cancel_event=None,
        )
        if raw:
            info = self._parse_twitch_output(raw, f"{browser.capitalize()} Cookies")
            if info:
                return info

        if self._debug:
            log_debug("streaminfo", "    🔄 Fallback: Extrahiere Kanalname aus URL...")
        return self._twitch_url_fallback(url)

    def _parse_twitch_output(self, output: str, source: str) -> StreamInfo | None:
        data = self._parse_partial_json(output)
        if data:
            uploader = data.get(
                "uploader",
                data.get("channel", data.get("creator", "Unknown")),
            )
            title = data.get("title", "Twitch Stream")
            duration = data.get("duration_string", "Live")
            view_count = data.get("view_count", 0)
            description = data.get("description", "")
            if len(description) > 200:
                description = description[:200] + "..."
            if self._debug:
                log_debug("streaminfo", f"      ✅ Success with {source}")
                log_debug("streaminfo", f"        Title: {title[:60]}")
                log_debug("streaminfo", f"        Channel: {uploader}")
            return StreamInfo(
                title=title,
                uploader=uploader,
                duration=duration,
                view_count=view_count,
                platform="twitch",
                description=description,
                duration_seconds=data.get("duration"),
                is_live=True,
                thumbnail="",
                original_url=data.get("webpage_url", ""),
                stream_url=data.get("url", ""),
            )

        lines = output.split("\n")
        title = None
        uploader = None
        for line in lines:
            if line.strip() and not line.startswith("{"):
                if title is None:
                    title = line.strip()
                elif uploader is None:
                    uploader = line.strip()
                    break
        if title and len(title) > 10:
            if self._debug:
                log_debug(
                    "streaminfo",
                    f"      ✅ Extracted title from output: {title}",
                )
            return StreamInfo(
                title=title[:100],
                uploader=uploader or "Twitch",
                duration="Live",
                view_count=0,
                platform="twitch",
                description="",
                duration_seconds=None,
                is_live=True,
                thumbnail="",
                original_url="",
                stream_url=None,
            )
        return None

    def _twitch_url_fallback(self, url: str) -> StreamInfo | None:
        try:
            parsed = urllib.parse.urlparse(url)
            path = parsed.path.strip("/")
            channel = (
                path.split("/")[0]
                if path
                else parsed.netloc.replace("www.", "").replace(".tv", "")
            )
            if channel:
                if self._debug:
                    log_debug(
                        "streaminfo",
                        f"      ✅ Extracted channel from URL: {channel}",
                    )
                return StreamInfo(
                    title=f"{channel} (Twitch Live)",
                    uploader=channel,
                    duration="Live",
                    view_count=0,
                    platform="twitch",
                    description="",
                    duration_seconds=None,
                    is_live=True,
                    thumbnail="",
                    original_url=url,
                    stream_url=None,
                )
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        return None

