    def __init__(self, parent: tk.Widget, text: str, gui_ref: Any) -> None:
        """Initialisiert den SummarizeDialog vollständig und thread‑sicher."""
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS

        self.text = text
        self.gui = gui_ref
        self.stream_title = self._extract_stream_title()
        self._request_cancel = threading.Event()
        self._destroyed = False
        self._state_lock = threading.RLock()
        self._summarize_in_progress = False
        self._combobox_font_set = False
        self._ollama_last_health_check = 0.0
        self._ollama_health_status = True

        adv = gui_ref.advanced_settings
        self.model = getattr(adv, "summarize_model", "llama3.1:8b")
        self.temperature = getattr(adv, "summarize_temperature", 0.1)
        self.strategy = getattr(adv, "summary_strategy", "Schnell (parallel)")
        self.language = getattr(adv, "summary_language", "Deutsch")
        self.style = getattr(adv, "summary_style", "Kompakt (3‑5 Sätze)")
        self.use_title_context = getattr(adv, "summary_use_title", False)
        self.max_chunk_tokens = getattr(adv, "summary_max_chunk_tokens", 2000)
        self.use_structured_output = getattr(adv, "summary_structured", False)
        self.max_parallel_requests = getattr(adv, "summary_max_parallel_requests", 2)

        self._user_edited_prompt = False
        self._retry_attempt = 0
        self.auto_tts_var = tk.BooleanVar(value=False)
        self._token_debounce_id = None

        self._response_cache = self._build_lru_cache(self.RESPONSE_CACHE_MAXSIZE)
        self._token_cache = self._build_lru_cache(500)
        self._cache_lock = threading.RLock()
        self.CACHE_TTL = 3600
        self._cache_ttl = self.CACHE_TTL
        self._chunk_cache = self._build_lru_cache(200)

        self._tiktoken = None
        try:
            import tiktoken

            self._tiktoken = tiktoken
            if _debug:
                log_debug("summarize", "tiktoken erfolgreich importiert")
        except ImportError:
            if _debug:
                log_debug("summarize", "tiktoken nicht verfügbar – verwende Heuristik")

        self._ollama_class = self._get_ollama_class()
        self._ollama_instance = None
        self._ollama_usage_count = 0
        self._ollama_usage_lock = threading.RLock()
        self._ollama_available = self._ollama_class is not None

        self._model_context_limit: int | None = None
        self.MAX_CHUNKS = 200

        self._nltk_available = False
        self._nltk_initialized = False
        try:
            import nltk

            self._nltk = nltk
            self._nltk_available = True
            threading.Thread(
                target=self._download_nltk_data,
                daemon=True,
                name="NLTKDownloader",
            ).start()
        except ImportError:
            if _debug:
                log_debug("summarize", "NLTK nicht verfügbar – verwende Regex‑Fallback")

        self._backup_file = Path(tempfile.gettempdir()) / "dragon_summary_backup.txt"
        self._backup_timer = None

        self._history: list[dict[str, Any]] = []
        self._history_file = (
            PlatformUtils.get_platform_config_dir() / "summarize_history.json"
        )
        self._load_history()
        self._MAX_HISTORY_ENTRIES = 200

        self._profiles: dict[str, dict[str, Any]] = {}
        self._load_profiles()

        self._user_templates: dict[str, dict[str, Any]] = {}
        self._load_user_templates()
        self._build_template_list()

        self._blacklist_patterns: list[Pattern] = []
        self._prepare_blacklist_patterns()

        self._available_models: list[str] = []
        self._model_fetch_in_progress = False
        self._model_fetch_timestamp = 0.0

        self._summary_state: dict[str, Any] = {
            "full_summary": "",
            "parts": [],
        }
        self._chunk_results: list[str | None] = []
        self._chunks_total = 0
        self._chunks_processed = 0
        self._chunks_lock = threading.RLock()
        self._last_progress_update = 0.0
        self._progress_update_interval = 0.5

        super().__init__(
            parent,
            "Zusammenfassung mit Ollama",
            width=1100,
            height=740,
            modal=True,
            resizable=True,
        )

        self.build_ui()
        self._bind_shortcuts()
        self._check_backup()
        self._reset_to_default_prompt()
        self._init_drag_drop()
        self._start_periodic_backup()
        self._fetch_available_models(force=False)
        self._start_ollama_health_check()

        if hasattr(self, "prompt_text") and self.prompt_text.winfo_exists():
            self.prompt_text.focus_set()

        if not self._ollama_available:
            self._disable_ollama_ui()

        if _debug:
            log_debug("summarize", "SummarizeDialog.__init__ FINISHED")

    @staticmethod
    def _build_lru_cache(maxsize: int = 500):
        """Erzeugt einen thread‑sicheren LRU‑Cache mit RLock.

        Verwendet OrderedDict und Move‑to‑End‑Strategie.
        """
        from collections import OrderedDict

        class _LRU:
            def __init__(self, maxsize):
                self.maxsize = maxsize
                self._data = OrderedDict()
                self._lock = threading.RLock()

            def get(self, key):
                with self._lock:
                    if key in self._data:
                        self._data.move_to_end(key)
                        return self._data[key]
                    return None

            def put(self, key, value):
                with self._lock:
                    if key in self._data:
                        del self._data[key]
                    self._data[key] = value
                    if len(self._data) > self.maxsize:
                        self._data.popitem(last=False)

            def remove(self, key):
                with self._lock:
                    if key in self._data:
                        del self._data[key]

            def clear(self):
                with self._lock:
                    self._data.clear()

            def __contains__(self, key):
                with self._lock:
                    return key in self._data

        return _LRU(maxsize)

    @staticmethod
    def _get_ollama_class():
        """Versucht, die OllamaSummarizer-Klasse zu laden."""
        cls = globals().get("OllamaSummarizer")
        if cls is not None:
            return cls
        try:
            from ollama_summarizer import OllamaSummarizer

            return OllamaSummarizer
        except ImportError:
            return None

    def _download_nltk_data(self) -> None:
        try:
            self._nltk.data.find("tokenizers/punkt_tab")
        except LookupError:
            self._nltk.download("punkt_tab", quiet=True)
        self._nltk_initialized = True

    def _init_drag_drop(self) -> None:
        """Initialisiert Drag&Drop für den Dialog.
        Bevorzugt die integrierte Tkinter-DND-Unterstützung (tkinter.dnd).
        Fallback auf externe tkinterdnd2-Bibliothek für sehr alte Systeme.
        """
        self._dnd_available = False

        try:
            from tkinter import dnd

            try:
                dnd.dnd_bind(self.dialog, "<<Drop>>", self._on_drop)
            except (AttributeError, TypeError):
                self.dialog.dnd_bind("<<Drop>>", self._on_drop)
            self._dnd_available = True
            log_debug("dnd", "✅ Drag&Drop aktiviert (Tkinter integriert)")
            return
        except (ImportError, AttributeError, tk.TclError) as e:
            log_debug("dnd", f"Integrierte DND nicht verfügbar: {e}")

        try:
            import tkinterdnd2  # noqa: F401

            self.dialog.tk.call(
                "tkdnd::drop_target",
                "register",
                self.dialog._w,
                "DND_Files",
            )
            self.dialog.drop_target_register("DND_Files")
            self.dialog.dnd_bind("<<Drop>>", self._on_drop)
            self._dnd_available = True
            log_debug("dnd", "✅ Drag&Drop aktiviert (tkinterdnd2 extern)")
        except (ImportError, AttributeError, tk.TclError) as e:
            if isinstance(e, tk.TclError) and "invalid command name" in str(e):
                log_debug(
                    "dnd",
                    "tkdnd-Erweiterung nicht verfügbar – Drag&Drop deaktiviert",
                )
            else:
                log_debug("dnd", f"Drag&Drop-Initialisierung fehlgeschlagen: {e}")
            self._dnd_available = False

    def _get_full_summary(self) -> str:
        """Gibt die aktuelle vollständige Zusammenfassung zurück (thread-sicher)."""
        with self._state_lock:
            return self._summary_state.get("full_summary", "")

    def _is_ollama_available(self) -> bool:
        """Prüft, ob OllamaSummarizer verfügbar ist."""
        cls = self._get_ollama_class()
        return cls is not None

    def _disable_ollama_ui(self) -> None:
        """Deaktiviert alle Summarize-Buttons, wenn Ollama nicht verfügbar ist."""
        for widget in (self.summarize_btn, self.test_prompt_btn):
            if widget and widget.winfo_exists():
                widget.config(state="disabled")
        if hasattr(self, "status_label") and self.status_label.winfo_exists():
            self.status_label.config(text="❌ OllamaSummarizer nicht verfügbar")

    def _extract_stream_title(self) -> str:
        """Extrahiert den Titel des aktuellen Streams aus der GUI."""
        info = getattr(self.gui, "current_stream_info", None)
        return info.title if info and info.title else ""

    def _prepare_blacklist_patterns(self) -> None:
        """Bereitet die Blacklist-Patterns für die Filterung vor."""
        blacklist = getattr(self.gui.advanced_settings, "blacklist", [])
        mode = getattr(self.gui.advanced_settings, "blacklist_mode", "word")
        for phrase in blacklist:
            if not phrase:
                continue
            try:
                if mode == "word":
                    pat = re.compile(r"\b" + re.escape(phrase) + r"\b", re.IGNORECASE)
                else:
                    pat = re.compile(re.escape(phrase), re.IGNORECASE)
                self._blacklist_patterns.append(pat)
            except re.error as e:
                log_debug("summarize", f"Ungültiges Blacklist-Muster '{phrase}': {e}")

    def _apply_blacklist(self, text: str) -> str:
        """Wendet die Blacklist auf einen Text an und entfernt unerwünschte Phrasen."""
        for pat in self._blacklist_patterns:
            text = pat.sub("", text)
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

    def _estimate_tokens(self, t: str) -> int:
        """Schätzt die Token‑Anzahl für den Text *t*.
        Verwendet den einmalig importierten tiktoken‑Cache.
        """
        if not isinstance(t, str):
            try:
                t = str(t)
            except Exception:
                return 1
        if not t:
            return 1

        cache = getattr(self, "_token_cache", None)
        cache_key = f"{self.model}||{
            hashlib.sha256(t.encode('utf-8', errors='ignore')).hexdigest()[:16]
        }"
        if cache is not None:
            cached = cache.get(cache_key)
            if cached is not None:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "summarize",
                        "_estimate_tokens: Cache‑HIT → %d Tokens",
                        cached,
                    )
                return cached

        tokens = None
        if self._tiktoken is not None:
            for enc_name in ("o200k_base", "cl100k_base", "p50k_base", "r50k_base"):
                try:
                    enc = self._tiktoken.get_encoding(enc_name)
                    tokens = len(enc.encode(t))
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "summarize",
                            "_estimate_tokens: tiktoken '%s' → %d Tokens",
                            enc_name,
                            tokens,
                        )
                    break
                except Exception:
                    continue

        if tokens is None:
            tokens = max(1, len(t) // 3)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "_estimate_tokens: Heuristik → %d Tokens",
                    tokens,
                )

        if cache is not None:
            try:
                cache.put(cache_key, tokens)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        return tokens

    def _get_model_context_limit(self) -> int:
        """Ermittelt das Kontext‑Token‑Limit des aktuellen Ollama‑Modells."""
        if self._model_context_limit is not None:
            return self._model_context_limit

        FALLBACK_LIMITS: dict[str, int] = {
            "llama3.1:8b": 128000,
            "llama3.1:70b": 128000,
            "llama3.1:405b": 128000,
            "qwen2.5:7b": 128000,
            "qwen2.5:14b": 128000,
            "qwen2.5:32b": 128000,
            "qwen2.5:72b": 128000,
            "qwen3:8b": 128000,
            "jaahas/qwen3-abliterated:8b": 128000,
            "deepseek-r1:7b": 128000,
            "deepseek-r1:14b": 128000,
            "deepseek-r1:32b": 128000,
            "deepseek-coder:6.7b": 128000,
            "deepseek-coder:33b": 128000,
            "mistral-nemo:12b": 128000,
            "mixtral:8x7b": 32768,
            "mixtral:8x22b": 65536,
            "glm4:9b": 128000,
            "glm4:9b-chat": 128000,
            "phi4:14b": 128000,
            "phi4-mini:3.8b": 128000,
            "gemma2:9b": 8192,
            "gemma2:27b": 8192,
            "llama3:8b": 8192,
            "llama3:70b": 8192,
            "mistral": 8192,
            "mistral:7b": 8192,
            "codellama": 16384,
            "codellama:13b": 16384,
            "codellama:34b": 16384,
            "wizardlm2:7b": 8192,
            "dolphin-mistral:latest": 8192,
            "dolphin-mixtral:latest": 32768,
            "tinyllama": 2048,
            "orca-mini": 2048,
            "llama2:7b": 4096,
            "llama2:13b": 4096,
            "llama2:70b": 4096,
        }

        found_limit = None
        for model_pattern, limit in FALLBACK_LIMITS.items():
            if self.model.startswith(model_pattern) or model_pattern in self.model:
                found_limit = limit
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "_get_model_context_limit: Modell '%s' → %d Tokens (Pattern: '%s')",
                        self.model,
                        limit,
                        model_pattern,
                    )
                break

        fallback = found_limit if found_limit is not None else 16384

        if DEBUG_LEVEL >= 3:
            if found_limit is None:
                log_debug(
                    "summarize",
                    "_get_model_context_limit: Kein spezifisches Limit für '%s' – "
                    "verwende Fallback %d Tokens.",
                    self.model,
                    fallback,
                )
            else:
                log_debug(
                    "summarize",
                    "_get_model_context_limit: Limit für '%s' = %d Tokens.",
                    self.model,
                    fallback,
                )

        self._model_context_limit = fallback
        return fallback

    def _truncate_text_to_fit(
        self,
        text: str,
        max_tokens: int,
        *,
        add_notice: bool = True,
    ) -> str:
        """Kürzt *text* so, dass er zusammen mit dem Prompt ins Kontextfenster passt."""
        if not isinstance(text, str):
            try:
                text = str(text)
            except Exception:
                return ""

        if max_tokens <= 0:
            return text

        current_tokens = self._estimate_tokens(text)
        if current_tokens <= max_tokens:
            return text

        if DEBUG_LEVEL >= 3:
            log_debug(
                "summarize",
                "_truncate_text_to_fit: Kürze Text von %d auf max. %d Tokens",
                current_tokens,
                max_tokens,
            )

        ratio = max_tokens / current_tokens
        approx_len = int(len(text) * ratio)

        trunc_pos = approx_len
        while trunc_pos > 0 and trunc_pos < len(text):
            if text[trunc_pos] in ".!?。！？":
                if trunc_pos + 1 >= len(text) or text[trunc_pos + 1] in " \n":
                    break
            trunc_pos -= 1

        if trunc_pos == 0:
            trunc_pos = approx_len

        truncated = text[: trunc_pos + 1].strip()

        original_len = len(text)
        if original_len > 0 and len(truncated) < original_len * 0.1:
            logger.warning(
                "_truncate_text_to_fit: Text wurde auf %d%% der Originallänge gekürzt.",
                int(len(truncated) / original_len * 100),
            )

        if add_notice:
            truncated += (
                "\n\n[Text wurde automatisch gekürzt, um das Kontextlimit einzuhalten.]"
            )

        return truncated

    def _split_sentences(self, text: str) -> list[str]:
        """Zerlegt einen Text in eine Liste von Sätzen.
        Verwendet NLTK, falls verfügbar, andernfalls einen eigenen Regex-Fallback.
        """
        if not text or not isinstance(text, str):
            return []

        clean = text.strip()
        if not clean:
            return []

        if self._nltk_available and getattr(self, "_nltk_initialized", False):
            try:
                sentences = self._nltk.sent_tokenize(clean)
                if sentences:
                    if DEBUG_LEVEL >= 4:
                        log_debug("summarize", f"NLTK: {len(sentences)} Sätze erkannt")
                    return sentences
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        f"NLTK sent_tokenize fehlgeschlagen: {e} – verwende Fallback",
                    )

        try:
            sentences = re.split(r"(?<=[.!?。！？])\s+", clean)
            sentences = [s.strip() for s in sentences if s.strip()]
            if sentences:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "summarize",
                        f"Regex-Fallback: {len(sentences)} Sätze erkannt",
                    )
                return sentences
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", f"Regex-Split fehlgeschlagen: {e}")

        return [clean] if clean else []

    def _split_into_chunks(self, text: str, max_tokens: int) -> list[str]:
        """Teilt einen Text in Chunks auf, wobei jeder Chunk maximal
        *max_tokens* Tokens beanspruchen darf.
        """
        if not text or max_tokens <= 0:
            return []

        sents = self._split_sentences(text)
        if not sents:
            return [text]

        chunks: list[str] = []
        current_chunk: list[str] = []
        current_tokens = 0

        for s in sents:
            t = self._estimate_tokens(s)
            if t > max_tokens:
                if current_chunk:
                    chunks.append(" ".join(current_chunk))
                    current_chunk = []
                    current_tokens = 0
                truncated = self._truncate_text_to_fit(s, max_tokens, add_notice=True)
                if truncated:
                    chunks.append(truncated)
                continue

            if current_tokens + t <= max_tokens:
                current_chunk.append(s)
                current_tokens += t
            else:
                if current_chunk:
                    chunks.append(" ".join(current_chunk))
                current_chunk = [s]
                current_tokens = t

        if current_chunk:
            chunks.append(" ".join(current_chunk))

        if len(chunks) > self.MAX_CHUNKS:
            chunks = chunks[: self.MAX_CHUNKS]

        return chunks or [text]

    def _cache_key(self, prompt: str) -> str:
        """Erzeugt einen eindeutigen Schlüssel für den Antwort‑Cache."""
        model = str(self.model) if self.model else "unknown"
        prompt = str(prompt) if prompt else ""
        text = str(self.text) if hasattr(self, "text") and self.text else ""

        raw = f"{model}|{prompt}|{text}"
        return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()

    def _get_cached(self, prompt: str) -> str | None:
        """Ruft eine gecachte Antwort ab, falls vorhanden und nicht abgelaufen."""
        key = self._cache_key(prompt)
        entry = self._response_cache.get(key)
        if entry:
            res, ts = entry
            if time.time() - ts < self._cache_ttl:
                log_debug("summarize", "Cache-HIT")
                return res
            self._response_cache.remove(key)
            log_debug("summarize", "Cache-Eintrag abgelaufen, entfernt")
        return None

    def _cache_set(self, prompt: str, res: str) -> None:
        """Speichert eine Antwort im Cache."""
        key = self._cache_key(prompt)
        self._response_cache.put(key, (res, time.time()))
        log_debug("summarize", f"Cache set for {key[:16]}…")

    def _set_full_summary(self, s: str) -> None:
        """Setzt die vollständige Zusammenfassung (thread‑sicher)."""
        if not isinstance(s, str):
            logger.warning(
                f"_set_full_summary: erwartet str, erhielt {type(s).__name__}",
            )
            return
        with self._state_lock:
            if self._summary_state.get("full_summary") != s:
                self._summary_state["full_summary"] = s
                if DEBUG_LEVEL >= 3:
                    log_debug("summarize", f"Full summary set (length: {len(s)})")

    def _append_summary_part(self, part: str) -> None:
        """Fügt einen Teil zur Zusammenfassung hinzu (thread‑sicher)."""
        if not part or not isinstance(part, str):
            return
        with self._state_lock:
            if "parts" not in self._summary_state:
                self._summary_state["parts"] = []
            self._summary_state["parts"].append(part)
            if DEBUG_LEVEL >= 4:
                log_debug("summarize", f"Appended summary part (length: {len(part)})")

    def _clear_summary_parts(self) -> None:
        """Leert die Liste der Zusammenfassungsteile (thread‑sicher)."""
        with self._state_lock:
            if "parts" in self._summary_state:
                count = len(self._summary_state["parts"])
                self._summary_state["parts"].clear()
                if DEBUG_LEVEL >= 3 and count > 0:
                    log_debug("summarize", f"Cleared {count} summary parts")

    def _get_summary_parts(self) -> list[str]:
        """Gibt eine Kopie der Zusammenfassungsteile zurück (thread‑sicher)."""
        with self._state_lock:
            return list(self._summary_state.get("parts", []))

    def _apply_blacklist_to_summary(self) -> None:
        """Wendet die konfigurierte Blacklist auf die aktuelle Zusammenfassung an.
        Überspringt die Verarbeitung, wenn die Blacklist leer ist.
        """
        blacklist = getattr(self.gui.advanced_settings, "blacklist", [])
        if not blacklist:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "_apply_blacklist_to_summary: Blacklist leer – überspringe",
                )
            return

        summary = self._get_full_summary()
        if not summary:
            return

        filtered = None
        filter_func = getattr(self.gui, "_filter_blacklist_text", None)
        if filter_func is not None:
            try:
                filtered = filter_func(summary, "summary")
            except Exception as e:
                log_debug("summarize", f"Blacklist filter (GUI) error: {e}")
                filtered = self._apply_blacklist_patterns(summary)
        else:
            filtered = self._apply_blacklist_patterns(summary)

        if filtered is None or filtered == summary:
            return

        if not filtered.strip():
            log_debug(
                "summarize",
                "Blacklist würde gesamte Zusammenfassung entfernen – Abbruch",
            )
            return

        self._set_full_summary(filtered)

        if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
            self._safe_after(0, self._update_summary_text_widget, filtered)

    def _apply_blacklist_patterns(self, text: str) -> str:
        """Wendet die kompilierten Blacklist-Patterns auf den Text an.
        Gibt den gefilterten Text zurück (oder den Originaltext, falls keine Änderung).
        """
        if not text or not self._blacklist_patterns:
            return text

        result = text
        for pattern in self._blacklist_patterns:
            result = pattern.sub("", result)

        result = re.sub(r"[ \t]+", " ", result)
        result = re.sub(r"\n{3,}", "\n\n", result)
        return result.strip()

    def _update_summary_text_widget(self, text: str) -> None:
        """Aktualisiert das Summary-Textfeld im Hauptthread."""
        try:
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self.summary_text.delete("1.0", "end")
                self.summary_text.insert("1.0", text)
        except tk.TclError:
            pass

    def _check_backup(self) -> None:
        """Prüft, ob ein Backup der Zusammenfassung vorhanden ist."""
        if not os.path.exists(self._backup_file):
            return
        try:
            if time.time() - os.path.getmtime(self._backup_file) > 3600:
                return
        except OSError:
            return
        if DarkMessageBox.askyesno(
            "Zusammenfassung wiederherstellen?",
            "Es wurde eine nicht gespeicherte Zusammenfassung gefunden. Wiederherstellen?",
            parent=self.dialog,
        ):
            try:
                with open(self._backup_file, encoding="utf-8") as f:
                    saved = f.read()
                self._set_full_summary(saved)
                self.dialog.after(100, self._restore_backup)
            except Exception as e:
                log_debug("summarize", f"Backup restore error: {e}")

    def _restore_backup(self) -> None:
        """Stellt das Backup in der GUI wieder her."""
        if self._destroyed or not self.dialog.winfo_exists():
            return
        try:
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self.summary_text.delete("1.0", "end")
                self.summary_text.insert("1.0", self._get_full_summary())
        except Exception as e:
            log_debug("summarize", f"Backup restore UI error: {e}")

    def _save_backup(self) -> None:
        """Speichert die aktuelle Zusammenfassung als Backup.
        Stellt sicher, dass das Zielverzeichnis existiert.
        Im Fehlerfall wird nur geloggt – die Anwendung läuft weiter.
        """
        summary = self._get_full_summary()
        if not summary or not isinstance(summary, str):
            return

        try:
            backup_path = Path(self._backup_file)
            backup_path.parent.mkdir(parents=True, exist_ok=True)

            with backup_path.open("w", encoding="utf-8") as f:
                f.write(summary)

        except OSError as e:
            log_debug("summarize", f"Backup save (OS error): {e}")
        except Exception as e:
            log_debug("summarize", f"Backup save error: {e}")

    def _start_periodic_backup(self) -> None:
        """Startet den periodischen Backup‑Timer."""
        if self._destroyed or not self.dialog or not self.dialog.winfo_exists():
            return

        def backup_worker():
            if self._destroyed or not self.dialog.winfo_exists():
                return
            if self._get_full_summary():
                self._save_backup()
            self._backup_timer = self.dialog.after(30000, backup_worker)

        self._backup_timer = self.dialog.after(30000, backup_worker)

    def _load_profiles(self) -> None:
        """Lädt gespeicherte Profile aus der JSON-Datei."""
        path = PlatformUtils.get_platform_config_dir() / "summarize_profiles.json"
        if path.exists():
            try:
                with open(path, encoding="utf-8") as f:
                    self._profiles = json.load(f)
            except Exception as e:
                log_debug("summarize", f"Profile konnten nicht geladen werden: {e}")
                self._profiles = {}

    def _save_profiles(self) -> None:
        """Speichert die Profile persistent."""
        path = PlatformUtils.get_platform_config_dir() / "summarize_profiles.json"
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(self._profiles, f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"Could not save profiles: {e}")

    def _save_current_profile(self) -> None:
        """Speichert die aktuellen Einstellungen als neues Profil."""
        name = simpledialog.askstring(
            "Profil speichern",
            "Name des Profils:",
            parent=self.dialog,
        )
        if not name:
            return
        profile = {
            "model": self.model,
            "temperature": self.temperature,
            "strategy": self.strategy,
            "language": self.language,
            "style": self.style,
            "use_title_context": self.use_title_context,
            "max_chunk_tokens": self.max_chunk_tokens,
            "use_structured_output": self.use_structured_output,
        }
        self._profiles[name] = profile
        self._save_profiles()
        self._update_profile_menu()
        self.status_label.config(text=f"✅ Profil '{name}' gespeichert")

    def _load_profile(self, name: str) -> None:
        """Lädt ein gespeichertes Profil und wendet es an."""
        profile = self._profiles.get(name)
        if not profile:
            self.status_label.config(text=f"❌ Profil '{name}' nicht gefunden")
            return
        self.model = profile["model"]
        self.model_var.set(self.model)
        self._token_cache.clear()
        self._model_context_limit = None
        self.temperature = profile["temperature"]
        self.temp_var.set(self.temperature)
        self.strategy = profile["strategy"]
        self.strategy_var.set(self.strategy)
        self.language = profile["language"]
        self.lang_var.set(self.language)
        self.style = profile["style"]
        self.style_var.set(self.style)
        self.use_title_context = profile.get("use_title_context", False)
        self.title_var.set(self.use_title_context)
        self.max_chunk_tokens = profile.get("max_chunk_tokens", 2000)
        self.use_structured_output = profile.get("use_structured_output", False)
        self.structured_var.set(self.use_structured_output)
        self._user_edited_prompt = False
        self._reset_to_default_prompt()
        self.status_label.config(text=f"✅ Profil '{name}' geladen")

    def _update_profile_menu(self) -> None:
        """Aktualisiert das Profil-Menü mit den verfügbaren Profilen."""
        if not hasattr(self, "profile_menu") or self.profile_menu is None:
            return
        self.profile_menu.delete(0, "end")
        for name in sorted(self._profiles.keys()):
            self.profile_menu.add_command(
                label=name,
                command=lambda n=name: self._load_profile(n),
            )
        if self._profiles:
            self.profile_menu.add_separator()
        self.profile_menu.add_command(
            label="➕ Neues Profil speichern",
            command=self._save_current_profile,
        )
        if self._profiles:
            self.profile_menu.add_command(
                label="🗑️ Profil löschen",
                command=self._delete_profile,
            )

    def _delete_profile(self) -> None:
        """Löscht ein benutzerdefiniertes Profil."""
        names = sorted(self._profiles.keys())
        if not names:
            return
        name = simpledialog.askstring(
            "Profil löschen",
            f"Welches Profil löschen?\n{', '.join(names)}",
            parent=self.dialog,
        )
        if name and name in self._profiles:
            del self._profiles[name]
            self._save_profiles()
            self._update_profile_menu()
            self.status_label.config(text=f"🗑️ Profil '{name}' gelöscht")

    def _load_user_templates(self) -> None:
        """Lädt benutzerdefinierte Prompt-Vorlagen."""
        path = PlatformUtils.get_platform_config_dir() / self.TEMPLATES_FILENAME
        if path.exists():
            try:
                with open(path, encoding="utf-8") as f:
                    self._user_templates = json.load(f)
            except Exception as e:
                log_debug("summarize", f"Vorlagen-Datei beschädigt: {e}")
                self._user_templates = {}
        else:
            self._user_templates = {}
        for k, v in list(self._user_templates.items()):
            if isinstance(v, str):
                self._user_templates[k] = {"text": v, "category": ""}
            elif not isinstance(v, dict):
                del self._user_templates[k]

    def _save_user_templates(self) -> None:
        """Speichert benutzerdefinierte Prompt-Vorlagen persistent."""
        path = PlatformUtils.get_platform_config_dir() / self.TEMPLATES_FILENAME
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(self._user_templates, f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"Could not save templates: {e}")

    def _build_template_list(self) -> None:
        """Erstellt die kombinierte Liste aller verfügbaren Vorlagen."""
        predefined = list(self.TEMPLATES.keys())
        user = sorted(self._user_templates.keys())
        combined = predefined[:]
        for name in user:
            if name not in combined:
                combined.append(name)
        self._template_names = combined

    def _get_template_prompt(self, name: str) -> str:
        """Gibt den Prompt-Text für eine Vorlage zurück."""
        if name in self._user_templates:
            entry = self._user_templates[name]
            return entry["text"] if isinstance(entry, dict) else entry
        return self.TEMPLATES.get(name, "")

    def _get_template_category(self, name: str) -> str:
        """Gibt die Kategorie einer Vorlage zurück."""
        if name in self._user_templates:
            entry = self._user_templates[name]
            return entry.get("category", "") if isinstance(entry, dict) else ""
        return ""

    def _save_current_as_template(self) -> None:
        """Speichert den aktuellen Prompt als neue Vorlage."""
        if not hasattr(self, "prompt_text") or not self.prompt_text.winfo_exists():
            return
        cur = self.prompt_text.get("1.0", "end-1c").strip()
        if not cur:
            self.status_label.config(text="❌ Prompt ist leer")
            return
        name = self.template_var.get().strip()
        if not name or (name in self.TEMPLATES and name not in self._user_templates):
            name = simpledialog.askstring(
                "Vorlage speichern",
                "Name:",
                parent=self.dialog,
            )
        if not name:
            return
        cat = (
            simpledialog.askstring("Kategorie", "(optional):", parent=self.dialog) or ""
        )
        self._user_templates[name] = {"text": cur, "category": cat}
        self._save_user_templates()
        self._build_template_list()
        self.template_combo["values"] = self._template_names
        self.template_var.set(name)
        self.status_label.config(text=f"✅ Vorlage '{name}' gespeichert")

    def _delete_current_template(self) -> None:
        """Löscht eine benutzerdefinierte Vorlage."""
        name = self.template_var.get().strip()
        if not name or name not in self._user_templates:
            self.status_label.config(text="❌ Nur eigene Vorlagen löschbar")
            return
        if DarkMessageBox.askyesno(
            "Löschen",
            f"'{name}' wirklich löschen?",
            parent=self.dialog,
        ):
            del self._user_templates[name]
            self._save_user_templates()
            self._build_template_list()
            self.template_combo["values"] = self._template_names
            self.template_var.set("")
            self.status_label.config(text=f"🗑️ '{name}' gelöscht")

    def _load_template(self) -> None:
        """Lädt die ausgewählte Vorlage in den Prompt.
        Bei manuell bearbeitetem Prompt wird der Benutzer gefragt.
        """
        name = self.template_var.get().strip()
        if not name:
            return

        if self._user_edited_prompt:
            current_prompt = self.prompt_text.get("1.0", "end-1c").strip()
            template_prompt = self._get_template_prompt(name)
            if current_prompt != template_prompt:
                if not DarkMessageBox.askyesno(
                    "Vorlage anwenden?",
                    "Sie haben den Prompt manuell bearbeitet. Möchten Sie ihn durch die ausgewählte Vorlage ersetzen?",
                    parent=self.dialog,
                ):
                    self.status_label.config(
                        text="ℹ️ Vorlage nicht angewendet (Benutzerabbruch)",
                    )
                    return

        prompt = self._get_template_prompt(name)
        if not prompt:
            self.status_label.config(text=f"❌ '{name}' nicht gefunden")
            return

        if not hasattr(self, "prompt_text") or not self.prompt_text.winfo_exists():
            return

        self.prompt_text.delete("1.0", "end")
        self.prompt_text.insert("1.0", prompt)
        self._user_edited_prompt = False
        self._update_preview()
        self.status_label.config(text=f"✅ '{name}' geladen")

    def _on_drop(self, event) -> None:
        """Behandelt Drag&Drop von Dateien.
        Erlaubt .txt, .md, .log, .srt, .vtt.
        """
        if not self._dnd_available:
            return
        try:
            files = self.dialog.tk.splitlist(event.data)
        except Exception:
            data = getattr(event, "data", "")
            files = [data.strip("{}")] if data else []
        if not files:
            return
        path = files[0]
        if not os.path.isfile(path):
            self.status_label.config(text="❌ Keine gültige Datei")
            return
        allowed_extensions = (".txt", ".md", ".log", ".srt", ".vtt")
        if not path.lower().endswith(allowed_extensions):
            self.status_label.config(
                text=f"❌ Nur {', '.join(allowed_extensions)} erlaubt",
            )
            return
        self._load_transcript_from_file(path)

    def _load_saved_transcript(self) -> None:
        """Öffnet einen Dateidialog und lädt eine Transkriptionsdatei."""
        from tkinter import filedialog

        filetypes = [
            ("Text files", "*.txt"),
            ("Markdown", "*.md"),
            ("Log files", "*.log"),
            ("SRT subtitles", "*.srt"),
            ("VTT subtitles", "*.vtt"),
            ("All files", "*.*"),
        ]
        path = filedialog.askopenfilename(
            title="Transkription laden",
            filetypes=filetypes,
            parent=self.dialog,
        )
        if not path:
            return

        try:
            with open(path, encoding="utf-8") as f:
                content = f.read()
        except UnicodeDecodeError:
            for enc in ("utf-8-sig", "latin-1", "cp1252"):
                try:
                    with open(path, encoding=enc) as f:
                        content = f.read()
                    break
                except UnicodeDecodeError:
                    continue
            else:
                DarkMessageBox.showerror(
                    "Fehler",
                    f"Konnte Datei nicht lesen: {path}",
                    parent=self.dialog,
                )
                return
        except Exception as e:
            DarkMessageBox.showerror(
                "Fehler",
                f"Fehler beim Lesen der Datei:\n{e}",
                parent=self.dialog,
            )
            return

        title, text = self._parse_transcript_content(content)
        if not text:
            self.status_label.config(text="❌ Kein Transkriptionstext in der Datei")
            return

        self._apply_loaded_transcript(title, text)

    def _load_transcript_from_file(self, path: str) -> None:
        """Lädt eine Transkriptionsdatei mit erweiterter Encoding‑Fallback‑Liste."""
        content = None
        encodings = [
            "utf-8",
            "utf-8-sig",
            "latin-1",
            "cp1252",
            "utf-16",
            "utf-32",
            "ascii",
        ]
        last_error = None
        for enc in encodings:
            try:
                with open(path, encoding=enc) as f:
                    content = f.read()
                break
            except (UnicodeDecodeError, UnicodeError) as e:
                last_error = e
                continue
            except Exception as e:
                DarkMessageBox.showerror("Fehler", str(e), parent=self.dialog)
                return
        if content is None:
            DarkMessageBox.showerror(
                "Fehler",
                f"Keine lesbaren Textdaten in '{os.path.basename(path)}'.\n"
                f"Letzter Fehler: {last_error}",
                parent=self.dialog,
            )
            return
        title, text = self._parse_transcript_content(content)
        if not text:
            self.status_label.config(text="❌ Kein Transkriptionstext")
            return
        self._apply_loaded_transcript(title, text)

    def _parse_transcript_content(self, content: str) -> tuple[str, str]:
        """Extrahiert Titel und Transkriptionstext aus einer Datei."""
        title = ""
        text = content.strip()
        if "=== STREAM INFORMATION ===" in content:
            parts = re.split(r"=== (?:TRANSCRIPT|TRANSLATION) ===", content, maxsplit=1)
            info = parts[0]
            m = re.search(r"Title:\s*(.+)", info)
            if m:
                title = m.group(1).strip()
            if len(parts) > 1:
                text = parts[1].strip()
        return title, text

    def _apply_loaded_transcript(self, title: str, text: str) -> None:
        """Wendet einen geladenen Transkriptionstext an."""
        if title:
            self.stream_title = title
            self.title_var.set(True)
            self.use_title_context = True
        else:
            self.stream_title = ""
            self.use_title_context = False
        self.text = text
        self._user_edited_prompt = False
        self._update_preview()
        self.status_label.config(
            text=f"✅ Geladen ({len(text):,} Zeichen)"
            + (f" – {title[:60]}…" if title else ""),
        )

    def _set_temperature_preset(self, temp: float) -> None:
        """Setzt die Temperatur auf einen vordefinierten Wert."""
        self.temperature = temp
        self.temp_var.set(temp)

    def _update_preview(self) -> None:
        """Aktualisiert die Vorschau des effektiven Prompts."""
        if self._user_edited_prompt and hasattr(self, "prompt_text"):
            effective = self.prompt_text.get("1.0", "end-1c")
        else:
            base = self.SUMMARY_LANGUAGE_PROMPTS.get(
                self.language,
                self.SUMMARY_LANGUAGE_PROMPTS["Deutsch"],
            )
            style = self.TEMPLATES.get(
                self.style,
                self.TEMPLATES["Kompakt (3-5 Sätze)"],
            )
            if self.use_title_context and self.stream_title:
                base = f"Titel: {self.stream_title}\n\n{base}"
            effective = f"{base}\n\n{style}"
        if hasattr(self, "preview_text") and self.preview_text.winfo_exists():
            self.preview_text.config(state="normal")
            self.preview_text.delete("1.0", "end")
            self.preview_text.insert("1.0", effective)
            self.preview_text.config(state="disabled")
        self._schedule_token_update()

    def _schedule_token_update(self) -> None:
        """Plant ein verzögertes Token-Update (Debounce)."""
        if self._token_debounce_id is not None:
            self.dialog.after_cancel(self._token_debounce_id)
        self._token_debounce_id = self.dialog.after(300, self._do_token_update)

    def _do_token_update(self) -> None:
        """Führt das Token-Update durch."""
        self._token_debounce_id = None
        if not hasattr(self, "preview_text") or not self.preview_text.winfo_exists():
            return
        effective = self.preview_text.get("1.0", "end-1c")
        total_text = effective + "\n\n" + self.text
        tokens = self._estimate_tokens(total_text)
        limit = self._get_model_context_limit()
        self._update_context_bar(tokens, limit)
        if hasattr(self, "token_label"):
            if tokens <= limit * 0.8:
                col = CURRENT_THEME.SUCCESS
            elif tokens <= limit:
                col = CURRENT_THEME.WARNING
            else:
                col = CURRENT_THEME.ERROR
            self.token_label.config(text=f"📊 Token: {tokens}/{limit}", fg=col)

    def _update_context_bar(self, tokens: int, limit: int) -> None:
        """Aktualisiert die visuelle Kontext-Anzeige."""
        if not hasattr(self, "context_bar") or self.context_bar is None:
            return
        pct = min(1.0, tokens / max(limit, 1))
        if pct <= 0.5:
            color = "#238636"
        elif pct <= 0.8:
            color = "#d29922"
        elif pct <= 1.0:
            color = "#f85149"
        else:
            color = "#ff00ff"
        self.context_bar.config(width=int(pct * 200), bg=color)
        if hasattr(self, "context_label"):
            self.context_label.config(text=f"{tokens} / {limit} Tokens ({pct:.0%})")

    def _update_readability_metrics(self, text: str) -> None:
        """Aktualisiert die Lesbarkeitsmetriken (Flesch-Index, etc.)."""
        if not hasattr(self, "metrics_label") or not text:
            return
        sentences = self._split_sentences(text)
        words = text.split()
        wc = len(words)
        sc = max(1, len(sentences))
        avg = wc / sc
        syllables = sum(self._count_syllables(w) for w in words)
        flesch = max(0, 180 - avg - (syllables * 60 / max(1, wc)))
        rt = max(1, wc // 200)

        if flesch >= 60:
            level = "sehr leicht"
        elif flesch >= 50:
            level = "leicht"
        elif flesch >= 30:
            level = "mittelschwer"
        elif flesch >= 0:
            level = "schwer"
        else:
            level = "sehr schwer"

        msg = (
            f"📊 {wc} Wörter | {sc} Sätze | ⌀ {avg:.1f} W/Satz | "
            f"📖 Flesch: {flesch:.0f} ({level}) | ⏱️ ~{rt}m"
        )
        self.metrics_label.config(text=msg)

    @staticmethod
    def _count_syllables(word: str) -> int:
        """Zählt die Silben eines Wortes (heuristisch)."""
        word = word.lower()
        cnt = 0
        vowels = "aeiouyäöü"
        prev = False
        for ch in word:
            is_v = ch in vowels
            if is_v and not prev:
                cnt += 1
            prev = is_v
        return max(1, cnt)

    def _clear_history(self) -> None:
        """Löscht den gesamten Zusammenfassungsverlauf."""
        if not self._history:
            return
        if DarkMessageBox.askyesno(
            "Verlauf löschen",
            "Möchten Sie den gesamten Verlauf wirklich löschen?",
            parent=self.dialog,
        ):
            self._history.clear()
            self._save_history()
            self._update_history_combobox()
            self.status_label.config(text="🗑️ Verlauf gelöscht")

    def _auto_regenerate(
        self,
        summary: str,
        prompt: str,
        temperature: float,
        min_word_gain: float = 1.2,
        max_attempts: int = 1,
    ) -> str | None:
        """Versucht, eine zu kurze oder qualitativ unzureichende Zusammenfassung
        durch einen zweiten, kreativeren Durchlauf mit höherer Temperatur zu
        verbessern.
        """
        if max_attempts <= 0:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate deaktiviert (max_attempts=%d)",
                    max_attempts,
                )
            return None

        if not summary or not summary.strip():
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", "Auto‑Regenerate übersprungen: summary ist leer")
            return None

        effective_min_gain = max(1.0, min_word_gain)
        original_words = len(summary.split())
        original_chars = len(summary)
        total_text_words = len(self.text.split()) if self.text else 0

        if original_words >= 50:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Zusammenfassung bereits lang (%d Wörter)",
                    original_words,
                )
            return None

        if total_text_words > 0 and original_words / total_text_words > 0.1:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Zusammenfassung bereits ausführlich "
                    "(%.1f%% des Originals, %d Wörter)",
                    (original_words / total_text_words) * 100,
                    original_words,
                )
            return None

        is_too_short = original_words < 20
        is_text_short = total_text_words < 100
        if not is_too_short and not is_text_short:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Keine Verbesserung nötig "
                    "(original_words=%d, text_words=%d)",
                    original_words,
                    total_text_words,
                )
            return None

        if DEBUG_LEVEL >= 2:
            log_debug(
                "summarize",
                "Auto‑Regenerate gestartet (original: %d Wörter, %d Zeichen, "
                "Textlänge: %d Wörter, min_gain=%.2f, max_attempts=%d)",
                original_words,
                original_chars,
                total_text_words,
                effective_min_gain,
                max_attempts,
            )

        refine_method = getattr(self, "_summarize_refine", None)
        mapreduce_method = getattr(self, "_summarize_map_reduce", None)

        if refine_method is None and mapreduce_method is None:
            logger.error(
                "_auto_regenerate: Weder _summarize_refine noch _summarize_map_reduce verfügbar",
            )
            return None

        if self.strategy == "Genau (schrittweise)":
            target_method = (
                refine_method if refine_method is not None else mapreduce_method
            )
        else:
            target_method = (
                mapreduce_method if mapreduce_method is not None else refine_method
            )

        if target_method is None:
            logger.error(
                "_auto_regenerate: Keine geeignete Summarizer‑Methode gefunden",
            )
            return None

        sig = inspect.signature(target_method)
        try:
            bound = sig.bind(prompt)
            bound.apply_defaults()
            supports_temperature = "temperature" in sig.parameters
        except TypeError:
            params = list(sig.parameters.keys())
            supports_temperature = "temperature" in params

        temperatures = []
        if max_attempts >= 1:
            temperatures.append(0.7)
        if max_attempts >= 2:
            temperatures.append(0.8)
        if max_attempts >= 3:
            temperatures.append(0.9)
        temperatures = temperatures[:max_attempts]

        if not temperatures:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Keine Temperaturen für max_attempts=%d",
                    max_attempts,
                )
            return None

        best_result = None
        best_word_count = original_words

        for attempt, current_temp in enumerate(temperatures, start=1):
            if self._request_cancel.is_set():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "Auto‑Regenerate abgebrochen (cancel_event) bei Versuch %d",
                        attempt,
                    )
                break

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate Versuch %d/%d mit Temperatur %.1f",
                    attempt,
                    len(temperatures),
                    current_temp,
                )

            try:
                if supports_temperature:
                    bound = sig.bind(prompt)
                    bound.apply_defaults()
                    bound.arguments["temperature"] = current_temp
                    regenerated = target_method(*bound.args, **bound.kwargs)
                else:
                    regenerated = target_method(prompt)

                if not regenerated or not isinstance(regenerated, str):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  Versuch %d lieferte leere oder ungültige Antwort",
                            attempt,
                        )
                    continue

                regenerated = regenerated.strip()
                if not regenerated:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  Versuch %d lieferte leere Antwort (nach strip)",
                            attempt,
                        )
                    continue

                new_word_count = len(regenerated.split())
                gain_ratio = new_word_count / max(original_words, 1)

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "  Versuch %d: %d Wörter (Gewinnfaktor %.2f)",
                        attempt,
                        new_word_count,
                        gain_ratio,
                    )

                if gain_ratio >= effective_min_gain:
                    best_result = regenerated
                    best_word_count = new_word_count
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "summarize",
                            "  ✅ Verbesserung akzeptiert (%.1f → %d Wörter, Faktor %.2f >= %.2f)",
                            original_words,
                            new_word_count,
                            gain_ratio,
                            effective_min_gain,
                        )
                    break
                if new_word_count > best_word_count:
                    best_result = regenerated
                    best_word_count = new_word_count
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  ⏺ Zwischenergebnis gespeichert (%d Wörter, bisher best: %d)",
                            new_word_count,
                            best_word_count,
                        )
                elif DEBUG_LEVEL >= 4:
                    log_debug(
                        "summarize",
                        "  Versuch %d lieferte keine Verbesserung (%d <= %d Wörter)",
                        attempt,
                        new_word_count,
                        best_word_count,
                    )

            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "  ❌ Auto‑Regenerate Versuch %d fehlgeschlagen: %s",
                        attempt,
                        str(e)[:100],
                    )
                continue

        if best_result and best_word_count > original_words:
            improvement_percent = int(
                (best_word_count / max(original_words, 1) - 1) * 100,
            )
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "summarize",
                    "✅ Auto‑Regenerate erfolgreich: %d → %d Wörter (Verbesserung um %d%%)",
                    original_words,
                    best_word_count,
                    improvement_percent,
                )
            return best_result

        if DEBUG_LEVEL >= 3:
            log_debug(
                "summarize",
                "❌ Auto‑Regenerate keine Verbesserung (bester Versuch: %d Wörter, original: %d)",
                best_word_count,
                original_words,
            )
        return None

    @contextmanager
    def _ollama_usage(self, timeout: float | None = None) -> Generator[Any, None, None]:
        """Kontextmanager für die Nutzung des OllamaSummarizers mit optionalem Timeout."""
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS

        if _debug:
            log_debug(
                "summarize",
                "_ollama_usage: Eintritt, aktuelle Nutzerzahl = %d",
                self._ollama_usage_count,
            )

        summarizer = None
        try:
            summarizer = self._get_ollama_summarizer()
        except Exception as e:
            if _debug:
                log_exception(
                    "summarize",
                    "_get_ollama_summarizer fehlgeschlagen",
                    e,
                    level="error",
                )

            if isinstance(e, (ConnectionError, TimeoutError, RuntimeError)):
                raise
            raise RuntimeError(
                f"Konnte OllamaSummarizer nicht bereitstellen: {e}",
            ) from e

        try:
            if _debug:
                log_debug(
                    "summarize",
                    "_ollama_usage: Gebe Summarizer aus (Nutzer = %d)",
                    self._ollama_usage_count,
                )
            if timeout is not None and hasattr(summarizer, "set_timeout"):
                summarizer.set_timeout(timeout)
            yield summarizer
        except Exception as e:
            if _debug:
                log_exception(
                    "summarize",
                    "Fehler im _ollama_usage-Block",
                    e,
                    level="error",
                )
            raise
        finally:
            self._ollama_usage_release()
            if _debug:
                log_debug(
                    "summarize",
                    "_ollama_usage: Verlassen, neue Nutzerzahl = %d",
                    self._ollama_usage_count,
                )

    def _get_ollama_summarizer(self) -> Any:
        """Gibt die **eine** `OllamaSummarizer`‑Instanz zurück und registriert
        eine Nutzung, indem der interne Zähler erhöht wird.
        Thread-sicher durch Verwendung von `_ollama_usage_lock`.
        """
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS

        with self._ollama_usage_lock:
            if self._ollama_instance is not None:
                try:
                    now = time.monotonic()

                    if now - self._ollama_last_health_check > 30.0:
                        if hasattr(self._ollama_instance, "is_server_reachable"):
                            reachable = self._ollama_instance.is_server_reachable()
                            self._ollama_last_health_check = now
                            self._ollama_health_status = reachable
                            if not reachable:
                                if _debug:
                                    log_debug(
                                        "summarize",
                                        "Gecachte Ollama‑Instanz nicht erreichbar – erstelle neue",
                                    )
                                self._ollama_instance = None
                        else:
                            self._ollama_last_health_check = now
                except Exception as e:
                    if _debug:
                        log_debug(
                            "summarize",
                            f"Health‑Check der gecachten Instanz fehlgeschlagen: {e} – erstelle neue",
                        )
                    self._ollama_instance = None

            if self._ollama_instance is None:
                cls = self._ollama_class
                if cls is None:
                    raise RuntimeError(
                        "OllamaSummarizer ist nicht verfügbar. "
                        "Stellen Sie sicher, dass das Modul geladen ist.",
                    )

                adv = self.gui.advanced_settings
                host = getattr(adv, "ollama_host", "http://localhost:11434")
                timeout = getattr(adv, "ollama_timeout", 90)
                keep_alive = getattr(adv, "ollama_keep_alive", 300)
                fallback_hosts = getattr(adv, "ollama_fallback_hosts", [])

                max_parallel = max(2, min(10, self.max_parallel_requests * 2))

                system_prompt = (
                    f"Du bist ein hilfreicher Assistent, der Video-Transkriptionen analysiert. "
                    f"Deine Aufgabe ist es, den Inhalt eines Video-Clips auf {self.language} "
                    f"so zusammenzufassen, als würdest du einem Freund das Video beschreiben. "
                    f"Verwende Formulierungen wie 'Das Video zeigt...', 'In diesem Clip wird erklärt...', "
                    f"'Der Sprecher sagt...'. Vermeide Bezüge auf 'Text' oder 'dieser Text'. "
                    f"Antworte ausschließlich auf {self.language} und ohne Zeichen aus anderen Schriftsystemen."
                )

                if _debug:
                    log_debug(
                        "summarize",
                        "Erstelle neue OllamaSummarizer‑Instanz mit: "
                        "model=%s, host=%s, timeout=%d, keep_alive=%d, max_parallel=%d",
                        self.model,
                        host,
                        timeout,
                        keep_alive,
                        max_parallel,
                    )

                try:
                    self._ollama_instance = cls(
                        self.gui,
                        model=self.model,
                        host=host,
                        timeout=timeout,
                        cache_manager=None,
                        system_prompt=system_prompt,
                        max_parallel_requests=max_parallel,
                        keep_alive=keep_alive,
                        fallback_hosts=fallback_hosts,
                    )
                    self._ollama_health_status = True
                except Exception as e:
                    raise RuntimeError(
                        f"Konnte OllamaSummarizer nicht initialisieren: {e}\n"
                        f"Prüfen Sie, ob Ollama läuft und unter {host} erreichbar ist.\n"
                        f"Tipp: Führen Sie 'ollama serve' in einem Terminal aus.",
                    ) from e

                if _debug:
                    log_debug(
                        "summarize",
                        f"✅ Neue OllamaSummarizer‑Instanz erstellt (usage_count={
                            self._ollama_usage_count
                        })",
                    )

            self._ollama_usage_count += 1
            if _debug and DEBUG_LEVEL >= 4:
                log_debug(
                    "summarize",
                    f"_ollama_usage_count erhöht → {self._ollama_usage_count}",
                )

            return self._ollama_instance

    def _is_ollama_healthy(self) -> bool:
        """Prüft, ob die gecachte Ollama‑Instanz noch erreichbar ist."""
        if self._ollama_instance is None:
            return False

        now = time.monotonic()
        if not hasattr(self, "_ollama_last_health_check"):
            self._ollama_last_health_check = 0.0

        if now - self._ollama_last_health_check < 30.0:
            return getattr(self, "_ollama_health_status", True)

        try:
            reachable = self._ollama_instance.is_server_reachable()
            self._ollama_health_status = reachable
            self._ollama_last_health_check = now
            return reachable
        except Exception:
            self._ollama_health_status = False
            self._ollama_last_health_check = now
            return False

    def _ollama_usage_release(self) -> None:
        with self._ollama_usage_lock:
            if self._ollama_usage_count > 0:
                self._ollama_usage_count -= 1
            else:
                log_debug(
                    "summarize",
                    "WARN: _ollama_usage_count war bereits 0 beim Release",
                )
                self._ollama_usage_count = 0

    def _get_ollama_config(self) -> dict[str, Any]:
        """Holt die Ollama‑Konfiguration aus den AdvancedSettings."""
        if hasattr(self, "_advanced_settings") and self._advanced_settings is not None:
            adv = self._advanced_settings
        else:
            adv = self.gui.advanced_settings

        return {
            "model": getattr(adv, "ollama_model", "llama3.1:8b"),
            "host": getattr(adv, "ollama_host", "http://localhost:11434"),
            "timeout": getattr(adv, "ollama_timeout", 90),
            "keep_alive": getattr(adv, "ollama_keep_alive", 300),
            "fallback_hosts": getattr(adv, "ollama_fallback_hosts", []),
            "max_parallel": max(2, min(10, self.max_parallel_requests * 2)),
        }

    def _format_error_message(self, exc: Exception, context: str = "") -> str:
        """Formatiert eine Fehlermeldung mit Kontext für Logging und UI."""
        exc_type = type(exc).__name__
        exc_msg = str(exc)

        if len(exc_msg) > 150:
            exc_msg = exc_msg[:150] + "..."

        if context:
            return f"[{context}] {exc_type}: {exc_msg}"
        return f"{exc_type}: {exc_msg}"

    def _safe_widget_update(self, widget_name: str, **kwargs) -> None:
        """Aktualisiert ein Widget sicher (prüft, ob es existiert).

        Args:
            widget_name: Name des Widget-Attributs (z.B. "status_label").
            **kwargs: Konfigurationsparameter für das Widget.

        """
        if self._destroyed:
            return
        widget = getattr(self, widget_name, None)
        if widget is not None:
            try:
                if widget.winfo_exists():
                    widget.config(**kwargs)
            except (tk.TclError, AttributeError, RuntimeError):
                pass

    def _get_system_prompt(self) -> str:
        """Generiert den System‑Prompt für den Summarizer – nur einmal."""
        if not hasattr(self, "_cached_system_prompt"):
            self._cached_system_prompt = (
                f"Du bist ein hilfreicher Assistent, der Video-Transkriptionen analysiert. "
                f"Deine Aufgabe ist es, den Inhalt eines Video-Clips auf {self.language} "
                f"so zusammenzufassen, als würdest du einem Freund das Video beschreiben. "
                f"Verwende Formulierungen wie 'Das Video zeigt...', 'In diesem Clip wird erklärt...', "
                f"'Der Sprecher sagt...'. Vermeide Bezüge auf 'Text' oder 'dieser Text'. "
                f"Antworte ausschließlich auf {self.language} und ohne Zeichen aus anderen Schriftsystemen."
            )
        return self._cached_system_prompt

    def _reset_ollama_instance(self) -> None:
        """Entlädt und verwirft die aktuelle OllamaSummarizer‑Instanz sofort."""
        with self._ollama_usage_lock:
            if self._ollama_instance is not None:
                try:
                    self._ollama_instance.stop()
                except Exception as e:
                    logger.debug("Ignored exception in stop(): %s", e, exc_info=True)
                try:
                    self._ollama_instance.dispose()
                except Exception as e:
                    logger.debug("Ignored exception in dispose(): %s", e, exc_info=True)
                finally:
                    self._ollama_instance = None
                    self._ollama_usage_count = 0
                    self._ollama_health_status = False
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "OllamaSummarizer‑Instanz zurückgesetzt (reset)",
                    )

    def _summarize_chunk(
        self,
        chunk: str,
        prompt: str,
        temperature: float | None = None,
        chunk_callback: Callable[[str], None] | None = None,
        abort_event: threading.Event | None = None,
        max_retries: int = 3,
        retry_delay_base: float = 1.0,
        timeout_seconds: float = 120.0,
    ) -> str | None:
        """Fasst einen einzelnen Text‑Chunk mit dem Ollama‑Modell zusammen."""
        if not chunk or not isinstance(chunk, str) or not chunk.strip():
            log_debug("summarize", "Leerer Chunk – übersprungen")
            return None

        clean_chunk = chunk.strip()
        if len(clean_chunk) < 10:
            log_debug(
                "summarize",
                f"Chunk zu kurz ({len(clean_chunk)} Zeichen) – übersprungen",
            )
            return None

        MAX_CHUNK_LENGTH = 50000
        if len(clean_chunk) > MAX_CHUNK_LENGTH:
            log_debug(
                "summarize",
                f"Chunk sehr groß ({len(clean_chunk)} Zeichen) – kürze auf {
                    MAX_CHUNK_LENGTH
                }",
            )
            clean_chunk = clean_chunk[:MAX_CHUNK_LENGTH]

        cache_key = self._get_chunk_cache_key(clean_chunk, prompt, temperature)
        try:
            cached = self._chunk_cache.get(cache_key)
            if cached is not None:
                log_debug(
                    "summarize",
                    f"Chunk aus Cache geladen (Länge: {len(cached)})",
                )
                return cached
        except Exception as e:
            log_debug("summarize", f"Cache-Zugriff fehlgeschlagen: {e}")

        if abort_event and abort_event.is_set():
            log_debug("summarize", "Abbruch vor Verarbeitung erkannt")
            return None

        effective_temp = temperature if temperature is not None else self.temperature

        ollama_cls = self._ollama_class
        timeout_exc = getattr(ollama_cls, "TimeoutError", None) if ollama_cls else None
        server_exc = (
            getattr(ollama_cls, "ServerUnreachableError", None) if ollama_cls else None
        )
        rate_exc = getattr(ollama_cls, "RateLimitError", None) if ollama_cls else None
        model_exc = (
            getattr(ollama_cls, "ModelNotFoundError", None) if ollama_cls else None
        )
        validation_exc = (
            getattr(ollama_cls, "ValidationError", None) if ollama_cls else None
        )

        last_exception = None

        for attempt in range(max_retries + 1):
            if abort_event and abort_event.is_set():
                log_debug("summarize", f"Abbruch während Retry (Versuch {attempt + 1})")
                return None

            current_timeout = timeout_seconds + attempt * 10

            try:
                log_debug(
                    "summarize",
                    f"Starte Chunk‑Zusammenfassung (Versuch {attempt + 1}/{max_retries + 1})",
                )
                start_time = time.perf_counter()

                with self._ollama_usage(timeout=current_timeout) as summarizer:
                    result = summarizer.summarize_sync(
                        text=clean_chunk,
                        prompt=prompt,
                        temperature=effective_temp,
                        chunk_callback=chunk_callback,
                        cancel_event=abort_event,
                        use_cache=False,
                        options=None,
                        output_format=None,
                        force_refresh=False,
                    )

                if result and isinstance(result, str) and result.strip():
                    elapsed = time.perf_counter() - start_time
                    log_debug(
                        "summarize",
                        f"Chunk erfolgreich in {elapsed:.2f}s (Länge: {len(result)})",
                    )
                    self._cache_chunk_result(cache_key, result)
                    return result

                log_debug("summarize", f"Leeres Ergebnis (Versuch {attempt + 1})")
                if attempt < max_retries:
                    delay = min(10.0, retry_delay_base * (2**attempt))
                    log_debug(
                        "summarize",
                        f"Wiederhole in {delay:.1f}s (abbruchbar)...",
                    )
                    if abort_event:
                        abort_event.wait(delay)
                        if abort_event.is_set():
                            log_debug(
                                "summarize",
                                f"Abbruch nach Wartezeit (Versuch {attempt + 1})",
                            )
                            return None
                    else:
                        time.sleep(delay)
                    continue
                return None

            except Exception as e:
                last_exception = e

                if model_exc and isinstance(e, model_exc):
                    log_debug("summarize", f"Modell nicht gefunden: {e}")
                    self._set_status(
                        f"❌ Modell '{self.model}' nicht verfügbar – bitte installieren",
                    )
                    raise
                if validation_exc and isinstance(e, validation_exc):
                    log_debug("summarize", f"Validierungsfehler: {e}")
                    raise

                is_retryable = False
                if timeout_exc and isinstance(e, timeout_exc):
                    is_retryable = True
                    log_debug("summarize", f"Timeout (Versuch {attempt + 1}): {e}")
                elif server_exc and isinstance(e, server_exc):
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Server nicht erreichbar (Versuch {attempt + 1}): {e}",
                    )
                elif rate_exc and isinstance(e, rate_exc):
                    is_retryable = True
                    log_debug("summarize", f"Rate‑Limit (Versuch {attempt + 1}): {e}")
                else:
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Unerwarteter Fehler (Versuch {attempt + 1}): {e}",
                    )

                if is_retryable and attempt < max_retries:
                    delay = min(
                        15.0,
                        retry_delay_base
                        * (2**attempt)
                        * (2 if rate_exc and isinstance(e, rate_exc) else 1),
                    )
                    log_debug(
                        "summarize",
                        f"Wiederhole in {delay:.1f}s (abbruchbar)...",
                    )
                    if abort_event:
                        abort_event.wait(delay)
                        if abort_event.is_set():
                            log_debug(
                                "summarize",
                                f"Abbruch nach Wartezeit (Versuch {attempt + 1})",
                            )
                            return None
                    else:
                        time.sleep(delay)
                    continue
                raise

        if last_exception:
            log_debug(
                "summarize",
                f"Alle {max_retries + 1} Versuche fehlgeschlagen: {last_exception}",
            )
        return None

    def _get_chunk_cache_key(
        self,
        chunk: str,
        prompt: str,
        temperature: float | None,
    ) -> str:
        """Erzeugt einen eindeutigen Cache‑Schlüssel für einen Chunk."""
        temp_str = f"{temperature:.2f}" if temperature is not None else "default"
        raw = f"{chunk}|{prompt}|{self.model}|{temp_str}"
        return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()

    def _cache_chunk_result(self, key: str, result: str) -> None:
        """Speichert ein Chunk‑Ergebnis im Cache (LRU)."""
        if not hasattr(self, "_chunk_cache"):
            self._chunk_cache = self._build_lru_cache(maxsize=200)
        try:
            self._chunk_cache.put(key, result)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "summarize",
                    f"Chunk im Cache gespeichert (Key: {key[:16]}...)",
                )
        except Exception as e:
            log_debug("summarize", f"Cache‑Speicherung fehlgeschlagen: {e}")

    def _process_chunk(
        self,
        idx: int,
        chunk: str,
        prompt: str,
        temperature: float | None = None,
        abort_event: threading.Event | None = None,
        chunk_callback: Callable[[str], None] | None = None,
    ) -> None:
        """Verarbeitet einen einzelnen Text-Chunk im Hintergrund (Summary)."""
        import gc
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", DEBUG_LEVEL)

        MAX_CHUNK_SIZE_DEFAULT = 10000
        SLOW_THRESHOLD_MS = 5000.0
        GC_EVERY_N_CHUNKS = 50
        LOG_EVERY_N_CHUNKS = 5

        def _ld(msg: str, *args: object, **kwargs: object) -> None:
            with contextlib.suppress(Exception):
                logger.debug(f"[summarize] {msg}", *args, **kwargs)

        def _le(msg: str, *args: object, **kwargs: object) -> None:
            with contextlib.suppress(Exception):
                logger.error(f"[summarize] {msg}", *args, **kwargs)

        def _li(msg: str, *args: object, **kwargs: object) -> None:
            with contextlib.suppress(Exception):
                logger.info(f"[summarize] {msg}", *args, **kwargs)

        diag: dict[str, object] = {
            "idx": idx,
            "chunk_size": 0,
            "chunk_size_original": 0,
            "truncated": False,
            "status": "unknown",
            "summarize_ms": 0.0,
            "total_ms": 0.0,
            "summary_len": 0,
            "error": None,
            "aborted": False,
            "abort_reason": None,
        }
        _start_t0 = time.perf_counter()

        if debug_level >= 4:
            _ld(
                f"Chunk {idx} ENTRY "
                f"(thread={threading.current_thread().name}, "
                f"chunk_len={len(chunk) if chunk else 0})"
            )

        def _mark_chunk_done(result_value: str | None) -> tuple[int, int]:
            """Schreibt das Ergebnis und zählt den Chunk. Lock wird hier gehalten."""
            with self._chunks_lock:
                self._chunk_results[idx] = result_value
                self._chunks_processed += 1
                return self._chunks_processed, getattr(self, "_total_chunks", 0)

        def _safe_update_progress() -> None:
            """Ruft _update_progress NIE unter gehaltenem Lock auf."""
            try:
                self._update_progress()
            except Exception as e:
                _le(f"Chunk {idx} _update_progress Fehler: {e}")

        def _persist_diag() -> None:
            with contextlib.suppress(Exception):
                self._last_chunk_diag = diag

        def _finalize_early(status: str, reason: str, error: str | None = None) -> None:
            """Einheitlicher Abschluss für Abort/Invalid-Pfade.

            Markiert den Chunk als abgeschlossen, aktualisiert Progress,
            persistiert die Diagnose. Wird von allen Early-Exits genutzt.
            """
            diag["status"] = status
            diag["abort_reason"] = reason
            if status == "aborted":
                diag["aborted"] = True
            if error is not None:
                diag["error"] = error
            _ld(f"Chunk {idx} früh beendet ({status}/{reason})")
            try:
                _mark_chunk_done(None)
            except Exception as e:
                _le(f"Chunk {idx} konnte Status '{status}' nicht eintragen: {e}")
            _safe_update_progress()
            _persist_diag()

        if abort_event and abort_event.is_set():
            _finalize_early("aborted", "abort_event_early")
            return
        if self._request_cancel.is_set():
            _finalize_early("aborted", "request_cancel_early")
            return

        if not chunk or not isinstance(chunk, str):
            _finalize_early(
                "invalid_chunk",
                "not_a_string",
                error=f"type={type(chunk).__name__}",
            )
            return

        diag["chunk_size_original"] = len(chunk)
        raw_max = getattr(self, "_max_chunk_size", MAX_CHUNK_SIZE_DEFAULT)
        max_chunk_size = (
            raw_max
            if isinstance(raw_max, int) and raw_max > 0
            else MAX_CHUNK_SIZE_DEFAULT
        )

        if len(chunk) > max_chunk_size:
            _ld(
                f"Chunk {idx} zu groß ({len(chunk)} Zeichen), "
                f"kürze auf {max_chunk_size}"
            )
            chunk = chunk[:max_chunk_size]
            diag["truncated"] = True

        diag["chunk_size"] = len(chunk)

        result: str | None = None
        _summarize_t0 = time.perf_counter()

        try:
            if abort_event and abort_event.is_set():
                _finalize_early("aborted", "abort_event_recheck")
                return
            if self._request_cancel.is_set():
                _finalize_early("aborted", "request_cancel_recheck")
                return

            if debug_level >= 3:
                _ld(
                    f"Chunk {idx} START "
                    f"(len={diag['chunk_size']}, "
                    f"truncated={diag['truncated']})"
                )

            result = self._summarize_chunk(
                chunk,
                prompt,
                temperature,
                chunk_callback=chunk_callback,
                abort_event=abort_event,
            )

            diag["status"] = "ok"
            diag["summary_len"] = len(result) if result else 0

        except Exception as e:
            diag["status"] = "error"
            diag["error"] = f"{type(e).__name__}: {str(e)[:200]}"
            _le(f"Chunk {idx} Fehler: {type(e).__name__}: {str(e)[:200]}")
            if debug_level >= 5:
                try:
                    import traceback as _tb

                    _ld(f"Chunk {idx} Traceback:\n{_tb.format_exc()}")
                except Exception:
                    pass
            if abort_event and abort_event.is_set():
                diag["aborted"] = True
                diag["abort_reason"] = "abort_during_summarize"
                _ld(f"Chunk {idx} durch Abbruch beendet")
            result = None

        finally:
            diag["summarize_ms"] = round(
                (time.perf_counter() - _summarize_t0) * 1000, 2
            )

        try:
            chunks_processed, total_chunks = _mark_chunk_done(result)
        except Exception as e:
            _le(f"Chunk {idx} Ergebnis-Eintrag fehlgeschlagen: {e}")
            chunks_processed, total_chunks = -1, -1

        _safe_update_progress()

        if idx > 0 and idx % GC_EVERY_N_CHUNKS == 0:
            try:
                collected = gc.collect()
                if debug_level >= 4:
                    _ld(f"Chunk {idx}: GC durchgeführt ({collected} Objekte)")
            except Exception as e:
                _ld(f"Chunk {idx}: GC fehlgeschlagen: {e}")

        diag["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)
        _persist_diag()

        if idx % LOG_EVERY_N_CHUNKS == 0 and chunks_processed > 0:
            _li(
                f"Progress: {chunks_processed}/{total_chunks} Chunks "
                f"(idx={idx}, status={diag['status']}, "
                f"total={diag['total_ms']:.0f}ms)"
            )

        if diag["total_ms"] > SLOW_THRESHOLD_MS:
            _ld(
                f"Chunk {idx} LANGSAM: "
                f"total={diag['total_ms']:.0f}ms, "
                f"summarize={diag['summarize_ms']:.0f}ms, "
                f"len={diag['chunk_size']}, "
                f"status={diag['status']}"
            )
        elif debug_level >= 4:
            _ld(
                f"Chunk {idx} DONE: "
                f"total={diag['total_ms']:.0f}ms, "
                f"summarize={diag['summarize_ms']:.0f}ms, "
                f"status={diag['status']}, "
                f"summary_len={diag['summary_len']}"
            )

        if debug_level >= 4:
            _ld(f"Chunk {idx} diag={diag}")

    def _update_progress(
        self,
        value: int | None = None,
        label: str | None = None,
        *,
        force: bool = False,
    ) -> None:
        """Aktualisiert die Fortschrittsanzeige (threadsicher, mit Rate‑Limiting)."""
        if not self._is_dialog_alive():
            if self._debug_level >= 4:
                logger.debug(
                    "[_update_progress] Dialog nicht mehr aktiv – Update übersprungen.",
                )
            return

        if value is None:
            try:
                total = getattr(self, "_chunks_total", 0)
                processed = getattr(self, "_chunks_processed", 0)
                if total > 0:
                    value = (processed / total) * 100.0
                else:
                    value = 0.0
            except ZeroDivisionError:
                value = 0.0

        if label is None:
            total = getattr(self, "_chunks_total", 0)
            processed = getattr(self, "_chunks_processed", 0)
            if total > 0:
                label = f"Chunk {processed}/{total}"
            else:
                label = ""

        if not force:
            now = time.time()
            last_update = getattr(self, "_last_progress_update", 0.0)
            interval = getattr(self, "_progress_update_interval", 0.5)

            if now - last_update < interval:
                if getattr(self, "_debug_level", 0) >= 5:
                    logger.debug(
                        f"[_update_progress] Rate‑Limit: "
                        f"{now - last_update:.3f}s < {interval}s – übersprungen.",
                    )
                return

            self._last_progress_update = now

        try:
            clamped_value = int(round(float(value)))
            clamped_value = max(0, min(100, clamped_value))
        except (ValueError, TypeError) as e:
            logger.warning(
                f"[_update_progress] Ungültiger value: {value!r} – Fehler: {e}",
            )
            clamped_value = 0

        clean_label = str(label).strip() if label is not None else ""

        if getattr(self, "_debug_level", 0) >= 3:
            last_value = getattr(self, "_last_reported_progress_value", -1)
            last_label = getattr(self, "_last_reported_progress_label", "")
            if last_value != clamped_value or last_label != clean_label:
                logger.debug(
                    f"[_update_progress] Setze Fortschritt: {clamped_value}% – "
                    f"Label: {clean_label!r}",
                )
                self._last_reported_progress_value = clamped_value
                self._last_reported_progress_label = clean_label

        try:
            self._safe_after(
                0,
                lambda: self._set_progress_gui(clamped_value, clean_label),
            )
        except Exception as e:
            logger.error(
                f"[_update_progress] Fehler beim GUI‑Update: {e}",
                exc_info=True,
            )

    def _summarize_map_reduce(
        self,
        prompt: str,
        temperature: float | None = None,
        *,
        abort_event: threading.Event | None = None,
        chunk_callback: Callable[[str], None] | None = None,
    ) -> str | None:
        """Map‑Reduce‑basierte Zusammenfassung für große Texte."""
        import concurrent.futures
        import time

        log_debug("summarize", "🚀 _summarize_map_reduce START")
        start_total = time.perf_counter()

        temp = temperature if temperature is not None else self.temperature
        effective_abort = abort_event or self._request_cancel
        limit = self._get_model_context_limit()
        max_tok = min(self.max_chunk_tokens, int(limit * 0.6))

        log_debug("summarize", "  limit=%d tokens, max_tok=%d", limit, max_tok)

        chunks = self._split_into_chunks(self.text, max_tok)
        if not chunks:
            log_debug("summarize", "  ❌ Keine Chunks erzeugt")
            self._set_status("⚠️ Kein Text zum Verarbeiten")
            return None

        log_debug("summarize", "  ➜ %d Chunk(s) erzeugt", len(chunks))

        if len(chunks) <= 1:
            log_debug("summarize", "  ➜ Nur ein Chunk – direkte Zusammenfassung")
            return self._summarize_chunk(
                chunks[0] if chunks else self.text,
                prompt,
                temp,
                chunk_callback=chunk_callback,
                abort_event=effective_abort,
            )

        self._chunks_total = len(chunks)
        self._chunk_results = [None] * len(chunks)
        self._chunks_processed = 0
        self._chunk_error_shown = False
        self._chunk_error_count = 0
        self._last_progress_update = 0.0
        self._chunk_times = []

        self._safe_after(0, lambda: self.progress_var.set(0))
        self._safe_after(
            0,
            lambda: self.progress_label.config(text="0% – Vorbereitung..."),
        )

        log_debug("summarize", "  ➜ %d Chunks für Map‑Reduce vorbereitet", len(chunks))

        MAX_TOTAL_TIME = 600.0
        MAX_RETRIES = 2
        RETRY_DELAY_BASE = 0.5

        workers = min(self.max_parallel_requests, max(1, len(chunks) // 2))
        workers = max(1, min(workers, 4))

        executor = None
        futures = {}

        try:
            executor = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
            log_debug(
                "summarize",
                "  🚀 ThreadPoolExecutor gestartet (max_workers=%d)",
                workers,
            )

            for idx, chunk in enumerate(chunks):
                if effective_abort.is_set():
                    log_debug(
                        "summarize",
                        "  ⏹️ Abbruch vor Einreichen von Chunk %d",
                        idx,
                    )
                    break
                log_debug(
                    "summarize",
                    "  📤 Chunk %d/%d eingereicht (Länge=%d)",
                    idx + 1,
                    len(chunks),
                    len(chunk),
                )
                future = executor.submit(
                    self._process_chunk_with_retry,
                    idx,
                    chunk,
                    prompt,
                    temp,
                    effective_abort,
                    max_retries=MAX_RETRIES,
                    retry_delay=RETRY_DELAY_BASE,
                )
                futures[future] = idx

            if not futures:
                log_debug("summarize", "  ❌ Keine Futures – breche ab")
                self._set_status("❌ Keine Chunks zur Verarbeitung")
                return None

            TIMEOUT_PER_FUTURE = 60.0
            total_deadline = time.monotonic() + MAX_TOTAL_TIME

            try:
                for future in concurrent.futures.as_completed(futures, timeout=None):
                    if effective_abort.is_set():
                        log_debug("summarize", "  ⏹️ Abbruch erkannt – breche ab")
                        for f in futures:
                            if not f.done():
                                f.cancel()
                        break

                    if time.monotonic() > total_deadline:
                        log_debug("summarize", "  ⏰ Gesamt‑Timeout überschritten")
                        for f in futures:
                            if not f.done():
                                f.cancel()
                        self._set_status("⏰ Zeitüberschreitung bei Map‑Reduce")
                        break

                    idx = futures.pop(future)
                    try:
                        future.result(timeout=TIMEOUT_PER_FUTURE)
                        log_debug(
                            "summarize",
                            "  ✅ Chunk %d/%d erfolgreich",
                            idx + 1,
                            len(chunks),
                        )
                    except Exception as exc:
                        self._chunk_error_count += 1
                        log_debug(
                            "summarize",
                            "  ❌ Chunk %d/%d fehlgeschlagen: %s",
                            idx + 1,
                            len(chunks),
                            exc,
                        )
                        if not self._chunk_error_shown:
                            self._chunk_error_shown = True
                            self._safe_after(
                                0,
                                lambda: self.status_label.config(
                                    text="⚠️ Einige Chunks fehlgeschlagen – Zusammenfassung evtl. unvollständig",
                                ),
                            )

                    self._update_progress_ui()
                    if not futures:
                        break

            except concurrent.futures.TimeoutError:
                log_debug("summarize", "  ⏰ Gesamt‑Timeout bei as_completed")
                for f in futures:
                    f.cancel()
                futures.clear()
            except Exception as e:
                log_debug("summarize", "  ❌ Fehler beim Sammeln der Ergebnisse: %s", e)
                for f in futures:
                    f.cancel()
                futures.clear()
                raise

            valid = [r for r in self._chunk_results if r is not None]
            log_debug(
                "summarize",
                "  ➜ %d von %d Chunks erfolgreich",
                len(valid),
                len(chunks),
            )
            if not valid:
                self._set_status("❌ Alle Chunks fehlgeschlagen")
                log_debug("summarize", "  ❌ Keine validen Ergebnisse")
                return None

            combined = "\n\n".join(valid)
            log_debug(
                "summarize",
                "  ➜ Synthese aus %d Teilen (Länge=%d)",
                len(valid),
                len(combined),
            )

            synthesis_prompt = self._get_synthesis_prompt()
            max_synthesis_tokens = limit - self._estimate_tokens(synthesis_prompt) - 500
            if max_synthesis_tokens <= 0:
                log_debug(
                    "summarize",
                    "  ❌ Prompt zu lang für Synthese (max_tokens=%d)",
                    max_synthesis_tokens,
                )
                self._set_status("❌ Prompt zu lang für Synthese")
                return None

            truncated_combined = self._truncate_text_to_fit(
                combined,
                max_synthesis_tokens,
                add_notice=True,
            )
            log_debug(
                "summarize",
                "  ➜ Synthese‑Text gekürzt auf %d Zeichen",
                len(truncated_combined),
            )

            try:
                result = self._summarize_chunk(
                    truncated_combined,
                    synthesis_prompt,
                    temp,
                    chunk_callback=chunk_callback,
                    abort_event=effective_abort,
                )
            except Exception as synth_exc:
                log_debug("summarize", "  ❌ Synthese fehlgeschlagen: %s", synth_exc)
                self._set_status(f"❌ Synthesefehler: {str(synth_exc)[:100]}")
                return None

            elapsed = time.perf_counter() - start_total
            log_debug(
                "summarize",
                "  ✅ Synthese abgeschlossen in %.2fs – Ergebnislänge=%d",
                elapsed,
                len(result) if result else 0,
            )
            return result

        except Exception as exc:
            log_debug("summarize", "  💥 Unerwarteter Fehler: %s", exc, exc_info=True)
            self._set_status(f"❌ Fehler: {str(exc)[:100]}")
            return None

        finally:
            if executor is not None:
                for f in futures:
                    if not f.done():
                        f.cancel()

                executor.shutdown(wait=True)
            self._safe_after(0, lambda: self.progress_var.set(100))
            self._safe_after(0, lambda: self.progress_label.config(text="100%"))
            log_debug(
                "summarize",
                "📊 _summarize_map_reduce END (Gesamtzeit: %.2fs)",
                time.perf_counter() - start_total,
            )

    def _update_progress_ui(self) -> None:
        """Aktualisiert die Fortschrittsanzeige mit Prozent und geschätzter Restzeit.
        Thread-sicher und mit Fehlerbehandlung.
        """
        if self._chunks_total <= 0:
            return

        with self._chunks_lock:
            processed = self._chunks_processed
            total = self._chunks_total

            times = getattr(self, "_chunk_times", [])
            recent_times = times[-5:] if times else []

        percent = (processed / total) * 100 if total > 0 else 0

        eta_text = ""
        if processed > 0 and len(recent_times) >= 2:
            avg_time = sum(recent_times) / len(recent_times)
            remaining = total - processed
            eta_seconds = avg_time * remaining
            if eta_seconds > 0:
                if eta_seconds < 60:
                    eta_text = f" – noch ca. {int(eta_seconds)}s"
                else:
                    minutes = int(eta_seconds // 60)
                    seconds = int(eta_seconds % 60)
                    eta_text = f" – noch ca. {minutes}:{seconds:02d} min"

        def _update_gui() -> None:
            """Interne Funktion für die GUI-Aktualisierung."""
            try:
                if hasattr(self, "progress_var") and self.progress_var is not None:
                    self.progress_var.set(percent)
                if hasattr(self, "progress_label") and self.progress_label is not None:
                    with contextlib.suppress(tk.TclError):
                        self.progress_label.config(text=f"{int(percent)}%{eta_text}")
            except Exception as e:
                log_debug("summarize", f"Fehler bei Progress-UI-Update: {e}")

        self._safe_after(0, _update_gui)

    def _get_synthesis_prompt(self) -> str:
        """Liefert einen sprachabhängigen Synthese‑Prompt."""
        lang = self.language
        if lang == "Deutsch":
            return (
                "Fasse die folgenden Teilzusammenfassungen zu einer einzigen, "
                "kohärenten Gesamtzusammenfassung auf Deutsch zusammen.\n\n"
                "Die Zusammenfassung sollte flüssig lesbar sein und die wichtigsten "
                "Punkte aller Teile enthalten.\n\n"
            )
        if lang == "Englisch":
            return (
                "Combine the following partial summaries into a single, "
                "coherent overall summary in English.\n\n"
                "The summary should be fluent and include the most important "
                "points from all parts.\n\n"
            )
        return (
            "Fasse die folgenden Teilzusammenfassungen zu einer einzigen, "
            "kohärenten Gesamtzusammenfassung zusammen.\n\n"
        )

    def _process_chunk_with_retry(
        self,
        idx: int,
        chunk: str,
        prompt: str,
        temperature: float,
        abort_event: threading.Event,
        max_retries: int = 2,
        retry_delay: float = 0.5,
    ) -> None:
        """Verarbeitet einen Chunk mit Wiederholungen bei Fehlern."""
        for attempt in range(max_retries + 1):
            if abort_event.is_set():
                return
            try:
                self._process_chunk(idx, chunk, prompt, temperature, abort_event)
                return
            except Exception as e:
                if attempt == max_retries:
                    raise
                log_debug(
                    "summarize",
                    "Chunk %d, Versuch %d/%d fehlgeschlagen: %s – wiederhole in %.1fs",
                    idx,
                    attempt + 1,
                    max_retries + 1,
                    e,
                    retry_delay * (2**attempt),
                )
                time.sleep(retry_delay * (2**attempt))

    def _summarize_refine(
        self,
        prompt: str,
        temperature: float | None = None,
        chunk_callback: Callable[[str], None] | None = None,
        max_chunks: int = 20,
    ) -> str | None:
        """Schrittweise, verfeinernde Zusammenfassung für hohe Genauigkeit.
        Verarbeitet den Text in aufeinanderfolgenden Chunks und baut die
        Zusammenfassung iterativ aus.
        """
        if self._request_cancel.is_set():
            self._update_status("⏹️ Abgebrochen (Refine)")
            return None

        limit = self._get_model_context_limit()
        max_tok = min(self.max_chunk_tokens, int(limit * 0.6))
        chunks = self._split_into_chunks(self.text, max_tok)

        if not chunks:
            self._update_status("⚠️ Kein Text zum Verarbeiten")
            return None

        original_count = len(chunks)
        if original_count > 100:
            effective_max = min(50, max_chunks * 2)
        elif original_count > 50:
            effective_max = min(30, max_chunks + 10)
        else:
            effective_max = max_chunks

        if original_count > effective_max:
            chunks = chunks[:effective_max]
            self._update_status(
                f"⚠️ Text auf {effective_max} Abschnitte begrenzt (von {original_count})",
            )
            log_debug(
                "summarize",
                f"Chunks begrenzt: {original_count} → {effective_max}",
            )

        total = len(chunks)
        cur_summary: str | None = None
        chunk_times: list[float] = []

        chunk_cache: dict[str, str] = {}
        MAX_CACHE_SIZE = 100

        GLOBAL_TIMEOUT = 300.0
        start_time = time.monotonic()

        self._update_progress(0, "0% – Vorbereitung ...")
        self._update_status("⏳ Verarbeite Chunks (Refine) ...")

        for i, chunk in enumerate(chunks):
            if self._request_cancel.is_set():
                self._update_status("⏹️ Abgebrochen (Refine)")
                return cur_summary

            if time.monotonic() - start_time > GLOBAL_TIMEOUT:
                self._update_status("⏰ Zeitüberschreitung (Refine) – breche ab")
                return cur_summary

            cache_key = hashlib.md5(chunk.encode(), usedforsecurity=False).hexdigest()[
                :12
            ]
            if cache_key in chunk_cache:
                step_result = chunk_cache[cache_key]
                log_debug("summarize", f"Chunk {i + 1}/{total} aus Cache geladen")
                chunk_times.append(0.5)
            else:
                if i == 0:
                    base_prompt = prompt
                    if self.use_title_context and self.stream_title:
                        base_prompt = f"Titel: {self.stream_title}\n\n{base_prompt}"
                    chunk_prompt = (
                        f"{base_prompt}\n\nText:\n{chunk}\n\nZusammenfassung:"
                    )
                else:
                    current = cur_summary or " (bisher keine Zusammenfassung)"
                    chunk_prompt = (
                        f"Bisherige Zusammenfassung:\n{current}\n\n"
                        f"Erweitere sie mit den folgenden Informationen, ohne bereits Gesagtes zu wiederholen:\n"
                        f"{chunk}\n\n"
                        f"Gib NUR die aktualisierte, vollständige Zusammenfassung zurück."
                    )

                step_start = time.perf_counter()

                step_result = self._summarize_chunk_with_error_handling(
                    chunk,
                    chunk_prompt,
                    temperature,
                    chunk_callback,
                    step_index=i + 1,
                    total_steps=total,
                )

                if step_result is not None:
                    elapsed = time.perf_counter() - step_start
                    chunk_times.append(elapsed)

                    if len(chunk_cache) >= MAX_CACHE_SIZE:
                        oldest = next(iter(chunk_cache))
                        del chunk_cache[oldest]
                    chunk_cache[cache_key] = step_result

            if step_result is None:
                log_debug(
                    "summarize",
                    f"⚠️ Schritt {
                        i + 1
                    } lieferte kein Ergebnis – verwende bisherige Zusammenfassung",
                )
                self._update_status(f"⚠️ Schritt {i + 1} fehlgeschlagen – setze fort")
                progress = int((i + 1) / total * 100)
                eta_text = self._calculate_eta(chunk_times, total, i + 1)
                self._update_progress(progress, f"{progress}%{eta_text}")
                continue

            if step_result.strip():
                cur_summary = step_result
            else:
                log_debug(
                    "summarize",
                    f"Schritt {i + 1} lieferte leeren Text – überspringe",
                )
                if not cur_summary:
                    cur_summary = "[Zusammenfassung konnte nicht erstellt werden]"

            progress = int((i + 1) / total * 100)
            eta_text = self._calculate_eta(chunk_times, total, i + 1)
            self._update_progress(progress, f"{progress}%{eta_text}")
            status_msg = f"Refine {i + 1}/{total}"
            if eta_text:
                status_msg += f" – ⏱️ {eta_text.strip()}"
            self._update_status(status_msg)

            if chunk_callback and cur_summary:
                chunk_callback(cur_summary)

        if cur_summary and cur_summary.strip():
            self._update_status("✅ Zusammenfassung erstellt (Refine)")
            log_debug("summarize", f"Refine erfolgreich – {len(cur_summary)} Zeichen")
            return cur_summary
        self._update_status(
            "❌ Keine Zusammenfassung erstellt – alle Chunks fehlgeschlagen",
        )
        return None

    def _calculate_eta(self, times: list[float], total: int, done: int) -> str:
        """Berechnet eine geschätzte Restzeit basierend auf bisherigen Zeiten."""
        if not times or done <= 0:
            return ""

        avg_time = sum(times) / len(times)
        remaining = total - done
        if remaining <= 0:
            return ""

        eta_seconds = avg_time * remaining

        if eta_seconds < 60:
            return f" – noch ca. {int(eta_seconds)}s"
        if eta_seconds < 3600:
            minutes = int(eta_seconds // 60)
            seconds = int(eta_seconds % 60)
            return f" – noch ca. {minutes}:{seconds:02d} min"
        hours = int(eta_seconds // 3600)
        minutes = int((eta_seconds % 3600) // 60)
        return f" – noch ca. {hours}h {minutes:02d} min"

    def _update_status(self, text: str) -> None:
        """Setzt den Status‑Label im Hauptthread (threadsicher).
        Delegiert an _set_status mit is_error=False.
        """
        self._set_status(text, is_error=False)

    def _is_dialog_alive(self) -> bool:
        """Prüft, ob der Dialog noch existiert und nicht zerstört wurde."""
        if self._destroyed:
            return False
        try:
            return bool(self.dialog and self.dialog.winfo_exists())
        except (tk.TclError, AttributeError, RuntimeError):
            return False

    def _set_status(self, text: str, is_error: bool = False) -> None:
        """Setzt den Status-Label im Hauptthread (threadsicher)."""
        if not self._is_dialog_alive():
            return

        if not isinstance(text, str) or not text.strip():
            text = "✅ Bereit"

        if len(text) > 100:
            text = text[:97] + "..."

        try:
            fg = CURRENT_THEME.ERROR if is_error else CURRENT_THEME.TEXT_SECONDARY
        except NameError:
            fg = "#ff0000" if is_error else "#e6edf3"

        self._safe_after(0, lambda: self._set_status_label(text, fg))

    def _set_status_label(self, text: str, fg: str) -> None:
        """Setzt den Status-Label (wird im Hauptthread aufgerufen).
        Vermeidet überflüssige Updates, falls sich Text oder Farbe nicht geändert haben.
        """
        try:
            if hasattr(self, "status_label") and self.status_label.winfo_exists():
                current_text = self.status_label.cget("text")
                current_fg = self.status_label.cget("fg")
                if current_text != text or current_fg != fg:
                    self.status_label.config(text=text, fg=fg)
        except tk.TclError:
            pass

    def _set_progress_gui(self, value: int, label: str) -> None:
        """Setzt Fortschrittsbalken und Label (wird im Hauptthread aufgerufen)."""
        if hasattr(self, "progress_var") and self.progress_var is not None:
            try:
                current = self.progress_var.get()
                if current != value:
                    self.progress_var.set(value)
            except tk.TclError:
                pass
            except (AttributeError, RuntimeError) as e:
                logger = logging.getLogger("dragon")
                logger.debug(f"Progress-Var Fehler: {e}")

        if hasattr(self, "progress_label") and self.progress_label is not None:
            try:
                if self.progress_label.winfo_exists():
                    current_text = self.progress_label.cget("text")
                    if current_text != label:
                        self.progress_label.config(text=label)
            except tk.TclError:
                pass
            except (AttributeError, RuntimeError) as e:
                logger = logging.getLogger("dragon")
                logger.debug(f"Progress-Label Fehler: {e}")

    def _summarize_chunk_with_error_handling(
        self,
        chunk: str,
        chunk_prompt: str,
        temperature: float | None,
        chunk_callback: Callable[[str], None] | None,
        step_index: int,
        total_steps: int,
        max_retries: int = 2,
        retry_delay_base: float = 0.5,
    ) -> str | None:
        """Führt `_summarize_chunk` mit erweiterter Fehlerbehandlung, Retry‑Logik
        und Abbruchunterstützung aus.
        """
        if not chunk or not isinstance(chunk, str) or not chunk.strip():
            log_debug(
                "summarize",
                f"Schritt {step_index}/{total_steps}: Leerer Chunk – übersprungen",
            )
            return None

        if (
            not chunk_prompt
            or not isinstance(chunk_prompt, str)
            or not chunk_prompt.strip()
        ):
            log_debug(
                "summarize",
                f"Schritt {step_index}/{total_steps}: Leerer Prompt – übersprungen",
            )
            return None

        if self._request_cancel.is_set():
            log_debug(
                "summarize",
                f"Schritt {step_index}/{total_steps}: Abbruch vor Verarbeitung",
            )
            return None

        ollama_cls = self._ollama_class
        timeout_exc = getattr(ollama_cls, "TimeoutError", None) if ollama_cls else None
        server_exc = (
            getattr(ollama_cls, "ServerUnreachableError", None) if ollama_cls else None
        )
        rate_exc = getattr(ollama_cls, "RateLimitError", None) if ollama_cls else None
        model_exc = (
            getattr(ollama_cls, "ModelNotFoundError", None) if ollama_cls else None
        )
        validation_exc = (
            getattr(ollama_cls, "ValidationError", None) if ollama_cls else None
        )
        cancelled_exc = (
            getattr(ollama_cls, "CancelledError", None) if ollama_cls else None
        )

        last_exception = None

        for attempt in range(max_retries + 1):
            if self._request_cancel.is_set():
                log_debug(
                    "summarize",
                    f"Schritt {step_index}/{total_steps}: Abbruch während Retry (Versuch {attempt + 1})",
                )
                return None

            try:
                log_debug(
                    "summarize",
                    f"Schritt {step_index}/{total_steps}: Verarbeitung (Versuch {attempt + 1}/{max_retries + 1})",
                )
                start_time = time.perf_counter()

                result = self._summarize_chunk(
                    chunk=chunk,
                    prompt=chunk_prompt,
                    temperature=temperature,
                    chunk_callback=chunk_callback,
                    abort_event=self._request_cancel,
                    max_retries=0,
                    retry_delay_base=retry_delay_base,
                    timeout_seconds=60.0,
                )

                elapsed = time.perf_counter() - start_time

                if result and isinstance(result, str) and result.strip():
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: ✅ Erfolg in {elapsed:.2f}s (Länge: {len(result)})",
                    )
                    if elapsed > 5.0:
                        self._set_status(
                            f"⏳ Schritt {step_index}/{total_steps} – {elapsed:.1f}s",
                        )
                    return result

                log_debug(
                    "summarize",
                    f"Schritt {step_index}/{total_steps}: Leeres Ergebnis (Versuch {attempt + 1})",
                )
                if attempt < max_retries:
                    delay = min(5.0, retry_delay_base * (2**attempt))
                    log_debug("summarize", f"Wiederhole in {delay:.1f}s...")
                    if self._interruptible_sleep(delay):
                        return None
                    continue
                return None

            except Exception as e:
                last_exception = e

                if model_exc and isinstance(e, model_exc):
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Modell nicht gefunden – {e}",
                    )
                    self._set_status(f"❌ Modell '{self.model}' nicht installiert")
                    raise

                if validation_exc and isinstance(e, validation_exc):
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Validierungsfehler – {e}",
                    )
                    self._set_status(f"❌ Validierungsfehler in Schritt {step_index}")
                    raise

                if cancelled_exc and isinstance(e, cancelled_exc):
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Abbruch durch Benutzer",
                    )
                    self._set_status("⏹️ Abgebrochen")
                    return None

                is_retryable = False
                if timeout_exc and isinstance(e, timeout_exc):
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Timeout (Versuch {attempt + 1})",
                    )
                elif server_exc and isinstance(e, server_exc):
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Server nicht erreichbar (Versuch {attempt + 1})",
                    )
                elif rate_exc and isinstance(e, rate_exc):
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Rate‑Limit (Versuch {attempt + 1})",
                    )
                else:
                    is_retryable = True
                    log_debug(
                        "summarize",
                        f"Schritt {step_index}/{total_steps}: Unerwarteter Fehler (Versuch {attempt + 1}) – {e}",
                    )

                if is_retryable and attempt < max_retries:
                    delay = min(
                        15.0,
                        retry_delay_base
                        * (2**attempt)
                        * (2 if rate_exc and isinstance(e, rate_exc) else 1),
                    )
                    log_debug("summarize", f"Wiederhole in {delay:.1f}s...")
                    if self._interruptible_sleep(delay):
                        return None
                    continue
                self._set_status(
                    f"❌ Schritt {step_index}/{total_steps}: {str(e)[:80]}",
                )
                raise

        if last_exception:
            log_debug(
                "summarize",
                f"Schritt {step_index}/{total_steps}: Alle {max_retries + 1} Versuche fehlgeschlagen",
            )
            self._set_status(
                f"⚠️ Schritt {step_index}/{total_steps}: Alle Versuche fehlgeschlagen",
            )
        return None

    def _interruptible_sleep(self, seconds: float, check_interval: float = 0.1) -> bool:
        """Schlafe für `seconds` Sekunden, aber prüfe regelmäßig auf Abbruch."""
        if seconds <= 0:
            return False

        if self._request_cancel.is_set():
            return True

        end_time = time.monotonic() + seconds
        while time.monotonic() < end_time:
            if self._request_cancel.is_set():
                return True
            remaining = end_time - time.monotonic()
            sleep_time = min(check_interval, remaining)
            time.sleep(sleep_time)
        return False

    def start_summarize(self) -> None:
        """Startet die Zusammenfassung asynchron im Hintergrund mit Streaming,
        automatischer TTS und detaillierter Fehlerdiagnose.
        """
        if self._destroyed:
            return

        if not self._ollama_available:
            self._set_status("❌ OllamaSummarizer nicht verfügbar")
            return

        if not self._ensure_server_reachable():
            self._set_status("❌ Ollama‑Server nicht erreichbar")
            return

        self._prepare_ui_for_summarize()

        effective_prompt = self.preview_text.get("1.0", "end-1c").strip()
        if not effective_prompt:
            self._set_status("❌ Prompt ist leer")
            self._reset_ui()
            return

        use_structured = self.structured_var.get()
        strategy = self.strategy_var.get()
        temperature = self.temperature
        original_text = self.text

        if not self._truncate_text_if_needed(effective_prompt):
            return

        cached = self._get_cached(effective_prompt)
        if cached:
            self._apply_cached_summary(cached, original_text)
            return

        def worker() -> None:
            """Haupt‑Worker mit Streaming, TTS und Fehlerbehandlung."""
            self._summarize_in_progress = True
            try:
                meth = (
                    self._summarize_refine
                    if strategy == "Genau (schrittweise)"
                    else self._summarize_map_reduce
                )

                chunk_cb = None
                if callable(meth):
                    import inspect

                    sig = inspect.signature(meth)
                    if "chunk_callback" in sig.parameters:

                        def on_chunk(chunk: str) -> None:
                            if self._destroyed or not hasattr(self, "summary_text"):
                                return
                            self._safe_after(
                                0,
                                lambda: self.summary_text.insert("end", chunk),
                            )
                            self._safe_after(0, lambda: self.summary_text.see("end"))

                        chunk_cb = on_chunk

                result = meth(effective_prompt, temperature, chunk_callback=chunk_cb)

                if result and not self._request_cancel.is_set():
                    regen = self._auto_regenerate(result, effective_prompt, temperature)
                    if regen:
                        result = regen

                    if use_structured:
                        result = json.dumps(
                            {
                                "summary": result,
                                "model": self.model,
                                "temperature": temperature,
                                "timestamp": datetime.now(UTC).isoformat(),
                            },
                            indent=2,
                            ensure_ascii=False,
                        )

                    self._finalize_summary(result, effective_prompt, original_text)

                    if self._is_tts_enabled():
                        self._speak_summary(result)

                elif not self._request_cancel.is_set():
                    self._set_status("❌ Zusammenfassung fehlgeschlagen")

            except Exception as e:
                hint = self._classify_error(e)
                self._set_status(f"❌ {hint}")
                log_debug("summarize", f"Worker Fehler: {e}", exc_info=True)
            finally:
                self._summarize_in_progress = False
                if self.text != original_text:
                    self.text = original_text
                self._safe_after(0, self._reset_ui)

        threading.Thread(
            target=worker,
            daemon=True,
            name=f"SummarizeWorker-{int(time.time())}",
        ).start()

    def _is_tts_enabled(self) -> bool:
        """Prüft sicher, ob die automatische Sprachausgabe aktiviert ist."""
        if not hasattr(self, "auto_tts_var"):
            log_debug("summarize", "auto_tts_var nicht initialisiert – TTS deaktiviert")
            return False

        try:
            return bool(self.auto_tts_var.get())
        except Exception as e:
            log_debug("summarize", f"Fehler beim Lesen von auto_tts_var: {e}")
            return False

    def _ensure_server_reachable(self) -> bool:
        """Prüft den Ollama-Server mit maximal 3 Wiederholungen."""
        for attempt in range(1, 4):
            try:
                with self._ollama_usage() as summarizer:
                    if summarizer.is_server_reachable():
                        self._retry_attempt = 0
                        return True
            except Exception as e:
                if attempt == 3:
                    DarkMessageBox.showerror(
                        "Serverfehler",
                        f"Ollama-Server auch nach 3 Versuchen nicht erreichbar.\nFehler: {str(e)[:200]}",
                        parent=self.dialog,
                    )
                    return False
                if DarkMessageBox.askyesno(
                    f"Server nicht erreichbar - Wiederholen? ({attempt}/3)",
                    str(e),
                    parent=self.dialog,
                ):
                    continue
                return False
        return False

    def _prepare_ui_for_summarize(self) -> None:
        """Setzt alle UI-Elemente für den Start zurück."""
        self._set_ui_enabled(False)
        self._clear_summary_parts()
        self._set_full_summary("")
        if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
            self.summary_text.delete("1.0", "end")
            self.summary_text.insert("1.0", "[Zusammenfassung wird erstellt...]")
        self._request_cancel.clear()
        self.progress_var.set(0)
        self.progress_label.config(text="0%")
        self._last_progress_update = time.time()

    def _truncate_text_if_needed(self, prompt: str) -> bool:
        """Kürzt den Text, falls nötig. Gibt False zurück, wenn der Prompt zu lang ist."""
        prompt_tokens = self._estimate_tokens(prompt)
        limit = self._get_model_context_limit()
        max_text_tokens = limit - prompt_tokens - 500
        if max_text_tokens <= 0:
            self._safe_after(
                0,
                lambda: self.status_label.config(
                    text="❌ Prompt bereits zu lang – bitte Prompt kürzen",
                ),
            )
            self._reset_ui()
            return False
        if max_text_tokens > 0:
            truncated = self._truncate_text_to_fit(
                self.text,
                max_text_tokens,
                add_notice=True,
            )
            if truncated != self.text:
                self.text = truncated
                self._safe_after(
                    0,
                    lambda: self.status_label.config(
                        text="⚠️ Text wurde gekürzt, um ins Kontextfenster zu passen",
                    ),
                )
        return True

    def _apply_cached_summary(self, cached: str, original_text: str) -> None:
        """Wendet ein gecachtes Ergebnis an und setzt die UI zurück."""
        self._set_full_summary(cached)
        self._apply_blacklist_to_summary()
        self._save_backup()
        self._update_readability_metrics(cached)
        self._add_to_history(cached)
        self.text = original_text
        self._safe_after(0, self._reset_ui)

    def _finalize_summary(self, result: str, prompt: str, original_text: str) -> None:
        """Speichert, cacht und zeigt die fertige Zusammenfassung an."""
        if not result or not isinstance(result, str) or not result.strip():
            self.status_label.config(
                text="❌ Leere Zusammenfassung – nicht gespeichert",
            )
            logger.warning("_finalize_summary: result is empty or invalid")
            return

        try:
            self._set_full_summary(result)
        except Exception as e:
            logger.error(f"Fehler beim Setzen der Zusammenfassung: {e}")
            self.status_label.config(
                text="⚠️ Fehler beim Speichern der Zusammenfassung",
            )
            return

        try:
            self._apply_blacklist_to_summary()
        except Exception as e:
            logger.warning(f"Blacklist-Filterung fehlgeschlagen: {e}")

        try:
            self._cache_set(prompt, result)
        except Exception as e:
            logger.warning(f"Cache-Speicherung fehlgeschlagen: {e}")

        try:
            self._save_backup()
        except Exception as e:
            logger.warning(f"Backup-Speicherung fehlgeschlagen: {e}")

        try:
            self._update_readability_metrics(result)
        except Exception as e:
            logger.warning(
                f"Lesbarkeitsmetriken konnten nicht aktualisiert werden: {e}",
            )

        try:
            if not self._is_summary_in_history(result):
                self._add_to_history(result)
            else:
                log_debug(
                    "summarize",
                    "Zusammenfassung bereits in der Historie – Duplikat übersprungen",
                )
        except Exception as e:
            logger.warning(f"Historie konnte nicht aktualisiert werden: {e}")

        try:
            self._delete_backup()
        except Exception as e:
            logger.warning(f"Backup-Datei konnte nicht gelöscht werden: {e}")

        self.progress_var.set(100)
        self.progress_label.config(text="100%")
        self.status_label.config(text="✅ Zusammenfassung erstellt")

        if self.text != original_text:
            self.text = original_text
            log_debug(
                "summarize",
                "Originaltext wiederhergestellt (Länge: %d)",
                len(original_text),
            )

        if hasattr(self, "event_bus") and self.event_bus:
            self.event_bus.emit(
                "summary_finalized",
                {
                    "length": len(result),
                    "language": self.language,
                    "model": self.model,
                    "timestamp": time.time(),
                },
            )

        log_debug(
            "summarize",
            "✅ Zusammenfassung finalisiert (Länge: %d Zeichen)",
            len(result),
        )

    def _delete_backup(self) -> None:
        """Löscht die Backup-Datei, falls sie existiert."""
        if os.path.exists(self._backup_file):
            try:
                os.unlink(self._backup_file)
                log_debug("summarize", "Backup-Datei gelöscht: %s", self._backup_file)
            except Exception as e:
                logger.warning(f"Backup-Datei konnte nicht gelöscht werden: {e}")

    def _is_summary_in_history(self, summary: str) -> bool:
        """Prüft, ob die Zusammenfassung bereits in der Historie existiert."""
        if not self._history:
            return False

        return any(entry.get("summary") == summary for entry in self._history[:10])

    def _speak_summary(self, summary: str) -> None:
        """Liest die Zusammenfassung automatisch vor (wenn TTS aktiviert)."""
        if not hasattr(self, "auto_tts_var"):
            return
        if not self.auto_tts_var.get():
            return
        tts = self.gui.tts_manager
        if tts is not None and tts.is_available():
            tts.speak_queued(summary, callback=lambda s, m: None)

    def _classify_error(self, exc: Exception) -> str:
        """Gibt eine benutzerfreundliche Fehlermeldung mit Handlungsempfehlung zurück.
        Berücksichtigt verschiedene Fehlertypen, HTTP-Statuscodes und Exception-Klassen.
        """
        msg = str(exc).lower()
        exc_type = type(exc).__name__

        model_keywords = [
            "model not found",
            "no such model",
            "model not available",
            "unable to find model",
            "model does not exist",
        ]
        if any(kw in msg for kw in model_keywords):
            return f"Modell '{
                self.model
            }' nicht gefunden. Installiere es mit: ollama pull {self.model}"

        connection_keywords = [
            "connection refused",
            "unreachable",
            "network is unreachable",
            "failed to connect",
            "connection error",
            "cannot connect",
            "no route to host",
        ]
        if (
            any(kw in msg for kw in connection_keywords)
            or "ConnectionError" in exc_type
            or "ConnectionRefusedError" in exc_type
        ):
            return "Ollama-Server läuft nicht oder ist nicht erreichbar. Starte ihn mit: ollama serve"

        if (
            "timeout" in msg
            or "timed out" in msg
            or "TimeoutError" in exc_type
            or "Timeout" in exc_type
        ):
            return (
                "Die Anfrage dauerte zu lange. Versuche ein kleineres Modell, "
                "kürze den Text oder erhöhe das Timeout in den Einstellungen."
            )

        rate_keywords = ["rate limit", "too many requests", "429"]
        if any(kw in msg for kw in rate_keywords):
            return "Zu viele Anfragen in kurzer Zeit. Bitte warte kurz und versuche es erneut."

        context_keywords = [
            "context length",
            "maximum context",
            "token limit",
            "too many tokens",
            "exceeds max",
            "input is too long",
        ]
        if any(kw in msg for kw in context_keywords):
            return (
                "Der Text ist zu lang für das Modellkontextfenster. "
                "Kürze den Text oder verwende ein Modell mit größerem Kontext (z.B. llama3.1:8b)."
            )

        if "400" in msg:
            return "Ungültige Anfrage. Prüfe den Prompt oder die Modellkonfiguration."
        if "401" in msg or "403" in msg:
            return "Zugriff verweigert. Prüfe die Ollama-Berechtigungen."
        if "404" in msg:
            return "Ressource nicht gefunden. Prüfe den Modellnamen oder die URL."
        if "500" in msg:
            return "Interner Serverfehler bei Ollama. Versuche es später erneut oder starte den Server neu."

        short_msg = str(exc)[:80]
        return f"{exc_type}: {short_msg}"

    def _set_ui_enabled(self, enabled: bool) -> None:
        """Aktiviert/deaktiviert die UI-Elemente."""
        if not self.dialog or not self.dialog.winfo_exists():
            return

        state = "normal" if enabled else "disabled"
        for btn_name in (
            "summarize_btn",
            "cancel_btn",
            "copy_btn",
            "save_btn",
            "translate_btn",
        ):
            btn = getattr(self, btn_name, None)
            if btn is not None and btn.winfo_exists():
                try:
                    btn.config(state=state)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

        if self.cancel_btn and self.cancel_btn.winfo_exists():
            try:
                self.cancel_btn.config(state="disabled" if enabled else "normal")
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    def _reset_ui(self) -> None:
        """Setzt die UI nach Abschluss oder Abbruch zurück."""
        self.summarize_btn.config(state="normal", text="🚀 Zusammenfassen")
        self.cancel_btn.config(state="disabled")
        has = bool(self._get_full_summary())
        for b in (self.copy_btn, self.save_btn, self.translate_btn):
            if b:
                b.config(state="normal" if has else "disabled")
        if has and hasattr(self, "summary_text"):
            self.summary_text.delete("1.0", "end")
            self.summary_text.insert("1.0", self._get_full_summary())
        self.status_label.config(text="✅ Bereit")
        self.progress_var.set(0)
        self.progress_label.config(text="0%")

    def cancel_request(self) -> None:
        """Bricht eine laufende Zusammenfassung ab."""
        self._request_cancel.set()

        with self._ollama_usage_lock:
            inst = self._ollama_instance
            if inst is not None:
                try:
                    inst.stop()
                except Exception as e:
                    log_debug("summarize", f"Fehler beim Stoppen von Ollama: {e}")
            self._ollama_usage_count = 0

        parts = self._get_summary_parts()
        if parts:
            self._set_full_summary("".join(parts))
            self._apply_blacklist_to_summary()
            self._save_backup()

        self._safe_after(0, self._reset_ui)

    def _retry_summarize(self) -> None:
        """Startet die Zusammenfassung erneut."""
        self.start_summarize()

    def copy_summary(self) -> None:
        """Kopiert die Zusammenfassung in die Zwischenablage."""
        s = self._get_full_summary()
        if not s:
            return
        self.dialog.clipboard_clear()
        self.dialog.clipboard_append(s)
        self.status_label.config(text="✅ Kopiert")

    def save_summary(self) -> None:
        """Speichert die Zusammenfassung als Datei."""
        s = self._get_full_summary()
        if not s:
            return
        fn = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text", "*.txt"), ("JSON", "*.json")],
        )
        if not fn:
            return
        try:
            if fn.endswith(".json"):
                with open(fn, "w", encoding="utf-8") as f:
                    json.dump(
                        {
                            "summary": s,
                            "model": self.model,
                            "timestamp": datetime.now(UTC).isoformat(),
                        },
                        f,
                        indent=2,
                        ensure_ascii=False,
                    )
            else:
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(s)
            self.status_label.config(text=f"💾 {os.path.basename(fn)}")
        except Exception as e:
            self.status_label.config(text=f"❌ {e}")
            log_debug("summarize", f"Save error: {e}")

    def translate_summary(self) -> None:
        """Übersetzt die Zusammenfassung."""
        s = self._get_full_summary()
        if not s:
            return
        engine = getattr(self.gui, "translation_engine", None)
        if not engine or not engine.is_functional():
            self.status_label.config(text="⚠️ Übersetzung nicht verfügbar")
            return
        TranslationDialog(self.dialog, engine, self.gui, initial_text=s)

    def _export_menu(self) -> None:
        """Erstellt das Export‑Menü."""
        menu = tk.Menu(self.dialog, tearoff=0)
        menu.add_command(
            label="Text (.txt)",
            command=lambda: self._export_summary("txt"),
        )
        menu.add_command(
            label="JSON (.json)",
            command=lambda: self._export_summary("json"),
        )
        if importlib.util.find_spec("docx"):
            menu.add_command(
                label="DOCX (.docx)",
                command=lambda: self._export_summary("docx"),
            )
        if importlib.util.find_spec("reportlab"):
            menu.add_command(
                label="PDF (.pdf)",
                command=lambda: self._export_summary("pdf"),
            )
        menu.add_command(
            label="Markdown (.md)",
            command=lambda: self._export_summary("md"),
        )
        menu.add_command(
            label="HTML (.html)",
            command=lambda: self._export_summary("html"),
        )
        menu.post(
            self.export_btn.winfo_rootx(),
            self.export_btn.winfo_rooty() + self.export_btn.winfo_height(),
        )

    def _export_summary(self, fmt: str) -> None:
        """Exportiert die Zusammenfassung in das angegebene Format."""
        s = self._get_full_summary()
        if not s:
            DarkMessageBox.showwarning(
                "Keine Zusammenfassung",
                "Nichts zu exportieren.",
            )
            return
        fn = filedialog.asksaveasfilename(
            defaultextension=f".{fmt}",
            filetypes=[(f"{fmt.upper()}", f"*.{fmt}")],
        )
        if not fn:
            return
        try:
            if fmt == "txt":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(s)
            elif fmt == "json":
                with open(fn, "w", encoding="utf-8") as f:
                    json.dump(
                        {
                            "summary": s,
                            "model": self.model,
                            "ts": datetime.now(UTC).isoformat(),
                        },
                        f,
                        indent=2,
                        ensure_ascii=False,
                    )
            elif fmt == "docx":
                from docx import Document

                doc = Document()
                doc.add_heading("Zusammenfassung", 0)
                doc.add_paragraph(s)
                doc.save(fn)
            elif fmt == "pdf":
                from reportlab.lib.pagesizes import A4
                from reportlab.lib.styles import getSampleStyleSheet
                from reportlab.platypus import Paragraph, SimpleDocTemplate

                doc = SimpleDocTemplate(fn, pagesize=A4)
                styles = getSampleStyleSheet()
                story = [Paragraph(s.replace("\n", "<br/>"), styles["Normal"])]
                doc.build(story)
            elif fmt == "md":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(f"# Zusammenfassung\n\n{s}")
            elif fmt == "html":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(f"<html><body><pre>{s}</pre></body></html>")
            self.status_label.config(text=f"✅ {os.path.basename(fn)}")
        except Exception as e:
            DarkMessageBox.showerror("Export fehlgeschlagen", str(e))
            log_debug("summarize", f"Export error: {e}")

    def _load_history(self) -> None:
        """Lädt den Zusammenfassungsverlauf aus der JSON‑Datei."""
        if self._history_file.exists():
            try:
                with open(self._history_file, encoding="utf-8") as f:
                    self._history = json.load(f)
                if len(self._history) > self._MAX_HISTORY_ENTRIES:
                    self._history = self._history[: self._MAX_HISTORY_ENTRIES]
                log_debug(
                    "summarize",
                    f"{len(self._history)} History-Einträge geladen (max. {self._MAX_HISTORY_ENTRIES})",
                )
            except Exception as e:
                log_debug("summarize", f"History-Datei beschädigt: {e}")
                self._history = []
        else:
            self._history = []

    def _save_history(self) -> None:
        """Speichert den Verlauf persistent."""
        try:
            self._history_file.parent.mkdir(parents=True, exist_ok=True)
            with open(self._history_file, "w", encoding="utf-8") as f:
                json.dump(self._history[:50], f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"History save error: {e}")

    def _add_to_history(self, summary: str) -> None:
        """Fügt eine Zusammenfassung dem Verlauf hinzu."""
        entry = {
            "ts": datetime.now(UTC).isoformat(),
            "model": self.model,
            "temperature": self.temperature,
            "language": self.language,
            "summary": summary,
            "source_title": self.stream_title,
            "source_length": len(self.text),
        }
        self._history.insert(0, entry)
        if len(self._history) > self._MAX_HISTORY_ENTRIES:
            self._history = self._history[: self._MAX_HISTORY_ENTRIES]
        self._save_history()
        self._update_history_combobox()

    def _update_history_combobox(self) -> None:
        """Aktualisiert die History-Combobox."""
        if not hasattr(self, "history_combo"):
            return
        values = []
        for e in self._history[:20]:
            title = e.get("source_title", "")[:30]
            s_len = e.get("source_length", 0)
            values.append(f"{e['ts'][:19]} | {title} | {s_len} Zeichen")
        self.history_combo["values"] = values
        if values:
            self.history_combo.current(0)

    def _on_history_selected(self, event=None) -> None:
        """Lädt einen Verlaufseintrag in die Zusammenfassungsansicht."""
        idx = self.history_combo.current()
        if 0 <= idx < len(self._history):
            entry = self._history[idx]
            self._set_full_summary(entry["summary"])
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self.summary_text.delete("1.0", "end")
                self.summary_text.insert("1.0", entry["summary"])
                self._update_readability_metrics(entry["summary"])
            self.status_label.config(text=f"📜 Verlauf: {entry['ts'][:19]}")

    def _fetch_available_models(self, force: bool = False) -> None:
        """Lädt die verfügbaren Ollama-Modelle asynchron vom Server.

        Args:
            force: Wenn True, wird der Cache ignoriert und neu geladen.

        """
        now = time.time()
        if (
            not force
            and self._available_models
            and (now - self._model_fetch_timestamp) < self.MODEL_FETCH_TTL
        ):
            self._update_model_list(self._available_models)
            if (
                hasattr(self, "model_status_label")
                and self.model_status_label is not None
            ):
                self.model_status_label.config(text="✅ Modelle geladen (Cache)")
            return

        if self._model_fetch_in_progress:
            return

        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="⏳ Lade Modelle...")

        def worker() -> None:
            """Führt den eigentlichen API‑Aufruf im Hintergrund durch."""
            try:
                import requests as _requests
            except ImportError:
                self._safe_after(
                    0,
                    lambda: self._set_model_status("❌ requests nicht installiert"),
                )
                self._model_fetch_in_progress = False
                return
            try:
                adv_settings = getattr(self.gui, "advanced_settings", None)
                if adv_settings is not None:
                    host = getattr(
                        adv_settings,
                        "ollama_host",
                        "http://localhost:11434",
                    )
                else:
                    host = "http://localhost:11434"
                host = host.rstrip("/")
            except Exception:
                host = "http://localhost:11434"

            try:
                resp = _requests.get(f"{host}/api/tags", timeout=5)
                if resp.status_code == 200:
                    data = resp.json()
                    models = [m["name"] for m in data.get("models", [])]
                    if models:
                        self._available_models = models
                        self._model_fetch_timestamp = time.time()
                        self._safe_after(0, lambda: self._update_model_list(models))
                        self._safe_after(
                            0,
                            lambda: self._set_model_status(
                                f"✅ {len(models)} Modelle geladen",
                            ),
                        )
                    else:
                        self._safe_after(
                            0,
                            lambda: self._set_model_status("⚠️ Keine Modelle gefunden"),
                        )
                else:
                    error_text = f"HTTP {resp.status_code}"
                    self._safe_after(
                        0,
                        lambda: self._set_model_status(
                            f"❌ Server-Fehler: {error_text}",
                        ),
                    )
                    log_debug("summarize", f"Ollama‑Server antwortet mit {error_text}")
            except _requests.exceptions.ConnectionError:
                self._safe_after(
                    0,
                    lambda: self._set_model_status("❌ Server nicht erreichbar"),
                )
                log_debug("summarize", "Ollama‑Server nicht erreichbar")
            except _requests.exceptions.Timeout:
                self._safe_after(
                    0,
                    lambda: self._set_model_status("⏰ Timeout beim Laden"),
                )
                log_debug("summarize", "Timeout beim Laden der Modelle")
            except Exception as e:
                error_msg = str(e)[:80]
                self._safe_after(
                    0,
                    lambda: self._set_model_status(f"❌ Fehler: {error_msg}"),
                )
                log_debug("summarize", f"Modell‑Liste konnte nicht geladen werden: {e}")
            finally:
                self._model_fetch_in_progress = False

        self._model_fetch_in_progress = True
        threading.Thread(target=worker, daemon=True, name="OllamaModelFetcher").start()

    def _set_model_status(self, text: str) -> None:
        """Setzt den Text des Modell‑Status‑Labels (thread‑sicher)."""
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            try:
                if self.model_status_label.winfo_exists():
                    self.model_status_label.config(text=text)
            except tk.TclError:
                pass

    def _clear_model_status(self) -> None:
        """Löscht den Modell-Status-Hinweis."""
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="")

    def _update_model_list(self, models: list[str]) -> None:
        """Aktualisiert die Modell-Combobox."""
        if not hasattr(self, "model_combo"):
            return
        self.model_combo["values"] = models
        if self.model in models:
            self.model_var.set(self.model)
        elif models:
            self.model_var.set(models[0])
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="✅")

    def _safe_after(
        self,
        delay: int,
        func: Callable,
        *args: Any,
        **kwargs: Any,
    ) -> None:
        """Sicherer `after`-Aufruf, der den Dialog-Zustand prüft."""
        if self._destroyed or not self.dialog.winfo_exists():
            return
        self.dialog.after(delay, func, *args, **kwargs)

    def _is_destroyed(self) -> bool:
        """Gibt zurück, ob der Dialog bereits zerstört wurde."""
        return self._destroyed

    def _set_destroyed(self) -> None:
        """Markiert den Dialog als zerstört."""
        self._destroyed = True

    def _bind_shortcuts(self) -> None:
        """Bindet Tastaturkürzel an den Dialog."""
        self.dialog.bind("<Control-s>", lambda e: self.save_summary())
        self.dialog.bind("<Escape>", lambda e: self.close())

    def _check_ollama_availability(self) -> None:
        """Prüft die Verfügbarkeit von Ollama und zeigt ggf. eine Hilfemeldung an.
        Diese Methode kann jederzeit aufgerufen werden, z.B. nach einem Health-Check.
        """
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        if self._ollama_available:
            self.status_label.config(text="✅ Ollama verfügbar", fg=theme.SUCCESS)
            if hasattr(self, "_ollama_help_btn") and self._ollama_help_btn is not None:
                try:
                    self._ollama_help_btn.destroy()
                    self._ollama_help_btn = None
                except tk.TclError:
                    pass
            return

        self.status_label.config(
            text="❌ Ollama nicht verfügbar – bitte installieren und starten Sie 'ollama serve'",
            fg=theme.ERROR,
        )

        if not hasattr(self, "_ollama_help_btn") or self._ollama_help_btn is None:
            if (
                not hasattr(self, "_ollama_help_frame")
                or self._ollama_help_frame is None
            ):
                self._ollama_help_frame = tk.Frame(self.main, bg=theme.BG_PRIMARY)
                max_row = 0
                for child in self.main.winfo_children():
                    try:
                        row = int(child.grid_info().get("row", 0))
                        max_row = max(max_row, row)
                    except (tk.TclError, ValueError):
                        pass
                self._ollama_help_frame.grid(
                    row=max_row + 1,
                    column=0,
                    sticky="ew",
                    pady=5,
                )
            else:
                self._ollama_help_frame.grid()

            self._ollama_help_btn = tk.Button(
                self._ollama_help_frame,
                text="📖 Installationshilfe",
                command=self._show_ollama_help,
                bg=getattr(theme, "INFO", "#58a6ff"),
                fg=getattr(theme, "TEXT_PRIMARY", "#e6edf3"),
                cursor="hand2",
                padx=10,
                pady=5,
            )
            self._ollama_help_btn.pack(side="left", padx=5)
        else:
            self._ollama_help_btn.pack(side="left", padx=5)

    def _show_ollama_help(self) -> None:
        """Zeigt eine detaillierte Installationsanleitung für Ollama an."""
        help_text = (
            "🐉 **Ollama – Installationsanleitung**\n\n"
            "Ollama wird für die Zusammenfassungsfunktion benötigt.\n\n"
            "📥 **Installation:**\n"
            "• **Windows:**  https://ollama.com/download/windows\n"
            "• **macOS:**    https://ollama.com/download/mac\n"
            "• **Linux:**    curl -fsSL https://ollama.com/install.sh | sh\n\n"
            "▶️ **Starten des Servers:**\n"
            "   Nach der Installation führen Sie im Terminal aus:\n"
            "   `ollama serve`\n\n"
            "📦 **Modell herunterladen (Beispiel):**\n"
            "   `ollama pull llama3.1:8b`\n\n"
            "🔄 **Nach der Installation:**\n"
            "   Schließen Sie diesen Dialog und klicken Sie erneut auf 'Zusammenfassen'.\n"
            "   Die Verbindung wird automatisch hergestellt."
        )
        try:
            DarkMessageBox.showinfo(
                "Ollama – Installationshilfe",
                help_text,
                parent=self.dialog,
                timeout=30,
            )
        except Exception as e:
            logger.warning(f"Konnte Hilfedialog nicht öffnen: {e}")
            self.status_label.config(
                text="ℹ️ Installieren Sie Ollama von https://ollama.com und starten Sie 'ollama serve'",
                fg=CURRENT_THEME.INFO,
            )

    def _start_ollama_health_check(self) -> None:
        """Startet einen periodischen Health-Check für Ollama (alle 30 Sekunden)."""

        def check():
            if self._destroyed or not self.dialog.winfo_exists():
                return
            if not getattr(self, "_summarize_in_progress", False):
                reachable = False
                try:
                    with self._ollama_usage() as summarizer:
                        reachable = summarizer.is_server_reachable()
                except Exception:
                    pass
                self._ollama_available = reachable
                self._check_ollama_availability()
            self._safe_after(30000, check)

        self._safe_after(30000, check)

