    def __init__(self, parent: tk.Tk, gui_ref: Any) -> None:
        """Initialisiert den Installationsdialog."""
        self.gui = gui_ref
        self._closed = False
        self._stop_event = threading.Event()
        self._current_process: subprocess.Popen | None = None
        self._process_lock = threading.RLock()
        self._update_running = False
        self._use_legacy_pip = False
        self._restart_in_progress = False
        self._exiting = False
        self._executor: ThreadPoolExecutor | None = None
        self._executor_shutdown = False

        self._force_close_timer: threading.Timer | None = None
        self._active_threads: list[threading.Thread] = []
        self._active_threads_lock = threading.Lock()
        self._gui_queue: queue.Queue[tuple[Callable, tuple, dict]] = queue.Queue()
        self.platform = SYSTEM.lower()
        self.pkg_manager = self._detect_package_manager()
        self.in_venv = hasattr(sys, "real_prefix") or (
            hasattr(sys, "base_prefix") and sys.base_prefix != sys.prefix
        )
        log_debug(
            "install_dlg",
            f"🐍 in_venv={self.in_venv}, pkg_manager={self.pkg_manager}",
            3,
        )
        self._tool_installed_cache: dict[str, bool] = {}
        self._tool_installed_lock = threading.RLock()
        self._vlc_installed = self._is_vlc_installed()
        self._prev_available: dict[str, bool] = {}
        self._last_stderr: str = ""
        self._player_cache: list[tuple[str, list[str]]] | None = None
        self._player_cache_lock = threading.RLock()
        self._previous_pkg_status: dict[str, bool] = {}
        self.sys_vars: dict[str, tk.BooleanVar] = {}
        self.py_vars: dict[str, tk.BooleanVar] = {}
        self._voice_vars: dict[str, tk.BooleanVar] = {}
        self._voice_frame: tk.Frame | None = None
        self._voice_container: tk.Frame | None = None
        self.package_labels: list[tuple[str, tk.Label]] = []
        self._pydantic_repair_btn: tk.Button | None = None
        self._pydantic_update_running = False
        self._search_filter: str | None = None
        self._filter_by_status: str | None = "all"
        self._current_install_phase: str = "IDLE"
        self._install_lock = threading.RLock()
        self._progress_callback: Callable[[int, str], None] | None = None
        self._progress_timer: threading.Timer | None = None
        self._size_cache: dict[str, int | None] = {}
        self._checkbutton_cache: dict[str, tk.Checkbutton | None] = {}
        self._init_search()
        self._init_executor()

        try:
            super().__init__(
                parent,
                "🐉 Abhängigkeiten installieren / aktualisieren",
                width=1024,
                height=860,
                modal=True,
            )
            log_debug("install_dlg", "✅ Super().__init__ erfolgreich", 3)
        except Exception as e:
            log_debug("install_dlg", f"❌ Fehler bei super().__init__: {e}", 2)
            raise
        self.status_var = tk.StringVar(value="🐉 Bereit")
        if hasattr(self, "dialog") and self.dialog:
            try:
                self.dialog.protocol("WM_DELETE_WINDOW", self.close)
                log_debug("install_dlg", "✅ WM_DELETE_WINDOW auf close() gesetzt", 4)
            except Exception as e:
                log_debug(
                    "install_dlg",
                    f"⚠️ WM_DELETE_WINDOW konnte nicht gesetzt werden: {e}",
                    2,
                )

        try:
            self.status_label = ttk.Label(
                self.dialog,
                text="",
                font=("TkDefaultFont", 10),
            )
            self.status_label.pack(pady=5, fill=tk.X, padx=10)
            self._has_status_label = True
            log_debug("install_dlg", "✅ status_label erstellt", 4)
        except Exception as e:
            log_debug(
                "install_dlg",
                f"⚠️ status_label konnte nicht erstellt werden: {e}",
                2,
            )
            self._has_status_label = False

        try:
            self._bind_shortcuts()
            self._start_gui_processor()
            self._safe_after(200, self._check_and_repair_pydantic_auto)
            log_debug(
                "install_dlg",
                "✅ Shortcuts, GUI-Processor und Pydantic-Check gestartet",
                3,
            )
        except Exception as e:
            log_debug("install_dlg", f"❌ Fehler bei Rest-Initialisierung: {e}", 2)
            if DEBUG_LEVEL >= 2:
                log_debug("install_dlg", f"⚠️ Nicht-kritischer Fehler: {e}", 2)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "install_dlg",
                "InstallDependencyDialog v16.1 (vollständig thread‑sicher) initialisiert",
                2,
            )

    def _safe_gui_call(self, func: Callable, *args, **kwargs) -> None:
        """Führt einen GUI-Callback sicher im Hauptthread aus."""
        if self._closed:
            return
        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.after(
                    0,
                    lambda: self._safe_gui_call_impl(func, args, kwargs),
                )
            else:
                func(*args, **kwargs)
        except Exception as e:
            logger.debug(f"_safe_gui_call Fehler: {e}")

    def _safe_gui_call_impl(self, func: Callable, args: tuple, kwargs: dict) -> None:
        try:
            if not self._closed and self.dialog and self.dialog.winfo_exists():
                func(*args, **kwargs)
        except tk.TclError:
            pass
        except Exception as e:
            logger.debug(f"GUI-Callback Fehler: {e}")

    def _init_executor(self) -> None:
        if self._executor is None:
            cpu_count = os.cpu_count() or 2
            workers = max(1, cpu_count // 2)
            self._executor = ThreadPoolExecutor(
                max_workers=workers,
                thread_name_prefix="InstallDlgWorker",
            )

    def _init_search(self) -> None:
        self._search_var = tk.StringVar()
        self._search_var.trace_add("write", lambda *_: self._apply_search_filter())
        self._search_filter = None
        self._filter_by_status = "all"

    def _bind_shortcuts(self) -> None:
        if self.dialog is None:
            return
        self.dialog.bind("<Escape>", lambda e: self.close())
        self.dialog.bind("<Control-c>", lambda e: self.cancel_installation())
        self.dialog.bind("<Control-w>", lambda e: self.close())
        self.dialog.bind("<Control-f>", lambda e: self._focus_search())
        self.dialog.bind("<Control-s>", lambda e: self._export_requirements())
        self.dialog.bind("<Control-a>", lambda e: self._select_all_packages())
        self.dialog.bind("<Control-d>", lambda e: self._deselect_all_packages())
        self.dialog.bind("<F1>", lambda e: self._show_help())

    def _focus_search(self) -> None:
        if hasattr(self, "search_entry") and self.search_entry.winfo_exists():
            self.search_entry.focus_set()

    def _select_all_packages(self) -> None:
        for var in self.sys_vars.values():
            var.set(True)
        for var in self.py_vars.values():
            var.set(True)
        for var in self._voice_vars.values():
            var.set(True)

    def _deselect_all_packages(self) -> None:
        for var in self.sys_vars.values():
            var.set(False)
        for var in self.py_vars.values():
            var.set(False)
        for var in self._voice_vars.values():
            var.set(False)

    def _show_help(self) -> None:
        help_text = (
            "🐉 DRACHENWARTUNG - HILFE\n"
            "═══════════════════════════════════════\n\n"
            "📦 PAKETE:\n"
            "  • Systempakete: Externe Tools (ffmpeg, yt-dlp, etc.)\n"
            "  • Python-Pakete: Pip/uv-Pakete für Python-Funktionalität\n"
            "  • Piper-Stimmen: TTS-Stimmen für Sprachausgabe (installierbar!)\n\n"
            "🔄 UPDATES:\n"
            "  • Kritisch: Nur die wichtigsten Pakete (schnell)\n"
            "  • Alle: Alle installierten pip-Pakete (kann dauern)\n\n"
            "⌨️ TASTATURKÜRZEL:\n"
            "  • Escape / Strg+W   : Dialog schließen\n"
            "  • Strg+C            : Laufende Installation abbrechen\n"
            "  • Strg+F            : Suchfeld fokussieren\n"
            "  • Strg+S            : requirements.txt exportieren\n"
            "  • Strg+A            : Alle Pakete auswählen\n"
            "  • Strg+D            : Alle Pakete abwählen\n"
            "  • F1                : Diese Hilfe anzeigen\n\n"
            "💡 TIPPS:\n"
            "  • Verwenden Sie eine virtuelle Umgebung (venv) für Sicherheit\n"
            "  • Piper-Stimmen werden parallel heruntergeladen – sehr schnell!\n"
        )
        DarkMessageBox.showinfo("🐉 Hilfe", help_text, parent=self.dialog)

    @staticmethod
    def _detect_package_manager() -> str:
        if IS_WINDOWS:
            return "winget" if shutil.which("winget") else "choco"
        if IS_MACOS:
            return "brew" if shutil.which("brew") else "manual"
        try:
            with open("/etc/os-release") as f:
                content = f.read()
            if "ID=ubuntu" in content or "ID=debian" in content:
                return "apt"
            if "ID=fedora" in content or "ID=rhel" in content:
                return "dnf"
            if "ID=arch" in content or "ID=manjaro" in content:
                return "pacman"
            if "ID=opensuse" in content:
                return "zypper"
            if "ID=alpine" in content:
                return "apk"
        except Exception:
            pass
        for manager, binary in [
            ("apt", "apt-get"),
            ("dnf", "dnf"),
            ("yum", "yum"),
            ("pacman", "pacman"),
            ("zypper", "zypper"),
            ("apk", "apk"),
        ]:
            if shutil.which(binary):
                return manager
        return "manual"

    @staticmethod
    def _is_tkdnd_installed() -> bool:
        """Prüft, ob tkdnd (Drag & Drop für Tkinter) verfügbar ist.
        Verwendet ein temporäres Tk‑Fenster, das nach der Prüfung sauber zerstört wird.
        Verzichtet auf root.quit(), um unbeabsichtigtes Beenden der Haupt‑GUI zu vermeiden.
        """
        root = None
        try:
            import tkinter as tk

            root = tk.Tk()
            root.withdraw()

            if DEBUG_LEVEL >= 3:
                log_debug("install_dlg", "tkdnd-Prüfung gestartet (Fenster versteckt)")

            result = root.tk.eval("package require tkdnd")

            if DEBUG_LEVEL >= 3:
                log_debug("install_dlg", f"tkdnd verfügbar: {bool(result)}")

            return bool(result)

        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("install_dlg", f"tkdnd-Prüfung fehlgeschlagen: {e}")
            return False

        finally:
            if root is not None:
                with contextlib.suppress(tk.TclError):
                    root.destroy()

    @classmethod
    def _is_vlc_installed(cls) -> bool:
        cache_attr = "_vlc_installed_cache"
        cached = getattr(cls, cache_attr, None)
        if isinstance(cached, bool):
            return cached
        try:
            if shutil.which("vlc"):
                setattr(cls, cache_attr, True)
                return True
        except Exception:
            pass
        if IS_WINDOWS:
            typical_paths = [
                os.path.expandvars(r"%ProgramFiles%\VideoLAN\VLC\vlc.exe"),
                os.path.expandvars(r"%ProgramFiles(x86)%\VideoLAN\VLC\vlc.exe"),
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]
            for path in typical_paths:
                if os.path.isfile(path):
                    setattr(cls, cache_attr, True)
                    return True
        setattr(cls, cache_attr, False)
        return False

    @staticmethod
    def _is_admin() -> bool:
        if not hasattr(InstallDependencyDialog, "_admin_cache"):
            InstallDependencyDialog._admin_cache = None
        if InstallDependencyDialog._admin_cache is not None:
            return InstallDependencyDialog._admin_cache

        is_admin = False
        try:
            if IS_WINDOWS:
                try:
                    import ctypes

                    is_admin = ctypes.windll.shell32.IsUserAnAdmin() != 0
                except Exception:
                    try:
                        import ctypes
                        import ctypes.wintypes

                        OpenProcessToken = ctypes.windll.advapi32.OpenProcessToken
                        GetTokenInformation = ctypes.windll.advapi32.GetTokenInformation
                        TOKEN_QUERY = 0x0008
                        TOKEN_ELEVATION = 20
                        TokenElevation = ctypes.c_ulong()
                        h_process = ctypes.windll.kernel32.GetCurrentProcess()
                        h_token = ctypes.wintypes.HANDLE()
                        if OpenProcessToken(
                            h_process,
                            TOKEN_QUERY,
                            ctypes.byref(h_token),
                        ):
                            size = ctypes.c_ulong(4)
                            if GetTokenInformation(
                                h_token,
                                TOKEN_ELEVATION,
                                ctypes.byref(TokenElevation),
                                size,
                                ctypes.byref(size),
                            ):
                                is_admin = TokenElevation.value != 0
                            ctypes.windll.kernel32.CloseHandle(h_token)
                    except Exception:
                        pass
            else:
                try:
                    is_admin = os.geteuid() == 0
                except AttributeError:
                    with contextlib.suppress(Exception):
                        is_admin = os.getuid() == 0
                if (
                    not is_admin
                    and ("SUDO_USER" in os.environ or "SUDO_UID" in os.environ)
                    and DEBUG_LEVEL >= 3
                ):
                    log_debug("install_dlg", "SUDO_USER gefunden, aber euid != 0")
        except Exception:
            pass

        InstallDependencyDialog._admin_cache = is_admin
        return is_admin

    def build_ui(self) -> None:
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui gestartet")

        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        canvas = tk.Canvas(self.main, bg=theme.BG_PRIMARY, highlightthickness=0)
        scrollbar = tk.Scrollbar(self.main, orient="vertical", command=canvas.yview)
        self.scrollable_frame = tk.Frame(canvas, bg=theme.BG_PRIMARY)

        self.scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all")),
        )
        canvas.create_window((0, 0), window=self.scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        def _on_mousewheel(event):
            try:
                if hasattr(event, "delta") and event.delta:
                    scroll = int(-1 * (event.delta / 120))
                elif hasattr(event, "num"):
                    if event.num == 4:
                        scroll = -1
                    elif event.num == 5:
                        scroll = 1
                    else:
                        scroll = 0
                else:
                    scroll = 0
                if scroll:
                    canvas.yview_scroll(scroll, "units")
            except Exception:
                pass
            return "break"

        for widget in (canvas, self.scrollable_frame):
            widget.bind("<MouseWheel>", _on_mousewheel, add="+")
            widget.bind("<Button-4>", _on_mousewheel, add="+")
            widget.bind("<Button-5>", _on_mousewheel, add="+")

        self._build_search_bar()
        try:
            self._build_system_packages_section()
            self._build_python_packages_section()
            self._build_piper_voices_section()
            self._build_update_section()
            self._build_output_section()
            self._build_control_buttons()
            self._build_export_import_bar()
            self._build_quick_actions_bar()
            self._build_status_bar()
            self._check_pydantic_and_update_ui()
        except Exception as e:
            logger.exception("Fehler beim Aufbau der UI‑Abschnitte: %s", e)
            error_label = tk.Label(
                self.scrollable_frame,
                text="⚠️ Fehler beim Laden der Oberfläche. Bitte Log prüfen.",
                bg=theme.BG_PRIMARY,
                fg=theme.ERROR,
                font=("Segoe UI", 10, "bold"),
            )
            error_label.pack(pady=20)

        self.scrollable_frame.update_idletasks()
        canvas.configure(scrollregion=canvas.bbox("all"))
        self._refresh_package_status()

        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui abgeschlossen")

    def _build_search_bar(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        search_frame = tk.Frame(self.scrollable_frame, bg=theme.BG_PRIMARY)
        search_frame.pack(fill="x", pady=(0, 5), padx=5)

        tk.Label(
            search_frame,
            text="🔍",
            bg=theme.BG_PRIMARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
        ).pack(side="left", padx=(0, 5))

        self.search_entry = tk.Entry(
            search_frame,
            textvariable=self._search_var,
            bg=theme.INPUT_BG,
            fg=theme.TEXT_PRIMARY,
            insertbackground=theme.TEXT_PRIMARY,
            width=30,
            font=Fonts.PRIMARY,
        )
        self.search_entry.pack(side="left", fill="x", expand=True)
        ToolTip(self.search_entry, "Pakete durchsuchen (Strg+F)")

        tk.Button(
            search_frame,
            text="✕",
            command=lambda: self._search_var.set(""),
            bg=theme.BG_TERTIARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.SMALL,
            cursor="hand2",
            relief="flat",
            padx=5,
        ).pack(side="left", padx=5)

        filter_var = tk.StringVar(value="all")
        filter_menu = ttk.Combobox(
            search_frame,
            textvariable=filter_var,
            values=["all", "installed", "missing"],
            state="readonly",
            width=12,
            font=Fonts.SMALL,
        )
        filter_menu.pack(side="left", padx=5)
        ToolTip(filter_menu, "Filter: alle, installierte, fehlende")
        filter_var.trace_add(
            "write",
            lambda *_: self._apply_status_filter(filter_var.get()),
        )

        self.search_info_label = tk.Label(
            search_frame,
            text="",
            bg=theme.BG_PRIMARY,
            fg=theme.TEXT_SECONDARY,
            font=Fonts.SMALL,
        )
        self.search_info_label.pack(side="left", padx=10)

    def _apply_status_filter(self, status: str) -> None:
        self._filter_by_status = status
        self._update_visible_packages()

    def _apply_search_filter(self) -> None:
        query = self._search_var.get().strip().lower()
        self._search_filter = query or None
        self._update_visible_packages()

        if self._search_filter or self._filter_by_status != "all":
            visible = 0
            for var_dict in (self.sys_vars, self.py_vars, self._voice_vars):
                visible += sum(1 for _ in var_dict.values())
            self.search_info_label.config(text=f"{visible} Pakete gefunden")
        else:
            self.search_info_label.config(text="")

    def _update_visible_packages(self) -> None:

        for pkg_name, var in self.sys_vars.items():
            visible = self._package_matches_search(pkg_name)
            if visible and self._filter_by_status != "all":
                installed = self._is_tool_installed(pkg_name)
                if (self._filter_by_status == "installed" and not installed) or (
                    self._filter_by_status == "missing" and installed
                ):
                    visible = False
            widget = self._find_checkbutton_by_var(var)
            if widget and widget.winfo_exists():
                if visible:
                    widget.grid()
                else:
                    widget.grid_remove()

        for pkg_name, var in self.py_vars.items():
            visible = self._package_matches_search(pkg_name)
            if visible and self._filter_by_status != "all":
                installed = self._previous_pkg_status.get(pkg_name, False)
                if (self._filter_by_status == "installed" and not installed) or (
                    self._filter_by_status == "missing" and installed
                ):
                    visible = False
            widget = self._find_checkbutton_by_var(var)
            if widget and widget.winfo_exists():
                if visible:
                    widget.grid()
                else:
                    widget.grid_remove()

        for voice_name, var in self._voice_vars.items():
            visible = self._package_matches_search(voice_name)
            if visible and self._filter_by_status != "all":
                try:
                    cache_dir = TTSManager.get_piper_cache_dir()
                except Exception:
                    cache_dir = ""
                model_path = (
                    os.path.join(cache_dir, f"{voice_name}.onnx") if cache_dir else ""
                )
                json_path = model_path + ".json" if model_path else ""
                installed = os.path.exists(model_path) and os.path.exists(json_path)
                if (self._filter_by_status == "installed" and not installed) or (
                    self._filter_by_status == "missing" and installed
                ):
                    visible = False
            widget = self._find_checkbutton_by_var(var)
            if widget and widget.winfo_exists():
                if visible:
                    widget.grid()
                else:
                    widget.grid_remove()

    def _package_matches_search(self, name: str) -> bool:
        if not self._search_filter:
            return True
        return self._search_filter in name.lower()

    def _build_system_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        sys_frame = tk.LabelFrame(
            self.scrollable_frame,
            text="🖥️ Systempakete (externe Tools)",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=5,
        )
        sys_frame.pack(fill="x", pady=5, padx=5)

        self.sys_vars = {}
        for pkg_name, pkg_data in self.SYSTEM_PACKAGES.items():
            installed = self._is_tool_installed(pkg_name)

            if installed:
                lbl = tk.Label(
                    sys_frame,
                    text=f"✅ {pkg_name} (bereits installiert)",
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                )
                lbl.pack(fill="x", pady=1)
                ToolTip(lbl, f"{pkg_name} ist bereits installiert und verfügbar.")
                continue

            if not (
                self.pkg_manager in pkg_data
                or "pip" in pkg_data
                or "fallback" in pkg_data
            ):
                lbl = tk.Label(
                    sys_frame,
                    text=f"⚠️ {pkg_name} (nicht unterstützt auf diesem System)",
                    bg=theme.BG_SECONDARY,
                    fg=theme.WARNING,
                    anchor="w",
                )
                lbl.pack(fill="x", pady=1)
                ToolTip(
                    lbl,
                    f"{pkg_name} kann auf diesem System nicht automatisch installiert werden.",
                )
                continue

            is_critical = pkg_name in self.CRITICAL_SYSTEM_PACKAGES
            var = tk.BooleanVar(value=is_critical)

            cb = tk.Checkbutton(
                sys_frame,
                text=f"{pkg_name} {'⚠️ kritisch' if is_critical else '(optional)'}",
                variable=var,
                bg=theme.BG_SECONDARY,
                fg=theme.TEXT_PRIMARY,
                selectcolor=theme.BG_TERTIARY,
                activebackground=theme.BG_HOVER,
                anchor="w",
            )
            cb.pack(fill="x", pady=1)
            self.sys_vars[pkg_name] = var
            self._checkbutton_cache[f"sys_{pkg_name}"] = cb

            tooltip = f"Installiert {pkg_name} über {self.pkg_manager or 'Fallback'}"
            if is_critical:
                tooltip += "\n⚠️ Für den Betrieb zwingend erforderlich"
            ToolTip(cb, tooltip)

        if not self.in_venv and not self._is_admin():
            warn_frame = tk.Frame(sys_frame, bg=theme.BG_SECONDARY)
            warn_frame.pack(fill="x", pady=5)

            tk.Label(
                warn_frame,
                text="⚠️  Sie installieren Pakete systemweit (kein venv).\n"
                "   Tipp: Verwenden Sie eine virtuelle Umgebung für mehr Sicherheit.",
                bg=theme.BG_SECONDARY,
                fg=theme.WARNING,
                font=Fonts.SMALL,
                justify="left",
            ).pack(side="left", fill="x", expand=True)

            tk.Button(
                warn_frame,
                text="🔧 venv erstellen",
                command=self._create_venv_and_restart,
                bg=theme.DRAGON_GREEN,
                fg=theme.TEXT_PRIMARY,
                font=Fonts.BUTTON,
                padx=8,
                pady=2,
                cursor="hand2",
            ).pack(side="right", padx=5)

        if IS_WINDOWS and self.pkg_manager == "winget" and not self._is_admin():
            tk.Button(
                sys_frame,
                text="🛡️ Als Administrator neu starten",
                command=self._restart_as_admin,
                bg=theme.WARNING,
                fg=theme.TEXT_PRIMARY,
                font=Fonts.BUTTON,
                padx=10,
                pady=5,
                cursor="hand2",
                activebackground=theme.DRAGON_GREEN,
            ).pack(pady=(5, 0))

    def _build_python_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        py_frame = tk.LabelFrame(
            self.scrollable_frame,
            text="🐍 Python-Pakete (pip/uv)",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=5,
        )
        py_frame.pack(fill="x", pady=5, padx=5)

        left_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        left_col.pack(side="left", fill="both", expand=True, padx=5)

        right_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        right_col.pack(side="right", fill="both", expand=True, padx=5)

        self.py_vars = {}
        self.package_labels.clear()

        package_specs = self._get_all_python_packages()
        half = len(package_specs) // 2

        for i, (pkg_name, display_text, _check_func, pkg_install_name) in enumerate(
            package_specs,
        ):
            if pkg_name == "pywin32" and not IS_WINDOWS:
                continue

            target = left_col if i < half else right_col
            installed, version = self._check_python_package(pkg_name, pkg_install_name)

            if not installed:
                is_critical = pkg_name in self.CRITICAL_PYTHON_PACKAGES
                var = tk.BooleanVar(value=is_critical)

                cb = tk.Checkbutton(
                    target,
                    text=f"{display_text} {'⚠️' if is_critical else ''}",
                    variable=var,
                    bg=theme.BG_SECONDARY,
                    fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY,
                    activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.pack(fill="x", pady=1)
                self.py_vars[pkg_name] = var
                self._checkbutton_cache[f"py_{pkg_name}"] = cb

                tooltip = f"Installiert {pkg_name} mit pip"
                if is_critical:
                    tooltip += "\n⚠️ Für den Betrieb zwingend erforderlich"
                ToolTip(cb, tooltip)
            else:
                lbl = tk.Label(
                    target,
                    text=(
                        f"✅ {display_text} (v{version})"
                        if version
                        else f"✅ {display_text}"
                    ),
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                )
                lbl.pack(fill="x", pady=1)
                self.package_labels.append((pkg_name, lbl))

                tooltip = f"{pkg_name} ist installiert"
                if version:
                    tooltip += f" (Version {version})"
                ToolTip(lbl, tooltip)

        python_version = f"{sys.version_info.major}.{sys.version_info.minor}.{
            sys.version_info.micro
        }"
        tk.Label(
            py_frame,
            text=f"🐍 Python {python_version} ({
                'venv' if self.in_venv else 'systemweit'
            })",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_SECONDARY,
            font=Fonts.SMALL,
            anchor="e",
        ).pack(side="bottom", fill="x", pady=(5, 0))

