    def __init__(self, parent: tk.Tk, gui: DragonWhispererGUI) -> None:
        """Initialisiert den optimierten AdvancedSettingsDialog."""
        self.parent = parent
        self.gui = gui
        self._original_theme = gui.settings.theme
        self._setup_dialog_window()
        self._loaded_tabs = set()
        self._validation_errors = {}
        self._spinbox_vars = {}
        self._pending_allowed_dirs = None
        self._pending_blacklist = None
        self._active_threads: list = []
        self._active_threads_lock = threading.RLock()
        self._search_text = tk.StringVar()
        self._search_text.trace_add("write", lambda *_: self._on_search_changed())
        self._init_search_index()
        self._load_profiles()
        self._create_tk_variables()
        self._build_ui()
        self._setup_ttk_styles()
        self._load_current_settings()
        self._setup_validation_styles()
        self._setup_global_mousewheel_binding()

        if DEBUG_LEVEL >= 3:
            log_debug("settings", "AdvancedSettingsDialog.__init__ abgeschlossen")

    def update_status_label(
        self,
        text: str,
        *,
        is_error: bool = False,
        is_success: bool = False,
        is_warning: bool = False,
    ) -> None:
        """Aktualisiert das Status-Label im Dialog."""
        import threading as _threading

        _is_main = _threading.current_thread() is _threading.main_thread()

        try:
            if is_error:
                _level = "ERROR"
            elif is_success:
                _level = "OK"
            elif is_warning:
                _level = "WARN"
            else:
                _level = "INFO"

            log_debug(
                "settings",
                f"update_status_label [{_level}]: {text!r} (main_thread={_is_main})",
            )
        except Exception:
            pass

        if not _is_main:
            try:
                _root = (
                    getattr(self, "root", None)
                    or getattr(self, "dialog", None)
                    or getattr(self, "parent", None)
                )
                if _root is not None and hasattr(_root, "after"):
                    _root.after(
                        0,
                        lambda: self.update_status_label(
                            text,
                            is_error=is_error,
                            is_success=is_success,
                            is_warning=is_warning,
                        ),
                    )
                    return
            except Exception:
                pass

        _updated_via = None
        try:
            _status_var = getattr(self, "status_var", None)
            if _status_var is not None and hasattr(_status_var, "set"):
                _status_var.set(text)
                _updated_via = "status_var"
        except Exception as _sv_exc:
            with contextlib.suppress(Exception):
                log_debug(
                    "settings",
                    f"update_status_label: status_var.set fehlge"
                    f"schlagen ({type(_sv_exc).__name__}): "
                    f"{_sv_exc}",
                )

        if _updated_via is None:
            try:
                _label = getattr(self, "status_label", None)
                if _label is not None and hasattr(_label, "config"):
                    _label.config(text=text)
                    _updated_via = "status_label"
            except Exception as _lbl_exc:
                with contextlib.suppress(Exception):
                    log_debug(
                        "settings",
                        f"update_status_label: status_label fehlge"
                        f"schlagen ({type(_lbl_exc).__name__}): "
                        f"{_lbl_exc}",
                    )

        if _updated_via is None:
            try:
                import sys as _sys

                print(f"[STATUS] {text}", file=_sys.stderr)
                _updated_via = "stderr"
            except Exception:
                pass

        try:
            _label = getattr(self, "status_label", None)
            if _label is not None and hasattr(_label, "config"):
                _fg_color = None
                if is_error:
                    _fg_color = "#f85149"
                elif is_success:
                    _fg_color = "#3fb950"
                elif is_warning:
                    _fg_color = "#d29922"

                if _fg_color is not None:
                    with contextlib.suppress(Exception):
                        _label.config(fg=_fg_color)
        except Exception:
            pass

    def _setup_dialog_window(self) -> None:
        """Erstellt und konfiguriert das Dialogfenster."""
        self.dialog = tk.Toplevel(self.parent)
        self.dialog.title("🐉 Advanced Settings")
        self.dialog.geometry("950x800")
        self.dialog.configure(bg=self.gui.current_theme.BG_PRIMARY)
        self.dialog.transient(self.parent)
        self.dialog.grab_set()
        self.dialog.update_idletasks()
        x = (
            self.parent.winfo_x()
            + (self.parent.winfo_width() - self.dialog.winfo_width()) // 2
        )
        y = (
            self.parent.winfo_y()
            + (self.parent.winfo_height() - self.dialog.winfo_height()) // 2
        )
        self.dialog.geometry(f"+{x}+{y}")
        if hasattr(self.gui, "_open_dialogs"):
            self.gui._open_dialogs.append(self.dialog)
            self.dialog.protocol("WM_DELETE_WINDOW", self._on_close)

        self._scrollable_canvases = []

