    def _show_error_dialog(
        self,
        title: str,
        message: str,
        parent: tk.Misc | None = None,
    ) -> None:
        """Zeigt einen modalen Fehler-Dialog mit mehrstufigem Fallback."""

        if getattr(self, "_in_error_dialog", False):
            with contextlib.suppress(Exception):
                logger.warning(
                    "[SETTINGS] _show_error_dialog reentrant "
                    "aufgerufen – verhindert (Titel=%r)",
                    title,
                )
            return

        self._in_error_dialog = True
        try:
            _caller = "unknown"
            try:
                import traceback as _tb

                _stack = _tb.extract_stack(limit=3)
                if len(_stack) >= 2:
                    _frame = _stack[-2]
                    _caller = f"{_frame.name}@{_frame.lineno}"
            except Exception:
                pass

            with contextlib.suppress(Exception):
                log_debug(
                    "settings",
                    f"_show_error_dialog AUFRUF: title={title!r}, "
                    f"msg_len={len(message)}, caller={_caller}, "
                    f"parent={'auto' if parent is None else 'given'}",
                )

            if parent is None:
                for _attr in (
                    "dialog",
                    "root",
                    "toplevel",
                    "master",
                    "window",
                ):
                    _candidate = getattr(self, _attr, None)
                    if _candidate is None:
                        continue
                    try:
                        if _candidate.winfo_exists():
                            parent = _candidate
                            break
                    except Exception:
                        continue

            _dmb = globals().get("DarkMessageBox")
            if _dmb is not None and hasattr(_dmb, "showerror"):
                try:
                    _dmb.showerror(title, message, parent=parent)
                    with contextlib.suppress(Exception):
                        log_debug(
                            "settings",
                            "_show_error_dialog: DarkMessageBox OK",
                        )
                    return
                except TypeError:
                    try:
                        _dmb.showerror(title, message)
                        with contextlib.suppress(Exception):
                            log_debug(
                                "settings",
                                "_show_error_dialog: DarkMessageBox OK (ohne parent)",
                            )
                        return
                    except Exception as _dmb_exc:
                        with contextlib.suppress(Exception):
                            logger.warning(
                                "[SETTINGS] DarkMessageBox.showerror "
                                "fehlgeschlagen (%s): %s – Fallback",
                                type(_dmb_exc).__name__,
                                _dmb_exc,
                            )
                except Exception as _dmb_exc:
                    with contextlib.suppress(Exception):
                        logger.warning(
                            "[SETTINGS] DarkMessageBox.showerror "
                            "fehlgeschlagen (%s): %s – Fallback",
                            type(_dmb_exc).__name__,
                            _dmb_exc,
                        )

            try:
                from tkinter import messagebox as _mb

                try:
                    _mb.showerror(title, message, parent=parent)
                    with contextlib.suppress(Exception):
                        log_debug(
                            "settings",
                            "_show_error_dialog: tkinter.messagebox OK",
                        )
                    return
                except Exception as _mb_exc:
                    with contextlib.suppress(Exception):
                        logger.warning(
                            "[SETTINGS] tkinter.messagebox.showerror "
                            "fehlgeschlagen (%s): %s – Fallback "
                            "auf stderr",
                            type(_mb_exc).__name__,
                            _mb_exc,
                        )
            except ImportError:
                pass
            except Exception:
                pass

            try:
                import sys as _sys

                print(
                    f"\n[FEHLER-DIALOG – Fallback] {title}\n"
                    f"{'-' * 60}\n"
                    f"{message}\n"
                    f"{'-' * 60}\n",
                    file=_sys.stderr,
                )
            except Exception:
                pass

            with contextlib.suppress(Exception):
                logger.error(
                    "[SETTINGS] _show_error_dialog: Alle GUI-"
                    "Fallbacks fehlgeschlagen. Titel=%r, "
                    "Nachricht=%r, caller=%s",
                    title,
                    message[:200] + ("…" if len(message) > 200 else ""),
                    _caller,
                )

        finally:
            self._in_error_dialog = False

    def _load_custom_profiles(self) -> dict[str, dict[str, Any]]:
        """Lädt benutzerdefinierte Profile aus dem Dateisystem."""
        profiles_dir = PlatformUtils.get_platform_config_dir() / "profiles"
        profiles = {}
        if not profiles_dir.exists():
            return profiles
        for file in profiles_dir.glob("*.json"):
            try:
                with open(file, encoding="utf-8") as f:
                    data = json.load(f)
                profiles[file.stem] = data
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
        return profiles

    @staticmethod
    def _is_scroll_inhibited(widget: tk.Widget) -> bool:
        """Return True if *widget* should handle mouse wheel events itself
        and not forward them to a surrounding canvas.
        """
        try:
            if not widget.winfo_exists():
                return True
        except (tk.TclError, AttributeError):
            return True
        if isinstance(widget, (tk.Listbox, ttk.Combobox)):
            return True

        return bool(hasattr(widget, "yview") and callable(widget.yview))

