    def _apply_theme_to_widget_tree(self, root_widget: tk.Widget) -> None:
        """Wendet das aktuelle Theme rekursiv (iterativ) auf alle Widgets im
        Teilbaum ab *root_widget* an.
        """
        theme = getattr(self, "current_theme", None) or DarkTheme()
        if (
            hasattr(self, "gui")
            and self.gui is not None
            and hasattr(self.gui, "current_theme")
        ):
            theme = self.gui.current_theme
        if theme is None:
            try:
                theme = CURRENT_THEME
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
        if theme is None:
            theme = DarkTheme()

        def _theme_attr(attr: str, default: str) -> str:
            """Liefert *attr* aus dem aktuellen Theme, sonst *default* (via DarkTheme)."""
            return getattr(theme, attr, getattr(DarkTheme(), attr, default))

        def _safe_configure(w: tk.Widget, **kwargs) -> None:
            """Wendet *kwargs* auf *w* an, fängt ``TclError`` und andere Fehler ab."""
            if not kwargs:
                return
            clean = {
                k: v for k, v in kwargs.items() if isinstance(k, str) and k.strip()
            }
            if not clean:
                return
            try:
                w.configure(**clean)
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("theme", f"_safe_configure({w}) Fehler: {e}")

        stack: list[tk.Widget] = [root_widget]
        updated = 0
        skipped = 0

        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue

            w_class = widget.__class__

            if issubclass(w_class, ttk.Widget):
                skipped += 1
                try:
                    stack.extend(widget.winfo_children())
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                continue

            if w_class == scrolledtext.ScrolledText:
                try:
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        insertbackground=_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    updated += 1
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

                try:
                    vbar = widget.vbar
                    if vbar and vbar.winfo_exists():
                        _safe_configure(
                            vbar,
                            bg=_theme_attr("SCROLLBAR", "#b3b3b3"),
                            activebackground=_theme_attr("SCROLLBAR_HOVER", "#999999"),
                            troughcolor=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                        updated += 1
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

                try:
                    stack.extend(widget.winfo_children())
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                continue

            try:
                if w_class in (tk.Label,):
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_PRIMARY", "#ffffff"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    updated += 1
                elif w_class in (tk.Button,):
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_TERTIARY", "#cccccc"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        activebackground=_theme_attr("BG_HOVER", "#dddddd"),
                        activeforeground=_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    updated += 1
                elif w_class in (tk.Checkbutton, tk.Radiobutton):
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectcolor=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        activebackground=_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        activeforeground=_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    updated += 1
                elif w_class in (tk.Entry, tk.Spinbox, tk.Text):
                    input_bg = _theme_attr(
                        "INPUT_BG",
                        _theme_attr("BG_TERTIARY", "#ffffff"),
                    )
                    _safe_configure(
                        widget,
                        bg=input_bg,
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        insertbackground=_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    if w_class == tk.Spinbox:
                        _safe_configure(
                            widget,
                            buttonbackground=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                    updated += 1
                elif w_class == tk.Frame:
                    _safe_configure(widget, bg=_theme_attr("BG_PRIMARY", "#ffffff"))
                    updated += 1
                elif w_class == tk.LabelFrame:
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    updated += 1
                elif w_class == tk.Scale:
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        troughcolor=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    updated += 1
                elif w_class == tk.Listbox:
                    _safe_configure(
                        widget,
                        bg=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    updated += 1
                elif w_class == tk.Scrollbar:
                    _safe_configure(
                        widget,
                        bg=_theme_attr("SCROLLBAR", "#b3b3b3"),
                        activebackground=_theme_attr("SCROLLBAR_HOVER", "#999999"),
                        troughcolor=_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    updated += 1
                elif w_class == tk.Canvas:
                    _safe_configure(widget, bg=_theme_attr("BG_PRIMARY", "#ffffff"))
                    updated += 1
                else:
                    try:
                        widget.configure(
                            bg=_theme_attr("BG_PRIMARY", "#ffffff"),
                            fg=_theme_attr("TEXT_PRIMARY", "#000000"),
                        )
                        updated += 1
                    except Exception as e:
                        if DEBUG_LEVEL >= 3:
                            log_debug("theme", f"Unbekanntes Widget {w_class}: {e}")
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("theme", f"Fehler bei {w_class.__name__}: {e}")

            try:
                stack.extend(widget.winfo_children())
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        if DEBUG_LEVEL >= 2:
            log_debug(
                "theme",
                f"_apply_theme_to_widget_tree: {updated} Widgets aktualisiert, "
                f"{skipped} ttk‑Widgets übersprungen",
            )

    def _on_tab_changed(self, event: tk.Event) -> None:
        """Wird aufgerufen, wenn der Benutzer ein Tab wechselt."""
        try:
            current_tab_id = self.notebook.select()
            current_widget = self.notebook.nametowidget(current_tab_id)
        except tk.TclError as e:
            logger.warning(f"Konnte aktuelles Tab nicht ermitteln: {e}")
            return

        if DEBUG_LEVEL >= 3:
            tab_text = self.notebook.tab(current_tab_id, "text")
            log_debug("settings", f"Tab gewechselt zu: '{tab_text}'")

        if current_widget is self.tab_audio and "audio" not in self._loaded_tabs:
            self._create_audio_vad_tab()
            self._apply_theme_to_widget_tree(self.tab_audio)
            self._loaded_tabs.add("audio")
            self._bind_validation_recursive(self.tab_audio)

        elif (
            current_widget is self.tab_packages and "packages" not in self._loaded_tabs
        ):
            self._create_packages_tab()
            self._apply_theme_to_widget_tree(self.tab_packages)
            self._loaded_tabs.add("packages")

        elif current_widget is self.tab_model and "model" not in self._loaded_tabs:
            self._create_model_inference_tab()
            self._apply_theme_to_widget_tree(self.tab_model)
            self._loaded_tabs.add("model")
            self._bind_validation_recursive(self.tab_model)

        elif (
            current_widget is self.tab_translate
            and "translate" not in self._loaded_tabs
        ):
            self._create_translation_tts_tab()
            self._apply_theme_to_widget_tree(self.tab_translate)
            self._loaded_tabs.add("translate")
            self._bind_validation_recursive(self.tab_translate)

        elif current_widget is self.tab_gui and "gui" not in self._loaded_tabs:
            self._create_gui_display_tab()
            self._apply_theme_to_widget_tree(self.tab_gui)
            self._loaded_tabs.add("gui")
            self._bind_validation_recursive(self.tab_gui)

        elif (
            current_widget is self.tab_advanced and "advanced" not in self._loaded_tabs
        ):
            self._create_advanced_system_tab()
            self._apply_theme_to_widget_tree(self.tab_advanced)
            self._loaded_tabs.add("advanced")
            self._bind_validation_recursive(self.tab_advanced)

        try:
            self._setup_ttk_styles()
        except Exception as e:
            logger.warning(f"Fehler beim Aktualisieren der ttk-Styles: {e}")

        theme = self.gui.current_theme
        for tab_name in self._loaded_tabs:
            tab_attr = f"tab_{tab_name}"
            if hasattr(self, tab_attr):
                tab_widget = getattr(self, tab_attr)
                if tab_widget is None or not tab_widget.winfo_exists():
                    continue
                try:
                    for child in tab_widget.winfo_children():
                        if isinstance(child, tk.Canvas):
                            child.configure(bg=theme.BG_PRIMARY)
                except tk.TclError as e:
                    logger.debug("Ignored TclError: %s", e)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

    def _make_scrollable(self, parent: tk.Widget) -> tk.Frame:
        """Erstellt einen scrollbaren Container (Canvas + Scrollbar) und gibt
        den inneren Frame zurück, in den die eigentlichen Inhalte gesetzt
        werden können.
        """
        SCROLL_SPEED = 2

        if DEBUG_LEVEL >= 3:
            log_debug("scrollframe", f"_make_scrollable: parent={parent!r}")

        try:
            theme = self.gui.current_theme
        except Exception:
            theme = DarkTheme()

        canvas = tk.Canvas(
            parent,
            bg=theme.BG_PRIMARY,
            highlightthickness=0,
            borderwidth=0,
        )

        scrollbar = tk.Scrollbar(
            parent,
            orient="vertical",
            command=canvas.yview,
            bg=theme.SCROLLBAR,
            activebackground=theme.SCROLLBAR_HOVER,
            troughcolor=theme.BG_TERTIARY,
        )

        scrollable = tk.Frame(canvas, bg=theme.BG_PRIMARY)
        scrollable._canvas = canvas

        canvas.create_window((0, 0), window=scrollable, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        def _on_configure(event: tk.Event) -> None:
            """Aktualisiert die Scrollregion, sobald der Inhalt wächst."""
            try:
                canvas.update_idletasks()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        scrollable.bind("<Configure>", _on_configure)

        def _widget_handles_own_scroll(widget: tk.Widget) -> bool:
            """Prüft, ob ein Widget eigene Scroll‑Fähigkeiten besitzt
            und daher das Mausrad selbst verarbeiten sollte.
            """
            try:
                if not widget.winfo_exists():
                    return True
            except (tk.TclError, AttributeError):
                return True

            if isinstance(widget, (tk.Listbox, ttk.Combobox)):
                return True
            return bool(hasattr(widget, "yview") and callable(widget.yview))

        def _on_mousewheel(event: tk.Event) -> str:
            """Scrollt den Canvas, wenn der Mauszeiger über ihm liegt.
            Gibt "break" zurück, um doppeltes Scrollen durch globale
            Handler zu verhindern.
            """
            source = event.widget

            if _widget_handles_own_scroll(source):
                return None

            if event.num == 4:
                canvas.yview_scroll(-SCROLL_SPEED, "units")
                return "break"
            if event.num == 5:
                canvas.yview_scroll(SCROLL_SPEED, "units")
                return "break"

            if hasattr(event, "delta"):
                step = int(-1 * (event.delta / 120))
                step = max(-3 * SCROLL_SPEED, min(3 * SCROLL_SPEED, step))
                canvas.yview_scroll(step, "units")
                return "break"

        for target in (canvas, scrollable):
            target.bind("<MouseWheel>", _on_mousewheel, add="+")
            target.bind("<Button-4>", _on_mousewheel, add="+")
            target.bind("<Button-5>", _on_mousewheel, add="+")

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        if hasattr(self, "_scrollable_canvases"):
            self._scrollable_canvases.append(canvas)
        else:
            self._scrollable_canvases = [canvas]

        if DEBUG_LEVEL >= 3:
            log_debug(
                "scrollframe",
                f"_make_scrollable: scrollbar={scrollbar!r}, "
                f"canvas={canvas!r}, parent={parent!r}, "
                f"registered canvas count={len(self._scrollable_canvases)}, "
                f"scroll_speed={SCROLL_SPEED}",
            )

        return scrollable

    def _create_audio_vad_tab(self) -> None:
        """Erstellt den Inhalt des Tabs "Audio & VAD" (Lazy Loading)."""
        parent = self._make_scrollable(self.tab_audio)

        audio_frame = tk.LabelFrame(
            parent,
            text=" Audio Konfiguration ",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.SUBTITLE,
            padx=10,
            pady=10,
            relief="flat",
            bd=0,
            highlightthickness=0,
        )
        audio_frame.pack(fill="x", padx=5, pady=5)

        creation_errors = []

        def safe_create(widget_cls, parent, **kwargs):
            try:
                widget = widget_cls(parent, **kwargs)
                return widget
            except tk.TclError as e:
                creation_errors.append(str(e))
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "audio_tab",
                        f"Fehler beim Erstellen von {widget_cls.__name__}: {e}",
                    )
                return tk.Label(parent, text="⚠️ Fehler", bg="red", fg="white")

        sr = self.gui.advanced_settings.config.SAMPLE_RATE
        lbl = safe_create(
            tk.Label,
            audio_frame,
            text="Sample Rate (Hz):",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
        )
        val = safe_create(
            tk.Label,
            audio_frame,
            text=str(sr),
            relief="sunken",
            width=15,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.MONOSPACE,
        )
        lbl.grid(row=0, column=0, sticky="w", pady=5, padx=2)
        val.grid(row=0, column=1, sticky="w", pady=5, padx=5)
        ch = self.gui.advanced_settings.config.CHANNELS
        lbl = safe_create(
            tk.Label,
            audio_frame,
            text="Kanäle:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
        )
        val = safe_create(
            tk.Label,
            audio_frame,
            text=str(ch),
            relief="sunken",
            width=15,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.MONOSPACE,
        )
        lbl.grid(row=1, column=0, sticky="w", pady=5, padx=2)
        val.grid(row=1, column=1, sticky="w", pady=5, padx=5)
        lbl = safe_create(
            tk.Label,
            audio_frame,
            text="Audio‑Profil:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
        )
        lbl.grid(row=2, column=0, sticky="w", pady=5, padx=2)

        try:
            filter_profiles = list(
                self.gui.advanced_settings.config.FILTER_PROFILES.keys(),
            )
        except AttributeError:
            filter_profiles = ["transcription", "realtime", "noisy", "podcast"]
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "audio_tab",
                    "FILTER_PROFILES nicht verfügbar – verwende Fallback‑Liste",
                )

        profile_combo = ttk.Combobox(
            audio_frame,
            textvariable=self.profile_var_audio,
            values=filter_profiles,
            width=self.COMBO_WIDTH_MEDIUM,
            state="readonly",
            style="Dark.TCombobox",
        )
        profile_combo.grid(row=2, column=1, sticky="w", pady=5, padx=5)
        ToolTip(
            profile_combo,
            "Wählen Sie das Audio‑Filterprofil.\n"
            "• transcription – Standard für normale Aufnahmen\n"
            "• realtime – optimiert für Livestreams\n"
            "• noisy – verstärkte Rauschunterdrückung\n"
            "• podcast – ausgewogen für Sprachaufnahmen",
        )

        lbl = safe_create(
            tk.Label,
            audio_frame,
            text="Chunk‑Dauer (s):",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=Fonts.PRIMARY,
        )
        lbl.grid(row=3, column=0, sticky="w", pady=5, padx=2)

