        self.auto_save_var.set(app.auto_save_on_completion)

        self.cache_var.set(self._get_safe(adv, "max_cache_size", 200))
        self.plugin_var.set(app.enable_plugins)
        self.cookies_var.set(app.use_browser_cookies)
