        self.download_inactivity_var.set(
            self._get_safe(adv, "download_inactivity_timeout", 30.0),
        )
        self.proxy_enabled_var.set(self._get_safe(adv, "proxy_enabled", False))
        self.proxy_var.set(self._get_safe(adv, "proxy_url", ""))
        self.max_mem_var.set(self._get_safe(adv, "max_memory_mb", 1024))
        self.auto_save_interval_var.set(self._get_safe(adv, "auto_save_interval", 300))
        self.optimize_var.set(self._get_safe(adv, "optimize_translations", False))
        self.sentiment_var.set(self._get_safe(adv, "enable_sentiment_analysis", False))
        self.diarize_var.set(self._get_safe(adv, "enable_speaker_diarization", False))
