    def _autosize_dialog(self) -> None:
        """Passt die Dialoggröße an die natürliche Inhaltshöhe an."""
        import contextlib

        if self.dialog is None:
            return

        with contextlib.suppress(tk.TclError):
            if not self.dialog.winfo_exists():
                return

        try:
            self.dialog.update_idletasks()

            req_w = int(self.dialog.winfo_reqwidth())
            req_h = int(self.dialog.winfo_reqheight())
            screen_w = int(self.dialog.winfo_screenwidth())
            screen_h = int(self.dialog.winfo_screenheight())

            if req_w <= 0 or req_h <= 0:
                self._log_debug(
                    f"[AUTOSIZE] Unplausible req-Größe ({req_w}x{req_h}) – überspringe",
                    level=2,
                )
                return

            MIN_W, MIN_H = 480, 400
            SCREEN_PAD = 80

            max_w = (screen_w - SCREEN_PAD) if screen_w > 200 else req_w + 20
            max_h = (screen_h - SCREEN_PAD) if screen_h > 200 else req_h + 20

            final_w = max(MIN_W, min(max(req_w + 20, 520), max_w))
            final_h = max(MIN_H, min(req_h + 20, max_h))
            final_w = min(final_w, max_w)
            final_h = min(final_h, max_h)

            cur_w = self.dialog.winfo_width()
            cur_h = self.dialog.winfo_height()
            changed = (cur_w, cur_h) != (final_w, final_h)

            if changed:
                self.dialog.geometry(f"{final_w}x{final_h}")

            _center = getattr(self, "_center_dialog", None)
            if callable(_center):
                with contextlib.suppress(Exception):
                    _center()

            if screen_h > 200 and req_h > screen_h - 200:
                self._log_debug(
                    f"[AUTOSIZE] ⚠️ Inhalt ({req_h}px) füllt fast den "
                    f"Bildschirm ({screen_h}px) – Layout prüfen",
                    level=1,
                )

            self._log_debug(
                f"[AUTOSIZE] Dialog: {final_w}x{final_h} "
                f"(req={req_w}x{req_h}, screen={screen_w}x{screen_h}, "
                f"current={cur_w}x{cur_h}, changed={changed})",
                level=2,
            )

        except tk.TclError as e:
            self._log_debug(
                f"[AUTOSIZE] TclError (Widget zerstört?): {e}",
                level=1,
            )
        except Exception as e:
            self._log_debug(f"[AUTOSIZE] Fehler: {e}", level=1)

