    class RateLimiter:
        """Begrenzt die Häufigkeit von GUI‑Updates pro Sekunde, um die
        Oberfläche vor Überlastung durch zu viele schnelle Aufrufe zu
        schützen, **ohne** dabei wichtige Meldungen zu verwerfen.
        """

        def __init__(
            self,
            max_updates_per_second: int = 120,
            important_types: set[str] | None = None,
            enabled: bool = True,
        ) -> None:
            """Args:
            max_updates_per_second: Maximal erlaubte Updates pro
                Sekunde (muss > 0 sein).

            """
            if max_updates_per_second <= 0:
                raise ValueError("max_updates_per_second must be > 0")

            self.max_updates_per_second = max_updates_per_second
            self.min_interval = 1.0 / max_updates_per_second
            self.enabled = enabled

            self.last_calls: dict[str, float] = {}
            self._lock = threading.RLock()
            self._cleanup_counter = 0
            self._blocked_counts: dict[str, int] = defaultdict(int)
            self._last_block_warning: float = 0.0
            self._stats_lock = threading.RLock()
            self.important_types: set[str] = important_types or set()

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "RateLimiter initialisiert: max=%d/s, interval=%.2fms, "
                    "important=%s, enabled=%s",
                    max_updates_per_second,
                    self.min_interval * 1000,
                    list(self.important_types),
                    enabled,
                )

        def set_max_updates_per_second(self, max_updates: int) -> None:
            """Ändert das Rate‑Limit zur Laufzeit.
            Negative oder Nullwerte werden ignoriert.
            """
            if max_updates <= 0:
                logger.warning("Ungültiges Rate‑Limit: %d, ignoriert", max_updates)
                return

            with self._lock:
                old = self.max_updates_per_second
                self.max_updates_per_second = max_updates
                self.min_interval = 1.0 / max_updates

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "Limit geändert: %d -> %d/s, interval=%.2fms",
                    old,
                    max_updates,
                    self.min_interval * 1000,
                )

        def set_enabled(self, enabled: bool) -> None:
            """Aktiviert oder deaktiviert die Drosselung vollständig."""
            with self._lock:
                self.enabled = enabled
            if DEBUG_LEVEL >= 3:
                log_debug("ratelimit", "RateLimiter enabled=%s", enabled)

        def add_important_type(self, update_type: str) -> None:
            """Fügt einen Nachrichtentyp zur Whitelist hinzu."""
            with self._lock:
                self.important_types.add(update_type)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "Typ '%s' zur Whitelist hinzugefügt",
                    update_type,
                )

        def remove_important_type(self, update_type: str) -> None:
            """Entfernt einen Nachrichtentyp aus der Whitelist."""
            with self._lock:
                self.important_types.discard(update_type)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "Typ '%s' aus Whitelist entfernt",
                    update_type,
                )

        def can_update(
            self,
            update_type: str = "default",
            force: bool = False,
        ) -> bool:
            """Prüft, ob ein Update des angegebenen Typs jetzt durchgeführt
            werden darf.
            """
            if force:
                return True

            with self._lock:
                if not self.enabled:
                    return True

                if update_type in self.important_types:
                    if DEBUG_LEVEL >= 4 and "ratelimit" in DEBUG_COMPONENTS:
                        log_debug(
                            "ratelimit",
                            "Important update ALLOWED: type='%s', force=%s",
                            update_type,
                            force,
                        )
                    return True

                now = time.monotonic()
                last = self.last_calls.get(update_type, 0.0)

                if now - last >= self.min_interval:
                    self.last_calls[update_type] = now
                    if DEBUG_LEVEL >= 4:
                        delta_ms = (now - last) * 1000.0 if last != 0.0 else 0.0
                        log_debug(
                            "ratelimit",
                            "Update allowed: type='%s', delta=%.2fms",
                            update_type,
                            delta_ms,
                        )
                    self._cleanup_counter += 1
                    if self._cleanup_counter % 1000 == 0:
                        self._cleanup_stale_entries(now)
                    return True

                if DEBUG_LEVEL >= 4:
                    delta_ms = (now - last) * 1000.0
                    log_debug(
                        "ratelimit",
                        "Update blocked: type='%s', delta=%.2fms < %.2fms",
                        update_type,
                        delta_ms,
                        self.min_interval * 1000,
                    )

                with self._stats_lock:
                    self._blocked_counts[update_type] += 1

                with self._stats_lock:
                    total_blocks = sum(self._blocked_counts.values())
                    if total_blocks >= 60:
                        if now - self._last_block_warning >= 60.0:
                            logger.warning(
                                "RateLimiter: %d blockierte Updates in der "
                                "letzten Minute. Häufigste Typen: %s",
                                total_blocks,
                                sorted(
                                    self._blocked_counts.items(),
                                    key=lambda x: x[1],
                                    reverse=True,
                                )[:5],
                            )
                            self._blocked_counts.clear()
                            self._last_block_warning = now
                return False

        def get_block_stats(self) -> dict[str, Any]:
            """Gibt die aktuellen Block‑Statistiken als Dictionary zurück.
            Die Zähler werden **nicht** zurückgesetzt.
            """
            with self._stats_lock:
                copy = dict(self._blocked_counts)
            return {
                "total_blocks": sum(copy.values()),
                "per_type": copy,
            }

        def get_stats(self) -> dict[str, Any]:
            """Gibt aktuelle Statistiken als Dictionary zurück."""
            with self._lock:
                return {
                    "max_updates_per_second": self.max_updates_per_second,
                    "min_interval_ms": round(self.min_interval * 1000, 2),
                    "enabled": self.enabled,
                    "active_types": len(self.last_calls),
                    "type_list": list(self.last_calls.keys()),
                    "important_types": list(self.important_types),
                }

        def reset(self, update_type: str | None = None) -> None:
            """Setzt den internen Zähler zurück."""
            with self._lock:
                if update_type is None:
                    count = len(self.last_calls)
                    self.last_calls.clear()
                    if DEBUG_LEVEL >= 3:
                        log_debug("ratelimit", "Alle %d Einträge zurückgesetzt", count)
                elif update_type in self.last_calls:
                    del self.last_calls[update_type]
                    if DEBUG_LEVEL >= 3:
                        log_debug("ratelimit", "Typ '%s' zurückgesetzt", update_type)
                elif DEBUG_LEVEL >= 3:
                    log_debug(
                        "ratelimit",
                        "Typ '%s' nicht gefunden – ignoriert",
                        update_type,
                    )

        def _cleanup_stale_entries(self, now: float) -> None:
            """Entfernt Einträge, die länger als das 10‑fache des minimalen
            Intervalls nicht mehr verwendet wurden.
            """
            threshold = now - (self.min_interval * 10)
            stale = [
                key
                for key, last_time in self.last_calls.items()
                if last_time < threshold
            ]
            for key in stale:
                del self.last_calls[key]

            if stale and DEBUG_LEVEL >= 3:
                log_debug(
                    "ratelimit",
                    "%d veraltete Einträge bereinigt",
                    len(stale),
                )

        def __repr__(self) -> str:
            with self._lock:
                return (
                    f"<RateLimiter max={self.max_updates_per_second}/s, "
                    f"enabled={self.enabled}, "
                    f"active={len(self.last_calls)}, "
                    f"important={list(self.important_types)}>"
                )

    @staticmethod
    def gui_error_handler(func: Callable) -> Callable:
        """Dekorator für GUI‑Methoden: fängt Exceptions ab und zeigt sie an."""

        @wraps(func)
        def wrapper(self, *args, **kwargs):
            try:
                return func(self, *args, **kwargs)
            except Exception as e:
                logger.exception(f"Fehler in {func.__name__}: {e}")
                self.update_status(f"❌ Interner Fehler: {str(e)[:50]}")

        return wrapper

    def __init__(self) -> None:
        """Initialisiert die DragonWhispererGUI."""
        import logging
        import threading
        import time
        import tkinter as tk

        logger = logging.getLogger("dragon")
        init_start = time.perf_counter()
        self._init_start_time = init_start
        self._init_errors: list[str] = []
        self._init_warnings: list[str] = []
        self._handling_error = False
        self._after_ids: list[str] = []
        self._mainloop_running = False
        self._cleanup_done = False
        self._cleanup_lock = threading.RLock()
        self._pending_transcript_segments: list[tuple[str, float | None, str]] = []
        self._pending_transcript_lock = threading.Lock()
        self._shutting_down = False
        self._last_tts_click_time = 0.0
        self._shutdown_lock = threading.RLock()
        self._open_dialogs: list[tk.Toplevel] = []
        self._open_dialogs_lock = threading.RLock()
        self.demo_mode = not WHISPER_AVAILABLE
        self.event_bus = None
        self._event_subscriptions = []
        self._is_initialized = False
        self._applied_translation_engine_name: str | None = None
        self.translation_engine = None
        self.auto_tts_transcript_var = None
        self.auto_tts_translation_var = None

        self.gui = self

        try:
            self.debug_level = int(globals().get("DEBUG_LEVEL", 0))
        except (TypeError, ValueError):
            self.debug_level = 0

        _dbg = self.debug_level
        _is_trace = _dbg >= 3
        _is_verbose = _dbg >= 2
        _is_debug = _dbg >= 1

        if _is_trace:
            logger.debug(
                "🔥 GUI __init__: self.gui=%s, type=%s, "
                "_safe_exit_dialog(gui)=%s, _safe_exit_dialog(self)=%s",
                self.gui,
                type(self.gui),
                hasattr(self.gui, "_safe_exit_dialog"),
                hasattr(self, "_safe_exit_dialog"),
            )

        init_steps = [
            ("basic_attributes", self._init_basic_attributes, False),
            ("settings", self._init_settings, False),
            ("tts_manager", self._init_tts_manager, False),
            ("app_context", self._init_app_context, True),
            ("tkinter_root", self._init_tkinter_root, True),
            ("auto_tts_vars", self._init_auto_tts_vars, False),
            ("controller_and_engines", self._init_controller_and_engines, True),
            ("queues_and_extractor", self._init_queues_and_extractor, False),
            ("model_manager", self._init_model_manager, False),
            ("gui_layout", self._init_gui_layout, True),
            ("signal_and_timers", self._init_signal_and_timers, False),
            ("duplicate_handling", self._init_duplicate_handling, False),
        ]

        if _is_debug:
            logger.debug(
                "🚀 Starte GUI-Initialisierung mit %d Schritten",
                len(init_steps),
            )
        step_times: dict[str, float] = {}

        for step_name, step_func, critical in init_steps:
            step_start = time.perf_counter()
            try:
                step_func()
                step_duration = (time.perf_counter() - step_start) * 1000
                step_times[step_name] = step_duration
                if _is_verbose:
                    logger.debug(
                        "✅ Init step '%s' successful (%.2fms)",
                        step_name,
                        step_duration,
                    )
            except Exception as e:
                error_msg = (
                    f"❌ Init step '{step_name}' failed: {type(e).__name__}: {e}"
                )
                logger.error(error_msg, exc_info=True)
                self._init_errors.append(error_msg)
                if critical:
                    logger.critical(
                        "Critical init step '%s' failed – aborting startup",
                        step_name,
                    )
                    self._show_init_errors_and_warnings()
                    raise RuntimeError(
                        f"Critical initialization failed: {error_msg}",
                    ) from e

        try:
            self._update_stream_buttons("idle")
        except Exception as _btn_exc:
            logger.warning(
                "Initialer Button-State fehlgeschlagen: %s",
                _btn_exc,
            )

        try:
            if getattr(self, "start_button", None) is not None:
                self._bind_button_hover(
                    self.start_button,
                    "#2ea043",
                    "#3fb950",
                )
            if getattr(self, "stop_button", None) is not None:
                self._bind_button_hover(
                    self.stop_button,
                    "#da3633",
                    "#f85149",
                )
        except Exception as _hover_exc:
            if _is_verbose:
                logger.debug(
                    "Hover-Bind fehlgeschlagen: %s",
                    _hover_exc,
                )

        _root = getattr(self, "root", None)

        if _is_trace:
            if hasattr(self, "status_bar"):
                logger.debug(
                    "🔥 GUI __init__: status_bar=%s, _safe_exit_dialog(status_bar)=%s",
                    self.status_bar,
                    hasattr(self.status_bar, "_safe_exit_dialog"),
                )
            else:
                logger.debug("🔥 GUI __init__: self.status_bar existiert NICHT!")

        if _is_trace and _root is not None:
            import traceback

            _original_quit = _root.quit

            def patched_quit():
                logger.debug(
                    "🔥 root.quit() AUFRUFEN! Stacktrace:\n%s",
                    "".join(traceback.format_stack()),
                )
                with contextlib.suppress(Exception):
                    _original_quit()

            _root.quit = patched_quit

            _original_destroy = _root.destroy

            def patched_destroy():
                logger.debug(
                    "🔥 root.destroy() AUFRUFEN! Stacktrace:\n%s",
                    "".join(traceback.format_stack()),
                )
                with contextlib.suppress(Exception):
                    _original_destroy()

            _root.destroy = patched_destroy

            logger.debug("✅ root.quit()/destroy()-Patches aktiviert (debug≥3)")

        try:
            self._finalize_init()
            if _is_verbose:
                logger.debug("✅ Finalization successful")
        except Exception as e:
            error_msg = f"❌ Finalization failed: {type(e).__name__}: {e}"
            logger.error(error_msg, exc_info=True)
            self._init_errors.append(error_msg)
            self._show_init_errors_and_warnings()
            raise

        _tq_method = None
        if hasattr(self, "_process_text_queue") and callable(
            self._process_text_queue,
        ):
            _tq_method = self._process_text_queue

        if _tq_method is not None:
            try:
                if _root is not None:
                    _root.after(100, _tq_method)
                    if _is_verbose:
                        logger.debug(
                            "✅ Text-Queue-Verarbeitung gestartet (after 100ms)"
                        )
                else:
                    logger.warning("⚠️ Kein root-Objekt – Text-Queue nicht gestartet")
            except Exception as e:
                logger.warning(
                    "[TEXT-QUEUE] ❌ Start der Text-Queue fehlgeschlagen: %s",
                    e,
                )
        else:
            logger.error(
                "[TEXT-QUEUE] ❌ _process_text_queue ist NICHT in der "
                "GUI-Klasse definiert! "
                "Transkriptionstexte werden nicht angezeigt."
            )

        if hasattr(self, "_on_state_changed") and callable(
            self._on_state_changed,
        ):
            try:
                if self.event_bus is not None:
                    self.event_bus.subscribe(
                        "processing_state_changed",
                        self._on_state_changed,
                    )
                    if _is_verbose:
                        logger.debug(
                            "✅ Event-Handler für "
                            "'processing_state_changed' registriert"
                        )
                else:
                    logger.warning(
                        "⚠️ Event-Bus nicht verfügbar – "
                        "Zustandsänderungen werden nicht verarbeitet"
                    )
            except Exception as e:
                logger.warning(
                    "❌ Registrierung des Event-Handlers fehlgeschlagen: %s",
                    e,
                )
        else:
            logger.warning("⚠️ _on_state_changed ist NICHT in der GUI-Klasse definiert!")

        try:
            target_name = SUPPORTED_LANGUAGES.get(
                self.advanced_settings.target_language,
                "Deutsch",
            )
            if not hasattr(self, "lang_var") or self.lang_var is None:
                self.lang_var = tk.StringVar(
                    master=self.root,
                    value=target_name,
                )
                if _is_verbose:
                    logger.debug(
                        "Sprach-Variable neu erzeugt (keine aus "
                        "create_compact_control_panel vorhanden): %r",
                        target_name,
                    )
            else:
                self.lang_var.set(target_name)
                if _is_verbose:
                    logger.debug(
                        "Sprach-Variable aktualisiert (bereits an "
                        "Combobox gebunden): %r",
                        target_name,
                    )
        except Exception as e:
            logger.warning("Could not set language variable: %s", e)
            if not hasattr(self, "lang_var") or self.lang_var is None:
                self.lang_var = tk.StringVar(
                    master=self.root,
                    value="Deutsch",
                )
            else:
                self.lang_var.set("Deutsch")

        self.ExitConfirmDialog = ExitConfirmDialog
        self._finalize_exit_button()

        try:
            _actual_engine = getattr(self, "translation_engine", None)
            if _actual_engine is not None:
                _type_name = type(_actual_engine).__name__
                if "GoogleTranslationEngine" in _type_name:
                    self._applied_translation_engine_name = "google"
                elif "OllamaTranslationEngine" in _type_name:
                    self._applied_translation_engine_name = "ollama"
                elif "ArgosTranslateEngine" in _type_name:
                    self._applied_translation_engine_name = "argos"
                elif "ReflectionTranslationEngine" in _type_name:
                    self._applied_translation_engine_name = getattr(
                        self.advanced_settings, "translation_engine", None
                    )
                elif "Dummy" in _type_name:
                    self._applied_translation_engine_name = "dummy"
                else:
                    self._applied_translation_engine_name = None

                if _is_verbose:
                    logger.debug(
                        "📌 Aktive Engine registriert: %s → '%s'",
                        _type_name,
                        self._applied_translation_engine_name,
                    )
        except Exception as _eng_name_exc:
            logger.debug(
                "init: _applied_translation_engine_name konnte nicht "
                "gesetzt werden: %s",
                _eng_name_exc,
            )

        _ap = getattr(self, "audio_processor", None)
        if _ap is None:
            if _is_debug:
                logger.debug(
                    "AudioProcessor nicht verfügbar – Transkription im Demo-Modus"
                )

        elif not hasattr(_ap, "_transcription_callback"):
            logger.warning("⚠️ AudioProcessor hat kein _transcription_callback-Attribut")
        elif _ap._transcription_callback is None:
            logger.warning(
                "⚠️ Transkription-Callback ist NICHT im AudioProcessor registriert"
            )
        elif _is_verbose:
            logger.debug("✅ Transkription-Callback ist im AudioProcessor registriert")

        total_duration = (time.perf_counter() - init_start) * 1000

        if self._init_errors:
            logger.warning(
                "⚠️ Initialisierung abgeschlossen mit %d Fehler(n) in %.2fms",
                len(self._init_errors),
                total_duration,
            )
            for i, err in enumerate(self._init_errors, 1):
                logger.warning("   %d. %s", i, err)
            self._show_init_errors_and_warnings()
        else:
            logger.info(
                "✅ DragonWhispererGUI initialized successfully in %.2f ms",
                total_duration,
            )
            if _is_verbose and step_times:
                slowest = sorted(
                    step_times.items(),
                    key=lambda x: x[1],
                    reverse=True,
                )[:5]
                if slowest:
                    logger.debug("📊 Langsamste Initialisierungsschritte:")
                    for name, duration in slowest:
                        if duration > 10:
                            logger.debug(
                                "   • %s: %.2fms",
                                name,
                                duration,
                            )

        if _is_verbose:
            logger.debug(
                "📊 Init-Status: errors=%d, warnings=%d, demo_mode=%s, initialized=%s",
                len(self._init_errors),
                len(self._init_warnings),
                self.demo_mode,
                self._is_initialized,
            )

    def _init_duplicate_handling(self) -> None:
        """Initialisiert alle Attribute für die Duplikaterkennung und Text‑Caches."""
        self._recent_transcriptions = deque(maxlen=20)
        self._last_transcription_text = ""
        self._last_translation_text = ""
        self._last_output_translation = ""
        self._already_flushed_texts: set[str] = set()
        self._flushed_combined_texts: set[str] = set()
        self._already_flushed_cache: TTLCache | None = None
        self._last_tts_texts: deque = deque(maxlen=5)
        self._blacklist_regex_cache: dict[tuple, re.Pattern] = {}
        self._blacklist_cache_lock = threading.RLock()
        self._blacklist_last_modified = 0.0
        self._already_flushed_texts_ttl: TTLCache | None = None
        self._pending_transcript_segments: list[tuple[str, float | None, str]] = []
        self._pending_transcript_lock = threading.Lock()

        if DEBUG_LEVEL >= 3:
            log_debug("init", "✅ Duplikaterkennungs‑Attribute initialisiert")

    def _init_model_manager(self) -> None:
        """Initialisiert den zentralen Modell-Manager."""
        self.model_manager = get_model_manager()
        logger.debug("✅ Modell-Manager initialisiert")

    def _init_auto_tts_vars(self) -> None:
        """Initialisiert die Tkinter‑Variablen für die automatische Sprachausgabe.
        Setzt voraus, dass self.root bereits existiert (wurde in _init_tkinter_root erstellt).
        """
        if not hasattr(self, "root") or self.root is None:
            logger.error("_init_auto_tts_vars: root existiert nicht – überspringe.")
            self.auto_tts_transcript_var = None
            self.auto_tts_translation_var = None
            return

        try:
            if self.auto_tts_transcript_var is None:
                self.auto_tts_transcript_var = tk.BooleanVar(
                    master=self.root,
                    value=getattr(self.advanced_settings, "auto_tts_transcript", False),
                )
            if self.auto_tts_translation_var is None:
                self.auto_tts_translation_var = tk.BooleanVar(
                    master=self.root,
                    value=getattr(
                        self.advanced_settings,
                        "auto_tts_translation",
                        False,
                    ),
                )

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "init",
                    "Auto‑TTS‑Variablen initialisiert: transcript=%s, translation=%s",
                    self.auto_tts_transcript_var.get(),
                    self.auto_tts_translation_var.get(),
                )
        except Exception as e:
            logger.error(f"Fehler bei der Initialisierung der Auto‑TTS‑Variablen: {e}")
            self.auto_tts_transcript_var = None
            self.auto_tts_translation_var = None

    def _log_active_threads(self, context: str = "shutdown") -> int:
        """Loggt alle aktiven Threads mit Stacktraces – ultimative Debugging-Hilfe."""
        import sys
        import threading
        import traceback

        log_lines = [f"🧵 Aktive Threads bei {context}:"]
        active_count = 0
        main_thread = threading.main_thread()

        for thread in threading.enumerate():
            if thread is main_thread:
                continue

            if not thread.is_alive():
                continue

            active_count += 1
            thread_info = f"  • Thread: {thread.name} (daemon={thread.daemon}, ident={
                thread.ident
            })"
            log_lines.append(thread_info)

            try:
                frame = sys._current_frames().get(thread.ident)
                if frame:
                    stack = traceback.format_stack(frame)
                    for line in stack:
                        log_lines.append(f"      {line.rstrip()}")
                else:
                    log_lines.append("      (Stacktrace nicht verfügbar – kein Frame)")
            except Exception as e:
                log_lines.append(f"      (Stacktrace-Fehler: {type(e).__name__}: {e})")

        if active_count == 0:
            log_lines.append("  ✅ Keine aktiven Hintergrund-Threads")
        else:
            log_lines.append(
                f"  📊 Insgesamt {active_count} aktive Hintergrund-Thread(s)",
            )

        full_log = "\n".join(log_lines)
        try:
            logger = logging.getLogger("dragon")
            logger.info(full_log)
        except Exception:
            try:
                print(full_log, file=sys.stderr)
                sys.stderr.flush()
            except Exception:
                pass

        return active_count

    def _emit_translation_error(
        self,
        error_msg: str,
        error_type: str = "",
        status_code: int | None = None,
        hint: str = "",
    ) -> None:
        """Zentrale Methode zum Senden von Übersetzungs-Fehlern an den Event-Bus und zur GUI."""
        if self.event_bus is not None:
            try:
                self.event_bus.emit(
                    "translation_error",
                    {
                        "error": error_msg,
                        "error_type": error_type,
                        "status_code": status_code,
                        "hint": hint,
                        "timestamp": time.time(),
                    },
                )
            except Exception as e:
                logger.debug(f"Fehler beim Senden von translation_error: {e}")
        short_msg = f"⚠️ Übersetzung: {error_msg[:60]}"
        if hint:
            short_msg += f" – {hint[:40]}"
        self.update_status(short_msg, priority=1)

    def _show_init_errors_and_warnings(self) -> None:
        """Zeigt alle während der Initialisierung gesammelten Fehler und Warnungen an.
        Ausgabe auf stderr, in der Log-Datei, und falls möglich in der GUI.
        """
        if not self._init_errors and not self._init_warnings:
            return

        import sys
        from datetime import UTC, datetime

        timestamp = datetime.now(UTC).strftime("%Y-%m-%d %H:%M:%S")
        unique_errors = list(dict.fromkeys(self._init_errors))
        unique_warnings = list(dict.fromkeys(self._init_warnings))

        MAX_DISPLAY = 20
        truncated_errors = len(unique_errors) > MAX_DISPLAY
        truncated_warnings = len(unique_warnings) > MAX_DISPLAY

        if truncated_errors:
            unique_errors = unique_errors[:MAX_DISPLAY]
        if truncated_warnings:
            unique_warnings = unique_warnings[:MAX_DISPLAY]

        if unique_errors:
            sys.stderr.write(f"\n[{timestamp}] " + "=" * 70 + "\n")
            sys.stderr.write(
                f"[{timestamp}] ❌ INITIALISIERUNGSFEHLER ({len(self._init_errors)} insgesamt, {len(unique_errors)} angezeigt)\n",
            )
            sys.stderr.write(f"[{timestamp}] " + "=" * 70 + "\n")
            for err in unique_errors:
                sys.stderr.write(f"  • {err}\n")
            if truncated_errors:
                sys.stderr.write(
                    f"  … und {len(self._init_errors) - MAX_DISPLAY} weitere Fehler\n",
                )
            sys.stderr.write(f"[{timestamp}] " + "=" * 70 + "\n\n")
            sys.stderr.flush()

        if unique_warnings:
            sys.stderr.write(f"\n[{timestamp}] " + "=" * 70 + "\n")
            sys.stderr.write(
                f"[{timestamp}] ⚠️ INITIALISIERUNGSWARNUNGEN ({len(self._init_warnings)} insgesamt, {len(unique_warnings)} angezeigt)\n",
            )
            sys.stderr.write(f"[{timestamp}] " + "=" * 70 + "\n")
            for warn in unique_warnings:
                sys.stderr.write(f"  • {warn}\n")
            if truncated_warnings:
                sys.stderr.write(
                    f"  … und {len(self._init_warnings) - MAX_DISPLAY} weitere Warnungen\n",
                )
            sys.stderr.write(f"[{timestamp}] " + "=" * 70 + "\n\n")
            sys.stderr.flush()

        try:
            import logging

            log = logging.getLogger("dragon")
            if unique_errors:
                log.error(
                    f"Init-Fehler ({len(unique_errors)} Einträge): {', '.join(unique_errors[:5])}"
                    + (" …" if len(unique_errors) > 5 else ""),
                )
            if unique_warnings:
                log.warning(
                    f"Init-Warnungen ({len(unique_warnings)} Einträge): {', '.join(unique_warnings[:5])}"
                    + (" …" if len(unique_warnings) > 5 else ""),
                )
        except Exception:
            for err in unique_errors:
                print(f"[Init-Error] {err}")
            for warn in unique_warnings:
                print(f"[Init-Warning] {warn}")

        try:
            if hasattr(self, "root") and self.root.winfo_exists():
                msg = ""
                if unique_errors:
                    msg += (
                        "❌ Fehler:\n"
                        + "\n".join(f"• {e}" for e in unique_errors)
                        + "\n\n"
                    )
                if unique_warnings:
                    msg += "⚠️ Warnungen:\n" + "\n".join(
                        f"• {w}" for w in unique_warnings
                    )

                if msg:
                    if truncated_errors or truncated_warnings:
                        msg += f"\n(Es wurden insgesamt {
                            len(self._init_errors)
                        } Fehler und {
                            len(self._init_warnings)
                        } Warnungen gefunden. Details in der Konsole/Log-Datei.)"

                    if len(msg) > 2000:
                        msg = msg[:1997] + "..."

                    try:
                        DarkMessageBox.showwarning(
                            "Start-Probleme",
                            msg
                            + "\n\nEinige Funktionen sind möglicherweise eingeschränkt.",
                            parent=self.root,
                            timeout=15,
                        )
                    except (NameError, AttributeError):
                        import tkinter.messagebox as mb

                        mb.showwarning("Start-Probleme", msg)
        except Exception:
            pass

