    def _safe_init_step(
        self,
        step_name: str,
        step_func: Callable,
        *,
        critical: bool = False,
        retries: int = 0,
        retry_delay: float = 0.5,
        log_to_stderr: bool = True,
    ) -> tuple[bool, str | None]:
        """Führt einen Initialisierungsschritt mit erweiterter Fehlerbehandlung aus."""
        import sys
        import time
        import traceback

        if DEBUG_LEVEL >= 3:
            log_debug(
                "init",
                f"▶️ Schritt: {step_name} (critical={critical}, retries={retries})",
            )

        last_exception: Exception | None = None
        last_traceback: str | None = None

        for attempt in range(retries + 1):
            try:
                step_func()

                if DEBUG_LEVEL >= 3:
                    log_debug("init", f"✅ Schritt '{step_name}' erfolgreich")
                return True, None

            except Exception as e:
                last_exception = e
                last_traceback = traceback.format_exc()

                if critical:
                    error_msg = (
                        f"❌ KRITISCHER Fehler in {step_name}: {type(e).__name__}: {e}"
                    )
                    logger.critical(error_msg, exc_info=True)
                    if log_to_stderr:
                        sys.stderr.write(f"\n{error_msg}\n")
                        sys.stderr.write(f"Traceback:\n{last_traceback}\n")
                        sys.stderr.flush()
                    self._init_errors.append(error_msg)
                    return False, error_msg

                error_msg = f"Fehler in {step_name} (Versuch {attempt + 1}/{
                    retries + 1
                }): {type(e).__name__}: {e}"
                logger.warning(error_msg, exc_info=DEBUG_LEVEL >= 3)
                if log_to_stderr:
                    sys.stderr.write(f"[WARN] {error_msg}\n")
                    sys.stderr.flush()

                if attempt < retries:
                    time.sleep(retry_delay * (attempt + 1))

        final_msg = f"❌ Schritt '{step_name}' nach {
            retries + 1
        } Versuchen fehlgeschlagen: {last_exception}"
        logger.error(final_msg, exc_info=DEBUG_LEVEL >= 3)
        if log_to_stderr:
            sys.stderr.write(f"\n{final_msg}\n")
            if last_traceback:
                sys.stderr.write(f"Traceback:\n{last_traceback}\n")
            sys.stderr.flush()
        self._init_errors.append(final_msg)
        return False, final_msg

