    def _init_settings(self) -> None:
        """Lädt AppSettings und AdvancedSettings."""
        try:
            self.settings = AppSettings.load_from_file()
            logger.debug("✅ AppSettings geladen")
            self._show_initial_status("✅ Einstellungen geladen")
        except Exception as e:
            self._init_errors.append(f"Einstellungen konnten nicht geladen werden: {e}")
            self.settings = AppSettings()
            logger.warning("AppSettings-Fallback verwendet")
            self._show_initial_status("⚠️ Einstellungen-Fallback")

        if IS_LINUX:
            saved_browser = self.settings.cookies_browser
            if saved_browser and shutil.which(saved_browser):
                logger.debug(
                    f"✅ Linux: Verwende gespeicherten Browser '{saved_browser}'",
                )
            elif shutil.which("chromium"):
                self.settings.cookies_browser = "chromium"
                logger.debug("✅ Linux: Browser auf 'chromium' gesetzt (Fallback)")
            elif shutil.which("chrome"):
                self.settings.cookies_browser = "chrome"
                logger.debug("✅ Linux: Browser auf 'chrome' gesetzt (Fallback)")
            else:
                self.settings.cookies_browser = "firefox"
                logger.debug("✅ Linux: Browser auf 'firefox' gesetzt (Standard)")

        try:
            self.advanced_settings = get_advanced_settings()
            PlatformUtils.set_allowed_dirs(self.advanced_settings.allowed_dirs)
            logger.debug("✅ AdvancedSettings geladen")
            self._show_initial_status("✅ Erweiterte Einstellungen geladen")
        except Exception as e:
            self._init_errors.append(
                f"Erweiterte Einstellungen konnten nicht geladen werden: {e}",
            )
            self.advanced_settings = AdvancedSettings()
            logger.warning("AdvancedSettings-Fallback verwendet")
            self._show_initial_status("⚠️ Erweiterte Einstellungen-Fallback")

        self._apply_cpu_optimizations()

        try:
            self.advanced_settings.repair()
            logger.debug("✅ AdvancedSettings repariert")
        except Exception as e:
            logger.debug(f"Ignored exception in repair: {e}")

        self._show_cookie_notice = (
            not self.settings.cookies_notice_shown and self.settings.use_browser_cookies
        )

    def _init_tts_manager(self) -> None:
        """Initialisiert den TTS-Manager."""
        try:
            self.tts_manager = TTSManager(self.advanced_settings)
            logger.debug("✅ TTSManager initialisiert")
            self._show_initial_status("✅ Sprachausgabe bereit")

            if self.tts_manager is not None:
                desired_voice = self.advanced_settings.tts_voice
                if desired_voice:
                    self.tts_manager.get_installed_piper_voices()
                    self.tts_manager.set_voice(desired_voice)
                    logger.debug(f"✅ TTS‑Stimme auf '{desired_voice}' gesetzt")
        except Exception as e:
            self._init_errors.append(f"TTS‑Manager konnte nicht gestartet werden: {e}")
            self.tts_manager = None
            logger.warning(f"TTSManager-Fehler: {e}")
            self._show_initial_status("⚠️ Sprachausgabe nicht verfügbar")

    def _init_controller_and_engines(self) -> None:
        """🐉 INITIALISIERUNG – PLASMA-POWERED V2.0 🔥
        Initialisiert den WhisperController, alle Engines und stellt die Verbindung
        zwischen AudioProcessor und GUI für Transkriptionstexte her.

        """
        import contextlib
        import logging
        import threading
        import time

        _logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        errors = []
        warnings = []
        callback_registered = False
        callback_repair_attempted = False

        _logger.debug("🐉🔥 _init_controller_and_engines V2.0 GESTARTET 🔥🐉")
        _logger.debug(
            f"▶️ _init_controller_and_engines ENTRY (Thread: {threading.current_thread().name})"
        )

        try:
            self._init_attributes()
            _logger.debug("  ✅ _init_attributes() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_attributes fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)
            raise

        try:
            self._init_event_bus()
            _logger.debug("  ✅ _init_event_bus() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_event_bus fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)
            raise

        try:
            self._init_controller()
            _logger.debug("  ✅ _init_controller() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_controller fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)
            raise

        try:
            _logger.debug("  → Rufe _init_managers_and_engines() auf...")
            self._init_managers_and_engines()
            _logger.debug("  ✅ _init_managers_and_engines() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_managers_and_engines fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)
            self.demo_mode = True
            _logger.warning("⚠️ Demo-Modus aktiviert – Transkription nicht verfügbar")

        if not self.demo_mode:
            try:
                if (
                    hasattr(self, "audio_processor")
                    and self.audio_processor is not None
                ):
                    ap = self.audio_processor
                    _logger.debug(f"  📡 AudioProcessor gefunden (ID: {id(ap)})")

                    if hasattr(ap, "set_text_callback"):
                        _logger.debug("  ✅ AudioProcessor hat set_text_callback()")

                        if hasattr(self, "_on_transcription_text") and callable(
                            self._on_transcription_text
                        ):
                            ap.set_text_callback(self._on_transcription_text)
                            _logger.debug(
                                "  ✅ Transkription-Callback an AudioProcessor übergeben: %s",
                                self._on_transcription_text.__name__,
                            )
                            callback_registered = True

                            if hasattr(ap, "_transcription_callback"):
                                if ap._transcription_callback is not None:
                                    _logger.debug(
                                        "  ✅ Callback erfolgreich im AudioProcessor registriert (direkt geprüft)",
                                    )
                                else:
                                    _logger.warning(
                                        "  ⚠️ Callback wurde via set_text_callback gesetzt, aber _transcription_callback ist None – versuche direkte Zuweisung",
                                    )
                                    ap._transcription_callback = (
                                        self._on_transcription_text
                                    )
                                    callback_repair_attempted = True
                                    if ap._transcription_callback is not None:
                                        _logger.debug(
                                            "  ✅ Direkte Zuweisung erfolgreich"
                                        )
                                    else:
                                        _logger.error(
                                            "  ❌ Direkte Zuweisung fehlgeschlagen – Callback bleibt None"
                                        )
                            else:
                                _logger.warning(
                                    "  ⚠️ AudioProcessor hat kein _transcription_callback-Attribut – setze es nach",
                                )
                                ap._transcription_callback = self._on_transcription_text
                                callback_repair_attempted = True
                        else:
                            warning_msg = "_on_transcription_text existiert nicht oder ist nicht aufrufbar"
                            warnings.append(warning_msg)
                            _logger.warning(f"  ⚠️ {warning_msg}")
                    else:
                        warning_msg = "AudioProcessor hat keine set_text_callback-Methode – versuche direkte Zuweisung"
                        warnings.append(warning_msg)
                        _logger.warning(f"  ⚠️ {warning_msg}")
                        if hasattr(ap, "_transcription_callback"):
                            ap._transcription_callback = self._on_transcription_text
                            _logger.debug(
                                "  ✅ Callback via direkter Zuweisung gesetzt"
                            )
                            callback_registered = True
                        else:
                            _logger.error(
                                "  ❌ AudioProcessor hat kein _transcription_callback-Attribut – Callback kann nicht gesetzt werden"
                            )
                else:
                    warning_msg = "AudioProcessor nicht verfügbar – Callback kann nicht gesetzt werden"
                    warnings.append(warning_msg)
                    _logger.warning(f"  ⚠️ {warning_msg}")
            except Exception as e:
                errors.append(f"Callback-Registrierung fehlgeschlagen: {e}")
                _logger.error(f"  ❌ {errors[-1]}", exc_info=True)
        else:
            _logger.debug("  ℹ️ Demo-Modus: Überspringe Callback-Registrierung")

        if (
            not self.demo_mode
            and hasattr(self, "audio_processor")
            and self.audio_processor is not None
        ):
            ap = self.audio_processor
            callback_set = getattr(ap, "_transcription_callback", None) is not None
            if not callback_set:
                _logger.warning(
                    "  ⚠️ Nach _init_managers_and_engines: Callback verschwunden – setze neu"
                )
                try:
                    if hasattr(self, "_on_transcription_text") and callable(
                        self._on_transcription_text
                    ):
                        if hasattr(ap, "set_text_callback"):
                            ap.set_text_callback(self._on_transcription_text)
                        else:
                            ap._transcription_callback = self._on_transcription_text
                        _logger.debug("  ✅ Callback nachträglich wiederhergestellt")
                        callback_registered = True
                    else:
                        _logger.error(
                            "  ❌ _on_transcription_text nicht aufrufbar – kann Callback nicht wiederherstellen"
                        )
                except Exception as e:
                    _logger.error(
                        f"  ❌ Wiederherstellung des Callbacks fehlgeschlagen: {e}"
                    )

        try:
            self._init_translation_executor()
            _logger.debug("  ✅ _init_translation_executor() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_translation_executor fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)

        try:
            self._init_stream_info_extractor()
            _logger.debug("  ✅ _init_stream_info_extractor() abgeschlossen")
        except Exception as e:
            errors.append(f"_init_stream_info_extractor fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)

        try:
            self._register_event_subscriptions()
            _logger.debug("  ✅ _register_event_subscriptions() abgeschlossen")
        except Exception as e:
            errors.append(f"_register_event_subscriptions fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)

        try:
            self._sync_stream_manager_with_gui()
            _logger.debug("  ✅ _sync_stream_manager_with_gui() abgeschlossen")
        except Exception as e:
            errors.append(f"_sync_stream_manager_with_gui fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)

        try:
            self._finalize_init()
            _logger.debug("  ✅ _finalize_init() abgeschlossen")
        except Exception as e:
            errors.append(f"_finalize_init fehlgeschlagen: {e}")
            _logger.error(f"❌ {errors[-1]}", exc_info=True)

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            ap = self.audio_processor
            has_callback_attr = hasattr(ap, "_transcription_callback")
            callback_is_set = getattr(ap, "_transcription_callback", None) is not None
            callback_type = (
                type(ap._transcription_callback).__name__ if callback_is_set else "None"
            )
            _logger.debug(
                "  📊 Callback-Status: Attribut vorhanden=%s, gesetzt=%s, Typ=%s",
                has_callback_attr,
                callback_is_set,
                callback_type,
            )
            if callback_is_set:
                try:
                    is_callable = callable(ap._transcription_callback)
                    _logger.debug(f"  📊 Callback aufrufbar: {is_callable}")
                    if is_callable:
                        _logger.debug("  ✅ Callback ist aufrufbar (ohne Test-Aufruf)")
                    else:
                        _logger.error(
                            "  ❌ Callback ist NICHT aufrufbar – Transkription wird fehlschlagen!"
                        )
                        if callback_repair_attempted:
                            _logger.warning(
                                "  ⚠️ Reparatur wurde bereits versucht – möglicherweise ist die Methode nicht korrekt gebunden"
                            )
                except Exception as e:
                    _logger.error(
                        f"  ❌ Fehler beim Prüfen der Callback-Aufrufbarkeit: {e}"
                    )
            else:
                _logger.error(
                    "  ❌ CALLBACK IST NICHT GESETZT – Transkription wird nicht in der GUI ankommen!"
                )
                if not callback_registered and not self.demo_mode:
                    _logger.critical(
                        "  💥 Reguläre Registrierung fehlgeschlagen und keine Reparatur – versuche finale Notfall-Registrierung"
                    )
                    try:
                        if hasattr(self, "_on_transcription_text") and callable(
                            self._on_transcription_text
                        ):
                            if hasattr(ap, "set_text_callback"):
                                ap.set_text_callback(self._on_transcription_text)
                            ap._transcription_callback = self._on_transcription_text
                            _logger.critical(
                                "  🚑 NOTFALL-CALLBACK GESETZT – bitte prüfen, ob Transkription nun ankommt"
                            )
                        else:
                            _logger.critical(
                                "  💀 Notfall-Registrierung unmöglich: _on_transcription_text nicht aufrufbar"
                            )
                    except Exception as e:
                        _logger.critical(
                            f"  💀 Notfall-Registrierung fehlgeschlagen: {e}"
                        )
        else:
            _logger.warning(
                "  ⚠️ AudioProcessor NICHT vorhanden – Transkription funktioniert nicht!",
            )

        if hasattr(self, "event_bus") and self.event_bus is not None:
            with contextlib.suppress(Exception):
                _logger.debug(
                    "  📊 Event-Bus vorhanden – processing_state_changed sollte registriert sein",
                )
        else:
            _logger.warning(
                "  ⚠️ Event-Bus nicht vorhanden – Event-basierte Kommunikation eingeschränkt"
            )

        duration = (time.monotonic() - start_time) * 1000
        if errors:
            _logger.warning(
                "⚠️ _init_controller_and_engines abgeschlossen mit %d Fehler(n) in %.2fms",
                len(errors),
                duration,
            )
            for i, err in enumerate(errors, 1):
                _logger.warning(f"  {i}. {err}")
        else:
            _logger.info(
                "✅ _init_controller_and_engines abgeschlossen in %.2fms (demo_mode=%s)",
                duration,
                self.demo_mode,
            )

        if warnings:
            for w in warnings:
                _logger.debug(f"  ⚠️ {w}")

        _logger.debug(
            "◀️ _init_controller_and_engines EXIT (demo_mode=%s, callback_registered=%s)",
            self.demo_mode,
            callback_registered,
        )

    def _init_attributes(self) -> None:
        """🧠 ATTRIBUT-INITIALISIERUNG V2.0 🔥
        Initialisiert alle Basis-Attribute der GUI – mit erweitertem Debugging,
        Fallback-Prüfungen und zusätzlichen Flags für Callback-Überwachung.
        """
        import logging
        import threading
        import time
        from collections import deque

        _logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        _logger.debug("▶️ _init_attributes ENTRY")

        try:
            self.demo_mode = not WHISPER_AVAILABLE
            self.is_processing = False
            self.subtitle_mode = False
            self.translate_active = True
            self.exit_confirmed = False
            self._stopping_done = False
            _logger.debug("  ✅ Status-Flags initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Status-Flags: {e}", exc_info=True)
            raise

        try:
            self.layout_mode = getattr(self.settings, "layout_mode", "vertical")
            self.target_language = self.advanced_settings.target_language
            self.current_language = self.target_language
            self.current_video_language = None

            target_lang_name = SUPPORTED_LANGUAGES.get(self.target_language, "Deutsch")
            self._last_valid_language = target_lang_name
            _logger.debug(
                f"  ✅ Sprache: Ziel={self.target_language} ({target_lang_name}), Layout={self.layout_mode}"
            )
        except Exception as e:
            _logger.error(
                f"  ❌ Fehler bei Sprach-/Layout-Einstellungen: {e}", exc_info=True
            )
            self.layout_mode = "vertical"
            self.target_language = "de"
            self.current_language = "de"
            self.current_video_language = None
            self._last_valid_language = "Deutsch"
            _logger.warning("  ⚠️ Sprach-/Layout-Fallback verwendet")

        try:
            self.current_stream_info = None
            self.last_completed_stream_info = None
            self.last_stream_title = ""
            _logger.debug("  ✅ Stream-Info initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Stream-Info: {e}", exc_info=True)
            raise

        try:
            self._translate_lock = threading.RLock()
            self._history_lock = threading.RLock()
            self._duplicate_lock = threading.RLock()
            self._tts_lock = threading.RLock()
            self._subscriptions_lock = threading.RLock()
            if not hasattr(self, "_callback_lock"):
                self._callback_lock = threading.RLock()
            if not hasattr(self, "_shutdown_lock"):
                self._shutdown_lock = threading.RLock()
            _logger.debug("  ✅ Locks initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Locks: {e}", exc_info=True)
            raise

        try:
            self.transcript_history = deque(maxlen=1000)
            self.translation_history = deque(maxlen=500)
            self._open_dialogs = []
            self._already_flushed_texts = set()
            self._last_tts_texts = deque(maxlen=5)
            self._blacklist_regex_cache = {}
            if not hasattr(self, "_recent_transcriptions"):
                self._recent_transcriptions = deque(maxlen=20)
            if not hasattr(self, "_flushed_combined_texts"):
                self._flushed_combined_texts = set()
            _logger.debug("  ✅ Container initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Containern: {e}", exc_info=True)
            raise

        try:
            self._progress_bar_started = False
            self._tts_active = False
            self._pending_tts_transcript = ""
            self._pending_tts_translation = ""
            self._current_layout = None
            self._subtitle_anim_id = None
            self._live_mode_toggle_time = 0.0
            if not hasattr(self, "_save_settings_timer"):
                self._save_settings_timer = None
            if not hasattr(self, "_vram_idle_timer"):
                self._vram_idle_timer = None
            if not hasattr(self, "_tts_timer"):
                self._tts_timer = None
            _logger.debug("  ✅ Timer/Animations-IDs initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Timern: {e}", exc_info=True)
            raise

        try:
            self.performance_monitor = SimplePerformanceTracker()
            self._last_text_queue_size = 0
            if not hasattr(self, "_gui_queue"):
                self._gui_queue = None
            if not hasattr(self, "_text_queue"):
                self._text_queue = None
            _logger.debug("  ✅ Performance-Monitor initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Performance-Monitor: {e}", exc_info=True)
            raise

        try:
            self._last_transcription_text = ""
            self._last_translation_text = ""
            self._last_output_translation = ""
            if not hasattr(self, "_last_transcription_time"):
                self._last_transcription_time = time.time()
            if not hasattr(self, "_last_translation_time"):
                self._last_translation_time = time.time()
            if not hasattr(self, "_last_activity_time"):
                self._last_activity_time = time.time()
            _logger.debug("  ✅ Letzte Texte initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei letzten Texten: {e}", exc_info=True)
            raise

        try:
            if not hasattr(self, "_init_errors"):
                self._init_errors = []
            if not hasattr(self, "_init_warnings"):
                self._init_warnings = []
            _logger.debug("  ✅ Fehler-/Warnungslisten initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Fehlerlisten: {e}", exc_info=True)
            raise

        try:
            self.transcription_engine = None
            self.controller = None
            self.translation_executor = None
            self.stream_info_extractor = None
            if not hasattr(self, "audio_processor"):
                self.audio_processor = None
            _logger.debug("  ✅ Engine-Referenzen initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Engine-Referenzen: {e}", exc_info=True)
            raise

        try:
            if not hasattr(self, "_callback_registered"):
                self._callback_registered = False
            if not hasattr(self, "_callback_repair_attempted"):
                self._callback_repair_attempted = False
            if not hasattr(self, "_audio_processor_callback_checked"):
                self._audio_processor_callback_checked = False
            if not hasattr(self, "_last_callback_check"):
                self._last_callback_check = 0.0
            _logger.debug("  ✅ Callback-Überwachungs-Flags initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Callback-Flags: {e}", exc_info=True)
            raise

        try:
            if not hasattr(self, "_shutting_down"):
                self._shutting_down = False
            if not hasattr(self, "_cleanup_done"):
                self._cleanup_done = False
            if not hasattr(self, "_disposed"):
                self._disposed = False
            if not hasattr(self, "_exit_requested"):
                self._exit_requested = False
            _logger.debug("  ✅ Shutdown/Cleanup-Flags initialisiert")
        except Exception as e:
            _logger.error(f"  ❌ Fehler bei Shutdown-Flags: {e}", exc_info=True)
            raise

        duration_ms = (time.monotonic() - start_time) * 1000
        _logger.debug(f"✅ Alle Attribute initialisiert in {duration_ms:.2f} ms")

    def _init_event_bus(self) -> None:
        _logger = logging.getLogger("dragon")
        if hasattr(self, "event_bus") and self.event_bus is not None:
            return
        self.event_bus = EventBus()
        _logger.debug("✅ Event-Bus instanziiert")

    def _init_controller(self) -> None:
        """Initialisiert den WhisperController."""
        _logger = logging.getLogger("dragon")

        try:
            self.controller = WhisperController(gui_ref=self, event_bus=self.event_bus)
            _logger.debug("✅ WhisperController initialisiert")
            if (
                hasattr(self.controller, "event_bus")
                and self.controller.event_bus is not None
            ):
                self.event_bus = self.controller.event_bus
                _logger.debug("✅ Event-Bus vom Controller übernommen")

        except Exception as e:
            _logger.exception("❌ WhisperController Fehler: %s", e)
            self._init_errors.append(f"Controller Fehler: {e}")
            self.controller = None
            self.demo_mode = True
            raise RuntimeError(f"Controller Fehler: {e}") from e

    def _on_state_changed(self, data: dict) -> None:
        """Wird aufgerufen, wenn der Controller den Zustand ändert.
        Aktualisiert den Start/Stop-Button-Status und die Statusleiste.
        """
        import logging
        import threading
        import tkinter as tk

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not data:
            if debug_level >= 3:
                logger.debug("[GUI] Zustandsänderung: Keine Daten empfangen")
            return

        state = data.get("state")
        if not state:
            if debug_level >= 3:
                logger.debug(f"[GUI] Zustandsänderung: Kein 'state' in Daten: {data}")
            return

        if hasattr(self, "_shutting_down") and self._shutting_down:
            if debug_level >= 4:
                logger.debug(f"[GUI] Shutdown läuft – Zustand '{state}' ignoriert")
            return

        if threading.current_thread() is not threading.main_thread():
            if debug_level >= 3:
                logger.debug(
                    "[GUI] Zustandsänderung im Hintergrund-Thread – leite an Hauptthread weiter",
                )
            try:
                if hasattr(self, "root") and self.root is not None:
                    self.root.after(0, lambda: self._on_state_changed(data))
                else:
                    logger.warning(
                        "[GUI] Kein Root-Fenster – Zustandsänderung im Hintergrund ignoriert",
                    )
            except Exception as e:
                logger.warning(
                    f"[GUI] after() für Zustandsänderung fehlgeschlagen: {e}",
                )
            return

        if debug_level >= 2:
            logger.debug(f"[GUI] Zustandsänderung empfangen: {state}")

        try:
            if not hasattr(self, "root") or self.root is None:
                if debug_level >= 3:
                    logger.debug(
                        "[GUI] root existiert nicht – überspringe Button-Update",
                    )
                return

            try:
                if not self.root.winfo_exists():
                    if debug_level >= 3:
                        logger.debug(
                            "[GUI] root wurde zerstört – überspringe Button-Update",
                        )
                    return
            except tk.TclError:
                if debug_level >= 3:
                    logger.debug("[GUI] root nicht mehr verfügbar – überspringe")
                return

            has_stop_button = (
                hasattr(self, "stop_button") and self.stop_button is not None
            )
            has_start_button = (
                hasattr(self, "start_button") and self.start_button is not None
            )

            if not has_stop_button and not has_start_button:
                if debug_level >= 3:
                    logger.debug("[GUI] Keine Buttons zum Aktualisieren vorhanden")
                return

            if state in ("IDLE", "ERROR", "STOPPING"):
                if has_stop_button:
                    try:
                        self.stop_button.config(state=tk.DISABLED)
                        if debug_level >= 4:
                            logger.debug("[GUI] Stop-Button deaktiviert")
                    except tk.TclError:
                        if debug_level >= 3:
                            logger.debug("[GUI] Stop-Button bereits zerstört")
                if has_start_button:
                    try:
                        self.start_button.config(state=tk.NORMAL)
                        if debug_level >= 4:
                            logger.debug("[GUI] Start-Button aktiviert")
                    except tk.TclError:
                        if debug_level >= 3:
                            logger.debug("[GUI] Start-Button bereits zerstört")

            elif state in ("PROCESSING", "STARTING"):
                if has_stop_button:
                    try:
                        self.stop_button.config(state=tk.NORMAL)
                        if debug_level >= 4:
                            logger.debug("[GUI] Stop-Button aktiviert")
                    except tk.TclError:
                        if debug_level >= 3:
                            logger.debug("[GUI] Stop-Button bereits zerstört")
                if has_start_button:
                    try:
                        self.start_button.config(state=tk.DISABLED)
                        if debug_level >= 4:
                            logger.debug("[GUI] Start-Button deaktiviert")
                    except tk.TclError:
                        if debug_level >= 3:
                            logger.debug("[GUI] Start-Button bereits zerstört")

            else:
                if debug_level >= 2:
                    logger.warning(
                        f"[GUI] Unbekannter Zustand: {state} – Start-Button aktiviert",
                    )
                if has_start_button:
                    with contextlib.suppress(tk.TclError):
                        self.start_button.config(state=tk.NORMAL)
                if has_stop_button:
                    with contextlib.suppress(tk.TclError):
                        self.stop_button.config(state=tk.DISABLED)

            if hasattr(self, "update_status") and callable(self.update_status):
                status_messages = {
                    "IDLE": "🐉 Bereit",
                    "PROCESSING": "🔄 Verarbeitung läuft...",
                    "STARTING": "🚀 Starte...",
                    "STOPPING": "⏹️ Stoppe...",
                    "ERROR": "❌ Fehler aufgetreten",
                }
                status_text = status_messages.get(state, f"Status: {state}")
                try:
                    self.update_status(status_text)
                    if debug_level >= 4:
                        logger.debug(f"[GUI] Statusleiste aktualisiert: {status_text}")
                except Exception as e:
                    if debug_level >= 3:
                        logger.debug(
                            f"[GUI] Statusleiste konnte nicht aktualisiert werden: {e}",
                        )

        except tk.TclError as e:
            logger.error(f"[GUI] TclError beim Aktualisieren der Buttons: {e}")
        except Exception as e:
            logger.error(
                f"[GUI] Fehler beim Aktualisieren der Buttons: {e}",
                exc_info=debug_level >= 3,
            )

    def _init_managers_and_engines(self) -> None:
        """Initialisiert Manager und Engines"""
        import logging
        import time

        _logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        errors = []

        try:
            _logger.debug("  → Rufe _init_managers() auf...")
            manager_start = time.monotonic()
            self._init_managers()
            _logger.debug(
                "  ✅ _init_managers() abgeschlossen in %.2fms",
                (time.monotonic() - manager_start) * 1000,
            )
        except Exception as e:
            error_msg = (
                f"Manager-Initialisierung fehlgeschlagen: {type(e).__name__}: {e}"
            )
            _logger.exception("❌ %s", error_msg)
            errors.append(error_msg)

        try:
            _logger.debug("  → Rufe _init_engines() auf...")
            engine_start = time.monotonic()
            self._init_engines()
            _logger.debug(
                "  ✅ _init_engines() abgeschlossen in %.2fms",
                (time.monotonic() - engine_start) * 1000,
            )
        except Exception as e:
            error_msg = (
                f"Engine-Initialisierung fehlgeschlagen: {type(e).__name__}: {e}"
            )
            _logger.exception("❌ %s", error_msg)
            errors.append(error_msg)

        duration = time.monotonic() - start_time

        if not errors:
            _logger.info(
                "✅ Manager und Engines initialisiert in %.2fms",
                duration * 1000,
            )
            if self.transcription_engine is None:
                _logger.warning(
                    "⚠️ _init_engines() hat keine TranscriptionEngine erzeugt! Demo‑Modus aktiviert.",
                )
                self._init_errors.append(
                    "TranscriptionEngine konnte nicht initialisiert werden",
                )
                self.demo_mode = True
            else:
                _logger.debug(
                    "   → transcription_engine = %s",
                    type(self.transcription_engine).__name__,
                )
            return

        self.demo_mode = True
        for err in errors:
            self._init_errors.append(err)

        has_transcription = self.transcription_engine is not None
        has_translation = getattr(self, "translation_engine", None) is not None

        if not has_transcription and not has_translation:
            status_msg = "⚠️ Manager/Engines nicht verfügbar – eingeschränkter Modus"
            _logger.error("❌ %s", status_msg)
            self._show_initial_status("⚠️ Keine Engines verfügbar – Demo-Modus")
        elif not has_transcription:
            status_msg = "⚠️ Transkription nicht verfügbar – nur Übersetzung"
            _logger.warning("⚠️ %s", status_msg)
            self._show_initial_status("⚠️ Transkription deaktiviert")
        else:
            _logger.warning("⚠️ Übersetzung nicht verfügbar – nur Transkription")
            self._show_initial_status("⚠️ Übersetzung deaktiviert")

        _logger.info(
            "✅ _init_managers_and_engines abgeschlossen in %.2fms (Demo-Modus=%s, Fehler=%d)",
            duration * 1000,
            self.demo_mode,
            len(errors),
        )

    def _init_translation_executor(self) -> None:
        """Initialisiert den Translation-Executor (V3.0)."""
        import logging
        import time
        from concurrent.futures import ThreadPoolExecutor

        _logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        _logger.debug("▶️ _init_translation_executor ENTRY")

        if (
            hasattr(self, "translation_executor")
            and self.translation_executor is not None
        ):
            _logger.debug(
                "  ℹ️ Translation-Executor existiert bereits – fahre alten herunter"
            )
            try:
                if hasattr(self.translation_executor, "shutdown"):
                    self.translation_executor.shutdown(wait=False, cancel_futures=True)
                    _logger.debug("  ✅ Alter Translation-Executor heruntergefahren")
            except Exception as e:
                _logger.warning("  ⚠️ Konnte alten Executor nicht herunterfahren: %s", e)
            self.translation_executor = None

        requested = None
        try:
            requested = getattr(self.advanced_settings, "translation_workers", None)
        except Exception as e:
            _logger.warning("  ⚠️ Konnte translation_workers nicht auslesen: %s", e)
            requested = None

        if isinstance(requested, int) and requested >= 1:
            base_workers = requested
            _source = f"advanced_settings.translation_workers={requested}"
        else:
            base_workers = 2
            _source = "Default (Settings-Wert fehlt/ungültig)"

        max_workers = max(base_workers, 2)
        max_workers = min(max_workers, 6)

        if max_workers != base_workers:
            _logger.debug(
                "  ℹ️ Worker-Anzahl angepasst: %d → %d (V3.0: min 2, max 6)",
                base_workers,
                max_workers,
            )

        _logger.debug("  📊 max_workers=%d (%s)", max_workers, _source)

        try:
            self.translation_executor = ThreadPoolExecutor(
                max_workers=max_workers,
                thread_name_prefix="Translation",
            )
            _logger.debug(
                "  ✅ TranslationExecutor initialisiert: "
                "max_workers=%d, prefix='Translation', ID=%s",
                max_workers,
                id(self.translation_executor),
            )
        except Exception as e:
            _logger.exception("  ❌ TranslationExecutor-Fehler: %s", e)
            with contextlib.suppress(Exception):
                self._init_errors.append(
                    f"Translation-Executor konnte nicht gestartet werden: {e}"
                )
            self.translation_executor = None
            with contextlib.suppress(Exception):
                self._show_initial_status("⚠️ Übersetzungs-Executor fehlt")
            return

        try:
            self._translation_executor_workers = max_workers
            self._translation_executor_created = time.time()
            _logger.debug("  ✅ Zusätzliche Executor-Attribute gesetzt")
        except Exception as e:
            _logger.warning("  ⚠️ Konnte Zusatzattribute nicht setzen: %s", e)

        try:
            if self.translation_executor is not None:
                future = self.translation_executor.submit(lambda: True)
                try:
                    result = future.result(timeout=0.5)
                    if result is True:
                        _logger.debug("  ✅ Executor-Funktionstest erfolgreich")
                    else:
                        _logger.warning(
                            "  ⚠️ Executor-Funktionstest ergab "
                            "unerwartetes Ergebnis: %r",
                            result,
                        )
                except Exception as fut_exc:
                    _logger.warning(
                        "  ⚠️ Funktionstest-Future fehlgeschlagen "
                        "(Executor bleibt aktiv): %s",
                        fut_exc,
                    )
                    with contextlib.suppress(Exception):
                        future.cancel()
        except Exception as e:
            _logger.warning(
                "  ⚠️ Executor-Funktionstest fehlgeschlagen: %s – Executor bleibt aktiv",
                e,
            )

        duration_ms = (time.monotonic() - start_time) * 1000
        if self.translation_executor is not None:
            _logger.debug(
                "✅ _init_translation_executor EXIT (Erfolg) in %.2f ms "
                "(max_workers=%d)",
                duration_ms,
                max_workers,
            )
        else:
            _logger.warning(
                "⚠️ _init_translation_executor EXIT (Executor ist None) in %.2f ms",
                duration_ms,
            )

    def _init_stream_info_extractor(self) -> None:
        """Initialisiert den StreamInfoExtractor mit den aktuellen Einstellungen.
        Berücksichtigt Browser‑Cookies, Proxy und Plattform‑Besonderheiten.
        """
        _logger = logging.getLogger("dragon")
        _logger.debug("▶️ _init_stream_info_extractor gestartet")

        def _apply_browser_settings(extractor) -> None:
            """Wendet die Browser‑Cookie‑Einstellungen an – mit Linux‑Fallback."""
            use_cookies = getattr(self.settings, "use_browser_cookies", True)
            browser = getattr(self.settings, "cookies_browser", None)

            extractor.use_browser_cookies = use_cookies

            if browser and browser != "auto":
                if IS_LINUX and not shutil.which(browser):
                    _logger.warning(
                        f"🍪 Konfigurierter Browser '{browser}' nicht gefunden – "
                        "suche automatisch Ersatz.",
                    )
                    browser = None

            if not browser or browser == "auto":
                if IS_LINUX:
                    candidates = [
                        "chromium",
                        "chrome",
                        "firefox",
                        "microsoft-edge",
                        "brave",
                    ]
                    for candidate in candidates:
                        if shutil.which(candidate):
                            browser = candidate
                            _logger.debug(
                                f"🍪 Linux: Browser automatisch auf '{browser}' gesetzt",
                            )
                            break
                    else:
                        browser = "firefox"
                        _logger.warning(
                            "🍪 Linux: Kein bekannter Browser gefunden – verwende 'firefox'",
                        )
                else:
                    browser = getattr(self.settings, "cookies_browser", "firefox")

            extractor.cookies_browser = browser
            _logger.debug(
                f"🍪 Verwende Browser-Cookies: {use_cookies}, Browser: {browser}",
            )

        def _apply_proxy_settings(extractor) -> None:
            """Wendet die Proxy‑Einstellungen an."""
            proxy_enabled = getattr(self.advanced_settings, "proxy_enabled", False)
            proxy_url = getattr(self.advanced_settings, "proxy_url", "")

            extractor.proxy_enabled = proxy_enabled
            extractor.proxy = proxy_url if proxy_enabled else ""

            if proxy_enabled and proxy_url:
                _logger.debug(f"🌐 Proxy aktiv: {proxy_url}")
            elif proxy_enabled and not proxy_url:
                _logger.warning(
                    "🌐 Proxy aktiviert, aber keine URL angegeben – deaktiviere Proxy",
                )
                extractor.proxy_enabled = False
            else:
                _logger.debug("🌐 Proxy deaktiviert")

        def _apply_timeout_settings(extractor) -> None:
            """Wendet Timeout‑Einstellungen an (optional)."""
            timeout = getattr(self.advanced_settings, "stream_timeout", None)
            if timeout is not None and timeout > 0:
                try:
                    extractor.timeout = timeout
                    _logger.debug(f"⏱️ Stream-Timeout auf {timeout}s gesetzt")
                except AttributeError:
                    _logger.debug(
                        "StreamInfoExtractor unterstützt kein 'timeout'-Attribut – überspringe",
                    )

        try:
            _logger.debug("  → Erstelle StreamInfoExtractor...")
            self.stream_info_extractor = StreamInfoExtractor()
        except Exception as e:
            _logger.exception(
                "❌ Fehler beim Instanziieren von StreamInfoExtractor: %s",
                e,
            )
            self._init_errors.append(
                f"StreamInfoExtractor konnte nicht instanziiert werden: {e}",
            )
            self.stream_info_extractor = None
            self._show_initial_status("⚠️ Stream-Info nicht verfügbar")
            return

        try:
            _apply_browser_settings(self.stream_info_extractor)
        except Exception as e:
            _logger.warning(
                f"🍪 Browser-Einstellungen konnten nicht angewendet werden: {e}",
            )

        try:
            _apply_proxy_settings(self.stream_info_extractor)
        except Exception as e:
            _logger.warning(
                f"🌐 Proxy-Einstellungen konnten nicht angewendet werden: {e}",
            )

        try:
            _apply_timeout_settings(self.stream_info_extractor)
        except Exception as e:
            _logger.debug(
                f"⏱️ Timeout-Einstellungen konnten nicht angewendet werden: {e}",
            )

        if hasattr(self.stream_info_extractor, "test_connection") and callable(
            self.stream_info_extractor.test_connection,
        ):
            try:
                _logger.debug(
                    "🔍 Führe Verbindungstest für StreamInfoExtractor durch...",
                )
                success = self.stream_info_extractor.test_connection()
                if success:
                    _logger.debug("✅ StreamInfoExtractor-Verbindungstest erfolgreich")
                else:
                    _logger.warning(
                        "⚠️ StreamInfoExtractor-Verbindungstest fehlgeschlagen – Extractor bleibt aktiv",
                    )
            except Exception as e:
                _logger.debug(
                    f"ℹ️ Verbindungstest nicht verfügbar oder fehlgeschlagen: {e}",
                )

        _logger.debug("✅ StreamInfoExtractor initialisiert und konfiguriert")
        self._show_initial_status("✅ Stream-Info bereit")

        _logger.debug(
            "📋 StreamInfoExtractor-Konfiguration: use_cookies=%s, browser=%s, proxy_enabled=%s, proxy=%s",
            getattr(self.stream_info_extractor, "use_browser_cookies", None),
            getattr(self.stream_info_extractor, "cookies_browser", "N/A"),
            getattr(self.stream_info_extractor, "proxy_enabled", False),
            getattr(self.stream_info_extractor, "proxy", "N/A"),
        )

    def _register_event_subscriptions(self) -> None:
        """Registriert alle Event-Bus-Abonnements."""
        _logger = logging.getLogger("dragon")

        try:
            self._register_gui_event_subscriptions()
            _logger.debug("✅ GUI‑Event‑Bus‑Abonnements registriert")
        except Exception as e:
            _logger.exception("❌ GUI-Event-Bus-Abonnements Fehler: %s", e)
            self._init_errors.append(
                f"GUI-Event-Bus-Abonnements konnten nicht registriert werden: {e}",
            )
            self._show_initial_status("⚠️ GUI-Event-Bus teilweise nicht verfügbar")

        try:
            self._register_event_bus_subscriptions()
            _logger.debug("✅ Controller‑Event‑Bus‑Abonnements registriert")
        except Exception as e:
            _logger.exception("❌ Controller-Event-Bus-Abonnements Fehler: %s", e)
            self._init_errors.append(
                f"Controller-Event-Bus-Abonnements konnten nicht registriert werden: {e}",
            )
            self._show_initial_status(
                "⚠️ Controller-Event-Bus teilweise nicht verfügbar",
            )

    def _sync_stream_manager_with_gui(self) -> None:
        """🔄 ULTIMATIVE STREAM-MANAGER SYNCHRONISATION V2.0 🔥
        Synchronisiert den StreamManager und StreamInfoExtractor mit den GUI-Einstellungen.
        Mit erweitertem Debugging, Werteprüfung, Fallback und ausführlichem Logging.
        """
        import logging

        _logger = logging.getLogger("dragon")
        _logger.debug("▶️ _sync_stream_manager_with_gui ENTRY")

        if self.stream_manager is None or self.stream_info_extractor is None:
            _logger.warning("⚠️ StreamManager oder StreamInfoExtractor nicht verfügbar")
            _logger.debug(
                "  ▶️ stream_manager=%s, stream_info_extractor=%s",
                self.stream_manager is not None,
                self.stream_info_extractor is not None,
            )
            return

        if not hasattr(self, "settings") or self.settings is None:
            _logger.warning("⚠️ settings nicht verfügbar – Synchronisation übersprungen")
            return
        if not hasattr(self, "advanced_settings") or self.advanced_settings is None:
            _logger.warning(
                "⚠️ advanced_settings nicht verfügbar – Synchronisation übersprungen"
            )
            return

        _logger.debug("  📊 StreamManager-ID: %s", id(self.stream_manager))
        _logger.debug("  📊 StreamInfoExtractor-ID: %s", id(self.stream_info_extractor))

        try:
            use_cookies = getattr(self.settings, "use_browser_cookies", True)
            cookies_browser = getattr(self.settings, "cookies_browser", "firefox")
            proxy_enabled = getattr(self.advanced_settings, "proxy_enabled", False)
            proxy_url = getattr(self.advanced_settings, "proxy_url", "")
            _logger.debug(
                "  📋 Einstellungen: use_cookies=%s, browser=%s, proxy_enabled=%s, proxy_url='%s'",
                use_cookies,
                cookies_browser,
                proxy_enabled,
                proxy_url or "(leer)",
            )
        except Exception as e:
            _logger.error(
                "❌ Fehler beim Auslesen der Einstellungen: %s", e, exc_info=True
            )
            return

        try:
            if hasattr(self.stream_manager, "use_browser_cookies"):
                old = self.stream_manager.use_browser_cookies
                self.stream_manager.use_browser_cookies = use_cookies
                if old != use_cookies:
                    _logger.debug(
                        "  ✅ StreamManager.use_browser_cookies: %s → %s",
                        old,
                        use_cookies,
                    )
                else:
                    _logger.debug(
                        "  ℹ️ StreamManager.use_browser_cookies bleibt %s", use_cookies
                    )
            else:
                _logger.debug("  ⚠️ StreamManager hat kein use_browser_cookies")

            if hasattr(self.stream_manager, "cookies_browser"):
                old = self.stream_manager.cookies_browser
                self.stream_manager.cookies_browser = cookies_browser
                if old != cookies_browser:
                    _logger.debug(
                        "  ✅ StreamManager.cookies_browser: %s → %s",
                        old,
                        cookies_browser,
                    )
                else:
                    _logger.debug(
                        "  ℹ️ StreamManager.cookies_browser bleibt %s", cookies_browser
                    )
            else:
                _logger.debug("  ⚠️ StreamManager hat kein cookies_browser")

            if hasattr(self.stream_manager, "_proxy_enabled"):
                old = self.stream_manager._proxy_enabled
                self.stream_manager._proxy_enabled = proxy_enabled
                if old != proxy_enabled:
                    _logger.debug(
                        "  ✅ StreamManager._proxy_enabled: %s → %s", old, proxy_enabled
                    )
                else:
                    _logger.debug(
                        "  ℹ️ StreamManager._proxy_enabled bleibt %s", proxy_enabled
                    )
            else:
                _logger.debug("  ⚠️ StreamManager hat kein _proxy_enabled")

            if hasattr(self.stream_manager, "_proxy"):
                old = self.stream_manager._proxy
                self.stream_manager._proxy = proxy_url
                if old != proxy_url:
                    _logger.debug(
                        "  ✅ StreamManager._proxy: '%s' → '%s'",
                        old or "(leer)",
                        proxy_url or "(leer)",
                    )
                else:
                    _logger.debug(
                        "  ℹ️ StreamManager._proxy bleibt '%s'", proxy_url or "(leer)"
                    )
            else:
                _logger.debug("  ⚠️ StreamManager hat kein _proxy")

            _logger.debug("  ✅ StreamManager synchronisiert")
        except Exception as e:
            _logger.error(
                "❌ Fehler bei StreamManager-Synchronisation: %s", e, exc_info=True
            )

        try:
            if hasattr(self.stream_info_extractor, "use_browser_cookies"):
                old = self.stream_info_extractor.use_browser_cookies
                self.stream_info_extractor.use_browser_cookies = use_cookies
                if old != use_cookies:
                    _logger.debug(
                        "  ✅ Extractor.use_browser_cookies: %s → %s", old, use_cookies
                    )
                else:
                    _logger.debug(
                        "  ℹ️ Extractor.use_browser_cookies bleibt %s", use_cookies
                    )
            else:
                _logger.debug("  ⚠️ StreamInfoExtractor hat kein use_browser_cookies")

            if hasattr(self.stream_info_extractor, "cookies_browser"):
                old = self.stream_info_extractor.cookies_browser
                self.stream_info_extractor.cookies_browser = cookies_browser
                if old != cookies_browser:
                    _logger.debug(
                        "  ✅ Extractor.cookies_browser: %s → %s", old, cookies_browser
                    )
                else:
                    _logger.debug(
                        "  ℹ️ Extractor.cookies_browser bleibt %s", cookies_browser
                    )
            else:
                _logger.debug("  ⚠️ StreamInfoExtractor hat kein cookies_browser")

            if hasattr(self.stream_info_extractor, "proxy_enabled"):
                old = self.stream_info_extractor.proxy_enabled
                self.stream_info_extractor.proxy_enabled = proxy_enabled
                if old != proxy_enabled:
                    _logger.debug(
                        "  ✅ Extractor.proxy_enabled: %s → %s", old, proxy_enabled
                    )
                else:
                    _logger.debug(
                        "  ℹ️ Extractor.proxy_enabled bleibt %s", proxy_enabled
                    )
            else:
                _logger.debug("  ⚠️ StreamInfoExtractor hat kein proxy_enabled")

            if hasattr(self.stream_info_extractor, "proxy"):
                old = self.stream_info_extractor.proxy
                self.stream_info_extractor.proxy = proxy_url
                if old != proxy_url:
                    _logger.debug(
                        "  ✅ Extractor.proxy: '%s' → '%s'",
                        old or "(leer)",
                        proxy_url or "(leer)",
                    )
                else:
                    _logger.debug(
                        "  ℹ️ Extractor.proxy bleibt '%s'", proxy_url or "(leer)"
                    )
            else:
                _logger.debug("  ⚠️ StreamInfoExtractor hat kein proxy")

            _logger.debug("  ✅ StreamInfoExtractor synchronisiert")
        except Exception as e:
            _logger.error(
                "❌ Fehler bei StreamInfoExtractor-Synchronisation: %s",
                e,
                exc_info=True,
            )

        _logger.debug("✅ StreamManager mit GUI‑Einstellungen synchronisiert")

    def _register_gui_event_subscriptions(self) -> None:
        """Registriert GUI-spezifische Event-Bus-Abonnements."""
        import logging

        _logger = logging.getLogger("dragon")

        event_bus = getattr(self, "event_bus", None)
        if event_bus is None:
            _logger.warning(
                "❌ Event-Bus nicht verfügbar – GUI-Abonnements nicht möglich",
            )
            return

        if getattr(self, "_gui_event_subscriptions_registered", False):
            _logger.debug(
                "_register_gui_event_subscriptions: bereits registriert "
                "– überspringe (bus=%s)",
                id(event_bus),
            )
            return

        old_subs = getattr(self, "_gui_event_subscriptions", None)
        if old_subs:
            unsubscribe_fn = getattr(event_bus, "unsubscribe", None)
            if callable(unsubscribe_fn):
                for event, callback in old_subs:
                    try:
                        unsubscribe_fn(event, callback)
                    except Exception as e:
                        _logger.debug(
                            "Konnte altes Abo '%s' nicht entfernen: %s",
                            event,
                            e,
                        )
        self._gui_event_subscriptions = []

        def _safe_ui_update(description: str, action) -> bool:
            """Führt eine UI-Aktion aus, fängt alle Fehler."""
            try:
                action()
                return True
            except Exception as e:
                _logger.debug(
                    "UI-Update '%s' fehlgeschlagen: %s",
                    description,
                    e,
                )
                return False

        def _set_button_state(btn_attr: str, state: str) -> None:
            """Setzt einen Button-State sicher (mit winfo_exists-Guard)."""
            btn = getattr(self, btn_attr, None)
            if btn is None:
                return

            def _do():
                if btn.winfo_exists():
                    btn.config(state=state)

            _safe_ui_update(f"{btn_attr}={state}", _do)

        def _set_status_text(text: str) -> None:
            """Aktualisiert die Statusleiste (var oder label)."""

            def _do():
                if hasattr(self, "status_var") and self.status_var:
                    self.status_var.set(text)
                elif hasattr(self, "status_label") and self.status_label:
                    self.status_label.config(text=text)

            _safe_ui_update(f"status='{text[:30]}'", _do)

        def _reset_progress() -> None:
            """Setzt den Fortschrittsbalken auf 0."""

            def _do():
                if hasattr(self, "progress_var") and self.progress_var:
                    self.progress_var.set(0)
                if hasattr(self, "progress_bar") and self.progress_bar:
                    self.progress_bar["value"] = 0

            _safe_ui_update("progress=0", _do)

        def on_processing_started(data=None):
            """Verarbeitung gestartet → GUI in Bearbeitungsmodus."""
            _logger.info(
                "🔄 processing_started empfangen – GUI → Bearbeitungsmodus",
            )
            try:
                _set_button_state("start_button", tk.DISABLED)
                _set_button_state("stop_button", tk.NORMAL)
                _set_status_text("Verarbeitung läuft...")
                _reset_progress()
                self.is_processing = True
                self._processing = True
            except Exception as e:
                _logger.error(
                    "on_processing_started: unerwarteter Fehler: %s",
                    e,
                    exc_info=True,
                )

        def on_processing_finished(data=None):
            """Verarbeitung beendet → GUI zurücksetzen."""
            if getattr(self, "_is_finished_called", False):
                _logger.debug(
                    "on_processing_finished: bereits aufgerufen – überspringe",
                )
                return
            self._is_finished_called = True

            _logger.info(
                "✅ processing_finished empfangen – GUI → idle",
            )
            try:
                _set_button_state("start_button", tk.NORMAL)
                _set_button_state("stop_button", tk.DISABLED)
                _reset_progress()
                _set_status_text("Bereit")
                self.is_processing = False
                self._processing = False
                self._processing_thread = None

                deactivate = getattr(
                    self,
                    "_deactivate_linux_optimizer",
                    None,
                )
                if callable(deactivate):
                    _safe_ui_update(
                        "deactivate_linux_optimizer",
                        deactivate,
                    )
            except Exception as e:
                _logger.error(
                    "on_processing_finished: unerwarteter Fehler: %s",
                    e,
                    exc_info=True,
                )

        def on_processing_state_changed(is_processing: bool):
            """State-Change → Button nur bei Start deaktivieren.

            Beim Ende übernimmt `on_processing_finished` das Re-Enable,
            damit dort der _is_finished_called-Guard greift.
            """
            self.is_processing = bool(is_processing)
            self._processing = bool(is_processing)
            _logger.debug(
                "processing_state_changed: %s",
                is_processing,
            )

            if is_processing:
                try:
                    _set_button_state("start_button", tk.DISABLED)
                    _set_button_state("stop_button", tk.NORMAL)
                    _set_status_text("Verarbeitung läuft...")
                except Exception as e:
                    _logger.error(
                        "on_processing_state_changed: Fehler: %s",
                        e,
                        exc_info=True,
                    )

        def on_info_message(message):
            """Info-Meldung in Statusleiste anzeigen."""
            if not message:
                return
            try:
                _set_status_text(str(message)[:100])
            except Exception as e:
                _logger.debug("on_info_message Fehler: %s", e)

        def on_error_message(message):
            """Fehlermeldung in Statusleiste anzeigen."""
            if not message:
                return
            try:
                _set_status_text(f"⚠️ {str(message)[:80]}")
            except Exception as e:
                _logger.debug("on_error_message Fehler: %s", e)

        subscriptions = [
            ("processing_started", on_processing_started),
            ("processing_finished", on_processing_finished),
            ("processing_state_changed", on_processing_state_changed),
            ("info", on_info_message),
            ("error", on_error_message),
        ]

        _logger.info(
            "🔎 GUI-Event-Abos: registriere %d Handler auf Bus %s",
            len(subscriptions),
            id(event_bus),
        )

        registered: list[tuple[str, Any]] = []
        errors: list[str] = []

        for event, callback in subscriptions:
            try:
                event_bus.subscribe(event, callback)
                registered.append((event, callback))
                _logger.info(
                    "  ✅ Abo gesetzt: %s (bus=%s)",
                    event,
                    id(event_bus),
                )
            except Exception as e:
                errors.append(event)
                _logger.error(
                    "  ❌ Abo für '%s' fehlgeschlagen: %s",
                    event,
                    e,
                    exc_info=True,
                )

        self._gui_event_subscriptions = registered

        try:
            subscriber_map = getattr(event_bus, "_subscribers", None)
            if isinstance(subscriber_map, dict):
                for event, _ in registered:
                    n = len(subscriber_map.get(event, []))
                    _logger.info(
                        "  🔍 Verify: %s → %d Handler auf Bus",
                        event,
                        n,
                    )
        except Exception as e:
            _logger.debug("Verifikation fehlgeschlagen: %s", e)

        controller = getattr(self, "controller", None)
        if controller is not None:
            ctrl_bus = getattr(controller, "event_bus", None)

            if ctrl_bus is None:
                try:
                    controller.event_bus = event_bus
                    _logger.warning(
                        "✅ Event-Bus im Controller nachträglich gesetzt (bus=%s)",
                        id(event_bus),
                    )
                except Exception as e:
                    _logger.warning(
                        "Konnte Event-Bus im Controller nicht setzen: %s",
                        e,
                    )
            elif id(ctrl_bus) != id(event_bus):
                _logger.error(
                    "⚠️ BUS-MISMATCH: Controller-Bus=%s, GUI-Bus=%s. "
                    "Events werden NICHT zugestellt!",
                    id(ctrl_bus),
                    id(event_bus),
                )
                try:
                    controller.event_bus = event_bus
                    _logger.warning(
                        "🔧 Controller-Bus auf GUI-Bus umgestellt",
                    )
                except Exception as e:
                    _logger.error(
                        "Konnte Controller-Bus nicht umstellen: %s",
                        e,
                    )
            else:
                _logger.info(
                    "✅ Controller nutzt denselben EventBus (bus=%s)",
                    id(event_bus),
                )

        if not hasattr(self, "_is_finished_called"):
            self._is_finished_called = False

        self._gui_event_subscriptions_registered = True

        if errors:
            _logger.warning(
                "GUI-Event-Abos: %d von %d registriert, Fehler bei: %s",
                len(registered),
                len(subscriptions),
                errors,
            )
        else:
            _logger.info(
                "✅ Alle %d GUI-Event-Abos erfolgreich registriert (bus=%s)",
                len(registered),
                id(event_bus),
            )

    def _init_gui_layout(self) -> None:
        """Erstellt das GUI-Layout und die Statusleiste."""

        def _init_tts_vars():
            """Initialisiert die Auto-TTS-Variablen."""
            if (
                not hasattr(self, "auto_tts_transcript_var")
                or self.auto_tts_transcript_var is None
            ):
                self.auto_tts_transcript_var = tk.BooleanVar(
                    value=getattr(
                        self.advanced_settings,
                        "auto_tts_transcript",
                        False,
                    ),
                )
            if (
                not hasattr(self, "auto_tts_translation_var")
                or self.auto_tts_translation_var is None
            ):
                self.auto_tts_translation_var = tk.BooleanVar(
                    value=getattr(
                        self.advanced_settings,
                        "auto_tts_translation",
                        False,
                    ),
                )

        def _create_layout_and_queue():
            """Erstellt LayoutManager und QueueManager."""
            self.layout = WhisperLayoutManager(gui_ref=self)
            self.queue_manager = QueueManager(self)
            self.event_bus.set_queue_manager(self.queue_manager)

        def _resolve_label(
            attr_name: str,
            candidates: list[str],
        ) -> tk.Widget | None:
            """Sucht ein Label-Widget im Selbst, GUI oder Layout."""
            _existing = getattr(self, attr_name, None)
            if _existing is not None:
                try:
                    if _existing.winfo_exists():
                        return _existing
                except Exception:
                    pass

            for _name in candidates:
                _w = getattr(self.layout, _name, None)
                if _w is not None:
                    try:
                        if _w.winfo_exists():
                            return _w
                    except Exception:
                        continue

            for _name in candidates:
                _w = getattr(self, _name, None)
                if _w is not None:
                    try:
                        if _w.winfo_exists():
                            return _w
                    except Exception:
                        continue

            return None

        def _setup_gui():
            """Baut das GUI-Layout auf und speichert Widget-Referenzen."""
            self._adaptive_window_size()
            self.layout.setup_gui()
            self.stream_title_label = _resolve_label(
                "stream_title_label",
                ("stream_title_label", "title_label", "stream_label"),
            )
            self.stream_details_label = _resolve_label(
                "stream_details_label",
                (
                    "stream_details_label",
                    "details_label",
                    "stream_info_label",
                ),
            )

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "GUI-Struktur aufgebaut: "
                    f"stream_title_label={'✅' if self.stream_title_label else '❌'}, "
                    f"stream_details_label="
                    f"{'✅' if self.stream_details_label else '❌'}",
                )

        def _init_model_combo():
            """Initialisiert die Modell-ComboBox."""
            if hasattr(self, "model_var") and self.model_var is not None:
                default_model = getattr(self.settings, "default_model", "base")
                normalized = self.model_manager.get_valid(default_model)
                self.model_var.set(normalized)

            if hasattr(self, "model_combo") and self.model_combo is not None:
                try:
                    self._load_model_list_async()
                except Exception as e:
                    logger.warning(
                        "Fehler beim Befüllen der Modell-ComboBox: %s",
                        e,
                    )
                    self.model_combo["values"] = [
                        "base",
                        "small",
                        "medium",
                        "large",
                    ]
                    self.model_var.set("base")

        def _init_status_bar():
            """Erstellt die Statusleiste."""
            self.status_bar = StatusBar(
                self.root,
                self,
                demo_mode=self.demo_mode,
            )
            self.status_bar.frame.grid(
                row=4,
                column=0,
                sticky="ew",
                pady=(2, 0),
            )
            self._update_vad_fallback_button()
            self._update_live_mode_button()

        def _finalize_window():
            """Aktualisiert die Fensterdarstellung."""
            self.root.update_idletasks()
            self.root.resizable(True, True)
            self.root.deiconify()

        try:
            _init_tts_vars()
        except Exception as e:
            logger.error(
                "Fehler beim Initialisieren der TTS-Variablen: %s",
                e,
            )

        try:
            _create_layout_and_queue()
        except Exception as e:
            self._init_errors.append(f"Layout/Queue-Manager Fehler: {e}")
            logger.exception(
                "❌ Fehler beim Erstellen von Layout/Queue-Manager",
            )
            raise

        try:
            _setup_gui()
        except Exception as e:
            self._init_errors.append(f"GUI-Setup Fehler: {e}")
            logger.exception("❌ Fehler beim Aufbau der GUI-Struktur")
            raise

        try:
            _init_model_combo()
        except Exception as e:
            logger.warning(
                "Fehler beim Initialisieren der Modell-ComboBox: %s",
                e,
            )

        try:
            self._setup_callbacks()
            self.vad_fallback_enabled = tk.BooleanVar(
                value=getattr(
                    self.advanced_settings,
                    "vad_fallback_enabled",
                    True,
                ),
            )
        except Exception as e:
            logger.warning(
                "Fehler beim Setzen der Callbacks/Variablen: %s",
                e,
            )

        try:
            _init_status_bar()
        except Exception as e:
            self._init_errors.append(f"Statusleiste Fehler: {e}")
            logger.exception("❌ Fehler beim Erstellen der Statusleiste")
            self.status_bar = None

        try:
            self._start_gui_updaters()
            self._set_initial_url()
        except Exception as e:
            logger.warning(
                "Fehler beim Starten der Updater/URL-Setzung: %s",
                e,
            )

        try:
            _finalize_window()
        except Exception as e:
            logger.warning(
                "Fehler beim finalen Anzeigen des Fensters: %s",
                e,
            )

        if DEBUG_LEVEL >= 3:
            log_debug("gui", "GUI-Layout erfolgreich aufgebaut")

        self._show_initial_status("✅ GUI bereit")

        if self.stream_title_label is not None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "✅ Stream-Title-Label gefunden und gespeichert",
                )
        else:
            logger.warning(
                "⚠️ Stream-Title-Label nicht gefunden – "
                "update_stream_info wird nicht funktionieren",
            )

        if self.stream_details_label is not None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "✅ Stream-Details-Label gefunden und gespeichert",
                )
        else:
            logger.warning(
                "⚠️ Stream-Details-Label nicht gefunden – "
                "update_stream_info wird nicht funktionieren",
            )

    def _init_signal_and_timers(self) -> None:
        """Registriert Signal‑Handler, Tastenkürzel und startet periodische Timer."""
        if hasattr(self, "_register_signal_handlers"):
            try:
                self._register_signal_handlers()
            except Exception as e:
                logger.warning("Signal‑Handler Registrierung fehlgeschlagen: %s", e)
        else:
            logger.warning(
                "_register_signal_handlers fehlt – Signale werden nicht behandelt.",
            )

        if self._show_cookie_notice and not self._dependency_issue:
            self._safe_after(500, self._show_cookie_notice_dialog)

        if hasattr(self, "_bind_shortcuts"):
            try:
                self._bind_shortcuts()
            except Exception as e:
                logger.warning("Tastenkürzel‑Bindung fehlgeschlagen: %s", e)
        else:
            logger.warning("_bind_shortcuts fehlt – Tastenkürzel nicht verfügbar.")

        self._safe_after(1000, self._start_system_monitoring)
        self._safe_after(2000, self._final_initialization_check)
        self._schedule_gui_health_check()

        if not hasattr(self.__class__, "_atexit_cleanup_registered"):
            try:
                atexit.register(self._atexit_cleanup)
                self.__class__._atexit_cleanup_registered = True
                logger.debug("✅ Atexit‑Cleanup für GUI registriert")
            except Exception as e:
                logger.warning("atexit‑Cleanup Registrierung fehlgeschlagen: %s", e)

        try:
            import loky  # noqa: F401

            if not hasattr(sys, "_loky_cleanup_registered"):
                atexit.register(_perform_loky_cleanup)
                sys._loky_cleanup_registered = True
                logger.debug("✅ Loky‑Cleanup als atexit‑Handler registriert")
        except ImportError:
            pass
        except Exception as e:
            logger.debug("Loky‑Cleanup Registrierung ignoriert: %s", e)

        missing_ffmpeg = not shutil.which("ffmpeg")
        missing_ytdlp = not shutil.which("yt-dlp")
        missing_numpy = not NUMPY_AVAILABLE
        if missing_ffmpeg or missing_ytdlp or missing_numpy:
            self._dependency_issue = True

            def _open_installer() -> None:
                if not self.is_shutting_down() and hasattr(self, "show_install_dialog"):
                    self.show_install_dialog()

            self._safe_after(1500, _open_installer)

        if self._init_errors:
            error_text = "Die folgenden Probleme wurden beim Start festgestellt:\n\n"
            error_text += "\n".join(f"• {err}" for err in self._init_errors[:20])
            if len(self._init_errors) > 20:
                error_text += f"\n… und {len(self._init_errors) - 20} weitere"
            error_text += "\n\nEinige Funktionen sind möglicherweise eingeschränkt."

            def _show_init_errors() -> None:
                try:
                    DarkMessageBox.showwarning(
                        "Start‑Warnungen",
                        error_text,
                        parent=self.root,
                    )
                except Exception:
                    logger.warning(
                        "Konnte Start‑Warnungen nicht anzeigen: %s",
                        error_text,
                    )

            self._safe_after(800, _show_init_errors)

    def _load_model_list_async(self) -> None:
        """Lädt die verfügbaren Modelle asynchron in die ComboBox."""

        def _load():
            try:
                models = sorted(self.model_manager.get_available_models())
                self._safe_gui_update(lambda: self._update_model_combo(models))
            except Exception as e:
                logger.warning(f"Asynchrones Laden der Modelle fehlgeschlagen: {e}")
                self._safe_gui_update(
                    lambda: self._update_model_combo(
                        ["base", "small", "medium", "large"],
                    ),
                )

        threading.Thread(target=_load, daemon=True, name="ModelListLoader").start()

    def _update_model_combo(self, models: list[str]) -> None:
        """Aktualisiert die Modell‑ComboBox im Hauptthread."""
        try:
            if hasattr(self, "model_combo") and self.model_combo is not None:
                self.model_combo["values"] = models
                current = self.model_var.get()
                if current not in models and models:
                    self.model_var.set(models[0])
                logger.debug(f"Modell‑ComboBox aktualisiert: {len(models)} Modelle")
        except Exception as e:
            logger.warning(f"Fehler beim Aktualisieren der Modell‑ComboBox: {e}")

    def _finalize_init(self) -> bool:
        """Führt abschließende Prüfungen durch, zeigt das Fenster an,
        startet den VRAM-Timer, synchronisiert Auto-TTS und
        startet die GUI-Queue-Verarbeitung (beide Queues).
        """
        import logging
        import time
        import tkinter as tk

        _logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        init_verbose = getattr(self, "_init_verbose", False)

        if getattr(self, "_finalization_done", False):
            if debug_level >= 3:
                _logger.debug(
                    "_finalize_init: bereits abgeschlossen – überspringe "
                    "(verhindert doppelte Timer/Logs)",
                )
            return True

        if debug_level >= 3:
            _logger.debug("▶️ _finalize_init: START")

        if getattr(self, "transcription_engine", None) is None:
            _logger.error(
                "❌ transcription_engine ist None am Ende der Init-Phase!",
            )
            self._init_errors.append(
                "TranscriptionEngine fehlt – Demo-Modus wird verwendet",
            )
            self.demo_mode = True

        if hasattr(self, "_init_errors") and self._init_errors:
            _logger.warning(
                "⚠️ Initialisierung mit %d Fehlern abgeschlossen",
                len(self._init_errors),
            )
            for err in self._init_errors:
                _logger.warning("   - %s", err)

            error_text = "Die folgenden Probleme wurden beim Start festgestellt:\n\n"
            error_text += "\n".join(f"• {err}" for err in self._init_errors[:20])
            if len(self._init_errors) > 20:
                error_text += f"\n… und {len(self._init_errors) - 20} weitere"
            error_text += "\n\nEinige Funktionen sind möglicherweise eingeschränkt."

            def _show_errors() -> None:
                try:
                    if self._ensure_root_exists():
                        DarkMessageBox.showwarning(
                            "Start-Warnungen",
                            error_text,
                            parent=self.root,
                            timeout=10,
                        )
                    else:
                        _logger.warning(
                            "Start-Warnungen (kein GUI-Fenster): %s",
                            error_text,
                        )
                except Exception as e:
                    _logger.warning(
                        "Konnte Start-Warnungen nicht anzeigen: %s – %s",
                        error_text,
                        e,
                    )

            self._safe_after(500, _show_errors)
        else:
            _logger.info("✅ Initialisierung erfolgreich abgeschlossen")
            _logger.debug(
                "✅ _init_controller_and_engines erfolgreich abgeschlossen",
            )
            try:
                import platform as _plat_ai

                _py_ver = _plat_ai.python_version()
                try:
                    import torch as _t_ai

                    _torch_ver = _t_ai.__version__
                    _cuda_ver = (
                        _t_ai.version.cuda if _t_ai.cuda.is_available() else "cpu"
                    )
                except Exception:
                    _torch_ver = "n/a"
                    _cuda_ver = "n/a"

                _adv_ai = getattr(self, "advanced_settings", None)
                _settings_ai = getattr(self, "settings", None)
                _ap_ai = getattr(self, "audio_processor", None)

                def _get_ai(*pairs, default="?"):
                    """Liefert ersten nicht-leeren Wert aus (obj, attr)-Paaren.
                    """
                    for _o, _a in pairs:
                        try:
                            if _o is None:
                                continue
                            _v = getattr(_o, _a, None)
                            if hasattr(_v, "get") and callable(
                                getattr(_v, "get", None)
                            ):
                                with contextlib.suppress(Exception):
                                    _v = _v.get()
                            elif callable(_v) and not isinstance(_v, str):
                                try:
                                    _v = _v()
                                except Exception:
                                    continue
                            if _v is not None and _v != "":
                                return _v
                        except Exception:
                            continue
                    return default

                _chunk_ai = _get_ai(
                    (_adv_ai, "chunk_duration"),
                    (_settings_ai, "chunk_duration"),
                    default="?",
                )

                _adv_cfg_ai = getattr(_adv_ai, "config", None)
                _set_cfg_ai = getattr(_settings_ai, "config", None)
                _overlap_ai = _get_ai(
                    (_adv_cfg_ai, "CHUNK_OVERLAP"),
                    (_set_cfg_ai, "CHUNK_OVERLAP"),
                    (_adv_ai, "chunk_overlap"),
                    default="?",
                )

                _model_ai = "?"
                try:
                    _argv_ai = sys.argv
                    for _i_ai, _a_ai in enumerate(_argv_ai):
                        if _a_ai == "--model" and _i_ai + 1 < len(_argv_ai):
                            _model_ai = _argv_ai[_i_ai + 1]
                            break
                        if _a_ai.startswith("--model="):
                            _model_ai = _a_ai.split("=", 1)[1]
                            break
                except Exception:
                    pass
                if _model_ai in ("?", None, ""):
                    _model_ai = _get_ai(
                        (self, "model_var"),
                        (self, "model"),
                        (_adv_ai, "model"),
                        (_adv_ai, "model_size"),
                        (_settings_ai, "model"),
                        (_settings_ai, "model_size"),
                        default="?",
                    )
                if _model_ai in ("?", None, "", "unknown"):
                    try:
                        import json as _json_ai
                        from pathlib import Path as _Path_ai

                        _cfg_path_ai = (
                            _Path_ai.home()
                            / ".config"
                            / "dragonwhisperer"
                            / "dragon_advanced_settings.json"
                        )
                        if _cfg_path_ai.exists():
                            _cfg_data_ai = _json_ai.loads(
                                _cfg_path_ai.read_text(encoding="utf-8")
                            )
                            _model_ai = (
                                _cfg_data_ai.get("model_size")
                                or _cfg_data_ai.get("model")
                                or _cfg_data_ai.get("default_model")
                                or "unknown"
                            )
                    except Exception:
                        pass
                if _model_ai in ("?", None, ""):
                    _model_ai = "unknown"

                log_ai(
                    "ARCH",
                    version="dw",
                    python=_py_ver,
                    torch=_torch_ver,
                    cuda=_cuda_ver,
                    host=_plat_ai.node()[:32],
                )
                log_ai(
                    "ARCH-CONFIG",
                    model="pending",
                    chunk=str(_chunk_ai),
                    overlap=str(_overlap_ai),
                    sr=16000,
                    channels=1,
                )
                try:
                    _tl_ai = getattr(_adv_ai, "target_language", None)
                    if _tl_ai:
                        _set_target_lang(_tl_ai)
                except Exception:
                    pass
                log_ai(
                    "ARCH-FLAGS",
                    halluc_filter="ON"
                    if getattr(_ap_ai, "_filter_hallucinations", True)
                    else "OFF",
                    sentence_buffer="ON"
                    if getattr(_ap_ai, "_enable_sentence_buffering", False)
                    else "OFF",
                    subtitle="ON" if getattr(_ap_ai, "subtitle_mode", False) else "OFF",
                )
                log_ai(
                    "ARCH-PIPELINE",
                    shape=("yt-dlp>ffmpeg>dispatcher>transcribe_q>translate_q>emit_q"),
                )
            except Exception:
                pass

        success = True

        try:
            if self._ensure_root_exists():
                self.root.deiconify()
                self.root.update_idletasks()
                if debug_level >= 3:
                    _logger.debug("GUI-Fenster sichtbar gemacht")
            else:
                _logger.warning(
                    "root-Fenster existiert nicht – kann nicht sichtbar gemacht werden",
                )
                success = False
        except tk.TclError as e:
            _logger.error("TclError beim Anzeigen des Fensters: %s", e)
            success = False
        except Exception as e:
            _logger.error(
                "Fehler beim Anzeigen des Fensters: %s",
                e,
                exc_info=True,
            )
            success = False

        try:
            if self._ensure_root_exists():
                self._schedule_vram_idle_check()
                if debug_level >= 2:
                    _logger.debug(
                        "VRAM-Idle-Timer gestartet (nach GUI-Init)",
                    )
            elif debug_level >= 3:
                _logger.debug(
                    "VRAM-Timer nicht gestartet – root nicht verfügbar",
                )
        except Exception as e:
            _logger.warning("Fehler beim Starten des VRAM-Timers: %s", e)
            success = False

        try:
            if hasattr(self, "_sync_auto_tts_to_processor") and callable(
                self._sync_auto_tts_to_processor,
            ):
                self._safe_after(100, self._sync_auto_tts_to_processor)
                if debug_level >= 3:
                    _logger.debug("_sync_auto_tts_to_processor aufgerufen")
            elif debug_level >= 3:
                _logger.debug(
                    "_sync_auto_tts_to_processor nicht verfügbar",
                )
        except Exception as e:
            _logger.warning(
                "Auto-TTS-Synchronisation fehlgeschlagen: %s",
                e,
            )

        if hasattr(self, "_process_gui_queue_dynamic") and callable(
            self._process_gui_queue_dynamic,
        ):
            try:
                if self._ensure_root_exists() and getattr(
                    self,
                    "root",
                    None,
                ):
                    self.root.after(100, self._process_gui_queue_dynamic)
                    if debug_level >= 2:
                        _logger.debug(
                            "✅ GUI-Queue-Verarbeitung gestartet (after 100ms)",
                        )
                elif debug_level >= 3:
                    _logger.debug(
                        "⚠️ Kein root-Objekt – GUI-Queue nicht gestartet",
                    )
            except Exception as e:
                _logger.warning(
                    "[GUI-QUEUE] ❌ Start der GUI-Queue-Verarbeitung "
                    "fehlgeschlagen: %s",
                    e,
                )
                success = False
        else:
            _logger.warning(
                "[GUI-QUEUE] ⚠️ _process_gui_queue_dynamic ist NICHT "
                "in der GUI-Klasse definiert!",
            )
            _gui_obj = getattr(self, "gui", None)
            if _gui_obj is not None and hasattr(_gui_obj, "_process_gui_queue_dynamic"):
                try:
                    if self._ensure_root_exists() and getattr(
                        self,
                        "root",
                        None,
                    ):
                        self.root.after(
                            100,
                            _gui_obj._process_gui_queue_dynamic,
                        )
                        if debug_level >= 2:
                            _logger.debug(
                                "✅ GUI-Queue gestartet (über self.gui)",
                            )
                    elif debug_level >= 3:
                        _logger.debug(
                            "⚠️ Kein root-Objekt – GUI-Queue nicht gestartet",
                        )
                except Exception as e:
                    _logger.warning(
                        "[GUI-QUEUE] ❌ Start der GUI-Queue (über "
                        "self.gui) fehlgeschlagen: %s",
                        e,
                    )
                    success = False
            else:
                _logger.error(
                    "[GUI-QUEUE] ❌ _process_gui_queue_dynamic konnte "
                    "nirgendwo gefunden werden! GUI-Queue wird nicht "
                    "verarbeitet.",
                )

        if hasattr(self, "_process_text_queue") and callable(
            self._process_text_queue,
        ):
            try:
                if self._ensure_root_exists() and getattr(
                    self,
                    "root",
                    None,
                ):
                    self.root.after(200, self._process_text_queue)
                    if debug_level >= 2:
                        _logger.debug(
                            "✅ Text-Queue-Verarbeitung gestartet (after 200ms)",
                        )
                elif debug_level >= 3:
                    _logger.debug(
                        "⚠️ Kein root-Objekt – Text-Queue nicht gestartet",
                    )
            except Exception as e:
                _logger.warning(
                    "[TEXT-QUEUE] ❌ Start der Text-Queue-Verarbeitung "
                    "fehlgeschlagen: %s",
                    e,
                )
                success = False
        else:
            _logger.warning(
                "[TEXT-QUEUE] ⚠️ _process_text_queue ist NICHT in der "
                "GUI-Klasse definiert!",
            )
            _gui_obj = getattr(self, "gui", None)
            if _gui_obj is not None and hasattr(_gui_obj, "_process_text_queue"):
                try:
                    if self._ensure_root_exists() and getattr(
                        self,
                        "root",
                        None,
                    ):
                        self.root.after(200, _gui_obj._process_text_queue)
                        if debug_level >= 2:
                            _logger.debug(
                                "✅ Text-Queue gestartet (über self.gui)",
                            )
                    elif debug_level >= 3:
                        _logger.debug(
                            "⚠️ Kein root-Objekt – Text-Queue nicht gestartet",
                        )
                except Exception as e:
                    _logger.warning(
                        "[TEXT-QUEUE] ❌ Start der Text-Queue (über "
                        "self.gui) fehlgeschlagen: %s",
                        e,
                    )
                    success = False
            else:
                _logger.error(
                    "[TEXT-QUEUE] ❌ _process_text_queue konnte "
                    "nirgendwo gefunden werden! Text-Queue wird nicht "
                    "verarbeitet.",
                )

        elapsed_ms = (time.perf_counter() - self._init_start_time) * 1000

        if success:
            _logger.debug(
                "✅ Alle Queues gestartet: GUI-Queue und Text-Queue",
            )
            _logger.info(
                "🐉 Dragon Whisperer GUI bereit in %.1f ms",
                elapsed_ms,
            )
            _logger.info("🐉 Bereit – Starten Sie einen Stream!")
            try:
                if hasattr(self, "update_status") and callable(
                    self.update_status,
                ):
                    self.update_status(
                        "🐉 Bereit – Starten Sie einen Stream!",
                    )
            except Exception as e:
                _logger.debug("Statusanzeige fehlgeschlagen: %s", e)
        else:
            _logger.warning(
                "🐉 Dragon Whisperer GUI wurde mit Fehlern initialisiert in %.1f ms",
                elapsed_ms,
            )
            try:
                if hasattr(self, "update_status") and callable(
                    self.update_status,
                ):
                    self.update_status(
                        "⚠️ Start mit Fehlern – Details in der Konsole",
                    )
            except Exception as e:
                _logger.debug("Statusanzeige fehlgeschlagen: %s", e)

        if init_verbose:
            print(
                f"🔍 [INIT] Initialisierung abgeschlossen in "
                f"{elapsed_ms:.1f} ms (success={success})",
            )

        _probes_enabled = (
            DEBUG_LEVEL >= 5
            and os.environ.get("DW_DEBUG_PROBES") == "1"
            and not getattr(self, "_debug_probes_installed", False)
        )
        if _probes_enabled:
            self._debug_probes_installed = True

            _logger.debug(
                "🔍 [DEBUG-PROBES] Installiere Diagnose-Probes "
                "(aktiviert via DW_DEBUG_PROBES=1)…",
            )

            try:

                def _on_global_click(event: tk.Event) -> None:
                    try:
                        _w = event.widget
                        _w_cls = type(_w).__name__
                        _w_repr = str(_w)[:80]
                        _w_text = ""
                        try:
                            if hasattr(_w, "cget"):
                                _w_text = str(_w.cget("text"))[:50]
                        except Exception:
                            pass
                        _logger.warning(
                            "🔍 [KLICK-ALL] widget=%s, text=%r, class=%s, x=%s, y=%s",
                            _w_repr,
                            _w_text,
                            _w_cls,
                            getattr(event, "x", "?"),
                            getattr(event, "y", "?"),
                        )
                    except Exception as _e:
                        _logger.warning(
                            "🔍 [KLICK-ALL] Fehler: %s",
                            _e,
                        )

                if self._ensure_root_exists() and getattr(
                    self,
                    "root",
                    None,
                ):
                    self.root.bind_all(
                        "<Button-1>",
                        _on_global_click,
                        add="+",
                    )
                    _logger.warning(
                        "🔍 [DEBUG-PROBES] bind_all <Button-1> aktiv",
                    )
                else:
                    _logger.warning(
                        "🔍 [DEBUG-PROBES] root nicht verfügbar – "
                        "bind_all übersprungen",
                    )
            except Exception as _e:
                _logger.warning(
                    "🔍 [DEBUG-PROBES] bind_all fehlgeschlagen: %s",
                    _e,
                )

            try:
                _lang_var = getattr(self, "lang_var", None)
                if _lang_var is None:
                    _logger.warning(
                        "🔍 [DEBUG-PROBES] lang_var ist None – Tracker "
                        "nicht installiert",
                    )
                else:

                    def _on_lang_var_write(*args, **kwargs) -> None:
                        try:
                            _val = _lang_var.get()
                            _logger.warning(
                                "🔍 [LANG-VAR] geschrieben: %r (args=%r)",
                                _val,
                                args,
                            )
                        except Exception as _e:
                            _logger.warning(
                                "🔍 [LANG-VAR] Fehler: %s",
                                _e,
                            )

                    _lang_var.trace_add("write", _on_lang_var_write)
                    try:
                        _trace_info = _lang_var.trace_info()
                        _logger.warning(
                            "🔍 [DEBUG-PROBES] lang_var-Tracker aktiv "
                            "(var=%s, traces=%r, trace_count=%d)",
                            str(_lang_var)[:40],
                            _trace_info,
                            len(_trace_info) if _trace_info else 0,
                        )
                    except Exception as _trace_exc:
                        _logger.warning(
                            "🔍 [DEBUG-PROBES] trace_info() fehlgeschlagen: %s",
                            _trace_exc,
                        )
            except Exception as _e:
                _logger.warning(
                    "🔍 [DEBUG-PROBES] lang_var-Tracker fehlgeschlagen: %s",
                    _e,
                )

            try:
                _combo = getattr(self, "lang_combo", None)
                if _combo is None:
                    _logger.warning(
                        "🔍 [DEBUG-PROBES] lang_combo ist None – "
                        "Combobox-Probe nicht installiert",
                    )
                else:
                    try:
                        _vals = _combo.cget("values")
                        _vals_list = list(_vals) if _vals else []
                        _vals_count = len(_vals_list)
                        _vals_preview = _vals_list[:10]
                        _logger.warning(
                            "🔍 [COMBO-VALUES] count=%d, first10=%r",
                            _vals_count,
                            _vals_preview,
                        )
                        _seps = [
                            v
                            for v in _vals_list
                            if isinstance(v, str) and v.startswith("---")
                        ]
                        _logger.warning(
                            "🔍 [COMBO-VALUES] Trennzeichen gefunden: %r",
                            _seps,
                        )
                        _suspicious = []
                        for v in _vals_list[:20]:
                            if (isinstance(v, str) and v != v.strip()) or (
                                isinstance(v, str)
                                and any(c in v for c in ("\u200b", "\ufeff", "\u00a0"))
                            ):
                                _suspicious.append(v)
                        if _suspicious:
                            _logger.warning(
                                "🔍 [COMBO-VALUES] Verdächtige Werte "
                                "(whitespace/unsichtbar): %r",
                                _suspicious,
                            )
                    except Exception as _ve:
                        _logger.warning(
                            "🔍 [COMBO-VALUES] Fehler beim Lesen der Werte: %s",
                            _ve,
                        )

                    def _on_combo_event(event: tk.Event) -> None:
                        try:
                            _var_val = None
                            try:
                                if _combo is not None and hasattr(
                                    _combo,
                                    "get",
                                ):
                                    _var_val = _combo.get()
                            except Exception:
                                pass

                            _current_idx = None
                            try:
                                if _combo is not None and hasattr(
                                    _combo,
                                    "current",
                                ):
                                    _current_idx = _combo.current()
                            except Exception:
                                pass

                            _logger.warning(
                                "🔍 [COMBO-EVENT-LANG] gefeuert: "
                                "lang_var=%r, combo.get()=%r, "
                                "combo.current()=%r, target_language=%r",
                                (
                                    self.lang_var.get()
                                    if getattr(self, "lang_var", None)
                                    else None
                                ),
                                _var_val,
                                _current_idx,
                                getattr(
                                    self,
                                    "target_language",
                                    None,
                                ),
                            )
                        except Exception as _e:
                            _logger.warning(
                                "🔍 [COMBO-EVENT-LANG] Fehler: %s",
                                _e,
                            )

                    _combo.bind(
                        "<<ComboboxSelected>>",
                        _on_combo_event,
                        add="+",
                    )

                    try:
                        _bindings = _combo.bind()
                        _logger.warning(
                            "🔍 [DEBUG-PROBES] Combobox-Bindings: %r",
                            _bindings,
                        )
                    except Exception as _be:
                        _logger.warning(
                            "🔍 [DEBUG-PROBES] Binding-Check fehlgeschlagen: %s",
                            _be,
                        )

                    _logger.warning(
                        "🔍 [DEBUG-PROBES] Combobox-Event-Handler aktiv (widget=%s)",
                        str(_combo)[:60],
                    )
            except Exception as _e:
                _logger.warning(
                    "🔍 [DEBUG-PROBES] Combobox-Probe fehlgeschlagen: %s",
                    _e,
                )

            _logger.warning(
                "🔍 [DEBUG-PROBES] Alle Probes installiert — "
                "starte GUI-Interaktion für Diagnose",
            )

        self._is_initialized = True

        if success:
            self._finalization_done = True

        if debug_level >= 3:
            _logger.debug(
                "◀️ _finalize_init: EXIT (success=%s, elapsed=%.1f ms, guard=%s)",
                success,
                elapsed_ms,
                "gesetzt" if success else "nicht gesetzt (Retry erlaubt)",
            )

        return success

    def _on_transcription_text(self, text: str) -> None:
        """Callback vom AudioProcessor – wird bei jeder neuen Transkription
        aufgerufen und legt den Text in die ``text_queue``.
        """
        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        call_id = f"TX-{int(time.time() * 1000) % 100000:05d}"

        if debug_level >= 2:
            logger.debug(
                f"[{call_id}] _on_transcription_text ENTRY: "
                f"text type={type(text).__name__}, "
                f"thread={threading.current_thread().name}",
            )

        start = None
        end = None
        language = None
        confidence = None

        try:
            if text is None:
                if debug_level >= 3:
                    logger.debug(f"[{call_id}] text is None – überspringe")
                return

            if isinstance(text, str):
                raw_text = text
            elif hasattr(text, "text") and isinstance(text.text, str):
                raw_text = text.text
                try:
                    _s = getattr(text, "start", None)
                    start = float(_s) if _s is not None else None
                except (TypeError, ValueError):
                    start = None
                try:
                    _e = getattr(text, "end", None)
                    end = float(_e) if _e is not None else None
                except (TypeError, ValueError):
                    end = None
                language = getattr(text, "language", None)
                try:
                    _c = getattr(text, "confidence", None)
                    confidence = float(_c) if _c is not None else None
                except (TypeError, ValueError):
                    confidence = None
            else:
                try:
                    raw_text = str(text)
                except Exception as e:
                    logger.error(f"[{call_id}] Konvertierung fehlgeschlagen: {e}")
                    return

            cleaned = raw_text.strip()
            if not cleaned:
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] Text nach Bereinigung leer – überspringe"
                    )
                return

            if debug_level >= 3:
                logger.debug(
                    f"[{call_id}] Normalisierter Text: '{cleaned[:80]}...' "
                    f"(Länge={len(cleaned)}, start={start}, end={end})"
                )

        except Exception as e:
            logger.exception(f"[{call_id}] Fehler beim Normalisieren: {e}")
            return

        try:
            _filter_fn = getattr(self, "_filter_blacklist_text", None)
            if callable(_filter_fn):
                _lang_code = language if isinstance(language, str) else "unknown"
                _filtered = _filter_fn(cleaned, _lang_code)

                if _filtered is None:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] 🚫 Blacklist filter removed text "
                            f"(lang={_lang_code}): {cleaned[:80]!r}",
                        )
                    return

                if _filtered != cleaned:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] ✂️ Blacklist filter cleaned text "
                            f"(lang={_lang_code}): "
                            f"{cleaned[:40]!r} → {_filtered[:40]!r}",
                        )
                    cleaned = _filtered

        except Exception as _bl_exc:
            logger.warning(
                f"[{call_id}] Blacklist-Filter Fehler (ignoriert): {_bl_exc}",
            )

        if getattr(self, "_shutting_down", False):
            if debug_level >= 3:
                logger.debug(f"[{call_id}] Shutdown aktiv – Text verworfen")
            return

        try:
            _dedup_ttl = float(os.getenv("DW_TEXT_DEDUP_TTL", "15.0"))
        except (TypeError, ValueError):
            _dedup_ttl = 15.0

        if _dedup_ttl > 0:
            try:
                _dedup_key = (
                    cleaned,
                    round(start, 2) if start is not None else None,
                    round(end, 2) if end is not None else None,
                )

                if not hasattr(self, "_tx_text_dedup_cache"):
                    self._tx_text_dedup_cache: dict = {}
                    self._tx_text_dedup_lock = threading.Lock()

                _now_ts = time.monotonic()
                _is_duplicate = False
                _last_seen = None

                with self._tx_text_dedup_lock:
                    if len(self._tx_text_dedup_cache) > 200:
                        _expired = [
                            k
                            for k, ts in self._tx_text_dedup_cache.items()
                            if _now_ts - ts > _dedup_ttl
                        ]
                        for k in _expired:
                            self._tx_text_dedup_cache.pop(k, None)

                    _last_seen = self._tx_text_dedup_cache.get(_dedup_key)
                    if _last_seen is not None and _now_ts - _last_seen < _dedup_ttl:
                        _is_duplicate = True
                    else:
                        self._tx_text_dedup_cache[_dedup_key] = _now_ts

                if _is_duplicate:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] TX-Dedup skip: "
                            f"Text bereits vor {_now_ts - _last_seen:.2f}s "
                            f"eingefügt "
                            f"(len={len(cleaned)}, start={start}, end={end})"
                        )
                    return

            except Exception as _de:
                if debug_level >= 2:
                    logger.debug(
                        f"[{call_id}] Dedup-Check fehlgeschlagen "
                        f"({type(_de).__name__}: {_de}) – fahre fort"
                    )

        try:
            payload = {
                "text": cleaned or "",
                "start": start,
                "end": end,
                "language": language,
                "confidence": confidence,
            }
        except Exception as _pe:
            logger.error(f"[{call_id}] Payload-Aufbau fehlgeschlagen: {_pe}")
            payload = {"text": str(cleaned) if cleaned else ""}

        if debug_level >= 4:
            logger.debug(
                f"[{call_id}] TX-DEBUG payload built: "
                f"text_len={len(payload.get('text', ''))}, "
                f"start={payload.get('start')}, "
                f"end={payload.get('end')}, "
                f"text_queue_set="
                f"{hasattr(self, 'text_queue') and self.text_queue is not None}"
            )

        queue_success = False
        update_type = getattr(self, "UPDATE_TYPE_TRANSCRIPT", "transcript")

        if hasattr(self, "text_queue") and self.text_queue is not None:
            try:
                self.text_queue.put_nowait((update_type, payload))
                queue_success = True

                if debug_level >= 3:
                    try:
                        qsize = self.text_queue.qsize()
                    except Exception:
                        qsize = -1
                    logger.debug(
                        f"[{call_id}] Payload in text_queue gelegt "
                        f"(Queue-Größe: {qsize}, start={start}, end={end})"
                    )

            except queue.Full:
                logger.warning(
                    f"[{call_id}] text_queue voll – verwerfe älteste Einträge"
                )
                dropped = 0
                try:
                    for _ in range(10):
                        try:
                            self.text_queue.get_nowait()
                            if hasattr(self.text_queue, "task_done"):
                                with contextlib.suppress(ValueError):
                                    self.text_queue.task_done()
                            dropped += 1
                        except queue.Empty:
                            break

                    self.text_queue.put_nowait((update_type, payload))
                    queue_success = True

                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] Payload nach Verwerfen von "
                            f"{dropped} Elementen eingefügt"
                        )
                except Exception as e:
                    logger.error(
                        f"[{call_id}] Auch nach Verwerfen von {dropped} "
                        f"Elementen fehlgeschlagen: {e}"
                    )

            except Exception as e:
                logger.error(f"[{call_id}] Fehler beim Einfügen in text_queue: {e}")
        else:
            if debug_level >= 2:
                logger.debug(f"[{call_id}] text_queue nicht verfügbar – Fallback")

        if not queue_success:
            self._fallback_append_text(cleaned, call_id, debug_level)

        if debug_level >= 4:
            logger.debug(
                f"[{call_id}] _on_transcription_text EXIT "
                f"(queue_success={queue_success})"
            )

    def _fallback_append_text(
        self,
        cleaned: str,
        call_id: str,
        debug_level: int,
    ) -> None:
        """Fallback für Text-Anzeige, wenn ``text_queue`` nicht verfügbar."""
        logger = logging.getLogger("dragon")
        if debug_level >= 2:
            logger.debug(f"[{call_id}] Verwende Fallback für Textanzeige")

        is_main_thread = threading.current_thread() is threading.main_thread()

        if is_main_thread:
            try:
                self._append_transcription(cleaned)
                if debug_level >= 3:
                    logger.debug(f"[{call_id}] Text direkt angehängt (Hauptthread)")
            except Exception as e:
                logger.error(f"[{call_id}] Fehler beim direkten Anhängen: {e}")
            return

        try:
            root = getattr(self, "root", None)
            if root is not None:
                root.after(0, lambda: self._append_transcription(cleaned))
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] Text über after() im Hauptthread angefordert"
                    )
                return

            gui_queue = getattr(self, "gui_queue", None)
            if gui_queue is not None:
                gui_queue.put_nowait(("append_transcription", cleaned))
                if debug_level >= 3:
                    logger.debug(f"[{call_id}] Text über gui_queue gesendet")
                return

            logger.warning(
                f"[{call_id}] Keine Queue oder root verfügbar – "
                f"Text verworfen: {cleaned[:50]}..."
            )
        except Exception as e:
            logger.error(f"[{call_id}] Fehler beim Fallback: {e}")

    def _process_text_queue(self) -> None:
        """DEPRECATED v2.0 – wird nicht mehr verwendet."""
        return

    def _normalize_translation_result(
        self, result, call_id: str = "N/A"
    ) -> dict | None:
        """Normalisiert verschiedene Eingabetypen zu einem einheitlichen Dictionary.
        Unterstützt: TranslationResult-Objekte, Dicts, Strings, None.
        Gibt ein Dictionary mit den Schlüsseln 'text', 'source_lang', 'target_lang',
        'start', 'confidence' zurück oder None bei Fehlern/leeren Texten.

        Args:
            result: Das zu normalisierende Ergebnis.
            call_id: Eindeutige ID für Debug-Logs.

        Returns:
            dict | None: Normalisiertes Dictionary oder None.

        """
        import logging
        import threading

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 3:
            logger.debug(
                f"[{call_id}] _normalize_translation_result ENTRY: "
                f"result type={type(result).__name__}, thread={threading.current_thread().name}",
            )

        try:
            if result is None:
                if debug_level >= 3:
                    logger.debug(f"[{call_id}] result is None – gebe None zurück")
                return None

            if hasattr(result, "translated"):
                text = getattr(result, "translated", "")
                if text is None:
                    text = ""
                text = str(text).strip()
                if not text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] TranslationResult hat leeren Text – gebe None zurück"
                        )
                    return None

                norm_dict = {
                    "text": text,
                    "source_lang": getattr(result, "source_lang", "auto"),
                    "target_lang": getattr(
                        result, "target_lang", getattr(self, "target_language", "de")
                    ),
                    "start": getattr(result, "start", None),
                    "confidence": getattr(result, "confidence", 0.0),
                }
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] TranslationResult normalisiert: "
                        f"text='{text[:50]}...', target_lang={norm_dict['target_lang']}",
                    )
                return norm_dict

            if isinstance(result, dict):
                text = result.get("translated", result.get("text", ""))
                if text is None:
                    text = ""
                text = str(text).strip()
                if not text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] Dict hat leeren Text – gebe None zurück"
                        )
                    return None

                norm_dict = {
                    "text": text,
                    "source_lang": result.get("source_lang", "auto"),
                    "target_lang": result.get(
                        "target_lang", getattr(self, "target_language", "de")
                    ),
                    "start": result.get("start", None),
                    "confidence": result.get("confidence", 0.0),
                }
                if debug_level >= 2:
                    logger.debug(f"[{call_id}] Dict normalisiert: '{text[:50]}...'")
                return norm_dict

            if isinstance(result, str):
                text = result.strip()
                if not text:
                    if debug_level >= 3:
                        logger.debug(f"[{call_id}] String ist leer – gebe None zurück")
                    return None

                if debug_level >= 2:
                    logger.warning(
                        f"[{call_id}] String als TranslationResult interpretiert: '{text[:50]}...'",
                    )
                return {
                    "text": text,
                    "source_lang": "auto",
                    "target_lang": getattr(self, "target_language", "de"),
                    "start": None,
                    "confidence": 0.0,
                }

            try:
                text = str(result).strip()
                if not text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] Konvertierung ergab leeren String – gebe None zurück"
                        )
                    return None
                if debug_level >= 2:
                    logger.warning(
                        f"[{call_id}] Unbekannter Typ {type(result).__name__} – "
                        f"konvertiert zu String: '{text[:50]}...'",
                    )
                return {
                    "text": text,
                    "source_lang": "auto",
                    "target_lang": getattr(self, "target_language", "de"),
                    "start": None,
                    "confidence": 0.0,
                }
            except Exception as e:
                logger.error(f"[{call_id}] Konvertierung fehlgeschlagen: {e}")
                return None

        except Exception as e:
            logger.exception(f"[{call_id}] Fehler beim Normalisieren: {e}")
            return None

    def _schedule_next_queue_processing(self) -> None:
        """DEPRECATED v2.0 – kein Rescheduling des alten Consumers mehr."""
        return

    def _calc_next_interval(self, qsize: int, state: dict) -> int:
        """Berechnet adaptives Intervall für nächsten Durchlauf in Millisekunden.
        Berücksichtigt Queue-Größe und Inaktivität.
        """
        import time

        if qsize > 1000:
            return 20
        if qsize > 500:
            return 30
        if qsize > 100:
            return 40
        if qsize > 0:
            return 50

        idle_since = state.get("idle_since", 0.0)
        if idle_since > 0 and (time.time() - idle_since) > 5.0:
            return 200
        return 50

    def _calc_batch_size(self, qsize: int) -> int:
        """Berechnet die maximale Anzahl von Items, die in einem Durchlauf verarbeitet werden.
        Adaptiv basierend auf Queue-Last.
        """
        if qsize <= 0:
            return 20
        if qsize < 100:
            return 30
        if qsize < 500:
            return 50
        if qsize < 2000:
            return 80
        return 120

    def _calc_max_duration(self, qsize: int) -> float:
        """Berechnet die maximale Dauer (in Sekunden) für einen Batch-Verarbeitungsdurchlauf.
        Adaptiv basierend auf Queue-Last.
        """
        if qsize <= 0:
            return 0.05
        if qsize < 100:
            return 0.10
        if qsize < 500:
            return 0.15
        if qsize < 2000:
            return 0.25
        return 0.40

    def _schedule_next(self, root: tk.Tk, interval: int) -> None:
        """Plant den nächsten Durchlauf der GUI-Queue-Verarbeitung mit `after`."""
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if getattr(self, "_shutting_down", False):
            if debug_level >= 4:
                logger.debug("[GUI-QUEUE] 🛑 Shutdown – keine weitere Planung")
            return

        if root is None:
            logger.warning("[GUI-QUEUE] root ist None – kann nicht planen")
            return

        interval = max(10, min(500, interval))

        try:
            root.after(interval, self._process_gui_queue_dynamic)
            if debug_level >= 5:
                _now = time.time()
                if _now - getattr(self, "_last_gui_queue_log", 0.0) >= 30.0:
                    logger.debug(
                        f"[GUI-QUEUE] 📅 Nächster Durchlauf in {interval}ms geplant",
                    )
                    self._last_gui_queue_log = _now

        except Exception as e:
            logger.error(f"[GUI-QUEUE] ❌ after-Planung fehlgeschlagen: {e}")

            try:
                root.after_idle(self._process_gui_queue_dynamic)
                if debug_level >= 3:
                    _now = time.time()
                    if _now - getattr(self, "_last_gui_queue_idle_log", 0.0) >= 30.0:
                        logger.debug(
                            "[GUI-QUEUE] 📅 Nächster Durchlauf via after_idle geplant",
                        )
                        self._last_gui_queue_idle_log = _now

            except Exception as e2:
                logger.critical(
                    f"[GUI-QUEUE] 💀 Auch after_idle fehlgeschlagen: {e2} – "
                    "GUI-Queue wird nicht mehr verarbeitet!",
                )

    def _gui_health_check(self, logger=None, debug_level=None) -> None:
        """Führt einen Health-Check der GUI-Queue durch.
        Bei Stau oder vielen Fehlern wird die Notfall-Wiederherstellung eingeleitet.
        """
        import logging
        import time

        if logger is None:
            logger = logging.getLogger("dragon")
        if debug_level is None:
            debug_level = getattr(self, "debug_level", 0)

        queue_obj = getattr(self, "gui_queue", None)
        if queue_obj is None:
            if debug_level >= 4:
                logger.debug("[GUI-QUEUE] Health-Check: gui_queue ist None")
            return

        try:
            qsize = queue_obj.qsize()
            state = getattr(self, "_gui_state", {})
            call_count = state.get("call_count", 0)
            last_call = state.get("last_call", 0)
            elapsed = time.time() - last_call if last_call else 0
            errors = state.get("consecutive_errors", 0)
            buffer_len = len(state.get("buffer", []))

            if debug_level >= 4:
                logger.debug(
                    f"[GUI-QUEUE] 💚 Health-Check: Queue={qsize}, "
                    f"Calls={call_count}, Idle={elapsed:.1f}s, "
                    f"Errors={errors}, Buffer={buffer_len}",
                )
            else:
                logger.debug(
                    f"[GUI-QUEUE] 💚 Health-Check: Queue={qsize}, "
                    f"Calls={call_count}, Idle={elapsed:.1f}s",
                )

            if qsize > 100 and elapsed > 5.0:
                logger.warning(
                    f"[GUI-QUEUE] ⚠️ Queue={qsize}, Idle={elapsed:.1f}s – "
                    "möglicher Stau! Leite Notfall-Wiederherstellung ein.",
                )
                if hasattr(self, "_emergency_recovery") and callable(
                    self._emergency_recovery,
                ):
                    self._emergency_recovery()
                else:
                    logger.error("[GUI-QUEUE] ❌ _emergency_recovery nicht verfügbar!")

            if errors >= 5:
                logger.warning(
                    f"[GUI-QUEUE] ⚠️ {errors} aufeinanderfolgende Fehler – "
                    "leite Notfall-Wiederherstellung ein.",
                )
                if hasattr(self, "_emergency_recovery") and callable(
                    self._emergency_recovery,
                ):
                    self._emergency_recovery()
                else:
                    logger.error("[GUI-QUEUE] ❌ _emergency_recovery nicht verfügbar!")

            if buffer_len > 50 and elapsed > 2.0:
                logger.warning(
                    f"[GUI-QUEUE] ⚠️ Buffer={buffer_len}, Idle={elapsed:.1f}s – "
                    "erzwinge Flush.",
                )
                state["buffer_last_flush"] = time.time() - state.get(
                    "buffer_max_age",
                    0.3,
                )

        except Exception as e:
            if debug_level >= 4:
                logger.debug(f"[GUI-QUEUE] Health-Check fehlgeschlagen: {e}")
            elif debug_level >= 3:
                logger.warning(f"[GUI-QUEUE] Health-Check Fehler: {e}")

    def _emergency_recovery(self) -> None:
        """Führt eine Notfall-Wiederherstellung durch, wenn die GUI-Queue blockiert.
        Leert Buffer und Queue, setzt Fehlerzähler zurück und startet die Verarbeitung neu.
        """
        import contextlib
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        logger.warning("[GUI-QUEUE] 🚑 Notfall-Wiederherstellung wird eingeleitet")

        try:
            state = getattr(self, "_gui_state", {})
            buffer_len = len(state.get("buffer", []))

            if buffer_len > 0:
                logger.warning(f"[GUI-QUEUE] Leere Buffer ({buffer_len} Items)")
                state["buffer"] = []
                state["buffer_last_flush"] = time.time()
                state["consecutive_errors"] = 0
                state["is_running"] = False
            queue_obj = getattr(self, "gui_queue", None)
            drained = 0
            if queue_obj is not None:
                try:
                    while not queue_obj.empty():
                        with contextlib.suppress(Exception):
                            queue_obj.get_nowait()
                            drained += 1
                    if drained > 0:
                        logger.warning(
                            f"[GUI-QUEUE] {drained} Items aus Queue entfernt (Notfall)",
                        )
                except Exception as e:
                    logger.error(f"[GUI-QUEUE] Fehler beim Leeren der Queue: {e}")

            state["consecutive_errors"] = 0
            state["is_running"] = False

            root = getattr(self, "root", None) or getattr(self, "_root", None)
            if root is not None:
                try:
                    root.after(10, self._process_gui_queue_dynamic)
                    if debug_level >= 3:
                        logger.debug(
                            "[GUI-QUEUE] Verarbeitung nach Notfall-Wiederherstellung "
                            "neu gestartet",
                        )
                except Exception as e:
                    logger.error(
                        f"[GUI-QUEUE] Neustart der Verarbeitung fehlgeschlagen: {e}",
                    )
            else:
                logger.warning(
                    "[GUI-QUEUE] Kein root-Objekt – Verarbeitung nicht neu gestartet",
                )

            if drained == 0 and buffer_len == 0:
                logger.debug(
                    "[GUI-QUEUE] ℹ️ Notfall-Wiederherstellung: Keine Daten zu bereinigen",
                )
            else:
                logger.info(
                    f"[GUI-QUEUE] ✅ Notfall-Wiederherstellung abgeschlossen "
                    f"(Queue: {drained} entfernt, Buffer: {buffer_len} geleert)",
                )

        except Exception as e:
            logger.error(
                f"[GUI-QUEUE] ❌ Notfall-Wiederherstellung fehlgeschlagen: {e}",
                exc_info=(debug_level >= 4),
            )

    def _process_gui_queue_dynamic(self) -> None:
        """ULTIMATIVE SUPERVERSION – Verarbeitet die GUI-Queue mit maximaler Effizienz,
        minimalem Overhead und garantierter Tkinter-Kompatibilität.
        """
        import contextlib
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if getattr(self, "_shutting_down", False):
            if debug_level >= 4:
                logger.debug("[GUI-QUEUE] 🛑 Shutdown aktiv – beende Verarbeitung")
            return

        root = getattr(self, "root", None) or getattr(self, "_root", None)
        if root is None:
            logger.error("[GUI-QUEUE] ❌ Kein Root-Objekt – GUI-Updates verworfen")
            return

        if not hasattr(self, "_gui_state"):
            self._gui_state = {
                "last_call": time.time(),
                "call_count": 0,
                "is_running": False,
                "running_since": 0.0,
                "idle_since": 0.0,
                "consecutive_errors": 0,
                "last_health_check": time.time(),
                "health_check_interval": 30.0,
                "updates_processed": 0,
                "buffer": [],
                "buffer_last_flush": time.time(),
                "buffer_max_age": 0.3,
            }

        state = self._gui_state
        current_time = time.time()
        state["call_count"] += 1
        state["last_call"] = current_time

        if state["is_running"]:
            if current_time - state["running_since"] > 2.0:
                logger.warning(
                    f"[GUI-QUEUE] ⚠️ Vorheriger Durchlauf hängt seit "
                    f"{current_time - state['running_since']:.1f}s – setze Flag zurück",
                )
                state["is_running"] = False
            else:
                interval = self._calc_next_interval(0, state)
                self._schedule_next(root, interval)
                return

        state["is_running"] = True
        state["running_since"] = current_time

        try:
            queue_obj = getattr(self, "gui_queue", None)
            if queue_obj is None:
                logger.warning("[GUI-QUEUE] gui_queue ist None – überspringe")
                return

            qsize = -1
            with contextlib.suppress(Exception):
                qsize = queue_obj.qsize()

            if (
                current_time - state["last_health_check"]
                > state["health_check_interval"]
            ):
                state["last_health_check"] = current_time
                self._gui_health_check(logger, debug_level)

            if state["consecutive_errors"] >= 10:
                logger.critical(
                    "[GUI-QUEUE] 💥 Zu viele Fehler – leite Notfall-Wiederherstellung ein",
                )
                self._emergency_recovery()
                state["consecutive_errors"] = 0

            max_items = self._calc_batch_size(qsize)
            max_duration = self._calc_max_duration(qsize)

            lock = getattr(self, "_gui_queue_lock", None)
            use_lock = lock is not None
            items_processed = 0
            start = time.time()

            while items_processed < max_items and (time.time() - start) < max_duration:
                try:
                    if use_lock:
                        with lock:
                            if queue_obj.empty():
                                break
                            item = queue_obj.get_nowait()
                    else:
                        if queue_obj.empty():
                            break
                        item = queue_obj.get_nowait()

                    state["buffer"].append(item)
                    items_processed += 1
                except Exception:
                    break

            buffer_age = time.time() - state["buffer_last_flush"]
            flush_needed = (
                len(state["buffer"]) >= 20
                or buffer_age >= state["buffer_max_age"]
                or (qsize == 0 and len(state["buffer"]) > 0)
                or (items_processed == 0 and len(state["buffer"]) > 0)
            )

            if flush_needed and len(state["buffer"]) > 0:
                batch = state["buffer"]
                state["buffer"] = []
                state["buffer_last_flush"] = time.time()

                self._process_gui_batch(batch)
                state["updates_processed"] += len(batch)
                state["idle_since"] = 0.0
                state["consecutive_errors"] = 0
            elif items_processed == 0 and state["idle_since"] == 0.0:
                state["idle_since"] = current_time

            if items_processed > 0 and state["call_count"] % 5 == 0:
                with contextlib.suppress(Exception):
                    root.update_idletasks()

            if qsize > 1000:
                logger.warning(
                    f"[GUI-QUEUE] ⚠️ Queue überläuft ({qsize} Items) – "
                    "erzwinge sofortige Verarbeitung",
                )
                with contextlib.suppress(Exception):
                    root.after(50, self._process_gui_queue_dynamic)
                    return

        except Exception as e:
            state["consecutive_errors"] += 1
            logger.error(
                f"[GUI-QUEUE] 💥 Unerwarteter Fehler: {e}",
                exc_info=(debug_level >= 4),
            )
        finally:
            state["is_running"] = False

            interval = self._calc_next_interval(qsize, state)
            self._schedule_next(root, interval)

            duration = time.time() - current_time
            if duration > 0.5 and debug_level >= 3:
                logger.warning(f"[GUI-QUEUE] ⏱️ Verarbeitung dauerte {duration:.2f}s")

    def _ensure_root_exists(self) -> bool:
        """Prüft sicher, ob root existiert und noch gültig ist."""
        try:
            return (
                hasattr(self, "root")
                and self.root is not None
                and self.root.winfo_exists()
            )
        except (tk.TclError, AttributeError, RuntimeError):
            return False

    def _finalize_exit_button(self) -> None:
        """Erstellt einen neuen Exit-Button, der garantiert _safe_exit_dialog aufruft.
        Ersetzt den von der StatusBar erstellten Button.
        """
        logger.debug("🔧 _finalize_exit_button: Starte Ersatz des Exit-Buttons")
        parent = None

        if hasattr(self, "exit_button") and self.exit_button:
            try:
                parent = self.exit_button.master
                logger.debug("📁 Parent von self.exit_button gefunden")
            except Exception:
                pass

        if parent is None and hasattr(self, "gui") and hasattr(self.gui, "exit_button"):
            try:
                parent = self.gui.exit_button.master
                logger.debug("📁 Parent von self.gui.exit_button gefunden")
            except Exception:
                pass

        if parent is None:
            logger.warning(
                "⚠️ Kein Parent-Container für Exit-Button gefunden – überspringe",
            )
            return
        try:
            if hasattr(self, "exit_button") and self.exit_button:
                self.exit_button.destroy()
                logger.debug("🗑️ alter self.exit_button zerstört")
        except Exception as e:
            logger.debug(f"Ignored exception destroying self.exit_button: {e}")

        try:
            if hasattr(self, "gui") and hasattr(self.gui, "exit_button"):
                self.gui.exit_button.destroy()
                logger.debug("🗑️ alter self.gui.exit_button zerstört")
        except Exception as e:
            logger.debug(f"Ignored exception destroying self.gui.exit_button: {e}")

        try:
            theme = getattr(self, "_theme", None)
            if theme is None:

                class FallbackTheme:
                    BG_PRIMARY = "#1e1e2e"
                    BG_SECONDARY = "#2d2d44"
                    BG_TERTIARY = "#3d3d5c"
                    BG_HOVER = "#4d4d6c"
                    TEXT_PRIMARY = "#cdd6f4"
                    TEXT_SECONDARY = "#a6adc8"
                    DRAGON_GREEN = "#a6e3a1"
                    DRAGON_GOLD = "#f7d44a"
                    WARNING = "#f9e2af"
                    ERROR = "#f38ba8"
                    SUCCESS = "#a6e3a1"
                    EXIT_BUTTON_BG = "#f38ba8"
                    EXIT_BUTTON_ACTIVE_BG = "#c82333"

                theme = FallbackTheme()

            exit_bg = getattr(theme, "EXIT_BUTTON_BG", theme.ERROR)
            exit_active_bg = getattr(theme, "EXIT_BUTTON_ACTIVE_BG", "#c82333")
            exit_fg = getattr(theme, "TEXT_PRIMARY", "#cdd6f4")
            font_small = getattr(Fonts, "SMALL", ("Segoe UI", 7))
            new_button = tk.Button(
                parent,
                text="⏻ EXIT",
                command=self._safe_exit_dialog,
                bg=exit_bg,
                fg=exit_fg,
                font=font_small,
                relief="flat",
                cursor="hand2",
                padx=12,
                pady=getattr(self, "PAD_Y_BUTTON", 3),
                activebackground=exit_active_bg,
                activeforeground=exit_fg,
                bd=0,
            )
            new_button.pack(side="left", padx=(12, 2))
            new_button._is_exit_button = True
            try:
                if hasattr(self, "_safe_tooltip") and callable(self._safe_tooltip):
                    self._safe_tooltip(new_button, "Programm beenden (Strg+Q)")
                elif "ToolTip" in globals():
                    ToolTip(new_button, "Programm beenden (Strg+Q)")
            except Exception as e:
                logger.debug(f"Tooltip nicht gesetzt: {e}")

            self.exit_button = new_button
            if hasattr(self, "gui"):
                self.gui.exit_button = new_button

            logger.info(
                "✅ NEUER Exit-Button erfolgreich erstellt und an _safe_exit_dialog gebunden",
            )

        except Exception as e:
            logger.exception(f"❌ Fehler beim Erstellen des neuen Exit-Buttons: {e}")

    def _init_verbose_print(self, msg: str) -> None:
        """Gibt bei DEBUG_LEVEL >= 3 eine Initialisierungsmeldung aus."""
        if self._init_verbose:
            print(f"🔍 {msg}")

    def _init_settings_and_managers(self) -> None:
        """Lädt Einstellungen, initialisiert TTS‑Manager und AdvancedSettings."""
        try:
            self.settings = AppSettings.load_from_file()
            logger.debug("✅ AppSettings geladen")
            self._show_initial_status("✅ Einstellungen geladen")
        except Exception as e:
            self._init_errors.append(f"Einstellungen konnten nicht geladen werden: {e}")
            self.settings = AppSettings()
            logger.warning("AppSettings-Fallback verwendet")
            self._show_initial_status("⚠️ Einstellungen-Fallback")

        if IS_LINUX:
            if shutil.which("chromium"):
                self.settings.cookies_browser = "chromium"
                logger.debug("✅ Linux: Browser auf 'chromium' gesetzt")
            elif shutil.which("chrome"):
                self.settings.cookies_browser = "chrome"
                logger.debug("✅ Linux: Browser auf 'chrome' gesetzt")
            else:
                self.settings.cookies_browser = "firefox"
                logger.debug("✅ Linux: Browser auf 'firefox' gesetzt")

        try:
            self.advanced_settings = get_advanced_settings()
            PlatformUtils.set_allowed_dirs(self.advanced_settings.allowed_dirs)
            logger.debug("✅ AdvancedSettings geladen")
            self._show_initial_status("✅ Erweiterte Einstellungen geladen")
        except Exception as e:
            self._init_errors.append(
                f"Erweiterte Einstellungen konnten nicht geladen werden: {e}",
            )
            self.advanced_settings = AdvancedSettings()
            logger.warning("AdvancedSettings-Fallback verwendet")
            self._show_initial_status("⚠️ Erweiterte Einstellungen-Fallback")

        try:
            self.tts_manager: TTSManager | None = TTSManager(self.advanced_settings)
            logger.debug("✅ TTSManager initialisiert")
            self._show_initial_status("✅ Sprachausgabe bereit")
        except Exception as e:
            self._init_errors.append(f"TTS‑Manager konnte nicht gestartet werden: {e}")
            self.tts_manager = None
            logger.warning(f"TTSManager-Fehler: {e}")
            self._show_initial_status("⚠️ Sprachausgabe nicht verfügbar")

        try:
            self.advanced_settings.repair()
            logger.debug("✅ AdvancedSettings repariert")
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        self._show_cookie_notice = (
            not self.settings.cookies_notice_shown and self.settings.use_browser_cookies
        )

    def _init_app_context(self) -> None:
        """Initialisiert AppContext, EventBus und Theme."""
        try:
            self.app_context = AppContext()
            self.event_bus = self.app_context.event_bus
            self.current_theme = self.app_context.theme
            logger.debug("✅ AppContext, EventBus, Theme geladen")
            self._show_initial_status("✅ Theme geladen")
        except Exception as e:
            self._init_errors.append(
                f"AppContext konnte nicht initialisiert werden: {e}",
            )
            raise RuntimeError(
                f"AppContext konnte nicht initialisiert werden: {e}",
            ) from e

        self._init_verbose_print("  → Event‑Bus Scheduler wird später gebunden")

    def _init_tkinter_root(self) -> None:
        """Erstellt das Tkinter-Root-Fenster und richtet grundlegende GUI-Infrastruktur ein.
        """
        import os
        import signal
        import sys
        import threading
        import time
        import tkinter as tk
        import traceback

        try:
            self.root = tk.Tk()
            self.root.withdraw()
            logger.debug("✅ Tkinter‑Root erstellt (zuerst versteckt)")
            self._show_initial_status("✅ Fenster vorbereitet")
        except (tk.TclError, RuntimeError) as e:
            logger.critical(f"❌ Tkinter-Fehler beim Erstellen des Root-Fensters: {e}")
            raise RuntimeError(f"Tkinter Fehler: {e}") from e
        except Exception as e:
            logger.critical(
                f"❌ Unerwarteter Fehler beim Erstellen des Root-Fensters: {e}",
            )
            raise RuntimeError(f"Unerwarteter Fehler: {e}") from e

        def _tk_exception_handler(exc_type, exc_val, exc_tb):
            tb_lines = traceback.format_exception(exc_type, exc_val, exc_tb)
            full_tb = "".join(tb_lines)
            logger.error("Tkinter callback error:\n%s", full_tb)

            now = time.monotonic()
            last_time = getattr(self, "_last_tk_error_time", 0.0)
            if now - last_time < 60.0:
                if getattr(self, "debug_level", 0) >= 3:
                    logger.debug(
                        "Tk-Fehler unterdrückt (Rate-Limit 60s, "
                        "letzter Fehler vor %.1fs)",
                        now - last_time,
                    )
                return
            self._last_tk_error_time = now

            short_msg = f"{exc_type.__name__}: {exc_val}"
            if len(short_msg) > 500:
                short_msg = short_msg[:497] + "..."
            detail_msg = (
                f"Ein unbehandelter Fehler ist in der GUI aufgetreten:\n\n"
                f"{short_msg}\n\n"
                f"Der vollständige Traceback wurde in die Log‑Datei geschrieben.\n"
                f"Sie können den Fehler mit Strg+C in die Zwischenablage kopieren."
            )
            try:
                DarkMessageBox.showerror("GUI‑Fehler", detail_msg, parent=self.root)
                if self.root.winfo_exists():
                    self.root.clipboard_clear()
                    self.root.clipboard_append(full_tb)
            except Exception:
                logger.exception("Konnte GUI‑Fehlerdialog nicht anzeigen")

        self.root.report_callback_exception = _tk_exception_handler
        logger.debug("✅ Tkinter-Exception-Handler registriert")

        try:
            if threading.current_thread() is not threading.main_thread():
                logger.debug(
                    "⚠️ Nicht im Hauptthread – Signal-Handler übersprungen",
                )
            elif getattr(self, "_signal_handler_registered", False):
                logger.debug(
                    "ℹ️ Signal-Handler bereits registriert – überspringe",
                )
            else:
                self._pending_signal: int | None = None
                self._signal_lock = threading.Lock()
                self._signal_poll_active = True

                try:
                    _wd_timeout = float(
                        os.getenv("DW_SIGNAL_SHUTDOWN_TIMEOUT", "5.0"),
                    )
                except (TypeError, ValueError):
                    _wd_timeout = 5.0
                _wd_timeout = max(1.0, min(30.0, _wd_timeout))

                def _signal_handler(signum, frame):
                    """Setzt nur ein Flag – die Arbeit macht `_poll_signal`."""
                    with self._signal_lock:
                        self._pending_signal = signum

                def _force_exit_after_timeout() -> None:
                    """Notausgang: beendet den Prozess, wenn der Shutdown hängt."""
                    time.sleep(_wd_timeout)
                    with contextlib.suppress(Exception):
                        os.write(
                            2,
                            (
                                f"\n🚨 Signal-Shutdown-Timeout "
                                f"({_wd_timeout:.1f}s) – os._exit(0)\n"
                            ).encode("utf-8", errors="replace"),
                        )
                    os._exit(0)

                def _poll_signal() -> None:
                    """Prüft das Signal-Flag und leitet Shutdown im Main-Thread ein.

                    Wird alle 200 ms via `root.after()` aufgerufen. Nur so kann
                    `_direct_shutdown()` im Main-Thread laufen, was für Tk-
                    Operationen (quit/destroy) erforderlich ist.
                    """
                    if not getattr(self, "_signal_poll_active", True):
                        return

                    signum = None
                    with self._signal_lock:
                        if self._pending_signal is not None:
                            signum = self._pending_signal
                            self._pending_signal = None

                    if signum is not None:
                        logger.info(
                            f"📟 Signal {signum} empfangen – "
                            f"leite Shutdown ein (via Polling-Timer)..."
                        )
                        if hasattr(self, "_log_active_threads"):
                            try:
                                self._log_active_threads(f"SIG{signum}")
                            except Exception as e:
                                logger.debug(f"Thread-Dump fehlgeschlagen: {e}")

                        threading.Thread(
                            target=_force_exit_after_timeout,
                            daemon=True,
                            name="Signal-ShutdownWatchdog",
                        ).start()

                        if hasattr(self, "_direct_shutdown"):
                            try:
                                self._direct_shutdown()
                            except Exception as e:
                                logger.exception(
                                    f"_direct_shutdown via Signal fehlgeschlagen: {e}",
                                )
                                sys.exit(0)
                        else:
                            sys.exit(0)
                        return

                    try:
                        if self.root and self.root.winfo_exists():
                            self._signal_poll_id = self.root.after(
                                200,
                                _poll_signal,
                            )
                    except (tk.TclError, RuntimeError):
                        self._signal_poll_active = False

                signal.signal(signal.SIGINT, _signal_handler)
                signal.signal(signal.SIGTERM, _signal_handler)
                self._signal_handler_registered = True
                logger.debug(
                    "✅ Signal-Handler für SIGINT/SIGTERM registriert "
                    "(Polling-Modus, Intervall=200ms)",
                )

                try:
                    if self.root and self.root.winfo_exists():
                        self._signal_poll_id = self.root.after(200, _poll_signal)
                        logger.debug("✅ Signal-Polling-Timer gestartet")
                except Exception as e:
                    logger.debug(f"⚠️ Signal-Polling-Start fehlgeschlagen: {e}")
        except Exception as e:
            logger.debug(f"⚠️ Signal-Handler Registrierung fehlgeschlagen: {e}")

        if not hasattr(self, "_shutting_down"):
            self._shutting_down = False

        def on_root_close():
            """Blockiert das direkte Schließen; nur bei aktivem Shutdown erlaubt."""
            if getattr(self, "_shutting_down", False):
                logger.debug(
                    "on_root_close: Shutdown aktiv – Hauptfenster wird geschlossen",
                )
                self.root.destroy()
            else:
                logger.debug("on_root_close: Schließen blockiert – Exit-Dialog zeigen")
                try:
                    self.root.deiconify()
                    self.root.lift()
                    self.root.focus_force()
                except Exception as e:
                    logger.debug(f"on_root_close: Re-Fokus fehlgeschlagen: {e}")

        self.root.protocol("WM_DELETE_WINDOW", on_root_close)
        logger.debug(
            "✅ WM_DELETE_WINDOW gesetzt (blockiert bei _shutting_down=False)",
        )

        original_quit = self.root.quit
        original_destroy = self.root.destroy

        def _refocus_main_window() -> None:
            """Holt das Hauptfenster in den Vordergrund (best-effort)."""
            with contextlib.suppress(Exception):
                self.root.deiconify()
                self.root.lift()
                self.root.focus_force()

        def patched_quit():
            """Blockiert root.quit() außer bei aktivem Shutdown."""
            try:
                if getattr(self, "_shutting_down", False):
                    logger.debug("patched_quit: Shutdown aktiv – führe quit aus")
                    original_quit()
                    return

                if not self.root or not self.root.winfo_exists():
                    logger.debug(
                        "patched_quit: root existiert nicht – führe quit direkt aus",
                    )
                    original_quit()
                    return

                logger.debug("patched_quit: blockiert (kein aktiver Shutdown)")
                _refocus_main_window()
            except Exception as e:
                logger.error(
                    f"patched_quit: Fehler – delegiere an original_quit: {e}",
                )
                with contextlib.suppress(Exception):
                    original_quit()

        def patched_destroy():
            """Blockiert root.destroy() außer bei aktivem Shutdown."""
            try:
                if getattr(self, "_shutting_down", False):
                    logger.debug("patched_destroy: Shutdown aktiv – führe destroy aus")
                    original_destroy()
                    return

                if not self.root or not self.root.winfo_exists():
                    logger.debug(
                        "patched_destroy: root existiert nicht – führe destroy direkt aus",
                    )
                    original_destroy()
                    return

                logger.debug("patched_destroy: blockiert (kein aktiver Shutdown)")
                _refocus_main_window()
            except Exception as e:
                logger.error(
                    f"patched_destroy: Fehler – delegiere an original_destroy: {e}",
                )
                with contextlib.suppress(Exception):
                    original_destroy()

        self.root.quit = patched_quit
        self.root.destroy = patched_destroy
        logger.debug(
            "✅ root.quit() und root.destroy() gepatcht "
            "(blockiert außer bei aktivem Shutdown)",
        )

        try:
            self.root.title(
                "🐉 Dragon Whisperer"
                if not self.demo_mode
                else "🐉 Dragon Whisperer (DEMO MODE)",
            )
            logger.debug(f"✅ Fenstertitel gesetzt (demo_mode={self.demo_mode})")
        except Exception as e:
            logger.warning(f"⚠️ Fenstertitel konnte nicht gesetzt werden: {e}")

        try:
            if not hasattr(self, "gui_queue") or self.gui_queue is None:
                self.gui_queue = queue.Queue(maxsize=200)
                logger.debug("✅ GUI‑Queue erstellt")
            if (
                not hasattr(self, "_text_update_queue")
                or self._text_update_queue is None
            ):
                self._text_update_queue = queue.Queue(maxsize=150)
                logger.debug("✅ Text‑Update‑Queue erstellt")
        except Exception as e:
            logger.warning(f"⚠️ Queue-Initialisierung fehlgeschlagen: {e}")
            with contextlib.suppress(Exception):
                if not hasattr(self, "gui_queue") or self.gui_queue is None:
                    self.gui_queue = DummyQueue(maxsize=200)
                if (
                    not hasattr(self, "_text_update_queue")
                    or self._text_update_queue is None
                ):
                    self._text_update_queue = DummyQueue(maxsize=150)
                logger.debug("✅ DummyQueues als Fallback erstellt")

        try:
            if hasattr(self, "event_bus") and self.event_bus is not None:
                self.event_bus.set_scheduler(self.root.after)
                logger.debug("✅ Event‑Bus Scheduler gebunden")
            else:
                logger.warning(
                    "⚠️ Event-Bus nicht verfügbar – Scheduler nicht gebunden",
                )
        except Exception as e:
            logger.warning(f"⚠️ Event-Bus Scheduler-Bindung fehlgeschlagen: {e}")

        if not hasattr(self, "performance_monitor") or self.performance_monitor is None:
            self.performance_monitor = SimplePerformanceTracker()
            logger.debug("✅ PerformanceMonitor initialisiert")

        logger.debug("✅ _init_tkinter_root() erfolgreich abgeschlossen")
        self._show_initial_status("✅ GUI-Infrastruktur bereit")

    def _init_queues_and_extractor(self) -> None:
        """Initialisiert StreamInfoExtractor, stellt die GUI-Queues sicher und gibt sie an den Controller weiter.
        Führt automatische Modellauswahl durch, falls eine TranscriptionEngine verfügbar ist.
        """
        if not hasattr(self, "performance_monitor") or self.performance_monitor is None:
            self.performance_monitor = SimplePerformanceTracker()
        self._last_text_queue_size = 0

        if not hasattr(self, "gui_queue") or self.gui_queue is None:
            import queue

            self.gui_queue = queue.Queue(maxsize=5000)
            logger.debug("[GUI] GUI-Queue neu erstellt (maxsize=5000)")
        else:
            logger.debug(
                f"[GUI] GUI-Queue bereits vorhanden (maxsize={getattr(self.gui_queue, 'maxsize', 'unbekannt')})",
            )

        if not hasattr(self, "text_queue") or self.text_queue is None:
            import queue

            self.text_queue = queue.Queue(maxsize=2000)
            logger.debug("[GUI] Text-Queue neu erstellt (maxsize=2000)")
        else:
            logger.debug(
                f"[GUI] Text-Queue bereits vorhanden (maxsize={getattr(self.text_queue, 'maxsize', 'unbekannt')})",
            )

        if hasattr(self, "controller") and self.controller is not None:
            if hasattr(self.controller, "gui_queue"):
                self.controller.gui_queue = self.gui_queue
            if hasattr(self.controller, "text_queue"):
                self.controller.text_queue = self.text_queue
            if (
                hasattr(self.controller, "audio_processor")
                and self.controller.audio_processor is not None
            ):
                if hasattr(self.controller.audio_processor, "gui_queue"):
                    self.controller.audio_processor.gui_queue = self.gui_queue
                if hasattr(self.controller.audio_processor, "text_queue"):
                    self.controller.audio_processor.text_queue = self.text_queue
            logger.debug("[GUI] Queues an Controller und AudioProcessor übergeben")
        else:
            logger.warning(
                "[GUI] Controller nicht vorhanden – Queues konnten nicht übergeben werden",
            )

        try:
            if (
                not hasattr(self, "stream_info_extractor")
                or self.stream_info_extractor is None
            ):
                self.stream_info_extractor = StreamInfoExtractor()

            self.stream_info_extractor.use_browser_cookies = getattr(
                self.settings,
                "use_browser_cookies",
                True,
            )
            browser = getattr(self.settings, "browser", None)
            if browser and browser != "auto":
                self.stream_info_extractor.cookies_browser = browser
            elif IS_LINUX:
                if shutil.which("chromium"):
                    self.stream_info_extractor.cookies_browser = "chromium"
                elif shutil.which("chrome"):
                    self.stream_info_extractor.cookies_browser = "chrome"
                else:
                    self.stream_info_extractor.cookies_browser = "firefox"
            else:
                self.stream_info_extractor.cookies_browser = "firefox"

            self.stream_info_extractor.proxy_enabled = getattr(
                self.advanced_settings,
                "proxy_enabled",
                False,
            )
            self.stream_info_extractor.proxy = getattr(
                self.advanced_settings,
                "proxy_url",
                "",
            )

            logger.debug("✅ StreamInfoExtractor initialisiert und konfiguriert")
        except Exception as e:
            logger.warning(f"StreamInfoExtractor-Fehler: {e}")

            self.stream_info_extractor = StreamInfoExtractor()
            self.stream_info_extractor.use_browser_cookies = getattr(
                self.settings,
                "use_browser_cookies",
                True,
            )
            self.stream_info_extractor.cookies_browser = "firefox"
            self.stream_info_extractor.proxy_enabled = False
            self.stream_info_extractor.proxy = ""

        if (
            hasattr(self, "transcription_engine")
            and self.transcription_engine is not None
        ):
            if (
                not hasattr(self.transcription_engine, "model")
                or self.transcription_engine.model is None
            ):
                self._perform_auto_model_selection()
            else:
                logger.debug(
                    "TranscriptionEngine hat bereits ein Modell – überspringe Auto-Modellauswahl",
                )
        else:
            logger.warning(
                "⚠️ Überspringe Auto-Modellauswahl – TranscriptionEngine noch nicht verfügbar.",
            )

        self._apply_precision_optimizations()
        self._last_low_conf_warning_time = 0.0
        self._volume_popup: tk.Toplevel | None = None

        logger.debug("[GUI] _init_queues_and_extractor abgeschlossen")

    def _init_load_model_async(self) -> None:
        """Lädt das Standardmodell asynchron im Hintergrund – optimiert für Robustheit."""
        if self.is_shutting_down():
            logger.info("🛑 _init_load_model_async: Shutdown aktiv – Abbruch")
            return

        if self.demo_mode or not self.settings.default_model:
            return

        if (
            not hasattr(self, "transcription_engine")
            or self.transcription_engine is None
        ):
            logger.warning(
                "Überspringe asynchrones Modell-Laden – Engine nicht verfügbar",
            )
            self.update_status("❌ Transkriptions-Engine nicht verfügbar")
            return

        default_model = self.settings.default_model
        if default_model not in Config.WHISPER_MODELS:
            logger.warning(
                f"Standardmodell '{default_model}' unbekannt – kein Auto‑Load.",
            )
            return

        if getattr(self, "_model_loading_in_progress", False):
            logger.debug(
                "_init_load_model_async: Ladevorgang bereits aktiv – überspringe",
            )
            return
        self._model_loading_in_progress = True

        models_to_try = [default_model]
        for m in ["large-v3-turbo", "medium", "small", "base", "tiny"]:
            if m not in models_to_try:
                models_to_try.append(m)

        engine = self.transcription_engine
        is_gpu = (
            self.advanced_settings.gpu_acceleration
            and getattr(engine, "device", "") == "cuda"
        )
        vram_gb = None
        if is_gpu:
            with contextlib.suppress(Exception):
                vram_gb = engine._get_free_gpu_memory()

        self.update_status(f"🤖 Lade Modell {default_model}...")
        self._show_initial_status(f"🤖 Lade Modell {default_model}...")
        self.event_bus.emit("model_load_started", {"model": default_model})

        def _load_model_async():
            loaded_model = None
            success = False
            last_exception = None

            try:
                for model in models_to_try:
                    if self.is_shutting_down():
                        logger.info("🛑 Modell-Laden abgebrochen (Shutdown)")
                        return

                    if is_gpu and vram_gb is not None:
                        try:
                            needed = engine._estimate_model_memory(model)
                            buffer = max(0.2, needed * 0.2)
                            if needed + buffer > vram_gb:
                                logger.debug(
                                    f"Überspringe {model}: benötigt {
                                        needed:.2f} GB, frei {vram_gb:.2f} GB"
                                )
                                continue
                        except Exception:
                            pass

                    try:
                        logger.info(f"🔄 Versuche Modell {model} zu laden ...")
                        result = engine.load_model(model, set_active=True)

                        if self.is_shutting_down():
                            logger.info(
                                "🛑 Ladevorgang abgebrochen (Shutdown während load_model)",
                            )
                            return

                        if result is not None:
                            loaded_model = model
                            success = True
                            logger.info(f"✅ Modell {model} erfolgreich geladen")
                            break
                        logger.warning(
                            f"❌ Modell {model} konnte nicht geladen werden (load_model gab None)",
                        )
                    except Exception as e:
                        last_exception = e
                        logger.warning(f"❌ Modell {model} fehlgeschlagen: {e}")

                        if (
                            isinstance(e, RuntimeError)
                            and "out of memory" in str(e).lower()
                        ):
                            logger.warning("💥 Out of Memory – Cache wird geleert")
                            if is_gpu:
                                try:
                                    import torch

                                    torch.cuda.empty_cache()
                                except Exception:
                                    pass
                        continue

                if self.is_shutting_down():
                    logger.info("🛑 Modell-Laden nach Schleife abgebrochen (Shutdown)")
                    return

                if not success:
                    error_msg = f"❌ Kein Modell konnte geladen werden (versucht: {models_to_try})"
                    if last_exception:
                        error_msg += f" – Letzter Fehler: {last_exception}"
                    logger.error(error_msg)

                    def _update_gui_error():
                        if self.is_shutting_down() or not self.root.winfo_exists():
                            return
                        self.update_status(error_msg[:120])
                        self._show_initial_status(error_msg[:80])
                        self._set_start_button_loading_state(False)
                        if hasattr(self, "model_var"):
                            self.model_var.set("none")
                        self.event_bus.emit(
                            "model_load_finished",
                            {"success": False, "error": error_msg},
                        )

                    if (
                        hasattr(self, "queue_manager")
                        and self.queue_manager is not None
                    ):
                        self.queue_manager.safe_put(
                            self.QUEUE_TYPE_GUI,
                            ("callback", _update_gui_error, True),
                        )
                    else:
                        self.root.after_idle(_update_gui_error)

                else:

                    def _update_gui_success():
                        if self.is_shutting_down() or not self.root.winfo_exists():
                            return
                        self.update_status(f"✅ Modell {loaded_model} geladen")
                        self._set_start_button_loading_state(False)
                        self._show_initial_status(f"✅ Modell {loaded_model} geladen")
                        self._last_transcription_time = time.time()
                        if (
                            hasattr(self, "model_var")
                            and self.model_var.get() != loaded_model
                        ):
                            self.model_var.set(loaded_model)
                        self._schedule_vram_idle_check()
                        self.event_bus.emit(
                            "model_load_finished",
                            {"success": True, "model": loaded_model},
                        )

                    if (
                        hasattr(self, "queue_manager")
                        and self.queue_manager is not None
                    ):
                        self.queue_manager.safe_put(
                            self.QUEUE_TYPE_GUI,
                            ("callback", _update_gui_success, True),
                        )
                    else:
                        self.root.after_idle(_update_gui_success)

                    logger.info(
                        f"✅ Asynchrones Modell-Laden abgeschlossen: {loaded_model}",
                    )

            finally:
                self._model_loading_in_progress = False

        threading.Thread(
            target=_load_model_async,
            daemon=True,
            name="AutoLoadModel",
        ).start()
        self._init_verbose_print(
            f"  → Asynchroner Ladevorgang für {default_model} gestartet",
        )

    def _init_finalize(self) -> None:
        """Schließt die Initialisierung ab und protokolliert die Dauer."""
        elapsed_ms = (time.perf_counter() - self._init_start_time) * 1000
        logger.debug(
            f"✅ DragonWhispererGUI.__init__ erfolgreich abgeschlossen ({
                elapsed_ms:.1f} ms)",
        )
        logger.info("🐉 GUI bereit – Hauptfenster wird jetzt angezeigt")
        self._show_initial_status("🐉 Bereit – Starten Sie einen Stream!")

        self._safe_after(100, self._sync_auto_tts_to_processor)

        if self._init_verbose:
            print(f"🔍 [INIT] Initialisierung abgeschlossen in {elapsed_ms:.1f} ms")

    def _show_initial_status(self, message: str, force: bool = False) -> None:
        """📌 ULTIMATIVE STATUSANZEIGE FÜR INITIALISIERUNG V2.0 🔥
        Zeigt eine Statusmeldung während der Initialisierung an.
        Mit Duplikat-Erkennung, Thread-Info, optionalem Logging und Fallback auf print().
        """
        import logging
        import threading

        _logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not message or not isinstance(message, str):
            if debug_level >= 3:
                _logger.debug(
                    f"_show_initial_status: Leere oder ungültige Nachricht ignoriert (Typ: {type(message).__name__})",
                )
            return

        clean_message = message.strip()
        if not clean_message:
            if debug_level >= 3:
                _logger.debug(
                    "_show_initial_status: Nachricht nur aus Whitespace – ignoriert"
                )
            return

        if len(clean_message) > 80:
            clean_message = clean_message[:77] + "..."

        current_thread = threading.current_thread()
        thread_name = current_thread.name
        is_main = current_thread is threading.main_thread()

        if debug_level >= 4:
            _logger.debug(
                f"_show_initial_status: Aufruf von Thread '{thread_name}' (main={is_main})",
            )

        if not hasattr(self, "_last_init_status_lock"):
            self._last_init_status_lock = threading.RLock()

        with self._last_init_status_lock:
            if not force:
                last_status = getattr(self, "_last_init_status", None)
                if last_status == clean_message:
                    if debug_level >= 4:
                        _logger.debug(
                            f"_show_initial_status: Duplikat übersprungen: '{clean_message}'",
                        )
                    return

            self._last_init_status = clean_message

        if debug_level >= 3:
            log_debug("init", f"📌 {clean_message}")

        try:
            if hasattr(self, "update_status") and callable(self.update_status):
                self.update_status(clean_message)
                if debug_level >= 4:
                    _logger.debug(
                        f"_show_initial_status: Status über update_status gesetzt: '{clean_message}'",
                    )
            elif debug_level >= 1:
                print(f"[INIT] {clean_message}")
                if debug_level >= 4:
                    _logger.debug(
                        f"_show_initial_status: Status über print() ausgegeben: '{clean_message}'",
                    )
            else:
                print(f"[INIT] {clean_message}")
        except Exception as e:
            if debug_level >= 2:
                _logger.debug(
                    f"_show_initial_status: Fehler beim Anzeigen von '{clean_message}': {e}",
                    exc_info=(debug_level >= 4),
                )
            import sys

            print(f"[INIT] {clean_message}", file=sys.stderr)

        try:
            if not hasattr(self, "_init_status_history"):
                self._init_status_history = []
            if (
                not self._init_status_history
                or self._init_status_history[-1] != clean_message
            ):
                self._init_status_history.append(clean_message)
                if len(self._init_status_history) > 200:
                    self._init_status_history = self._init_status_history[-100:]
        except Exception as e:
            if debug_level >= 4:
                _logger.debug(
                    f"_show_initial_status: Konnte Status-Historie nicht speichern: {e}"
                )

        if debug_level >= 4:
            _logger.debug(f"_show_initial_status: EXIT (message='{clean_message}')")

    @property
    def last_transcription_text(self) -> str:
        """Gibt den letzten transkribierten Text thread‑sicher zurück."""
        with self._duplicate_lock:
            return self._last_transcription_text

    @last_transcription_text.setter
    def last_transcription_text(self, value: str) -> None:
        """Setzt den letzten transkribierten Text thread‑sicher."""
        with self._duplicate_lock:
            self._last_transcription_text = value

    @property
    def last_translation_text(self) -> str:
        """Gibt den letzten übersetzten Text thread‑sicher zurück."""
        with self._duplicate_lock:
            return self._last_translation_text

    @last_translation_text.setter
    def last_translation_text(self, value: str) -> None:
        """Setzt den letzten übersetzten Text thread‑sicher."""
        with self._duplicate_lock:
            self._last_translation_text = value

    def _set_initial_url(self) -> None:
        """Setzt die initiale URL im Eingabefeld, falls vorhanden."""
        if hasattr(self, "url_entry") and self.url_entry.winfo_exists():
            self.url_entry.delete(0, "end")
            self.url_entry.insert(0, self.settings.last_url)
        else:
            self._safe_after(200, self._set_initial_url)

    def _register_event_bus_subscriptions(self) -> None:
        """Registriert alle Event-Bus-Abonnements – idempotent und fehlertolerant."""
        if self.event_bus is None:
            logger.warning(
                "Event-Bus nicht verfügbar – Abonnements werden nicht registriert.",
            )
            return

        if getattr(self, "_subscriptions_registered", False):
            logger.debug("Event-Bus-Abonnements bereits registriert – überspringe.")
            return

        subscriptions = [
            ("transcription", self.handle_transcription),
            ("translation", self.handle_translation),
            ("info", self.handle_info),
            ("error", self.handle_error),
            ("controller_state", self._on_controller_state),
            ("stream_info", self.update_stream_info),
            ("file_finished", self._on_file_finished),
            ("processing_finished", self._on_processing_finished),
            ("processing_state_changed", self._on_processing_state_changed),
            ("update_url", self._on_update_url),
            ("translation_language_changed", self._on_translation_language_changed),
            ("reset_gui", self._on_reset_gui),
            ("progress", self.update_progress),
            ("model_changed", self._on_model_changed),
            ("translation_quality_warning", self._on_translation_quality_warning),
            ("audio_processor_idle", self._on_audio_processor_idle),
            ("music_detected", self._on_music_detected),
            ("silence_detected", self._on_silence_detected),
            ("speech_detected", self._on_speech_detected),
            ("model_load_started", self._on_model_load_started),
            ("model_load_finished", self._on_model_load_finished),
        ]

        registered_count = 0
        with self._subscriptions_lock:
            for event, callback in subscriptions:
                try:
                    self.event_bus.subscribe(event, callback)
                    self._event_subscriptions.append((event, callback))
                    registered_count += 1
                except Exception as e:
                    logger.error(f"Fehler beim Registrieren von Event '{event}': {e}")

            self._subscriptions_registered = True

        logger.debug(
            f"Event handlers registered: {registered_count} von {
                len(subscriptions)
            } erfolgreich."
        )

    def _on_audio_processor_idle(self, _data: Any = None) -> None:
        """Callback, wenn der AudioProcessor in den IDLE-Zustand wechselt."""
        self._on_processing_finished()

    def _on_model_load_started(self, _data: Any = None) -> None:
        """Callback, wenn der asynchrone Modell-Ladevorgang beginnt."""
        self._set_start_button_loading_state(True)

    def _on_model_load_finished(self, _data: Any = None) -> None:
        """Callback, wenn der asynchrone Modell-Ladevorgang abgeschlossen ist."""
        if self.is_shutting_down():
            return

        if DEBUG_LEVEL >= 3:
            log_debug("model", "_on_model_load_finished aufgerufen")

        self._set_start_button_loading_state(False)

        if hasattr(self, "update_status"):
            self.update_status("✅ Modell bereit – START drücken zum Transkribieren")

    def _init_managers(self) -> None:
        """Initialisiert die verschiedenen Manager (Stream, FFmpeg, Export, Memory).
        Startet nach erfolgreicher Initialisierung das CPU-Monitoring.
        """
        debug_level = getattr(self, "debug_level", 0)

        self.resource_manager = ResourceManager()
        if debug_level >= 3:
            logger.debug(
                "ResourceManager initialisiert",
                extra={"component": "controller"},
            )

        self.stream_manager = StreamManager(
            enable_debug=(debug_level >= 1),
            use_browser_cookies=self.settings.use_browser_cookies,
            proxy=self.advanced_settings.proxy_url,
            proxy_enabled=self.advanced_settings.proxy_enabled,
        )
        if debug_level >= 3:
            logger.debug(
                f"StreamManager initialisiert (cookies={self.settings.use_browser_cookies}, "
                f"browser={self.settings.cookies_browser}, proxy={self.advanced_settings.proxy_url})",
                extra={"component": "controller"},
            )

        self.ffmpeg_manager = FFmpegManager(
            self.advanced_settings.config,
            self.stream_manager,
            self.advanced_settings,
            resource_manager=self.resource_manager,
        )
        if debug_level >= 3:
            logger.debug(
                "FFmpegManager initialisiert",
                extra={"component": "controller"},
            )

        self.export_manager = ExportManager()
        if debug_level >= 3:
            logger.debug(
                "ExportManager initialisiert",
                extra={"component": "controller"},
            )

        self.memory_manager = MemoryManager()
        if debug_level >= 3:
            logger.debug(
                "MemoryManager initialisiert",
                extra={"component": "controller"},
            )

        if IS_LINUX:
            self.performance_optimizer = LinuxPerformanceOptimizer(gui_ref=self)
            if debug_level >= 3:
                logger.debug(
                    "LinuxPerformanceOptimizer initialisiert",
                    extra={"component": "controller"},
                )

        self._start_cpu_monitoring()

        if debug_level >= 2:
            logger.debug(
                "Alle Manager initialisiert: resource, stream, ffmpeg, export, memory, "
                f"{'performance_optimizer, ' if IS_LINUX else ''}cpu_monitor",
                extra={"component": "controller"},
            )

    def _init_engines(self) -> None:
        """Initialisiert die Transkriptions‑, Übersetzungs‑ und Audio‑Engines
        mit maximaler Robustheit und detaillierten Debug‑Informationen.
        Führt nach der Initialisierung einen asynchronen Test der
        Übersetzungs‑Engine durch, um deren Funktionsfähigkeit frühzeitig
        zu erkennen.
        """
        log_debug("init", "▶️ _init_engines gestartet")
        self.transcription_engine = None
        self.demo_mode = False

        if WHISPER_AVAILABLE:
            try:
                log_debug("init", "Versuche TranscriptionEngine zu erstellen...")
                self.transcription_engine = TranscriptionEngine(
                    self.advanced_settings,
                    cache_manager=self.app_context.cache_manager,
                    event_bus=self.event_bus,
                )

                if self.transcription_engine is not None:
                    log_debug("init", "✅ TranscriptionEngine erfolgreich erstellt.")
                else:
                    logger.warning(
                        "TranscriptionEngine-Instanz ist None – verwende Dummy.",
                    )
                    self.transcription_engine = None

            except Exception as e:
                logger.exception(
                    "❌ Fehler beim Erstellen der TranscriptionEngine: %s\n"
                    "Mögliche Ursachen: PyTorch fehlt/defekt, CUDA‑Treiber nicht kompatibel, "
                    "Microsoft Visual C++ Redistributable nicht installiert.",
                    e,
                )
                self.transcription_engine = None
        else:
            logger.warning(
                "Kein Whisper‑Backend verfügbar (faster‑whisper/openai‑whisper fehlen) – "
                "verwende DummyTranscriptionEngine.",
            )

        if self.transcription_engine is None:
            try:
                log_debug("init", "Erstelle DummyTranscriptionEngine als Fallback...")
                self.transcription_engine = DummyTranscriptionEngine(
                    self.advanced_settings,
                    cache_manager=(
                        self.app_context.cache_manager if self.app_context else None
                    ),
                )
                self.demo_mode = True
                logger.info(
                    "🔄 Demo‑Modus aktiviert (DummyTranscriptionEngine verwendet).",
                )
            except Exception as e:
                logger.critical(
                    "❌ Auch DummyTranscriptionEngine konnte nicht erstellt werden: %s",
                    e,
                    exc_info=True,
                )
                self.transcription_engine = None
                self.demo_mode = True

        log_debug(
            "init",
            "Transkriptions‑Engine final: %s (demo_mode=%s)",
            (
                type(self.transcription_engine).__name__
                if self.transcription_engine
                else "None"
            ),
            self.demo_mode,
        )

        try:
            if self.transcription_engine is not None:
                self.language_detector = LanguageDetector(self.transcription_engine)
                log_debug("init", "✅ LanguageDetector erstellt.")
            else:
                self.language_detector = None
                logger.warning(
                    "LanguageDetector nicht erstellt, da transcription_engine None ist.",
                )
        except Exception as e:
            logger.exception("❌ Fehler beim Erstellen des LanguageDetectors: %s", e)
            self.language_detector = None

        log_debug("init", "Erstelle Übersetzungs‑Engine...")
        self.translation_engine = None
        self._applied_translation_engine_name: str | None = None

        try:
            if hasattr(self, "_create_translation_engine") and callable(
                self._create_translation_engine,
            ):
                self.translation_engine = self._create_translation_engine()
                if self.translation_engine is None:
                    logger.warning(
                        "_create_translation_engine gab None zurück – verwende Dummy.",
                    )
            else:
                logger.warning(
                    "DragonWhispererGUI._create_translation_engine nicht gefunden – "
                    "verwende DummyTranslationEngine.",
                )

            if self.translation_engine is None:
                self.translation_engine = DummyTranslationEngine(
                    target_lang=self.current_language,
                    settings=self.advanced_settings,
                    cache_manager=(
                        self.app_context.cache_manager if self.app_context else None
                    ),
                )
                logger.info(
                    "ℹ️ DummyTranslationEngine als Übersetzungs‑Engine verwendet.",
                )

            if (
                hasattr(self.translation_engine, "is_functional")
                and not self.translation_engine.is_functional()
            ):
                logger.warning(
                    "Übersetzungs‑Engine ist nicht funktionsfähig – wechsle zu Dummy.",
                )
                self.translation_engine = DummyTranslationEngine(
                    target_lang=self.current_language,
                    settings=self.advanced_settings,
                    cache_manager=(
                        self.app_context.cache_manager if self.app_context else None
                    ),
                )

            log_debug(
                "init",
                f"✅ Übersetzungs‑Engine erstellt: {
                    type(self.translation_engine).__name__
                }",
            )

        except Exception as e:
            logger.exception(
                "❌ Fehler beim Erstellen der Übersetzungs‑Engine: %s\n   Verwende DummyTranslationEngine.",
                e,
            )
            self.translation_engine = DummyTranslationEngine(
                target_lang=self.current_language,
                settings=self.advanced_settings,
                cache_manager=(
                    self.app_context.cache_manager if self.app_context else None
                ),
            )

        try:
            _actual_type = type(self.translation_engine).__name__
            if "GoogleTranslationEngine" in _actual_type:
                self._applied_translation_engine_name = "google"
            elif "OllamaTranslationEngine" in _actual_type:
                self._applied_translation_engine_name = "ollama"
            elif "ArgosTranslateEngine" in _actual_type:
                self._applied_translation_engine_name = "argos"
            elif "ReflectionTranslationEngine" in _actual_type:
                self._applied_translation_engine_name = getattr(
                    self.advanced_settings, "translation_engine", None
                )
            elif "Dummy" in _actual_type:
                self._applied_translation_engine_name = "dummy"
            else:
                self._applied_translation_engine_name = None

            log_debug(
                "init",
                f"📌 Aktive Engine registriert: "
                f"{_actual_type} → "
                f"'{self._applied_translation_engine_name}'",
            )
        except Exception as _eng_name_exc:
            logger.debug(
                "init: _applied_translation_engine_name konnte nicht "
                "gesetzt werden: %s",
                _eng_name_exc,
            )
            self._applied_translation_engine_name = None

        fallback_translation_engine = None

        if ARGOS_AVAILABLE:
            try:
                log_debug("init", "Versuche Argos‑Fallback‑Engine...")
                fallback_translation_engine = ArgosTranslateEngine(
                    target_lang=self.current_language,
                    settings=self.advanced_settings,
                    cache_manager=(
                        self.app_context.cache_manager if self.app_context else None
                    ),
                )
                if fallback_translation_engine.is_functional():
                    log_debug(
                        "init",
                        "✅ Argos‑Fallback‑Engine erstellt und funktionsfähig.",
                    )
                else:
                    logger.warning(
                        "Argos‑Fallback‑Engine ist nicht funktionsfähig – wird ignoriert.",
                    )
                    fallback_translation_engine = None
            except Exception as e:
                logger.warning(
                    "Fehler beim Erstellen der Argos‑Fallback‑Engine: %s",
                    e,
                    exc_info=True,
                )
                fallback_translation_engine = None
        elif OLLAMA_AVAILABLE:
            try:
                log_debug("init", "Versuche Ollama‑Fallback‑Engine...")
                fallback_translation_engine = OllamaTranslationEngine(
                    target_lang=self.current_language,
                    settings=self.advanced_settings,
                    model=self.advanced_settings.ollama_model,
                    host=self.advanced_settings.ollama_host,
                    timeout=getattr(self.advanced_settings, "ollama_timeout", 45),
                    cache_manager=(
                        self.app_context.cache_manager if self.app_context else None
                    ),
                )
                if fallback_translation_engine.is_functional():
                    log_debug(
                        "init",
                        "✅ Ollama‑Fallback‑Engine erstellt und funktionsfähig.",
                    )
                else:
                    logger.warning(
                        "Ollama‑Fallback‑Engine ist nicht funktionsfähig – wird ignoriert.",
                    )
                    fallback_translation_engine = None
            except Exception as e:
                logger.warning(
                    "Fehler beim Erstellen der Ollama‑Fallback‑Engine: %s",
                    e,
                    exc_info=True,
                )
                fallback_translation_engine = None
        else:
            log_debug(
                "init",
                "Keine Fallback‑Übersetzungs‑Engine verfügbar (Argos/Ollama fehlen).",
            )

        try:
            log_debug("init", "Erstelle AudioProcessor...")
            self.audio_processor = AudioProcessor(
                controller_ref=self.controller,
                ffmpeg_manager=self.ffmpeg_manager,
                settings=self.advanced_settings,
                use_browser_cookies=self.settings.use_browser_cookies,
                stream_manager=self.stream_manager,
                cache_manager=(
                    self.app_context.cache_manager if self.app_context else None
                ),
            )
            self.audio_processor.set_engines(
                transcription_engine=self.transcription_engine,
                translation_engine=self.translation_engine,
                fallback_translation_engine=fallback_translation_engine,
            )
            log_debug("init", "✅ AudioProcessor erstellt und Engines konfiguriert.")
        except Exception as e:
            logger.exception("❌ Fehler beim Erstellen des AudioProcessors: %s", e)
            raise

        if self.demo_mode:
            if (
                hasattr(self, "model_combo")
                and self.model_combo is not None
                and self.model_combo.winfo_exists()
            ):
                self.model_combo.config(state="disabled")
                self.model_var.set("dummy (Demo)")
            self.update_status(
                "⚠️ Demo‑Modus: Whisper nicht verfügbar – verwende Dummy‑Transkriptionen",
            )
            log_debug("init", "Demo‑Modus GUI‑Anpassungen vorgenommen.")
        elif (
            hasattr(self, "model_combo")
            and self.model_combo is not None
            and self.model_combo.winfo_exists()
        ):
            self.model_combo.config(state="readonly")
            if self.settings.default_model:
                self.model_var.set(self.settings.default_model)
            else:
                available = get_available_whisper_models()
                self.model_var.set(next(iter(available)) if available else "base")
        log_debug(
            "init",
            "✅ _init_engines abgeschlossen – transcription_engine=%s, demo_mode=%s",
            (
                type(self.transcription_engine).__name__
                if self.transcription_engine
                else "None"
            ),
            self.demo_mode,
        )
        self._start_translation_test_after_gui_ready()

    def _append_transcript(self, text):
        """Fügt einen Text in das Transkriptions‑Textfeld ein."""
        try:
            self.transcript_text.insert(tk.END, text + "\n")
            self.transcript_text.see(tk.END)
        except Exception as e:
            logger.error(f"Fehler beim Einfügen von Text: {e}")

    def _start_cpu_monitoring(self) -> None:
        """🖥️ ULTIMATIVE CPU-MONITORING-START V2.0 🔥
        Startet das CPU-Monitoring über den Controller.
        Mit erweiterten Prüfungen, Doppelstart-Schutz, Thread-Info und Fallback.
        """
        import logging
        import threading

        _logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        _logger.debug("▶️ _start_cpu_monitoring ENTRY")

        if getattr(self, "_shutting_down", False):
            _logger.debug("  ⏹️ Shutdown aktiv – CPU-Monitoring wird nicht gestartet")
            return

        if hasattr(self, "_cpu_monitor_running") and self._cpu_monitor_running:
            _logger.debug("  ℹ️ CPU-Monitoring läuft bereits – überspringe")
            return

        if not hasattr(self, "controller") or self.controller is None:
            _logger.warning("  ⚠️ Kein Controller verfügbar für CPU-Monitoring")
            return

        if not hasattr(self.controller, "_start_cpu_monitoring"):
            _logger.warning("  ⚠️ Controller hat keine _start_cpu_monitoring-Methode")
            return

        try:
            if (
                hasattr(self.controller, "is_shutting_down")
                and self.controller.is_shutting_down()
            ):
                _logger.debug(
                    "  ⏹️ Controller wird heruntergefahren – starte kein Monitoring"
                )
                return

            _logger.debug(
                f"  🧠 Rufe controller._start_cpu_monitoring() auf (Thread: {threading.current_thread().name})"
            )
            self.controller._start_cpu_monitoring()
            self._cpu_monitor_running = True
            _logger.debug("  ✅ CPU-Monitoring über Controller gestartet")
        except Exception as e:
            _logger.error(
                f"  ❌ Fehler beim Starten des CPU-Monitorings: {e}", exc_info=True
            )
            self._cpu_monitor_running = False

        if debug_level >= 3:
            try:
                monitor_threads = [
                    t for t in threading.enumerate() if t.name == "CPUMonitor"
                ]
                if monitor_threads and monitor_threads[0].is_alive():
                    _logger.debug(
                        "  ✅ CPU-Monitor-Thread läuft (TID: %s)",
                        monitor_threads[0].ident,
                    )
                else:
                    _logger.warning(
                        "  ⚠️ CPU-Monitor-Thread nicht gefunden oder nicht aktiv"
                    )
            except Exception as e:
                _logger.debug(f"  ⚠️ Konnte Monitor-Thread nicht prüfen: {e}")
        try:
            pass
        except Exception as e:
            _logger.debug(f"  ⚠️ Watchdog-Start fehlgeschlagen: {e}")

        _logger.debug("◀️ _start_cpu_monitoring EXIT")

    def _apply_cpu_optimizations(self) -> None:
        """Wendet alle CPU‑spezifischen Optimierungen an, falls GPU deaktiviert ist
        oder das System nicht genügend VRAM/Rechenleistung bietet.
        """
        force_cpu = False
        if not self.advanced_settings.gpu_acceleration:
            force_cpu = True
        else:
            try:
                import torch

                if torch.cuda.is_available():
                    cc_major, cc_minor = torch.cuda.get_device_capability(0)
                    if cc_major < 6:
                        logger.warning(
                            f"⚠️ GPU Compute Capability {cc_major}.{cc_minor} ist zu alt (< 6.0) – "
                            "deaktiviere GPU und wechsle zu CPU.",
                        )
                        force_cpu = True
                        self.advanced_settings.gpu_acceleration = False
                else:
                    force_cpu = True
            except Exception:
                force_cpu = True

        if not force_cpu:
            logger.debug(
                "CPU‑Optimierungen nicht angewendet – GPU‑Beschleunigung ist aktiv und kompatibel.",
            )
            return

        adv = self.advanced_settings
        config = adv.config

        if not hasattr(config, "_is_cpu_mode"):
            config._is_cpu_mode = True
        else:
            config._is_cpu_mode = True

        config._is_cpu_mode = True
        if hasattr(adv, "_is_cpu_mode"):
            adv._is_cpu_mode = True

        if (
            hasattr(self, "transcription_engine")
            and self.transcription_engine is not None
        ):
            engine = self.transcription_engine
            if getattr(engine, "device", "cpu") != "cpu":
                with engine._device_lock:
                    engine.device = "cpu"
                    engine.compute_type = "int8"
                logger.info("💻 CPU‑Modus: TranscriptionEngine auf CPU gesetzt")

        if self.settings.default_model not in ("tiny", "tiny.en", "base", "base.en"):
            old_model = self.settings.default_model
            self.settings.default_model = "tiny"
            logger.info(
                f"✅ CPU‑Modus: Modell von '{old_model}' auf 'tiny' gesetzt (für Performance)",
            )

        expected_duration = getattr(self, "_expected_duration", None)
        if (
            expected_duration is None
            and hasattr(self, "audio_processor")
            and self.audio_processor is not None
        ):
            expected_duration = getattr(
                self.audio_processor,
                "_expected_duration",
                None,
            )

        if expected_duration is not None and expected_duration > 120:
            if config.CHUNK_DURATION < 10.0:
                config.CHUNK_DURATION = 10.0
                logger.info(
                    "📈 CPU‑VOD‑Modus: Chunk‑Dauer auf 10.0s erhöht (besserer Kontext)",
                )
            config.MAX_CHUNK_DURATION = min(config.MAX_CHUNK_DURATION, 10.0)
        else:
            if config.CHUNK_DURATION > 5.0:
                config.CHUNK_DURATION = 5.0
                logger.info(
                    "⚡ CPU‑Live‑Modus: Chunk‑Dauer auf 5.0s reduziert (niedrige Latenz)",
                )
            config.MAX_CHUNK_DURATION = min(config.MAX_CHUNK_DURATION, 5.0)

        adv.beam_size = 1
        adv.best_of = 1
        logger.info("⚙️ CPU‑Modus: beam_size=1, best_of=1")

        adv.condition_on_previous_text = False
        logger.info("⚙️ CPU‑Modus: condition_on_previous_text deaktiviert")

        adv.vad_filter = False
        logger.info("⚙️ CPU‑Modus: VAD deaktiviert")

        adv.enable_audio_enhancement = False
        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            self.audio_processor._audio_enhancer = None
        logger.info("⚙️ CPU‑Modus: Audio‑Enhancement deaktiviert")

        adv.transcription_workers = 1
        logger.info("⚙️ CPU‑Modus: Transkriptions‑Worker auf 1 gesetzt")

        if hasattr(adv, "translation_workers"):
            adv.translation_workers = 1
            logger.info("⚙️ CPU‑Modus: Übersetzungs‑Worker auf 1 gesetzt")

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            ap = self.audio_processor
            if hasattr(ap, "_translation_semaphore"):
                ap._translation_semaphore = threading.Semaphore(1)
                logger.info("⚙️ CPU‑Modus: Übersetzungs‑Semaphor auf 1 begrenzt")

        if hasattr(adv, "fallback_source_language"):
            adv.fallback_source_language = "en"
            logger.info("⚙️ CPU‑Modus: Fallback‑Sprache auf 'en' gesetzt")

        if hasattr(adv, "no_speech_threshold"):
            adv.no_speech_threshold = 0.9
            logger.info("⚙️ CPU‑Modus: no_speech_threshold auf 0.9 erhöht")
        if hasattr(adv, "log_prob_threshold"):
            adv.log_prob_threshold = -2.0
            logger.info("⚙️ CPU‑Modus: log_prob_threshold auf -2.0 gesetzt")
        if hasattr(adv, "compression_ratio_threshold"):
            adv.compression_ratio_threshold = 2.8
            logger.info("⚙️ CPU‑Modus: compression_ratio_threshold auf 2.8 gesetzt")

        if hasattr(adv, "adaptive_chunk"):
            adv.adaptive_chunk = False
            logger.info("⚙️ CPU‑Modus: Adaptive Chunk deaktiviert")

        if hasattr(adv, "duplicate_similarity_threshold"):
            adv.duplicate_similarity_threshold = 0.99
            logger.info(
                "⚙️ CPU‑Modus: Duplikat‑Schwelle auf 0.99 erhöht (de facto deaktiviert)",
            )

        if hasattr(adv, "min_confidence"):
            adv.min_confidence = 0.05
            logger.info("⚙️ CPU‑Modus: min_confidence auf 0.05 gesetzt")

        if hasattr(adv, "sentence_flush_interval"):
            adv.sentence_flush_interval = 2.0
            logger.info("⚙️ CPU‑Modus: sentence_flush_interval auf 2.0s gesetzt")
        if hasattr(adv, "sentence_flush_word_threshold"):
            adv.sentence_flush_word_threshold = 15
            logger.info("⚙️ CPU‑Modus: sentence_flush_word_threshold auf 15 gesetzt")

        if hasattr(adv, "tts_length_scale"):
            adv.tts_length_scale = 0.8
            logger.info("⚙️ CPU‑Modus: tts_length_scale auf 0.8 gesetzt")

        if hasattr(config, "CHUNK_OVERLAP"):
            old_overlap = config.CHUNK_OVERLAP
            config.CHUNK_OVERLAP = 0.0
            logger.info(
                f"⚙️ CPU‑Modus: Chunk-Überlappung von {old_overlap:.1f}s auf 0.0s gesetzt",
            )

        if hasattr(config, "FFMPEG_THREADS"):
            old_threads = config.FFMPEG_THREADS
            config.FFMPEG_THREADS = 1
            logger.info(f"⚙️ CPU‑Modus: FFmpeg-Threads von {old_threads} auf 1 gesetzt")

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            ap = self.audio_processor
            if hasattr(ap, "_max_buffer_bytes"):
                old_buffer = ap._max_buffer_bytes

                new_buffer = min(old_buffer, 2 * 1024 * 1024)
                if new_buffer != old_buffer:
                    ap._max_buffer_bytes = new_buffer
                    logger.info(
                        f"⚙️ CPU‑Modus: Audio-Puffergröße von {
                            old_buffer // 1024
                        }KB auf {new_buffer // 1024}KB reduziert"
                    )

        if hasattr(self, "app_context") and self.app_context is not None:
            cm = getattr(self.app_context, "cache_manager", None)
            if cm is not None:
                if hasattr(cm, "transcription_cache") and hasattr(
                    cm.transcription_cache,
                    "maxsize",
                ):
                    old = cm.transcription_cache.maxsize
                    new = max(10, old // 4)
                    cm.transcription_cache.maxsize = new
                    logger.info(
                        f"⚙️ CPU‑Modus: Transkriptions-Cache von {old} auf {new} reduziert",
                    )

                if hasattr(cm, "translation_cache") and hasattr(
                    cm.translation_cache,
                    "maxsize",
                ):
                    old = cm.translation_cache.maxsize
                    new = max(10, old // 4)
                    cm.translation_cache.maxsize = new
                    logger.info(
                        f"⚙️ CPU‑Modus: Übersetzungs-Cache von {old} auf {new} reduziert",
                    )

                if hasattr(cm, "audio_cache") and hasattr(cm.audio_cache, "maxsize"):
                    old = cm.audio_cache.maxsize
                    new = max(10, old // 4)
                    cm.audio_cache.maxsize = new
                    logger.info(
                        f"⚙️ CPU‑Modus: Audio-Cache von {old} auf {new} reduziert",
                    )

                if hasattr(cm, "generic_cache") and hasattr(
                    cm.generic_cache,
                    "maxsize",
                ):
                    old = cm.generic_cache.maxsize
                    new = max(10, old // 4)
                    cm.generic_cache.maxsize = new
                    logger.info(
                        f"⚙️ CPU‑Modus: Generic-Cache von {old} auf {new} reduziert",
                    )

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            ap = self.audio_processor
            if hasattr(ap, "_subtitle_watchdog_seconds"):
                old_watchdog = ap._subtitle_watchdog_seconds
                ap._subtitle_watchdog_seconds = 120.0
                logger.info(
                    f"⚙️ CPU‑Modus: Subtitle-Watchdog von {old_watchdog:.1f}s auf 120.0s erhöht",
                )

        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            ap = self.audio_processor
            if hasattr(ap, "_max_segment_buffer_size"):
                old_size = ap._max_segment_buffer_size
                new_size = min(old_size, 500)
                if new_size != old_size:
                    ap._max_segment_buffer_size = new_size
                    logger.info(
                        f"⚙️ CPU‑Modus: Segment-Puffer von {old_size} auf {new_size} reduziert",
                    )

        if hasattr(self, "queue_manager") and self.queue_manager is not None:
            qm = self.queue_manager
            if qm.GUI_QUEUE_MAX_SIZE > 50:
                qm.GUI_QUEUE_MAX_SIZE = max(30, qm.GUI_QUEUE_MAX_SIZE // 2)
            if qm.TEXT_QUEUE_MAX_SIZE > 30:
                qm.TEXT_QUEUE_MAX_SIZE = max(20, qm.TEXT_QUEUE_MAX_SIZE // 2)
            logger.info("⚙️ CPU‑Modus: Queue‑Größen halbiert")

        if adv.hotwords:
            adv.hotwords = ""
            logger.info("⚙️ CPU‑Modus: Hotwords geleert")

        try:
            import torch

            if torch.cuda.is_available():
                torch.cuda.empty_cache()
                logger.info("⚙️ CPU‑Modus: CUDA‑Cache geleert")
        except Exception:
            pass

        try:
            adv.save_to_file()
            self.settings.save_to_file()
            logger.debug("CPU‑Optimierungen in AdvancedSettings gespeichert")
        except Exception as e:
            logger.warning(f"Konnte CPU‑Optimierungen nicht speichern: {e}")

        if hasattr(self, "model_var") and self.model_var is not None:
            try:
                self.model_var.set(self.settings.default_model)
                logger.debug(
                    f"Modell‑ComboBox auf '{self.settings.default_model}' gesetzt",
                )
            except Exception as e:
                logger.debug(f"Konnte Modell‑ComboBox nicht aktualisieren: {e}")

        if hasattr(self, "event_bus") and self.event_bus is not None:
            try:
                self.event_bus.emit("cpu_optimizations_applied", {"settings": adv})
            except Exception as e:
                logger.debug("Fehler beim Senden des CPU‑Optimierungs‑Events: %s", e)

        if hasattr(self, "_print_system_diagnostics"):
            self._print_system_diagnostics()

        logger.info("✅ Alle CPU‑Optimierungen erfolgreich angewendet")

    def _apply_advanced_settings(self) -> None:
        """Übernimmt die aktuellen Werte aus den erweiterten Einstellungen (AdvancedSettings)
        und wendet sie auf den AudioProcessor und andere Komponenten an.
        """
        import logging
        import time

        logger = logging.getLogger("dragon")

        if self.is_shutting_down():
            logger.debug("_apply_advanced_settings: Shutdown aktiv – Abbruch")
            return

        adv = self.advanced_settings
        if adv is None:
            logger.warning("_apply_advanced_settings: AdvancedSettings nicht verfügbar")
            return

        ap = getattr(self, "audio_processor", None)
        if ap is not None:
            new_chunk = adv.chunk_duration
            try:
                ap.set_chunk_duration(new_chunk, force=False)
                logger.debug(
                    f"Chunk-Dauer auf {new_chunk:.1f}s gesetzt (über AudioProcessor)",
                )
            except Exception as e:
                logger.warning(f"Fehler beim Setzen der Chunk-Dauer: {e}")
                adv.config.CHUNK_DURATION = new_chunk
                ap._update_chunk_size()
                if hasattr(ap, "_adaptive_bytes_per_sec"):
                    ap._adaptive_bytes_per_sec = getattr(
                        adv.config,
                        "BYTES_PER_SECOND",
                        32000.0,
                    )
                    ap._adaptive_warmup_chunks = 0
                    logger.debug(
                        f"Fallback: adaptive_bytes_per_sec auf {ap._adaptive_bytes_per_sec:.0f} gesetzt",
                    )

            if not hasattr(ap, "settings") or ap.settings is None:
                logger.warning(
                    "AudioProcessor hat kein settings-Objekt – überspringe Zuweisungen",
                )
                if hasattr(ap, "beam_size"):
                    ap.beam_size = adv.beam_size
                if hasattr(ap, "temperature"):
                    ap.temperature = adv.temperature
            else:
                try:
                    ap.settings.vad_filter = adv.vad_filter
                    ap.settings.vad_threshold = adv.vad_threshold
                    ap.settings.vad_min_speech_duration_ms = (
                        adv.vad_min_speech_duration_ms
                    )
                    ap.settings.vad_min_silence_duration_ms = (
                        adv.vad_min_silence_duration_ms
                    )
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von VAD-Parametern: {e}")

                whisper_attrs = [
                    "beam_size",
                    "temperature",
                    "condition_on_previous_text",
                    "no_speech_threshold",
                    "log_prob_threshold",
                    "compression_ratio_threshold",
                    "best_of",
                    "patience",
                ]
                for attr in whisper_attrs:
                    if hasattr(adv, attr):
                        try:
                            setattr(ap.settings, attr, getattr(adv, attr))
                        except Exception as e:
                            logger.warning(f"Fehler beim Setzen von {attr}: {e}")

                try:
                    ap.settings.enable_audio_enhancement = adv.enable_audio_enhancement
                    if adv.enable_audio_enhancement and ap._audio_enhancer is None:
                        ap._init_audio_enhancement()
                    elif (
                        not adv.enable_audio_enhancement
                        and ap._audio_enhancer is not None
                    ):
                        ap._audio_enhancer = None
                        logger.info("Audio-Enhancement deaktiviert")
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von Audio-Enhancement: {e}")

                try:
                    if adv.translation_engine != getattr(
                        ap.settings,
                        "translation_engine",
                        None,
                    ):
                        ap.settings.translation_engine = adv.translation_engine
                        ap._init_translation_executor()
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen der Übersetzungs-Engine: {e}")

                try:
                    if hasattr(ap.settings, "ollama_model"):
                        ap.settings.ollama_model = adv.ollama_model
                        ap.settings.ollama_host = adv.ollama_host
                        ap.settings.enable_reflection = adv.enable_reflection
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von Ollama-Parametern: {e}")

                try:
                    ap.settings.sentence_flush_interval = adv.sentence_flush_interval
                    ap.settings.sentence_flush_word_threshold = (
                        adv.sentence_flush_word_threshold
                    )
                    if hasattr(ap, "_sentence_flush_interval"):
                        ap._sentence_flush_interval = adv.sentence_flush_interval
                        ap._sentence_flush_word_threshold = (
                            adv.sentence_flush_word_threshold
                        )
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen der Satzpuffer-Parameter: {e}")

                try:
                    if hasattr(ap.settings, "tts_engine"):
                        ap.settings.tts_engine = adv.tts_engine
                        ap.settings.tts_voice = adv.tts_voice
                        ap.settings.tts_length_scale = adv.tts_length_scale
                        ap.settings.tts_sentence_silence = adv.tts_sentence_silence
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von TTS-Parametern: {e}")

                try:
                    if hasattr(ap.settings, "auto_tts_transcript"):
                        ap.settings.auto_tts_transcript = adv.auto_tts_transcript
                        ap.settings.auto_tts_translation = adv.auto_tts_translation
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von Auto-TTS: {e}")

                try:
                    ap.settings.duplicate_similarity_threshold = (
                        adv.duplicate_similarity_threshold
                    )
                    ap.settings.min_confidence = adv.min_confidence
                    ap.settings.gpu_acceleration = adv.gpu_acceleration
                    if hasattr(ap, "_is_gpu_available"):
                        AudioProcessor.reset_gpu_cache()
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von Konfidenz/GPU: {e}")

                try:
                    ap.settings.vram_idle_timeout_seconds = (
                        adv.vram_idle_timeout_seconds
                    )
                    ap.settings.adaptive_chunk = adv.adaptive_chunk
                    ap.settings.proxy_enabled = adv.proxy_enabled
                    ap.settings.proxy_url = adv.proxy_url
                    ap.settings.blacklist = adv.blacklist
                    ap.settings.blacklist_mode = adv.blacklist_mode
                    ap.settings.max_memory_mb = adv.max_memory_mb
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen von VRAM/Proxy/Blacklist: {e}")

                try:
                    self._safe_set_hotwords(ap, adv.hotwords)
                except Exception as e:
                    logger.warning(f"Fehler beim Setzen der Hotwords: {e}")

                logger.info("✅ Advanced Settings auf AudioProcessor angewendet")

        else:
            logger.warning(
                "AudioProcessor nicht verfügbar – Einstellungen nur in AdvancedSettings gespeichert",
            )

        if hasattr(self, "stream_manager") and self.stream_manager is not None:
            sm = self.stream_manager
            try:
                if hasattr(sm, "use_browser_cookies"):
                    sm.use_browser_cookies = self.settings.use_browser_cookies
                if hasattr(sm, "cookies_browser"):
                    sm.cookies_browser = self.settings.cookies_browser
                if hasattr(sm, "_proxy_enabled"):
                    sm._proxy_enabled = adv.proxy_enabled
                if hasattr(sm, "_proxy"):
                    sm._proxy = adv.proxy_url
                logger.debug("StreamManager aktualisiert")
            except Exception as e:
                logger.warning(f"StreamManager-Update fehlgeschlagen: {e}")

        if (
            hasattr(self, "stream_info_extractor")
            and self.stream_info_extractor is not None
        ):
            sie = self.stream_info_extractor
            try:
                sie.use_browser_cookies = self.settings.use_browser_cookies
                sie.cookies_browser = self.settings.cookies_browser
                sie.proxy_enabled = adv.proxy_enabled
                sie.proxy = adv.proxy_url
                logger.debug("StreamInfoExtractor aktualisiert")
            except Exception as e:
                logger.warning(f"StreamInfoExtractor-Update fehlgeschlagen: {e}")

        try:
            YtDlpHelper.set_config(
                use_cookies=self.settings.use_browser_cookies,
                cookies_browser=self.settings.cookies_browser,
                proxy=adv.proxy_url if adv.proxy_enabled else "",
                proxy_enabled=adv.proxy_enabled,
            )
            logger.debug("YtDlpHelper-Konfiguration aktualisiert")
        except Exception as e:
            logger.warning(f"YtDlpHelper-Synchronisation fehlgeschlagen: {e}")

        if hasattr(self, "tts_manager") and self.tts_manager is not None:
            try:
                tts = self.tts_manager
                if adv.tts_engine != tts._engine_name:
                    tts.set_engine(adv.tts_engine)
                if adv.tts_voice != tts._voice:
                    tts.set_voice(adv.tts_voice)
                tts.length_scale = adv.tts_length_scale
                tts.sentence_silence = adv.tts_sentence_silence
                logger.debug("TTS-Manager aktualisiert")
            except Exception as e:
                logger.warning(f"TTS-Manager-Update fehlgeschlagen: {e}")

        if (
            hasattr(self, "transcription_engine")
            and self.transcription_engine is not None
        ):
            try:
                te = self.transcription_engine
                if hasattr(te, "set_gpu_acceleration"):
                    te.set_gpu_acceleration(adv.gpu_acceleration)
                if hasattr(te, "settings") and te.settings is not None:
                    te.settings.beam_size = adv.beam_size
                    te.settings.temperature = adv.temperature
                    te.settings.condition_on_previous_text = (
                        adv.condition_on_previous_text
                    )
                    te.settings.no_speech_threshold = adv.no_speech_threshold
                    te.settings.log_prob_threshold = adv.log_prob_threshold
                    te.settings.compression_ratio_threshold = (
                        adv.compression_ratio_threshold
                    )
                    te.settings.best_of = adv.best_of
                    te.settings.patience = adv.patience
                    if hasattr(te.settings, "cpu_threads"):
                        te.settings.cpu_threads = adv.cpu_threads
                    self._safe_set_hotwords(te, adv.hotwords)
                logger.debug("TranscriptionEngine aktualisiert")
            except Exception as e:
                logger.warning(f"TranscriptionEngine-Update fehlgeschlagen: {e}")

        if self.event_bus is not None:
            try:
                self.event_bus.emit(
                    "advanced_settings_applied",
                    {
                        "chunk_duration": adv.chunk_duration,
                        "gpu_acceleration": adv.gpu_acceleration,
                        "translation_engine": adv.translation_engine,
                        "timestamp": time.time(),
                    },
                )
            except Exception as e:
                logger.debug(f"Event-Bus Fehler: {e}")

        try:
            adv.save_to_file()
            self.settings.save_to_file()
            logger.debug("Einstellungen nach _apply_advanced_settings gespeichert")
        except Exception as e:
            logger.warning(f"Konnte Einstellungen nicht speichern: {e}")

        self.update_status("✅ Erweiterte Einstellungen übernommen")

    def _safe_set_hotwords(self, target_obj, hotwords_value: str) -> None:
        """Sicherer Setter für Hotwords – prüft alle Ebenen der Objektkette."""
        if target_obj is None:
            return
        if not hasattr(target_obj, "settings"):
            return
        if target_obj.settings is None:
            return
        if not hasattr(target_obj.settings, "hotwords"):
            return

        try:
            target_obj.settings.hotwords = hotwords_value
        except Exception as e:
            logger = logging.getLogger("dragon")
            logger.warning(f"Konnte Hotwords nicht setzen: {e}")

    def _safe_get_hotwords(self, source_obj) -> str:
        """Sicherer Getter für Hotwords – prüft alle Ebenen der Objektkette."""
        if source_obj is None:
            return ""
        if not hasattr(source_obj, "settings"):
            return ""
        if source_obj.settings is None:
            return ""
        return getattr(source_obj.settings, "hotwords", "")

    def _print_system_diagnostics(self) -> None:
        """Gibt eine detaillierte Systemübersicht für Debug‑Zwecke aus."""
        import platform

        logger.info("=" * 60)
        logger.info("🐉 SYSTEM DIAGNOSTICS (CPU‑Optimized)")
        logger.info("=" * 60)
        logger.info(f"  CPU: {platform.processor()} ({os.cpu_count()} Kerne)")
        logger.info(f"  RAM: {psutil.virtual_memory().total / (1024**3):.1f} GB")
        if hasattr(self, "transcription_engine"):
            engine = self.transcription_engine
            logger.info(f"  Device: {getattr(engine, 'device', 'unknown')}")
            logger.info(f"  Compute Type: {getattr(engine, 'compute_type', 'unknown')}")
            logger.info(
                f"  Model: {
                    engine.get_current_model()
                    if hasattr(engine, 'get_current_model')
                    else 'unknown'
                }"
            )
        else:
            logger.info("  Device: N/A (no engine)")
        logger.info(
            f"  Chunk Duration: {self.advanced_settings.config.CHUNK_DURATION:.1f}s",
        )
        logger.info(f"  Beam Size: {self.advanced_settings.beam_size}")
        logger.info(f"  VAD: {'ON' if self.advanced_settings.vad_filter else 'OFF'}")
        logger.info(
            f"  Enhancement: {
                'ON' if self.advanced_settings.enable_audio_enhancement else 'OFF'
            }"
        )
        logger.info(
            f"  Workers: {
                getattr(self.advanced_settings, 'transcription_workers', '?')
            }"
        )
        logger.info("=" * 60)

    def _test_translation_engine_async(self) -> None:
        """Führt einen asynchronen Test der Übersetzungs‑Engine durch."""
        engine = getattr(self, "translation_engine", None)
        if engine is None:
            if DEBUG_LEVEL >= 2:
                log_debug("init", "Keine Engine vorhanden – überspringe Test")
            return

        if isinstance(engine, DummyTranslationEngine):
            if DEBUG_LEVEL >= 2:
                log_debug("init", "Dummy-Engine – überspringe Test")
            return

        if hasattr(engine, "is_functional") and not engine.is_functional():
            logger.debug("Engine ist nicht funktionsfähig – Test übersprungen")
            return

        if not hasattr(self, "_translation_test_fail_cache"):
            self._translation_test_fail_cache = {}
            self._translation_test_fail_cache_ttl_transient = 60
            self._translation_test_fail_cache_ttl_permanent = 600

        if getattr(self, "_translation_test_running", False):
            logger.debug("Übersetzungs‑Engine‑Test läuft bereits – überspringe")
            return
        self._translation_test_running = True

        cache_key = type(engine).__name__
        now = time.time()
        if cache_key in self._translation_test_fail_cache:
            fail_time, fail_type, fail_reason = self._translation_test_fail_cache[
                cache_key
            ]
            ttl = (
                self._translation_test_fail_cache_ttl_transient
                if fail_type == "transient"
                else self._translation_test_fail_cache_ttl_permanent
            )
            if now - fail_time < ttl:
                logger.debug(
                    "Übersetzungs‑Engine‑Test übersprungen (Negativ‑Cache): %s – %s (Typ: %s, noch %ds)",
                    cache_key,
                    fail_reason,
                    fail_type,
                    int(ttl - (now - fail_time)),
                )
                self._translation_test_running = False
                return
            del self._translation_test_fail_cache[cache_key]

        if DEBUG_LEVEL >= 2:
            log_debug(
                "init",
                f"🔍 Teste Übersetzungs‑Engine {
                    type(engine).__name__
                } im Hintergrund...",
            )

        def _is_valid_translation(original: str, translated: str) -> tuple[bool, str]:
            if not translated or len(translated) < 2:
                return False, "Leere oder zu kurze Übersetzung"
            error_patterns = (
                "error",
                "exception",
                "timeout",
                "500",
                "403",
                "429",
                "unavailable",
                "blocked",
                "quota",
                "exceeded",
                "invalid",
                "not found",
                "permission denied",
            )
            lower = translated.lower()
            for pattern in error_patterns:
                if pattern in lower:
                    return False, f"Fehlerindikator '{pattern}' im Text"
            if len(original) > 0:
                ratio = len(translated) / len(original)
                if ratio < 0.2 or ratio > 5.0:
                    return False, f"Unplausibles Längenverhältnis: {ratio:.2f}"
            words = translated.split()
            if len(words) < 1:
                return False, "Keine Wörter in der Übersetzung"
            alpha_count = sum(c.isalpha() for c in translated)
            if alpha_count > 0:
                latin_ratio = (
                    sum(ord(c) < 128 and c.isalpha() for c in translated) / alpha_count
                )
                if latin_ratio < 0.3 and len(translated) > 10:
                    if original.startswith("Hello world"):
                        return (
                            False,
                            f"Zu viele nicht-lateinische Zeichen: {latin_ratio:.1%}",
                        )
            return True, "OK"

        def _emit_error_safe(
            error_msg: str,
            error_type: str = "",
            status_code: int | None = None,
            hint: str = "",
        ) -> None:
            """Sicherer Aufruf von _emit_translation_error – falls die Methode fehlt."""
            if hasattr(self, "_emit_translation_error") and callable(
                self._emit_translation_error,
            ):
                self._emit_translation_error(error_msg, error_type, status_code, hint)
            else:
                logger.warning(
                    "_emit_translation_error nicht verfügbar – Fehler wird nur geloggt: %s",
                    error_msg,
                )
                self.update_status(f"⚠️ Übersetzung: {error_msg[:60]}", priority=1)

        def _test_worker() -> None:
            try:
                import concurrent.futures
                import time

                test_text = "Hello world, I love to entertain you!"
                test_source = "en"

                logger.info(
                    "🔍 Teste Übersetzungs‑Engine (%s) ...",
                    type(engine).__name__,
                )

                with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
                    future = executor.submit(
                        engine.translate_text,
                        test_text,
                        test_source,
                    )
                    result = future.result(timeout=20.0)

                if result is None:
                    error_msg = f"Engine gab None zurück für '{test_text}'"
                    logger.error("❌ %s", error_msg)
                    self._translation_test_fail_cache[type(engine).__name__] = (
                        time.time(),
                        "permanent",
                        "None_Response",
                    )
                    _emit_error_safe(error_msg)
                    return

                translated = getattr(result, "translated", "")
                if not translated:
                    error_msg = (
                        f"Übersetzungs‑Engine liefert leeres Ergebnis für '{test_text}'"
                    )
                    logger.error("❌ %s", error_msg)
                    self._translation_test_fail_cache[type(engine).__name__] = (
                        time.time(),
                        "permanent",
                        "Empty_Translation",
                    )
                    _emit_error_safe(error_msg)
                    return

                is_valid, reason = _is_valid_translation(test_text, translated)
                if not is_valid:
                    preview = translated[:50] + ("…" if len(translated) > 50 else "")
                    error_msg = f"Ungültige Übersetzung: '{preview}' – Grund: {reason}"
                    logger.error("❌ %s", error_msg)
                    self._translation_test_fail_cache[type(engine).__name__] = (
                        time.time(),
                        "permanent",
                        f"Invalid: {reason}",
                    )
                    _emit_error_safe(error_msg)
                    return

                preview = translated[:50] + ("…" if len(translated) > 50 else "")
                logger.info(
                    "✅ Übersetzungs‑Engine funktioniert: '%s' -> '%s'",
                    test_text,
                    preview,
                )
                self._translation_test_fail_cache.pop(type(engine).__name__, None)
                if self.event_bus is not None:
                    self.event_bus.emit(
                        "translation_engine_ok",
                        {
                            "engine": type(engine).__name__,
                            "test_text": test_text,
                            "translated": translated[:100],
                        },
                    )

            except concurrent.futures.TimeoutError:
                error_msg = (
                    "Timeout nach 15s – Engine reagiert nicht oder ist sehr langsam"
                )
                logger.error("❌ Übersetzungs‑Engine‑Test abgebrochen: %s", error_msg)
                self._translation_test_fail_cache[type(engine).__name__] = (
                    time.time(),
                    "transient",
                    "Timeout",
                )
                _emit_error_safe(error_msg)

            except Exception as e:
                error_msg = str(e)
                error_type = type(e).__name__
                status_code = getattr(e, "response", None)
                status_code = (
                    status_code.status_code
                    if status_code and hasattr(status_code, "status_code")
                    else None
                )

                if status_code in (500, 502, 503, 504):
                    fail_type = "transient"
                    hint = "Serverfehler – temporäres Problem, die Engine wird später automatisch neu getestet"
                elif status_code == 429:
                    fail_type = "transient"
                    hint = "Rate-Limit erreicht – bitte später erneut versuchen oder Engine wechseln"
                elif status_code == 403:
                    fail_type = "permanent"
                    hint = "Zugriff verweigert – bitte API-Key/Proxy prüfen"
                elif (
                    "connection" in error_msg.lower() or "timeout" in error_msg.lower()
                ):
                    fail_type = "transient"
                    hint = "Netzwerkproblem – Verbindung zur Engine-API nicht möglich"
                elif "key" in error_msg.lower() or "quota" in error_msg.lower():
                    fail_type = "permanent"
                    hint = "API-Key oder Kontingent – bitte Einstellungen prüfen"
                else:
                    fail_type = "permanent"
                    hint = "Unbekannter Fehler – bitte Log-Datei prüfen"

                self._translation_test_fail_cache[type(engine).__name__] = (
                    time.time(),
                    fail_type,
                    f"{error_type}: {error_msg[:50]}",
                )
                logger.error(
                    "❌ Übersetzungs‑Engine‑Test fehlgeschlagen: %s (HTTP %s) – %s",
                    error_type,
                    status_code or "N/A",
                    hint,
                    exc_info=DEBUG_LEVEL >= 3,
                )
                _emit_error_safe(error_msg, error_type, status_code, hint)

            finally:
                self._translation_test_running = False

        threading.Thread(
            target=_test_worker,
            daemon=True,
            name="TranslationEngineTest",
        ).start()

        if DEBUG_LEVEL >= 2:
            log_debug(
                "init",
                "Asynchroner Engine-Test gestartet (Thread: TranslationEngineTest)",
            )

    def _is_translation_engine_defective(self, engine_name: str) -> bool:
        """Prüft, ob die Engine kürzlich beim Test fehlgeschlagen ist."""
        if not hasattr(self, "_translation_test_fail_cache"):
            return False
        entry = self._translation_test_fail_cache.get(engine_name)
        if entry is None:
            return False
        fail_time, _ = entry
        return (time.time() - fail_time) < 300

    def _is_valid_translation(original: str, translated: str) -> tuple[bool, str]:
        """Prüft, ob die Übersetzung qualitativ in Ordnung ist.
        Returns: (gültig, Grund)
        """
        if not translated or len(translated) < 2:
            return False, "Leere oder zu kurze Übersetzung"

        error_patterns = (
            "error",
            "exception",
            "timeout",
            "500",
            "403",
            "429",
            "unavailable",
            "blocked",
            "quota",
            "exceeded",
            "invalid",
            "not found",
            "permission denied",
        )
        lower = translated.lower()
        for pattern in error_patterns:
            if pattern in lower:
                return False, f"Fehlerindikator '{pattern}' im Text"

        if len(original) > 0:
            ratio = len(translated) / len(original)
            if ratio < 0.2 or ratio > 5.0:
                return False, f"Unplausibles Längenverhältnis: {ratio:.2f}"

        words = translated.split()
        if len(words) < 1:
            return False, "Keine Wörter in der Übersetzung"

        alpha_count = sum(c.isalpha() for c in translated)
        if alpha_count > 0:
            latin_ratio = (
                sum(ord(c) < 128 and c.isalpha() for c in translated) / alpha_count
            )
            if latin_ratio < 0.3 and len(translated) > 10:
                if original.startswith("Hello world"):
                    return (
                        False,
                        f"Zu viele nicht-lateinische Zeichen: {latin_ratio:.1%}",
                    )

        return True, "OK"

