    def _get_language_flag(self, lang_code: str | None) -> str:
        """Liefert das Flaggen-Emoji für einen Sprachcode.

        Fallback: 🌐 für unbekannte Codes oder None.
        """
        if not lang_code:
            return "🌐"
        code = str(lang_code).strip()
        if code in self._LANG_FLAG_MAP:
            return self._LANG_FLAG_MAP[code]
        base = code.split("-")[0].split("_")[0].lower()
        return self._LANG_FLAG_MAP.get(base, "🌐")

    def _format_transcript_line(self, payload: dict) -> str:
        """Baut eine formatierte Zeile für das Transcript-Widget."""

        if not isinstance(payload, dict):
            try:
                _text = str(payload).strip() if payload is not None else ""
            except Exception as _str_exc:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcript",
                        f"_format_transcript_line: "
                        f"str(payload) fehlgeschlagen "
                        f"(type={type(payload).__name__}): {_str_exc}",
                    )
                return ""

            if DEBUG_LEVEL >= 4:
                log_debug(
                    "transcript",
                    f"_format_transcript_line: non-dict payload "
                    f"(type={type(payload).__name__}, len={len(_text)})",
                )
            return f"{_text}\n" if _text else ""

        text = str(payload.get("text") or "").strip()
        if not text:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "transcript",
                    "_format_transcript_line: leerer Text – überspringe "
                    f"(payload_keys={list(payload.keys())})",
                )
            return ""

        if len(text) > 10_000 and DEBUG_LEVEL >= 3:
            log_debug(
                "transcript",
                f"_format_transcript_line: ungewöhnlich langer Text "
                f"({len(text)} Zeichen) – Anzeige könnte träge werden",
            )

        subtitle_mode = self._is_subtitle_mode()

        _raw_start = payload.get("start")
        _raw_end = payload.get("end")

        start_f: float | None = None
        end_f: float | None = None
        _ts_convert_error: str | None = None

        try:
            if _raw_start is not None:
                start_f = float(_raw_start)
            if _raw_end is not None:
                end_f = float(_raw_end)
        except (TypeError, ValueError) as _exc:
            _ts_convert_error = str(_exc)

        prefix = ""
        _format_kind = "absolute"
        _duration_ms: float | None = None

        if subtitle_mode:
            if _ts_convert_error is not None:
                prefix = f"[{datetime.now().strftime('%H:%M:%S')}] "
                _format_kind = "absolute_error"
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcript",
                        f"_format_transcript_line: "
                        f"Timestamp-Konvertierung fehlgeschlagen "
                        f"(start={_raw_start!r}, end={_raw_end!r}): "
                        f"{_ts_convert_error}",
                    )
            elif (
                start_f is not None
                and end_f is not None
                and end_f > start_f
                and start_f >= 0.0
            ):
                prefix = (
                    f"[{self._format_timestamp(start_f)}"
                    f" → {self._format_timestamp(end_f)}] "
                )
                _format_kind = "video_range"
                _duration_ms = (end_f - start_f) * 1000.0
            elif start_f is not None and end_f is None and start_f >= 0.0:
                prefix = f"[{self._format_timestamp(start_f)}] "
                _format_kind = "video_single"
            else:
                prefix = f"[{datetime.now().strftime('%H:%M:%S')}] "
                _format_kind = "absolute_fallback"

                if DEBUG_LEVEL >= 4 and (start_f is not None or end_f is not None):
                    _reason = "unbekannt"
                    if start_f is not None and start_f < 0.0:
                        _reason = f"start < 0 ({start_f})"
                    elif start_f is not None and end_f is not None and end_f <= start_f:
                        _reason = f"end <= start ({end_f} <= {start_f})"
                    log_debug(
                        "transcript",
                        f"_format_transcript_line: ungültige Timestamps "
                        f"({_reason}) → Fallback auf Uhrzeit",
                    )
        else:
            prefix = f"[{datetime.now().strftime('%H:%M:%S')}] "
            _format_kind = "absolute"

        if DEBUG_LEVEL >= 4:
            _preview_max = 60
            _preview = text[:_preview_max] + "…" if len(text) > _preview_max else text
            _dur_str = f"{_duration_ms:.0f}ms" if _duration_ms is not None else "n/a"
            _ap = getattr(self, "audio_processor", None)
            _ap_val = getattr(_ap, "subtitle_mode", None) if _ap is not None else None
            log_debug(
                "transcript",
                f"_format_transcript_line: "
                f"subtitle_mode={subtitle_mode} (ap={_ap_val}), "
                f"kind={_format_kind}, "
                f"start={start_f!r}, end={end_f!r}, "
                f"duration={_dur_str}, "
                f"prefix='{prefix.strip()}', "
                f"text_len={len(text)}, "
                f"text='{_preview}'",
            )

        return f"{prefix}{text}\n"

    def _is_valid_segment(self, text: str, confidence: float) -> bool:
        """Zentrale Validierung eines Transkriptionssegments."""
        engine = getattr(self, "transcription_engine", None)
        if engine is not None:
            return engine.is_valid_segment(text, confidence)
        return len(text) >= 2

    def _apply_blacklist(self, text: str, lang: str) -> str | None:
        """Wendet die Blacklist an und gibt den gefilterten Text zurück,
        oder None, wenn der Text komplett entfernt wurde.
        """
        blacklist = getattr(self.advanced_settings, "blacklist", [])
        if not blacklist:
            return text
        return self._filter_blacklist_text(text, lang)

    def _is_duplicate_transcription(self, text: str) -> bool:
        """Prüft, ob der Text bereits kürzlich ausgegeben wurde.
        Verwendet normalisierten Stringvergleich und Fuzzy‑Matching.
        """
        with self._duplicate_lock:
            if text == self._last_transcription_text:
                return True

            if len(text) > 20:
                norm = self._normalize_text_for_duplicate(text)
                recent = (
                    list(self._recent_transcriptions)[-3:]
                    if self._recent_transcriptions
                    else []
                )
                for prev in recent:
                    if prev and len(prev) > 20:
                        prev_norm = self._normalize_text_for_duplicate(prev)
                        if norm == prev_norm:
                            return True
                if hasattr(self, "_fuzz") and self._fuzz is not None:
                    for prev in recent:
                        if prev and len(prev) > 10:
                            if (
                                self._fuzz.ratio(
                                    norm,
                                    self._normalize_text_for_duplicate(prev),
                                )
                                > 90
                            ):
                                return True

            self._last_transcription_text = text
            self._recent_transcriptions.append(text)
            return False

    def _format_transcription_entry(
        self,
        text: str,
        lang: str,
        result: TranscriptionResult,
    ) -> str:
        """Erzeugt den formatierten String für das Transkriptions-Widget."""
        _use_video_time = self._is_subtitle_mode()
        _start_raw = getattr(result, "start", None)
        _format_kind = "absolute"

        if _use_video_time and _start_raw is not None:
            try:
                timestamp = self._format_timestamp(_start_raw)
                _format_kind = "video"
            except (TypeError, ValueError) as _exc:
                timestamp = datetime.now().strftime("%H:%M:%S")
                _format_kind = "absolute_fallback"
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcription",
                        f"_format_transcription_entry: "
                        f"Timestamp-Konvertierung fehlgeschlagen "
                        f"(start={_start_raw!r}): {_exc}",
                    )
        else:
            timestamp = datetime.now().strftime("%H:%M:%S")

        lang_display = LANGUAGE_SHORT_CODES.get(lang, lang[:3].upper())
        _line = f"[{timestamp}] [{lang_display}] {text}\n"

        if DEBUG_LEVEL >= 4:
            _preview = text[:60] + "…" if len(text) > 60 else text
            log_debug(
                "transcription",
                f"_format_transcription_entry: "
                f"subtitle_mode={_use_video_time}, "
                f"kind={_format_kind}, "
                f"start={_start_raw!r}, "
                f"timestamp='{timestamp}', "
                f"lang={lang}→{lang_display}, "
                f"text='{_preview}'",
            )

        return _line

    def _queue_transcription(self, formatted: str, clean_text: str) -> None:
        self._mark_text_as_flushed(clean_text)

        if hasattr(self, "queue_manager") and self.queue_manager is not None:
            self.queue_manager.safe_put(
                self.QUEUE_TYPE_TEXT,
                (self.UPDATE_TYPE_TRANSCRIPT, formatted),
                important=False,
            )

        if hasattr(self, "event_bus") and self.event_bus is not None:
            self.event_bus.emit("transcription", {"text": formatted, "raw": clean_text})
        else:
            self._fallback_transcription_insert(formatted)

    def _update_transcription_history(
        self,
        text: str,
        result: TranscriptionResult,
        confidence: float,
    ) -> None:
        """Aktualisiert die Transkriptionshistorie und den Performance‑Monitor."""
        with self._history_lock:
            self.transcript_history.append(result)
        if hasattr(self, "performance_monitor"):
            self.performance_monitor.log_transcription()
        with self._duplicate_lock:
            self._last_transcription_text = text

    def _normalize_text_for_duplicate(self, text: str) -> str:
        """Normalisiert Text für die Duplikaterkennung (ignoriert Satzzeichen, Leerzeichen, Groß-/Kleinschreibung)."""
        text = text.lower()
        text = re.sub(r"[^a-z0-9äöüß]", "", text)
        return text

    def _auto_tts_enabled_for(self, source: str) -> bool:
        """Prüft, ob Auto‑TTS für die angegebene Quelle aktiviert ist."""
        if self.is_shutting_down():
            return False
        settings = getattr(self, "advanced_settings", None)
        if settings is None:
            return False
        if source == "transcript":
            return getattr(settings, "auto_tts_transcript", False)
        if source == "translation":
            return getattr(settings, "auto_tts_translation", False)
        return False

    def _format_timestamp_for_display(
        self,
        result: TranscriptionResult | dict | None,
    ) -> str:
        """Erzeugt einen Zeitstempel für die Anzeige."""
        _subtitle = self._is_subtitle_mode()
        _raw_start: Any = None
        if result is not None:
            if isinstance(result, dict):
                _raw_start = result.get("start")
            else:
                _raw_start = getattr(result, "start", None)

        _result_str: str = ""
        _kind: str = "absolute"

        if _subtitle and _raw_start is not None:
            try:
                _result_str = self._format_timestamp(_raw_start)
                _kind = "video"
            except (TypeError, ValueError) as _exc:
                _result_str = datetime.now().strftime("%H:%M:%S")
                _kind = "absolute_error"
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "timestamp",
                        f"_format_timestamp_for_display: "
                        f"Video-Timestamp-Konvertierung fehlgeschlagen "
                        f"(start={_raw_start!r}): {_exc}",
                    )
        elif _subtitle and _raw_start is None:
            _result_str = datetime.now().strftime("%H:%M:%S")
            _kind = "absolute_fallback"
        else:
            _result_str = datetime.now().strftime("%H:%M:%S")
            _kind = "absolute"

        if DEBUG_LEVEL >= 4:
            _ap = getattr(self, "audio_processor", None)
            _ap_val = getattr(_ap, "subtitle_mode", None) if _ap is not None else None
            _res_type = type(result).__name__ if result is not None else "None"
            log_debug(
                "timestamp",
                f"_format_timestamp_for_display: "
                f"subtitle={_subtitle} (ap={_ap_val}), "
                f"kind={_kind}, "
                f"raw_start={_raw_start!r}, "
                f"result_type={_res_type}, "
                f"timestamp='{_result_str}'",
            )

        return _result_str

    def _mark_text_as_flushed(self, clean_text: str) -> None:
        """Fügt *clean_text* threadsicher in das ``_already_flushed_texts``‑Set
        ein und begrenzt das Set auf 50 000 Einträge, um Speicherlecks bei
        sehr langen Livestreams zu verhindern.
        """
        if not hasattr(self, "_already_flushed_texts"):
            with self._duplicate_lock:
                if not hasattr(self, "_already_flushed_texts"):
                    self._already_flushed_texts = set()
                    log_debug(
                        "gui",
                        "_mark_text_as_flushed: _already_flushed_texts lazy‑initialisiert",
                    )

        with self._duplicate_lock:
            self._already_flushed_texts.add(clean_text)

            if len(self._already_flushed_texts) > 50_000:
                self._already_flushed_texts.clear()
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "gui",
                        "_already_flushed_texts cleared (size limit 50 000 reached).",
                    )

    FLUSHED_TEXT_CACHE_LIMIT: int = 50_000

    def _check_and_mark_text_as_flushed(self, clean_text: str) -> bool:
        """Thread‑sicher prüfen, ob *clean_text* bereits im
        ``_already_flushed_texts``‑Set enthalten ist, und den Text
        andernfalls hinzufügen.
        """
        with self._duplicate_lock:
            if not hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts = set()

            flushed_set = self._already_flushed_texts

            if clean_text in flushed_set:
                if DEBUG_LEVEL >= 3:
                    preview = (
                        clean_text[:50] + "..." if len(clean_text) > 50 else clean_text
                    )
                    log_debug("gui", f"Duplicate text detected: '{preview}'")
                return False

            flushed_set.add(clean_text)

            if len(flushed_set) > self.FLUSHED_TEXT_CACHE_LIMIT:
                flushed_set.clear()
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "gui",
                        f"Cleared _already_flushed_texts (size limit {
                            self.FLUSHED_TEXT_CACHE_LIMIT
                        } reached)",
                    )

            return True

    def _output_and_mark_transcription(self, formatted: str, clean_text: str) -> None:
        """Fügt den formatierten Transkriptionstext in das Widget ein und
        markiert den bereinigten Text im ``_already_flushed_texts``‑Set,
        um spätere Doppelausgaben durch den finalen Flush zu verhindern.
        """
        self._mark_text_as_flushed(clean_text)
        self._safe_transcription_insert(formatted)
        if DEBUG_LEVEL >= 4:
            log_debug(
                "gui",
                "Marked and inserted: '%s…'",
                clean_text[:50],
            )

    def _flush_pending_transcript_segment(self) -> None:
        """Verarbeitet alle in ``_pending_transcript_segments`` verbliebenen"""
        if not hasattr(self, "_pending_transcript_segments"):
            self._pending_transcript_segments: list[tuple[str, float | None, str]] = []
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_pending_transcript_segments lazy initialised",
                )
        if not hasattr(self, "_pending_transcript_lock"):
            self._pending_transcript_lock = threading.Lock()
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_pending_transcript_lock lazy initialised",
                )
        if not hasattr(self, "_already_flushed_texts"):
            self._already_flushed_texts: set[str] = set()

        with self._pending_transcript_lock:
            if not self._pending_transcript_segments:
                return
            snapshot = list(self._pending_transcript_segments)
            self._pending_transcript_segments.clear()

        widget = getattr(self, "transcript_text", None)
        if widget is None or not widget.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "transcript_text widget not available – cannot flush",
                )
            return

        scroll_var = getattr(self, "transcript_scroll_var", None)
        subtitle_mode = self._is_subtitle_mode()

        if DEBUG_LEVEL >= 4:
            _ap = getattr(self, "audio_processor", None)
            _ap_val = getattr(_ap, "subtitle_mode", None) if _ap is not None else None
            log_debug(
                "gui",
                f"_flush_pending_transcript_segment: START "
                f"(subtitle_mode={subtitle_mode}, ap={_ap_val}, "
                f"pending={len(snapshot)})",
            )

        flushed = 0
        skipped_duplicate = 0
        insert_errors = 0

        for text, timestamp, lang in snapshot:
            clean = text.strip()
            if not clean:
                continue

            if not self._check_and_mark_text_as_flushed(clean):
                skipped_duplicate += 1
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        f"  Segment already flushed, skipping: '{clean[:50]}...'",
                    )
                continue

            _kind = "absolute"
            if subtitle_mode:
                if timestamp is not None:
                    try:
                        time_str = self._format_timestamp(timestamp)
                        _kind = "video"
                    except (TypeError, ValueError) as _ts_exc:
                        time_str = datetime.now().strftime("%H:%M:%S")
                        _kind = "absolute_error"
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "gui",
                                f"Timestamp-Konvertierung fehlgeschlagen "
                                f"(ts={timestamp!r}): {_ts_exc}",
                            )
                else:
                    time_str = datetime.now().strftime("%H:%M:%S")
                    _kind = "absolute_fallback"
            else:
                time_str = datetime.now().strftime("%H:%M:%S")

            lang_disp = (
                LANGUAGE_SHORT_CODES.get(lang, lang[:3].upper()) if lang else "??"
            )
            formatted = f"[{time_str}] [{lang_disp}] {clean}\n"

            try:
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True

                widget.insert("end", formatted)

                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")

                flushed += 1

                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        f"Flushed pending: kind={_kind}, lang={lang}, "
                        f"len={len(clean)}, ts='{time_str}'",
                    )

            except tk.TclError as _tclexc:
                insert_errors += 1
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError in pending flush: {_tclexc}")
                break

            except Exception as _exc:
                insert_errors += 1
                logger.warning(
                    "Fehler beim Einfügen eines pending Segments: %s",
                    _exc,
                )
                continue

        if DEBUG_LEVEL >= 2 and (
            flushed > 0 or skipped_duplicate > 0 or insert_errors > 0
        ):
            log_debug(
                "gui",
                f"_flush_pending_transcript_segment: "
                f"{flushed} inserted, "
                f"{skipped_duplicate} duplicates skipped, "
                f"{insert_errors} errors, "
                f"subtitle_mode={subtitle_mode}, "
                f"total pending in snapshot={len(snapshot)}",
            )

    def _clear_pending_buffers(self) -> None:
        """Hilfsmethode, um die beiden Puffer zu leeren.
        Leert den Segments-Puffer und setzt den Einzel-Segment-Puffer zurück.
        """
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        self._pending_transcript_segments.clear()
        self._pending_transcript_segment = None

        if debug_level >= 4:
            logger.debug(
                "Pending transcript buffers cleared.",
                extra={"component": "gui"},
            )

    def _safe_transcription_insert(self, formatted: str) -> None:
        """Fügt den formatierten Transkriptionstext in die GUI ein."""
        if self.is_shutting_down():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_safe_transcription_insert: Shutdown aktiv – Fallback",
                )
            self._fallback_transcription_insert(formatted)
            return

        if not hasattr(self, "queue_manager") or self.queue_manager is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_safe_transcription_insert: Kein QueueManager – Fallback",
                )
            self._fallback_transcription_insert(formatted)
            return

        try:
            success = self.queue_manager.safe_put(
                self.QUEUE_TYPE_TEXT,
                (self.UPDATE_TYPE_TRANSCRIPT, formatted),
            )
            if not success:
                logger.warning("QueueManager safe_put schlug fehl – verwende Fallback")
                self._fallback_transcription_insert(formatted)
        except Exception as e:
            logger.warning("Fehler in QueueManager.safe_put: %s – verwende Fallback", e)
            self._fallback_transcription_insert(formatted)

    def _create_audio_callbacks(self) -> dict:
        """Erstellt die Callback-Funktionen für den AudioProcessor."""
        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        def _on_transcription(result):
            try:
                if result is None:
                    logger.warning("Transcription callback: result is None")
                    return
                if debug_level >= 4:
                    text = getattr(result, "text", str(result))
                    log_debug(
                        "audio",
                        f"📝 Transkription empfangen: {text[:50]}...",
                    )
                handler = getattr(self, "handle_transcription", None)
                if handler is not None:
                    handler(result)
                else:
                    logger.warning("Transcription callback: handle_transcription fehlt")
            except Exception as e:
                logger.error(
                    f"❌ Fehler in transcription_callback: {e}",
                    exc_info=True,
                )

        def _on_translation(result):
            try:
                if result is None:
                    logger.warning("Translation callback: result is None")
                    return
                if debug_level >= 4:
                    translated = getattr(result, "translated", str(result))
                    log_debug(
                        "audio",
                        f"🌐 Übersetzung empfangen: {translated[:50]}...",
                    )
                handler = getattr(self, "handle_translation", None)
                if handler is not None:
                    handler(result)
                else:
                    logger.warning("Translation callback: handle_translation fehlt")
            except Exception as e:
                logger.error(
                    f"❌ Fehler in translation_callback: {e}",
                    exc_info=True,
                )

        def _on_error(error_msg):
            try:
                logger.error(f"❌ Fehler empfangen: {error_msg}")
                handler = getattr(self, "_handle_audio_error", None)
                if handler is not None:
                    handler(error_msg)
            except Exception as e:
                logger.error(
                    f"❌ Fehler in error_callback: {e}",
                    exc_info=True,
                )

        def _on_info(info_msg):
            try:
                if debug_level >= 3:
                    log_debug("audio", f"ℹ️ Info: {info_msg}")
                handler = getattr(self, "handle_info", None)
                if handler is not None:
                    handler(info_msg)
            except Exception as e:
                logger.error(
                    f"❌ Fehler in info_callback: {e}",
                    exc_info=True,
                )

        def _on_finished(result=None):
            try:
                if debug_level >= 3:
                    logger.debug("✅ Audio-Verarbeitung abgeschlossen (Callback)")
                handler = getattr(self, "_on_processing_finished", None)
                if handler is not None:
                    handler(result)
            except Exception as e:
                logger.error(
                    f"❌ Fehler in finished_callback: {e}",
                    exc_info=True,
                )

        return {
            "transcription_callback": _on_transcription,
            "translation_callback": _on_translation,
            "error_callback": _on_error,
            "info_callback": _on_info,
            "finished_callback": _on_finished,
        }

    def _start_audio_processor_with_url(
        self,
        url: str,
        model_name: str,
        src_lang: str,
        target_lang: str,
        is_direct_url: bool = False,
        is_live: bool | None = None,
    ) -> tuple[bool, str | None]:
        """🚀 AUDIOPROCESSOR-START V5.0 – MIT CALLBACK-GARANTIE 🔥"""
        import logging
        import queue
        import subprocess
        import threading
        import time
        from collections import deque

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        extraction_id = f"{int(time.time() * 1000)}"

        logger.debug(
            "🔥🔥🔥 _start_audio_processor_with_url V5.0 - CALLBACK-GARANTIE! 🔥🔥🔥",
        )
        logger.debug(f"[START-AP-{extraction_id}] 🚀 STARTE AUDIOPROCESSOR-START")

        if not hasattr(self, "_ap_start_stats"):
            self._ap_start_stats = {
                "attempts": 0,
                "success": 0,
                "failures": 0,
                "modes_used": {"direct": 0, "pipe": 0, "download_sections": 0},
                "errors": [],
                "circuit_breaker": False,
                "circuit_breaker_reset": 0.0,
                "total_duration_ms": 0.0,
                "last_error": None,
                "start_timestamps": deque(maxlen=20),
            }
            self._ap_start_stats_lock = threading.RLock()
            self._ap_circuit_breaker_failures = 0
            self._ap_circuit_breaker_last_failure = 0.0
            self._ap_circuit_breaker_threshold = 3
            self._ap_circuit_breaker_window = 60.0

        start_time = time.perf_counter()
        step_times = {}

        def _log_step(step: str, msg: str, level: int = 3) -> None:
            if level <= debug_level:
                logger.debug(f"[START-AP-{extraction_id}][{step}] {msg}")

        def _log_info(msg: str) -> None:
            logger.info(f"[START-AP-{extraction_id}] {msg}")

        def _log_warning(msg: str) -> None:
            logger.warning(f"[START-AP-{extraction_id}] ⚠️ {msg}")

        def _log_error(msg: str) -> None:
            logger.error(f"[START-AP-{extraction_id}] ❌ {msg}")

        def _log_critical(msg: str) -> None:
            logger.critical(f"[START-AP-{extraction_id}] 💥 {msg}")

        def _record_metric(key: str, value: Any) -> None:
            with self._ap_start_stats_lock:
                if key == "mode":
                    self._ap_start_stats["modes_used"][value] = (
                        self._ap_start_stats["modes_used"].get(value, 0) + 1
                    )
                elif key == "success":
                    self._ap_start_stats["success"] += 1
                elif key == "failure":
                    self._ap_start_stats["failures"] += 1
                    self._ap_start_stats["last_error"] = value
                elif key == "error_detail":
                    self._ap_start_stats["errors"].append(value)
                    if len(self._ap_start_stats["errors"]) > 20:
                        self._ap_start_stats["errors"].pop(0)

        def _test_url_health(audio_url: str, timeout: float = 5.0) -> tuple[bool, str]:
            """Prüft, ob eine Audio-URL erreichbar ist."""
            if not audio_url:
                return False, "URL ist leer"
            if audio_url.startswith(("http://", "https://")):
                try:
                    import requests

                    response = requests.head(
                        audio_url, timeout=timeout, allow_redirects=True
                    )
                    if response.status_code < 400:
                        return True, f"HTTP {response.status_code}"
                    return False, f"HTTP {response.status_code}"
                except ImportError:
                    pass
                except Exception as e:
                    return False, f"HTTP-HEAD Fehler: {e}"
            try:
                test_cmd = [
                    "ffmpeg",
                    "-i",
                    audio_url,
                    "-t",
                    "1",
                    "-f",
                    "null",
                    "-",
                    "-loglevel",
                    "error",
                ]
                result = subprocess.run(
                    test_cmd,
                    capture_output=True,
                    text=True,
                    timeout=timeout,
                    check=False,
                )
                if result.returncode == 0:
                    return True, "FFmpeg-Test OK"
                stderr = result.stderr[:100] if result.stderr else "unbekannter Fehler"
                return False, f"FFmpeg-Test fehlgeschlagen: {stderr}"
            except Exception as e:
                return False, f"FFmpeg-Test Exception: {e}"

        with self._ap_start_stats_lock:
            now = time.monotonic()
            if self._ap_start_stats["circuit_breaker"]:
                if (
                    now - self._ap_start_stats["circuit_breaker_reset"]
                    > self._ap_circuit_breaker_window
                ):
                    self._ap_start_stats["circuit_breaker"] = False
                    self._ap_circuit_breaker_failures = 0
                    _log_step("CIRCUIT", "Circuit Breaker zurückgesetzt")
                else:
                    _log_warning("Circuit Breaker aktiv – Start verhindert")
                    return False, "Circuit Breaker aktiv (zu viele Fehler)"

        _log_step("VALIDATE", f"URL: {url[:80]}..., is_direct_url={is_direct_url}")
        logger.debug(f"[START-AP-{extraction_id}]   • url: {url}")
        logger.debug(f"[START-AP-{extraction_id}]   • model_name: {model_name}")
        logger.debug(f"[START-AP-{extraction_id}]   • src_lang: {src_lang}")
        logger.debug(f"[START-AP-{extraction_id}]   • target_lang: {target_lang}")
        logger.debug(f"[START-AP-{extraction_id}]   • is_direct_url: {is_direct_url}")

        if not url or not isinstance(url, str):
            _log_error("URL ist leer oder kein String")
            return False, "Ungültige URL"

        url = url.strip()
        if not url:
            _log_error("URL ist nach Bereinigung leer")
            return False, "Ungültige URL"

        is_youtube = "youtube.com" in url.lower() or "youtu.be" in url.lower()

        if is_live is None:
            is_live = bool(getattr(self, "_is_live", False))
            _source = "self._is_live"

            if not is_live:
                _si = getattr(self, "current_stream_info", None)
                if _si is not None:
                    _si_live = getattr(_si, "is_live", None)
                    if _si_live is not None:
                        is_live = bool(_si_live)
                        _source = "current_stream_info"

            if not is_live and is_youtube:
                try:
                    _fm = getattr(self, "ffmpeg_manager", None)
                    if _fm is not None and hasattr(_fm, "_detect_stream_type"):
                        _t0 = time.monotonic()
                        _detect_result = _fm._detect_stream_type(url)
                        _dt_ms = (time.monotonic() - _t0) * 1000.0

                        _detected_live = False
                        if (
                            isinstance(_detect_result, tuple)
                            and len(_detect_result) >= 1
                        ):
                            _detected_live = bool(_detect_result[0])
                        elif isinstance(_detect_result, bool):
                            _detected_live = bool(_detect_result)

                        if _detected_live:
                            is_live = True
                            _source = f"synchroner_detect ({_dt_ms:.0f}ms)"

                        _log_step(
                            "VALIDATE",
                            f"Synchroner Live-Check: {_detected_live} ({_dt_ms:.0f}ms)",
                        )
                except Exception as _live_exc:
                    _log_warning(f"Synchroner Live-Check fehlgeschlagen: {_live_exc}")

            if not is_live:
                is_live = "/live" in url or "live=1" in url
                _source = "url_heuristik"
        else:
            _source = "parameter"

        _log_step(
            "VALIDATE",
            f"is_live={is_live} (Quelle: {_source}), is_youtube={is_youtube}",
        )

        if is_youtube and is_direct_url:
            _log_warning(
                "YouTube-URL als direkte Audio-URL übergeben – erzwinge Pipe-Modus"
            )
            is_direct_url = False
            _log_step("FALLBACK", "✅ is_direct_url auf False gesetzt (Pipe-Modus)")

        ap = getattr(self, "audio_processor", None)
        if ap is None:
            _log_error("AudioProcessor nicht verfügbar")
            return False, "AudioProcessor nicht verfügbar"
        _log_step("AP", f"AudioProcessor gefunden (ID: {id(ap)})")

        engine = getattr(self, "transcription_engine", None)
        if engine is not None and model_name:
            try:
                current_model = engine.get_current_model()
                _log_step("MODEL", f"Aktuell: {current_model}, gewünscht: {model_name}")
                if current_model != model_name:
                    _log_info(f"🔄 Lade Modell '{model_name}' für AudioProcessor...")
                    load_start = time.perf_counter()
                    engine.load_model(model_name, set_active=True)
                    step_times["load_model"] = (time.perf_counter() - load_start) * 1000
                    _log_step(
                        "MODEL", f"✅ Geladen in {step_times['load_model']:.2f}ms"
                    )
                else:
                    _log_step("MODEL", "✅ Modell bereits geladen")
            except Exception as e:
                _log_error(f"Fehler beim Laden des Modells: {e}")
                _record_metric("failure", f"Model load error: {e}")
                return False, f"Modell-Fehler: {e}"
        else:
            _log_step("MODEL", "Kein Modell-Laden erforderlich")

        if hasattr(ap, "gui_queue"):
            ap.gui_queue = self.gui_queue
            _log_step("QUEUE", f"✅ GUI-Queue gesetzt (ID: {id(self.gui_queue)})")
        else:
            try:
                ap.gui_queue = self.gui_queue
                _log_step(
                    "QUEUE",
                    f"✅ GUI-Queue nachträglich gesetzt (ID: {id(self.gui_queue)})",
                )
            except Exception as e:
                _log_warning(f"GUI-Queue konnte nicht gesetzt werden: {e}")

        if hasattr(ap, "gui_queue") and ap.gui_queue is not None:
            _log_step("QUEUE", "✅ GUI-Queue ist verfügbar")
        else:
            _log_warning(
                "⚠️ GUI-Queue ist NICHT verfügbar – Transkriptionen werden nicht angezeigt!"
            )

        if not hasattr(self, "_audio_queue") or self._audio_queue is None:
            self._audio_queue = queue.Queue(maxsize=5000)
            _log_step("QUEUE", "✅ Neue Audio-Queue erstellt (maxsize=5000)")
        else:
            _log_step(
                "QUEUE",
                f"✅ Audio-Queue bereits vorhanden (ID: {id(self._audio_queue)})",
            )

        _log_step("CALLBACKS", "🔄 Erstelle Callbacks mit garantierter Bindung...")

        if hasattr(self, "_on_transcription_text") and callable(
            self._on_transcription_text
        ):
            transcription_callback = self._on_transcription_text
            _log_step(
                "CALLBACKS",
                f"✅ _on_transcription_text ist aufrufbar (ID: {id(transcription_callback)})",
            )
        else:
            _log_critical(
                "❌ _on_transcription_text ist NICHT aufrufbar – Callback kann nicht gesetzt werden!"
            )
            return False, "_on_transcription_text nicht aufrufbar"

        callbacks = self._create_audio_callbacks()
        callbacks["transcription_callback"] = transcription_callback

        _log_step(
            "CALLBACKS",
            f"trans={callbacks['transcription_callback'] is not None}, "
            f"transl={callbacks['translation_callback'] is not None}, "
            f"info={callbacks['info_callback'] is not None}, "
            f"error={callbacks['error_callback'] is not None}",
        )

        _log_step("CALLBACKS", "🛠️ Setze Callback DIREKT im AudioProcessor...")

        try:
            if hasattr(ap, "set_text_callback"):
                ap.set_text_callback(transcription_callback)
                _log_step("CALLBACKS", "  ✅ ap.set_text_callback() aufgerufen")
            else:
                _log_step(
                    "CALLBACKS",
                    "  ⚠️ ap.set_text_callback existiert nicht – verwende direkte Zuweisung",
                )

            if hasattr(ap, "_transcription_callback"):
                ap._transcription_callback = transcription_callback
                _log_step(
                    "CALLBACKS",
                    f"  ✅ ap._transcription_callback direkt gesetzt (ID: {id(ap._transcription_callback)})",
                )
            else:
                ap._transcription_callback = transcription_callback
                _log_step(
                    "CALLBACKS",
                    "  ✅ ap._transcription_callback neu erstellt und gesetzt",
                )

            if hasattr(ap, "_transcription_callback"):
                if ap._transcription_callback is not None:
                    _log_step(
                        "CALLBACKS",
                        f"  ✅ Callback ist gesetzt: {type(ap._transcription_callback).__name__}",
                    )

                    if not callable(ap._transcription_callback):
                        _log_critical(
                            "  ❌ Callback ist gesetzt, aber nicht aufrufbar!"
                        )
                    else:
                        _log_step(
                            "CALLBACKS",
                            "  ✅ Callback ist aufrufbar (ohne Test-Aufruf)",
                        )

                else:
                    _log_critical("  ❌ Callback ist None – versuche erneute Zuweisung")
                    ap._transcription_callback = transcription_callback
                    if ap._transcription_callback is not None:
                        _log_step(
                            "CALLBACKS", "  ✅ Callback nach erneuter Zuweisung gesetzt"
                        )
                    else:
                        _log_critical(
                            "  💥 Callback bleibt None – Transkription wird nicht ankommen!"
                        )
                        return False, "Callback konnte nicht gesetzt werden"

        except Exception as e:
            _log_critical(f"❌ Fehler beim Setzen des Callbacks: {e}")
            return False, f"Callback-Setzung fehlgeschlagen: {e}"

        self._state = "starting"
        if hasattr(self, "_stop_event"):
            self._stop_event.clear()

        if hasattr(self, "stream_info_extractor") and self.stream_info_extractor:
            try:
                _log_step("STREAM-INFO", "Starte synchrone Extraktion...")
                info = self.stream_info_extractor.extract_stream_info(url)
                if info and hasattr(self, "event_bus"):
                    self.event_bus.emit(
                        "stream_info_updated",
                        {
                            "title": (
                                info.title if hasattr(info, "title") else "Unbekannt"
                            ),
                            "channel": (
                                info.uploader
                                if hasattr(info, "uploader")
                                else "Unbekannt"
                            ),
                            "duration": (
                                info.duration if hasattr(info, "duration") else 0
                            ),
                            "platform": (
                                info.platform
                                if hasattr(info, "platform")
                                else "unknown"
                            ),
                            "thumbnail": (
                                info.thumbnail if hasattr(info, "thumbnail") else ""
                            ),
                        },
                    )
                    _log_step(
                        "STREAM-INFO",
                        f"✅ Info extrahiert: {info.title if hasattr(info, 'title') else '?'}",
                    )
            except Exception as e:
                _log_warning(f"Stream-Info-Extraktion fehlgeschlagen: {e}")

        elif is_youtube and hasattr(self, "event_bus"):
            try:
                import yt_dlp

                ydl_opts = {
                    "quiet": True,
                    "no_warnings": True,
                    "extract_flat": True,
                }
                with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                    info = ydl.extract_info(url, download=False)
                    if info:
                        self.event_bus.emit(
                            "stream_info_updated",
                            {
                                "title": info.get("title", "Unbekannter Titel"),
                                "channel": info.get("uploader", "Unbekannter Kanal"),
                                "duration": info.get("duration", 0),
                            },
                        )
                        _log_step(
                            "STREAM-INFO",
                            f"✅ yt-dlp Info: {info.get('title', '?')}",
                        )
            except Exception as e:
                _log_warning(f"yt-dlp Info fehlgeschlagen: {e}")

        if is_direct_url:
            _log_step("URL-TEST", "Prüfe direkte URL auf Erreichbarkeit...")
            health_ok, health_msg = _test_url_health(url, timeout=5.0)
            if health_ok:
                _log_step("URL-TEST", f"✅ URL erreichbar ({health_msg})")
            else:
                _log_warning(f"Direkte URL scheint ungültig: {health_msg}")
                if is_youtube:
                    _log_warning(
                        "Erzwinge Pipe-Modus, da direkte URL nicht funktioniert"
                    )
                    is_direct_url = False
                    _log_step("FALLBACK", "is_direct_url auf False gesetzt")

        with self._ap_start_stats_lock:
            self._ap_start_stats["attempts"] += 1
            self._ap_start_stats["start_timestamps"].append(time.time())

        start_start = time.perf_counter()
        success = False
        final_error = None
        used_mode = "direct" if is_direct_url else "pipe"
        extra_params = {
            "output_queue": getattr(self, "_audio_queue", None),
            "original_url": url,
            "is_live": is_live,
        }

        _log_info(
            f"🚀 Starte AudioProcessor: url={url[:80]}..., "
            f"is_direct_url={is_direct_url}, is_live={is_live}"
        )

        try:
            if hasattr(ap, "_transcription_callback"):
                ap._transcription_callback = transcription_callback
                _log_step(
                    "CALLBACKS",
                    "  🔄 Callback erneut direkt gesetzt (sicherheitshalber)",
                )
        except Exception as e:
            _log_warning(f"Callback-Refresh vor Start fehlgeschlagen: {e}")

        try:
            success = ap.start_processing(
                url=url,
                transcription_callback=transcription_callback,
                translation_callback=callbacks["translation_callback"],
                info_callback=callbacks["info_callback"],
                error_callback=callbacks["error_callback"],
                finished_callback=callbacks["finished_callback"],
                is_direct_url=is_direct_url,
                **extra_params,
            )
            step_times["start_processing"] = (time.perf_counter() - start_start) * 1000

            if success:
                if hasattr(ap, "_transcription_callback"):
                    if ap._transcription_callback is None:
                        _log_critical(
                            "⚠️ Nach start_processing ist der Callback verschwunden! Setze neu..."
                        )
                        ap._transcription_callback = transcription_callback
                        if ap._transcription_callback is not None:
                            _log_step(
                                "CALLBACKS",
                                "  ✅ Callback nach dem Start erfolgreich wiederhergestellt",
                            )
                        else:
                            _log_critical(
                                "  💥 Callback konnte auch nach dem Start nicht wiederhergestellt werden!"
                            )
                    else:
                        _log_step(
                            "CALLBACKS",
                            "✅ Callback ist nach dem Start noch vorhanden",
                        )
                else:
                    _log_warning(
                        "⚠️ ap hat kein _transcription_callback-Attribut nach dem Start"
                    )

        except Exception as e:
            self._state = "idle"
            error_msg = f"Exception beim Starten des AudioProcessors: {e}"
            _log_error(error_msg)
            logger.exception(error_msg)
            _record_metric("failure", f"exception: {e}")
            _record_metric("error_detail", f"exception: {type(e).__name__}: {e}")
            return False, error_msg

        if success:
            self._state = "running"
            with self._ap_start_stats_lock:
                self._ap_circuit_breaker_failures = 0
                self._ap_start_stats["circuit_breaker"] = False
            _record_metric("success", None)
            _record_metric("mode", used_mode)
            total_ms = (time.perf_counter() - start_time) * 1000
            _log_info(
                f"✅ AudioProcessor gestartet (Modus: {used_mode}) in {total_ms:.2f}ms"
            )
            self._ap_start_stats["total_duration_ms"] += total_ms
            return True, None

        self._state = "idle"
        error_msg = f"AudioProcessor start fehlgeschlagen (Modus: {used_mode})"
        _log_error(error_msg)
        _record_metric("failure", error_msg)
        _record_metric("error_detail", f"{used_mode}: {error_msg}")

        if is_youtube and is_direct_url:
            _log_warning(
                "YouTube + direkter Modus fehlgeschlagen – versuche Pipe-Modus"
            )
            try:
                _log_info("🔄 Zweiter Startversuch mit Pipe-Modus...")
                pipe_start = time.perf_counter()
                success = ap.start_processing(
                    url=url,
                    transcription_callback=transcription_callback,
                    translation_callback=callbacks["translation_callback"],
                    info_callback=callbacks["info_callback"],
                    error_callback=callbacks["error_callback"],
                    finished_callback=callbacks["finished_callback"],
                    is_direct_url=False,
                    **extra_params,
                )
                step_times["fallback_pipe"] = (time.perf_counter() - pipe_start) * 1000

                if success:
                    self._state = "running"
                    with self._ap_start_stats_lock:
                        self._ap_circuit_breaker_failures = 0
                        self._ap_start_stats["circuit_breaker"] = False
                    _record_metric("success", None)
                    _record_metric("mode", "pipe_fallback")
                    total_ms = (time.perf_counter() - start_time) * 1000
                    _log_info(
                        f"✅ AudioProcessor im Pipe-Modus gestartet (Fallback) in {total_ms:.2f}ms"
                    )
                    return True, None
                self._state = "idle"
                _log_error("❌ Auch Pipe-Modus fehlgeschlagen")
                _record_metric("failure", "pipe_fallback_failed")
            except Exception as e2:
                self._state = "idle"
                _log_error(f"Fallback-Versuch fehlgeschlagen: {e2}")
                _record_metric("failure", f"pipe_fallback_exception: {e2}")
                final_error = f"Fallback-Fehler: {e2}"

        if is_youtube and not success:
            _log_warning("Versuche letzten Ausweg: Download-Sections-Modus")
            try:
                _log_info("🔄 Dritter Startversuch mit Download-Sections...")
                ds_start = time.perf_counter()
                if hasattr(ap, "_start_download_sections_mode"):
                    success = ap._start_download_sections_mode(
                        url=url,
                        transcription_callback=transcription_callback,
                        translation_callback=callbacks["translation_callback"],
                        info_callback=callbacks["info_callback"],
                        error_callback=callbacks["error_callback"],
                    )
                    step_times["download_sections"] = (
                        time.perf_counter() - ds_start
                    ) * 1000
                    if success:
                        self._state = "running"
                        with self._ap_start_stats_lock:
                            self._ap_circuit_breaker_failures = 0
                            self._ap_start_stats["circuit_breaker"] = False
                        _record_metric("success", None)
                        _record_metric("mode", "download_sections")
                        total_ms = (time.perf_counter() - start_time) * 1000
                        _log_info(
                            f"✅ AudioProcessor im Download-Sections-Modus gestartet in {total_ms:.2f}ms"
                        )
                        return True, None
                else:
                    _log_warning(
                        "Download-Sections-Modus nicht verfügbar – überspringe"
                    )
            except Exception as e3:
                self._state = "idle"
                _log_error(f"Download-Sections-Fallback fehlgeschlagen: {e3}")
                _record_metric("failure", f"download_sections_exception: {e3}")

        with self._ap_start_stats_lock:
            self._ap_circuit_breaker_failures += 1
            if self._ap_circuit_breaker_failures >= self._ap_circuit_breaker_threshold:
                self._ap_start_stats["circuit_breaker"] = True
                self._ap_start_stats["circuit_breaker_reset"] = time.monotonic()
                _log_warning(
                    f"⚡ Circuit Breaker aktiviert "
                    f"({self._ap_circuit_breaker_failures} Fehler)"
                )

        return False, final_error or error_msg

    def _get_direct_audio_url_fallback(self, url: str, timeout: int = 45) -> str | None:
        """Holt die direkte Audio-URL mit yt-dlp -g (Fallback, falls StreamInfoExtractor keine extract_audio_url hat)."""
        import subprocess

        logger = logging.getLogger("dragon")

        try:
            logger.debug(f"[AUDIO] 🔍 yt-dlp -g Fallback für {url[:50]}...")
            cmd = ["yt-dlp", "-f", "bestaudio", "-g", url]
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            if result.returncode == 0:
                audio_url = result.stdout.strip()
                if audio_url and audio_url.startswith(("http", "https")):
                    logger.debug(
                        f"[AUDIO] ✅ yt-dlp -g erfolgreich: {audio_url[:60]}...",
                    )
                    return audio_url
                logger.warning(
                    f"[AUDIO] ⚠️ yt-dlp -g lieferte keine gültige URL: {audio_url}",
                )
            else:
                logger.warning(
                    f"[AUDIO] ⚠️ yt-dlp -g fehlgeschlagen (code {result.returncode})",
                )
            return None
        except subprocess.TimeoutExpired:
            logger.warning(f"[AUDIO] ⚠️ yt-dlp -g Timeout nach {timeout}s")
            return None
        except Exception as e:
            logger.warning(f"[AUDIO] ⚠️ yt-dlp -g Exception: {e}")
            return None

    def _run_audio_processor_with_cleanup(
        self,
        url: str,
        model_name: str,
        src_lang: str,
        target_lang: str,
    ) -> tuple[bool, str | None]:
        """🧠 AUDIOPROCESSOR-START – optimierte Version ohne toten Code."""
        import logging
        import os
        import threading
        import time
        import contextlib
        from collections import deque

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not hasattr(self, "_ap_run_stats"):
            self._ap_run_stats = {
                "attempts": 0,
                "success": 0,
                "failures": 0,
                "modes_used": {"pipe": 0, "direct": 0, "fallback": 0},
                "platforms": {
                    "youtube": 0,
                    "local": 0,
                    "hls": 0,
                    "generic": 0,
                    "unknown": 0,
                },
                "errors": [],
                "last_success": 0.0,
                "last_failure": 0.0,
                "total_duration_ms": 0.0,
                "start_timestamps": deque(maxlen=20),
            }
            self._ap_run_stats_lock = threading.RLock()
            self._ap_run_circuit_breaker_failures = 0
            self._ap_run_circuit_breaker_threshold = 3
            self._ap_run_circuit_breaker_window = 60.0
            self._ap_run_circuit_breaker_reset = 0.0

        start_time = time.perf_counter()
        step_times = {}

        def _log_step(step: str, msg: str, level: int = 3) -> None:
            if level <= debug_level:
                logger.debug(f"[RUN-AP][{step}] {msg}")

        def _log_info(msg: str) -> None:
            logger.info(f"[RUN-AP] {msg}")

        def _log_warning(msg: str) -> None:
            logger.warning(f"[RUN-AP] ⚠️ {msg}")

        def _log_error(msg: str) -> None:
            logger.error(f"[RUN-AP] ❌ {msg}")

        def _record_metric(key: str, value: Any) -> None:
            with self._ap_run_stats_lock:
                if key == "mode":
                    self._ap_run_stats["modes_used"][value] = (
                        self._ap_run_stats["modes_used"].get(value, 0) + 1
                    )
                elif key == "platform":
                    self._ap_run_stats["platforms"][value] = (
                        self._ap_run_stats["platforms"].get(value, 0) + 1
                    )
                elif key == "success":
                    self._ap_run_stats["success"] += 1
                    self._ap_run_stats["last_success"] = time.time()
                elif key == "failure":
                    self._ap_run_stats["failures"] += 1
                    self._ap_run_stats["last_failure"] = time.time()
                    self._ap_run_stats["last_error"] = value
                elif key == "error_detail":
                    self._ap_run_stats["errors"].append(value)
                    if len(self._ap_run_stats["errors"]) > 20:
                        self._ap_run_stats["errors"].pop(0)

        def _safe_get_ap() -> Any:
            """Holt den AudioProcessor sicher mit mehreren Fallbacks."""
            ap = getattr(self, "audio_processor", None)
            if ap is None:
                ap = getattr(self, "_audio_processor", None)
            if ap is None:
                controller = getattr(self, "controller", None)
                if controller is not None:
                    ap = getattr(controller, "audio_processor", None)
            return ap

        def _is_local_file(path: str) -> bool:
            if not path:
                return False
            if path.startswith(("file://", "/", "./", "../")):
                return True
            return bool(os.path.exists(path))

        def _is_hls_stream(path: str) -> bool:
            if not path:
                return False
            return ".m3u8" in path.lower() or "manifest.googlevideo.com" in path.lower()

        def _is_youtube_url(path: str) -> bool:
            if not path:
                return False
            path_lower = path.lower()
            return (
                "youtube.com" in path_lower
                or "youtu.be" in path_lower
                or "googlevideo.com" in path_lower
                or "ytimg.com" in path_lower
                or "ggpht.com" in path_lower
            )

        def _detect_platform(path: str) -> tuple[str, bool]:
            if not path:
                return "unknown", False
            path_lower = path.lower()
            if _is_youtube_url(path):
                is_live = (
                    "/live" in path_lower
                    or "live=1" in path_lower
                    or "is_live=1" in path_lower
                )
                return "youtube", is_live
            if _is_local_file(path):
                return "local", False
            if _is_hls_stream(path):
                return "hls", True
            if "twitch.tv" in path_lower:
                return "twitch", True
            platforms = {
                "kick.com": ("kick", True),
                "rumble.com": ("rumble", False),
                "tiktok.com": ("tiktok", False),
                "facebook.com": ("facebook", False),
                "fb.watch": ("facebook", False),
                "dailymotion.com": ("dailymotion", False),
                "vimeo.com": ("vimeo", False),
                "twitter.com": ("twitter", False),
                "x.com": ("twitter", False),
            }
            for domain, (plat, live) in platforms.items():
                if domain in path_lower:
                    return plat, live
            if path_lower.startswith(("http://", "https://")):
                return "generic", False
            return "unknown", False

        def _extract_audio_url(original_url: str, timeout: int = 45) -> str | None:
            """Extrahiert eine direkte Audio-URL (zentralisiert)."""
            audio_url = None
            try:
                if (
                    hasattr(self, "stream_info_extractor")
                    and self.stream_info_extractor is not None
                ):
                    if hasattr(self.stream_info_extractor, "extract_audio_url"):
                        audio_url = self.stream_info_extractor.extract_audio_url(
                            original_url,
                            prefer_audio=True,
                            timeout=timeout,
                        )
                        if audio_url and audio_url.startswith(("http", "https")):
                            _log_step(
                                "EXTRACT",
                                f"✅ StreamInfoExtractor lieferte URL: {audio_url[:60]}...",
                            )
                        else:
                            audio_url = None
            except Exception as e:
                _log_warning(f"StreamInfoExtractor Fehler: {e}")

            if not audio_url:
                audio_url = self._get_direct_audio_url_fallback(
                    original_url, timeout=timeout
                )

            return audio_url

        with self._ap_run_stats_lock:
            now = time.monotonic()
            if (
                self._ap_run_circuit_breaker_failures
                >= self._ap_run_circuit_breaker_threshold
            ):
                if (
                    now - self._ap_run_circuit_breaker_reset
                    > self._ap_run_circuit_breaker_window
                ):
                    self._ap_run_circuit_breaker_failures = 0
                    _log_step("CIRCUIT", "Circuit Breaker zurückgesetzt")
                else:
                    _log_warning(
                        f"Circuit Breaker aktiv – Start verhindert ({self._ap_run_circuit_breaker_failures} Fehler)",
                    )
                    return False, "Circuit Breaker aktiv (zu viele Fehler)"

        _log_step("VALIDATE", f"URL: {url[:80]}...")
        if not url or not isinstance(url, str):
            _log_error("URL ist leer oder kein String")
            return False, "Ungültige URL"
        url = url.strip()
        if not url:
            _log_error("URL ist nach Bereinigung leer")
            return False, "Ungültige URL"

        platform, is_live = _detect_platform(url)
        is_youtube = platform == "youtube"
        _log_step(
            "PLATFORM",
            f"platform={platform}, is_live={is_live}, is_youtube={is_youtube}",
        )
        _record_metric("platform", platform)

        ap = _safe_get_ap()
        if ap is None:
            _log_error("AudioProcessor nicht verfügbar")
            return False, "AudioProcessor nicht verfügbar"
        _log_step("AP", f"AudioProcessor gefunden (ID: {id(ap)})")

        state = getattr(ap, "state", None)
        if state in ("PROCESSING", "STARTING"):
            _log_warning(
                f"AudioProcessor läuft bereits (state={state}) – überspringe Start",
            )
            return True, None

        if is_youtube:
            original_extract = getattr(ap, "_extract_audio_url", None)
            if original_extract is not None:
                _log_step("HACK", "Überschreibe _extract_audio_url für Pipe-Modus")
                ap._extract_audio_url = lambda u: (None, "pipe")
                ap._original_extract = original_extract
            else:
                _log_warning(
                    "AudioProcessor hat keine _extract_audio_url-Methode – Hack übersprungen",
                )

            _log_info("🎯 YouTube erkannt – starte Pipe-Modus (yt-dlp → ffmpeg)")
            attempt_start = time.perf_counter()

            try:
                success, error = self._start_audio_processor_with_url(
                    url=url,
                    model_name=model_name,
                    src_lang=src_lang,
                    target_lang=target_lang,
                    is_direct_url=False,
                )
                step_times["pipe_attempt"] = (
                    time.perf_counter() - attempt_start
                ) * 1000

                if success:
                    _record_metric("success", None)
                    _record_metric("mode", "pipe")
                    total_ms = (time.perf_counter() - start_time) * 1000
                    _log_info(
                        f"✅ AudioProcessor im Pipe-Modus gestartet in {total_ms:.2f}ms",
                    )

                    with contextlib.suppress(AttributeError, TypeError):
                        if hasattr(ap, "_original_extract"):
                            ap._extract_audio_url = ap._original_extract
                            del ap._original_extract
                    with self._ap_run_stats_lock:
                        self._ap_run_circuit_breaker_failures = 0
                    return True, None

                _log_warning(f"Pipe-Modus fehlgeschlagen: {error}")
                with contextlib.suppress(AttributeError, TypeError):
                    if hasattr(ap, "_original_extract"):
                        ap._extract_audio_url = ap._original_extract
                        del ap._original_extract

                _log_info("🔄 Fallback: Versuche direkte Audio-URL...")
                audio_url = _extract_audio_url(url, timeout=45)

                if audio_url:
                    success2, error2 = self._start_audio_processor_with_url(
                        audio_url,
                        model_name,
                        src_lang,
                        target_lang,
                        is_direct_url=True,
                    )
                    if success2:
                        _record_metric("success", None)
                        _record_metric("mode", "direct")
                        total_ms = (time.perf_counter() - start_time) * 1000
                        _log_info(
                            f"✅ AudioProcessor mit direkter URL gestartet in {total_ms:.2f}ms",
                        )
                        return True, None
                    _log_error(f"Direkter Modus fehlgeschlagen: {error2}")
                    return False, error2 or "Direkter Modus fehlgeschlagen"

                _log_error("Keine Audio-URL extrahierbar – Abbruch")
                return False, "Keine Audio-URL extrahierbar"

            except Exception as e:
                _log_error(f"Exception im Pipe-Modus: {e}")
                with contextlib.suppress(AttributeError, TypeError):
                    if hasattr(ap, "_original_extract"):
                        ap._extract_audio_url = ap._original_extract
                        del ap._original_extract
                return False, f"Pipe-Exception: {e}"

        _log_info("🔍 Versuche direkte Audio-URL zu extrahieren...")
        audio_url = _extract_audio_url(url, timeout=45)

        if audio_url:
            _log_info("🚀 Starte AudioProcessor mit direkter URL")
            try:
                success, error = self._start_audio_processor_with_url(
                    audio_url,
                    model_name,
                    src_lang,
                    target_lang,
                    is_direct_url=True,
                )
                if success:
                    _record_metric("success", None)
                    _record_metric("mode", "direct")
                    total_ms = (time.perf_counter() - start_time) * 1000
                    _log_info(
                        f"✅ AudioProcessor mit direkter URL gestartet in {total_ms:.2f}ms",
                    )
                    return True, None
                _log_warning(f"Direkter Modus fehlgeschlagen: {error}")
            except Exception as e:
                _log_error(f"Exception im direkten Modus: {e}")

        _log_info("🔄 Letzter Ausweg: Starte mit Original-URL (is_direct_url=False)")
        try:
            success, error = self._start_audio_processor_with_url(
                url,
                model_name,
                src_lang,
                target_lang,
                is_direct_url=False,
            )
            if success:
                _record_metric("success", None)
                _record_metric("mode", "fallback")
                total_ms = (time.perf_counter() - start_time) * 1000
                _log_info(
                    f"✅ AudioProcessor mit Original-URL gestartet in {total_ms:.2f}ms",
                )
                return True, None
            _log_error(f"Fallback fehlgeschlagen: {error}")
            return False, error
        except Exception as e:
            _log_error(f"Exception im Fallback: {e}")
            return False, f"Fallback-Exception: {e}"

    def start_processing(self, url: str | None = None) -> None:
        """Startet die Audio-Verarbeitung mit der neuen AudioProcessor-Startlogik."""
        import logging
        import threading
        import time
        import contextlib

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        def _debug(msg: str, level: int = 3) -> None:
            if level <= debug_level:
                logger.debug(f"[START-PROC] {msg}")

        def _error(msg: str) -> None:
            logger.error(f"[START-PROC] ❌ {msg}")

        def _get_gui_var(attr: str, default: str) -> str:
            """Holt sicher einen GUI-Variablen-Wert oder gibt den Default zurück."""
            try:
                var = getattr(self, attr, None)
                if var is not None and hasattr(var, "get"):
                    return var.get()
                return default
            except Exception:
                return default

        _debug("🔥🔥🔥 start_processing AUFGERUFEN (NEUE VERSION) 1")

        if url is None:
            try:
                if hasattr(self, "url_entry") and self.url_entry is not None:
                    url = self.url_entry.get().strip()
                    _debug(f"📋 URL aus GUI: {url[:80] if url else '(leer)'}")
                else:
                    _error("❌ URL-Eingabefeld nicht verfügbar")
                    self.update_status("❌ GUI-Fehler: url_entry nicht gefunden")
                    return
            except Exception as e:
                _error(f"❌ Fehler beim Lesen der URL: {e}")
                self.update_status(f"❌ GUI-Fehler (URL): {str(e)[:50]}")
                return
        else:
            try:
                if hasattr(self, "url_entry") and self.url_entry is not None:
                    self.url_entry.delete(0, tk.END)
                    self.url_entry.insert(0, url)
                    _debug(f"📋 URL aus Parameter: {url[:80]}")
            except Exception:
                _debug("ℹ️ URL konnte nicht in GUI gesetzt werden")

        if not url:
            _error("❌ Keine URL eingegeben")
            self.update_status("❌ Keine URL eingegeben")
            return

        _debug(f"✅ URL validiert: {url[:80]}...")

        model_name = _get_gui_var("model_var", "base")
        _debug(f"📋 Modell aus GUI: {model_name}")

        if not model_name or model_name == "dummy (Demo)":
            model_name = "base"
            _debug("📋 Modell auf 'base' gesetzt (Fallback)")

        if model_name.endswith(".en"):
            corrected = model_name.replace(".en", "")
            try:
                if corrected in Config.WHISPER_MODELS:
                    _debug(
                        f"🔄 Monolinguales Modell '{model_name}' → multilinguales '{corrected}'",
                    )
                    model_name = corrected

                    if hasattr(self, "model_var") and self.model_var is not None:
                        with contextlib.suppress(Exception):
                            self.model_var.set(model_name)
            except (NameError, AttributeError):
                pass

        src_lang_name = _get_gui_var("src_lang_var", "Automatisch")
        target_lang_name = _get_gui_var("lang_var", "Deutsch")

        _debug(f"🎯 Verwende Modell: {model_name}")
        _debug(f"🎯 Quellsprache: {src_lang_name}, Zielsprache: {target_lang_name}")

        self.is_processing = True
        with contextlib.suppress(Exception):
            if hasattr(self, "start_button") and self.start_button:
                self.start_button.config(state=tk.DISABLED)
        with contextlib.suppress(Exception):
            if hasattr(self, "stop_button") and self.stop_button:
                self.stop_button.config(state=tk.NORMAL)
        self.update_status("🔄 Starte Audio-Verarbeitung...")

        def _reset_gui_after_failure():
            """Setzt die GUI nach einem Fehler zurück."""
            try:
                self.is_processing = False
                with contextlib.suppress(Exception):
                    if hasattr(self, "start_button") and self.start_button:
                        self.start_button.config(state=tk.NORMAL)
                with contextlib.suppress(Exception):
                    if hasattr(self, "stop_button") and self.stop_button:
                        self.stop_button.config(state=tk.DISABLED)
                self.update_status("Bereit")
            except Exception as e:
                logger.debug(f"Fehler beim GUI-Reset: {e}")

        def _start_audio():
            try:
                _debug("🚀 Rufe _run_audio_processor_with_cleanup auf...")
                success, error = self._run_audio_processor_with_cleanup(
                    url=url,
                    model_name=model_name,
                    src_lang=src_lang_name,
                    target_lang=target_lang_name,
                )

                if success:
                    _debug("✅ Audio-Verarbeitung erfolgreich gestartet")
                else:
                    _error(f"❌ Audio-Verarbeitung fehlgeschlagen: {error}")
                    self.update_status(f"❌ Fehler: {error[:80]}")
                    _reset_gui_after_failure()
            except Exception as e:
                _error(f"💥 Exception in start_audio: {type(e).__name__}: {e}")
                if debug_level >= 3:
                    logger.exception("Start-Exception:")
                self.update_status(f"❌ Interner Fehler: {str(e)[:50]}")
                _reset_gui_after_failure()

        thread = threading.Thread(
            target=_start_audio,
            daemon=True,
            name=f"AudioStarter-{int(time.time() * 1000)}",
        )
        thread.start()
        _debug("✅ Thread für Audio-Starter gestartet")

    def _handle_audio_error(self, error_msg: str) -> None:
        """Zentrale Fehlerbehandlung für AudioProcessor-Fehler."""
        logger = logging.getLogger("dragon")
        logger.error(f"[AUDIO] Fehler vom AudioProcessor: {error_msg}")

        if hasattr(self, "update_status"):
            self.update_status(f"❌ Audio-Fehler: {error_msg[:60]}")

        if hasattr(self, "event_bus") and self.event_bus is not None:
            try:
                self.event_bus.emit("audio_error", {"error": error_msg})
            except Exception as e:
                logger.debug(f"Event-Bus Fehler: {e}")

    def _insert_transcription_text(self, formatted: str) -> None:
        """Fügt den formatierten Transkriptionstext direkt in das transcript_text‑Widget ein."""
        if not formatted or not isinstance(formatted, str):
            return

        formatted = formatted.strip()
        if not formatted:
            return

        try:
            widget = getattr(self, "transcript_text", None)
            if widget is None:
                return

            if not widget.winfo_exists():
                return

            scroll_var = getattr(self, "transcript_scroll_var", None)
            was_at_end = False
            if scroll_var is not None:
                try:
                    if scroll_var.get():
                        was_at_end = widget.yview()[1] >= 0.99
                except Exception:
                    was_at_end = True
            else:
                was_at_end = True

            widget.insert("end", formatted)

            if was_at_end:
                widget.see("end")

        except tk.TclError:
            pass
        except Exception as e:
            logger.warning(f"Fehler beim direkten Einfügen der Transkription: {e}")

    def _fallback_transcription_insert(self, formatted: str) -> None:
        """Fallback: Fügt den Transkriptionstext direkt per root.after in das
        Text‑Widget ein, ohne den QueueManager zu verwenden.
        """
        if not hasattr(self, "root") or not self.root.winfo_exists():
            return

        def insert():
            try:
                widget = getattr(self, "transcript_text", None)
                if widget is None or not widget.winfo_exists():
                    return
                scroll_var = getattr(self, "transcript_scroll_var", None)
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True
                widget.insert("end", formatted)
                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"TclError in Fallback-Insert: {e}")
            except Exception as e:
                logger.warning(f"Unerwarteter Fehler im Fallback-Insert: {e}")

        self.root.after(0, insert)

    def _is_new_sentence_context(self) -> bool:
        """Gibt zurück, ob der zuletzt ausgegebene Text mit einem Satzendzeichen endete.
        Dies wird verwendet, um zu entscheiden, ob ein neuer Zeitstempel angezeigt werden soll.
        """
        with self._duplicate_lock:
            last = self._last_transcription_text
            if not last:
                return True
            return last[-1] in ".!?。！？"

    def _apply_blacklist_filter(self, text: str, lang: str) -> bool:
        """Wendet die konfigurierte Blacklist auf einen Text an."""
        blacklist = getattr(self.advanced_settings, "blacklist", [])
        if not blacklist:
            return False
        if not text or not text.strip():
            return False
        mode = getattr(self.advanced_settings, "blacklist_mode", "word")
        asian_langs = {"zh", "ja", "ko", "th", "vi", "tl", "yue", "lo", "km", "my"}
        effective_mode = "substring" if lang in asian_langs else mode
        if not hasattr(self, "_blacklist_regex_cache"):
            self._blacklist_regex_cache = {}
            self._blacklist_last_modified = 0
        cache_key = (tuple(sorted(blacklist)), effective_mode)
        if cache_key in self._blacklist_regex_cache:
            regex = self._blacklist_regex_cache[cache_key]
        else:
            if effective_mode == "word":
                escaped_phrases = [re.escape(phrase) for phrase in blacklist if phrase]
                if not escaped_phrases:
                    return False
                pattern = r"\b(" + "|".join(escaped_phrases) + r")\b"
            else:
                escaped_phrases = [re.escape(phrase) for phrase in blacklist if phrase]
                if not escaped_phrases:
                    return False
                pattern = "(" + "|".join(escaped_phrases) + ")"
            try:
                regex = re.compile(pattern, re.IGNORECASE)
            except re.error as e:
                logger.warning(f"Ungültiges Blacklist-Pattern: {e}")
                return False
            self._blacklist_regex_cache[cache_key] = regex
            if len(self._blacklist_regex_cache) > 10:
                oldest = next(iter(self._blacklist_regex_cache))
                del self._blacklist_regex_cache[oldest]
        try:
            match = regex.search(text)
            if match:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "blacklist",
                        f"Filtered '{text[:100]}' (lang={lang}, mode={effective_mode}) – matched: '{match.group(0)}'",
                    )
                return True
        except Exception as e:
            logger.warning(f"Blacklist regex search error: {e}")
            return False
        return False

    def _filter_blacklist_text(self, text: str, lang: str) -> str | None:
        """Entfernt alle konfigurierten Blacklist‑Phrasen aus *text* und gibt den
        bereinigten Text zurück.  Ist das Ergebnis leer oder besteht es nur aus
        Whitespace, wird ``None`` zurückgegeben.
        """
        blacklist = getattr(self.advanced_settings, "blacklist", [])
        if not blacklist or not text:
            return text
        mode = getattr(self.advanced_settings, "blacklist_mode", "word")
        asian_langs = {"zh", "ja", "ko", "th", "vi", "tl", "yue", "lo", "km", "my"}
        effective_mode = mode if lang not in asian_langs else "substring"
        if not hasattr(self, "_blacklist_regex_cache"):
            self._blacklist_regex_cache = {}
        if not hasattr(self, "_blacklist_cache_lock"):
            self._blacklist_cache_lock = threading.RLock()
        cache_key = (tuple(sorted(blacklist)), effective_mode)
        with self._blacklist_cache_lock:
            regex = self._blacklist_regex_cache.get(cache_key)
            if regex is None:
                if effective_mode == "word":
                    pattern = (
                        r"\b(" + "|".join(re.escape(p) for p in blacklist if p) + r")\b"
                    )
                else:
                    pattern = "(" + "|".join(re.escape(p) for p in blacklist if p) + ")"
                try:
                    regex = re.compile(pattern, re.IGNORECASE)
                except re.error as e:
                    logger.warning(
                        "Ungültiges Blacklist‑Pattern: %s. "
                        "Blacklist wird für diese Anfrage ignoriert.",
                        e,
                    )
                    return text
                self._blacklist_regex_cache[cache_key] = regex
                if len(self._blacklist_regex_cache) > 10:
                    oldest_key = next(iter(self._blacklist_regex_cache))
                    del self._blacklist_regex_cache[oldest_key]

        cleaned = regex.sub("", text)
        cleaned = re.sub(r"\s+", " ", cleaned)
        cleaned = re.sub(r"\s([.,!?;:])", r"\1", cleaned)
        cleaned = cleaned.strip()

        if cleaned and re.fullmatch(r"[\s.,;:!?\-–—()\[\]{}0-9]+", cleaned):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "blacklist",
                    f"Rest ist nur Müll ({cleaned!r}) – verworfen",
                )
            return None

        if not cleaned:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "blacklist",
                    f"Text komplett durch Blacklist entfernt: '{text[:100]}'",
                )
            return None
        if DEBUG_LEVEL >= 4:
            log_debug(
                "blacklist",
                f"Blacklist-Filter: '{text[:80]}' → '{cleaned[:80]}'",
            )
        return cleaned

    @gui_error_handler
    def handle_translation(self, result):
        """Verarbeitet ein Übersetzungsergebnis – robust gegen Strings,
        Dicts und None.
        """
        import logging
        import threading
        import time
        from datetime import datetime
        from types import SimpleNamespace

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        call_id = f"TR-{int(time.time() * 1000) % 100000:05d}"
        _t_entry = time.perf_counter()

        _input_type = type(result).__name__
        if debug_level >= 3:
            logger.debug(
                f"[{call_id}] handle_translation ENTRY: "
                f"result type={_input_type}, "
                f"thread={threading.current_thread().name}",
            )

        try:
            _ai_out_len = 0
            if result is not None:
                if hasattr(result, "translated"):
                    _ai_out_len = len(str(result.translated))
                elif isinstance(result, dict):
                    _ai_out_len = len(str(result.get("translated", "")))
            log_ai(
                "TRANSLATE-EMIT",
                tr_id=call_id,
                path=_input_type,
                len=_ai_out_len,
            )
        except Exception:
            pass
        _normalized_path = "unknown"
        try:
            if result is None:
                if debug_level >= 3:
                    logger.debug(f"[{call_id}] result is None – überspringe")
                return

            if hasattr(result, "translated"):
                _normalized_path = "object"

            elif isinstance(result, dict):
                raw_text = result.get("translated", result.get("text", ""))
                if raw_text is None:
                    raw_text = ""
                raw_text = str(raw_text).strip()
                if not raw_text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] Dict enthält leeren Text – überspringe",
                        )
                    return
                result = SimpleNamespace(
                    translated=raw_text,
                    source_lang=result.get("source_lang", "auto"),
                    target_lang=result.get(
                        "target_lang",
                        getattr(self, "target_language", "de"),
                    ),
                    start=result.get("start", None),
                    confidence=result.get("confidence", 0.0),
                )
                _normalized_path = "dict"
                if debug_level >= 2:
                    logger.debug(
                        f"[{call_id}] Dict normalisiert: "
                        f"'{raw_text[:50]}...' "
                        f"(keys={list(result.__dict__.keys())})",
                    )

            elif isinstance(result, str):
                raw_text = result.strip()
                if not raw_text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] result ist leerer String – überspringe",
                        )
                    return
                result = SimpleNamespace(
                    translated=raw_text,
                    source_lang="auto",
                    target_lang=getattr(self, "target_language", "de"),
                    start=None,
                    confidence=0.0,
                )
                _normalized_path = "string_fallback"
                if debug_level >= 2:
                    logger.warning(
                        f"[{call_id}] handle_translation erhielt String "
                        f"statt TranslationResult – "
                        f"Text: '{raw_text[:50]}...' – verwende Fallback.",
                    )

            else:
                try:
                    raw_text = str(result).strip()
                    if not raw_text:
                        if debug_level >= 3:
                            logger.debug(
                                f"[{call_id}] Konvertierung ergab leeren "
                                f"String – überspringe",
                            )
                        return
                    result = SimpleNamespace(
                        translated=raw_text,
                        source_lang="auto",
                        target_lang=getattr(self, "target_language", "de"),
                        start=None,
                        confidence=0.0,
                    )
                    _normalized_path = "unknown_type_converted"
                    if debug_level >= 2:
                        logger.warning(
                            f"[{call_id}] Unbekannter Ergebnis-Typ "
                            f"{_input_type} – konvertiert zu String: "
                            f"'{raw_text[:50]}...'",
                        )
                except Exception as _conv_exc:
                    logger.error(
                        f"[{call_id}] Konvertierung fehlgeschlagen: {_conv_exc}",
                    )
                    return

        except Exception as _norm_exc:
            logger.exception(
                f"[{call_id}] Fehler beim Normalisieren: {_norm_exc}",
            )
            return

        try:
            current_text = getattr(result, "translated", "")
            if current_text is None:
                current_text = ""
            current_text = str(current_text).strip()
            if not current_text:
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] Übersetzungstext ist leer – überspringe",
                    )
                return

            target_lang = getattr(result, "target_lang", "de")
            source_lang = getattr(result, "source_lang", "auto")

            _raw_start = getattr(result, "start", None)
            start_ts = (
                float(_raw_start) if isinstance(_raw_start, (int, float)) else None
            )

            _raw_conf = getattr(result, "confidence", None)
            if isinstance(_raw_conf, (int, float)):
                confidence = float(_raw_conf)
            else:
                confidence = None

            if debug_level >= 3:
                _conf_str = f"{confidence:.2f}" if confidence is not None else "?"
                _start_str = f"{start_ts:.2f}" if start_ts is not None else "?"
                logger.debug(
                    f"[{call_id}] Verarbeitete Übersetzung: "
                    f"'{current_text[:80]}...' "
                    f"(Länge={len(current_text)}, "
                    f"Ziel={target_lang}, Quelle={source_lang}, "
                    f"conf={_conf_str}, start={_start_str}, "
                    f"path={_normalized_path})",
                )

        except Exception as _extract_exc:
            logger.exception(
                f"[{call_id}] Fehler beim Extrahieren der Daten: {_extract_exc}",
            )
            return

        try:
            if hasattr(
                self,
                "_apply_blacklist_filter",
            ) and self._apply_blacklist_filter(current_text, target_lang):
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] Übersetzung durch Blacklist gefiltert",
                    )
                return
        except Exception as _bl_exc:
            logger.warning(f"[{call_id}] Blacklist-Fehler: {_bl_exc}")

        try:
            with self._duplicate_lock:
                if current_text == self._last_translation_text:
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] Duplikat erkannt – ignoriert",
                        )
                    return
                self._last_translation_text = current_text
        except Exception as _dup_exc:
            logger.warning(f"[{call_id}] Duplikat-Lock Fehler: {_dup_exc}")

        try:
            auto_tts_enabled = False
            ap = getattr(self, "audio_processor", None)
            if ap is not None and hasattr(ap, "settings") and ap.settings is not None:
                auto_tts_enabled = bool(
                    getattr(ap.settings, "auto_tts_translation", False),
                )
                if debug_level >= 4:
                    logger.debug(
                        f"[{call_id}] auto_tts_translation from "
                        f"AudioProcessor: {auto_tts_enabled}",
                    )
            else:
                auto_tts_enabled = bool(
                    getattr(
                        self.advanced_settings,
                        "auto_tts_translation",
                        False,
                    ),
                )
                if debug_level >= 4:
                    logger.debug(
                        f"[{call_id}] auto_tts_translation from "
                        f"advanced_settings: {auto_tts_enabled}",
                    )

            if auto_tts_enabled and not self.is_shutting_down():
                if hasattr(self, "tts_manager") and self.tts_manager is not None:
                    self._schedule_tts(current_text, "translation")
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] TTS für Übersetzung geplant",
                        )
                elif debug_level >= 4:
                    logger.debug(
                        f"[{call_id}] TTS manager not available – skip TTS",
                    )
            elif debug_level >= 4:
                if not auto_tts_enabled:
                    logger.debug(
                        f"[{call_id}] auto-TTS translation disabled – skip",
                    )
                elif self.is_shutting_down():
                    logger.debug(
                        f"[{call_id}] shutdown active – skip TTS",
                    )
        except Exception as _tts_exc:
            logger.warning(f"[{call_id}] TTS-Fehler: {_tts_exc}")

        try:
            if hasattr(self, "performance_monitor"):
                self.performance_monitor.log_translation()
            with self._history_lock:
                self.translation_history.append(result)
        except Exception as _hist_exc:
            logger.warning(
                f"[{call_id}] Historie/Performance-Fehler: {_hist_exc}",
            )

        _subtitle_mode = self._is_subtitle_mode()
        _kind = "absolute"
        formatted = ""

        try:
            lang_code = LANGUAGE_SHORT_CODES.get(
                target_lang,
                target_lang[:3].upper(),
            )

            if _subtitle_mode:
                if start_ts is not None:
                    try:
                        timestamp = self._format_timestamp(start_ts)
                        _kind = "video"
                    except (TypeError, ValueError) as _ts_exc:
                        timestamp = datetime.now().strftime("%H:%M:%S")
                        _kind = "absolute_error"
                        if debug_level >= 3:
                            logger.debug(
                                f"[{call_id}] Video-Timestamp-Konvertierung "
                                f"fehlgeschlagen (start={start_ts!r}): "
                                f"{_ts_exc}",
                            )
                else:
                    timestamp = datetime.now().strftime("%H:%M:%S")
                    _kind = "absolute_fallback"
            else:
                timestamp = datetime.now().strftime("%H:%M:%S")
                _kind = "absolute"

            formatted = f"[{timestamp}] [{lang_code}] {current_text}\n"

            if debug_level >= 4:
                _ap = getattr(self, "audio_processor", None)
                _ap_val = (
                    getattr(_ap, "subtitle_mode", None) if _ap is not None else None
                )
                _gui_val = getattr(self, "subtitle_mode", None)
                logger.debug(
                    f"[{call_id}] Format: kind={_kind}, "
                    f"subtitle_mode={_subtitle_mode} "
                    f"(ap={_ap_val}, gui={_gui_val}), "
                    f"timestamp='{timestamp}', lang={lang_code}",
                )

        except Exception as _fmt_exc:
            logger.error(f"[{call_id}] Formatierungsfehler: {_fmt_exc}")
            formatted = current_text + "\n"
            _kind = "format_error"

        def _update_gui():
            try:
                widget = getattr(self, "translation_text", None)
                if widget is not None and widget.winfo_exists():
                    scroll_var = getattr(
                        self,
                        "translation_scroll_var",
                        None,
                    )
                    was_at_end = False
                    if scroll_var and scroll_var.get():
                        try:
                            was_at_end = widget.yview()[1] >= 0.99
                        except Exception:
                            was_at_end = True
                    widget.insert("end", formatted)
                    if was_at_end:
                        widget.see("end")
                else:
                    fallback_widget = getattr(
                        self,
                        "transcript_text",
                        None,
                    )
                    if fallback_widget and fallback_widget.winfo_exists():
                        fallback_widget.insert(
                            "end",
                            f"🌐 {current_text}\n",
                        )
                        fallback_widget.see("end")
            except Exception as _gui_exc:
                logger.error(
                    f"[{call_id}] GUI-Update fehlgeschlagen: {_gui_exc}",
                )

        self._safe_gui_update(_update_gui, important=True)

        if debug_level >= 3:
            _elapsed_ms = (time.perf_counter() - _t_entry) * 1000.0
            logger.debug(
                f"[{call_id}] handle_translation EXIT "
                f"(path={_normalized_path}, kind={_kind}, "
                f"{_elapsed_ms:.1f}ms)",
            )

    def _insert_translation_text(
        self,
        formatted: str,
        force_direct: bool = False,
        important: bool = False,
    ) -> None:
        """Fügt den formatierten Übersetzungstext in die GUI ein."""
        if not formatted or not formatted.strip():
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "_insert_translation_text: leerer Text – ignoriert")
            return

        if DEBUG_LEVEL >= 3:
            log_debug(
                "gui",
                "_insert_translation_text: text_len=%d, force_direct=%s, important=%s, queue_manager_available=%s",
                len(formatted),
                force_direct,
                important,
                hasattr(self, "queue_manager") and self.queue_manager is not None,
            )

        qm_available = (
            hasattr(self, "queue_manager")
            and self.queue_manager is not None
            and not force_direct
            and not self.is_shutting_down()
        )

        if qm_available:
            try:
                success = self.queue_manager.safe_put(
                    self.QUEUE_TYPE_TEXT,
                    (self.UPDATE_TYPE_TRANSLATION, formatted),
                    important=important,
                )
                if success:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "gui",
                            "safe_put via QueueManager: success=True, queue_size=%d",
                            (
                                self.queue_manager.text_queue.qsize()
                                if hasattr(self.queue_manager, "text_queue")
                                else -1
                            ),
                        )
                    return
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "gui",
                        "safe_put via QueueManager: success=False – falling back to direct insert",
                    )
            except Exception as e:
                logger.warning(
                    "Fehler in QueueManager.safe_put für Übersetzung: %s – verwende Fallback",
                    e,
                )
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "gui",
                        "QueueManager safe_put failed",
                        e,
                        level="debug",
                    )

        if not hasattr(self, "root") or not self.root.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "root window not available – cannot insert translation",
                )
            return

        def direct_insert() -> None:
            """Hilfsfunktion, die im Hauptthread ausgeführt wird."""
            try:
                widget = getattr(self, "translation_text", None)
                if widget is None:
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "translation_text widget not found")
                    return
                if not widget.winfo_exists():
                    if DEBUG_LEVEL >= 3:
                        log_debug("gui", "translation_text widget destroyed")
                    return

                scroll_var = getattr(self, "translation_scroll_var", None)
                was_at_end = False
                if scroll_var and scroll_var.get():
                    try:
                        was_at_end = widget.yview()[1] >= 0.99
                    except Exception:
                        was_at_end = True

                widget.insert("end", formatted)

                if scroll_var and scroll_var.get() and was_at_end:
                    widget.see("end")

                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        "Direct translation insert succeeded, text_len=%d",
                        len(formatted),
                    )
            except tk.TclError as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("gui", f"Direct insert TclError: {e}")
            except Exception as e:
                logger.error("Direct insert unexpected error: %s", e)

        try:
            self.root.after_idle(direct_insert)
            if DEBUG_LEVEL >= 4:
                log_debug("gui", "Direct insert scheduled via after_idle")
        except tk.TclError as e:
            if DEBUG_LEVEL >= 3:
                log_debug("gui", f"after_idle scheduling failed: {e}")
            direct_insert()

    def _adaptive_window_size(self) -> None:
        """Passt die Fenstergröße an die Bildschirmauflösung an (mind. 800×600)."""
        try:
            screen_w = self.root.winfo_screenwidth()
            screen_h = self.root.winfo_screenheight()
            usable_w = int(screen_w * 0.85)
            usable_h = int(screen_h * 0.80)
            width = min(950, usable_w)
            height = min(700, usable_h)
            self.root.geometry(f"{width}x{height}")
            self.root.minsize(800, 600)
        except Exception as e:
            logger.warning(f"Could not adapt window size: {e}")

    @gui_error_handler
    def handle_info(self, info_msg: str) -> None:
        """Zeigt eine Info-Meldung in der Statusleiste an."""
        if info_msg is None:
            return

        if isinstance(info_msg, dict):
            short = "📡 Stream-Informationen werden eingeholt …"
            self._safe_gui_update(
                lambda: self.update_status(f"ℹ️ {short}"),
                important=True,
            )
            return

        if not isinstance(info_msg, str):
            return

        text = info_msg.strip()
        if not text:
            return

        _looks_like_stream_dump = ("'title':" in text or '"title":' in text) and (
            "'channel':" in text
            or '"channel":' in text
            or "'uploader':" in text
            or '"uploader":' in text
        )
        if _looks_like_stream_dump:
            text = "📡 Stream-Informationen werden verarbeitet …"
        elif len(text) > 80:
            text = text[:77] + "…"

        self._safe_gui_update(
            lambda: self.update_status(f"ℹ️ {text}"),
            important=True,
        )

    @gui_error_handler
    def handle_error(self, error_msg: str, exc: Exception | None = None) -> None:
        """Zentrale Fehlerbehandlung mit Konsole‑Logging, Kategorisierung und GUI-Update."""
        if hasattr(self, "_handling_error") and self._handling_error:
            logger.debug(f"⚠️ Rekursive Fehlerbehandlung unterbunden: {error_msg}")
            return
        self._handling_error = True

        try:
            if exc is not None:
                logger.error(f"❌ GUI-Fehler: {error_msg}", exc_info=exc)
            else:
                logger.error(f"❌ GUI-Fehler: {error_msg}")

            import sys

            sys.stderr.write(f"[ERROR] {error_msg}\n")
            if exc is not None:
                sys.stderr.write(f"  └─ Exception: {type(exc).__name__}: {exc}\n")
            sys.stderr.flush()

            if self.controller is None:
                logger.debug("Fehler ignoriert (Controller nicht vorhanden)")
                return

            try:
                state = self.controller.state
                if state in (
                    WhisperController.State.STOPPING,
                    WhisperController.State.IDLE,
                ):
                    logger.debug(f"Fehler ignoriert (Controller-Zustand: {state.name})")
                    return
            except AttributeError:
                pass

            hint = self._get_error_hint(error_msg, exc)
            if hint:
                logger.info(f"💡 Hinweis: {hint}")

            if hasattr(self, "root") and self.root.winfo_exists():
                self._safe_gui_update(
                    lambda: self._handle_error_gui(error_msg, hint),
                    important=True,
                )
            else:
                logger.debug("GUI root nicht verfügbar – GUI-Update übersprungen")

            if self._is_fatal_error(error_msg, exc):
                logger.critical("🚨 Schwerwiegender Fehler – Controller wird gestoppt.")
                if hasattr(self.controller, "stop_processing"):
                    self.controller.stop_processing(wait=False)
                if self.event_bus is not None:
                    self.event_bus.emit("fatal_error", {"error": error_msg})

            if self.event_bus is not None:
                try:
                    self.event_bus.emit(
                        "error_detailed",
                        {
                            "message": error_msg,
                            "exception": str(exc) if exc else None,
                            "timestamp": time.time(),
                        },
                    )
                except Exception as e:
                    logger.debug(
                        f"Event-Bus Fehler beim Senden von error_detailed: {e}",
                    )

        except Exception as e:
            logger.critical(
                "Kritischer Fehler in der Fehlerbehandlung selbst: %s",
                e,
                exc_info=True,
            )
        finally:
            self._handling_error = False

    def _get_error_hint(
        self,
        error_msg: str,
        exc: Exception | None = None,
    ) -> str | None:
        """Analysiert eine Exception und gibt eine benutzerfreundliche Handlungsempfehlung zurück."""
        error_lower = str(exc).lower() if exc is not None else error_msg.lower()
        if any(
            kw in error_lower
            for kw in ("timeout", "connection", "reset", "refused", "unreachable")
        ):
            if "proxy" in error_lower or "socks" in error_lower:
                return (
                    "Proxy‑Verbindung fehlgeschlagen. Bitte prüfen Sie:\n"
                    "  • Proxy‑Einstellungen in den erweiterten Einstellungen\n"
                    "  • Ob der Proxy‑Server läuft und erreichbar ist"
                )
            if "ollama" in error_lower or "11434" in error_lower:
                return (
                    "Ollama‑Server nicht erreichbar. Bitte prüfen Sie:\n"
                    "  • Ist Ollama installiert? (ollama --version)\n"
                    "  • Läuft der Server? (ollama serve)"
                )
            return (
                "Netzwerkverbindung unterbrochen. Bitte prüfen Sie:\n"
                "  • Internetverbindung\n"
                "  • Firewall‑Einstellungen\n"
                "  • Ob die Stream‑URL noch gültig ist"
            )

        if any(kw in error_lower for kw in ("ffmpeg", "codec", "stream")):
            return (
                "FFmpeg‑Fehler beim Dekodieren des Streams. Mögliche Ursachen:\n"
                "  • Der Stream verwendet ein ungewöhnliches Audio‑Format\n"
                "  • Die Verbindung ist instabil\n"
                "  • FFmpeg ist nicht korrekt installiert"
            )

        if any(kw in error_lower for kw in ("cuda", "out of memory")):
            return (
                "GPU‑Speicher (VRAM) ist erschöpft. Das Programm wechselt automatisch\n"
                "auf CPU‑Betrieb oder versucht ein kleineres Modell."
            )

        if any(kw in error_lower for kw in ("deep_translator", "google", "translate")):
            if "key" in error_lower or "quota" in error_lower:
                return (
                    "Google Translate API‑Problem (möglicherweise Kontingent erschöpft).\n"
                    "Wechseln Sie zu einer anderen Übersetzungs‑Engine in den Einstellungen."
                )
            return "Übersetzungs‑Engine temporär nicht verfügbar – das Programm wird automatisch wiederholen."

        if "reconnect" in error_lower:
            return "Der Stream wurde neu verbunden, aber die Verbindung ist instabil. Bitte prüfen Sie Ihre Netzwerkverbindung."

        return None

    @gui_error_handler
    def _handle_error_gui(self, error_msg: str, hint: str | None = None) -> None:
        """Aktualisiert die GUI-Statuszeile mit Fehlermeldung und optionalem Hinweis.
        Optimiert mit Rekursionsschutz, Shutdown-Prüfung und sicherer Controller-Freigabe.
        """
        if hasattr(self, "_handling_error") and self._handling_error:
            logger.debug(f"⚠️ Rekursive Fehlerbehandlung unterbunden: {error_msg}")
            return
        self._handling_error = True

        try:
            if self.is_shutting_down():
                logger.debug(f"⚠️ Shutdown aktiv – Fehler ignoriert: {error_msg}")
                return

            MAX_DISPLAY_LEN = 120
            display_msg = (
                error_msg
                if len(error_msg) <= MAX_DISPLAY_LEN
                else error_msg[: MAX_DISPLAY_LEN - 3] + "..."
            )

            display = f"❌ {display_msg}"
            if hint:
                hint_short = hint if len(hint) <= 60 else hint[:57] + "..."
                display += f" – {hint_short}"

            with self._status_lock:
                if self._last_status_message != display:
                    logger.error(f"GUI-Fehler: {error_msg}")
                    self.update_status(display)
                else:
                    logger.debug(f"Duplikat-Fehler ignoriert: {error_msg[:60]}")

            if hasattr(self, "controller") and self.controller is not None:
                if self.controller.state not in (
                    WhisperController.State.IDLE,
                    WhisperController.State.STOPPING,
                ):
                    try:
                        if not getattr(self.controller, "_stop_in_progress", False):
                            self.controller.stop_processing(wait=False)
                    except Exception as e:
                        logger.debug(
                            f"Controller-Stop im Fehlerfall fehlgeschlagen: {e}",
                        )
        finally:
            self._handling_error = False

    def _is_fatal_error(self, error_msg: str, exc: Exception | None) -> bool:
        """Entscheidet, ob der Fehler so schwerwiegend ist, dass der Controller gestoppt werden muss."""
        if exc is None:
            return False
        error_lower = str(exc).lower()
        fatal_keywords = ("out of memory", "segmentation fault", "critical", "fatal")
        return any(kw in error_lower for kw in fatal_keywords)

    @gui_error_handler
    def _on_controller_state(self, state_name: str) -> None:
        def update():
            if state_name == "PROCESSING":
                self._safe_widget_config("start_button", state="disabled")
                self._safe_widget_config("stop_button", state="normal")
            elif state_name in ("IDLE", "ERROR"):
                self._safe_widget_config("start_button", state="normal")
                self._safe_widget_config("stop_button", state="disabled")

        self._safe_gui_update(update, important=True)

    @gui_error_handler
    def _on_model_changed(self, data: dict) -> None:
        """Wird aufgerufen, wenn die TranscriptionEngine das aktive Modell wechselt."""
        import logging
        import threading
        import time
        import tkinter as tk

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if self.is_shutting_down():
            if debug_level >= 3:
                logger.debug(
                    "_on_model_changed: Shutdown aktiv – ignoriert",
                    extra={"component": "gui"},
                )
            return

        if data is None or not isinstance(data, dict):
            logger.warning(
                "_on_model_changed: data ist None oder kein Dict – ignoriert",
                extra={"component": "gui"},
            )
            return

        actual = data.get("actual")
        requested = data.get("requested")
        fallback = data.get("fallback_occurred", False)

        if (
            not actual
            or not isinstance(actual, str)
            or actual.strip().lower() in ("none", "null", "undefined", "")
        ):
            logger.warning(
                "_on_model_changed: Ungültiger Modellname '%s' – setze Fallback auf 'base'",
                actual,
                extra={"component": "gui"},
            )
            actual = "base"
            fallback = True
            requested = requested or "unknown"

        actual = actual.strip()

        try:
            available_models = get_available_whisper_models()
            if actual not in available_models:
                logger.warning(
                    "_on_model_changed: Modell '%s' nicht in verfügbarer Liste – setze auf 'base'",
                    actual,
                    extra={"component": "gui"},
                )
                actual = "base"
                fallback = True
                requested = requested or "unknown"
        except Exception as e:
            logger.debug(
                "_on_model_changed: Konnte verfügbare Modelle nicht abrufen: %s",
                e,
                extra={"component": "gui"},
            )

        def update_gui():
            """Führt die eigentlichen GUI-Updates im Hauptthread durch."""
            try:
                if (
                    self.is_shutting_down()
                    or not hasattr(self, "root")
                    or not self.root.winfo_exists()
                ):
                    if debug_level >= 3:
                        logger.debug(
                            "_on_model_changed: GUI nicht mehr verfügbar – Updates abgebrochen",
                            extra={"component": "gui"},
                        )
                    return

                if hasattr(self, "model_var") and self.model_var is not None:
                    try:
                        current = self.model_var.get()
                        if current != actual:
                            self.model_var.set(actual)
                            if debug_level >= 3:
                                logger.debug(
                                    f"Modell-ComboBox aktualisiert: {current} → {actual}",
                                    extra={"component": "gui"},
                                )
                    except tk.TclError as e:
                        logger.debug(
                            "_on_model_changed: TclError beim Setzen von model_var: %s",
                            e,
                            extra={"component": "gui"},
                        )
                elif debug_level >= 4:
                    logger.debug(
                        "_on_model_changed: model_var nicht verfügbar",
                        extra={"component": "gui"},
                    )

                if (
                    hasattr(self, "vram_unload_btn")
                    and self.vram_unload_btn is not None
                ):
                    try:
                        if self.vram_unload_btn.winfo_exists():
                            self.vram_unload_btn.config(state="normal")
                            if debug_level >= 4:
                                logger.debug(
                                    "VRAM-Button aktiviert",
                                    extra={"component": "gui"},
                                )
                    except tk.TclError as e:
                        logger.debug(
                            "_on_model_changed: TclError beim Aktivieren des VRAM-Buttons: %s",
                            e,
                            extra={"component": "gui"},
                        )
                elif debug_level >= 4:
                    logger.debug(
                        "_on_model_changed: vram_unload_btn nicht verfügbar",
                        extra={"component": "gui"},
                    )

                if hasattr(self, "start_button") and self.start_button is not None:
                    try:
                        if self.start_button.winfo_exists():
                            if actual and actual != "none" and actual != "dummy (Demo)":
                                self.start_button.config(state="normal")
                                if debug_level >= 4:
                                    logger.debug(
                                        "Start-Button aktiviert (Modell verfügbar)",
                                        extra={"component": "gui"},
                                    )
                            else:
                                self.start_button.config(state="disabled")
                                if debug_level >= 4:
                                    logger.debug(
                                        "Start-Button deaktiviert (kein gültiges Modell)",
                                        extra={"component": "gui"},
                                    )
                    except tk.TclError as e:
                        logger.debug(
                            "_on_model_changed: TclError beim Setzen des Start-Buttons: %s",
                            e,
                            extra={"component": "gui"},
                        )

                if hasattr(self, "update_status") and callable(self.update_status):
                    try:
                        if fallback and requested and requested != actual:
                            self.update_status(
                                f"⚠️ Modell '{requested}' nicht verfügbar – verwende '{actual}'",
                                priority=1,
                            )
                            logger.warning(
                                f"Modell-Fallback in GUI: {requested} → {actual}",
                                extra={"component": "gui"},
                            )
                            if self.event_bus is not None:
                                try:
                                    self.event_bus.emit(
                                        "model_fallback_used",
                                        {
                                            "requested": requested,
                                            "actual": actual,
                                            "timestamp": time.time(),
                                        },
                                    )
                                except Exception as e:
                                    logger.debug(
                                        "Event-Bus Fehler in _on_model_changed: %s",
                                        e,
                                        extra={"component": "gui"},
                                    )
                        elif actual and actual != "none" and actual != "dummy (Demo)":
                            self.update_status(
                                f"✅ Modell '{actual}' bereit – START drücken zum Transkribieren",
                            )
                        else:
                            self.update_status(
                                "⚠️ Kein gültiges Modell geladen – bitte Modell auswählen",
                                priority=1,
                            )
                    except Exception as e:
                        logger.warning(
                            "_on_model_changed: Fehler beim Setzen der Statusmeldung: %s",
                            e,
                            extra={"component": "gui"},
                        )

                if hasattr(self, "_start_system_monitoring") and callable(
                    self._start_system_monitoring,
                ):
                    try:
                        self._start_system_monitoring()
                        if debug_level >= 4:
                            logger.debug(
                                "System-Monitoring neu gestartet",
                                extra={"component": "gui"},
                            )
                    except Exception as e:
                        logger.debug(
                            "_on_model_changed: Fehler beim Neustart des System-Monitorings: %s",
                            e,
                            extra={"component": "gui"},
                        )

            except Exception as e:
                logger.exception(
                    "_on_model_changed: Unerwarteter Fehler im GUI-Update-Block: %s",
                    e,
                    extra={"component": "gui"},
                )

        try:
            if hasattr(self, "_safe_gui_update") and callable(self._safe_gui_update):
                self._safe_gui_update(update_gui, important=True)
                if debug_level >= 4:
                    logger.debug(
                        "_on_model_changed: GUI-Update über _safe_gui_update geplant",
                        extra={"component": "gui"},
                    )
            elif threading.current_thread() is threading.main_thread():
                update_gui()
            elif hasattr(self, "root") and self.root.winfo_exists():
                self.root.after(0, update_gui)
                if debug_level >= 4:
                    logger.debug(
                        "_on_model_changed: GUI-Update über root.after geplant",
                        extra={"component": "gui"},
                    )
            else:
                logger.warning(
                    "_on_model_changed: Kein root-Fenster verfügbar – GUI-Update verworfen",
                    extra={"component": "gui"},
                )
        except Exception as e:
            logger.exception(
                "_on_model_changed: Unerwarteter Fehler beim Planen des GUI-Updates: %s",
                e,
                extra={"component": "gui"},
            )

        if debug_level >= 3:
            logger.debug(
                "_on_model_changed abgeschlossen: actual=%s, requested=%s, fallback=%s",
                actual,
                requested,
                fallback,
                extra={"component": "gui"},
            )

    @gui_error_handler
    def _on_processing_state_changed(self, is_processing: bool) -> None:
        self.is_processing = is_processing

        def update():
            self._safe_widget_config(
                "start_button",
                state="disabled" if is_processing else "normal",
            )
            self._safe_widget_config(
                "stop_button",
                state="normal" if is_processing else "disabled",
            )
            if not is_processing:
                self.update_status("✅ READY")

        self._safe_gui_update(update, important=True)

    @gui_error_handler
    def _on_file_finished(self, _=None) -> None:
        """Callback for the normal end of a file (e.g., YouTube VOD)."""
        logger.info("📁 File processing finished normally")

        if not hasattr(self, "root") or not self.root.winfo_exists():
            logger.warning(
                "⚠️ GUI nicht verfügbar – File-Finished-Callback abgebrochen",
            )
            return

        if threading.current_thread() is not threading.main_thread():
            logger.error(
                "_on_file_finished außerhalb des GUI‑Threads aufgerufen – ignoriert",
            )
            return

        try:
            self._flush_pending_transcript_segment()

            if hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts.clear()
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "gui",
                        "_already_flushed_texts cleared after file finished",
                    )
        finally:
            self._reset_progress()
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_on_file_finished: progress bar reset in finally block",
                )

        if getattr(self, "_shutting_down", False):
            logger.info("GUI im Shutdown – Auto-Save wird nicht ausgeführt")
            return

        if self.settings.auto_save_on_completion:
            if not (hasattr(self, "transcript_history") and self.transcript_history):
                logger.info("Auto-Save übersprungen – keine Transkriptionen vorhanden")
                self.update_status("✅ Dateiende – keine Transkription zum Speichern")
                return

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_on_file_finished: scheduling auto-save via after_idle",
                )

            def do_auto_save() -> None:
                """Perform the actual auto-save in the main thread."""
                try:
                    if hasattr(self, "save_transcript"):
                        self.save_transcript()
                        if DEBUG_LEVEL >= 3:
                            log_debug("gui", "Auto-save triggered successfully")
                    else:
                        logger.warning(
                            "save_transcript nicht verfügbar – Auto-Save fehlgeschlagen",
                        )
                except Exception as e:
                    logger.error(f"❌ Auto-save failed: {e}", exc_info=True)
                    self.update_status("❌ Auto-Save fehlgeschlagen")

            self.root.after_idle(do_auto_save)
        else:
            self.update_status("✅ Dateiende – zum Speichern 💾 klicken (Strg+S)")
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "gui",
                    "_on_file_finished: manual save reminder displayed",
                )

        if DEBUG_LEVEL >= 4:
            total_chunks = 0
            if hasattr(self, "audio_processor") and self.audio_processor is not None:
                total_chunks = getattr(self.audio_processor, "_chunk_counter", 0)
            log_debug(
                "gui",
                f"_on_file_finished: total chunks processed = {total_chunks}",
            )

    def _start_button_watchdog(self):
        """Überwacht den Start-Button-Zustand und korrigiert bei Bedarf."""
        if not hasattr(self, "start_button"):
            return
        btn_state = self.start_button["state"]
        controller_state = self.controller.state if self.controller else None
        if (
            controller_state == WhisperController.State.IDLE
            and btn_state == tk.DISABLED
        ):
            logger.warning(
                "Start button disabled but controller is IDLE – force enabling",
            )
            self.start_button.config(state=tk.NORMAL)
        self.root.after(2000, self._start_button_watchdog)

    @gui_error_handler
    def _on_processing_finished(self, result=None) -> None:
        """Callback für das Ende der Audioverarbeitung.

        Phasen
        ------
        0) Guard: Doppelaufruf verhindern.
        1) Setup: Thread-Info, Debug-Level, Zeitmessung.
        2) _safe_update (GUI-Reset + Stream-Info-Ausgrauen).
        3) Ausführung im richtigen Thread (MainThread direkt oder via
           ``root.after``).
        4) Post-Update-Diagnose (AudioProcessor-State loggen).
        5) Flag zurücksetzen.

        Nebenwirkungen
        --------------
        * Setzt den Controller-State auf IDLE.
        * Setzt ``_processing=False``, ``_processing_thread=None``.
        * Sendet ``processing_finished``-Event mit ``success=…``.
        * Graut Stream-Titel und -Kanal optisch aus.
        * Speichert die letzte Stream-Info in ``last_completed_stream_info``.
        """
        import contextlib
        import logging
        import threading
        import time
        import traceback

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        def _dbg(level: int, msg: str, *args) -> None:
            if debug_level >= level:
                try:
                    log_debug("gui", msg, *args)
                except Exception:
                    with contextlib.suppress(Exception):
                        logger.debug(msg, *args)

        if getattr(self, "_is_finished_called", False):
            _dbg(
                3,
                "_on_processing_finished bereits aufgerufen – überspringe (Thread=%s)",
                threading.current_thread().name,
            )
            return
        self._is_finished_called = True
        thread_name = threading.current_thread().name
        start_time = time.monotonic()

        if debug_level >= 3:
            stack = "".join(traceback.format_stack()[:-1])
            log_debug(
                "gui",
                f"_on_processing_finished aufgerufen von Thread '{thread_name}'\n"
                f"Stacktrace:\n{stack}",
            )
        else:
            logger.debug("_on_processing_finished: Thread=%s", thread_name)

        def _safe_update() -> None:
            """Führt die GUI-Updates im Hauptthread durch."""
            try:
                self._reset_progress()
                self._reset_status_text("Bereit")
                self._update_stream_buttons("idle")
                self._deactivate_linux_optimizer()
                _dbg(4, "_safe_update: Basis-Resets abgeschlossen")

                try:
                    _si = getattr(self, "current_stream_info", None)
                    if _si is not None:
                        with contextlib.suppress(Exception):
                            self.last_completed_stream_info = _si

                        _title_label = getattr(self, "stream_title_label", None)
                        _details_label = getattr(self, "stream_details_label", None)
                        _SUFFIX_TITLE = "   ⏹ (Stream beendet)"
                        _SUFFIX_DETAILS = "   • offline"

                        if _title_label is not None:
                            try:
                                _cur = _title_label.cget("text") or ""
                                for _sfx in (_SUFFIX_TITLE, "   ⏹"):
                                    if _cur.endswith(_sfx):
                                        _cur = _cur[: -len(_sfx)]
                                _title_label.config(
                                    text=_cur + _SUFFIX_TITLE,
                                    foreground="#808080",
                                )
                                _dbg(
                                    4,
                                    "_safe_update: Titel ausgegraut (len=%d)",
                                    len(_cur),
                                )
                            except Exception as _te:
                                _dbg(
                                    3,
                                    "Titel-Ausgrauen fehlgeschlagen: %s",
                                    _te,
                                )

                        if _details_label is not None:
                            try:
                                _cur = _details_label.cget("text") or ""
                                for _sfx in (_SUFFIX_DETAILS, "   •"):
                                    if _cur.endswith(_sfx):
                                        _cur = _cur[: -len(_sfx)]
                                _details_label.config(
                                    text=_cur + _SUFFIX_DETAILS,
                                    foreground="#808080",
                                )
                                _dbg(
                                    4,
                                    "_safe_update: Details ausgegraut (len=%d)",
                                    len(_cur),
                                )
                            except Exception as _de:
                                _dbg(
                                    3,
                                    "Details-Ausgrauen fehlgeschlagen: %s",
                                    _de,
                                )

                        _dbg(
                            3,
                            "Stream-Info als beendet markiert (title='%.40s...')",
                            getattr(_si, "title", "?"),
                        )
                    else:
                        _dbg(
                            3,
                            "_safe_update: current_stream_info is None – "
                            "kein Ausgrauen möglich",
                        )
                except Exception as _sie:
                    _dbg(
                        2,
                        "Stream-Info-Ausgrauen (äußerer Block) fehlgeschlagen: %s",
                        _sie,
                    )

                if getattr(self, "controller", None):
                    try:
                        if hasattr(self.controller, "set_state"):
                            self.controller.set_state(WhisperController.State.IDLE)
                            _dbg(4, "Controller-State via set_state auf IDLE")
                        else:
                            self.controller._state = WhisperController.State.IDLE
                            _dbg(4, "Controller-State direkt auf IDLE")
                    except Exception as e:
                        logger.warning(
                            "Konnte Controller-Zustand nicht zurücksetzen: %s",
                            e,
                        )

                self._processing = False
                self._processing_thread = None
                self.is_processing = False
                if hasattr(self, "is_processing"):
                    self.is_processing = False

                if getattr(self, "_event_bus", None):
                    try:
                        if isinstance(result, dict):
                            success = result.get("success", True)
                        else:
                            success = True
                        self._event_bus.emit(
                            "processing_finished",
                            source="gui",
                            success=success,
                            result=result,
                        )
                        _dbg(
                            4,
                            "Event 'processing_finished' gesendet (success=%s)",
                            success,
                        )
                    except Exception as e:
                        logger.debug("Event-Bus emit fehlgeschlagen: %s", e)

                try:
                    self._log_gui_state("AFTER_FINISHED")
                except Exception as _ge:
                    _dbg(3, "_log_gui_state fehlgeschlagen: %s", _ge)

                duration = (time.monotonic() - start_time) * 1000
                _dbg(
                    3,
                    "_on_processing_finished: GUI-Reset in %.2f ms abgeschlossen",
                    duration,
                )

            except Exception as e:
                logger.error("Fehler in _safe_update: %s", e, exc_info=True)
                with contextlib.suppress(Exception):
                    self._enable_start_button()

        try:
            if threading.current_thread() is threading.main_thread():
                _dbg(4, "_safe_update direkt im MainThread")
                _safe_update()
            elif hasattr(self, "root") and self.root:
                try:
                    self.root.after(0, _safe_update)
                    _dbg(4, "_safe_update via root.after geplant")
                except Exception as e:
                    logger.warning(
                        "Konnte _safe_update nicht im MainThread planen: %s",
                        e,
                    )
                    _safe_update()
            else:
                logger.warning(
                    "Kein root-Objekt für after() – führe _safe_update direkt aus",
                )
                _safe_update()
        except Exception as e:
            logger.error(
                "Unerwarteter Fehler beim Ausführen von _safe_update: %s",
                e,
                exc_info=True,
            )
            with contextlib.suppress(Exception):
                self._enable_start_button()

        if debug_level >= 3:
            try:
                ap = getattr(self, "audio_processor", None)
                if ap and hasattr(ap, "state"):
                    logger.debug(
                        "AudioProcessor-State nach _on_processing_finished: %s",
                        ap.state,
                    )
                else:
                    logger.debug(
                        "AudioProcessor nicht verfügbar oder ohne state-Attribut",
                    )
            except Exception as _pe:
                _dbg(4, "Post-Update-Diagnose fehlgeschlagen: %s", _pe)

        if debug_level >= 2:
            try:
                duration_total = (time.monotonic() - start_time) * 1000
                log_debug(
                    "gui",
                    f"_on_processing_finished abgeschlossen "
                    f"(total {duration_total:.2f} ms)",
                )
            except Exception:
                pass

        self._is_finished_called = False

    def _bind_button_hover(self, btn: tk.Button, normal_bg: str, hover_bg: str) -> None:
        """Bindet Hover-Effekt an einen Button (sanft, ohne Animation)."""
        import tkinter as tk

        def _on_enter(_event):
            try:
                if btn.cget("state") == tk.NORMAL:
                    btn.config(bg=hover_bg)
            except Exception:
                pass

        def _on_leave(_event):
            try:
                if btn.cget("state") == tk.NORMAL:
                    btn.config(bg=normal_bg)
            except Exception:
                pass

        btn.bind("<Enter>", _on_enter, add="+")
        btn.bind("<Leave>", _on_leave, add="+")

    def _enable_start_button(self) -> None:
        """Aktiviert den Start-Button und zugehörige Steuerelemente."""
        if hasattr(self, "start_button") and self.start_button:
            try:
                self.start_button.config(state=tk.NORMAL)
                log_debug("gui", "Start button enabled", 4)
            except Exception as e:
                log_warning("gui", f"Failed to enable start button: {e}", 3)
        if hasattr(self, "control_buttons") and self.control_buttons:
            for btn in self.control_buttons:
                try:
                    if btn and btn != self.start_button:
                        btn.config(state=tk.NORMAL)
                except Exception as e:
                    logger.debug("Fehler beim Aktivieren eines Buttons: %s", e)

    def _update_stream_buttons(self, state: str) -> None:
        """Setzt Start- und Stop-Button in einen konsistenten visuellen Zustand."""
        import logging
        import tkinter as tk

        _logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        theme = getattr(self, "current_theme", None)
        if theme is None:
            try:
                theme = DarkTheme()
            except Exception:
                theme = None

        def _tc(attr: str, fallback: str) -> str:
            """Theme-Farbe mit Fallback (robust gegen fehlende Attribute)."""
            if theme is None:
                return fallback
            try:
                return getattr(theme, attr, fallback)
            except Exception:
                return fallback

        BG_TERTIARY = _tc("BG_TERTIARY", "#242d38")
        TEXT_TERTIARY = _tc("TEXT_TERTIARY", "#6e7681")

        _START_ACTIVE_BG = _tc("DRAGON_GREEN_LIGHT", "#2ea043")
        _START_ACTIVE_HOVER = _tc("START_BUTTON_HOVER", "#3fb950")
        _START_ACTIVE_FG = _tc("TEXT_PRIMARY", "#ffffff")

        _STOP_ACTIVE_BG = _tc("ERROR", "#da3633")
        _STOP_ACTIVE_HOVER = _tc("STOP_BUTTON_HOVER", "#f85149")
        _STOP_ACTIVE_FG = _tc("TEXT_PRIMARY", "#ffffff")

        _DISABLED_BG = BG_TERTIARY
        _DISABLED_FG = TEXT_TERTIARY
        _DISABLED_HOVER_BG = BG_TERTIARY

        if debug_level >= 4:
            _logger.debug(
                "_update_stream_buttons: Theme-Farben: start=%s/%s, "
                "stop=%s/%s, disabled=%s/%s (theme=%s)",
                _START_ACTIVE_BG,
                _START_ACTIVE_HOVER,
                _STOP_ACTIVE_BG,
                _STOP_ACTIVE_HOVER,
                _DISABLED_BG,
                _DISABLED_FG,
                type(theme).__name__ if theme else "None",
            )

        _start_state: str
        _start_bg: str
        _start_fg: str
        _start_hover: str
        _start_text: str
        _stop_state: str
        _stop_bg: str
        _stop_fg: str
        _stop_hover: str
        _stop_text: str

        if state == "idle":
            _start_state = tk.NORMAL
            _start_bg, _start_fg, _start_hover = (
                _START_ACTIVE_BG,
                _START_ACTIVE_FG,
                _START_ACTIVE_HOVER,
            )
            _start_text = "🚀  START"
            _stop_state = tk.DISABLED
            _stop_bg, _stop_fg, _stop_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _stop_text = "⏹  STOP"

        elif state == "starting":
            _start_state = tk.DISABLED
            _start_bg, _start_fg, _start_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _start_text = "⏳  Startet…"
            _stop_state = tk.DISABLED
            _stop_bg, _stop_fg, _stop_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _stop_text = "⏹  STOP"

        elif state == "running":
            _start_state = tk.DISABLED
            _start_bg, _start_fg, _start_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _start_text = "🚀  START"
            _stop_state = tk.NORMAL
            _stop_bg, _stop_fg, _stop_hover = (
                _STOP_ACTIVE_BG,
                _STOP_ACTIVE_FG,
                _STOP_ACTIVE_HOVER,
            )
            _stop_text = "⏹  STOP"

        elif state == "stopping":
            _start_state = tk.DISABLED
            _start_bg, _start_fg, _start_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _start_text = "🚀  START"
            _stop_state = tk.DISABLED
            _stop_bg, _stop_fg, _stop_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _stop_text = "⏳  Stoppt…"

        elif state == "error":
            _start_state = tk.NORMAL
            _start_bg, _start_fg, _start_hover = (
                _START_ACTIVE_BG,
                _START_ACTIVE_FG,
                _START_ACTIVE_HOVER,
            )
            _start_text = "🚀  START"
            _stop_state = tk.DISABLED
            _stop_bg, _stop_fg, _stop_hover = (
                _DISABLED_BG,
                _DISABLED_FG,
                _DISABLED_HOVER_BG,
            )
            _stop_text = "⏹  STOP"

        else:
            _logger.warning(
                "_update_stream_buttons: unbekannter state=%r – ignoriert",
                state,
            )
            return

        _start_updated = False
        _stop_updated = False

        start_btn = getattr(self, "start_button", None)
        if start_btn is not None:
            try:
                if start_btn.winfo_exists():
                    start_btn.config(
                        state=_start_state,
                        text=_start_text,
                        bg=_start_bg,
                        fg=_start_fg,
                        activebackground=_start_hover,
                        activeforeground=_start_fg,
                        disabledforeground=_DISABLED_FG,
                        cursor=("hand2" if _start_state == tk.NORMAL else "arrow"),
                    )
                    _start_updated = True
            except tk.TclError as _tcl_exc:
                if debug_level >= 3:
                    _logger.debug(
                        "Start-Button-Update TclError (Widget zerstört?): %s",
                        _tcl_exc,
                    )
            except Exception as e:
                _logger.debug(
                    "Start-Button-Update fehlgeschlagen: %s",
                    e,
                    exc_info=debug_level >= 4,
                )

        stop_btn = getattr(self, "stop_button", None)
        if stop_btn is not None:
            try:
                if stop_btn.winfo_exists():
                    stop_btn.config(
                        state=_stop_state,
                        text=_stop_text,
                        bg=_stop_bg,
                        fg=_stop_fg,
                        activebackground=_stop_hover,
                        activeforeground=_stop_fg,
                        disabledforeground=_DISABLED_FG,
                        cursor=("hand2" if _stop_state == tk.NORMAL else "arrow"),
                    )
                    _stop_updated = True
            except tk.TclError as _tcl_exc:
                if debug_level >= 3:
                    _logger.debug(
                        "Stop-Button-Update TclError (Widget zerstört?): %s",
                        _tcl_exc,
                    )
            except Exception as e:
                _logger.debug(
                    "Stop-Button-Update fehlgeschlagen: %s",
                    e,
                    exc_info=debug_level >= 4,
                )

        try:
            _root = getattr(self, "root", None)
            if _root is not None:
                _root.update_idletasks()
        except Exception:
            pass

        if debug_level >= 3:
            _logger.debug(
                "_update_stream_buttons: state=%s angewendet "
                "(start=%s, stop=%s, start_updated=%s, stop_updated=%s)",
                state,
                _start_state,
                _stop_state,
                _start_updated,
                _stop_updated,
            )

    def _reset_status_text(self, text: str = "Bereit") -> None:
        """Setzt den Status-Text zurück."""
        if hasattr(self, "status_var") and self.status_var:
            self.status_var.set(text)
        elif hasattr(self, "status_label") and self.status_label:
            self.status_label.config(text=text)
        log_debug("gui", f"Status text reset to '{text}'", 4)

    def _disable_stop_button(self) -> None:
        """Deaktiviert den Stop-Button."""
        if hasattr(self, "stop_button") and self.stop_button:
            try:
                self.stop_button.config(state=tk.DISABLED)
                log_debug("gui", "Stop button disabled", 4)
            except Exception as e:
                log_warning("gui", f"Failed to disable stop button: {e}", 3)

    def _log_gui_state(self, context: str = "") -> None:
        """Loggt den aktuellen GUI- und Controller-Zustand für Debugging."""
        if not logger.isEnabledFor(logging.DEBUG):
            return

        state = {
            "context": context,
            "controller_state": (
                getattr(self.controller, "_state", "UNKNOWN")
                if hasattr(self, "controller") and self.controller
                else "NO_CONTROLLER"
            ),
            "start_button_state": (
                self.start_button["state"]
                if hasattr(self, "start_button") and self.start_button
                else "NO_BUTTON"
            ),
            "stop_button_state": (
                self.stop_button["state"]
                if hasattr(self, "stop_button") and self.stop_button
                else "NO_BUTTON"
            ),
            "processing": getattr(self, "_processing", False),
            "thread_alive": (
                self._processing_thread.is_alive()
                if hasattr(self, "_processing_thread") and self._processing_thread
                else False
            ),
            "is_finished_called": getattr(self, "_is_finished_called", False),
        }
        log_debug("gui", f"GUI_STATE: {state}", 4)

    def _deactivate_linux_optimizer(self) -> None:
        """Deaktiviert den Linux-Performance-Optimierer, falls vorhanden und aktiv."""
        if not IS_LINUX:
            return
        if (
            not hasattr(self, "performance_optimizer")
            or self.performance_optimizer is None
        ):
            log_debug("gui", "No Linux optimizer available", 4)
            return

        try:
            optimizer = self.performance_optimizer
            is_active = getattr(optimizer, "is_processing", False) or getattr(
                optimizer,
                "_optimization_active",
                False,
            )
            if is_active:
                log_debug("gui", "Deactivating Linux optimizer", 3)
                optimizer.restore_normal_mode()
                log_debug("gui", "Linux optimizer deactivated successfully", 3)
            else:
                log_debug("gui", "Linux optimizer already inactive – skipping", 4)
        except Exception as e:
            logger.warning(f"Failed to deactivate Linux optimizer: {e}")
            log_exception(
                "gui",
                "Linux optimizer deactivation failed",
                e,
                level="debug",
            )

    def _set_gui_idle_state(self) -> None:
        """Setzt alle GUI-Elemente in den Idle-Zustand (Start-Button aktiv, etc.)."""
        try:
            if hasattr(self, "_start_button"):
                self._start_button.config(state="normal")
                log_debug("gui", "Start button enabled", 4)

            if hasattr(self, "_url_entry"):
                self._url_entry.config(state="normal")

            if hasattr(self, "_model_combo"):
                self._model_combo.config(state="normal")

            if hasattr(self, "_status_label"):
                self._status_label.config(text="Bereit")

            if hasattr(self, "_event_bus"):
                self._event_bus.emit("gui_idle", source="gui")

            log_debug("gui", "GUI idle state set", 4)

        except Exception as e:
            logger.error(f"Failed to set GUI idle state: {e}")
            log_exception("gui", "_set_gui_idle_state failed", e, level="error")

    def _show_error(self, message: str) -> None:
        """Zeigt eine Fehlermeldung in der GUI an (z.B. in einem Label oder Dialog)."""
        logger.error(f"GUI Error: {message}")
        if hasattr(self, "_status_label"):
            self._status_label.config(text=f"Fehler: {message}", foreground="red")
        if hasattr(self, "after"):
            self.after(
                5000,
                lambda: self._status_label.config(text="Bereit", foreground="white"),
            )

