    def _on_progress(self, data: Any = None) -> None:
        """Empfängt progress-Events und leitet sie an die GUI weiter."""
        if not data:
            if DEBUG_LEVEL >= 4:
                log_debug("controller", "progress-Event ohne Daten empfangen")
            return

        if isinstance(data, dict):
            processed = data.get("processed", 0)
            total = data.get("total")
            chunks = data.get("chunks", 0)
            percent = data.get("percent")
            bytes_processed = data.get("bytes_processed")
        else:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "controller",
                    "progress-Event mit unerwartetem Format: %s",
                    type(data).__name__,
                )
            return

        if DEBUG_LEVEL >= 4:
            log_debug(
                "controller",
                "progress: processed=%s, total=%s, chunks=%s, percent=%s",
                processed,
                total,
                chunks,
                percent,
            )

        gui = self.gui_ref() if hasattr(self, "gui_ref") else None
        if gui is None:
            return

        try:
            if hasattr(gui, "_on_progress_update") and callable(
                gui._on_progress_update
            ):
                gui._on_progress_update(
                    processed, total, chunks, percent, bytes_processed
                )
            elif hasattr(gui, "_update_progress_bar") and callable(
                gui._update_progress_bar
            ):
                gui._update_progress_bar(processed, total)
            elif DEBUG_LEVEL >= 3:
                log_debug(
                    "controller",
                    "Keine GUI-Callback-Methode für Progress gefunden",
                )
        except Exception as e:
            logger.warning(
                "_on_progress: GUI-Weiterleitung fehlgeschlagen: %s",
                e,
                exc_info=DEBUG_LEVEL >= 3,
            )

