    @staticmethod
    def _fmt_ts(value: float | None) -> str:
        """Formatiert einen optionalen Timestamp für Log-Ausgaben."""
        if value is None:
            return "None"
        try:
            return f"{float(value):.2f}"
        except (TypeError, ValueError):
            return "None"

    def set_gui_queue(self, queue: Any) -> None:
        """Setzt die GUI-Queue für die Ausgabe von Transkriptionen.
        Wird von der GUI aufgerufen, nachdem der AudioProcessor erstellt wurde.
        """
        self.gui_queue = queue
        if DEBUG_LEVEL >= 3:
            log_debug(
                "queue",
                f"✅ GUI-Queue im AudioProcessor gesetzt (ID: {id(queue)})",
            )

    def _synchronize_ytdlp_cookies(self) -> bool:
        """Stellt sicher, dass YtDlpHelper die aktuellen Cookie-Einstellungen kennt."""
        try:
            use_cookies = getattr(self.stream_manager, "use_browser_cookies", True)
            cookies_browser = getattr(self.settings, "cookies_browser", "firefox")
            proxy_enabled = getattr(self.settings, "proxy_enabled", False)
            proxy_url = getattr(self.settings, "proxy_url", "") if proxy_enabled else ""

            YtDlpHelper.set_config(
                use_cookies=use_cookies,
                cookies_browser=cookies_browser,
                proxy=proxy_url,
                proxy_enabled=proxy_enabled,
            )

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "cookie_sync",
                    "YtDlpHelper konfiguriert: use_cookies=%s, browser=%s, proxy=%s",
                    use_cookies,
                    cookies_browser,
                    proxy_url if proxy_enabled else "deaktiviert",
                )

            return True

        except Exception as e:
            logger.warning(f"Cookie‑Synchronisation fehlgeschlagen: {e}")
            return False

    def _safe_clear(self, attr_name: str) -> None:
        """Ruft .clear() auf einem Attribut auf, falls es existiert, nicht None ist
        und eine clear()-Methode besitzt. Verhindert 'NoneType' object has no attribute 'clear'.
        """
        obj = getattr(self, attr_name, None)
        if obj is None:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "safe_clear",
                    f"Attribut '{attr_name}' ist None – überspringe",
                )
            return
        clear_method = getattr(obj, "clear", None)
        if not callable(clear_method):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "safe_clear",
                    f"Attribut '{attr_name}' (Typ {
                        type(obj).__name__
                    }) hat keine aufrufbare clear()-Methode – überspringe",
                )
            return
        try:
            clear_method()
            if DEBUG_LEVEL >= 4:
                log_debug("safe_clear", f"✅ {attr_name}.clear() erfolgreich")
        except Exception as e:
            obj_type = type(obj).__name__
            obj_repr = repr(obj)[:100]

            fallback_success = False
            if isinstance(obj, (dict, list, set)):
                try:
                    obj.clear()
                    fallback_success = True
                except Exception:
                    pass
            if fallback_success:
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "safe_clear",
                        f"⚠️ {attr_name}.clear() schlug fehl, aber Fallback (direktes clear) erfolgreich. Fehler: {e}",
                    )
            else:
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "safe_clear",
                        f"❌ {attr_name}.clear() fehlgeschlagen (Typ: {obj_type}, Wert: {obj_repr})",
                        e,
                        level="debug",
                    )
                else:
                    logger.warning(
                        f"_safe_clear({attr_name}) fehlgeschlagen: {e} (Typ: {obj_type})",
                    )
                if DEBUG_LEVEL >= 5:
                    import traceback

                    traceback.print_exc()

    def _next_translation_seq(self) -> int:
        """Gibt eine eindeutige Sequenznummer für eine Übersetzungsanfrage zurück."""
        with self._translation_seq_lock:
            self._translation_seq += 1
            seq = self._translation_seq
        if DEBUG_LEVEL >= 3 or "translate" in DEBUG_COMPONENTS:
            log_debug("translate", f"Neue Übersetzungs‑Sequenz: {seq}")
        return seq

    def _is_gpu_available(self, force_refresh: bool = False) -> bool:
        """Prüft, ob GPU‑Beschleunigung aktiv und verfügbar ist – mit Caching."""
        if not force_refresh:
            with self._gpu_cache_lock:
                if self._gpu_available_cache is not None:
                    return self._gpu_available_cache

        if not hasattr(self, "settings") or self.settings is None:
            with self._gpu_cache_lock:
                self._gpu_available_cache = False
            return False

        if not getattr(self.settings, "gpu_acceleration", False):
            with self._gpu_cache_lock:
                self._gpu_available_cache = False
            return False

        if not TORCH_AVAILABLE:
            with self._gpu_cache_lock:
                self._gpu_available_cache = False
            return False

        try:
            import torch

            available = torch.cuda.is_available()
        except (ImportError, RuntimeError) as e:
            logger.debug(f"GPU‑Verfügbarkeitsprüfung fehlgeschlagen: {e}")
            available = False
        except Exception as e:
            logger.warning(f"Unerwarteter Fehler bei GPU‑Prüfung: {e}")
            available = False

        with self._gpu_cache_lock:
            self._gpu_available_cache = available

        return available

    @classmethod
    def reset_gpu_cache(cls) -> None:
        """Setzt den GPU‑Cache zurück (z.B. nach Änderung der Hardware)."""
        with cls._gpu_cache_lock:
            cls._gpu_available_cache = None

    def _load_settings(self) -> AdvancedSettings:
        """Lädt die AdvancedSettings mit robustem Fallback bei Fehlern.
        Unterscheidet zwischen behebbaren Dateifehlern und kritischen Exceptions.
        """
        try:
            settings = get_advanced_settings()
            if settings is None:
                raise RuntimeError("get_advanced_settings() returned None")
            return settings

        except (json.JSONDecodeError, OSError, PermissionError) as e:
            logger.error(
                "AudioProcessor: Settings file error (%s). Using clean fallback defaults.",
                e,
            )
            AudioProcessor._fallback_settings = AdvancedSettings()
            return AudioProcessor._fallback_settings

        except Exception as e:
            logger.critical(
                "AudioProcessor: Unexpected critical error loading settings: %s. "
                "Using fallback defaults.",
                e,
                exc_info=True,
            )
            if AudioProcessor._fallback_settings is None:
                AudioProcessor._fallback_settings = AdvancedSettings()
            return AudioProcessor._fallback_settings

    def _apply_performance_profile(self) -> dict[str, Any]:
        """Wählt automatisch ein optimales Profil für CPU oder GPU.
        Verwendet den zentralen Setter für chunk_duration, um die adaptive Rate zurückzusetzen.
        """
        if not hasattr(self, "settings") or self.settings is None:
            logger.warning("_apply_performance_profile: settings is None – skipping")
            return {}

        adv = self.settings
        is_gpu = self._is_gpu_available()

        log_debug(
            "performance_profile",
            f"🔍 _apply_performance_profile: is_gpu={is_gpu}, "
            f"current_chunk={adv.chunk_duration}, "
            f"adaptive_rate={getattr(self, '_adaptive_bytes_per_sec', 'not set')}",
        )

        gpu_profile = {
            "chunk_duration": 12.0,
            "vad_filter": True,
            "adaptive_chunk": True,
            "beam_size": 3,
            "best_of": 3,
            "patience": 1.2,
            "temperature": 0.0,
            "condition_on_previous_text": True,
            "no_speech_threshold": 0.6,
            "log_prob_threshold": -1.0,
            "compression_ratio_threshold": 2.4,
            "length_penalty": 0.0,
            "transcription_workers": 2,
            "transcription_queue_size": 2000,
            "translation_workers": 1,
            "duplicate_similarity_threshold": 0.95,
            "min_confidence": 0.1,
            "min_language_confidence": 0.2,
            "sentence_flush_interval": 2.5,
            "sentence_flush_word_threshold": 20,
            "tts_length_scale": 0.9,
            "tts_sentence_silence": 0.1,
            "asian_mode": False,
            "precision_mode": False,
            "enable_audio_enhancement": True,
            "vram_idle_timeout_seconds": 60,
        }
        cpu_profile = {
            "chunk_duration": 5.0,
            "vad_filter": False,
            "adaptive_chunk": False,
            "beam_size": 1,
            "best_of": 1,
            "patience": 1.0,
            "temperature": 0.0,
            "condition_on_previous_text": False,
            "no_speech_threshold": 0.9,
            "log_prob_threshold": -2.0,
            "compression_ratio_threshold": 2.8,
            "length_penalty": 0.0,
            "transcription_workers": 1,
            "transcription_queue_size": 1000,
            "translation_workers": 1,
            "duplicate_similarity_threshold": 0.99,
            "min_confidence": 0.05,
            "min_language_confidence": 0.3,
            "sentence_flush_interval": 1.5,
            "sentence_flush_word_threshold": 12,
            "tts_length_scale": 0.7,
            "tts_sentence_silence": 0.05,
            "asian_mode": False,
            "precision_mode": False,
            "enable_audio_enhancement": False,
            "vram_idle_timeout_seconds": 60,
        }

        profile = gpu_profile if is_gpu else cpu_profile
        profile_name = "GPU" if is_gpu else "CPU"

        changed = {}
        skipped = []

        PROTECTED_ATTRS = {"config", "_adaptive_bytes_per_sec"}

        for key, new_value in profile.items():
            if key in PROTECTED_ATTRS:
                skipped.append(key)
                continue

            if not hasattr(adv, key):
                skipped.append(key)
                continue

            old_value = getattr(adv, key)
            if old_value != new_value:
                setattr(adv, key, new_value)
                changed[key] = {"old": old_value, "new": new_value}
                log_debug(
                    "performance_profile",
                    f"  ✅ {key}: {old_value} → {new_value}",
                )

        if "chunk_duration" in changed:
            self._apply_chunk_duration_change(changed["chunk_duration"], adv)

        if "transcription_workers" in changed:
            self._apply_transcription_workers_change(changed["transcription_workers"])

        if "translation_workers" in changed:
            self._apply_translation_workers_change(changed["translation_workers"], adv)

        self._finalize_profile_application(changed, skipped, profile_name, is_gpu, adv)

        return changed

    def _check_callback_health(self) -> None:
        """Periodischer Health-Check für den Transkriptions-Callback."""
        if self._transcription_callback is None:
            logger.error(
                f"💔 Callback-Health-Check fehlgeschlagen! (AP-ID: {id(self)})\n"
                f"  → Versuche Wiederherstellung...",
            )

    def set_text_callback(self, callback: Callable[[str], None]) -> None:
        """Setzt einen Callback für Transkriptionstexte.
        Die GUI kann sich so registrieren, um Transkriptionen zu empfangen.
        """
        import logging
        import traceback

        logger = logging.getLogger("dragon")
        old_callback = getattr(self, "_transcription_callback", None)

        stack = ""
        if DEBUG_LEVEL >= 3:
            stack = "".join(traceback.format_stack()[:-1])

        logger.debug(
            f"📌 set_text_callback AUFRUF:\n"
            f"  → AudioProcessor-ID: {id(self)}\n"
            f"  → alter Callback: {old_callback}\n"
            f"  → neuer Callback: {callback}\n"
            f"  → neuer Callback aufrufbar: {callable(callback) if callback is not None else False}\n"
            f"  → Stacktrace:\n{stack}",
        )

        if callback is None:
            logger.warning(
                f"⚠️ set_text_callback: Callback wird auf None gesetzt! (AP-ID: {id(self)})",
            )

        if callback is not None and not callable(callback):
            logger.error(
                f"❌ Übergebener Callback ist NICHT aufrufbar! Typ: {type(callback)} (AP-ID: {id(self)})",
            )

        self._transcription_callback = callback

        if callback is not None:
            logger.debug(
                f"✅ Text-Callback in AudioProcessor registriert (AP-ID: {id(self)})"
            )
        else:
            logger.debug(
                f"ℹ️ Text-Callback in AudioProcessor auf None gesetzt (AP-ID: {id(self)})"
            )

    def _apply_chunk_duration_change(
        self,
        change_info: dict,
        adv: AdvancedSettings,
    ) -> None:
        """Wendet die Änderung der Chunk-Dauer an und setzt die adaptive Rate zurück."""
        new_duration = change_info["new"]
        if hasattr(self, "set_chunk_duration"):
            try:
                self.set_chunk_duration(new_duration, force=True)
                log_debug(
                    "performance_profile",
                    f"  🔄 chunk_duration geändert: {change_info['old']} → {
                        new_duration
                    }s (adaptive Rate zurückgesetzt)",
                )
            except Exception as e:
                logger.warning(
                    f"set_chunk_duration fehlgeschlagen: {e} – verwende Fallback",
                )
                self._fallback_chunk_duration_change(change_info, adv)
        else:
            self._fallback_chunk_duration_change(change_info, adv)

    def _safe_notify_all(self, lock_held: bool = False) -> None:
        if lock_held:
            self._pending_tasks_cond.notify_all()
        else:
            with self._pending_tasks_cond:
                self._pending_tasks_cond.notify_all()

    def _safe_emit_event(self, event_name: str, data: Any = None) -> None:
        """Sicherer Event-Bus-Emitting mit Fehlerbehandlung."""
        if self._event_bus is None:
            return
        try:
            self._event_bus.emit(event_name, data)
        except Exception as e:
            logger.debug(f"Event-Bus error for '{event_name}': {e}")

    def _fallback_chunk_duration_change(
        self,
        change_info: dict,
        adv: AdvancedSettings,
    ) -> None:
        """Fallback, wenn set_chunk_duration nicht verfügbar ist."""
        adv.chunk_duration = change_info["new"]
        self._update_chunk_size()
        self._adaptive_bytes_per_sec = 32000.0
        self._adaptive_warmup_chunks = 0
        log_debug(
            "performance_profile",
            f"  🔄 chunk_duration geändert: {change_info['old']} → {
                change_info['new']
            }s (adaptive Rate manuell zurückgesetzt)",
        )

    def _extract_audio_url(self, url: str) -> tuple[str | None, str]:
        """Extrahiert die Audio‑URL über den StreamManager.
        Gibt (audio_url, method) zurück.
        Robust gegen String-, 2-Tupel- und 3-Tupel-Rückgaben.
        """
        if self.stream_manager is None:
            logger.error("_extract_audio_url: StreamManager nicht verfügbar")
            return None, "stream_manager_missing"

        try:
            result = self.stream_manager.extract_audio_url(url)
            logger.debug(f"[_extract_audio_url] Ergebnis-Typ: {type(result)}")

            if isinstance(result, str):
                audio_url = result
                method = "direct_string"
                logger.debug(f"✅ StreamManager gab String zurück: {audio_url[:80]}...")

            elif isinstance(result, tuple):
                if len(result) == 1:
                    audio_url = result[0]
                    method = "single_tuple"
                elif len(result) == 2:
                    audio_url, method = result
                elif len(result) >= 3:
                    audio_url, method, *extra = result
                    if (
                        extra
                        and extra[0]
                        and hasattr(self, "event_bus")
                        and self.event_bus is not None
                    ):
                        self.event_bus.emit("stream_info", extra[0])
                        logger.debug(
                            f"Metadaten per EventBus gesendet: {extra[0].get('title', '')}",
                        )
                else:
                    logger.error(f"Unerwartete Tuple-Länge: {len(result)}")
                    return None, f"invalid_tuple_len_{len(result)}"
            else:
                logger.error(f"Unerwarteter Rückgabetyp: {type(result)}")
                return None, f"invalid_return_type_{type(result).__name__}"

            if not audio_url:
                logger.warning(f"❌ Keine Audio-URL in Ergebnis: {result}")
                return None, "no_url_in_result"

            if method in ("no_audio_pipe_fallback", "pipe_fallback", "pipe"):
                logger.info(
                    "🔄 Keine Audio‑URL – wechsle in Pipe‑Modus (yt‑dlp → FFmpeg)",
                )
                return None, "pipe"

            if audio_url:
                if not audio_url.startswith(
                    ("http://", "https://", "file://", "dvb://"),
                ):
                    logger.warning(
                        f"⚠️ Ungewöhnliches Audio-URL-Format: {audio_url[:50]}...",
                    )
                else:
                    logger.info(
                        f"✅ Audio-URL extrahiert: {audio_url[:80]}... (Methode: {method})",
                    )
                return audio_url, method

            logger.warning(
                f"❌ Audio‑URL konnte nicht extrahiert werden (Methode: {method})",
            )
            return None, "failed"

        except Exception as e:
            logger.error(f"Audio-URL-Extraktion fehlgeschlagen: {e}", exc_info=True)
            return None, f"extraction_exception: {e}"

    def _apply_transcription_workers_change(self, change_info: dict) -> None:
        """Passt die Anzahl der Transkriptions-Worker an."""
        new_workers = change_info["new"]
        old_workers = change_info["old"]
        log_debug(
            "performance_profile",
            f"  🔄 transcription_workers: {old_workers} → {new_workers}",
        )

        if hasattr(self, "_transcription_executor"):
            try:
                current_workers = getattr(
                    self._transcription_executor,
                    "_max_workers",
                    0,
                )
                if current_workers != new_workers:
                    self._set_transcription_workers(new_workers)
                    log_debug(
                        "performance_profile",
                        f"  ✅ Executor neu initialisiert mit {new_workers} Workern",
                    )
            except Exception as e:
                logger.warning(f"Fehler beim Setzen der Transkriptions-Worker: {e}")

    def _apply_translation_workers_change(
        self,
        change_info: dict,
        adv: AdvancedSettings,
    ) -> None:
        """Passt die Anzahl der Übersetzungs-Worker an – mit Sicherheitsnetz."""
        new_workers = change_info["new"]
        if new_workers == 0:
            logger.warning(
                "⚠️ translation_workers auf 0 gesetzt – Übersetzung wird deaktiviert! "
                "Setze auf mindestens 1 Worker.",
            )
            new_workers = 1
            adv.translation_workers = 1
            change_info["new"] = 1

        if hasattr(self, "_translation_executor"):
            try:
                current_workers = getattr(self._translation_executor, "_max_workers", 0)
                if current_workers != new_workers:
                    self._init_translation_executor()
                    log_debug(
                        "performance_profile",
                        f"  ✅ Übersetzungs-Executor neu initialisiert mit {new_workers} Workern",
                    )
            except Exception as e:
                logger.warning(f"Fehler beim Setzen der Übersetzungs-Worker: {e}")

    def _finalize_profile_application(
        self,
        changed: dict,
        skipped: list,
        profile_name: str,
        is_gpu: bool,
        adv: AdvancedSettings,
    ) -> None:
        """Führt abschließende Aktionen nach der Profilanwendung durch."""
        if changed:
            critical_changes = [
                k
                for k in changed
                if k
                in ("chunk_duration", "transcription_workers", "translation_workers")
            ]
            logger.info(
                "🚀 %s‑Profil aktiviert: %d Änderungen%s",
                profile_name,
                len(changed),
                (
                    f" (kritisch: {', '.join(critical_changes)})"
                    if critical_changes
                    else ""
                ),
            )
            if DEBUG_LEVEL >= 3:
                log_debug("settings", f"Profiländerungen: {changed}")
                if skipped:
                    log_debug("settings", f"Übersprungene Attribute: {skipped}")
        else:
            logger.debug("ℹ️ %s‑Profil bereits aktiv – keine Änderungen.", profile_name)

        if (
            changed
            and hasattr(self, "_adaptive_bytes_per_sec")
            and self._adaptive_bytes_per_sec > 0
        ):
            current_rate = self._adaptive_bytes_per_sec
            nominal_rate = adv.config.BYTES_PER_SECOND
            if abs(current_rate - nominal_rate) / max(1, nominal_rate) > 0.1:
                logger.warning(
                    f"⚠️ Adaptive Rate ({current_rate:.0f} B/s) weicht stark von nominaler Rate "
                    f"({nominal_rate:.0f} B/s) ab. Dies könnte auf ein Problem hinweisen.",
                )
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "adaptive_rate",
                        f"  🔍 adaptive_rate={current_rate:.0f}, nominal={nominal_rate:.0f}, "
                        f"diff={abs(current_rate - nominal_rate) / max(1, nominal_rate) * 100:.1f}%",
                    )

        if changed:
            try:
                adv.save_to_file()
                logger.debug("✅ Profil-Einstellungen gespeichert.")
            except Exception as e:
                logger.warning(f"⚠️ Konnte Profil-Einstellungen nicht speichern: {e}")

        if changed and self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "performance_profile_changed",
                    {
                        "profile": profile_name,
                        "changes": changed,
                        "is_gpu": is_gpu,
                        "timestamp": time.time(),
                    },
                )
                log_debug(
                    "performance_profile",
                    "  📢 Event 'performance_profile_changed' gesendet",
                )
            except Exception as e:
                log_debug("performance_profile", f"  ⚠️ Event-Bus Fehler: {e}")

    @staticmethod
    def _get_global_cache_manager() -> CacheManager | None:
        """Holt den CacheManager aus dem globalen AppContext – oder None."""
        try:
            ctx = AppContext()
            return ctx.cache_manager
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "cache",
                    "Could not retrieve CacheManager from AppContext: %s",
                    e,
                )
            return None

    def _init_cache_manager(self, cache_manager: CacheManager | None) -> None:
        """Initialisiert den CacheManager"""
        if cache_manager is not None:
            self._cache_manager = cache_manager
            return

        try:
            ctx = AppContext()
            if ctx.cache_manager is not None:
                self._cache_manager = ctx.cache_manager
                if DEBUG_LEVEL >= 3:
                    log_debug("cache", "Using CacheManager from global AppContext")
                return
        except Exception as e:
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "cache",
                    "Could not retrieve CacheManager from AppContext: %s",
                    e,
                )

        logger.warning(
            "⚠️ Kein CacheManager verfügbar – erstelle eigene Standalone‑Instanz.",
        )
        self._cache_manager = CacheManager()

    def _init_state_machines(self) -> None:
        """Zentrale Methode zum vollständigen Zurücksetzen aller Zustands‑ und Flags‑Variablen."""
        import logging
        import threading
        import time

        logger = logging.getLogger("dragon")

        if not hasattr(self, "_state_lock"):
            self._state_lock = threading.RLock()

        with self._state_lock:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "state_machines",
                    "_init_state_machines: Starte Zustands-Reset",
                )

            old_state = getattr(self, "_state", AudioProcessor.State.IDLE)
            self._state = AudioProcessor.State.IDLE

            if hasattr(self, "_state_condition"):
                self._state_condition.notify_all()

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "state_machines",
                    f"  → State: {old_state.name} → {self._state.name}",
                )

            flag_names = (
                "_cleanup_done",
                "_finalizing",
                "_shutting_down",
                "_stop_in_progress",
                "_disposed",
                "_engines_disposed",
                "_guaranteed_cleanup_done",
                "_loky_cleanup_done",
                "_stream_loop_started",
                "_download_mode_active",
                "_shutdown_pending_tasks",
                "_overflow_worker_started",
                "_dispatcher_started",
                "_timeout_executor_shutdown_done",
                "_translation_executor_shutdown_done",
                "_dispose_in_progress",
                "_final_cleanup_started",
                "_cleanup_timeout_executor_in_progress",
                "_dispatcher_shutdown_in_progress",
                "_transcription_executor_shutdown_done",
                "_set_state_in_progress",
            )

            for flag in flag_names:
                setattr(self, flag, False)
                if DEBUG_LEVEL >= 4:
                    log_debug("state_machines", f"  → {flag} = False")

            event_names = (
                "_stop_event",
                "processing_completed_event",
                "_dispatcher_shutdown",
                "_dispatcher_stop_event",
                "_debug_monitor_stop_event",
                "_dispose_stop_event",
                "_download_completed_event",
                "_in_final_flush",
                "_translation_enabled",
            )

            for evt_name in event_names:
                evt = getattr(self, evt_name, None)
                if evt is not None and isinstance(evt, threading.Event):
                    evt.clear()
                    if DEBUG_LEVEL >= 4:
                        log_debug("state_machines", f"  → {evt_name} clear()")

            if (
                hasattr(self, "_tasks_done_event")
                and self._tasks_done_event is not None
            ):
                self._tasks_done_event.set()
                if DEBUG_LEVEL >= 4:
                    log_debug("state_machines", "  → _tasks_done_event set()")
            elif DEBUG_LEVEL >= 3:
                log_debug(
                    "state_machines",
                    "  → _tasks_done_event existiert noch nicht – überspringe",
                )

            self._pending_tasks = 0

            if DEBUG_LEVEL >= 3:
                log_debug("state_machines", "  → pending_tasks = 0")

            self._chunk_counter = 0
            self._empty_reads = 0
            self._consecutive_errors = 0
            self._consecutive_timeouts = 0
            self._queue_enqueue_counter = 0
            self._queue_dequeue_counter = 0
            self._queue_drop_counter = 0
            self._segment_counter = 0
            self._tts_pending_count = 0
            self._translation_watchdog_error_count = 0
            self._translation_watchdog_disabled_until = 0.0
            self._restart_failures = 0
            self._total_restarts = 0

            if DEBUG_LEVEL >= 4:
                log_debug("state_machines", "  → Zähler zurückgesetzt")

            if hasattr(self, "_event_bus") and self._event_bus is not None:
                try:
                    self._event_bus.emit(
                        "state_machines_reset",
                        {
                            "old_state": old_state.name,
                            "new_state": self._state.name,
                            "timestamp": time.time(),
                        },
                    )
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "state_machines",
                            "  → Event 'state_machines_reset' gesendet",
                        )
                except Exception as e:
                    logger.warning(f"Event-Bus-Emit fehlgeschlagen: {e}")

            if DEBUG_LEVEL >= 3:
                log_debug("state_machines", "_init_state_machines: Reset abgeschlossen")

    def _init_stream_management(self, force_reset_token: bool = True) -> None:
        """Initialisiert Stream-Management-Attribute."""
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        self._current_stream_id = None
        self._video_url: str | None = None
        self._is_live: bool = False
        self._download_mode_active = False

        try:
            evt = getattr(self, "_download_completed_event", None)
            if evt is not None and hasattr(evt, "clear"):
                evt.clear()
        except Exception as e:
            if debug_level >= 4:
                logger.debug(
                    "[INIT-STREAM] download_completed_event.clear() fehlgeschlagen: %s",
                    e,
                )

        self._processing_thread = None

        try:
            current_state = getattr(self, "_state", None)
            is_processing = (
                current_state is not None
                and hasattr(current_state, "name")
                and current_state.name == "PROCESSING"
            )
        except Exception:
            is_processing = False

        old_token = getattr(self, "_processing_token", None)

        if force_reset_token or not is_processing:
            self._processing_token = None
            if debug_level >= 4:
                logger.debug(
                    "[INIT-STREAM] _processing_token invalidiert "
                    "(war %s, force=%s, state=%s)",
                    f"id={id(old_token)}" if old_token is not None else "None",
                    force_reset_token,
                    "PROCESSING" if is_processing else "other",
                )
        else:
            if debug_level >= 3:
                logger.debug(
                    "[INIT-STREAM] ⚠️ Token-Reset übersprungen – "
                    "State=PROCESSING (force=False). "
                    "Alter Token bleibt erhalten (id=%s)",
                    f"id={id(old_token)}" if old_token is not None else "None",
                )

        self._shutdown_pending_tasks = False
        self._final_cleanup_started = False
        self._stream_loop_started = False

    def _init_engines_attributes(self) -> None:
        """Initialisiert die Engine-Referenzen (Kaltstart) bzw. behält sie (Reset)."""
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        def _type_name(obj) -> str | None:
            """Gibt den Klassennamen zurück oder None."""
            if obj is None:
                return None
            try:
                return type(obj).__name__
            except Exception:
                return "<unknown>"

        _before = {
            "transcription": _type_name(getattr(self, "_transcription_engine", None)),
            "translation": _type_name(getattr(self, "_translation_engine", None)),
            "fallback": _type_name(getattr(self, "_fallback_translation_engine", None)),
        }

        if debug_level >= 4:
            logger.debug(
                "[engine_init] ENTRY – before=%s",
                _before,
            )

        _reinit_transcription = False
        try:
            if not hasattr(self, "_transcription_engine"):
                self._transcription_engine = None
                _reinit_transcription = True
                if debug_level >= 4:
                    logger.debug("[engine_init] transcription_engine: Kaltstart → None")
            else:
                _existing = getattr(self, "_transcription_engine", None)
                if _existing is not None:
                    for _m in ("reset_error_counter", "reset"):
                        _fn = getattr(_existing, _m, None)
                        if callable(_fn):
                            try:
                                _fn()
                                if debug_level >= 4:
                                    logger.debug(
                                        "[engine_init] %s.%s() aufgerufen",
                                        type(_existing).__name__,
                                        _m,
                                    )
                            except Exception as e:
                                logger.debug(
                                    "[engine_init] %s.%s() fehlgeschlagen: %s",
                                    type(_existing).__name__,
                                    _m,
                                    e,
                                    exc_info=(debug_level >= 5),
                                )
                elif debug_level >= 4:
                    logger.debug("[engine_init] transcription_engine: Reset (war None)")
        except Exception as e:
            logger.warning(
                "[engine_init] transcription_engine-Handling fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

        _reinit_translation = False
        try:
            if not hasattr(self, "_translation_engine"):
                self._translation_engine = None
                _reinit_translation = True
                if debug_level >= 4:
                    logger.debug("[engine_init] translation_engine: Kaltstart → None")
            else:
                _existing = getattr(self, "_translation_engine", None)
                if _existing is not None:
                    for _m in (
                        "reset_error_counter",
                        "reset_circuit_breaker",
                        "reset",
                    ):
                        _fn = getattr(_existing, _m, None)
                        if callable(_fn):
                            try:
                                _fn()
                                if debug_level >= 4:
                                    logger.debug(
                                        "[engine_init] %s.%s() aufgerufen",
                                        type(_existing).__name__,
                                        _m,
                                    )
                            except Exception as e:
                                logger.debug(
                                    "[engine_init] %s.%s() fehlgeschlagen: %s",
                                    type(_existing).__name__,
                                    _m,
                                    e,
                                    exc_info=(debug_level >= 5),
                                )
                elif debug_level >= 4:
                    logger.debug("[engine_init] translation_engine: Reset (war None)")
        except Exception as e:
            logger.warning(
                "[engine_init] translation_engine-Handling fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

        _reinit_fallback = False
        try:
            if not hasattr(self, "_fallback_translation_engine"):
                self._fallback_translation_engine = None
                _reinit_fallback = True
                if debug_level >= 4:
                    logger.debug(
                        "[engine_init] fallback_translation_engine: Kaltstart → None"
                    )
            else:
                _existing = getattr(self, "_fallback_translation_engine", None)
                if _existing is not None:
                    for _m in ("reset_error_counter", "reset"):
                        _fn = getattr(_existing, _m, None)
                        if callable(_fn):
                            try:
                                _fn()
                                if debug_level >= 5:
                                    logger.debug(
                                        "[engine_init] fallback.%s() aufgerufen",
                                        _m,
                                    )
                            except Exception as e:
                                logger.debug(
                                    "[engine_init] fallback.%s() fehlgeschlagen: %s",
                                    _m,
                                    e,
                                    exc_info=(debug_level >= 5),
                                )
                elif debug_level >= 4:
                    logger.debug(
                        "[engine_init] fallback_translation_engine: Reset (war None)"
                    )
        except Exception as e:
            logger.warning(
                "[engine_init] fallback_translation_engine-Handling fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

        _pending_dispose_count = 0
        try:
            pending = getattr(self, "_pending_dispose", None)
            if pending is not None and hasattr(pending, "clear"):
                try:
                    _pending_dispose_count = len(pending)
                except Exception:
                    _pending_dispose_count = 0
                pending.clear()
                if _pending_dispose_count > 0 and debug_level >= 4:
                    logger.debug(
                        "[engine_init] _pending_dispose: %d Einträge geleert",
                        _pending_dispose_count,
                    )
        except Exception as e:
            logger.debug(
                "[engine_init] _pending_dispose.clear() fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        try:
            old_thread = getattr(self, "_dispose_thread", None)
            self._dispose_thread = None
            if old_thread is not None and debug_level >= 4:
                logger.debug(
                    "[engine_init] _dispose_thread zurückgesetzt (war: %s, alive=%s)",
                    getattr(old_thread, "name", "?"),
                    getattr(old_thread, "is_alive", lambda: "?")(),
                )
        except Exception as e:
            logger.debug(
                "[engine_init] _dispose_thread reset fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        try:
            dispose_evt = getattr(self, "_dispose_stop_event", None)
            if dispose_evt is not None and hasattr(dispose_evt, "clear"):
                was_set = False
                if hasattr(dispose_evt, "is_set"):
                    with contextlib.suppress(Exception):
                        was_set = dispose_evt.is_set()
                dispose_evt.clear()
                if was_set and debug_level >= 4:
                    logger.debug(
                        "[engine_init] _dispose_stop_event war gesetzt → gecleart"
                    )
        except Exception as e:
            logger.debug(
                "[engine_init] _dispose_stop_event.clear() fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        _after = {
            "transcription": _type_name(getattr(self, "_transcription_engine", None)),
            "translation": _type_name(getattr(self, "_translation_engine", None)),
            "fallback": _type_name(getattr(self, "_fallback_translation_engine", None)),
        }

        if debug_level >= 3:
            logger.debug(
                "[engine_init] _init_engines_attributes DONE – "
                "reinit={transcription:%s, translation:%s, fallback:%s} | "
                "before=%s | after=%s",
                _reinit_transcription,
                _reinit_translation,
                _reinit_fallback,
                _before,
                _after,
            )

        if (
            _before["translation"] is not None
            and _after["translation"] is None
            and not _reinit_translation
        ):
            logger.warning(
                "[engine_init] ⚠️ Translation-Engine UNERWARTET verloren: "
                "%s → None (das sollte nicht passieren!)",
                _before["translation"],
            )

        if (
            _before["transcription"] is not None
            and _after["transcription"] is None
            and not _reinit_transcription
        ):
            logger.warning(
                "[engine_init] ⚠️ Transcription-Engine UNERWARTET verloren: "
                "%s → None (das sollte nicht passieren!)",
                _before["transcription"],
            )

    def _init_queues_and_dispatcher(self) -> None:
        """Initialisiert die Rohdaten-Queue und die Dispatcher-Infrastruktur."""
        import logging
        import queue

        logger = logging.getLogger("dragon")
        logger.debug("[QUEUE] _init_queues_and_dispatcher() aufgerufen")
        maxsize = getattr(self.settings, "transcription_queue_size", 1000)
        queue_size = max(2000, min(10000, maxsize))
        logger.debug(f"[QUEUE] Berechnete Queue-Größe: {queue_size} (aus {maxsize})")

        if self._raw_audio_queue is None:
            self._raw_audio_queue = queue.Queue(maxsize=queue_size)
            logger.debug(
                "[QUEUE] Neue _raw_audio_queue erstellt (ID: %s, maxsize: %d)",
                id(self._raw_audio_queue),
                queue_size,
            )
        else:
            old_queue = self._raw_audio_queue
            old_size = old_queue.qsize()
            logger.debug(
                "[QUEUE] Bestehende Queue wird geleert (ID: %s, aktuelle Größe: %d)",
                id(old_queue),
                old_size,
            )

            discarded = 0
            try:
                while True:
                    try:
                        old_queue.get_nowait()
                        if hasattr(old_queue, "task_done"):
                            with contextlib.suppress(ValueError):
                                old_queue.task_done()
                        discarded += 1
                    except queue.Empty:
                        break
            except Exception as e:
                logger.warning(f"[QUEUE] Fehler beim Leeren der Queue: {e}")

            logger.debug(f"[QUEUE] {discarded} Elemente aus alter Queue verworfen")

            if old_queue.maxsize != queue_size:
                logger.debug(
                    f"[QUEUE] Queue-Größe ändert sich: {old_queue.maxsize} → {queue_size} – erstelle neue Queue",
                )
                self._raw_audio_queue = queue.Queue(maxsize=queue_size)
                logger.debug(
                    "[QUEUE] Neue _raw_audio_queue erstellt (ID: %s, maxsize: %d)",
                    id(self._raw_audio_queue),
                    queue_size,
                )
            else:
                self._raw_audio_queue = old_queue
                logger.debug(
                    "[QUEUE] Bestehende Queue wiederverwendet (ID: %s, maxsize: %d)",
                    id(self._raw_audio_queue),
                    queue_size,
                )

        logger.debug("[QUEUE] Setze Dispatcher-Zustand zurück...")
        self._reset_dispatcher_state()
        logger.debug("[QUEUE] Dispatcher-Zustand zurückgesetzt")

        try:
            if hasattr(self, "_transcript_queue"):
                with self._transcript_queue_lock:
                    self._transcript_queue.clear()
                    self._next_expected_transcript_start = 0.0
                    logger.debug("[QUEUE] _transcript_queue geleert")

            if hasattr(self, "_translation_queue"):
                with self._translation_queue_lock:
                    self._translation_queue.clear()
                    self._next_expected_translation_start = 0.0
                    logger.debug("[QUEUE] _translation_queue geleert")

            if hasattr(self, "_segment_buffer"):
                with self._segment_buffer_lock:
                    self._segment_buffer.clear()
                    self._next_expected_start = 0.0
                    logger.debug("[QUEUE] _segment_buffer geleert")

        except Exception as e:
            logger.warning(f"[QUEUE] Fehler beim Zurücksetzen zusätzlicher Puffer: {e}")

        if self._raw_audio_queue is not None:
            logger.debug(
                "[QUEUE] Queue bereit – maxsize: %d, aktuell: %d, ID: %s",
                self._raw_audio_queue.maxsize,
                self._raw_audio_queue.qsize(),
                id(self._raw_audio_queue),
            )
        else:
            logger.error("[QUEUE] ❌ Queue konnte nicht initialisiert werden!")

        logger.debug("[QUEUE] _init_queues_and_dispatcher() abgeschlossen")

