    def _init_audio_enhancement(self) -> None:
        """Initialisiert den Audio-Enhancer – aber nur, wenn:
        - Der Benutzer es aktiviert hat (enable_audio_enhancement)
        - Eine GPU verfügbar ist (torch.cuda.is_available())
        - Mindestens 4 GB RAM vorhanden sind
        """
        if not self.settings.enable_audio_enhancement:
            self._audio_enhancer = None
            log_debug("enhance", "Audio-Enhancement durch Benutzer deaktiviert")
            return

        gpu_available = False
        if TORCH_AVAILABLE:
            try:
                import torch

                gpu_available = torch.cuda.is_available()
            except Exception:
                pass

        total_ram_gb = self._get_total_ram_gb()
        low_ram = total_ram_gb < 4.0

        if not gpu_available or low_ram:
            self.settings.enable_audio_enhancement = False
            self._audio_enhancer = None
            if not gpu_available:
                logger.info("💡 Audio-Enhancement deaktiviert (keine GPU verfügbar)")
            else:
                logger.info(
                    f"💡 Audio-Enhancement deaktiviert (RAM: {total_ram_gb:.1f} GB < 4 GB)",
                )
            return

        try:
            self._audio_enhancer = AudioEnhancer(self.settings.config, self.settings)
            log_debug("enhance", "Audio-Enhancer erfolgreich initialisiert (GPU-Modus)")
        except Exception as e:
            logger.warning(f"Audio-Enhancer konnte nicht initialisiert werden: {e}")
            self._audio_enhancer = None

