    def _reset_internal_state(
        self,
        reset_executors: bool = False,
        reset_dispatcher: bool = False,
    ) -> dict:
        """Zentrale Methode zum Zurücksetzen aller internen Zustände des AudioProcessors."""
        import logging
        import time
        import traceback as _tb

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", DEBUG_LEVEL)
        _total_t0 = time.perf_counter()

        diag: dict = {
            "success": False,
            "steps": {},
            "state_before": None,
            "state_after": None,
            "token_before": None,
            "token_after": None,
            "token_preserved": False,
            "total_ms": 0.0,
            "errors": [],
        }

        try:
            state_obj = getattr(self, "_state", None)
            if state_obj is not None and hasattr(state_obj, "name"):
                diag["state_before"] = state_obj.name
            elif state_obj is not None:
                diag["state_before"] = str(state_obj)
        except Exception:
            diag["state_before"] = None

        try:
            tok = getattr(self, "_processing_token", None)
            diag["token_before"] = f"id={id(tok)}" if tok is not None else None
        except Exception:
            diag["token_before"] = None

        log_debug(
            "processor",
            "_reset_internal_state: Starte internen Reset "
            "(executors=%s, dispatcher=%s, state=%s, token=%s)",
            reset_executors,
            reset_dispatcher,
            diag["state_before"],
            diag["token_before"],
        )

        if debug_level >= 4:
            try:
                _stack = "".join(_tb.format_stack(limit=6)[:-1])
                logger.debug("[RESET-INTERNAL] Entry-Stacktrace:\n%s", _stack)
            except Exception:
                pass

        def _safe_step(name: str, func, *args, **kwargs) -> bool:
            """Führt einen Schritt aus und gibt True bei Erfolg zurück."""
            t0 = time.perf_counter()
            ok = False
            try:
                func(*args, **kwargs)
                ok = True
            except Exception as e:
                logger.error(f"  ❌ {name} fehlgeschlagen: {e}")
                diag["errors"].append(f"{name}: {e}")
                if debug_level >= 3:
                    log_debug(
                        "processor",
                        "  ❌ Traceback:\n%s",
                        "".join(_tb.format_tb(e.__traceback__)),
                    )
            finally:
                elapsed_ms = (time.perf_counter() - t0) * 1000
                diag["steps"][name] = {
                    "ok": ok,
                    "ms": round(elapsed_ms, 2),
                }
                if debug_level >= 3 and ok:
                    log_debug(
                        "processor",
                        f"  ✅ {name} in {elapsed_ms:.2f} ms",
                    )
            return ok

        _safe_step("_init_state_machines", self._init_state_machines)

        try:
            current_state = getattr(self, "_state", None)
            is_processing = (
                current_state is not None
                and hasattr(current_state, "name")
                and current_state.name == "PROCESSING"
            )
        except Exception:
            is_processing = False

        _force_token_reset = not is_processing

        if debug_level >= 3:
            log_debug(
                "processor",
                "  → _init_stream_management: is_processing=%s, force_reset_token=%s",
                is_processing,
                _force_token_reset,
            )

        try:
            _safe_step(
                "_init_stream_management",
                lambda: self._init_stream_management(
                    force_reset_token=_force_token_reset
                ),
            )
        except TypeError:
            if debug_level >= 3:
                log_debug(
                    "processor",
                    "  → _init_stream_management ohne force_reset_token "
                    "aufgerufen (Fallback für alte Signatur)",
                )
            _safe_step(
                "_init_stream_management",
                self._init_stream_management,
            )

        _safe_step("_init_engines_attributes", self._init_engines_attributes)
        _safe_step("_init_sentence_buffers", self._init_sentence_buffers)
        _safe_step(
            "_init_duplicate_and_subtitle",
            self._init_duplicate_and_subtitle,
        )
        _safe_step("_init_adaptive_chunk", self._init_adaptive_chunk)
        _safe_step(
            "_init_stats_and_monitoring",
            self._init_stats_and_monitoring,
        )
        _safe_step(
            "_init_translation_watchdog",
            self._init_translation_watchdog,
        )
        _safe_step("_init_temp_files", self._init_temp_files)
        _safe_step("_init_pending_tasks_sync", self._init_pending_tasks_sync)

        if reset_executors:
            log_debug(
                "processor",
                "_reset_internal_state: Initialisiere Executors neu",
            )
            if not hasattr(self, "_get_available_ram_gb"):

                def _fallback_ram_gb():
                    try:
                        import psutil

                        return psutil.virtual_memory().total / (1024**3)
                    except ImportError:
                        return 16.0

                self._get_available_ram_gb = _fallback_ram_gb
                log_debug(
                    "processor",
                    "  → _get_available_ram_gb als Fallback definiert",
                )

            _safe_step("_init_executors", self._init_executors)

        if reset_dispatcher:
            log_debug(
                "processor",
                "_reset_internal_state: Initialisiere Queues und Dispatcher neu",
            )
            _safe_step(
                "_init_queues_and_dispatcher",
                self._init_queues_and_dispatcher,
            )

        try:
            self._stop_event.clear()
            self.processing_completed_event.clear()
            self._dispatcher_shutdown.clear()
            self._dispatcher_stop_event.clear()
            self._debug_monitor_stop_event.clear()
            self._dispose_stop_event.clear()
            self._download_completed_event.clear()
            self._in_final_flush.clear()
            self._translation_enabled.clear()
            if debug_level >= 4:
                log_debug("processor", "  ✅ Events zurückgesetzt")
        except Exception as e:
            logger.error(f"  ❌ Events zurücksetzen fehlgeschlagen: {e}")
            diag["errors"].append(f"events_clear: {e}")

        try:
            self._transcription_callback = None
            self._translation_callback = None
            self._info_callback = None
            self._error_callback = None
            self._finished_callback = None
            self._progress_callback = None
            if debug_level >= 4:
                log_debug("processor", "  ✅ Callbacks zurückgesetzt")
        except Exception as e:
            logger.error(f"  ❌ Callbacks zurücksetzen fehlgeschlagen: {e}")
            diag["errors"].append(f"callbacks_reset: {e}")

        try:
            self._safe_clear("_last_chunk_hashes")
            self._last_chunk_tail = b""
            if debug_level >= 4:
                log_debug("processor", "  ✅ Chunk-Hashes zurückgesetzt")
        except Exception as e:
            logger.error(f"  ❌ Chunk-Hashes zurücksetzen fehlgeschlagen: {e}")
            diag["errors"].append(f"chunk_hashes: {e}")

        try:
            with self._duplicate_lock:
                self._safe_clear("_recent_transcriptions")
                self._last_transcription_text = ""
                self._safe_clear("_already_flushed_texts")
                self._safe_clear("_flushed_combined_texts")
            if debug_level >= 4:
                log_debug("processor", "  ✅ Duplikat-Puffer zurückgesetzt")
        except Exception as e:
            logger.error(f"  ❌ Duplikat-Puffer zurücksetzen fehlgeschlagen: {e}")
            diag["errors"].append(f"duplicate_buffers: {e}")

        try:
            self._safe_clear("_overflow_chunks")
            self._overflow_worker_started = False
            if debug_level >= 4:
                log_debug("processor", "  ✅ Overflow-Chunks zurückgesetzt")
        except Exception as e:
            logger.error(f"  ❌ Overflow-Chunks zurücksetzen fehlgeschlagen: {e}")
            diag["errors"].append(f"overflow_chunks: {e}")

        try:
            self._synchronize_tasks_done_event()
            if debug_level >= 4:
                log_debug("processor", "  ✅ Tasks-Done-Event synchronisiert")
        except Exception as e:
            logger.error(f"  ❌ Tasks-Done-Event synchronisieren fehlgeschlagen: {e}")
            diag["errors"].append(f"tasks_done_sync: {e}")

        try:
            state_obj = getattr(self, "_state", None)
            if state_obj is not None and hasattr(state_obj, "name"):
                diag["state_after"] = state_obj.name
            elif state_obj is not None:
                diag["state_after"] = str(state_obj)
        except Exception:
            diag["state_after"] = None

        try:
            tok = getattr(self, "_processing_token", None)
            diag["token_after"] = f"id={id(tok)}" if tok is not None else None
            diag["token_preserved"] = (
                diag["token_before"] is not None
                and diag["token_after"] is not None
                and diag["token_before"] == diag["token_after"]
            )
        except Exception:
            diag["token_after"] = None
            diag["token_preserved"] = False

        diag["total_ms"] = round((time.perf_counter() - _total_t0) * 1000, 2)
        diag["success"] = len(diag["errors"]) == 0

        if (
            is_processing
            and diag["token_before"] is not None
            and diag["token_after"] is None
        ):
            logger.warning(
                "[RESET-INTERNAL] ⚠️ Token während PROCESSING genullt! "
                "Das kann den V9.1-Guard aushebeln "
                "(war %s → None)",
                diag["token_before"],
            )

        if debug_level >= 2:
            steps_summary = ", ".join(
                f"{name}={v['ms']:.1f}ms{'!' if not v['ok'] else ''}"
                for name, v in diag["steps"].items()
            )
            log_debug(
                "processor",
                "_reset_internal_state: abgeschlossen in %.2fms – "
                "state=%s→%s, token=%s→%s (preserved=%s) – "
                "Steps: %s",
                diag["total_ms"],
                diag["state_before"],
                diag["state_after"],
                diag["token_before"],
                diag["token_after"],
                diag["token_preserved"],
                steps_summary or "n/a",
            )
        else:
            log_debug(
                "processor",
                "_reset_internal_state: Interner Reset abgeschlossen "
                "in %.2fms (success=%s)",
                diag["total_ms"],
                diag["success"],
            )

        with contextlib.suppress(Exception):
            self._last_reset_diag = diag

        return diag

    def _init_executors(self) -> None:
        """Initialisiert alle Executoren für Transkription, Übersetzung und Timeout‑Handling."""
        import os
        import threading
        from concurrent.futures import ThreadPoolExecutor

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_info = logger.info

        cpu_count = os.cpu_count() or 4
        is_gpu = self._is_gpu_available()
        ram_gb = self._get_available_ram_gb_fallback() or 16.0
        is_subtitle = getattr(self, "subtitle_mode", False)
        is_live = getattr(self, "_is_live", None)

        if DEBUG_LEVEL >= 2:
            log_debug(
                f"_init_executors: cpu={cpu_count}, gpu={is_gpu}, ram={ram_gb:.1f}GB, "
                f"subtitle={is_subtitle}, live={is_live}",
            )

        if is_gpu:
            base_workers = max(4, min(8, cpu_count // 3))
        else:
            base_workers = max(2, min(6, cpu_count // 4))

        if ram_gb > 24:
            max_workers = min(base_workers + 2, 12)
        elif ram_gb > 16:
            max_workers = min(base_workers + 1, 8)
        else:
            max_workers = base_workers

        if is_subtitle:
            max_workers = max(4, max_workers)
            log_debug(f"Subtitle-Mode: Worker auf mind. 4 gesetzt ({max_workers})")

        if is_live is True:
            max_workers = min(max_workers + 1, 12)
            log_debug(f"Live-Mode: Worker um 1 erhöht ({max_workers})")

        user_workers = getattr(self.settings, "transcription_workers", None)
        if user_workers is not None and user_workers > 0:
            final_workers = user_workers
            log_debug(f"Transcription-Worker: Benutzerüberschreibung {user_workers}")
        else:
            final_workers = max_workers

        if is_gpu:
            queue_size = 15000
        else:
            queue_size = 8000

        self._transcription_executor = OptimizedThreadPoolExecutor(
            max_workers=final_workers,
            thread_name_prefix="Transcribe",
            max_queue_size=queue_size,
        )

        log_debug(
            f"✅ Transcription Executor: workers={final_workers}, queue_size={queue_size}, "
            f"gpu={is_gpu}, ram={ram_gb:.1f}GB, subtitle={is_subtitle}",
        )

        if is_gpu:
            trans_workers = max(2, min(6, cpu_count // 6))
        else:
            trans_workers = max(1, min(3, cpu_count // 8))

        if is_subtitle:
            trans_workers = max(3, trans_workers)

        user_trans_workers = getattr(self.settings, "translation_workers", None)
        if user_trans_workers is not None and user_trans_workers > 0:
            final_trans_workers = user_trans_workers
            log_debug(
                f"Translation-Worker: Benutzerüberschreibung {user_trans_workers}",
            )
        else:
            final_trans_workers = trans_workers

        trans_queue_size = 2000 if is_gpu else 1000

        self._translation_executor = OptimizedThreadPoolExecutor(
            max_workers=final_trans_workers,
            thread_name_prefix="Translate",
            max_queue_size=trans_queue_size,
        )

        log_debug(
            f"✅ Translation Executor: workers={final_trans_workers}, queue_size={trans_queue_size}",
        )

        if is_gpu:
            timeout_workers = max(3, min(6, cpu_count // 6))
        else:
            timeout_workers = max(2, min(4, cpu_count // 8))

        timeout_queue_size = 500

        self._transcribe_timeout_executor = ThreadPoolExecutor(
            max_workers=timeout_workers,
            thread_name_prefix="TranscribeTimeout",
        )

        self._timeout_queue_maxsize = timeout_queue_size
        self._timeout_futures = set()

        log_debug(
            f"✅ Timeout Executor: workers={timeout_workers}, queue_limit={timeout_queue_size}",
        )

        semaphore_size = final_trans_workers + 3
        self._translation_semaphore = threading.Semaphore(semaphore_size)
        self._translation_enabled.set()
        self._translation_seq = 0
        self._translation_flush_timer = None

        log_debug(f"✅ Translation Semaphore: max={semaphore_size}")

        self._executor_config = {
            "transcription": {
                "workers": final_workers,
                "queue_size": queue_size,
                "is_gpu": is_gpu,
                "subtitle": is_subtitle,
            },
            "translation": {
                "workers": final_trans_workers,
                "queue_size": trans_queue_size,
            },
            "timeout": {
                "workers": timeout_workers,
                "queue_limit": timeout_queue_size,
            },
        }

        log_info(
            "✅ Executors initialized: transcribe=%d, translate=%d, timeout=%d, "
            "trans_queue=%d, timeout_queue=%d",
            final_workers,
            final_trans_workers,
            timeout_workers,
            queue_size,
            timeout_queue_size,
        )

        if DEBUG_LEVEL >= 3:
            log_debug(f"📊 Executor Config: {self._executor_config}")

    def _init_stream_manager(
        self,
        use_browser_cookies: bool,
        stream_manager: StreamManager | None,
    ) -> None:
        if stream_manager is not None:
            self.stream_manager = stream_manager
        else:
            proxy = getattr(self.settings, "proxy_url", "")
            proxy_enabled = getattr(self.settings, "proxy_enabled", False)
            self.stream_manager = StreamManager(
                enable_debug=(DEBUG_LEVEL >= 1),
                use_browser_cookies=use_browser_cookies,
                proxy=proxy,
                proxy_enabled=proxy_enabled,
            )

    def _init_stream_handler(self) -> None:
        try:
            self._stream_handler = StreamHandler(self, self.stream_manager)
        except Exception as e:
            logger.critical("Konnte StreamHandler nicht initialisieren: %s", e)
            self._stream_handler = None

    def _init_temp_files(self) -> None:
        self._temp_files.clear()
        self._cleanup_orphaned_temp_files()

    def _init_event_bus_subscriptions(self) -> None:
        if self._event_bus is not None:
            self._event_bus.subscribe("config_changed", self._on_config_changed)

    def _init_callbacks(self) -> None:
        self._transcription_callback = None
        self._translation_callback = None
        self._info_callback = None
        self._error_callback = None
        self._finished_callback = None
        self._progress_callback = None
        self._total_file_size = None
        self._expected_duration = None

    def _init_miscellaneous(self) -> None:
        """Initialisiert sonstige Attribute."""
        self._stream_loop_started: bool = False

        if hasattr(self.settings, "allowed_dirs"):
            try:
                PlatformUtils.set_allowed_dirs(self.settings.allowed_dirs)
            except Exception as e:
                logger.debug("Fehler beim Setzen der allowed_dirs: %s", e)

    def _log_initialization_summary(
        self,
        *,
        include_system: bool = True,
        include_hardware: bool = True,
        include_executors: bool = True,
        include_cache: bool = True,
        include_debug: bool | None = None,
        return_dict: bool = False,
    ) -> dict[str, Any] | None:
        """Gibt eine detaillierte, strukturierte Zusammenfassung der Initialisierung aus."""
        import sys
        import time
        from datetime import datetime

        if include_debug is None:
            include_debug = DEBUG_LEVEL >= 3

        def _safe_get(obj: Any, attr: str, default: Any = "N/A") -> Any:
            """Sicherer Zugriff auf ein Attribut mit Fallback."""
            try:
                return getattr(obj, attr, default)
            except Exception:
                return default

        def _format_bytes(b: int) -> str:
            """Wandelt Bytes in lesbare Einheiten um."""
            if b is None or b < 0:
                return "N/A"
            if b >= 1024 * 1024 * 1024:
                return f"{b / (1024**3):.2f} GB"
            if b >= 1024 * 1024:
                return f"{b / (1024**2):.2f} MB"
            if b >= 1024:
                return f"{b / 1024:.2f} KB"
            return f"{b} B"

        def _format_duration(seconds: float) -> str:
            """Formatiert eine Dauer in Sekunden."""
            if seconds is None or seconds < 0:
                return "N/A"
            if seconds < 60:
                return f"{seconds:.1f}s"
            if seconds < 3600:
                return f"{seconds / 60:.1f}m"
            return f"{seconds / 3600:.1f}h"

        data = {
            "timestamp": datetime.now().isoformat(),
            "uptime": _format_duration(
                (
                    time.time() - getattr(self, "_stream_start_time", 0.0)
                    if hasattr(self, "_stream_start_time") and self._stream_start_time
                    else 0
                ),
            ),
        }

        if include_system:
            try:
                import platform

                data["system"] = {
                    "os": f"{platform.system()} {platform.release()}",
                    "python": platform.python_version(),
                    "executable": sys.executable,
                    "pid": os.getpid(),
                    "cpu_count": os.cpu_count(),
                    "hostname": platform.node(),
                }
            except Exception as e:
                data["system"] = {"error": str(e)}

        if include_hardware:
            hardware = {}
            try:
                import psutil

                mem = psutil.virtual_memory()
                hardware["ram_total"] = _format_bytes(mem.total)
                hardware["ram_available"] = _format_bytes(mem.available)
                hardware["ram_usage_percent"] = f"{mem.percent:.1f}%"
                hardware["cpu_percent"] = f"{psutil.cpu_percent(interval=0.1):.1f}%"
            except ImportError:
                hardware["psutil"] = "not installed"
            except Exception as e:
                hardware["psutil_error"] = str(e)

            gpu_info = {}
            try:
                import torch

                if torch.cuda.is_available():
                    gpu_info["cuda_available"] = True
                    gpu_info["device_name"] = torch.cuda.get_device_name(0)
                    gpu_info["device_count"] = torch.cuda.device_count()
                    gpu_info["memory_allocated"] = _format_bytes(
                        torch.cuda.memory_allocated(0),
                    )
                    gpu_info["memory_reserved"] = _format_bytes(
                        torch.cuda.memory_reserved(0),
                    )
                    with contextlib.suppress(Exception):
                        gpu_info["compute_capability"] = (
                            f"{torch.cuda.get_device_capability(0)[0]}.{torch.cuda.get_device_capability(0)[1]}"
                        )
                elif hasattr(torch, "mps") and torch.mps.is_available():
                    gpu_info["mps_available"] = True
                else:
                    gpu_info["cuda_available"] = False
                    gpu_info["mps_available"] = False
            except ImportError:
                gpu_info["torch"] = "not installed"
            except Exception as e:
                gpu_info["torch_error"] = str(e)
            hardware["gpu"] = gpu_info
            data["hardware"] = hardware

        config = {}
        try:
            cfg = self.settings.config
            config["chunk_duration"] = f"{cfg.CHUNK_DURATION:.1f}s"
            config["chunk_size"] = _format_bytes(cfg.CHUNK_SIZE_BYTES)
            config["overlap"] = _format_bytes(cfg.OVERLAP_SIZE_BYTES)
            config["sample_rate"] = f"{cfg.SAMPLE_RATE:,} Hz"
            config["channels"] = cfg.CHANNELS
            config["bytes_per_second"] = _format_bytes(cfg.BYTES_PER_SECOND)
            config["audio_format"] = cfg.AUDIO_FORMAT
            config["audio_profile"] = _safe_get(
                self.settings,
                "audio_profile",
                "default",
            )
            config["vad_filter"] = (
                "ON" if _safe_get(self.settings, "vad_filter", False) else "OFF"
            )
            config["adaptive_chunk"] = (
                "ON" if _safe_get(self.settings, "adaptive_chunk", False) else "OFF"
            )
            config["enable_audio_enhancement"] = (
                "ON" if self._audio_enhancer is not None else "OFF"
            )
            config["subtitle_mode"] = (
                "ON" if getattr(self, "subtitle_mode", False) else "OFF"
            )
            config["sentence_buffering"] = (
                "ON" if getattr(self, "_enable_sentence_buffering", False) else "OFF"
            )
        except Exception as e:
            config["error"] = str(e)
        data["config"] = config

        if include_executors:
            executors = {}
            for name, attr in [
                ("transcription", "_transcription_executor"),
                ("translation", "_translation_executor"),
                ("timeout", "_transcribe_timeout_executor"),
            ]:
                try:
                    executor = getattr(self, attr, None)
                    if executor is not None:
                        info = {
                            "max_workers": _safe_get(executor, "_max_workers", "?"),
                            "queue_size": _safe_get(executor, "_task_queue", None),
                        }
                        try:
                            if info["queue_size"] is not None and hasattr(
                                info["queue_size"],
                                "qsize",
                            ):
                                info["queue_size"] = info["queue_size"].qsize()
                            else:
                                info["queue_size"] = "N/A"
                        except Exception:
                            info["queue_size"] = "?"
                        executors[name] = info
                    else:
                        executors[name] = "not initialized"
                except Exception as e:
                    executors[name] = {"error": str(e)}
            data["executors"] = executors

        if include_cache:
            cache_info = {}
            try:
                cm = getattr(self, "_cache_manager", None)
                if cm is not None and hasattr(cm, "get_stats"):
                    stats = cm.get_stats()
                    for name, cache_stats in stats.items():
                        if isinstance(cache_stats, dict):
                            cache_info[name] = {
                                "size": cache_stats.get("size", 0),
                                "maxsize": cache_stats.get("maxsize", 0),
                                "ttl": cache_stats.get("ttl", "N/A"),
                            }
                else:
                    cache_info["status"] = "not available"
            except Exception as e:
                cache_info["error"] = str(e)
            data["cache"] = cache_info
        stats = {}
        try:
            with self._stats_lock:
                stats["chunk_counter"] = self._chunk_counter
                stats["total_bytes_processed"] = _format_bytes(
                    self._total_bytes_processed,
                )
                stats["processed_seconds"] = f"{self._processed_seconds:.1f}s"
                stats["real_processed_seconds"] = f"{self._real_processed_seconds:.1f}s"
                stats["realtime_factor"] = (
                    f"{self._last_realtime_factor:.2f}x"
                    if self._last_realtime_factor > 0
                    else "N/A"
                )
                stats["consecutive_errors"] = self._consecutive_errors
                stats["consecutive_timeouts"] = self._consecutive_timeouts
                stats["queue_enqueued"] = self._queue_enqueue_counter
                stats["queue_dequeued"] = self._queue_dequeue_counter
                stats["queue_dropped"] = self._queue_drop_counter
        except Exception as e:
            stats["error"] = str(e)
        data["stats"] = stats
        thread_info = {}
        try:
            thread_info["dispatcher_alive"] = (
                self._dispatcher_thread is not None
                and self._dispatcher_thread.is_alive()
            )
            thread_info["dispatcher_shutdown"] = self._dispatcher_shutdown.is_set()
            thread_info["pending_tasks"] = self._pending_tasks
            thread_info["tasks_done"] = self._tasks_done_event.is_set()
            if self._raw_audio_queue is not None:
                try:
                    thread_info["queue_size"] = self._raw_audio_queue.qsize()
                    thread_info["queue_maxsize"] = self._raw_audio_queue.maxsize
                except Exception:
                    thread_info["queue_size"] = "?"
                    thread_info["queue_maxsize"] = "?"
            else:
                thread_info["queue"] = "not initialized"
        except Exception as e:
            thread_info["error"] = str(e)
        data["threads"] = thread_info

        lines = []
        lines.append("=" * 80)
        lines.append("🐉 DRAGON WHISPERER INITIALIZATION SUMMARY")
        lines.append(f"   Timestamp: {data['timestamp']}")
        lines.append("=" * 80)

        if include_system and "system" in data and isinstance(data["system"], dict):
            sys_info = data["system"]
            lines.append("\n🖥️  SYSTEM")
            lines.append(f"   OS: {sys_info.get('os', 'N/A')}")
            lines.append(f"   Python: {sys_info.get('python', 'N/A')}")
            lines.append(f"   Executable: {sys_info.get('executable', 'N/A')}")
            lines.append(f"   PID: {sys_info.get('pid', 'N/A')}")
            lines.append(f"   CPU Cores: {sys_info.get('cpu_count', 'N/A')}")
            lines.append(f"   Hostname: {sys_info.get('hostname', 'N/A')}")

        if include_hardware and "hardware" in data:
            hw = data["hardware"]
            lines.append("\n💻  HARDWARE")
            lines.append(f"   RAM Total: {hw.get('ram_total', 'N/A')}")
            lines.append(f"   RAM Available: {hw.get('ram_available', 'N/A')}")
            lines.append(f"   RAM Usage: {hw.get('ram_usage_percent', 'N/A')}")
            lines.append(f"   CPU Load: {hw.get('cpu_percent', 'N/A')}")

            gpu = hw.get("gpu", {})
            if gpu:
                lines.append("   GPU:")
                if gpu.get("cuda_available"):
                    lines.append(f"      Device: {gpu.get('device_name', 'N/A')}")
                    lines.append(
                        f"      Compute Capability: {gpu.get('compute_capability', 'N/A')}",
                    )
                    lines.append(
                        f"      Memory Allocated: {gpu.get('memory_allocated', 'N/A')}",
                    )
                    lines.append(
                        f"      Memory Reserved: {gpu.get('memory_reserved', 'N/A')}",
                    )
                elif gpu.get("mps_available"):
                    lines.append("      Apple MPS (Metal) available")
                elif gpu.get("torch") == "not installed":
                    lines.append("      PyTorch not installed")
                else:
                    lines.append("      No GPU acceleration available")

        if "config" in data:
            cfg = data["config"]
            lines.append("\n⚙️  CONFIGURATION")
            for key, value in cfg.items():
                if key != "error":
                    lines.append(f"   {key.replace('_', ' ').title()}: {value}")
            if "error" in cfg:
                lines.append(f"   ⚠️ Config Error: {cfg['error']}")

        if include_executors and "executors" in data:
            lines.append("\n🔧  EXECUTORS")
            for name, info in data["executors"].items():
                if isinstance(info, dict):
                    workers = info.get("max_workers", "?")
                    queue = info.get("queue_size", "?")
                    lines.append(f"   {name.title()}: workers={workers}, queue={queue}")
                else:
                    lines.append(f"   {name.title()}: {info}")

        if include_cache and "cache" in data:
            lines.append("\n💾  CACHE")
            cache = data["cache"]
            if isinstance(cache, dict):
                for name, info in cache.items():
                    if isinstance(info, dict):
                        lines.append(
                            f"   {name}: size={info.get('size', 0)}/{info.get('maxsize', 0)} (TTL={info.get('ttl', 'N/A')})",
                        )
                    else:
                        lines.append(f"   {name}: {info}")
            else:
                lines.append(f"   {cache}")

        if "stats" in data:
            stats = data["stats"]
            lines.append("\n📊  PROCESSING STATISTICS")
            for key, value in stats.items():
                if key != "error":
                    lines.append(f"   {key.replace('_', ' ').title()}: {value}")
            if "error" in stats:
                lines.append(f"   ⚠️ Stats Error: {stats['error']}")

        if "threads" in data:
            th = data["threads"]
            lines.append("\n🧵  THREADS & DISPATCHER")
            lines.append(f"   Dispatcher Alive: {th.get('dispatcher_alive', 'N/A')}")
            lines.append(
                f"   Dispatcher Shutdown: {th.get('dispatcher_shutdown', 'N/A')}",
            )
            lines.append(f"   Pending Tasks: {th.get('pending_tasks', 'N/A')}")
            lines.append(f"   Tasks Done Event: {th.get('tasks_done', 'N/A')}")
            lines.append(
                f"   Queue Size: {th.get('queue_size', 'N/A')}/{th.get('queue_maxsize', 'N/A')}",
            )

        if include_debug:
            lines.append("\n🐞  DEBUG INFORMATION")
            try:
                import platform

                lines.append(f"   Architecture: {platform.machine()}")
                lines.append(f"   Processor: {platform.processor()}")
            except Exception:
                pass

            try:
                import psutil

                disk = psutil.disk_usage("/")
                lines.append(
                    f"   Disk Free: {_format_bytes(disk.free)} / {_format_bytes(disk.total)}",
                )
            except Exception:
                pass

            lines.append(f"   Active Threads: {threading.active_count()}")
            for t in threading.enumerate():
                if t is not threading.main_thread():
                    lines.append(
                        f"      - {t.name} (daemon={t.daemon}, alive={t.is_alive()})",
                    )

            if hasattr(self, "_last_error") and self._last_error:
                lines.append(f"   Last Error: {self._last_error}")

        lines.append("\n" + "=" * 80)

        output = "\n".join(lines)
        logger.info(output)

        if return_dict:
            return data

        return None

    def _update_derived_attributes(self) -> None:
        """Berechnet alle von der Config abhängigen Attribute neu."""
        cfg = self.settings.config
        self.sample_rate = cfg.SAMPLE_RATE
        self.channels = cfg.CHANNELS
        self.audio_format = cfg.AUDIO_FORMAT
        self.chunk_size = cfg.CHUNK_SIZE_BYTES
        self.overlap_size = cfg.OVERLAP_SIZE_BYTES
        self._max_buffer_bytes = self.MAX_BUFFER_SECONDS * cfg.BYTES_PER_SECOND
        self._max_buffer_chunks = self._max_buffer_bytes // cfg.MIN_CHUNK_BYTES + 10
        self._min_chunk_duration = cfg.MIN_CHUNK_DURATION

    def _register_loky_cleanup_atexit(self) -> None:
        """Registriert einen atexit‑Handler für die umfassende Bereinigung von:
        - loky‑Reusable‑Executor (Semaphore‑Leaks verhindern)
        - joblib‑Parallel‑Backend (falls aktiv)
        - Verbleibende Subprozesse (über multiprocessing.active_children)
        - Garbage‑Collection (erzwingt Freigabe zirkulärer Referenzen)
        """
        import atexit
        import gc
        import threading
        import time

        if not hasattr(AudioProcessor, "_loky_atexit_registered"):
            AudioProcessor._loky_atexit_registered = False
            AudioProcessor._loky_atexit_lock = threading.Lock()
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "loky",
                    "Initialisiere _loky_atexit_lock und _loky_atexit_registered",
                )

        with AudioProcessor._loky_atexit_lock:
            if AudioProcessor._loky_atexit_registered:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "loky",
                        "Atexit‑Handler bereits registriert – überspringe",
                    )
                return
            AudioProcessor._loky_atexit_registered = True
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "Markiere _loky_atexit_registered als True")

        def _cleanup_loky_atexit() -> None:
            """Führt die Bereinigung beim Programmende durch – nur einmal.
            Reihenfolge: Loky‑Executor → Resource‑Tracker → Joblib → Multiprocessing → Threads → GC
            """
            if hasattr(_cleanup_loky_atexit, "_done"):
                return
            _cleanup_loky_atexit._done = True

            start_time = time.perf_counter()
            logger.info("🧹 Loky‑Cleanup‑Handler wird ausgeführt...")

            try:
                from loky import get_reusable_executor

                executor = get_reusable_executor()
                if executor is not None:
                    try:
                        if hasattr(executor, "_pending_work_items"):
                            pending = list(executor._pending_work_items.keys())
                            cancelled = 0
                            for future in pending:
                                if not future.done():
                                    future.cancel()
                                    cancelled += 1
                            if pending:
                                logger.debug(
                                    f"  → {
                                        len(pending)
                                    } ausstehende Future(s) abgebrochen ({
                                        cancelled
                                    } erfolgreich)",
                                )
                    except Exception as e:
                        logger.debug(f"  → Fehler beim Abbrechen von Futures: {e}")

                    try:
                        safe_shutdown_executor(executor, wait=True, cancel_futures=True)
                        logger.debug(
                            "✅ Loky‑Executor erfolgreich heruntergefahren (wait=True)",
                        )
                    except TypeError:
                        executor.shutdown(wait=True)
                        logger.debug(
                            "✅ Loky‑Executor mit Fallback heruntergefahren (wait=True)",
                        )
                    except Exception as e:
                        logger.warning(f"⚠️ Loky‑Executor‑Shutdown fehlgeschlagen: {e}")
                        try:
                            safe_shutdown_executor(
                                executor,
                                wait=False,
                                cancel_futures=True,
                            )
                            logger.debug(
                                "✅ Loky‑Executor asynchron heruntergefahren (Fallback)",
                            )
                        except Exception as e2:
                            logger.debug(
                                f"  → Auch asynchroner Shutdown fehlgeschlagen: {e2}",
                            )
                else:
                    logger.debug("ℹ️ Kein loky‑Executor aktiv")
            except ImportError:
                logger.debug("ℹ️ Loky nicht installiert – überspringe")
            except Exception as e:
                logger.warning(f"⚠️ Loky‑Executor‑Shutdown fehlgeschlagen: {e}")

            try:
                import multiprocessing.resource_tracker as rt

                if hasattr(rt, "_resource_tracker") and hasattr(
                    rt._resource_tracker,
                    "stop",
                ):
                    rt._resource_tracker.stop()
                    logger.debug("✅ Resource‑Tracker gestoppt")
                if hasattr(rt, "_resource_tracker") and hasattr(
                    rt._resource_tracker,
                    "_semaphores",
                ):
                    rt._resource_tracker._semaphores.clear()
                    logger.debug("✅ Semaphore‑Cache geleert")
            except ImportError:
                logger.debug("ℹ️ multiprocessing.resource_tracker nicht verfügbar")
            except Exception as e:
                logger.warning(f"⚠️ Resource‑Tracker‑Stop fehlgeschlagen: {e}")

            try:
                import joblib

                backend = getattr(joblib, "_parallel_backend", None)
                if backend is not None:
                    if hasattr(backend, "terminate"):
                        backend.terminate()
                        logger.debug("✅ Joblib‑Parallel‑Backend terminiert")
                    elif hasattr(backend, "shutdown"):
                        backend.shutdown()
                        logger.debug("✅ Joblib‑Parallel‑Backend heruntergefahren")
            except Exception as e:
                logger.debug(f"Joblib‑Cleanup fehlgeschlagen (ignoriert): {e}")

            try:
                import multiprocessing

                active = multiprocessing.active_children()
                if active:
                    logger.debug(
                        f"🧹 Terminiere {
                            len(active)
                        } verbleibende Multiprocessing‑Prozesse..."
                    )
                    for p in active:
                        try:
                            p.terminate()
                            p.join(timeout=0.5)
                        except Exception as e:
                            logger.debug(
                                f"  → Fehler beim Beenden von Prozess {p.pid}: {e}",
                            )
            except Exception as e:
                logger.debug(f"Multiprocessing‑Cleanup fehlgeschlagen: {e}")

            main_thread = threading.main_thread()
            daemon_marked = 0
            for t in threading.enumerate():
                if t is not main_thread and not t.daemon and t.is_alive():
                    try:
                        t.daemon = True
                        daemon_marked += 1
                        if DEBUG_LEVEL >= 4:
                            logger.debug(f"  → Thread '{t.name}' als Daemon markiert")
                    except Exception as e:
                        logger.debug(
                            f"  → Konnte Thread '{t.name}' nicht als Daemon setzen: {e}",
                        )
            if daemon_marked > 0:
                logger.debug(f"  → {daemon_marked} Thread(s) als Daemon markiert")

            try:
                gc.collect()
                logger.debug("✅ Garbage‑Collection durchgeführt")
            except Exception as e:
                logger.debug(f"GC fehlgeschlagen: {e}")

            elapsed_ms = (time.perf_counter() - start_time) * 1000
            logger.info(f"✅ Loky‑Cleanup abgeschlossen in {elapsed_ms:.2f} ms")

        try:
            atexit.register(_perform_loky_cleanup)
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "loky",
                    "Atexit‑Handler erfolgreich registriert (umfassende Bereinigung)",
                )
        except Exception as e:
            logger.error(f"❌ Fehler bei der Registrierung des atexit‑Handlers: {e}")
            with AudioProcessor._loky_atexit_lock:
                AudioProcessor._loky_atexit_registered = False
            raise

    def _get_available_ram_gb(self) -> float:
        """Ermittelt den verfügbaren Arbeitsspeicher in GB."""
        try:
            import psutil

            return psutil.virtual_memory().total / (1024**3)
        except (ImportError, AttributeError):
            try:
                import platform

                if platform.system() == "Linux":
                    with open("/proc/meminfo") as f:
                        for line in f:
                            if line.startswith("MemTotal:"):
                                mem_kb = int(line.split()[1])
                                return mem_kb / (1024 * 1024)
            except Exception:
                pass
            return 16.0

    def _get_available_ram_gb_fallback(self) -> float:
        """Fallback für RAM-Erkennung ohne psutil."""
        try:
            import psutil

            return psutil.virtual_memory().total / (1024**3)
        except ImportError:
            return 16.0

    def _cleanup_orphaned_temp_files(self) -> None:
        """Löscht alle übriggebliebenen temporären Dateien, die von früheren,
        nicht sauber heruntergefahrenen Instanzen stammen (z. B. nach
        einem harten Abbruch wie ``kill -9``).
        """
        import glob
        import os
        import tempfile

        temp_dir = tempfile.gettempdir()
        pattern = os.path.join(temp_dir, "dragon_*")
        deleted_count = 0

        for tmp_file in glob.iglob(pattern):
            if not os.path.isfile(tmp_file):
                continue
            try:
                os.remove(tmp_file)
                deleted_count += 1
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "temp",
                        f"Orphaned temp file removed: {tmp_file}",
                    )
            except OSError as exc:
                logger.warning(
                    "Could not delete orphaned temp file %s: %s",
                    tmp_file,
                    exc,
                )
            except Exception as exc:
                logger.warning(
                    "Unexpected error while deleting %s: %s",
                    tmp_file,
                    exc,
                )
        if deleted_count > 0:
            logger.info(
                "Startup cleanup: removed %d orphaned temp file(s).",
                deleted_count,
            )

    def _cancel_timeout_futures(self) -> int:
        """Bricht alle aktiven Timeout-Futures ab und gibt die Anzahl der abgebrochenen zurück."""
        if not hasattr(self, "_timeout_futures_lock"):
            self._timeout_futures_lock = threading.RLock()
        with self._timeout_futures_lock:
            futures = list(self._active_timeout_futures)
            cancelled = 0
            for future in futures:
                if not future.done():
                    try:
                        if future.cancel():
                            cancelled += 1
                    except Exception as e:
                        log_debug("processor", f"Error cancelling future: {e}")
            self._active_timeout_futures.clear()
            return cancelled

    def _cleanup_timeout_executor(self, force: bool = False) -> None:
        """Bereinigt den Timeout-Executor und bricht alle ausstehenden Futures ab."""
        if not hasattr(self, "_cleanup_timeout_executor_lock"):
            self._cleanup_timeout_executor_lock = threading.RLock()
            self._cleanup_timeout_executor_in_progress = False

        with self._cleanup_timeout_executor_lock:
            if self._cleanup_timeout_executor_in_progress:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "processor",
                        "_cleanup_timeout_executor: already in progress",
                    )
                return
            self._cleanup_timeout_executor_in_progress = True

        try:
            cancelled = self._cancel_timeout_futures()
            if cancelled:
                log_debug("processor", f"Cancelled {cancelled} timeout futures")

            success = self._shutdown_timeout_executor(force=force)
            if success:
                log_debug("processor", "TimeoutExecutor cleanup successful")
            else:
                logger.warning("TimeoutExecutor cleanup completed with errors")

            if force or cancelled > 20:
                gc.collect()
                log_debug("processor", "Garbage collection triggered")

        except Exception as e:
            logger.error(
                f"Unexpected error in _cleanup_timeout_executor: {e}",
                exc_info=True,
            )
            self._transcribe_timeout_executor = None
        finally:
            with self._cleanup_timeout_executor_lock:
                self._cleanup_timeout_executor_in_progress = False

    def _register_timeout_future(self, future: Future) -> None:
        """Registriert eine Future im Timeout-Executor, um sie später abbrechen zu können."""
        with self._timeout_futures_lock:
            self._active_timeout_futures.add(future)
            future.add_done_callback(self._unregister_timeout_future)

    def _unregister_timeout_future(self, future: Future) -> None:
        """Entfernt eine Future aus der Menge der aktiven Futures."""
        with self._timeout_futures_lock:
            self._active_timeout_futures.discard(future)

    def _set_transcription_workers(self, count: int) -> None:
        """Passt die Anzahl der Transkriptions‑Worker dynamisch an.
        Falls count None oder < 1 ist, wird ein sinnvoller Default (CPU-Kerne / 2) verwendet.
        """
        if count is None:
            logger.warning(
                "⚠️ _set_transcription_workers: count ist None – verwende Default (CPU-Kerne / 2)",
            )
            count = max(1, (os.cpu_count() or 2) // 2)

        if not isinstance(count, int):
            logger.warning(
                f"⚠️ _set_transcription_workers: count ist {
                    type(count).__name__
                }, erwartet int – versuche Konvertierung"
            )
            try:
                count = int(count)
            except (ValueError, TypeError):
                count = max(1, (os.cpu_count() or 2) // 2)
                logger.warning(
                    f"⚠️ Konvertierung fehlgeschlagen – verwende Default: {count}",
                )

        if count < 1:
            logger.warning(
                f"⚠️ _set_transcription_workers: count={count} < 1 – setze auf 1",
            )
            count = 1

        max_allowed = 16
        if count > max_allowed:
            logger.warning(
                f"⚠️ _set_transcription_workers: count={count} > {max_allowed} – begrenzt auf {max_allowed}",
            )
            count = max_allowed

        if DEBUG_LEVEL >= 3:
            log_debug("processor", f"Setting transcription workers to {count}")

        old_executor = self._transcription_executor
        if old_executor is not None:
            try:
                safe_shutdown_executor(old_executor, wait=False, cancel_futures=True)
                if DEBUG_LEVEL >= 4:
                    log_debug("processor", "Old transcription executor shut down")
            except Exception as e:
                logger.warning(f"Error shutting down old transcription executor: {e}")
                with contextlib.suppress(Exception):
                    del old_executor

        try:
            self._transcription_executor = OptimizedThreadPoolExecutor(
                max_workers=count,
                thread_name_prefix="Transcribe",
                max_queue_size=2000,
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    f"Transcription executor recreated with {count} worker(s)",
                )
        except Exception as e:
            logger.error(f"❌ Failed to create new transcription executor: {e}")
            self._transcription_executor = None
            raise

    def _pause_transcription_for_tts(self) -> None:
        """Registriert eine laufende TTS‑Wiedergabe im internen Zähler."""
        if getattr(self, "_disposed", False):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_drossel",
                    "_pause: AudioProcessor disposed – keine Aktion.",
                )
            return

        lock = getattr(self, "_tts_drossel_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tts_drossel_lock = lock
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "tts_drossel",
                    "_tts_drossel_lock ad‑hoc initialisiert.",
                )

        with lock:
            pending = getattr(self, "_tts_pending_count", 0)
            MAX_PENDING = 100

            if pending >= MAX_PENDING:
                logger.warning(
                    "_pause_transcription_for_tts: Zähler hat unerwartet "
                    "%d erreicht – wird zurückgesetzt (kein Executor‑Eingriff).",
                    MAX_PENDING,
                )
                pending = 0

            self._tts_pending_count = pending + 1
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_drossel",
                    "TTS‑Drosselzähler erhöht: %d → %d (kein Executor‑Eingriff).",
                    pending,
                    self._tts_pending_count,
                )

    def _resume_transcription_after_tts(self, force: bool = False) -> None:
        """Dekrementiert den TTS‑Zähler nach Abschluss oder Abbruch der
        Sprachausgabe.
        """
        if getattr(self, "_disposed", False):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_drossel",
                    "_resume: AudioProcessor disposed – keine Aktion.",
                )
            return

        lock = getattr(self, "_tts_drossel_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._tts_drossel_lock = lock
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "tts_drossel",
                    "_tts_drossel_lock ad‑hoc initialisiert.",
                )

        with lock:
            if force:
                old = getattr(self, "_tts_pending_count", 0)
                self._tts_pending_count = 0
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "tts_drossel",
                        "TTS‑Drosselzähler erzwungen auf 0 gesetzt (vorher %d).",
                        old,
                    )
                return

            pending = getattr(self, "_tts_pending_count", 0)
            if pending <= 0:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "tts_drossel",
                        "_resume: Zähler bereits bei 0 – nichts zu tun.",
                    )
                return

            self._tts_pending_count = pending - 1
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "tts_drossel",
                    "TTS‑Drosselzähler dekrementiert: %d → %d.",
                    pending,
                    self._tts_pending_count,
                )

    def _on_config_changed(self, data: Any) -> None:
        """Wird aufgerufen, wenn sich die Konfiguration (z. B. der Typ) geändert hat.
        Aktualisiert alle abhängigen Attribute und Puffer und benachrichtigt den Event‑Bus.
        """
        log_debug("processor", "Config changed – updating derived attributes")
        old_chunk_duration = self.settings.config.CHUNK_DURATION
        self._update_derived_attributes()
        if old_chunk_duration != self.settings.config.CHUNK_DURATION:
            self._update_chunk_size()
            with self._buffer_lock:
                self._audio_chunks.clear()
                self._audio_total_bytes = 0
            logger.info(
                f"Chunk duration changed to {self.settings.config.CHUNK_DURATION}s",
            )

        if self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "config_changed",
                    {
                        "config_type": getattr(self.settings, "config_type", "unknown"),
                        "chunk_duration": self.settings.config.CHUNK_DURATION,
                        "sample_rate": self.settings.config.SAMPLE_RATE,
                        "channels": self.settings.config.CHANNELS,
                        "bytes_per_second": self.settings.config.BYTES_PER_SECOND,
                    },
                )
            except Exception as e:
                log_debug("processor", f"Failed to emit config_changed event: {e}")

    def _schedule_dispose(self) -> None:
        """Plant die verzögerte Entsorgung alter Übersetzungs-Engines."""
        MAX_PENDING_DISPOSE = 10

        with self._engine_lock:
            if self._dispose_thread is not None and self._dispose_thread.is_alive():
                if DEBUG_LEVEL >= 3:
                    log_debug("engine", "Laufender Dispose‑Thread wird abgebrochen")
                self._dispose_stop_event.set()
                self._dispose_thread.join(timeout=0.5)
                self._dispose_stop_event.clear()

            if len(self._pending_dispose) > MAX_PENDING_DISPOSE:
                to_dispose_now = self._pending_dispose[:-MAX_PENDING_DISPOSE]
                self._pending_dispose = self._pending_dispose[-MAX_PENDING_DISPOSE:]
                for engine in to_dispose_now:
                    try:
                        engine.dispose()
                    except Exception as e:
                        logger.warning(
                            "Fehler beim sofortigen Entsorgen einer Engine: %s",
                            e,
                        )

            def worker() -> None:
                """Entsorgt die gepufferten Engines nach einer kurzen Wartezeit."""
                try:
                    wait_time = 0.1 if len(self._pending_dispose) >= 3 else 0.5

                    for _ in range(int(wait_time / 0.1)):
                        if self._dispose_stop_event.wait(0.1):
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "engine",
                                    "Dispose‑Thread durch Stop‑Event abgebrochen",
                                )
                            return

                    self._cleanup_pending_engines()

                except Exception as e:
                    logger.error("Fehler im Dispose‑Worker: %s", e, exc_info=True)

                    with self._engine_lock:
                        self._pending_dispose.clear()

            self._dispose_thread = threading.Thread(
                target=worker,
                daemon=True,
                name="AudioProc-DisposeWorker",
            )
            self._dispose_thread.start()

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "engine",
                    "Dispose‑Worker‑Thread gestartet (pending: %d Engines)",
                    len(self._pending_dispose),
                )

    def _cleanup_pending_engines(self) -> None:
        """Entsorgt alle in _pending_dispose gesammelten alten Übersetzungs-Engines.
        Thread-sicher und fehlertolerant.
        """
        with self._engine_lock:
            to_dispose = self._pending_dispose[:]
            self._pending_dispose.clear()

        if not to_dispose:
            return

        disposed_count = 0
        error_count = 0

        for engine in to_dispose:
            if engine is None:
                continue

            if not hasattr(engine, "dispose") or not callable(engine.dispose):
                logger.warning(
                    "Engine %s hat keine dispose()-Methode – überspringe",
                    type(engine).__name__,
                )
                continue

            try:
                engine.dispose()
                disposed_count += 1
                if DEBUG_LEVEL >= 3:
                    log_debug("engine", f"Disposed old engine: {type(engine).__name__}")
            except Exception as e:
                error_count += 1
                logger.warning(
                    "Fehler beim Entsorgen von %s: %s",
                    type(engine).__name__,
                    e,
                    exc_info=DEBUG_LEVEL >= 3,
                )

        if disposed_count > 0 or error_count > 0:
            logger.debug(
                "Engine-Cleanup abgeschlossen: %d entsorgt, %d Fehler",
                disposed_count,
                error_count,
            )

        if disposed_count > 5:
            import gc

            gc.collect()
            if DEBUG_LEVEL >= 3:
                log_debug("engine", "GC nach Engine-Cleanup durchgeführt")

    @property
    def transcription_engine(self) -> TranscriptionEngine | None:
        """Gibt die aktuelle Transkriptions-Engine zurück."""
        with self._engine_lock:
            return self._transcription_engine

    @transcription_engine.setter
    def transcription_engine(self, engine: TranscriptionEngine | None) -> None:
        """Setzt eine neue Transkriptions-Engine und entsorgt die alte.
        Verwendet die zentrale `_set_engine`-Methode für Konsistenz.
        """
        self._set_engine("_transcription_engine", engine, dispose_old=True)

    @property
    def translation_engine(self) -> BaseTranslationEngine | None:
        with self._engine_lock:
            return self._translation_engine

    @translation_engine.setter
    def translation_engine(self, engine: BaseTranslationEngine | None) -> None:
        self._set_engine("_translation_engine", engine, dispose_old=True)

    def _update_translation_status(self) -> None:
        """Prüft die Funktionalität der Übersetzungs-Engine und setzt
        `_translation_enabled` entsprechend.
        """
        with self._engine_lock:
            engine = self._translation_engine
            functional = False
            if engine is not None:
                if hasattr(engine, "is_functional"):
                    try:
                        functional = engine.is_functional()
                    except Exception:
                        functional = False
                else:
                    functional = True

            if engine is None or not functional:
                self._translation_enabled.clear()
                log_debug("engine", "Translation engine not functional – disabled")
            else:
                self._translation_enabled.set()
                log_debug(
                    "engine",
                    f"Translation engine functional: {type(engine).__name__}",
                )

    def _test_audio_url(self, audio_url: str, timeout: float = 5.0) -> bool:
        """Prüft, ob eine Audio-URL noch erreichbar ist."""
        try:
            import requests

            response = requests.head(audio_url, timeout=timeout, allow_redirects=True)
            return response.status_code < 400
        except Exception:
            return False

    def _start_dispatcher(self) -> dict:
        """Startet den AudioDispatcher-Thread."""
        import logging
        import threading
        import time
        import traceback as _tb

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_warning = logger.warning

        debug_level = getattr(self, "debug_level", 0)
        _start_t0 = time.perf_counter()

        result: dict = {
            "success": False,
            "skipped": False,
            "queue_id": None,
            "thread_name": None,
            "thread_ident": None,
            "state_before": None,
            "state_after": None,
            "restart_count": 0,
            "watchdog_scheduled": False,
            "errors": [],
            "total_ms": 0.0,
        }

        def _state_name(st) -> str | None:
            if st is None:
                return None
            return st.name if hasattr(st, "name") else str(st)

        def _finalize() -> dict:
            try:
                result["state_after"] = _state_name(getattr(self, "_state", None))
            except Exception:
                result["state_after"] = None
            result["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)
            with contextlib.suppress(Exception):
                self._last_dispatcher_start_diag = result
            if debug_level >= 3:
                log_debug(
                    "[DISPATCHER] _start_dispatcher COMPLETED in %.2fms "
                    "(success=%s, skipped=%s, thread=%s, "
                    "state=%s→%s, watchdog=%s, errors=%d)",
                    result["total_ms"],
                    result["success"],
                    result["skipped"],
                    result["thread_name"],
                    result["state_before"],
                    result["state_after"],
                    result["watchdog_scheduled"],
                    len(result["errors"]),
                    extra={"component": "dispatcher"},
                )
            return result

        if debug_level >= 4:
            try:
                _stack = "".join(_tb.format_stack(limit=5)[:-1])
                log_debug(
                    "[DISPATCHER] _start_dispatcher ENTRY (thread=%s)\n%s",
                    threading.current_thread().name,
                    _stack,
                    extra={"component": "dispatcher"},
                )
            except Exception:
                pass

        start_lock = getattr(self, "_dispatcher_start_lock", None)
        if start_lock is None or not (
            hasattr(start_lock, "acquire") and hasattr(start_lock, "release")
        ):
            try:
                start_lock = threading.RLock()
                self._dispatcher_start_lock = start_lock
                if debug_level >= 4:
                    log_debug(
                        "[DISPATCHER] ✅ _dispatcher_start_lock erstellt",
                        extra={"component": "dispatcher"},
                    )
            except Exception as e:
                result["errors"].append(f"create_start_lock: {e}")
                log_warning(
                    "[DISPATCHER] Lock-Erstellung fehlgeschlagen: %s",
                    e,
                    extra={"component": "dispatcher"},
                )
                start_lock = None

        if start_lock is None:
            return self._start_dispatcher_impl(result, _finalize, debug_level)

        with start_lock:
            return self._start_dispatcher_impl(result, _finalize, debug_level)

    def _start_dispatcher_impl(self, result: dict, _finalize, debug_level: int) -> dict:
        """Interne Implementierung von _start_dispatcher (unter Lock).

        Wird separat gehalten, damit der Lock-Block in _start_dispatcher
        sauber bleibt und Reentrancy einfach handhabbar ist.
        """
        import logging
        import queue as queue_module
        import threading
        import time

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_warning = logger.warning
        log_error = logger.error

        _existing_thread = getattr(self, "_dispatcher_thread", None)
        _existing_started = bool(getattr(self, "_dispatcher_started", False))

        if (
            _existing_started
            and _existing_thread is not None
            and _existing_thread.is_alive()
        ):
            if debug_level >= 3:
                log_debug(
                    "[DISPATCHER] ⏭️ Dispatcher läuft bereits "
                    "(thread=%s, alive=True) – überspringe Start",
                    _existing_thread.name,
                    extra={"component": "dispatcher"},
                )
            result["skipped"] = True
            result["success"] = True
            result["thread_name"] = _existing_thread.name
            result["thread_ident"] = getattr(_existing_thread, "ident", None)
            return _finalize()

        try:
            result["state_before"] = (
                self._state.name if hasattr(self._state, "name") else str(self._state)
            )
        except Exception:
            result["state_before"] = None

        raw_queue = getattr(self, "_raw_audio_queue", None)
        if raw_queue is None:
            try:
                raw_queue = queue_module.Queue(maxsize=5000)
                self._raw_audio_queue = raw_queue
                if debug_level >= 3:
                    log_debug(
                        "[DISPATCHER] ✅ Neue _raw_audio_queue erstellt "
                        "(maxsize=5000, id=%s)",
                        id(raw_queue),
                        extra={"component": "dispatcher"},
                    )
            except Exception as e:
                result["errors"].append(f"create_queue: {e}")
                log_error(
                    "[DISPATCHER] ❌ Queue-Erstellung fehlgeschlagen: %s",
                    e,
                    extra={"component": "dispatcher"},
                )
                return _finalize()
        else:
            if debug_level >= 4:
                log_debug(
                    "[DISPATCHER] ✅ _raw_audio_queue bereits vorhanden (id=%s)",
                    id(raw_queue),
                    extra={"component": "dispatcher"},
                )
        result["queue_id"] = id(raw_queue)

        _current_state = getattr(self, "_state", None)
        _is_processing = (
            _current_state is not None
            and hasattr(_current_state, "name")
            and _current_state.name == "PROCESSING"
        )

        if _is_processing:
            if debug_level >= 3:
                log_debug(
                    "[DISPATCHER] ℹ️ State ist bereits PROCESSING – "
                    "kein erneuter Übergang (reason=dispatcher_started)",
                    extra={"component": "dispatcher"},
                )
        else:
            try:
                set_state_fn = getattr(self, "_set_state", None)
                State = getattr(self, "State", None)
                if callable(set_state_fn) and State is not None:
                    try:
                        set_state_fn(
                            State.PROCESSING,
                            force=True,
                            reason="dispatcher_started",
                        )
                        if debug_level >= 3:
                            log_debug(
                                "[DISPATCHER] ✅ State via _set_state auf "
                                "PROCESSING gesetzt "
                                "(reason=dispatcher_started)",
                                extra={"component": "dispatcher"},
                            )
                    except TypeError:
                        set_state_fn(State.PROCESSING)
                    except Exception as e:
                        result["errors"].append(f"set_state: {e}")
                        log_warning(
                            "[DISPATCHER] ⚠️ _set_state(PROCESSING) fehlgeschlagen: %s",
                            e,
                            extra={"component": "dispatcher"},
                        )
                else:
                    if debug_level >= 4:
                        log_debug(
                            "[DISPATCHER] ℹ️ _set_state/State nicht verfügbar "
                            "– State wird nicht geändert",
                            extra={"component": "dispatcher"},
                        )
            except Exception as e:
                result["errors"].append(f"set_state_outer: {e}")
                log_warning(
                    "[DISPATCHER] _set_state-Block Fehler: %s",
                    e,
                    extra={"component": "dispatcher"},
                )

        try:
            shutdown_evt = getattr(self, "_dispatcher_shutdown", None)
            if isinstance(shutdown_evt, threading.Event):
                shutdown_evt.clear()
        except Exception as e:
            result["errors"].append(f"clear_shutdown: {e}")

        try:
            stop_evt = getattr(self, "_dispatcher_stop_event", None)
            if isinstance(stop_evt, threading.Event):
                stop_evt.clear()
        except Exception as e:
            result["errors"].append(f"clear_stop: {e}")

        try:
            _restart_count = int(getattr(self, "_dispatcher_restart_count", 0))
            result["restart_count"] = _restart_count

            thread_name = f"DW-Audio-Dispatcher-{id(self)}"

            dispatcher_target = getattr(self, "_dispatcher_loop", None)
            if not callable(dispatcher_target):
                for _candidate in (
                    "_run_dispatcher_loop_inner",
                    "_run_dispatcher_loop",
                    "_dispatcher_loop_inner",
                ):
                    _fn = getattr(self, _candidate, None)
                    if callable(_fn):
                        dispatcher_target = _fn
                        break

            if not callable(dispatcher_target):
                result["errors"].append("no_dispatcher_loop_method")
                log_error(
                    "[DISPATCHER] ❌ Keine Dispatcher-Loop-Methode gefunden "
                    "(versucht: _dispatcher_loop, _run_dispatcher_loop_inner, "
                    "_run_dispatcher_loop, _dispatcher_loop_inner)",
                    extra={"component": "dispatcher"},
                )
                return _finalize()

            dispatcher_thread = threading.Thread(
                target=dispatcher_target,
                daemon=True,
                name=thread_name,
            )
            dispatcher_thread.start()

            self._dispatcher_thread = dispatcher_thread
            self._dispatcher_started = True

            result["thread_name"] = thread_name
            result["thread_ident"] = getattr(dispatcher_thread, "ident", None)

            if debug_level >= 3:
                log_debug(
                    "[DISPATCHER] 🧵 Dispatcher-Thread gestartet "
                    "(Name: %s, TID: %s, restart_count=%d)",
                    thread_name,
                    result["thread_ident"],
                    _restart_count,
                    extra={"component": "dispatcher"},
                )

            with contextlib.suppress(Exception):
                self._dispatcher_restart_count = _restart_count + 1

        except Exception as e:
            result["errors"].append(f"start_thread: {e}")
            log_error(
                "[DISPATCHER] ❌ Thread-Start fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
                extra={"component": "dispatcher"},
            )
            return _finalize()

        try:
            time.sleep(0.05)
            dispatcher_thread = getattr(self, "_dispatcher_thread", None)
            if dispatcher_thread is not None and not dispatcher_thread.is_alive():
                log_warning(
                    "[DISPATCHER] ⚠️ Dispatcher-Thread starb sofort nach Start "
                    "(TID: %s)",
                    result["thread_ident"],
                    extra={"component": "dispatcher"},
                )
                self._dispatcher_started = False
                result["errors"].append("thread_died_immediately")
                return _finalize()
        except Exception:
            pass

        try:
            schedule_fn = getattr(self, "_schedule_watchdog", None)
            if callable(schedule_fn):
                try:
                    schedule_fn()
                    result["watchdog_scheduled"] = True
                    if debug_level >= 3:
                        log_debug(
                            "[DISPATCHER] ✅ Watchdog gestartet",
                            extra={"component": "dispatcher"},
                        )
                except Exception as e:
                    result["errors"].append(f"schedule_watchdog: {e}")
                    log_debug(
                        "[DISPATCHER] ⚠️ _schedule_watchdog fehlgeschlagen: %s",
                        e,
                        extra={"component": "dispatcher"},
                    )
            else:
                if debug_level >= 3:
                    log_debug(
                        "[DISPATCHER] ℹ️ _schedule_watchdog nicht verfügbar "
                        "– Watchdog deaktiviert",
                        extra={"component": "dispatcher"},
                    )
        except Exception as e:
            result["errors"].append(f"watchdog_outer: {e}")

        result["success"] = (
            len([e for e in result["errors"] if not e.startswith("clear_")]) == 0
        )

        return _finalize()

    def _stop_dispatcher(self, clear_queue: bool = False) -> dict:
        """Beendet den Dispatcher-Thread schnell, zuverlässig und thread-sicher."""
        import logging
        import queue as queue_module
        import threading
        import time
        import traceback as _tb

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_warning = logger.warning
        log_error = logger.error

        debug_level = getattr(self, "debug_level", 0)

        result: dict = {
            "success": False,
            "skipped": False,
            "dispatcher_was_started": False,
            "thread_was_alive": False,
            "thread_alive_after": False,
            "thread_ident": None,
            "sentinel_sent": False,
            "sentinel_error": None,
            "queue_cleared": False,
            "watchdog_cancelled": False,
            "watchdog_reactivated": False,
            "total_ms": 0.0,
            "phases": {},
            "errors": [],
            "reentrant": False,
            "lock_acquired": False,
            "events_cleared": False,
            "thread_ref_reset": False,
        }

        if debug_level >= 4:
            try:
                _stack = "".join(_tb.format_stack(limit=6)[:-1])
                log_debug(
                    "_stop_dispatcher ENTRY (clear_queue=%s, thread=%s)\n%s",
                    clear_queue,
                    threading.current_thread().name,
                    _stack,
                    extra={"component": "processor"},
                )
            except Exception:
                pass

        lock = getattr(self, "_stop_dispatcher_lock", None)
        if lock is None or not (hasattr(lock, "acquire") and hasattr(lock, "release")):
            try:
                lock = threading.RLock()
                self._stop_dispatcher_lock = lock
                if debug_level >= 4:
                    log_debug(
                        "_stop_dispatcher: RLock neu angelegt",
                        extra={"component": "processor"},
                    )
            except Exception as e:
                log_warning(
                    "_stop_dispatcher: Lock-Erstellung fehlgeschlagen: %s",
                    e,
                    extra={"component": "processor"},
                )
                lock = None

        try:
            _me = threading.get_ident()
            _owner = getattr(self, "_stop_dispatcher_lock_owner", None)
            _reentrant = _owner == _me
        except Exception:
            _me = None
            _owner = None
            _reentrant = False

        result["reentrant"] = _reentrant

        if _reentrant and debug_level >= 4:
            log_debug(
                "_stop_dispatcher: reentranter Aufruf vom selben Thread "
                "(tid=%s) – RLock erlaubt das",
                _me,
                extra={"component": "processor"},
            )

        _lock_ctx = lock if lock is not None else None

        def _impl() -> dict:
            """Eigentliche Stop-Logik – läuft unter Lock."""

            if getattr(self, "_dispatcher_shutdown_in_progress", False):
                if debug_level >= 3:
                    log_debug(
                        "_stop_dispatcher: bereits im Shutdown – überspringe",
                        extra={"component": "processor"},
                    )
                result["skipped"] = True
                result["success"] = True
                return result

            try:
                self._dispatcher_shutdown_in_progress = True
            except Exception as e:
                log_debug(
                    "_stop_dispatcher: shutdown_in_progress setzen: %s",
                    e,
                    extra={"component": "processor"},
                )

            overall_start = time.perf_counter()
            phases: dict = {}
            errors: list = []

            try:
                dispatcher_started = bool(getattr(self, "_dispatcher_started", False))
                result["dispatcher_was_started"] = dispatcher_started

                dispatcher_thread = getattr(self, "_dispatcher_thread", None)
                thread_was_alive = bool(
                    dispatcher_thread is not None and dispatcher_thread.is_alive()
                )
                result["thread_was_alive"] = thread_was_alive
                if dispatcher_thread is not None:
                    result["thread_ident"] = getattr(dispatcher_thread, "ident", None)

                shutdown_evt = getattr(self, "_dispatcher_shutdown", None)
                shutdown_set = (
                    shutdown_evt.is_set()
                    if isinstance(shutdown_evt, threading.Event)
                    else "n/a"
                )
                stop_evt = getattr(self, "_dispatcher_stop_event", None)
                stop_set = (
                    stop_evt.is_set()
                    if isinstance(stop_evt, threading.Event)
                    else "n/a"
                )

                raw_queue = getattr(self, "_raw_audio_queue", None)
                queue_size_before = "n/a"
                if raw_queue is not None and hasattr(raw_queue, "qsize"):
                    try:
                        queue_size_before = raw_queue.qsize()
                    except Exception:
                        queue_size_before = "err"

                watchdog_after_id = getattr(self, "_watchdog_after_id", None)

                if debug_level >= 3:
                    log_debug(
                        "_stop_dispatcher: START (clear_queue=%s, "
                        "dispatcher_started=%s, thread_alive=%s, "
                        "thread_tid=%s, shutdown_set=%s, stop_set=%s, "
                        "queue_size=%s, watchdog_id=%s, caller=%s)",
                        clear_queue,
                        dispatcher_started,
                        thread_was_alive,
                        result["thread_ident"],
                        shutdown_set,
                        stop_set,
                        queue_size_before,
                        watchdog_after_id,
                        threading.current_thread().name,
                        extra={"component": "processor"},
                    )

                if not dispatcher_started:
                    if debug_level >= 3:
                        log_debug(
                            "_stop_dispatcher: Dispatcher nie gestartet "
                            "– Cleanup-Pfad ohne Thread-Join",
                            extra={"component": "processor"},
                        )

                    if clear_queue:
                        _t0 = time.perf_counter()
                        try:
                            self._clear_and_sync_queue()
                            result["queue_cleared"] = True
                        except Exception as e:
                            errors.append(f"clear_queue_early: {e}")
                        phases["clear_queue"] = (time.perf_counter() - _t0) * 1000
                    else:
                        phases["clear_queue"] = 0.0

                    _t0 = time.perf_counter()
                    try:
                        cancel_fn = getattr(self, "_cancel_watchdog", None)
                        if callable(cancel_fn):
                            cancel_fn()
                            result["watchdog_cancelled"] = True
                    except Exception as e:
                        errors.append(f"cancel_watchdog_early: {e}")
                    phases["cancel_watchdog"] = (time.perf_counter() - _t0) * 1000

                    try:
                        if (
                            dispatcher_thread is not None
                            and not dispatcher_thread.is_alive()
                        ):
                            self._dispatcher_thread = None
                            result["thread_ref_reset"] = True
                    except Exception:
                        pass

                    result["errors"] = errors
                    result["success"] = True
                    return result

                phase_start = time.perf_counter()

                if not hasattr(self, "_dispatcher_shutdown"):
                    try:
                        self._dispatcher_shutdown = threading.Event()
                    except Exception as e:
                        errors.append(f"create_shutdown_event: {e}")

                try:
                    shutdown_evt = getattr(self, "_dispatcher_shutdown", None)
                    if isinstance(shutdown_evt, threading.Event):
                        if not shutdown_evt.is_set():
                            shutdown_evt.set()
                            if debug_level >= 3:
                                log_debug(
                                    "  → _dispatcher_shutdown gesetzt",
                                    extra={"component": "processor"},
                                )
                except Exception as e:
                    errors.append(f"set_shutdown_event: {e}")

                if not hasattr(self, "_dispatcher_stop_event"):
                    try:
                        self._dispatcher_stop_event = threading.Event()
                    except Exception as e:
                        errors.append(f"create_stop_event: {e}")

                try:
                    stop_evt = getattr(self, "_dispatcher_stop_event", None)
                    if isinstance(stop_evt, threading.Event):
                        stop_evt.set()
                        if debug_level >= 4:
                            log_debug(
                                "  → _dispatcher_stop_event gesetzt",
                                extra={"component": "processor"},
                            )
                except Exception as e:
                    errors.append(f"set_stop_event: {e}")

                phases["signal_events"] = (time.perf_counter() - phase_start) * 1000

                if clear_queue:
                    phase_start = time.perf_counter()
                    try:
                        self._clear_and_sync_queue()
                        result["queue_cleared"] = True
                    except Exception as e:
                        errors.append(f"clear_queue: {e}")
                    phases["clear_queue"] = (time.perf_counter() - phase_start) * 1000
                else:
                    phases["clear_queue"] = 0.0

                phase_start = time.perf_counter()
                sentinel = getattr(self, "_DISPATCHER_STOP_SENTINEL", None)

                if sentinel is None:
                    if debug_level >= 4:
                        log_debug(
                            "  → Kein Sentinel definiert – überspringe",
                            extra={"component": "processor"},
                        )
                else:
                    try:
                        raw_queue = getattr(self, "_raw_audio_queue", None)
                        if raw_queue is None:
                            result["sentinel_error"] = "raw_queue_none"
                        else:
                            try:
                                raw_queue.put_nowait(sentinel)
                                result["sentinel_sent"] = True
                                if debug_level >= 4:
                                    qs = "?"
                                    if hasattr(raw_queue, "qsize"):
                                        try:
                                            qs = raw_queue.qsize()
                                        except Exception:
                                            qs = "err"
                                    log_debug(
                                        "  → Sentinel in Queue gelegt (qsize≈%s)",
                                        qs,
                                        extra={"component": "processor"},
                                    )
                            except queue_module.Full:
                                result["sentinel_error"] = "queue_full"
                                log_warning(
                                    "  → Queue voll – Sentinel nicht "
                                    "gesendet (Queue-Größe: %s)",
                                    getattr(raw_queue, "maxsize", "?"),
                                    extra={"component": "processor"},
                                )
                            except Exception as e:
                                result["sentinel_error"] = str(e)
                                errors.append(f"sentinel_put: {e}")
                    except Exception as e:
                        result["sentinel_error"] = str(e)
                        errors.append(f"sentinel_outer: {e}")

                phases["sentinel"] = (time.perf_counter() - phase_start) * 1000
                join_timeout = 3.0 if result["sentinel_sent"] else 8.0
                dispatcher_thread = getattr(self, "_dispatcher_thread", None)

                if dispatcher_thread is not None and dispatcher_thread.is_alive():
                    phase_start = time.perf_counter()
                    if debug_level >= 3:
                        log_debug(
                            "  → Warte auf Dispatcher-Thread (timeout=%.1fs, tid=%s) …",
                            join_timeout,
                            result["thread_ident"],
                            extra={"component": "processor"},
                        )
                    try:
                        dispatcher_thread.join(timeout=join_timeout)
                    except Exception as e:
                        errors.append(f"join: {e}")
                    phases["join_thread"] = (time.perf_counter() - phase_start) * 1000

                    result["thread_alive_after"] = dispatcher_thread.is_alive()

                    if result["thread_alive_after"]:
                        log_warning(
                            "  ⚠️ Dispatcher-Thread läuft noch nach %.1fs "
                            "– wird ignoriert (daemon=%s, tid=%s)",
                            join_timeout,
                            getattr(dispatcher_thread, "daemon", "?"),
                            result["thread_ident"],
                            extra={"component": "processor"},
                        )
                    elif debug_level >= 3:
                        log_debug(
                            "  ✅ Dispatcher-Thread sauber beendet in %.1fms",
                            phases["join_thread"],
                            extra={"component": "processor"},
                        )
                else:
                    if debug_level >= 3:
                        log_debug(
                            "  → Dispatcher-Thread bereits beendet oder None",
                            extra={"component": "processor"},
                        )
                    phases["join_thread"] = 0.0

                phase_start = time.perf_counter()
                try:
                    sync_fn = getattr(self, "_synchronize_tasks_done_event", None)
                    if callable(sync_fn):
                        sync_fn()
                except Exception as e:
                    errors.append(f"sync_event: {e}")
                phases["sync_event"] = (time.perf_counter() - phase_start) * 1000
                phase_start = time.perf_counter()
                try:
                    cancel_fn = getattr(self, "_cancel_watchdog", None)
                    if callable(cancel_fn):
                        cancel_fn()
                        result["watchdog_cancelled"] = True
                except Exception as e:
                    errors.append(f"cancel_watchdog: {e}")
                phases["cancel_watchdog"] = (time.perf_counter() - phase_start) * 1000
                phase_start = time.perf_counter()

                if not result["thread_alive_after"]:
                    try:
                        self._dispatcher_started = False
                    except Exception as e:
                        errors.append(f"reset_started_flag: {e}")

                    try:
                        self._dispatcher_thread = None
                        result["thread_ref_reset"] = True
                    except Exception as e:
                        errors.append(f"reset_thread_ref: {e}")

                    for evt_attr in (
                        "_dispatcher_shutdown",
                        "_dispatcher_stop_event",
                    ):
                        try:
                            evt = getattr(self, evt_attr, None)
                            if isinstance(evt, threading.Event):
                                evt.clear()
                                result["events_cleared"] = True
                        except Exception as e:
                            errors.append(f"clear_{evt_attr}: {e}")

                    if debug_level >= 3:
                        log_debug(
                            "  ✅ Flags + Events zurückgesetzt "
                            "(thread_ref_reset=%s, events_cleared=%s)",
                            result["thread_ref_reset"],
                            result["events_cleared"],
                            extra={"component": "processor"},
                        )
                else:
                    if debug_level >= 3:
                        log_warning(
                            "  ⚠️ Dispatcher-Thread läuft noch – "
                            "Events/Flags bleiben gesetzt für Retry "
                            "(thread_alive_after=True)"
                        )

                    try:
                        schedule_fn = getattr(self, "_schedule_watchdog", None)
                        if callable(schedule_fn):
                            schedule_fn()
                            result["watchdog_reactivated"] = True
                            if debug_level >= 3:
                                log_debug(
                                    "  → Watchdog reaktiviert für Zombie-Erkennung",
                                    extra={"component": "processor"},
                                )
                    except Exception as e:
                        errors.append(f"reschedule_watchdog: {e}")
                        log_debug(
                            "  → Watchdog-Reaktivierung fehlgeschlagen: %s",
                            e,
                            extra={"component": "processor"},
                        )

                phases["reset_flags"] = (time.perf_counter() - phase_start) * 1000

            except Exception as e:
                errors.append(f"unexpected: {e}")
                log_error(
                    "_stop_dispatcher: unerwarteter Fehler: %s",
                    e,
                    exc_info=(debug_level >= 3),
                    extra={"component": "processor"},
                )

            finally:
                result["total_ms"] = round(
                    (time.perf_counter() - overall_start) * 1000, 2
                )
                result["phases"] = {k: round(v, 2) for k, v in phases.items()}
                result["errors"] = errors
                result["success"] = len(errors) == 0

                try:
                    self._dispatcher_shutdown_in_progress = False
                except Exception as e:
                    log_debug(
                        "_stop_dispatcher: in_progress reset: %s",
                        e,
                        extra={"component": "processor"},
                    )

                if debug_level >= 3:
                    phase_str = ", ".join(
                        f"{name}={val:.1f}ms" for name, val in result["phases"].items()
                    )
                    log_debug(
                        "_stop_dispatcher: COMPLETED in %.2f ms "
                        "(clear_queue=%s, sentinel=%s, watchdog=%s, "
                        "watchdog_reactivated=%s, thread_alive_after=%s, "
                        "events_cleared=%s, thread_ref_reset=%s, "
                        "errors=%d) – Phasen: %s",
                        result["total_ms"],
                        clear_queue,
                        result["sentinel_sent"],
                        result["watchdog_cancelled"],
                        result["watchdog_reactivated"],
                        result["thread_alive_after"],
                        result["events_cleared"],
                        result["thread_ref_reset"],
                        len(errors),
                        phase_str,
                        extra={"component": "processor"},
                    )
                    if errors:
                        log_debug(
                            "_stop_dispatcher: Fehlerliste: %s",
                            errors[:5],
                            extra={"component": "processor"},
                        )

            return result

        if _lock_ctx is None:
            if debug_level >= 4:
                log_debug(
                    "_stop_dispatcher: kein Lock – direkter Aufruf",
                    extra={"component": "processor"},
                )
            return _impl()

        try:
            with _lock_ctx:
                result["lock_acquired"] = True
                with contextlib.suppress(Exception):
                    self._stop_dispatcher_lock_owner = threading.get_ident()
                try:
                    return _impl()
                finally:
                    with contextlib.suppress(Exception):
                        self._stop_dispatcher_lock_owner = None
        except Exception as e:
            log_error(
                "_stop_dispatcher: Lock-Kontext fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
                extra={"component": "processor"},
            )
            result["errors"].append(f"lock_context: {e}")
            return result

    def _schedule_watchdog(self) -> None:
        """Startet einen periodischen Watchdog, der toten Dispatcher erkennt."""
        import logging
        import threading
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        _interval_ms = getattr(self, "WATCHDOG_INTERVAL_MS", 1000)
        _idle_log_every = 30.0

        lock = getattr(self, "_watchdog_scheduling_lock", None)
        if lock is None or not (hasattr(lock, "acquire") and hasattr(lock, "release")):
            try:
                lock = threading.RLock()
                self._watchdog_scheduling_lock = lock
            except Exception as e:
                logger.debug("[WATCHDOG] Lock-Erstellung fehlgeschlagen: %s", e)
                lock = None

        self._cancel_watchdog()

        def _impl() -> None:
            if getattr(self, "_watchdog_after_id", None) is not None:
                if debug_level >= 4:
                    logger.debug(
                        "[WATCHDOG] _schedule_watchdog: bereits aktiv "
                        "(after_id=%s) – überspringe",
                        self._watchdog_after_id,
                    )
                return

            root = None
            try:
                find_fn = getattr(self, "_find_tk_root", None)
                if callable(find_fn):
                    root = find_fn()
            except Exception as e:
                logger.debug("[WATCHDOG] _find_tk_root() fehlgeschlagen: %s", e)
                root = None

            if root is None:
                if debug_level >= 3:
                    logger.debug(
                        "[WATCHDOG] Kein Tk-Root verfügbar – Watchdog "
                        "nicht gestartet (wird bei nächstem "
                        "Dispatcher-Start erneut versucht)"
                    )
                return

            _last_idle_log: dict = {"ts": 0.0}

            def _check() -> None:
                _reschedule = True

                try:
                    if getattr(self, "_watchdog_after_id", None) is None:
                        if debug_level >= 4:
                            logger.debug(
                                "[WATCHDOG] Tick übersprungen – Watchdog "
                                "wurde extern gecancelt"
                            )
                        _reschedule = False
                        return

                    with contextlib.suppress(Exception):
                        self._watchdog_tick_count = (
                            getattr(self, "_watchdog_tick_count", 0) + 1
                        )

                    current_state = getattr(self, "_state", None)
                    state_name = (
                        current_state.name
                        if current_state is not None and hasattr(current_state, "name")
                        else str(current_state)
                    )

                    State = getattr(self, "State", None)
                    is_processing = State is not None and current_state == getattr(
                        State, "PROCESSING", None
                    )

                    if not is_processing:
                        now = time.monotonic()
                        if debug_level >= 4 and (
                            now - _last_idle_log["ts"] >= _idle_log_every
                        ):
                            _last_idle_log["ts"] = now
                            logger.debug(
                                "[WATCHDOG] Tick: State=%s – Watchdog "
                                "pausiert (kein Re-Schedule; wird bei "
                                "nächstem Stream-Start neu aktiviert)",
                                state_name,
                            )
                        _reschedule = False
                        return

                    disp_thread = getattr(self, "_dispatcher_thread", None)
                    disp_alive = bool(
                        disp_thread is not None and disp_thread.is_alive()
                    )

                    raw_q = getattr(self, "_raw_audio_queue", None)
                    q_size = 0
                    if raw_q is not None and hasattr(raw_q, "qsize"):
                        try:
                            q_size = raw_q.qsize()
                        except Exception:
                            q_size = -1

                    _tick = getattr(self, "_watchdog_tick_count", 0)
                    _watchdog_interesting = (
                        not disp_alive or q_size > 0 or state_name != "PROCESSING"
                    )
                    if debug_level >= 4 and (_watchdog_interesting or _tick % 60 == 0):
                        logger.debug(
                            "[WATCHDOG] Tick #%d: dispatcher_alive=%s, "
                            "qsize=%d, state=%s",
                            _tick,
                            disp_alive,
                            q_size,
                            state_name,
                        )

                    if disp_alive or q_size <= 0:
                        return

                    now = time.monotonic()
                    ts_list = getattr(self, "_watchdog_restart_timestamps", None)
                    if ts_list is None:
                        try:
                            self._watchdog_restart_timestamps = []
                            ts_list = self._watchdog_restart_timestamps
                        except Exception:
                            ts_list = None

                    if ts_list is not None:
                        cutoff = now - 60.0
                        with contextlib.suppress(Exception):
                            ts_list[:] = [t for t in ts_list if t > cutoff]

                        if len(ts_list) >= 5:
                            logger.warning(
                                "[WATCHDOG] ⚠️ Restart-Throttle aktiv "
                                "(%d Restarts in 60 s) – überspringe "
                                "Restart. Dispatcher scheint dauerhaft "
                                "defekt.",
                                len(ts_list),
                            )
                            return

                    logger.warning(
                        "[WATCHDOG] 🚨 Dispatcher tot, aber Queue "
                        "enthält %d Item(s) – starte Dispatcher neu",
                        q_size,
                    )

                    try:
                        self._watchdog_restart_count = (
                            getattr(self, "_watchdog_restart_count", 0) + 1
                        )
                        self._watchdog_last_restart_ts = time.time()
                        if ts_list is not None:
                            ts_list.append(now)
                    except Exception:
                        pass

                    try:
                        self._dispatcher_started = False
                        start_fn = getattr(self, "_start_dispatcher", None)
                        if callable(start_fn):
                            start_fn()
                            if debug_level >= 3:
                                logger.debug(
                                    "[WATCHDOG] ✅ Dispatcher-Restart "
                                    "eingeleitet (Restart-Nr. %d)",
                                    getattr(
                                        self,
                                        "_watchdog_restart_count",
                                        0,
                                    ),
                                )
                        else:
                            logger.error(
                                "[WATCHDOG] _start_dispatcher nicht "
                                "verfügbar – Restart unmöglich"
                            )
                    except Exception as e:
                        logger.error(
                            "[WATCHDOG] ❌ Dispatcher-Restart fehlgeschlagen: %s",
                            e,
                            exc_info=(debug_level >= 3),
                        )

                except Exception as e:
                    logger.error(
                        "[WATCHDOG] ❌ Fehler im Watchdog-Tick: %s",
                        e,
                        exc_info=(debug_level >= 4),
                    )
                finally:
                    if _reschedule and root is not None:
                        try:
                            self._watchdog_after_id = root.after(_interval_ms, _check)
                        except Exception as _e:
                            logger.debug(
                                "[WATCHDOG] Re-Schedule fehlgeschlagen: %s",
                                _e,
                            )
                            self._watchdog_after_id = None
                    else:
                        self._watchdog_after_id = None

            try:
                self._watchdog_after_id = root.after(_interval_ms, _check)
                if debug_level >= 3:
                    logger.debug(
                        "[WATCHDOG] ✅ Watchdog gestartet (after_id=%s, interval=%dms)",
                        self._watchdog_after_id,
                        _interval_ms,
                    )
            except Exception as e:
                logger.error(
                    "[WATCHDOG] Watchdog-Start fehlgeschlagen: %s",
                    e,
                    exc_info=(debug_level >= 3),
                )
                self._watchdog_after_id = None

        if lock is None:
            _impl()
            return

        try:
            with lock:
                _impl()
        except Exception as e:
            logger.error(
                "[WATCHDOG] Lock-Kontext fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

    def _cancel_watchdog(self) -> None:
        """Bricht den Watchdog-Timer ab (idempotent)."""
        import logging
        import threading

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        cancel_lock = getattr(self, "_watchdog_cancel_lock", None)
        if cancel_lock is None or not (
            hasattr(cancel_lock, "acquire") and hasattr(cancel_lock, "release")
        ):
            try:
                cancel_lock = threading.RLock()
                self._watchdog_cancel_lock = cancel_lock
            except Exception as e:
                logger.debug(
                    "[WATCHDOG] Cancel-Lock-Erstellung fehlgeschlagen: %s",
                    e,
                )
                cancel_lock = None

        def _impl() -> None:
            wid = getattr(self, "_watchdog_after_id", None)
            if wid is None:
                if debug_level >= 4:
                    logger.debug("[WATCHDOG] Kein aktiver Timer zu canceln")
                return

            root = None
            try:
                find_fn = getattr(self, "_find_tk_root", None)
                if callable(find_fn):
                    root = find_fn()
            except Exception as e:
                logger.debug("[WATCHDOG] _find_tk_root() fehlgeschlagen: %s", e)
                root = None

            cancel_success = False
            if root is not None and hasattr(root, "after_cancel"):
                try:
                    root.after_cancel(wid)
                    cancel_success = True
                    if debug_level >= 3:
                        logger.debug(
                            "[WATCHDOG] ✅ Watchdog gecancelt (after_id=%s)",
                            wid,
                        )
                except Exception as e:
                    if debug_level >= 5:
                        logger.debug(
                            "[WATCHDOG] after_cancel(%s) fehlgeschlagen: %s",
                            wid,
                            e,
                            exc_info=True,
                        )
                    else:
                        logger.debug(
                            "[WATCHDOG] after_cancel(%s) fehlgeschlagen: %s",
                            wid,
                            e,
                        )
            else:
                if debug_level >= 4:
                    if root is None:
                        logger.debug(
                            "[WATCHDOG] Kein Root – kann after_id=%s "
                            "nicht canceln (wird beim Prozess-Ende "
                            "aufgeräumt)",
                            wid,
                        )
                    else:
                        logger.debug(
                            "[WATCHDOG] Root hat kein after_cancel – "
                            "kann after_id=%s nicht canceln",
                            wid,
                        )

            try:
                self._watchdog_after_id = None
                if cancel_success and debug_level >= 5:
                    logger.debug("[WATCHDOG] _watchdog_after_id zurückgesetzt")
            except Exception as e:
                logger.debug(
                    "[WATCHDOG] _watchdog_after_id reset fehlgeschlagen: %s",
                    e,
                )

        if cancel_lock is None:
            _impl()
            return

        try:
            with cancel_lock:
                _impl()
        except Exception as e:
            with contextlib.suppress(Exception):
                self._watchdog_after_id = None
            if debug_level >= 3:
                logger.debug("[WATCHDOG] Cancel-Lock-Kontext fehlgeschlagen: %s", e)

    def _on_dispatcher_stuck(self, data: dict) -> None:
        """Wird aufgerufen, wenn ein Dispatcher-Stuck erkannt wird."""
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        try:
            data_repr = str(data)[:200] if data else "(keine Daten)"
        except Exception:
            data_repr = "(nicht serialisierbar)"

        if debug_level >= 3:
            logger.debug("[DISP-EVENT] stuck-Event empfangen: %s", data_repr)

        try:
            if getattr(self, "_shutdown_impl_entry_count", 0) > 0:
                if not getattr(self, "_guaranteed_cleanup_done", False):
                    logger.debug("[DISP-EVENT] stuck ignoriert – Shutdown läuft")
                    return
        except Exception:
            pass

        try:
            stop_evt = getattr(self, "_stop_event", None)
            if stop_evt is not None and hasattr(stop_evt, "is_set"):
                if stop_evt.is_set():
                    logger.debug("[DISP-EVENT] stuck ignoriert – Stop-Event gesetzt")
                    return
        except Exception:
            pass

        try:
            if self._state == self.State.IDLE:
                logger.debug("[DISP-EVENT] stuck ignoriert – State ist bereits IDLE")
                return
        except Exception:
            pass

        try:
            now = time.monotonic()
            ts_list = getattr(self, "_disp_stuck_restart_ts", None)
            if ts_list is None:
                self._disp_stuck_restart_ts = []
                ts_list = self._disp_stuck_restart_ts

            cutoff = now - 60.0
            ts_list[:] = [t for t in ts_list if t > cutoff]

            if len(ts_list) >= 3:
                logger.warning(
                    "[DISP-EVENT] ⚠️ stuck-Restart-Throttle aktiv "
                    "(%d Restarts in den letzten 60 s) – überspringe",
                    len(ts_list),
                )
                return
        except Exception:
            ts_list = None

        logger.warning("🔄 Dispatcher stuck – restarting... (data=%s)", data_repr)
        try:
            restart_fn = getattr(self, "_restart_dispatcher", None)
            if callable(restart_fn):
                success = restart_fn()
                if debug_level >= 3:
                    logger.debug("[DISP-EVENT] stuck-Restart-Ergebnis: %s", success)
            else:
                logger.error("[DISP-EVENT] _restart_dispatcher nicht verfügbar")

            if ts_list is not None:
                with contextlib.suppress(Exception):
                    ts_list.append(time.monotonic())
        except Exception as e:
            logger.error(
                "[DISP-EVENT] ❌ stuck-Restart fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

    def _find_tk_root(self):
        """Findet den Tk-Root über mehrere Fallback-Strategien."""
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        for attr in ("root", "_root", "gui_root", "_tk_root"):
            candidate = getattr(self, attr, None)
            if candidate is not None and hasattr(candidate, "after"):
                if debug_level >= 4:
                    logger.debug("[WATCHDOG] Root gefunden via self.%s", attr)
                return candidate

        ctrl = getattr(self, "controller_ref", None)
        if ctrl is not None:
            gui_ref = getattr(ctrl, "gui_ref", None)
            if callable(gui_ref):
                try:
                    gui = gui_ref()
                    if gui is not None:
                        for attr in ("root", "_root", "master"):
                            candidate = getattr(gui, attr, None)
                            if candidate is not None and hasattr(candidate, "after"):
                                if debug_level >= 4:
                                    logger.debug(
                                        "[WATCHDOG] Root via "
                                        "controller_ref.gui_ref().%s",
                                        attr,
                                    )
                                return candidate
                except Exception as e:
                    if debug_level >= 4:
                        logger.debug("[WATCHDOG] gui_ref() fehlgeschlagen: %s", e)

        if ctrl is not None:
            gui = getattr(ctrl, "gui", None)
            if gui is not None:
                for attr in ("root", "_root", "master"):
                    candidate = getattr(gui, attr, None)
                    if candidate is not None and hasattr(candidate, "after"):
                        if debug_level >= 4:
                            logger.debug(
                                "[WATCHDOG] Root via controller_ref.gui.%s", attr
                            )
                        return candidate

        try:
            import __main__

            gui = getattr(__main__, "_DRAGON_GUI_INSTANCE", None)
            if gui is not None:
                for attr in ("root", "_root", "master"):
                    candidate = getattr(gui, attr, None)
                    if candidate is not None and hasattr(candidate, "after"):
                        if debug_level >= 4:
                            logger.debug(
                                "[WATCHDOG] Root via __main__._DRAGON_GUI_INSTANCE.%s",
                                attr,
                            )
                        return candidate
        except Exception as e:
            if debug_level >= 4:
                logger.debug("[WATCHDOG] __main__-Strategie fehlgeschlagen: %s", e)

        try:
            from app_context import AppContext

            ctx = AppContext()
            gui = getattr(ctx, "gui", None) or getattr(ctx, "_gui", None)
            if gui is not None:
                for attr in ("root", "_root", "master"):
                    candidate = getattr(gui, attr, None)
                    if candidate is not None and hasattr(candidate, "after"):
                        if debug_level >= 4:
                            logger.debug(
                                "[WATCHDOG] Root via AppContext.gui.%s",
                                attr,
                            )
                        return candidate
        except Exception as e:
            if debug_level >= 4:
                logger.debug("[WATCHDOG] AppContext-Strategie fehlgeschlagen: %s", e)

        return None

    def _on_dispatcher_died(self, data: dict) -> None:
        """Wird aufgerufen, wenn der Dispatcher-Thread unerwartet stirbt."""
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        try:
            data_repr = str(data)[:200] if data else "(keine Daten)"
        except Exception:
            data_repr = "(nicht serialisierbar)"

        if debug_level >= 3:
            logger.debug("[DISP-EVENT] died-Event empfangen: %s", data_repr)

        try:
            if getattr(self, "_shutdown_impl_entry_count", 0) > 0:
                if not getattr(self, "_guaranteed_cleanup_done", False):
                    logger.debug("[DISP-EVENT] died ignoriert – Shutdown läuft")
                    return
        except Exception:
            pass

        try:
            stop_evt = getattr(self, "_stop_event", None)
            if stop_evt is not None and hasattr(stop_evt, "is_set"):
                if stop_evt.is_set():
                    logger.debug("[DISP-EVENT] died ignoriert – Stop-Event gesetzt")
                    return
        except Exception:
            pass

        try:
            if self._state == self.State.IDLE:
                logger.debug("[DISP-EVENT] died ignoriert – State ist bereits IDLE")
                return
        except Exception:
            pass

        try:
            disp_thread = getattr(self, "_dispatcher_thread", None)
            if disp_thread is not None and disp_thread.is_alive():
                logger.debug(
                    "[DISP-EVENT] died ignoriert – aktueller "
                    "Dispatcher-Thread läuft noch (Alive-Check)"
                )
                return
        except Exception:
            pass

        try:
            now = time.monotonic()
            ts_list = getattr(self, "_disp_died_restart_ts", None)
            if ts_list is None:
                self._disp_died_restart_ts = []
                ts_list = self._disp_died_restart_ts

            cutoff = now - 60.0
            ts_list[:] = [t for t in ts_list if t > cutoff]

            if len(ts_list) >= 3:
                logger.warning(
                    "[DISP-EVENT] ⚠️ died-Restart-Throttle aktiv "
                    "(%d Restarts in den letzten 60 s) – überspringe",
                    len(ts_list),
                )
                return
        except Exception:
            ts_list = None

        logger.warning("🔄 Dispatcher died – restarting... (data=%s)", data_repr)
        try:
            restart_fn = getattr(self, "_restart_dispatcher", None)
            if callable(restart_fn):
                success = restart_fn()
                if debug_level >= 3:
                    logger.debug("[DISP-EVENT] died-Restart-Ergebnis: %s", success)
            else:
                logger.error("[DISP-EVENT] _restart_dispatcher nicht verfügbar")

            if ts_list is not None:
                with contextlib.suppress(Exception):
                    ts_list.append(time.monotonic())
        except Exception as e:
            logger.error(
                "[DISP-EVENT] ❌ died-Restart fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

    def _restart_dispatcher(self) -> bool:
        """Stoppt den alten Dispatcher und startet einen neuen – mit erweitertem
        Rate‑Limiting, Backoff, Health‑Check und Thread‑Diagnose.
        """
        if not hasattr(self, "_restart_attempt_counter"):
            self._restart_attempt_counter = 0
            self._restart_timestamps = []
            self._last_restart_time = 0.0
            self._restart_failures = 0
            self._dispatcher_restart_lock = threading.RLock()
            self._total_restarts = 0
            self._restart_max_total = 50
            self._restart_success_count = 0
            self._restart_last_success_time = 0.0

        if not hasattr(self, "_dispatcher_started"):
            self._dispatcher_started = False
        if not hasattr(self, "_dispatcher_thread"):
            self._dispatcher_thread = None
        if not hasattr(self, "_shutting_down"):
            self._shutting_down = False
        if not hasattr(self, "_pending_tasks"):
            self._pending_tasks = 0
        if not hasattr(self, "_pending_tasks_lock"):
            self._pending_tasks_lock = threading.RLock()
        if not hasattr(self, "_dispatcher_stop_event"):
            self._dispatcher_stop_event = threading.Event()

        THREAD_JOIN_TIMEOUT = getattr(self, "_restart_thread_join_timeout", 2.0)
        POST_RESTART_WAIT = getattr(self, "_restart_post_wait", 0.2)
        HEALTH_CHECK_ENABLED = getattr(self, "_restart_health_check_enabled", True)
        HEALTH_CHECK_TIMEOUT = getattr(self, "_restart_health_check_timeout", 0.5)
        RATE_LIMIT_WINDOW = 60.0
        RATE_LIMIT_MAX = 5

        if self._shutting_down:
            log_debug("dispatcher", "  → Shutdown aktiv – kein Neustart")
            return False

        now = time.monotonic()

        with self._dispatcher_restart_lock:
            self._restart_timestamps = [
                t for t in self._restart_timestamps if now - t < RATE_LIMIT_WINDOW
            ]

            if len(self._restart_timestamps) >= RATE_LIMIT_MAX:
                logger.warning(
                    "_restart_dispatcher: Zu viele Neustarts (%d in %d Sekunden) – überspringe",
                    len(self._restart_timestamps),
                    int(RATE_LIMIT_WINDOW),
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("dispatcher", "  → Rate‑Limit erreicht, kein Neustart")
                return False

            if self._total_restarts >= self._restart_max_total:
                logger.error(
                    "_restart_dispatcher: Maximale Neustarts (%d) erreicht – keine automatische Wiederherstellung mehr",
                    self._restart_max_total,
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("dispatcher", "  → Max. Neustarts überschritten")
                return False

            self._restart_attempt_counter += 1
            self._restart_timestamps.append(now)
            self._last_restart_time = now
            self._total_restarts += 1

        if self._restart_failures > 0:
            import random

            base_delay = min(30.0, 0.5 * (2 ** min(self._restart_failures, 10)))
            jitter = random.uniform(0, base_delay * 0.2)
            backoff_delay = base_delay + jitter

            log_debug(
                "dispatcher",
                "  → Backoff‑Delay: %.2fs (Failures=%d, base=%.2f, jitter=%.2f)",
                backoff_delay,
                self._restart_failures,
                base_delay,
                jitter,
            )
            time.sleep(backoff_delay)

        if DEBUG_LEVEL >= 3:
            old_thread = self._dispatcher_thread
            old_thread_id = (
                old_thread.ident if (old_thread and old_thread.is_alive()) else "None"
            )
            old_thread_alive = old_thread.is_alive() if old_thread else False
            import traceback

            stack_trace = ""
            if old_thread and old_thread.is_alive():
                try:
                    import sys

                    frame = sys._current_frames().get(old_thread.ident)
                    if frame:
                        stack_trace = "".join(traceback.format_stack(frame))
                        if len(stack_trace) > 500:
                            stack_trace = stack_trace[:500] + "... (gekürzt)"
                except Exception as e:
                    stack_trace = f"(Fehler beim Abrufen des Stack‑Traces: {e})"

            log_debug(
                "dispatcher",
                "  → Diagnose vor Neustart: thread_id=%s, alive=%s, stack=%s",
                old_thread_id,
                old_thread_alive,
                stack_trace or "(nicht verfügbar)",
            )

            with self._pending_tasks_lock:
                pending = self._pending_tasks
                if pending > 0:
                    log_debug(
                        "dispatcher",
                        "  → Achtung: %d pending_tasks beim Neustart!",
                        pending,
                    )

        with self._dispatcher_restart_lock:
            logger.info(
                "🔄 Dispatcher‑Neustart wird eingeleitet (Versuch #%d, Fehler=%d, total=%d)",
                self._restart_attempt_counter,
                self._restart_failures,
                self._total_restarts,
            )

            if self._dispatcher_started:
                if DEBUG_LEVEL >= 3:
                    logger.debug("_start_dispatcher: Stoppe alten Dispatcher...")
                try:
                    self._stop_dispatcher(clear_queue=True)
                    if DEBUG_LEVEL >= 4:
                        log_debug("dispatcher", "  → _stop_dispatcher erfolgreich")
                except Exception as e:
                    logger.error(
                        "_restart_dispatcher: Fehler beim Stoppen des alten Dispatchers: %s",
                        e,
                        exc_info=True,
                    )
            elif DEBUG_LEVEL >= 3:
                log_debug("dispatcher", "  → Dispatcher war bereits gestoppt")

            old_thread = self._dispatcher_thread
            if old_thread is not None and old_thread.is_alive():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "dispatcher",
                        "  → Warte auf Beendigung des alten Dispatcher‑Threads (max. %.1fs)...",
                        THREAD_JOIN_TIMEOUT,
                    )
                old_thread.join(timeout=THREAD_JOIN_TIMEOUT)
                if old_thread.is_alive():
                    logger.warning(
                        "_restart_dispatcher: Alter Dispatcher‑Thread beendet sich nicht – "
                        "wird ignoriert und neu gestartet (Thread‑ID: %s)",
                        old_thread.ident,
                    )
                    with contextlib.suppress(RuntimeError):
                        old_thread.daemon = True
                    self._dispatcher_stop_event.set()
                elif DEBUG_LEVEL >= 4:
                    log_debug(
                        "dispatcher",
                        "  → Alter Dispatcher‑Thread erfolgreich beendet",
                    )
            elif DEBUG_LEVEL >= 4:
                log_debug(
                    "dispatcher",
                    "  → Kein alter Dispatcher‑Thread vorhanden",
                )

            time.sleep(POST_RESTART_WAIT)

            if DEBUG_LEVEL >= 3:
                log_debug("dispatcher", "  → Starte neuen Dispatcher...")

            try:
                self._dispatcher_stop_event.clear()
                self._start_dispatcher()
            except Exception as e:
                logger.error(
                    "_restart_dispatcher: Fehler beim Starten des neuen Dispatchers: %s",
                    e,
                    exc_info=True,
                )
                self._dispatcher_started = False
                self._restart_failures += 1
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "dispatcher",
                        "  → Neustart fehlgeschlagen, _restart_failures=%d",
                        self._restart_failures,
                    )
                return False

            if (
                self._dispatcher_started
                and self._dispatcher_thread is not None
                and self._dispatcher_thread.is_alive()
            ):
                time.sleep(0.05)

                health_ok = True
                if HEALTH_CHECK_ENABLED:
                    health_ok = self._verify_dispatcher_health(HEALTH_CHECK_TIMEOUT)

                if health_ok:
                    self._restart_success_count += 1
                    self._restart_last_success_time = now

                    if self._restart_failures < 3:
                        self._restart_attempt_counter = 0
                        self._restart_failures = 0
                    else:
                        self._restart_failures = max(0, self._restart_failures - 1)

                    logger.info(
                        "✅ Dispatcher erfolgreich neu gestartet (PID: %s, Versuch #%d, total=%d, success_count=%d)",
                        self._dispatcher_thread.ident,
                        self._restart_attempt_counter,
                        self._total_restarts,
                        self._restart_success_count,
                    )
                    return True
                logger.warning(
                    "⚠️ Dispatcher gestartet, aber Health‑Check fehlgeschlagen (Thread‑ID: %s)",
                    (
                        self._dispatcher_thread.ident
                        if self._dispatcher_thread
                        else "None"
                    ),
                )
                self._dispatcher_started = False
                self._restart_failures += 1
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "dispatcher",
                        "  → Health‑Check fehlgeschlagen, _restart_failures=%d",
                        self._restart_failures,
                    )
                return False

            logger.error(
                "❌ Dispatcher‑Neustart fehlgeschlagen – Thread ist nicht am Leben "
                "(started=%s, thread=%s)",
                self._dispatcher_started,
                self._dispatcher_thread,
            )
            self._dispatcher_started = False
            self._restart_failures += 1
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "dispatcher",
                    "  → Neustart fehlgeschlagen, _restart_failures=%d",
                    self._restart_failures,
                )
            return False

    def _verify_dispatcher_health(self, timeout: float = 0.5) -> bool:
        """Überprüft, ob der Dispatcher nach dem Neustart tatsächlich funktioniert."""
        if not hasattr(self, "_dispatcher_thread") or self._dispatcher_thread is None:
            log_debug("dispatcher", "  → Health‑Check: _dispatcher_thread ist None")
            return False

        if not self._dispatcher_thread.is_alive():
            log_debug("dispatcher", "  → Health‑Check: Thread ist nicht am Leben")
            return False

        if not getattr(self, "_dispatcher_started", False):
            log_debug("dispatcher", "  → Health‑Check: _dispatcher_started ist False")
            return False

        if getattr(self, "_shutting_down", False):
            log_debug("dispatcher", "  → Health‑Check: _shutting_down ist True")
            return False

        if hasattr(self, "_dispatcher_queue") and self._dispatcher_queue is not None:
            try:
                import time

                ping_token = f"ping_{time.monotonic()}"
                self._dispatcher_queue.put(ping_token, block=False)
                time.sleep(0.05)

                try:
                    response = self._dispatcher_queue.get(timeout=timeout)
                    if response == f"pong_{ping_token}":
                        log_debug(
                            "dispatcher",
                            "  → Health‑Check: Queue-Ping erfolgreich",
                        )
                        return True
                    log_debug(
                        "dispatcher",
                        f"  → Health‑Check: Ungültige Ping-Antwort: {response}",
                    )
                    return False
                except Exception as e:
                    log_debug(
                        "dispatcher",
                        f"  → Health‑Check: Keine Ping-Antwort innerhalb {timeout}s: {e}",
                    )
                    return False

            except Exception as e:
                log_debug(
                    "dispatcher",
                    f"  → Health‑Check: Queue‑Test fehlgeschlagen: {e}",
                )
                return False

        if (
            hasattr(self, "_dispatcher_last_activity")
            and self._dispatcher_last_activity
        ):
            import time

            last_activity = self._dispatcher_last_activity
            elapsed = time.monotonic() - last_activity
            max_idle = getattr(self, "_dispatcher_health_max_idle", 30.0)

            if elapsed > max_idle:
                log_debug(
                    "dispatcher",
                    f"  → Health‑Check: Keine Aktivität seit {elapsed:.1f}s (max {max_idle}s)",
                )
                return False
            log_debug(
                "dispatcher",
                f"  → Health‑Check: Letzte Aktivität vor {elapsed:.1f}s",
            )

        if hasattr(self, "_pending_tasks") and hasattr(self, "_pending_tasks_lock"):
            with self._pending_tasks_lock:
                pending = self._pending_tasks
                max_pending = getattr(self, "_dispatcher_health_max_pending", 500)

                if pending > max_pending:
                    log_debug(
                        "dispatcher",
                        f"  → Health‑Check: Zu viele ausstehende Tasks: {pending} > {max_pending}",
                    )
                    return False
                if pending > 0:
                    log_debug(
                        "dispatcher",
                        f"  → Health‑Check: {pending} ausstehende Tasks (unter Limit)",
                    )

        log_debug("dispatcher", "  → Health‑Check: ✅ Dispatcher ist gesund")
        return True

    def _check_queue_after_error(self) -> None:
        """Prüft nach einem Fehler den Zustand der Audio‑Queue und des Dispatchers.
        Bei Überlast oder totem Dispatcher wird ein Neustart eingeleitet.
        """
        if not self.is_processing() or self._stop_event.is_set():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "queue_check",
                    "_check_queue_after_error: Nicht im Processing‑Modus oder Stop‑Event gesetzt – überspringe",
                )
            return

        queue_size = 0
        try:
            if self._raw_audio_queue is not None:
                queue_size = self._raw_audio_queue.qsize()
        except Exception as e:
            logger.warning(
                f"_check_queue_after_error: Konnte Queue‑Größe nicht ermitteln: {e}",
            )
            return

        dispatcher_alive = False
        try:
            dispatcher_alive = (
                self._dispatcher_thread is not None
                and self._dispatcher_thread.is_alive()
            )
        except Exception as e:
            logger.warning(
                f"_check_queue_after_error: Konnte Dispatcher‑Status nicht prüfen: {e}",
            )

        QUEUE_OVERFLOW_THRESHOLD = 100
        should_restart = False
        reason = ""

        if queue_size > QUEUE_OVERFLOW_THRESHOLD:
            should_restart = True
            reason = f"Queue‑Überlauf ({queue_size} > {QUEUE_OVERFLOW_THRESHOLD})"
        elif not dispatcher_alive and not self._dispatcher_shutdown.is_set():
            should_restart = True
            reason = "Dispatcher‑Thread tot"

        if not should_restart:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "queue_check",
                    f"_check_queue_after_error: Zustand OK (queue={queue_size}, dispatcher_alive={dispatcher_alive})",
                )
            return

        if not hasattr(self, "_restart_attempt_counter"):
            self._restart_attempt_counter = 0
        if not hasattr(self, "_last_restart_time"):
            self._last_restart_time = 0.0

        now = time.monotonic()
        if now - self._last_restart_time < 10.0:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "queue_check",
                    f"_check_queue_after_error: Neustart zu häufig – überspringe (letzter vor {
                        now - self._last_restart_time:.1f}s)",
                )
            return

        if self._restart_attempt_counter >= 10:
            logger.error(
                "_check_queue_after_error: Maximale Anzahl von Dispatcher‑Neustarts erreicht – keine automatische Wiederherstellung mehr",
            )
            return

        logger.warning(
            f"🔄 _check_queue_after_error: Starte Dispatcher‑Neustart (Grund: {reason})",
        )
        self._restart_attempt_counter += 1
        self._last_restart_time = now

        try:
            self._restart_dispatcher()
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "queue_check",
                    f"Dispatcher‑Neustart erfolgreich (Versuch #{
                        self._restart_attempt_counter
                    })",
                )
        except Exception as e:
            logger.error(
                f"_check_queue_after_error: Dispatcher‑Neustart fehlgeschlagen: {e}",
                exc_info=True,
            )

        if DEBUG_LEVEL >= 3:
            try:
                import traceback

                stack = "".join(traceback.format_stack()[:-2])
                log_debug("queue_check", f"Aufrufer‑Stack:\n{stack}")
            except Exception:
                pass

    def _rescue_remaining_queue_items(
        self,
        max_items: int | None = None,
    ) -> dict[str, int]:
        """Rettet alle (oder maximal `max_items`) in der Rohdaten‑Queue wartenden Audio‑Chunks."""
        rescued = 0
        saved_to_disk = 0
        empty_or_invalid = 0

        if self._raw_audio_queue is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    "_rescue_remaining_queue_items: raw_audio_queue ist None – nichts zu retten.",
                )
            return {"rescued": 0, "saved_to_disk": 0, "empty_or_invalid": 0}

        if DEBUG_LEVEL >= 3:
            try:
                qsize_before = self._raw_audio_queue.qsize()
                log_debug(
                    "processor",
                    "_rescue_remaining_queue_items: Start, max_items=%s, queue_size=%d",
                    max_items if max_items is not None else "unbegrenzt",
                    qsize_before,
                )
            except Exception:
                log_debug(
                    "processor",
                    "_rescue_remaining_queue_items: Start, max_items=%s",
                    max_items,
                )

        while True:
            if (
                max_items is not None
                and (rescued + saved_to_disk + empty_or_invalid) >= max_items
            ):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "processor",
                        "_rescue_remaining_queue_items: Limit %d erreicht, breche ab.",
                        max_items,
                    )
                break

            item = None
            try:
                item = self._raw_audio_queue.get_nowait()
            except queue.Empty:
                break
            except AttributeError:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "processor",
                        "_rescue_remaining_queue_items: Queue existiert nicht mehr (AttributeError).",
                    )
                break
            except Exception as exc:
                logger.warning(
                    "_rescue_remaining_queue_items: Fehler beim Lesen der Queue: %s",
                    exc,
                )
                break

            try:
                if item is None:
                    continue

                if not isinstance(item, tuple) or len(item) < 3:
                    logger.debug(
                        "_rescue_remaining_queue_items: Ungültiges Queue‑Element "
                        "(Typ %s, Länge %d) – verworfen.",
                        type(item).__name__,
                        len(item) if isinstance(item, (tuple, list)) else -1,
                    )
                    empty_or_invalid += 1
                    continue

                if len(item) >= 5:
                    audio_data, chunk_offset, trans_cb, transl_cb, error_cb = item[:5]
                else:
                    audio_data, trans_cb, transl_cb, error_cb = item[:4]
                    chunk_offset = None

                if not audio_data or len(audio_data) < 16:
                    empty_or_invalid += 1
                    continue

                success = False
                executor = self._transcription_executor

                if executor is not None:
                    self._modify_pending_tasks(1, reason="rescue_chunk")
                    try:
                        future = executor.submit(
                            self._process_audio_chunk_async,
                            audio_data,
                            trans_cb,
                            transl_cb,
                            error_cb,
                            chunk_byte_offset=chunk_offset,
                        )

                        future.add_done_callback(
                            lambda f: self._modify_pending_tasks(
                                -1,
                                reason="rescue_done",
                            ),
                        )
                        success = True
                        rescued += 1
                    except RuntimeError as exc:
                        logger.debug(
                            "Executor während Rettung nicht verfügbar – "
                            "Chunk wird als WAV gesichert. (%s)",
                            exc,
                        )
                        self._modify_pending_tasks(-1, reason="rescue_failed")
                    except Exception as exc:
                        logger.error(
                            "Unerwarteter Fehler beim Retten eines Chunks: %s",
                            exc,
                            exc_info=DEBUG_LEVEL >= 3,
                        )
                        self._modify_pending_tasks(-1, reason="rescue_failed")
                else:
                    logger.debug(
                        "Kein Executor vorhanden – Chunk wird als WAV gesichert.",
                    )

                if not success:
                    try:
                        self._save_lost_chunk(audio_data, "rescue_no_executor")
                        saved_to_disk += 1
                    except Exception as save_exc:
                        logger.error(
                            "Sicherung des verlorenen Chunks fehlgeschlagen: %s",
                            save_exc,
                        )

            finally:
                try:
                    self._raw_audio_queue.task_done()
                except ValueError:
                    pass
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_debug("processor", "task_done() fehlgeschlagen: %s", e)

        if rescued > 0 or saved_to_disk > 0:
            logger.info(
                "🛟 Queue‑Rettung: %d Chunk(s) an Executor übergeben, "
                "%d als WAV gesichert, %d ungültige/leere Elemente ignoriert.",
                rescued,
                saved_to_disk,
                empty_or_invalid,
            )
            if self._event_bus is not None:
                try:
                    self._event_bus.emit(
                        "info",
                        f"🛟 {rescued} Audio‑Chunk(s) gerettet"
                        + (
                            f", {saved_to_disk} als Datei gesichert"
                            if saved_to_disk > 0
                            else ""
                        ),
                    )
                except Exception as exc:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "processor",
                            "Event‑Bus Benachrichtigung fehlgeschlagen: %s",
                            exc,
                        )
        elif DEBUG_LEVEL >= 3:
            log_debug(
                "processor",
                "_rescue_remaining_queue_items: Keine Chunks gerettet (Queue leer oder bereits abgearbeitet).",
            )

        return {
            "rescued": rescued,
            "saved_to_disk": saved_to_disk,
            "empty_or_invalid": empty_or_invalid,
        }

    def _clear_and_sync_queue(self) -> None:
        """Leert die interne Rohdaten‑Queue (``_raw_audio_queue``) vollständig,
        ruft für jedes entnommene Element ``task_done()`` auf und
        synchronisiert abschließend das ``_tasks_done_event`` mit dem
        aktuellen ``_pending_tasks``‑Zähler.
        """
        queue_obj = self._raw_audio_queue
        if queue_obj is None:
            if DEBUG_LEVEL >= 3:
                log_debug("processor", "_clear_and_sync_queue: queue_obj is None")
            return

        cleared_items = 0
        cleared_bytes = 0
        task_done_errors = 0

        while True:
            item = None
            try:
                item = queue_obj.get_nowait()
            except queue.Empty:
                break
            except Exception as exc:
                logger.warning(
                    "_clear_and_sync_queue: Fehler beim Lesen der Queue: %s",
                    exc,
                )
                break

            if item is not None:
                if (
                    isinstance(item, tuple)
                    and len(item) >= 1
                    and isinstance(item[0], bytes)
                ):
                    cleared_bytes += len(item[0])
                elif isinstance(item, bytes):
                    cleared_bytes += len(item)
                cleared_items += 1

            task_done_method = getattr(queue_obj, "task_done", None)
            if task_done_method is not None:
                try:
                    task_done_method()
                except Exception as exc:
                    task_done_errors += 1
                    logger.warning("_clear_and_sync_queue: task_done() Fehler: %s", exc)

        if cleared_items > 0 and DEBUG_LEVEL >= 2:
            log_debug(
                "processor",
                "_clear_and_sync_queue: %d Element(e) entfernt (%d Bytes), "
                "task_done‑Fehler: %d",
                cleared_items,
                cleared_bytes,
                task_done_errors,
            )

        self._synchronize_tasks_done_event()

    def _drain_audio_queue_after_shutdown(self) -> None:
        """Entleert die Rohdaten-Queue und ruft für jedes entfernte Element task_done() auf,
        um den internen Zähler der Queue zu synchronisieren.

        """
        if self._pending_tasks > 0 or self._dispatcher_started:
            logger.error(
                "_drain_audio_queue_after_shutdown aufgerufen, obwohl noch %d Aufgaben "
                "ausstehen oder der Dispatcher aktiv ist. Abbruch, um Queue-Korruption zu vermeiden.",
                self._pending_tasks,
            )
            return

        queue_obj = self._raw_audio_queue
        if queue_obj is None:
            logger.debug(
                "_drain_audio_queue_after_shutdown: raw_audio_queue ist None – nichts zu tun.",
            )
            return

        drained_items = 0
        while True:
            try:
                queue_obj.get_nowait()
            except queue.Empty:
                break
            try:
                queue_obj.task_done()
            except ValueError:
                if drained_items == 0:
                    logger.debug(
                        "_drain_audio_queue_after_shutdown: task_done() schlug fehl "
                        "(Zähler bereits 0).",
                    )
            drained_items += 1

        if drained_items > 0:
            logger.info(
                "_drain_audio_queue_after_shutdown: %d Elemente aus der Queue entfernt "
                "und synchronisiert.",
                drained_items,
            )
        else:
            logger.debug("_drain_audio_queue_after_shutdown: Queue war bereits leer.")

    def _synchronize_tasks_done_event(self) -> None:
        """Bringt den Zustand des ``_tasks_done_event`` mit dem aktuellen
        Wert von ``_pending_tasks`` in Einklang.
        """
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        cond = getattr(self, "_pending_tasks_cond", None)
        if cond is None:
            logger.warning(
                "_synchronize_tasks_done_event: _pending_tasks_cond ist None – erstelle neues",
                extra={"component": "task_event"},
            )
            self._pending_tasks_cond = threading.Condition()
            self._pending_tasks = 0
            self._tasks_done_event = threading.Event()
            self._tasks_done_event.set()
            return

        if not hasattr(self, "_tasks_done_event") or self._tasks_done_event is None:
            logger.debug(
                "_synchronize_tasks_done_event: _tasks_done_event ist None – erstelle neues",
                extra={"component": "task_event"},
            )
            self._tasks_done_event = threading.Event()

        with cond:
            pending = getattr(self, "_pending_tasks", 0)

            if pending < 0:
                logger.warning(
                    "_synchronize_tasks_done_event: pending_tasks war negativ (%d) – "
                    "wird auf 0 korrigiert. Dies deutet auf einen doppelten "
                    "task_done()‑Aufruf oder einen inkonsistenten Zustand hin.",
                    pending,
                    extra={"component": "task_event"},
                )
                self._pending_tasks = 0
                pending = 0

            if pending == 0:
                self._tasks_done_event.set()
                if debug_level >= 3:
                    logger.debug(
                        "_tasks_done_event SET (pending=0, via _synchronize)",
                        extra={"component": "task_event"},
                    )
            else:
                self._tasks_done_event.clear()
                if debug_level >= 3:
                    logger.debug(
                        f"_tasks_done_event CLEAR (pending={pending}, via _synchronize)",
                        extra={"component": "task_event"},
                    )

            try:
                cond.notify_all()
            except RuntimeError as e:
                logger.error(
                    f"Fehler beim Benachrichtigen der Bedingungsvariablen: {e}",
                    exc_info=True,
                    extra={"component": "task_event"},
                )

            if pending > 100 and pending % 50 == 0:
                logger.warning(
                    f"⚠️ Hohe Anzahl ausstehender Tasks bei Synchronisation: {pending}",
                    extra={"component": "task_event"},
                )
            elif pending > 500:
                logger.warning(
                    f"🚨 Sehr hohe Anzahl ausstehender Tasks ({pending}) – "
                    "möglicherweise hängt der Dispatcher oder die Executoren sind überlastet.",
                    extra={"component": "task_event"},
                )
                if debug_level >= 3:
                    try:
                        queue = getattr(self, "_raw_audio_queue", None)
                        qsize = queue.qsize() if queue is not None else -1

                        dispatcher_thread = getattr(self, "_dispatcher_thread", None)
                        dispatcher_alive = (
                            dispatcher_thread.is_alive()
                            if dispatcher_thread is not None
                            else False
                        )

                        stop_event = getattr(self, "_stop_event", None)
                        stop_event_set = (
                            stop_event.is_set() if stop_event is not None else False
                        )

                        logger.debug(
                            f"Diagnose: queue_size={qsize}, dispatcher_alive={dispatcher_alive}, "
                            f"stop_event={stop_event_set}",
                            extra={"component": "task_event"},
                        )
                    except Exception as e:
                        logger.debug(
                            f"Diagnose-Fehler: {e}",
                            extra={"component": "task_event"},
                        )

    def _dispatcher_loop(self) -> None:
        """Hintergrund‑Thread, der Audiodaten aus der Rohdaten‑Queue entnimmt
        und als Transkriptions‑Tasks an den Executor übergibt.
        ULTIMATIVE EDITION – mit Metriken, konsistentem Logging und konfigurierbaren Werten.
        """
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not hasattr(self, "_dispatcher_err_cb"):
            self._dispatcher_err_cb = None
        if not hasattr(self, "_dispatcher_stop_event"):
            self._dispatcher_stop_event = threading.Event()
        if not hasattr(self, "_dispatcher_shutdown"):
            self._dispatcher_shutdown = threading.Event()
        if not hasattr(self, "_pending_tasks_cond"):
            self._pending_tasks_cond = threading.Condition(threading.RLock())

        max_restarts = getattr(self, "DISPATCHER_MAX_RESTARTS", 10)
        backoff_base = getattr(self, "DISPATCHER_BACKOFF_BASE", 0.3)
        min_restart_interval = getattr(self, "DISPATCHER_MIN_RESTART_INTERVAL", 2.0)
        getattr(self, "DISPATCHER_METRIC_INTERVAL", 300.0)

        if not hasattr(self, "_dispatcher_start_time"):
            self._dispatcher_start_time = time.time()
        if not hasattr(self, "_dispatcher_metric_last_log"):
            self._dispatcher_metric_last_log = 0.0
        if not hasattr(self, "_dispatcher_chunk_counter"):
            self._dispatcher_chunk_counter = 0
        if not hasattr(self, "_dispatcher_queue_drops"):
            self._dispatcher_queue_drops = 0

        restart_attempt = 0
        last_restart_time = 0.0

        if debug_level >= 3:
            logger.debug(
                f"[DISPATCHER] 🚀 Dispatcher gestartet (Loop-ID: {id(self)})",
                extra={"component": "dispatcher"},
            )

        while not self._stop_event.is_set() and not self._dispatcher_shutdown.is_set():
            restart_attempt += 1
            current_time = time.time()

            if (
                restart_attempt > 1
                and (current_time - last_restart_time) < min_restart_interval
            ):
                sleep_time = min_restart_interval - (current_time - last_restart_time)
                if debug_level >= 3:
                    logger.debug(
                        f"[DISPATCHER] ⏳ Zu schnelle Neustarts – warte {sleep_time:.1f}s",
                        extra={"component": "dispatcher"},
                    )
                time.sleep(sleep_time)
            last_restart_time = time.time()

            if debug_level >= 3:
                self._log_dispatcher_status(logger, "START")

            try:
                self._run_dispatcher_loop_inner(logger)

                if debug_level >= 3:
                    logger.debug(
                        "[DISPATCHER] Loop normal beendet",
                        extra={"component": "dispatcher"},
                    )
                break

            except Exception as e:
                if self._stop_event.is_set() or self._dispatcher_shutdown.is_set():
                    if debug_level >= 3:
                        logger.info(
                            "[DISPATCHER] Shutdown aktiv – breche ab",
                            extra={"component": "dispatcher"},
                        )
                    break

                logger.error(
                    f"[DISPATCHER] ❌ Loop crashed (Attempt {restart_attempt}/{max_restarts}): {e}",
                    exc_info=True,
                    extra={"component": "dispatcher"},
                )

                if restart_attempt >= max_restarts:
                    logger.critical(
                        f"[DISPATCHER] 💀 Max. Neustarts ({max_restarts}) erreicht – gebe auf",
                        extra={"component": "dispatcher"},
                    )
                    if self._dispatcher_err_cb:
                        try:
                            self._dispatcher_err_cb(f"Dispatcher fatal: {e}")
                        except Exception as cb_err:
                            logger.error(
                                f"[DISPATCHER] Fehler in dispatcher_err_cb: {cb_err}",
                                extra={"component": "dispatcher"},
                            )
                    self._set_state(self.State.ERROR)
                    break

                delay = min(10.0, backoff_base * (2 ** (restart_attempt - 1)))
                if debug_level >= 3:
                    logger.info(
                        f"[DISPATCHER] 🔄 Neustart in {delay:.1f}s...",
                        extra={"component": "dispatcher"},
                    )
                time.sleep(delay)
                self._reset_dispatcher_state()
                if debug_level >= 3:
                    logger.debug(
                        "[DISPATCHER] State zurückgesetzt",
                        extra={"component": "dispatcher"},
                    )

        self._dispatcher_stop_event.set()
        if hasattr(self, "_dispatcher_shutdown"):
            self._dispatcher_shutdown.set()

        total_duration = time.time() - self._dispatcher_start_time
        chunks = getattr(self, "_dispatcher_chunk_counter", 0)
        drops = getattr(self, "_dispatcher_queue_drops", 0)

        if debug_level >= 3:
            logger.debug(
                f"[DISPATCHER] 🧹 Loop beendet: "
                f"Dauer={total_duration:.0f}s, "
                f"Chunks={chunks}, "
                f"Drops={drops}, "
                f"Restarts={restart_attempt}",
                extra={"component": "dispatcher"},
            )

    def _log_dispatcher_status(self, logger: logging.Logger, phase: str) -> None:
        """Loggt den aktuellen Dispatcher-Status (für Debug-Zwecke)."""
        if not hasattr(self, "_raw_audio_queue"):
            return

        queue_size = self._raw_audio_queue.qsize() if self._raw_audio_queue else 0
        queue_max = self._raw_audio_queue.maxsize if self._raw_audio_queue else 0
        pending = self._pending_tasks if hasattr(self, "_pending_tasks") else 0
        active = len(self._active_futures) if hasattr(self, "_active_futures") else 0
        chunks = getattr(self, "_dispatcher_chunk_counter", 0)
        drops = getattr(self, "_dispatcher_queue_drops", 0)

        logger.debug(
            f"[DISPATCHER] 📊 Status ({phase}): "
            f"queue={queue_size}/{queue_max} ({queue_size / queue_max * 100:.1f}%), "
            f"pending={pending}, active={active}, "
            f"chunks={chunks}, drops={drops}",
            extra={"component": "dispatcher"},
        )

    def _log_dispatcher_metrics(self) -> None:
        """Loggt Dispatcher-Metriken (alle 5 Minuten).
        Warnungen bei Überschreitung von Schwellwerten.
        """
        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level < 3:
            return

        queue_size = self._raw_audio_queue.qsize() if self._raw_audio_queue else 0
        queue_max = self._raw_audio_queue.maxsize if self._raw_audio_queue else 0
        pending = self._pending_tasks if hasattr(self, "_pending_tasks") else 0
        active = len(self._active_futures) if hasattr(self, "_active_futures") else 0
        chunks = getattr(self, "_dispatcher_chunk_counter", 0)
        drops = getattr(self, "_dispatcher_queue_drops", 0)
        uptime = time.time() - getattr(self, "_dispatcher_start_time", time.time())

        logger.debug(
            f"[DISPATCHER] 📊 Metriken: "
            f"queue={queue_size}/{queue_max} ({queue_size / queue_max * 100:.1f}%), "
            f"pending={pending}, active={active}, "
            f"drops={drops}, chunks={chunks}, uptime={uptime:.0f}s",
            extra={"component": "dispatcher"},
        )

        queue_warning = getattr(self, "DISPATCHER_QUEUE_WARNING_THRESHOLD", 1000)
        pending_warning = getattr(self, "DISPATCHER_PENDING_WARNING_THRESHOLD", 50)

        if queue_size > queue_warning:
            logger.warning(
                f"[DISPATCHER] ⚠️ QUEUE HOCH: {queue_size}/{queue_max}",
                extra={"component": "dispatcher"},
            )
        if pending > pending_warning:
            logger.warning(
                f"[DISPATCHER] ⚠️ PENDING HOCH: {pending} Tasks",
                extra={"component": "dispatcher"},
            )
        if drops > 0:
            logger.warning(
                f"[DISPATCHER] ⚠️ DROPPED CHUNKS: {drops}",
                extra={"component": "dispatcher"},
            )

    def _reset_dispatcher_state(self) -> None:
        """Setzt alle dispatcher- und pufferbezogenen Attribute auf den Ausgangszustand zurück.
        Wird von _init_queues_and_dispatcher aufgerufen, kann aber auch separat verwendet werden.
        OPTIMIERTE VERSION mit vollständiger Bereinigung.
        """
        import logging
        import queue

        logger = logging.getLogger("dragon")
        log_debug = logger.debug

        self._dispatcher_thread = None
        self._dispatcher_started = False
        self._dispatcher_shutdown.clear()
        self._dispatcher_stop_event.clear()

        with self._pending_tasks_cond:
            self._pending_tasks = 0
            self._tasks_done_event.set()
            self._tasks_done_event.clear()
            self._pending_tasks_cond.notify_all()

        if hasattr(self, "_raw_audio_queue") and self._raw_audio_queue is not None:
            try:
                cleared = 0
                while not self._raw_audio_queue.empty():
                    try:
                        self._raw_audio_queue.get_nowait()
                        cleared += 1
                    except queue.Empty:
                        break
                if cleared > 0:
                    log_debug(f"Dispatcher: {cleared} Items aus Queue entfernt (Reset)")
            except Exception as e:
                log_debug(f"Dispatcher: Queue leeren fehlgeschlagen: {e}")

        if hasattr(self, "_active_timeout_futures"):
            cancelled = 0
            for future in list(self._active_timeout_futures):
                if not future.done():
                    future.cancel()
                    cancelled += 1
            self._active_timeout_futures.clear()
            if cancelled > 0:
                log_debug(f"Dispatcher: {cancelled} alte Futures abgebrochen")

        if hasattr(self, "_timeout_futures"):
            cancelled = 0
            for future in list(self._timeout_futures):
                if not future.done():
                    future.cancel()
                    cancelled += 1
            self._timeout_futures.clear()
            if cancelled > 0:
                log_debug(f"Dispatcher: {cancelled} Timeout-Futures abgebrochen")

        if hasattr(self, "_audio_chunks"):
            self._audio_chunks.clear()
        if hasattr(self, "_overflow_chunks"):
            self._overflow_chunks.clear()
        self._audio_total_bytes = 0

        if hasattr(self, "settings") and self.settings is not None:
            with contextlib.suppress(Exception):
                self._max_buffer_bytes = int(
                    self.MAX_BUFFER_SECONDS * self.settings.config.BYTES_PER_SECOND,
                )
        self._last_buffer_flush = time.time()
        self._last_chunk_tail = b""

        if hasattr(self, "_debug_monitor_stop_event"):
            self._debug_monitor_stop_event.clear()
        self._debug_monitor_thread = None

        self._last_queue_log_time = 0.0
        self._last_perf_log_time = 0.0
        self._last_status_time = 0.0

        if hasattr(self, "_reader_backpressure"):
            self._reader_backpressure = False

        if hasattr(self, "_event_bus") and self._event_bus is not None:
            with contextlib.suppress(Exception):
                self._event_bus.publish("dispatcher_reset", {})

        log_debug("Dispatcher: Zustand vollständig zurückgesetzt")

    def _run_dispatcher_loop_inner(self, logger: logging.Logger) -> None:
        """Eigentliche Dispatcher‑Logik – wird von der äußeren Schleife aufgerufen.

        ULTIMATIVE VERSION 7.1 – Patch 2026-09-13:
          - In-Loop-Stuck-Check entfernt (False-Positives bei langsamen
            Streams). Die lokale Variable `last_progress_time` wurde nur im
            `else`-Zweig aktualisiert, nicht bei leerer Queue → nach 60 s
            konstant → fälschlich „stuck" → killte lebende Streams.
          - Echter Dispatcher-Tod (Thread tot + Queue nicht leer) wird
            extern von _schedule_watchdog erkannt.
          - `self._last_progress_time` wird nach jedem erfolgreichen Submit
            aktualisiert, damit externe Beobachter (CPU-Monitor,
            _is_dispatcher_really_stuck) einen konsistenten Wert sehen.
        """
        import contextlib
        import queue
        import time

        debug_level = getattr(self, "debug_level", 0)
        stop_event = self._stop_event
        dispatcher_shutdown = self._dispatcher_shutdown
        dispatcher_stop_event = self._dispatcher_stop_event
        raw_audio_queue = self._raw_audio_queue
        transcription_executor = self._transcription_executor
        pending_tasks_cond = self._pending_tasks_cond
        tasks_done_event = self._tasks_done_event

        log_debug = logger.debug
        log_info = logger.info
        log_warning = logger.warning
        log_error = logger.error

        sleep_short = getattr(self, "_dispatcher_sleep_short", 0.01)
        sleep_medium = getattr(self, "_dispatcher_sleep_medium", 0.02)
        sleep_long = getattr(self, "_dispatcher_sleep_long", 0.05)
        sleep_backpressure = getattr(self, "_dispatcher_sleep_backpressure", 0.05)
        sleep_pending = getattr(self, "_dispatcher_sleep_pending", 0.05)

        inactivity_timeout = getattr(
            self,
            "_dispatcher_inactivity_timeout",
            300.0 if not getattr(self, "_is_live", False) else 120.0,
        )

        if debug_level >= 3:
            log_debug(
                f"Dispatcher Sleep-Konfiguration: short={sleep_short * 1000:.1f}ms, "
                f"medium={sleep_medium * 1000:.1f}ms, long={sleep_long * 1000:.1f}ms, "
                f"backpressure={sleep_backpressure * 1000:.1f}ms, pending={sleep_pending * 1000:.1f}ms",
                extra={"component": "dispatcher"},
            )

        def _log(level: int, msg: str, *args, **kwargs) -> None:
            if debug_level >= level:
                kwargs.setdefault("extra", {"component": "dispatcher"})
                if level <= 2:
                    log_debug(msg, *args, **kwargs)
                elif level == 3:
                    log_info(msg, *args, **kwargs)
                elif level == 4:
                    log_warning(msg, *args, **kwargs)
                else:
                    log_error(msg, *args, **kwargs)

        log_debug(
            "🔄 Dispatcher‑Loop gestartet (optimierte V7.1 mit Queue-Warte-Logik)",
            extra={"component": "dispatcher"},
        )

        if hasattr(self, "_dispatcher_stop_event"):
            self._dispatcher_stop_event.clear()
            log_debug(
                "Dispatcher: Stop-Event beim Start zurückgesetzt",
                extra={"component": "dispatcher"},
            )

        wait_start = time.monotonic()
        while raw_audio_queue is None and not stop_event.is_set():
            dispatcher_stop_event.wait(0.1)
            if time.monotonic() - wait_start > 5.0:
                log_warning(
                    "Dispatcher: Warte seit >5s auf Queue – weiter...",
                    extra={"component": "dispatcher"},
                )
                break

        if raw_audio_queue is None:
            log_warning(
                "Dispatcher: Keine Queue erhalten – beende",
                extra={"component": "dispatcher"},
            )
            return

        if not hasattr(raw_audio_queue, "put") or not hasattr(raw_audio_queue, "get"):
            log_error(
                f"Dispatcher: raw_audio_queue ist keine gültige Queue (Typ: {type(raw_audio_queue).__name__}) – beende",
                extra={"component": "dispatcher"},
            )
            return

        log_debug(
            f"Dispatcher: Queue empfangen (Typ: {type(raw_audio_queue).__name__}, maxsize={raw_audio_queue.maxsize}, ID: {id(raw_audio_queue)})",
            extra={"component": "dispatcher"},
        )

        executor = transcription_executor
        if executor is None:
            log_warning(
                "Dispatcher: Transkriptions‑Executor ist None – initiiere",
                extra={"component": "dispatcher"},
            )
            self._init_transcription_executor()
            executor = self._transcription_executor
            if executor is None:
                log_error(
                    "Dispatcher: Transkriptions‑Executor konnte nicht initialisiert werden – Loop wird nicht gestartet.",
                    extra={"component": "dispatcher"},
                )
                return

        self._dispatcher_trans_cb = getattr(
            self, "_transcription_callback", None
        ) or getattr(self, "transcription_callback", None)
        self._dispatcher_transl_cb = getattr(
            self, "_translation_callback", None
        ) or getattr(self, "translation_callback", None)
        self._dispatcher_err_cb = getattr(self, "_error_callback", None) or getattr(
            self, "error_callback", None
        )

        if self._dispatcher_trans_cb is None:
            if debug_level >= 3:
                log_debug(
                    "ℹ️ transcription_callback noch nicht gesetzt – "
                    "dynamische Auflösung aktiv",
                    extra={"component": "dispatcher"},
                )
            self._dispatcher_trans_cb = lambda text: (
                getattr(self, "_transcription_callback", None)
                or getattr(self, "transcription_callback", None)
                or (lambda x: None)
            )(text)

        if self._dispatcher_transl_cb is None:
            if debug_level >= 3:
                log_debug(
                    "ℹ️ translation_callback noch nicht gesetzt – "
                    "dynamische Auflösung aktiv",
                    extra={"component": "dispatcher"},
                )
            self._dispatcher_transl_cb = lambda text: (
                getattr(self, "_translation_callback", None)
                or getattr(self, "translation_callback", None)
                or (lambda x: None)
            )(text)

        if self._dispatcher_err_cb is None:
            self._dispatcher_err_cb = lambda err: log_error(
                f"Transcription error: {err}",
                extra={"component": "dispatcher"},
            )

        is_live = getattr(self, "_is_live", False)
        INACTIVITY_TIMEOUT = inactivity_timeout
        STATUS_INTERVAL = 5.0
        WATCHDOG_INTERVAL = 60.0
        QUEUE_HIGH_WATERMARK = 0.85
        QUEUE_LOW_WATERMARK = 0.3

        MAX_PENDING_TASKS = getattr(self, "_max_pending_tasks", 1000)
        MAX_PENDING_TASKS = min(MAX_PENDING_TASKS, 1500)
        MAX_PENDING_TASKS = max(MAX_PENDING_TASKS, 200)

        QUEUE_FIXED_MAXSIZE = getattr(raw_audio_queue, "maxsize", 5000)
        if QUEUE_FIXED_MAXSIZE < 5000:
            raw_audio_queue.maxsize = 5000
            QUEUE_FIXED_MAXSIZE = 5000
            log_debug(
                f"Queue maxsize auf {QUEUE_FIXED_MAXSIZE} erhöht",
                extra={"component": "dispatcher"},
            )

        BACKPRESSURE_THRESHOLD = 0.80

        processed_items = 0
        skipped_old_format = 0
        skipped_errors = 0
        last_activity_time = time.monotonic()
        last_status_time = time.monotonic()
        empty_loop_count = 0
        consecutive_full_queue = 0
        last_queue_size_log = time.monotonic()
        watchdog_reset_counter = 0

        ffmpeg = self.ffmpeg_manager
        process_id = self._current_stream_id
        stop_requested = False
        stream_ended_normally = False

        if not hasattr(self, "_reader_backpressure"):
            self._reader_backpressure = False

        DROP_THRESHOLD = int(QUEUE_FIXED_MAXSIZE * 0.95)

        def _set_backpressure(active: bool) -> None:
            if active != getattr(self, "_reader_backpressure", False):
                self._reader_backpressure = active
                if debug_level >= 3:
                    log_debug(
                        f"{'🔴' if active else '🟢'} Backpressure: {'aktiviert' if active else 'deaktiviert'}",
                        extra={"component": "dispatcher"},
                    )

        def _get_queue_load() -> tuple[int, float]:
            try:
                qsize = raw_audio_queue.qsize()
                maxsize = getattr(raw_audio_queue, "maxsize", QUEUE_FIXED_MAXSIZE)
                return qsize, qsize / maxsize if maxsize > 0 else 0.0
            except Exception:
                return 0, 0.0

        def _drop_oldest_items(count: int) -> None:
            dropped = 0
            try:
                for _ in range(count):
                    try:
                        raw_audio_queue.get_nowait()
                        raw_audio_queue.task_done()
                        dropped += 1
                    except queue.Empty:
                        break
                if dropped > 0:
                    log_warning(
                        f"Dispatcher: {dropped} älteste Items aus Queue entfernt (Überlauf)",
                        extra={"component": "dispatcher"},
                    )
            except Exception as e:
                log_debug(
                    f"Fehler beim Droppen von Items: {e}",
                    extra={"component": "dispatcher"},
                )

        try:
            loop_start = time.monotonic()
            log_debug(
                f"Dispatcher: Hauptschleife gestartet (Loop-ID: {id(self)})",
                extra={"component": "dispatcher"},
            )

            reader_thread = getattr(self, "_reader_thread", None)
            if reader_thread is not None and reader_thread.is_alive():
                log_debug(
                    f"✅ Reader-Thread läuft: {reader_thread.name} (TID: {reader_thread.ident})",
                    extra={"component": "dispatcher"},
                )
            else:
                log_debug(
                    "ℹ️ Reader-Thread ist noch nicht aktiv – Dispatcher wartet auf Daten.",
                    extra={"component": "dispatcher"},
                )

            if ffmpeg and process_id:
                try:
                    pinfo = ffmpeg._processes.get(process_id)
                    if pinfo and pinfo.process:
                        poll = pinfo.process.poll()
                        if poll is None:
                            log_debug(
                                f"✅ FFmpeg-Prozess (PID {pinfo.process.pid}) läuft",
                                extra={"component": "dispatcher"},
                            )
                        else:
                            log_debug(
                                f"ℹ️ FFmpeg-Prozess (PID {pinfo.process.pid}) beendet mit Code {poll}",
                                extra={"component": "dispatcher"},
                            )
                    else:
                        log_debug(
                            "ℹ️ FFmpeg-Prozess nicht im Manager registriert (wird später gestartet)",
                            extra={"component": "dispatcher"},
                        )
                except Exception as e:
                    log_debug(f"Fehler beim Prüfen von FFmpeg: {e}")

            while (
                not dispatcher_shutdown.is_set()
                and not stop_event.is_set()
                and not dispatcher_stop_event.is_set()
            ):
                qsize, load = _get_queue_load()

                _set_backpressure(load > BACKPRESSURE_THRESHOLD)

                if qsize > DROP_THRESHOLD:
                    drop_count = qsize - int(QUEUE_FIXED_MAXSIZE * 0.80)
                    if drop_count > 0:
                        _drop_oldest_items(drop_count)

                now = time.monotonic()
                if now - last_queue_size_log > 10.0 and debug_level >= 2:
                    log_debug(
                        f"📊 Queue: size={qsize}/{QUEUE_FIXED_MAXSIZE}, load={load:.1%}, "
                        f"pending={self._pending_tasks}, processed={processed_items}",
                        extra={"component": "dispatcher"},
                    )
                    last_queue_size_log = now

                if load > QUEUE_HIGH_WATERMARK:
                    consecutive_full_queue += 1
                    if consecutive_full_queue % 10 == 0 and debug_level >= 2:
                        log_debug(
                            f"⚠️ Queue hoch ausgelastet ({qsize}/{QUEUE_FIXED_MAXSIZE}, load={load:.1%}) – pausiere",
                            extra={"component": "dispatcher"},
                        )
                    time.sleep(sleep_backpressure)
                    continue
                consecutive_full_queue = 0

                if self._pending_tasks > MAX_PENDING_TASKS:
                    if debug_level >= 3 and self._pending_tasks % 20 == 0:
                        log_debug(
                            f"⏳ Pending-Tasks {self._pending_tasks}/{MAX_PENDING_TASKS} – warte",
                            extra={"component": "dispatcher"},
                        )
                    ratio = self._pending_tasks / MAX_PENDING_TASKS
                    sleep_time = min(sleep_pending, 0.05 * ratio)
                    time.sleep(sleep_time)
                    continue

                item = None
                try:
                    if debug_level >= 3 and qsize > 0:
                        log_debug(
                            f"📥 Versuche get_nowait() – Queue enthält {qsize} Item(s)",
                            extra={"component": "dispatcher"},
                        )

                    item = raw_audio_queue.get_nowait()
                    empty_loop_count = 0
                    last_activity_time = time.monotonic()

                    if debug_level >= 2:
                        item_type = type(item).__name__
                        item_len = len(item) if hasattr(item, "__len__") else "?"
                        log_debug(
                            f"📤 Item aus Queue geholt: Typ={item_type}, Länge={item_len}, qsize={qsize - 1}",
                            extra={"component": "dispatcher"},
                        )
                        if isinstance(item, bytes) and len(item) > 0:
                            preview = item[:20].hex() if len(item) >= 20 else item.hex()
                            log_debug(
                                f"   Bytes preview (hex): {preview}...",
                                extra={"component": "dispatcher"},
                            )

                except queue.Empty:
                    empty_loop_count += 1
                    now = time.monotonic()

                    if empty_loop_count % 500 == 0 and debug_level >= 2:
                        log_debug(
                            f"😴 Leerlauf – processed={processed_items}, pending={self._pending_tasks}, "
                            f"queue_size={qsize}, empty_loops={empty_loop_count}",
                            extra={"component": "dispatcher"},
                        )

                    if now - last_activity_time > INACTIVITY_TIMEOUT:
                        ffmpeg_alive = False
                        if ffmpeg and process_id:
                            try:
                                pinfo = ffmpeg._processes.get(process_id)
                                if (
                                    pinfo
                                    and pinfo.process
                                    and pinfo.process.poll() is None
                                ):
                                    ffmpeg_alive = True
                            except Exception:
                                pass

                        if ffmpeg_alive:
                            if debug_level >= 3:
                                log_debug(
                                    f"Inaktivität ({INACTIVITY_TIMEOUT:.1f}s), aber FFmpeg läuft – warte weiter",
                                    extra={"component": "dispatcher"},
                                )
                            last_activity_time = now
                            empty_loop_count = 0
                            time.sleep(sleep_short)
                            continue
                        log_warning(
                            f"Dispatcher: Inaktivitäts-Timeout ({INACTIVITY_TIMEOUT:.1f} s) – FFmpeg nicht mehr aktiv, beende Thread",
                            extra={"component": "dispatcher"},
                        )
                        stream_ended_normally = True
                        break

                    if load > QUEUE_HIGH_WATERMARK:
                        sleep_time = sleep_backpressure
                    elif load > QUEUE_LOW_WATERMARK:
                        sleep_time = sleep_medium
                    else:
                        sleep_time = (
                            sleep_short if self._pending_tasks <= 10 else sleep_medium
                        )
                    time.sleep(sleep_time)
                    continue

                try:
                    raw_audio_queue.task_done()
                except ValueError:
                    if debug_level >= 4:
                        log_debug(
                            "task_done() ValueError – ignoriert",
                            extra={"component": "dispatcher"},
                        )
                except Exception as exc:
                    log_error(
                        f"Dispatcher: task_done() Fehler: {exc}",
                        extra={"component": "dispatcher"},
                    )

                if item is getattr(self, "_DISPATCHER_STOP_SENTINEL", None):
                    log_debug(
                        "Dispatcher: Sentinel empfangen, beende",
                        extra={"component": "dispatcher"},
                    )
                    stop_requested = True
                    break

                if isinstance(item, bytes):
                    if debug_level >= 4:
                        log_debug(
                            "Altes Format (bytes) erkannt – konvertiere",
                            extra={"component": "dispatcher"},
                        )
                    item = (
                        item,
                        0,
                        0.0,
                        self._dispatcher_trans_cb,
                        self._dispatcher_transl_cb,
                        self._dispatcher_err_cb,
                    )

                if not isinstance(item, tuple):
                    log_error(
                        f"Dispatcher: Fehlerhaftes Queue-Item (kein tuple) – Typ {type(item).__name__} – verworfen.",
                        extra={"component": "dispatcher"},
                    )
                    skipped_errors += 1
                    continue

                try:
                    item_len = len(item)
                    if item_len >= 6:
                        (
                            audio_data,
                            chunk_byte_offset,
                            overlap_duration,
                            trans_cb,
                            transl_cb,
                            error_cb,
                        ) = item[:6]
                    elif item_len >= 5:
                        audio_data, chunk_byte_offset, trans_cb, transl_cb, error_cb = (
                            item[:5]
                        )
                        overlap_duration = 0.0
                    elif item_len >= 4:
                        audio_data, trans_cb, transl_cb, error_cb = item[:4]
                        chunk_byte_offset = None
                        overlap_duration = 0.0
                    else:
                        log_error(
                            f"Dispatcher: Queue-Item zu kurz (Länge {item_len}) – verworfen.",
                            extra={"component": "dispatcher"},
                        )
                        skipped_errors += 1
                        continue

                    if debug_level >= 3:
                        audio_len = len(audio_data) if audio_data else 0
                        log_debug(
                            f"📦 Item entpackt: audio_len={audio_len} bytes, offset={chunk_byte_offset}, overlap={overlap_duration:.2f}s",
                            extra={"component": "dispatcher"},
                        )
                except Exception as e:
                    log_error(
                        f"Dispatcher: Fehler beim Entpacken: {e}",
                        exc_info=True,
                        extra={"component": "dispatcher"},
                    )
                    skipped_errors += 1
                    continue

                if not isinstance(audio_data, bytes):
                    log_error(
                        f"Dispatcher: audio_data ist nicht bytes (Typ: {type(audio_data).__name__}) – verworfen.",
                        extra={"component": "dispatcher"},
                    )
                    skipped_errors += 1
                    continue

                if self._pending_tasks < MAX_PENDING_TASKS:
                    try:
                        future = executor.submit(
                            self._process_audio_chunk_async,
                            audio_data,
                            trans_cb or self._dispatcher_trans_cb,
                            transl_cb or self._dispatcher_transl_cb,
                            error_cb or self._dispatcher_err_cb,
                            chunk_byte_offset=chunk_byte_offset,
                            overlap_duration=overlap_duration,
                        )
                        if debug_level >= 4:
                            log_debug(
                                f"✅ Task submitted (pending={self._pending_tasks + 1})",
                                extra={"component": "dispatcher"},
                            )
                    except RuntimeError as exc:
                        log_error(
                            f"Dispatcher: Executor lehnt Aufgabe ab: {exc}",
                            extra={"component": "dispatcher"},
                        )
                        skipped_errors += 1
                        continue
                    except Exception as exc:
                        log_error(
                            f"Dispatcher: Unerwarteter Fehler beim Submit: {exc}",
                            exc_info=True,
                            extra={"component": "dispatcher"},
                        )
                        skipped_errors += 1
                        continue

                    self._modify_pending_tasks(1, reason="dispatcher_submit")
                    future.add_done_callback(
                        lambda f: self._modify_pending_tasks(-1, reason="task_done"),
                    )
                    processed_items += 1
                    self._last_progress_time = time.monotonic()
                else:
                    if debug_level >= 3:
                        log_debug(
                            f"⏳ Pending-Tasks Limit erreicht ({self._pending_tasks}/{MAX_PENDING_TASKS}) – Item zurückgelegt",
                            extra={"component": "dispatcher"},
                        )
                    try:
                        raw_audio_queue.put(item)
                    except Exception as e:
                        log_error(
                            f"Dispatcher: Fehler beim Zurücklegen des Items: {e}",
                            extra={"component": "dispatcher"},
                        )
                    time.sleep(sleep_pending)
                    continue

                now = time.monotonic()
                if load > QUEUE_HIGH_WATERMARK:
                    sleep_time = sleep_backpressure
                elif load > QUEUE_LOW_WATERMARK:
                    sleep_time = sleep_medium
                else:
                    sleep_time = (
                        sleep_short if self._pending_tasks <= 10 else sleep_medium
                    )

                if sleep_time > 0.005 and debug_level >= 4:
                    log_debug(
                        f"💤 Sleep: {sleep_time * 1000:.1f}ms (load={load:.1%}, pending={self._pending_tasks})",
                        extra={"component": "dispatcher"},
                    )
                time.sleep(sleep_time)

                if now - last_status_time >= STATUS_INTERVAL and debug_level >= 2:
                    log_debug(
                        f"📊 Status: queue={qsize}, pending={self._pending_tasks}, "
                        f"dropped={self._queue_drop_counter}, processed={processed_items}, load={load:.1%}",
                        extra={"component": "dispatcher"},
                    )
                    last_status_time = now

        except Exception as loop_exc:
            log_error(
                f"Dispatcher: Kritischer Fehler in Hauptschleife: {loop_exc}",
                exc_info=True,
                extra={"component": "dispatcher"},
            )
            try:
                if self._dispatcher_err_cb:
                    self._dispatcher_err_cb(f"Dispatcher loop error: {loop_exc}")
            except Exception:
                pass
            raise

        finally:
            log_debug(
                "Dispatcher: Starte Cleanup...",
                extra={"component": "dispatcher"},
            )
            _set_backpressure(False)

            if stop_requested or dispatcher_shutdown.is_set():
                cleared = 0
                if raw_audio_queue is not None:
                    while True:
                        try:
                            item = raw_audio_queue.get_nowait()
                            with contextlib.suppress(Exception):
                                raw_audio_queue.task_done()
                            cleared += 1
                            if cleared % 100 == 0 and debug_level >= 3:
                                log_debug(
                                    f"🧹 Queue geleert: {cleared} Items",
                                    extra={"component": "dispatcher"},
                                )
                        except queue.Empty:
                            break
                if cleared > 0:
                    log_debug(
                        f"Dispatcher: {cleared} Items aus Queue entfernt (Shutdown).",
                        extra={"component": "dispatcher"},
                    )
            elif raw_audio_queue is not None:
                try:
                    remaining = raw_audio_queue.qsize()
                    if remaining > 0:
                        log_warning(
                            f"Dispatcher: Beendet, aber {remaining} Items in Queue – werden beim nächsten Start verarbeitet.",
                            extra={"component": "dispatcher"},
                        )
                except Exception:
                    pass

            with pending_tasks_cond:
                if self._pending_tasks == 0 and not tasks_done_event.is_set():
                    tasks_done_event.set()
                    if debug_level >= 3:
                        log_debug(
                            "_tasks_done_event SET (pending=0)",
                            extra={"component": "dispatcher"},
                        )

            loop_duration = (
                time.monotonic() - loop_start if "loop_start" in locals() else 0
            )
            log_debug(
                f"🛑 Dispatcher-Loop beendet. Dauer={loop_duration:.2f}s, processed={processed_items}, "
                f"old_format={skipped_old_format}, errors={skipped_errors}, "
                f"stop_requested={stop_requested}, stream_ended={stream_ended_normally}, "
                f"watchdog_restarts={watchdog_reset_counter}",
                extra={"component": "dispatcher"},
            )

    def _is_current_thread_dispatcher(self) -> bool:
        """Prüft, ob der aktuelle Thread der Dispatcher-Thread ist."""
        _dt = getattr(self, "_dispatcher_thread", None)
        _current = threading.current_thread()

        if _dt is None:
            _is_dispatcher = False
        else:
            _is_dispatcher = _current is _dt

        if DEBUG_LEVEL >= 3:
            try:
                _dt_name = getattr(_dt, "name", None) if _dt else None
                _dt_ident = getattr(_dt, "ident", None) if _dt else None
                _dt_alive = _dt.is_alive() if _dt is not None else False
                log_debug(
                    "dispatcher_restart",
                    "_is_current_thread_dispatcher: "
                    f"result={_is_dispatcher}, "
                    f"current={_current.name}(tid={_current.ident}), "
                    f"dispatcher_thread={_dt_name}(tid={_dt_ident}, "
                    f"alive={_dt_alive})",
                )
            except Exception:
                pass

        return _is_dispatcher

    def _cancel_pending_futures(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
    ) -> int:
        """Bricht alle registrierten Futures ab und setzt den
        Pending-Zähler zurück.
        """
        import time as _time

        _t0 = _time.perf_counter()
        _diag: dict[str, Any] = {
            "started_at": _time.time(),
            "sets_scanned": [],
            "total_seen": 0,
            "already_done": 0,
            "cancelled": 0,
            "running_cannot_cancel": 0,
            "errors": 0,
            "pending_before": getattr(self, "_pending_tasks", -1),
            "pending_after": -1,
        }

        _future_set_names = (
            "_active_translation_futures",
            "_active_timeout_futures",
            "_timeout_futures",
        )

        if debug_level >= 3:
            with contextlib.suppress(Exception):
                logger.debug(
                    "[DISPATCHER-RESTART] _cancel_pending_futures: START "
                    "(sets=%s, pending=%s)",
                    _future_set_names,
                    _diag["pending_before"],
                )

        for _set_name in _future_set_names:
            _future_set = getattr(self, _set_name, None)
            if not _future_set:
                _diag["sets_scanned"].append(
                    {"name": _set_name, "state": "leer_oder_fehlt"}
                )
                continue

            try:
                _snapshot = list(_future_set)
            except Exception as _snap_exc:
                if debug_level >= 2:
                    logger.warning(
                        "[DISPATCHER-RESTART] Snapshot von %s fehlgeschlagen: %s",
                        _set_name,
                        _snap_exc,
                    )
                _diag["errors"] += 1
                continue

            _set_diag = {
                "name": _set_name,
                "size": len(_snapshot),
                "cancelled_here": 0,
                "done_here": 0,
                "running_here": 0,
            }

            for _fut in _snapshot:
                _diag["total_seen"] += 1
                if _fut is None:
                    continue

                try:
                    if _fut.done():
                        _diag["already_done"] += 1
                        _set_diag["done_here"] += 1
                        continue
                except Exception:
                    pass

                try:
                    _was_cancelled = _fut.cancel()
                except Exception as _cancel_exc:
                    _diag["errors"] += 1
                    if debug_level >= 2:
                        logger.warning(
                            "[DISPATCHER-RESTART] Future-Cancel "
                            "aus %s fehlgeschlagen: %s",
                            _set_name,
                            _cancel_exc,
                        )
                    continue

                if _was_cancelled:
                    _diag["cancelled"] += 1
                    _set_diag["cancelled_here"] += 1
                    if debug_level >= 3:
                        logger.debug(
                            "[DISPATCHER-RESTART] Future aus %s gecancelt: %s",
                            _set_name,
                            _fut,
                        )
                else:
                    _diag["running_cannot_cancel"] += 1
                    _set_diag["running_here"] += 1
                    if debug_level >= 3:
                        try:
                            _fut_state = _fut._state

                        except Exception:
                            _fut_state = "?"
                        logger.debug(
                            "[DISPATCHER-RESTART] Future aus %s "
                            "konnte nicht gecancelt werden "
                            "(state=%s) – Thread läuft weiter als "
                            "Daemon-Zombie",
                            _set_name,
                            _fut_state,
                        )

            _diag["sets_scanned"].append(_set_diag)

        try:
            _pending_before_reset = getattr(self, "_pending_tasks", 0)
            self._pending_tasks = 0
            _diag["pending_after"] = 0
            if debug_level >= 3 and _pending_before_reset != 0:
                logger.debug(
                    "[DISPATCHER-RESTART] pending_tasks zurückgesetzt: %d → 0",
                    _pending_before_reset,
                )
        except Exception as _reset_exc:
            _diag["errors"] += 1
            if debug_level >= 2:
                logger.warning(
                    "[DISPATCHER-RESTART] pending_tasks-Reset fehlgeschlagen: %s",
                    _reset_exc,
                )

        try:
            _tde = getattr(self, "_tasks_done_event", None)
            if _tde is not None and not _tde.is_set():
                _tde.set()
                if debug_level >= 3:
                    logger.debug(
                        "[DISPATCHER-RESTART] _tasks_done_event "
                        "gesetzt (nach Pending-Reset)"
                    )
        except Exception as _event_exc:
            _diag["errors"] += 1
            if debug_level >= 2:
                logger.warning(
                    "[DISPATCHER-RESTART] _tasks_done_event.set() fehlgeschlagen: %s",
                    _event_exc,
                )

        _diag["duration_ms"] = (_time.perf_counter() - _t0) * 1000.0
        with contextlib.suppress(Exception):
            self._last_cancel_diag = _diag

        with contextlib.suppress(Exception):
            logger.info(
                "[DISPATCHER-RESTART] _cancel_pending_futures: "
                "%d Future(s) gecancelt, %d liefen bereits "
                "(nicht abbrechbar), %d waren fertig, "
                "%d Fehler, %.1f ms (pending %s → %s)",
                _diag["cancelled"],
                _diag["running_cannot_cancel"],
                _diag["already_done"],
                _diag["errors"],
                _diag["duration_ms"],
                _diag["pending_before"],
                _diag["pending_after"],
            )

        if (
            _diag["pending_before"] > 0
            and _diag["cancelled"] == 0
            and _diag["running_cannot_cancel"] > 0
        ):
            if debug_level >= 1:
                logger.warning(
                    "[DISPATCHER-RESTART] %d Task(s) liefen bereits und "
                    "konnten nicht abgebrochen werden – sie laufen als "
                    "Daemon-Zombies weiter. Wenn das wiederholt "
                    "auftritt, Executor-Timeout prüfen.",
                    _diag["running_cannot_cancel"],
                )

        return _diag["cancelled"]

    def _set_stop_events(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
    ) -> None:
        """Setzt alle Stop-Events, damit laufende Worker-Threads
        kooperativ beenden können.
        """

        _stop_event_names = (
            "_stop_event",
            "_dispatcher_stop_event",
            "_dispatcher_shutdown",
            "_debug_monitor_stop_event",
            "_dispose_stop_event",
            "_reader_stop_event",
            "_health_check_stop",
            "_worker_stop_event",
        )

        _events_set: list[str] = []
        _events_missing: list[str] = []

        for _name in _stop_event_names:
            try:
                _event = getattr(self, _name, None)
                if _event is None:
                    _events_missing.append(_name)
                    continue
                if hasattr(_event, "set"):
                    if not _event.is_set():
                        _event.set()
                        _events_set.append(_name)
                else:
                    if not _event:
                        setattr(self, _name, True)
                        _events_set.append(f"{_name}(bool)")
            except Exception as _exc:
                if debug_level >= 2:
                    logger.warning(
                        "[DISPATCHER-RESTART] _set_stop_events: "
                        "'%s' fehlgeschlagen (%s): %s",
                        _name,
                        type(_exc).__name__,
                        _exc,
                    )

        if debug_level >= 3:
            logger.debug(
                "[DISPATCHER-RESTART] _set_stop_events: "
                "%d Event(s) gesetzt, %d fehlten (%s)",
                len(_events_set),
                len(_events_missing),
                ", ".join(_events_set) if _events_set else "keine",
            )

    def _send_stop_sentinel(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
    ) -> None:
        """Wirft den Dispatcher-Stop-Sentinel in die Audio-Queue."""
        import queue as _queue_module

        _queue = getattr(self, "_raw_audio_queue", None)
        if _queue is None:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _send_stop_sentinel: keine Queue",
                    extra={"component": "dispatcher_restart"},
                )
            return

        _sentinel = getattr(self, "_DISPATCHER_STOP_SENTINEL", None)
        if _sentinel is None:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _send_stop_sentinel: kein Sentinel-Objekt",
                    extra={"component": "dispatcher_restart"},
                )
            return

        try:
            _queue.put_nowait(_sentinel)
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _send_stop_sentinel: ✅ "
                    "Sentinel eingefügt (qsize=%s)",
                    _queue.qsize(),
                    extra={"component": "dispatcher_restart"},
                )
        except _queue_module.Full:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _send_stop_sentinel: Queue "
                    "voll – Sentinel verworfen (Event-Signale reichen)",
                    extra={"component": "dispatcher_restart"},
                )
        except Exception as _exc:
            if debug_level >= 2:
                logger.warning(
                    "[DISPATCHER-RESTART] _send_stop_sentinel: %s",
                    _exc,
                    extra={"component": "dispatcher_restart"},
                )

    def _join_dispatcher_thread(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
        timeout: float = 3.0,
    ) -> None:
        """Wartet auf das Ende des Dispatcher-Threads (mit Timeout)."""
        import threading as _threading

        _thread = getattr(self, "_dispatcher_thread", None)
        if _thread is None:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _join_dispatcher_thread: "
                    "kein Dispatcher-Thread",
                    extra={"component": "dispatcher_restart"},
                )
            return

        if _threading.current_thread() is _thread:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _join_dispatcher_thread: "
                    "Selbst-Join übersprungen",
                    extra={"component": "dispatcher_restart"},
                )
            return

        if not _thread.is_alive():
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _join_dispatcher_thread: "
                    "Thread bereits beendet",
                    extra={"component": "dispatcher_restart"},
                )
            return

        try:
            _thread.join(timeout=timeout)
            _still_alive = _thread.is_alive()
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _join_dispatcher_thread: joined (alive=%s)",
                    _still_alive,
                    extra={"component": "dispatcher_restart"},
                )
            if _still_alive and debug_level >= 2:
                logger.warning(
                    "[DISPATCHER-RESTART] ⚠️ Dispatcher-Thread läuft "
                    "noch nach %.1fs Join-Timeout",
                    timeout,
                    extra={"component": "dispatcher_restart"},
                )
        except Exception as _exc:
            if debug_level >= 2:
                logger.warning(
                    "[DISPATCHER-RESTART] _join_dispatcher_thread: %s",
                    _exc,
                    extra={"component": "dispatcher_restart"},
                )

    def _ensure_transcription_executor(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
    ) -> None:
        """Stellt sicher, dass der Transcription-Executor lebt."""
        _executor = getattr(self, "_transcription_executor", None)

        if _executor is None:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] _ensure_transcription_executor: "
                    "kein Executor vorhanden",
                    extra={"component": "dispatcher_restart"},
                )
            return

        _state = getattr(_executor, "_state", None)
        if _state is not None:
            _state_name = getattr(_state, "name", str(_state))
            if _state_name in ("SHUTDOWN", "STOPPED"):
                if debug_level >= 2:
                    logger.warning(
                        "[DISPATCHER-RESTART] ⚠️ Transcription-Executor "
                        "ist im Zustand %s – Neustart empfohlen",
                        _state_name,
                        extra={"component": "dispatcher_restart"},
                    )
                return

        if debug_level >= 3:
            logger.debug(
                "[DISPATCHER-RESTART] _ensure_transcription_executor: Executor OK",
                extra={"component": "dispatcher_restart"},
            )

    def _update_watchdog_status(self) -> None:
        """Aktualisiert den Watchdog-Status nach einem Reset."""
        import time as _time

        try:
            if hasattr(self, "_watchdog_restart_count"):
                self._watchdog_restart_count = (
                    getattr(
                        self,
                        "_watchdog_restart_count",
                        0,
                    )
                    + 1
                )
            if hasattr(self, "_watchdog_last_restart_ts"):
                self._watchdog_last_restart_ts = _time.monotonic()
        except Exception:
            pass

        try:
            if hasattr(self, "_stuck_counter"):
                self._stuck_counter = 0
            if hasattr(self, "_last_progress_time"):
                self._last_progress_time = _time.monotonic()
        except Exception:
            pass

    def _reset_events_for_restart(
        self,
        logger: logging.Logger,
        debug_level: int = 0,
    ) -> None:
        """Setzt die Stop-Events zurück, damit ein Neustart möglich ist."""
        _events_to_clear = (
            "_dispatcher_stop_event",
            "_dispatcher_shutdown",
        )

        _cleared: list[str] = []
        for _name in _events_to_clear:
            try:
                _event = getattr(self, _name, None)
                if _event is not None and hasattr(_event, "clear"):
                    if _event.is_set():
                        _event.clear()
                        _cleared.append(_name)
            except Exception:
                pass

        if debug_level >= 3:
            logger.debug(
                "[DISPATCHER-RESTART] _reset_events_for_restart: "
                "%d Event(s) gecleart (%s)",
                len(_cleared),
                ", ".join(_cleared) if _cleared else "keine",
                extra={"component": "dispatcher_restart"},
            )

    def _handle_stuck_dispatcher(self) -> dict:
        """Behandelt einen hängenden Dispatcher – ULTIMATIVE EDITION.
        Gibt ein Dictionary mit Diagnose-Daten zurück.
        """
        import logging
        import threading
        import time
        import traceback

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        is_verbose = debug_level >= 3

        diagnosis = {
            "success": False,
            "reset_triggered": False,
            "elapsed": 0.0,
            "cancelled_futures": 0,
            "cleared_queue_items": 0,
            "reader_restarted": False,
            "dispatcher_restarted": False,
            "reason": "unknown",
            "stacktrace": None,
        }

        if not hasattr(self, "_stuck_reset_lock"):
            self._stuck_reset_lock = threading.RLock()

        with self._stuck_reset_lock:
            start_time = time.time()

            try:
                if not self._is_dispatcher_really_stuck():
                    if is_verbose:
                        logger.debug(
                            "[DISPATCHER-RESTART] Dispatcher läuft noch – kein Reset nötig",
                            extra={"component": "dispatcher_restart"},
                        )
                    diagnosis["reason"] = "not_stuck"
                    return diagnosis

                logger.warning(
                    "[DISPATCHER-RESTART] 🔄 Dispatcher stuck – forcing restart...",
                    extra={"component": "dispatcher_restart"},
                )

                if debug_level >= 4:
                    self._log_stuck_thread_stacktrace(logger)

                max_resets = getattr(self, "DISPATCHER_MAX_RESETS", 5)
                reset_window = getattr(self, "DISPATCHER_RESET_WINDOW", 600.0)

                if not self._can_attempt_reset(max_resets, reset_window):
                    logger.error(
                        f"[DISPATCHER-RESTART] ❌ Zu viele Resets ({max_resets}) in {reset_window:.0f}s – Abbruch",
                        extra={"component": "dispatcher_restart"},
                    )
                    diagnosis["reason"] = "too_many_resets"
                    return diagnosis

                is_dispatcher_thread = self._is_current_thread_dispatcher()
                if is_verbose:
                    logger.debug(
                        f"[DISPATCHER-RESTART] Aufgerufen {'vom' if is_dispatcher_thread else 'von extern'}-Dispatcher-Thread",
                        extra={"component": "dispatcher_restart"},
                    )

                cancelled = self._cancel_pending_futures(logger, debug_level)
                diagnosis["cancelled_futures"] = cancelled
                cleared = self._clear_queues(logger, debug_level)
                diagnosis["cleared_queue_items"] = cleared
                self._set_stop_events(logger, debug_level)
                self._send_stop_sentinel(logger, debug_level)
                self._join_dispatcher_thread(logger, debug_level)
                self._reset_pending_tasks(logger, debug_level)
                reader_restarted = self._restart_reader_thread_correct(
                    logger,
                    debug_level,
                    timeout=5.0,
                )
                diagnosis["reader_restarted"] = reader_restarted
                self._reset_audio_processor_safe(logger, debug_level)
                self._ensure_transcription_executor(logger, debug_level)
                self._update_watchdog_status()

                if not is_dispatcher_thread:
                    self._reset_events_for_restart(logger, debug_level)

                dispatcher_restarted = self._restart_dispatcher_if_needed(
                    logger,
                    debug_level,
                )
                diagnosis["dispatcher_restarted"] = dispatcher_restarted
                success = self._verify_dispatcher_restart(logger, debug_level)
                diagnosis["success"] = success
                diagnosis["reset_triggered"] = True
                diagnosis["reason"] = "reset_completed" if success else "reset_failed"

                elapsed = time.time() - start_time
                diagnosis["elapsed"] = elapsed

                if success:
                    logger.info(
                        f"[DISPATCHER-RESTART] ✅ Reset abgeschlossen in {elapsed:.2f}s "
                        f"(cancelled={cancelled}, cleared={cleared})",
                        extra={"component": "dispatcher_restart"},
                    )
                else:
                    logger.critical(
                        f"[DISPATCHER-RESTART] ❌ Reset fehlgeschlagen in {elapsed:.2f}s",
                        extra={"component": "dispatcher_restart"},
                    )

            except KeyboardInterrupt:
                logger.info(
                    "[DISPATCHER-RESTART] ⏹️ KeyboardInterrupt während Reset – breche ab",
                    extra={"component": "dispatcher_restart"},
                )
                diagnosis["reason"] = "interrupted"
                return diagnosis

            except Exception as e:
                logger.error(
                    f"[DISPATCHER-RESTART] 💥 Unerwarteter Fehler während Reset: {e}",
                    exc_info=True,
                    extra={"component": "dispatcher_restart"},
                )
                diagnosis["reason"] = f"exception: {type(e).__name__}"
                diagnosis["stacktrace"] = traceback.format_exc()
                return diagnosis

        return diagnosis

    def _restart_reader_thread_correct(
        self,
        logger,
        debug_level: int,
        timeout: float = 5.0,
    ) -> bool:
        """Startet den Reader-Thread KORREKT neu – mit Timeout pro Versuch."""
        import time

        if hasattr(self, "ffmpeg_manager") and self.ffmpeg_manager is not None:
            if hasattr(self.ffmpeg_manager, "restart_reader_thread"):
                try:
                    self.ffmpeg_manager.restart_reader_thread()
                    if debug_level >= 3:
                        logger.debug(
                            "[DISPATCHER-RESTART] Reader-Thread über FFmpegManager neu gestartet",
                            extra={"component": "dispatcher_restart"},
                        )
                    return True
                except Exception as e:
                    logger.warning(
                        f"[DISPATCHER-RESTART] FFmpegManager.restart_reader_thread fehlgeschlagen: {e}",
                        extra={"component": "dispatcher_restart"},
                    )

        if hasattr(self, "stream_handler") and self.stream_handler is not None:
            if hasattr(self.stream_handler, "_restart_reader_thread"):
                try:
                    self.stream_handler._restart_reader_thread()
                    if debug_level >= 3:
                        logger.debug(
                            "[DISPATCHER-RESTART] Reader-Thread über StreamHandler neu gestartet",
                            extra={"component": "dispatcher_restart"},
                        )
                    return True
                except Exception as e:
                    logger.warning(
                        f"[DISPATCHER-RESTART] StreamHandler._restart_reader_thread fehlgeschlagen: {e}",
                        extra={"component": "dispatcher_restart"},
                    )

        try:
            if hasattr(self, "_reader_thread") and self._reader_thread is not None:
                if self._reader_thread.is_alive():
                    if hasattr(self, "_reader_stop_event"):
                        self._reader_stop_event.set()
                    time.sleep(0.2)
                    self._reader_thread.join(timeout=timeout)

                if hasattr(self, "_start_reader_thread"):
                    self._start_reader_thread()
                    if debug_level >= 3:
                        logger.debug(
                            "[DISPATCHER-RESTART] Reader-Thread via _start_reader_thread neu gestartet",
                            extra={"component": "dispatcher_restart"},
                        )
                    return True
        except Exception as e:
            logger.warning(
                f"[DISPATCHER-RESTART] Direkter Reader-Thread-Neustart fehlgeschlagen: {e}",
                extra={"component": "dispatcher_restart"},
            )

        logger.warning(
            "[DISPATCHER-RESTART] ❌ Reader-Thread konnte nicht neu gestartet werden.",
            extra={"component": "dispatcher_restart"},
        )
        return False

    def _verify_dispatcher_restart(self, logger, debug_level: int) -> bool:
        """Prüft, ob der Dispatcher nach dem Reset erfolgreich neu gestartet wurde.
        Erweitert: Prüft auch, ob Daten fließen (Queue-Größe).
        """
        dispatcher_thread = getattr(self, "_dispatcher_thread", None)

        if dispatcher_thread is None:
            logger.warning(
                "[DISPATCHER-RESTART] ⚠️ Dispatcher-Thread ist None nach Reset",
                extra={"component": "dispatcher_restart"},
            )
            return False

        if not dispatcher_thread.is_alive():
            logger.warning(
                "[DISPATCHER-RESTART] ⚠️ Dispatcher-Thread ist tot nach Reset",
                extra={"component": "dispatcher_restart"},
            )
            return False

        if hasattr(self, "_dispatcher_shutdown") and self._dispatcher_shutdown.is_set():
            logger.warning(
                "[DISPATCHER-RESTART] ⚠️ _dispatcher_shutdown ist noch gesetzt",
                extra={"component": "dispatcher_restart"},
            )
            return False

        if (
            hasattr(self, "_dispatcher_stop_event")
            and self._dispatcher_stop_event.is_set()
        ):
            logger.warning(
                "[DISPATCHER-RESTART] ⚠️ _dispatcher_stop_event ist noch gesetzt",
                extra={"component": "dispatcher_restart"},
            )
            return False

        if hasattr(self, "_raw_audio_queue") and self._raw_audio_queue is not None:
            try:
                qsize = self._raw_audio_queue.qsize()
                if qsize > 0:
                    logger.debug(
                        f"[DISPATCHER-RESTART] ✅ Queue enthält {qsize} Elemente – Daten fließen",
                        extra={"component": "dispatcher_restart"},
                    )
                else:
                    logger.debug(
                        "[DISPATCHER-RESTART] ⚠️ Queue ist leer – möglicherweise noch keine Daten",
                        extra={"component": "dispatcher_restart"},
                    )
            except Exception:
                pass

        if debug_level >= 3:
            logger.debug(
                "[DISPATCHER-RESTART] ✅ Dispatcher-Thread läuft und Flags sind zurückgesetzt",
                extra={"component": "dispatcher_restart"},
            )
        return True

    def _can_attempt_reset(self, max_resets: int = 5, window: float = 600.0) -> bool:
        """Prüft, ob ein Reset erlaubt ist (max. `max_resets` innerhalb von `window` Sekunden)."""
        if not hasattr(self, "_reset_history"):
            self._reset_history = []

        now = time.time()
        self._reset_history = [t for t in self._reset_history if now - t < window]

        if len(self._reset_history) >= max_resets:
            return False

        self._reset_history.append(now)
        return True

    def _reset_audio_processor_safe(self, logger, debug_level: int) -> None:
        """Setzt den AudioProcessor zurück (falls verfügbar)."""
        ap = getattr(self, "_audio_processor", None)
        if ap is None:
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] AudioProcessor nicht verfügbar – überspringe reset_all",
                    extra={"component": "dispatcher_restart"},
                )
            return

        if hasattr(ap, "reset_all") and callable(ap.reset_all):
            try:
                ap.reset_all()
                if debug_level >= 3:
                    logger.debug(
                        "[DISPATCHER-RESTART] AudioProcessor.reset_all() aufgerufen",
                        extra={"component": "dispatcher_restart"},
                    )
            except Exception as e:
                logger.error(
                    f"[DISPATCHER-RESTART] AudioProcessor.reset_all() fehlgeschlagen: {e}",
                    exc_info=True,
                    extra={"component": "dispatcher_restart"},
                )
        elif debug_level >= 3:
            logger.debug(
                "[DISPATCHER-RESTART] AudioProcessor hat kein reset_all – überspringe",
                extra={"component": "dispatcher_restart"},
            )

    def _is_dispatcher_really_stuck(self) -> bool:
        """Prüft, ob der Dispatcher wirklich hängt (False-Positives vermeiden)."""
        import time as _time

        dispatcher_thread = getattr(self, "_dispatcher_thread", None)
        if dispatcher_thread is None or not dispatcher_thread.is_alive():
            return False

        try:
            q = getattr(self, "_raw_audio_queue", None)
            queue_size = q.qsize() if q is not None else 0
        except Exception:
            queue_size = 0
        try:
            pending = int(getattr(self, "_pending_tasks", 0) or 0)
        except Exception:
            pending = 0

        if queue_size == 0 and pending == 0:
            self._last_progress_time = _time.monotonic()
            return False

        last_progress = getattr(self, "_last_progress_time", None)
        if last_progress is None:
            self._last_progress_time = _time.monotonic()
            return False

        threshold = float(getattr(self, "_stuck_threshold_seconds", 90.0))
        try:
            elapsed = _time.monotonic() - last_progress
        except Exception:
            self._last_progress_time = _time.monotonic()
            return False

        if elapsed < threshold:
            return False

        for attr in (
            "_active_timeout_futures",
            "_active_translation_futures",
            "_timeout_futures",
        ):
            fut_set = getattr(self, attr, None)
            if not fut_set:
                continue
            try:
                active = sum(1 for f in fut_set if not f.done())
            except Exception:
                active = 0
            if active > 0:
                self._last_progress_time = _time.monotonic()
                return False

        return True

    def _log_stuck_thread_stacktrace(self, logger) -> None:
        """Loggt den Stacktrace des hängenden Dispatcher-Threads."""
        dispatcher_thread = getattr(self, "_dispatcher_thread", None)
        if dispatcher_thread is None:
            return

        try:
            import sys

            frame = sys._current_frames().get(dispatcher_thread.ident)
            if frame:
                stack = traceback.format_stack(frame)
                logger.warning(
                    f"[DISPATCHER-RESTART] 📊 Dispatcher-Thread Stacktrace:\n{''.join(stack)}",
                    extra={"component": "dispatcher_restart"},
                )
        except Exception as e:
            logger.debug(
                f"[DISPATCHER-RESTART] Stacktrace konnte nicht geloggt werden: {e}",
                extra={"component": "dispatcher_restart"},
            )

    def _clear_queues(self, logger, debug_level: int) -> int:
        """Leert alle relevanten Queues mit Begrenzung.
        Gibt die Gesamtzahl der geleerten Elemente zurück.
        """
        MAX_CLEAR = 10000
        total_cleared = 0

        for queue_name, queue_ref in [
            ("_raw_audio_queue", getattr(self, "_raw_audio_queue", None)),
            ("_read_queue", getattr(self, "_read_queue", None)),
        ]:
            if queue_ref is None:
                continue

            cleared = 0
            try:
                while cleared < MAX_CLEAR:
                    queue_ref.get_nowait()
                    cleared += 1
            except queue.Empty:
                pass
            except Exception as e:
                logger.warning(
                    f"[DISPATCHER-RESTART] Fehler beim Leeren von {queue_name}: {e}",
                    extra={"component": "dispatcher_restart"},
                )

            total_cleared += cleared
            if cleared and debug_level >= 3:
                logger.debug(
                    f"[DISPATCHER-RESTART] {cleared} Elemente aus {queue_name} entfernt",
                    extra={"component": "dispatcher_restart"},
                )

        return total_cleared

    def _restart_reader_thread_safe(self, logger, debug_level: int) -> bool:
        """Startet den Reader-Thread mit einem separaten Lock neu, um Race-Conditions zu vermeiden.
        Gibt True zurück, wenn der Neustart erfolgreich war.
        """
        if not hasattr(self, "_reader_restart_lock"):
            self._reader_restart_lock = threading.RLock()

        with self._reader_restart_lock:
            reader_thread = getattr(self, "_reader_thread", None)
            if reader_thread is not None:
                if debug_level >= 3:
                    logger.debug(
                        "[DISPATCHER-RESTART] Beende alten Reader-Thread...",
                        extra={"component": "dispatcher_restart"},
                    )
                if hasattr(self, "_reader_stop_event"):
                    self._reader_stop_event.set()

                time.sleep(0.2)
                if reader_thread.is_alive():
                    reader_thread.join(timeout=0.5)

            if hasattr(self, "_start_read_thread") and callable(
                self._start_read_thread,
            ):
                try:
                    self._start_read_thread()
                    if debug_level >= 3:
                        logger.debug(
                            "[DISPATCHER-RESTART] Reader-Thread neu gestartet",
                            extra={"component": "dispatcher_restart"},
                        )
                    return True
                except Exception as e:
                    logger.error(
                        f"[DISPATCHER-RESTART] Fehler beim Neustart des Reader-Threads: {e}",
                        exc_info=True,
                        extra={"component": "dispatcher_restart"},
                    )
            else:
                logger.warning(
                    "[DISPATCHER-RESTART] _start_read_thread Methode nicht vorhanden – Reader-Thread nicht neu gestartet",
                    extra={"component": "dispatcher_restart"},
                )
            return False

    def _restart_dispatcher_if_needed(self, logger, debug_level: int) -> bool:
        """Startet den Dispatcher neu, falls er tot ist.
        Gibt True zurück, wenn der Neustart erfolgreich war oder nicht nötig war.
        """
        dispatcher_thread = getattr(self, "_dispatcher_thread", None)

        if dispatcher_thread is not None and dispatcher_thread.is_alive():
            if debug_level >= 3:
                logger.debug(
                    "[DISPATCHER-RESTART] Dispatcher-Thread läuft noch – Neustart wird später erfolgen",
                    extra={"component": "dispatcher_restart"},
                )
            self._dispatcher_restart_needed = True
            return True

        logger.info(
            "[DISPATCHER-RESTART] 🔄 Starte Dispatcher neu...",
            extra={"component": "dispatcher_restart"},
        )

        try:
            if hasattr(self, "_start_dispatcher") and callable(self._start_dispatcher):
                self._start_dispatcher()
                logger.info(
                    "[DISPATCHER-RESTART] ✅ Dispatcher restart initiated",
                    extra={"component": "dispatcher_restart"},
                )
                return True
            logger.warning(
                "[DISPATCHER-RESTART] _start_dispatcher Methode nicht vorhanden – Dispatcher nicht neu gestartet",
                extra={"component": "dispatcher_restart"},
            )
        except Exception as e:
            logger.error(
                f"[DISPATCHER-RESTART] Dispatcher-Neustart fehlgeschlagen: {e}",
                exc_info=True,
                extra={"component": "dispatcher_restart"},
            )
        return False

    def _log_future_exception(
        self,
        future: Future,
        name: str,
        timeout: float = 0.0,
    ) -> None:
        """Safely log any exception that occurred in a Future without
        blocking or re‑raising.
        """
        if future is None:
            return
        try:
            if timeout > 0.0:
                try:
                    future.result(timeout=timeout)
                except FutureTimeout:
                    logger.warning(
                        "%s Future did not finish within %.1f s – "
                        "cannot retrieve exception.",
                        name,
                        timeout,
                    )
                    return
                except Exception:
                    pass
            elif not future.done():
                logger.debug(
                    "%s Future is not yet done – skipping exception check.",
                    name,
                )
                return

            exc = future.exception()
            if exc is not None:
                logger.error(
                    "❌ %s Future failed: %s: %s",
                    name,
                    type(exc).__name__,
                    exc,
                    exc_info=DEBUG_LEVEL >= 3,
                )
            elif future.cancelled():
                logger.debug("%s Future was cancelled.", name)

        except Exception as e:
            logger.warning(
                "Unexpected error while retrieving exception from %s Future: %s",
                name,
                e,
            )

    def _log_queue_stats_periodic(self) -> None:
        """Periodisch einen kompakten Status der Audio‑Pipeline ausgeben.
        Enthält Queue‑Grösse, Verarbeitungs‑Statistiken, Dispatcher‑Status,
        Realtime‑Faktor und aktuelle Chunk‑Zahl.
        """
        if DEBUG_LEVEL < 3 and "queue" not in DEBUG_COMPONENTS:
            return

        with self._state_lock:
            is_processing = self._state == AudioProcessor.State.PROCESSING
            is_starting = self._state == AudioProcessor.State.STARTING

        now = time.time()

        interval = 5.0 if is_processing else 30.0

        if now - self._last_queue_log_time < interval:
            return

        with self._stats_lock:
            enqueued = self._queue_enqueue_counter
            dequeued = self._queue_dequeue_counter
            dropped = self._queue_drop_counter
            chunks = self._chunk_counter
            rt_factor = self._last_realtime_factor
            slow_chunks = self._slow_chunks
            low_conf = self._low_conf_counter

        try:
            qsize = self._raw_audio_queue.qsize() if self._raw_audio_queue else -1
            maxsize = (
                getattr(self._raw_audio_queue, "maxsize", 0)
                if self._raw_audio_queue
                else -1
            )
        except Exception:
            qsize = -1
            maxsize = -1

        with self._pending_tasks_lock:
            pending = self._pending_tasks

        dispatcher_alive = (
            self._dispatcher_thread is not None and self._dispatcher_thread.is_alive()
        )
        dispatcher_shutdown = self._dispatcher_shutdown.is_set()

        active_futures = -1
        if DEBUG_LEVEL >= 4:
            with self._timeout_futures_lock:
                active_futures = len(self._active_timeout_futures)

        uptime = -1.0
        if self._stream_start_time is not None:
            uptime = now - self._stream_start_time

        log_msg = (
            f"AudioDispatcher: queue={qsize}/{maxsize if maxsize > 0 else '∞'} "
            f"enq={enqueued} deq={dequeued} drop={dropped} "
            f"pending={pending} chunks={chunks}"
        )

        if DEBUG_LEVEL >= 3:
            if rt_factor > 0:
                log_msg += f" rt={rt_factor:.2f}"
            if slow_chunks > 0:
                log_msg += f" slow={slow_chunks}"
            if low_conf > 0:
                log_msg += f" lowConf={low_conf}"
            if not dispatcher_alive:
                log_msg += " ⚠️ dispatcher=DEAD"
            elif dispatcher_shutdown:
                log_msg += " dispatcher=STOPPING"
            else:
                log_msg += " dispatcher=OK"

        if DEBUG_LEVEL >= 4 and active_futures >= 0:
            log_msg += f" futures={active_futures}"

        if uptime > 0:
            log_msg += f" uptime={uptime:.0f}s"

        if qsize > 0 and maxsize > 0 and qsize >= maxsize * 0.8:
            log_msg += " ⚠️ HIGH QUEUE LOAD"

        if is_starting:
            log_msg += " (starting)"

        log_debug("queue", log_msg)

        self._last_queue_log_time = now

    def _log_performance_snapshot(self) -> None:
        """Periodically logs a snapshot of system and processing performance
        when the component 'perf' is included in DEBUG_COMPONENTS.
        """
        if "perf" not in DEBUG_COMPONENTS and DEBUG_LEVEL < 3:
            return

        now = time.time()
        if not hasattr(self, "_last_perf_log_time"):
            self._last_perf_log_time = 0.0
        if now - self._last_perf_log_time < 15.0:
            return
        self._last_perf_log_time = now

        with self._stats_lock:
            chunks = self._chunk_counter
            rtf = self._last_realtime_factor
            slow = self._slow_chunks

        cpu_str = "N/A"
        ram_str = "N/A"
        gpu_str = ""
        try:
            import psutil

            cpu = psutil.cpu_percent(interval=0)
            mem = psutil.virtual_memory()
            cpu_str = f"{cpu:.0f}%"
            ram_str = f"{mem.used / (1024**3):.1f}/{mem.total / (1024**3):.1f}G"
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        if TORCH_AVAILABLE:
            try:
                import torch

                if torch.cuda.is_available():
                    alloc = torch.cuda.memory_allocated() / (1024**3)
                    reserve = torch.cuda.memory_reserved() / (1024**3)
                    gpu_str = f" VRAM alloc={alloc:.1f}G reserve={reserve:.1f}G"
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        logger.debug(
            "PERF: chunks=%d rtf=%.2f slow=%d cpu=%s ram=%s%s",
            chunks,
            rtf,
            slow,
            cpu_str,
            ram_str,
            gpu_str,
        )
        try:
            import time as _t_snap

            _now_snap = _t_snap.time()
            if not hasattr(self, "_ai_last_snapshot"):
                self._ai_last_snapshot = 0.0
            if _now_snap - self._ai_last_snapshot >= 60.0:
                self._ai_last_snapshot = _now_snap
                _ram_snap = str(ram_str).replace("G", "").strip()
                if "/" in _ram_snap:
                    _ram_snap = _ram_snap.split("/")[0]
                log_ai(
                    "SNAPSHOT",
                    chunks=chunks,
                    rtf=f"{rtf:.3f}",
                    cpu=str(cpu_str),
                    ram_gb=_ram_snap,
                    slow=slow,
                )
        except Exception:
            pass

    def _start_debug_monitor(self) -> None:
        """Startet einen Daemon‑Thread, der periodisch Queue‑ und
        Performance‑Statistiken ausgibt, solange die Verarbeitung aktiv ist.
        """
        if not getattr(self.settings, "enable_debug_monitor", True):
            return

        if (
            DEBUG_LEVEL < 3
            and "queue" not in DEBUG_COMPONENTS
            and "perf" not in DEBUG_COMPONENTS
        ):
            return

        try:
            with self._stats_lock:
                chunks = self._chunk_counter
                rt_factor = self._last_realtime_factor
        except Exception:
            chunks = 0
            rt_factor = 1.0

        interval = 5.0 if rt_factor > 1.5 or chunks > 1000 else 2.0

        if DEBUG_LEVEL >= 4:
            log_debug(
                "monitor",
                f"Debug‑Monitor Intervall: {interval:.1f}s (rt_factor={rt_factor:.2f})",
            )

        def _monitor_loop():
            logger.debug("Debug‑Monitor‑Thread gestartet (Intervall: %.1f s)", interval)
            while not self._debug_monitor_stop_event.is_set() and self.is_processing():
                try:
                    self._log_queue_stats_periodic()
                    self._log_performance_snapshot()

                    if DEBUG_LEVEL >= 3:
                        with self._pending_tasks_cond:
                            pending = self._pending_tasks
                        dispatcher_alive = (
                            self._dispatcher_thread is not None
                            and self._dispatcher_thread.is_alive()
                        )
                        with self._timeout_futures_lock:
                            active_futures = len(self._active_timeout_futures)

                        log_debug(
                            "monitor_detail",
                            f"pending_tasks={pending}, dispatcher_alive={dispatcher_alive}, "
                            f"active_futures={active_futures}, stop_event={self._stop_event.is_set()}",
                        )

                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        logger.exception("Fehler im Debug‑Monitor: %s", e)
                    else:
                        logger.debug("Fehler im Debug‑Monitor: %s", e)

                self._debug_monitor_stop_event.wait(timeout=interval)

            logger.debug("Debug‑Monitor‑Thread beendet.")

        stream_id = getattr(self, "_current_stream_id", None) or "unknown"
        thread_name = f"DebugMonitor-{stream_id}"

        self._debug_monitor_thread = threading.Thread(
            target=_monitor_loop,
            daemon=True,
            name=thread_name,
        )
        self._debug_monitor_thread.start()

        if DEBUG_LEVEL >= 2:
            log_debug(
                "monitor",
                f"Debug‑Monitor gestartet (Thread: {thread_name}, Intervall: {
                    interval:.1f}s)",
            )

    @contextmanager
    def _pending_task_guard(self):
        """Context Manager, der den Zähler für ausstehende Transkriptionen
        automatisch erhöht und nach Verlassen des Blocks wieder dekrementiert.
        Verhindert manuelle Fehler beim Zählen und ist threadsicher.
        """
        self._modify_pending_tasks(1)
        try:
            yield
        finally:
            self._modify_pending_tasks(-1)

    def _process_audio_chunk_async(
        self,
        audio_data: bytes,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
        error_callback: ErrorCallback,
        overlap_bytes: int = 0,
        chunk_byte_offset: int | None = None,
        overlap_duration: float = 0.0,
    ) -> dict[str, Any] | None:
        """Verarbeitet einen einzelnen Audio-Chunk asynchron."""
        import gc
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        thread_name = threading.current_thread().name

        phase_times: dict[str, float] = {}
        _phase_t0 = time.perf_counter()

        def _mark_phase(name: str) -> float:
            """Markiert das Ende einer Phase und gibt die Dauer in ms zurück."""
            nonlocal _phase_t0
            now = time.perf_counter()
            delta_ms = (now - _phase_t0) * 1000.0
            phase_times[name] = round(delta_ms, 2)
            _phase_t0 = now
            return delta_ms

        start_time = time.perf_counter()

        lock = getattr(self, "_chunk_counter_lock", None)
        if lock is None:
            lock = threading.Lock()
            with contextlib.suppress(Exception):
                self._chunk_counter_lock = lock

        with lock:
            self._chunk_counter += 1
            chunk_id = self._chunk_counter

        processing_duration = 0.0
        chunk_duration = 0.0
        bytes_per_sec = 32000
        processed_audio = audio_data
        trans_engine = None
        absolute_offset = 0.0
        rt_factor = 1.0
        dynamic_timeout = 30.0
        stop_event = self._stop_event
        settings = self.settings
        config = settings.config if settings else None

        result_status: dict[str, Any] = {
            "chunk_id": chunk_id,
            "success": False,
            "segments_count": 0,
            "callback_called": False,
            "error": None,
            "processing_time": 0.0,
            "phase_times": phase_times,
            "thread": thread_name,
        }

        def _finalize_early(
            phase_name: str,
            callback_reason: str | None = None,
        ) -> dict[str, Any]:
            """Beendet die Methode vorzeitig.

            `callback_reason=None` unterdrückt den Callback (reiner Stop).
            """
            _mark_phase(phase_name)
            if callback_reason is not None:
                self._safe_call_callback(
                    transcription_callback,
                    "",
                    chunk_id,
                    callback_reason,
                )
            result_status["callback_called"] = True
            result_status["phase_times"] = dict(phase_times)
            return result_status

        if debug_level >= 4:
            logger.debug(
                "[CHUNK] #%d ENTRY (thread=%s, bytes=%d, offset=%s, overlap=%.2fs)",
                chunk_id,
                thread_name,
                len(audio_data),
                chunk_byte_offset,
                overlap_duration,
                extra={"component": "chunk", "chunk_id": chunk_id},
            )

        try:
            if not self._validate_chunk_prerequisites(audio_data):
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d prerequisites failed (bytes=%d) – skip",
                        chunk_id,
                        len(audio_data),
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                return _finalize_early("validate_prerequisites", "prerequisites_failed")

            _mark_phase("validate_prerequisites")
            trans_engine = self._transcription_engine
            if trans_engine is None or not trans_engine.is_functional():
                if debug_level >= 2:
                    logger.warning(
                        "[CHUNK] #%d transcription engine not functional – saving chunk",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                self._save_lost_chunk(audio_data, "engine_unavailable")
                return _finalize_early("check_engine", "engine_unavailable")

            _mark_phase("check_engine")

            if stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d stop event set early – skip",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                return _finalize_early("stop_event_early")

            bytes_per_sec = self._calculate_adaptive_bytes_per_sec(config)
            is_cpu_mode = getattr(config, "_is_cpu_mode", False)

            offset_result = self._calculate_chunk_offset(
                audio_data=audio_data,
                bytes_per_sec=bytes_per_sec,
                chunk_byte_offset=chunk_byte_offset,
                overlap_duration=overlap_duration,
                chunk_id=chunk_id,
            )
            if offset_result is None:
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d offset calculation failed – skip",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                return _finalize_early("calc_offset", "offset_failed")

            absolute_offset = offset_result["absolute_offset"]
            chunk_duration = offset_result["chunk_duration"]
            max_allowed_offset = offset_result["max_allowed_offset"]
            processed_audio = offset_result["audio_data"]
            _mark_phase("calc_offset")

            if debug_level >= 3:
                logger.debug(
                    "[CHUNK] #%d prepared: duration=%.2fs, offset=%.3fs, bytes_per_sec=%d",
                    chunk_id,
                    chunk_duration,
                    absolute_offset,
                    bytes_per_sec,
                    extra={"component": "chunk", "chunk_id": chunk_id},
                )

            processed_audio = self._apply_audio_enhancement(
                audio_data=processed_audio,
                chunk_id=chunk_id,
                is_cpu_mode=is_cpu_mode,
            )
            _mark_phase("enhancement")

            if stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d stop event set after enhancement – skip",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                return _finalize_early("stop_event_after_enhancement", "stop_event")

            rt_factor = self._get_realtime_factor()
            dynamic_timeout = self._calculate_dynamic_timeout(
                chunk_duration=chunk_duration,
                is_cpu_mode=is_cpu_mode,
                rt_factor=rt_factor,
            )
            _mark_phase("calc_timeout")

            if debug_level >= 3:
                logger.debug(
                    "[CHUNK] #%d timeout=%.1fs (rt=%.2f, cpu=%s)",
                    chunk_id,
                    dynamic_timeout,
                    rt_factor,
                    is_cpu_mode,
                    extra={"component": "chunk", "chunk_id": chunk_id},
                )

            segments, task_failed = self._perform_transcription_with_fallback(
                chunk_id=chunk_id,
                audio_data=processed_audio,
                trans_engine=trans_engine,
                dynamic_timeout=dynamic_timeout,
                error_callback=error_callback,
            )
            _mark_phase("transcription")

            if stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d stop event set after transcription – skip",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                return _finalize_early(
                    "stop_event_after_transcription",
                    "stop_event_after_transcription",
                )

            valid_segments = self._validate_and_clean_segments(
                chunk_id=chunk_id,
                segments=segments,
                trans_engine=trans_engine,
            )
            _mark_phase("validate_segments")

            processing_duration = time.perf_counter() - start_time

            if debug_level >= 3:
                logger.debug(
                    "[CHUNK] #%d validate done: %d raw → %d valid (took %.3fs)",
                    chunk_id,
                    len(segments),
                    len(valid_segments),
                    processing_duration,
                    extra={"component": "chunk", "chunk_id": chunk_id},
                )

            if valid_segments:
                self._apply_timestamps(
                    valid_segments,
                    absolute_offset,
                    overlap_duration,
                    max_allowed_offset,
                )
                self._apply_forced_language(valid_segments, trans_engine, chunk_id)
                _mark_phase("apply_timestamps")

                if debug_level >= 2:
                    logger.debug(
                        "[CHUNK] #%d dispatching %d segments",
                        chunk_id,
                        len(valid_segments),
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )

                try:
                    self._dispatch_segments(
                        chunk_id=chunk_id,
                        segments=valid_segments,
                        transcription_callback=transcription_callback,
                        translation_callback=translation_callback,
                    )
                    result_status["segments_count"] = len(valid_segments)
                    result_status["success"] = True
                except Exception as dispatch_error:
                    logger.error(
                        "[CHUNK] #%d dispatch failed: %s",
                        chunk_id,
                        dispatch_error,
                        exc_info=True,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )
                    self._safe_call_callback(
                        error_callback,
                        f"Dispatch-Fehler in Chunk {chunk_id}: {dispatch_error}",
                        chunk_id,
                        "dispatch_error",
                    )
                    result_status["callback_called"] = True
                    raise
                _mark_phase("dispatch")

            else:
                if task_failed:
                    self._save_lost_chunk(
                        processed_audio,
                        f"transcription_failed_chunk_{chunk_id}",
                    )
                    if debug_level >= 2:
                        logger.debug(
                            "[CHUNK] #%d transcription failed – chunk saved",
                            chunk_id,
                            extra={"component": "chunk", "chunk_id": chunk_id},
                        )
                elif debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d no valid segments (likely silence/noise)",
                        chunk_id,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )

                self._safe_call_callback(
                    transcription_callback,
                    "",
                    chunk_id,
                    "no_segments" if not task_failed else "transcription_failed",
                )
                result_status["callback_called"] = True
                _mark_phase("empty_segments")

            self._update_realtime_factor(chunk_duration, processing_duration)
            _mark_phase("update_rt_factor")

            if debug_level >= 3:
                self._log_chunk_performance(
                    chunk_id,
                    chunk_duration,
                    processing_duration,
                    valid_segments,
                )

            result_status["processing_time"] = processing_duration

            total_ms = (time.perf_counter() - start_time) * 1000.0
            if debug_level >= 2:
                logger.debug(
                    "[CHUNK] #%d OK (t=%.0fms, rt=%.2f, segs=%d, phases=%s)",
                    chunk_id,
                    total_ms,
                    rt_factor,
                    len(valid_segments),
                    phase_times,
                    extra={"component": "chunk", "chunk_id": chunk_id},
                )

        except Exception as e:
            elapsed_ms = (time.perf_counter() - start_time) * 1000.0

            logger.error(
                "[CHUNK] #%d CRITICAL after %.0fms "
                "(duration=%.2fs, offset=%.3fs, rt=%.2f): %s",
                chunk_id,
                elapsed_ms,
                chunk_duration,
                absolute_offset,
                rt_factor,
                e,
                exc_info=True,
                extra={"component": "chunk", "chunk_id": chunk_id},
            )
            result_status["error"] = str(e)
            result_status["phase_times"] = dict(phase_times)

            self._handle_critical_chunk_error(
                chunk_id=chunk_id,
                audio_data=processed_audio,
                error=e,
                trans_engine=trans_engine,
                chunk_duration=chunk_duration,
                absolute_offset=absolute_offset,
                rt_factor=rt_factor,
                dynamic_timeout=dynamic_timeout,
                error_callback=error_callback,
            )

            self._safe_call_callback(
                error_callback,
                f"Kritischer Fehler in Chunk {chunk_id}: {e}",
                chunk_id,
                "critical_error",
            )
            result_status["callback_called"] = True
            raise

        finally:
            try:
                self._update_chunk_statistics(processed_audio, bytes_per_sec)
            except Exception as stat_exc:
                if debug_level >= 3:
                    logger.debug(
                        "[CHUNK] #%d statistics update failed: %s",
                        chunk_id,
                        stat_exc,
                        extra={"component": "chunk", "chunk_id": chunk_id},
                    )

            if processing_duration > chunk_duration * 10 and chunk_duration > 0:
                time.sleep(0.01)

            try:
                gc_lock = getattr(self, "_gc_counter_lock", None)
                if gc_lock is None:
                    gc_lock = threading.Lock()
                    self._gc_counter_lock = gc_lock
                with gc_lock:
                    if not hasattr(self, "_gc_counter"):
                        self._gc_counter = 0
                    self._gc_counter += 1
                    gc_now = self._gc_counter % 5 == 0
                if gc_now:
                    gc.collect()
                    if debug_level >= 4:
                        logger.debug(
                            "[CHUNK] #%d GC triggered",
                            chunk_id,
                            extra={"component": "gc", "chunk_id": chunk_id},
                        )
            except Exception:
                pass

            if debug_level >= 4:
                logger.debug(
                    "[CHUNK] #%d exit (success=%s, segs=%d, callback=%s, phases=%s)",
                    chunk_id,
                    result_status["success"],
                    result_status["segments_count"],
                    result_status["callback_called"],
                    phase_times,
                    extra={"component": "chunk", "chunk_id": chunk_id},
                )

        return result_status

    def _safe_call_callback(
        self,
        callback: Callable | None,
        data: Any,
        chunk_id: int,
        context: str = "unknown",
    ) -> bool:
        """Ruft einen Callback sicher auf – mit Fehlerbehandlung und Debug-Log."""
        if callback is None:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "chunk",
                    f"Chunk #{chunk_id}: Callback ist None (context={context}) – überspringe",
                )
            return False

        if not callable(callback):
            logger.warning(
                f"[CHUNK] Chunk #{chunk_id}: Callback nicht aufrufbar (Typ: {type(callback).__name__}) – überspringe",
                extra={"component": "chunk"},
            )
            return False

        try:
            callback(data)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "chunk",
                    f"Chunk #{chunk_id}: Callback erfolgreich aufgerufen (context={context}, data_len={len(str(data))})",
                )
            return True
        except Exception as e:
            logger.error(
                f"[CHUNK] Chunk #{chunk_id}: Fehler beim Aufruf des Callbacks (context={context}): {e}",
                exc_info=True,
                extra={"component": "chunk"},
            )
            return False

    def _calculate_adaptive_bytes_per_sec(self, config: Any) -> float:
        """Berechnet die adaptive Bitrate."""
        nominal = float(config.BYTES_PER_SECOND)
        if not hasattr(self, "_adaptive_warmup_chunks"):
            self._adaptive_warmup_chunks = 0
        self._adaptive_warmup_chunks += 1

        if self._adaptive_warmup_chunks <= 5:
            return nominal

        adaptive = getattr(self, "_adaptive_bytes_per_sec", nominal)
        if adaptive <= 0:
            return nominal

        deviation = abs(adaptive - nominal) / max(1.0, nominal)
        if deviation > 0.05:
            log_debug(
                "adaptive_rate",
                f"Adaptive Rate: {adaptive:.0f} B/s (Abweichung {deviation:.1%})",
            )
            return adaptive
        return nominal

    def _calculate_chunk_offset(
        self,
        audio_data: bytes,
        bytes_per_sec: float,
        chunk_byte_offset: int | None,
        overlap_duration: float,
        chunk_id: int,
    ) -> dict[str, Any] | None:
        """Berechnet Offset, Dauer und kürzt ggf. den Chunk."""
        if not hasattr(self, "_monotonic_offset"):
            self._monotonic_offset = 0.0

        monotonic_offset = self._monotonic_offset
        expected_duration = self._expected_duration
        tolerance = max(1.0, getattr(self.settings, "duration_tolerance", 5.0))

        if chunk_byte_offset is not None:
            current_offset = chunk_byte_offset / bytes_per_sec
            if overlap_duration > 0.0:
                current_offset = max(0.0, current_offset - overlap_duration)
        else:
            with self._stats_lock:
                current_offset = self._total_bytes_processed / max(1.0, bytes_per_sec)
            if overlap_duration > 0.0:
                current_offset = max(0.0, current_offset - overlap_duration)

        if current_offset < monotonic_offset:
            log_debug(
                "offset",
                f"Chunk #{chunk_id}: Offset auf {monotonic_offset:.3f} korrigiert",
            )
            current_offset = monotonic_offset

        max_allowed_offset = None
        if expected_duration is not None and expected_duration > 0:
            max_allowed_offset = expected_duration + tolerance
            if current_offset > max_allowed_offset:
                log_debug(
                    "offset",
                    f"Chunk #{chunk_id}: Überschreitung – passe Dauer an",
                )
                with self._stats_lock:
                    self._expected_duration = current_offset + tolerance
                expected_duration = self._expected_duration
                max_allowed_offset = expected_duration + tolerance

        raw_length = len(audio_data)
        chunk_duration = raw_length / bytes_per_sec
        chunk_end = current_offset + chunk_duration

        if max_allowed_offset is not None and chunk_end > max_allowed_offset:
            new_duration = max(0.1, max_allowed_offset - current_offset)
            log_debug(
                "offset",
                f"Chunk #{chunk_id}: gekürzt {chunk_duration:.2f}s → {
                    new_duration:.2f}s",
            )
            chunk_duration = new_duration
            new_len = int(chunk_duration * bytes_per_sec)
            if new_len < len(audio_data):
                audio_data = audio_data[:new_len]
                if len(audio_data) < 16:
                    log_debug("offset", f"Chunk #{chunk_id}: zu kurz nach Kürzung")
                    return None

        absolute_offset = max(0.0, current_offset)
        new_monotonic = absolute_offset + chunk_duration - 0.001
        if max_allowed_offset is not None:
            new_monotonic = min(new_monotonic, max_allowed_offset)
        if new_monotonic > monotonic_offset:
            self._monotonic_offset = new_monotonic

        return {
            "absolute_offset": absolute_offset,
            "chunk_duration": chunk_duration,
            "max_allowed_offset": max_allowed_offset,
            "audio_data": audio_data,
        }

    def _apply_audio_enhancement(
        self,
        audio_data: bytes,
        chunk_id: int | None = None,
        is_cpu_mode: bool = False,
    ) -> bytes:
        """Wendet Audio-Enhancement an – nur wenn aktiv und sinnvoll."""
        if not hasattr(self, "settings") or self.settings is None:
            return audio_data

        if not self.settings.enable_audio_enhancement or self._audio_enhancer is None:
            return audio_data
        with self._last_confidence_lock:
            last_conf = self.last_confidence

        apply_enhancement = (last_conf < 0.5) or (self._noisereduce_counter % 3 == 0)
        if is_cpu_mode and apply_enhancement:
            apply_enhancement = last_conf < 0.4

        if not apply_enhancement:
            return audio_data

        try:
            with self._noisereduce_lock:
                nr_counter = self._noisereduce_counter
                self._noisereduce_counter += 1

            enhanced = self._audio_enhancer.enhance_audio(
                audio_data,
                last_conf,
                nr_counter,
            )

            if DEBUG_LEVEL >= 3:
                chunk_info = f"Chunk #{chunk_id} " if chunk_id is not None else ""
                log_debug(
                    "enhance",
                    f"{chunk_info}Enhancement applied (conf={last_conf:.2f}, "
                    f"counter={nr_counter}, cpu={is_cpu_mode})",
                )

            return enhanced

        except Exception as e:
            if DEBUG_LEVEL >= 3:
                chunk_info = f"Chunk #{chunk_id} " if chunk_id is not None else ""
                log_debug("enhance", f"{chunk_info}Enhancement failed: {e}")
            return audio_data

    def _get_realtime_factor(self) -> float:
        """Holt den aktuellen Realtime-Faktor (thread-safe)."""
        with self._stats_lock:
            value = getattr(self, "_last_realtime_factor", 1.0)
            value = max(value, 1.0)
            return value

    def _calculate_dynamic_timeout(
        self,
        chunk_duration: float,
        is_cpu_mode: bool,
        rt_factor: float,
    ) -> float:
        """Berechnet das dynamische Timeout für die Transkription eines Audio-Chunks."""
        if chunk_duration <= 0.0:
            chunk_duration = 0.1

        capped_rt = max(1.0, min(rt_factor, 5.0))

        if is_cpu_mode:
            base_timeout = max(20.0, chunk_duration * 1.5)
        else:
            base_timeout = max(30.0, chunk_duration * 3.0)

        timeout = base_timeout * capped_rt
        timeout = max(10.0, min(180.0, timeout))

        min_timeout = max(10.0, chunk_duration * 2.0)
        timeout = max(timeout, min_timeout)

        return timeout

    def _apply_forced_language(
        self,
        segments: list,
        trans_engine: Any,
        chunk_id: int,
    ) -> None:
        """Wendet die erzwungene Sprache an (falls vorhanden)."""
        forced_lang = getattr(trans_engine, "forced_language", None)
        if not forced_lang:
            return

        auto_lang = getattr(trans_engine, "_last_auto_detected_language", None)
        if auto_lang and auto_lang != "unknown":
            for seg in segments:
                if hasattr(seg, "language") and seg.language != auto_lang:
                    seg.language = auto_lang
                    log_debug(
                        "language",
                        f"Chunk #{chunk_id}: Sprache auf {auto_lang} korrigiert",
                    )

    def _log_chunk_performance(
        self,
        chunk_id: int,
        chunk_duration: float,
        processing_duration: float,
        valid_segments: list,
    ) -> None:
        """Protokolliert Performance-Metriken."""
        if DEBUG_LEVEL >= 3:
            rt = processing_duration / chunk_duration if chunk_duration > 0 else 0.0
            log_debug(
                "performance",
                f"Chunk #{chunk_id}: Dauer={processing_duration:.2f}s, "
                f"Chunk={chunk_duration:.2f}s, RT={rt:.2f}, Segmente={
                    len(valid_segments)
                }",
            )

        if processing_duration > chunk_duration * 2.0:
            self._slow_chunks += 1
            if DEBUG_LEVEL >= 2 and processing_duration > chunk_duration * 4.0:
                log_debug(
                    "perf_warn",
                    f"Chunk #{chunk_id}: EXTREM langsam – RT={
                        processing_duration / chunk_duration:.2f}",
                )

    def _update_chunk_statistics(self, audio_data: bytes, bytes_per_sec: float) -> None:
        """Aktualisiert die globalen Statistiken nach Abschluss eines Chunks."""
        import hashlib
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not audio_data:
            return

        try:
            bps = float(bytes_per_sec)
        except (TypeError, ValueError):
            bps = 1.0
        if bps <= 0.0:
            bps = 1.0

        audio_len = len(audio_data)

        stats_lock = getattr(self, "_stats_lock", None)
        if stats_lock is None:
            stats_lock = threading.RLock()
            with contextlib.suppress(Exception):
                self._stats_lock = stats_lock

        with stats_lock:
            current_total = getattr(self, "_total_bytes_processed", 0)
            new_total = current_total + audio_len
            self._total_bytes_processed = new_total
            processed_seconds = new_total / bps
            self._processed_seconds = processed_seconds
            self._real_processed_seconds = processed_seconds

        last_hashes = getattr(self, "_last_chunk_hashes", None)
        if last_hashes is not None:
            try:
                chunk_hash = hashlib.sha256(audio_data).digest()
                now_mono = time.monotonic()
                with stats_lock:
                    last_hashes.append((chunk_hash, now_mono))
            except Exception as e:
                if debug_level >= 2:
                    logger.debug(
                        f"_update_chunk_statistics: Hash-Update fehlgeschlagen: "
                        f"{type(e).__name__}: {e}"
                    )

        if debug_level >= 4:
            logger.debug(
                f"_update_chunk_statistics: +{audio_len} bytes, "
                f"total={self._total_bytes_processed} bytes "
                f"(~{processed_seconds:.2f}s @ {bps:.0f} B/s), "
                f"hash_buffer={len(last_hashes) if last_hashes is not None else 0}"
            )

    def _trigger_translations(
        self,
        segments: list[TranscriptionResult],
        translation_callback: TranslationCallback,
        trans_engine: TranscriptionEngine,
    ) -> None:
        """Zentrale Methode zum Auslösen von Übersetzungen."""
        import inspect
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not translation_callback:
            if debug_level >= 2:
                logger.debug(
                    "[TRANSLATE] ❌ translation_callback ist None – überspringe"
                )
            return

        if not self._translation_enabled.is_set():
            if debug_level >= 2:
                logger.debug("[TRANSLATE] ⏸️ Übersetzung deaktiviert – überspringe")
            return

        translation_engine = self._translation_engine
        if translation_engine is None:
            if debug_level >= 2:
                logger.warning(
                    "[TRANSLATE] ⚠️ translation_engine ist None – überspringe"
                )
            return

        if not segments:
            if debug_level >= 3:
                logger.debug("[TRANSLATE] ℹ️ Keine Segmente – überspringe")
            return

        if not hasattr(self, "_translate_and_send_async"):
            logger.error(
                "[TRANSLATE] ❌ _translate_and_send_async Methode nicht gefunden!"
            )
            return

        translate_method = self._translate_and_send_async

        try:
            sig = inspect.signature(translate_method)
            param_names = list(sig.parameters.keys())
            if debug_level >= 3:
                logger.debug(f"[TRANSLATE] 📋 Methode erwartet: {param_names}")
        except Exception as e:
            if debug_level >= 3:
                logger.debug(f"[TRANSLATE] ℹ️ Signatur nicht ermittelbar: {e}")
            param_names = []

        def _get_param_name(candidates: list[str]) -> str | None:
            for name in candidates:
                if name in param_names:
                    return name
            return None

        callback_param_name = _get_param_name(
            ["translation_callback", "callback", "cb", "on_translation"]
        )
        text_param_name = _get_param_name(["text", "transcript", "content"])
        source_lang_param_name = _get_param_name(
            ["source_lang", "src_lang", "source", "lang"]
        )
        start_param_name = _get_param_name(["start", "start_time", "begin"])
        end_param_name = _get_param_name(["end", "end_time", "finish"])

        if debug_level >= 3:
            logger.debug(
                f"[TRANSLATE] 📋 Param-Mapping: callback={callback_param_name}, text={text_param_name}, "
                f"source_lang={source_lang_param_name}, start={start_param_name}, end={end_param_name}"
            )

        translated_count = 0
        skipped_count = 0
        error_count = 0

        for seg in segments:
            if seg is None:
                skipped_count += 1
                continue

            try:
                text = getattr(seg, "text", "").strip()
                if not text or len(text) < 2:
                    skipped_count += 1
                    continue

                language = getattr(seg, "language", None)
                if not language or language == "unknown":
                    if (
                        trans_engine
                        and hasattr(trans_engine, "forced_language")
                        and trans_engine.forced_language
                    ):
                        language = trans_engine.forced_language
                    else:
                        language = "auto"

                start = getattr(seg, "start", None)
                end = getattr(seg, "end", None)

                kwargs = {}

                if text_param_name:
                    kwargs[text_param_name] = text
                else:
                    kwargs["text"] = text

                if source_lang_param_name:
                    kwargs[source_lang_param_name] = language
                else:
                    kwargs["source_lang"] = language

                if callback_param_name:
                    kwargs[callback_param_name] = translation_callback
                else:
                    try:
                        kwargs["callback"] = translation_callback
                    except Exception:
                        if debug_level >= 3:
                            logger.debug("[TRANSLATE] ℹ️ Verwende positional arguments")

                if start is not None and start_param_name:
                    kwargs[start_param_name] = start
                if end is not None and end_param_name:
                    kwargs[end_param_name] = end

                if debug_level >= 3:
                    logger.debug(
                        f"[TRANSLATE] 📤 Übersetzung für: '{text[:30]}...' (lang={language}, kwargs={list(kwargs.keys())})"
                    )

                try:
                    translate_method(**kwargs)
                    translated_count += 1
                except TypeError as e:
                    if "callback" in str(e) or "unexpected keyword" in str(e):
                        if debug_level >= 2:
                            logger.warning(
                                f"[TRANSLATE] ⚠️ Callback-Argument abgelehnt – versuche ohne: {e}"
                            )
                        kwargs.pop(callback_param_name, None)
                        kwargs.pop("callback", None)
                        try:
                            translate_method(**kwargs)
                            translated_count += 1
                        except Exception as e2:
                            logger.error(
                                f"[TRANSLATE] ❌ Fehler beim Übersetzen (ohne Callback): {e2}"
                            )
                            error_count += 1
                    else:
                        raise

                except Exception as e:
                    logger.error(f"[TRANSLATE] ❌ Fehler beim Übersetzen: {e}")
                    error_count += 1

            except Exception as e:
                logger.error(f"[TRANSLATE] ❌ Unerwarteter Fehler für Segment: {e}")
                error_count += 1

        if debug_level >= 1:
            logger.debug(
                f"[TRANSLATE] 📊 Übersetzungen: {translated_count} erfolgreich, "
                f"{skipped_count} übersprungen, {error_count} Fehler (Gesamt: {len(segments)})",
            )

        if translated_count == 0 and len(segments) > 0 and error_count > 0:
            logger.warning(
                "[TRANSLATE] ⚠️ Keine Übersetzung erfolgreich – prüfe Engine oder Callback"
            )

    def _perform_transcription_with_fallback(
        self,
        chunk_id: int,
        audio_data: bytes,
        trans_engine: TranscriptionEngine,
        dynamic_timeout: float,
        error_callback: ErrorCallback,
    ) -> tuple[list[TranscriptionResult], bool]:
        """Führt die Transkription mit Fallback bei Fehlern durch – ULTIMATIVE VERSION."""
        import time

        logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        segments: list[TranscriptionResult] = []
        task_failed = False
        first_attempt_failed = False

        if DEBUG_LEVEL >= 3:
            log_debug(
                "transcribe",
                f"Chunk #{chunk_id}: Starte Transkription (Timeout={dynamic_timeout:.1f}s, Audio={len(audio_data)} bytes)",
            )

        try:
            result = self._transcribe_with_timeout(
                audio_data,
                timeout=dynamic_timeout,
            )

            if result is None:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcribe",
                        f"Chunk #{chunk_id}: Transcription returned None",
                    )
                first_attempt_failed = True
                task_failed = True
            elif not result:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcribe",
                        f"Chunk #{chunk_id}: Transcription returned empty list",
                    )
                first_attempt_failed = True
                task_failed = True
            else:
                segments = result
                with self._stats_lock:
                    self._consecutive_timeouts = 0
                    self._consecutive_errors = 0

                duration = time.monotonic() - start_time
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "transcribe",
                        f"Chunk #{chunk_id}: Transcription OK ({len(segments)} segments) in {duration * 1000:.1f}ms",
                    )
                self._invoke_transcription_callback(segments, chunk_id)
                return segments, False

        except TimeoutError as e:
            logger.error(
                f"Chunk #{chunk_id}: Transcription timeout after {
                    dynamic_timeout:.1f}s: {e}"
            )
            first_attempt_failed = True
            task_failed = True
        except TranscriptionError as e:
            logger.error(f"Chunk #{chunk_id}: TranscriptionError: {e}")
            first_attempt_failed = True
            task_failed = True
        except RuntimeError as e:
            error_msg = str(e).lower()
            if "out of memory" in error_msg and trans_engine.device == "cuda":
                logger.error(f"Chunk #{chunk_id}: CUDA OOM, versuche CPU‑Fallback")
                trans_engine._handle_universal_cuda_oom()
                first_attempt_failed = True
                task_failed = True
            else:
                logger.exception(f"Chunk #{chunk_id}: Unexpected RuntimeError")
                first_attempt_failed = True
                task_failed = True
        except Exception as e:
            logger.exception(f"Chunk #{chunk_id}: Unexpected transcription error: {e}")
            first_attempt_failed = True
            task_failed = True

        if first_attempt_failed and not self._stop_event.is_set():
            logger.info(
                f"Chunk #{chunk_id}: Trying fallback transcription (minimal params)",
            )
            try:
                forced_lang = getattr(trans_engine, "forced_language", None)
                fallback_result = trans_engine.transcribe_with_language(
                    audio_data,
                    language=forced_lang,
                    include_timestamps=True,
                    cancel_event=None,
                )

                if fallback_result is not None:
                    if isinstance(fallback_result, list):
                        segments = fallback_result
                    else:
                        segments = [fallback_result] if fallback_result else []

                    if segments:
                        task_failed = False
                        logger.info(
                            f"Chunk #{chunk_id}: Fallback successful ({
                                len(segments)
                            } segments)"
                        )

                        with self._stats_lock:
                            self._consecutive_timeouts = 0
                            self._consecutive_errors = 0

                        self._invoke_transcription_callback(segments, chunk_id)

                        return segments, False
                    logger.warning(
                        f"Chunk #{chunk_id}: Fallback returned empty list",
                    )
                else:
                    logger.warning(f"Chunk #{chunk_id}: Fallback returned None")

            except Exception as e:
                logger.error(f"Chunk #{chunk_id}: Fallback failed: {e}")

        if not segments:
            segments = []
            task_failed = True

        if not isinstance(segments, list):
            segments = [segments] if segments else []

        if segments and not task_failed:
            self._invoke_transcription_callback(segments, chunk_id)

        return segments, task_failed

    def _invoke_transcription_callback(
        self,
        segments: list[TranscriptionResult],
        chunk_id: int,
    ) -> dict[str, Any]:
        """Zentraler Einstiegspunkt für Transkriptions- UND Übersetzungs-Ausgabe."""
        import logging
        import threading
        import time

        MAX_CALLBACK_TEXT_LENGTH = getattr(self, "_max_callback_text_length", 10000)
        LOG_PREVIEW_LEN = 80
        MIN_TEXT_LENGTH = 1
        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        thread_name = threading.current_thread().name
        is_main_thread = threading.current_thread() is threading.main_thread()

        start_time = time.perf_counter()
        call_id = f"{int(start_time * 1000)}-{chunk_id}"

        metrics: dict[str, Any] = {
            "call_id": call_id,
            "chunk_id": chunk_id,
            "success": False,
            "delivered": False,
            "callback_type": None,
            "callback_bound_to_gui": False,
            "dispatch_chain": [],
            "text_length": 0,
            "text_preview": "",
            "was_truncated": False,
            "extraction_errors": [],
            "execution_time_ms": 0.0,
            "extraction_time_ms": 0.0,
            "invoke_time_ms": 0.0,
            "fallback_used": False,
            "fallback_reason": None,
            "thread_info": thread_name,
            "is_main_thread": is_main_thread,
            "headless_mode": False,
            "translation_triggered": False,
            "translation_skip_reason": None,
            "detected_language": None,
            "exception": None,
        }

        def _finalize() -> dict[str, Any]:
            """Schließt die Methode ab: berechnet Dauer + liefert Metriken."""
            metrics["execution_time_ms"] = round(
                (time.perf_counter() - start_time) * 1000.0, 3
            )
            return metrics

        if not segments:
            metrics["success"] = True
            metrics["fallback_reason"] = "no_segments"
            if debug_level >= 3:
                logger.debug(
                    "[CALLBACK] #%d kein Text – überspringe Callback",
                    chunk_id,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )
            return _finalize()

        if self._transcription_callback is None:
            metrics["success"] = True
            metrics["fallback_reason"] = "callback_none"
            if debug_level >= 2:
                logger.warning(
                    "[CALLBACK] #%d kein Transcription-Callback registriert",
                    chunk_id,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )
            return _finalize()

        if debug_level >= 3:
            logger.debug(
                "[CALLBACK] #%d enter (thread=%s, main=%s, segs=%d)",
                chunk_id,
                thread_name,
                is_main_thread,
                len(segments),
                extra={"component": "callback", "chunk_id": chunk_id},
            )

        callback_bound_to_gui = False
        callback_is_bound = hasattr(self._transcription_callback, "__self__")

        if callback_is_bound:
            bound_obj = getattr(self._transcription_callback, "__self__", None)
            if bound_obj is not None:
                callback_bound_to_gui = hasattr(bound_obj, "text_queue") or hasattr(
                    bound_obj, "_on_transcription_text"
                )
                if debug_level >= 3:
                    logger.debug(
                        "[CALLBACK] #%d gebunden an %s (GUI=%s)",
                        chunk_id,
                        type(bound_obj).__name__,
                        callback_bound_to_gui,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )
        else:
            if debug_level >= 2:
                logger.warning(
                    "[CALLBACK] #%d nicht gebunden (type=%s) – Reparaturversuch",
                    chunk_id,
                    type(self._transcription_callback).__name__,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )

        if not callback_bound_to_gui:
            gui = self._find_gui_root()
            if gui is not None and hasattr(gui, "_on_transcription_text"):
                self._transcription_callback = gui._on_transcription_text
                callback_bound_to_gui = True
                metrics["fallback_used"] = True
                metrics["fallback_reason"] = "callback_repaired_to_gui"
                metrics["dispatch_chain"].append("repair_to_gui")
                if debug_level >= 2:
                    logger.info(
                        "[CALLBACK] #%d ✅ Callback durch GUI-Methode ersetzt",
                        chunk_id,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )
            else:
                metrics["headless_mode"] = True
                if debug_level >= 2:
                    logger.debug(
                        "[CALLBACK] #%d headless – kein GUI-Root verfügbar",
                        chunk_id,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )

        metrics["callback_bound_to_gui"] = callback_bound_to_gui

        extraction_t0 = time.perf_counter()
        texts: list[str] = []

        for idx, seg in enumerate(segments):
            try:
                extracted = self._extract_text_from_segment(seg)
                if extracted and isinstance(extracted, str):
                    stripped = extracted.strip()
                    if len(stripped) >= MIN_TEXT_LENGTH:
                        texts.append(stripped)
            except Exception as e:
                metrics["extraction_errors"].append(f"seg{idx}: {e}")
                if debug_level >= 3:
                    logger.debug(
                        "[CALLBACK] #%d Segment %d Extraktionsfehler: %s",
                        chunk_id,
                        idx,
                        e,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )

        metrics["extraction_time_ms"] = round(
            (time.perf_counter() - extraction_t0) * 1000.0, 3
        )

        if not texts:
            metrics["success"] = True
            metrics["fallback_reason"] = "no_text"
            if debug_level >= 2:
                logger.debug(
                    "[CALLBACK] #%d kein Text in %d Segmenten",
                    chunk_id,
                    len(segments),
                    extra={"component": "callback", "chunk_id": chunk_id},
                )
            return _finalize()

        full_text = " ".join(texts).strip()
        if not full_text:
            metrics["fallback_reason"] = "empty_after_join"
            return _finalize()

        if len(full_text) > MAX_CALLBACK_TEXT_LENGTH:
            full_text = full_text[:MAX_CALLBACK_TEXT_LENGTH] + "…"
            metrics["was_truncated"] = True
            if debug_level >= 2:
                logger.warning(
                    "[CALLBACK] #%d Text auf %d Zeichen gekürzt",
                    chunk_id,
                    MAX_CALLBACK_TEXT_LENGTH,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )

        metrics["text_length"] = len(full_text)
        metrics["text_preview"] = full_text[:LOG_PREVIEW_LEN]

        _min_start: float | None = None
        _max_end: float | None = None
        _lang: str | None = None
        _conf: float | None = None
        for _seg in segments:
            try:
                _s = getattr(_seg, "start", None)
                _e = getattr(_seg, "end", None)
                if _s is not None:
                    _s_f = float(_s)
                    _min_start = _s_f if _min_start is None else min(_min_start, _s_f)
                if _e is not None:
                    _e_f = float(_e)
                    _max_end = _e_f if _max_end is None else max(_max_end, _e_f)
                if _lang is None:
                    _lang = getattr(_seg, "language", None) or getattr(
                        _seg, "lang", None
                    )
                if _conf is None:
                    _c = getattr(_seg, "confidence", None)
                    if isinstance(_c, (int, float)):
                        _conf = float(_c)
            except Exception:
                continue

        metrics["aggregated_start"] = _min_start
        metrics["aggregated_end"] = _max_end
        metrics["aggregated_lang"] = _lang

        _SegCls = self._get_callback_segment_class()
        callback_payload = _SegCls(
            full_text,
            start=_min_start if _min_start is not None else 0.0,
            end=_max_end if _max_end is not None else 0.0,
            language=_lang,
            confidence=_conf if _conf is not None else 1.0,
        )

        if not callable(self._transcription_callback):
            logger.error(
                "[CALLBACK] #%d Callback nicht aufrufbar (type=%s)",
                chunk_id,
                type(self._transcription_callback).__name__,
                extra={"component": "callback", "chunk_id": chunk_id},
            )
            metrics["callback_type"] = "not_callable"
            metrics["exception"] = (
                f"Not callable: {type(self._transcription_callback).__name__}"
            )
            return _finalize()

        invoke_t0 = time.perf_counter()
        success, error, chain, cb_type = self._dispatch_callback_with_fallback(
            callback_payload=callback_payload,
            chunk_id=chunk_id,
            is_main_thread=is_main_thread,
            debug_level=debug_level,
            logger=logger,
        )

        metrics["invoke_time_ms"] = round((time.perf_counter() - invoke_t0) * 1000.0, 3)
        metrics["success"] = success
        metrics["delivered"] = success
        metrics["callback_type"] = cb_type
        metrics["dispatch_chain"] = chain
        if error is not None:
            metrics["exception"] = str(error)
        if len(chain) > 1:
            metrics["fallback_used"] = True
            if metrics["fallback_reason"] is None:
                metrics["fallback_reason"] = f"chain={'>'.join(chain)}"

        if success:
            if getattr(self, "_enable_sentence_buffering", False):
                metrics["translation_triggered"] = False
                metrics["translation_skip_reason"] = "sentence_buffering_active"
                if debug_level >= 3:
                    logger.debug(
                        "[CALLBACK] #%d Callback-Übersetzung übersprungen – Sentence-Buffering aktiv",
                        chunk_id,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )
            else:
                try:
                    triggered, skip_reason, detected_lang = (
                        self._trigger_translation_for_callback(
                            full_text=full_text,
                            segments=segments,
                            chunk_id=chunk_id,
                            debug_level=debug_level,
                            logger=logger,
                        )
                    )
                    metrics["translation_triggered"] = triggered
                    metrics["translation_skip_reason"] = skip_reason
                    metrics["detected_language"] = detected_lang
                except Exception as e:
                    logger.warning(
                        "[CALLBACK] #%d Übersetzungs-Trigger-Exception: %s",
                        chunk_id,
                        e,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )
                    metrics["translation_skip_reason"] = f"exception: {e}"

        if debug_level >= 2:
            status = "✅ OK" if success else "❌ FAIL"
            fallback_info = f" via {'>'.join(chain)}" if chain else ""
            trans_info = (
                " [trans=✅]"
                if metrics["translation_triggered"]
                else (
                    f" [trans=⏭️ {metrics['translation_skip_reason']}]"
                    if metrics["translation_skip_reason"]
                    else ""
                )
            )
            logger.debug(
                "[CALLBACK] #%d %s (len=%d, t=%.1fms%s%s)",
                chunk_id,
                status,
                len(full_text),
                metrics["execution_time_ms"],
                fallback_info,
                trans_info,
                extra={"component": "callback", "chunk_id": chunk_id},
            )

        if success:
            bus = getattr(self, "_event_bus", None)
            if bus is not None:
                try:
                    bus.emit(
                        "transcription_callback_invoked",
                        {
                            "chunk_id": chunk_id,
                            "text_length": len(full_text),
                            "callback_type": metrics["callback_type"],
                            "fallback_used": metrics["fallback_used"],
                            "execution_time_ms": metrics["execution_time_ms"],
                            "dispatch_chain": chain,
                            "translation_triggered": metrics["translation_triggered"],
                            "detected_language": metrics["detected_language"],
                        },
                    )
                except Exception as e:
                    if debug_level >= 4:
                        logger.debug(
                            "[CALLBACK] #%d Event-Bus-Emission fehlgeschlagen: %s",
                            chunk_id,
                            e,
                            extra={"component": "callback", "chunk_id": chunk_id},
                        )

        return _finalize()

    def _get_callback_segment_class(self) -> type:
        """Liefert die (pro Klasse) gecachte `_CallbackSegment`-Klasse."""
        _SegCls = getattr(type(self), "_CachedCallbackSegment", None)
        if _SegCls is not None:
            return _SegCls

        import logging

        logger = logging.getLogger("dragon")

        class _CallbackSegment:
            """Robuster Wrapper um einen Transkriptions-String."""

            __slots__ = ("confidence", "end", "language", "start", "text")
            _delegation_count: int = 0
            _delegation_log_budget: int = 100
            _log_budget_used: int = 0

            @staticmethod
            def _diag_warning(msg: str) -> None:
                try:
                    if DEBUG_LEVEL >= 4:
                        logger.debug(f"[CallbackSegment] {msg}")
                except Exception:
                    pass

            @classmethod
            def _diag_delegation(cls, name: str) -> None:
                try:
                    if DEBUG_LEVEL < 5:
                        return
                    if cls._log_budget_used >= cls._delegation_log_budget:
                        return
                    cls._log_budget_used += 1
                    logger.debug(
                        f"[CallbackSegment] __getattr__ delegated: "
                        f"{name!r} (count={cls._delegation_count}, "
                        f"log={cls._log_budget_used}/"
                        f"{cls._delegation_log_budget})"
                    )
                except Exception:
                    pass

            @classmethod
            def _diag_increment(cls) -> None:
                with contextlib.suppress(Exception):
                    cls._delegation_count += 1

            def __init__(
                self,
                t: Any,
                start: float = 0.0,
                end: float = 0.0,
                language: str | None = None,
                confidence: float = 1.0,
            ) -> None:
                if t is None:
                    t = ""
                elif not isinstance(t, str):
                    try:
                        t = str(t)
                        _CallbackSegment._diag_warning(
                            f"nicht-str Typ {type(t).__name__} → str()"
                        )
                    except Exception:
                        t = ""
                object.__setattr__(self, "text", t)
                try:
                    object.__setattr__(
                        self,
                        "start",
                        float(start) if start is not None else 0.0,
                    )
                except (TypeError, ValueError):
                    object.__setattr__(self, "start", 0.0)
                try:
                    object.__setattr__(
                        self,
                        "end",
                        float(end) if end is not None else 0.0,
                    )
                except (TypeError, ValueError):
                    object.__setattr__(self, "end", 0.0)
                object.__setattr__(self, "language", language)
                try:
                    object.__setattr__(
                        self,
                        "confidence",
                        float(confidence) if confidence is not None else 1.0,
                    )
                except (TypeError, ValueError):
                    object.__setattr__(self, "confidence", 1.0)

            def __str__(self) -> str:
                return self.text

            def __repr__(self) -> str:
                return f"<CallbackSegment {self.text[:40]!r}>"

            def __len__(self) -> int:
                return len(self.text)

            def __copy__(self):
                return _CallbackSegment(
                    self.text,
                    self.start,
                    self.end,
                    self.language,
                    self.confidence,
                )

            def __deepcopy__(self, memo):
                return _CallbackSegment(
                    self.text,
                    self.start,
                    self.end,
                    self.language,
                    self.confidence,
                )

            def __reduce__(self):
                return (
                    _CallbackSegment,
                    (self.text, self.start, self.end, self.language, self.confidence),
                )

            def __bool__(self) -> bool:
                return bool(self.text)

            def __contains__(self, item) -> bool:
                return item in self.text

            def __iter__(self):
                return iter(self.text)

            def __getitem__(self, key):
                return self.text[key]

            def __eq__(self, other) -> bool:
                if isinstance(other, _CallbackSegment):
                    return self.text == other.text
                if isinstance(other, str):
                    return self.text == other
                return NotImplemented

            def __ne__(self, other) -> bool:
                result = self.__eq__(other)
                if result is NotImplemented:
                    return result
                return not result

            def __hash__(self) -> int:
                return hash(self.text)

            def __add__(self, other):
                if isinstance(other, _CallbackSegment):
                    return self.text + other.text
                if isinstance(other, str):
                    return self.text + other
                return NotImplemented

            def __radd__(self, other):
                if isinstance(other, str):
                    return other + self.text
                return NotImplemented

            def __mul__(self, n):
                if isinstance(n, int):
                    return self.text * n
                return NotImplemented

            def __rmul__(self, n):
                if isinstance(n, int):
                    return n * self.text
                return NotImplemented

            def __mod__(self, args):
                return self.text % args

            def __format__(self, spec: str) -> str:
                return format(self.text, spec)

            def __getattr__(self, name: str):
                """Delegiert String-Methoden an ``self.text``."""
                if name == "text":
                    raise AttributeError(name)
                try:
                    text = object.__getattribute__(self, "text")
                except AttributeError:
                    raise AttributeError(
                        f"'_CallbackSegment' object has no attribute "
                        f"'{name}' (object not fully initialized)"
                    ) from None
                attr = getattr(text, name, None)
                if attr is None:
                    raise AttributeError(
                        f"'_CallbackSegment' object has no attribute "
                        f"'{name}' (and 'str' has no such method either)"
                    )
                type(self)._diag_increment()
                type(self)._diag_delegation(name)
                return attr

        type(self)._CachedCallbackSegment = _CallbackSegment
        return _CallbackSegment

    def _dispatch_callback_with_fallback(
        self,
        callback_payload: Any,
        chunk_id: int,
        is_main_thread: bool,
        debug_level: int,
        logger: Any,
    ) -> tuple[bool, Exception | None, list[str], str | None]:
        """Führt den Transkriptions-Callback mit 4-stufiger Fallback-Kette aus."""
        chain: list[str] = []
        callback_error: Exception | None = None
        callback_type: str | None = None

        def _try_direct(label: str) -> bool:
            nonlocal callback_error
            chain.append(label)
            try:
                self._transcription_callback(callback_payload)
                return True
            except Exception as e:
                callback_error = e
                logger.error(
                    "[CALLBACK] #%d %s fehlgeschlagen: %s",
                    chunk_id,
                    label,
                    e,
                    exc_info=debug_level >= 3,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )
                return False

        success = False

        if is_main_thread:
            success = _try_direct("direct_main_thread")
            if success:
                callback_type = "direct_main_thread"
            return success, callback_error, chain, callback_type

        gui = self._find_gui_root()

        if gui is not None and hasattr(gui, "root"):
            try:
                root = gui.root
                if root is not None and hasattr(root, "tk") and root.tk:
                    root.after(
                        0,
                        lambda p=callback_payload, cid=chunk_id: (
                            self._safe_invoke_callback(p, cid)
                        ),
                    )
                    chain.append("after_planned")
                    success = True
                    callback_type = "after_planned"
            except Exception as e:
                if debug_level >= 3:
                    logger.debug(
                        "[CALLBACK] #%d Stufe 1 (after) fehlgeschlagen: %s",
                        chunk_id,
                        e,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )

        if not success and gui is not None:
            try:
                gq = getattr(gui, "gui_queue", None)
                if gq is not None:
                    gq.put_nowait(("append_transcription", callback_payload))
                    chain.append("gui_queue")
                    success = True
                    callback_type = "gui_queue"
            except Exception as e:
                if debug_level >= 3:
                    logger.debug(
                        "[CALLBACK] #%d Stufe 2 (gui_queue) fehlgeschlagen: %s",
                        chunk_id,
                        e,
                        extra={"component": "callback", "chunk_id": chunk_id},
                    )

        if not success:
            qm = getattr(self, "_queue_manager", None)
            if qm is not None and hasattr(qm, "safe_put"):
                try:
                    qm.safe_put(
                        "gui",
                        (
                            "callback",
                            self._safe_invoke_callback,
                            callback_payload,
                            chunk_id,
                        ),
                    )
                    chain.append("queue_manager")
                    success = True
                    callback_type = "queue_manager"
                except Exception as e:
                    if debug_level >= 3:
                        logger.debug(
                            "[CALLBACK] #%d Stufe 3 (QueueManager) fehlgeschlagen: %s",
                            chunk_id,
                            e,
                            extra={"component": "callback", "chunk_id": chunk_id},
                        )

        if not success:
            if debug_level >= 2:
                logger.warning(
                    "[CALLBACK] #%d alle GUI-Stufen fehlgeschlagen "
                    "– direkter Notfall-Aufruf",
                    chunk_id,
                    extra={"component": "callback", "chunk_id": chunk_id},
                )
            success = _try_direct("direct_emergency")
            if success:
                callback_type = "direct_emergency"

        return success, callback_error, chain, callback_type

    def _trigger_translation_for_callback(
        self,
        full_text: str,
        segments: list[TranscriptionResult],
        chunk_id: int,
        debug_level: int,
        logger: Any,
    ) -> tuple[bool, str | None, str | None]:
        """Löst die Übersetzung für einen Text aus – mit **Dedup-Schutz**."""
        import threading as _threading
        import time as _time

        if not full_text or not full_text.strip():
            return False, "empty_text", None

        detected_lang = "unknown"
        lang_weights: dict[str, float] = {}

        for seg in segments or []:
            lang = getattr(seg, "language", None)
            if lang and isinstance(lang, str) and lang.strip() and lang != "unknown":
                conf = getattr(seg, "confidence", 0.5)
                w = float(conf) if isinstance(conf, (int, float)) else 0.5
                w = max(0.0, min(1.0, w))
                lang_weights[lang] = lang_weights.get(lang, 0.0) + w

        if lang_weights:
            detected_lang = max(lang_weights, key=lang_weights.get)
        else:
            try:
                detected_lang = (
                    getattr(self.settings, "source_language", None) or "auto"
                )
            except Exception:
                detected_lang = "auto"

        seg_start: float | None = None
        seg_end: float | None = None
        if segments:
            s = getattr(segments[0], "start", None)
            e = getattr(segments[-1], "end", None)
            if isinstance(s, (int, float)):
                seg_start = float(s)
            if isinstance(e, (int, float)):
                seg_end = float(e)

        translation_engine = getattr(self, "translation_engine", None)
        translation_cb = getattr(self, "_translation_callback", None)
        translation_enabled = getattr(self, "_translation_enabled", None)
        translation_is_on = (
            translation_enabled is not None and translation_enabled.is_set()
        )

        if translation_engine is None:
            return False, "no_engine", detected_lang
        if translation_cb is None:
            return False, "no_callback", detected_lang
        if not callable(translation_cb):
            return False, "callback_not_callable", detected_lang
        if not translation_is_on:
            return False, "translation_disabled", detected_lang

        if not hasattr(self, "_translation_dedup_lock"):
            self._translation_dedup_lock = _threading.RLock()
        if not hasattr(self, "_recent_translation_triggers"):
            self._recent_translation_triggers: dict[int, float] = {}

        ttl = getattr(self, "_translation_dedup_ttl", 30.0)
        max_entries = getattr(self, "_translation_dedup_max", 500)

        try:
            text_hash = hash((full_text, len(segments) if segments else 0))
        except Exception:
            text_hash = hash(full_text)

        now = _time.monotonic()

        with self._translation_dedup_lock:
            if self._recent_translation_triggers:
                cutoff = now - ttl
                stale = [
                    h
                    for h, t in self._recent_translation_triggers.items()
                    if t < cutoff
                ]
                for h in stale:
                    self._recent_translation_triggers.pop(h, None)

            prev_ts = self._recent_translation_triggers.get(text_hash)
            if prev_ts is not None and (now - prev_ts) < ttl:
                if debug_level >= 3:
                    logger.debug(
                        "[TRANSLATE-TRIGGER] #%d Dedup: Text bereits "
                        "übersetzt vor %.2fs (hash=%d) – skip",
                        chunk_id,
                        now - prev_ts,
                        text_hash,
                        extra={"component": "translate_trigger", "chunk_id": chunk_id},
                    )
                return False, "duplicate_within_window", detected_lang

            if len(self._recent_translation_triggers) >= max_entries:
                try:
                    oldest = min(
                        self._recent_translation_triggers.items(),
                        key=lambda kv: kv[1],
                    )
                    self._recent_translation_triggers.pop(oldest[0], None)
                except Exception:
                    self._recent_translation_triggers.clear()

            self._recent_translation_triggers[text_hash] = now

        if debug_level >= 2:
            logger.debug(
                "[CALLBACK] #%d Übersetzung angefordert: "
                "lang=%s, len=%d, start=%s, end=%s",
                chunk_id,
                detected_lang,
                len(full_text),
                seg_start,
                seg_end,
                extra={"component": "callback", "chunk_id": chunk_id},
            )

        try:
            self._translate_and_send_async(
                full_text,
                detected_lang,
                translation_cb,
                start=seg_start,
                end=seg_end,
            )
            return True, None, detected_lang
        except Exception as e:
            logger.warning(
                "[CALLBACK] #%d _translate_and_send_async Exception: %s",
                chunk_id,
                e,
                extra={"component": "callback", "chunk_id": chunk_id},
            )
            try:
                with self._translation_dedup_lock:
                    self._recent_translation_triggers.pop(text_hash, None)
            except Exception:
                pass
            return False, f"exception: {e}", detected_lang

    def _safe_invoke_callback(self, text: str, chunk_id: int) -> None:
        """Sichere Ausführung des Transcription-Callbacks."""
        import contextlib
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if not text or not text.strip():
            return

        if self._transcription_callback is None:
            if debug_level >= 3:
                logger.debug(
                    f"[CALLBACK] Chunk #{chunk_id}: Callback ist None",
                    extra={"component": "callback"},
                )
            return

        if not callable(self._transcription_callback):
            logger.error(
                f"[CALLBACK] Chunk #{chunk_id}: Callback nicht aufrufbar: "
                f"{type(self._transcription_callback)}",
                extra={"component": "callback"},
            )
            return

        try:
            self._transcription_callback(text)

            if debug_level >= 4:
                logger.debug(
                    f"[CALLBACK] Chunk #{chunk_id}: ✅ Callback erfolgreich "
                    f"({len(text)} Zeichen)",
                    extra={"component": "callback"},
                )
        except Exception as e:
            logger.error(
                f"[CALLBACK] Chunk #{chunk_id}: ❌ Fehler im "
                f"Transcription-Callback: {e}",
                extra={"component": "callback"},
                exc_info=debug_level >= 3,
            )
            error_cb = getattr(self, "_error_callback", None)
            if error_cb is not None and callable(error_cb):
                with contextlib.suppress(Exception):
                    error_cb(f"Callback-Fehler in Chunk {chunk_id}: {e}")

    def _find_gui_root(self) -> Any:
        """🚀
        Versucht mit maximaler Intelligenz und unzähligen Fallbacks die
        GUI-Instanz zu finden, die den Tkinter-Root besitzt.

        """
        import contextlib
        import logging
        import sys
        import threading
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        call_id = f"findgui-{int(time.time() * 1000)}"
        if not hasattr(self, "_find_gui_stats"):
            self._find_gui_stats = {
                "total_calls": 0,
                "successful_calls": 0,
                "failed_calls": 0,
                "cache_hits": 0,
                "cache_misses": 0,
                "strategy_stats": {},
                "last_success_time": 0.0,
                "last_error": None,
                "avg_search_time": 0.0,
                "total_search_time": 0.0,
            }
        if not hasattr(self, "_find_gui_cache"):
            self._find_gui_cache = None
            self._find_gui_cache_time = 0.0
            self._find_gui_cache_ttl = 5.0
            self._find_gui_cache_lock = threading.RLock()

        stats = self._find_gui_stats
        stats["total_calls"] += 1
        start_time = time.perf_counter()
        search_time = 0.0
        found_gui = None
        used_strategy = None
        strategy_attempts = []

        with self._find_gui_cache_lock:
            if self._find_gui_cache is not None:
                cache_age = time.time() - self._find_gui_cache_time
                if cache_age < self._find_gui_cache_ttl:
                    try:
                        cached = self._find_gui_cache
                        if (
                            cached is not None
                            and hasattr(cached, "root")
                            and cached.root is not None
                        ):
                            try:
                                if cached.root.winfo_exists():
                                    stats["cache_hits"] += 1
                                    if debug_level >= 3:
                                        logger.debug(
                                            f"[{call_id}] ✅ GUI aus Cache (Alter: {cache_age:.1f}s) – root: {cached.root}",
                                        )
                                    return cached
                            except Exception as e:
                                if debug_level >= 4:
                                    logger.debug(
                                        f"[{call_id}] ⚠️ Cache-Validierung fehlgeschlagen: {e}",
                                    )
                    except Exception as e:
                        if debug_level >= 4:
                            logger.debug(f"[{call_id}] Cache-Ungültig: {e}")
                    self._find_gui_cache = None
                    self._find_gui_cache_time = 0.0
                elif debug_level >= 4:
                    logger.debug(
                        f"[{call_id}] Cache abgelaufen (Alter: {cache_age:.1f}s)"
                    )

        def _log_strategy(strategy: str, level: int, msg: str, *args, **kwargs) -> None:
            if level <= debug_level:
                logger.debug(f"[{call_id}][STRATEGY:{strategy}] {msg}", *args, **kwargs)

        def _record_attempt(
            strategy: str, success: bool, duration: float, details: str = ""
        ) -> None:
            attempt = {
                "strategy": strategy,
                "success": success,
                "duration": duration,
                "details": details,
            }
            strategy_attempts.append(attempt)
            if strategy not in stats["strategy_stats"]:
                stats["strategy_stats"][strategy] = {
                    "attempts": 0,
                    "successes": 0,
                    "failures": 0,
                    "total_time": 0.0,
                }
            s = stats["strategy_stats"][strategy]
            s["attempts"] += 1
            if success:
                s["successes"] += 1
            else:
                s["failures"] += 1
            s["total_time"] += duration

        def goto_cache_and_return():
            """Interne Funktion, die Cache setzt und Metriken aktualisiert."""
            nonlocal search_time, used_strategy, found_gui
            if found_gui is not None:
                with self._find_gui_cache_lock:
                    self._find_gui_cache = found_gui
                    self._find_gui_cache_time = time.time()
                    if debug_level >= 3:
                        logger.debug(
                            f"[{call_id}] 💾 GUI im Cache gespeichert (TTL: {self._find_gui_cache_ttl}s)"
                        )
            search_time = time.perf_counter() - start_time
            stats["total_search_time"] += search_time
            stats["avg_search_time"] = stats["total_search_time"] / stats["total_calls"]
            if found_gui is not None:
                stats["successful_calls"] += 1
                stats["last_success_time"] = time.time()
                stats["last_error"] = None
                if debug_level >= 2:
                    logger.debug(
                        f"[{call_id}] ✅ GUI gefunden via '{used_strategy}' in {search_time * 1000:.1f}ms",
                    )
                if debug_level >= 3:
                    logger.debug(
                        f"[{call_id}] 📊 GUI: {type(found_gui).__name__}, "
                        f"root: {found_gui.root if hasattr(found_gui, 'root') else 'None'}, "
                        f"has _on_transcription_text: {hasattr(found_gui, '_on_transcription_text')}",
                    )
                    if hasattr(found_gui, "root"):
                        with contextlib.suppress(Exception):
                            logger.debug(
                                f"[{call_id}] 📊 root.winfo_exists(): {found_gui.root.winfo_exists()}",
                            )
                return found_gui
            stats["failed_calls"] += 1
            if debug_level >= 2:
                logger.warning(
                    f"[{call_id}] ❌ KEINE GUI gefunden – alle Strategien fehlgeschlagen in {search_time * 1000:.1f}ms",
                )
            if debug_level >= 3:
                for attempt in strategy_attempts:
                    logger.debug(
                        f"[{call_id}]   Versuch: {attempt['strategy']} – "
                        f"{'✅ Erfolg' if attempt['success'] else '❌ Fehlschlag'} "
                        f"({attempt['duration'] * 1000:.1f}ms)"
                        + (f" – {attempt['details']}" if attempt["details"] else ""),
                    )
            return None

        strategy_start = time.perf_counter()
        try:
            if hasattr(self, "controller_ref") and self.controller_ref is not None:
                gui = getattr(self.controller_ref, "gui", None)
                if gui is not None and hasattr(gui, "root") and gui.root is not None:
                    try:
                        if gui.root.winfo_exists():
                            found_gui = gui
                            used_strategy = "controller_ref.gui"
                            _log_strategy(used_strategy, 3, "✅ Erfolg")
                            _record_attempt(
                                used_strategy,
                                True,
                                time.perf_counter() - strategy_start,
                            )
                            goto_cache_and_return()
                        else:
                            _log_strategy(
                                "controller_ref.gui",
                                4,
                                "root existiert nicht (winfo_exists False)",
                            )
                    except Exception as e:
                        _log_strategy(
                            "controller_ref.gui",
                            4,
                            f"root-Validierung fehlgeschlagen: {e}",
                        )
                else:
                    _log_strategy(
                        "controller_ref.gui", 4, "gui nicht verfügbar oder root None"
                    )
            else:
                _log_strategy("controller_ref.gui", 4, "controller_ref nicht vorhanden")
        except Exception as e:
            _log_strategy("controller_ref.gui", 4, f"Fehler: {e}")
        _record_attempt(
            "controller_ref.gui", False, time.perf_counter() - strategy_start
        )

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                if hasattr(self, "_gui") and self._gui is not None:
                    gui = self._gui
                    if hasattr(gui, "root") and gui.root is not None:
                        try:
                            if gui.root.winfo_exists():
                                found_gui = gui
                                used_strategy = "_gui"
                                _log_strategy(used_strategy, 3, "✅ Erfolg")
                                _record_attempt(
                                    used_strategy,
                                    True,
                                    time.perf_counter() - strategy_start,
                                )
                                goto_cache_and_return()
                            else:
                                _log_strategy("_gui", 4, "root existiert nicht")
                        except Exception as e:
                            _log_strategy(
                                "_gui", 4, f"root-Validierung fehlgeschlagen: {e}"
                            )
                    else:
                        _log_strategy("_gui", 4, "_gui vorhanden, aber root ungültig")
                else:
                    _log_strategy("_gui", 4, "_gui nicht vorhanden")
            except Exception as e:
                _log_strategy("_gui", 4, f"Fehler: {e}")
            _record_attempt("_gui", False, time.perf_counter() - strategy_start)

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                from .app_context import AppContext

                ctx = AppContext.get_instance()
                if ctx is not None:
                    gui = getattr(ctx, "gui", None)
                    if (
                        gui is not None
                        and hasattr(gui, "root")
                        and gui.root is not None
                    ):
                        try:
                            if gui.root.winfo_exists():
                                found_gui = gui
                                used_strategy = "AppContext"
                                _log_strategy(used_strategy, 3, "✅ Erfolg")
                                _record_attempt(
                                    used_strategy,
                                    True,
                                    time.perf_counter() - strategy_start,
                                )
                                goto_cache_and_return()
                            else:
                                _log_strategy("AppContext", 4, "root existiert nicht")
                        except Exception as e:
                            _log_strategy(
                                "AppContext", 4, f"root-Validierung fehlgeschlagen: {e}"
                            )
                    else:
                        _log_strategy(
                            "AppContext", 4, "gui nicht verfügbar oder root None"
                        )
                else:
                    _log_strategy("AppContext", 4, "AppContext.get_instance() gab None")
            except ImportError:
                _log_strategy("AppContext", 4, "Modul .app_context nicht importierbar")
            except Exception as e:
                _log_strategy("AppContext", 4, f"Fehler: {e}")
            _record_attempt("AppContext", False, time.perf_counter() - strategy_start)

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                main_module = sys.modules.get("__main__")
                if main_module is not None:
                    registered = getattr(main_module, "_DRAGON_GUI_INSTANCE", None)
                    if registered is not None:
                        _log_strategy(
                            "__main__._DRAGON_GUI_INSTANCE",
                            4,
                            f"Registrierte GUI gefunden: {type(registered).__name__}",
                        )
                        if (
                            hasattr(registered, "root")
                            and hasattr(registered, "_on_transcription_text")
                            and registered.root is not None
                        ):
                            try:
                                if registered.root.winfo_exists():
                                    found_gui = registered
                                    used_strategy = "__main__._DRAGON_GUI_INSTANCE"
                                    _log_strategy(used_strategy, 3, "✅ Erfolg")
                                    _record_attempt(
                                        used_strategy,
                                        True,
                                        time.perf_counter() - strategy_start,
                                    )
                                    goto_cache_and_return()
                            except Exception as e:
                                _log_strategy(
                                    "__main__._DRAGON_GUI_INSTANCE",
                                    4,
                                    f"root-Validierung fehlgeschlagen: {e}",
                                )
            except Exception as e:
                _log_strategy("__main__._DRAGON_GUI_INSTANCE", 4, f"Fehler: {e}")
            _record_attempt(
                "__main__._DRAGON_GUI_INSTANCE",
                False,
                time.perf_counter() - strategy_start,
            )

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                import tkinter as tk

                root = tk._default_root
                if root is not None:
                    _log_strategy("Tkinter", 4, f"default_root gefunden: {root}")
                    for child in root.winfo_children():
                        if hasattr(child, "gui") and hasattr(child.gui, "root"):
                            gui = child.gui
                            if gui.root is not None:
                                try:
                                    if gui.root.winfo_exists():
                                        found_gui = gui
                                        used_strategy = "Tkinter.gui"
                                        _log_strategy(used_strategy, 3, "✅ Erfolg")
                                        _record_attempt(
                                            used_strategy,
                                            True,
                                            time.perf_counter() - strategy_start,
                                        )
                                        goto_cache_and_return()
                                    else:
                                        _log_strategy(
                                            "Tkinter.gui", 4, "root existiert nicht"
                                        )
                                except Exception as e:
                                    _log_strategy(
                                        "Tkinter.gui",
                                        4,
                                        f"root-Validierung fehlgeschlagen: {e}",
                                    )
                        if hasattr(child, "_on_transcription_text") and hasattr(
                            child, "root"
                        ):
                            gui = child
                            if gui.root is not None:
                                try:
                                    if gui.root.winfo_exists():
                                        found_gui = gui
                                        used_strategy = "Tkinter.method"
                                        _log_strategy(used_strategy, 3, "✅ Erfolg")
                                        _record_attempt(
                                            used_strategy,
                                            True,
                                            time.perf_counter() - strategy_start,
                                        )
                                        goto_cache_and_return()
                                    else:
                                        _log_strategy(
                                            "Tkinter.method", 4, "root existiert nicht"
                                        )
                                except Exception as e:
                                    _log_strategy(
                                        "Tkinter.method",
                                        4,
                                        f"root-Validierung fehlgeschlagen: {e}",
                                    )
                    if hasattr(root, "_on_transcription_text") and hasattr(
                        root, "root"
                    ):
                        gui = root
                        try:
                            if gui.root is not None and gui.root.winfo_exists():
                                found_gui = gui
                                used_strategy = "Tkinter.root"
                                _log_strategy(used_strategy, 3, "✅ Erfolg")
                                _record_attempt(
                                    used_strategy,
                                    True,
                                    time.perf_counter() - strategy_start,
                                )
                                goto_cache_and_return()
                        except Exception as e:
                            _log_strategy(
                                "Tkinter.root",
                                4,
                                f"root-Validierung fehlgeschlagen: {e}",
                            )
                else:
                    _log_strategy("Tkinter", 4, "tk._default_root ist None")
            except ImportError:
                _log_strategy("Tkinter", 4, "tkinter nicht verfügbar")
            except Exception as e:
                _log_strategy("Tkinter", 4, f"Fehler: {e}")
            _record_attempt("Tkinter", False, time.perf_counter() - strategy_start)

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                main_module = sys.modules.get("__main__", {})
                for key, value in main_module.__dict__.items():
                    if hasattr(value, "root") and hasattr(
                        value, "_on_transcription_text"
                    ):
                        if value.root is not None:
                            try:
                                if value.root.winfo_exists():
                                    found_gui = value
                                    used_strategy = f"__main__.{key}"
                                    _log_strategy(
                                        used_strategy, 3, f"✅ Erfolg via {key}"
                                    )
                                    _record_attempt(
                                        used_strategy,
                                        True,
                                        time.perf_counter() - strategy_start,
                                    )
                                    goto_cache_and_return()
                                else:
                                    _log_strategy(
                                        f"__main__.{key}", 4, "root existiert nicht"
                                    )
                            except Exception as e:
                                _log_strategy(
                                    f"__main__.{key}",
                                    4,
                                    f"root-Validierung fehlgeschlagen: {e}",
                                )
                gui = main_module.__dict__.get("gui")
                if gui is not None and hasattr(gui, "root") and gui.root is not None:
                    try:
                        if gui.root.winfo_exists():
                            found_gui = gui
                            used_strategy = "__main__.gui"
                            _log_strategy(used_strategy, 3, "✅ Erfolg")
                            _record_attempt(
                                used_strategy,
                                True,
                                time.perf_counter() - strategy_start,
                            )
                            goto_cache_and_return()
                    except Exception as e:
                        _log_strategy(
                            "__main__.gui", 4, f"root-Validierung fehlgeschlagen: {e}"
                        )
            except Exception as e:
                _log_strategy("__main__", 4, f"Fehler: {e}")
            _record_attempt("__main__", False, time.perf_counter() - strategy_start)

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                if hasattr(self, "gui") and self.gui is not None:
                    gui = self.gui
                    if hasattr(gui, "root") and gui.root is not None:
                        try:
                            if gui.root.winfo_exists():
                                found_gui = gui
                                used_strategy = "self.gui"
                                _log_strategy(used_strategy, 3, "✅ Erfolg")
                                _record_attempt(
                                    used_strategy,
                                    True,
                                    time.perf_counter() - strategy_start,
                                )
                                goto_cache_and_return()
                            else:
                                _log_strategy("self.gui", 4, "root existiert nicht")
                        except Exception as e:
                            _log_strategy(
                                "self.gui", 4, f"root-Validierung fehlgeschlagen: {e}"
                            )
                    else:
                        _log_strategy(
                            "self.gui", 4, "gui vorhanden, aber root ungültig"
                        )
                else:
                    _log_strategy("self.gui", 4, "self.gui nicht vorhanden")
            except Exception as e:
                _log_strategy("self.gui", 4, f"Fehler: {e}")
            _record_attempt("self.gui", False, time.perf_counter() - strategy_start)

        if found_gui is None:
            strategy_start = time.perf_counter()
            try:
                if hasattr(self, "_gui_weak_refs") and self._gui_weak_refs:
                    for ref in self._gui_weak_refs:
                        gui = ref()
                        if (
                            gui is not None
                            and hasattr(gui, "root")
                            and gui.root is not None
                        ):
                            try:
                                if gui.root.winfo_exists():
                                    found_gui = gui
                                    used_strategy = "weakrefs"
                                    _log_strategy(used_strategy, 3, "✅ Erfolg")
                                    _record_attempt(
                                        used_strategy,
                                        True,
                                        time.perf_counter() - strategy_start,
                                    )
                                    goto_cache_and_return()
                            except Exception as e:
                                _log_strategy(
                                    "weakrefs",
                                    4,
                                    f"root-Validierung fehlgeschlagen: {e}",
                                )
                else:
                    _log_strategy("weakrefs", 4, "Keine WeakRefs registriert")
            except Exception as e:
                _log_strategy("weakrefs", 4, f"Fehler: {e}")
            _record_attempt("weakrefs", False, time.perf_counter() - strategy_start)

        return goto_cache_and_return()

    def _extract_text_from_segment(self, segment) -> str | None:
        """Extrahiert Text aus einem Segment, unabhängig vom Typ."""
        if segment is None:
            return None

        if isinstance(segment, str):
            return segment.strip() if segment.strip() else None

        if hasattr(segment, "text"):
            text = segment.text
            if text and isinstance(text, str):
                return text.strip()

        if hasattr(segment, "get_text") and callable(segment.get_text):
            try:
                text = segment.get_text()
                if text and isinstance(text, str):
                    return text.strip()
            except Exception:
                pass

        if isinstance(segment, dict):
            for key in ("text", "transcription", "content", "message"):
                if key in segment:
                    text = segment[key]
                    if text and isinstance(text, str):
                        return text.strip()

        if hasattr(segment, "content"):
            text = segment.content
            if text and isinstance(text, str):
                return text.strip()

        try:
            text = str(segment)
            if text and text not in ("None", "[]", "{}", "()") and len(text) < 1000:
                return text.strip()
        except Exception:
            pass

        return None

    def _validate_and_clean_segments(
        self,
        chunk_id: int,
        segments: list[TranscriptionResult],
        trans_engine: TranscriptionEngine,
    ) -> list[TranscriptionResult]:
        """Validiert und bereinigt Transkriptionssegmente (Anti‑Halluzination & Qualitätsfilter)."""
        if not segments:
            return []

        settings = getattr(self, "settings", None)
        if settings is not None:
            no_speech_threshold = getattr(settings, "no_speech_threshold", 0.6)
            log_prob_threshold = getattr(settings, "log_prob_threshold", -1.0)
            min_text_length = getattr(settings, "min_segment_text_length", 2)
            min_confidence = getattr(settings, "min_confidence", 0.1)

            min_confidence_short = getattr(settings, "min_confidence_short_text", 0.25)
        else:
            no_speech_threshold = 0.6
            log_prob_threshold = -1.0
            min_text_length = 2
            min_confidence = 0.1
            min_confidence_short = 0.25

        asian_langs = {"zh", "ja", "ko", "th", "vi", "yue", "lo", "km", "my"}

        def is_asian_language(lang: str) -> bool:
            return lang in asian_langs

        valid_segments: list[TranscriptionResult] = []
        discarded_count = 0
        total_segments = len(segments)
        short_discarded = 0

        for idx, seg in enumerate(segments):
            if seg is None:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        f"Chunk #{chunk_id}: Segment {idx} ist None – übersprungen",
                    )
                discarded_count += 1
                continue

            text = getattr(seg, "text", None)
            if not isinstance(text, str) or not text.strip():
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "validate",
                        f"Chunk #{chunk_id} seg {idx}: kein gültiger Text – verworfen",
                    )
                discarded_count += 1
                continue

            clean_text = text.strip()
            if len(clean_text) < min_text_length:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "validate",
                        f"Chunk #{chunk_id} seg {idx}: Text zu kurz ({
                            len(clean_text)
                        } < {min_text_length}) – verworfen",
                    )
                discarded_count += 1
                continue

            conf = getattr(seg, "confidence", 0.0)
            if not isinstance(conf, (int, float)):
                conf = 0.0
            language = getattr(seg, "language", "unknown")

            effective_min_conf = (
                min_confidence * 0.7 if is_asian_language(language) else min_confidence
            )

            if conf < effective_min_conf:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "validate",
                        f"Chunk #{chunk_id} seg {idx}: Konfidenz {conf:.2f} < {
                            effective_min_conf:.2f} – verworfen",
                    )
                discarded_count += 1
                continue

            no_speech = getattr(seg, "no_speech_prob", None)
            avg_log = getattr(seg, "avg_logprob", None)

            if no_speech is not None and avg_log is not None:
                effective_log_threshold = (
                    log_prob_threshold * 0.8
                    if is_asian_language(language)
                    else log_prob_threshold
                )

                if (
                    no_speech > no_speech_threshold
                    and avg_log < effective_log_threshold
                ):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "hallucination",
                            f"Chunk #{chunk_id} seg {idx}: verworfen (no_speech={
                                no_speech:.2f} > {no_speech_threshold:.2f}, avg_log={
                                avg_log:.2f} < {effective_log_threshold:.2f})",
                        )
                    discarded_count += 1
                    continue

            words = clean_text.split()
            word_count = len(words)

            if word_count <= 2:
                if conf < min_confidence_short:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "validate_short",
                            f"Chunk #{chunk_id} seg {idx}: kurzes Segment ({
                                word_count
                            } Wort(e), conf={conf:.2f} < {
                                min_confidence_short:.2f}) – verworfen",
                        )
                    short_discarded += 1
                    discarded_count += 1
                    continue

                if not any(c.isalpha() for c in clean_text):
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "validate_short",
                            f"Chunk #{chunk_id} seg {idx}: kurzes Segment ohne Buchstaben – verworfen",
                        )
                    short_discarded += 1
                    discarded_count += 1
                    continue

            valid_segments.append(seg)

        if discarded_count > 0 and DEBUG_LEVEL >= 2:
            log_debug(
                "validate",
                f"Chunk #{chunk_id}: {discarded_count} von {total_segments} Segment(en) verworfen "
                f"(davon {short_discarded} kurze Segmente) – valid: {len(valid_segments)}",
            )

        return valid_segments

    def _dispatch_segments(
        self,
        chunk_id: int,
        segments: list[TranscriptionResult],
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
    ) -> None:
        """Verteilt die validierten Segmente an die entsprechenden Ausgabepfade.
        Optimiert mit konsistentem Logging, Callback-Prüfungen und besseren Debug-Möglichkeiten.
        """
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 1:
            logger.debug(
                f"[DISPATCH] ENTRY Chunk {chunk_id}: {len(segments) if segments else 0} Segmente empfangen",
            )

        if not segments:
            if debug_level >= 3:
                logger.debug(f"[DISPATCH] Chunk {chunk_id}: leere Segmentliste")
            return

        if not callable(transcription_callback):
            logger.error(
                f"[DISPATCH] Chunk {chunk_id}: transcription_callback ist NICHT aufrufbar: {transcription_callback}",
            )
            return

        if translation_callback is not None and not callable(translation_callback):
            logger.error(
                f"[DISPATCH] Chunk {chunk_id}: translation_callback ist NICHT aufrufbar: {translation_callback}",
            )

        clean_segments = [
            seg
            for seg in segments
            if seg is not None
            and hasattr(seg, "text")
            and isinstance(seg.text, str)
            and seg.text.strip()
        ]

        if not clean_segments:
            if debug_level >= 3:
                logger.debug(
                    f"[DISPATCH] Chunk {chunk_id}: keine gültigen Segmente nach Filterung",
                )
            return

        unique_segments = self._filter_duplicate_segments(clean_segments)
        if not unique_segments:
            if debug_level >= 3:
                logger.debug(
                    f"[DISPATCH] Chunk {chunk_id}: alle Segmente als Duplikate verworfen",
                )
            return

        if debug_level >= 3:
            logger.debug(
                f"[DISPATCH] Chunk {chunk_id}: {len(unique_segments)} unique segments",
            )

        effective_engine = self._get_effective_translation_engine()
        translation_possible = (
            translation_callback is not None
            and callable(translation_callback)
            and effective_engine is not None
            and self._translation_enabled.is_set()
        )

        if not translation_possible and debug_level >= 3:
            logger.debug(
                f"[DISPATCH] Chunk {chunk_id}: Übersetzung nicht möglich – "
                f"callback={translation_callback is not None}, "
                f"callable={callable(translation_callback) if translation_callback is not None else False}, "
                f"engine={effective_engine is not None}, "
                f"enabled={self._translation_enabled.is_set()}",
            )

        if debug_level >= 2:
            gui_queue = getattr(self, "gui_queue", None)
            if gui_queue is not None:
                try:
                    qsize = gui_queue.qsize()
                    logger.debug(
                        f"[DISPATCH] Chunk {chunk_id}: GUI-Queue-Größe vor Verarbeitung: {qsize}",
                    )
                except Exception:
                    pass
            else:
                logger.warning(f"[DISPATCH] Chunk {chunk_id}: GUI-Queue ist None!")

        try:
            if self.subtitle_mode:
                if debug_level >= 3:
                    logger.debug(
                        f"[DISPATCH] Chunk {chunk_id}: Subtitle-Modus – {len(unique_segments)} Segmente gepuffert",
                    )
                self._buffer_and_flush_segments(
                    unique_segments,
                    transcription_callback,
                    translation_callback if translation_possible else None,
                )
            elif self._enable_sentence_buffering:
                if debug_level >= 3:
                    logger.debug(
                        f"[DISPATCH] Chunk {chunk_id}: Sentence-Buffering – {len(unique_segments)} Segmente eingereiht",
                    )
                self._enqueue_transcript_segments(
                    unique_segments,
                    transcription_callback,
                    translation_callback if translation_possible else None,
                )
            else:
                if debug_level >= 3:
                    logger.debug(
                        f"[DISPATCH] Chunk {chunk_id}: Normal-Modus – {len(unique_segments)} Segmente direkt ausgegeben",
                    )
                self._emit_segments_directly(
                    unique_segments,
                    transcription_callback,
                    translation_callback if translation_possible else None,
                )

            if debug_level >= 2:
                logger.debug(
                    f"[DISPATCH] Chunk {chunk_id}: Ausgabe erfolgreich ({len(unique_segments)} Segmente)",
                )

        except Exception as e:
            logger.error(
                f"[DISPATCH] Chunk {chunk_id}: Fehler in der Ausgabeverarbeitung: {e}",
                exc_info=(debug_level >= 3),
            )

            if debug_level >= 2:
                logger.debug(
                    f"[DISPATCH] Chunk {chunk_id}: Fallback – direkte Ausgabe nach Fehler",
                )

            emitted_count = 0
            for seg in unique_segments:
                try:
                    if transcription_callback and callable(transcription_callback):
                        transcription_callback(seg)
                        emitted_count += 1
                    else:
                        logger.error(
                            f"[DISPATCH] Fallback: transcription_callback nicht aufrufbar für Chunk {chunk_id}",
                        )

                    if (
                        translation_callback
                        and translation_possible
                        and callable(translation_callback)
                    ):
                        self._translate_and_send_async(
                            seg.text,
                            seg.language,
                            translation_callback,
                            start=seg.start,
                            end=seg.end,
                        )
                except Exception as cb_err:
                    logger.error(
                        f"[DISPATCH] Fallback-Callback Fehler für Chunk {chunk_id}: {cb_err}",
                        exc_info=(debug_level >= 3),
                    )

            if debug_level >= 2:
                logger.debug(
                    f"[DISPATCH] Chunk {chunk_id}: Fallback {emitted_count}/{len(unique_segments)} Segmente ausgegeben",
                )

        if debug_level >= 3:
            gui_queue = getattr(self, "gui_queue", None)
            if gui_queue is not None:
                try:
                    qsize = gui_queue.qsize()
                    logger.debug(
                        f"[DISPATCH] Chunk {chunk_id}: GUI-Queue-Größe nach Verarbeitung: {qsize}",
                    )
                except Exception:
                    pass

        if debug_level >= 2:
            logger.debug(
                f"[DISPATCH] Chunk {chunk_id}: EXIT – {len(unique_segments) if unique_segments else 0} Segmente verarbeitet",
            )

    def _dispatch_subtitle_mode(
        self,
        chunk_id: int,
        segments: list[TranscriptionResult],
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
    ) -> None:
        """Verarbeitet Segmente im Subtitle‑Modus (chronologisch)."""
        logger.info(
            ">>> _dispatch_subtitle_mode ENTER: chunk_id=%d, segments=%d",
            chunk_id,
            len(segments) if segments else 0,
        )

        if not segments:
            if "subtitle" in DEBUG_COMPONENTS:
                log_debug(
                    "subtitle",
                    f"Chunk #{chunk_id}: leere Segmentliste – übersprungen",
                )
            logger.info(">>> _dispatch_subtitle_mode: segments is empty – returning")
            return

        if transcription_callback is None:
            logger.error(">>> _dispatch_subtitle_mode: transcription_callback is None!")
            return

        clean_segments: list[TranscriptionResult] = []
        for seg in segments:
            if seg is None:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "subtitle",
                        f"Chunk #{chunk_id}: None‑Segment übersprungen",
                    )
                continue
            text = getattr(seg, "text", "")
            if not text or not isinstance(text, str) or not text.strip():
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "subtitle",
                        f"Chunk #{chunk_id}: Segment ohne Text übersprungen",
                    )
                continue

            start = getattr(seg, "start", None)
            end = getattr(seg, "end", None)
            if start is None or end is None:
                logger.warning(
                    f"Chunk #{chunk_id}: Segment ohne Zeitstempel – Übersetzung übersprungen",
                )

            elif end <= start:
                logger.warning(
                    f"Chunk #{chunk_id}: ungültige Zeitstempel (end <= start) – korrigiert",
                )
                seg.end = start + 0.001
            clean_segments.append(seg)

        if not clean_segments:
            logger.info(
                ">>> _dispatch_subtitle_mode: no valid segments after filtering",
            )
            return

        sorted_segments = sorted(
            clean_segments,
            key=lambda s: s.start if s.start is not None else float("inf"),
        )

        logger.info(
            ">>> _dispatch_subtitle_mode: %d segments after sorting",
            len(sorted_segments),
        )

        unique_segments: list[TranscriptionResult] = []
        last_end = -1.0
        tolerance = 0.1

        for seg in sorted_segments:
            start = seg.start if seg.start is not None else 0.0
            end = seg.end if seg.end is not None else start + 0.001

            if last_end >= 0.0 and start <= last_end + tolerance:
                if self._is_duplicate_text(seg.text):
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "subtitle",
                            f"Chunk #{chunk_id}: Duplikat übersprungen: '{seg.text[:50]}...'",
                        )
                    continue
                if unique_segments:
                    last_seg = unique_segments[-1]
                    last_seg.text += " " + seg.text
                    last_seg.end = max(last_seg.end, end)
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "subtitle",
                            f"Chunk #{chunk_id}: Segment zusammengeführt: end={
                                last_seg.end:.2f}",
                        )
                    continue

            unique_segments.append(seg)
            last_end = end

        logger.info(
            ">>> _dispatch_subtitle_mode: %d unique segments after duplicate check",
            len(unique_segments),
        )

        if not unique_segments:
            logger.info(
                ">>> _dispatch_subtitle_mode: all segments filtered as duplicates",
            )
            return

        MAX_SEGMENTS_PER_CALLBACK = 50
        sent = 0
        segments_to_send = unique_segments[:MAX_SEGMENTS_PER_CALLBACK]

        for seg in segments_to_send:
            try:
                if callable(transcription_callback):
                    transcription_callback(seg)
                    sent += 1
            except Exception as e:
                logger.error(
                    f"Chunk #{chunk_id}: Fehler beim Transkriptions-Callback: {e}",
                )

        if self.settings.config.ENABLE_TIMED_TRANSCRIPTIONS:
            try:
                with self._subtitle_lock:
                    self._timed_transcriptions.extend(segments_to_send)
                    if len(self._timed_transcriptions) > 10000:
                        self._timed_transcriptions = deque(
                            list(self._timed_transcriptions)[-5000:],
                            maxlen=10000,
                        )
                        logger.info(
                            f"Chunk #{chunk_id}: _timed_transcriptions auf 5000 Einträge begrenzt",
                        )
            except Exception as e:
                logger.error(
                    f"Chunk #{chunk_id}: Fehler beim Speichern der Untertitel: {e}",
                )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "subtitle",
                f"Chunk #{chunk_id}: {sent} Segment(e) im Subtitle‑Modus gesendet",
            )

        if (
            translation_callback is not None
            and self.translation_engine
            and self._translation_enabled.is_set()
        ):
            logger.info(
                ">>> _dispatch_subtitle_mode: triggering translations for %d segments",
                len(segments_to_send),
            )
            translated_count = 0
            for seg in segments_to_send:
                try:
                    text = getattr(seg, "text", "")
                    if text and len(text) > 1:
                        self._translate_and_send_async(
                            text,
                            getattr(seg, "language", "unknown"),
                            translation_callback,
                            start=seg.start,
                            end=seg.end,
                        )
                        translated_count += 1
                except Exception as e:
                    logger.error(
                        f"Chunk #{chunk_id}: Fehler beim Anstoßen der Übersetzung: {e}",
                    )

            logger.info(
                ">>> _dispatch_subtitle_mode: %d translations triggered",
                translated_count,
            )

        logger.info(
            ">>> _dispatch_subtitle_mode EXIT: chunk_id=%d, sent=%d, translations_triggered=%d",
            chunk_id,
            sent,
            (
                translated_count
                if translation_callback and self._translation_enabled.is_set()
                else 0
            ),
        )

    def _dispatch_sentence_buffering(
        self,
        chunk_id: int,
        segments: list[TranscriptionResult],
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
    ) -> None:
        """Verarbeitet Segmente mit Satzpufferung (Übersetzung)."""
        for seg in segments:
            self._handle_transcript_segment(
                seg,
                transcription_callback,
                translation_callback,
            )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "sentence",
                f"Chunk #{chunk_id}: {
                    len(segments)
                } Segment(e) im Satzpuffer verarbeitet",
            )

    def _dispatch_normal_mode(
        self,
        chunk_id: int,
        segments: list[TranscriptionResult],
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
    ) -> None:
        """Verarbeitet Segmente im Normal‑Modus (direkte Ausgabe)."""
        trans_engine = self.translation_engine
        trans_enabled = self._translation_enabled.is_set()
        do_translate = trans_engine is not None and trans_enabled
        for seg in segments:
            if callable(transcription_callback):
                transcription_callback(seg)

            if do_translate and seg.text and len(seg.text) > 1:
                self._translate_and_send_async(
                    seg.text,
                    seg.language,
                    translation_callback,
                    start=seg.start,
                    end=seg.end,
                )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "normal",
                f"Chunk #{chunk_id}: {
                    len(segments)
                } Segment(e) im Normal‑Modus gesendet",
            )

    def _emit_segments_directly(
        self,
        segments: list[TranscriptionResult],
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        *,
        batch_size: int = 5,
        fallback_to_gui_queue: bool = True,
        max_segments_per_call: int = 50,
    ) -> None:
        """Gibt Segmente im Normal‑Modus aus (mit Batch‑Verarbeitung)."""
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        is_verbose = debug_level >= 3 or "emit" in getattr(self, "debug_components", [])

        if not segments:
            if is_verbose:
                logger.debug("[EMIT] Leere Segmentliste – überspringe")
            return

        if not callable(trans_cb):
            logger.error(
                "[EMIT] ❌ trans_cb ist nicht aufrufbar – Übersetzung wird deaktiviert",
            )
            if fallback_to_gui_queue:
                self._emit_via_gui_queue(segments, "transcription", logger)
            return

        if hasattr(self, "_filter_duplicate_segments") and callable(
            self._filter_duplicate_segments,
        ):
            filtered_segments = self._filter_duplicate_segments(segments)
            if len(filtered_segments) < len(segments):
                if is_verbose:
                    logger.debug(
                        f"[EMIT] Duplikate gefiltert: {len(segments)} → {len(filtered_segments)}",
                    )
                segments = filtered_segments

        if not segments:
            if is_verbose:
                logger.debug("[EMIT] Nach Duplikatfilterung keine Segmente übrig")
            return

        if len(segments) > max_segments_per_call:
            logger.warning(
                f"[EMIT] {len(segments)} Segmente > Limit {max_segments_per_call} – kürze",
            )
            segments = segments[:max_segments_per_call]

        gui_queue = getattr(self, "gui_queue", None)
        if gui_queue is not None and is_verbose:
            try:
                qsize = gui_queue.qsize()
                logger.debug(f"[EMIT] GUI-Queue-Größe vor Batch: {qsize}")
            except Exception as e:
                logger.debug(f"[EMIT] qsize() fehlgeschlagen: {e}")

        effective_batch_size = batch_size
        if len(segments) > 20:
            effective_batch_size = min(10, batch_size + 2)
        elif len(segments) > 10:
            effective_batch_size = min(8, batch_size + 1)

        if is_verbose:
            logger.debug(
                f"[EMIT] Batch-Größe: {effective_batch_size} (Segmente: {len(segments)})",
            )

        batch = []
        emitted_count = 0
        error_count = 0

        for idx, seg in enumerate(segments):
            if seg is None:
                if is_verbose:
                    logger.debug(f"[EMIT] Segment {idx} ist None – überspringe")
                continue

            text = getattr(seg, "text", "").strip()
            if not text:
                if is_verbose:
                    logger.debug(f"[EMIT] Segment {idx} hat leeren Text – überspringe")
                continue

            batch.append(seg)

            if len(batch) >= effective_batch_size:
                try:
                    self._emit_batch(batch, trans_cb, transl_cb)
                    emitted_count += len(batch)
                except Exception as e:
                    logger.error(f"[EMIT] Batch-Fehler: {e}", exc_info=is_verbose)
                    error_count += 1
                    for single_seg in batch:
                        try:
                            self._emit_single_segment(
                                single_seg,
                                trans_cb,
                                transl_cb,
                                gui_queue,
                            )
                            emitted_count += 1
                        except Exception as single_e:
                            logger.error(
                                f"[EMIT] Einzelausgabe fehlgeschlagen: {single_e}",
                            )
                            error_count += 1
                batch.clear()

        if batch:
            try:
                self._emit_batch(batch, trans_cb, transl_cb)
                emitted_count += len(batch)
            except Exception as e:
                logger.error(f"[EMIT] Rest-Batch-Fehler: {e}", exc_info=is_verbose)
                error_count += 1
                for single_seg in batch:
                    try:
                        self._emit_single_segment(
                            single_seg,
                            trans_cb,
                            transl_cb,
                            gui_queue,
                        )
                        emitted_count += 1
                    except Exception as single_e:
                        logger.error(
                            f"[EMIT] Einzelausgabe (Rest) fehlgeschlagen: {single_e}",
                        )
                        error_count += 1

        if is_verbose:
            try:
                if gui_queue is not None:
                    qsize = gui_queue.qsize()
                    logger.debug(f"[EMIT] Queue-Größe nach Batch: {qsize}")
                else:
                    logger.debug("[EMIT] Keine GUI-Queue vorhanden")
            except Exception:
                pass

            logger.debug(
                f"[EMIT] Abgeschlossen: {emitted_count} Segmente gesendet, {error_count} Fehler",
            )

        if (
            emitted_count == 0
            and error_count > 0
            and fallback_to_gui_queue
            and gui_queue is not None
        ):
            logger.warning(
                "[EMIT] Keine Segmente über Callbacks gesendet – versuche Direkt-Queue",
            )
            self._emit_via_gui_queue(segments, "transcription", logger)

    def _emit_batch(
        self,
        batch: list[TranscriptionResult],
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        *,
        return_stats: bool = False,
    ) -> dict | None:
        """Fasst einen Batch von Segmenten zusammen und leitet ihn weiter.

        **Robustheitskette (4 Stufen):**

            1. `trans_cb(combined_seg)` – Transkriptions-Callback
            2. `gui_queue.put(...)` – direkter GUI-Fallback
            3. `_write_fallback_file(text)` – Datei-Persistenz
            4. `_emit_segments_fallback(batch, ...)` – Segment-Level

        **Übersetzung:** Wird zusätzlich via `_translate_and_send_async(...)`
        angestoßen, wenn `translation_engine` vorhanden und
        `_translation_enabled` gesetzt ist.

        **Aggregation der Metadaten:**
            - `combined_text`: Alle Segmente, whitespace-normalisiert, verbunden.
            - `avg_confidence`: **Arithmetisches Mittel** der Segment-Confidences.
              Default 0.5, wenn keine Confidence verfügbar.
            - `language`: **Confidence-gewichtete Mehrheit** (nicht mehr reine
              Häufigkeits-Mehrheit). Fallback: häufigste Sprache, dann
              "unknown".

        **Änderungen v3.0:**
            - ✨ **Return-Dict** (`success`, `fallback_used`, `stats`, …)
              für Diagnose und Tests.
            - ✨ **Statistik-Tracking** in `self._emit_batch_stats`:
              Gesamt-Aufrufe, erfolgreiche, Fallback-Zähler, Fehler.
            - ✨ **Confidence-gewichtete Sprach-Aggregation**: Robuster bei
              gemischt-sprachigen Segmenten.
            - ✨ **Truncation für Logs** (Konstante `_LOG_TEXT_PREVIEW_LEN`).
            - ✨ **Konstanten** am Methodenanfang (keine Magic Numbers).
            - ✨ **`combined_seg`-Reuse**: Kein Neuaufbau im Fallback.
            - ✨ **Geringere Allokationen**: Listen-Comprehension statt `append`.
            - 🔧 **`exc_info=is_verbose`** statt `exc_info=debug_level >= 3`
              (identische Semantik, klarer benannt).
            - 🔧 **GUI-Queue-Put mit optionalem `block=True, timeout=…`**
              (aus Settings), damit die Pipeline nicht ewig wartet.

        Args:
            batch: Liste der Transkriptions-Segmente.
            trans_cb: Transkriptions-Callback (kann None sein).
            transl_cb: Übersetzungs-Callback (kann None sein).
            return_stats: Wenn True, wird ein Diagnose-Dict zurückgegeben.
                Standard: False (nur Side-Effects, wie v2.0).

        Returns:
            None (Standard) oder dict (bei `return_stats=True`) mit:
                - success (bool): True wenn mindestens eine Stufe erfolgreich
                - fallback_used (bool): True wenn Stufe > 1 verwendet wurde
                - callback_called (bool): True wenn `trans_cb` erfolgreich
                - gui_queue_put (bool): True wenn GUI-Queue-Fallback griff
                - file_fallback (bool): True wenn Datei-Fallback griff
                - segments_fallback (bool): True wenn Segment-Level-Fallback
                - translation_triggered (bool): True wenn Übersetzung angestoßen
                - combined_text_len (int)
                - segments_count (int)
                - language (str)
                - avg_confidence (float)
                - duration_ms (float)
                - error (str | None): Fehlermeldung falls Exception
        """
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        is_verbose = debug_level >= 3

        t_start = time.monotonic()

        LOG_PREVIEW_LEN = 50
        DEFAULT_CONFIDENCE = 0.5
        GUI_QUEUE_PUT_TIMEOUT = 2.0
        GUI_QUEUE_PUT_BLOCK = True

        stats_result: dict = {
            "success": False,
            "fallback_used": False,
            "callback_called": False,
            "gui_queue_put": False,
            "file_fallback": False,
            "segments_fallback": False,
            "translation_triggered": False,
            "combined_text_len": 0,
            "segments_count": len(batch) if batch else 0,
            "language": "unknown",
            "avg_confidence": DEFAULT_CONFIDENCE,
            "duration_ms": 0.0,
            "error": None,
        }

        def _finalize() -> dict | None:
            """Berechnet die Dauer und gibt das Ergebnis zurück."""
            stats_result["duration_ms"] = (time.monotonic() - t_start) * 1000
            try:
                if not hasattr(self, "_emit_batch_stats"):
                    self._emit_batch_stats = {
                        "total": 0,
                        "success": 0,
                        "fallback": 0,
                        "failed": 0,
                        "translation_triggered": 0,
                    }
                s = self._emit_batch_stats
                s["total"] += 1
                if stats_result["success"]:
                    s["success"] += 1
                elif stats_result["error"]:
                    s["failed"] += 1
                if stats_result["fallback_used"]:
                    s["fallback"] += 1
                if stats_result["translation_triggered"]:
                    s["translation_triggered"] += 1
            except Exception:
                pass
            return stats_result if return_stats else None

        if not batch:
            if is_verbose:
                logger.debug("[EMIT_BATCH] Leerer Batch – übersprungen")
            stats_result["success"] = True
            return _finalize()

        gui_queue = getattr(self, "gui_queue", None)
        if gui_queue is None:
            logger.error(
                "[EMIT_BATCH] GUI-Queue ist None! Daten können nicht "
                "an GUI gesendet werden.",
            )
        elif debug_level >= 2:
            with contextlib.suppress(Exception):
                logger.debug(
                    f"[EMIT_BATCH] GUI-Queue-Größe VOR Batch: {gui_queue.qsize()}",
                )

        combined_text: str = ""
        avg_conf: float = DEFAULT_CONFIDENCE
        language: str = "unknown"
        start: float | None = None
        end: float | None = None
        combined_seg: TranscriptionResult | None = None
        callback_success = False

        try:
            texts: list[str] = []
            for seg in batch:
                seg_text = getattr(seg, "text", None)
                if seg_text and isinstance(seg_text, str):
                    stripped = seg_text.strip()
                    if stripped:
                        texts.append(stripped)

            if not texts:
                if is_verbose:
                    logger.debug("[EMIT_BATCH] Kein Text in Segmenten")
                stats_result["success"] = True
                return _finalize()

            combined_text = " ".join(texts).strip()
            stats_result["combined_text_len"] = len(combined_text)

            if self._is_duplicate_text(combined_text):
                if is_verbose:
                    logger.debug(
                        f"[EMIT_BATCH] Batch als Duplikat verworfen: "
                        f"{combined_text[:LOG_PREVIEW_LEN]}...",
                    )
                stats_result["success"] = True
                return _finalize()

            confidences: list[float] = []
            lang_confidence: dict[str, float] = {}
            lang_counts: dict[str, int] = {}

            for seg in batch:
                conf = getattr(seg, "confidence", None)
                if isinstance(conf, (int, float)):
                    conf_f = max(0.0, min(1.0, float(conf)))
                    confidences.append(conf_f)

                    lang = getattr(seg, "language", None)
                    if lang and isinstance(lang, str) and lang != "unknown":
                        lang_confidence[lang] = lang_confidence.get(lang, 0.0) + conf_f
                        lang_counts[lang] = lang_counts.get(lang, 0) + 1

            if confidences:
                avg_conf = sum(confidences) / len(confidences)
                avg_conf = max(0.0, min(1.0, avg_conf))
            stats_result["avg_confidence"] = avg_conf

            if lang_confidence:
                max_weight = max(lang_confidence.values())
                candidates = [
                    lang for lang, w in lang_confidence.items() if w == max_weight
                ]
                if len(candidates) == 1:
                    language = candidates[0]
                else:
                    language = max(candidates, key=lambda l: lang_counts.get(l, 0))
            elif lang_counts:
                language = max(lang_counts, key=lang_counts.get)

            stats_result["language"] = language

            first_seg = batch[0]
            last_seg = batch[-1]
            seg_start = getattr(first_seg, "start", None)
            seg_end = getattr(last_seg, "end", None)
            if isinstance(seg_start, (int, float)):
                start = float(seg_start)
            if isinstance(seg_end, (int, float)):
                end = float(seg_end)

            combined_seg = TranscriptionResult(
                text=combined_text,
                confidence=avg_conf,
                language=language,
                start=start,
                end=end,
                timestamp=time.time(),
            )

            if callable(trans_cb):
                try:
                    if debug_level >= 2:
                        logger.debug(
                            f"[EMIT_BATCH] trans_cb: "
                            f"'{combined_text[:LOG_PREVIEW_LEN]}...'",
                        )
                    trans_cb(combined_seg)
                    self._mark_text_as_flushed(combined_text, batch)
                    callback_success = True
                    stats_result["callback_called"] = True

                    if debug_level >= 2 and gui_queue is not None:
                        with contextlib.suppress(Exception):
                            logger.debug(
                                f"[EMIT_BATCH] GUI-Queue NACH trans_cb: "
                                f"{gui_queue.qsize()}",
                            )
                except Exception as e:
                    logger.error(
                        f"[EMIT_BATCH] trans_cb fehlgeschlagen: {e}",
                        exc_info=is_verbose,
                    )
            else:
                logger.error("[EMIT_BATCH] trans_cb ist nicht aufrufbar")

            if gui_queue is not None and not callback_success:
                try:
                    queue_empty = gui_queue.qsize() == 0
                except Exception:
                    queue_empty = True

                if queue_empty:
                    if debug_level >= 2:
                        logger.warning(
                            "[EMIT_BATCH] Callback hat Queue nicht befüllt "
                            "– verwende Fallback",
                        )
                    try:
                        gui_queue.put(
                            {
                                "type": "transcription",
                                "text": combined_text,
                                "start": start,
                                "end": end,
                                "language": language,
                                "confidence": avg_conf,
                            },
                            block=GUI_QUEUE_PUT_BLOCK,
                            timeout=GUI_QUEUE_PUT_TIMEOUT,
                        )
                        stats_result["gui_queue_put"] = True
                        stats_result["fallback_used"] = True
                        if debug_level >= 2:
                            with contextlib.suppress(Exception):
                                logger.debug(
                                    f"[EMIT_BATCH] GUI-Queue NACH Fallback: "
                                    f"{gui_queue.qsize()}",
                                )
                    except Exception as e:
                        logger.error(
                            f"[EMIT_BATCH] GUI-Queue-Fallback fehlgeschlagen: {e}"
                        )
                elif is_verbose:
                    logger.debug("[EMIT_BATCH] Queue wurde durch Callback befüllt")

            translation_engine = getattr(self, "translation_engine", None)
            translation_enabled = getattr(self, "_translation_enabled", None)
            translation_is_on = (
                translation_enabled is not None and translation_enabled.is_set()
            )
            if translation_engine is not None and translation_is_on:
                try:
                    if is_verbose:
                        logger.debug(
                            f"[EMIT_BATCH] Übersetzung angefordert: "
                            f"'{combined_text[:LOG_PREVIEW_LEN]}...'",
                        )
                    self._translate_and_send_async(
                        combined_text,
                        language,
                        transl_cb,
                        start=start,
                        end=end,
                    )
                    stats_result["translation_triggered"] = True
                except Exception as e:
                    logger.warning(
                        f"[EMIT_BATCH] Übersetzung fehlgeschlagen: {e}",
                    )

            if debug_level >= 2:
                logger.debug(
                    f"[EMIT_BATCH] Batch OK: {len(batch)} Segmente, "
                    f"{len(combined_text)} Zeichen, Sprache={language}, "
                    f"Confidence={avg_conf:.3f}, "
                    f"fallback={stats_result['fallback_used']}",
                )

            stats_result["success"] = True

        except Exception as e:
            stats_result["error"] = f"{type(e).__name__}: {e}"
            logger.error(
                f"[EMIT_BATCH] Unerwarteter Fehler: {e}",
                exc_info=True,
            )

            if gui_queue is not None:
                try:
                    gui_queue.put(
                        {
                            "type": "transcription",
                            "text": combined_text or "Fehler bei Batch-Verarbeitung",
                            "start": start,
                            "end": end,
                            "language": language,
                            "confidence": avg_conf,
                        },
                    )
                    stats_result["gui_queue_put"] = True
                    stats_result["fallback_used"] = True
                    logger.debug(
                        "[EMIT_BATCH] Notfall: Daten in GUI-Queue gelegt",
                    )
                except Exception as e2:
                    logger.error(
                        f"[EMIT_BATCH] Notfall put fehlgeschlagen: {e2}",
                    )

            if combined_text and hasattr(self, "_write_fallback_file"):
                try:
                    self._write_fallback_file(combined_text)
                    stats_result["file_fallback"] = True
                    stats_result["fallback_used"] = True
                    logger.warning(
                        "[EMIT_BATCH] Fallback-Datei geschrieben (kein Callback/Queue)",
                    )
                except Exception as e3:
                    logger.error(
                        f"[EMIT_BATCH] Fallback-Datei fehlgeschlagen: {e3}",
                    )

            if hasattr(self, "_emit_segments_fallback"):
                try:
                    self._emit_segments_fallback(batch, trans_cb, transl_cb)
                    stats_result["segments_fallback"] = True
                    stats_result["fallback_used"] = True
                    logger.warning(
                        "[EMIT_BATCH] Segment-Level-Fallback aktiviert",
                    )
                except Exception as e4:
                    logger.error(
                        f"[EMIT_BATCH] Segment-Level-Fallback fehlgeschlagen: {e4}",
                    )

        return _finalize()

    def _emit_single_segment(
        self,
        seg: TranscriptionResult,
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        gui_queue: Any = None,
    ) -> None:
        """Gibt ein einzelnes Segment aus (Fallback bei Batch-Fehlern)."""
        import logging

        logger = logging.getLogger("dragon")

        if seg is None:
            return

        text = getattr(seg, "text", "").strip()
        if not text:
            return

        if self._is_duplicate_text(text):
            return

        if callable(trans_cb):
            try:
                trans_cb(seg)
                self._mark_text_as_flushed(text, [seg])
                return
            except Exception as e:
                logger.warning(f"_emit_single_segment: trans_cb fehlgeschlagen: {e}")

        if gui_queue is not None:
            try:
                gui_queue.put(
                    {
                        "type": "transcription",
                        "text": text,
                        "start": getattr(seg, "start", None),
                        "end": getattr(seg, "end", None),
                        "language": getattr(seg, "language", "unknown"),
                        "confidence": getattr(seg, "confidence", 0.5),
                    },
                )
                return
            except Exception as e:
                logger.warning(f"_emit_single_segment: GUI-Queue-Fehler: {e}")

        if hasattr(self, "_write_fallback_file"):
            self._write_fallback_file(text)
            logger.warning("_emit_single_segment: Fallback-Datei geschrieben")

    def _emit_via_gui_queue(
        self,
        segments: list[TranscriptionResult],
        queue_type: str,
        logger: Any,
    ) -> None:
        """Direkte Queue-Einreihung als ultimativer Fallback."""
        gui_queue = getattr(self, "gui_queue", None)
        if gui_queue is None:
            logger.error(
                "[EMIT] GUI-Queue nicht verfügbar – keine Fallback-Möglichkeit",
            )
            return

        count = 0
        for seg in segments:
            if seg is None:
                continue
            text = getattr(seg, "text", "").strip()
            if not text:
                continue
            try:
                gui_queue.put(
                    {
                        "type": queue_type,
                        "text": text,
                        "start": getattr(seg, "start", None),
                        "end": getattr(seg, "end", None),
                        "language": getattr(seg, "language", "unknown"),
                        "confidence": getattr(seg, "confidence", 0.5),
                    },
                )
                count += 1
            except Exception as e:
                logger.error(f"[EMIT] Direkt-Queue-Fehler: {e}")
        if count:
            logger.info(
                f"[EMIT] {count} Segmente direkt in GUI-Queue eingereiht (Fallback)",
            )

    def _enqueue_transcript_segments(
        self,
        segments: list[TranscriptionResult],
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
    ) -> None:
        """Reiht Segmente in die Transkript‑Queue ein (für Satzpufferung)."""
        for seg in segments:
            self._handle_transcript_segment(seg, trans_cb, transl_cb)

    def _filter_duplicate_segments(
        self,
        segments: list[TranscriptionResult],
    ) -> list[TranscriptionResult]:
        """Entfernt Segmente, die bereits als Duplikate erkannt wurden (auf Chunk‑Ebene)."""
        if not segments:
            return []

        if not hasattr(self, "_batch_seen_texts"):
            self._batch_seen_texts = set()

        batch_seen = self._batch_seen_texts
        batch_seen.clear()

        lock = getattr(self, "_duplicate_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._duplicate_lock = lock

        max_cache_size = getattr(self, "_max_flushed_texts_cache", 1000)
        use_fuzzy = getattr(self, "_enable_fuzzy_duplicate_check", False)
        similarity_threshold = getattr(self, "_fuzzy_similarity_threshold", 0.85)

        fuzzy_available = False
        if use_fuzzy:
            try:
                from rapidfuzz import fuzz

                fuzzy_available = True
            except ImportError:
                logger.debug("rapidfuzz nicht verfügbar – Fuzzy-Matching deaktiviert")

        unique = []

        with lock:
            if not hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts = set()

            flushed = self._already_flushed_texts

            for seg in segments:
                text = getattr(seg, "text", "").strip()
                if not text:
                    continue

                if text in flushed or text in batch_seen:
                    continue

                if fuzzy_available and len(text) > 5:
                    is_duplicate = False
                    check_set = flushed if len(flushed) <= 50 else list(flushed)[-50:]
                    for existing in check_set:
                        if (
                            len(existing) > 5
                            and fuzz.ratio(text, existing) >= similarity_threshold * 100
                        ):
                            is_duplicate = True
                            if DEBUG_LEVEL >= 4:
                                log_debug(
                                    "duplicate",
                                    f"Fuzzy-Duplikat: '{text[:30]}' ≈ '{existing[:30]}'",
                                )
                            break
                    if is_duplicate:
                        continue

                unique.append(seg)
                batch_seen.add(text)
                flushed.add(text)
                if len(flushed) > max_cache_size:
                    if len(flushed) > max_cache_size * 1.5:
                        flushed.clear()
                        logger.debug("Duplicate cache cleared (size limit reached)")

        return unique

    def _handle_transcript_segment(
        self,
        segment: TranscriptionResult,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback | None = None,
    ) -> None:
        """Reiht ein Transkriptionssegment in die chronologische Warteschlange ein."""
        if segment is None or not getattr(segment, "text", "").strip():
            return

        class _NullContext:
            """Ein Kontextmanager, der nichts tut – wird verwendet, wenn ein
            benötigtes Lock in der Instanz nicht existiert.
            """

            __slots__ = ()

            def __enter__(self):
                return self

            def __exit__(self, *args: object) -> None:
                pass

        has_queue = (
            hasattr(self, "_transcript_queue")
            and hasattr(self, "_transcript_queue_lock")
            and hasattr(self, "_process_transcript_queue")
        )

        if not has_queue:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "transcript",
                    "Fallback: _transcript_queue nicht verfügbar – direkte Ausgabe",
                )

            if transcription_callback is not None:
                try:
                    transcription_callback(segment)
                except Exception as exc:
                    logger.error(
                        "transcription_callback error in fallback: %s",
                        exc,
                    )

            if (
                translation_callback is not None
                and getattr(self, "_translation_enabled", threading.Event()).is_set()
                and getattr(self, "translation_engine", None) is not None
            ):
                try:
                    self._handle_sentence_buffering(segment, translation_callback)
                except Exception as exc:
                    logger.error(
                        "Fehler im Satzpuffer für Übersetzung (Fallback): %s",
                        exc,
                    )
            return

        queue_lock = getattr(self, "_transcript_queue_lock", _NullContext())
        pushed = False
        try:
            with queue_lock:
                self._transcript_queue.append(segment)
                pushed = True
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "transcript",
                        "Segment in _transcript_queue eingereiht (start=%.3f, text='%.50s')",
                        getattr(segment, "start", -1.0),
                        segment.text[:50],
                    )
        except Exception as exc:
            logger.error(
                "Fehler beim Befüllen der _transcript_queue: %s – gebe direkt aus.",
                exc,
            )
            if transcription_callback is not None:
                try:
                    transcription_callback(segment)
                except Exception as cb_exc:
                    logger.error(
                        "transcription_callback error after queue failure: %s",
                        cb_exc,
                    )
            if (
                translation_callback is not None
                and getattr(self, "_translation_enabled", threading.Event()).is_set()
                and getattr(self, "translation_engine", None) is not None
            ):
                try:
                    self._handle_sentence_buffering(segment, translation_callback)
                except Exception as cb_exc:
                    logger.error(
                        "Übersetzungs‑Callback error after queue failure: %s",
                        cb_exc,
                    )
            return

        if pushed:
            try:
                self._process_transcript_queue(transcription_callback)
            except Exception as exc:
                logger.error(
                    "Fehler beim Abarbeiten der _transcript_queue: %s",
                    exc,
                    exc_info=DEBUG_LEVEL >= 3,
                )

        if (
            translation_callback is not None
            and getattr(self, "_translation_enabled", threading.Event()).is_set()
            and getattr(self, "translation_engine", None) is not None
        ):
            try:
                self._handle_sentence_buffering(segment, translation_callback)
            except Exception as exc:
                logger.error(
                    "Fehler beim Satzpuffer für Übersetzung: %s",
                    exc,
                )

    def _process_translation_queue(
        self,
        translation_callback: TranslationCallback | None,
        force_flush: bool = False,
    ) -> None:
        """Arbeitet die sortierte Übersetzungs‑Warteschlange ab und gibt chronologisch
        korrekte Übersetzungen aus. Asynchron eintreffende Einträge werden gepuffert
        und nicht als „late“ verworfen.
        """
        if translation_callback is None:
            return
        FORWARD_TOLERANCE = 2.0
        BACKWARD_TOLERANCE = 10.0
        MAX_QUEUE_SIZE = 200
        MAX_FUTURE_WAIT = 5.0

        class _NullContext:
            __slots__ = ()

            def __enter__(self):
                return self

            def __exit__(self, *args: object) -> None:
                pass

        queue_lock = getattr(self, "_translation_queue_lock", _NullContext())
        with queue_lock:
            if not hasattr(self, "_translation_queue"):
                self._translation_queue = deque(maxlen=500)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "translate_queue",
                        "Initialized _translation_queue (maxlen=500)",
                    )

            queue = self._translation_queue
            if not queue and not force_flush:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "translate_queue",
                        "Queue empty and force_flush=False – nothing to do",
                    )
                return
            immediate: list[TranslationResult] = []
            timed: list[TranslationResult] = []
            for entry in list(queue):
                if entry.start is None:
                    immediate.append(entry)
                else:
                    timed.append(entry)

            queue.clear()
            queue.extend(timed)

            _total_split = len(immediate) + len(timed)
            if DEBUG_LEVEL >= 3 and _total_split > 0:
                log_debug(
                    "translate_queue",
                    "Queue split: %d immediate, %d timed (total %d)",
                    len(immediate),
                    len(timed),
                    _total_split,
                )

            if len(queue) > MAX_QUEUE_SIZE:
                overflow = [queue.popleft() for _ in range(len(queue) - MAX_QUEUE_SIZE)]
                immediate.extend(overflow)
                logger.warning(
                    "Translation queue overflow – %d oldest entries flushed immediately",
                    len(overflow),
                )
            sorted_list = sorted(
                queue,
                key=lambda r: r.start if r.start is not None else float("inf"),
            )
            queue.clear()
            queue.extend(sorted_list)
            if not hasattr(self, "_next_expected_translation_start"):
                self._next_expected_translation_start = 0.0

            if self._next_expected_translation_start == 0.0 and queue:
                first = queue[0]
                if first.start is not None:
                    self._next_expected_translation_start = first.start
                    log_debug(
                        "translate_queue",
                        "Initialized next_expected_translation_start = %.2f (first entry start)",
                        first.start,
                    )
            to_emit: list[TranslationResult] = []
            remaining: list[TranslationResult] = []

            for entry in queue:
                if force_flush:
                    to_emit.append(entry)
                    continue

                start = entry.start
                if start is None:
                    to_emit.append(entry)
                    continue

                expected = self._next_expected_translation_start
                if start <= expected + FORWARD_TOLERANCE:
                    if start < expected - BACKWARD_TOLERANCE:
                        log_debug(
                            "translate_queue",
                            "Late entry (start=%.2f, expected=%.2f) – emitting anyway",
                            start,
                            expected,
                        )
                    to_emit.append(entry)
                else:
                    remaining.append(entry)

            future_emit: list[TranslationResult] = []
            remaining_filtered: list[TranslationResult] = []
            for entry in remaining:
                if (
                    entry.start is not None
                    and entry.start
                    > self._next_expected_translation_start + MAX_FUTURE_WAIT
                ):
                    future_emit.append(entry)
                else:
                    remaining_filtered.append(entry)

            if future_emit:
                log_debug(
                    "translate_queue",
                    "%d entries forced due to > %.1fs future limit",
                    len(future_emit),
                    MAX_FUTURE_WAIT,
                )
                to_emit.extend(future_emit)
                remaining = remaining_filtered

            if to_emit:
                for entry in to_emit:
                    end_val = (
                        entry.end
                        if entry.end is not None
                        else (entry.start + 0.001 if entry.start is not None else 0.001)
                    )
                    self._next_expected_translation_start = max(
                        self._next_expected_translation_start,
                        end_val,
                    )
                if force_flush:
                    remaining.clear()
            queue.clear()
            queue.extend(remaining)

            if DEBUG_LEVEL >= 3 and (len(to_emit) > 0 or len(immediate) > 0):
                log_debug(
                    "translate_queue",
                    "After processing: to_emit=%d, remaining=%d, immediate=%d, next_expected=%.2f",
                    len(to_emit),
                    len(remaining),
                    len(immediate),
                    self._next_expected_translation_start,
                )

        def _safe_invoke_callback(entry: TranslationResult) -> None:
            """Rufe _safe_translation_callback mit allen benötigten Argumenten auf."""
            try:
                clean_text = getattr(entry, "clean_text", "")
                source_lang = getattr(entry, "source_lang", "")
                target_lang = getattr(entry, "target_lang", "")
                prefix = getattr(entry, "prefix", "")
                start = getattr(entry, "start", 0.0)
                end = getattr(
                    entry,
                    "end",
                    start + 0.001 if start is not None else 0.001,
                )

                if not clean_text and hasattr(entry, "original_text"):
                    clean_text = entry.original_text
                if not clean_text and hasattr(entry, "text"):
                    clean_text = entry.text
                if clean_text is None or clean_text is Ellipsis:
                    logger.warning(
                        "Invalid clean_text in entry: %r – using empty string",
                        clean_text,
                    )
                    clean_text = ""

                self._safe_translation_callback(
                    translation_callback,
                    clean_text=clean_text,
                    source_lang=source_lang,
                    target_lang=target_lang,
                    prefix=prefix,
                    start=start,
                    end=end,
                )
            except TypeError as e:
                logger.error(
                    "TypeError in translation callback for start=%.2f: %s – trying fallback with only text",
                    getattr(entry, "start", -1.0),
                    e,
                )
                try:
                    self._safe_translation_callback(translation_callback, clean_text)
                except Exception as fallback_e:
                    logger.error(
                        "Fallback callback also failed: %s",
                        fallback_e,
                        exc_info=DEBUG_LEVEL >= 3,
                    )
            except Exception as e:
                logger.error(
                    "Error in translation callback for start=%.2f: %s",
                    getattr(entry, "start", -1.0),
                    e,
                    exc_info=DEBUG_LEVEL >= 3,
                )

        for entry in immediate:
            _safe_invoke_callback(entry)

        if force_flush:
            to_emit.sort(key=lambda r: r.start if r.start is not None else float("inf"))

        for entry in to_emit:
            _safe_invoke_callback(entry)

        if DEBUG_LEVEL >= 3 and (immediate or to_emit):
            log_debug(
                "translate_queue",
                "Flushed %d immediate + %d timed translations (remaining=%d)",
                len(immediate),
                len(to_emit),
                len(remaining),
            )

    def _safe_invoke_translation_callback(
        self,
        callback: TranslationCallback | None,
        entry: TranslationResult | None,
        context: str = "",
    ) -> None:
        """Sicherer Aufruf der _safe_translation_callback mit einem vollständigen
        TranslationResult-Objekt.
        """
        if callback is None:
            return

        if entry is None:
            logger.warning(
                "_safe_invoke_translation_callback: entry ist None – überspringe",
            )
            return

        try:
            self._safe_translation_callback(callback, entry)

            if DEBUG_LEVEL >= 4:
                start_str = f"{entry.start:.2f}" if entry.start is not None else "None"
                log_debug(
                    "translate_callback",
                    "✅ Callback invoked (context=%s): start=%s, text='%s...'",
                    context,
                    start_str,
                    (entry.translated or "")[:30],
                )
        except Exception as e:
            logger.error(
                "❌ Error invoking translation callback (context=%s): %s",
                context,
                e,
                exc_info=DEBUG_LEVEL >= 3,
            )

    @staticmethod
    def safe_callback(cb: Callable | None, *args: Any, **kwargs: Any) -> None:
        """Ruft einen Callback auf und fängt **alle** Exceptions ab, um die
        Verarbeitung nicht zu unterbrechen.  Thread‑sicher.
        """
        if cb is None:
            return
        try:
            cb(*args, **kwargs)
        except Exception as e:
            try:
                cb_name = getattr(cb, "__name__", type(cb).__name__)
                _safe_log_debug("callback", f"Callback '{cb_name}' fehlgeschlagen: {e}")
            except (NameError, Exception):
                try:
                    logger = logging.getLogger("dragon")
                    logger.debug("Callback fehlgeschlagen: %s", e, exc_info=True)
                except Exception:
                    pass

    def _analyze_audio_for_music_silence(
        self,
        audio_data: bytes,
        valid_segments: list,
    ) -> None:
        """Analysiert, ob der aktuelle Chunk Musik oder Stille enthält,
        und sendet entsprechende Events über den Event‑Bus.
        """
        if self._stop_event.is_set():
            return
        is_silent = self._is_silent(audio_data, threshold=0.002)
        with self._music_silence_lock:
            if valid_segments:
                self._consecutive_music_chunks = 0
                self._consecutive_silence_chunks = 0
                if self._music_state_active or self._silence_state_active:
                    self._music_state_active = False
                    self._silence_state_active = False
                    self._emit_music_silence_event("speech_detected")
            else:
                if is_silent:
                    self._consecutive_music_chunks = 0
                    self._consecutive_silence_chunks += 1
                    self._consecutive_silence_chunks = min(
                        self._consecutive_silence_chunks,
                        1000,
                    )
                else:
                    self._consecutive_silence_chunks = 0
                    self._consecutive_music_chunks += 1
                    self._consecutive_music_chunks = min(
                        self._consecutive_music_chunks,
                        1000,
                    )
                MUSIC_THRESHOLD = 5
                SILENCE_THRESHOLD = 10
                now = time.time()
                if (
                    self._consecutive_music_chunks >= MUSIC_THRESHOLD
                    and not self._music_state_active
                    and (now - self._last_music_event_time) > 30.0
                ):
                    self._music_state_active = True
                    self._silence_state_active = False
                    self._last_music_event_time = now
                    self._emit_music_silence_event("music_detected")
                elif (
                    self._consecutive_silence_chunks >= SILENCE_THRESHOLD
                    and not self._silence_state_active
                    and (now - self._last_music_event_time) > 30.0
                ):
                    self._silence_state_active = True
                    self._music_state_active = False
                    self._last_music_event_time = now
                    self._emit_music_silence_event("silence_detected")

    def _emit_music_silence_event(self, event_type: str) -> None:
        """Sendet ein Musik‑/Stille‑/Sprach‑Event sicher an den Event‑Bus."""
        if self._event_bus is not None:
            try:
                self._event_bus.emit(event_type, {"timestamp": time.time()})
                if DEBUG_LEVEL >= 3:
                    log_debug("audio", f"Emitted event: {event_type}")
            except Exception as e:
                logger.warning(f"Fehler beim Senden von {event_type}: {e}")

    def _configure_subtitle_buffer(
        self,
        max_size: int = 2000,
        gap_tolerance: float = 0.5,
        max_backward_time: float = 30.0,
        max_segment_age: float = 60.0,
        watchdog_seconds: float = 60.0,
    ) -> None:
        """Konfiguriert die Parameter für den chronologischen Segment‑Puffer
        (Subtitle‑Modus) und stellt sicher, dass alle Werte in sinnvollen
        Grenzen liegen.
        """
        if max_size < 100:
            logger.warning(
                "_configure_subtitle_buffer: max_size=%d zu klein, setze auf 100.",
                max_size,
            )
            max_size = 100
        if max_size > 10000:
            logger.warning(
                "_configure_subtitle_buffer: max_size=%d sehr groß, "
                "auf 10000 begrenzt.",
                max_size,
            )
            max_size = 10000

        gap_tolerance = max(0.1, min(5.0, gap_tolerance))
        max_backward_time = max(1.0, min(120.0, max_backward_time))
        max_segment_age = max(5.0, min(300.0, max_segment_age))
        watchdog_seconds = max(10.0, min(300.0, watchdog_seconds))

        self._max_segment_buffer_size = max_size
        self._subtitle_gap_tolerance = gap_tolerance
        self._subtitle_max_backward_time = max_backward_time
        self._subtitle_max_segment_age = max_segment_age
        self._subtitle_watchdog_seconds = watchdog_seconds
        self._subtitle_watchdog_time = time.monotonic()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "SUBTITLE_CFG",
                "Subtitle buffer configured: max_size=%d, gap=%.1fs, "
                "backward=%.1fs, age=%.1fs, watchdog=%.1fs",
                max_size,
                gap_tolerance,
                max_backward_time,
                max_segment_age,
                watchdog_seconds,
            )

    def _buffer_and_flush_segments(
        self,
        segments: list[TranscriptionResult],
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback | None = None,
    ) -> None:
        """Puffert zeitgestempelte Transkriptionssegmente und gibt sie chronologisch aus."""
        debug_subtitle = "subtitle" in DEBUG_COMPONENTS

        if not segments:
            if debug_subtitle:
                log_debug("subtitle", "_buffer_and_flush_segments: leere Segmentliste")
            return

        if transcription_callback is None:
            if debug_subtitle:
                log_debug(
                    "subtitle",
                    "_buffer_and_flush_segments: kein Transkriptions-Callback",
                )
            return

        max_size = getattr(self, "_max_segment_buffer_size", 2000)
        gap_tolerance = getattr(self, "_subtitle_gap_tolerance", 0.5)
        max_backward_time = getattr(self, "_subtitle_max_backward_time", 30.0)
        max_segment_age = getattr(self, "_subtitle_max_segment_age", 30.0)
        watchdog_seconds = getattr(self, "_subtitle_watchdog_seconds", 5.0)
        drift_warning_threshold = getattr(self, "_subtitle_drift_threshold", 5.0)

        lock = getattr(self, "_segment_buffer_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._segment_buffer_lock = lock

        with lock:
            if not hasattr(self, "_segment_buffer") or self._segment_buffer is None:
                from collections import OrderedDict

                self._segment_buffer = OrderedDict()
                self._segment_keys = set()
                self._next_expected_start = 0.0
                self._subtitle_watchdog_time = time.monotonic()
                self._segment_counter = 0
                self._last_drift_warning_time = 0.0
                self._sorted_keys_cache = []

            buffer = self._segment_buffer
            keys = self._segment_keys
            added_count = 0

            for seg in segments:
                start_val = getattr(seg, "start", None)
                end_val = getattr(seg, "end", None)

                if start_val is None or end_val is None:
                    logger.warning(
                        "Segment ohne Zeitstempel – sofortige Ausgabe: '%.50s'",
                        seg.text[:50] if seg.text else "",
                    )
                    try:
                        transcription_callback(seg)
                    except Exception as e:
                        logger.error(f"Fehler bei sofortiger Ausgabe: {e}")
                    continue

                start_val = max(start_val, 0.0)
                if end_val <= start_val:
                    end_val = start_val + 0.001
                seg.start = start_val
                seg.end = end_val

                text_fingerprint = f"{len(seg.text)}:{seg.text[:50]}"
                key = (start_val, end_val, text_fingerprint)

                if key in keys:
                    existing = buffer.get(start_val)
                    if existing and existing.end < end_val:
                        existing.end = end_val
                        existing.text += " " + seg.text
                    continue

                if start_val in buffer:
                    existing = buffer[start_val]
                    existing.text += " " + seg.text
                    existing.end = max(existing.end, seg.end)
                else:
                    buffer[start_val] = seg
                    keys.add(key)
                    self._segment_counter += 1
                    added_count += 1

            if added_count > 0:
                self._sorted_keys_cache = sorted(buffer.keys())
                if debug_subtitle:
                    log_debug(
                        "subtitle",
                        f"{added_count} neue Segmente, Puffergröße: {len(buffer)}",
                    )

            if len(buffer) > max_size:
                sorted_items = sorted(buffer.items(), key=lambda x: x[0])
                to_remove = sorted_items[: max(0, len(sorted_items) - max_size)]
                for start_key, seg_to_remove in to_remove:
                    keys.discard(
                        (
                            start_key,
                            seg_to_remove.end,
                            f"{len(seg_to_remove.text)}:{seg_to_remove.text[:50]}",
                        ),
                    )
                    del buffer[start_key]
                self._sorted_keys_cache = sorted(buffer.keys())
                if debug_subtitle:
                    log_debug(
                        "subtitle",
                        f"Überlauf: {len(to_remove)} älteste Segmente entfernt",
                    )

        flushed_this_call = 0
        max_iterations = 1000
        iteration = 0

        while iteration < max_iterations:
            iteration += 1

            with lock:
                if not self._segment_buffer or not self._sorted_keys_cache:
                    break

                next_start = self._sorted_keys_cache[0]
                seg = self._segment_buffer.get(next_start)
                if seg is None:
                    self._sorted_keys_cache.pop(0)
                    continue

                now = time.monotonic()
                seg_start = seg.start

                if self._next_expected_start == 0.0 and self._segment_buffer:
                    self._next_expected_start = max(
                        0.0,
                        min(self._segment_buffer.keys()),
                    )

                if seg_start < self._next_expected_start - max_backward_time:
                    logger.warning(
                        "Verwerfe zu altes Segment: start=%.2f, expected=%.2f",
                        seg_start,
                        self._next_expected_start,
                    )
                    self._remove_and_output_segment(
                        seg,
                        next_start,
                        transcription_callback,
                        translation_callback,
                        _log_reason="zu alt",
                    )
                    flushed_this_call += 1
                    continue

                age_since_last_flush = now - self._subtitle_watchdog_time
                if age_since_last_flush > max_segment_age:
                    if debug_subtitle:
                        log_debug(
                            "subtitle",
                            f"Watchdog (Alter): erzwinge Ausgabe von start={seg_start:.2f}",
                        )
                    self._remove_and_output_segment(
                        seg,
                        next_start,
                        transcription_callback,
                        translation_callback,
                        _log_reason="Alter",
                    )
                    flushed_this_call += 1
                    self._subtitle_watchdog_time = now
                    continue

                if seg_start <= self._next_expected_start + gap_tolerance:
                    self._remove_and_output_segment(
                        seg,
                        next_start,
                        transcription_callback,
                        translation_callback,
                        _log_reason="normal",
                    )
                    flushed_this_call += 1
                    self._subtitle_watchdog_time = now

                    if flushed_this_call % 10 == 0 and len(self._segment_buffer) > 1:
                        self._check_subtitle_drift(drift_warning_threshold)
                    continue

                if now - self._subtitle_watchdog_time > watchdog_seconds:
                    if debug_subtitle:
                        log_debug(
                            "subtitle",
                            f"Watchdog (global): erzwinge Ausgabe von start={seg_start:.2f}",
                        )
                    self._remove_and_output_segment(
                        seg,
                        next_start,
                        transcription_callback,
                        translation_callback,
                        _log_reason="global",
                    )
                    flushed_this_call += 1
                    self._subtitle_watchdog_time = now
                    continue

                break

            with lock:
                if self._segment_buffer and len(self._segment_buffer) > max_size * 0.9:
                    logger.warning(
                        "Puffer fast voll (%d/%d) – erzwinge Ausgabe aller Segmente",
                        len(self._segment_buffer),
                        max_size,
                    )
                    items = list(self._segment_buffer.items())
                    for start_key, seg in items:
                        self._remove_and_output_segment(
                            seg,
                            start_key,
                            transcription_callback,
                            translation_callback,
                            _log_reason="overflow",
                        )
                        flushed_this_call += 1
                    self._segment_buffer.clear()
                    self._segment_keys.clear()
                    self._sorted_keys_cache = []
                    if items:
                        self._next_expected_start = max(
                            self._next_expected_start,
                            items[-1][1].end or 0.0,
                        )
                    self._subtitle_watchdog_time = time.monotonic()
                    break

        if flushed_this_call > 0 and debug_subtitle:
            with lock:
                buffer_size = len(self._segment_buffer) if self._segment_buffer else 0
            log_debug(
                "subtitle",
                f"Flushed {flushed_this_call} Segmente, Puffergröße jetzt {buffer_size}",
            )

    def _remove_and_output_segment(
        self,
        seg: TranscriptionResult,
        start_key: float,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback | None,
        disable_duplicate_check: bool = False,
        _log_reason: str = "normal",
    ) -> bool:
        """Entfernt ein Segment aus dem Puffer und gibt es garantiert aus."""
        _verbose = bool(os.getenv("DW_DEBUG_SEGMENT_OUT"))
        if not hasattr(self, "_seg_out_stats"):
            self._seg_out_stats = {
                "calls": 0,
                "buffer_cleanup_errors": 0,
                "transcription_ok": 0,
                "transcription_fail": 0,
                "translation_ok": 0,
                "translation_fail": 0,
            }
        self._seg_out_stats["calls"] += 1

        if seg is None:
            if _verbose or DEBUG_LEVEL >= 3:
                log_debug(
                    "SEG_OUT",
                    f"⏭️ _remove_and_output_segment: seg is None (reason={_log_reason})",
                )
            self._seg_out_stats["transcription_fail"] += 1
            return False

        if not callable(transcription_callback):
            logger.warning(
                "_remove_and_output_segment: transcription_callback "
                "ist nicht callable (reason=%s, type=%s)",
                _log_reason,
                type(transcription_callback).__name__,
            )
            self._seg_out_stats["transcription_fail"] += 1
            return False

        seg_text_raw = getattr(seg, "text", "") or ""
        seg_text_len = len(seg_text_raw) if isinstance(seg_text_raw, str) else 0

        if _verbose:
            log_debug(
                "SEG_OUT",
                f"🔍 _remove_and_output_segment ENTRY: "
                f"reason={_log_reason}, "
                f"start_key={start_key!r}, "
                f"seg.start={getattr(seg, 'start', None)!r}, "
                f"seg.end={getattr(seg, 'end', None)!r}, "
                f"text_len={seg_text_len}, "
                f"dedup_disabled={disable_duplicate_check}, "
                f"buffer_size={len(self._segment_buffer) if self._segment_buffer is not None else -1}",
            )

        transcription_ok = False
        try:
            with self._segment_buffer_lock:
                if self._segment_buffer is None:
                    if _verbose or DEBUG_LEVEL >= 3:
                        log_debug(
                            "SEG_OUT",
                            "_remove_and_output_segment: "
                            "_segment_buffer is None – überspringe Cleanup",
                        )
                else:
                    text_for_fp = (
                        seg_text_raw
                        if isinstance(seg_text_raw, str)
                        else str(seg_text_raw)
                    )
                    text_fingerprint = f"{len(text_for_fp)}:{text_for_fp[:50]}"
                    seg_end = getattr(seg, "end", None)
                    key = (start_key, seg_end, text_fingerprint)

                    try:
                        self._segment_keys.discard(key)
                    except Exception:
                        if _verbose:
                            log_debug(
                                "SEG_OUT",
                                "discard(key) fehlgeschlagen",
                                exc_info=True,
                            )

                    if start_key in self._segment_buffer:
                        try:
                            del self._segment_buffer[start_key]
                        except Exception:
                            if _verbose:
                                log_debug(
                                    "SEG_OUT",
                                    "del buffer[start_key] fehlgeschlagen",
                                    exc_info=True,
                                )

                    try:
                        if (
                            self._sorted_keys_cache
                            and self._sorted_keys_cache[0] == start_key
                        ):
                            self._sorted_keys_cache.pop(0)
                        else:
                            self._sorted_keys_cache = sorted(
                                self._segment_buffer.keys()
                            )
                    except Exception:
                        try:
                            self._sorted_keys_cache = sorted(
                                self._segment_buffer.keys()
                            )
                        except Exception:
                            self._sorted_keys_cache = []

                    if seg_end is not None:
                        try:
                            self._next_expected_start = max(
                                self._next_expected_start, seg_end
                            )
                        except Exception:
                            self._next_expected_start = seg_end

        except Exception:
            self._seg_out_stats["buffer_cleanup_errors"] += 1
            logger.exception(
                "_remove_and_output_segment: Buffer-Cleanup "
                "fehlgeschlagen (reason=%s, start_key=%r) – "
                "fahre mit Ausgabe fort",
                _log_reason,
                start_key,
            )

        try:
            transcription_ok = bool(
                self._output_segment_guaranteed(
                    seg,
                    transcription_callback,
                    disable_duplicate_check=disable_duplicate_check,
                )
            )
            if transcription_ok:
                self._seg_out_stats["transcription_ok"] += 1
            else:
                self._seg_out_stats["transcription_fail"] += 1
        except Exception:
            self._seg_out_stats["transcription_fail"] += 1
            logger.exception(
                "_remove_and_output_segment: "
                "_output_segment_guaranteed warf eine Exception "
                "(reason=%s, text_len=%d)",
                _log_reason,
                seg_text_len,
            )

        if (
            translation_callback is not None
            and getattr(self, "translation_engine", None) is not None
            and getattr(self, "_translation_enabled", None) is not None
            and self._translation_enabled.is_set()
        ):
            try:
                text = getattr(seg, "text", "") or ""
                if isinstance(text, str) and len(text) >= 2:
                    if _verbose or DEBUG_LEVEL >= 3:
                        log_debug(
                            "translate",
                            f"🔄 Übersetzung für: {text[:50]}...",
                        )
                    try:
                        self._translate_and_send_async(
                            text,
                            getattr(seg, "language", "unknown"),
                            translation_callback,
                            start=getattr(seg, "start", None),
                            end=getattr(seg, "end", None),
                        )
                        self._seg_out_stats["translation_ok"] += 1
                    except Exception:
                        self._seg_out_stats["translation_fail"] += 1
                        logger.exception(
                            "_remove_and_output_segment: "
                            "_translate_and_send_async fehlgeschlagen "
                            "(text_len=%d, lang=%r)",
                            len(text),
                            getattr(seg, "language", None),
                        )
                else:
                    if _verbose:
                        log_debug(
                            "SEG_OUT",
                            f"Übersetzung übersprungen – "
                            f"Text zu kurz ({len(text)} Zeichen) "
                            f"oder kein String",
                        )
            except Exception:
                self._seg_out_stats["translation_fail"] += 1
                logger.exception(
                    "_remove_and_output_segment: Phase-3-Wrapper warf eine Exception"
                )

        if _verbose and self._seg_out_stats["calls"] % 50 == 0:
            log_debug(
                "SEG_OUT",
                f"📊 _remove_and_output_segment Statistik: "
                f"calls={self._seg_out_stats['calls']}, "
                f"tx_ok={self._seg_out_stats['transcription_ok']}, "
                f"tx_fail={self._seg_out_stats['transcription_fail']}, "
                f"tr_ok={self._seg_out_stats['translation_ok']}, "
                f"tr_fail={self._seg_out_stats['translation_fail']}, "
                f"buffer_err={self._seg_out_stats['buffer_cleanup_errors']}",
            )

        if _verbose:
            log_debug(
                "SEG_OUT",
                f"✅ _remove_and_output_segment EXIT: "
                f"reason={_log_reason}, ok={transcription_ok}, "
                f"buffer_size={len(self._segment_buffer) if self._segment_buffer is not None else -1}",
            )

        return transcription_ok

    def _check_subtitle_drift(self, threshold: float) -> None:
        """Prüft die Drift im Subtitle‑Puffer und gibt eine Warnung aus (mit Rate‑Limiter)."""
        try:
            buffer = self._segment_buffer
            if len(buffer) < 2:
                return

            first_key = next(iter(buffer))
            last_key = next(reversed(buffer))
            first_seg = buffer[first_key]
            last_seg = buffer[last_key]

            if last_seg.start is None or first_seg.start is None:
                return

            actual_duration = last_seg.start - first_seg.start
            expected_duration = (
                last_key - first_key
            ) * self.settings.config.CHUNK_DURATION
            drift = actual_duration - expected_duration

            if abs(drift) > threshold:
                now = time.time()
                if now - getattr(self, "_last_drift_warning_time", 0.0) > 60.0:
                    self._last_drift_warning_time = now
                    logger.warning(
                        "⚠️ Subtitle-Drift: %.1fs vs %.1fs (diff=%.1fs), Puffer=%d, next_expected=%.2f",
                        actual_duration,
                        expected_duration,
                        drift,
                        len(buffer),
                        self._next_expected_start,
                    )
        except Exception as e:
            if "subtitle" in DEBUG_COMPONENTS:
                log_debug("subtitle", f"Drift‑Prüfung fehlgeschlagen: {e}")

    def _output_segment_guaranteed(
        self,
        seg: TranscriptionResult,
        callback: TranscriptionCallback,
        *,
        allow_duplicate: bool = False,
        log_gap: bool = False,
        disable_duplicate_check: bool = False,
    ) -> bool:
        """Gibt ein einzelnes Transkriptionssegment garantiert aus – optimierte Version."""
        if seg is None:
            if DEBUG_LEVEL >= 3:
                log_debug("SEG_OUT", "❌ seg is None – ignoriert")
            return False

        seg_text = getattr(seg, "text", "").strip()
        if not seg_text:
            if DEBUG_LEVEL >= 3:
                log_debug("SEG_OUT", "❌ Leerer Text – ignoriert")
            return False

        start_ts = getattr(seg, "start", None)
        end_ts = getattr(seg, "end", None)

        if callback is None or not callable(callback):
            if DEBUG_LEVEL >= 3:
                log_debug("SEG_OUT", "❌ Callback ungültig – Segment verworfen")
            return False
        debug_enabled = DEBUG_LEVEL >= 3 or "SEG_OUT" in DEBUG_COMPONENTS
        try:
            from contextlib import nullcontext
        except ImportError:

            class _NullContext:
                __slots__ = ()

                def __enter__(self):
                    return self

                def __exit__(self, *args):
                    pass

            nullcontext = _NullContext
        if log_gap and start_ts is not None:
            try:
                with getattr(self, "_last_output_timestamp_lock", nullcontext()):
                    last_ts = getattr(self, "_last_output_timestamp", 0.0)
                    if last_ts > 0.0 and start_ts > last_ts:
                        gap = start_ts - last_ts
                        if gap > 5.0:
                            logger.warning(
                                "SEG_GAP: %.2f s gap before start=%.2f text='%.50s'",
                                gap,
                                start_ts,
                                seg_text[:50],
                            )
            except Exception as exc:
                if debug_enabled:
                    log_debug("SEG_OUT", "Gap logging failed: %s", exc)

        duplicate_lock = getattr(self, "_duplicate_lock", threading.RLock())
        duplicate_skipped = False

        with duplicate_lock:
            if not hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts = set()
            if (
                not hasattr(self, "_already_flushed_cache")
                or self._already_flushed_cache is None
            ):
                try:
                    import psutil

                    total_ram = psutil.virtual_memory().total
                    max_entries = max(1000, min(50000, int(total_ram * 0.001 // 100)))
                except (ImportError, AttributeError):
                    max_entries = 50000
                self._already_flushed_cache = TTLCache(maxsize=max_entries, ttl=120)
                if debug_enabled:
                    log_debug(
                        "SEG_OUT",
                        f"TTLCache initialisiert (maxsize={max_entries})",
                    )
            flushed_set = self._already_flushed_texts
            cache = self._already_flushed_cache

        if not disable_duplicate_check:
            if len(seg_text) < 30:
                with duplicate_lock:
                    if seg_text in flushed_set:
                        if debug_enabled:
                            log_debug(
                                "SEG_OUT",
                                "⏭️ Exaktes Duplikat (kurzer Text): '%.50s'",
                                seg_text[:50],
                            )
                        return False
            else:
                with duplicate_lock:
                    if seg_text in flushed_set:
                        if debug_enabled:
                            log_debug(
                                "SEG_OUT",
                                "⏭️ Exaktes Duplikat (Set): '%.50s'",
                                seg_text[:50],
                            )
                        return False
                    if cache.get(seg_text) is not None:
                        if debug_enabled:
                            log_debug(
                                "SEG_OUT",
                                "⏭️ Duplikat (TTL‑Cache): '%.50s'",
                                seg_text[:50],
                            )
                        return False

                    if (
                        len(seg_text) > 50
                        and not allow_duplicate
                        and (debug_enabled or "fuzzy" in DEBUG_COMPONENTS)
                        and self._fuzzy_duplicate(seg_text, flushed_set)
                    ):
                        cache.put(seg_text, True)
                        if debug_enabled:
                            log_debug(
                                "SEG_OUT",
                                "⏭️ Fuzzy‑Duplikat: '%.50s'",
                                seg_text[:50],
                            )
                        return False

                    if allow_duplicate and debug_enabled:
                        log_debug(
                            "SEG_OUT",
                            "ℹ️ allow_duplicate=True – nur TTL-Cache geprüft",
                        )
        else:
            duplicate_skipped = True
            if debug_enabled:
                log_debug("SEG_OUT", "🚀 Duplikatprüfung komplett deaktiviert")

        t0 = time.perf_counter()
        try:
            callback(seg)
        except Exception as exc:
            duration_ms = (time.perf_counter() - t0) * 1000.0
            logger.error(
                "SEG_OUT: callback FAILED after %.1f ms for '%.50s': %s",
                duration_ms,
                seg_text[:50],
                exc,
                exc_info=True,
            )

            self._write_fallback_segment(start_ts, end_ts, seg_text, force_sync=True)

            if not disable_duplicate_check:
                with duplicate_lock:
                    cache.put(seg_text, True)
                    flushed_set.add(seg_text)
            return False

        if not disable_duplicate_check:
            with duplicate_lock:
                flushed_set.add(seg_text)

                if len(flushed_set) > 50000:
                    temp = list(flushed_set)

                    to_keep = temp[-25000:] if len(temp) > 25000 else temp
                    flushed_set.clear()
                    flushed_set.update(to_keep)
                    if debug_enabled:
                        log_debug(
                            "SEG_OUT",
                            "Duplikat‑Set auf %d Einträge reduziert",
                            len(flushed_set),
                        )
                cache.put(seg_text, True)

        duration_ms = (time.perf_counter() - t0) * 1000.0
        if duration_ms > 500.0:
            logger.warning(
                "SEG_OUT: SLOW callback (%.1f ms) for '%.50s'",
                duration_ms,
                seg_text[:50],
            )

        if not hasattr(self, "_output_counter"):
            self._output_counter = 0
        self._output_counter += 1
        if debug_enabled and self._output_counter % 100 == 0:
            log_debug(
                "SEG_OUT",
                f"📊 Bereits {self._output_counter} Segmente ausgegeben",
            )

        if debug_enabled and self._output_counter % 1000 == 0:
            try:
                size = cache.get_stats().get("size", 0)
                log_debug(
                    "SEG_OUT",
                    "TTL‑Cache size: %d / %d, Set size: %d",
                    size,
                    getattr(cache, "maxsize", 50000),
                    len(flushed_set),
                )
            except Exception:
                pass

        if (
            hasattr(self, "settings")
            and self.settings is not None
            and getattr(self.settings.config, "ENABLE_TIMED_TRANSCRIPTIONS", False)
        ):
            try:
                with getattr(self, "_subtitle_lock", nullcontext()):
                    if hasattr(self, "_timed_transcriptions"):
                        self._timed_transcriptions.append(seg)
            except Exception as exc:
                logger.error("SEG_OUT: failed to store timed transcription: %s", exc)

        if end_ts is not None:
            try:
                with getattr(self, "_last_output_timestamp_lock", nullcontext()):
                    if end_ts < getattr(self, "_last_output_timestamp", 0.0) - 0.1:
                        logger.warning(
                            "SEG_OUT: Time jump backward: %.2f → %.2f (text='%.50s')",
                            self._last_output_timestamp,
                            end_ts,
                            seg_text[:50],
                        )
                    elif end_ts > getattr(self, "_last_output_timestamp", 0.0):
                        self._last_output_timestamp = end_ts
            except Exception as exc:
                if debug_enabled:
                    log_debug("SEG_OUT", "Timestamp update failed: %s", exc)

        if debug_enabled and duplicate_skipped:
            log_debug("SEG_OUT", "✅ Segment ausgegeben (Duplikatprüfung aus)")

        return True

    def _fuzzy_duplicate(self, text: str, flushed_set: set) -> bool:
        """Prüft, ob der Text einem der letzten 50 Einträge ähnlich ist."""
        recent = list(flushed_set)[-50:] if flushed_set else []
        if not recent:
            return False

        if not hasattr(self, "_fuzz"):
            try:
                from rapidfuzz import fuzz

                self._fuzz = fuzz
            except ImportError:
                self._fuzz = None
                try:
                    import difflib

                    self._difflib = difflib
                except ImportError:
                    self._difflib = None

        if self._fuzz is not None:
            for existing in recent:
                if self._fuzz.ratio(text, existing) > 90:
                    log_debug(
                        "SEG_OUT",
                        "Fuzzy‑Duplikat (rapidfuzz): %.1f%%",
                        self._fuzz.ratio(text, existing),
                    )
                    return True
        elif self._difflib is not None:
            for existing in recent:
                if self._difflib.SequenceMatcher(None, text, existing).ratio() > 0.9:
                    log_debug("SEG_OUT", "Fuzzy‑Duplikat (difflib)")
                    return True
        return False

    def _write_fallback_segment(
        self,
        start: float | None,
        end: float | None,
        text: str,
    ) -> None:
        """Schreibt ein verlorenes Segment als Textdatei (im Hintergrund)."""

        def _write():
            try:
                import tempfile

                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")[:-3]
                fallback_path = os.path.join(
                    tempfile.gettempdir(),
                    f"segment_fallback_{timestamp}.txt",
                )
                with open(fallback_path, "w", encoding="utf-8") as f:
                    f.write(f"Start: {start}\nEnd: {end}\nText: {text}\n")
                log_debug("SEG_OUT", f"Fallback-Datei geschrieben: {fallback_path}")
            except Exception as exc:
                log_debug("SEG_OUT", f"Fallback-Datei fehlgeschlagen: {exc}")

        threading.Thread(
            target=_write,
            daemon=True,
            name="SegmentFallbackWriter",
        ).start()

    def _is_text_already_flushed(self, text: str) -> bool:
        """Prüft, ob ein Text bereits ausgegeben wurde (Duplikatprüfung)."""
        if not text or not isinstance(text, str):
            return False

        clean_text = text.strip()
        if not clean_text:
            return False

        if not hasattr(self, "_duplicate_lock"):
            self._duplicate_lock = threading.RLock()

        with self._duplicate_lock:
            if not hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts = set()

            flushed_set = self._already_flushed_texts

            if clean_text in flushed_set:
                if "duplicate" in DEBUG_COMPONENTS:
                    log_debug(
                        "duplicate",
                        f"Exaktes Duplikat erkannt: {clean_text[:50]}...",
                    )
                return True

            if (
                hasattr(self, "_already_flushed_cache")
                and self._already_flushed_cache is not None
            ):
                cached = self._already_flushed_cache.get(clean_text)
                if cached is not None:
                    if "duplicate" in DEBUG_COMPONENTS:
                        log_debug(
                            "duplicate",
                            f"TTL‑Cache‑Duplikat erkannt: {clean_text[:50]}...",
                        )
                    return True

            return False

    def _transcribe_with_timeout(
        self,
        audio_data: bytes,
        timeout: float | None = None,
        *,
        cancel_event: threading.Event | None = None,
    ) -> list[TranscriptionResult]:
        """Transkribiert einen Audio‑Chunk mit dynamischem Zeitlimit und Fallback‑Strategie."""
        if not self.is_processing() or self._stop_event.is_set():
            _safe_log_debug(
                "transcribe",
                "Abbruch: Processor nicht aktiv oder Stop‑Event gesetzt (%d Bytes verworfen).",
                len(audio_data) if audio_data else 0,
            )
            return []

        if not audio_data:
            _safe_log_debug("transcribe", "Leerer Audio‑Chunk – keine Transkription.")
            return []

        engine = self.transcription_engine
        if engine is None:
            logger.warning(
                "_transcribe_with_timeout: Keine Transkriptions‑Engine gesetzt.",
            )
            return []

        bytes_per_sec = max(1, self.settings.config.BYTES_PER_SECOND)
        chunk_duration = len(audio_data) / bytes_per_sec

        if timeout is None:
            with self._stats_lock:
                rt_factor = max(1.0, self._last_realtime_factor)
            dynamic_timeout = max(60.0, min(600.0, chunk_duration * 5.0 * rt_factor))
            _safe_log_debug(
                "transcribe",
                "Dynamic timeout: %.1f s (chunk=%.2f s, rt=%.2f)",
                dynamic_timeout,
                chunk_duration,
                rt_factor,
            )
        else:
            dynamic_timeout = timeout

        MAX_REINIT_ATTEMPTS = 3
        reinit_attempts = 0

        def _ensure_executor() -> ThreadPoolExecutor | None:
            nonlocal reinit_attempts
            executor = self._transcribe_timeout_executor
            if executor is not None and not getattr(executor, "_shutdown", False):
                return executor

            if not hasattr(self, "_timeout_executor_reinit_lock"):
                self._timeout_executor_reinit_lock = threading.Lock()

            with self._timeout_executor_reinit_lock:
                executor = self._transcribe_timeout_executor
                if executor is not None and not getattr(executor, "_shutdown", False):
                    return executor

                reinit_attempts += 1
                if reinit_attempts > MAX_REINIT_ATTEMPTS:
                    logger.error(
                        "_transcribe_with_timeout: Konnte Timeout‑Executor nach %d Versuchen nicht initialisieren.",
                        MAX_REINIT_ATTEMPTS,
                    )
                    return None

                logger.warning(
                    "Timeout‑Executor ist None – starte Neuinitialisierung (%d/%d).",
                    reinit_attempts,
                    MAX_REINIT_ATTEMPTS,
                )
                self._cleanup_timeout_executor(force=True)
                self._init_transcribe_timeout_executor()
                return self._transcribe_timeout_executor

        executor = _ensure_executor()
        if executor is None:
            self._save_lost_chunk(audio_data, "no_timeout_executor")
            return []

        effective_cancel = cancel_event or threading.Event()
        future: Future | None = None
        start_time = time.perf_counter()

        try:
            try:
                import inspect

                sig = inspect.signature(engine.transcribe_audio)
                supports_cancel = "cancel_event" in sig.parameters
            except Exception:
                supports_cancel = False

            if supports_cancel:
                future = executor.submit(
                    engine.transcribe_audio,
                    audio_data,
                    include_timestamps=True,
                    cancel_event=effective_cancel,
                )
            else:
                future = executor.submit(
                    engine.transcribe_audio,
                    audio_data,
                    include_timestamps=True,
                )

            self._register_timeout_future(future)
            _safe_log_debug("transcribe", "Task submitted to Timeout‑Executor.")

        except RuntimeError:
            logger.exception("_transcribe_with_timeout: Konnte Task nicht einreichen.")
            self._save_lost_chunk(audio_data, "submit_failed")
            return []

        try:
            result = future.result(timeout=dynamic_timeout)
            duration = time.perf_counter() - start_time

            with self._stats_lock:
                self._consecutive_timeouts = 0

            seg_count = len(result) if result else 0
            _safe_log_debug(
                "whisper",
                "Transkription erfolgreich – Dauer=%.2fs, Segmente=%d, Chunk=%.2fs, RT=%.2f",
                duration,
                seg_count,
                chunk_duration,
                duration / chunk_duration if chunk_duration > 0 else 0,
            )
            return result or []

        except FutureTimeout:
            effective_cancel.set()
            _safe_log_debug("transcribe", "Cancel‑Event gesetzt (Timeout).")

            with self._stats_lock:
                self._consecutive_timeouts += 1
                consecutive = self._consecutive_timeouts

            cancelled = future.cancel()
            if not cancelled:
                _safe_log_debug(
                    "transcribe",
                    "Future.cancel() konnte die Aufgabe nicht stoppen.",
                )

            logger.warning(
                "Transkriptions‑Timeout nach %.1fs (Chunk=%.2fs, consecutive=%d).",
                dynamic_timeout,
                chunk_duration,
                consecutive,
            )

            fallback_cancel = threading.Event()
            try:
                fallback_lang = getattr(engine, "forced_language", None)
                fallback_start = time.perf_counter()
                fallback_result = engine.transcribe_with_language(
                    audio_data,
                    language=fallback_lang,
                    include_timestamps=True,
                    cancel_event=fallback_cancel,
                )
                fallback_duration = time.perf_counter() - fallback_start
                if fallback_result:
                    seg_count = len(fallback_result)
                    logger.info(
                        "✅ Fallback‑Transkription nach Timeout erfolgreich (%d Segmente, %.2fs).",
                        seg_count,
                        fallback_duration,
                    )
                    with self._stats_lock:
                        self._consecutive_timeouts = 0
                    _safe_log_debug(
                        "whisper",
                        "Fallback erfolgreich – Dauer=%.2fs, Segmente=%d",
                        fallback_duration,
                        seg_count,
                    )
                    return fallback_result
                logger.warning(
                    "Fallback‑Transkription nach Timeout lieferte keine Ergebnisse.",
                )
            except Exception:
                logger.exception("Fehler in Fallback‑Transkription nach Timeout:")

            self._save_lost_chunk(audio_data, "timeout_fallback_failed")

            if consecutive >= 3:
                logger.warning(
                    "Drei aufeinanderfolgende Timeouts – Executor wird neu gestartet.",
                )
                self._cleanup_timeout_executor(force=True)
                self._init_transcribe_timeout_executor()
                with self._stats_lock:
                    self._consecutive_timeouts = 0

            return []

        except Exception as exc:
            effective_cancel.set()
            logger.exception(
                "Transkriptions‑Task fehlgeschlagen: %s",
                type(exc).__name__,
            )
            self._save_lost_chunk(audio_data, "exception_in_transcription")
            return []

        finally:
            if future is not None:
                self._unregister_timeout_future(future)

    def _process_audio_data(
        self,
        audio_data: bytes,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
        error_callback: ErrorCallback,
        info_callback: InfoCallback | None = None,
    ) -> None:
        """Verarbeitet einen Audio-Chunk asynchron und leitet ihn in die Pipeline.

        v2 mit:
        - Thread-sicherer Chunk-ID-Vergabe (Lock)
        - Strukturierten Phase-Timings
        - Thread-Kontext im Log
        - Defensivem Callback-Handling

        v3 (Fix #3):
        - Redundanter `_invoke_transcription_callback`-Aufruf entfernt.
          Der Callback wird bereits in `_perform_transcription_with_fallback`
          gefeuert, das über `_perform_chunk_transcription` aufgerufen wird.
        """
        import hashlib
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        thread_name = threading.current_thread().name

        import sys

        print(
            f"[PROC-DIAG] ENTER thread={thread_name} "
            f"debug_level={debug_level} bytes={len(audio_data)}",
            file=sys.stderr,
            flush=True,
        )

        stop_event = self._stop_event
        stats_lock = self._stats_lock
        event_bus = self._event_bus
        last_chunk_hashes = getattr(self, "_last_chunk_hashes", None)
        phase_times: dict[str, float] = {}
        _phase_t0 = time.perf_counter()

        def _mark_phase(name: str) -> None:
            nonlocal _phase_t0
            now = time.perf_counter()
            phase_times[name] = round((now - _phase_t0) * 1000.0, 2)
            _phase_t0 = now

        start_time = time.perf_counter()

        lock = getattr(self, "_chunk_counter_lock", None)
        if lock is None:
            lock = threading.Lock()
            with contextlib.suppress(Exception):
                self._chunk_counter_lock = lock
        with lock:
            self._chunk_counter += 1
            chunk_id = self._chunk_counter

        original_audio = audio_data
        processing_duration = 0.0
        chunk_duration = 0.0
        bytes_per_sec = (
            self.settings.config.BYTES_PER_SECOND
            if self.settings and hasattr(self.settings, "config")
            else 32000
        )

        if debug_level >= 3:
            logger.debug(
                "[PROCESSOR] #%d enter (thread=%s, bytes=%d)",
                chunk_id,
                thread_name,
                len(audio_data),
                extra={"component": "processor", "chunk_id": chunk_id},
            )

        try:
            if (
                transcription_callback is None
                or translation_callback is None
                or error_callback is None
            ):
                _mark_phase("validate_callbacks")
                logger.error(
                    "[PROCESSOR] #%d critical callbacks missing "
                    "(trans=%s, transl=%s, err=%s) – discarding %d bytes",
                    chunk_id,
                    transcription_callback is not None,
                    translation_callback is not None,
                    error_callback is not None,
                    len(audio_data) if audio_data else 0,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )
                self._save_lost_chunk(audio_data, "missing_callbacks")
                return
            _mark_phase("validate_callbacks")

            if debug_level >= 4:
                logger.debug(
                    "[PROCESSOR] #%d callbacks OK",
                    chunk_id,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            if not self._validate_chunk_prerequisites(audio_data):
                _mark_phase("validate_prerequisites")
                if debug_level >= 4:
                    logger.debug(
                        "[PROCESSOR] #%d prerequisites failed",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return
            _mark_phase("validate_prerequisites")

            chunk_info = self._prepare_chunk(audio_data, error_callback)
            if chunk_info is None:
                _mark_phase("prepare_chunk")
                if debug_level >= 3:
                    logger.debug(
                        "[PROCESSOR] #%d preparation failed",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return

            bytes_per_sec = chunk_info["bytes_per_sec"]
            original_audio = chunk_info["original_audio"]
            chunk_duration = chunk_info["chunk_duration"]
            absolute_offset = chunk_info.get("absolute_offset", 0.0)
            _mark_phase("prepare_chunk")

            if debug_level >= 4:
                logger.debug(
                    "[PROCESSOR] #%d prepared (duration=%.2fs, offset=%.3fs)",
                    chunk_id,
                    chunk_duration,
                    absolute_offset,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            if stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[PROCESSOR] #%d stop event after preparation",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return

            transcription_result = self._perform_chunk_transcription(
                chunk_info,
                error_callback,
                chunk_id=chunk_id,
            )
            _mark_phase("transcribe")

            if transcription_result is None:
                if debug_level >= 3:
                    logger.debug(
                        "[PROCESSOR] #%d transcription failed",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return

            processing_duration = transcription_result["processing_duration"]
            segments = transcription_result["segments"]

            if debug_level >= 4:
                logger.debug(
                    "[PROCESSOR] #%d transcribe OK (%d segs, %.3fs)",
                    chunk_id,
                    len(segments),
                    processing_duration,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            if stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[PROCESSOR] #%d stop event after transcription",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return

            _mark_phase("invoke_transcription_callback")

            self._handle_chunk_result(
                chunk_info,
                transcription_result,
                transcription_callback,
                translation_callback,
            )
            _mark_phase("handle_chunk_result")

            if debug_level >= 3:
                rt = processing_duration / chunk_duration if chunk_duration > 0 else 0.0
                total_ms = (time.perf_counter() - start_time) * 1000.0
                logger.debug(
                    "[PROCESSOR] #%d success (rt=%.2fx, segs=%d, t=%.0fms, phases=%s)",
                    chunk_id,
                    rt,
                    len(segments),
                    total_ms,
                    phase_times,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

        except Exception as e:
            elapsed_ms = (time.perf_counter() - start_time) * 1000.0
            logger.exception(
                "[PROCESSOR] #%d critical error after %.0fms "
                "(duration=%.2fs, offset=%.3fs): %s",
                chunk_id,
                elapsed_ms,
                chunk_duration,
                (
                    chunk_info.get("absolute_offset", 0.0)
                    if "chunk_info" in locals() and chunk_info
                    else 0.0
                ),
                e,
                extra={"component": "processor", "chunk_id": chunk_id},
            )
            self._save_lost_chunk(original_audio, f"critical_error_chunk_{chunk_id}")

            try:
                if error_callback is not None:
                    error_callback(
                        f"Kritischer Fehler in Chunk {chunk_id}: {str(e)[:100]}",
                    )
            except Exception as cb_err:
                logger.error(
                    "[PROCESSOR] #%d error_callback itself failed: %s",
                    chunk_id,
                    cb_err,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            if event_bus is not None:
                try:
                    event_bus.emit(
                        "chunk_processing_error",
                        {
                            "chunk_id": chunk_id,
                            "error": str(e)[:200],
                            "audio_len": len(original_audio),
                            "phase_times": phase_times,
                        },
                    )
                except Exception as bus_err:
                    if debug_level >= 3:
                        logger.debug(
                            "[PROCESSOR] #%d event_bus emit failed: %s",
                            chunk_id,
                            bus_err,
                            extra={"component": "processor", "chunk_id": chunk_id},
                        )

        finally:
            try:
                with stats_lock:
                    self._total_bytes_processed += len(original_audio)
                    self._processed_seconds = self._total_bytes_processed / max(
                        1,
                        bytes_per_sec,
                    )
                    self._real_processed_seconds = self._processed_seconds
            except Exception as stat_exc:
                if debug_level >= 3:
                    logger.debug(
                        "[PROCESSOR] #%d stats update failed: %s",
                        chunk_id,
                        stat_exc,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )

            if last_chunk_hashes is not None and original_audio:
                try:
                    chunk_hash = hashlib.sha256(original_audio).digest()
                    last_chunk_hashes.append((chunk_hash, time.monotonic()))
                    if len(last_chunk_hashes) > 100:
                        last_chunk_hashes.popleft()
                except Exception:
                    pass

            if processing_duration > chunk_duration * 10 and chunk_duration > 0:
                if debug_level >= 3:
                    rt = processing_duration / chunk_duration
                    logger.debug(
                        "[PROCESSOR] #%d extreme overload – sleeping 10ms (rt=%.1fx)",
                        chunk_id,
                        rt,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                time.sleep(0.01)

            if debug_level >= 4:
                total_ms = (time.perf_counter() - start_time) * 1000.0
                logger.debug(
                    "[PROCESSOR] #%d exit (t=%.0fms, phases=%s)",
                    chunk_id,
                    total_ms,
                    phase_times,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

    def _validate_chunk_prerequisites(self, audio_data: bytes) -> bool:
        """Prüft, ob der Audio‑Chunk grundlegende Anforderungen für die Verarbeitung erfüllt."""
        if self._stop_event.is_set() or not self.is_processing():
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "processor",
                    "Chunk discarded: processor inactive (stop_event=%s, processing=%s)",
                    self._stop_event.is_set(),
                    self.is_processing(),
                )
            return False
        data_len = len(audio_data) if audio_data else 0
        min_bytes = getattr(self, "MIN_CHUNK_BYTES", 16)
        if data_len < min_bytes:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "processor",
                    f"Chunk too short: {data_len} bytes < {min_bytes} bytes, ignored",
                )
            return False
        return True

    def _prepare_chunk(
        self,
        audio_data: bytes,
        error_callback: ErrorCallback,
    ) -> dict | None:
        config = self.settings.config
        nominal_bps = max(1, config.BYTES_PER_SECOND)

        self._init_adaptive_rate(nominal_bps)
        bytes_per_sec = self._get_adaptive_bytes_per_sec(nominal_bps)

        audio_data, overlap_duration, original_length = self._apply_overlap(
            audio_data,
            config,
        )
        if DEBUG_LEVEL >= 4:
            log_debug(
                "overlap",
                f"Overlap applied: overlap_duration={overlap_duration:.3f}s, "
                f"original_len={original_length}, new_len={len(audio_data)}",
            )

        offset_info = self._compute_chunk_offset(
            audio_data=audio_data,
            bytes_per_sec=bytes_per_sec,
            overlap_duration=overlap_duration,
            config=config,
        )
        if offset_info is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    "Chunk discarded after offset computation (too short)",
                )
            return None

        enhanced_audio = self._apply_audio_enhancement(audio_data)

        if self._stop_event.is_set():
            if DEBUG_LEVEL >= 3:
                log_debug("processor", "Stop event set after enhancement – aborting")
            return None

        rt_factor = max(1.0, self._last_realtime_factor)
        is_cpu_mode = getattr(config, "_is_cpu_mode", False)
        chunk_duration = offset_info["chunk_duration"]
        base_timeout = max(20.0, chunk_duration * (1.5 if is_cpu_mode else 3.0))
        dynamic_timeout = min(180.0, max(10.0, base_timeout * rt_factor))

        if DEBUG_LEVEL >= 3:
            log_debug(
                "timeout",
                f"Chunk #{self._chunk_counter + 1}: timeout={dynamic_timeout:.1f}s (rt={rt_factor:.2f})",
            )

        return {
            "audio_data": enhanced_audio,
            "bytes_per_sec": bytes_per_sec,
            "overlap_duration": overlap_duration,
            "absolute_offset": offset_info["absolute_offset"],
            "chunk_duration": chunk_duration,
            "max_allowed_offset": offset_info["max_allowed_offset"],
            "rt_factor": rt_factor,
            "dynamic_timeout": dynamic_timeout,
            "config": config,
            "original_audio": audio_data,
        }

    def _init_adaptive_rate(self, nominal_bps: int) -> None:
        if not hasattr(self, "_adaptive_bytes_per_sec"):
            self._adaptive_bytes_per_sec = float(nominal_bps)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "adaptive_rate",
                    f"Adaptive Rate init: {self._adaptive_bytes_per_sec:.0f} B/s",
                )
        if not hasattr(self, "_adaptive_warmup_chunks"):
            self._adaptive_warmup_chunks = 0

    def _get_adaptive_bytes_per_sec(self, nominal_bps: int) -> int:
        self._adaptive_warmup_chunks += 1
        use_adaptive = self._adaptive_warmup_chunks > 5
        if use_adaptive and self._adaptive_bytes_per_sec > 0:
            deviation = abs(self._adaptive_bytes_per_sec - nominal_bps) / max(
                1,
                nominal_bps,
            )
            if deviation > 0.05:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "adaptive_rate",
                        f"Chunk #{self._chunk_counter + 1}: adaptive rate {self._adaptive_bytes_per_sec:.0f} B/s",
                    )
                return int(self._adaptive_bytes_per_sec)
        return nominal_bps

    def _perform_chunk_transcription(
        self,
        chunk_info: dict,
        error_callback: ErrorCallback,
        chunk_id: int | None = None,
    ) -> dict | None:
        """Führt die Transkription eines vorbereiteten Chunks durch."""
        import logging
        import threading
        import time

        logger = logging.getLogger("dragon")
        debug_level = DEBUG_LEVEL
        thread_name = threading.current_thread().name

        if chunk_id is None:
            lock = getattr(self, "_chunk_counter_lock", None)
            if lock is None:
                lock = threading.Lock()
                with contextlib.suppress(Exception):
                    self._chunk_counter_lock = lock
            with lock:
                self._chunk_counter += 1
                chunk_id = self._chunk_counter

        trans_engine = self._transcription_engine
        if trans_engine is None or not trans_engine.is_functional():
            logger.error(
                "[PERF-CHUNK] #%d transcription engine unavailable – chunk saved",
                chunk_id,
                extra={"component": "processor", "chunk_id": chunk_id},
            )
            self._save_lost_chunk(chunk_info["original_audio"], "engine_unavailable")
            return None

        start_time = time.perf_counter()

        if debug_level >= 4:
            logger.debug(
                "[PERF-CHUNK] #%d start (thread=%s, audio=%d bytes, timeout=%.1fs)",
                chunk_id,
                thread_name,
                len(chunk_info.get("audio_data", b"")),
                chunk_info.get("dynamic_timeout", 0.0),
                extra={"component": "processor", "chunk_id": chunk_id},
            )

        try:
            segments, task_failed = self._perform_transcription_with_fallback(
                chunk_id=chunk_id,
                audio_data=chunk_info["audio_data"],
                trans_engine=trans_engine,
                dynamic_timeout=chunk_info["dynamic_timeout"],
                error_callback=error_callback,
            )

            if self._stop_event.is_set():
                if debug_level >= 3:
                    logger.debug(
                        "[PERF-CHUNK] #%d stop event after transcription – aborting",
                        chunk_id,
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )
                return None

            valid_segments = self._validate_and_clean_segments(
                chunk_id=chunk_id,
                segments=segments,
                trans_engine=trans_engine,
            )

            processing_duration = time.perf_counter() - start_time

            if debug_level >= 3:
                logger.debug(
                    "[PERF-CHUNK] #%d transcribe+validate: %.3fs "
                    "(%d raw → %d valid, failed=%s)",
                    chunk_id,
                    processing_duration,
                    len(segments),
                    len(valid_segments),
                    task_failed,
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            if not valid_segments:
                if task_failed:
                    self._save_lost_chunk(
                        chunk_info["original_audio"],
                        f"transcription_failed_chunk_{chunk_id}",
                    )
                    if debug_level >= 2:
                        logger.warning(
                            "[PERF-CHUNK] #%d transcription failed – chunk saved",
                            chunk_id,
                            extra={"component": "processor", "chunk_id": chunk_id},
                        )
                elif debug_level >= 3:
                    logger.debug(
                        "[PERF-CHUNK] #%d no valid segments "
                        "(likely silence/noise, raw=%d)",
                        chunk_id,
                        len(segments),
                        extra={"component": "processor", "chunk_id": chunk_id},
                    )

                self._update_realtime_factor(
                    chunk_info["chunk_duration"],
                    processing_duration,
                )
                return None

            if debug_level >= 4:
                rt = (
                    processing_duration / chunk_info["chunk_duration"]
                    if chunk_info.get("chunk_duration", 0.0) > 0
                    else 0.0
                )
                logger.debug(
                    "[PERF-CHUNK] #%d OK (%.3fs, rt=%.2fx, segs=%d)",
                    chunk_id,
                    processing_duration,
                    rt,
                    len(valid_segments),
                    extra={"component": "processor", "chunk_id": chunk_id},
                )

            return {
                "segments": valid_segments,
                "processing_duration": processing_duration,
                "chunk_id": chunk_id,
                "task_failed": task_failed,
            }

        except Exception as e:
            elapsed_ms = (time.perf_counter() - start_time) * 1000.0
            logger.error(
                "[PERF-CHUNK] #%d exception after %.0fms "
                "(duration=%.2fs, offset=%.3fs): %s",
                chunk_id,
                elapsed_ms,
                chunk_info.get("chunk_duration", 0.0),
                chunk_info.get("absolute_offset", 0.0),
                e,
                exc_info=debug_level >= 3,
                extra={"component": "processor", "chunk_id": chunk_id},
            )

            self._handle_chunk_exception(
                chunk_id=chunk_id,
                audio_data=chunk_info["original_audio"],
                error=e,
                trans_engine=trans_engine,
                chunk_duration=chunk_info["chunk_duration"],
                absolute_offset=chunk_info["absolute_offset"],
                rt_factor=chunk_info["rt_factor"],
                dynamic_timeout=chunk_info["dynamic_timeout"],
                error_callback=error_callback,
            )
            return None

    def _handle_chunk_result(
        self,
        chunk_info: dict,
        transcription_result: dict,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
    ) -> None:
        chunk_id = transcription_result["chunk_id"]
        valid_segments = transcription_result["segments"]
        processing_duration = transcription_result["processing_duration"]
        chunk_duration = chunk_info["chunk_duration"]

        try:
            self._apply_timestamps(
                valid_segments,
                chunk_info["absolute_offset"],
                chunk_info["overlap_duration"],
                chunk_info["max_allowed_offset"],
            )
        except Exception as e:
            logger.error(
                f"Chunk #{chunk_id}: timestamp application failed: {e}",
                exc_info=DEBUG_LEVEL >= 3,
            )
            self._apply_timestamps(valid_segments, 0.0, 0.0, None)

        try:
            self._dispatch_segments(
                chunk_id=chunk_id,
                segments=valid_segments,
                transcription_callback=transcription_callback,
                translation_callback=translation_callback,
            )
        except Exception as e:
            logger.error(
                f"Chunk #{chunk_id}: dispatch failed: {e}",
                exc_info=DEBUG_LEVEL >= 3,
            )
            self._save_lost_chunk(
                chunk_info["original_audio"],
                f"dispatch_error_chunk_{chunk_id}",
            )

        self._update_realtime_factor(chunk_duration, processing_duration)

        if processing_duration > chunk_duration * 2.0:
            self._slow_chunks += 1
            if DEBUG_LEVEL >= 2 and processing_duration > chunk_duration * 4.0:
                log_debug(
                    "perf_warn",
                    f"Chunk #{chunk_id}: EXTREM langsam: {processing_duration:.2f}s vs {chunk_duration:.2f}s",
                )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "performance",
                f"Chunk #{chunk_id}: OK – {processing_duration:.2f}s, RT={processing_duration / chunk_duration:.2f}, "
                f"seg={len(valid_segments)}",
            )

    def _compute_chunk_offset(
        self,
        audio_data: bytes,
        bytes_per_sec: float,
        overlap_duration: float,
        config: Config,
    ) -> dict[str, Any] | None:
        """Berechnet den absoluten Offset, die Chunk-Dauer und kürzt ggf. den Chunk.
        Gibt ein Dictionary mit den benötigten Werten zurück oder None, wenn der Chunk verworfen werden soll.
        """
        if not hasattr(self, "_monotonic_offset"):
            self._monotonic_offset = 0.0

        monotonic_offset = self._monotonic_offset
        expected_duration = self._expected_duration
        tolerance = max(1.0, getattr(self.settings, "duration_tolerance", 5.0))

        with self._stats_lock:
            total_bytes = self._total_bytes_processed

        current_offset = total_bytes / max(1, bytes_per_sec)
        if overlap_duration > 0.0:
            current_offset = max(0.0, current_offset - overlap_duration)

        if current_offset < monotonic_offset:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "offset",
                    f"Offset korrigiert (monoton): {monotonic_offset:.3f} → {
                        current_offset:.3f}",
                )
            current_offset = monotonic_offset

        max_allowed_offset = None
        if expected_duration is not None and expected_duration > 0:
            max_allowed_offset = expected_duration + tolerance
            if current_offset > max_allowed_offset:
                if DEBUG_LEVEL >= 1:
                    log_debug(
                        "offset",
                        f"Überschreitung: {current_offset:.3f}s > {
                            max_allowed_offset:.3f}s – passe erwartete Dauer an",
                    )
                with self._stats_lock:
                    self._expected_duration = current_offset + tolerance
                expected_duration = self._expected_duration
                max_allowed_offset = expected_duration + tolerance

        raw_length = len(audio_data) - config.OVERLAP_SIZE_BYTES
        chunk_duration = raw_length / bytes_per_sec
        chunk_end = current_offset + chunk_duration

        if max_allowed_offset is not None and chunk_end > max_allowed_offset:
            new_duration = max(0.1, max_allowed_offset - current_offset)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "offset",
                    f"Chunk gekürzt: {chunk_duration:.2f}s → {new_duration:.2f}s",
                )
            chunk_duration = new_duration
            new_len = int(chunk_duration * bytes_per_sec)
            if new_len < len(audio_data):
                audio_data = audio_data[:new_len]
                if len(audio_data) < 16:
                    if DEBUG_LEVEL >= 3:
                        log_debug("offset", "Chunk nach Kürzung zu kurz – verworfen")
                    return None

        absolute_offset = max(0.0, current_offset)

        new_monotonic = absolute_offset + chunk_duration - 0.001
        if max_allowed_offset is not None:
            new_monotonic = min(new_monotonic, max_allowed_offset)
        if new_monotonic > monotonic_offset:
            self._monotonic_offset = new_monotonic

        if DEBUG_LEVEL >= 3:
            log_debug(
                "offset_debug",
                f"offset={absolute_offset:.3f}s, dur={
                    chunk_duration:.2f}s, bytes_per_sec={bytes_per_sec:.0f}",
            )

        return {
            "absolute_offset": absolute_offset,
            "chunk_duration": chunk_duration,
            "max_allowed_offset": max_allowed_offset,
            "audio_data": audio_data,
        }

    def _apply_timestamps(
        self,
        segments: list[TranscriptionResult],
        offset: float,
        overlap: float,
        max_end: float | None,
    ) -> None:
        """Wendet absolute Zeitstempel auf eine Segmentliste an."""
        for seg in segments:
            if overlap > 0.0:
                if seg.start is not None:
                    seg.start = max(0.0, seg.start - overlap)
                if seg.end is not None:
                    seg.end = max(0.0, seg.end - overlap)

            if seg.start is not None:
                seg.start += offset
            if seg.end is not None:
                seg.end += offset

            if max_end is not None:
                if seg.start is not None and seg.start > max_end:
                    seg.start = max_end
                if seg.end is not None and seg.end > max_end:
                    seg.end = max_end

            if seg.start is not None and seg.start < 0.0:
                seg.start = 0.0
            if seg.end is not None and seg.end < 0.0:
                seg.end = 0.0

    def _handle_critical_chunk_error(
        self,
        chunk_id: int,
        audio_data: bytes,
        error: Exception,
        trans_engine: Any,
        chunk_duration: float,
        absolute_offset: float,
        rt_factor: float,
        dynamic_timeout: float,
        error_callback: ErrorCallback,
    ) -> None:
        """Zentrale Fehlerbehandlung für kritische Chunk‑Fehler."""
        logger.exception("❌ CRITICAL error in chunk %d: %s", chunk_id, error)

        with self._pending_tasks_cond:
            pending_tasks = self._pending_tasks

        diag_info = {
            "chunk_id": chunk_id,
            "audio_len": len(audio_data),
            "forced_language": getattr(trans_engine, "forced_language", "N/A"),
            "device": getattr(trans_engine, "device", "N/A"),
            "compute_type": getattr(trans_engine, "compute_type", "N/A"),
            "chunk_duration": chunk_duration,
            "offset": absolute_offset,
            "queue_size": (
                self._raw_audio_queue.qsize() if self._raw_audio_queue else -1
            ),
            "pending_tasks": pending_tasks,
            "dispatcher_alive": (
                self._dispatcher_thread.is_alive() if self._dispatcher_thread else False
            ),
            "stop_event_set": self._stop_event.is_set(),
            "rt_factor": rt_factor,
            "dynamic_timeout": dynamic_timeout,
        }
        logger.debug("Diagnose für Chunk %d: %s", chunk_id, diag_info)

        try:
            self._save_lost_chunk(audio_data, f"critical_error_chunk_{chunk_id}")
        except Exception as save_err:
            logger.warning("Konnte verlorenen Chunk nicht sichern: %s", save_err)

        if error_callback:
            try:
                error_callback(
                    f"❌ Verarbeitungsfehler in Chunk {chunk_id}: {str(error)[:100]}",
                )
            except Exception as cb_err:
                logger.error("Fehler im error_callback: %s", cb_err)

        if not self._dispatcher_shutdown.is_set():
            qsize = self._raw_audio_queue.qsize() if self._raw_audio_queue else 0
            dispatcher_dead = not (
                self._dispatcher_thread and self._dispatcher_thread.is_alive()
            )
            if qsize > 100 or dispatcher_dead:
                logger.warning(
                    "Dispatcher möglicherweise defekt (queue=%d, alive=%s) – starte Neustart",
                    qsize,
                    not dispatcher_dead,
                )
                self._restart_dispatcher()

            error_lower = str(error).lower()
            if "out of memory" in error_lower or "cuda" in error_lower:
                logger.warning(
                    "CUDA OOM oder schwerwiegender GPU-Fehler – versuche Engine-Reset",
                )
                if hasattr(trans_engine, "_force_model_cleanup"):
                    trans_engine._force_model_cleanup()
                if hasattr(trans_engine, "_set_oom"):
                    trans_engine._set_oom()

        if self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "chunk_processing_error",
                    {
                        "chunk_id": chunk_id,
                        "error": str(error)[:200],
                        "queue_size": qsize if "qsize" in locals() else -1,
                        "pending_tasks": pending_tasks,
                    },
                )
            except Exception as bus_err:
                log_debug("event_bus", "Event-Bus Fehler: %s", bus_err)

    def _handle_chunk_exception(
        self,
        chunk_id: int,
        audio_data: bytes,
        error: Exception,
        trans_engine: Any,
        chunk_duration: float,
        absolute_offset: float,
        rt_factor: float,
        dynamic_timeout: float,
        error_callback: ErrorCallback,
    ) -> None:
        """Zentrale Fehlerbehandlung für einen Chunk."""
        logger.error(
            f"❌ CRITICAL error in chunk {chunk_id}: {type(error).__name__}: {error}",
        )

        diag_info = {
            "chunk_id": chunk_id,
            "audio_len": len(audio_data),
            "forced_language": getattr(trans_engine, "forced_language", "N/A"),
            "device": getattr(trans_engine, "device", "N/A"),
            "compute_type": getattr(trans_engine, "compute_type", "N/A"),
            "chunk_duration": chunk_duration,
            "offset": absolute_offset,
            "queue_size": (
                self._raw_audio_queue.qsize() if self._raw_audio_queue else -1
            ),
            "pending_tasks": self._pending_tasks,
            "dispatcher_alive": (
                self._dispatcher_thread.is_alive() if self._dispatcher_thread else False
            ),
            "stop_event_set": self._stop_event.is_set(),
            "rt_factor": rt_factor,
            "dynamic_timeout": dynamic_timeout,
        }
        logger.debug(f"Diagnose für Chunk {chunk_id}: {diag_info}")

        try:
            self._save_lost_chunk(audio_data, f"critical_error_chunk_{chunk_id}")
        except Exception as save_err:
            logger.warning(f"Konnte verlorenen Chunk nicht sichern: {save_err}")

        if error_callback:
            try:
                error_callback(
                    f"❌ Verarbeitungsfehler in Chunk {chunk_id}: {str(error)[:100]}",
                )
            except Exception as cb_err:
                logger.error(f"Fehler im error_callback: {cb_err}")

        if not self._dispatcher_shutdown.is_set():
            qsize = self._raw_audio_queue.qsize() if self._raw_audio_queue else 0
            dispatcher_dead = not (
                self._dispatcher_thread and self._dispatcher_thread.is_alive()
            )
            if qsize > 100 or dispatcher_dead:
                logger.warning(
                    f"Dispatcher möglicherweise defekt (queue={qsize}) – Neustart",
                )
                self._restart_dispatcher()

            if "out of memory" in str(error).lower() or "cuda" in str(error).lower():
                logger.warning("CUDA OOM – versuche Engine-Reset")
                if hasattr(trans_engine, "_force_model_cleanup"):
                    trans_engine._force_model_cleanup()
                if hasattr(trans_engine, "_set_oom"):
                    trans_engine._set_oom()

        if self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "chunk_processing_error",
                    {
                        "chunk_id": chunk_id,
                        "error": str(error)[:200],
                        "queue_size": qsize if "qsize" in locals() else -1,
                        "pending_tasks": self._pending_tasks,
                    },
                )
            except Exception as bus_err:
                logger.debug(f"Event-Bus Fehler: {bus_err}")

    def _is_duplicate_chunk(self, audio_data: bytes) -> bool:
        """Prüft, ob der Chunk ein Duplikat eines kürzlich verarbeiteten Chunks ist."""
        chunk_hash = hashlib.sha256(audio_data).digest()
        current_time = time.monotonic()

        with self._duplicate_lock:
            if not hasattr(self, "_last_chunk_hashes"):
                self._last_chunk_hashes = deque(maxlen=30)
                self._hash_cleanup_counter = 0

            for h, ts in self._last_chunk_hashes:
                if h == chunk_hash and (current_time - ts) < 5.0:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "processor",
                            "DUPLICATE CHUNK detected (within last 5s) – ignoring (%d bytes).",
                            len(audio_data),
                        )
                    return True

            self._last_chunk_hashes.append((chunk_hash, current_time))

            self._hash_cleanup_counter = getattr(self, "_hash_cleanup_counter", 0) + 1
            if self._hash_cleanup_counter >= 2000:
                old_len = len(self._last_chunk_hashes)
                trim_count = old_len // 2
                for _ in range(trim_count):
                    self._last_chunk_hashes.popleft()
                self._hash_cleanup_counter = 0
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "processor",
                        "Trimmed hash deque: %d → %d",
                        old_len,
                        len(self._last_chunk_hashes),
                    )

        return False

    def _is_silent_chunk(self, audio_data: bytes, chunk_duration: float) -> bool:
        """Prüft, ob der Chunk überwiegend Stille enthält (RMS‑Schwellwert)."""
        rms = self._compute_rms(audio_data)
        threshold = (
            self.SILENCE_RMS_THRESHOLD * 0.5
            if chunk_duration < 2.0
            else self.SILENCE_RMS_THRESHOLD
        )
        if rms is not None and rms < threshold:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "processor",
                    "Discarding silent chunk (rms=%.6f < %.6f, len=%d, dur=%.2fs)",
                    rms,
                    threshold,
                    len(audio_data),
                    chunk_duration,
                )
            return True
        return False

    def _apply_overlap(
        self,
        audio_data: bytes,
        config: Config,
    ) -> tuple[bytes, float, int]:
        """Wendet den Overlap des vorherigen Chunks an und speichert den neuen Tail."""
        with self._overlap_lock:
            original_length = len(audio_data)
            overlap_bytes = config.OVERLAP_SIZE_BYTES

            applied_overlap_bytes = 0
            if self._last_chunk_tail and overlap_bytes > 0 and original_length > 0:
                audio_data = self._last_chunk_tail + audio_data
                applied_overlap_bytes = len(self._last_chunk_tail)
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "overlap",
                        "Prepended %d overlap bytes, new total %d bytes",
                        applied_overlap_bytes,
                        len(audio_data),
                    )
            elif DEBUG_LEVEL >= 4 and overlap_bytes > 0:
                log_debug(
                    "overlap",
                    "No tail available or chunk too short, skipping overlap",
                )

            if overlap_bytes > 0 and len(audio_data) >= overlap_bytes:
                self._last_chunk_tail = audio_data[-overlap_bytes:]
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "overlap",
                        "Stored new tail of %d bytes",
                        len(self._last_chunk_tail),
                    )
            else:
                self._last_chunk_tail = b""
                if DEBUG_LEVEL >= 4:
                    log_debug("overlap", "Cleared tail (chunk too short or overlap=0)")

            overlap_duration = applied_overlap_bytes / max(1, config.BYTES_PER_SECOND)

            return audio_data, overlap_duration, original_length

    def _update_stats_and_offset(
        self,
        audio_data: bytes,
        original_length: int,
        overlap_duration: float,
        config: Config,
        bytes_per_sec: int,
    ) -> dict[str, Any]:
        """OFFSET-KORREKTUR mit adaptiver Rate und mehrstufiger Reset-Logik (v9.1 – ultimativ robust)."""
        if not hasattr(self, "HISTORY_LENGTH"):
            self.HISTORY_LENGTH = 20
        if not hasattr(self, "DRIFT_WARNING_THRESHOLD_SEC"):
            self.DRIFT_WARNING_THRESHOLD_SEC = 2.5
        if not hasattr(self, "HARD_RESET_THRESHOLD_SEC"):
            self.HARD_RESET_THRESHOLD_SEC = 25.0
        if not hasattr(self, "DELTA_DRIFT_THRESHOLD_SEC"):
            self.DELTA_DRIFT_THRESHOLD_SEC = 2.0
        if not hasattr(self, "MAX_CORRECTION_SEC_BASE"):
            self.MAX_CORRECTION_SEC_BASE = 3.0
        if not hasattr(self, "MAX_CORRECTION_SEC_MAX"):
            self.MAX_CORRECTION_SEC_MAX = 25.0
        if not hasattr(self, "CORRECTION_FACTOR_BASE"):
            self.CORRECTION_FACTOR_BASE = 0.9
        if not hasattr(self, "CORRECTION_FACTOR_MAX"):
            self.CORRECTION_FACTOR_MAX = 1.35
        if not hasattr(self, "ADAPTIVE_BPS_MIN_RATIO"):
            self.ADAPTIVE_BPS_MIN_RATIO = 0.35
        if not hasattr(self, "ADAPTIVE_BPS_MAX_RATIO"):
            self.ADAPTIVE_BPS_MAX_RATIO = 2.5
        if not hasattr(self, "ADAPTIVE_DRIFT_THRESHOLD_SEC"):
            self.ADAPTIVE_DRIFT_THRESHOLD_SEC = 1.8
        if not hasattr(self, "ADAPTIVE_BPS_BETA_MIN"):
            self.ADAPTIVE_BPS_BETA_MIN = 0.3
        if not hasattr(self, "ADAPTIVE_BPS_BETA_MAX"):
            self.ADAPTIVE_BPS_BETA_MAX = 0.6

        debug_enabled = DEBUG_LEVEL >= 3 or "drift" in DEBUG_COMPONENTS
        drift_id = (
            f"D{self._chunk_counter + 1:04d}"
            if hasattr(self, "_chunk_counter")
            else "D0001"
        )

        if debug_enabled:
            log_debug("drift", f"[{drift_id}] ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            log_debug(
                "drift",
                f"[{drift_id}] START: original_length={original_length}, overlap={overlap_duration:.3f}s",
            )

        if bytes_per_sec <= 0:
            logger.error(
                f"[{drift_id}] bytes_per_sec <= 0 ({bytes_per_sec}) – setze auf 1",
            )
            bytes_per_sec = 1

        if (
            not hasattr(self, "_adaptive_bytes_per_sec")
            or self._adaptive_bytes_per_sec <= 0
        ):
            self._adaptive_bytes_per_sec = float(bytes_per_sec)
            if debug_enabled:
                log_debug(
                    "drift",
                    f"[{drift_id}] 📊 Adaptive Rate initialisiert: {self._adaptive_bytes_per_sec:.0f} B/s",
                )

        if not hasattr(self, "_adaptive_warmup_chunks"):
            self._adaptive_warmup_chunks = 0
        self._adaptive_warmup_chunks += 1
        use_adaptive_rate = self._adaptive_warmup_chunks > 5

        if not hasattr(self, "_stats_lock"):
            self._stats_lock = threading.RLock()
        if not hasattr(self, "_drift_lock"):
            self._drift_lock = threading.RLock()

        nominal_bytes_per_sec = bytes_per_sec

        effective_bytes_per_sec = (
            self._adaptive_bytes_per_sec
            if (use_adaptive_rate and self._adaptive_bytes_per_sec > 0)
            else bytes_per_sec
        )
        if abs(effective_bytes_per_sec - bytes_per_sec) / max(1, bytes_per_sec) > 0.02:
            bytes_per_sec = effective_bytes_per_sec
            if debug_enabled:
                log_debug(
                    "drift",
                    f"[{drift_id}] 📊 Adaptive Rate aktiv: {bytes_per_sec:.0f} B/s (nominal: {nominal_bytes_per_sec:.0f})",
                )

        with self._stats_lock:
            offset_before = self._total_bytes_processed
            new_bytes = max(0, original_length - int(overlap_duration * bytes_per_sec))
            self._total_bytes_processed += new_bytes
            self._processed_seconds = self._total_bytes_processed / max(
                1,
                bytes_per_sec,
            )
            self._real_processed_seconds = self._processed_seconds
            chunks_count = self._chunk_counter
            total_bytes_processed = self._total_bytes_processed

        if debug_enabled:
            log_debug(
                "drift",
                f"[{drift_id}] stats: offset_before={offset_before}, new_bytes={new_bytes}, total={total_bytes_processed}",
            )

        processed_seconds = self._processed_seconds
        deterministic_offset = int(processed_seconds * bytes_per_sec)
        measured_offset = offset_before
        current_drift = measured_offset - deterministic_offset

        if chunks_count == 1 and not hasattr(self, "_initial_drift_correction"):
            if abs(current_drift) > 0.1 * bytes_per_sec:
                self._initial_drift_correction = current_drift
                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] 🎯 Initialer Drift erkannt: {current_drift:+d} Bytes – wird als Basis korrigiert",
                    )
                measured_offset -= self._initial_drift_correction
                current_drift = measured_offset - deterministic_offset

                with self._stats_lock:
                    self._total_bytes_processed = measured_offset + new_bytes
                    self._processed_seconds = self._total_bytes_processed / max(
                        1,
                        bytes_per_sec,
                    )
                    self._real_processed_seconds = self._processed_seconds
                offset_before = measured_offset
                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}]   → korrigierter measured_offset={measured_offset}, drift={current_drift:+d}",
                    )

        if not hasattr(self, "_drift_delta_history"):
            self._drift_delta_history = deque(maxlen=5)
        if hasattr(self, "_last_drift"):
            drift_delta = current_drift - self._last_drift
            self._drift_delta_history.append(drift_delta)
        self._last_drift = current_drift

        if debug_enabled:
            log_debug(
                "drift",
                f"[{drift_id}] offset: measured={measured_offset}, deterministic={deterministic_offset}, drift={current_drift:+d}",
            )
            if self._drift_delta_history:
                avg_delta = sum(self._drift_delta_history) / len(
                    self._drift_delta_history,
                )
                log_debug(
                    "drift",
                    f"[{drift_id}] delta: avg={avg_delta:+.0f} bytes/chunk ({avg_delta / bytes_per_sec:+.3f}s)",
                )

        with self._drift_lock:
            if not hasattr(self, "_offset_history"):
                self._offset_history = deque(maxlen=30)
            if not hasattr(self, "_raw_drift_history"):
                self._raw_drift_history = deque(maxlen=30)
            if not hasattr(self, "_smoothed_drift"):
                self._smoothed_drift = 0.0
            if not hasattr(self, "_drift_alpha"):
                self._drift_alpha = 0.15
            if not hasattr(self, "_last_correction"):
                self._last_correction = 0
            if not hasattr(self, "_correction_history"):
                self._correction_history = deque(maxlen=20)
            if not hasattr(self, "_total_correction_applied"):
                self._total_correction_applied = 0

            self._offset_history.append(current_drift)
            self._raw_drift_history.append(current_drift)

        hist = list(self._offset_history)[-self.HISTORY_LENGTH :]
        avg_drift = sum(hist) / max(1, len(hist))
        abs_avg_drift = abs(avg_drift)

        if len(hist) >= 5:
            sorted_vals = sorted(hist)
            median_drift = sorted_vals[len(sorted_vals) // 2]
        else:
            median_drift = current_drift

        abs_median = abs(median_drift)
        if abs_median > int(8.0 * bytes_per_sec):
            alpha = min(0.6, 0.25 + (abs_median / (bytes_per_sec * 25.0)))
        else:
            alpha = 0.15
        self._drift_alpha = max(0.05, min(0.7, alpha))

        if self._smoothed_drift == 0.0:
            self._smoothed_drift = float(median_drift)
        else:
            self._smoothed_drift = (
                alpha * float(median_drift) + (1.0 - alpha) * self._smoothed_drift
            )

        effective_drift = self._smoothed_drift
        abs_eff_drift = abs(effective_drift)

        if debug_enabled:
            max_drift = max(abs(d) for d in hist) if hist else 0
            log_debug(
                "drift",
                f"[{drift_id}] smooth: avg={avg_drift:+.0f} ({avg_drift / bytes_per_sec:+.3f}s), "
                f"eff={effective_drift:+.0f} ({effective_drift / bytes_per_sec:+.3f}s), max={max_drift}",
            )

        if not hasattr(self, "_actual_bytes_history"):
            self._actual_bytes_history = deque(maxlen=10)
        self._actual_bytes_history.append(new_bytes)
        adaptive_bps_used = bytes_per_sec

        if use_adaptive_rate and len(self._actual_bytes_history) >= 3:
            recent_bytes = list(self._actual_bytes_history)[-3:]
            avg_actual_bytes = sum(recent_bytes) / len(recent_bytes)
            expected_bytes = bytes_per_sec * config.CHUNK_DURATION
            deviation_ratio = (
                avg_actual_bytes / expected_bytes if expected_bytes > 0 else 1.0
            )

            if deviation_ratio < 0.85 or deviation_ratio > 1.15:
                actual_bps = avg_actual_bytes / config.CHUNK_DURATION
                new_bps = max(
                    self.ADAPTIVE_BPS_MIN_RATIO * nominal_bytes_per_sec,
                    min(
                        self.ADAPTIVE_BPS_MAX_RATIO * nominal_bytes_per_sec,
                        actual_bps,
                    ),
                )
                old_bps = self._adaptive_bytes_per_sec

                severity = min(1.0, abs_eff_drift / (10.0 * nominal_bytes_per_sec))
                beta = self.ADAPTIVE_BPS_BETA_MIN + severity * (
                    self.ADAPTIVE_BPS_BETA_MAX - self.ADAPTIVE_BPS_BETA_MIN
                )

                self._adaptive_bytes_per_sec = beta * new_bps + (1.0 - beta) * old_bps
                adaptive_bps_used = int(self._adaptive_bytes_per_sec)

                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] 🔄 Rate (Chunk): {old_bps:.0f} → {self._adaptive_bytes_per_sec:.0f} B/s "
                        f"(beta={beta:.2f}, severity={severity:.2f})",
                    )

            drift_seconds = abs_avg_drift / nominal_bytes_per_sec
            if drift_seconds > 2.0:
                correction = max(
                    -800,
                    min(800, -avg_drift / (nominal_bytes_per_sec * 0.02)),
                )
                old_bps = self._adaptive_bytes_per_sec
                self._adaptive_bytes_per_sec += correction
                self._adaptive_bytes_per_sec = max(
                    self.ADAPTIVE_BPS_MIN_RATIO * nominal_bytes_per_sec,
                    min(
                        self.ADAPTIVE_BPS_MAX_RATIO * nominal_bytes_per_sec,
                        self._adaptive_bytes_per_sec,
                    ),
                )
                if abs(self._adaptive_bytes_per_sec - old_bps) > 20 and debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] ⚡ Korrektur: {correction:.0f} B/s (Drift={drift_seconds:.2f}s) "
                        f"→ {self._adaptive_bytes_per_sec:.0f} B/s",
                    )

        drift_seconds = abs_avg_drift / nominal_bytes_per_sec
        severity = min(1.0, drift_seconds / self.HARD_RESET_THRESHOLD_SEC)

        delta_severity = 0.0
        if hasattr(self, "_drift_delta_history") and self._drift_delta_history:
            avg_delta = sum(self._drift_delta_history) / len(self._drift_delta_history)
            delta_seconds = abs(avg_delta) / nominal_bytes_per_sec
            if delta_seconds > self.DELTA_DRIFT_THRESHOLD_SEC:
                delta_severity = min(
                    1.0,
                    delta_seconds / (self.DELTA_DRIFT_THRESHOLD_SEC * 2),
                )
                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] ⚡ DELTA: {delta_seconds:.2f}s (severity={delta_severity:.2f})",
                    )

        combined_severity = max(severity, delta_severity * 1.5)

        if debug_enabled:
            log_debug(
                "drift",
                f"[{drift_id}] severity: drift={severity:.2f}, delta={delta_severity:.2f}, combined={combined_severity:.2f}",
            )

        if not hasattr(self, "_consecutive_large_drift"):
            self._consecutive_large_drift = 0
        if not hasattr(self, "_reset_cooldown"):
            self._reset_cooldown = 0
        if not hasattr(self, "_reset_counter"):
            self._reset_counter = 0

        drift_warning_bytes = int(
            self.DRIFT_WARNING_THRESHOLD_SEC * nominal_bytes_per_sec,
        )

        if abs_avg_drift > drift_warning_bytes or abs_eff_drift > drift_warning_bytes:
            self._consecutive_large_drift += 1
        else:
            self._consecutive_large_drift = max(0, self._consecutive_large_drift - 2)

        should_reset = False
        reset_reason = ""
        reset_triggered = None

        if drift_seconds > 300.0:
            should_reset = True
            reset_reason = f"EXTREME DRIFT ({drift_seconds:.0f}s)"
            reset_triggered = "extreme_drift"

        elif combined_severity > 0.9 and self._consecutive_large_drift > 10:
            should_reset = True
            reset_reason = (
                f"HARDRESET (severity={combined_severity:.2f}, "
                f"consecutive={self._consecutive_large_drift})"
            )
            reset_triggered = "hard_reset"

        elif self._consecutive_large_drift > 80:
            should_reset = True
            reset_reason = (
                f"FORCED RESET (consecutive={self._consecutive_large_drift} > 80)"
            )
            reset_triggered = "forced_reset"

        elif delta_severity > 0.8 and self._consecutive_large_drift > 5:
            should_reset = True

            reset_reason = (
                f"DELTA RESET (delta={delta_severity:.2f}, "
                f"consecutive={self._consecutive_large_drift})"
            )
            reset_triggered = "delta_reset"

        if self._reset_cooldown > 0:
            self._reset_cooldown -= 1
            if should_reset and reset_triggered not in (
                "hard_reset",
                "forced_reset",
                "extreme_drift",
            ):
                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] ⏳ Reset-Cooldown aktiv ({self._reset_cooldown} Chunks) – überspringe {reset_reason}",
                    )
                should_reset = False
                reset_triggered = None

        if should_reset:
            logger.warning(
                f"🚨 {reset_reason}: "
                f"avg_drift={avg_drift:.0f} bytes "
                f"({drift_seconds:.2f}s), "
                f"smooth={effective_drift:.0f}"
            )

            if debug_enabled:
                log_debug("drift", f"[{drift_id}] 🚨 RESET: {reset_reason}")
                log_debug(
                    "drift",
                    f"[{drift_id}]    avg_drift={avg_drift:.0f} ({drift_seconds:.2f}s)",
                )
                log_debug(
                    "drift",
                    f"[{drift_id}]    smooth={effective_drift:.0f} ({effective_drift / nominal_bytes_per_sec:.2f}s)",
                )
                log_debug(
                    "drift",
                    f"[{drift_id}]    consecutive={self._consecutive_large_drift}",
                )
                log_debug(
                    "drift",
                    f"[{drift_id}]    adaptive_rate={self._adaptive_bytes_per_sec:.0f} B/s",
                )
                log_debug(
                    "drift",
                    f"[{drift_id}]    total_correction={self._total_correction_applied}",
                )

            corrected_offset = deterministic_offset
            with self._stats_lock:
                self._total_bytes_processed = deterministic_offset + new_bytes
                self._processed_seconds = self._total_bytes_processed / max(
                    1,
                    nominal_bytes_per_sec,
                )
                self._real_processed_seconds = self._processed_seconds

            with self._drift_lock:
                self._offset_history.clear()
                self._raw_drift_history.clear()
                self._drift_delta_history.clear()
                self._smoothed_drift = 0.0
                self._consecutive_large_drift = 0
                self._reset_counter += 1
                self._reset_cooldown = 20

            if reset_triggered in ("hard_reset", "forced_reset", "extreme_drift"):
                old_rate = self._adaptive_bytes_per_sec
                self._adaptive_bytes_per_sec = float(nominal_bytes_per_sec)
                if debug_enabled:
                    log_debug(
                        "drift",
                        f"[{drift_id}] 📊 Rate zurückgesetzt: {old_rate:.0f} → {self._adaptive_bytes_per_sec:.0f} B/s",
                    )

            return self._finalize_stats(
                chunks_count,
                total_bytes_processed,
                corrected_offset,
                nominal_bytes_per_sec,
                adaptive_bps_used,
                reset_triggered=reset_triggered,
            )

        if severity > 0.6:
            correction_factor = self.CORRECTION_FACTOR_BASE + (severity - 0.6) * 2.0
            correction_factor = min(self.CORRECTION_FACTOR_MAX, correction_factor)
        elif self._consecutive_large_drift > 10:
            correction_factor = 1.1
        elif self._consecutive_large_drift > 5:
            correction_factor = 0.9
        else:
            correction_factor = 0.6

        if debug_enabled and correction_factor > 1.0:
            log_debug(
                "drift",
                f"[{drift_id}] factor: {correction_factor:.2f} (severity={severity:.2f})",
            )

        max_correction_sec = max(
            self.MAX_CORRECTION_SEC_BASE,
            min(
                self.MAX_CORRECTION_SEC_MAX,
                abs_avg_drift / (nominal_bytes_per_sec * 0.1),
            ),
        )
        max_correction_bytes = int(max_correction_sec * nominal_bytes_per_sec)

        target_correction = -effective_drift * correction_factor
        if abs(target_correction) > max_correction_bytes:
            target_correction = (
                max_correction_bytes if target_correction > 0 else -max_correction_bytes
            )

        max_change = max(0.3 * max_correction_bytes, int(1.0 * nominal_bytes_per_sec))
        delta = target_correction - self._last_correction
        if abs(delta) > max_change:
            target_correction = self._last_correction + (
                max_change if delta > 0 else -max_change
            )

        correction = int(target_correction)
        with self._drift_lock:
            self._correction_history.append(correction)
            self._last_correction = correction
            self._total_correction_applied += abs(correction)

        corrected_offset = measured_offset + correction

        if corrected_offset < 0:
            logger.warning(
                f"[{drift_id}] corrected_offset negativ ({corrected_offset}) – setze auf 0",
            )
            corrected_offset = 0
            correction = -measured_offset

        if debug_enabled and correction != 0:
            log_debug(
                "drift",
                f"[{drift_id}] 🛠️ Korrektur: {correction:+d} Bytes (max={max_correction_bytes}, factor={correction_factor:.2f})",
            )

        if chunks_count % 50 == 0 and debug_enabled:
            log_debug(
                "drift_summary",
                f"[{drift_id}] 📊 Chunk #{chunks_count}: "
                f"drift={avg_drift:.0f} ({avg_drift / nominal_bytes_per_sec:.2f}s), "
                f"corr={correction:+d}, rate={adaptive_bps_used}, "
                f"consecutive={self._consecutive_large_drift}, "
                f"total={total_bytes_processed / 1024 / 1024:.1f}MB",
            )

        log_debug(
            "transcript_pipeline",
            f"DRIFT_DETAIL: chunk={chunks_count}, "
            f"measured={measured_offset}, "
            f"deterministic={deterministic_offset}, "
            f"avg_drift={avg_drift:.0f}, "
            f"adaptive_bps={adaptive_bps_used}, "
            f"correction={correction:+d}, "
            f"corrected={corrected_offset}, "
            f"severity={severity:.2f}",
        )

        if debug_enabled:
            log_debug(
                "drift",
                f"[{drift_id}] END: corrected_offset={corrected_offset}, rate={adaptive_bps_used}",
            )

        return self._finalize_stats(
            chunks_count,
            total_bytes_processed,
            corrected_offset,
            nominal_bytes_per_sec,
            adaptive_bps_used,
            reset_triggered=None,
        )

    def _finalize_stats(
        self,
        chunks_count: int,
        total_bytes_processed: int,
        corrected_offset: int,
        bytes_per_sec: int,
        adaptive_bps_used: int,
        reset_triggered: str | None = None,
    ) -> dict[str, Any]:
        """Sammelt alle Statistiken und gibt sie als Dictionary zurück."""
        try:
            qsize = self._raw_audio_queue.qsize() if self._raw_audio_queue else 0
            queue_maxsize = getattr(self._raw_audio_queue, "maxsize", 1000) or 1000
        except Exception:
            qsize = 0
            queue_maxsize = 1000

        if not hasattr(self, "_queue_size_history"):
            self._queue_size_history = deque(maxlen=10)
        self._queue_size_history.append(qsize)
        avg_queue_ratio = sum(self._queue_size_history) / (
            len(self._queue_size_history) * max(1, queue_maxsize)
        )

        with self._stats_lock:
            current_rt_factor = self._last_realtime_factor

        drift_diag = {}
        if hasattr(self, "_offset_history") and len(self._offset_history) > 0:
            drift_diag = {
                "avg_drift_bytes": sum(self._offset_history)
                / len(self._offset_history),
                "max_drift_bytes": max(self._offset_history, default=0),
                "min_drift_bytes": min(self._offset_history, default=0),
                "consecutive_drift": self._consecutive_large_drift,
                "total_correction_applied": self._total_correction_applied,
                "reset_counter": self._reset_counter,
            }

        result = {
            "chunks_count": chunks_count,
            "total_bytes_processed": total_bytes_processed,
            "chunk_byte_offset": corrected_offset,
            "avg_queue_ratio": avg_queue_ratio,
            "current_rt_factor": current_rt_factor,
            "adaptive_bps_used": adaptive_bps_used,
            "drift_correction_applied": getattr(self, "_total_correction_applied", 0),
            "reset_triggered": reset_triggered,
            **drift_diag,
        }

        if DEBUG_LEVEL >= 3:
            log_debug("offset_stats", f"Final stats: {result}")

        return result

    def _adjust_adaptive_chunk(
        self,
        config: Config,
        avg_queue_ratio: float,
        current_rt_factor: float,
    ) -> None:
        """Passt die Chunk‑Dauer dynamisch an die Systemlast und Queue‑Größe an."""
        if not getattr(self.settings, "adaptive_chunk", False):
            self._consecutive_high_queue = 0
            self._consecutive_low_queue = 0
            return

        now = time.monotonic()
        cooldown = getattr(self, "_chunk_adjust_cooldown", 15.0)
        last_adjust = getattr(self, "_last_chunk_adjust_time", 0.0)
        if (now - last_adjust) < cooldown:
            return

        current_duration = config.CHUNK_DURATION
        min_dur = config.MIN_CHUNK_DURATION
        max_dur = config.MAX_CHUNK_DURATION

        MIN_CHUNK_DURATION_HARD = 15.0
        effective_min_dur = max(min_dur, MIN_CHUNK_DURATION_HARD)

        changed = False
        new_duration = current_duration

        if avg_queue_ratio > 0.8:
            consecutive = getattr(self, "_consecutive_high_queue", 0) + 1
            self._consecutive_high_queue = consecutive
            self._consecutive_low_queue = 0
            threshold = getattr(self, "_chunk_adjust_threshold", 10)
            if consecutive >= threshold and current_duration > effective_min_dur:
                new_duration = max(effective_min_dur, current_duration - 1.0)
                changed = True
                self._consecutive_high_queue = 0

        elif avg_queue_ratio < 0.2:
            consecutive = getattr(self, "_consecutive_low_queue", 0) + 1
            self._consecutive_low_queue = consecutive
            self._consecutive_high_queue = 0
            threshold = getattr(self, "_chunk_adjust_threshold", 10)
            if consecutive >= threshold and current_duration < max_dur:
                new_duration = min(max_dur, current_duration + 0.5)
                changed = True
                self._consecutive_low_queue = 0

        else:
            self._consecutive_high_queue = 0
            self._consecutive_low_queue = 0

        if changed and new_duration != current_duration:
            new_duration = max(effective_min_dur, new_duration)
            if new_duration != current_duration:
                logger.info(
                    "Adaptive chunk change: %.1fs → %.1fs (queue_ratio=%.2f, rt_factor=%.2f)",
                    current_duration,
                    new_duration,
                    avg_queue_ratio,
                    current_rt_factor,
                )
                self.set_chunk_duration(new_duration, force=True)
                self._last_chunk_adjust_time = now
                self._chunk_adjust_count = getattr(self, "_chunk_adjust_count", 0) + 1

        if DEBUG_LEVEL >= 4:
            log_debug(
                "adaptive",
                "No change: dur=%.1fs, queue=%.2f, rt=%.2f, high=%d, low=%d",
                current_duration,
                avg_queue_ratio,
                current_rt_factor,
                getattr(self, "_consecutive_high_queue", 0),
                getattr(self, "_consecutive_low_queue", 0),
            )
        elif DEBUG_LEVEL >= 3 and avg_queue_ratio > 0.7:
            log_debug(
                "adaptive",
                "Queue high (%.2f), dur=%.1fs, rt=%.2f, pending changes: high=%d, low=%d",
                avg_queue_ratio,
                current_duration,
                current_rt_factor,
                getattr(self, "_consecutive_high_queue", 0),
                getattr(self, "_consecutive_low_queue", 0),
            )

    def _trigger_periodic_callbacks(
        self,
        chunks_count: int,
        total_bytes_processed: int,
        info_callback: InfoCallback | None,
    ) -> None:
        """Ruft periodische Fortschritts‑ und Info‑Callbacks auf."""
        if self._progress_callback is not None and chunks_count % 10 == 0:
            try:
                self._progress_callback(
                    total_bytes_processed,
                    self._total_file_size,
                    chunks_count,
                )
            except Exception as exc:
                if DEBUG_LEVEL >= 3:
                    log_debug("processor", "Progress callback error: %s", exc)

        if chunks_count % 50 == 0 and info_callback is not None:
            try:
                info_callback(f"📊 {chunks_count} chunks processed …")
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("processor", "Info callback error: %s", e)

    def _ensure_dispatcher_alive(
        self,
        error_callback: ErrorCallback,
        chunks_count: int,
        audio_len: int,
        audio_data: bytes,
    ) -> None:
        """Prüft, ob der Dispatcher noch läuft, und startet ihn bei Bedarf neu."""
        dispatcher_ok = (
            self._dispatcher_started
            and self._dispatcher_thread is not None
            and self._dispatcher_thread.is_alive()
        )
        if dispatcher_ok:
            return

        logger.warning(
            "_process_audio_data: Dispatcher not active (alive=%s, started=%s) – attempting restart",
            self._dispatcher_thread.is_alive() if self._dispatcher_thread else "None",
            self._dispatcher_started,
        )

        if not hasattr(self, "_dispatcher_restart_lock"):
            self._dispatcher_restart_lock = threading.Lock()

        with self._dispatcher_restart_lock:
            if (
                self._dispatcher_started
                and self._dispatcher_thread is not None
                and self._dispatcher_thread.is_alive()
            ):
                restart_success = True
            else:
                restart_success = False
                for attempt in range(1, 4):
                    self._start_dispatcher()
                    time.sleep(0.1 * attempt)
                    if (
                        self._dispatcher_started
                        and self._dispatcher_thread is not None
                        and self._dispatcher_thread.is_alive()
                    ):
                        restart_success = True
                        break
                    logger.warning("Dispatcher restart attempt %d/3 failed.", attempt)

            if not restart_success:
                logger.error(
                    "Dispatcher could not be restarted – chunk %d lost (%d bytes).",
                    chunks_count,
                    audio_len,
                )
                if error_callback is not None:
                    error_callback(
                        "Interner Fehler: Audio-Dispatcher ausgefallen – Chunk verworfen.",
                    )
                self._save_lost_chunk(audio_data, "dispatcher_restart_failed")
                return

    def _log_performance_metrics(
        self,
        chunk_duration: float,
        chunks_count: int,
    ) -> None:
        """Protokolliert Performance‑Metriken und führt bei Bedarf Garbage‑Collection durch."""
        processing_duration = (
            time.perf_counter() - self._last_chunk_start_time
            if hasattr(self, "_last_chunk_start_time")
            else 0
        )
        self._last_chunk_start_time = time.perf_counter()

        if processing_duration > chunk_duration * 0.5:
            logger.debug(
                "Slow _process_audio_data: %.2f ms for %.2fs chunk (%.2f%%)",
                processing_duration * 1000,
                chunk_duration,
                (processing_duration / chunk_duration) * 100,
            )

        if chunks_count % 5000 == 0 and chunks_count > 0:
            gc.collect()
            if DEBUG_LEVEL >= 3:
                log_debug("processor", "Triggered GC after %d chunks", chunks_count)

        if DEBUG_LEVEL >= 3:
            now = time.monotonic()
            interval = getattr(self, "_queue_log_interval", 10.0)
            with self._stats_lock:
                if (now - getattr(self, "_last_queue_log_time", 0.0)) >= interval:
                    try:
                        qsize = self._raw_audio_queue.qsize()
                    except Exception:
                        qsize = 0
                    log_debug(
                        "queue_stats",
                        "Queue: enqueued=%d, dequeued=%d, dropped=%d, current_size=%d",
                        getattr(self, "_queue_enqueue_counter", 0),
                        getattr(self, "_queue_dequeue_counter", 0),
                        getattr(self, "_queue_drop_counter", 0),
                        qsize,
                    )
                    self._last_queue_log_time = now

    def _attempt_enqueue(self, item: tuple, block_timeout: float = 0.5) -> bool:
        """Versucht, ein Queue-Item in die Verarbeitungs-Pipeline einzureihen."""
        import logging
        import queue
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        is_testing = getattr(self, "_testing", False) or getattr(
            self, "_TESTING", False
        )

        if self._stop_event.is_set():
            if debug_level >= 3:
                log_debug(
                    "queue",
                    "_attempt_enqueue: Stop-Event gesetzt – Einreihen abgelehnt",
                )
            return False

        q = self._raw_audio_queue
        if q is None:
            logger.error(
                "_attempt_enqueue: raw_audio_queue ist None – Einreihen unmöglich",
                extra={"component": "queue"},
            )
            return False

        try:
            current_size = q.qsize()
            max_size = getattr(q, "maxsize", 0)
        except Exception as e:
            current_size = -1
            max_size = 0
            if debug_level >= 4:
                log_debug(
                    "queue",
                    f"_attempt_enqueue: Fehler beim Abfragen der Queue-Größe: {e}",
                )

        if debug_level >= 4:
            log_debug(
                "queue",
                f"_attempt_enqueue: Versuche Einreihen (current_size={current_size}, max_size={max_size}, timeout={block_timeout}s)",
            )

        if not is_testing and max_size > 0 and current_size > 0:
            try:
                MAX_QUEUE_SIZE = getattr(self, "_max_queue_size", 1000)
                MIN_QUEUE_SIZE = getattr(self, "_min_queue_size", 5)
                STEP_UP = getattr(self, "_queue_size_step_up", 50)
                STEP_DOWN = getattr(self, "_queue_size_step_down", 10)

                if current_size > max_size * 0.8 and max_size < MAX_QUEUE_SIZE:
                    new_max = min(MAX_QUEUE_SIZE, max_size + STEP_UP)
                    if new_max != max_size:
                        q.maxsize = new_max
                        if debug_level >= 3:
                            log_debug(
                                "queue",
                                f"_attempt_enqueue: maxsize erhöht: {max_size} → {new_max} (current={current_size}, load={current_size / max_size:.1%})",
                            )
                elif current_size < max_size * 0.2 and max_size > MIN_QUEUE_SIZE:
                    new_max = max(MIN_QUEUE_SIZE, max_size - STEP_DOWN)
                    if new_max != max_size:
                        q.maxsize = new_max
                        if debug_level >= 3:
                            log_debug(
                                "queue",
                                f"_attempt_enqueue: maxsize reduziert: {max_size} → {new_max} (current={current_size}, load={current_size / max_size:.1%})",
                            )
            except Exception as e:
                if debug_level >= 4:
                    log_debug(
                        "queue",
                        f"_attempt_enqueue: Fehler bei dynamischer Anpassung: {e}",
                    )

        try:
            q.put_nowait(item)
            self._increment_enqueue_stats()

            if debug_level >= 4:
                log_debug(
                    "queue",
                    f"_attempt_enqueue: put_nowait erfolgreich (queue_size={current_size + 1})",
                )
            return True

        except queue.Full:
            if debug_level >= 4:
                log_debug(
                    "queue",
                    "_attempt_enqueue: put_nowait fehlgeschlagen – Queue voll",
                )
        except Exception as e:
            logger.error(
                f"_attempt_enqueue: unerwarteter Fehler bei put_nowait: {e}",
                exc_info=True,
                extra={"component": "queue"},
            )
            return False

        try:
            load_ratio = current_size / max_size if max_size > 0 else 1.0
        except Exception:
            load_ratio = 0.0

        if load_ratio > 0.85 and debug_level >= 2:
            log_debug(
                "queue",
                f"⚠️ Queue-Backpressure: {current_size}/{max_size} ({load_ratio:.1%}) – blockiere",
            )

        if is_testing and load_ratio > 0.95:
            try:
                dropped = 0
                while q.qsize() > max_size * 0.8 and dropped < 10:
                    try:
                        q.get_nowait()
                        q.task_done()
                        dropped += 1
                    except queue.Empty:
                        break
                if dropped > 0:
                    log_debug(
                        "queue",
                        f"TEST-MODE: {dropped} älteste Items aus Queue verworfen (load={load_ratio:.1%})",
                    )
            except Exception as e:
                if debug_level >= 4:
                    log_debug("queue", f"TEST-MODE: Fehler beim Verwerfen: {e}")

        effective_timeout = block_timeout
        if is_testing:
            effective_timeout = min(block_timeout, 0.1)

        if debug_level >= 3:
            log_debug(
                "queue",
                f"_attempt_enqueue: Queue voll ({current_size}/{max_size}), versuche blockierend (timeout={effective_timeout:.2f}s)...",
            )

        start_wait = time.monotonic()
        try:
            q.put(item, block=True, timeout=effective_timeout)
            self._increment_enqueue_stats()
            wait_time = time.monotonic() - start_wait

            if debug_level >= 3:
                log_debug(
                    "queue",
                    f"_attempt_enqueue: blockierendes put erfolgreich (gewatet={wait_time * 1000:.1f}ms)",
                )
            return True

        except queue.Full:
            wait_time = time.monotonic() - start_wait

            try:
                current_size_after = q.qsize()
            except Exception:
                current_size_after = "?"

            with self._stats_lock:
                self._queue_drop_counter += 1

            logger.warning(
                f"_attempt_enqueue: Queue nach {effective_timeout:.1f}s immer noch voll "
                f"(Größe {current_size_after}/{max_size}, load={load_ratio:.1%}) – "
                f"Element verworfen (gewatet={wait_time * 1000:.1f}ms)",
                extra={"component": "queue"},
            )

            if hasattr(self, "_event_bus") and self._event_bus is not None:
                try:
                    self._event_bus.emit(
                        "queue_overflow",
                        {
                            "queue_size": current_size_after,
                            "max_size": max_size,
                            "load_ratio": load_ratio,
                            "wait_time": wait_time,
                            "timestamp": time.time(),
                        },
                    )
                except Exception as e:
                    if debug_level >= 4:
                        log_debug(
                            "queue", f"Event-Bus Benachrichtigung fehlgeschlagen: {e}"
                        )

            if load_ratio > 0.95 and hasattr(self, "_check_queue_after_error"):
                if not hasattr(self, "_last_overflow_warning"):
                    self._last_overflow_warning = 0.0

                now = time.monotonic()
                if now - self._last_overflow_warning > 10.0:
                    self._last_overflow_warning = now
                    logger.warning(
                        f"🚨 Anhaltende Queue-Überlastung ({load_ratio:.1%}) – prüfe Dispatcher",
                        extra={"component": "queue"},
                    )
                    try:
                        self._check_queue_after_error()
                    except Exception as e:
                        logger.error(f"Fehler in _check_queue_after_error: {e}")

            return False

        except Exception as e:
            logger.error(
                f"_attempt_enqueue: unerwarteter Fehler bei blockierendem put: {e}",
                exc_info=True,
                extra={"component": "queue"},
            )
            return False

        finally:
            if debug_level >= 3:
                try:
                    final_size = q.qsize()
                except Exception:
                    final_size = "?"

                if final_size != current_size:
                    log_debug(
                        "queue",
                        f"_attempt_enqueue: Queue-Zustand geändert: {current_size} → {final_size}",
                    )

    def _increment_enqueue_stats(self) -> None:
        """Aktualisiert die Zähler für erfolgreich eingereihte Audio‑Chunks."""
        with self._stats_lock:
            if not hasattr(self, "_queue_enqueue_counter"):
                self._queue_enqueue_counter = 0
            if not hasattr(self, "_consecutive_queue_drops"):
                self._consecutive_queue_drops = 0

            self._queue_enqueue_counter += 1
            self._consecutive_queue_drops = 0

            if DEBUG_LEVEL >= 4 and self._queue_enqueue_counter % 100 == 0:
                log_debug(
                    "queue_stats",
                    "_increment_enqueue_stats: total_enqueued=%d",
                    self._queue_enqueue_counter,
                )

    def _handle_overflow_chunk(self, item: tuple) -> None:
        """Verwaltet den sekundären Overflow‑Puffer für nicht einreihbare Chunks."""
        if not hasattr(self, "_overflow_chunks"):
            self._overflow_chunks: deque = deque()
            self._overflow_lock = threading.RLock()
            self._overflow_worker_started = False
            self._overflow_max_chunks = 20

        if not isinstance(item, tuple) or len(item) < 4:
            logger.warning(
                "_handle_overflow_chunk: Ungültiges Queue‑Item empfangen "
                "(Typ %s, Länge %s). Wird verworfen.",
                type(item).__name__ if item is not None else "None",
                len(item) if isinstance(item, (tuple, list)) else "N/A",
            )
            return
        audio_data = item[0]
        if not isinstance(audio_data, bytes):
            logger.warning(
                "_handle_overflow_chunk: Erstes Element des Queue‑Items "
                "ist kein bytes-Objekt (Typ %s). Wird verworfen.",
                type(audio_data).__name__,
            )
            return

        with self._overflow_lock:
            self._overflow_chunks.append(item)
            total_count = len(self._overflow_chunks)

        if total_count == 1:
            logger.warning(
                "_handle_overflow_chunk: Queue voll – erster Chunk in "
                "Overflow‑Puffer (wird automatisch erneut zugestellt).",
            )
        elif total_count == 5:
            logger.warning(
                "_handle_overflow_chunk: %d Chunks im Overflow‑Puffer.",
                total_count,
            )
        elif total_count == 10:
            logger.warning(
                "_handle_overflow_chunk: %d Chunks im Overflow‑Puffer – "
                "die Verarbeitung hinkt deutlich hinterher.",
                total_count,
            )

        if total_count > self._overflow_max_chunks:
            oldest = None
            with self._overflow_lock:
                if self._overflow_chunks:
                    oldest = self._overflow_chunks.popleft()
            if oldest is not None and isinstance(oldest, tuple) and len(oldest) >= 1:
                maybe_audio = oldest[0]
                if isinstance(maybe_audio, bytes):
                    self._save_lost_chunk(maybe_audio, "overflow_buffer_exceeded")
                    logger.warning(
                        "_handle_overflow_chunk: Ältester Overflow‑Chunk "
                        "gesichert (Puffer überschreitet Limit %d).",
                        self._overflow_max_chunks,
                    )
                else:
                    logger.warning(
                        "_handle_overflow_chunk: Ältester Overflow‑Chunk "
                        "enthält keine bytes – kein _save_lost_chunk.",
                    )
            else:
                logger.warning(
                    "_handle_overflow_chunk: Overflow‑Puffer enthielt "
                    "entweder None oder ein ungültiges Element – kein "
                    "`_save_lost_chunk` aufgerufen.",
                )

        self._start_overflow_worker()

        with self._stats_lock:
            self._queue_drop_counter += 1
            self._consecutive_queue_drops += 1

    def _start_overflow_worker(self) -> None:
        """Startet **genau einen** dauerhaften Hintergrund‑Thread, der alle im
        Overflow‑Puffer ``_overflow_chunks`` wartenden Audio‑Chunks
        wiederholt in die Haupt‑Queue ``_raw_audio_queue`` einzureihen
        versucht.
        """
        with self._overflow_lock:
            if self._overflow_worker_started:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "overflow",
                        "_start_overflow_worker: Worker läuft bereits – "
                        "ignoriere weiteren Start.",
                    )
                return
            self._overflow_worker_started = True

        max_retries_per_chunk = 3

        def worker() -> None:
            logger.debug(
                "Overflow‑Worker gestartet (Daemon, max_retries=%d).",
                max_retries_per_chunk,
            )
            try:
                while not self._stop_event.is_set():
                    chunk_to_process = None
                    with self._overflow_lock:
                        if self._overflow_chunks:
                            chunk_to_process = self._overflow_chunks.popleft()
                        else:
                            self._overflow_worker_started = False
                            if DEBUG_LEVEL >= 4:
                                log_debug(
                                    "overflow",
                                    "Overflow‑Worker: Puffer leer – beende.",
                                )
                            break

                    if chunk_to_process is None:
                        break

                    retries = 0
                    success = False
                    while (
                        retries < max_retries_per_chunk
                        and not self._stop_event.is_set()
                    ):
                        success = self._attempt_enqueue(chunk_to_process)
                        if success:
                            if DEBUG_LEVEL >= 4:
                                log_debug(
                                    "overflow",
                                    "Overflow‑Worker: Chunk nach %d Versuch(en) "
                                    "erfolgreich eingereiht.",
                                    retries + 1,
                                )
                            break

                        retries += 1
                        if retries < max_retries_per_chunk:
                            delay = 0.2 * (2 ** (retries - 1))
                            if self._stop_event.wait(timeout=delay):
                                break

                    if not success and not self._stop_event.is_set():
                        audio_bytes = (
                            chunk_to_process[0]
                            if isinstance(chunk_to_process, tuple)
                            else chunk_to_process
                        )
                        self._save_lost_chunk(audio_bytes, "overflow_retry_exhausted")
                        logger.warning(
                            "Overflow‑Worker: Chunk nach %d Versuchen endgültig "
                            "verloren – als WAV gesichert.",
                            max_retries_per_chunk,
                        )

                    if self._stop_event.wait(timeout=0.05):
                        break

            except Exception as exc:
                logger.error(
                    "Overflow‑Worker: Unerwarteter Fehler im Haupt‑Loop – "
                    "Worker wird beendet: %s",
                    exc,
                    exc_info=DEBUG_LEVEL >= 3,
                )
            finally:
                with self._overflow_lock:
                    self._overflow_worker_started = False
                logger.debug("Overflow‑Worker beendet.")

        threading.Thread(
            target=worker,
            daemon=True,
            name="AudioOverflowWorker",
        ).start()

        if DEBUG_LEVEL >= 3:
            log_debug("overflow", "Overflow‑Worker‑Thread gestartet (daemon).")

    def _compute_rms(self, audio_data: bytes) -> float | None:
        """Berechnet den RMS‑Wert (Root Mean Square) eines 16‑Bit‑PCM‑Chunks."""
        if not audio_data or len(audio_data) < 2:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "rms",
                    "_compute_rms: Input too short (%d bytes) – returning None.",
                    len(audio_data) if audio_data else 0,
                )
            return None

        np = getattr(self, "_np", None)
        if np is None:
            try:
                import numpy as _np_module

                np = _np_module
            except ImportError:
                np = None

        if np is not None:
            try:
                audio_np = np.frombuffer(audio_data, dtype=np.int16).astype(np.float32)
                audio_np /= 32768.0
                rms = float(np.sqrt(np.mean(audio_np**2)))
                return rms
            except Exception as exc:
                logger.warning(
                    "_compute_rms: numpy‑Berechnung fehlgeschlagen: %s – "
                    "versuche struct‑Fallback.",
                    exc,
                )
                if DEBUG_LEVEL >= 3:
                    log_exception("rms", "numpy RMS failed", exc, level="debug")

        try:
            import math
            import struct

            num_samples = len(audio_data) // 2
            if num_samples == 0:
                return None

            fmt = f"<{num_samples}h"
            samples = struct.unpack(fmt, audio_data[: num_samples * 2])
            sum_sq = sum(float(s) * float(s) for s in samples)
            rms = math.sqrt(sum_sq / num_samples)
            rms /= 32768.0
            return rms
        except Exception as exc:
            logger.warning("_compute_rms: struct‑Fallback fehlgeschlagen: %s", exc)
            if DEBUG_LEVEL >= 3:
                log_exception("rms", "struct RMS fallback failed", exc, level="debug")

        return None

    def _save_lost_chunk(self, audio_data: bytes, reason: str = "unknown") -> None:
        """Sichert einen verlorenen Audio-Chunk als WAV-Datei mit begleitender JSON-Metadatei.
        ULTIMATIVE, ROBUSTE VERSION mit asynchroner Speicherung.
        """
        import json
        import re
        import shutil
        import struct
        import tempfile
        import threading
        from datetime import datetime
        from pathlib import Path

        if not audio_data or len(audio_data) < 16:
            _safe_log_debug(
                "lost_chunk",
                "Audio data too short (%d bytes) – skipped.",
                len(audio_data) if audio_data else 0,
            )
            return

        MAX_CHUNKS_PER_SECOND = 5
        MAX_BURST = 10
        TOKEN_REFRESH_RATE = MAX_CHUNKS_PER_SECOND

        with AudioProcessor._lost_chunk_rate_lock:
            now = time.monotonic()
            if not hasattr(AudioProcessor, "_lost_chunk_tokens"):
                AudioProcessor._lost_chunk_tokens = MAX_BURST
                AudioProcessor._lost_chunk_last_refill = now

            elapsed = now - AudioProcessor._lost_chunk_last_refill
            AudioProcessor._lost_chunk_tokens = min(
                MAX_BURST,
                AudioProcessor._lost_chunk_tokens + elapsed * TOKEN_REFRESH_RATE,
            )
            AudioProcessor._lost_chunk_last_refill = now

            if AudioProcessor._lost_chunk_tokens < 1.0:
                logger.warning(
                    "_save_lost_chunk: Rate-Limit überschritten (%.1f Tokens) – Chunk verworfen. reason=%s",
                    AudioProcessor._lost_chunk_tokens,
                    reason,
                )
                return

            AudioProcessor._lost_chunk_tokens -= 1.0

        stream_id = getattr(self, "_current_stream_id", "unknown")
        now_ts = time.time()
        local_time_str = datetime.now().strftime("%Y%m%d_%H%M%S")
        chunk_length = len(audio_data)

        byte_offset = None
        try:
            with self._stats_lock:
                byte_offset = self._total_bytes_processed
        except (AttributeError, RuntimeError) as e:
            _safe_log_debug(
                "lost_chunk",
                "Could not read _total_bytes_processed: %s",
                e,
            )

        if self.settings:
            bytes_per_sec = self.settings.config.BYTES_PER_SECOND
            sample_rate = self.settings.config.SAMPLE_RATE
            channels = self.settings.config.CHANNELS
        else:
            bytes_per_sec = 32000
            sample_rate = 16000
            channels = 1

        duration_sec = chunk_length / max(1, bytes_per_sec)

        metadata = {
            "stream_id": stream_id,
            "timestamp": local_time_str,
            "unix_timestamp": now_ts,
            "reason": reason,
            "audio_bytes": chunk_length,
            "duration_sec": round(duration_sec, 3),
            "byte_offset": byte_offset,
            "sample_rate": sample_rate,
            "channels": channels,
            "application": "DragonWhisperer",
            "version": getattr(self, "_version", "unknown"),
        }

        if hasattr(self, "_expected_duration") and self._expected_duration:
            metadata["expected_duration"] = round(self._expected_duration, 2)
        if hasattr(self, "_chunk_counter"):
            metadata["chunk_counter"] = self._chunk_counter

        base_dir = Path(tempfile.gettempdir()) / "dragon_lost_chunks"
        date_dir = base_dir / datetime.now().strftime("%Y%m%d")
        target_dir = date_dir

        try:
            target_dir.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            logger.error(
                "_save_lost_chunk: Kann Zielverzeichnis %s nicht erstellen: %s",
                target_dir,
                exc,
            )
            target_dir = base_dir
            try:
                target_dir.mkdir(parents=True, exist_ok=True)
            except OSError as fallback_exc:
                logger.error(
                    "Auch Fallback-Verzeichnis %s nicht erstellbar: %s",
                    target_dir,
                    fallback_exc,
                )
                return

        try:
            self._cleanup_lost_chunks(
                target_dir,
                max_files_per_day=1000,
                max_age_days=7,
            )
        except Exception as e:
            _safe_log_debug("lost_chunk", "Cleanup failed: %s", e)

        unique_id = uuid.uuid4().hex[:12]
        safe_reason = re.sub(r"[^\w\-]", "_", reason)[:30]
        base_name = f"lost_{stream_id}_{local_time_str}_{unique_id}_{safe_reason}"
        wav_path = target_dir / f"{base_name}.wav"
        json_path = target_dir / f"{base_name}.json"

        def _save_files() -> None:
            """Speichert die Dateien im Hintergrund-Thread."""
            tmp_wav_path = None
            tmp_json_path = None

            try:
                tmp_fd, tmp_wav_path = tempfile.mkstemp(
                    suffix=".wav",
                    prefix="tmp_",
                    dir=target_dir,
                )
                os.close(tmp_fd)

                data_size = chunk_length
                byte_rate = sample_rate * channels * 2
                block_align = channels * 2

                with open(tmp_wav_path, "wb") as f:
                    f.write(b"RIFF")
                    f.write(struct.pack("<I", 36 + data_size))
                    f.write(b"WAVE")
                    f.write(b"fmt ")
                    f.write(struct.pack("<I", 16))
                    f.write(struct.pack("<H", 1))
                    f.write(struct.pack("<H", channels))
                    f.write(struct.pack("<I", sample_rate))
                    f.write(struct.pack("<I", byte_rate))
                    f.write(struct.pack("<H", block_align))
                    f.write(struct.pack("<H", 16))
                    f.write(b"data")
                    f.write(struct.pack("<I", data_size))
                    f.write(audio_data)

                if wav_path.exists():
                    wav_path.unlink()
                shutil.move(tmp_wav_path, wav_path)
                tmp_wav_path = None

                tmp_fd, tmp_json_path = tempfile.mkstemp(
                    suffix=".json",
                    prefix="tmp_",
                    dir=target_dir,
                )
                os.close(tmp_fd)

                with open(tmp_json_path, "w", encoding="utf-8") as f:
                    json.dump(metadata, f, indent=2, ensure_ascii=False)

                if json_path.exists():
                    json_path.unlink()
                shutil.move(tmp_json_path, json_path)
                tmp_json_path = None

                with self._temp_files_lock:
                    self._temp_files.append(str(wav_path))
                    if json_path.exists():
                        self._temp_files.append(str(json_path))

                logger.warning(
                    "LOST AUDIO CHUNK saved to %s (reason: %s, bytes: %d, stream: %s)",
                    wav_path,
                    reason,
                    chunk_length,
                    stream_id,
                )

                if self._event_bus is not None:
                    try:
                        self._event_bus.emit(
                            "lost_chunk_saved",
                            {
                                "wav_path": str(wav_path),
                                "reason": reason,
                                "bytes": chunk_length,
                                "stream_id": stream_id,
                                "duration_sec": duration_sec,
                            },
                        )
                    except Exception as e:
                        _safe_log_debug(
                            "lost_chunk",
                            "Event-Bus emission failed: %s",
                            e,
                        )

            except Exception as exc:
                logger.exception("_save_lost_chunk: Fehler beim Speichern: %s", exc)
                if tmp_wav_path and Path(tmp_wav_path).exists():
                    with contextlib.suppress(OSError):
                        Path(tmp_wav_path).unlink()
                if tmp_json_path and Path(tmp_json_path).exists():
                    with contextlib.suppress(OSError):
                        Path(tmp_json_path).unlink()

        try:
            thread = threading.Thread(
                target=_save_files,
                daemon=True,
                name="LostChunkSaver",
            )
            thread.start()
            if DEBUG_LEVEL >= 4:
                _safe_log_debug(
                    "lost_chunk",
                    "Speicher-Thread gestartet für %s",
                    base_name,
                )
        except Exception as e:
            logger.error("Konnte Speicher-Thread nicht starten: %s", e)
            _save_files()

        if not hasattr(self, "_lost_chunk_count"):
            self._lost_chunk_count = 0
            self._lost_chunk_last_warning = 0

        self._lost_chunk_count += 1

        now = time.time()
        if self._lost_chunk_count > 50 and (now - self._lost_chunk_last_warning) > 300:
            self._lost_chunk_last_warning = now
            logger.error(
                "⚠️ Mehr als 50 Audio-Chunks verloren (Grund: %s). "
                "Bitte prüfen Sie die Stabilität der Verbindung und die Transkriptions-Engine.",
                reason,
            )
            if self._event_bus is not None:
                with contextlib.suppress(Exception):
                    self._event_bus.emit(
                        "error_with_hint",
                        {
                            "error": f"Mehr als 50 verlorene Audio-Chunks (Grund: {reason})",
                            "hint": "Bitte prüfen Sie die Netzwerkverbindung und die Transkriptions-Engine.",
                            "consecutive": self._lost_chunk_count,
                        },
                    )

    def _cleanup_lost_chunks(
        self,
        directory: Path,
        max_files_per_day: int = 1000,
        max_age_days: int = 7,
    ) -> None:
        """Löscht alte Lost-Chunk-Dateien, um das Verzeichnis nicht übermäßig wachsen zu lassen."""
        try:
            if not directory.exists():
                return

            files = list(directory.glob("lost_*.wav")) + list(
                directory.glob("lost_*.json"),
            )
            if len(files) <= max_files_per_day:
                return

            files.sort(key=lambda p: p.stat().st_mtime if p.exists() else 0)

            to_delete = files[:-max_files_per_day]
            for f in to_delete:
                try:
                    f.unlink()
                    if DEBUG_LEVEL >= 3:
                        _safe_log_debug("lost_chunk", "Alte Datei gelöscht: %s", f)
                except OSError as e:
                    _safe_log_debug("lost_chunk", "Konnte %s nicht löschen: %s", f, e)

            cutoff = time.time() - (max_age_days * 86400)
            for f in files:
                if f.exists() and f.stat().st_mtime < cutoff:
                    try:
                        f.unlink()
                        if DEBUG_LEVEL >= 3:
                            _safe_log_debug(
                                "lost_chunk",
                                "Alte Datei (Alter) gelöscht: %s",
                                f,
                            )
                    except OSError as e:
                        _safe_log_debug(
                            "lost_chunk",
                            "Konnte %s nicht löschen: %s",
                            f,
                            e,
                        )

        except Exception as e:
            _safe_log_debug("lost_chunk", "Cleanup fehlgeschlagen: %s", e)

    def _backup_raw_audio_queue(
        self,
        _force_save: bool = True,
        max_items: int | None = 200,
        timeout: float | None = 10.0,
        cancel_event: threading.Event | None = None,
    ) -> dict[str, Any]:
        """Sichert bis zu `max_items` Audio‑Chunks aus der Rohdaten‑Queue als WAV‑Dateien.
        Jedes entnommene Element wird mit `task_done()` markiert, um die Queue
        konsistent zu halten.
        """
        result: dict[str, Any] = {
            "saved_chunks": 0,
            "total_bytes": 0,
            "errors": 0,
            "queue_was_empty": True,
            "truncated": False,
            "total_chunks_in_queue": -1,
        }
        queue_obj = self._raw_audio_queue
        if queue_obj is None:
            logger.warning(
                "_backup_raw_audio_queue: raw_audio_queue ist None – Abbruch.",
            )
            return result

        try:
            approx_size = queue_obj.qsize()
            result["total_chunks_in_queue"] = approx_size
            if approx_size == 0:
                if DEBUG_LEVEL >= 4:
                    log_debug("backup", "_backup_raw_audio_queue: Queue bereits leer.")
                return result
        except (NotImplementedError, AttributeError):
            approx_size = -1
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "backup",
                    "qsize() nicht verfügbar – schätze Größe durch Iteration.",
                )

        result["queue_was_empty"] = False
        logger.info(
            "🛡️ Sichere Audio‑Chunks aus der raw_audio_queue (max_items=%s, timeout=%ss, queue_size≈%s)...",
            max_items if max_items is not None else "∞",
            timeout,
            approx_size if approx_size >= 0 else "unbekannt",
        )

        saved_count = 0
        saved_bytes = 0
        error_count = 0
        empty_items = 0
        start_time = time.monotonic()
        deadline = start_time + timeout if timeout is not None else None

        while True:
            if cancel_event is not None and cancel_event.is_set():
                logger.info("_backup_raw_audio_queue: Abbruch durch cancel_event.")
                result["truncated"] = True
                break
            if max_items is not None and saved_count >= max_items:
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "backup",
                        f"Maximale Anzahl gesicherter Chunks ({max_items}) erreicht.",
                    )
                result["truncated"] = True
                break
            if deadline is not None and time.monotonic() >= deadline:
                logger.warning(
                    "_backup_raw_audio_queue: Zeitlimit überschritten (%.1fs).",
                    timeout,
                )
                result["truncated"] = True
                break

            item = None
            try:
                item = queue_obj.get_nowait()
            except queue.Empty:
                break
            except Exception as exc:
                logger.error(
                    "_backup_raw_audio_queue: Fehler beim Lesen aus der Queue: %s",
                    exc,
                )
                error_count += 1
                break

            try:
                queue_obj.task_done()
            except ValueError:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "backup",
                        "task_done() ignorierte ValueError (Zähler bereits 0).",
                    )
            except Exception as exc:
                logger.warning("task_done() fehlgeschlagen: %s", exc)

            if item is None:
                continue

            audio_bytes: bytes | None = None
            if (
                isinstance(item, tuple)
                and len(item) >= 1
                and isinstance(item[0], bytes)
            ):
                audio_bytes = item[0]
            elif isinstance(item, bytes):
                audio_bytes = item
            else:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "backup",
                        "Item ohne Audio‑Bytes übersprungen (Typ=%s, Len=%d).",
                        type(item).__name__,
                        len(item) if hasattr(item, "__len__") else -1,
                    )
                empty_items += 1
                continue

            if not audio_bytes or len(audio_bytes) < 16:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "backup",
                        "Audio‑Block zu kurz (%d Bytes) – übersprungen.",
                        len(audio_bytes) if audio_bytes else 0,
                    )
                empty_items += 1
                continue

            try:
                self._save_lost_chunk(audio_bytes, "guaranteed_cleanup_backup")
                saved_count += 1
                saved_bytes += len(audio_bytes)

                if DEBUG_LEVEL >= 2 and saved_count % 10 == 0:
                    log_debug(
                        "backup",
                        "Bereits %d Chunks gesichert (%d Bytes)...",
                        saved_count,
                        saved_bytes,
                    )
            except Exception as exc:
                logger.error("_save_lost_chunk fehlgeschlagen: %s", exc)
                error_count += 1

        result["saved_chunks"] = saved_count
        result["total_bytes"] = saved_bytes
        result["errors"] = error_count

        if saved_count > 0:
            logger.warning(
                "🛡️ %d Audio‑Chunk(s) (%d Bytes) aus der Queue gesichert. "
                "Fehler: %d, leere/schadhafte Elemente: %d, abgebrochen: %s",
                saved_count,
                saved_bytes,
                error_count,
                empty_items,
                result["truncated"],
            )
        elif error_count > 0 or empty_items > 0:
            logger.info(
                "_backup_raw_audio_queue: Keine vollständigen Chunks gesichert "
                "(Fehler=%d, Leer=%d).",
                error_count,
                empty_items,
            )
        elif DEBUG_LEVEL >= 4:
            log_debug("backup", "Queue enthielt keine sicherbaren Daten.")

        return result

    def _download_and_process_remaining(
        self,
        video_url: str,
        start_seconds: float,
        trans_cb: TranscriptionCallback | None = None,
        transl_cb: TranslationCallback | None = None,
        error_cb: ErrorCallback | None = None,
        info_cb: InfoCallback | None = None,
        cancel_event: threading.Event | None = None,
        global_timeout: float | None = None,
    ) -> bool:
        """Lädt den restlichen Teil eines YouTube‑VODs herunter und verarbeitet die Audiodaten."""
        import logging
        import threading
        import time
        from contextlib import suppress

        logger = logging.getLogger("dragon")
        method_start = time.perf_counter()
        callbacks = self._prepare_callbacks(trans_cb, transl_cb, error_cb, info_cb)
        info_callback = (
            callbacks.get("info") if isinstance(callbacks, dict) else info_cb
        )
        error_callback = (
            callbacks.get("error") if isinstance(callbacks, dict) else error_cb
        )
        callbacks.get("transcription") if isinstance(callbacks, dict) else trans_cb
        callbacks.get("translation") if isinstance(callbacks, dict) else transl_cb

        if DEBUG_LEVEL >= 3:
            log_debug(
                "download",
                f"_download_and_process_remaining: START (url={video_url[:50]}..., "
                f"start={start_seconds:.1f}s, timeout={global_timeout or 'None'}, "
                f"cancel={cancel_event is not None})",
            )

        if self._is_download_cancelled(cancel_event):
            self._safe_callback(info_callback, "⏹️ Vorgang abgebrochen")
            self._download_completed_event.set()
            return False

        timeout = self._calculate_global_timeout(start_seconds, global_timeout)
        used_cancel_event = cancel_event or threading.Event()

        if DEBUG_LEVEL >= 3:
            log_debug("download", f"  → Timeout: {timeout:.1f}s")

        timeout_timer = self._start_timeout_timer(timeout, used_cancel_event)

        if not self._reset_for_download():
            logger.error("Reset für Download fehlgeschlagen")
            self._safe_callback(error_callback, "Reset für Download fehlgeschlagen")
            with suppress(Exception):
                timeout_timer.cancel()
            return False

        if self._is_download_cancelled(cancel_event):
            self._safe_callback(info_callback, "⏹️ Vorgang abgebrochen")
            with suppress(Exception):
                timeout_timer.cancel()
            return False

        self._safe_callback(
            info_callback,
            f"⬇️ Lade restliches Audio ab {start_seconds:.1f}s …",
        )

        success = False
        chunk_count = 0
        pending_temp_files: list[str] = []
        download_start = time.perf_counter()

        try:
            if DEBUG_LEVEL >= 3:
                log_debug("download", "  → Versuche Sections-Download...")
            chunk_count = self._try_sections_download(
                video_url,
                start_seconds,
                callbacks,
                used_cancel_event,
            )

            if DEBUG_LEVEL >= 3:
                log_debug("download", f"  → Sections-Download: {chunk_count} Chunks")

            if chunk_count == 0 and not self._is_download_cancelled(cancel_event):
                if DEBUG_LEVEL >= 3:
                    log_debug("download", "  → Fallback auf Full-Download...")
                chunk_count = self._try_full_download_fallback(
                    video_url,
                    start_seconds,
                    callbacks,
                    used_cancel_event,
                    pending_temp_files,
                )
                if DEBUG_LEVEL >= 3:
                    log_debug("download", f"  → Full-Download: {chunk_count} Chunks")

            if chunk_count > 0 and not self._is_download_cancelled(cancel_event):
                if DEBUG_LEVEL >= 3:
                    log_debug("download", "  → Warte auf Queue-Drain (60s)...")
                drain_start = time.perf_counter()
                self._await_queue_drain(timeout=60.0)
                drain_elapsed = time.perf_counter() - drain_start
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "download",
                        f"  → Queue-Drain abgeschlossen in {drain_elapsed:.1f}s",
                    )
                self._synchronize_tasks_done_event()
                if DEBUG_LEVEL >= 3:
                    log_debug("download", "  → Tasks-Done-Event synchronisiert")

            success = chunk_count > 0

        except Exception as exc:
            logger.error(
                f"❌ Unvorhergesehener Fehler im Download‑Modus: {exc}",
                exc_info=DEBUG_LEVEL >= 3,
            )
            self._safe_callback(error_callback, f"Download-Fehler: {str(exc)[:100]}")
            success = False
            chunk_count = 0
        finally:
            elapsed_ms = (time.perf_counter() - method_start) * 1000
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "download",
                    f"_download_and_process_remaining: Cleanup (success={success}, "
                    f"chunks={chunk_count}, elapsed={elapsed_ms:.1f}ms)",
                )

            with suppress(Exception):
                timeout_timer.cancel()

            for temp_file in pending_temp_files:
                with suppress(Exception):
                    if os.path.exists(temp_file):
                        os.unlink(temp_file)
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "download",
                                f"  → Temp‑Datei gelöscht: {temp_file}",
                            )

            if hasattr(self, "_cleanup_download_resources"):
                with suppress(Exception):
                    self._cleanup_download_resources(
                        timeout_timer=timeout_timer,
                        pending_temp_files=pending_temp_files,
                        success=success,
                        chunk_count=chunk_count,
                        download_start=download_start,
                        cancel_event=cancel_event,
                    )

            if hasattr(self, "_download_completed_event"):
                self._download_completed_event.set()

            if success:
                logger.info(
                    f"✅ Download abgeschlossen: {chunk_count} Chunks verarbeitet in {elapsed_ms:.1f}ms",
                )
            else:
                logger.warning(
                    f"⚠️ Download fehlgeschlagen: {chunk_count} Chunks in {elapsed_ms:.1f}ms",
                )

        return success

    def _prepare_callbacks(
        self,
        trans_cb: TranscriptionCallback | None,
        transl_cb: TranslationCallback | None,
        error_cb: ErrorCallback | None,
        info_cb: InfoCallback | None,
    ) -> dict[str, Callable]:
        """Erstellt ein Dict mit No‑Op‑Fallbacks für alle Callbacks."""

        def noop_trans(_):
            pass

        def noop_transl(_):
            pass

        def noop_error(msg):
            logger.warning("Download error (unhandled): %s", msg)

        def noop_info(msg):
            pass

        return {
            "transcription": trans_cb or noop_trans,
            "translation": transl_cb or noop_transl,
            "error": error_cb or noop_error,
            "info": info_cb or noop_info,
        }

    def _calculate_global_timeout(
        self,
        start_seconds: float,
        user_timeout: float | None,
    ) -> float:
        """Berechnet ein angemessenes globales Timeout."""
        if user_timeout is not None:
            return max(60.0, user_timeout)

        expected = getattr(self, "_expected_duration", None)
        if expected is not None:
            remaining = max(1.0, expected - start_seconds)
            return max(60.0, remaining * 1.5)

        with self._stats_lock:
            bytes_processed = self._total_bytes_processed
        if bytes_processed > 0:
            bytes_per_sec = max(1, self.settings.config.BYTES_PER_SECOND)
            estimated_duration = bytes_processed / bytes_per_sec
            remaining = max(30.0, estimated_duration * 0.5)
            return max(60.0, remaining * 1.5)

        return 300.0

    def _is_download_cancelled(self, cancel_event: threading.Event | None) -> bool:
        """Prüft, ob der Download abgebrochen werden soll."""
        if cancel_event is not None and cancel_event.is_set():
            return True
        return self.is_stop_requested()

    def _calculate_download_timeout(
        self,
        start_seconds: float,
        global_timeout: float | None,
    ) -> float:
        """Berechnet das globale Timeout für den Download."""
        if global_timeout is not None:
            return max(10.0, global_timeout)

        expected = getattr(self, "_expected_duration", None)
        if expected is not None:
            remaining = max(1.0, expected - start_seconds)
            return max(60.0, remaining * 1.5)

        with self._stats_lock:
            bytes_processed = self._total_bytes_processed

        if bytes_processed > 0:
            bytes_per_sec = max(1, self.settings.config.BYTES_PER_SECOND)
            estimated_duration = bytes_processed / bytes_per_sec
            remaining = max(30.0, estimated_duration * 0.5)
            return max(60.0, remaining * 1.5)

        return 300.0

    def _get_download_auth_config(self) -> tuple[bool, str | None, str]:
        """Holt Cookie‑ und Proxy‑Konfiguration aus den Einstellungen."""
        use_cookies = getattr(self.stream_manager, "use_browser_cookies", True)
        cookies_browser = None
        if use_cookies:
            cookies_browser = getattr(self.settings, "cookies_browser", None)
            if not cookies_browser:
                try:
                    app_settings = AppSettings.load_from_file()
                    cookies_browser = getattr(
                        app_settings,
                        "cookies_browser",
                        "firefox",
                    )
                except Exception:
                    cookies_browser = "firefox"

        proxy_enabled = getattr(self.settings, "proxy_enabled", False)
        proxy_url = getattr(self.settings, "proxy_url", "") if proxy_enabled else ""
        return use_cookies, cookies_browser, proxy_url

    def _build_download_strategies(
        self,
        start_seconds: int,
        video_url: str,
        use_cookies: bool,
        cookies_browser: str | None,
        proxy_url: str,
        *,
        return_metadata: bool = False,
    ) -> list[dict] | tuple[list[dict], dict]:
        """Erstellt eine Liste von Download-Strategien (Client × Format) für yt-dlp."""
        import time

        t_start = time.monotonic()
        call_id = f"bds-{int(t_start * 1000) % 1000000}"
        debug_enabled = DEBUG_LEVEL >= 3
        trace_enabled = DEBUG_LEVEL >= 4

        if not isinstance(video_url, str) or not video_url.strip():
            logger.warning(
                f"[{call_id}] _build_download_strategies: "
                f"video_url ungültig (leer/nicht-String) – keine Strategien"
            )
            return self._bds_empty_result(return_metadata, t_start)

        video_url = video_url.strip()
        original_start = start_seconds
        try:
            start_seconds = int(start_seconds)
        except (TypeError, ValueError):
            logger.warning(
                f"[{call_id}] start_seconds={original_start!r} ungültig – verwende 0"
            )
            start_seconds = 0
        if start_seconds < 0:
            start_seconds = 0

        if cookies_browser is not None and not isinstance(cookies_browser, str):
            if debug_enabled:
                log_debug(
                    "download",
                    f"[{call_id}] cookies_browser ist {type(cookies_browser).__name__} "
                    f"– wird ignoriert",
                )
            cookies_browser = None
        if isinstance(cookies_browser, str):
            cookies_browser = cookies_browser.strip() or None

        if not isinstance(proxy_url, str):
            proxy_url = ""
        proxy_url = proxy_url.strip()
        url_lower = video_url.lower()
        url_is_youtube = (
            "youtube.com" in url_lower
            or "youtu.be" in url_lower
            or "youtube-nocookie.com" in url_lower
        )

        default_formats = (
            "bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio/best",
            "bestaudio/best",
            "worstaudio",
            "best",
        )

        formats = self._bds_resolve_formats(default_formats, call_id, debug_enabled)
        all_clients = ("android", "web", "ios")

        if url_is_youtube:
            clients = all_clients
            use_client_in_cmd = True
            deduplicated = False
        else:
            clients = ("default",)
            use_client_in_cmd = False
            deduplicated = True
            if debug_enabled:
                log_debug(
                    "download",
                    f"[{call_id}] Nicht-YouTube-URL – Client-Differenzierung "
                    f"deaktiviert (nur 1 Client statt 3)",
                )

        use_cookies_effective = bool(use_cookies and cookies_browser)
        proxy_effective = bool(proxy_url)

        if debug_enabled:
            log_debug(
                "download",
                f"[{call_id}] Strategie-Aufbau: "
                f"clients={len(clients)}, formats={len(formats)}, "
                f"cookies={'ja' if use_cookies_effective else 'nein'}, "
                f"proxy={'ja' if proxy_effective else 'nein'}, "
                f"youtube={'ja' if url_is_youtube else 'nein'}, "
                f"start={start_seconds}s",
            )

        strategies: list[dict] = []
        strategy_errors: list[str] = []

        for client in clients:
            for fmt in formats:
                try:
                    cmd = self._bds_build_cmd(
                        video_url=video_url,
                        fmt=fmt,
                        start_seconds=start_seconds,
                        use_cookies=use_cookies_effective,
                        cookies_browser=cookies_browser,
                        proxy_url=proxy_url if proxy_effective else "",
                        client=client if use_client_in_cmd else None,
                    )

                    if not cmd:
                        strategy_errors.append(f"{client}/{fmt[:30]}: leeres cmd")
                        continue

                    is_emergency = fmt in ("worstaudio", "best")

                    strategies.append(
                        {
                            "client": client,
                            "format": fmt,
                            "cmd": cmd,
                            "index": len(strategies) + 1,
                            "is_emergency": is_emergency,
                        }
                    )

                    if trace_enabled:
                        log_debug(
                            "download",
                            f"[{call_id}] Strategie #{len(strategies)} "
                            f"({client}/{fmt[:40]}): {len(cmd)} args",
                        )

                except Exception as e:
                    msg = f"{client}/{fmt[:30]}: {type(e).__name__}: {e}"
                    strategy_errors.append(msg)
                    logger.warning(f"[{call_id}] {msg}")

        if not strategies:
            logger.error(
                f"[{call_id}] _build_download_strategies: KEINE Strategien "
                f"erzeugt ({len(strategy_errors)} Fehler)"
            )
            return self._bds_empty_result(return_metadata, t_start)

        duration_ms = (time.monotonic() - t_start) * 1000

        if debug_enabled:
            formats_summary = " | ".join(
                f"{i + 1}:{f[:25]}{'…' if len(f) > 25 else ''}"
                for i, f in enumerate(formats)
            )
            log_debug(
                "download",
                f"[{call_id}] ✅ {len(strategies)} Strategien "
                f"({len(clients)} Client × {len(formats)} Formats) "
                f"in {duration_ms:.2f}ms. Formate: [{formats_summary}]",
            )

        if trace_enabled and strategies:
            masked = self._bds_mask_cmd(strategies[0]["cmd"])
            log_debug(
                "download",
                f"[{call_id}] Erste Strategie (maskiert): {' '.join(masked[:14])}...",
            )

        if return_metadata:
            metadata = {
                "total": len(strategies),
                "clients_used": list(clients),
                "formats_used": list(formats),
                "url_is_youtube": url_is_youtube,
                "cookies_used": use_cookies_effective,
                "proxy_used": proxy_effective,
                "deduplicated": deduplicated,
                "strategy_errors": strategy_errors,
                "duration_ms": duration_ms,
            }
            return strategies, metadata

        return strategies

    def _bds_resolve_formats(
        self,
        default_formats: tuple[str, ...],
        call_id: str,
        debug_enabled: bool,
    ) -> tuple[str, ...]:
        """Löst die Format-Liste auf – mit Dedupe und Fallback auf Defaults."""
        try:
            settings = getattr(self, "settings", None)
            custom = getattr(settings, "yt_dlp_format_fallbacks", None)

            if not custom or not isinstance(custom, (list, tuple)):
                return default_formats

            seen: set[str] = set()
            resolved: list[str] = []
            for f in custom:
                if not isinstance(f, str):
                    continue
                f_clean = f.strip()
                if not f_clean or f_clean in seen:
                    continue
                seen.add(f_clean)
                resolved.append(f_clean)

            if not resolved:
                return default_formats

            if debug_enabled:
                log_debug(
                    "download",
                    f"[{call_id}] Custom-Formats: {len(resolved)} Einträge "
                    f"(von {len(custom)} gegeben, {len(custom) - len(resolved)} "
                    f"dedupliziert)",
                )

            return tuple(resolved)

        except Exception as e:
            if debug_enabled:
                log_debug(
                    "download",
                    f"[{call_id}] Custom-Format-Auflösung fehlgeschlagen: {e} "
                    f"– verwende Defaults",
                )
            return default_formats

    def _bds_build_cmd(
        self,
        video_url: str,
        fmt: str,
        start_seconds: int,
        use_cookies: bool,
        cookies_browser: str | None,
        proxy_url: str,
        client: str | None,
    ) -> list[str]:
        """Baut einen yt-dlp-Befehl für eine Strategie."""
        cmd = ["yt-dlp", "-f", fmt]

        if use_cookies and cookies_browser:
            cmd.extend(["--cookies-from-browser", cookies_browser])

        if client and client != "web":
            cmd.extend(
                [
                    "--extractor-args",
                    f"youtube:player_client={client}",
                ]
            )

        if proxy_url:
            cmd.extend(["--proxy", proxy_url])

        cmd.extend(
            [
                "--download-sections",
                f"*{start_seconds}-inf",
                "--force-keyframes-at-cuts",
                "--no-playlist",
                "--quiet",
                "--no-warnings",
                "--socket-timeout",
                "30",
                "--retries",
                "3",
                "--fragment-retries",
                "3",
                "-o",
                "-",
                "--",
                video_url,
            ]
        )

        return cmd

    def _bds_mask_cmd(self, cmd: list[str]) -> list[str]:
        """Maskiert sensitive Werte in einem yt-dlp-Befehl für Logs."""
        masked = list(cmd)
        for i, part in enumerate(masked):
            if part == "--cookies-from-browser" and i + 1 < len(masked):
                masked[i + 1] = "<browser>"
            elif part == "--proxy" and i + 1 < len(masked):
                masked[i + 1] = "<proxy-url>"
            elif part == "--extractor-args" and i + 1 < len(masked):
                if "player_client" in masked[i + 1]:
                    masked[i + 1] = "<extractor-args>"
            elif part.startswith("http") and i == len(masked) - 1:
                masked[i] = "<url>"
        return masked

    def _bds_empty_result(
        self,
        return_metadata: bool,
        t_start: float,
    ) -> list[dict] | tuple[list[dict], dict]:
        """Liefert ein konsistentes leeres Ergebnis."""
        import time

        if return_metadata:
            return [], {
                "total": 0,
                "clients_used": [],
                "formats_used": [],
                "url_is_youtube": False,
                "cookies_used": False,
                "proxy_used": False,
                "deduplicated": False,
                "strategy_errors": ["empty_result"],
                "duration_ms": (time.monotonic() - t_start) * 1000,
            }
        return []

    def _safe_callback(self, cb: Callable | None, *args: Any, **kwargs: Any) -> None:
        """Ruft einen Callback sicher auf – fängt alle Exceptions ab."""
        AudioProcessor.safe_callback(cb, *args, **kwargs)

    @staticmethod
    def _noop_trans_cb(result: TranscriptionResult) -> None:
        pass

    @staticmethod
    def _noop_transl_cb(result: TranslationResult) -> None:
        pass

    @staticmethod
    def _noop_error_cb(message: str) -> None:
        logger.warning("Download error (unhandled): %s", message)

    @staticmethod
    def _noop_info_cb(message: str) -> None:
        pass

    def _start_timeout_timer(
        self,
        timeout: float,
        cancel_event: threading.Event,
    ) -> threading.Timer | None:
        """Startet einen Timeout-Timer, der das cancel_event setzt."""
        if timeout <= 0:
            return None

        timer = threading.Timer(timeout, cancel_event.set)
        timer.daemon = True
        timer.start()

        if DEBUG_LEVEL >= 3:
            log_debug("DOWNLOAD", "Globaler Timeout‑Timer gestartet: %.1fs", timeout)

        return timer

    def _reset_for_download(self) -> bool:
        """Setzt den AudioProcessor für den Download‑Modus zurück und startet
        den Dispatcher neu, damit die heruntergeladenen Chunks verarbeitet werden.
        """
        logger.debug("🔄 Download-Modus: Beende vorherige Transkriptionen…")

        if self._dispatcher_started:
            self._stop_dispatcher(clear_queue=True)

        self._wait_for_pending_tasks()

        with self._pending_tasks_cond:
            if self._pending_tasks > 0:
                logger.warning(
                    "Nach _wait_for_pending_tasks noch %d Tasks – erzwungener Reset.",
                    self._pending_tasks,
                )
                self._pending_tasks = 0
                self._pending_tasks_cond.notify_all()

        self._synchronize_tasks_done_event()
        self._init_transcription_executor()
        self._shutdown_translation_executor()
        self._init_translation_executor()
        self._clear_all_buffers()
        self._synchronize_tasks_done_event()

        if not self._start_or_restart_dispatcher():
            logger.error("❌ Dispatcher konnte nach Reset nicht gestartet werden!")
            return False

        logger.debug("✅ Download-Modus: Reset abgeschlossen, Dispatcher läuft.")
        return True

    def _try_sections_download(
        self,
        video_url: str,
        start_seconds: float,
        callbacks: dict,
        cancel_event: threading.Event,
    ) -> int:
        """Versucht den Download mit --download-sections (nur den fehlenden Teil)."""
        if not self._supports_download_sections():
            return 0

        max_retries = 2
        for attempt in range(1, max_retries + 1):
            if self._is_download_cancelled(cancel_event):
                break

            try:
                chunk_count = self._download_with_ytdlp_sections(
                    video_url,
                    start_seconds,
                    trans_cb=callbacks["transcription"],
                    transl_cb=callbacks["translation"],
                    error_cb=callbacks["error"],
                    info_cb=callbacks["info"],
                    cancel_event=cancel_event,
                )
                if chunk_count > 0:
                    logger.info(
                        "✅ --download-sections erfolgreich (%d Chunks, Versuch %d)",
                        chunk_count,
                        attempt,
                    )
                    return chunk_count

                if attempt < max_retries:
                    delay = min(2.0, 0.5 * (2 ** (attempt - 1)))
                    logger.info(
                        "Keine Chunks – wiederhole in %.1fs (Versuch %d/%d)",
                        delay,
                        attempt + 1,
                        max_retries,
                    )
                    time.sleep(delay)

            except Exception as e:
                logger.error(
                    "Fehler in _download_with_ytdlp_sections (Versuch %d): %s",
                    attempt,
                    e,
                    exc_info=True,
                )
                if self._is_permanent_error(e):
                    logger.warning("Permanenter Fehler – überspringe Fallback")
                    break
                if attempt < max_retries:
                    delay = min(5.0, 1.0 * (2 ** (attempt - 1)))
                    time.sleep(delay)
        return 0

    def _try_full_download_fallback(
        self,
        video_url: str,
        start_seconds: float,
        callbacks: dict,
        cancel_event: threading.Event,
        pending_temp_files: list[str],
    ) -> int:
        """Fallback: Lädt das gesamte Video herunter und trimmt es mit ffmpeg.
        Verwendet tempfile mit delete=True, um große Dateien automatisch zu löschen.
        """
        logger.info("🔄 Fallback: Lade gesamtes Audio und schneide mit ffmpeg zu")

        try:
            info = self._get_video_info(video_url)
            filesize = info.get("filesize_approx") or info.get("filesize")
            if filesize and filesize > 500 * 1024 * 1024:
                self._safe_callback(
                    callbacks["info"],
                    f"⚠️ Video ist {filesize // (1024 * 1024)} MB groß – Full‑Download kann lange dauern.",
                )
                if filesize > 2 * 1024 * 1024 * 1024:
                    logger.warning(
                        "Video >2 GB – Fallback abgebrochen, um Speicher zu sparen.",
                    )
                    self._safe_callback(
                        callbacks["info"],
                        "❌ Video zu groß für Full‑Download",
                    )
                    return 0
        except Exception as e:
            logger.warning("Konnte Dateigröße nicht ermitteln: %s", e)

        max_retries = 2
        for attempt in range(1, max_retries + 1):
            if self._is_download_cancelled(cancel_event):
                break

            try:
                chunk_count = self._download_full_and_seek(
                    video_url,
                    start_seconds,
                    trans_cb=callbacks["transcription"],
                    transl_cb=callbacks["translation"],
                    error_cb=callbacks["error"],
                    info_cb=callbacks["info"],
                    cancel_event=cancel_event,
                    temp_file_callback=lambda path: (
                        pending_temp_files.append(path) if path else None
                    ),
                )
                if chunk_count > 0:
                    logger.info(
                        "✅ Fallback erfolgreich (%d Chunks, Versuch %d)",
                        chunk_count,
                        attempt,
                    )
                    return chunk_count

                if attempt < max_retries:
                    delay = min(2.0, 0.5 * (2 ** (attempt - 1)))
                    logger.info(
                        "Fallback lieferte keine Chunks – wiederhole in %.1fs",
                        delay,
                    )
                    time.sleep(delay)

            except Exception as e:
                logger.error(
                    "Fehler in _download_full_and_seek (Versuch %d): %s",
                    attempt,
                    e,
                    exc_info=True,
                )
                if self._is_permanent_error(e):
                    logger.warning("Permanenter Fehler im Fallback – breche ab")
                    break
                if attempt < max_retries:
                    delay = min(5.0, 1.0 * (2 ** (attempt - 1)))
                    time.sleep(delay)

        return 0

    def _cleanup_download_resources(
        self,
        timeout_timer: threading.Timer | None,
        pending_temp_files: list[str],
        success: bool,
        chunk_count: int,
        download_start: float,
        cancel_event: threading.Event | None,
    ) -> None:
        """Führt die finale Bereinigung nach dem Download durch."""
        if timeout_timer is not None:
            try:
                timeout_timer.cancel()
                if DEBUG_LEVEL >= 3:
                    log_debug("DOWNLOAD", "Globaler Timeout‑Timer abgebrochen")
            except Exception as e:
                logger.debug("Fehler beim Abbrechen des Timeout-Timers: %s", e)

        for tmp_path in pending_temp_files:
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
                    if DEBUG_LEVEL >= 3:
                        log_debug("DOWNLOAD", f"Temp‑Datei gelöscht: {tmp_path}")
            except OSError as e:
                logger.warning(
                    "Konnte temporäre Datei %s nicht löschen: %s",
                    tmp_path,
                    e,
                )

        try:
            self._cleanup_temp_files()
        except Exception as e:
            logger.warning("Fehler bei _cleanup_temp_files: %s", e)

        if not success or self._is_download_cancelled(cancel_event):
            logger.debug("Download‑Modus: Erzwinge sauberen Dispatcher‑Reset")
            try:
                self._stop_dispatcher(clear_queue=True)
            except Exception as e:
                logger.warning("Fehler beim Zurücksetzen des Dispatchers: %s", e)
            self._synchronize_tasks_done_event()

        self._finalize_download(
            chunk_count,
            download_start,
            self._is_download_cancelled(cancel_event),
        )

        if DEBUG_LEVEL >= 2:
            log_debug(
                "DOWNLOAD",
                "Download-Modus beendet: success=%s, chunks=%d, dauer=%.1fs",
                success,
                chunk_count,
                time.perf_counter() - download_start,
            )

    def _execute_download_strategy(
        self,
        video_url: str,
        start_seconds: float,
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        error_cb: ErrorCallback,
        info_cb: InfoCallback,
        cancel_event: threading.Event,
        max_retries: int = 2,
    ) -> int:
        """Führt die Download-Strategie mit Wiederholungen aus."""
        chunk_count = 0

        strategies = [
            ("--download-sections", self._download_with_ytdlp_sections),
            ("full + seek", self._download_full_and_seek),
        ]

        for attempt in range(max_retries + 1):
            for strategy_name, strategy_func in strategies:
                if self._is_download_cancelled(cancel_event):
                    return chunk_count

                if attempt > 0:
                    delay = min(5.0, 1.0 * (2 ** (attempt - 1)))
                    logger.info(
                        "Warte %.1fs vor Wiederholung (Versuch %d/%d)",
                        delay,
                        attempt + 1,
                        max_retries + 1,
                    )
                    time.sleep(delay)

                try:
                    logger.info(
                        "Versuche Strategie '%s' (Versuch %d/%d)",
                        strategy_name,
                        attempt + 1,
                        max_retries + 1,
                    )
                    chunk_count = strategy_func(
                        video_url=video_url,
                        start_seconds=start_seconds,
                        trans_cb=trans_cb,
                        transl_cb=transl_cb,
                        error_cb=error_cb,
                        info_cb=info_cb,
                        cancel_event=cancel_event,
                    )
                    if chunk_count > 0:
                        logger.info(
                            "✅ Strategie '%s' erfolgreich (%d Chunks)",
                            strategy_name,
                            chunk_count,
                        )
                        return chunk_count
                    logger.warning("Strategie '%s' lieferte 0 Chunks", strategy_name)
                except Exception as e:
                    logger.error(
                        "Fehler in Strategie '%s': %s",
                        strategy_name,
                        e,
                        exc_info=True,
                    )
                    if self._is_permanent_error(e):
                        logger.warning("Permanenter Fehler – breche ab")
                        return chunk_count

        return chunk_count

    def _safe_delattr(self, attr_name: str) -> None:
        """Sicherer Löschvorgang für ein Attribut (falls vorhanden).
        Verhindert AttributeError, wenn das Attribut nicht existiert.
        """
        if hasattr(self, attr_name):
            try:
                delattr(self, attr_name)
                if DEBUG_LEVEL >= 4:
                    logger.debug(f"[AudioProcessor] Attribut '{attr_name}' gelöscht")
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    logger.debug(
                        f"[AudioProcessor] Konnte Attribut '{attr_name}' nicht löschen: {e}",
                    )
        elif DEBUG_LEVEL >= 4:
            logger.debug(
                f"[AudioProcessor] Attribut '{attr_name}' nicht vorhanden – überspringe",
            )

    def _finalize_download_cleanup(
        self,
        timeout_timer: threading.Timer | None,
        download_success: bool,
        chunk_count: int,
        download_start: float,
        cancel_event: threading.Event,
    ) -> None:
        """Führt die finale Bereinigung nach dem Download durch."""
        if timeout_timer is not None:
            try:
                timeout_timer.cancel()
                if DEBUG_LEVEL >= 3:
                    log_debug("DOWNLOAD", "Globaler Timeout‑Timer abgebrochen")
            except Exception as e:
                logger.debug("Fehler beim Abbrechen des Timeout-Timers: %s", e)

        if not download_success or self._is_download_cancelled(cancel_event):
            logger.debug("Download‑Modus: Erzwinge sauberen Dispatcher‑Reset")
            self._stop_dispatcher(clear_queue=True)
            self._synchronize_tasks_done_event()

        self._finalize_download(
            chunk_count,
            download_start,
            self._is_download_cancelled(cancel_event),
        )

    def _clear_all_buffers(self) -> None:
        """Zentrale Reset‑Funktion für den AudioProcessor.
        Setzt alle Puffer, Caches, Zähler und Flags zurück – mit maximaler Robustheit.
        """
        import gc
        import time
        from contextlib import contextmanager

        logger.debug("[_clear_all_buffers] 🧹 Starte vollständige Bereinigung...")

        @contextmanager
        def _with_lock(lock_attr: str):
            """Sicherer Lock‑Context‑Manager – fallback auf Dummy bei fehlendem Lock."""
            lock = getattr(self, lock_attr, None)
            if lock is not None and hasattr(lock, "__enter__"):
                with lock:
                    yield
            else:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "processor",
                        f"[_clear_all_buffers] Lock '{lock_attr}' nicht verfügbar – verwende Dummy",
                    )
                yield

        def _safe_step(step_name: str, action: Callable[[], None]) -> None:
            """Führt einen Schritt aus, protokolliert Fehler und misst die Zeit."""
            start = time.perf_counter()
            try:
                action()
                elapsed = (time.perf_counter() - start) * 1000
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "processor",
                        f"[_clear_all_buffers] ✅ {step_name} – {elapsed:.2f} ms",
                    )
            except Exception as exc:
                elapsed = (time.perf_counter() - start) * 1000
                logger.warning(
                    "[_clear_all_buffers] ❌ Schritt '%s' fehlgeschlagen (%.2f ms): %s",
                    step_name,
                    elapsed,
                    exc,
                )
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "processor",
                        f"Fehler in Schritt '{step_name}'",
                        exc,
                        level="debug",
                    )

        def _safe_clear_attr(attr_name: str) -> None:
            """Sicherer Löschvorgang für ein Attribut – verwendet hasattr-Prüfung.
            Ersetzt die fehlende _safe_delattr-Methode.
            """
            if hasattr(self, attr_name):
                try:
                    delattr(self, attr_name)
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "processor",
                            f"[_clear_all_buffers] ✅ Attribut '{attr_name}' gelöscht",
                        )
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "processor",
                            f"[_clear_all_buffers] ⚠️ Konnte Attribut '{attr_name}' nicht löschen: {e}",
                        )
            elif DEBUG_LEVEL >= 4:
                log_debug(
                    "processor",
                    f"[_clear_all_buffers] ℹ️ Attribut '{attr_name}' nicht vorhanden – überspringe",
                )

        steps = [
            (
                "clear_duplicate_and_flushed",
                "_duplicate_lock",
                lambda: (
                    self._safe_clear("_last_chunk_hashes"),
                    self._safe_clear("_already_flushed_texts"),
                    self._safe_clear("_flushed_combined_texts"),
                    self._safe_clear("_recent_transcriptions"),
                    self._safe_clear("_already_flushed_cache"),
                    setattr(self, "_last_transcription_text", ""),
                    setattr(self, "_last_translation_text", ""),
                ),
            ),
            (
                "clear_audio_buffer",
                "_buffer_lock",
                lambda: (
                    self._safe_clear("_audio_chunks"),
                    setattr(self, "_audio_total_bytes", 0),
                    setattr(self, "_last_chunk_tail", b""),
                    self._safe_clear("_overflow_chunks"),
                    setattr(self, "_overflow_worker_started", False),
                ),
            ),
            (
                "reset_segment_buffer",
                "_segment_buffer_lock",
                lambda: (
                    self._safe_clear("_segment_buffer"),
                    self._safe_clear("_segment_keys"),
                    self._safe_clear("_sorted_keys_cache"),
                    self._safe_clear("_integrity_segments"),
                    setattr(self, "_segment_counter", 0),
                    setattr(self, "_next_expected_start", 0.0),
                    setattr(self, "_subtitle_watchdog_time", time.monotonic()),
                ),
            ),
            (
                "reset_transcript_sentence_buffer",
                "_sentence_lock",
                lambda: (
                    self._safe_clear("_transcript_parts"),
                    self._safe_clear("_transcript_segments"),
                    setattr(self, "_transcript_last_flush", 0.0),
                    setattr(self, "_transcript_segments_since_flush", 0),
                ),
            ),
            (
                "reset_sentence_buffer",
                "_sentence_lock",
                lambda: (
                    self._safe_clear("_sentence_parts"),
                    self._safe_clear("_sentence_segments"),
                    setattr(self, "_last_sentence_time", 0.0),
                ),
            ),
            (
                "drain_raw_audio_queue",
                None,
                lambda: self._drain_queue_safe(getattr(self, "_raw_audio_queue", None)),
            ),
            (
                "clear_subtitle_buffers",
                "_subtitle_lock",
                lambda: (
                    self._safe_clear("_timed_transcriptions"),
                    self._safe_clear("_timed_translations"),
                ),
            ),
            (
                "reset_stats",
                "_stats_lock",
                lambda: (
                    setattr(self, "_chunk_counter", 0),
                    setattr(self, "_total_bytes_processed", 0),
                    setattr(self, "_processed_seconds", 0.0),
                    setattr(self, "_real_processed_seconds", 0.0),
                    setattr(self, "_empty_reads", 0),
                    setattr(self, "_consecutive_errors", 0),
                    setattr(self, "_consecutive_timeouts", 0),
                    setattr(self, "_consecutive_successes", 0),
                    setattr(self, "_low_conf_counter", 0),
                    setattr(self, "_slow_chunks", 0),
                    setattr(self, "_last_realtime_factor", 0.0),
                    setattr(self, "_last_chunk_processing_time", 0.0),
                    setattr(self, "_queue_drop_counter", 0),
                    setattr(self, "_queue_enqueue_counter", 0),
                    setattr(self, "_queue_dequeue_counter", 0),
                    setattr(self, "_consecutive_queue_drops", 0),
                    setattr(self, "_last_queue_log_time", 0.0),
                    setattr(self, "_last_perf_log_time", 0.0),
                    setattr(self, "_last_gpu_stats_time", 0.0),
                    self._safe_clear("_read_durations"),
                    self._safe_clear("_error_timestamps"),
                    self._safe_clear("_slow_read_counter"),
                ),
            ),
            (
                "reset_adaptive_chunk",
                "_word_count_lock",
                lambda: (
                    self._safe_clear("_word_count_history"),
                    self._safe_clear("_adaptive_queue_history"),
                    self._safe_clear("_queue_size_history"),
                    setattr(self, "_smoothed_word_count", None),
                    setattr(
                        self,
                        "_last_chunk_duration",
                        self.settings.config.CHUNK_DURATION,
                    ),
                    setattr(self, "_chunk_stable_counter", 0),
                    setattr(self, "_chunk_adjust_count", 0),
                    setattr(self, "_consecutive_high_queue", 0),
                    setattr(self, "_consecutive_low_queue", 0),
                    setattr(self, "_last_chunk_adjust_time", 0.0),
                    setattr(
                        self,
                        "_adaptive_bytes_per_sec",
                        float(self.settings.config.BYTES_PER_SECOND),
                    ),
                    setattr(self, "_adaptive_warmup_chunks", 0),
                ),
            ),
            (
                "reset_music_silence",
                "_music_silence_lock",
                lambda: (
                    setattr(self, "_consecutive_music_chunks", 0),
                    setattr(self, "_consecutive_silence_chunks", 0),
                    setattr(self, "_music_state_active", False),
                    setattr(self, "_silence_state_active", False),
                    setattr(self, "_last_music_event_time", 0.0),
                ),
            ),
            (
                "clear_transcript_queue",
                "_transcript_queue_lock",
                lambda: (
                    self._safe_clear("_transcript_queue"),
                    setattr(self, "_next_expected_transcript_start", 0.0),
                    setattr(self, "_transcript_segments_since_flush", 0),
                    setattr(self, "_last_transcript_transfer_time", 0.0),
                ),
            ),
            (
                "clear_translation_queue",
                "_translation_queue_lock",
                lambda: (
                    self._safe_clear("_translation_queue"),
                    setattr(self, "_next_expected_translation_start", 0.0),
                    setattr(self, "_translation_seq", 0),
                    self._safe_clear("_translation_flush_timer"),
                ),
            ),
            (
                "clear_tts_drossel",
                "_tts_drossel_lock",
                lambda: (
                    setattr(self, "_tts_pending_count", 0),
                    _safe_clear_attr("_tts_original_workers"),
                ),
            ),
            (
                "clear_overflow_buffer",
                "_overflow_lock",
                lambda: (
                    self._safe_clear("_overflow_chunks"),
                    setattr(self, "_overflow_worker_started", False),
                ),
            ),
            (
                "reset_timestamps_and_offsets",
                None,
                lambda: (
                    self._safe_clear("_offset_history"),
                    self._safe_clear("_raw_drift_history"),
                    self._safe_clear("_correction_history"),
                    self._safe_clear("_actual_bytes_history"),
                    self._safe_clear("_drift_delta_history"),
                    setattr(self, "_smoothed_drift", 0.0),
                    setattr(self, "_last_correction", 0),
                    setattr(self, "_total_correction_applied", 0),
                    setattr(self, "_consecutive_large_drift", 0),
                    setattr(self, "_reset_counter", 0),
                    setattr(self, "_reset_cooldown", 0),
                    setattr(self, "_monotonic_offset", 0.0),
                    setattr(self, "_last_output_timestamp", 0.0),
                    setattr(self, "_last_drift_warning_time", 0.0),
                ),
            ),
            (
                "reset_stream_flags",
                None,
                lambda: (
                    setattr(self, "_stream_loop_started", False),
                    setattr(self, "_download_mode_active", False),
                    setattr(self, "_download_completed_event", threading.Event()),
                    setattr(self, "_finalizing", False),
                    setattr(self, "_in_final_flush", threading.Event()),
                    setattr(self, "_shutdown_pending_tasks", False),
                    setattr(self, "_final_cleanup_started", False),
                    setattr(self, "_current_stream_id", None),
                    setattr(self, "_stream_start_time", None),
                    setattr(self, "_last_chunk_start_time", 0.0),
                    setattr(self, "_last_chunk_end", 0.0),
                    setattr(self, "_last_chunk_tail", b""),
                    self._safe_clear("_pending_transcript_segments"),
                ),
            ),
            (
                "reset_translation_watchdog",
                None,
                lambda: (
                    setattr(self, "_translation_watchdog_error_count", 0),
                    setattr(self, "_translation_watchdog_disabled_until", 0.0),
                    self._safe_clear("_translation_watchdog_lock"),
                ),
            ),
            (
                "reset_pending_tasks",
                "_pending_tasks_lock",
                lambda: self._reset_pending_tasks(),
            ),
            (
                "cancel_timeout_futures",
                "_timeout_futures_lock",
                lambda: (
                    (
                        self._cancel_all_timeout_futures()
                        if hasattr(self, "_cancel_all_timeout_futures")
                        else None
                    ),
                    self._safe_clear("_active_timeout_futures"),
                ),
            ),
            (
                "synchronize_tasks_done_event",
                None,
                lambda: self._synchronize_tasks_done_event(),
            ),
            ("trigger_gc", None, lambda: gc.collect()),
        ]

        for step_name, lock_attr, action in steps:
            if lock_attr is None:
                _safe_step(step_name, action)
            else:
                with _with_lock(lock_attr):
                    _safe_step(step_name, action)

        if DEBUG_LEVEL >= 3:
            try:
                with self._pending_tasks_cond:
                    pending = self._pending_tasks
                    if pending != 0:
                        logger.warning(
                            "[_clear_all_buffers] ⚠️ pending_tasks nach Reset: %d (sollte 0 sein) – Korrektur",
                            pending,
                        )
                        self._pending_tasks = 0
                        self._pending_tasks_cond.notify_all()
                if not self._tasks_done_event.is_set():
                    logger.warning(
                        "[_clear_all_buffers] ⚠️ _tasks_done_event wurde nicht gesetzt – wird nachgeholt",
                    )
                    self._tasks_done_event.set()
            except Exception as e:
                logger.debug(
                    "[_clear_all_buffers] Integritätsprüfung fehlgeschlagen: %s",
                    e,
                )

        if DEBUG_LEVEL >= 2:
            log_debug(
                "processor",
                "[_clear_all_buffers] ✅ Alle Puffer, Caches, Zähler und Flags zurückgesetzt",
            )
        else:
            logger.info("🧹 AudioProcessor: Alle internen Puffer wurden zurückgesetzt.")

    def reset_all(self) -> None:
        """Setzt den AudioProcessor vollständig zurück – threadsicher, fehlertolerant,
        mit Timeout für stop_processing und detailliertem Debug-Logging.
        WICHTIG: Callbacks (Transkription, Übersetzung, Fehler) werden NICHT gelöscht.
        """
        import logging
        import time
        from contextlib import suppress

        logger = logging.getLogger("dragon")
        logger.debug("🔄 AudioProcessor.reset_all() gestartet (optimierte Version)")

        if not hasattr(self, "_reset_lock"):
            self._reset_lock = threading.RLock()
        with self._reset_lock:
            start_time = time.perf_counter()

            try:
                logger.debug(
                    "  ⏳ stop_processing(force=True, wait=False, timeout=1.0) ..."
                )
                self.stop_processing(force=True, wait=False, timeout=1.0)
                logger.debug("  ✅ stop_processing() angestoßen (nicht blockierend)")
            except Exception as e:
                logger.warning(
                    f"  ⚠️ stop_processing() fehlgeschlagen: {e} – fahre fort"
                )

            try:
                current = self._state
                if current != self.State.IDLE:
                    self._set_state(self.State.IDLE)
                    logger.debug(f"  ✅ Zustand {current} → IDLE")
                else:
                    logger.debug("  ℹ️ Zustand bereits IDLE")
            except Exception as e:
                logger.warning(f"  ⚠️ Zustand konnte nicht gesetzt werden: {e}")

            try:
                logger.debug("  ⏳ _clear_all_buffers() ...")
                self._clear_all_buffers()
                logger.debug("  ✅ _clear_all_buffers() abgeschlossen")
            except Exception as e:
                logger.error(f"  ❌ _clear_all_buffers() fehlgeschlagen: {e}")

            if hasattr(self, "_reset_engine_fallback"):
                with suppress(Exception):
                    self._reset_engine_fallback()
                    logger.debug("  ✅ _reset_engine_fallback() abgeschlossen")
            else:
                logger.debug("  ℹ️ Kein _reset_engine_fallback() vorhanden")

            with suppress(Exception):
                self._tasks_done_event.set()
                logger.debug("  ✅ _tasks_done_event gesetzt")
            with self._pending_tasks_cond:
                self._pending_tasks = 0
                self._pending_tasks_cond.notify_all()
                logger.debug("  ✅ Tasks zurückgesetzt (pending=0)")

            if hasattr(self, "_shutdown_event"):
                with suppress(Exception):
                    self._shutdown_event.clear()
                    logger.debug("  ✅ _shutdown_event gelöscht")
            else:
                logger.debug("  ℹ️ Kein _shutdown_event vorhanden")

            if hasattr(self, "_translation_flush_timer"):
                with suppress(Exception):
                    self._translation_flush_timer.cancel()
                    self._translation_flush_timer = None
                    logger.debug("  ✅ Translation‑Flush‑Timer abgebrochen")
            else:
                logger.debug("  ℹ️ Kein _translation_flush_timer vorhanden")

            for flag in (
                "_stop_in_progress",
                "_finalizing",
                "_dispatcher_shutdown_in_progress",
            ):
                if hasattr(self, flag):
                    with suppress(AttributeError):
                        setattr(self, flag, False)
                        logger.debug(f"  ✅ Flag {flag} zurückgesetzt")
                else:
                    logger.debug(f"  ℹ️ Flag {flag} nicht vorhanden")

            logger.debug("  ℹ️ Callbacks bleiben unverändert erhalten")

            duration = (time.perf_counter() - start_time) * 1000
            logger.debug(
                f"✅ AudioProcessor.reset_all() abgeschlossen in {duration:.2f} ms"
            )

    def _clear_duplicate_and_flushed_safe(self) -> None:
        """Leert die Duplikaterkennung und alle Ausgabe‑Markierungen
        unter dem ``_duplicate_lock`` – mit maximaler Fehlertoleranz.
        """
        lock = getattr(self, "_duplicate_lock", None)
        if lock is None:
            lock = threading.RLock()
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    "_clear_duplicate_and_flushed_safe: _duplicate_lock fehlte – Fallback-Lock erstellt",
                )
        with lock:

            def _safe_clear(attr_name: str) -> None:
                if not hasattr(self, attr_name):
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "processor",
                            f"_safe_clear: {attr_name} existiert nicht",
                        )
                    return
                obj = getattr(self, attr_name)
                if obj is None:
                    if DEBUG_LEVEL >= 4:
                        log_debug("processor", f"_safe_clear: {attr_name} ist None")
                    return
                if hasattr(obj, "clear"):
                    try:
                        obj.clear()
                        if DEBUG_LEVEL >= 4:
                            log_debug(
                                "processor",
                                f"_safe_clear: {attr_name}.clear() erfolgreich",
                            )
                    except Exception as e:
                        logger.warning(
                            f"_safe_clear: clear() auf {attr_name} fehlgeschlagen: {e}",
                        )
                elif DEBUG_LEVEL >= 3:
                    log_debug(
                        "processor",
                        f"_safe_clear: {attr_name} hat keine clear()-Methode (Typ {type(obj).__name__})",
                    )

            _safe_clear("_last_transcription_text")
            _safe_clear("_last_translation_text")
            _safe_clear("_recent_transcriptions")
            _safe_clear("_already_flushed_texts")
            _safe_clear("_flushed_combined_texts")
            _safe_clear("_already_flushed_cache")
            _safe_clear("_last_tts_texts")
            _safe_clear("_last_chunk_hashes")
            try:
                self._last_transcription_text = ""
            except Exception as e:
                logger.warning(
                    f"Setzen von _last_transcription_text fehlgeschlagen: {e}",
                )
            try:
                self._last_translation_text = ""
            except Exception as e:
                logger.warning(f"Setzen von _last_translation_text fehlgeschlagen: {e}")

            if DEBUG_LEVEL >= 2:
                log_debug(
                    "processor",
                    "_clear_duplicate_and_flushed_safe: Alle Duplikat-Caches geleert",
                )

    def _clear_audio_buffer_safe(self) -> None:
        """Leert den Audio‑Chunk‑Puffer sowie den Overlap‑Tail und
        die Hash‑Caches unter dem ``_buffer_lock``.
        """
        with self._buffer_lock:
            self._safe_clear("_audio_chunks")
            self._audio_total_bytes = 0
        self._last_chunk_tail = b""
        self._safe_clear("_last_chunk_hashes")

    def _cancel_all_timeout_futures(self) -> None:
        """Bricht alle aktiven Timeout-Futures ab und leert die Liste.
        Wird in Notfall‑Cleanups verwendet, um hängende Transkriptionen zu beenden.
        """
        with self._timeout_futures_lock:
            futures = list(self._active_timeout_futures)
            self._active_timeout_futures.clear()
            for future in futures:
                if not future.done():
                    cancelled = future.cancel()
                    if DEBUG_LEVEL >= 4 and not cancelled:
                        log_debug(
                            "shutdown",
                            "Future konnte nicht abgebrochen werden (bereits laufend?)",
                        )
        if futures and DEBUG_LEVEL >= 3:
            log_debug("shutdown", f"{len(futures)} Timeout-Futures abgebrochen.")

    def _drain_queue_and_sync(self) -> None:
        """Leert die Rohdaten-Queue vollständig und synchronisiert das Tasks‑Done‑Event.
        Wird intern von den Shutdown-Methoden aufgerufen.
        """
        self._clear_and_sync_queue()
        with self._pending_tasks_cond:
            self._pending_tasks = 0
            self._pending_tasks_cond.notify_all()
        self._synchronize_tasks_done_event()
        if DEBUG_LEVEL >= 3:
            log_debug("shutdown", "Queue geleert und pending_tasks auf 0 gesetzt.")

    def _join_worker_threads(
        self,
        threads: list[threading.Thread],
        max_time: float,
        attr: str,
        *,
        name_prefix: str | None = None,
        mark_daemon_on_timeout: bool = False,
    ) -> int:
        """Jointed eine Liste von Threads mit einem gemeinsamen Zeitbudget."""
        if not threads and name_prefix:
            threads = [
                t
                for t in threading.enumerate()
                if t.name.startswith(name_prefix)
                and t.is_alive()
                and t is not threading.current_thread()
            ]
            if threads and DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    f"  → {len(threads)} Thread(s) via Namenspräfix "
                    f"'{name_prefix}' gefunden (Auto-Discovery)",
                )

        if not threads:
            return 0

        deadline = time.monotonic() + max_time
        joined = 0
        still_alive: list[threading.Thread] = []

        for idx, t in enumerate(threads, start=1):
            if not t.is_alive():
                joined += 1
                continue

            remaining = deadline - time.monotonic()
            if remaining <= 0.01:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"  → Zeitbudget erschöpft – "
                        f"{len(threads) - idx + 1} Thread(s) verbleiben",
                    )
                still_alive.append(t)
                still_alive.extend(threads[idx:])
                break

            per_thread_timeout = min(
                0.5,
                remaining / (len(threads) - idx + 1),
            )
            t.join(timeout=per_thread_timeout)

            if t.is_alive():
                still_alive.append(t)
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        f"  → Thread '{t.name}' läuft noch nach "
                        f"{per_thread_timeout:.2f} s",
                    )
            else:
                joined += 1
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        f"  → Thread '{t.name}' erfolgreich gejoint",
                    )

        if mark_daemon_on_timeout and still_alive:
            for t in still_alive:
                if t.is_alive():
                    with contextlib.suppress(Exception):
                        t.daemon = True
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    f"  → {len(still_alive)} Thread(s) als Daemon markiert",
                )

        return joined

    def _reset_expected_timestamps(self) -> None:
        """Setzt alle erwarteten Startzeiten zurück."""
        with self._segment_buffer_lock:
            self._next_expected_start = 0.0
        self._next_expected_transcript_start = 0.0
        self._next_expected_translation_start = 0.0

    def _clear_duplicate_caches(self) -> None:
        """Leert alle Duplikat‑Caches."""
        with self._duplicate_lock:
            if hasattr(self, "_last_chunk_hashes"):
                self._last_chunk_hashes.clear()
            if hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts.clear()
            if hasattr(self, "_flushed_combined_texts"):
                self._flushed_combined_texts.clear()
            self._last_transcription_text = ""
            self._recent_transcriptions.clear()

    def _clear_transcript_queue_safe(self) -> None:
        with self._transcript_queue_lock:
            self._transcript_queue.clear()
            self._next_expected_transcript_start = 0.0

    def _clear_translation_queue_safe(self) -> None:
        with self._translation_queue_lock:
            self._translation_queue.clear()
            self._next_expected_translation_start = 0.0

    def _clear_tts_drossel_safe(self) -> None:
        if hasattr(self, "_tts_pending_count"):
            self._tts_pending_count = 0
        if hasattr(self, "_tts_original_workers"):
            del self._tts_original_workers

    def _cleanup_dispose_thread_safe(self) -> None:
        if hasattr(self, "_dispose_thread") and self._dispose_thread:
            if hasattr(self, "_dispose_stop_event"):
                self._dispose_stop_event.set()
            self._dispose_thread.join(timeout=1.0)
            if self._dispose_thread.is_alive():
                self._dispose_thread.daemon = True
            self._dispose_thread = None
            if hasattr(self, "_dispose_stop_event"):
                self._dispose_stop_event.clear()

    def _reset_segment_buffer_safe(self) -> None:
        """Setzt den Segment‑Puffer und den Segment‑Zähler unter dem
        ``_subtitle_lock`` zurück (jetzt konsolidiert).
        """
        with self._subtitle_lock:
            if hasattr(self, "_segment_buffer"):
                self._segment_buffer.clear()
            if hasattr(self, "_segment_keys"):
                self._segment_keys.clear()
            self._segment_counter = 0
            self._next_expected_start = 0.0
            if hasattr(self, "_sorted_keys_cache"):
                self._sorted_keys_cache.clear()

    def _reset_stats_safe(self) -> None:
        """Setzt alle Zähler unter dem ``_stats_lock`` zurück."""
        with getattr(self, "_stats_lock", threading.RLock()):
            self._chunk_counter = 0
            self._total_bytes_processed = 0
            self._processed_seconds = 0.0
            self._real_processed_seconds = 0.0
            self._empty_reads = 0
            self._read_error_count = 0
            self._consecutive_errors = 0
            self._consecutive_timeouts = 0
            self._consecutive_successes = 0
            self._low_conf_counter = 0
            self._slow_chunks = 0
            self._last_realtime_factor = 0.0
            self._queue_drop_counter = 0
            self._queue_enqueue_counter = 0
            self._queue_dequeue_counter = 0
            self._consecutive_queue_drops = 0

    def _reset_adaptive_chunk_safe(self) -> None:
        with self._word_count_lock:
            if (
                hasattr(self, "_word_count_history")
                and self._word_count_history is not None
            ):
                self._word_count_history.clear()
            if (
                hasattr(self, "_adaptive_queue_history")
                and self._adaptive_queue_history is not None
            ):
                self._adaptive_queue_history.clear()
            if (
                hasattr(self, "_queue_size_history")
                and self._queue_size_history is not None
            ):
                self._queue_size_history.clear()
            self._smoothed_word_count = None
            self._last_chunk_duration = self.settings.config.CHUNK_DURATION
            self._chunk_stable_counter = 0
            self._chunk_adjust_count = 0
            self._last_chunk_adjust_time = 0.0
            self._consecutive_high_queue = 0
            self._consecutive_low_queue = 0
            self._adaptive_bytes_per_sec = float(self.settings.config.BYTES_PER_SECOND)
            self._adaptive_warmup_chunks = 0

    @staticmethod
    def _drain_queue_safe(q: queue.Queue | None) -> None:
        """Leert eine Queue vollständig und ruft für jedes Element
        ``task_done()`` auf, ohne bei ``ValueError`` abzubrechen.
        """
        if q is None:
            return
        while True:
            try:
                q.get_nowait()
            except queue.Empty:
                break
            except Exception:
                break
            try:
                q.task_done()
            except ValueError:
                break
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    def _clamp_start_seconds(self, start_seconds: float) -> float:
        """Stellt sicher, dass ``start_seconds`` im gültigen Bereich liegt."""
        original = start_seconds
        expected = self._expected_duration

        if expected is None:
            return max(0.0, start_seconds)

        start_seconds = max(0.0, start_seconds)
        if start_seconds > expected:
            start_seconds = max(0.0, expected - 30.0)
        start_seconds = max(0.0, start_seconds - 1.0)

        if start_seconds != original:
            log_debug(
                "DOWNLOAD",
                "Startzeit korrigiert: %.1f → %.1f",
                original,
                start_seconds,
            )
            if self._info_callback:
                self._info_callback(
                    f"⚠️ Startposition korrigiert auf {start_seconds:.1f}s",
                )

        return start_seconds

    def _start_or_restart_dispatcher(self) -> bool:
        """Stellt sicher, dass der Dispatcher‑Thread und alle für die
        Verarbeitung notwendigen Executors ordnungsgemäß laufen.
        Wird insbesondere nach einem Emergency‑Shutdown (z. B. durch die
        Stuck‑Erkennung von ``_wait_for_pending_tasks``) aufgerufen,
        um den Download‑Modus mit frischen Ressourcen zu versorgen.
        """
        executor_initialized = False

        if self._transcription_executor is None:
            logger.info("Transkriptions‑Executor ist None – initialisiere neu.")
            self._init_transcription_executor()
            executor_initialized = True

        if self._transcribe_timeout_executor is None:
            logger.info("Timeout‑Executor ist None – initialisiere neu.")
            self._init_transcribe_timeout_executor()
            executor_initialized = True

        if executor_initialized and DEBUG_LEVEL >= 3:
            log_debug(
                "processor",
                "Executors nach Emergency‑Reset wiederhergestellt.",
            )

        if (
            self._dispatcher_started
            and self._dispatcher_thread is not None
            and self._dispatcher_thread.is_alive()
        ):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    "Dispatcher läuft bereits – kein Neustart nötig.",
                )
            return True

        if self._dispatcher_shutdown.is_set():
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    "Setze dispatcher_shutdown zurück.",
                )
            self._dispatcher_shutdown.clear()

        logger.info("Dispatcher nicht aktiv – starte neu für Download-Modus")
        self._clear_and_sync_queue()
        self._start_dispatcher()
        time.sleep(0.2)
        success = (
            self._dispatcher_started
            and self._dispatcher_thread is not None
            and self._dispatcher_thread.is_alive()
        )

        if success:
            logger.debug("Dispatcher erfolgreich neu gestartet.")
        else:
            logger.error(
                "Dispatcher konnte nicht gestartet werden – "
                "Download‑Modus ist nicht möglich.",
            )
        return success

    def _supports_download_sections(self) -> bool:
        """Ermittelt, ob die installierte yt-dlp-Version die Option
        ``--download-sections`` unterstützt. Das Ergebnis wird für 300 Sekunden gecacht.
        """
        if not hasattr(self, "_supports_download_sections_cache"):
            self._supports_download_sections_cache = None
            self._supports_download_sections_cache_time = 0.0
            self._supports_download_sections_lock = threading.Lock()

        with self._supports_download_sections_lock:
            now = time.monotonic()
            if (
                self._supports_download_sections_cache is not None
                and (now - self._supports_download_sections_cache_time) < 300.0
            ):
                return self._supports_download_sections_cache
            try:
                result = subprocess.run(
                    ["yt-dlp", "--help"],
                    capture_output=True,
                    text=True,
                    timeout=5,
                    check=False,
                )
                supports = "--download-sections" in result.stdout
            except subprocess.TimeoutExpired:
                logger.warning(
                    "yt-dlp --help timed out – assuming no --download-sections support",
                )
                supports = False
            except FileNotFoundError:
                logger.warning(
                    "yt-dlp not found – assuming no --download-sections support",
                )
                supports = False
            except Exception as e:
                log_debug("DOWNLOAD", f"Fehler beim Prüfen von yt-dlp --help: {e}")
                supports = False

            self._supports_download_sections_cache = supports
            self._supports_download_sections_cache_time = now
            return supports

    def _finalize_download(
        self,
        chunk_count: int,
        start_time: float,
        stopped: bool,
    ) -> None:
        """Setzt die Flags nach dem Download und informiert den Benutzer."""
        duration = time.perf_counter() - start_time
        reason = "Benutzerabbruch" if stopped else "abgeschlossen"
        logger.info(
            "Download-Modus beendet (%d Chunks, Dauer: %.2fs, Grund: %s)",
            chunk_count,
            duration,
            reason,
        )
        if self._info_callback:
            try:
                if stopped:
                    self._info_callback("⏹️ Download abgebrochen")
                elif chunk_count > 0:
                    self._info_callback(
                        "✅ Restliches Audio heruntergeladen und verarbeitet",
                    )
                else:
                    self._info_callback("⚠️ Download‑Modus lieferte keine Daten")
            except Exception as e:
                logger.warning(
                    "Fehler im info_callback während _finalize_download: %s",
                    e,
                )

        self._download_mode_active = False
        self._download_completed_event.set()

    def _await_queue_drain(self, timeout: float = 60.0) -> bool:
        """Wait until all pending transcription tasks are finished or a timeout occurs."""
        with self._pending_tasks_cond:
            if self._pending_tasks == 0:
                return True
            initial_pending = self._pending_tasks
        chunk_duration = self.settings.config.CHUNK_DURATION
        with self._stats_lock:
            rt_factor = max(1.0, self._last_realtime_factor)
        estimated_seconds = initial_pending * chunk_duration * rt_factor * 2.5
        MAX_WAIT_SECONDS = max(60.0, min(1200.0, estimated_seconds))

        STUCK_TIMEOUT = getattr(self, "STUCK_TIMEOUT", 120.0)
        CONDITION_WAIT_TIMEOUT = 30.0
        LOG_INTERVAL = 5.0

        wait_start = time.perf_counter()
        last_log_time = wait_start
        last_pending = initial_pending

        last_change_time = wait_start

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(
                "Waiting for %d pending task(s) (dynamic timeout: %.1f s, "
                "stuck timeout: %.1f s)",
                initial_pending,
                MAX_WAIT_SECONDS,
                STUCK_TIMEOUT,
            )

        while True:
            with self._pending_tasks_cond:
                current_pending = self._pending_tasks

                if current_pending == 0:
                    if logger.isEnabledFor(logging.DEBUG):
                        elapsed = time.perf_counter() - wait_start
                        logger.debug("All tasks finished after %.2f s", elapsed)
                    return True

                if self._stop_event.is_set():
                    logger.debug("Stop event set – aborting wait")
                    break

                if (
                    self._dispatcher_thread is not None
                    and not self._dispatcher_thread.is_alive()
                    and not self._dispatcher_shutdown.is_set()
                ):
                    logger.warning(
                        "Dispatcher thread unexpectedly dead – aborting wait",
                    )
                    break

                now = time.perf_counter()
                elapsed = now - wait_start

                if current_pending != last_pending:
                    last_change_time = now
                    last_pending = current_pending
                    if logger.isEnabledFor(logging.DEBUG):
                        logger.debug(
                            "Still %d task(s) after %.1f s",
                            current_pending,
                            elapsed,
                        )
                elif now - last_log_time >= LOG_INTERVAL:
                    if logger.isEnabledFor(logging.DEBUG):
                        logger.debug(
                            "Still %d task(s) after %.1f s (no change since %.1f s ago)",
                            current_pending,
                            elapsed,
                            now - last_change_time,
                        )
                    last_log_time = now

                if current_pending > 0 and (now - last_change_time) > STUCK_TIMEOUT:
                    logger.warning(
                        "⚠️ Pending tasks stuck at %d for %.1f s – forcing emergency reset",
                        current_pending,
                        STUCK_TIMEOUT,
                    )
                    self._pending_tasks = 0
                    self._pending_tasks_cond.notify_all()
                    if not self._tasks_done_event.is_set():
                        self._tasks_done_event.set()
                    return True

                if elapsed >= MAX_WAIT_SECONDS:
                    logger.warning(
                        "Timeout after %.1f s while waiting – %d task(s) still pending",
                        MAX_WAIT_SECONDS,
                        current_pending,
                    )
                    break

                remaining = MAX_WAIT_SECONDS - elapsed
                wait_timeout = min(CONDITION_WAIT_TIMEOUT, remaining)
                if wait_timeout <= 0:
                    break

                predicate_met = self._pending_tasks_cond.wait_for(
                    lambda: self._pending_tasks == 0 or self._stop_event.is_set(),
                    timeout=wait_timeout,
                )
                if predicate_met:
                    continue

        with self._pending_tasks_cond:
            final_pending = self._pending_tasks
            if final_pending > 0:
                logger.warning(
                    "Emergency reset: forcing pending tasks from %d to 0 "
                    "(prevents deadlock)",
                    final_pending,
                )
                self._pending_tasks = 0
                self._pending_tasks_cond.notify_all()
                if not self._tasks_done_event.is_set():
                    self._tasks_done_event.set()

        return False

    def _join_queue_with_timeout(self, timeout: float) -> bool:
        """Wartet darauf, dass die interne Rohdaten‑Queue vollständig abgearbeitet ist
        (queue.join()), jedoch mit einem echten Timeout.
        """
        if not hasattr(self._raw_audio_queue, "join"):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "processor",
                    f"_join_queue_with_timeout: Queue without join(), "
                    f"falling back to idle wait (timeout={timeout}s)",
                )
            return self._wait_for_queue_idle(timeout)

        try:
            if self._raw_audio_queue.empty():
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "processor",
                        "_join_queue_with_timeout: Queue already empty, returning True",
                    )
                return True
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("processor", f"Queue.empty() raised exception: {e}")
        join_completed = threading.Event()
        join_error: Exception | None = None

        def do_join() -> None:
            """Führt queue.join() aus und signalisiert danach das Event.
            Fängt alle Exceptions ab, um das Event in jedem Fall zu setzen.
            """
            nonlocal join_error
            try:
                self._raw_audio_queue.join()
                if DEBUG_LEVEL >= 4:
                    log_debug("processor", "Queue join thread completed successfully")
            except Exception as e:
                join_error = e
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "processor",
                        f"Queue join thread caught exception: {type(e).__name__}: {e}",
                    )
            finally:
                join_completed.set()

        join_thread = threading.Thread(
            target=do_join,
            daemon=True,
            name=f"QueueJoin-{id(self):x}",
        )
        join_thread.start()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "processor",
                f"Started queue join thread (timeout={timeout}s, "
                f"thread={join_thread.name})",
            )

        success = join_completed.wait(timeout)

        if success:
            if DEBUG_LEVEL >= 3:
                log_debug("processor", f"Queue join completed within {timeout}s")
            if join_error is not None:
                logger.warning(f"Queue join thread finished with error: {join_error}")
                return False
            return True
        logger.warning(
            f"Queue join timed out after {timeout}s – "
            f"the queue may be stuck (unfinished_tasks > 0)",
        )
        if DEBUG_LEVEL >= 3:
            try:
                with self._raw_audio_queue.mutex:
                    unfinished = self._raw_audio_queue.unfinished_tasks
            except Exception:
                unfinished = "unknown"
            log_debug(
                "processor",
                f"Queue state after timeout: unfinished_tasks={unfinished}, "
                f"qsize={self._raw_audio_queue.qsize()}",
            )
        return False

    def _wait_for_queue_idle(self, timeout: float) -> bool:
        """Zeitbasierte Heuristik für Queues, die `join()` nicht unterstützen."""
        start_time = time.perf_counter()
        idle_start = None
        required_idle_duration = 2.0
        current_sleep = 0.05
        max_sleep = 1.0
        backoff_factor = 1.5
        if DEBUG_LEVEL >= 3:
            log_debug(
                "processor",
                f"_wait_for_queue_idle: timeout={timeout}s, "
                f"required_idle={required_idle_duration}s, backoff enabled",
            )
        while time.perf_counter() - start_time < timeout:
            if self.is_stop_requested():
                if DEBUG_LEVEL >= 3:
                    log_debug("processor", "_wait_for_queue_idle: stop requested")
                return False
            try:
                qsize = self._raw_audio_queue.qsize()
            except Exception:
                qsize = 0

            with self._pending_tasks_lock:
                pending = self._pending_tasks
            if qsize == 0 and pending == 0:
                if idle_start is None:
                    idle_start = time.perf_counter()
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "processor",
                            "_wait_for_queue_idle: queue became empty",
                        )
                elif time.perf_counter() - idle_start >= required_idle_duration:
                    elapsed = time.perf_counter() - start_time
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "processor",
                            f"_wait_for_queue_idle: Queue stabil leer nach {
                                elapsed:.2f}s",
                        )
                    return True
                time.sleep(current_sleep)
            else:
                idle_start = None
                time.sleep(current_sleep)
            current_sleep = min(max_sleep, current_sleep * backoff_factor)
        logger.warning(f"_wait_for_queue_idle: Timeout nach {timeout}s")
        return False

    def _download_with_ytdlp_sections(
        self,
        video_url: str,
        start_seconds: float,
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        error_cb: ErrorCallback,
        info_cb: InfoCallback | None = None,
        cancel_event: threading.Event | None = None,
    ) -> int:
        """Lädt den restlichen Teil eines YouTube‑VODs mittels yt‑dlp
        ``--download-sections`` herunter und verarbeitet die Audiodaten.
        """

        def _is_cancelled() -> bool:
            return (
                cancel_event is not None and cancel_event.is_set()
            ) or self.is_stop_requested()

        if _is_cancelled():
            logger.info("🛑 Download sections: Abbruch vor Start erkannt")
            self._safe_callback(info_cb, "⏹️ Download abgebrochen")
            return 0

        rounded_start = self._prepare_start_position(start_seconds)
        if rounded_start is None:
            return 0

        timeout = self._calculate_download_timeout(rounded_start)
        if timeout <= 0:
            logger.warning("⚠️ Berechnetes Timeout ist 0 – setze auf 60s")
            timeout = 60

        use_cookies, cookies_browser, proxy_url = self._get_download_auth_config()
        strategies = self._build_download_strategies(
            rounded_start,
            use_cookies,
            cookies_browser,
            proxy_url,
        )

        chunk_count = 0
        last_error = None

        for _strategy_idx, strategy in enumerate(strategies, 1):
            if _is_cancelled():
                logger.info("🛑 Download sections: Abbruch während Strategie‑Schleife")
                self._safe_callback(info_cb, "⏹️ Download abgebrochen")
                break

            cmd = strategy["cmd"]
            label = f"{strategy['client']}/{strategy['format']}"
            retries = 2

            for attempt in range(1, retries + 1):
                if _is_cancelled():
                    break

                logger.debug(
                    "🔄 Versuche %s (Versuch %d/%d, timeout=%ds)",
                    label,
                    attempt,
                    retries,
                    timeout,
                )

                try:
                    chunk_count = self._run_ffmpeg_pipe(
                        cmd,
                        trans_cb=trans_cb,
                        transl_cb=transl_cb,
                        error_cb=error_cb,
                        info_cb=info_cb,
                        seek=False,
                        timeout=timeout,
                        cancel_event=cancel_event,
                    )
                except subprocess.TimeoutExpired as e:
                    last_error = e
                    logger.warning(
                        "⏰ %s: Timeout nach %ds (Versuch %d)",
                        label,
                        timeout,
                        attempt,
                    )
                    if attempt < retries:
                        delay = min(5.0, 1.5**attempt)
                        time.sleep(delay)
                    continue
                except Exception as e:
                    last_error = e
                    logger.error(
                        "❌ %s: Fehler: %s",
                        label,
                        e,
                        exc_info=DEBUG_LEVEL >= 3,
                    )
                    if self._is_permanent_error(e):
                        logger.warning(
                            "🛑 Permanenter Fehler – überspringe weitere Retries für %s",
                            label,
                        )
                        break
                    if attempt < retries:
                        delay = min(5.0, 1.5**attempt)
                        time.sleep(delay)
                    continue

                if chunk_count > 0:
                    logger.info("✅ %s erfolgreich: %d Chunks", label, chunk_count)
                    self._safe_callback(
                        info_cb,
                        f"✅ Download abgeschlossen ({chunk_count} Chunks)",
                    )
                    return chunk_count

                logger.debug(
                    "ℹ️ %s lieferte 0 Chunks – versuche nächste Strategie",
                    label,
                )
                break

        logger.warning(
            "❌ Alle Download‑Strategien fehlgeschlagen. Letzter Fehler: %s",
            last_error,
        )
        self._safe_callback(info_cb, "❌ Download fehlgeschlagen – siehe Log")
        return 0

    def _prepare_start_position(self, start_seconds: float) -> int | None:
        """Bereinigt die Startposition und gibt sie als Ganzzahl zurück."""
        rounded_start = max(0, int(start_seconds) - 1)

        if self._expected_duration is not None:
            if rounded_start >= self._expected_duration:
                logger.warning(
                    "rounded_start (%ds) >= expected duration (%.1fs) – setze auf vorletzten Puffer.",
                    rounded_start,
                    self._expected_duration,
                )
                rounded_start = max(0, int(self._expected_duration) - 30)
                rounded_start = max(0, rounded_start)

        MAX_REASONABLE_START = 86400
        if rounded_start > MAX_REASONABLE_START:
            logger.warning(
                "rounded_start (%ds) > %ds – begrenzt.",
                rounded_start,
                MAX_REASONABLE_START,
            )
            rounded_start = MAX_REASONABLE_START
        return rounded_start

    def _download_full_and_seek(
        self,
        video_url: str,
        start_seconds: float,
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        error_cb: ErrorCallback,
        info_cb: InfoCallback | None = None,
        cancel_event: threading.Event | None = None,
        temp_file_callback: Callable[[str], None] | None = None,
    ) -> int:
        """🚨 FALLBACK-MODUS – Lädt das gesamte Audio herunter und schneidet es mit ffmpeg zu."""

        def _is_cancelled() -> bool:
            return (
                cancel_event is not None and cancel_event.is_set()
            ) or self.is_stop_requested()

        def _safe_kill(
            proc: subprocess.Popen | None,
            name: str,
            force: bool = False,
        ) -> None:
            """Beendet einen Prozess sicher – mit Timeout und Fallback."""
            if proc is None or proc.poll() is not None:
                return
            try:
                if force:
                    proc.kill()
                else:
                    proc.terminate()
                try:
                    proc.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait(timeout=1.0)
            except Exception as e:
                logger.debug(f"Fehler beim Beenden von {name} (PID {proc.pid}): {e}")

        def _safe_callback(cb, *args, **kwargs) -> None:
            if cb is None:
                return
            try:
                cb(*args, **kwargs)
            except Exception as e:
                logger.warning(f"Callback-Fehler: {e}", exc_info=DEBUG_LEVEL >= 3)

        if _is_cancelled():
            logger.info("🛑 Full-Download: Abbruch vor Start erkannt")
            _safe_callback(info_cb, "⏹️ Download abgebrochen")
            return 0

        try:
            import concurrent.futures

            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
                future = executor.submit(self._get_video_info, video_url)
                info = future.result(timeout=15.0)
        except concurrent.futures.TimeoutError:
            logger.warning("⏰ Video-Info-Timeout – fahre ohne Größenprüfung fort")
            info = {}
        except Exception as e:
            logger.warning(f"Konnte Video-Info nicht abrufen: {e}")
            info = {}

        filesize = info.get("filesize_approx") or info.get("filesize")
        if filesize:
            size_mb = filesize // (1024 * 1024)
            size_gb = filesize / (1024**3)
            _safe_callback(info_cb, f"📦 Videogröße: {size_mb} MB ({size_gb:.1f} GB)")

            if filesize > 2 * 1024 * 1024 * 1024:
                logger.warning(f"Video >2 GB ({size_gb:.1f} GB) – Fallback abgebrochen")
                _safe_callback(info_cb, "❌ Video zu groß für Full‑Download-Fallback")
                return 0

            if filesize > 500 * 1024 * 1024:
                logger.warning(f"Video {size_mb} MB – Full-Download kann lange dauern")
                _safe_callback(
                    info_cb,
                    f"⚠️ Lade {size_mb} MB herunter (kann dauern)...",
                )

        use_cookies = getattr(self.stream_manager, "use_browser_cookies", True)
        cookies_browser = None
        if use_cookies:
            cookies_browser = getattr(self.settings, "cookies_browser", None)
            if not cookies_browser:
                try:
                    app_settings = AppSettings.load_from_file()
                    cookies_browser = getattr(
                        app_settings,
                        "cookies_browser",
                        "firefox",
                    )
                except Exception:
                    cookies_browser = "firefox"

        proxy_url = (
            getattr(self.settings, "proxy_url", "")
            if getattr(self.settings, "proxy_enabled", False)
            else ""
        )

        import tempfile

        temp_path = None
        temp_file_obj = None

        try:
            temp_file_obj = tempfile.NamedTemporaryFile(
                suffix=".mp4",
                prefix="dragon_full_",
                delete=False,
            )
            temp_path = temp_file_obj.name
            temp_file_obj.close()

            if temp_file_callback:
                temp_file_callback(temp_path)

            log_debug("DOWNLOAD", f"📁 Temporäre Datei: {temp_path}")
        except Exception as e:
            logger.error(f"❌ Temp-Datei Fehler: {e}")
            _safe_callback(error_cb, f"Temp-Datei Fehler: {str(e)[:100]}")
            return 0

        yt_cmd = [
            "yt-dlp",
            "-f",
            "bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio/best",
            "--no-playlist",
            "--quiet",
            "--no-warnings",
            "--socket-timeout",
            "45",
            "--retries",
            "5",
            "--fragment-retries",
            "5",
            "--buffer-size",
            "16M",
            "-o",
            temp_path,
        ]

        if use_cookies and cookies_browser:
            yt_cmd.extend(["--cookies-from-browser", cookies_browser])
        if proxy_url:
            yt_cmd.extend(["--proxy", proxy_url])

        if "youtube.com" in video_url.lower() or "youtu.be" in video_url.lower():
            yt_cmd.extend()

        yt_cmd.append(video_url)

        log_debug("DOWNLOAD", f"🐚 yt-dlp: {' '.join(yt_cmd)}")

        ff_cmd = [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            temp_path,
            "-ss",
            str(max(0.0, start_seconds)),
            "-vn",
            "-f",
            self.settings.config.AUDIO_FORMAT,
            "-acodec",
            "pcm_s16le",
            "-ar",
            str(self.settings.config.SAMPLE_RATE),
            "-ac",
            str(self.settings.config.CHANNELS),
            "-",
        ]

        if getattr(self.settings, "enable_audio_enhancement", False):
            ff_cmd.extend(["-af", "highpass=f=80,lowpass=f=3400"])

        log_debug("DOWNLOAD", f"🎚️ ffmpeg: {' '.join(ff_cmd)}")

        yt_proc = None
        ff_proc = None
        chunk_count = 0
        total_bytes = 0
        start_time = time.perf_counter()

        try:
            yt_proc = subprocess.Popen(
                yt_cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
                stdin=subprocess.DEVNULL,
                start_new_session=True,
                bufsize=1,
            )
            log_debug("DOWNLOAD", f"🔄 yt-dlp gestartet (PID: {yt_proc.pid})")

            DOWNLOAD_TIMEOUT = 600
            deadline = time.perf_counter() + DOWNLOAD_TIMEOUT
            last_download_progress = 0.0

            while yt_proc.poll() is None:
                if _is_cancelled():
                    _safe_kill(yt_proc, "yt-dlp", force=True)
                    _safe_callback(info_cb, "⏹️ Download abgebrochen")
                    return 0

                if time.perf_counter() > deadline:
                    _safe_kill(yt_proc, "yt-dlp", force=True)
                    logger.error(f"⏰ Download-Timeout nach {DOWNLOAD_TIMEOUT}s")
                    _safe_callback(info_cb, "❌ Download-Timeout")
                    return 0

                if os.path.exists(temp_path):
                    current_size = os.path.getsize(temp_path)
                    if filesize and filesize > 0:
                        progress = min(100, (current_size / filesize) * 100)
                        if progress - last_download_progress > 5:
                            last_download_progress = progress
                            _safe_callback(info_cb, f"⬇️ Download: {progress:.0f}%")

                time.sleep(0.5)

            if yt_proc.returncode != 0:
                stderr = (
                    yt_proc.stderr.read().decode(errors="replace")[:500]
                    if yt_proc.stderr
                    else ""
                )
                logger.error(f"❌ yt-dlp Fehler (exit {yt_proc.returncode}): {stderr}")
                _safe_callback(error_cb, f"yt-dlp Fehler: {stderr[:100]}")
                return 0

            _safe_callback(info_cb, "✅ Download abgeschlossen")

            ff_proc = subprocess.Popen(
                ff_cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                bufsize=10 * 1024 * 1024,
                start_new_session=True,
            )
            log_debug("DOWNLOAD", f"🎬 ffmpeg gestartet (PID: {ff_proc.pid})")

            ap = self._get_ap()
            if ap is None:
                logger.error("❌ AudioProcessor nicht verfügbar")
                _safe_callback(error_cb, "Interner Fehler: AudioProcessor fehlt")
                _safe_kill(ff_proc, "ffmpeg", force=True)
                return 0

            chunk_size = self.settings.config.CHUNK_SIZE_BYTES
            last_data_time = time.perf_counter()
            max_idle = getattr(self.settings, "download_inactivity_timeout", 30.0)
            consec_errors = 0
            max_errors = 5
            total_chunks = 0

            _safe_callback(info_cb, "🎵 Verarbeite Audio...")

            while True:
                if _is_cancelled():
                    _safe_kill(ff_proc, "ffmpeg", force=True)
                    _safe_callback(info_cb, "⏹️ Verarbeitung abgebrochen")
                    break

                if time.perf_counter() - last_data_time > max_idle:
                    logger.warning(
                        f"⏰ Inaktivitäts-Timeout ({max_idle:.1f}s) erreicht",
                    )
                    _safe_callback(info_cb, "❌ Inaktivitäts-Timeout")
                    break

                try:
                    data = ff_proc.stdout.read(chunk_size)
                except (ValueError, OSError) as e:
                    logger.debug(f"ffmpeg read error: {e}")
                    break
                except Exception as e:
                    logger.warning(f"Unerwarteter read error: {e}")
                    consec_errors += 1
                    if consec_errors >= max_errors:
                        logger.error("Zu viele Lesefehler – breche ab")
                        _safe_callback(error_cb, f"Lesefehler: {str(e)[:100]}")
                        break
                    time.sleep(0.1)
                    continue

                if not data:
                    logger.debug("ffmpeg EOF – Audio vollständig verarbeitet")
                    break

                consec_errors = 0
                last_data_time = time.perf_counter()
                total_bytes += len(data)
                total_chunks += 1

                try:
                    ap._process_audio_data(
                        data,
                        transcription_callback=trans_cb,
                        translation_callback=transl_cb,
                        error_callback=error_cb,
                        info_callback=info_cb,
                    )
                    chunk_count += 1

                    if total_chunks % 50 == 0:
                        elapsed = time.perf_counter() - start_time
                        speed = total_bytes / elapsed / 1024 if elapsed > 0 else 0
                        _safe_callback(
                            info_cb,
                            f"📊 {total_chunks} Chunks, {speed:.0f} KB/s",
                        )

                except Exception as e:
                    logger.error(
                        f"Fehler in _process_audio_data: {e}",
                        exc_info=DEBUG_LEVEL >= 3,
                    )
                    _safe_callback(error_cb, f"Verarbeitungsfehler: {str(e)[:100]}")
                    consec_errors += 1
                    if consec_errors >= max_errors:
                        logger.error("Zu viele Verarbeitungsfehler – breche ab")
                        break
                    continue

            ff_exit = ff_proc.poll()
            if ff_exit is not None and ff_exit != 0:
                stderr = (
                    ff_proc.stderr.read().decode(errors="replace")[:500]
                    if ff_proc.stderr
                    else ""
                )
                logger.error(f"❌ ffmpeg Fehler (exit {ff_exit}): {stderr}")
                _safe_callback(error_cb, f"ffmpeg Fehler: {stderr[:100]}")
                chunk_count = 0

        except Exception as e:
            logger.exception(f"💥 Unerwarteter Fehler im Full-Download: {e}")
            _safe_callback(error_cb, f"Interner Fehler: {str(e)[:100]}")
            chunk_count = 0

        finally:
            for proc, name in ((ff_proc, "ffmpeg"), (yt_proc, "yt-dlp")):
                if proc is not None and proc.poll() is None:
                    _safe_kill(proc, name, force=True)

            if temp_path and os.path.exists(temp_path):
                try:
                    os.unlink(temp_path)
                    log_debug("DOWNLOAD", f"🗑️ Temp-Datei gelöscht: {temp_path}")
                except OSError as e:
                    logger.warning(f"⚠️ Konnte {temp_path} nicht löschen: {e}")

        if chunk_count == 0:
            logger.warning(
                "⚠️ Fallback-Download lieferte 0 Chunks – möglicherweise fehlerhafter Stream.",
            )
            _safe_callback(info_cb, "❌ Keine Audiodaten verarbeitet")
        else:
            elapsed = time.perf_counter() - start_time
            logger.info(
                f"✅ Fallback-Download beendet: {chunk_count} Chunks, {
                    total_bytes / 1024 / 1024:.1f} MB in {elapsed:.1f}s"
            )
            _safe_callback(info_cb, f"✅ {chunk_count} Chunks verarbeitet")

        return chunk_count

    def _run_ffmpeg_pipe(
        self,
        yt_cmd: list[str],
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        error_cb: ErrorCallback,
        info_cb: InfoCallback | None = None,
        seek: bool | float = False,
        timeout: float | None = None,
        cancel_event: threading.Event | None = None,
    ) -> int:
        """Startet eine Pipeline aus yt‑dlp und ffmpeg, liest PCM‑Daten und speist
        sie in die asynchrone Verarbeitungs‑Queue des AudioProcessors ein.
        """
        start_total = time.perf_counter()
        chunk_count = 0
        total_bytes = 0

        def is_stop_requested() -> bool:
            if cancel_event and cancel_event.is_set():
                return True
            return (
                self.is_stop_requested()
                if hasattr(self, "is_stop_requested")
                else False
            )

        def _safe_kill(proc: subprocess.Popen | None, name: str) -> None:
            if proc is None or proc.poll() is not None:
                return
            try:
                PlatformUtils.terminate_process(
                    proc,
                    child_terminate_timeout=1.0,
                    child_kill_wait=0.5,
                    parent_terminate_timeout=2.0,
                    parent_kill_wait=1.0,
                    fallback_terminate_timeout=1.0,
                    fallback_kill_wait=0.5,
                )
            except Exception as e:
                logger.warning(f"Fehler beim Beenden von {name} (PID {proc.pid}): {e}")

        def _log_stderr(
            proc: subprocess.Popen | None,
            name: str,
            max_lines: int = 50,
        ) -> str:
            """Liest stderr des Prozesses und gibt ihn als String zurück."""
            if proc is None or proc.stderr is None:
                return ""
            try:
                stderr = proc.stderr.read().decode("utf-8", errors="ignore")
                lines = stderr.splitlines()
                if len(lines) > max_lines:
                    lines = lines[:max_lines] + [
                        f"... ({len(lines) - max_lines} more lines)",
                    ]
                return "\n".join(lines)
            except Exception:
                return ""

        if is_stop_requested():
            logger.info("Download abgebrochen vor Start (Benutzerwunsch)")
            if info_cb:
                info_cb("⏹️ Download abgebrochen")
            return 0

        if timeout is None:
            expected_duration = getattr(self, "_expected_duration", None)
            if expected_duration is not None:
                remaining = max(
                    1.0,
                    expected_duration - getattr(self, "_real_processed_seconds", 0.0),
                )
            else:
                remaining = 300.0

            rt_factor = 1.0
            ap = self._get_audio_processor()
            if ap is not None and hasattr(ap, "_last_realtime_factor"):
                rt_factor = max(1.0, ap._last_realtime_factor)

            dynamic_timeout = max(60.0, min(1800.0, remaining * rt_factor * 2.0))
        else:
            dynamic_timeout = timeout

        if DEBUG_LEVEL >= 3:
            log_debug(
                "download",
                f"_run_ffmpeg_pipe: START - seek={seek}, timeout={dynamic_timeout:.1f}s",
            )

        format_selectors = [
            "bestaudio[ext=m4a]/bestaudio[ext=webm]/bestaudio/best",
            "bestaudio/best",
            "best",
        ]

        for attempt, fmt in enumerate(format_selectors, 1):
            if is_stop_requested():
                break
            current_yt_cmd = list(yt_cmd)
            try:
                fmt_index = current_yt_cmd.index("-f")
                current_yt_cmd[fmt_index + 1] = fmt
            except ValueError:
                current_yt_cmd.extend(["-f", fmt])

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "download",
                    f"🔄 Versuch {attempt}/{len(format_selectors)} mit -f '{fmt}'",
                )

            yt_proc, ff_proc, error = self._start_pipeline(
                current_yt_cmd,
                seek,
                error_cb,
                info_cb,
                is_stop_requested,
            )

            if error:
                if "Requested format is not available" in error:
                    logger.warning(
                        f"⚠️ Format '{fmt}' nicht verfügbar – versuche nächsten Selector",
                    )
                    if info_cb:
                        info_cb(
                            f"📦 Format '{fmt}' nicht verfügbar – versuche nächsten...",
                        )
                    continue
                logger.error(f"❌ Pipeline-Start fehlgeschlagen: {error}")
                if error_cb:
                    error_cb(f"Pipeline-Fehler: {error[:100]}")
                return 0

            logger.info(f"✅ Pipeline gestartet (Format: {fmt})")
            if info_cb:
                info_cb("🎵 Verarbeite Audio...")

            chunk_count, total_bytes = self._read_pipeline_data(
                ff_proc,
                yt_proc,
                trans_cb,
                transl_cb,
                error_cb,
                info_cb,
                dynamic_timeout,
                is_stop_requested,
                start_total,
            )

            if chunk_count > 0:
                logger.info(
                    f"✅ Download abgeschlossen: {chunk_count} Chunks, {total_bytes} Bytes",
                )
                return chunk_count

            logger.warning(
                f"⚠️ Format '{fmt}' lieferte 0 Chunks – versuche nächsten...",
            )
            if info_cb:
                info_cb(
                    f"📦 Format '{fmt}' lieferte keine Daten – versuche nächsten...",
                )

        logger.error("❌ Alle Format-Selectors fehlgeschlagen – Download abgebrochen")
        if error_cb:
            error_cb("Kein passendes Audio-Format gefunden")
        return 0

    def _get_audio_processor(self) -> Any:
        """Holt den AudioProcessor – robust mit Fallback."""
        if hasattr(self, "audio_processor") and self.audio_processor is not None:
            return self.audio_processor
        if hasattr(self, "_audio_processor") and self._audio_processor is not None:
            return self._audio_processor
        if hasattr(self, "ap") and self.ap is not None:
            return self.ap
        if hasattr(self, "gui_ref"):
            gui = self.gui_ref()
            if gui and hasattr(gui, "audio_processor"):
                return gui.audio_processor
        return None

    def _start_pipeline(
        self,
        yt_cmd: list[str],
        seek: bool | float,
        error_cb: ErrorCallback,
        info_cb: InfoCallback | None,
        is_stop_requested: Callable[[], bool],
    ) -> tuple[subprocess.Popen | None, subprocess.Popen | None, str | None]:
        """Startet yt-dlp und ffmpeg als Pipeline.
        Gibt (yt_proc, ff_proc, error_message) zurück.
        """
        yt_proc = None
        ff_proc = None

        try:
            yt_proc = subprocess.Popen(
                yt_cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                stdin=subprocess.DEVNULL,
                bufsize=10 * 1024 * 1024,
                start_new_session=True,
            )
            if DEBUG_LEVEL >= 3:
                log_debug("download", f"yt-dlp started (PID: {yt_proc.pid})")
        except Exception as e:
            return None, None, f"yt-dlp start failed: {e}"

        if is_stop_requested():
            _safe_kill(yt_proc, "yt-dlp")
            return None, None, "Cancelled"

        config = self.settings.config
        ff_cmd = [
            "ffmpeg",
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            "pipe:0",
            "-f",
            config.AUDIO_FORMAT,
            "-acodec",
            "pcm_s16le",
            "-ar",
            str(config.SAMPLE_RATE),
            "-ac",
            str(config.CHANNELS),
        ]
        if seek and isinstance(seek, (int, float)) and seek > 0:
            ff_cmd[1:1] = ["-ss", str(seek)]
        ff_cmd.append("pipe:1")

        try:
            ff_proc = subprocess.Popen(
                ff_cmd,
                stdin=yt_proc.stdout,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                bufsize=10 * 1024 * 1024,
                start_new_session=True,
            )
            if DEBUG_LEVEL >= 3:
                log_debug("download", f"ffmpeg started (PID: {ff_proc.pid})")
        except Exception as e:
            _safe_kill(yt_proc, "yt-dlp")
            return None, None, f"ffmpeg start failed: {e}"

        if is_stop_requested():
            _safe_kill(ff_proc, "ffmpeg")
            _safe_kill(yt_proc, "yt-dlp")
            return None, None, "Cancelled"

        time.sleep(0.2)
        if yt_proc.poll() is not None:
            stderr = _log_stderr(yt_proc, "yt-dlp")
            return (
                None,
                None,
                f"yt-dlp died early (exit {yt_proc.poll()}): {stderr[:200]}",
            )
        if ff_proc.poll() is not None:
            stderr = _log_stderr(ff_proc, "ffmpeg")
            return (
                None,
                None,
                f"ffmpeg died early (exit {ff_proc.poll()}): {stderr[:200]}",
            )

        return yt_proc, ff_proc, None

    def _read_pipeline_data(
        self,
        ff_proc: subprocess.Popen,
        yt_proc: subprocess.Popen,
        trans_cb: TranscriptionCallback,
        transl_cb: TranslationCallback,
        error_cb: ErrorCallback,
        info_cb: InfoCallback | None,
        dynamic_timeout: float,
        is_stop_requested: Callable[[], bool],
        start_total: float,
    ) -> tuple[int, int]:
        """Liest die PCM-Daten von ffmpeg stdout und verarbeitet sie.
        Gibt (chunk_count, total_bytes) zurück.
        """
        ap = self._get_audio_processor()
        if ap is None:
            logger.error("AudioProcessor nicht verfügbar")
            return 0, 0

        chunk_count = 0
        total_bytes = 0
        time.perf_counter()
        inactivity_timeout = getattr(self.settings, "download_inactivity_timeout", 30.0)
        chunk_size = self.settings.config.CHUNK_SIZE_BYTES

        consec_errors = 0
        MAX_CONSECUTIVE_ERRORS = 5
        backoff_delay = 0.1
        timer = None
        timer_lock = threading.RLock()
        inactivity_event = threading.Event()

        def inactivity_killer():
            inactivity_event.set()

        def reset_inactivity_timer():
            nonlocal timer
            with timer_lock:
                if timer:
                    timer.cancel()
                    timer = None
                if inactivity_timeout > 0:
                    inactivity_event.clear()
                    timer = threading.Timer(inactivity_timeout, inactivity_killer)
                    timer.daemon = True
                    timer.start()

        reset_inactivity_timer()

        try:
            while True:
                if inactivity_event.is_set():
                    logger.warning("Inaktivitäts-Timeout erreicht")
                    break
                if is_stop_requested():
                    logger.info("Abbruch durch Benutzer")
                    break
                if time.perf_counter() - start_total > dynamic_timeout:
                    logger.warning(
                        f"Globales Timeout ({dynamic_timeout:.1f}s) überschritten",
                    )
                    break

                try:
                    if ff_proc.stdout is None:
                        break
                    data = ff_proc.stdout.read(chunk_size)
                except Exception as e:
                    logger.warning(f"Lesefehler: {e}")
                    consec_errors += 1
                    if consec_errors >= MAX_CONSECUTIVE_ERRORS:
                        logger.error("Zu viele Lesefehler – breche ab")
                        break
                    time.sleep(backoff_delay)
                    backoff_delay = min(backoff_delay * 2, 2.0)
                    continue

                if not data:
                    logger.debug("EOF von ffmpeg erreicht")
                    break

                consec_errors = 0
                backoff_delay = 0.1
                time.perf_counter()
                reset_inactivity_timer()
                total_bytes += len(data)

                try:
                    ap._process_audio_data(
                        data,
                        transcription_callback=trans_cb,
                        translation_callback=transl_cb,
                        error_callback=error_cb,
                        info_callback=info_cb,
                    )
                    chunk_count += 1

                    if chunk_count % 10 == 0:
                        logger.info(
                            f"  → {chunk_count} Chunks verarbeitet ({total_bytes / 1024:.1f} KB)",
                        )
                except Exception as e:
                    logger.error(
                        f"Fehler in _process_audio_data: {e}",
                        exc_info=DEBUG_LEVEL >= 3,
                    )
                    if error_cb:
                        error_cb(f"Verarbeitungsfehler: {str(e)[:100]}")
                    consec_errors += 1
                    if consec_errors >= MAX_CONSECUTIVE_ERRORS:
                        logger.error("Zu viele Verarbeitungsfehler – breche ab")
                        break

        finally:
            with timer_lock:
                if timer:
                    timer.cancel()

        return chunk_count, total_bytes

    def _safe_terminate_process(self, proc: subprocess.Popen) -> None:
        """Terminiert einen Subprozess sicher (erst SIGTERM, dann SIGKILL)."""
        if proc is None:
            return
        try:
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait(timeout=1.0)
        except Exception as e:
            log_debug("processor", f"Error in safe_terminate_process: {e}")

    def _get_config_type(self) -> str:
        cfg = self.settings.config
        if isinstance(cfg, RealtimeConfig):
            return "realtime"
        if isinstance(cfg, HighAccuracyConfig):
            return "high_accuracy"
        if isinstance(cfg, YouTubeOptimizedConfig):
            return "youtube"
        return "default"

    def _get_total_ram_gb(self) -> float:
        """Ermittelt den gesamten Arbeitsspeicher in GB (mit Fallback)."""
        try:
            import psutil

            return psutil.virtual_memory().total / (1024**3)
        except ImportError:
            try:
                with open("/proc/meminfo") as f:
                    for line in f:
                        if line.startswith("MemTotal:"):
                            kb = int(line.split()[1])
                            return kb / (1024 * 1024)
            except Exception:
                pass
            try:
                import ctypes

                kernel32 = ctypes.windll.kernel32

                class MEMORYSTATUSEX(ctypes.Structure):
                    _fields_ = [
                        ("dwLength", ctypes.c_ulong),
                        ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong),
                        ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong),
                        ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong),
                        ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                    ]

                mem = MEMORYSTATUSEX()
                mem.dwLength = ctypes.sizeof(mem)
                if kernel32.GlobalMemoryStatusEx(ctypes.byref(mem)):
                    return mem.ullTotalPhys / (1024**3)
            except Exception:
                pass
            return 0.0

    def _fallback_language_detection(self, text: str) -> str | None:
        try:
            import langdetect

            if len(text) < 20:
                return None
            detected = langdetect.detect(text)
            if detected in SUPPORTED_LANGUAGES:
                return detected
            if detected.startswith("zh"):
                return "zh"
            return None
        except ImportError:
            return None
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                logger.debug(f"Language detection error: {e}")
            return None

    def _assess_translation_quality(
        self,
        original: str,
        translated: str,
        target_lang: str,
    ) -> float:
        if not translated:
            return 0.0
        len_orig = len(original)
        len_trans = len(translated)
        if len_orig == 0:
            return 0.5
        ratio = len_trans / len_orig
        if ratio < 0.2 or ratio > 4.0:
            log_debug("translate", f"Suspicious length ratio: {ratio:.2f}")
            return 0.0
        words_orig = len(original.split())
        words_trans = len(translated.split())
        if words_orig > 0:
            word_ratio = words_trans / words_orig
            if word_ratio < 0.15 or word_ratio > 5.0:
                log_debug("translate", f"Suspicious word ratio: {word_ratio:.2f}")
                return 0.1

        if target_lang == "de":
            non_latin = sum(1 for c in translated if ord(c) > 0x7F and not c.isspace())
            if non_latin > len_trans * 0.3:
                log_debug(
                    "translate",
                    f"Too many non-Latin characters ({non_latin}/{len_trans})",
                )
                return 0.1
            cjk = sum(
                1
                for c in translated
                if "\u4e00" <= c <= "\u9fff" or "\u3040" <= c <= "\u30ff"
            )
            cyrillic = sum(1 for c in translated if "\u0400" <= c <= "\u04ff")
            arabic = sum(1 for c in translated if "\u0600" <= c <= "\u06ff")
            if (
                cjk > len_trans * 0.1
                or cyrillic > len_trans * 0.1
                or arabic > len_trans * 0.1
            ):
                log_debug(
                    "translate",
                    f"Wrong script detected (CJK:{cjk}, Cyrillic:{cyrillic}, Arabic:{arabic})",
                )
                return 0.0
        elif target_lang == "en":
            non_latin = sum(1 for c in translated if ord(c) > 0x7F and not c.isspace())
            if non_latin > len_trans * 0.5:
                log_debug(
                    "translate",
                    f"Too many non-Latin characters for English ({non_latin}/{len_trans})",
                )
                return 0.2
        elif target_lang.startswith("zh"):
            cjk = sum(1 for c in translated if "\u4e00" <= c <= "\u9fff")
            if len_trans > 10 and cjk < len_trans * 0.1:
                log_debug(
                    "translate",
                    f"Too few CJK characters for Chinese ({cjk}/{len_trans})",
                )
                return 0.1
        special_chars = sum(
            1 for c in translated if not c.isalnum() and not c.isspace()
        )
        special_ratio = special_chars / max(len_trans, 1)
        if special_ratio > 0.5:
            log_debug("translate", f"Too many special characters ({special_ratio:.2f})")
            return 0.2
        if translated.strip().lower() == original.strip().lower():
            log_debug("translate", "Translation is identical to original")
            return 0.0
        return 1.0

    def _update_chunk_size(self) -> None:
        """Aktualisiert die chunk_size basierend auf der aktuellen Konfiguration."""
        import logging

        logger = logging.getLogger("dragon")

        try:
            if (
                hasattr(self, "_adaptive_bytes_per_sec")
                and self._adaptive_bytes_per_sec > 0
            ):
                bytes_per_sec = self._adaptive_bytes_per_sec
                logger.debug(
                    f"_update_chunk_size: Verwende _adaptive_bytes_per_sec = {bytes_per_sec}",
                )
            else:
                bytes_per_sec = self.settings.config.BYTES_PER_SECOND
        except AttributeError:
            logger.warning(
                "_update_chunk_size: Fehler beim Zugriff auf BYTES_PER_SECOND – verwende Fallback 32000",
            )
            bytes_per_sec = 32000

        try:
            duration = self.settings.config.CHUNK_DURATION
        except AttributeError:
            logger.warning(
                "_update_chunk_size: Fehler beim Zugriff auf CHUNK_DURATION – verwende Fallback 10.0",
            )
            duration = 10.0

        if duration <= 0:
            logger.warning(
                f"_update_chunk_size: Ungültige duration={duration} – setze auf 10.0",
            )
            duration = 10.0
        if bytes_per_sec <= 0:
            logger.warning(
                f"_update_chunk_size: Ungültige bytes_per_sec={bytes_per_sec} – setze auf 32000",
            )
            bytes_per_sec = 32000

        new_chunk_size = int(duration * bytes_per_sec)
        if new_chunk_size % 2 != 0:
            new_chunk_size = max(2, new_chunk_size - 1)
        if new_chunk_size <= 0:
            logger.warning(
                f"_update_chunk_size: Berechnete chunk_size={new_chunk_size} ungültig – setze auf 320000",
            )
            new_chunk_size = 320000

        old_size = getattr(self, "chunk_size", 0)
        if old_size == new_chunk_size:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "processor",
                    f"_update_chunk_size: chunk_size bleibt bei {self.chunk_size}",
                )
            return

        self.chunk_size = new_chunk_size
        try:
            overlap = self.settings.config.CHUNK_OVERLAP
        except AttributeError:
            overlap = 1.0
        self.overlap_size = int(overlap * bytes_per_sec)
        if self.overlap_size % 2 != 0:
            self.overlap_size = max(2, self.overlap_size - 1)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "processor",
                f"_update_chunk_size: chunk_duration={duration}s, "
                f"bytes_per_sec={bytes_per_sec}, "
                f"chunk_size={self.chunk_size} bytes (alt: {old_size}), "
                f"overlap={self.overlap_size} bytes",
            )

    def set_chunk_duration(self, new_duration: float, force: bool = False) -> None:
        """Zentrale Methode zum Ändern der Chunk‑Dauer."""
        if not isinstance(new_duration, (int, float)) or new_duration <= 0:
            raise ValueError("Chunk‑Dauer muss eine positive Zahl sein.")
        if not force and self.is_processing():
            logger.warning(
                "Chunk‑Dauer kann während der Verarbeitung nicht geändert werden. "
                "Bitte stoppen Sie zuerst den Stream.",
            )
            return
        old_duration = self.settings.config.CHUNK_DURATION
        if abs(old_duration - new_duration) < 0.01:
            return
        self.settings.config.CHUNK_DURATION = new_duration

        try:
            self._adaptive_bytes_per_sec = self.settings.config.BYTES_PER_SECOND
        except AttributeError:
            self._adaptive_bytes_per_sec = 32000.0

        self._adaptive_warmup_chunks = 0
        self._smoothed_drift = 0.0
        self._offset_history.clear()
        self._raw_drift_history.clear()
        self._update_chunk_size()
        logger.info(
            "Chunk‑Dauer geändert: %.1fs → %.1fs, adaptive Rate zurückgesetzt.",
            old_duration,
            new_duration,
        )

    def _load_modules(self) -> None:
        if self._np is None and NUMPY_AVAILABLE:
            self._np = FastLazyLoader.load("numpy")
        if self._scipy_signal is None and SCIPY_AVAILABLE:
            self._scipy_signal = FastLazyLoader.load("scipy.signal")

    def set_expected_duration(self, duration: float | None) -> None:
        self._expected_duration = duration
        if duration is not None:
            logger.info(f"⏱️ Expected stream duration set: {duration:.1f}s")

    def set_progress_callback(
        self,
        callback: Callable[[int, int | None, int], None],
    ) -> None:
        self._progress_callback = callback

    def _set_engine(
        self,
        attr_name: str,
        new_engine: Any,
        dispose_old: bool = True,
    ) -> None:
        """Zentrale Methode zum Setzen einer Engine mit automatischer Entsorgung der alten."""
        with self._engine_lock:
            old = getattr(self, attr_name, None)
            setattr(self, attr_name, new_engine)
            if dispose_old and old is not None:
                self._pending_dispose.append(old)
                self._schedule_dispose()

    def _is_engine_functional(self, engine: Any) -> bool:
        """Hilfsmethode: prüft Funktionalität einer Engine (ohne Lock)."""
        if engine is None:
            return False
        if hasattr(engine, "is_functional"):
            try:
                return engine.is_functional()
            except Exception:
                return False
        return True

    def set_engines(
        self,
        transcription_engine: TranscriptionEngine | None,
        translation_engine: BaseTranslationEngine | None = None,
        fallback_translation_engine: BaseTranslationEngine | None = None,
    ) -> None:
        """Setzt alle drei Engines atomar und entsorgt alte Engines asynchron.
        Optimiert: keine doppelten Funktionalitätsprüfungen, robuste Fehlerbehandlung.

        ★ v2.4: Reicht die Fallback-Engine zusätzlich an die Haupt-Engine
        weiter, damit `GoogleTranslationEngine._call_argos_fallback` sie
        findet (sonst ist Argos-Fallback faktisch tot).
        """
        if (
            fallback_translation_engine is not None
            and not self._is_engine_functional_safe(fallback_translation_engine)
        ):
            fallback_translation_engine = None

        old_engines = []

        with self._engine_lock:
            for attr, new_engine in [
                ("_transcription_engine", transcription_engine),
                ("_translation_engine", translation_engine),
                ("_fallback_translation_engine", fallback_translation_engine),
            ]:
                old = getattr(self, attr, None)
                if old is not None:
                    old_engines.append(old)
                setattr(self, attr, new_engine)

            if (
                translation_engine is not None
                and fallback_translation_engine is not None
            ):
                try:
                    translation_engine._fallback_translation_engine = (
                        fallback_translation_engine
                    )
                except Exception as _wire_exc:
                    logger.debug("Fallback-Verdrahtung fehlgeschlagen: %s", _wire_exc)

            main_functional = self._is_engine_functional_safe(self._translation_engine)
            fallback_functional = False

            if not main_functional and self._fallback_translation_engine is not None:
                fallback_functional = self._is_engine_functional_safe(
                    self._fallback_translation_engine,
                )

            functional = main_functional or fallback_functional

            if functional:
                self._translation_enabled.set()
            else:
                self._translation_enabled.clear()

        for old in old_engines:
            self._pending_dispose.append(old)
        if old_engines:
            self._schedule_dispose()

        log_debug(
            "engine",
            f"Transcription engine set: {
                type(transcription_engine).__name__ if transcription_engine else 'None'
            }",
        )
        log_debug(
            "engine",
            f"Translation engine set: {
                type(translation_engine).__name__ if translation_engine else 'None'
            }",
        )
        if fallback_translation_engine:
            log_debug(
                "engine",
                f"Fallback translation engine set: {
                    type(fallback_translation_engine).__name__
                }",
            )
        else:
            log_debug("engine", "No fallback translation engine set")
        log_debug(
            "engine",
            f"Translation enabled: {self._translation_enabled.is_set()}",
        )

    def _is_engine_functional_safe(self, engine: Any) -> bool:
        """Prüft, ob eine Engine funktional ist – fehlertolerant."""
        if engine is None:
            return False
        try:
            if hasattr(engine, "is_functional"):
                return bool(engine.is_functional())
            return True
        except Exception as e:
            log_debug("engine", f"Engine functional check failed: {e}")
            return False

    def _get_effective_translation_engine(self) -> BaseTranslationEngine | None:
        """Gibt die aktuell funktionsfähige Übersetzungs-Engine zurück."""
        if not self._translation_enabled.is_set():
            return None

        if not hasattr(self, "_engine_functional_cache"):
            self._engine_functional_cache = {}
            self._engine_functional_cache_time = {}
        if not hasattr(self, "_engine_cache_lock"):
            self._engine_cache_lock = threading.RLock()
        if not hasattr(self, "_engine_failure_count"):
            self._engine_failure_count = {}
        if not hasattr(self, "_engine_disabled_until"):
            self._engine_disabled_until = {}

        def _get_cached_functional(engine, key: str, ttl: float = 60.0) -> bool:
            with self._engine_cache_lock:
                now = time.time()
                if key in self._engine_disabled_until:
                    if now < self._engine_disabled_until[key]:
                        return False
                    del self._engine_disabled_until[key]
                    self._engine_failure_count[key] = 0

                if key in self._engine_functional_cache:
                    if now - self._engine_functional_cache_time.get(key, 0) < ttl:
                        return self._engine_functional_cache[key]

                functional = self._is_engine_functional(engine)
                self._engine_functional_cache[key] = functional
                self._engine_functional_cache_time[key] = now

                if not functional:
                    self._engine_failure_count[key] = (
                        self._engine_failure_count.get(key, 0) + 1
                    )
                    if self._engine_failure_count[key] >= 3:
                        self._engine_disabled_until[key] = now + 60.0
                        logger.warning(
                            "⚠️ Engine %s temporär deaktiviert (3 Fehler in Folge) für 60s",
                            key,
                        )
                else:
                    self._engine_failure_count[key] = 0
                    if key in self._engine_disabled_until:
                        del self._engine_disabled_until[key]

                return functional

        def _get_ttl(engine) -> float:
            if engine is None:
                return 60.0
            engine_type = type(engine).__name__
            if "Google" in engine_type:
                return 30.0
            if "Ollama" in engine_type:
                return 120.0
            if "Argos" in engine_type:
                return 300.0
            return 60.0

        with self._engine_lock:
            main_engine = self._translation_engine
            fallback_engine = self._fallback_translation_engine

        if main_engine is not None:
            key = f"main_{id(main_engine)}"
            ttl = _get_ttl(main_engine)
            if _get_cached_functional(main_engine, key, ttl):
                if DEBUG_LEVEL >= 3:
                    logger.debug(
                        "✅ Haupt-Übersetzungs-Engine verfügbar: %s",
                        type(main_engine).__name__,
                    )
                return main_engine
            if DEBUG_LEVEL >= 2:
                logger.debug(
                    "Haupt-Übersetzungs-Engine (%s) nicht funktionsfähig – versuche Fallback",
                    type(main_engine).__name__,
                )

        if fallback_engine is not None:
            key = f"fallback_{id(fallback_engine)}"
            ttl = _get_ttl(fallback_engine)
            if _get_cached_functional(fallback_engine, key, ttl):
                logger.info(
                    "🔄 Verwende Fallback-Übersetzungs-Engine: %s",
                    type(fallback_engine).__name__,
                )
                return fallback_engine
            if DEBUG_LEVEL >= 2:
                logger.debug(
                    "Fallback-Engine (%s) ebenfalls nicht funktionsfähig",
                    type(fallback_engine).__name__,
                )

        if DEBUG_LEVEL >= 2:
            logger.debug("❌ Keine funktionsfähige Übersetzungs-Engine verfügbar")
        return None

    def _reset_engine_functional_cache(self) -> None:
        """Setzt den Cache für den Funktionsstatus zurück (z.B. nach Fehlern)."""
        if hasattr(self, "_engine_functional_cache"):
            self._engine_functional_cache.clear()
            self._engine_functional_cache_time.clear()

    def set_vad_fallback_enabled(self, enabled: bool) -> None:
        self._vad_fallback_enabled = enabled
        if self.transcription_engine:
            self.transcription_engine.set_vad_fallback_enabled(enabled)
        logger.debug(
            f"VAD‑Fallback im AudioProcessor {
                'aktiviert' if enabled else 'deaktiviert'
            }",
        )

    def enable_subtitle_mode(self, enabled: bool) -> dict:
        """Aktiviert oder deaktiviert den Untertitel-Modus atomar."""
        import logging
        import os
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", DEBUG_LEVEL)
        _start_t0 = time.perf_counter()

        diag: dict = {
            "success": False,
            "applied": False,
            "reason": None,
            "old_mode": None,
            "new_mode": None,
            "state_before": None,
            "workers_set": None,
            "swap_method": None,
            "errors": [],
            "total_ms": 0.0,
        }

        logger.info(
            "🐉 [SUBTITLE] enable_subtitle_mode called: enabled=%s",
            enabled,
        )

        try:
            st = getattr(self, "_state", None)
            diag["state_before"] = st.name if hasattr(st, "name") else str(st)
        except Exception:
            diag["state_before"] = None

        _is_processing = False
        try:
            st = getattr(self, "_state", None)
            _is_processing = (
                st is not None
                and hasattr(st, "name")
                and st.name in ("PROCESSING", "STARTING", "STOPPING")
            )
        except Exception:
            pass

        if _is_processing:
            logger.warning(
                "🐉 [SUBTITLE] ⛔ Toggle ignoriert – State=%s "
                "(erst stoppen, dann Subtitle-Modus wechseln). "
                "Grund: Executor-Shutdown-Race würde einen "
                "Audio-Chunk verwerfen.",
                diag["state_before"],
            )
            diag["reason"] = "processing_active"
            diag["new_mode"] = bool(enabled)
            diag["success"] = False
            diag["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)
            with contextlib.suppress(Exception):
                self._last_subtitle_toggle_diag = diag
            return diag

        old_mode = bool(getattr(self, "subtitle_mode", False))
        diag["old_mode"] = old_mode
        diag["new_mode"] = bool(enabled)

        if old_mode == enabled:
            if debug_level >= 3:
                log_debug(
                    "subtitle",
                    f"enable_subtitle_mode: bereits {enabled} – ignoriert",
                )
            diag["reason"] = "already_in_target_state"
            diag["applied"] = False
            diag["success"] = True
            diag["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)
            with contextlib.suppress(Exception):
                self._last_subtitle_toggle_diag = diag
            return diag

        target_mode = bool(enabled)

        if debug_level >= 2:
            log_debug(
                "subtitle",
                f"enable_subtitle_mode: Wechsel von {old_mode} → "
                f"{target_mode} angefordert.",
            )

        with self._subtitle_mode_lock:
            try:
                if target_mode:
                    self._subtitle_event.set()
                    self._subtitle_watchdog_seconds = 5.0
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            f"Watchdog auf "
                            f"{self._subtitle_watchdog_seconds}s "
                            f"gesetzt (Subtitle-Modus)",
                        )
                else:
                    self._subtitle_event.clear()
                    self._subtitle_watchdog_seconds = 60.0
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            f"Watchdog auf "
                            f"{self._subtitle_watchdog_seconds}s "
                            f"zurückgesetzt (Normal-Modus)",
                        )
            except Exception as e:
                diag["errors"].append(f"subtitle_event: {e}")
                logger.error(f"[SUBTITLE] Event-Set fehlgeschlagen: {e}")

            try:
                with self._segment_buffer_lock:
                    self._segment_buffer.clear()
                    self._next_expected_start = 0.0
                if debug_level >= 3:
                    log_debug("subtitle", "Segment buffer cleared")
            except Exception as e:
                diag["errors"].append(f"segment_buffer: {e}")

            if target_mode:
                new_workers = 1
            elif (
                hasattr(self, "_original_transcription_workers")
                and self._original_transcription_workers is not None
            ):
                new_workers = self._original_transcription_workers
            else:
                cpu_count = os.cpu_count() or 4
                new_workers = getattr(
                    self.settings,
                    "transcription_workers",
                    max(2, min(8, cpu_count // 4)),
                )
                self._original_transcription_workers = new_workers

            diag["workers_set"] = new_workers

            _swap_success = False
            try:
                _ExecutorCls = globals().get("OptimizedThreadPoolExecutor")
                _replace_fn = getattr(self, "_replace_executor", None)

                if _ExecutorCls is not None and callable(_replace_fn):
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            f"Verwende atomaren _replace_executor-Swap "
                            f"(workers={new_workers})",
                        )
                    try:
                        new_executor = _ExecutorCls(
                            max_workers=new_workers,
                            thread_name_prefix="Transcribe",
                            max_queue_size=2000,
                        )

                        _replace_fn(
                            "_transcription_executor",
                            new_executor,
                            shutdown_timeout=10.0,
                            cancel_futures=True,
                        )
                        _swap_success = True
                        diag["swap_method"] = "atomic"
                        if debug_level >= 3:
                            log_debug(
                                "subtitle",
                                f"✅ Executor atomar getauscht ({new_workers} worker)",
                            )
                    except Exception as e:
                        diag["errors"].append(f"replace_executor: {e}")
                        logger.warning(
                            f"[SUBTITLE] _replace_executor fehlgeschlagen, "
                            f"Fallback: {e}"
                        )
                else:
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            "OptimizedThreadPoolExecutor oder "
                            "_replace_executor nicht verfügbar – Fallback",
                        )
            except Exception as e:
                diag["errors"].append(f"atomic_swap_outer: {e}")

            if not _swap_success:
                try:
                    self._set_transcription_workers(new_workers)
                    diag["swap_method"] = "fallback"
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            f"Transkriptions-Worker auf {new_workers} "
                            f"gesetzt (Fallback)",
                        )
                except Exception as e:
                    diag["errors"].append(f"set_workers: {e}")
                    logger.error(f"Fehler beim Setzen der Transkriptions-Worker: {e}")
                    try:
                        if target_mode:
                            self._subtitle_event.clear()
                        else:
                            self._subtitle_event.set()
                    except Exception:
                        pass
                    diag["success"] = False
                    diag["reason"] = "set_workers_failed"
                    diag["total_ms"] = round(
                        (time.perf_counter() - _start_t0) * 1000, 2
                    )
                    with contextlib.suppress(Exception):
                        self._last_subtitle_toggle_diag = diag
                    return diag

            try:
                swap_fn = getattr(self, "_swap_timeout_executor", None)
                if callable(swap_fn):
                    swap_fn(target_mode)
            except Exception as e:
                diag["errors"].append(f"swap_timeout_executor: {e}")
                logger.debug(f"[SUBTITLE] _swap_timeout_executor fehlgeschlagen: {e}")

            if target_mode and not hasattr(self, "_original_transcription_workers"):
                cpu_count = os.cpu_count() or 4
                self._original_transcription_workers = getattr(
                    self.settings,
                    "transcription_workers",
                    max(2, min(8, cpu_count // 4)),
                )

            try:
                if self._event_bus is not None:
                    self._event_bus.emit("subtitle_mode_changed", target_mode)
                    if debug_level >= 3:
                        log_debug(
                            "subtitle",
                            f"Event 'subtitle_mode_changed' gesendet "
                            f"(value={target_mode})",
                        )
            except Exception as e:
                diag["errors"].append(f"emit_event: {e}")
                if debug_level >= 3:
                    log_debug(
                        "subtitle",
                        f"Failed to emit subtitle_mode_changed event: {e}",
                    )

            try:
                self.subtitle_mode = target_mode
                diag["applied"] = True
            except Exception as e:
                diag["errors"].append(f"set_mode_flag: {e}")

        diag["success"] = diag["applied"] and len(diag["errors"]) == 0
        diag["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)

        with contextlib.suppress(Exception):
            self._last_subtitle_toggle_diag = diag

        logger.info(
            "🎬 Subtitle mode: %s (was %s) – applied=%s, swap=%s, "
            "workers=%s, errors=%d, %.2fms",
            "ENABLED" if target_mode else "DISABLED",
            "ENABLED" if old_mode else "DISABLED",
            diag["applied"],
            diag["swap_method"] or "none",
            diag["workers_set"],
            len(diag["errors"]),
            diag["total_ms"],
        )

        if debug_level >= 2:
            log_debug(
                "subtitle",
                f"enable_subtitle_mode: Wechsel abgeschlossen "
                f"({old_mode} → {target_mode}, "
                f"swap={diag['swap_method']}, "
                f"workers={diag['workers_set']}, "
                f"errors={len(diag['errors'])})",
            )

        return diag

    def _swap_timeout_executor(self, target_mode: bool) -> None:
        """Hilfsmethode zum Austausch des Timeout-Executors."""
        old_executor = self._transcribe_timeout_executor

        if target_mode:
            new_workers = 1
        else:
            cpu_count = os.cpu_count() or 4
            new_workers = max(1, min(4, cpu_count // 4))

        new_executor = ThreadPoolExecutor(
            max_workers=new_workers,
            thread_name_prefix="TranscribeTimeout",
        )

        if old_executor is not None:
            safe_shutdown_executor(
                old_executor,
                wait=False,
                cancel_futures=True,
            )
            if DEBUG_LEVEL >= 4:
                log_debug("subtitle", "Alter Timeout‑Executor heruntergefahren")

        self._transcribe_timeout_executor = new_executor

        if DEBUG_LEVEL >= 3:
            log_debug(
                "subtitle",
                f"Timeout‑Executor auf {new_workers} Worker(s) gesetzt",
            )

    def update_target_language(self, lang_code: str) -> None:
        if hasattr(self, "translation_engine") and self.translation_engine is not None:
            self.translation_engine.set_target_language(lang_code)
        with self._translation_seq_lock:
            self._translation_seq += 1
        logger.info(
            f"🌐 AudioProcessor: Zielsprache auf {lang_code} gesetzt, Sequenz {
                self._translation_seq
            }",
        )

    def _replace_executor(
        self,
        attr: str,
        new_executor: Any | None,
        *,
        shutdown_timeout: float = 10.0,
        cancel_futures: bool = False,
        force: bool = False,
    ) -> None:
        """Ersetzt einen internen ThreadPoolExecutor (oder ähnlichen) **garantiert** und
        **thread‑sicher**. Behandelt alle Randfälle, korrigiert Inkonsistenzen und
        protokolliert detailliert.
        """
        import gc
        import logging
        import threading
        import time
        import traceback

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)
        is_verbose = debug_level >= 3 or "executor" in getattr(
            self,
            "debug_components",
            [],
        )

        if is_verbose:
            stack = traceback.extract_stack()[:-1]
            caller = " <- ".join(f"{f.name}:{f.lineno}" for f in stack[-3:])
            logger.debug(
                f"[EXECUTOR] _replace_executor called: attr={attr}, "
                f"new={type(new_executor).__name__ if new_executor else 'None'}, "
                f"timeout={shutdown_timeout:.1f}s, cancel={cancel_futures}, "
                f"force={force}, caller={caller}",
                extra={"component": "executor"},
            )
        else:
            logger.debug(
                f"[EXECUTOR] _replace_executor called: attr={attr}, "
                f"new={type(new_executor).__name__ if new_executor else 'None'}, "
                f"timeout={shutdown_timeout:.1f}s, cancel={cancel_futures}, "
                f"force={force}",
                extra={"component": "executor"},
            )

        old_executor: Any = getattr(self, attr, None)

        if old_executor is None:
            if new_executor is not None:
                setattr(self, attr, new_executor)
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] ✅ Neuer Executor für '{attr}' gesetzt (kein alter).",
                        extra={"component": "executor"},
                    )
            elif is_verbose:
                logger.debug(
                    f"[EXECUTOR] ℹ️ Executor '{attr}' bereits None – nichts zu tun.",
                    extra={"component": "executor"},
                )
            return

        shutdown_start = time.monotonic()
        shutdown_success = False
        shutdown_error: Exception | None = None

        try:
            if cancel_futures:
                cancelled = self._cancel_executor_futures(old_executor, attr)
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] → {cancelled} Future(s) abgebrochen (attr={attr})",
                        extra={"component": "executor"},
                    )

            if force:
                safe_shutdown_executor(old_executor, wait=False, cancel_futures=True)
                elapsed = time.monotonic() - shutdown_start
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] → Shutdown (force) abgeschlossen in {elapsed:.2f}s",
                        extra={"component": "executor"},
                    )
                shutdown_success = True
            else:
                shutdown_completed = threading.Event()
                shutdown_error_local: Exception | None = None

                def _do_shutdown() -> None:
                    nonlocal shutdown_error_local
                    try:
                        safe_shutdown_executor(
                            old_executor,
                            wait=True,
                            cancel_futures=cancel_futures,
                        )
                    except Exception as e:
                        shutdown_error_local = e
                    finally:
                        shutdown_completed.set()

                shutdown_thread = threading.Thread(
                    target=_do_shutdown,
                    daemon=True,
                    name=f"Shutdown-{attr}",
                )
                shutdown_thread.start()

                if shutdown_completed.wait(timeout=shutdown_timeout):
                    if shutdown_error_local is not None:
                        shutdown_error = shutdown_error_local
                        logger.error(
                            f"[EXECUTOR] ❌ Fehler beim Shutdown von Executor '{attr}': {shutdown_error}",
                            exc_info=True,
                            extra={"component": "executor"},
                        )
                    else:
                        shutdown_success = True
                        elapsed = time.monotonic() - shutdown_start
                        if is_verbose:
                            logger.debug(
                                f"[EXECUTOR] → Shutdown (graceful) abgeschlossen in {elapsed:.2f}s",
                                extra={"component": "executor"},
                            )
                else:
                    logger.warning(
                        f"[EXECUTOR] ⏰ Shutdown von Executor '{attr}' überschritt Timeout ({shutdown_timeout:.1f}s) – "
                        "erzwinge sofortigen Abbruch.",
                        extra={"component": "executor"},
                    )
                    try:
                        safe_shutdown_executor(
                            old_executor,
                            wait=False,
                            cancel_futures=True,
                        )
                        shutdown_success = True
                        elapsed = time.monotonic() - shutdown_start
                        if is_verbose:
                            logger.debug(
                                f"[EXECUTOR] → Shutdown (erzwungen) abgeschlossen in {elapsed:.2f}s",
                                extra={"component": "executor"},
                            )
                    except Exception as e:
                        logger.error(
                            f"[EXECUTOR] ❌ Auch erzwungener Shutdown von Executor '{attr}' fehlgeschlagen: {e}",
                            exc_info=True,
                            extra={"component": "executor"},
                        )
                        shutdown_error = e

        except Exception as exc:
            logger.error(
                f"[EXECUTOR] ❌ Unerwarteter Fehler beim Shutdown von Executor '{attr}': {exc}",
                exc_info=True,
                extra={"component": "executor"},
            )
            shutdown_error = exc

        if not force:
            prefix = getattr(old_executor, "_thread_name_prefix", attr)
            worker_threads = self._get_worker_threads(old_executor, prefix, attr)

            if worker_threads:
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] → {len(worker_threads)} Worker‑Thread(s) gefunden ({attr})",
                        extra={"component": "executor"},
                    )
                joined_count = self._join_worker_threads(
                    worker_threads,
                    max_time=shutdown_timeout * 0.5,
                    attr=attr,
                )
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] → {joined_count} von {len(worker_threads)} Thread(s) erfolgreich gejoint",
                        extra={"component": "executor"},
                    )

                still_alive = [t for t in worker_threads if t.is_alive()]
                if still_alive:
                    logger.debug(
                        f"[EXECUTOR] ℹ️ {len(still_alive)} Worker‑Thread(s) von "
                        f"Executor '{attr}' noch am Leben (daemon=True) – "
                        "werden beim Prozess‑Exit automatisch beendet.",
                        extra={"component": "executor"},
                    )
                    if debug_level >= 4:
                        self._log_thread_stacktraces(still_alive, attr)

            if len(worker_threads) > 10 and not shutdown_success:
                gc.collect()
                if is_verbose:
                    logger.debug(
                        f"[EXECUTOR] → GC nach Thread‑Join ausgelöst (attr={attr})",
                        extra={"component": "executor"},
                    )

        setattr(self, attr, None)

        if new_executor is not None:
            setattr(self, attr, new_executor)
            if is_verbose:
                logger.debug(
                    f"[EXECUTOR] ✅ Neuer Executor für '{attr}' gesetzt.",
                    extra={"component": "executor"},
                )
        elif is_verbose:
            logger.debug(
                f"[EXECUTOR] ℹ️ Executor '{attr}' auf None gesetzt.",
                extra={"component": "executor"},
            )

        elapsed_total = time.monotonic() - shutdown_start
        if shutdown_success:
            logger.debug(
                f"[EXECUTOR] ✅ _replace_executor für '{attr}' erfolgreich abgeschlossen in {elapsed_total * 1000:.2f}ms",
                extra={"component": "executor"},
            )
        else:
            logger.error(
                f"[EXECUTOR] ❌ _replace_executor für '{attr}' mit Fehlern abgeschlossen (Dauer {elapsed_total * 1000:.2f}ms) – "
                f"letzter Fehler: {shutdown_error}",
                extra={"component": "executor"},
            )

    def _cancel_executor_futures(self, executor: Any, attr: str) -> int:
        """Bricht alle aktiven und ausstehenden Futures eines Executors ab
        und drainiert die interne `_work_queue`.
        """
        import contextlib
        import queue as _queue_mod

        cancelled = 0
        section_counts: dict[str, int] = {}
        errors: list[str] = []

        if hasattr(executor, "_active_futures"):
            try:
                lock = getattr(executor, "_active_futures_lock", None)
                ctx = lock if lock is not None else contextlib.nullcontext()
                with ctx:
                    futures = list(executor._active_futures)
                    section_count = 0
                    for f in futures:
                        try:
                            if not f.done():
                                f.cancel()
                                section_count += 1
                        except Exception as fe:
                            errors.append(f"cancel(_active_futures): {fe}")
                    try:
                        executor._active_futures.clear()
                    except Exception as ce:
                        errors.append(f"clear(_active_futures): {ce}")
                cancelled += section_count
                section_counts["_active_futures"] = section_count
            except Exception as e:
                errors.append(f"_active_futures: {e}")

        if hasattr(executor, "_pending_work_items"):
            try:
                pending = list(executor._pending_work_items.keys())
                section_count = 0
                for f in pending:
                    try:
                        if not f.done():
                            f.cancel()
                            section_count += 1
                    except Exception as fe:
                        errors.append(f"cancel(_pending_work_items): {fe}")
                    with contextlib.suppress(Exception):
                        executor._pending_work_items.pop(f, None)
                with contextlib.suppress(Exception):
                    executor._pending_work_items.clear()
                cancelled += section_count
                section_counts["_pending_work_items"] = section_count
            except Exception as e:
                errors.append(f"_pending_work_items: {e}")

        if hasattr(executor, "_futures"):
            try:
                futures = list(executor._futures)
                section_count = 0
                for f in futures:
                    try:
                        if not f.done():
                            f.cancel()
                            section_count += 1
                    except Exception as fe:
                        errors.append(f"cancel(_futures): {fe}")
                try:
                    executor._futures.clear()
                except Exception as ce:
                    errors.append(f"clear(_futures): {ce}")
                cancelled += section_count
                section_counts["_futures"] = section_count
            except Exception as e:
                errors.append(f"_futures: {e}")

        if hasattr(executor, "_work_queue"):
            queue_obj = executor._work_queue
            drained = 0
            drain_errors = 0
            try:
                while True:
                    try:
                        item = queue_obj.get_nowait()
                    except _queue_mod.Empty:
                        break
                    except Exception as ge:
                        drain_errors += 1
                        errors.append(f"get_nowait(_work_queue): {ge}")
                        break

                    if hasattr(item, "cancel"):
                        try:
                            item.cancel()
                        except Exception as ce:
                            errors.append(f"cancel(_work_queue item): {ce}")
                    drained += 1

                cancelled += drained
                section_counts["_work_queue"] = drained

                if drain_errors:
                    errors.append(f"_work_queue: {drain_errors} Drain-Fehler")
            except Exception as e:
                errors.append(f"_work_queue: {e}")

        if DEBUG_LEVEL >= 4:
            parts = [
                f"{name}={count}" for name, count in section_counts.items() if count > 0
            ]
            if parts:
                log_debug(
                    "executor",
                    "  → Futures abgebrochen für '%s': %s",
                    attr,
                    ", ".join(parts),
                )

        if errors and DEBUG_LEVEL >= 3:
            log_debug(
                "executor",
                "  → _cancel_executor_futures('%s'): %d abgebrochen, %d Fehler",
                attr,
                cancelled,
                len(errors),
            )
            for err in errors[:5]:
                log_debug("executor", "     • %s", err)
            if len(errors) > 5:
                log_debug(
                    "executor",
                    "     • ... (%d weitere Fehler)",
                    len(errors) - 5,
                )

        if cancelled == 0 and DEBUG_LEVEL >= 5:
            log_debug(
                "executor",
                "  → _cancel_executor_futures('%s'): nichts abzubrechen",
                attr,
            )

        return cancelled

    def _get_worker_threads(
        self,
        executor: Any,
        prefix: str,
        attr: str,
    ) -> list[threading.Thread]:
        """Sammelt die Worker-Threads eines Executors.
        """
        _getter = getattr(executor, "get_worker_threads", None)
        if callable(_getter):
            try:
                tracked = list(_getter())
                alive = [
                    t
                    for t in tracked
                    if t is not None
                    and t.is_alive()
                    and t is not threading.current_thread()
                ]
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        "  → %d/%d Thread(s) via get_worker_threads() (alive/tracked)",
                        len(alive),
                        len(tracked),
                    )
                return alive
            except Exception as e:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        "  → get_worker_threads() nicht nutzbar: %s",
                        e,
                    )

        if hasattr(executor, "_workers"):
            try:
                tracked = [t for t in executor._workers if t is not None]
                alive = [
                    t
                    for t in tracked
                    if t.is_alive() and t is not threading.current_thread()
                ]
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        "  → %d/%d Thread(s) via _workers (alive/tracked)",
                        len(alive),
                        len(tracked),
                    )
                return alive
            except Exception as e:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        "  → _workers nicht lesbar: %s",
                        e,
                    )

        if hasattr(executor, "_threads"):
            try:
                std_threads = list(executor._threads)
                if std_threads and DEBUG_LEVEL >= 4:
                    log_debug(
                        "executor",
                        "  → %d Threads via _threads gefunden",
                        len(std_threads),
                    )
                return [
                    t
                    for t in std_threads
                    if t.is_alive() and t is not threading.current_thread()
                ]
            except Exception as e:
                if DEBUG_LEVEL >= 4:
                    log_debug("executor", "  → _threads nicht lesbar: %s", e)

        threads: list[threading.Thread] = []
        for t in threading.enumerate():
            if (
                t.name.startswith(prefix)
                and t.is_alive()
                and t is not threading.current_thread()
            ):
                threads.append(t)

        if threads and DEBUG_LEVEL >= 4:
            log_debug(
                "executor",
                "  → %d Threads via Namenspräfix '%s' gefunden",
                len(threads),
                prefix,
            )

        return threads

    def _log_thread_stacktraces(
        self,
        threads: list[threading.Thread],
        attr: str,
    ) -> None:
        """Gibt Stacktraces der übergebenen Threads aus (nur bei DEBUG_LEVEL >= 4)."""
        import sys
        import traceback

        frames = sys._current_frames()
        for t in threads:
            if t.ident is None:
                continue
            frame = frames.get(t.ident)
            if frame is None:
                log_debug(
                    "executor",
                    "  → Thread '%s': kein Stacktrace verfügbar",
                    t.name,
                )
                continue
            stack = "".join(traceback.format_stack(frame))
            log_debug(
                "executor",
                "  → Thread '%s' (alive=%s):\n%s",
                t.name,
                t.is_alive(),
                stack,
            )

    def _init_transcription_executor(self) -> None:
        """Initialisiert oder ersetzt den Transkriptions‑Executor mit optimierter Worker‑Anzahl
        und garantiert, dass die Queue‑Größe niemals unter einem sinnvollen Minimum liegt.
        """
        if self.subtitle_mode:
            workers = 1
            queue_size = 1100
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    "Subtitle mode active – using 1 transcription worker, queue_size=500",
                )
            self._replace_executor(
                "_transcription_executor",
                OptimizedThreadPoolExecutor(
                    max_workers=workers,
                    thread_name_prefix="Transcribe",
                    max_queue_size=queue_size,
                ),
                cancel_futures=True,
            )
            return

        cpu_count = os.cpu_count() or 2
        is_arm = IS_ARM
        is_gpu = self._is_gpu_available()
        total_ram_gb = self._get_system_ram_gb()
        base_workers = cpu_count

        if is_arm:
            base_workers = min(base_workers, 2)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    "ARM architecture detected – limiting workers to 2",
                )

        if total_ram_gb < 4.0:
            base_workers = min(base_workers, 2)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    f"Low RAM ({total_ram_gb:.1f} GB) – limiting workers to 2",
                )
        if is_gpu:
            optimal_workers = max(4, min(base_workers, cpu_count // 2))
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    f"GPU available – optimal workers: {optimal_workers}",
                )
        else:
            optimal_workers = max(2, min(base_workers, cpu_count // 4))
            if DEBUG_LEVEL >= 3:
                log_debug("executor", f"CPU mode – optimal workers: {optimal_workers}")

        user_workers = getattr(self.settings, "transcription_workers", None)
        if user_workers is not None and user_workers > 0:
            max_allowed = cpu_count * 2
            workers = min(user_workers, max_allowed)
            workers = max(1, workers)
            if workers > optimal_workers and (is_arm or total_ram_gb < 4.0):
                logger.warning(
                    f"⚠️ User requested {workers} workers, but system is weak "
                    f"(ARM={is_arm}, RAM={total_ram_gb:.1f}GB). "
                    f"Reducing to {optimal_workers} for stability.",
                )
                workers = optimal_workers
        else:
            workers = optimal_workers

        user_queue_size = getattr(self.settings, "transcription_queue_size", None)
        if user_queue_size is not None and user_queue_size > 0:
            queue_size = max(100, user_queue_size)
            if DEBUG_LEVEL >= 3:
                log_debug("executor", f"Using user‑defined queue_size={queue_size}")
        else:
            queue_size = max(1000, min(8000, workers * 1000))
            if workers <= 2:
                queue_size = max(queue_size, 2000)

        current_executor = getattr(self, "_transcription_executor", None)
        if current_executor is not None:
            current_workers = getattr(current_executor, "_max_workers", 0)
            current_queue = getattr(current_executor, "_max_queue_size", 0)
            if current_workers == workers and current_queue == queue_size:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"Executor already configured with workers={workers}, queue_size={queue_size} – skipping",
                    )
                return

        try:
            new_executor = OptimizedThreadPoolExecutor(
                max_workers=workers,
                thread_name_prefix="Transcribe",
                max_queue_size=queue_size,
            )
            self._replace_executor(
                "_transcription_executor",
                new_executor,
                cancel_futures=True,
            )
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "executor",
                    f"Transcription executor initialized: workers={workers}, "
                    f"queue_size={queue_size}, gpu={is_gpu}, arm={is_arm}, "
                    f"ram={total_ram_gb:.1f}GB, cores={cpu_count}",
                )
        except Exception as e:
            logger.error(
                f"Failed to initialize transcription executor: {e}",
                exc_info=True,
            )

            try:
                fallback_executor = OptimizedThreadPoolExecutor(
                    max_workers=1,
                    thread_name_prefix="TranscribeFallback",
                    max_queue_size=250,
                )
                self._replace_executor(
                    "_transcription_executor",
                    fallback_executor,
                    cancel_futures=True,
                )
                logger.warning(
                    "⚠️ Transcription executor fallback to 1 worker, queue_size=200",
                )
            except Exception as fallback_e:
                logger.critical(f"Even fallback executor failed: {fallback_e}")
                self._transcription_executor = None
                raise RuntimeError("Could not initialize transcription executor") from e

        if DEBUG_LEVEL >= 4:
            if hasattr(self._transcription_executor, "_max_queue_size"):
                log_debug(
                    "executor",
                    f"Executor queue max size: {self._transcription_executor._max_queue_size}",
                )

    def _get_system_ram_gb(self) -> float:
        """Ermittelt den verfügbaren Arbeitsspeicher in GB."""
        try:
            import psutil

            return psutil.virtual_memory().total / (1024**3)
        except ImportError:
            try:
                with open("/proc/meminfo") as f:
                    for line in f:
                        if line.startswith("MemTotal:"):
                            kb = int(line.split()[1])
                            return kb / (1024 * 1024)
            except Exception:
                pass
        return 2.0

    def _init_timeout_executor(self) -> None:
        """Initialisiert den Timeout‑Executor für Transkriptionen."""
        current_executor = getattr(self, "_transcribe_timeout_executor", None)
        if current_executor is not None:
            current_workers = getattr(current_executor, "_max_workers", 0)
            if current_workers == 1:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        "Timeout executor already configured with 1 worker – skipping",
                    )
                return
            with contextlib.suppress(Exception):
                current_executor.shutdown(wait=False, cancel_futures=True)

        def daemon_thread_factory(*args, **kwargs):
            """Erzeugt einen Daemon-Thread für den Executor."""
            thread = threading.Thread(*args, **kwargs)
            thread.daemon = True
            return thread

        try:
            new_executor = OptimizedThreadPoolExecutor(
                max_workers=1,
                thread_name_prefix="TranscribeTimeout",
                max_queue_size=100,
                thread_factory=daemon_thread_factory,
            )
            self._transcribe_timeout_executor = new_executor

            if DEBUG_LEVEL >= 2:
                log_debug(
                    "executor",
                    "✅ Timeout executor initialized: workers=1, queue_size=100 (daemon threads)",
                )

        except Exception as e:
            logger.error("Failed to initialize timeout executor: %s", e, exc_info=True)

            try:
                from concurrent.futures import ThreadPoolExecutor

                fallback_executor = ThreadPoolExecutor(
                    max_workers=1,
                    thread_name_prefix="TranscribeTimeoutFallback",
                )
                self._transcribe_timeout_executor = fallback_executor
                logger.warning(
                    "⚠️ Timeout executor fallback to standard ThreadPoolExecutor (1 worker) – "
                    "Threads sind möglicherweise nicht als Daemon markiert",
                )
            except Exception as fallback_e:
                logger.critical("Even fallback timeout executor failed: %s", fallback_e)
                self._transcribe_timeout_executor = None
                raise RuntimeError("Could not initialize timeout executor") from e

        if not hasattr(self, "_timeout_executor_shutdown_lock"):
            self._timeout_executor_shutdown_lock = threading.RLock()
        self._timeout_executor_shutdown_done = False

        if DEBUG_LEVEL >= 4:
            log_debug(
                "executor",
                "Timeout executor state: %s",
                type(self._transcribe_timeout_executor).__name__,
            )

    def _init_translation_executor(self) -> None:
        """Initialisiert oder ersetzt den Übersetzungs‑Executor mit optimierter Worker‑Anzahl.
        Berücksichtigt CPU-Kerne, ARM-Architektur, verfügbaren Arbeitsspeicher,
        API-Rate-Limits (z. B. Google Translate) und Benutzervorgaben.
        """
        cpu_count = os.cpu_count() or 4
        is_arm = IS_ARM
        is_gpu = self._is_gpu_available()
        engine_type = getattr(self.settings, "translation_engine", "google")
        total_ram_gb = self._get_system_ram_gb()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "executor",
                "🔍 _init_translation_executor: cpu_count=%d, is_arm=%s, is_gpu=%s, engine=%s, ram=%.1fGB",
                cpu_count,
                is_arm,
                is_gpu,
                engine_type,
                total_ram_gb,
            )

        if is_arm or cpu_count < 4:
            optimal_workers = 2
        else:
            optimal_workers = max(2, min(6, cpu_count // 2))

        if total_ram_gb < 2.0:
            optimal_workers = min(optimal_workers, 1)
            logger.info(
                f"💻 Very low RAM ({total_ram_gb:.1f} GB) – limiting translation workers to 1",
            )
        elif total_ram_gb < 4.0:
            optimal_workers = min(optimal_workers, 2)
        elif total_ram_gb < 8.0:
            optimal_workers = min(optimal_workers, 3)

        user_workers = getattr(self.settings, "translation_workers", None)
        if user_workers is not None:
            if user_workers <= 0:
                logger.warning(
                    "⚠️ translation_workers auf %d gesetzt – Übersetzung wird deaktiviert! "
                    "Setze auf mindestens 1 Worker.",
                    user_workers,
                )
                user_workers = 1

            MAX_USER_WORKERS = 8
            workers = min(user_workers, MAX_USER_WORKERS)

            if workers > optimal_workers and (is_arm or total_ram_gb < 4.0):
                logger.warning(
                    f"⚠️ User requested {workers} translation workers, but system is weak "
                    f"(ARM={is_arm}, RAM={total_ram_gb:.1f}GB). "
                    f"Reducing to {optimal_workers} for stability.",
                )
                workers = optimal_workers
            elif workers > optimal_workers and is_gpu:
                workers = min(workers, optimal_workers * 2)
        else:
            workers = optimal_workers

        original_workers = workers

        if engine_type == "google" and workers > 3:
            logger.info(
                f"Google Translate erkannt – reduziere Worker von {workers} auf 3 "
                "(wegen API-Rate-Limits)",
            )
            workers = 3
        elif engine_type == "ollama" and workers > 4:
            workers = min(workers, 6)
        elif engine_type == "argos" and workers > 2:
            workers = min(workers, 4)

        workers = max(1, workers)

        if workers != original_workers and DEBUG_LEVEL >= 2:
            log_debug(
                "executor",
                f"Engine-specific adjustment: {original_workers} → {workers} (engine={engine_type})",
            )

        queue_size = max(150, min(500, workers * 75))
        if engine_type == "google":
            queue_size = min(queue_size, 200)
        elif engine_type == "ollama":
            queue_size = max(queue_size, 200)

        if DEBUG_LEVEL >= 3:
            log_debug("executor", f"  Queue size: {queue_size} (workers={workers})")

        current_executor = getattr(self, "_translation_executor", None)
        if current_executor is not None:
            current_workers = getattr(current_executor, "_max_workers", 0)
            current_queue = getattr(current_executor, "_max_queue_size", 0)
            current_semaphore = getattr(self, "_translation_semaphore", None)
            current_semaphore_workers = (
                current_semaphore._value if current_semaphore else 0
            )

            if (
                current_workers == workers
                and current_queue == queue_size
                and current_semaphore_workers == workers
            ):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"Translation executor already configured with workers={workers}, queue_size={queue_size} – skipping",
                    )
                return

        self._translation_semaphore = threading.Semaphore(workers)

        try:
            new_executor = OptimizedThreadPoolExecutor(
                max_workers=workers,
                thread_name_prefix="Translate",
                max_queue_size=queue_size,
            )
            self._replace_executor(
                "_translation_executor",
                new_executor,
                cancel_futures=True,
            )

            if DEBUG_LEVEL >= 2:
                log_debug(
                    "executor",
                    f"✅ Translation executor initialized: workers={workers}, "
                    f"queue_size={queue_size}, cpu_count={cpu_count}, "
                    f"ram={total_ram_gb:.1f}GB, engine={engine_type}, "
                    f"user_override={user_workers is not None}, arm={is_arm}, gpu={is_gpu}",
                )

            self._translation_enabled.set()

        except Exception as e:
            logger.error(
                f"❌ Failed to initialize translation executor: {e}",
                exc_info=True,
            )

            try:
                fallback_workers = 1
                fallback_queue = 100
                fallback_executor = OptimizedThreadPoolExecutor(
                    max_workers=fallback_workers,
                    thread_name_prefix="TranslateFallback",
                    max_queue_size=fallback_queue,
                )
                self._replace_executor(
                    "_translation_executor",
                    fallback_executor,
                    cancel_futures=True,
                )
                self._translation_semaphore = threading.Semaphore(fallback_workers)
                logger.warning(
                    f"⚠️ Translation executor fallback to {fallback_workers} worker, queue_size={fallback_queue}",
                )
                self._translation_enabled.set()
            except Exception as fallback_e:
                logger.critical(
                    f"❌ Even fallback translation executor failed: {fallback_e}",
                )
                self._translation_executor = None
                self._translation_semaphore = threading.Semaphore(1)
                self._translation_enabled.clear()
                logger.error(
                    "🚨 Translation executor is disabled due to initialization failure",
                )
                raise RuntimeError("Could not initialize translation executor") from e

        if engine_type == "google" and not TRANSLATOR_AVAILABLE:
            logger.warning(
                "⚠️ Google Translate engine selected but 'deep-translator' is not installed. "
                "Install it with: pip install deep-translator",
            )
        elif engine_type == "ollama" and not OLLAMA_AVAILABLE:
            logger.warning(
                "⚠️ Ollama engine selected but 'requests' is not installed or Ollama server is not reachable. "
                "Install with: pip install requests",
            )
        elif engine_type == "argos" and not ARGOS_AVAILABLE:
            logger.warning(
                "⚠️ Argos engine selected but 'argostranslate' is not installed. "
                "Install with: pip install argostranslate",
            )

        if DEBUG_LEVEL >= 4:
            if hasattr(self._translation_executor, "_max_queue_size"):
                log_debug(
                    "executor",
                    f"  Executor queue max size: {self._translation_executor._max_queue_size}",
                )
            if hasattr(self._translation_semaphore, "_value"):
                log_debug(
                    "executor",
                    f"  Semaphore value: {self._translation_semaphore._value}",
                )

    def _init_transcribe_timeout_executor(self) -> None:
        """Initialisiert oder ersetzt den Timeout‑Executor für Transkriptionen."""
        cpu_count = os.cpu_count() or 2
        is_arm = IS_ARM
        is_gpu = self._is_gpu_available()
        is_subtitle = self.subtitle_mode

        total_ram_gb = self._get_total_ram_gb()

        if is_subtitle:
            workers = 1
            if DEBUG_LEVEL >= 3:
                log_debug("executor", "Subtitle mode – using 1 timeout worker")
        else:
            workers = max(1, min(4, cpu_count // 4))

            if is_gpu:
                workers = max(workers, 2)
                if DEBUG_LEVEL >= 3:
                    log_debug("executor", f"GPU available – timeout workers: {workers}")

            if total_ram_gb < 4.0:
                workers = min(workers, 2)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"Low RAM ({
                            total_ram_gb:.1f} GB) – limiting timeout workers to {
                            workers
                        }",
                    )

            if total_ram_gb < 2.0:
                workers = 1
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"Very low RAM ({
                            total_ram_gb:.1f} GB) – using 1 timeout worker",
                    )

            if is_arm:
                workers = min(workers, 2)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        "ARM architecture – limiting timeout workers to 2",
                    )

        current_executor = getattr(self, "_transcribe_timeout_executor", None)
        if current_executor is not None:
            current_workers = getattr(current_executor, "_max_workers", 0)
            if current_workers == workers:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "executor",
                        f"Timeout executor already configured with {workers} workers – skipping",
                    )
                return

        if current_executor is not None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "executor",
                    f"Shutting down old timeout executor ({current_workers} workers) ...",
                )

            with self._timeout_futures_lock:
                futures = list(self._active_timeout_futures)
                self._active_timeout_futures.clear()
                cancelled = 0
                for future in futures:
                    if not future.done():
                        future.cancel()
                        cancelled += 1
                if DEBUG_LEVEL >= 3 and cancelled > 0:
                    log_debug(
                        "executor",
                        f"Cancelled {cancelled} pending timeout futures",
                    )

            shutdown_done = threading.Event()
            shutdown_error = None

            def _shutdown_old():
                nonlocal shutdown_error
                try:
                    safe_shutdown_executor(
                        current_executor,
                        wait=True,
                        cancel_futures=True,
                    )
                except TypeError:
                    current_executor.shutdown(wait=True)
                except Exception as e:
                    shutdown_error = e
                finally:
                    shutdown_done.set()

            shutdown_thread = threading.Thread(target=_shutdown_old, daemon=True)
            shutdown_thread.start()

            SHUTDOWN_TIMEOUT = 3.0
            if not shutdown_done.wait(timeout=SHUTDOWN_TIMEOUT):
                logger.warning(
                    f"⚠️ Old timeout executor did not shut down within {SHUTDOWN_TIMEOUT}s – forcing abort",
                )
                with contextlib.suppress(Exception):
                    safe_shutdown_executor(
                        current_executor,
                        wait=False,
                        cancel_futures=True,
                    )
            elif shutdown_error:
                logger.warning(
                    f"⚠️ Error during old timeout executor shutdown: {shutdown_error}",
                )

            self._transcribe_timeout_executor = None

        new_executor = ThreadPoolExecutor(
            max_workers=workers,
            thread_name_prefix="TranscribeTimeout",
        )

        self._transcribe_timeout_executor = new_executor
        with self._timeout_futures_lock:
            self._active_timeout_futures.clear()

        logger.debug(
            f"✅ TranscribeTimeout executor initialized: {workers} worker(s) "
            f"(cpu={cpu_count}, ram={total_ram_gb:.1f}GB, gpu={is_gpu}, arm={
                is_arm
            }, subtitle={is_subtitle})",
        )

    @property
    def subtitle_mode(self) -> bool:
        """Thread‑sicherer Zugriff auf den Untertitel‑Modus."""
        return self._subtitle_event.is_set()

    @subtitle_mode.setter
    def subtitle_mode(self, value: bool) -> None:
        """Thread‑sicheres Setzen des Untertitel‑Modus mit automatischer Anpassung
        der Worker‑Anzahl und Benachrichtigung über den Event‑Bus.
        """
        old_mode = self.subtitle_mode
        if old_mode == value:
            if DEBUG_LEVEL >= 3:
                log_debug("subtitle", f"subtitle_mode bereits {value} – ignoriert")
            return

        if DEBUG_LEVEL >= 2:
            log_debug(
                "subtitle",
                f"subtitle_mode: Wechsel von {old_mode} → {value} angefordert",
            )

        with self._subtitle_mode_lock:
            if value:
                self._subtitle_event.set()
            else:
                self._subtitle_event.clear()

            with self._segment_buffer_lock:
                self._segment_buffer.clear()
                self._next_expected_start = 0.0
                if DEBUG_LEVEL >= 3:
                    log_debug("subtitle", "Segment‑Puffer geleert")

            if value:
                new_workers = 1
            else:
                cpu_count = os.cpu_count() or 4
                new_workers = getattr(
                    self.settings,
                    "transcription_workers",
                    max(1, cpu_count // 8),
                )
                if hasattr(self, "_original_transcription_workers"):
                    new_workers = self._original_transcription_workers
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "subtitle",
                            f"Stelle originale Worker‑Anzahl wieder her: {new_workers}",
                        )

            try:
                self._set_transcription_workers(new_workers)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "subtitle",
                        f"Transkriptions‑Worker auf {new_workers} gesetzt",
                    )
            except Exception as e:
                logger.error(f"Fehler beim Setzen der Transkriptions‑Worker: {e}")
                if value:
                    self._subtitle_event.clear()
                else:
                    self._subtitle_event.set()
                raise

            old_timeout_executor = self._transcribe_timeout_executor
            try:
                if value:
                    new_timeout_executor = ThreadPoolExecutor(
                        max_workers=1,
                        thread_name_prefix="TranscribeTimeout",
                    )
                else:
                    cpu_count = os.cpu_count() or 4
                    timeout_workers = max(1, cpu_count // 4)
                    timeout_workers = min(timeout_workers, 4)
                    new_timeout_executor = ThreadPoolExecutor(
                        max_workers=timeout_workers,
                        thread_name_prefix="TranscribeTimeout",
                    )

                if old_timeout_executor is not None:
                    try:
                        safe_shutdown_executor(
                            executor,
                            wait=False,
                            cancel_futures=True,
                        )
                        if DEBUG_LEVEL >= 4:
                            log_debug(
                                "subtitle",
                                "Alter Timeout‑Executor heruntergefahren",
                            )
                    except Exception:
                        old_timeout_executor.shutdown(wait=False)

                self._transcribe_timeout_executor = new_timeout_executor
                if DEBUG_LEVEL >= 3:
                    actual_workers = 1 if value else timeout_workers
                    log_debug(
                        "subtitle",
                        f"Timeout‑Executor auf {actual_workers} Worker(s) gesetzt",
                    )

            except Exception as e:
                logger.warning(
                    f"Konnte Timeout‑Executor nicht anpassen: {e} – Moduswechsel dennoch wirksam",
                )
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "subtitle",
                        "Timeout executor swap failed",
                        e,
                        level="debug",
                    )

        if self._event_bus is not None:
            try:
                self._event_bus.emit("subtitle_mode_changed", value)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "subtitle",
                        f"Event 'subtitle_mode_changed' gesendet (value={value})",
                    )
            except Exception as e:
                log_debug(
                    "subtitle",
                    f"Failed to emit subtitle_mode_changed event: {e}",
                )

        logger.info(
            "🎬 Subtitle mode: %s (was %s)",
            "ENABLED" if value else "DISABLED",
            "ENABLED" if old_mode else "DISABLED",
        )

        if DEBUG_LEVEL >= 2:
            log_debug(
                "subtitle",
                f"subtitle_mode: Wechsel erfolgreich abgeschlossen ({old_mode} → {value})",
            )

    def start_processing(
        self,
        url: str,
        transcription_callback: TranscriptionCallback,
        translation_callback: TranslationCallback,
        info_callback: InfoCallback,
        error_callback: ErrorCallback,
        finished_callback: FinishedCallback | None = None,
        is_direct_url: bool = False,
        **kwargs,
    ) -> bool:
        """🚀 DAS HERZ DER AUDIO-VERARBEITUNG!
        Startet die asynchrone Audioverarbeitung für eine gegebene URL.
        """
        import logging
        import queue
        import threading
        import time

        logger = logging.getLogger("dragon")
        start_time = time.monotonic()
        call_id = f"start-{int(time.time() * 1000)}-{id(self)}"

        if not hasattr(self, "_start_processing_lock"):
            self._start_processing_lock = threading.RLock()

        if not self._start_processing_lock.acquire(blocking=False):
            logger.warning(
                f"[PROCESSOR] ⚠️ start_processing läuft bereits – "
                f"call_id={call_id} wird ignoriert"
            )
            return False

        try:
            logger.info("=" * 80)
            logger.info("🔥 start_processing V8.1 – ZENTRALE GESTARTET")
            logger.info(f"   • CALL-ID:      {call_id}")
            logger.info(f"   • URL:          {url[:100]}...")
            logger.info(f"   • IS_DIRECT:    {is_direct_url}")
            logger.info(f"   • KARGS-KEYS:   {list(kwargs.keys())}")
            logger.info("=" * 80)
            _session_model = "?"
            try:
                _argv_st = sys.argv
                for _i_st, _a_st in enumerate(_argv_st):
                    if _a_st == "--model" and _i_st + 1 < len(_argv_st):
                        _session_model = _argv_st[_i_st + 1]
                        break
                    if _a_st.startswith("--model="):
                        _session_model = _a_st.split("=", 1)[1]
                        break
            except Exception:
                pass
            if _session_model in ("?", None, ""):
                try:
                    _te_st = getattr(self, "transcription_engine", None)
                    if _te_st is None:
                        _ap_st = getattr(self, "audio_processor", None)
                        _te_st = getattr(_ap_st, "transcription_engine", None)
                    _session_model = getattr(_te_st, "model_size", None) or getattr(
                        _te_st, "_requested_model", None
                    )
                except Exception:
                    _session_model = None
            if _session_model in ("?", None, ""):
                try:
                    import json as _json_st
                    from pathlib import Path as _Path_st

                    _cfg_path_st = (
                        _Path_st.home()
                        / ".config"
                        / "dragonwhisperer"
                        / "dragon_advanced_settings.json"
                    )
                    if _cfg_path_st.exists():
                        _cfg_data_st = _json_st.loads(
                            _cfg_path_st.read_text(encoding="utf-8")
                        )
                        _session_model = (
                            _cfg_data_st.get("model_size")
                            or _cfg_data_st.get("model")
                            or "unknown"
                        )
                except Exception:
                    _session_model = "unknown"
            if _session_model in ("?", None, ""):
                _session_model = "unknown"
            log_ai(
                "SESSION-START",
                id=call_id,
                url=str(url)[:200],
                model=str(_session_model),
                is_direct=is_direct_url,
                live=kwargs.get("is_live", False),
            )

            output_queue = kwargs.get("output_queue")
            original_url = kwargs.get("original_url", url)
            is_live = kwargs.get("is_live", False)

            self._output_queue = output_queue
            self._original_url = original_url
            self._is_live = is_live

            logger.debug(
                f"[PROCESSOR] 📤 output_queue: {output_queue is not None} "
                f"(ID: {id(output_queue) if output_queue else 'None'})"
            )
            logger.debug(f"[PROCESSOR] 📋 original_url: {original_url}")
            logger.debug(f"[PROCESSOR] 📡 is_live: {is_live}")

            self._is_direct_url = is_direct_url

            if transcription_callback is None:
                raise ValueError("transcription_callback darf nicht None sein")
            if translation_callback is None:
                raise ValueError("translation_callback darf nicht None sein")
            if info_callback is None:
                raise ValueError("info_callback darf nicht None sein")

            if error_callback is not None and callable(error_callback):
                self._error_callback = error_callback
                logger.debug("[PROCESSOR] ✅ error_callback ist gültig")
            else:
                logger.warning(
                    "[PROCESSOR] ⚠️ error_callback ist NICHT aufrufbar – Dummy-Fallback"
                )
                self._error_callback = lambda msg: logger.error(f"[ERROR] {msg}")

            try:
                url = PlatformUtils.sanitize_url(url)
            except Exception as e:
                logger.error(f"[PROCESSOR] ❌ URL-Sanitization fehlgeschlagen: {e}")
                raise ValueError(f"❌ URL-Sanitization fehlgeschlagen: {e}") from e
            if not url:
                raise ValueError("❌ Ungültige URL (nach Sanitization leer)")
            logger.debug(f"[PROCESSOR] ✅ URL validiert: {url[:80]}...")

            with self._state_lock:
                state = self._state
                state_name = state.name if hasattr(state, "name") else str(state)
                logger.debug(f"[PROCESSOR] 📊 Aktueller Zustand: {state_name}")

                if state == self.State.IDLE:
                    logger.debug("[PROCESSOR] ✅ Zustand IDLE – Start möglich")

                elif state in (self.State.PROCESSING, self.State.STARTING):
                    last_setter = getattr(self, "_state_last_set_by", "never_set")
                    logger.warning(
                        f"[PROCESSOR] ⚠️ Zustand {state_name} – erzwinge Reset "
                        f"(letzter Setter: {last_setter}, "
                        f"Thread: {threading.current_thread().name})"
                    )
                    try:
                        self._set_state(
                            self.State.IDLE,
                            force=True,
                            reason="reset_before_start",
                        )
                        self._clear_all_buffers()
                        logger.debug("[PROCESSOR] ✅ Reset auf IDLE durchgeführt")
                    except Exception as e:
                        logger.error(
                            f"[PROCESSOR] ❌ Reset fehlgeschlagen: "
                            f"{type(e).__name__}: {e}",
                            exc_info=True,
                        )
                        self._state = self.State.IDLE
                        self._state_last_set_by = (
                            f"fallback_reset_before_start @ "
                            f"{threading.current_thread().name}"
                        )
                        self._clear_all_buffers()
                        logger.debug(
                            "[PROCESSOR] ✅ Direkter Reset auf IDLE durchgeführt"
                        )

                elif state == self.State.STOPPING:
                    logger.warning(
                        "[PROCESSOR] ⚠️ Verarbeitung wird gestoppt – warte..."
                    )
                    wait_start = time.monotonic()
                    while (
                        self._state == self.State.STOPPING
                        and time.monotonic() - wait_start < 5.0
                    ):
                        time.sleep(0.1)
                    if self._state == self.State.STOPPING:
                        raise RuntimeError("⚠️ Verarbeitung wird weiterhin gestoppt")
                    if self._state == self.State.IDLE:
                        logger.debug("[PROCESSOR] ✅ Nach Wartezeit: Zustand IDLE")
                    else:
                        logger.warning(
                            f"[PROCESSOR] ⚠️ Nach Wartezeit: Zustand "
                            f"{self._state.name} – erzwinge Reset"
                        )
                        self._set_state(
                            self.State.IDLE,
                            force=True,
                            reason="reset_after_stop",
                        )
                        self._clear_all_buffers()

                elif state == self.State.ERROR:
                    logger.debug("[PROCESSOR] State ERROR → IDLE")
                    self._set_state(
                        self.State.IDLE, force=True, reason="reset_from_error"
                    )
                    self._clear_all_buffers()

                else:
                    logger.warning(
                        f"[PROCESSOR] ⚠️ Unbekannter Zustand {state} – erzwinge Reset"
                    )
                    self._set_state(
                        self.State.IDLE,
                        force=True,
                        reason="reset_unknown_state",
                    )
                    self._clear_all_buffers()

                if self._state != self.State.IDLE:
                    logger.error(
                        f"[PROCESSOR] ❌ Zustand nach Reparatur immer noch "
                        f"{self._state.name} – Abbruch"
                    )
                    raise RuntimeError(
                        f"Zustand konnte nicht auf IDLE repariert werden: "
                        f"{self._state.name}"
                    )

            if self._translation_engine is None:
                logger.warning(
                    "[PROCESSOR] Translation engine not set – "
                    "DummyTranslationEngine als Fallback"
                )
                try:
                    self._translation_engine = DummyTranslationEngine(
                        target_lang=self.settings.target_language,
                        settings=self.settings,
                        cache_manager=self._cache_manager,
                    )
                    self._translation_enabled.set()
                    logger.info("✅ DummyTranslationEngine als Fallback aktiviert")
                except Exception as e:
                    raise RuntimeError(
                        f"❌ Übersetzungs-Engine konnte nicht erstellt werden: {e}"
                    ) from e

            logger.debug("[PROCESSOR] Reset all internal buffers and states...")
            self._clear_and_sync_queue()

            with self._buffer_lock:
                self._audio_chunks.clear()
                self._audio_total_bytes = 0
            with self._sentence_lock:
                self._sentence_parts.clear()
                self._sentence_segments.clear()
            with self._transcript_sentence_lock:
                self._transcript_parts.clear()
                self._transcript_segments.clear()
            with self._segment_buffer_lock:
                self._segment_buffer.clear()
                self._next_expected_start = 0.0
            with self._subtitle_lock:
                self._timed_transcriptions.clear()
                self._timed_translations.clear()
            with self._duplicate_lock:
                self._recent_transcriptions.clear()
                self._last_transcription_text = ""
                if hasattr(self, "_already_flushed_texts"):
                    self._already_flushed_texts.clear()
                if hasattr(self, "_flushed_combined_texts"):
                    self._flushed_combined_texts.clear()
            if hasattr(self, "_last_chunk_hashes"):
                self._last_chunk_hashes.clear()
            self._last_chunk_tail = b""
            with self._pending_tasks_cond:
                self._pending_tasks = 0
                self._pending_tasks_cond.notify_all()
            self._synchronize_tasks_done_event()
            with self._transcript_queue_lock:
                self._transcript_queue.clear()
                self._next_expected_transcript_start = 0.0
            with self._translation_queue_lock:
                self._translation_queue.clear()
                self._next_expected_translation_start = 0.0

            self._stop_event.clear()
            self.reset_stop_flag()
            self._current_stream_id = f"stream_{int(time.time())}"
            self._total_file_size = None
            self._expected_duration = None
            self._download_mode_active = False
            self._download_completed_event.clear()
            if hasattr(self, "processing_completed_event"):
                self.processing_completed_event.clear()
            logger.debug(
                f"[PROCESSOR] ✅ Events zurückgesetzt, "
                f"Stream-ID: {self._current_stream_id}"
            )

            with self._stats_lock:
                self._chunk_counter = 0
                self._total_bytes_processed = 0
                self._processed_seconds = 0.0
                self._real_processed_seconds = 0.0
                self._consecutive_timeouts = 0
                self._consecutive_errors = 0
                self._consecutive_successes = 0
                self._low_conf_counter = 0
                self._slow_chunks = 0
                self._last_realtime_factor = 0.0
                self._queue_drop_counter = 0
                self._queue_enqueue_counter = 0
                self._queue_dequeue_counter = 0
                self._consecutive_queue_drops = 0
            logger.debug("[PROCESSOR] ✅ Statistiken zurückgesetzt")

            logger.debug("[PROCESSOR] Apply system optimizations...")
            self._apply_system_optimizations()
            self._init_translation_executor()
            self._init_transcription_executor()
            self._init_transcribe_timeout_executor()
            self._synchronize_tasks_done_event()

            if output_queue is not None:
                self._raw_audio_queue = output_queue
                self._audio_queue = output_queue
                if hasattr(self, "_dispatcher_queue"):
                    self._dispatcher_queue = output_queue
                if hasattr(self, "_queue"):
                    self._queue = output_queue
                logger.debug(
                    f"[PROCESSOR] ✅ _raw_audio_queue auf übergebene Queue "
                    f"gesetzt (ID: {id(output_queue)})"
                )
            elif self._raw_audio_queue is None:
                self._raw_audio_queue = queue.Queue(maxsize=5000)
                logger.debug(
                    f"[PROCESSOR] ✅ Neue _raw_audio_queue erstellt "
                    f"(ID: {id(self._raw_audio_queue)})"
                )
            else:
                logger.debug(
                    f"[PROCESSOR] ✅ _raw_audio_queue bereits vorhanden "
                    f"(ID: {id(self._raw_audio_queue)})"
                )

            if hasattr(self, "_dispatcher") and self._dispatcher is not None:
                try:
                    self._dispatcher._queue = self._raw_audio_queue
                    self._dispatcher._raw_audio_queue = self._raw_audio_queue
                    logger.debug(
                        f"[PROCESSOR] ✅ dispatcher._queue gesetzt "
                        f"(ID: {id(self._raw_audio_queue)})"
                    )
                except Exception as e:
                    logger.warning(
                        f"[PROCESSOR] ❌ dispatcher._queue setzen fehlgeschlagen: {e}"
                    )

            if self._dispatcher_started:
                logger.debug("[PROCESSOR] Stopping old dispatcher...")
                self._stop_dispatcher(clear_queue=True)
            self._clear_and_sync_queue()

            logger.debug("[PROCESSOR] Starting dispatcher...")
            self._start_dispatcher()
            time.sleep(0.05)

            if not self._dispatcher_thread or not self._dispatcher_thread.is_alive():
                logger.error("[PROCESSOR] ❌ Dispatcher konnte nicht gestartet werden")
                raise RuntimeError("❌ Dispatcher konnte nicht gestartet werden")
            logger.debug(
                f"[PROCESSOR] ✅ Dispatcher gestartet und läuft "
                f"(TID: {self._dispatcher_thread.ident})"
            )

            if hasattr(self, "_dispatcher") and self._dispatcher is not None:
                dq = getattr(self._dispatcher, "_queue", None)
                if dq is self._raw_audio_queue:
                    logger.debug(
                        f"[PROCESSOR] ✅ VERIFIZIERT: dispatcher._queue zeigt "
                        f"auf _raw_audio_queue "
                        f"(ID: {id(self._raw_audio_queue)})"
                    )
                else:
                    logger.warning(
                        f"[PROCESSOR] ⚠️ dispatcher._queue "
                        f"({id(dq) if dq else 'None'}) zeigt NICHT auf "
                        f"_raw_audio_queue ({id(self._raw_audio_queue)}) – "
                        f"setze nach"
                    )
                    try:
                        self._dispatcher._queue = self._raw_audio_queue
                        logger.debug("[PROCESSOR] ✅ dispatcher._queue nachgesetzt")
                    except Exception as e:
                        logger.warning(
                            f"[PROCESSOR] ❌ dispatcher._queue nachsetzen "
                            f"fehlgeschlagen: {e}"
                        )

            self._transcription_callback = transcription_callback
            self._translation_callback = translation_callback
            self._info_callback = info_callback
            self._finished_callback = finished_callback
            logger.debug("[PROCESSOR] ✅ Callbacks gespeichert")

            if self._transcription_engine:
                try:
                    with self._transcription_engine._state_lock:
                        self._transcription_engine._last_oom = False
                    self._transcription_engine.reset_fallback_state()
                    logger.debug("[PROCESSOR] ✅ Transcription Engine zurückgesetzt")
                except Exception as e:
                    logger.debug(f"[PROCESSOR] Ignored engine reset error: {e}")

            with self._translation_watchdog_lock:
                self._translation_watchdog_error_count = 0
                self._translation_watchdog_disabled_until = 0.0
            logger.debug("[PROCESSOR] ✅ Translation Watchdog zurückgesetzt")

            new_token = object()
            self._processing_token = new_token
            logger.debug(
                f"[PROCESSOR] 🎫 Neuer Processing-Token gesetzt (ID: {id(new_token)})"
            )

            with self._state_lock:
                current_state = self._state
                current_state_name = (
                    current_state.name
                    if hasattr(current_state, "name")
                    else str(current_state)
                )

                if current_state == self.State.IDLE:
                    self._set_state(self.State.STARTING)
                    logger.debug("[PROCESSOR] State → STARTING")

                elif current_state == self.State.PROCESSING:
                    last_setter = getattr(self, "_state_last_set_by", "never_set")
                    logger.debug(
                        f"[PROCESSOR] ✅ State bereits PROCESSING "
                        f"(gesetzt durch: {last_setter}) – "
                        f"STARTING übersprungen"
                    )

                elif current_state == self.State.ERROR:
                    logger.debug("[PROCESSOR] State ERROR → IDLE → STARTING")
                    self._set_state(
                        self.State.IDLE,
                        force=True,
                        reason="reset_from_error",
                    )
                    self._clear_all_buffers()
                    self._set_state(self.State.STARTING)

                else:
                    last_setter = getattr(self, "_state_last_set_by", "never_set")
                    logger.warning(
                        f"[PROCESSOR] ⚠️ Zustand vor Start: "
                        f"{current_state_name} – warte auf Selbstheilung "
                        f"(letzter Setter: {last_setter}, "
                        f"Thread: {threading.current_thread().name})"
                    )
                    wait_deadline = time.monotonic() + 2.0
                    while (
                        self._state
                        not in (
                            self.State.IDLE,
                            self.State.PROCESSING,
                            self.State.ERROR,
                        )
                        and time.monotonic() < wait_deadline
                    ):
                        time.sleep(0.05)

                    if self._state == self.State.IDLE:
                        self._set_state(self.State.STARTING)
                    elif self._state == self.State.PROCESSING:
                        logger.debug(
                            "[PROCESSOR] ✅ Nach Wartezeit: PROCESSING – "
                            "STARTING übersprungen"
                        )
                    elif self._state == self.State.ERROR:
                        self._set_state(
                            self.State.IDLE,
                            force=True,
                            reason="reset_from_error",
                        )
                        self._clear_all_buffers()
                        self._set_state(self.State.STARTING)
                    else:
                        logger.warning(
                            f"[PROCESSOR] ⚠️ Nach 2 s immer noch "
                            f"{self._state.name} – erzwinge Reset"
                        )
                        self._set_state(
                            self.State.IDLE,
                            force=True,
                            reason="pre_start_reset",
                        )
                        self._clear_all_buffers()
                        self._set_state(self.State.STARTING)

            thread_token = new_token

            def _process_thread() -> None:
                try:
                    logger.debug("[PROCESSOR] Processing thread started")
                    self._process_loop_enhanced(
                        url,
                        self._transcription_callback,
                        self._translation_callback,
                        self._info_callback,
                        self._error_callback,
                        self._finished_callback,
                        **kwargs,
                    )
                except Exception as e:
                    logger.exception(
                        "❌ Unerwartete Exception im Processing-Thread: %s", e
                    )
                    if self._error_callback:
                        self._error_callback(f"Interner Fehler: {e}")
                finally:
                    with self._state_lock:
                        if self._processing_token is thread_token:
                            self._processing_thread = None
                            self._processing_token = None
                            if self._state in (
                                self.State.STARTING,
                                self.State.PROCESSING,
                            ):
                                self._set_state(self.State.IDLE)
                                logger.debug(
                                    "[PROCESSOR] State → IDLE (thread finished)"
                                )
                        else:
                            logger.debug(
                                "[PROCESSOR] Veralteter Thread beendet sich – "
                                "kein State-Update"
                            )
                    self._stop_event.set()
                    logger.debug("[PROCESSOR] Processing thread finished")

            thread = threading.Thread(
                target=_process_thread,
                daemon=True,
                name=f"DW-AudioProc_{self._current_stream_id}",
            )
            self._processing_thread = thread
            thread.start()
            logger.debug(
                f"[PROCESSOR] ✅ Thread '{thread.name}' gestartet (TID: {thread.ident})"
            )

            self._start_debug_monitor()

            with self._state_lock:
                if self._state == self.State.STARTING:
                    self._set_state(self.State.PROCESSING)
                    logger.debug("[PROCESSOR] State → PROCESSING")
                elif self._state == self.State.PROCESSING:
                    logger.debug(
                        "[PROCESSOR] State ist bereits PROCESSING – überspringe"
                    )
                else:
                    current_state_name = (
                        self._state.name
                        if hasattr(self._state, "name")
                        else str(self._state)
                    )
                    logger.warning(
                        f"[PROCESSOR] Unerwarteter Zustand nach "
                        f"Thread-Start: {current_state_name}"
                    )
                    if self._state != self.State.PROCESSING:
                        raise RuntimeError(
                            f"Unerwarteter Zustand {current_state_name} "
                            f"nach Thread-Start"
                        )

            FLUSH_INTERVAL = 1.5

            def _flush() -> None:
                if (
                    self._state == self.State.PROCESSING
                    and not self._stop_event.is_set()
                ):
                    try:
                        self._process_translation_queue(
                            self._translation_callback, force_flush=True
                        )
                    except Exception as e:
                        logger.warning(
                            f"[PROCESSOR] Fehler im Übersetzungs-Flusher: {e}"
                        )
                if (
                    self._state == self.State.PROCESSING
                    and not self._stop_event.is_set()
                ):
                    self._translation_flush_timer = threading.Timer(
                        FLUSH_INTERVAL, _flush
                    )
                    self._translation_flush_timer.daemon = True
                    self._translation_flush_timer.start()

            self._translation_flush_timer = threading.Timer(FLUSH_INTERVAL, _flush)
            self._translation_flush_timer.daemon = True
            self._translation_flush_timer.start()
            logger.debug(
                f"[PROCESSOR] Übersetzungs-Flusher gestartet "
                f"(Intervall: {FLUSH_INTERVAL:.1f} s)"
            )

            elapsed_ms = (time.monotonic() - start_time) * 1000
            logger.info(
                f"[PROCESSOR] ✅ START ABGESCHLOSSEN in {elapsed_ms:.2f}ms | "
                f"Queue-ID: "
                f"{id(self._raw_audio_queue) if self._raw_audio_queue else 'None'} | "
                f"Dispatcher alive: "
                f"{self._dispatcher_thread.is_alive() if self._dispatcher_thread else False}"
            )
            logger.info(f"✅ Processing-Thread gestartet (Init in {elapsed_ms:.2f} ms)")
            return True

        finally:
            with contextlib.suppress(Exception):
                self._start_processing_lock.release()

    def _apply_system_optimizations(self) -> None:
        """ULTIMATIVE MAXIMUM EDITION – Wendet umfassende CPU‑, RAM‑, GPU‑ und System‑Optimierungen an."""
        import logging
        import time

        logger = logging.getLogger("dragon")

        start_time = time.perf_counter()
        log_debug = logger.debug
        log_warning = logger.warning

        log_debug(
            "[SYSOPT] === START _apply_system_optimizations ===",
            extra={"component": "sysopt"},
        )

        try:
            sys_info = self._detect_system_info()
            if not sys_info:
                raise ValueError("System-Info war leer")
        except Exception as e:
            log_warning(
                f"[SYSOPT] System-Info fehlgeschlagen: {e} – verwende Fallback",
                extra={"component": "sysopt"},
            )
            sys_info = self._get_fallback_system_info()

        is_container = self._is_in_container()
        if is_container:
            log_debug(
                "[SYSOPT] Container-Umgebung erkannt – reduziere Ressourcen",
                extra={"component": "sysopt"},
            )

        try:
            gpu_ok, gpu_msg = _check_gpu_health()
            if gpu_ok:
                log_debug(
                    f"[SYSOPT] GPU-Status: {gpu_msg}",
                    extra={"component": "sysopt"},
                )
            else:
                log_warning(
                    f"[SYSOPT] GPU-Probleme: {gpu_msg} – CPU-Modus aktiv",
                    extra={"component": "sysopt"},
                )
                sys_info["device"] = "cpu"
        except NameError:
            log_warning(
                "[SYSOPT] _check_gpu_health nicht definiert – überspringe GPU-Check",
                extra={"component": "sysopt"},
            )
        except Exception as e:
            log_warning(
                f"[SYSOPT] GPU-Health-Check fehlgeschlagen: {e}",
                extra={"component": "sysopt"},
            )

        user_override_chunk = (
            hasattr(self, "_chunk_duration_override")
            and self._chunk_duration_override is not None
        )
        user_override_workers = (
            hasattr(self, "_workers_override") and self._workers_override is not None
        )
        user_override_cache = (
            hasattr(self, "_cache_override") and self._cache_override is not None
        )

        config = self._compute_optimized_config(sys_info, is_container)

        if user_override_chunk:
            config["_chunk_duration"] = self._chunk_duration_override
            log_debug(
                "[SYSOPT] Benutzer-Override für Chunk-Dauer angewendet",
                extra={"component": "sysopt"},
            )
        if user_override_workers:
            config["_transcription_workers"] = self._workers_override
            config["_translation_workers"] = max(1, self._workers_override // 2)
            log_debug(
                "[SYSOPT] Benutzer-Override für Worker angewendet",
                extra={"component": "sysopt"},
            )
        if user_override_cache:
            log_debug(
                "[SYSOPT] Benutzer-Override für Cache erkannt – überspringe Cache-Optimierung",
                extra={"component": "sysopt"},
            )

        self._apply_config_safely(config)
        self._validate_final_config()

        try:
            self._save_settings()
        except Exception as e:
            log_warning(
                f"[SYSOPT] Speichern der Einstellungen fehlgeschlagen: {e}",
                extra={"component": "sysopt"},
            )

        elapsed_ms = (time.perf_counter() - start_time) * 1000
        log_debug(
            f"[SYSOPT] Optimierung abgeschlossen in {elapsed_ms:.2f}ms",
            extra={"component": "sysopt"},
        )

        self._log_optimization_summary()

        log_debug(
            "[SYSOPT] === END _apply_system_optimizations ===",
            extra={"component": "sysopt"},
        )

    def _get_fallback_system_info(self) -> dict:
        """Sicherer Fallback, falls System-Info nicht verfügbar."""
        return {
            "total_ram_gb": 8.0,
            "available_ram_gb": 4.0,
            "cpu_count": 4,
            "cpu_percent": 10.0,
            "device": "cpu",
            "gpu_name": "Unknown",
            "gpu_mem_total": 0.0,
            "gpu_mem_free": 0.0,
            "is_linux": True,
            "is_macos": False,
            "is_windows": False,
            "is_arm": False,
            "is_x86": True,
        }

    def _is_in_container(self) -> bool:
        """Prüft, ob das Skript in einem Container (Docker/Kubernetes) läuft."""
        import os

        try:
            if os.path.exists("/.dockerenv"):
                return True
            with open("/proc/1/cgroup") as f:
                content = f.read()
                return "docker" in content or "kubepods" in content
        except Exception:
            return False

    def _get_cache_sizes(self, available_ram_gb: float) -> dict:
        """Zentrale Cache-Größen-Berechnung basierend auf RAM."""
        if available_ram_gb < 4:
            return {"transcription": 200, "translation": 300, "audio": 64}
        if available_ram_gb < 8:
            return {"transcription": 300, "translation": 500, "audio": 128}
        return {"transcription": 400, "translation": 800, "audio": 200}

    def _compute_optimized_config(self, sys_info: dict, is_container: bool) -> dict:
        """Berechnet alle Optimierungswerte zentral anhand der System-Info."""
        ram = sys_info.get("available_ram_gb", 8.0)
        is_gpu = sys_info.get("device") == "cuda"
        cpu = sys_info.get("cpu_count", 4)

        if ram < 4:
            duration = 8.0
        elif ram < 8:
            duration = 10.0
        else:
            duration = 12.0
        if is_container:
            duration = min(duration, 10.0)

        if is_gpu:
            trans_workers = min(4, max(2, cpu // 4))
        else:
            trans_workers = max(1, cpu // 6)
        if is_container:
            trans_workers = min(trans_workers, 2)

        trans_late_workers = 1 if ram < 4 else 2
        if is_container:
            trans_late_workers = min(trans_late_workers, 1)

        cache = self._get_cache_sizes(ram)

        max_pending = 1000 if ram < 8 else 1500
        if is_container:
            max_pending = int(max_pending * 0.6)

        beam = 5 if is_gpu else 3
        best_of = 5 if is_gpu else 3

        memory_limit = 2048 if ram > 8 else 1024
        gc_interval = 30 if ram > 8 else 15

        return {
            "_chunk_duration": duration,
            "_adaptive_bytes_per_sec": 32000,
            "_transcription_workers": trans_workers,
            "_translation_workers": trans_late_workers,
            "_transcription_cache_size": cache["transcription"],
            "_translation_cache_size": cache["translation"],
            "_audio_cache_size": cache["audio"],
            "_max_pending_tasks": max_pending,
            "_beam_size": beam,
            "_best_of": best_of,
            "_vad_enabled": True,
            "_audio_enhancement_enabled": True,
            "_buffer_size": 937 * 1024,
            "_memory_limit_mb": memory_limit,
            "_gc_interval": gc_interval,
        }

    def _apply_config_safely(self, config: dict) -> None:
        """Wendet ein Konfigurations-Dictionary sicher an (mit try/except)."""
        import logging

        logger = logging.getLogger("dragon")
        for key, value in config.items():
            try:
                setattr(self, key, value)
            except Exception as e:
                logger.warning(
                    f"[SYSOPT] Konnte {key} nicht setzen: {e}",
                    extra={"component": "sysopt"},
                )

    def _validate_final_config(self) -> None:
        """Prüft und korrigiert die finalen Werte auf Plausibilität."""
        adaptive = getattr(self, "_adaptive_bytes_per_sec", 32000)
        if adaptive < 16000:
            self._adaptive_bytes_per_sec = 32000

        chunk_dur = getattr(self, "_chunk_duration", 10.0)
        if chunk_dur < 2.0:
            self._chunk_duration = 5.0

        beam = getattr(self, "_beam_size", 5)
        if not (1 <= beam <= 20):
            self._beam_size = 5

        best = getattr(self, "_best_of", 5)
        if best < 1 or best > 20:
            self._best_of = 5

        trans_w = getattr(self, "_transcription_workers", 2)
        if trans_w < 1:
            self._transcription_workers = 2

        transl_w = getattr(self, "_translation_workers", 1)
        if transl_w < 1:
            self._translation_workers = 1

    def _log_optimization_summary(self) -> None:
        """Gibt eine strukturierte Zusammenfassung der optimierten Werte aus."""
        import logging

        log = logging.getLogger("dragon").debug
        log(
            "[SYSOPT] === OPTIMIERUNGSZUSAMMENFASSUNG ===",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Chunk-Dauer: {getattr(self, '_chunk_duration', 10.0):.1f}s",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Bytes/Sekunde: {getattr(self, '_adaptive_bytes_per_sec', 32000)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Transkription-Worker: {getattr(self, '_transcription_workers', 2)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Übersetzungs-Worker: {getattr(self, '_translation_workers', 1)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • MAX_PENDING_TASKS: {getattr(self, '_max_pending_tasks', 1000)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Beam-Size: {getattr(self, '_beam_size', 5)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Cache-Größen: T={getattr(self, '_transcription_cache_size', 300)}, "
            f"Tr={getattr(self, '_translation_cache_size', 500)}, "
            f"A={getattr(self, '_audio_cache_size', 128)}",
            extra={"component": "sysopt"},
        )
        log(
            f"  • Memory-Limit: {getattr(self, '_memory_limit_mb', 2048)}MB",
            extra={"component": "sysopt"},
        )
        log(
            f"  • GC-Intervall: {getattr(self, '_gc_interval', 30)}s",
            extra={"component": "sysopt"},
        )

    def _safe_optimize(self, name: str, func, *args, default=None, **kwargs):
        """Sicherer Wrapper für Optimierungsmethoden."""
        try:
            return func(*args, **kwargs)
        except AttributeError:
            if self.debug_level >= 3:
                self._safe_log_debug(
                    f"[SYSOPT] Methode {name} nicht gefunden – überspringe",
                )
            return default
        except Exception as e:
            self._safe_log_warning(f"[SYSOPT] {name} fehlgeschlagen: {e}")
            return default

    def _detect_system_info(self) -> dict:
        """Ermittelt alle relevanten System‑ und Hardware‑Informationen."""
        import os
        import platform
        import time

        logger = logging.getLogger("dragon")
        log_debug = logger.debug

        cache_key = "_system_info_cache"
        if hasattr(self, cache_key) and getattr(self, cache_key) is not None:
            cache_time = getattr(self, "_system_info_cache_time", 0)
            if time.time() - cache_time < 5.0:
                log_debug("[SYSOPT] System-Info aus Cache geladen")
                return getattr(self, cache_key)

        system = platform.system()
        machine = platform.machine().lower()

        is_linux = system == "Linux"
        is_macos = system == "Darwin"
        is_windows = system == "Windows"
        is_arm = machine in ("arm64", "aarch64")
        is_x86 = not is_arm

        try:
            import psutil

            mem = psutil.virtual_memory()
            total_ram_gb = mem.total / (1024**3)
            available_ram_gb = mem.available / (1024**3)
            cpu_count = os.cpu_count() or 1
            cpu_percent = psutil.cpu_percent(interval=0.1)
        except ImportError:
            log_debug("[SYSOPT] psutil nicht verfügbar – verwende Fallback")
            total_ram_gb = 8.0
            available_ram_gb = 4.0
            cpu_count = os.cpu_count() or 4
            cpu_percent = 50.0
        except Exception as e:
            log_debug(f"[SYSOPT] psutil Fehler: {e} – verwende Fallback")
            total_ram_gb = 8.0
            available_ram_gb = 4.0
            cpu_count = os.cpu_count() or 4
            cpu_percent = 50.0

        gpu_name = "CPU"
        device = "cpu"
        gpu_mem_total = 0.0
        gpu_mem_free = 0.0
        has_cuda = False
        has_mps = False

        try:
            import torch

            if hasattr(torch, "cuda") and torch.cuda.is_available():
                has_cuda = True
                device = "cuda"
                gpu_name = torch.cuda.get_device_name(0)
                gpu_mem_total = torch.cuda.get_device_properties(0).total_memory / (
                    1024**3
                )

                gpu_mem_free = self._get_free_vram_gb()
                if gpu_mem_free is None:
                    allocated = torch.cuda.memory_allocated(0) / (1024**3)
                    gpu_mem_free = gpu_mem_total - allocated
        except ImportError:
            pass
        except Exception as e:
            log_debug(f"[SYSOPT] CUDA-Erkennung fehlgeschlagen: {e}")

        if not has_cuda:
            try:
                import torch

                if hasattr(torch, "backends") and hasattr(torch.backends, "mps"):
                    if torch.backends.mps.is_available():
                        has_mps = True
                        device = "mps"
                        gpu_name = "Apple MPS"
                        gpu_mem_total = total_ram_gb * 0.6
                        gpu_mem_free = gpu_mem_total
            except ImportError:
                pass
            except Exception as e:
                log_debug(f"[SYSOPT] MPS-Erkennung fehlgeschlagen: {e}")

        is_wsl = False
        if is_linux:
            try:
                with open("/proc/version") as f:
                    is_wsl = "microsoft" in f.read().lower()
            except Exception:
                pass

        sys_info = {
            "total_ram_gb": total_ram_gb,
            "available_ram_gb": available_ram_gb,
            "cpu_count": cpu_count,
            "cpu_percent": cpu_percent,
            "is_linux": is_linux,
            "is_macos": is_macos,
            "is_windows": is_windows,
            "is_wsl": is_wsl,
            "is_arm": is_arm,
            "is_x86": is_x86,
            "device": device,
            "gpu_name": gpu_name,
            "gpu_mem_total": gpu_mem_total,
            "gpu_mem_free": gpu_mem_free,
            "has_cuda": has_cuda,
            "has_mps": has_mps,
        }
        setattr(self, cache_key, sys_info)
        self._system_info_cache_time = time.time()
        log_debug(
            f"[SYSOPT] System-Info erkannt: device={device}, ram={total_ram_gb:.1f}GB, cpu={cpu_count} Kerne",
        )
        if has_cuda:
            log_debug(
                f"[SYSOPT] GPU: {gpu_name} ({gpu_mem_total:.1f}GB, frei={gpu_mem_free:.1f}GB)",
            )
        return sys_info

    def _get_free_vram_gb(self) -> float | None:
        """Ermittelt den freien VRAM mit pynvml (genauer als torch.cuda.memory_allocated)."""
        if not hasattr(self, "_nvml_handle"):
            try:
                import pynvml

                pynvml.nvmlInit()
                self._nvml_handle = pynvml.nvmlDeviceGetHandleByIndex(0)
                self._nvml = pynvml
                if hasattr(self, "_debug_level") and self._debug_level >= 4:
                    logger = logging.getLogger("dragon")
                    logger.debug("✅ pynvml initialisiert – VRAM-Abfrage verfügbar")
            except ImportError:
                self._nvml = None
                self._nvml_handle = None
                if hasattr(self, "_debug_level") and self._debug_level >= 3:
                    logger = logging.getLogger("dragon")
                    logger.debug(
                        "⚠️ pynvml nicht installiert – VRAM-Abfrage deaktiviert",
                    )
            except Exception as e:
                self._nvml = None
                self._nvml_handle = None
                logger = logging.getLogger("dragon")
                logger.debug(f"⚠️ pynvml-Initialisierung fehlgeschlagen: {e}")

        if self._nvml is None or self._nvml_handle is None:
            return None
        try:
            info = self._nvml.nvmlDeviceGetMemoryInfo(self._nvml_handle)
            free_gb = info.free / (1024**3)
            if hasattr(self, "_debug_level") and self._debug_level >= 5:
                logger = logging.getLogger("dragon")
                logger.debug(f"🖥️ Freier VRAM: {free_gb:.2f} GB")
            return free_gb
        except Exception as e:
            logger = logging.getLogger("dragon")
            logger.debug(f"⚠️ VRAM-Abfrage fehlgeschlagen: {e}")
            return None

    def _optimize_chunk_duration(self, sys_info: dict) -> None:
        """Passt die Chunk‑Dauer und die Bytes/Sekunde an die Hardware und den Betriebsmodus an."""
        import logging

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_info = logger.info
        log_warning = logger.warning
        log_error = logger.error

        device = sys_info.get("device", "cpu")
        total_ram = sys_info.get("total_ram_gb", 8.0)
        cpu_percent = sys_info.get("cpu_percent", 50.0)
        is_gpu = device != "cpu"
        is_high_ram = total_ram >= 16.0
        is_medium_ram = 8.0 <= total_ram < 16.0
        is_subtitle = getattr(self, "subtitle_mode", False)
        is_live = getattr(self, "_is_live", None)

        if is_subtitle:
            base_duration = 3.0
            reason = "Subtitle‑Mode"
        elif is_gpu and is_high_ram:
            base_duration = 10.0
            reason = "GPU + High‑RAM"
        elif is_gpu and is_medium_ram:
            base_duration = 8.0
            reason = "GPU + Medium‑RAM"
        elif is_gpu:
            base_duration = 6.0
            reason = "GPU + Low‑RAM"
        elif is_high_ram:
            base_duration = 6.0
            reason = "CPU + High‑RAM"
        elif is_medium_ram:
            base_duration = 4.0
            reason = "CPU + Medium‑RAM"
        else:
            base_duration = 3.0
            reason = "CPU + Low‑RAM"

        if cpu_percent > 80:
            base_duration = max(2.0, base_duration * 0.8)
            reason += f" (CPU {cpu_percent:.0f}% → reduziert)"
        elif cpu_percent > 60:
            base_duration = max(2.0, base_duration * 0.9)
            reason += f" (CPU {cpu_percent:.0f}% → leicht reduziert)"

        if is_live is False:
            base_duration = min(15.0, base_duration + 3.0)
            reason += " (VOD‑Modus → +3s)"
        elif is_live is True:
            base_duration = max(2.0, base_duration - 1.0)
            reason += " (Live‑Modus → -1s)"

        max_duration = max(2.0, min(15.0, base_duration))

        if hasattr(self, "settings") and self.settings is not None:
            try:
                bytes_per_sec = self.settings.config.BYTES_PER_SECOND
            except Exception:
                bytes_per_sec = 32000
        else:
            bytes_per_sec = 32000

        if bytes_per_sec <= 0:
            bytes_per_sec = 32000
            log_warning("[SYSOPT] bytes_per_sec war <= 0 – korrigiere auf 32000")

        try:
            current = getattr(self.settings.config, "CHUNK_DURATION", 5.0)
            if abs(max_duration - current) > 0.1:
                self.set_chunk_duration(max_duration, force=True)
                log_info(
                    f"⚙️ Chunk-Dauer optimiert: {current:.1f}s → {max_duration:.1f}s "
                    f"(Grund: {reason})",
                )
            else:
                log_debug(f"[SYSOPT] Chunk-Dauer bleibt unverändert ({current:.1f}s)")

            if hasattr(self, "_adaptive_bytes_per_sec"):
                if self._adaptive_bytes_per_sec != bytes_per_sec:
                    log_debug(
                        f"[SYSOPT] _adaptive_bytes_per_sec: {self._adaptive_bytes_per_sec} → {bytes_per_sec}",
                    )
                    self._adaptive_bytes_per_sec = bytes_per_sec
            else:
                self._adaptive_bytes_per_sec = bytes_per_sec
                log_debug(
                    f"[SYSOPT] _adaptive_bytes_per_sec auf {bytes_per_sec} gesetzt",
                )

        except AttributeError as e:
            log_error(f"[SYSOPT] set_chunk_duration nicht verfügbar: {e}")
            if hasattr(self, "_chunk_duration"):
                self._chunk_duration = max_duration
            if hasattr(self, "_adaptive_bytes_per_sec"):
                self._adaptive_bytes_per_sec = bytes_per_sec
            log_warning(
                "[SYSOPT] Fallback: chunk_duration und adaptive_bytes_per_sec direkt gesetzt",
            )

        except Exception as e:
            log_error(f"[SYSOPT] Fehler beim Setzen der Chunk-Dauer: {e}")
            self._chunk_duration = max(
                2.0,
                min(15.0, getattr(self, "_chunk_duration", 10.0)),
            )
            self._adaptive_bytes_per_sec = 32000
            log_warning(
                "[SYSOPT] Notfall-Fallback: chunk_duration=%.1f, adaptive_bytes_per_sec=32000",
                self._chunk_duration,
            )

        if DEBUG_LEVEL >= 3:
            log_debug(
                f"[SYSOPT] Chunk-Berechnung: device={device}, ram={total_ram:.1f}GB, "
                f"cpu={cpu_percent:.1f}%, subtitle={is_subtitle}, live={is_live}, "
                f"result={max_duration:.1f}s, bytes_per_sec={bytes_per_sec} (Grund: {reason})",
            )

    def _optimize_workers(self, sys_info: dict) -> None:
        """Passt die Anzahl der Transkriptions‑Worker an."""
        if not hasattr(self, "_transcription_executor"):
            return
        device = sys_info["device"]
        cpu_count = sys_info["cpu_count"]
        total_ram = sys_info["total_ram_gb"]
        cpu_percent = sys_info["cpu_percent"]
        is_gpu = device != "cpu"

        if is_gpu and total_ram >= 16.0:
            new_workers = min(cpu_count // 2, 4)
        elif is_gpu and total_ram >= 8.0:
            new_workers = min(cpu_count // 2, 2)
        else:
            new_workers = 1

        if cpu_percent > 70 and new_workers > 1:
            new_workers = max(1, new_workers - 1)

        current = getattr(self._transcription_executor, "_max_workers", 1)
        if current != new_workers:
            self._set_transcription_workers(new_workers)
            logger.info(f"⚙️ Worker angepasst: {current} → {new_workers}")
        else:
            logger.debug("[SYSOPT] Worker bereits optimal")

    def _optimize_vad(self, sys_info: dict) -> None:
        """Aktiviert/deaktiviert VAD basierend auf Hardware."""
        device = sys_info["device"]
        is_gpu = device != "cpu"
        if is_gpu:
            if not self.settings.vad_filter:
                self.settings.vad_filter = True
                logger.info("⚙️ VAD aktiviert (GPU verfügbar)")
            if hasattr(self, "vad_threshold") and self.vad_threshold < 0.3:
                self.vad_threshold = 0.35
                logger.debug("[SYSOPT] VAD-Schwellwert auf 0.35 erhöht")
        elif self.settings.vad_filter:
            self.settings.vad_filter = False
            logger.info("⚙️ VAD deaktiviert (CPU-Modus)")

    def _optimize_audio_enhancement(self, sys_info: dict) -> None:
        """Aktiviert/deaktiviert Audio‑Enhancement."""
        device = sys_info["device"]
        total_ram = sys_info["total_ram_gb"]
        is_gpu = device != "cpu"
        is_high_ram = total_ram >= 16.0

        if is_gpu and is_high_ram:
            if not self.settings.enable_audio_enhancement:
                self.settings.enable_audio_enhancement = True
                try:
                    self._audio_enhancer = AudioEnhancer(
                        start_boost_threshold=0.05,
                        start_boost_gain=3.0,
                        noisereduce_interval=10,
                        highpass=True,
                        device=device,
                    )
                    logger.info("⚙️ Audio-Enhancement aktiviert (GPU/High-RAM)")
                except Exception as e:
                    logger.warning(
                        f"[SYSOPT] AudioEnhancer konnte nicht initialisiert werden: {e}",
                    )
        elif self.settings.enable_audio_enhancement:
            self.settings.enable_audio_enhancement = False
            self._audio_enhancer = None
            logger.info("⚙️ Audio-Enhancement deaktiviert (CPU/Low-RAM)")

    def _optimize_buffer(self, sys_info: dict) -> None:
        """Passt die Puffergröße für Audio‑Chunks an."""
        device = sys_info["device"]
        total_ram = sys_info["total_ram_gb"]
        is_gpu = device != "cpu"
        is_high_ram = total_ram >= 16.0
        is_low_ram = total_ram < 8.0

        if is_high_ram and is_gpu:
            new_buffer = min(self._max_buffer_bytes, 32 * 1024 * 1024)
        elif not is_low_ram:
            new_buffer = min(self._max_buffer_bytes, 16 * 1024 * 1024)
        else:
            new_buffer = min(self._max_buffer_bytes, 4 * 1024 * 1024)

        old = self._max_buffer_bytes
        if new_buffer != old:
            self._max_buffer_bytes = new_buffer
            logger.info(
                f"⚙️ Puffergröße angepasst: {old // 1024} KB → {new_buffer // 1024} KB",
            )
        else:
            logger.debug("[SYSOPT] Puffergröße bleibt unverändert")

    def _optimize_caches(self, sys_info: dict) -> None:
        """Passt Cache‑Größen an (doppelt bei GPU+High‑RAM, halbiert bei CPU/Low‑RAM)."""
        if not hasattr(self, "_cache_manager") or self._cache_manager is None:
            return
        is_gpu = sys_info["device"] != "cpu"
        is_high_ram = sys_info["total_ram_gb"] >= 16.0
        is_low_ram = sys_info["total_ram_gb"] < 8.0

        if is_gpu and is_high_ram:
            factor = 2.0
        elif is_low_ram or not is_gpu:
            factor = 0.5
        else:
            factor = 1.0

        if factor == 1.0:
            return

        cm = self._cache_manager
        for cache_name in (
            "transcription_cache",
            "translation_cache",
            "audio_cache",
            "generic_cache",
        ):
            cache = getattr(cm, cache_name, None)
            if cache and hasattr(cache, "maxsize"):
                old = cache.maxsize
                new = int(max(30, old * factor))
                if new != old:
                    cache.maxsize = new
                    logger.debug(f"[SYSOPT] Cache {cache_name}: {old} → {new}")
        logger.info(
            f"⚙️ Cache-Größen {'vergrößert' if factor > 1 else 'halbiert'} (Faktor {factor:.1f})",
        )

    def _optimize_whisper_params(self, sys_info: dict) -> None:
        """Optimiert Whisper‑Parameter (Beam, Temperature, etc.)."""
        engine = self._transcription_engine
        if engine is None or not hasattr(engine, "settings"):
            return
        settings = engine.settings
        device = sys_info["device"]
        is_gpu = device != "cpu"
        has_high_gpu = sys_info["gpu_mem_total"] >= 8.0 if is_gpu else False

        params = {}
        if is_gpu and has_high_gpu:
            params = {
                "beam_size": 10,
                "best_of": 5,
                "temperature": 0.1,
                "patience": 1.5,
                "condition_on_previous_text": True,
            }
        elif is_gpu:
            params = {
                "beam_size": 5,
                "best_of": 3,
                "temperature": 0.1,
                "patience": 1.2,
                "condition_on_previous_text": True,
            }
        else:
            params = {
                "beam_size": 3,
                "best_of": 1,
                "temperature": 0.0,
                "patience": 0.8,
                "condition_on_previous_text": False,
            }

        changed = False
        for key, value in params.items():
            if hasattr(settings, key):
                old = getattr(settings, key)
                if old != value:
                    setattr(settings, key, value)
                    logger.debug(f"[SYSOPT] {key}: {old} → {value} ({device.upper()})")
                    changed = True
        if changed:
            logger.info("⚙️ Whisper-Parameter optimiert")
        else:
            logger.debug("[SYSOPT] Whisper-Parameter bereits optimal")

    def _optimize_pending_tasks(self, sys_info: dict) -> None:
        """Setzt das Limit für ausstehende Transkriptions‑Tasks."""
        is_gpu = sys_info["device"] != "cpu"
        is_low_ram = sys_info["total_ram_gb"] < 8.0

        if is_gpu and not is_low_ram:
            new_limit = None
            self._max_pending_tasks_cpu = None
            logger.info("⚙️ Max. Pending Tasks: unbegrenzt (GPU/High-RAM)")
        else:
            new_limit = 30 if not is_gpu else 20
            if self._max_pending_tasks_cpu != new_limit:
                self._max_pending_tasks_cpu = new_limit
                logger.info(f"⚙️ Max. Pending Tasks auf {new_limit} begrenzt")

    def _optimize_os(self, sys_info: dict) -> None:
        """Setzt nice‑ und ionice‑Werte unter Linux."""
        if not sys_info["is_linux"]:
            return
        import os
        import subprocess

        is_cpu = sys_info["device"] == "cpu"
        current_nice = os.nice(0)

        if is_cpu:
            if current_nice < 10:
                os.nice(10)
                logger.debug(
                    f"[SYSOPT] Nice-Level erhöht: {current_nice} → 10 (CPU-Modus)",
                )
        elif current_nice > 0:
            os.nice(-current_nice)
            logger.debug("[SYSOPT] Nice-Level zurückgesetzt auf 0 (GPU-Modus)")

        try:
            if is_cpu:
                subprocess.run(
                    ["ionice", "-c", "2", "-n", "7", "-p", str(os.getpid())],
                    check=False,
                    capture_output=True,
                )
                logger.debug(
                    "[SYSOPT] I/O-Priorität auf Best-Effort (Klasse 2, Level 7) gesetzt",
                )
        except Exception:
            pass

    def _optimize_torch(self, sys_info: dict) -> None:
        """Optimiert Torch‑Threads und CuDNN."""
        import torch

        device = sys_info["device"]
        cpu_count = sys_info["cpu_count"]
        is_gpu = device != "cpu"

        if is_gpu and sys_info["has_cuda"]:
            if hasattr(torch.backends.cudnn, "benchmark"):
                torch.backends.cudnn.benchmark = True
                logger.debug("[SYSOPT] CuDNN Benchmark aktiviert")
            if hasattr(torch.backends.cudnn, "deterministic"):
                torch.backends.cudnn.deterministic = False
                logger.debug("[SYSOPT] CuDNN deterministic deaktiviert")
            torch.set_num_threads(min(cpu_count, 4))
            logger.debug(f"[SYSOPT] Torch-Threads auf {min(cpu_count, 4)} gesetzt")
        else:
            torch.set_num_threads(min(cpu_count, 8))
            logger.debug(f"[SYSOPT] Torch-Threads auf {min(cpu_count, 8)} gesetzt")
            if hasattr(torch, "set_num_interop_threads"):
                torch.set_num_interop_threads(1)
                logger.debug("[SYSOPT] Torch Inter-Op-Threads auf 1 gesetzt")

    def _optimize_env(self, sys_info: dict) -> None:
        """Setzt Umgebungsvariablen für OpenMP und MKL."""
        import logging
        import os

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 3:
            logger.debug("[SYSOPT] _optimize_env aufgerufen")

        cpu_count = sys_info.get("cpu_count", 1)
        device = sys_info.get("device", "unknown")

        if debug_level >= 4:
            logger.debug(f"[SYSOPT] System: cpu_count={cpu_count}, device={device}")

        is_cpu = device == "cpu"

        if is_cpu:
            threads = min(cpu_count, 4)
        else:
            threads = min(cpu_count, 2)

        if threads < 1:
            threads = 1
            logger.warning("[SYSOPT] threads war 0 – setze auf 1")

        try:
            current_omp = os.environ.get("OMP_NUM_THREADS")
            current_mkl = os.environ.get("MKL_NUM_THREADS")

            os.environ["OMP_NUM_THREADS"] = str(threads)
            os.environ["MKL_NUM_THREADS"] = str(threads)

            if debug_level >= 3:
                logger.debug(
                    f"[SYSOPT] Threads gesetzt: OMP_NUM_THREADS={threads} "
                    f"(vorher: {current_omp}), MKL_NUM_THREADS={threads} "
                    f"(vorher: {current_mkl})",
                )

        except Exception as e:
            logger.error(f"[SYSOPT] ❌ Fehler beim Setzen der Umgebungsvariablen: {e}")

    def _optimize_gc(self) -> dict[str, int]:
        """Führt Garbage Collection durch und gibt Statistiken zurück.

        Returns:
            Ein Dictionary mit GC‑Statistiken (collected, uncollectable, etc.).

        """
        import gc
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 3:
            logger.debug("[SYSOPT] _optimize_gc aufgerufen")

        gc_stats_before = {
            "collected": gc.get_count()[0] if hasattr(gc, "get_count") else 0,
            "thresholds": (
                gc.get_threshold() if hasattr(gc, "get_threshold") else (0, 0, 0)
            ),
        }

        try:
            collected = gc.collect()
            uncollectable = len(gc.garbage) if hasattr(gc, "garbage") else 0

            if debug_level >= 3:
                logger.debug(
                    f"[SYSOPT] Garbage Collection durchgeführt: {collected} Objekte gesammelt, "
                    f"{uncollectable} unerreichbar",
                )

            gc_stats_after = {
                "collected": gc.get_count()[0] if hasattr(gc, "get_count") else 0,
                "thresholds": (
                    gc.get_threshold() if hasattr(gc, "get_threshold") else (0, 0, 0)
                ),
            }

            return {
                "collected": collected,
                "uncollectable": uncollectable,
                "stats_before": gc_stats_before,
                "stats_after": gc_stats_after,
            }

        except Exception as e:
            logger.error(
                f"[SYSOPT] ❌ Fehler bei Garbage Collection: {e}",
                exc_info=True,
            )
            return {
                "collected": -1,
                "uncollectable": -1,
                "error": str(e),
            }

    def _save_settings(self) -> bool:
        """Speichert die aktualisierten Einstellungen in die Konfigurationsdatei."""
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 3:
            logger.debug("[SYSOPT] _save_settings aufgerufen")

        try:
            if not hasattr(self, "settings") or self.settings is None:
                logger.warning("[SYSOPT] ⚠️ Keine Settings zum Speichern vorhanden")
                return False

            if hasattr(self.settings, "_backup_file"):
                try:
                    self.settings._backup_file()
                    if debug_level >= 4:
                        logger.debug("[SYSOPT] ✅ Backup der Einstellungen erstellt")
                except Exception as e:
                    logger.warning(f"[SYSOPT] ⚠️ Backup fehlgeschlagen: {e}")

            if hasattr(self.settings, "save_to_file"):
                self.settings.save_to_file()
                if debug_level >= 3:
                    logger.debug("[SYSOPT] ✅ Einstellungen erfolgreich gespeichert")
                return True
            logger.warning("[SYSOPT] ⚠️ settings hat kein save_to_file")
            return False

        except Exception as e:
            logger.error(
                f"[SYSOPT] ❌ Speichern der Einstellungen fehlgeschlagen: {e}",
                exc_info=True,
            )
            return False

    def _reset_all_buffers(self) -> None:
        """Zentrale Methode zum Zurücksetzen aller Puffer, Caches und temporären Daten.
        Ersetzt _guaranteed_cleanup und _clear_all_buffers.
        """
        self._clear_and_sync_queue()

        with self._buffer_lock:
            self._audio_chunks.clear()
            self._audio_total_bytes = 0
        with self._sentence_lock:
            self._sentence_parts.clear()
            self._sentence_segments.clear()
        with self._transcript_sentence_lock:
            self._transcript_parts.clear()
            self._transcript_segments.clear()
        with self._segment_buffer_lock:
            self._segment_buffer.clear()
            self._next_expected_start = 0.0
        with self._subtitle_lock:
            self._timed_transcriptions.clear()
            self._timed_translations.clear()
        with self._duplicate_lock:
            self._recent_transcriptions.clear()
            self._last_transcription_text = ""
            if hasattr(self, "_already_flushed_texts"):
                self._already_flushed_texts.clear()
            if hasattr(self, "_flushed_combined_texts"):
                self._flushed_combined_texts.clear()
        if hasattr(self, "_last_chunk_hashes"):
            self._last_chunk_hashes.clear()
        self._last_chunk_tail = b""

        with self._pending_tasks_cond:
            self._pending_tasks = 0
            self._pending_tasks_cond.notify_all()
        self._synchronize_tasks_done_event()

        with self._transcript_queue_lock:
            self._transcript_queue.clear()
            self._next_expected_transcript_start = 0.0
        with self._translation_queue_lock:
            self._translation_queue.clear()
            self._next_expected_translation_start = 0.0

        self._stop_event.clear()
        logger.debug("Alle Puffer und Caches zurückgesetzt")

    def reset_stop_flag(self) -> None:
        """Löscht das Stop‑Event und sorgt dafür, dass mehrere abhängige
        Events und Flags ebenfalls zurückgesetzt werden, damit ein
        sauberer Neustart möglich ist.
        """
        self._stop_event.clear()

        if hasattr(self, "_debug_monitor_stop_event"):
            self._debug_monitor_stop_event.clear()

        if hasattr(self, "processing_completed_event"):
            try:
                self.processing_completed_event.clear()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
        if hasattr(self, "_download_completed_event"):
            try:
                self._download_completed_event.clear()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        if hasattr(self, "_shutting_down"):
            self._shutting_down = False

        if DEBUG_LEVEL >= 4:
            log_debug("processor", "reset_stop_flag: all events cleared")

    def is_processing(self) -> bool:
        """Gibt ``True`` zurück, wenn der AudioProcessor aktiv im Zustand ``PROCESSING`` ist
        und kein Shutdown eingeleitet wurde.
        """
        if not hasattr(self, "_state"):
            return False
        if self._state != AudioProcessor.State.PROCESSING:
            return False
        return not getattr(self, "_shutting_down", False)

    def is_stop_requested(self) -> bool:
        """Prüft zuverlässig, ob die Verarbeitung gestoppt werden soll."""
        if self._stop_event.is_set():
            return True

        if getattr(self, "_shutting_down", False):
            return True
        if getattr(self, "_disposed", False):
            return True

        ext = getattr(self, "_external_cancel_event", None)
        return bool(ext is not None and ext.is_set())

    def stop_processing(
        self,
        wait: bool = False,
        timeout: float = 5.0,
        backup_queue: bool = False,
        force: bool = False,
    ) -> bool:
        """Stoppt die laufende Audioverarbeitung – optimiert für sofortigen Abbruch."""
        import contextlib
        import logging
        import threading
        import time

        logger = getattr(self, "_logger", None)
        if logger is None:
            logger = logging.getLogger("dragon")

        debug_level = getattr(self, "debug_level", DEBUG_LEVEL)
        _start_t0 = time.perf_counter()

        diag: dict = {
            "success": False,
            "already_idle": False,
            "skip_in_progress": False,
            "force": bool(force),
            "wait": bool(wait),
            "backup_queue": bool(backup_queue),
            "state_before": None,
            "state_after": None,
            "token_before": None,
            "token_after": None,
            "token_invalidated": False,
            "stop_event_set": False,
            "cancel_event_set": False,
            "shutdown_impl_called": None,
            "total_ms": 0.0,
            "errors": [],
        }

        def _finalize() -> bool:
            try:
                with self._state_lock:
                    st = getattr(self, "_state", None)
                    diag["state_after"] = st.name if hasattr(st, "name") else str(st)
                    tk = getattr(self, "_processing_token", None)
                    diag["token_after"] = f"id={id(tk)}" if tk is not None else None
            except Exception:
                pass

            diag["total_ms"] = round((time.perf_counter() - _start_t0) * 1000, 2)

            with contextlib.suppress(Exception):
                self._last_stop_diag = diag

            if debug_level >= 3:
                logger.debug(
                    "[STOP-AP] abgeschlossen in %.2fms (success=%s, "
                    "already_idle=%s, skip=%s, state=%s→%s, "
                    "token_invalidated=%s, cancel_set=%s, "
                    "shutdown=%s) – Fehler: %d",
                    diag["total_ms"],
                    diag["success"],
                    diag["already_idle"],
                    diag["skip_in_progress"],
                    diag["state_before"],
                    diag["state_after"],
                    diag["token_invalidated"],
                    diag["cancel_event_set"],
                    diag["shutdown_impl_called"],
                    len(diag["errors"]),
                )
            return bool(diag["success"])

        if not hasattr(self, "_stop_lock"):
            self._stop_lock = threading.RLock()
        if not hasattr(self, "_state_lock"):
            self._state_lock = threading.RLock()
        if not hasattr(self, "_stop_event"):
            self._stop_event = threading.Event()
        if not hasattr(self, "_state_condition"):
            self._state_condition = threading.Condition(self._state_lock)
        if not hasattr(self, "_event_bus"):
            self._event_bus = None
        if not hasattr(self, "_stop_in_progress"):
            self._stop_in_progress = False
        if not hasattr(self, "_processing_token"):
            self._processing_token = None
        if not hasattr(self, "_pipe_cancel_event"):
            self._pipe_cancel_event = threading.Event()
        if not hasattr(self, "State"):
            from enum import Enum

            class State(Enum):
                IDLE = 0
                STARTING = 1
                PROCESSING = 2
                STOPPING = 3

            self.State = State

        if force:
            logger.warning(
                "🚨 Force-Shutdown aktiviert – sofortiger Abbruch ohne Wartezeit!",
            )
            backup_queue = False
            diag["backup_queue"] = False

        log_debug(
            "processor",
            "stop_processing (wait=%s, timeout=%.1f, backup_queue=%s, force=%s)",
            wait,
            timeout,
            backup_queue,
            force,
        )

        with self._stop_lock:
            if self._stop_in_progress:
                if debug_level >= 3:
                    log_debug(
                        "processor",
                        "stop_processing: bereits aktiv – überspringe",
                    )
                diag["skip_in_progress"] = True
                diag["success"] = True
                return _finalize()
            self._stop_in_progress = True

        try:
            with self._state_lock:
                st = getattr(self, "_state", None)
                diag["state_before"] = st.name if hasattr(st, "name") else str(st)
                tk_before = getattr(self, "_processing_token", None)
                diag["token_before"] = (
                    f"id={id(tk_before)}" if tk_before is not None else None
                )

                if self._state not in (
                    self.State.PROCESSING,
                    self.State.STARTING,
                ):
                    if debug_level >= 3:
                        log_debug(
                            "processor",
                            "Bereits idle (state=%s) – nichts zu tun",
                            diag["state_before"],
                        )
                    diag["already_idle"] = True
                    if tk_before is not None:
                        self._processing_token = None
                        diag["token_invalidated"] = True
                    try:
                        if hasattr(self, "_pipe_cancel_event"):
                            self._pipe_cancel_event.set()
                            diag["cancel_event_set"] = True
                    except Exception:
                        pass

                    with contextlib.suppress(Exception):
                        self._stop_in_progress = False

                    if self._event_bus is not None:
                        with contextlib.suppress(Exception):
                            self._event_bus.emit("audio_processor_idle", None)
                            self._event_bus.emit(
                                "processing_state_changed",
                                {"state": "idle"},
                            )

                    diag["success"] = True
                    return _finalize()

                self._set_state(self.State.STOPPING)
                if debug_level >= 3:
                    log_debug(
                        "processor",
                        "[STOP-AP] State: %s → STOPPING",
                        diag["state_before"],
                    )

                if not self._stop_event.is_set():
                    self._stop_event.set()
                    diag["stop_event_set"] = True
                    if debug_level >= 3:
                        log_debug("processor", "[STOP-AP] _stop_event gesetzt")
                else:
                    diag["stop_event_set"] = True

                if tk_before is not None:
                    self._processing_token = None
                    diag["token_invalidated"] = True
                    if debug_level >= 3:
                        log_debug(
                            "processor",
                            "[STOP-AP] 🎫 _processing_token invalidiert (war %s)",
                            diag["token_before"],
                        )

                try:
                    cancel_evt = getattr(self, "_pipe_cancel_event", None)
                    if cancel_evt is not None and hasattr(cancel_evt, "set"):
                        if not cancel_evt.is_set():
                            cancel_evt.set()
                            diag["cancel_event_set"] = True
                            if debug_level >= 3:
                                log_debug(
                                    "processor",
                                    "[STOP-AP] 🛑 _pipe_cancel_event gesetzt",
                                )
                        else:
                            diag["cancel_event_set"] = True
                except Exception as e:
                    diag["errors"].append(f"pipe_cancel_event: {e}")
                    logger.debug(
                        "[STOP-AP] Pipe-Cancel-Event setzen fehlgeschlagen: %s",
                        e,
                    )
        except Exception as e:
            diag["errors"].append(f"state_transition: {e}")
            logger.error(
                "[STOP-AP] State-Übergang fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 3),
            )

        try:
            stop_timer_fn = getattr(self, "_stop_translation_flush_timer", None)
            if callable(stop_timer_fn):
                stop_timer_fn()
        except Exception as e:
            diag["errors"].append(f"stop_flush_timer: {e}")
            logger.debug(
                "[STOP-AP] _stop_translation_flush_timer fehlgeschlagen: %s",
                e,
            )

        def _do_shutdown() -> None:
            """Führt die eigentliche Ressourcenbereinigung durch."""
            try:
                if force:
                    shutdown_fn = getattr(self, "_shutdown_impl_force", None)
                    if callable(shutdown_fn):
                        diag["shutdown_impl_called"] = "force"
                        shutdown_fn(backup_queue)
                    else:
                        diag["shutdown_impl_called"] = "impl_force_fallback"
                        self._shutdown_impl(backup_queue, force=True)
                else:
                    diag["shutdown_impl_called"] = "impl"
                    self._shutdown_impl(backup_queue, force=False)
            except AttributeError as e:
                diag["errors"].append(f"shutdown_missing: {e}")
                logger.error("Fehler: Shutdown-Methode nicht implementiert: %s", e)
            except Exception as e:
                diag["errors"].append(f"shutdown_exception: {e}")
                logger.error(
                    "Fehler im Hintergrund‑Shutdown: %s",
                    e,
                    exc_info=(debug_level >= 3),
                )
            finally:
                try:
                    with self._state_lock:
                        self._set_state(self.State.IDLE)
                        with contextlib.suppress(Exception):
                            self._state_condition.notify_all()
                except Exception as e:
                    diag["errors"].append(f"set_idle: {e}")

                with contextlib.suppress(Exception):
                    self._stop_event.clear()

                with contextlib.suppress(Exception):
                    self._stop_in_progress = False

                try:
                    evt = getattr(self, "processing_completed_event", None)
                    if evt is not None and hasattr(evt, "set"):
                        evt.set()
                except Exception:
                    pass

                if self._event_bus is not None:
                    with contextlib.suppress(Exception):
                        self._event_bus.emit("audio_processor_idle", None)

                if debug_level >= 3:
                    log_debug(
                        "processor",
                        "[STOP-AP] Hintergrund-Shutdown abgeschlossen (state=IDLE)",
                    )

        if wait:
            _do_shutdown()
            with self._state_lock:
                if self._state == self.State.IDLE:
                    diag["success"] = True
                    return _finalize()
                try:
                    self._state_condition.wait(timeout=timeout)
                except Exception as e:
                    diag["errors"].append(f"wait: {e}")
                diag["success"] = self._state == self.State.IDLE
                return _finalize()
        else:
            try:
                thread = threading.Thread(
                    target=_do_shutdown,
                    daemon=True,
                    name=f"AudioProc-Shutdown-{id(self):x}",
                )
                thread.start()
                if debug_level >= 4:
                    log_debug(
                        "processor",
                        "Hintergrund-Shutdown gestartet (Thread=%s)",
                        thread.name,
                    )
            except Exception as e:
                diag["errors"].append(f"thread_start: {e}")
                logger.error(
                    "[STOP-AP] Shutdown-Thread starten fehlgeschlagen: %s",
                    e,
                    exc_info=(debug_level >= 3),
                )
            diag["success"] = True
            return _finalize()

    def _shutdown_impl_force(self, backup_queue: bool = False) -> dict:
        """Force-Shutdown-Alias für _shutdown_impl(force=True)."""
        return self._shutdown_impl(backup_queue=backup_queue, force=True)

    def _shutdown_impl(self, backup_queue: bool = False, force: bool = False) -> dict:
        """
        Führt die eigentliche Ressourcenbereinigung durch – blockiert nicht.
        """
        import time as _time
        import traceback as _tb

        logger = logging.getLogger("dragon")
        log_debug = logger.debug
        log_info = logger.info
        log_warning = logger.warning
        log_error = logger.error

        debug_level = getattr(self, "debug_level", 0)

        result: dict = {
            "success": False,
            "skipped": False,
            "force": bool(force),
            "backup_queue": bool(backup_queue),
            "total_ms": 0.0,
            "pre_kill_ms": 0.0,
            "steps": {},
            "errors": [],
            "state_before": None,
            "state_after": None,
            "entry_count": 0,
            "reentrant": False,
        }

        try:
            result["entry_count"] = (
                int(getattr(self, "_shutdown_impl_entry_count", 0)) + 1
            )
            self._shutdown_impl_entry_count = result["entry_count"]
        except Exception:
            result["entry_count"] = -1

        if debug_level >= 4:
            try:
                _stack = "".join(_tb.format_stack(limit=6)[:-1])
                log_debug(
                    f"_shutdown_impl ENTRY #{result['entry_count']} "
                    f"(force={force}, backup_queue={backup_queue}, "
                    f"thread={threading.current_thread().name})\n{_stack}"
                )
            except Exception:
                pass

        def _state_name(state_obj) -> str | None:
            """Liefert den reinen Namen eines State-Enums oder None."""
            if state_obj is None:
                return None
            name = getattr(state_obj, "name", None)
            if name:
                return str(name)
            s = str(state_obj)
            if "." in s:
                return s.rsplit(".", 1)[-1]
            return s

        _pre_kill_t0 = _time.perf_counter()
        _guard_state = (
            "set" if getattr(self, "_guaranteed_cleanup_done", False) else "clear"
        )
        try:
            kill_fn = getattr(self, "_kill_ffmpeg_streams", None)
            if callable(kill_fn):
                if debug_level >= 3:
                    log_debug(
                        f"_shutdown_impl: PRE-KILL START "
                        f"(entry=#{result['entry_count']}, guard={_guard_state})"
                    )
                kill_fn()
                if debug_level >= 3:
                    log_debug(
                        f"_shutdown_impl: PRE-KILL DONE "
                        f"(entry=#{result['entry_count']})"
                    )
            else:
                if debug_level >= 3:
                    log_debug(
                        "_shutdown_impl: _kill_ffmpeg_streams nicht verfügbar "
                        "– skip PRE-KILL"
                    )
        except Exception as e:
            log_error(
                f"_shutdown_impl: PRE-KILL fehlgeschlagen: {e}",
                exc_info=(debug_level >= 3),
            )
            result["errors"].append(f"pre_kill: {e}")

        result["pre_kill_ms"] = round((_time.perf_counter() - _pre_kill_t0) * 1000, 2)

        lock = getattr(self, "_shutdown_impl_lock", None)
        if lock is None:
            lock = threading.Lock()
            with contextlib.suppress(Exception):
                self._shutdown_impl_lock = lock

        try:
            _lock_owner = getattr(self, "_shutdown_impl_lock_owner", None)
            _me = threading.get_ident()
        except Exception:
            _lock_owner = None
            _me = None

        _reentrant = _lock_owner == _me and _me is not None
        result["reentrant"] = _reentrant

        if _reentrant:
            log_warning(
                f"_shutdown_impl: reentranter Aufruf vom selben Thread "
                f"(entry=#{result['entry_count']}) – fahre ohne Lock fort"
            )

        _lock_acquired = False
        if not _reentrant:
            try:
                lock.acquire()
                _lock_acquired = True
                with contextlib.suppress(Exception):
                    self._shutdown_impl_lock_owner = _me
            except Exception as e:
                log_error(
                    f"_shutdown_impl: Lock-Acquire fehlgeschlagen: {e}",
                    exc_info=(debug_level >= 3),
                )
                result["total_ms"] = result["pre_kill_ms"]
                return result

        try:
            if getattr(self, "_guaranteed_cleanup_done", False):
                if debug_level >= 3:
                    log_debug(
                        f"_shutdown_impl: bereits abgeschlossen "
                        f"(entry=#{result['entry_count']}) – skip nach PRE-KILL "
                        f"(pre_kill_ms={result['pre_kill_ms']:.2f})"
                    )
                result["skipped"] = True
                result["success"] = True
                result["total_ms"] = result["pre_kill_ms"]
                return result

            with contextlib.suppress(Exception):
                self._final_cleanup_started = True

            state_before_obj = None
            try:
                state_before_obj = getattr(self, "_state", None)
                result["state_before"] = _state_name(state_before_obj)

                st = getattr(self, "State", None)
                set_state_fn = getattr(self, "_set_state", None)
                if st is not None and callable(set_state_fn):
                    target_state = None
                    for candidate in ("STOPPING", "IDLE", "ERROR"):
                        if hasattr(st, candidate):
                            target_state = getattr(st, candidate)
                            break

                    if target_state is not None:
                        before_name = _state_name(state_before_obj)
                        after_name = _state_name(target_state)

                        if before_name != after_name:
                            try:
                                ok_state = set_state_fn(
                                    target_state,
                                    force=True,
                                    reason="shutdown_impl",
                                )
                                if debug_level >= 4:
                                    log_debug(
                                        f"_shutdown_impl: State-Übergang "
                                        f"{before_name}→{after_name} "
                                        f"(ok={ok_state})"
                                    )
                            except TypeError:
                                try:
                                    set_state_fn(target_state)
                                except Exception as inner:
                                    log_debug(
                                        f"_shutdown_impl: State-Übergang "
                                        f"fehlgeschlagen (TypeError-Fallback): "
                                        f"{inner}"
                                    )
                            except Exception as inner:
                                log_debug(
                                    f"_shutdown_impl: State-Übergang "
                                    f"fehlgeschlagen: {inner}"
                                )
            except Exception as exc:
                log_debug(f"_shutdown_impl: State-Handling übersprungen: {exc}")

            log_debug(
                f"_shutdown_impl: Start (force={force}, "
                f"backup_queue={backup_queue}, "
                f"state_before={result['state_before']}, "
                f"debug_level={debug_level}, entry=#{result['entry_count']})"
            )

            start_time = _time.perf_counter()
            step_times: dict = {}
            errors: list = list(result["errors"])
            step_deadline = 2.0 if force else 5.0

            def _safe_step(
                step_name: str,
                action,
                critical: bool = False,
                timeout: float | None = None,
            ) -> None:
                """Führt einen Schritt mit Fehlerbehandlung, Zeitmessung und Timeout aus."""
                t0 = _time.perf_counter()
                ok = False
                err = None
                timed_out = False
                effective_timeout = step_deadline if timeout is None else timeout

                if effective_timeout and effective_timeout > 0:
                    done = threading.Event()
                    exc_holder: list = []

                    def _runner():
                        try:
                            action()
                        except Exception as e:
                            exc_holder.append(e)
                        finally:
                            done.set()

                    worker = threading.Thread(
                        target=_runner,
                        name=f"DW-ShutdownStep-{step_name}",
                        daemon=True,
                    )
                    worker.start()
                    finished = done.wait(timeout=effective_timeout)
                    if not finished:
                        timed_out = True
                        log_warning(
                            f"  ⏱️ Schritt '{step_name}' Timeout nach "
                            f"{effective_timeout:.1f}s"
                        )
                    elif exc_holder:
                        err = exc_holder[0]
                    else:
                        ok = True
                else:
                    try:
                        action()
                        ok = True
                    except Exception as e:
                        err = e

                if err is not None:
                    log_error(
                        f"  ❌ Schritt '{step_name}' fehlgeschlagen: {err}",
                        exc_info=debug_level >= 3,
                    )
                    errors.append(f"{step_name}: {err}")
                    if critical:
                        log_warning(
                            f"  ⚠️ Schritt '{step_name}' ist kritisch – "
                            f"fahre trotzdem fort"
                        )

                elapsed_ms = (_time.perf_counter() - t0) * 1000
                step_times[step_name] = {
                    "ms": round(elapsed_ms, 2),
                    "ok": ok,
                    "error": str(err) if err else None,
                    "timed_out": timed_out,
                    "critical": critical,
                }

                if debug_level >= 4 and ok:
                    log_debug(f"  ✅ {step_name} abgeschlossen ({elapsed_ms:.1f}ms)")
                elif debug_level >= 3 and timed_out:
                    log_debug(f"  ⏱️ {step_name} Timeout ({elapsed_ms:.1f}ms)")

            if backup_queue:
                _safe_step(
                    "backup_raw_audio_queue",
                    self._backup_raw_audio_queue_safe,
                )
            else:
                step_times["backup_raw_audio_queue"] = {
                    "ms": 0.0,
                    "ok": True,
                    "error": None,
                    "timed_out": False,
                    "critical": False,
                    "skipped": True,
                }

            _safe_step(
                "stop_dispatcher",
                lambda: self._stop_dispatcher(clear_queue=not backup_queue),
                critical=True,
            )

            _safe_step(
                "shutdown_timeout_executor",
                lambda: self._shutdown_timeout_executor(force=True),
            )

            _safe_step(
                "shutdown_transcription_executor",
                lambda: self._shutdown_transcription_executor(force=force),
                critical=True,
            )

            _safe_step(
                "shutdown_translation_executor",
                lambda: self._shutdown_translation_executor(force=force),
                critical=True,
            )

            _safe_step(
                "clear_and_sync_queue",
                self._clear_and_sync_queue_safe,
            )

            _safe_step(
                "reset_pending_tasks",
                self._reset_pending_tasks_safe,
            )

            _safe_step(
                "reset_engine_fallback",
                self._reset_engine_fallback,
            )

            _safe_step(
                "cleanup_temp_files",
                self._cleanup_temp_files,
            )

            _safe_step(
                "mark_threads_daemon",
                self._mark_all_worker_threads_daemon,
                critical=False,
            )

            if getattr(self, "_event_bus", None):
                _safe_step(
                    "emit_cleanup_event",
                    lambda: self._event_bus.emit(
                        "shutdown_completed",
                        {"force": force, "backup_queue": backup_queue},
                    ),
                )

            total_ms = (_time.perf_counter() - start_time) * 1000
            result["total_ms"] = round(total_ms + result["pre_kill_ms"], 2)
            result["steps"] = step_times
            result["errors"] = errors
            result["success"] = (len(errors) == 0) or bool(force)
            result["skipped"] = False

            try:
                result["state_after"] = _state_name(getattr(self, "_state", None))
            except Exception:
                result["state_after"] = None

            for flag_name, flag_value in (
                ("_guaranteed_cleanup_done", True),
                ("_final_cleanup_started", False),
                ("_engines_disposed", True),
                ("_cleanup_done", True),
            ):
                with contextlib.suppress(Exception):
                    setattr(self, flag_name, flag_value)

            if debug_level >= 2:
                steps_summary = ", ".join(
                    f"{k}={v['ms']:.1f}ms{'!' if not v['ok'] else ''}"
                    for k, v in step_times.items()
                    if not v.get("skipped", False)
                )
                log_debug(
                    f"_shutdown_impl: abgeschlossen in {result['total_ms']:.2f}ms "
                    f"(pre_kill={result['pre_kill_ms']:.1f}ms) – "
                    f"state={result['state_before']}→{result['state_after']} – "
                    f"Schritte: {steps_summary}"
                )
                if errors:
                    log_debug(f"_shutdown_impl: {len(errors)} Fehler: {errors[:5]}")
            else:
                suffix = f" ({len(errors)} Fehler)" if errors else ""
                log_info(
                    f"🧹 Ressourcenbereinigung abgeschlossen in "
                    f"{result['total_ms']:.2f}ms{suffix} "
                    f"[{result['state_before']}→{result['state_after']}]"
                )

            return result

        finally:
            if _lock_acquired:
                with contextlib.suppress(Exception):
                    self._shutdown_impl_lock_owner = None
                with contextlib.suppress(RuntimeError):
                    lock.release()

    def _kill_ffmpeg_streams(self) -> None:
        """Beendet alle aktiven FFmpeg-/yt-dlp-Streams – IDEMPOTENT."""
        import logging
        import time

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        diag = {
            "caller_stream_id": getattr(self, "_current_stream_id", None),
            "registry_before": 0,
            "registry_alive_before": 0,
            "cancel_event_set": False,
            "sigterm_sent": 0,
            "sigkill_sent": 0,
            "kill_errors": 0,
            "yt_killed": False,
            "manager_called": False,
            "manager_errors": 0,
            "registry_after": 0,
            "duration_ms": 0.0,
        }
        _t0 = time.monotonic()

        if debug_level >= 3:
            logger.debug(
                "[AUDIO] _kill_ffmpeg_streams ENTRY (stream_id=%s, debug=%d)",
                diag["caller_stream_id"],
                debug_level,
            )

        try:
            cancel_evt = getattr(self, "_pipe_cancel_event", None)
            if cancel_evt is None:
                if debug_level >= 4:
                    logger.debug("[AUDIO] ℹ️ Kein _pipe_cancel_event vorhanden – skip")
            elif cancel_evt.is_set():
                if debug_level >= 4:
                    logger.debug("[AUDIO] ℹ️ _pipe_cancel_event war bereits gesetzt")
            else:
                cancel_evt.set()
                diag["cancel_event_set"] = True
                if debug_level >= 4:
                    logger.debug("[AUDIO] ✋ _pipe_cancel_event gesetzt")
        except Exception as e:
            diag["kill_errors"] += 1
            logger.debug(
                "[AUDIO] ⚠️ Cancel-Event setzen fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        active = getattr(self, "_active_pipe_procs", None)
        if active is None:
            if debug_level >= 4:
                logger.debug(
                    "[AUDIO] ℹ️ _active_pipe_procs nicht vorhanden – "
                    "überspringe Registry-Kill"
                )
        else:
            try:
                snapshot = list(active)
                diag["registry_before"] = len(snapshot)

                if debug_level >= 5:
                    _pids_before = []
                    for entry in snapshot:
                        p = entry[0] if isinstance(entry, (tuple, list)) else entry
                        _pids_before.append(
                            getattr(p, "pid", None) if p is not None else None
                        )
                    logger.debug(
                        "[AUDIO] 🔍 Registry vor Kill: %d Einträge, PIDs=%s",
                        len(snapshot),
                        _pids_before,
                    )

                for idx, entry in enumerate(snapshot):
                    proc = (
                        entry[0]
                        if isinstance(entry, (tuple, list)) and len(entry) > 0
                        else entry
                    )
                    if proc is None:
                        if debug_level >= 5:
                            logger.debug("[AUDIO] ⚠️ Registry[%d] ist None – skip", idx)
                        continue
                    try:
                        rc = proc.poll()
                        if rc is None:
                            diag["registry_alive_before"] += 1
                            proc.terminate()
                            diag["sigterm_sent"] += 1
                            if debug_level >= 4:
                                logger.debug(
                                    "[AUDIO] SIGTERM an PID %s (registry[%d])",
                                    getattr(proc, "pid", "?"),
                                    idx,
                                )
                        elif debug_level >= 5:
                            logger.debug(
                                "[AUDIO] ℹ️ Registry[%d] PID=%s bereits "
                                "beendet (rc=%s) – skip",
                                idx,
                                getattr(proc, "pid", "?"),
                                rc,
                            )
                    except ProcessLookupError:
                        if debug_level >= 5:
                            logger.debug(
                                "[AUDIO] ℹ️ Registry[%d] PID=%s bereits weg",
                                idx,
                                getattr(proc, "pid", "?"),
                            )
                    except Exception as e:
                        diag["kill_errors"] += 1
                        logger.debug(
                            "[AUDIO] ⚠️ terminate registry[%d] PID=%s: %s",
                            idx,
                            getattr(proc, "pid", "?"),
                            e,
                            exc_info=(debug_level >= 5),
                        )

                if diag["sigterm_sent"] > 0:
                    if debug_level >= 4:
                        logger.debug(
                            "[AUDIO] ⏳ Warte 200ms auf SIGTERM-Exit (%d Prozesse)",
                            diag["sigterm_sent"],
                        )
                    time.sleep(0.2)

                    for idx, entry in enumerate(snapshot):
                        proc = (
                            entry[0]
                            if isinstance(entry, (tuple, list)) and len(entry) > 0
                            else entry
                        )
                        if proc is None:
                            continue
                        try:
                            if proc.poll() is None:
                                proc.kill()
                                diag["sigkill_sent"] += 1
                                if debug_level >= 4:
                                    logger.debug(
                                        "[AUDIO] SIGKILL an PID %s "
                                        "(reagierte nicht auf SIGTERM)",
                                        getattr(proc, "pid", "?"),
                                    )
                        except ProcessLookupError:
                            pass
                        except Exception as e:
                            diag["kill_errors"] += 1
                            logger.debug(
                                "[AUDIO] ⚠️ kill registry[%d] PID=%s: %s",
                                idx,
                                getattr(proc, "pid", "?"),
                                e,
                                exc_info=(debug_level >= 5),
                            )

                try:
                    active.clear()
                except (AttributeError, TypeError):
                    try:
                        self._active_pipe_procs = []
                    except Exception as e:
                        diag["kill_errors"] += 1
                        logger.debug(
                            "[AUDIO] ⚠️ Registry-Neuaufbau fehlgeschlagen: %s",
                            e,
                        )
                diag["registry_after"] = (
                    len(self._active_pipe_procs)
                    if isinstance(self._active_pipe_procs, list)
                    else 0
                )
                if debug_level >= 5:
                    logger.debug(
                        "[AUDIO] 🔍 Registry nach Clear: %d Einträge",
                        diag["registry_after"],
                    )
            except Exception as e:
                diag["kill_errors"] += 1
                logger.error(
                    "[AUDIO] ❌ Registry-Kill fehlgeschlagen: %s",
                    e,
                    exc_info=True,
                )

        try:
            yt_proc = getattr(self, "_yt_process", None)
            if yt_proc is None:
                if debug_level >= 5:
                    logger.debug("[AUDIO] ℹ️ Kein _yt_process gesetzt")
            else:
                rc = yt_proc.poll()
                if rc is None:
                    if debug_level >= 4:
                        logger.debug(
                            "[AUDIO] SIGTERM an yt-dlp PID %s",
                            getattr(yt_proc, "pid", "?"),
                        )
                    yt_proc.terminate()
                    try:
                        yt_proc.wait(timeout=1.0)
                        diag["yt_killed"] = True
                        if debug_level >= 4:
                            logger.debug(
                                "[AUDIO] ✅ yt-dlp PID %s sauber beendet",
                                getattr(yt_proc, "pid", "?"),
                            )
                    except Exception:
                        try:
                            yt_proc.kill()
                            diag["yt_killed"] = True
                            if debug_level >= 4:
                                logger.debug(
                                    "[AUDIO] SIGKILL an yt-dlp PID %s "
                                    "(kein SIGTERM-Exit)",
                                    getattr(yt_proc, "pid", "?"),
                                )
                        except Exception as e:
                            diag["kill_errors"] += 1
                            logger.debug(
                                "[AUDIO] ⚠️ yt-dlp kill PID %s: %s",
                                getattr(yt_proc, "pid", "?"),
                                e,
                                exc_info=(debug_level >= 5),
                            )
                else:
                    if debug_level >= 5:
                        logger.debug(
                            "[AUDIO] ℹ️ yt-dlp PID %s bereits beendet (rc=%s)",
                            getattr(yt_proc, "pid", "?"),
                            rc,
                        )
        except Exception as e:
            diag["kill_errors"] += 1
            logger.debug(
                "[AUDIO] ⚠️ yt_process cleanup: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        try:
            manager = getattr(self, "ffmpeg_manager", None)
            if manager is None:
                if debug_level >= 5:
                    logger.debug("[AUDIO] ℹ️ ffmpeg_manager nicht verfügbar – skip")
            else:
                kill_all = getattr(manager, "kill_all_streams", None)
                if callable(kill_all):
                    kill_all()
                    diag["manager_called"] = True
                    if debug_level >= 4:
                        logger.debug(
                            "[AUDIO] ✅ ffmpeg_manager.kill_all_streams() aufgerufen"
                        )
                else:
                    if debug_level >= 4:
                        logger.debug(
                            "[AUDIO] ℹ️ ffmpeg_manager hat kein kill_all_streams – skip"
                        )
        except Exception as e:
            diag["manager_errors"] += 1
            logger.error(
                "[AUDIO] ❌ Fehler in ffmpeg_manager.kill_all_streams(): %s",
                e,
                exc_info=True,
            )

        try:
            old_sid = getattr(self, "_current_stream_id", None)
            self._current_stream_id = None
            if debug_level >= 4 and old_sid is not None:
                logger.debug(
                    "[AUDIO] 🔑 _current_stream_id zurückgesetzt (%s → None)",
                    old_sid,
                )
        except Exception as e:
            logger.debug(
                "[AUDIO] ⚠️ Stream-ID-Reset fehlgeschlagen: %s",
                e,
                exc_info=(debug_level >= 5),
            )

        diag["duration_ms"] = (time.monotonic() - _t0) * 1000.0

        if debug_level >= 3:
            logger.debug(
                "[AUDIO] ✅ _kill_ffmpeg_streams DONE in %.2fms | "
                "registry=%d→%d (alive_before=%d) | "
                "sigterm=%d sigkill=%d | yt_killed=%s | "
                "manager=%s | errors=%d",
                diag["duration_ms"],
                diag["registry_before"],
                diag["registry_after"],
                diag["registry_alive_before"],
                diag["sigterm_sent"],
                diag["sigkill_sent"],
                diag["yt_killed"],
                diag["manager_called"],
                diag["kill_errors"] + diag["manager_errors"],
            )

        with contextlib.suppress(Exception):
            self._last_kill_diag = diag

    def _backup_raw_audio_queue_safe(self) -> None:
        """Sichert die Rohdaten-Queue (max. 200 Items).
        Verwendet _backup_raw_audio_queue falls vorhanden, sonst nur Log.
        """
        import logging

        logger = logging.getLogger("dragon")
        debug_level = getattr(self, "debug_level", 0)

        if debug_level >= 3:
            logger.debug("[AUDIO] _backup_raw_audio_queue_safe aufgerufen")

        try:
            if hasattr(self, "_backup_raw_audio_queue"):
                if callable(self._backup_raw_audio_queue):
                    self._backup_raw_audio_queue(force_save=True, max_items=200)
                    if debug_level >= 3:
                        logger.debug("[AUDIO] ✅ Queue gesichert (max. 200 Items)")
                else:
                    logger.warning(
                        "[AUDIO] ⚠️ _backup_raw_audio_queue ist nicht aufrufbar",
                    )
            else:
                logger.debug(
                    "[AUDIO] ℹ️ _backup_raw_audio_queue nicht vorhanden – überspringe",
                )
        except Exception as e:
            logger.error(
                f"[AUDIO] ❌ Fehler beim Sichern der Queue: {e}",
                exc_info=True,
            )

