    def _recreate_config(self) -> None:
        """Erzeugt eine neue Config‑Instanz passend zum aktuellen config_type
        und synchronisiert den internen Chunk‑Dauer‑Speicher.
        """
        try:
            if self.config_type == "realtime":
                self.config = RealtimeConfig()
            elif self.config_type == "high_accuracy":
                self.config = HighAccuracyConfig()
            elif self.config_type == "youtube":
                self.config = YouTubeOptimizedConfig()
            else:
                self.config = Config()
            logger.info(f"✅ Config gewechselt zu: {self.config_type or 'default'}")
            self._chunk_duration = self.config.CHUNK_DURATION
            self._notify_audio_processor_chunk_change()
        except Exception as e:
            logger.error(f"Fehler beim Neuerstellen der Config: {e}")
            self.config = Config()
            self._chunk_duration = self.config.CHUNK_DURATION

    def _apply_mode_overrides(self) -> None:
        """Wendet modusabhängige Overrides an und sichert vorher die Originalwerte.
        Bei Deaktivierung beider Modi werden die Originalwerte wiederhergestellt.
        """
        asian_active = getattr(self, "asian_mode", False)
        precision_active = getattr(self, "precision_mode", False)
        any_active = asian_active or precision_active

        config = getattr(self, "config", None)
        if config is None:
            logger.warning(
                "_apply_mode_overrides: Keine config gefunden – kann Overrides nicht anwenden",
            )
            return

        if not hasattr(self, "_original_values"):
            self._original_values = {}
        if not self._original_values:
            self._original_values = {
                "chunk_duration": config.CHUNK_DURATION,
                "chunk_overlap": config.CHUNK_OVERLAP,
                "vad_threshold": self.vad_threshold,
                "vad_min_speech_duration_ms": self.vad_min_speech_duration_ms,
                "vad_min_silence_duration_ms": self.vad_min_silence_duration_ms,
                "beam_size": self.beam_size,
                "temperature": self.temperature,
                "adaptive_chunk": getattr(self, "adaptive_chunk", False),
                "condition_on_previous_text": getattr(
                    self,
                    "condition_on_previous_text",
                    True,
                ),
                "no_speech_threshold": getattr(self, "no_speech_threshold", 0.6),
                "log_prob_threshold": getattr(self, "log_prob_threshold", -1.0),
                "compression_ratio_threshold": getattr(
                    self,
                    "compression_ratio_threshold",
                    2.4,
                ),
                "patience": getattr(self, "patience", 1.0),
                "min_confidence": getattr(self, "min_confidence", 0.1),
                "duplicate_similarity_threshold": getattr(
                    self,
                    "duplicate_similarity_threshold",
                    0.98,
                ),
            }
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "settings",
                    f"_apply_mode_overrides: Originalwerte gesichert ({len(self._original_values)} Einträge)",
                )

        if not any_active and self._original_values:
            restored = 0
            for key, value in self._original_values.items():
                if hasattr(config, key):
                    target = config
                elif hasattr(self, key):
                    target = self
                else:
                    continue

                current = getattr(target, key)
                if current != value:
                    setattr(target, key, value)
                    restored += 1

            if restored > 0:
                logger.info(
                    f"_apply_mode_overrides: {restored} Originalwerte wiederhergestellt "
                    "(beide Modi deaktiviert)",
                )
            self._original_values.clear()
            return

        changes: dict[str, dict[str, Any]] = {}
        chunk_duration_changed = False

        if asian_active:
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "settings",
                    "_apply_mode_overrides: Wende asian_mode Overrides an",
                )

            asian_overrides = {
                (config, "CHUNK_DURATION"): (10.0, 2.0, 30.0),
                (config, "CHUNK_OVERLAP"): (max(0.5, 10.0 * 0.1), 0.0, 5.0),
                (self, "vad_threshold"): (0.35, 0.0, 1.0),
                (self, "vad_min_speech_duration_ms"): (300, 0, 2000),
                (self, "vad_min_silence_duration_ms"): (120, 0, 2000),
                (self, "no_speech_threshold"): (0.9, 0.0, 1.0),
                (self, "log_prob_threshold"): (-3.0, -5.0, 0.0),
                (self, "compression_ratio_threshold"): (4.0, 1.0, 5.0),
                (self, "adaptive_chunk"): (False, None, None),
                (self, "min_confidence"): (0.2, 0.0, 1.0),
                (self, "duplicate_similarity_threshold"): (0.95, 0.5, 1.0),
            }
            for (target, attr), (new_val, min_v, max_v) in asian_overrides.items():
                changed, old = self._safe_set(target, attr, new_val, min_v, max_v)
                if changed:
                    changes[attr] = {"old": old, "new": new_val}
                    if attr == "CHUNK_DURATION":
                        chunk_duration_changed = True

        if precision_active:
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "settings",
                    "_apply_mode_overrides: Wende precision_mode Overrides an",
                )

            precision_overrides = {
                (config, "CHUNK_DURATION"): (20.0, 2.0, 30.0),
                (config, "CHUNK_OVERLAP"): (max(0.5, 20.0 * 0.05), 0.0, 5.0),
                (self, "beam_size"): (15, 1, 20),
                (self, "temperature"): (0.0, 0.0, 2.0),
                (self, "vad_threshold"): (0.25, 0.0, 1.0),
                (self, "vad_min_speech_duration_ms"): (260, 0, 2000),
                (self, "vad_min_silence_duration_ms"): (110, 0, 2000),
                (self, "patience"): (1.2, 0.0, 2.0),
                (self, "condition_on_previous_text"): (True, None, None),
            }
            for (target, attr), (new_val, min_v, max_v) in precision_overrides.items():
                changed, old = self._safe_set(target, attr, new_val, min_v, max_v)
                if changed:
                    changes[attr] = {"old": old, "new": new_val}
                    if attr == "CHUNK_DURATION":
                        chunk_duration_changed = True

        if chunk_duration_changed:
            if (
                hasattr(self, "_adaptive_bytes_per_sec")
                and self._adaptive_bytes_per_sec > 0
            ):
                logger.info(
                    f"_apply_mode_overrides: Adaptive Rate zurückgesetzt "
                    f"(war {self._adaptive_bytes_per_sec:.0f} B/s)",
                )
                self._adaptive_bytes_per_sec = 32000
                changes["adaptive_rate_reset"] = {
                    "old": "aktiv",
                    "new": "zurückgesetzt",
                }

            ap = self._get_audio_processor()
            if ap is not None and hasattr(ap, "_update_chunk_size"):
                try:
                    ap._update_chunk_size()
                    log_debug(
                        "settings",
                        "_apply_mode_overrides: _update_chunk_size() aufgerufen",
                    )
                except Exception as e:
                    logger.warning(f"Fehler beim Aufruf von _update_chunk_size(): {e}")
            else:
                log_debug(
                    "settings",
                    "_apply_mode_overrides: Kein AudioProcessor für _update_chunk_size()",
                )

        if changes and hasattr(self, "_event_bus") and self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "mode_overrides_applied",
                    {
                        "asian_mode": asian_active,
                        "precision_mode": precision_active,
                        "changes": changes,
                        "timestamp": time.time(),
                    },
                )
                log_debug("settings", "  📢 Event 'mode_overrides_applied' gesendet")
            except Exception as e:
                log_debug("settings", f"  ⚠️ Event-Bus Fehler: {e}")

        if changes:
            logger.info(
                "🔧 Mode Overrides angewendet: asian=%s, precision=%s – %d Änderungen",
                asian_active,
                precision_active,
                len(changes),
            )
            if DEBUG_LEVEL >= 3:
                log_debug("settings", f"  Änderungen: {changes}")
        else:
            log_debug("settings", "_apply_mode_overrides: Keine Änderungen vorgenommen")

        self._mode_overrides_applied = True

        if DEBUG_LEVEL >= 2:
            log_debug("settings", "_apply_mode_overrides: Abgeschlossen")

    def _safe_set(
        target: Any,
        attr_name: str,
        new_value: Any,
        min_val: float | None = None,
        max_val: float | None = None,
    ) -> tuple[bool, Any]:
        """Setzt ein Attribut sicher mit Typkonvertierung und Bereichsprüfung.
        Gibt (geändert, alter_Wert) zurück.
        """
        if not hasattr(target, attr_name):
            return False, None

        old_value = getattr(target, attr_name)
        old_type = type(old_value)
        if not isinstance(new_value, old_type):
            try:
                new_value = old_type(new_value)
            except (ValueError, TypeError):
                logger.error(
                    f"Kann '{new_value}' nicht in {old_type.__name__} konvertieren "
                    f"für '{attr_name}' – überspringe Setzen",
                )
                return False, old_value

        if min_val is not None and new_value < min_val:
            new_value = min_val
            logger.debug(f"'{attr_name}' auf Minimum {min_val} geklemmt")
        if max_val is not None and new_value > max_val:
            new_value = max_val
            logger.debug(f"'{attr_name}' auf Maximum {max_val} geklemmt")

        if old_value == new_value:
            return False, old_value

        try:
            setattr(target, attr_name, new_value)
            return True, old_value
        except Exception as e:
            logger.error(f"Fehler beim Setzen von '{attr_name}': {e}")
            return False, old_value

    def _get_audio_processor(self) -> Any:
        """Gibt den AudioProcessor zurück, falls verfügbar.
        Verwendet eine direkte Referenz, die beim Start gesetzt wird.
        """
        if hasattr(self, "_audio_processor") and self._audio_processor is not None:
            return self._audio_processor

        gui = getattr(self, "_gui_ref", None)
        if gui and hasattr(gui, "audio_processor"):
            return gui.audio_processor

        controller = getattr(self, "_controller_ref", None)
        if controller and hasattr(controller, "gui_ref"):
            gui = controller.gui_ref()
            if gui and hasattr(gui, "audio_processor"):
                return gui.audio_processor

        return None

    def _validate_settings(self) -> None:
        """Prüft alle relevanten Einstellungen auf Plausibilität und korrigiert sie ggf.
        Wird beim Start und nach Änderungen aufgerufen, um Inkonsistenzen zu vermeiden.
        """
        config = self.settings.config

        if not (1.0 <= config.CHUNK_DURATION <= 30.0):
            old = config.CHUNK_DURATION
            config.CHUNK_DURATION = max(1.0, min(30.0, old))
            logger.warning(
                f"CHUNK_DURATION {old:.1f}s auf {config.CHUNK_DURATION:.1f}s korrigiert",
            )

        if not (0.0 <= config.CHUNK_OVERLAP <= 2.0):
            old = config.CHUNK_OVERLAP
            config.CHUNK_OVERLAP = max(0.0, min(2.0, old))
            logger.warning(
                f"CHUNK_OVERLAP {old:.2f}s auf {config.CHUNK_OVERLAP:.2f}s korrigiert",
            )

        if config.CHUNK_OVERLAP > config.CHUNK_DURATION * 0.5:
            new_overlap = config.CHUNK_DURATION * 0.4
            logger.warning(
                f"CHUNK_OVERLAP {config.CHUNK_OVERLAP:.2f}s > 50% der Chunk‑Dauer, "
                f"auf {new_overlap:.2f}s reduziert",
            )
            config.CHUNK_OVERLAP = new_overlap

        if not (1 <= self.beam_size <= 20):
            old = self.beam_size
            self.beam_size = max(1, min(20, old))
            logger.warning(f"beam_size {old} auf {self.beam_size} korrigiert")

        if not (1 <= self.best_of <= 10):
            old = self.best_of
            self.best_of = max(1, min(10, old))
            logger.warning(f"best_of {old} auf {self.best_of} korrigiert")

        if not (0.0 <= self.temperature <= 1.0):
            old = self.temperature
            self.temperature = max(0.0, min(1.0, old))
            logger.warning(
                f"temperature {old:.2f} auf {self.temperature:.2f} korrigiert",
            )

        if not (0.5 <= self.patience <= 2.0):
            old = self.patience
            self.patience = max(0.5, min(2.0, old))
            logger.warning(f"patience {old:.2f} auf {self.patience:.2f} korrigiert")

        if not (0.0 <= self.vad_threshold <= 1.0):
            old = self.vad_threshold
            self.vad_threshold = max(0.0, min(1.0, old))
            logger.warning(
                f"vad_threshold {old:.2f} auf {self.vad_threshold:.2f} korrigiert",
            )

        if hasattr(self, "vad_min_speech_duration_ms"):
            if not (100 <= self.vad_min_speech_duration_ms <= 3000):
                old = self.vad_min_speech_duration_ms
                self.vad_min_speech_duration_ms = max(100, min(3000, old))
                logger.warning(
                    f"vad_min_speech_duration_ms {old} auf {self.vad_min_speech_duration_ms} korrigiert",
                )

        if hasattr(self, "vad_min_silence_duration_ms"):
            if not (100 <= self.vad_min_silence_duration_ms <= 3000):
                old = self.vad_min_silence_duration_ms
                self.vad_min_silence_duration_ms = max(100, min(3000, old))
                logger.warning(
                    f"vad_min_silence_duration_ms {old} auf {self.vad_min_silence_duration_ms} korrigiert",
                )

        if hasattr(self, "cache_maxsize_transcription"):
            if not (20 <= self.cache_maxsize_transcription <= 5000):
                old = self.cache_maxsize_transcription
                self.cache_maxsize_transcription = max(20, min(5000, old))
                logger.warning(
                    f"cache_maxsize_transcription {old} auf {self.cache_maxsize_transcription} korrigiert",
                )

        if hasattr(self, "cache_maxsize_translation"):
            if not (20 <= self.cache_maxsize_translation <= 10000):
                old = self.cache_maxsize_translation
                self.cache_maxsize_translation = max(20, min(10000, old))
                logger.warning(
                    f"cache_maxsize_translation {old} auf {self.cache_maxsize_translation} korrigiert",
                )

        if hasattr(self, "stream_timeout"):
            if not (10 <= self.stream_timeout <= 600):
                old = self.stream_timeout
                self.stream_timeout = max(10, min(600, old))
                logger.warning(
                    f"stream_timeout {old}s auf {self.stream_timeout}s korrigiert",
                )

        if hasattr(self, "ffmpeg_timeout"):
            if not (5 <= self.ffmpeg_timeout <= 120):
                old = self.ffmpeg_timeout
                self.ffmpeg_timeout = max(5, min(120, old))
                logger.warning(
                    f"ffmpeg_timeout {old}s auf {self.ffmpeg_timeout}s korrigiert",
                )

        if self.beam_size > config.CHUNK_DURATION * 2:
            new_beam = max(5, int(config.CHUNK_DURATION * 1.5))
            logger.warning(
                f"beam_size {self.beam_size} zu groß für Chunk‑Dauer {config.CHUNK_DURATION:.1f}s, "
                f"auf {new_beam} reduziert",
            )
            self.beam_size = new_beam

        if self.best_of > self.beam_size:
            logger.warning(
                f"best_of {self.best_of} > beam_size {self.beam_size}, auf {self.beam_size} reduziert",
            )
            self.best_of = self.beam_size

        if config.CHUNK_DURATION < 3.0 and self.vad_threshold > 0.5:
            new_threshold = 0.35
            logger.warning(
                f"vad_threshold {self.vad_threshold:.2f} bei kurzer Chunk‑Dauer "
                f"({config.CHUNK_DURATION:.1f}s) auf {new_threshold:.2f} reduziert",
            )
            self.vad_threshold = new_threshold

        logger.debug("[SYSOPT] Alle Einstellungen validiert und korrigiert")

    def restore_mode_overrides(self) -> None:
        """Stellt die ursprünglichen Werte wieder her, die vor dem ersten Aufruf von
        `_apply_mode_overrides` gesichert wurden.
        """
        import logging
        import time

        logger = logging.getLogger("dragon")

        debug_level = getattr(self, "debug_level", 0)

        if not hasattr(self, "_original_values") or not self._original_values:
            if debug_level >= 2:
                logger.debug(
                    "restore_mode_overrides: Keine gesicherten Werte – nichts zu tun",
                )
            return

        config = getattr(self, "config", None)
        if config is None:
            logger.warning(
                "restore_mode_overrides: Keine config gefunden – kann Werte nicht wiederherstellen",
            )
            self._restore_self_values()
            return

        if debug_level >= 2:
            logger.debug(
                f"restore_mode_overrides: Stelle {len(self._original_values)} Werte wieder her",
            )

        restored = []
        chunk_duration_changed = False

        if "chunk_duration" in self._original_values:
            old_val = config.CHUNK_DURATION
            new_val = self._original_values["chunk_duration"]
            if old_val != new_val:
                config.CHUNK_DURATION = new_val
                restored.append(f"chunk_duration: {old_val} → {new_val}")
                chunk_duration_changed = True
                if debug_level >= 2:
                    logger.debug(
                        f"  'chunk_duration' wiederhergestellt: {old_val} → {new_val}",
                    )

        self_keys = [
            "vad_threshold",
            "vad_min_speech_duration_ms",
            "vad_min_silence_duration_ms",
            "beam_size",
            "temperature",
            "adaptive_chunk",
            "condition_on_previous_text",
        ]

        for key in self_keys:
            if key not in self._original_values:
                continue
            if not hasattr(self, key):
                logger.warning(
                    f"restore_mode_overrides: Attribut '{key}' existiert nicht – übersprungen",
                )
                continue

            current_value = getattr(self, key)
            new_value = self._original_values[key]
            if current_value != new_value:
                try:
                    setattr(self, key, new_value)
                    restored.append(f"{key}: {current_value} → {new_value}")
                    if debug_level >= 2:
                        logger.debug(
                            f"  '{key}' wiederhergestellt: {current_value} → {new_value}",
                        )
                except Exception as e:
                    logger.error(
                        f"restore_mode_overrides: Fehler beim Wiederherstellen von '{key}': {e}",
                    )

        if chunk_duration_changed:
            try:
                bytes_per_sec = self.settings.config.BYTES_PER_SECOND
            except (AttributeError, TypeError):
                bytes_per_sec = 32000
                logger.warning(
                    f"restore_mode_overrides: Konnte BYTES_PER_SECOND nicht lesen, verwende Fallback {bytes_per_sec}",
                )

            if hasattr(self, "_adaptive_bytes_per_sec"):
                old_bps = self._adaptive_bytes_per_sec
                self._adaptive_bytes_per_sec = bytes_per_sec
                logger.info(
                    f"🔄 Adaptive Rate zurückgesetzt: {old_bps:.0f} → {bytes_per_sec} B/s",
                )
                restored.append(f"adaptive_rate: {old_bps:.0f} → {bytes_per_sec}")
            else:
                self._adaptive_bytes_per_sec = bytes_per_sec
                logger.info(f"🔄 Adaptive Rate auf {bytes_per_sec} B/s gesetzt")
                restored.append(f"adaptive_rate: neu {bytes_per_sec}")

            ap = None
            if hasattr(self, "_get_audio_processor"):
                try:
                    ap = self._get_audio_processor()
                except Exception as e:
                    logger.debug(
                        f"restore_mode_overrides: _get_audio_processor() fehlgeschlagen: {e}",
                    )

            if ap is not None and hasattr(ap, "_update_chunk_size"):
                try:
                    ap._update_chunk_size()
                    if debug_level >= 2:
                        logger.debug(
                            "restore_mode_overrides: _update_chunk_size() aufgerufen",
                        )
                except Exception as e:
                    logger.warning(f"Fehler beim Aufruf von _update_chunk_size(): {e}")
            elif debug_level >= 2:
                logger.debug(
                    "restore_mode_overrides: Kein AudioProcessor für _update_chunk_size()",
                )

        if restored and hasattr(self, "_event_bus") and self._event_bus is not None:
            try:
                self._event_bus.emit(
                    "mode_overrides_restored",
                    {"restored": restored, "timestamp": time.time()},
                )
                if debug_level >= 2:
                    logger.debug("  📢 Event 'mode_overrides_restored' gesendet")
            except Exception as e:
                logger.debug(f"  ⚠️ Event-Bus Fehler: {e}")

        self._original_values.clear()
        self._mode_overrides_applied = False

        if restored:
            logger.info(f"🔧 Mode Overrides zurückgesetzt: {', '.join(restored)}")
        elif debug_level >= 2:
            logger.debug("restore_mode_overrides: Keine Änderungen notwendig")

        if debug_level >= 2:
            logger.debug(
                f"restore_mode_overrides: {len(restored)} Werte wiederhergestellt, Cache geleert",
            )

    def _restore_self_values(self) -> None:
        """Hilfsmethode: Stellt nur die Werte auf `self` wieder her (Fallback, wenn keine config vorhanden)."""
        if not hasattr(self, "_original_values") or not self._original_values:
            return
        restored = []
        for key, original_value in self._original_values.items():
            if key == "chunk_duration":
                continue
            if not hasattr(self, key):
                continue
            current_value = getattr(self, key)
            if current_value != original_value:
                try:
                    setattr(self, key, original_value)
                    restored.append(f"{key}: {current_value} → {original_value}")
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "settings",
                            f"Fehler beim Wiederherstellen von {key}: {e}",
                        )

        if restored:
            log_debug(
                "settings",
                f"restore_mode_overrides (Fallback): {', '.join(restored)}",
            )

    @classmethod
    def load_from_file(
        cls,
        filename: str = "dragon_advanced_settings.json",
        *,
        force_reload: bool = False,
    ) -> AdvancedSettings:
        """Lädt die erweiterten Einstellungen von der Platte – optimiert, robust und mit ausführlichem Debug-Logging."""
        import time
        from contextlib import suppress
        from dataclasses import MISSING, fields
        from typing import get_args, get_origin

        load_start = time.perf_counter()
        if not hasattr(cls, "_pydantic_checked"):
            cls._pydantic_checked = True
            cls._pydantic_available = False
            show_warning = (
                os.environ.get("PYDANTIC_SILENT", "").lower()
                not in ("1", "true", "yes")
                and DEBUG_LEVEL >= 2
            )
            try:
                if importlib.util.find_spec("pydantic") is not None:
                    cls._pydantic_available = True
                    log_debug("settings", "✅ Pydantic verfügbar")
                elif show_warning:
                    logger.warning(
                        "⚠️ Pydantic nicht installiert – strukturierte Ausgaben deaktiviert",
                    )
            except Exception as e:
                if show_warning:
                    logger.warning(f"⚠️ Pydantic-Prüfung fehlgeschlagen: {e}")

        if not hasattr(cls, "_cache"):
            cls._cache: dict[str, AdvancedSettings] = {}
            cls._cache_lock = threading.RLock()
        if not hasattr(cls, "_warned_obsolete_fields"):
            cls._warned_obsolete_fields: set[str] = set()
        if not hasattr(cls, "_HOTWORD_BLACKLIST"):
            cls._HOTWORD_BLACKLIST = frozenset()

        config_dir = PlatformUtils.get_platform_config_dir()
        file_path = (config_dir / filename).resolve()
        backup_path = file_path.with_suffix(".json.bak")
        cache_key = str(file_path)

        if not force_reload:
            with cls._cache_lock:
                if cache_key in cls._cache:
                    log_debug("settings", f"📦 Cache‑Treffer für {cache_key}")
                    return cls._cache[cache_key]

        log_debug(
            "settings",
            f"🔄 Lade Einstellungen von {file_path} (force_reload={force_reload})",
        )

        data = cls._read_json_safe(file_path)
        if data is None and backup_path.exists():
            logger.warning(
                f"⚠️ Hauptkonfiguration beschädigt – versuche Backup {backup_path}",
            )
            data = cls._read_json_safe(backup_path)
            if data is not None:
                logger.info("✅ Backup erfolgreich geladen.")
                with suppress(Exception):
                    shutil.copy2(backup_path, file_path)
                    log_debug("settings", "Backup als Hauptdatei wiederhergestellt")

        if data is None:
            logger.warning(
                "⚠️ Konnte Einstellungen nicht lesen – verwende Standard-Instanz.",
            )
            instance = cls._create_default_instance()
            cls._cache_and_log(instance, cache_key, time.perf_counter())
            return instance

        file_version = data.get("_version", 1)
        if file_version > 3:
            logger.warning(
                f"Einstellungen haben neuere Version {file_version} – "
                f"möglicherweise nicht vollständig kompatibel.",
            )
        elif file_version < 3:
            data = cls._migrate_data(data, file_version)
            logger.info(
                f"Einstellungen von Version {file_version} auf 3 migriert.",
            )
            data["_version"] = 3

        chunk_duration_val = data.pop("chunk_duration", None)

        valid_field_names = {f.name for f in fields(cls) if f.init}
        field_types: dict[str, type] = {}
        defaults: dict[str, Any] = {}
        for f in fields(cls):
            if not f.init:
                continue
            typ = f.type
            origin = get_origin(typ)
            if origin is types.UnionType:
                args = [t for t in get_args(typ) if t is not type(None)]
                typ = args[0] if args else str
            field_types[f.name] = typ
            if f.default is not MISSING:
                defaults[f.name] = f.default
            elif f.default_factory is not MISSING:
                with suppress(Exception):
                    defaults[f.name] = f.default_factory()

        type_fallbacks: dict[type, Any] = {
            int: 0,
            float: 0.0,
            bool: False,
            str: "",
            list: [],
            dict: {},
        }

        filtered: dict[str, Any] = {}
        outdated: list[str] = []
        removed_hotwords: list[str] = []

        for key, value in data.items():
            if key == "_version":
                continue
            if key not in valid_field_names:
                outdated.append(key)
                if key not in cls._warned_obsolete_fields:
                    cls._warned_obsolete_fields.add(key)
                    log_debug("settings", f"Ignoriere veraltetes Feld '{key}'")
                continue

            target_type = field_types.get(key, str)
            default_for_key = defaults.get(key, type_fallbacks.get(target_type))
            converted = cls._convert_value_safe(value, target_type, default_for_key)
            filtered[key] = converted

        hotwords_raw = filtered.get("hotwords", "")
        if hotwords_raw and isinstance(hotwords_raw, str):
            blacklist = getattr(cls, "_HOTWORD_BLACKLIST", frozenset())
            cleaned = []
            for word in hotwords_raw.split(","):
                w = word.strip()
                if w and w.lower() not in blacklist:
                    cleaned.append(w)
                else:
                    removed_hotwords.append(w)
            if removed_hotwords:
                logger.info(
                    f"Hotwords bereinigt – entfernte Einträge: {
                        ', '.join(removed_hotwords)
                    }"
                )
            filtered["hotwords"] = ", ".join(cleaned)
        elif hotwords_raw is None:
            filtered["hotwords"] = ""

        for list_field in ("blacklist", "allowed_dirs"):
            val = filtered.get(list_field)
            if val is None or not isinstance(val, list):
                filtered[list_field] = []
            else:
                filtered[list_field] = [
                    str(item).strip() for item in val if item and str(item).strip()
                ]

        voice = filtered.get("tts_voice")
        if voice:
            if not hasattr(cls, "_tts_voice_pattern"):
                cls._tts_voice_pattern = re.compile(
                    r"^[a-z]{2}_[A-Z]{2}-[a-z]+-(?:low|medium|high)$",
                )
            if not cls._tts_voice_pattern.match(voice):
                logger.warning(
                    f"Ungültiges TTS-Stimmen-Format '{voice}' – setze auf 'de_DE-thorsten-medium'",
                )
                filtered["tts_voice"] = "de_DE-thorsten-medium"

        if "target_language" in filtered:
            lang = filtered["target_language"]
            if lang in SUPPORTED_LANGUAGES.values():
                for code, name in SUPPORTED_LANGUAGES.items():
                    if name == lang:
                        filtered["target_language"] = code
                        logger.info(
                            f"Migriere target_language von Name '{lang}' zu Code '{code}'",
                        )
                        break
            elif lang not in SUPPORTED_LANGUAGES and lang != "auto":
                logger.warning(
                    f"Ungültiger target_language-Code '{lang}', setze auf 'de'",
                )
                filtered["target_language"] = "de"

        numeric_validators = {
            "chunk_duration": (
                Config.MIN_CHUNK_DURATION,
                Config.MAX_CHUNK_DURATION,
                float,
            ),
            "beam_size": (1, 20, int),
            "temperature": (0.0, 2.0, float),
            "vad_threshold": (0.0, 1.0, float),
        }
        for key, (min_val, max_val, typ) in numeric_validators.items():
            if key in filtered:
                with suppress(Exception):
                    val = typ(filtered[key])
                    if not (min_val <= val <= max_val):
                        clamped = max(min_val, min(val, max_val))
                        filtered[key] = clamped
                        logger.warning(
                            f"{key} {val} außerhalb [{min_val}, {max_val}], auf {clamped} geklemmt",
                        )

        proxy_url = filtered.get("proxy_url", "").strip()
        if proxy_url:
            if not any(
                proxy_url.startswith(s)
                for s in ("http://", "https://", "socks4://", "socks5://")
            ):
                logger.warning(
                    f"Ungültiges Proxy-Schema in '{proxy_url}' – Proxy deaktiviert",
                )
                filtered["proxy_url"] = ""
                filtered["proxy_enabled"] = False
            else:
                filtered["proxy_url"] = proxy_url

        try:
            instance = cls(**filtered)
        except Exception as e:
            logger.error(
                f"Fehler beim Erstellen der AdvancedSettings‑Instanz: {e}. Verwende Standardeinstellungen.",
            )
            instance = cls()

        if chunk_duration_val is not None:
            with suppress(ValueError, TypeError):
                instance.chunk_duration = float(chunk_duration_val)

        instance._repair_if_needed()

        total_removed = len(outdated) + len(removed_hotwords)
        if total_removed > 0:
            logger.info(
                f"🔧 {total_removed} veraltete(s) Feld(er) / Hotwords entfernt. Speichere bereinigte Konfiguration…",
            )
            with suppress(Exception):
                instance.save_to_file(filename=filename)
                logger.info("✅ Bereinigte Einstellungen gespeichert.")

        cls._cache_and_log(instance, cache_key, time.perf_counter())

        load_duration = (time.perf_counter() - load_start) * 1000
        log_debug(
            "settings",
            f"✅ Geladen aus {file_path}, {len(filtered)} Felder, gecached als {
                cache_key
            } – {load_duration:.2f} ms",
        )
        return instance

    @staticmethod
    def _convert_value_safe(value: Any, target_type: type, default: Any) -> Any:
        """Konvertiert *value* sicher in den Zieltyp und gibt bei Fehlern
        den übergebenen *default* zurück, ohne Warnungen zu wiederholen.
        """
        if value is None:
            return default
        try:
            if target_type is bool:
                if isinstance(value, bool):
                    return value
                if isinstance(value, (int, float)):
                    return bool(value)
                if isinstance(value, str):
                    return value.strip().lower() in (
                        "true",
                        "1",
                        "yes",
                        "on",
                        "ja",
                        "wahr",
                        "y",
                        "enable",
                    )
                return default
            if target_type is int:
                return int(float(value))
            if target_type is float:
                return float(value)
            if target_type is str:
                return str(value)
            if target_type is list:
                if isinstance(value, list):
                    return [str(v).strip() for v in value if str(v).strip()]
                if isinstance(value, str):
                    parts = [v.strip() for v in re.split(r"[;,]", value) if v.strip()]
                    return parts
                return default if default is not None else []
            return value
        except (ValueError, TypeError):
            return default

    @classmethod
    def _create_default_instance(cls) -> AdvancedSettings:
        """Erstellt eine Instanz mit Standardwerten und führt eine Reparatur
        durch.  Diese Methode kapselt die Logik, die an mehreren Stellen
        gebraucht wird.
        """
        instance = cls()
        instance._repair_if_needed()
        return instance

    @classmethod
    def _cache_and_log(
        cls,
        instance: AdvancedSettings,
        cache_key: str,
        start_time: float,
    ) -> None:
        """Legt die Instanz im Cache ab und schreibt eine Info‑Meldung."""
        with cls._cache_lock:
            cls._cache[cache_key] = instance
        duration = (time.perf_counter() - start_time) * 1000
        logger.info(
            "✅ Erweiterte Einstellungen geladen (%s, %.1f ms)",
            instance.config_type,
            duration,
        )

    @staticmethod
    def _read_json_safe(
        file_path: Path,
        *,
        use_cache: bool = True,
        cache_ttl: float = 2.0,
    ) -> dict[str, Any] | None:
        """Liest eine JSON‑Datei mit mehreren Encodings und optionalem Caching.
        Bei Fehlern wird ein Backup erstellt.
        """
        if not hasattr(AdvancedSettings, "_json_cache"):
            AdvancedSettings._json_cache = {}
            AdvancedSettings._json_cache_lock = threading.RLock()
            AdvancedSettings._json_cache_ttl = cache_ttl

        cache_key = str(file_path.resolve())
        if use_cache:
            with AdvancedSettings._json_cache_lock:
                entry = AdvancedSettings._json_cache.get(cache_key)
                if entry:
                    data, timestamp = entry
                    if time.monotonic() - timestamp < cache_ttl:
                        log_debug(
                            "settings",
                            f"📦 _read_json_safe Cache‑Treffer für {cache_key}",
                        )
                        return data
                    del AdvancedSettings._json_cache[cache_key]

        if not file_path.exists():
            log_debug("settings", f"Datei nicht vorhanden: {file_path}")
            return None

        try:
            if file_path.stat().st_size == 0:
                logger.warning(f"Leere JSON‑Datei: {file_path}")
                return None
        except OSError as e:
            logger.warning(f"Kann Dateigröße nicht ermitteln: {e}")

        encodings = ["utf-8", "utf-8-sig", "latin-1", "cp1252"]
        last_error = None
        content = None
        used_encoding = None

        for enc in encodings:
            try:
                with open(file_path, encoding=enc) as f:
                    content = f.read()
                used_encoding = enc
                break
            except UnicodeDecodeError as e:
                last_error = e
                continue
            except (OSError, PermissionError) as e:
                logger.warning(f"Lesefehler bei {file_path} mit {enc}: {e}")
                return None
            except Exception as e:
                logger.error(f"Unerwarteter Fehler beim Lesen von {file_path}: {e}")
                return None

        if content is None:
            logger.error(
                f"Konnte Datei mit keinem der Encodings lesen. Letzter Fehler: {last_error}",
            )
            return None

        try:
            data = json.loads(content)
        except json.JSONDecodeError as e:
            logger.error(
                f"JSONDecodeError in {file_path} (Zeile {e.lineno}, Spalte {e.colno}): {
                    e.msg
                }",
            )
            backup_path = file_path.with_suffix(".json.bak")
            try:
                shutil.copy2(file_path, backup_path)
                logger.warning(f"Korrupte Einstellungen gesichert als: {backup_path}")
            except Exception as be:
                logger.warning(f"Konnte kein Backup erstellen: {be}")
            return None
        except Exception as e:
            logger.error(f"Unerwarteter Fehler beim Parsen von {file_path}: {e}")
            return None

        if not isinstance(data, dict):
            logger.warning(
                f"JSON-Wurzel ist kein Dictionary in {file_path} – Typ: {type(data).__name__}",
            )
            return None

        log_debug(
            "settings",
            f"✅ JSON geladen von {file_path} (Encoding: {used_encoding}, {
                len(data)
            } Felder)",
        )

        if use_cache:
            with AdvancedSettings._json_cache_lock:
                AdvancedSettings._json_cache[cache_key] = (data, time.monotonic())
                if len(AdvancedSettings._json_cache) > 10:
                    oldest = min(
                        AdvancedSettings._json_cache.items(),
                        key=lambda x: x[1][1],
                    )
                    del AdvancedSettings._json_cache[oldest[0]]
        return data

    @classmethod
    def _build_type_map(cls) -> dict[str, type]:
        """Baut ein Mapping von Feldnamen auf deren Python‑Typ auf.
        Nur einfache Typen werden berücksichtigt (int, float, bool, str, list).
        """
        type_map: dict[str, type] = {}
        for f in fields(cls):
            if not f.init:
                continue
            typ = f.type
            origin = get_origin(typ)
            if origin is types.UnionType:
                args = [t for t in get_args(typ) if t is not type(None)]
                if args:
                    typ = args[0]
            if typ in (int, float, bool, str, list):
                type_map[f.name] = typ
        return type_map

    @classmethod
    def _migrate_data(cls, data: dict[str, Any], from_version: int) -> dict[str, Any]:
        """Führt Versions‑Migrationen durch.  Wird erweitert, sobald
        sich die Datenstruktur ändert.
        """
        if from_version < 2:
            data.pop("some_old_key", None)
            if "old_name" in data:
                data["new_name"] = data.pop("old_name")

        if from_version < 3:
            if data.get("blacklist_mode") == "word":
                data["blacklist_mode"] = "substring"

        return data

    @classmethod
    def invalidate_cache(cls, filename: str = "dragon_advanced_settings.json") -> None:
        """Entfernt einen Eintrag aus dem internen Cache, sodass der nächste
        Ladevorgang die aktuellen Daten von der Platte liest.
        """
        if not hasattr(cls, "_cache"):
            return
        config_dir = PlatformUtils.get_platform_config_dir()
        file_path = (config_dir / filename).resolve()
        cache_key = str(file_path)
        with cls._cache_lock:
            if cache_key in cls._cache:
                del cls._cache[cache_key]
                if DEBUG_LEVEL >= 3:
                    log_debug("settings", f"Cache invalidated for {cache_key}")

    @staticmethod
    def _convert_value(value: Any, target_type: type, default: Any) -> Any:
        """Konvertiert *value* sicher in den Zieltyp.
        Unterstützt ``bool``, ``int``, ``float``, ``str`` und ``list``.
        Bei fehlgeschlagener Konvertierung wird *default* zurückgegeben.
        """
        if value is None:
            return default

        if target_type is bool:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return value != 0
            if isinstance(value, str):
                return value.strip().lower() in (
                    "true",
                    "1",
                    "yes",
                    "on",
                    "ja",
                    "wahr",
                    "y",
                    "enable",
                )
            return default

        if target_type is int:
            try:
                return int(value)
            except (ValueError, TypeError):
                return default
        if target_type is float:
            try:
                return float(value)
            except (ValueError, TypeError):
                return default

        if target_type is str:
            return str(value) if value is not None else default

        if target_type is list:
            if isinstance(value, list):
                return [str(v).strip() for v in value if str(v).strip()]
            if isinstance(value, str):
                parts = [v.strip() for v in re.split(r"[;,|\n]+", value) if v.strip()]
                return parts or (default if isinstance(default, list) else [])
            return default if isinstance(default, list) else []

        try:
            return target_type(value)
        except (ValueError, TypeError, OverflowError):
            return default

    def _repair_if_needed(self) -> None:
        """Führt eine vollständige Reparatur aller Einstellungen durch.
        Die Methode ist idempotent und kann mehrfach aufgerufen werden.
        Kritische, langlaufende Operationen (Pydantic‑Reparatur) werden
        asynchron in einem Hintergrund‑Thread ausgeführt, um den GUI‑Start
        nicht zu blockieren.
        """
        self._validate_tts_voice()
        self._validate_language_settings()
        self._validate_tts_engine()
        self._clamp_numeric_values()
        self._validate_worker_counts()
        self._validate_auto_tts_delay()
        self._validate_sentence_buffering()
        self._validate_download_timeout()
        self._validate_config_type()
        self._validate_audio_profile()
        self._cleanup_proxy()
        self._cleanup_hotwords()
        self._cleanup_lists()
        self._validate_summarize_model()
        self._validate_ollama_model()
        self._cleanup_suppress_tokens()
        self._clamp_confidence_values()
        self._clamp_vad_threshold()
        self._clamp_duplicate_threshold()
        try:
            from importlib.metadata import version

            pv = version("pydantic")
            cv = version("pydantic-core")
            p_base = pv.split("+")[0]
            c_base = cv.split("+")[0]
            p_major = p_base.split(".")[0]
            c_major = c_base.split(".")[0]
            if p_major != c_major:
                self._schedule_pydantic_repair()
        except Exception as e:
            logger.debug(f"Pydantic‑Prüfung fehlgeschlagen: {e}")

        if not hasattr(self, "config") or self.config is None:
            self._recreate_config()
        self._apply_mode_overrides()

        if hasattr(self, "_chunk_duration"):
            self.chunk_duration = self._chunk_duration

        if not hasattr(self, "_original_values") or not isinstance(
            self._original_values,
            dict,
        ):
            self._original_values = {}
        if not hasattr(self, "_mode_overrides_applied"):
            self._mode_overrides_applied = False

        if DEBUG_LEVEL >= 2:
            log_debug("settings", "_repair_if_needed: Alle Reparaturen abgeschlossen")

    def _schedule_pydantic_repair(self) -> None:
        """Startet die Pydantic‑Reparatur in einem Hintergrund‑Thread."""

        def repair_worker():
            try:
                self._notify_user("🔧 Pydantic‑Inkompatibilität wird repariert …")
                success, msg = self._perform_pydantic_repair()
                if success:
                    logger.info("Pydantic‑Reparatur erfolgreich: %s", msg)
                    self._notify_user("✅ Pydantic‑Reparatur erfolgreich")
                else:
                    logger.warning("Pydantic‑Reparatur fehlgeschlagen: %s", msg)
                    self._notify_user(
                        "⚠️ Pydantic‑Reparatur fehlgeschlagen – bitte manuell prüfen",
                    )
            except Exception as e:
                logger.error("Pydantic‑Reparatur unerwartet fehlgeschlagen: %s", e)
                self._notify_user("❌ Pydantic‑Reparatur fehlgeschlagen – siehe Log")

        threading.Thread(
            target=repair_worker,
            daemon=True,
            name="PydanticRepair",
        ).start()

    def _notify_user(self, message: str) -> None:
        """Sendet eine Benachrichtigung an den Benutzer über den verfügbaren Kanal."""
        if not message:
            return

        try:
            bus = AppContext().event_bus
            if bus is not None and hasattr(bus, "emit"):
                bus.emit("info", message)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "notify",
                        f"Nachricht via Event-Bus gesendet: {message[:80]}...",
                    )
                return
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("notify", f"Event-Bus Fehler: {e}")

        try:
            gui = getattr(self, "gui", None) or getattr(self, "_gui", None)
            if gui is None and hasattr(self, "controller_ref"):
                ctrl = self.controller_ref
                if hasattr(ctrl, "gui_ref"):
                    gui = ctrl.gui_ref()
            if gui is not None and hasattr(gui, "update_status"):
                gui.update_status(message)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "notify",
                        f"Nachricht via GUI-Statusleiste: {message[:80]}...",
                    )
                return
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("notify", f"GUI-Statusleiste Fehler: {e}")

        logger.info(f"ℹ️ {message}")
        if DEBUG_LEVEL >= 2:
            log_debug("notify", f"Nachricht via Logger: {message[:80]}...")

    def _perform_pydantic_repair(self) -> tuple[bool, str]:
        """Führt die Pydantic‑Reparatur durch (subprocess‑Aufruf von pip).
        Gibt (Erfolg, Nachricht) zurück. Diese Methode sollte NIEMALS
        im Hauptthread aufgerufen werden, da sie blockieren kann.
        """
        TARGET_PYDANTIC = "2.46.4"
        TARGET_CORE = "2.46.4"

        def _get_versions():
            """Hilfsfunktion zum Abrufen der aktuellen Versionen."""
            try:
                from importlib.metadata import version

                pv = version("pydantic")
                cv = version("pydantic-core")
                return pv, cv
            except Exception:
                return None, None

        pv, cv = _get_versions()
        if pv and cv:
            p_base = pv.split("+")[0]
            c_base = cv.split("+")[0]
            if p_base.split(".")[:2] == c_base.split(".")[:2]:
                return True, f"Bereits kompatibel (pydantic={pv}, core={cv})"

        cmd = [
            sys.executable,
            "-m",
            "pip",
            "install",
            f"pydantic=={TARGET_PYDANTIC}",
            f"pydantic-core=={TARGET_CORE}",
            "--upgrade",
            "--no-cache-dir",
        ]

        in_venv = hasattr(sys, "real_prefix") or (
            hasattr(sys, "base_prefix") and sys.base_prefix != sys.prefix
        )
        if not in_venv:
            if self._pip_supports_break_system():
                cmd.append("--break-system-packages")
            else:
                cmd.append("--user")

        try:
            subprocess.run(
                cmd,
                check=True,
                timeout=120,
                capture_output=True,
                text=True,
            )

            FastLazyLoader.clear_cache("pydantic")
            FastLazyLoader.clear_cache("pydantic_core")

            pv_new, cv_new = _get_versions()
            if pv_new and cv_new:
                p_base_new = pv_new.split("+")[0]
                c_base_new = cv_new.split("+")[0]
                if p_base_new.split(".")[:2] == c_base_new.split(".")[:2]:
                    return (
                        True,
                        f"Reparatur erfolgreich (pydantic={pv_new}, core={cv_new})",
                    )
                return False, (
                    f"Reparatur schien erfolgreich, aber Versionen sind immer noch "
                    f"inkompatibel (pydantic={pv_new}, core={cv_new})"
                )
            return True, "Reparatur erfolgreich (Versionen nicht lesbar)"

        except subprocess.CalledProcessError as e:
            stderr = e.stderr.strip() if e.stderr else "keine Fehlerausgabe"
            return False, f"pip Fehler (Code {e.returncode}): {stderr}"

        except subprocess.TimeoutExpired:
            return False, "Zeitüberschreitung (120s) – Abbruch"

        except Exception as e:
            return False, f"Unerwarteter Fehler: {e!s}"

    def _validate_language_settings(self) -> None:
        """Überprüft Ziel‑ und Fallback‑Sprache."""
        if (
            self.target_language not in SUPPORTED_LANGUAGES
            and self.target_language != "auto"
        ):
            logger.warning(
                f"Unbekannte Zielsprache '{self.target_language}', setze auf 'de'",
            )
            self.target_language = "de"

        if (
            not hasattr(self, "fallback_source_language")
            or self.fallback_source_language is None
        ):
            self.fallback_source_language = "de"
        elif self.fallback_source_language not in WHISPER_SUPPORTED_LANGUAGES:
            logger.warning(
                f"Unbekannte Fallback‑Sprache '{
                    self.fallback_source_language
                }', setze auf 'de'",
            )
            self.fallback_source_language = "de"

    def _validate_tts_voice(self) -> None:
        """Stellt sicher, dass eine gültige TTS‑Stimme gesetzt ist.
        Prüft zuerst das Format, dann – falls möglich – die Verfügbarkeit
        im Piper‑Cache. Bei Abweichungen wird ein Fallback gesetzt.
        """
        if not isinstance(self.tts_voice, str) or not self.tts_voice.strip():
            old_voice = self.tts_voice
            self.tts_voice = "de_DE-thorsten-medium"
            logger.warning(
                f"TTS‑Stimme '{old_voice}' ungültig, setze auf '{self.tts_voice}'",
            )
            return

        voice = self.tts_voice.strip()

        if not re.match(r"^[a-z]{2}_[A-Z]{2}-[a-z]+-(?:low|medium|high)$", voice):
            logger.warning(
                f"TTS‑Stimme '{voice}' hat ein ungewöhnliches Format. "
                "Erwartet wird z.B. 'de_DE-thorsten-medium'. Die Stimme wird beibehalten, "
                "aber die Funktionalität ist nicht garantiert.",
            )
            return

        tts_manager = self._get_tts_manager_safe()
        if tts_manager is None:
            if DEBUG_LEVEL >= 3:
                logger.debug(
                    "TTSManager nicht verfügbar – überspringe Verfügbarkeitsprüfung",
                )
            return
        try:
            installed_voices = tts_manager.get_installed_piper_voices()
            if not installed_voices:
                logger.warning(
                    "Keine Piper‑Stimmen installiert. Setze auf Standard 'de_DE-thorsten-medium'.",
                )
                self.tts_voice = "de_DE-thorsten-medium"
                return

            if voice not in installed_voices:
                fallback = installed_voices[0]
                logger.warning(
                    f"TTS‑Stimme '{voice}' nicht installiert. Verfügbare Stimmen: {installed_voices}. "
                    f"Wechsle zu '{fallback}'.",
                )
                self.tts_voice = fallback
            elif DEBUG_LEVEL >= 3:
                logger.debug(f"TTS‑Stimme '{voice}' ist installiert")
        except Exception as e:
            logger.warning(f"Fehler beim Abrufen der installierten Piper‑Stimmen: {e}")

    def _get_tts_manager_safe(self) -> Any:
        """Versucht, den zentralen TTSManager zu laden.
        Gibt None zurück, wenn nicht verfügbar.
        """
        try:
            import importlib.util

            spec = importlib.util.find_spec("app_context")
            if spec is not None:
                from app_context import AppContext

                app = AppContext()
                if hasattr(app, "tts_manager"):
                    return app.tts_manager
        except (ImportError, AttributeError, Exception) as e:
            if DEBUG_LEVEL >= 3:
                logger.debug(f"TTSManager konnte nicht geladen werden: {e}")
        return None

    def _clamp_numeric_values(self) -> None:
        """Klemmt alle numerischen Parameter auf gültige Bereiche – optimiert und robust."""
        import logging
        import math

        logger = logging.getLogger("dragon")
        _warned_fields = set()
        numeric_fields = {
            "chunk_duration": (
                Config.MIN_CHUNK_DURATION,
                Config.MAX_CHUNK_DURATION,
                float,
                Config.BASE_CHUNK_DURATION,
            ),
            "vad_threshold": (0.0, 1.0, float, 0.25),
            "vad_min_speech_duration_ms": (0, 2000, int, 225),
            "vad_min_silence_duration_ms": (0, 2000, int, 80),
            "beam_size": (1, 20, int, 10),
            "temperature": (0.0, 2.0, float, 0.0),
            "best_of": (1, 20, int, 5),
            "patience": (0.0, 2.0, float, 1.0),
            "no_speech_threshold": (0.0, 1.0, float, 0.6),
            "log_prob_threshold": (-5.0, 0.0, float, -1.0),
            "compression_ratio_threshold": (1.0, 5.0, float, 2.4),
            "length_penalty": (-2.0, 2.0, float, 0.0),
            "ollama_temperature": (0.0, 2.0, float, 0.7),
            "ollama_timeout": (30, 300, int, 90),
            "summarize_temperature": (0.0, 1.0, float, 0.1),
            "tts_length_scale": (0.5, 1.5, float, 0.9),
            "tts_sentence_silence": (0.0, 0.5, float, 0.1),
            "max_memory_mb": (50, 16384, int, 1024),
            "max_cache_size": (10, 1000, int, 200),
            "auto_save_interval": (0, 3600, int, 300),
            "vram_idle_timeout_seconds": (0, 3600, int, 180),
            "transcript_max_lines": (100, 5000, int, 800),
            "translation_max_lines": (100, 5000, int, 600),
            "sentence_flush_interval": (0.5, 10.0, float, 3.0),
            "sentence_flush_word_threshold": (5, 100, int, 30),
            "duplicate_similarity_threshold": (0.5, 1.0, float, 0.98),
            "min_confidence": (0.0, 1.0, float, 0.1),
            "min_language_confidence": (0.0, 1.0, float, 0.2),
            "noisereduce_interval": (1, 100, int, 10),
            "start_boost_gain": (1.0, 10.0, float, 3.0),
            "start_boost_rms_threshold": (0.0, 1.0, float, 0.05),
        }

        optional_fields = {
            "cpu_threads": (0, 32, int, 0),
            "transcription_workers": (1, 16, int, 4),
            "translation_workers": (1, 8, int, 2),
            "adaptive_chunk_low_words": (1, 20, int, 3),
            "adaptive_chunk_high_words": (1, 20, int, 12),
            "download_inactivity_timeout": (5, 300, float, 30.0),
        }

        all_fields = {**numeric_fields, **optional_fields}

        for field_name, (min_val, max_val, target_type, default) in all_fields.items():
            if not hasattr(self, field_name):
                continue

            raw_value = getattr(self, field_name)
            if raw_value is None:
                setattr(self, field_name, default)
                continue

            try:
                if target_type is int:
                    value = int(float(raw_value))
                elif target_type is float:
                    value = float(raw_value)
                    if not math.isfinite(value):
                        raise ValueError(f"Unendlicher oder NaN-Wert: {value}")
                else:
                    value = raw_value
            except (ValueError, TypeError, AttributeError) as e:
                if field_name not in _warned_fields:
                    logger.warning(
                        f"Feld '{field_name}' hat ungültigen Wert {raw_value!r} – "
                        f"setze auf Standard {default}. Fehler: {e}",
                    )
                    _warned_fields.add(field_name)
                setattr(self, field_name, default)
                continue

            clamped = max(min_val, min(value, max_val))
            if clamped != value:
                if field_name not in _warned_fields:
                    logger.warning(
                        f"{field_name} = {value} außerhalb [{min_val}, {max_val}], "
                        f"auf {clamped} geklemmt",
                    )
                    _warned_fields.add(field_name)
                setattr(self, field_name, clamped)
            else:
                setattr(self, field_name, value)

    def _validate_tts_engine(self) -> None:
        """Stellt sicher, dass eine gültige TTS‑Engine gesetzt ist.
        Prüft den Engine-Namen gegen die Liste der unterstützten Engines.
        Falls die Engine nicht unterstützt wird, wird ein Fallback auf 'piper' gesetzt.
        Zusätzlich wird geprüft, ob die Engine auf dem System verfügbar ist (optional).
        """
        if not isinstance(self.tts_engine, str) or not self.tts_engine.strip():
            old_engine = self.tts_engine
            self.tts_engine = "piper"
            logger.warning(
                "TTS‑Engine '%s' ungültig, setze auf 'piper'",
                old_engine,
            )
            return

        engine = self.tts_engine.strip().lower()
        valid_engines = ("piper", "pyttsx3", "espeak")

        if engine not in valid_engines:
            logger.warning(
                "TTS‑Engine '%s' wird nicht unterstützt. Unterstützt: %s. Setze auf 'piper'.",
                engine,
                valid_engines,
            )
            self.tts_engine = "piper"
            return

        if engine == "piper":
            self._check_piper_availability()
        elif engine == "espeak":
            if not shutil.which("espeak"):
                logger.warning(
                    "espeak ist nicht im PATH. Die Sprachausgabe wird möglicherweise nicht funktionieren.",
                )

        if DEBUG_LEVEL >= 3:
            log_debug(
                "settings",
                "TTS‑Engine '%s' ist gültig und wurde validiert.",
                engine,
            )

    def _check_piper_availability(self) -> None:
        """Prüft, ob Piper verfügbar ist (PATH oder Cache mit Modellen)."""
        if shutil.which("piper"):
            return

        try:
            cache_dir = TTSManager.get_piper_cache_dir()
            if not os.path.isdir(cache_dir):
                logger.warning(
                    "Piper ist nicht im PATH und Cache-Verzeichnis '%s' existiert nicht. "
                    "Die Sprachausgabe wird nicht funktionieren.",
                    cache_dir,
                )
                return

            has_model = False
            for entry in os.listdir(cache_dir):
                full_path = os.path.join(cache_dir, entry)
                if os.path.isfile(full_path) and entry.endswith(".onnx"):
                    has_model = True
                    break

            if has_model:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "settings",
                        "Piper ist nicht im PATH, aber Stimmen im Cache vorhanden: %s",
                        cache_dir,
                    )
            else:
                logger.warning(
                    "Piper ist nicht im PATH und es wurden keine Stimmen im Cache '%s' gefunden. "
                    "Die Sprachausgabe wird nicht funktionieren.",
                    cache_dir,
                )

        except (OSError, PermissionError) as e:
            logger.warning(
                "Piper‑Verfügbarkeitsprüfung fehlgeschlagen: %s",
                e,
            )
        except Exception as e:
            logger.exception("Unerwarteter Fehler bei Piper‑Prüfung: %s", e)

    def _validate_worker_counts(self) -> None:
        """Setzt fehlende oder ungültige Worker‑Anzahlen auf sinnvolle Werte."""
        cpu_count = os.cpu_count() or 4

        if not hasattr(self, "translation_workers") or self.translation_workers < 1:
            self.translation_workers = max(1, cpu_count // 4)
            logger.debug(f"Übersetzungs‑Worker auf {self.translation_workers} gesetzt")

        if not hasattr(self, "transcription_workers") or self.transcription_workers < 1:
            self.transcription_workers = max(1, cpu_count // 4)
            logger.debug(
                f"Transkriptions‑Worker auf {self.transcription_workers} gesetzt",
            )

    def _validate_auto_tts_delay(self) -> None:
        """Stellt sicher, dass die Auto‑TTS‑Verzögerung nicht negativ ist."""
        if not hasattr(self, "auto_tts_delay_ms") or self.auto_tts_delay_ms < 0:
            self.auto_tts_delay_ms = 1500

    def _validate_sentence_buffering(self) -> None:
        """Klemmt die Satzpuffer‑Parameter auf sinnvolle Werte."""
        if not (0.5 <= self.sentence_flush_interval <= 10.0):
            old = self.sentence_flush_interval
            self.sentence_flush_interval = max(
                0.5,
                min(self.sentence_flush_interval, 10.0),
            )
            logger.warning(
                f"Satzpuffer‑Intervall {old} außerhalb [0.5, 10.0], "
                f"geklemmt auf {self.sentence_flush_interval}",
            )

        if not (5 <= self.sentence_flush_word_threshold <= 100):
            old = self.sentence_flush_word_threshold
            self.sentence_flush_word_threshold = max(
                5,
                min(self.sentence_flush_word_threshold, 100),
            )
            logger.warning(
                f"Satzpuffer‑Wortschwelle {old} außerhalb [5, 100], "
                f"geklemmt auf {self.sentence_flush_word_threshold}",
            )

    def _validate_download_timeout(self) -> None:
        """Stellt sicher, dass das Download‑Timeout im Bereich 5‑300s liegt."""
        if not (5.0 <= self.download_inactivity_timeout <= 300.0):
            old = self.download_inactivity_timeout
            self.download_inactivity_timeout = max(
                5.0,
                min(self.download_inactivity_timeout, 300.0),
            )
            logger.warning(
                f"Download‑Inaktivitäts‑Timeout {old} außerhalb [5.0, 300.0], "
                f"geklemmt auf {self.download_inactivity_timeout}",
            )

    def _validate_config_type(self) -> None:
        """Setzt einen gültigen Konfigurationstyp."""
        valid_types = ("default", "realtime", "high_accuracy", "youtube")
        if self.config_type not in valid_types:
            logger.warning(
                f"Ungültiger Konfigurationstyp '{
                    self.config_type
                }', setze auf 'high_accuracy'",
            )
            self.config_type = "high_accuracy"

    def _validate_audio_profile(self) -> None:
        """Setzt ein gültiges Audio‑Profil."""
        valid_profiles = ("transcription", "realtime", "noisy", "podcast", "music")
        if self.audio_profile not in valid_profiles:
            logger.warning(
                f"Ungültiges Audio‑Profil '{
                    self.audio_profile
                }', setze auf 'transcription'",
            )
            self.audio_profile = "transcription"

    def _validate_and_repair(self) -> None:
        """Validiert und repariert alle Konfigurationswerte beim Laden.
        Stellt sicher, dass alle Werte im gültigen Bereich liegen, korrekte Typen haben
        und keine ungültigen Werte (z.B. 'invalid') enthalten sind.
        Protokolliert alle Änderungen als Warnung.
        """
        changes = []

        def clamp_float(
            value: Any,
            min_val: float,
            max_val: float,
            default: float,
        ) -> float:
            """Klemmt einen Float-Wert in den Bereich [min_val, max_val] oder setzt default."""
            try:
                v = float(value)
            except (ValueError, TypeError):
                return default
            if v < min_val or v > max_val:
                return max(min_val, min(max_val, v))
            return v

        def clamp_int(value: Any, min_val: int, max_val: int, default: int) -> int:
            """Klemmt einen Integer-Wert in den Bereich [min_val, max_val] oder setzt default."""
            try:
                v = int(float(value))
            except (ValueError, TypeError):
                return default
            if v < min_val or v > max_val:
                return max(min_val, min(max_val, v))
            return v

        def ensure_bool(value: Any, default: bool = False) -> bool:
            """Stellt sicher, dass der Wert ein Bool ist."""
            if isinstance(value, bool):
                return value
            if isinstance(value, str):
                return value.lower() in ("true", "1", "yes", "on")
            if isinstance(value, (int, float)):
                return value != 0
            return default

        def ensure_str(value: Any, default: str = "") -> str:
            """Stellt sicher, dass der Wert ein String ist."""
            if value is None:
                return default
            return str(value).strip()

        def ensure_list(value: Any, default: list | None = None) -> list:
            """Stellt sicher, dass der Wert eine Liste ist."""
            if value is None:
                return default or []
            if isinstance(value, list):
                return value[:]
            if isinstance(value, tuple):
                return list(value)
            if isinstance(value, str):
                return [v.strip() for v in value.split(",") if v.strip()]
            return default or []

        old = self.chunk_duration
        self.chunk_duration = clamp_float(self.chunk_duration, 2.0, 30.0, 15.0)
        if self.chunk_duration != old:
            changes.append(f"chunk_duration: {old} -> {self.chunk_duration}")

        old = self.vad_threshold
