    def _cleanup_proxy(self) -> None:
        """Prüft die Proxy‑URL auf gültiges Schema und deaktiviert sie bei Fehlern."""
        if self.proxy_url and self.proxy_enabled:
            self.proxy_url = self.proxy_url.strip()
            if not any(
                self.proxy_url.startswith(s)
                for s in ("http://", "https://", "socks4://", "socks5://")
            ):
                logger.warning(
                    f"Ungültiges Proxy‑Schema in '{self.proxy_url}', deaktiviere Proxy",
                )
                self.proxy_enabled = False
                self.proxy_url = ""

    def _cleanup_hotwords(self) -> None:
        """Entfernt leere Einträge aus den Hotwords und formatiert sie korrekt."""
        if self.hotwords:
            raw = self.hotwords.strip()
            if raw:
                cleaned = [w.strip() for w in raw.split(",") if w.strip()]
                self.hotwords = ", ".join(cleaned)
            else:
                self.hotwords = ""

    def _cleanup_lists(self) -> None:
        """Bereinigt `blacklist` und `allowed_dirs`."""
        _changed = False

        if isinstance(self.blacklist, list):
            _cleaned: list[str] = []
            _seen: set[str] = set()
            for item in self.blacklist:
                if not item or not isinstance(item, str):
                    _changed = True
                    continue
                stripped = item.strip()
                if not stripped:
                    _changed = True
                    continue
                key = stripped.lower()
                if key in _seen:
                    _changed = True
                    continue
                _seen.add(key)
                _cleaned.append(stripped)
            if _cleaned != self.blacklist:
                _changed = True
            self.blacklist = _cleaned
        else:
            _changed = True
            self.blacklist = []

        if not self.blacklist:
            self.blacklist = list(_DEFAULT_BLACKLIST)
            _changed = True
            logger.info(
                "🔧 Blacklist war leer – %d Default-Einträge eingesetzt",
                len(self.blacklist),
            )

        if isinstance(self.allowed_dirs, list):
            _cleaned_dirs: list[str] = []
            _seen_dirs: set[str] = set()
            for d in self.allowed_dirs:
                if not d or not isinstance(d, str):
                    _changed = True
                    continue
                try:
                    resolved = str(Path(d).resolve())
                except (OSError, RuntimeError) as _e:
                    logger.debug(
                        "allowed_dirs: %r konnte nicht aufgelöst werden: %s",
                        d,
                        _e,
                    )
                    _changed = True
                    continue
                if resolved in _seen_dirs:
                    _changed = True
                    continue
                _seen_dirs.add(resolved)
                _cleaned_dirs.append(resolved)
            if _cleaned_dirs != self.allowed_dirs:
                _changed = True
            self.allowed_dirs = _cleaned_dirs
        else:
            _changed = True
            self.allowed_dirs = []

        if _changed and DEBUG_LEVEL >= 3:
            log_debug(
                "settings",
                f"_cleanup_lists: Blacklist={len(self.blacklist)} "
                f"Einträge, allowed_dirs={len(self.allowed_dirs)} Einträge",
            )

    def _validate_summarize_model(self) -> None:
        """Setzt ein gültiges Zusammenfassungsmodell."""
        if (
            not isinstance(self.summarize_model, str)
            or not self.summarize_model.strip()
        ):
            self.summarize_model = "qwen2.5:7b"

    def _validate_ollama_model(self) -> None:
        """Setzt ein gültiges Ollama‑Modell."""
        if not isinstance(self.ollama_model, str) or not self.ollama_model.strip():
            self.ollama_model = "llama3.1:8b"

    def _cleanup_suppress_tokens(self) -> None:
        """Entfernt ungültige Token‑IDs aus der Suppress‑Tokens‑Liste."""
        if self.suppress_tokens:
            tokens = [t.strip() for t in self.suppress_tokens.split(",") if t.strip()]
            if tokens:
                valid = []
                for t in tokens:
                    try:
                        int(t)
                        valid.append(t)
                    except ValueError:
                        logger.warning(f"Ungültiger Suppress‑Token '{t}' ignoriert")
                self.suppress_tokens = ", ".join(valid) if valid else "-1"
            else:
                self.suppress_tokens = "-1"

    def _clamp_confidence_values(self) -> None:
        """Klemmt min_confidence und min_language_confidence auf [0.0, 1.0]."""
        if self.min_confidence < 0.0 or self.min_confidence > 1.0:
            old = self.min_confidence
            self.min_confidence = max(0.0, min(self.min_confidence, 1.0))
            logger.warning(
                f"Min‑Konfidenz {old} außerhalb [0.0, 1.0], geklemmt auf {
                    self.min_confidence
                }",
            )

        if self.min_language_confidence < 0.0 or self.min_language_confidence > 1.0:
            old = self.min_language_confidence
            self.min_language_confidence = max(
                0.0,
                min(self.min_language_confidence, 1.0),
            )
            logger.warning(
                f"Min‑Sprachkonfidenz {old} außerhalb [0.0, 1.0], "
                f"geklemmt auf {self.min_language_confidence}",
            )

    def _clamp_vad_threshold(self) -> None:
        """Stellt sicher, dass der VAD‑Schwellwert im Bereich [0.0, 1.0] liegt."""
        if self.vad_threshold < 0.0 or self.vad_threshold > 1.0:
            old = self.vad_threshold
            self.vad_threshold = max(0.0, min(self.vad_threshold, 1.0))
            logger.warning(
                f"VAD‑Schwellwert {old} außerhalb [0.0, 1.0], geklemmt auf {
                    self.vad_threshold
                }",
            )

    def _clamp_duplicate_threshold(self) -> None:
        """Klemmt die Duplikat‑Schwelle auf [0.0, 1.0]."""
        if (
            self.duplicate_similarity_threshold < 0.0
            or self.duplicate_similarity_threshold > 1.0
        ):
            old = self.duplicate_similarity_threshold
            self.duplicate_similarity_threshold = max(
                0.0,
                min(self.duplicate_similarity_threshold, 1.0),
            )
            logger.warning(
                f"Duplikat‑Schwelle {old} außerhalb [0.0, 1.0], "
                f"geklemmt auf {self.duplicate_similarity_threshold}",
            )

