def _cleanup_old_crash_logs(config_dir: Path, keep: int = 2) -> None:
    """Löscht alte Crash-Logs, behält die letzten ``keep`` Paare (.log + .json)."""
    import logging as _lg

    _log = _lg.getLogger("dragon")

    try:
        if not config_dir.exists():
            return

        entries: list[tuple[float, Path, Path]] = []
        try:
            for _p in config_dir.iterdir():
                if not _p.is_file():
                    continue
                if not _p.name.startswith("crash_"):
                    continue
                if _p.suffix not in (".log", ".json"):
                    continue

                if _p.suffix == ".log":
                    _paired = _p.with_suffix(".json")
                else:
                    _paired = _p.with_suffix(".log")

                try:
                    _mtime = _p.stat().st_mtime
                except OSError:
                    continue

                entries.append((_mtime, _p, _paired if _paired.exists() else _p))
        except OSError:
            return

        unique: dict[str, tuple[float, Path, Path]] = {}
        for _mt, _a, _b in entries:
            _key = str(_a)
            if _key not in unique or _mt > unique[_key][0]:
                unique[_key] = (_mt, _a, _b)

        sorted_entries = sorted(unique.values(), key=lambda x: x[0], reverse=True)

        for _mt, _primary, _secondary in sorted_entries[keep:]:
            for _p in {_primary, _secondary}:
                try:
                    if _p.exists():
                        _p.unlink()
                        _log.debug("Alter Crash-Log gelöscht: %s", _p.name)
                except Exception as _e:
                    _log.debug("Konnte %s nicht löschen: %s", _p, _e)
    except Exception:
        pass


def global_exception_handler(exc_type, exc_value, exc_traceback):
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
        return
    logger.critical(
        "Unhandled exception in main thread",
        exc_info=(exc_type, exc_value, exc_traceback),
    )
    try:
        import tkinter.messagebox as mb

        mb.showerror(
            "Dragon Whisperer - Unerwarteter Fehler",
            f"Ein unerwarteter Fehler ist aufgetreten:\n\n{exc_value}\n\nDetails in der Konsole.",
        )
    except Exception as e:
        logger.debug("Ignored exception: %s", e, exc_info=True)
    sys.__excepthook__(exc_type, exc_value, exc_traceback)


def thread_exception_handler(args):
    logger.critical(
        f"Unhandled exception in thread {args.thread.name}: {args.exc_value}",
        exc_info=(args.exc_type, args.exc_value, args.exc_traceback),
    )


sys.excepthook = global_exception_handler
threading.excepthook = thread_exception_handler


def configure_logging(
    debug_level: int,
    debug_components: list[str],
    quiet: bool,
) -> None:
    """Konfiguriert das Logging basierend auf Debug‑Level und Quiet‑Modus."""
    if quiet:
        log_level = logging.ERROR
    elif debug_level >= 1:
        log_level = logging.DEBUG
    else:
        log_level = logging.WARNING

    logging.basicConfig(
        level=log_level,
        format="[%(asctime)s.%(msecs)03d] [%(levelname)s] %(message)s",
        datefmt="%H:%M:%S",
    )

    if not logging.getLogger().handlers:
        logging.getLogger().addHandler(logging.StreamHandler(sys.stdout))

    dragonlogger = logging.getLogger("dragon")
    dragonlogger.setLevel(log_level)

    for lib in ["huggingface_hub", "faster_whisper", "httpx", "urllib3", "httpcore"]:
        logging.getLogger(lib).setLevel(logging.WARNING)

    debug_filter = DebugFilter(
        enable_metrics=False,
        rate_limit=0.0,
        debug_level=debug_level,
        debug_components=debug_components,
        log_filter_decisions=False,
        allow_debug_without_component=True,
    )
    dragonlogger.addFilter(debug_filter)
    logging.getLogger().addFilter(debug_filter)

    if debug_level >= 3:
        for handler in logging.getLogger().handlers:
            for filt in list(handler.filters):
                if isinstance(filt, DebugFilter):
                    handler.removeFilter(filt)
        for name in [
            "dragon",
            "ytdlp",
            "ffmpeg",
            "processor",
            "stream",
            "cache",
            "pending",
        ]:
            logging.getLogger(name).setLevel(logging.DEBUG)

    if debug_level >= 1:
        dragonlogger.setLevel(logging.DEBUG)
        for _h in dragonlogger.handlers[:]:
            dragonlogger.removeHandler(_h)
        dragonlogger.propagate = True

    if debug_level >= 2:
        dragonlogger.debug(
            "Logging konfiguriert: level=%s, debug_level=%d, components=%s, quiet=%s",
            logging.getLevelName(log_level),
            debug_level,
            debug_components,
            quiet,
        )


def setup_platform_environment(debug_level: int = 0) -> None:
    """Richtet plattformspezifische Umgebungen ein."""
    if IS_WINDOWS:
        try:
            if hasattr(PlatformUtils, "_setup_windows_console"):
                PlatformUtils._setup_windows_console(debug_level)
            else:
                _setup_windows_console(debug_level)
        except Exception as e:
            logger.warning("Windows‑Konsolen‑Setup fehlgeschlagen: %s", e)
    PlatformUtils.setup_platform_environment()


def run_tests() -> int:
    """Führt alle internen Unit‑Tests aus und gibt 0 bei Erfolg, sonst 1 zurück."""
    import importlib
    import logging
    import os
    import queue
    import tempfile
    import threading
    import time
    from collections import deque

    TORCH_AVAILABLE = importlib.util.find_spec("torch") is not None
    DEEP_TRANSLATOR_AVAILABLE = importlib.util.find_spec("deep_translator") is not None
    NUMPY_AVAILABLE = importlib.util.find_spec("numpy") is not None
    RAPIDFUZZ_AVAILABLE = importlib.util.find_spec("rapidfuzz") is not None

    _LOG_TARGETS = (
        "",
        "dragon",
        "huggingface_hub",
        "faster_whisper",
        "httpx",
        "urllib3",
        "httpcore",
    )
    _saved_levels: dict[str, int] = {}

    def _silence_loggers() -> None:
        for name in _LOG_TARGETS:
            lg = logging.getLogger(name) if name else logging.getLogger()
            _saved_levels[name or "__root__"] = lg.level
            lg.setLevel(logging.ERROR)

    def _restore_loggers() -> None:
        for key, level in _saved_levels.items():
            name = "" if key == "__root__" else key
            lg = logging.getLogger(name) if name else logging.getLogger()
            lg.setLevel(level)

