_is_windows_terminal_cache: bool | None = None
_platform_string_cache: str | None = None
_container_type_cache: str | None = None


def _is_windows_terminal(debug_level: int = 0) -> bool:
    """Erkennt zuverlässig moderne Windows‑Terminals (Unterstützung für Emojis) – mit Cache."""
    global _is_windows_terminal_cache
    if _is_windows_terminal_cache is not None:
        return _is_windows_terminal_cache

    if not sys.platform.startswith("win"):
        _is_windows_terminal_cache = False
        return False

    if os.environ.get("WT_SESSION"):
        if debug_level >= 4:
            log_debug("welcome", "Windows Terminal erkannt (WT_SESSION)")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("TERM_PROGRAM") == "vscode":
        if debug_level >= 4:
            log_debug("welcome", "VS Code Terminal erkannt (TERM_PROGRAM=vscode)")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("CONEMUPID"):
        if debug_level >= 4:
            log_debug("welcome", "ConEmu/Cmder erkannt (CONEMUPID)")
        _is_windows_terminal_cache = True
        return True

    ps_module_path = os.environ.get("PSMODULEPATH", "")
    if "powershell" in ps_module_path.lower():
        if debug_level >= 4:
            log_debug("welcome", "PowerShell erkannt → Emojis möglich")
        _is_windows_terminal_cache = True
        return True

    term = os.environ.get("TERM", "").lower()
    if term in ("xterm", "xterm-256color", "cygwin") and shutil.which("mintty"):
        if debug_level >= 4:
            log_debug("welcome", "Mintty (Git Bash) erkannt")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("TERM", "").endswith("256color"):
        if debug_level >= 4:
            log_debug("welcome", "TERM mit 256 Farben → Emojis wahrscheinlich")
        _is_windows_terminal_cache = True
        return True

    if debug_level >= 4:
        log_debug(
            "welcome",
            "Altes CMD oder nicht unterstütztes Terminal → Emojis deaktiviert",
        )
    _is_windows_terminal_cache = False
    return False


def _get_platform_string() -> str:
    """Erzeugt einen lesbaren Plattform‑String mit Architektur und Container‑Info (gecached)."""
    global _platform_string_cache
    if _platform_string_cache is not None:
        return _platform_string_cache

    import platform

    base = platform.system()
    arch = "ARM" if platform.machine().lower() in ("arm64", "aarch64") else "x86"
    info = f"{base} {arch}"
    container = _get_container_type()
    if container != "none":
        info += f" ({container.upper()})"
    _platform_string_cache = info
    return info


def _get_container_type() -> str:
    """Ermittelt den Containertyp (docker, wsl, flatpak, snap) – mit Cache."""
    global _container_type_cache
    if _container_type_cache is not None:
        return _container_type_cache

    import platform

    if os.path.exists("/.dockerenv"):
        _container_type_cache = "docker"
        return "docker"
    try:
        with open("/proc/1/cgroup") as f:
            if any("docker" in line for line in f):
                _container_type_cache = "docker"
                return "docker"
            if any("lxc" in line for line in f):
                _container_type_cache = "lxc"
                return "lxc"
    except Exception as e:
        logger.debug("Ignored exception: %s", e, exc_info=True)
    if (
        "WSL_DISTRO_NAME" in os.environ
        or "microsoft" in platform.uname().release.lower()
    ):
        _container_type_cache = "wsl"
        return "wsl"
    if "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ:
        _container_type_cache = "flatpak"
        return "flatpak"
    if "SNAP" in os.environ or "SNAP_NAME" in os.environ:
        _container_type_cache = "snap"
        return "snap"
    _container_type_cache = "none"
    return "none"


def extract_debug_info(args: argparse.Namespace) -> tuple[int, list[str]]:
    """Extrahiert Debug-Level und -Komponenten aus den akkumulierten --debug-Argumenten."""
    import contextlib
    import logging
    import os

    debug_level: int = 0
    debug_components: list[str] = []
    all_components_requested: bool = False
    raw_items: list[str] = []

    if hasattr(args, "debug") and args.debug:
        if isinstance(args.debug, list):
            raw_items = args.debug
        elif isinstance(args.debug, str):
            raw_items = [args.debug]
        else:
            raw_items = [str(args.debug)]

    if hasattr(args, "debug_level") and args.debug_level is not None:
        with contextlib.suppress(ValueError, TypeError):
            debug_level = max(debug_level, int(args.debug_level))

    def _parse_item(item: str) -> None:
        nonlocal debug_level, all_components_requested
        item = item.strip()
        if not item:
            return

        if item.lower() == "all":
            all_components_requested = True
            debug_level = max(debug_level, 3)
            return

        if item.isdigit():
            with contextlib.suppress(ValueError):
                level = int(item)
                debug_level = max(debug_level, level)
            return

        if "," in item:
            for part in item.split(","):
                _parse_item(part.strip())
            return

        debug_components.append(item.lower())

    for item in raw_items:
        if not isinstance(item, str):
            continue
        _parse_item(item)

    env_debug = os.environ.get("DRAGON_DEBUG", "").strip()
    if env_debug:
        for part in env_debug.split(","):
            _parse_item(part.strip())

    if all_components_requested:
        debug_components.extend(ALL_DEBUG_COMPONENTS)
    debug_components = sorted(set(debug_components))
    unknown = [c for c in debug_components if c not in ALL_DEBUG_COMPONENTS]
    if unknown:
        log = logging.getLogger("dragon")
        log.warning(f"⚠️ Unbekannte Debug-Komponente(n): {', '.join(unknown)}")
        log.info(
            f"   Verfügbare Komponenten: {', '.join(ALL_DEBUG_COMPONENTS[:10])}...",
        )

    if hasattr(args, "quiet") and args.quiet:
        debug_level = 0
        debug_components = []

    with contextlib.suppress(Exception):
        log = logging.getLogger("dragon")
        log.debug(
            "Debug-Konfiguration extrahiert: level=%d, components=%d (%s)",
            debug_level,
            len(debug_components),
            ", ".join(debug_components[:5])
            + ("..." if len(debug_components) > 5 else ""),
        )
    return debug_level, debug_components


def _write_crash_report(exception: BaseException, traceback_str: str) -> None:
    """Schreibt einen ausführlichen Crash-Report (.log + .json)."""
    import logging
    import os
    import sys
    import tempfile
    import time

    _logger = logging.getLogger("dragon")
    _debug = bool(os.environ.get("DW_DEBUG"))

    def _dbg(msg: str, *args) -> None:
        if _debug:
            with contextlib.suppress(Exception):
                _logger.debug(msg, *args)

    if isinstance(exception, (KeyboardInterrupt, SystemExit)):
        _dbg("[CRASH-REPORT] KeyboardInterrupt/SystemExit – überspringe Report")
        return

    try:
        exc_type = type(exception).__name__
        exc_msg = str(exception)[:200]
    except Exception:
        exc_type = "Unknown"
        exc_msg = ""

    _dbg(
        "[CRASH-REPORT] Start: type=%s, msg_len=%d, tb_len=%d",
        exc_type,
        len(exc_msg),
        len(traceback_str) if isinstance(traceback_str, str) else -1,
    )

    config_dir: Path
    try:
        config_dir = PlatformUtils.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
        _dbg("[CRASH-REPORT] Config-Dir: %s", config_dir)
    except (OSError, PermissionError, AttributeError) as e:
        try:
            config_dir = Path(tempfile.gettempdir()) / "dragon_crashes"
            config_dir.mkdir(parents=True, exist_ok=True)
            _logger.warning(
                "[CRASH-REPORT] Config-Dir nicht verfügbar (%s) – Fallback auf %s",
                type(e).__name__,
                config_dir,
            )
        except Exception as e2:
            _logger.error(
                "[CRASH-REPORT] Auch Fallback-Dir fehlgeschlagen: %s – "
                "kein Report möglich",
                e2,
            )
            return

    try:
        _cleanup_old_crash_logs(config_dir, keep=2)
        _dbg("[CRASH-REPORT] Cleanup abgeschlossen (keep=2)")
    except Exception as cleanup_exc:
        _dbg(
            "[CRASH-REPORT] Cleanup fehlgeschlagen (ignoriert): %s",
            cleanup_exc,
        )

    timestamp = time.strftime("%Y%m%d_%H%M%S")
    crash_file = config_dir / f"crash_{timestamp}.log"
    json_file = config_dir / f"crash_{timestamp}.json"

    _sensitive_keywords = (
        "key",
        "token",
        "secret",
        "password",
        "passwd",
        "pwd",
        "auth",
        "credential",
        "ssh",
        "aws",
        "gcp",
        "azure",
        "jwt",
        "bearer",
        "api_key",
        "private",
    )

    def _is_sensitive(k: str) -> bool:
        kl = k.lower()
        return any(s in kl for s in _sensitive_keywords)

    safe_env: dict[str, str] = {}
    try:
        for k, v in os.environ.items():
            if not _is_sensitive(k):
                safe_env[k] = v
    except Exception:
        pass

    system_info: dict = {
        "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        "exception_type": exc_type,
        "exception_message": exc_msg,
        "traceback": (
            traceback_str[:200000]
            if isinstance(traceback_str, str)
            else "(kein Traceback)"
        ),
        "platform": sys.platform,
        "python_version": sys.version,
        "python_executable": sys.executable,
        "cpu_count": os.cpu_count(),
        "working_directory": os.getcwd(),
        "command_line": sys.argv,
        "environment": safe_env,
    }

    try:
        import psutil

        try:
            mem = psutil.virtual_memory()
            system_info["memory_total_gb"] = round(mem.total / (1024**3), 2)
            system_info["memory_available_gb"] = round(mem.available / (1024**3), 2)
        except (OSError, AttributeError):
            pass
        try:
            disk = psutil.disk_usage(str(config_dir))
            system_info["disk_free_gb"] = round(disk.free / (1024**3), 2)
        except (OSError, AttributeError):
            pass
        with contextlib.suppress(OSError, AttributeError):
            system_info["cpu_percent"] = psutil.cpu_percent(interval=0.1)
    except ImportError:
        _dbg("[CRASH-REPORT] psutil nicht verfügbar – überspringe Metriken")

    try:
        with open(crash_file, "w", encoding="utf-8") as f:
            f.write("=" * 80 + "\n")
            f.write("DRAGON WHISPERER CRASH REPORT\n")
            f.write(f"Time: {system_info['time']}\n")
            f.write(
                f"Exception: {system_info['exception_type']}: "
                f"{system_info['exception_message']}\n"
            )
            f.write("=" * 80 + "\n\n")
            f.write("TRACEBACK:\n")
            f.write(system_info["traceback"])
            f.write("\n\n" + "=" * 80 + "\n")
            f.write("SYSTEM INFORMATION:\n")
            for key, value in system_info.items():
                if key in (
                    "traceback",
                    "exception_type",
                    "exception_message",
                ):
                    continue
                if isinstance(value, dict):
                    f.write(f"\n{key}:\n")
                    for k, v in value.items():
                        f.write(f"  {k}: {v}\n")
                else:
                    f.write(f"{key}: {value}\n")
        _logger.info("📄 Crash-Report gespeichert: %s", crash_file)
    except (OSError, PermissionError) as e:
        _logger.warning("⚠️ Crash-Report (.log) fehlgeschlagen: %s", e)
    except Exception as e:
        _logger.warning(
            "⚠️ Crash-Report (.log) – unerwarteter Fehler: %s",
            e,
            exc_info=bool(_debug),
        )

    try:
        import json

        with open(json_file, "w", encoding="utf-8") as f:
            json.dump(
                system_info,
                f,
                indent=2,
                default=str,
                ensure_ascii=False,
            )
        _dbg("📄 JSON-Crash-Report gespeichert: %s", json_file)
    except (OSError, PermissionError) as e:
        _dbg("⚠️ Crash-Report (.json) fehlgeschlagen: %s", e)
    except Exception as e:
        _dbg(
            "⚠️ Crash-Report (.json) – unerwarteter Fehler: %s",
            e,
        )

    _dbg("[CRASH-REPORT] Fertig")


def _global_crash_handler(
    exc_type: type,
    exc_value: BaseException,
    exc_tb: Any,
    debug_level: int,
) -> None:
    """Globaler Exception‑Handler, der einen Crash‑Report erstellt und loggt."""
    tb_str = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
    if not issubclass(exc_type, KeyboardInterrupt):
        _write_crash_report(exc_value, tb_str)
        if debug_level >= 1:
            logger.critical("Unhandled exception:\n%s", tb_str)
    sys.__excepthook__(exc_type, exc_value, exc_tb)


def _log_debug_welcome_info(debug_level: int, use_emoji: bool, quiet: bool) -> None:
    """Protokolliert detaillierte System‑ und Debug‑Informationen bei Debug‑Level >= 3."""
    if debug_level < 3:
        return

    import platform

    log_debug("welcome", "=" * 60)
    log_debug("welcome", "🐉 DEBUG: _print_welcome - Detaillierte Diagnose")
    log_debug("welcome", "=" * 60)

    log_debug("welcome", f"Debug-Level        : {debug_level}")
    log_debug("welcome", f"Quiet-Modus        : {quiet}")
    log_debug("welcome", f"Emoji aktiviert    : {use_emoji}")
    log_debug("welcome", f"stdout.isatty()    : {sys.stdout.isatty()}")
    log_debug("welcome", f"stdout.encoding    : {sys.stdout.encoding or 'UNKNOWN'}")
    log_debug("welcome", f"stdin.encoding     : {sys.stdin.encoding or 'UNKNOWN'}")
    log_debug("welcome", f"stderr.encoding    : {sys.stderr.encoding or 'UNKNOWN'}")

    env_vars = (
        "TERM",
        "LANG",
        "WT_SESSION",
        "COLORTERM",
        "PYTHONIOENCODING",
        "TERM_PROGRAM",
        "ConEmuPID",
        "WSL_DISTRO_NAME",
    )
    for var in env_vars:
        value = os.environ.get(var, "nicht gesetzt")
        log_debug("welcome", f"${var:20} : {value}")

    log_debug("welcome", f"SYSTEM             : {platform.system()}")
    log_debug("welcome", f"IS_WINDOWS         : {sys.platform.startswith('win')}")
    log_debug("welcome", f"IS_MACOS           : {sys.platform == 'darwin'}")
    log_debug("welcome", f"IS_LINUX           : {sys.platform.startswith('linux')}")
    log_debug(
        "welcome",
        f"IS_ARM             : {platform.machine().lower() in ('arm64', 'aarch64')}",
    )
    log_debug(
        "welcome",
        f"IS_X86             : {platform.machine().lower() in ('x86_64', 'amd64')}",
    )
    log_debug("welcome", f"platform.uname()   : {platform.uname()}")
    log_debug("welcome", f"Python-Version     : {sys.version}")
    log_debug("welcome", f"Python-Executable  : {sys.executable}")

    enc_info = _get_encoding_info()
    for key, value in enc_info.items():
        log_debug("welcome", f"encoding_{key:20} : {value or 'UNKNOWN'}")

    log_debug("welcome", "-" * 60)
    log_debug("welcome", "Emoji-Entscheidung im Detail:")

    if not sys.stdout.isatty():
        log_debug("welcome", "  ❌ stdout ist kein TTY → Emojis deaktiviert")
    elif sys.platform.startswith("win") and not _is_windows_terminal(debug_level):
        log_debug(
            "welcome",
            "  ❌ Windows: Kein modernes Terminal → Emojis deaktiviert",
        )
    elif (sys.stdout.encoding or "unknown").lower() not in ("utf-8", "utf8"):
        log_debug(
            "welcome",
            f"  ❌ Kodierung {sys.stdout.encoding} nicht UTF-8 → Emojis deaktiviert",
        )
    elif os.environ.get("TERM", "").lower() in ("dumb", "unknown", ""):
        log_debug(
            "welcome",
            f"  ❌ TERM={os.environ.get('TERM', 'nicht gesetzt')} → Emojis deaktiviert",
        )
    else:
        log_debug("welcome", "  ✅ Alle Prüfungen bestanden → Emojis aktiviert")

    log_debug("welcome", "=" * 60)


def _get_encoding_info() -> dict[str, str | None]:
    """Sammelt alle relevanten Kodierungsinformationen des Systems."""
    import locale

    def safe_encoding(enc: str | None) -> str | None:
        return enc or None

    return {
        "stdin_encoding": safe_encoding(sys.stdin.encoding),
        "stdout_encoding": safe_encoding(sys.stdout.encoding),
        "stderr_encoding": safe_encoding(sys.stderr.encoding),
        "locale_preferred": safe_encoding(locale.getpreferredencoding()),
        "filesystem_encoding": safe_encoding(sys.getfilesystemencoding()),
        "default_encoding": safe_encoding(sys.getdefaultencoding()),
    }


def _show_critical_error(message: str, *, timeout: int = 10) -> bool:
    """Zeigt eine kritische Fehlermeldung an (GUI oder Konsole).
    Gibt True zurück, wenn die Meldung erfolgreich angezeigt wurde, sonst False.
    """
    import contextlib
    import logging
    import sys

    logger = logging.getLogger("dragon")
    debug_level = getattr(logger, "debug_level", 0)

    if not message:
        return False
    with contextlib.suppress(Exception):
        print(f"\n💥 KRITISCHER FEHLER: {message}", file=sys.stderr)

    short_msg = message[:200] + "..." if len(message) > 200 else message
    if GUI_AVAILABLE:
        try:
            import tkinter as tk

            root = None
            if tk._default_root is not None and tk._default_root.winfo_exists():
                root = tk._default_root
            dark_msg_box = globals().get("DarkMessageBox")
            if dark_msg_box is not None:
                dark_msg_box.showerror(
                    "Kritischer Fehler",
                    f"{short_msg}\n\nDie Anwendung wird möglicherweise nicht korrekt funktionieren.",
                    parent=root,
                    timeout=timeout,
                )
                return True
            import tkinter.messagebox as mb

            mb.showerror("Kritischer Fehler", short_msg, parent=root)
            return True
        except Exception as e:
            logger.error(
                f"GUI-Fehleranzeige fehlgeschlagen: {e}",
                exc_info=debug_level >= 3,
            )
    if IS_WINDOWS:
        try:
            import ctypes

            ctypes.windll.user32.MessageBoxW(
                0,
                f"Dragon Whisperer - Critical Error\n\n{short_msg}",
                "Critical Error",
                0x10,
            )
            return True
        except Exception as e:
            logger.error(
                f"Windows-MessageBox fehlgeschlagen: {e}",
                exc_info=debug_level >= 3,
            )

    return True


def _setup_early_environment() -> None:
    """Setzt frühzeitig Umgebungsvariablen für maximale Kompatibilität."""
    os.environ.setdefault("LOKY_PURGE", "1")
    os.environ.setdefault(
        "JOBLIB_START_METHOD",
        "fork" if not sys.platform.startswith("win") else "spawn",
    )
    if "LOKY_MAX_WORKERS" not in os.environ:
        cpu_count = os.cpu_count() or 2
        os.environ["LOKY_MAX_WORKERS"] = str(max(1, cpu_count // 2))
    os.environ.setdefault("PYDANTIC_IGNORE_CORE_MISMATCH", "1")
    os.environ.setdefault("PYTHONUNBUFFERED", "1")
    if sys.platform.startswith("win"):
        os.environ.setdefault("PYTHONLEGACYWINDOWSSTDIO", "1")


def _validate_and_repair_environment(debug_level: int) -> list[str]:
    """Führt Umgebungsvalidierungen und -reparaturen durch."""
    repairs = []
    config_dir = PlatformUtils.get_platform_config_dir()
    adv_file = config_dir / "dragon_advanced_settings.json"
    if adv_file.exists() and adv_file.stat().st_size == 0:
        try:
            adv_file.unlink()
            repairs.append("Leere AdvancedSettings‑Datei gelöscht")
        except (OSError, PermissionError) as e:
            logger.debug("Could not delete empty settings file: %s", e)
    try:
        with tempfile.NamedTemporaryFile(delete=False) as test_file:
            test_file.close()
            os.unlink(test_file.name)
    except (PermissionError, OSError):
        user_temp = Path.home() / ".cache" / "dragon_temp"
        user_temp.mkdir(parents=True, exist_ok=True)
        tempfile.tempdir = str(user_temp)
        repairs.append(f"Temp‑Verzeichnis auf {user_temp} umgestellt")

    if sys.platform.startswith("win") and os.environ.get("PYTHONIOENCODING") != "utf-8":
        os.environ["PYTHONIOENCODING"] = "utf-8"
        repairs.append("PYTHONIOENCODING auf utf-8 gesetzt")
    return repairs


def _check_gpu_health() -> tuple[bool, str]:
    """Prüft die GPU‑Verfügbarkeit und den freien VRAM."""
    if not TORCH_AVAILABLE:
        return False, "PyTorch nicht installiert"
    try:
        import torch

        if not torch.cuda.is_available():
            return False, "Keine CUDA‑fähige GPU gefunden"
        try:
            free, _total = torch.cuda.mem_get_info()
        except AttributeError:
            free = torch.cuda.memory_allocated()
            _total = torch.cuda.get_device_properties(0).total_memory
        free_gb = free / (1024**3)
        if free_gb < 0.5:
            return False, f"VRAM fast voll ({free_gb:.1f} GB frei)"
        device_name = torch.cuda.get_device_name(0)
        return True, f"✅ {device_name}, {free_gb:.1f} GB frei"
    except (ImportError, AttributeError, RuntimeError) as e:
        return False, f"GPU‑Fehler: {e}"


def _repair_configuration() -> list[str]:
    """Setzt eine beschädigte Konfiguration zurück und erstellt eine neue."""
    repairs = []
    config_dir = PlatformUtils.get_platform_config_dir()
    adv_file = config_dir / "dragon_advanced_settings.json"
    if adv_file.exists():
        backup = adv_file.with_suffix(".json.broken")
        try:
            os.replace(str(adv_file), str(backup))
            repairs.append(f"Defekte Konfiguration nach {backup.name} verschoben")
        except (OSError, PermissionError) as e:
            logger.warning("Could not backup broken config: %s", e)
    AdvancedSettings.invalidate_cache()
    repairs.append("Neue Standardkonfiguration wird erstellt")
    return repairs


def _cancel_executor_futures(executors: list[tuple[str, Any]]) -> None:
    """Bricht alle Futures in den übergebenen Executoren ab."""
    for name, exec_obj in executors:
        for futures_attr in ("_futures", "_active_futures", "_pending_work_items"):
            if hasattr(exec_obj, futures_attr):
                try:
                    container = getattr(exec_obj, futures_attr)
                    if isinstance(container, dict):
                        items = list(container.keys())
                    elif isinstance(container, (list, set)):
                        items = list(container)
                    else:
                        continue
                    for f in items:
                        if not f.done():
                            f.cancel()
                    container.clear()
                    if items:
                        logger.debug(
                            "  → %d Future(s) aus '%s' abgebrochen",
                            len(items),
                            name,
                        )
                except (AttributeError, RuntimeError) as e:
                    logger.debug("Error cancelling futures for %s: %s", name, e)


def _shutdown_executor_list(executors: list[tuple[str, Any]]) -> None:
    """Fährt eine Liste von Executoren herunter."""
    for name, exec_obj in executors:
        if exec_obj is None:
            logger.debug("  ⏭️ Executor '%s' ist None – überspringe", name)
            continue

        logger.debug("  ▶️ Shutdown Executor '%s' ...", name)
        try:
            safe_shutdown_executor(
                exec_obj,
                wait=True,
                cancel_futures=True,
                timeout=1.5,
                log_context=name,
            )
            logger.debug(
                "    → shutdown(wait=True, cancel_futures=True, "
                "timeout=1.5s) erfolgreich",
            )
        except Exception as e:
            logger.warning("    → shutdown fehlgeschlagen: %s", e)


def _join_priority_threads(timeout: float, start: float) -> None:
    """Beendet Threads nach Priorität (loky, ProcessPool, Transcribe, …)."""
    import contextlib
    import threading
    import time

    main_thread = threading.main_thread()
    current_thread = threading.current_thread()
    remaining = timeout - (time.monotonic() - start)

    if remaining <= 0:
        survivors = [
            t
            for t in threading.enumerate()
            if t is not main_thread and t is not current_thread and t.is_alive()
        ]
        if survivors:
            names = ", ".join(
                f"{t.name}(tid={t.ident}, daemon={t.daemon})" for t in survivors[:10]
            )
            extra = f" (+{len(survivors) - 10} weitere)" if len(survivors) > 10 else ""
            logger.warning(
                "⏰ Keine Zeit mehr für Thread-Joins – "
                "%d Thread(s) bleiben übrig: %s%s",
                len(survivors),
                names,
                extra,
            )
        else:
            logger.debug("⏰ Keine Zeit mehr für Thread-Joins – keine Survivor")
        return

    priority_groups = [
        "loky",
        "ProcessPool",
        "FasterWhisperTimeout",
        "Transcribe",
        "Translate",
        "FFmpeg",
        "TTSQueue",
        "CacheCleanup",
        "DVBMonitor",
        "Periodic",
        "tqdm_monitor",
        "other",
    ]

    thread_groups: dict[str, list[threading.Thread]] = {}

    for t in threading.enumerate():
        if t is main_thread or t is current_thread or not t.is_alive():
            continue

        name = t.name
        group = "other"
        for g in priority_groups:
            if name.startswith(g) or (g in name):
                group = g
                break
        thread_groups.setdefault(group, []).append(t)

    if not thread_groups:
        logger.debug("Keine joinbaren Threads gefunden")
        return

    sorted_groups = sorted(
        thread_groups.keys(),
        key=lambda g: (
            priority_groups.index(g) if g in priority_groups else 999,
            g,
        ),
    )

    logger.debug(
        "Thread-Gruppen: %s (insgesamt %d Threads)",
        sorted_groups,
        sum(len(v) for v in thread_groups.values()),
    )

    for group_name in sorted_groups:
        threads = thread_groups[group_name]
        if remaining <= 0:
            break

        per_thread_timeout = min(
            1.0,
            max(0.1, remaining / max(1, len(threads))),
        )
        logger.debug(
            "  Gruppe '%s': %d Thread(s), %.1fs pro Thread",
            group_name,
            len(threads),
            per_thread_timeout,
        )

        for t in threads:
            if not t.is_alive():
                continue

            if hasattr(t, "_stop_event") and callable(
                getattr(t._stop_event, "set", None),
            ):
                with contextlib.suppress(Exception):
                    t._stop_event.set()

            join_start = time.monotonic()
            try:
                t.join(timeout=per_thread_timeout)
            except RuntimeError as e:
                logger.warning(
                    "  → Join von '%s' fehlgeschlagen: %s",
                    t.name,
                    e,
                )
                continue
            except Exception as e:
                logger.warning(
                    "  → Unerwarteter Fehler beim Join von '%s': %s",
                    t.name,
                    e,
                )
                continue

            join_duration = time.monotonic() - join_start
            if t.is_alive():
                logger.debug(
                    "  → Thread '%s' nach %.1fs noch aktiv "
                    "(tid=%s, daemon=%s) – Join-Timeout",
                    t.name,
                    join_duration,
                    t.ident,
                    t.daemon,
                )
            else:
                logger.debug(
                    "  → Thread '%s' erfolgreich gejoint (%.1fs)",
                    t.name,
                    join_duration,
                )

            remaining = timeout - (time.monotonic() - start)

        if remaining > 0.1:
            time.sleep(0.05)

    still_alive = [
        t
        for t in threading.enumerate()
        if t is not main_thread and t is not current_thread and t.is_alive()
    ]

    if still_alive:
        names = ", ".join(
            f"{t.name}(tid={t.ident}, daemon={t.daemon})" for t in still_alive[:10]
        )
        extra = f" (+{len(still_alive) - 10} weitere)" if len(still_alive) > 10 else ""
        logger.warning(
            "%d Thread(s) konnten nicht beendet werden: %s%s",
            len(still_alive),
            names,
            extra,
        )
        _non_daemon = [t for t in still_alive if not t.daemon]
        if _non_daemon:
            logger.warning(
                "  → %d Thread(s) sind NICHT als daemon markiert – "
                "sie können `sys.exit()` blockieren. Der Force-Exit-Pfad "
                "muss ggf. `os._exit()` verwenden.",
                len(_non_daemon),
            )
    else:
        logger.debug(
            "  ✅ Alle Threads sauber beendet",
        )


def _kill_subprocesses(
    gui: Any | None,
    *,
    debug_level: int = 0,
    force_kill: bool = False,
    timeout: float = 2.0,
) -> None:
    """Beendet alle noch laufenden Subprozesse (FFmpeg, yt‑dlp, etc.) und räumt
    temporäre Dateien auf – ultimative, vollständige Version mit Debug-Unterstützung.
    """
    if gui is None:
        if debug_level >= 1:
            logger.debug("_kill_subprocesses: gui ist None – nichts zu tun")
        return

    log_debug = logger.debug
    log_warning = logger.warning
    log_exception = logger.exception

    if debug_level >= 1:
        log_debug(
            "🔍 _kill_subprocesses: Starte Bereinigung (force_kill=%s, timeout=%.1fs)",
            force_kill,
            timeout,
        )

    managers: set[Any] = set()
    ap = getattr(gui, "audio_processor", None)
    if ap is not None:
        ffmpeg = getattr(ap, "ffmpeg_manager", None)
        if ffmpeg is not None:
            managers.add(ffmpeg)
            if debug_level >= 2:
                log_debug(
                    "  → FFmpegManager aus AudioProcessor hinzugefügt (ID: %s)",
                    id(ffmpeg),
                )

    ffmpeg_mgr = getattr(gui, "ffmpeg_manager", None)
    if ffmpeg_mgr is not None:
        managers.add(ffmpeg_mgr)
        if debug_level >= 2:
            log_debug("  → FFmpegManager aus GUI hinzugefügt (ID: %s)", id(ffmpeg_mgr))

    if debug_level >= 1:
        log_debug("  → Insgesamt %d FFmpegManager-Instanz(en) gefunden", len(managers))

    for idx, mgr in enumerate(managers, 1):
        if not hasattr(mgr, "kill_all_streams"):
            if debug_level >= 2:
                log_debug(
                    "  ⏭️ Manager #%d hat keine kill_all_streams-Methode – übersprungen",
                    idx,
                )
            continue
        try:
            if debug_level >= 1:
                log_debug("  🔄 Manager #%d (ID: %s) wird beendet ...", idx, id(mgr))
            mgr.kill_all_streams()
            if debug_level >= 1:
                log_debug("  ✅ Manager #%d erfolgreich beendet", idx)
        except AttributeError as e:
            log_warning(
                "  ⚠️ Manager #%d hat keine kill_all_streams-Methode: %s",
                idx,
                e,
            )
            if debug_level >= 3:
                log_exception("  🔍 Stacktrace:", exc_info=True)
        except (OSError, RuntimeError, subprocess.SubprocessError) as e:
            log_warning("  ⚠️ Fehler beim Beenden von Manager #%d: %s", idx, e)
            if debug_level >= 3:
                log_exception("  🔍 Stacktrace:", exc_info=True)
        except Exception:
            log_exception("  ❌ Unerwarteter Fehler beim Beenden von Manager #%d", idx)
            if debug_level >= 3:
                log_exception("  🔍 Stacktrace:")

    resource_mgr = getattr(gui, "resource_manager", None)
    if resource_mgr is not None and hasattr(resource_mgr, "cleanup"):
        try:
            if debug_level >= 1:
                log_debug(
                    "  🧹 ResourceManager-Cleanup wird gestartet (timeout=%.1fs)",
                    timeout,
                )
            resource_mgr.cleanup(timeout=timeout)
            if debug_level >= 1:
                log_debug("  ✅ ResourceManager-Cleanup erfolgreich")
        except (OSError, RuntimeError) as e:
            log_warning("  ⚠️ Fehler im ResourceManager-Cleanup: %s", e)
            if debug_level >= 3:
                log_exception("  🔍 Stacktrace:", exc_info=True)
        except Exception:
            log_exception("  ❌ Unerwarteter Fehler im ResourceManager-Cleanup")
            if debug_level >= 3:
                log_exception("  🔍 Stacktrace:")

    _cleanup_temp_files(gui, debug_level=debug_level)

    if force_kill:
        _kill_orphaned_subprocesses(debug_level=debug_level)

    if debug_level >= 1:
        log_debug("✅ _kill_subprocesses abgeschlossen")


def _cleanup_temp_files(gui: Any | None, *, debug_level: int = 0) -> None:
    """Löscht alle registrierten temporären Dateien aus dem AudioProcessor und der GUI."""
    if gui is None:
        return

    log_debug = logger.debug
    log_warning = logger.warning
    log_exception = logger.exception

    if debug_level >= 1:
        log_debug("  🗑️ Bereinigung temporärer Dateien gestartet")

    ap = getattr(gui, "audio_processor", None)
    if ap is not None:
        cleanup_method = getattr(ap, "_cleanup_temp_files", None)
        if callable(cleanup_method):
            try:
                if debug_level >= 2:
                    log_debug("    → Rufe AudioProcessor._cleanup_temp_files() auf")
                cleanup_method()
                if debug_level >= 1:
                    log_debug("  ✅ Temporäre Dateien des AudioProcessors gelöscht")
            except (OSError, PermissionError, FileNotFoundError) as e:
                log_warning(
                    "  ⚠️ Fehler beim Löschen von Temp‑Dateien (AudioProcessor): %s",
                    e,
                )
                if debug_level >= 3:
                    log_exception("  🔍 Stacktrace:", exc_info=True)
            except Exception:
                log_exception(
                    "  ❌ Unerwarteter Fehler beim Löschen von Temp‑Dateien (AudioProcessor)",
                )
                if debug_level >= 3:
                    log_exception("  🔍 Stacktrace:")

    temp_files = getattr(gui, "_temp_files", None)
    if isinstance(temp_files, list):
        total = len(temp_files)
        if debug_level >= 1:
            log_debug("    → %d GUI-Temp-Datei(en) gefunden", total)

        deleted = 0
        for file_path in temp_files[:]:
            if not isinstance(file_path, str):
                if debug_level >= 2:
                    log_debug(
                        "      ⏭️ Überspringe ungültigen Temp‑Eintrag: %r",
                        file_path,
                    )
                continue
            try:
                if os.path.exists(file_path):
                    os.remove(file_path)
                    deleted += 1
                    if debug_level >= 3:
                        log_debug("      🗑️ Gelöscht: %s", file_path)
            except (PermissionError, OSError, FileNotFoundError) as e:
                log_warning("      ⚠️ Konnte %s nicht löschen: %s", file_path, e)
                if debug_level >= 3:
                    log_exception("      🔍 Stacktrace:", exc_info=True)
            except Exception:
                log_exception(
                    "      ❌ Unerwarteter Fehler beim Löschen von %s",
                    file_path,
                )
                if debug_level >= 3:
                    log_exception("      🔍 Stacktrace:")

        temp_files.clear()
        if debug_level >= 1:
            log_debug(
                "  ✅ GUI‑Temp‑Dateien bereinigt (%d von %d gelöscht)",
                deleted,
                total,
            )
    elif debug_level >= 2:
        log_debug("  ℹ️ Keine GUI‑Temp‑Dateien zu löschen")


def _kill_orphaned_subprocesses(*, debug_level: int = 0) -> None:
    """Beendet alle verwaisten Subprozesse des aktuellen Prozesses (z.B. FFmpeg, yt-dlp).
    Verwendet psutil, falls verfügbar, sonst einen Fallback über die Betriebsbefehle.
    """
    log_debug = logger.debug
    log_warning = logger.warning
    log_exception = logger.exception

    if debug_level >= 1:
        log_debug("  🔍 Suche nach verwaisten Subprozessen ...")
    try:
        import psutil

        current = psutil.Process()
        children = current.children(recursive=True)
        if not children:
            if debug_level >= 2:
                log_debug("    → Keine verwaisten Subprozesse gefunden")
            return
        if debug_level >= 1:
            log_debug("    → %d verwaiste Subprozesse gefunden", len(children))

        for child in children:
            try:
                if debug_level >= 2:
                    log_debug("      → Beende PID %d (%s)", child.pid, child.name())

                child.terminate()
                try:
                    child.wait(timeout=1.0)
                    if debug_level >= 3:
                        log_debug("        ✅ PID %d beendet (SIGTERM)", child.pid)
                except psutil.TimeoutExpired:
                    child.kill()
                    child.wait(timeout=0.5)
                    if debug_level >= 3:
                        log_debug("        ✅ PID %d beendet (SIGKILL)", child.pid)

            except psutil.NoSuchProcess:
                if debug_level >= 3:
                    log_debug("        ⏭️ PID %d bereits beendet", child.pid)
            except psutil.AccessDenied as e:
                log_warning(
                    "        ⚠️ Keine Berechtigung für PID %d: %s",
                    child.pid,
                    e,
                )
            except (psutil.TimeoutExpired, OSError, RuntimeError) as e:
                log_exception(
                    "        ❌ Fehler beim Beenden von PID %d: %s",
                    child.pid,
                    e,
                )

    except ImportError:
        if sys.platform.startswith("win"):
            if debug_level >= 1:
                log_debug(
                    "    ℹ️ psutil nicht verfügbar und Windows – überspringe Orphan-Kill",
                )
            return

        if debug_level >= 1:
            log_debug("    ℹ️ psutil nicht verfügbar – verwende pkill-Fallback")

        try:
            if debug_level >= 2:
                log_debug("      → Führe pkill -9 -f '(ffmpeg|yt-dlp)' aus")
            subprocess.run(
                ["pkill", "-9", "-f", "(ffmpeg|yt-dlp)"],
                capture_output=True,
                timeout=2.0,
                check=False,
            )
            if debug_level >= 1:
                log_debug("    ✅ pkill-Fallback ausgeführt")
        except (OSError, subprocess.SubprocessError) as e:
            log_warning("    ⚠️ pkill-Fallback fehlgeschlagen: %s", e)
            if debug_level >= 3:
                log_exception("    🔍 Stacktrace:", exc_info=True)

    except (OSError, subprocess.SubprocessError) as e:
        log_exception(
            "    ❌ Unerwarteter Fehler beim Killen verwaister Prozesse: %s",
            e,
        )
        if debug_level >= 3:
            log_exception("    🔍 Stacktrace:", exc_info=True)
    except Exception:
        log_exception("    ❌ Kritischer Fehler beim Killen verwaister Prozesse")
        if debug_level >= 3:
            log_exception("    🔍 Stacktrace:", exc_info=True)


def _emit_shutdown_event(gui: DragonWhispererGUI | None) -> None:
    """Sendet ein Shutdown‑Event über den Event‑Bus (falls vorhanden)."""
    if gui is None:
        return
    event_bus = getattr(gui, "event_bus", None)
    if event_bus is None or not hasattr(event_bus, "emit"):
        return
    try:
        event_bus.emit("shutdown_completed", {"timestamp": time.time()})
        logger.debug("  ✅ Shutdown‑Event gesendet")
    except (AttributeError, TypeError, RuntimeError) as e:
        logger.warning(
            "  ⚠️ Fehler beim Senden des Shutdown‑Events: %s",
            e,
            exc_info=True,
        )
    except Exception:
        logger.exception("  ❌ Unerwarteter Fehler beim Senden des Shutdown‑Events")


def _perform_guaranteed_cleanup(
    gui: DragonWhispererGUI | None,
    timeout: float = 10.0,
) -> bool:
    """Führt eine garantierte Bereinigung aller Ressourcen durch."""
    start = time.monotonic()
    step_times: dict[str, float] = {}
    success = True

    def run_step(name: str, action: Callable[[], None], step_timeout: float) -> bool:
        """Führt einen einzelnen Bereinigungsschritt in einem separaten Thread aus."""
        t0 = time.monotonic()
        try:
            thread = threading.Thread(target=action, daemon=True)
            thread.start()
            thread.join(timeout=step_timeout)
            if thread.is_alive():
                logger.warning(
                    "  ⏰ Schritt '%s' überschritt Timeout (%.1fs)",
                    name,
                    step_timeout,
                )
                return False
            return True
        except Exception:
            logger.exception("  ❌ Fehler in Schritt '%s'", name)
            return False
        finally:
            step_times[name] = (time.monotonic() - t0) * 1000

    steps: list[tuple[str, Callable[[], None]]] = [
        ("loky_cleanup", _perform_loky_cleanup),
        ("gc_collect", gc.collect),
    ]

    if gui is not None:
        ap = getattr(gui, "audio_processor", None)
        if ap is not None and hasattr(ap, "dispose"):
            steps.append(("audio_processor_dispose", ap.dispose))
        if hasattr(gui, "dispose"):
            steps.append(("gui_dispose", gui.dispose))

    for step_name, action in steps:
        remaining = max(0.5, timeout - (time.monotonic() - start))
        step_timeout = min(3.0, remaining)
        if not run_step(step_name, action, step_timeout):
            success = False

    elapsed = time.monotonic() - start
    if elapsed >= timeout:
        logger.warning(
            "⏰ Gesamt‑Timeout (%.1fs) überschritten",
            timeout,
        )
        success = False

    if success or DEBUG_LEVEL >= 2:
        logger.info(
            "✅ Garantierte Bereinigung abgeschlossen in %.2f ms – Schritt‑Zeiten: %s",
            elapsed * 1000,
            ", ".join(f"{k}={v:.1f}ms" for k, v in step_times.items()),
        )
    return success


def _perform_loky_cleanup() -> None:
    """Ultimative, vereinheitlichte Bereinigung des loky‑Reusable‑Executors.
    Behebt Semaphore‑Leaks, beendet verbleibende Threads und Prozesse,
    bereinigt joblib‑Backend und führt Garbage‑Collection durch.
    """
    warnings.filterwarnings(
        "ignore",
        category=UserWarning,
        module="multiprocessing.resource_tracker",
    )

    def _set_daemon(thread: threading.Thread) -> None:
        """Setzt einen Thread als Daemon, ignoriert Fehler still."""
        with contextlib.suppress(RuntimeError, AttributeError):
            thread.daemon = True

    def _cleanup_executor(executor: Any, name: str = "executor") -> None:
        """Bereinigt einen einzelnen Executor – Futures abbrechen, Threads beenden."""
        if executor is None:
            return
        with contextlib.suppress(AttributeError):
            pending = list(executor._pending_work_items.keys())
            for future in pending:
                future.cancel()
            executor._pending_work_items.clear()
            if DEBUG_LEVEL >= 4:
                log_debug("loky", f"{len(pending)} Futures abgebrochen ({name})")

        with contextlib.suppress(AttributeError):
            inner = executor._executor
            if inner is not None:
                with contextlib.suppress(TypeError, AttributeError):
                    safe_shutdown_executor(inner, wait=False, cancel_futures=True)
                with contextlib.suppress(AttributeError):
                    inner.shutdown(wait=False)
                with contextlib.suppress(AttributeError):
                    for t in list(inner._threads):
                        if t.is_alive():
                            _set_daemon(t)
                    inner._threads.clear()
                executor._executor = None
                if DEBUG_LEVEL >= 4:
                    log_debug("loky", f"Innerer Executor bereinigt ({name})")

        with contextlib.suppress(TypeError, AttributeError):
            safe_shutdown_executor(executor, wait=False, cancel_futures=True)
        with contextlib.suppress(AttributeError):
            executor.shutdown(wait=False)
        with contextlib.suppress(AttributeError):
            executor._stop()
        with contextlib.suppress(AttributeError):
            for t in list(executor._threads):
                if t.is_alive():
                    _set_daemon(t)
            executor._threads.clear()
        with contextlib.suppress(AttributeError):
            executor._executor = None
        with contextlib.suppress(AttributeError):
            executor._shutdown = True
        if DEBUG_LEVEL >= 3:
            log_debug("loky", f"Executor {name} bereinigt")

    executor = None
    with contextlib.suppress(ImportError, AttributeError, OSError):
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if DEBUG_LEVEL >= 3 and executor is not None:
            log_debug("loky", "Reusable‑Executor gefunden")

    if executor is not None:
        _cleanup_executor(executor, "reusable")

    with contextlib.suppress(ImportError, AttributeError, OSError):
        import loky

        executor2 = getattr(loky, "_reusable_executor", None)
        if executor2 is not None and executor2 is not executor:
            _cleanup_executor(executor2, "direct")
        loky._reusable_executor = None
        if DEBUG_LEVEL >= 3:
            log_debug("loky", "loky._reusable_executor auf None gesetzt")

    loky_threads = [
        t for t in threading.enumerate() if t.name.startswith("loky") and t.is_alive()
    ]
    if loky_threads:
        if DEBUG_LEVEL >= 3:
            log_debug("loky", f"Beende {len(loky_threads)} loky‑Thread(s)...")
        for t in loky_threads:
            t.join(timeout=0.5)
            if t.is_alive():
                _set_daemon(t)
                if DEBUG_LEVEL >= 4:
                    log_debug("loky", f"Thread '{t.name}' als Daemon markiert")

    with contextlib.suppress(ImportError, AttributeError, OSError):
        import joblib

        backend = getattr(joblib, "_parallel_backend", None)
        if backend is not None:
            if hasattr(backend, "terminate"):
                with contextlib.suppress(RuntimeError, AttributeError):
                    backend.terminate()
            elif hasattr(backend, "shutdown"):
                with contextlib.suppress(RuntimeError, AttributeError):
                    backend.shutdown()
            joblib._parallel_backend = None
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "joblib parallel backend bereinigt")

    with contextlib.suppress(ImportError, AttributeError, OSError):
        import multiprocessing

        active = multiprocessing.active_children()
        if active:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "loky",
                    f"Terminiere {len(active)} Multiprocessing‑Prozesse...",
                )
            for p in active:
                with contextlib.suppress(OSError, RuntimeError):
                    p.terminate()
                    p.join(timeout=1.0)

    with contextlib.suppress(ImportError, AttributeError, OSError):
        import multiprocessing.resource_tracker as rt

        if hasattr(rt, "_resource_tracker") and hasattr(rt._resource_tracker, "stop"):
            rt._resource_tracker.stop()
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "Resource‑Tracker gestoppt")
        if hasattr(rt, "_resource_tracker") and hasattr(
            rt._resource_tracker,
            "_semaphores",
        ):
            rt._resource_tracker._semaphores.clear()
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "Semaphore‑Cache geleert")

    for _ in range(3):
        gc.collect()
    if DEBUG_LEVEL >= 3:
        log_debug("loky", "Garbage Collection (3x) durchgeführt")

    main_thread = threading.main_thread()
    for t in threading.enumerate():
        if t is not main_thread and not t.daemon and t.is_alive():
            _set_daemon(t)
            if DEBUG_LEVEL >= 4:
                log_debug("loky", f"Thread '{t.name}' als Daemon markiert")

    if DEBUG_LEVEL >= 2:
        log_debug("loky", "✅ Loky‑Cleanup abgeschlossen (Semaphore‑Leak behoben)")


@dataclass
class StartupConfig:
    debug_level: int = 0
    debug_components: list[str] = field(default_factory=list)
    quiet: bool = False
    headless: bool = False
    url: str | None = None
    profile: str | None = None
    model: str | None = None
    language: str | None = None
    benchmark: bool = False
    safe_mode: bool = False
    repair_config: bool = False
    check_gpu: bool = False
    crash_report: bool = True
    startup_timeout: float = 30.0
    shutdown_timeout: float = 15.0


def _run_benchmark() -> None:
    """Misst die Startzeiten der kritischen Initialisierungsphasen."""
    import json
    import os as _os
    import sys as _sys
    import time

    timings: dict[str, float] = {}
    start_total = time.perf_counter()

    def _phase(name: str, fn) -> bool:
        """Führt eine Benchmark-Phase aus und protokolliert die Dauer.

        Returns:
            True bei Erfolg, False bei Exception.
        """
        t0 = time.perf_counter()
        try:
            fn()
            dt = (time.perf_counter() - t0) * 1000.0
            timings[name] = dt
            print(
                f"[BENCHMARK] ✅ {name}: {dt:.2f} ms",
                file=_sys.stderr,
                flush=True,
            )
            return True
        except Exception as exc:
            dt = (time.perf_counter() - t0) * 1000.0
            timings[name] = dt
            print(
                f"[BENCHMARK] ❌ {name}: {dt:.2f} ms — {type(exc).__name__}: {exc}",
                file=_sys.stderr,
                flush=True,
            )
            return False

    print(
        "[BENCHMARK] ═══════════════════════════════════════════",
        file=_sys.stderr,
        flush=True,
    )
    print(
        "[BENCHMARK] Start — messe Initialisierungsphasen",
        file=_sys.stderr,
        flush=True,
    )
    print(
        "[BENCHMARK] ═══════════════════════════════════════════",
        file=_sys.stderr,
        flush=True,
    )

    _phase("early_env", _setup_early_environment)

    _args_holder: dict = {}

    def _parse_and_store() -> None:
        _args_holder["args"] = parse_arguments()

    if not _phase("parse_args", _parse_and_store):
        print(
            "[BENCHMARK] ❌ parse_args fehlgeschlagen — Abbruch",
            file=_sys.stderr,
            flush=True,
        )
        _os._exit(1)

    args = _args_holder.get("args")
    if args is None:
        print(
            "[BENCHMARK] ❌ args ist None — Abbruch",
            file=_sys.stderr,
            flush=True,
        )
        _os._exit(1)

    _debug_holder: dict = {"level": 0}

    def _extract_debug() -> None:
        level, _ = extract_debug_info(args)
        _debug_holder["level"] = level

    _phase("debug_extract", _extract_debug)
    debug_level = _debug_holder["level"]

    _phase("logging", lambda: configure_logging(debug_level, [], False))
    _phase("monkeypatch", lambda: None)

    _phase("platform", lambda: setup_platform_environment(debug_level))

    _phase("repair", lambda: _validate_and_repair_environment(debug_level))

    def _measure_tkinter_import() -> None:
        """Misst, ob Tkinter importierbar ist (Warm-Pfad)."""
        import importlib

        importlib.import_module("tkinter")

    _phase("tkinter_import", _measure_tkinter_import)

    timings["total"] = (time.perf_counter() - start_total) * 1000.0

    print(
        "[BENCHMARK] ═══════════════════════════════════════════",
        file=_sys.stderr,
        flush=True,
    )
    print(
        "[BENCHMARK] Ergebnis (alle Werte in ms):",
        file=_sys.stderr,
        flush=True,
    )
    print(json.dumps(timings, indent=2))
    print(
        "[BENCHMARK] ═══════════════════════════════════════════",
        file=_sys.stderr,
        flush=True,
    )

    print(
        "[BENCHMARK] os._exit(0)",
        file=_sys.stderr,
        flush=True,
    )
    _os._exit(0)


def _run_headless(args: argparse.Namespace, startup_config: StartupConfig) -> int:
    """Führt das Programm im Headless‑Modus (ohne GUI) aus.
    Gibt Transkriptionen und Übersetzungen auf der Konsole aus.
    """
    import logging
    import signal
    import sys
    import threading
    import time

    logger = logging.getLogger("dragon")
    logger.info("🐉 Starting in headless mode...")

    if not args.url:
        print("Error: --headless requires --url to specify a stream.", file=sys.stderr)
        return 1
    try:
        PlatformUtils.check_platform_dependencies()
    except RuntimeError as e:
        print(f"❌ Fehlende Abhängigkeiten: {e}", file=sys.stderr)
        return 1
    app_settings = AppSettings.load_from_file()
    adv_settings = AdvancedSettings.load_from_file()
    if args.model and args.model in Config.WHISPER_MODELS:
        app_settings.default_model = args.model
    if args.language and args.language in SUPPORTED_LANGUAGES:
        app_settings.default_language = args.language
    ffmpeg_manager = FFmpegManager(adv_settings.config, settings=adv_settings)
    stream_manager = StreamManager(
        enable_debug=(startup_config.debug_level >= 1),
        use_browser_cookies=app_settings.use_browser_cookies,
        proxy=adv_settings.proxy_url,
        proxy_enabled=adv_settings.proxy_enabled,
    )
    if WHISPER_AVAILABLE:
        try:
            transcription_engine = TranscriptionEngine(adv_settings)
            if (
                transcription_engine.load_model(
                    app_settings.default_model,
                    set_active=True,
                )
                is None
            ):
                logger.error("❌ Failed to load model '%s'", app_settings.default_model)
                return 1
        except Exception as e:
            logger.error(f"❌ Failed to initialize transcription engine: {e}")
            return 1
    else:
        logger.warning("⚠️ Whisper not available – using dummy transcription engine")
        transcription_engine = DummyTranscriptionEngine(adv_settings)
    translation_engine = None
    engine_name = adv_settings.translation_engine
    try:
        if engine_name == "ollama" and OLLAMA_AVAILABLE:
            translation_engine = OllamaTranslationEngine(
                target_lang=app_settings.default_language,
                settings=adv_settings,
                model=adv_settings.ollama_model,
                host=adv_settings.ollama_host,
            )
        elif engine_name == "argos" and ARGOS_AVAILABLE:
            translation_engine = ArgosTranslateEngine(
                target_lang=app_settings.default_language,
                settings=adv_settings,
            )
        elif TRANSLATOR_AVAILABLE:
            translation_engine = GoogleTranslationEngine(
                target_lang=app_settings.default_language,
                settings=adv_settings,
            )
        else:
            translation_engine = DummyTranslationEngine(
                target_lang=app_settings.default_language,
                settings=adv_settings,
            )
        if (
            hasattr(translation_engine, "is_functional")
            and not translation_engine.is_functional()
        ):
            logger.warning(
                "⚠️ Translation engine '%s' is not functional – using dummy",
                engine_name,
            )
            translation_engine = DummyTranslationEngine(
                target_lang=app_settings.default_language,
                settings=adv_settings,
            )
    except Exception as e:
        logger.error(f"❌ Failed to initialize translation engine: {e}")
        translation_engine = DummyTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
    processor = AudioProcessor(
        None,
        ffmpeg_manager,
        adv_settings,
        stream_manager=stream_manager,
    )
    processor.set_engines(
        transcription_engine=transcription_engine,
        translation_engine=translation_engine,
    )
    if args.quiet:

        def trans_cb(res: TranscriptionResult) -> None:
            if res and res.text:
                print(res.text)

        def transl_cb(res: TranslationResult) -> None:
            pass

    else:

        def trans_cb(res: TranscriptionResult) -> None:
            if res and res.text:
                print(f"[{time.strftime('%H:%M:%S')}] {res.text}")

        def transl_cb(res: TranslationResult) -> None:
            if res and res.translated:
                print(f"[{time.strftime('%H:%M:%S')}] → {res.translated}")

    def info_cb(msg: str) -> None:
        logger.info(msg)

    def error_cb(msg: str) -> None:
        logger.error(msg)

    def finished_cb() -> None:
        logger.info("Processing finished.")

    shutdown_requested = threading.Event()

    def signal_handler(signum, frame):
        logger.info("Received signal %d – shutting down...", signum)
        shutdown_requested.set()
        processor.stop_processing(wait=False)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    processor.start_processing(
        url=args.url,
        transcription_callback=trans_cb,
        translation_callback=transl_cb,
        info_callback=info_cb,
        error_callback=error_cb,
        finished_callback=finished_cb,
    )
    try:
        while processor.is_processing() and not shutdown_requested.is_set():
            time.sleep(0.5)
        if shutdown_requested.is_set():
            logger.info("Shutdown requested – waiting for graceful stop...")
            for _ in range(10):
                if not processor.is_processing():
                    break
                time.sleep(0.5)
            if processor.is_processing():
                logger.warning("Processor still active – forcing stop...")
                processor.stop_processing(wait=True, force=True)
    except KeyboardInterrupt:
        logger.info("Interrupted by user (KeyboardInterrupt)")
        processor.stop_processing(wait=True)
    except Exception as e:
        logger.exception("Unexpected error in headless loop: %s", e)
        return 1
    finally:
        logger.info("Cleaning up resources...")
        try:
            processor.dispose()
        except Exception as e:
            logger.error(f"Error disposing processor: {e}")
        try:
            transcription_engine.dispose()
        except Exception as e:
            logger.error(f"Error disposing transcription engine: {e}")
        try:
            translation_engine.dispose()
        except Exception as e:
            logger.error(f"Error disposing translation engine: {e}")
        try:
            ffmpeg_manager.dispose()
        except Exception as e:
            logger.error(f"Error disposing FFmpeg manager: {e}")
        try:
            stream_manager.dispose()
        except Exception as e:
            logger.error(f"Error disposing stream manager: {e}")
        try:
            from loky import get_reusable_executor

            exec = get_reusable_executor()
            if exec:
                exec.shutdown(wait=False, cancel_futures=True)
        except Exception:
            pass
        logger.info("Headless mode finished.")

    return 0


def _run_gui_with_fallbacks(
    startup_config: StartupConfig,
) -> DragonWhispererGUI | None:
    """Startet die GUI mit mehrstufigen Fallbacks bei fehlenden Abhängigkeiten."""
    import time as _time
    import uuid as _uuid

    run_id = f"RUN-{_uuid.uuid4().hex[:8]}"
    run_start = _time.monotonic()

    logger.info("[RUN] [ID=%s] 🐉 Starte GUI-Initialisierung", run_id)
    logger.debug(
        "[RUN] [ID=%s] StartupConfig: url=%s, profile=%s, debug=%s, "
        "safe_mode=%s, quiet=%s, model=%s, language=%s",
        run_id,
        "yes" if startup_config.url else "no",
        startup_config.profile or "none",
        startup_config.debug_level,
        startup_config.safe_mode,
        startup_config.quiet,
        startup_config.model or "auto",
        startup_config.language or "auto",
    )

    if not GUI_AVAILABLE:
        logger.warning(
            "[RUN] [ID=%s] Tkinter nicht verfügbar – wechsle in Headless-Modus",
            run_id,
        )
        if startup_config.url:
            try:
                args = _build_headless_args(startup_config)
                _run_headless(args, startup_config)
            except Exception as e:
                logger.exception(
                    "[RUN] [ID=%s] Headless-Ausführung fehlgeschlagen: %s",
                    run_id,
                    e,
                )
                with contextlib.suppress(Exception):
                    _show_critical_error(
                        f"Headless-Ausführung fehlgeschlagen:\n{e}",
                    )
            return None

        try:
            _show_critical_error(
                "Tkinter ist nicht installiert und keine URL angegeben.\n"
                "Install Tkinter (z.B. sudo apt install python3-tk) "
                "oder nutzen Sie --url.",
            )
        except Exception as e:
            logger.error(
                "[RUN] [ID=%s] Kritischer Fehler konnte nicht angezeigt werden: %s",
                run_id,
                e,
            )
        return None

    dependency_issue = False
    try:
        PlatformUtils.check_platform_dependencies()
    except RuntimeError as e:
        dependency_issue = True
        logger.warning(
            "[RUN] [ID=%s] Einige kritische Abhängigkeiten fehlen, "
            "aber GUI kann trotzdem gestartet werden:\n%s",
            run_id,
            e,
        )
    except Exception as e:
        dependency_issue = True
        logger.warning(
            "[RUN] [ID=%s] Unerwarteter Fehler bei Abhängigkeitsprüfung: %s",
            run_id,
            e,
            exc_info=startup_config.debug_level >= 3,
        )

    app: DragonWhispererGUI | None = None
    try:
        logger.debug("[RUN] [ID=%s] Erstelle DragonWhispererGUI...", run_id)
        app = DragonWhispererGUI()
        import sys as _sys

        _main_mod = _sys.modules.get("__main__")
        if _main_mod is not None:
            with contextlib.suppress(Exception):
                _main_mod._DRAGON_GUI_INSTANCE = app
        logger.info("[RUN] [ID=%s] ✅ GUI erfolgreich erstellt", run_id)
    except (tk.TclError, RuntimeError, ImportError, OSError) as e:
        logger.exception(
            "[RUN] [ID=%s] ❌ GUI-Initialisierung fehlgeschlagen: %s",
            run_id,
            e,
        )
        with contextlib.suppress(Exception):
            _show_critical_error(
                f"Die Benutzeroberfläche konnte nicht gestartet werden:\n{e}",
            )
        return None
    except BaseException as e:
        logger.critical(
            "[RUN] [ID=%s] 💥 Unerwarteter BaseException bei GUI-Erstellung: %s: %s",
            run_id,
            type(e).__name__,
            e,
            exc_info=True,
        )
        with contextlib.suppress(Exception):
            _show_critical_error(
                f"Unerwarteter Fehler beim Start:\n{type(e).__name__}: {e}",
            )
        return None

    try:
        event_bus = getattr(app, "event_bus", None)
        safeguard_result = _create_controller_with_safeguard(app, event_bus)

        if not isinstance(safeguard_result, dict):
            logger.error(
                "[RUN] [ID=%s] ❌ Safeguard-Rückgabe ist kein dict "
                "(Typ: %s) – möglicherweise alte Signatur",
                run_id,
                type(safeguard_result).__name__,
            )
        elif safeguard_result.get("success", False):
            self_test = safeguard_result.get("self_test_result") or {}
            logger.info(
                "[RUN] [ID=%s] ✅ Controller erstellt und registriert "
                "(duration=%.2fms, events=%d, self_test=%s)",
                run_id,
                safeguard_result.get("duration_ms", 0.0),
                self_test.get("subscription_count", 0),
                "OK" if safeguard_result.get("self_test_passed", False) else "WARN",
            )
            logger.debug(
                "[RUN] [ID=%s] Diagnose: %s",
                run_id,
                {
                    k: v
                    for k, v in safeguard_result.items()
                    if k not in ("self_test_result", "controller")
                },
            )
        elif safeguard_result.get("safe_mode_activated", False):
            logger.critical(
                "[RUN] [ID=%s] ⚠️ Controller-Safe-Mode aktiv – "
                "Audio-Funktionen deaktiviert. Fehler: %s",
                run_id,
                safeguard_result.get("errors", []),
            )
        else:
            logger.error(
                "[RUN] [ID=%s] ❌ Controller-Setup unklar – errors=%s, warnings=%s",
                run_id,
                safeguard_result.get("errors", []),
                safeguard_result.get("warnings", []),
            )

    except Exception as e:
        logger.exception(
            "[RUN] [ID=%s] 💥 Controller-Safeguard fehlgeschlagen: %s",
            run_id,
            e,
        )

    if startup_config.profile:
        try:
            _load_profile(
                app,
                startup_config.profile,
                startup_config.debug_level,
            )
            logger.debug(
                "[RUN] [ID=%s] ✅ Profil '%s' geladen",
                run_id,
                startup_config.profile,
            )
        except Exception as e:
            logger.error(
                "[RUN] [ID=%s] ⚠️ Profil '%s' konnte nicht geladen werden: %s",
                run_id,
                startup_config.profile,
                e,
            )

    if startup_config.url:
        try:
            _set_url_async(app, startup_config.url)
            logger.debug(
                "[RUN] [ID=%s] ✅ URL asynchron gesetzt",
                run_id,
            )
        except Exception as e:
            logger.error(
                "[RUN] [ID=%s] ⚠️ URL konnte nicht gesetzt werden: %s",
                run_id,
                e,
            )

    if dependency_issue:
        try:
            _schedule_install_dialog(app)
            logger.debug(
                "[RUN] [ID=%s] ✅ Install-Dialog geplant",
                run_id,
            )
        except Exception as e:
            logger.warning(
                "[RUN] [ID=%s] ⚠️ Install-Dialog konnte nicht geplant werden: %s",
                run_id,
                e,
            )

    if startup_config.debug_level >= 1 and not startup_config.quiet:
        try:
            _print_welcome(startup_config.debug_level, startup_config.quiet)
        except Exception as e:
            logger.debug(
                "[RUN] [ID=%s] Welcome-Ausgabe fehlgeschlagen: %s",
                run_id,
                e,
            )

    if startup_config.debug_level >= 3:
        try:
            _log_debug_welcome_info(
                startup_config.debug_level,
                True,
                startup_config.quiet,
            )
        except Exception as e:
            logger.debug(
                "[RUN] [ID=%s] Debug-Welcome-Info fehlgeschlagen: %s",
                run_id,
                e,
            )

    def _delayed_health_check(*args: Any) -> None:
        """Wird nach dem ersten erfolgreichen Modell-Laden aufgerufen."""
        try:
            if app is None or app.is_shutting_down():
                return
            if startup_config.safe_mode:
                return

            health_issues = _post_startup_health_check(app)
            if health_issues:
                logger.warning(
                    "[RUN] [ID=%s] ⚠️ Health-Check Probleme:\n  • %s",
                    run_id,
                    "\n  • ".join(health_issues),
                )
                if startup_config.debug_level >= 1:
                    with contextlib.suppress(Exception):
                        app.update_status(
                            "⚠️ Einige Funktionen eingeschränkt – Details im Log",
                        )
            else:
                logger.debug(
                    "[RUN] [ID=%s] ✅ Health-Check ohne Beanstandungen",
                    run_id,
                )
        except Exception as e:
            logger.debug(
                "[RUN] [ID=%s] Health-Check fehlgeschlagen: %s",
                run_id,
                e,
            )

    try:
        if app.event_bus is not None:
            app.event_bus.subscribe_once(
                "model_load_finished",
                _delayed_health_check,
            )
            logger.debug(
                "[RUN] [ID=%s] ✅ Delayed Health-Check registriert",
                run_id,
            )
        else:
            logger.warning(
                "[RUN] [ID=%s] Kein Event-Bus – Health-Check wird nicht "
                "automatisch ausgeführt",
                run_id,
            )
    except Exception as e:
        logger.warning(
            "[RUN] [ID=%s] ⚠️ Health-Check konnte nicht registriert werden: %s",
            run_id,
            e,
        )

    exit_code = 0
    exit_reason = "unknown"
    try:
        logger.info(
            "[RUN] [ID=%s] 🚀 Starte Main-Loop (Phase 8)...",
            run_id,
        )
        app.run()
        exit_reason = "normal"
        logger.info(
            "[RUN] [ID=%s] ✅ Anwendung normal beendet",
            run_id,
        )

    except KeyboardInterrupt:
        exit_reason = "keyboard_interrupt"
        exit_code = 130
        logger.info(
            "[RUN] [ID=%s] 🛑 Vom Benutzer unterbrochen (KeyboardInterrupt)",
            run_id,
        )

    except SystemExit as e:
        exit_reason = "system_exit"
        exit_code = e.code if isinstance(e.code, int) else 0
        logger.info(
            "[RUN] [ID=%s] SystemExit mit Code %s empfangen",
            run_id,
            exit_code,
        )

    except (tk.TclError, RuntimeError, OSError) as e:
        exit_reason = "gui_error"
        exit_code = 2
        logger.exception(
            "[RUN] [ID=%s] 💥 Erwarteter Fehler in Main-Loop: %s",
            run_id,
            e,
        )
        if startup_config.debug_level >= 2:
            with contextlib.suppress(Exception):
                traceback.print_exc()

    except BaseException as e:
        exit_reason = "unexpected"
        exit_code = 3
        logger.critical(
            "[RUN] [ID=%s] 💥 Unerwarteter BaseException in Main-Loop: %s: %s",
            run_id,
            type(e).__name__,
            e,
            exc_info=True,
        )

    try:
        if app is not None:
            root_exists = False
            try:
                if hasattr(app, "root") and app.root is not None:
                    root_exists = app.root.winfo_exists()
            except (tk.TclError, AttributeError):
                root_exists = False
            except Exception:
                root_exists = False

            if root_exists:
                logger.debug(
                    "[RUN] [ID=%s] 🔄 GUI läuft noch – überspringe Cleanup",
                    run_id,
                )
            else:
                cleanup_success = False

                if hasattr(app, "_cleanup_resources"):
                    try:
                        app._cleanup_resources(emergency=False)
                        cleanup_success = True
                        logger.debug(
                            "[RUN] [ID=%s] ✅ _cleanup_resources() ausgeführt",
                            run_id,
                        )
                    except (OSError, RuntimeError, AttributeError, tk.TclError) as e:
                        logger.warning(
                            "[RUN] [ID=%s] _cleanup_resources() fehlgeschlagen: %s",
                            run_id,
                            e,
                        )

                if not cleanup_success and hasattr(app, "dispose"):
                    try:
                        app.dispose()
                        cleanup_success = True
                        logger.debug(
                            "[RUN] [ID=%s] ✅ dispose() ausgeführt",
                            run_id,
                        )
                    except Exception as e:
                        logger.warning(
                            "[RUN] [ID=%s] dispose() fehlgeschlagen: %s",
                            run_id,
                            e,
                        )

                if not cleanup_success:
                    try:
                        if hasattr(app, "root") and app.root is not None:
                            if app.root.winfo_exists():
                                app.root.destroy()
                                logger.debug(
                                    "[RUN] [ID=%s] ✅ root.destroy() ausgeführt",
                                    run_id,
                                )
                    except (OSError, RuntimeError, AttributeError, tk.TclError) as e:
                        logger.warning(
                            "[RUN] [ID=%s] root.destroy() fehlgeschlagen: %s",
                            run_id,
                            e,
                        )

    except Exception as e:
        logger.warning(
            "[RUN] [ID=%s] ⚠️ Cleanup-Phase fehlgeschlagen: %s",
            run_id,
            e,
            exc_info=True,
        )

    try:
        _perform_loky_cleanup()
        logger.debug(
            "[RUN] [ID=%s] ✅ Loky-Cleanup durchgeführt",
            run_id,
        )
    except Exception as e:
        logger.debug(
            "[RUN] [ID=%s] Loky-Cleanup fehlgeschlagen: %s",
            run_id,
            e,
        )

    try:
        gc.collect()
        logger.debug(
            "[RUN] [ID=%s] ✅ Garbage Collection durchgeführt",
            run_id,
        )
    except Exception as e:
        logger.debug(
            "[RUN] [ID=%s] GC fehlgeschlagen: %s",
            run_id,
            e,
        )

    duration_s = _time.monotonic() - run_start

    logger.info(
        "[RUN] [ID=%s] 🏁 Lauf beendet (reason=%s, exit_code=%d, duration=%.2fs)",
        run_id,
        exit_reason,
        exit_code,
        duration_s,
    )

    if exit_code == 0 and app is not None:
        try:
            if not app.is_shutting_down():
                return app
            logger.debug(
                "[RUN] [ID=%s] App is_shutting_down – gebe None zurück",
                run_id,
            )
        except Exception as e:
            logger.debug(
                "[RUN] [ID=%s] is_shutting_down()-Prüfung fehlgeschlagen: %s",
                run_id,
                e,
            )
            return app

    return None


def _build_headless_args(
    startup_config: StartupConfig,
) -> argparse.Namespace:
    """Baut das argparse.Namespace für den Headless-Modus aus der StartupConfig.

    Ausgelagert aus `_run_gui_with_fallbacks`, damit die Hauptmethode
    übersichtlicher bleibt.

    Args:
        startup_config: Die Startup-Konfiguration.

    Returns:
        Namespace für `_run_headless()`.
    """
    return argparse.Namespace(
        url=startup_config.url,
        headless=True,
        quiet=startup_config.quiet,
        debug=(str(startup_config.debug_level) if startup_config.debug_level else "0"),
        model=startup_config.model,
        language=startup_config.language,
        profile=startup_config.profile,
        version=False,
        sysinfo=False,
        check=False,
        test=False,
        help=False,
        benchmark=False,
        repair_config=False,
        check_gpu=False,
        safe_mode=startup_config.safe_mode,
    )


def _create_controller_with_safeguard(
    gui_instance: Any,
    event_bus: Any,
) -> dict[str, Any]:
    """Erstellt den WhisperController mit mehrstufigem Fallback und Diagnose."""
    import time as _time
    import uuid as _uuid

    start_time = _time.monotonic()
    run_id = f"SAFE-{_uuid.uuid4().hex[:8]}"

    result: dict[str, Any] = {
        "success": False,
        "controller": None,
        "controller_created": False,
        "controller_registered": False,
        "already_existed": False,
        "self_test_run": False,
        "self_test_passed": False,
        "self_test_result": None,
        "safe_mode_activated": False,
        "errors": [],
        "warnings": [],
        "step_times": {},
        "duration_ms": 0.0,
        "error_id": run_id,
    }

    logger.info(
        "[SAFEGUARD] [ID=%s] 🚀 Starte Controller-Erstellung mit Safeguard",
        run_id,
    )

    def _timed_step(
        name: str,
        func: Callable[[], Any],
        critical: bool,
    ) -> tuple[bool, Any]:
        """Führt einen Schritt aus, misst Zeit und fängt Fehler ab.

        Returns:
            (success, return_value):
                success = False, wenn eine Exception auftrat.
                return_value = der Rückgabewert von func() oder None.
        """
        step_start = _time.monotonic()
        try:
            ret = func()
            elapsed = (_time.monotonic() - step_start) * 1000
            result["step_times"][name] = round(elapsed, 2)
            logger.debug(
                "[SAFEGUARD] [ID=%s] ✅ Phase '%s' erfolgreich (%.2fms)",
                run_id,
                name,
                elapsed,
            )
            return True, ret
        except Exception as e:
            elapsed = (_time.monotonic() - step_start) * 1000
            result["step_times"][name] = round(elapsed, 2)
            error_msg = f"Phase '{name}' fehlgeschlagen: {type(e).__name__}: {e}"
            result["errors"].append(error_msg)
            logger.error(
                "[SAFEGUARD] [ID=%s] ❌ Phase '%s' fehlgeschlagen "
                "(kritisch=%s, %.2fms): %s",
                run_id,
                name,
                critical,
                elapsed,
                e,
                exc_info=(DEBUG_LEVEL >= 3),
            )
            return False, None

    def _add_warning(msg: str) -> None:
        result["warnings"].append(msg)
        logger.warning("[SAFEGUARD] [ID=%s] ⚠️ %s", run_id, msg)

    def _phase_existing_check() -> Any:
        existing = getattr(gui_instance, "controller", None)
        if existing is not None:
            result["already_existed"] = True
            result["controller"] = existing
            logger.info(
                "[SAFEGUARD] [ID=%s] Controller existiert bereits – "
                "überspringe Neuerstellung",
                run_id,
            )
        return existing

    _timed_step("existing_check", _phase_existing_check, critical=False)

    if result["already_existed"] and result["controller"] is not None:
        controller = result["controller"]

        if hasattr(controller, "self_test") and callable(controller.self_test):

            def _phase_self_test_existing() -> dict:
                test_result = controller.self_test(
                    verbose=(DEBUG_LEVEL >= 4),
                )
                result["self_test_run"] = True
                result["self_test_passed"] = bool(
                    test_result.get("success", False),
                )
                result["self_test_result"] = test_result
                if not test_result.get("success", False):
                    for f in test_result.get("failures", [])[:5]:
                        _add_warning(
                            f"Self-Test (existing): {f.get('check')}: "
                            f"{f.get('detail')}",
                        )
                return test_result

            _timed_step(
                "self_test_existing",
                _phase_self_test_existing,
                critical=False,
            )

        result["success"] = True
        result["controller_registered"] = True
        result["duration_ms"] = round(
            (_time.monotonic() - start_time) * 1000,
            2,
        )
        logger.info(
            "[SAFEGUARD] [ID=%s] ✅ Bestehender Controller übernommen "
            "(duration=%.2fms)",
            run_id,
            result["duration_ms"],
        )
        return result

    def _phase_create_controller() -> Any:
        ctrl = WhisperController(gui_instance, event_bus)
        result["controller"] = ctrl
        result["controller_created"] = True
        logger.info(
            "[SAFEGUARD] [ID=%s] ✅ WhisperController erfolgreich erstellt",
            run_id,
        )
        return ctrl

    created_ok, _ = _timed_step(
        "controller_creation",
        _phase_create_controller,
        critical=True,
    )

    if not created_ok:
        logger.critical(
            "[SAFEGUARD] [ID=%s] 💥 Controller-Erstellung fehlgeschlagen – "
            "aktiviere Safe-Mode",
            run_id,
        )

        def _phase_safe_mode() -> None:
            _activate_safe_mode(gui_instance, result, run_id)

        _timed_step("safe_mode_activation", _phase_safe_mode, critical=False)

        result["duration_ms"] = round(
            (_time.monotonic() - start_time) * 1000,
            2,
        )
        logger.critical(
            "[SAFEGUARD] [ID=%s] 🛑 Controller-Erstellung abgebrochen – "
            "GUI läuft im Safe-Mode (duration=%.2fms)",
            run_id,
            result["duration_ms"],
        )
        return result

    def _phase_register() -> None:
        gui_instance.controller = result["controller"]
        result["controller_registered"] = True
        logger.debug(
            "[SAFEGUARD] [ID=%s] Controller in GUI registriert (gui.controller)",
            run_id,
        )

    _timed_step("controller_registration", _phase_register, critical=False)

    controller = result["controller"]
    if controller is not None and hasattr(controller, "self_test"):

        def _phase_self_test() -> dict:
            test_result = controller.self_test(
                verbose=(DEBUG_LEVEL >= 4),
            )
            result["self_test_run"] = True
            result["self_test_passed"] = bool(
                test_result.get("success", False),
            )
            result["self_test_result"] = test_result
            return test_result

        self_test_ok, _ = _timed_step(
            "self_test",
            _phase_self_test,
            critical=False,
        )

        if self_test_ok:
            tr = result["self_test_result"] or {}
            if result["self_test_passed"]:
                logger.info(
                    "[SAFEGUARD] [ID=%s] ✅ Self-Test bestanden "
                    "(%d Checks, %d Warnungen, %.2fms)",
                    run_id,
                    tr.get("checks_passed", 0),
                    len(tr.get("warnings", [])),
                    tr.get("duration_ms", 0.0),
                )
            else:
                logger.error(
                    "[SAFEGUARD] [ID=%s] ⚠️ Self-Test fehlgeschlagen: "
                    "%d/%d Checks – Controller wird trotzdem verwendet",
                    run_id,
                    tr.get("checks_failed", 0),
                    tr.get("checks_passed", 0) + tr.get("checks_failed", 0),
                )
                for f in tr.get("failures", [])[:5]:
                    _add_warning(
                        f"Self-Test: {f.get('check')}: {f.get('detail')}",
                    )
                try:
                    if hasattr(gui_instance, "update_status"):
                        gui_instance.update_status(
                            "⚠️ Controller-Warnung – siehe Log",
                        )
                except Exception:
                    pass
        elif result["self_test_run"] is False:
            _add_warning(
                "Self-Test konnte nicht ausgeführt werden – "
                "Controller läuft ohne Validierung",
            )
    else:
        _add_warning(
            "WhisperController hat keine self_test()-Methode – "
            "keine Validierung möglich",
        )

    result["success"] = result["controller_created"] and result["controller_registered"]
    result["duration_ms"] = round(
        (_time.monotonic() - start_time) * 1000,
        2,
    )

    if DEBUG_LEVEL >= 3 and result["step_times"]:
        sorted_steps = sorted(
            result["step_times"].items(),
            key=lambda x: x[1],
            reverse=True,
        )[:3]
        logger.debug(
            "[SAFEGUARD] [ID=%s] 📊 Langsamste Phasen: %s",
            run_id,
            ", ".join(f"{n}={t:.2f}ms" for n, t in sorted_steps),
        )

    if result["success"]:
        logger.info(
            "[SAFEGUARD] [ID=%s] ✅ Controller-Safeguard erfolgreich "
            "abgeschlossen (duration=%.2fms, errors=%d, warnings=%d)",
            run_id,
            result["duration_ms"],
            len(result["errors"]),
            len(result["warnings"]),
        )
    else:
        logger.critical(
            "[SAFEGUARD] [ID=%s] ❌ Controller-Safeguard fehlgeschlagen "
            "(duration=%.2fms, errors=%d)",
            run_id,
            result["duration_ms"],
            len(result["errors"]),
        )

    return result


def _activate_safe_mode(
    gui_instance: Any,
    result: dict[str, Any],
    run_id: str,
) -> None:
    """Deaktiviert alle Action-Buttons und zeigt Safe-Mode-Status."""
    result["safe_mode_activated"] = True

    try:
        if hasattr(gui_instance, "update_status"):
            gui_instance.update_status(
                "❌ Controller-Fehler – Anwendung läuft im Safe-Mode",
            )
    except Exception as e:
        logger.debug("[SAFEGUARD] [ID=%s] Status-Update fehlgeschlagen: %s", run_id, e)

    buttons_to_disable = [
        "start_button",
        "stop_button",
    ]
    for btn_name in buttons_to_disable:
        try:
            btn = getattr(gui_instance, btn_name, None)
            if btn is not None and hasattr(btn, "config"):
                btn.config(state="disabled")
                logger.debug(
                    "[SAFEGUARD] [ID=%s] Button '%s' deaktiviert",
                    run_id,
                    btn_name,
                )
        except Exception as e:
            logger.debug(
                "[SAFEGUARD] [ID=%s] Button '%s' konnte nicht deaktiviert werden: %s",
                run_id,
                btn_name,
                e,
            )

    try:
        action_buttons = getattr(gui_instance, "action_buttons", None)
        if isinstance(action_buttons, dict):
            for action_name, btn in action_buttons.items():
                try:
                    if btn is not None and hasattr(btn, "config"):
                        btn.config(state="disabled")
                        logger.debug(
                            "[SAFEGUARD] [ID=%s] Action-Button '%s' deaktiviert",
                            run_id,
                            action_name,
                        )
                except Exception:
                    pass
    except Exception as e:
        logger.debug(
            "[SAFEGUARD] [ID=%s] Action-Buttons konnten nicht deaktiviert werden: %s",
            run_id,
            e,
        )

    try:
        if hasattr(gui_instance, "progress_var"):
            gui_instance.progress_var.set(0)
        if hasattr(gui_instance, "progress_bar"):
            gui_instance.progress_bar["value"] = 0
    except Exception:
        pass

    try:
        if hasattr(gui_instance, "show_error"):
            gui_instance.show_error(
                "Der Audio-Controller konnte nicht initialisiert werden.\n"
                "Die Anwendung läuft im eingeschränkten Modus weiter.\n"
                "Details siehe Log.",
                title="Controller-Fehler",
            )
    except Exception:
        pass


def _load_profile(app: DragonWhispererGUI, profile_name: str, debug_level: int) -> None:
    """Lädt ein benutzerdefiniertes Profil aus dem Profilverzeichnis."""
    try:
        profile_path = (
            PlatformUtils.get_platform_config_dir()
            / "profiles"
            / f"{profile_name}.json"
        )
        if profile_path.exists():
            with open(profile_path, encoding="utf-8") as f:
                profile_data = json.load(f)
            for key, value in profile_data.items():
                if hasattr(app.advanced_settings, key):
                    setattr(app.advanced_settings, key, value)
            logger.info("✅ Profile '%s' loaded", profile_name)
        else:
            logger.warning("⚠️ Profile '%s' not found", profile_name)
    except (OSError, json.JSONDecodeError, AttributeError) as e:
        logger.warning("⚠️ Failed to load profile: %s", e)


def _safe_schedule(
    app: DragonWhispererGUI,
    delay_ms: int,
    callback: Callable[[], None],
) -> None:
    """Führt einen Callback sicher nach einer Verzögerung im GUI-Thread aus."""
    delay_ms = max(delay_ms, 0)

    if hasattr(app, "_safe_after"):
        app._safe_after(delay_ms, callback)
    elif hasattr(app, "root") and app.root.winfo_exists():
        app.root.after(delay_ms, callback)
    else:
        logger.debug("GUI nicht verfügbar – führe Callback direkt aus")
        try:
            callback()
        except Exception as e:
            logger.error(f"Callback-Fehler im direkten Ausführung: {e}")


def _set_url_async(app: DragonWhispererGUI, url: str) -> None:
    """Setzt die URL asynchron im Hauptthread der GUI."""

    def _set_url() -> None:
        try:
            if hasattr(app, "url_entry") and app.url_entry.winfo_exists():
                app.url_entry.delete(0, "end")
                app.url_entry.insert(0, url)
                logger.info("📌 URL from command line: %s", url)
            else:
                logger.warning("URL-Eingabefeld nicht verfügbar – URL nicht gesetzt")
        except Exception as e:
            logger.error(f"Fehler beim Setzen der URL: {e}")

    _safe_schedule(app, 500, _set_url)


def _schedule_install_dialog(app: DragonWhispererGUI) -> None:
    """Plant das Öffnen des Installationsdialogs nach einer Verzögerung."""

    def _open_installer() -> None:
        try:
            if hasattr(app, "show_install_dialog") and not app.is_shutting_down():
                app.show_install_dialog()
        except Exception as e:
            logger.error(f"Fehler beim Öffnen des Installationsdialogs: {e}")

    _safe_schedule(app, 1500, _open_installer)


def _post_startup_health_check(app: DragonWhispererGUI) -> list[str]:
    """Führt einen schnellen Gesundheitscheck der Engines und Tools durch."""
    issues = []
    if hasattr(app, "transcription_engine") and app.transcription_engine:
        try:
            if not app.transcription_engine.test_model_functionality(timeout=10):
                issues.append("Transkriptionsmodell reagiert nicht")
        except (TimeoutError, RuntimeError, AttributeError) as e:
            issues.append(f"Transkriptionstest fehlgeschlagen: {e}")
    if hasattr(app, "translation_engine") and app.translation_engine:
        try:
            test_result = app.translation_engine.translate_text("Hello", "en")
            if not test_result or not test_result.translated:
                issues.append("Übersetzungs‑Engine liefert leere Antwort")
        except (RuntimeError, AttributeError, ConnectionError) as e:
            issues.append(f"Übersetzungstest fehlgeschlagen: {e}")
    if shutil.which("ffmpeg") is None:
        issues.append("FFmpeg nicht im PATH – Livestreams nicht möglich")
    if shutil.which("yt-dlp") is None:
        issues.append("yt-dlp nicht im PATH – YouTube‑Streams eingeschränkt")
    return issues


def _cleanup_gui(app: DragonWhispererGUI | None, startup_config: StartupConfig) -> None:
    """Führt die GUI‑Ressourcenbereinigung durch, falls die GUI initialisiert wurde."""
    if app is not None:
        try:
            if hasattr(app, "_cleanup_resources"):
                app._cleanup_resources(emergency=False)
            elif hasattr(app, "dispose"):
                app.dispose()
            elif hasattr(app, "root") and app.root.winfo_exists():
                app.root.destroy()
        except (OSError, RuntimeError, AttributeError, tk.TclError) as e:
            logger.warning("Fehler bei GUI‑Ressourcenbereinigung: %s", e)
    _perform_loky_cleanup()
    gc.collect()


def _print_version() -> None:
    """Gibt die Versionsinformationen aus – ultimativ optimiert."""
    import subprocess
    import sys

    if QUIET_MODE:
        return

    use_emoji = sys.stdout.isatty()
    lines = []
    dragon = "🐉" if use_emoji else "[Dragon]"
    lines.append(f"{dragon} Dragon Whisperer v6.0 (optimized)")
    arch = "ARM" if IS_ARM else "x86"
    lines.append(f"Platform: {SYSTEM} {arch}")
    lines.append(f"Python: {sys.version.split()[0]}")
    lines.append(f"Debug Level: {DEBUG_LEVEL}")

    try:
        git_hash = subprocess.check_output(
            ["git", "rev-parse", "--short", "HEAD"],
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=2.0,
        ).strip()
        if git_hash:
            lines.append(f"Git commit: {git_hash}")
    except (
        subprocess.SubprocessError,
        FileNotFoundError,
        OSError,
        subprocess.TimeoutExpired,
    ):
        pass

    try:
        import torch

        if torch.cuda.is_available():
            device_name = torch.cuda.get_device_name(0)
            vram_total = torch.cuda.get_device_properties(0).total_memory // (1024**3)
            lines.append(f"GPU: {device_name} ({vram_total} GB VRAM)")
        else:
            lines.append("GPU: None (CPU mode)")
    except (ImportError, AttributeError, RuntimeError):
        lines.append("GPU: Unknown (torch not available)")

    if DEBUG_LEVEL >= 2:
        libraries = {
            "faster-whisper": "faster_whisper",
            "openai-whisper": "whisper",
            "torch": "torch",
            "yt-dlp": "yt_dlp",
            "argostranslate": "argostranslate",
            "numpy": "numpy",
        }
        for name, import_name in libraries.items():
            try:
                mod = __import__(import_name)
                version = getattr(mod, "__version__", "unknown")
                lines.append(f"{name}: {version}")
            except ImportError:
                lines.append(f"{name}: not installed")

    lines.append("License: MIT License (https://opensource.org/licenses/MIT)")
    output = "\n".join(lines)
    print(output)

    if DEBUG_LEVEL >= 2:
        logger.debug(f"Version info:\n{output}")


