def parse_arguments() -> argparse.Namespace:
    """Kommandozeilen‑Parser mit:
    - --debug=all Unterstützung
    - URL-Validierung (nur bei tatsächlicher Angabe)
    - Log-File Option
    - Config-Datei Option
    - Dump-Config Option
    - No-Color Option
    - Umgebungsvariablen-Fallbacks
    """
    import argparse
    import os
    from urllib.parse import urlparse

    def valid_url(value: str) -> str:
        """Validiert eine URL und gibt sie zurück oder wirft einen Fehler."""
        if not value or not value.strip():
            raise argparse.ArgumentTypeError("URL darf nicht leer sein.")
        value = value.strip()
        if not (
            value.startswith(("http://", "https://", "file://"))
            or value.startswith(("ftp://", "rtmp://", "rtsp://"))
            or value.startswith("youtube.com/")
            or value.startswith("www.youtube.com/")
        ):
            value = f"https://{value}"
        try:
            result = urlparse(value)
            if not result.netloc and not result.path:
                raise ValueError("Ungültige URL-Struktur")
        except Exception as e:
            raise argparse.ArgumentTypeError(f"Ungültige URL: {e}") from e
        return value

    def valid_debug_level(value: str) -> str:
        """Validiert und normalisiert einen --debug Wert."""
        if not value or not value.strip():
            return ""
        value = value.strip().lower()
        if value == "all":
            return "all"
        try:
            level = int(value)
            if 0 <= level <= 5:
                return value
            raise argparse.ArgumentTypeError(
                f"Debug-Level muss zwischen 0 und 5 liegen (ist: {level})",
            )
        except ValueError:
            return value

    def default_from_env(var_name: str, default: str = "") -> str:
        """Holt einen Wert aus der Umgebungsvariable oder gibt den Default zurück."""
        return os.getenv(var_name, default)

    parser = argparse.ArgumentParser(
        description="🐉 Dragon Whisperer - Livestream Transcription & Translation",
        epilog=(
            "Examples:\n"
            "  %(prog)s --url https://www.youtube.com/watch?v=... --model large-v3\n"
            "  %(prog)s --debug 3 --language de\n"
            "  %(prog)s --debug all --headless --url ...\n"
            "\n"
            "Debug Components: audio, transcription, translation, dispatcher, queue, "
            "gui, shutdown, system, vad, model, cache, stream, plugin, network, memory\n"
            "\n"
            "Environment variables:\n"
            "  DW_DEBUG      = Default debug level (e.g., '3' or 'audio,transcription')\n"
            "  DW_LOG_FILE   = Default log file path\n"
            "  DW_CONFIG     = Default config file path\n"
            "  DW_LANGUAGE   = Default target language\n"
            "  DW_MODEL      = Default Whisper model\n"
            "  DW_URL        = Default URL to process\n"
            "For more information, visit: https://github.com/your-repo/dragon-whisperer"
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    parser.add_argument(
        "-q",
        "--quiet",
        action="store_true",
        help="Suppress all output except errors",
    )

    parser.add_argument(
        "--no-color",
        action="store_true",
        help="Disable colored console output",
    )

    parser.add_argument(
        "--debug",
        action="append",
        type=valid_debug_level,
        help=(
            "Enable debug output. Can be a number (0-5) or a comma-separated "
            "list of components. Use 'all' for all components. Can be repeated.\n"
            "Examples: --debug 3, --debug audio,transcription, --debug all\n"
            f"Default from DW_DEBUG: {default_from_env('DW_DEBUG', '') or 'not set'}"
        ),
    )

    parser.add_argument(
        "--log-file",
        metavar="PATH",
        default=default_from_env("DW_LOG_FILE", ""),
        help=f"Write logs to this file (default from DW_LOG_FILE: {default_from_env('DW_LOG_FILE', 'not set')})",
    )

    parser.add_argument(
        "--config",
        metavar="PATH",
        default=default_from_env("DW_CONFIG", ""),
        help=f"Use custom config file (default from DW_CONFIG: {default_from_env('DW_CONFIG', 'not set')})",
    )

    parser.add_argument(
        "--dump-config",
        action="store_true",
        help="Load and dump the effective configuration, then exit",
    )

    parser.add_argument(
        "--check",
        action="store_true",
        help="Run system compatibility check and exit",
    )

    parser.add_argument(
        "--test",
        action="store_true",
        help="Run internal unit tests and exit",
    )

    parser.add_argument(
        "--version",
        "-v",
        action="store_true",
        help="Show version information and exit",
    )

    parser.add_argument(
        "--sysinfo",
        action="store_true",
        help="Print detailed system information and exit",
    )

    parser.add_argument(
        "--headless",
        action="store_true",
        help="Run in headless mode (no GUI, console output only)",
    )

    parser.add_argument(
        "--benchmark",
        action="store_true",
        help="Measure startup times and exit",
    )

    parser.add_argument(
        "--repair-config",
        action="store_true",
        help="Reset broken configuration to defaults",
    )

    parser.add_argument(
        "--check-gpu",
        action="store_true",
        help="Check GPU availability and VRAM, then exit",
    )

    parser.add_argument(
        "--safe-mode",
        action="store_true",
        help="Disable non‑essential features (e.g., some optimizations)",
    )

    parser.add_argument(
        "--url",
        metavar="URL",
        default=default_from_env("DW_URL", None),
        help="Start processing the given URL immediately (default from DW_URL)",
    )

    parser.add_argument(
        "--profile",
        metavar="NAME",
        help="Load a custom settings profile",
    )

    parser.add_argument(
        "--model",
        default=default_from_env("DW_MODEL", "large-v3-turbo"),
        help=f"Whisper model to use (default from DW_MODEL: {default_from_env('DW_MODEL', 'large-v3-turbo')})",
    )

    parser.add_argument(
        "--language",
        default=default_from_env("DW_LANGUAGE", "de"),
        help=f"Target language for translation (default from DW_LANGUAGE: {default_from_env('DW_LANGUAGE', 'de')})",
    )

    parser.add_argument(
        "--source-language",
        default=default_from_env("DW_SOURCE_LANGUAGE", ""),
        help="Source language for transcription (auto-detect if empty, default from DW_SOURCE_LANGUAGE)",
    )

    parser.add_argument(
        "--chunk-duration",
        type=float,
        default=float(default_from_env("DW_CHUNK_DURATION", "12.0")),
        help="Chunk duration in seconds (default from DW_CHUNK_DURATION: 12.0)",
    )

    parser.add_argument(
        "--workers",
        type=int,
        default=int(default_from_env("DW_WORKERS", "0")),
        help="Number of transcription workers (0 = auto, default from DW_WORKERS: 0)",
    )

    parser.add_argument(
        "--no-vad",
        action="store_true",
        help="Disable Voice Activity Detection (VAD)",
    )

    parser.add_argument(
        "--subtitle-mode",
        action="store_true",
        help="Enable subtitle mode (optimized for subtitles)",
    )

    parser.add_argument(
        "--no-translation",
        action="store_true",
        help="Disable translation (only transcribe)",
    )

    args = parser.parse_args()

    if args.url is not None and args.url != "":
        try:
            args.url = valid_url(args.url)
        except argparse.ArgumentTypeError as e:
            parser.error(str(e))

    if args.debug is None and os.getenv("DW_DEBUG"):
        env_debug = os.getenv("DW_DEBUG")
        if env_debug:
            parts = [p.strip() for p in env_debug.split(",") if p.strip()]
            args.debug = parts if len(parts) > 1 else [env_debug]

    if args.debug:
        normalized = []
        for item in args.debug:
            if item == "all":
                normalized.extend(
                    [
                        "audio",
                        "transcription",
                        "translation",
                        "dispatcher",
                        "queue",
                        "gui",
                        "shutdown",
                        "system",
                        "vad",
                        "model",
                        "cache",
                        "stream",
                        "plugin",
                        "network",
                        "memory",
                    ],
                )
            else:
                normalized.append(item)
        args.debug = normalized

    return args


def main() -> int:
    """Zentraler Einstiegspunkt des Dragon Whisperer."""
    import atexit
    import sys
    import threading
    import tkinter as tk
    from contextlib import suppress

    import urllib3

    global _EXIT_IN_PROGRESS_EVENT
    _EXIT_IN_PROGRESS_EVENT = threading.Event()

    def _early_log_debug(msg: str, *args) -> None:
        try:
            if int(globals().get("DEBUG_LEVEL", 0) or 0) >= 3:
                import logging as _logging

                _logging.getLogger("dragon").debug(msg, *args)
        except Exception:
            pass

    def _early_log_warning(msg: str, *args) -> None:
        try:
            if int(globals().get("DEBUG_LEVEL", 0) or 0) >= 2:
                import logging as _logging

                _logging.getLogger("dragon").warning(msg, *args)
        except Exception:
            pass

    _early_log_debug("urllib3 version: %s", urllib3.__version__)

    def filter_kwargs(kwargs):
        kwargs.pop("key_threadpool", None)
        kwargs.pop("threadpool", None)
        kwargs.pop("_pool", None)
        return kwargs

    try:
        import urllib3.connectionpool
        import urllib3.poolmanager

        orig_http_init = urllib3.connectionpool.HTTPConnectionPool.__init__

        def patched_http_init(self, *args, **kwargs):
            filter_kwargs(kwargs)
            orig_http_init(self, *args, **kwargs)

        urllib3.connectionpool.HTTPConnectionPool.__init__ = patched_http_init

        if hasattr(urllib3.connectionpool, "HTTPSConnectionPool"):
            orig_https_init = urllib3.connectionpool.HTTPSConnectionPool.__init__

            def patched_https_init(self, *args, **kwargs):
                filter_kwargs(kwargs)
                orig_https_init(self, *args, **kwargs)

            urllib3.connectionpool.HTTPSConnectionPool.__init__ = patched_https_init

        orig_pool_init = urllib3.poolmanager.PoolManager.__init__

        def patched_pool_init(self, *args, **kwargs):
            filter_kwargs(kwargs)
            orig_pool_init(self, *args, **kwargs)

        urllib3.poolmanager.PoolManager.__init__ = patched_pool_init

        if hasattr(urllib3.poolmanager, "ProxyManager"):
            orig_proxy_init = urllib3.poolmanager.ProxyManager.__init__

            def patched_proxy_init(self, *args, **kwargs):
                filter_kwargs(kwargs)
                orig_proxy_init(self, *args, **kwargs)

            urllib3.poolmanager.ProxyManager.__init__ = patched_proxy_init

        if hasattr(urllib3.connectionpool, "PoolKey"):
            orig_poolkey_new = urllib3.connectionpool.PoolKey.__new__

            def patched_poolkey_new(cls, *args, **kwargs):
                filter_kwargs(kwargs)
                return orig_poolkey_new(cls, *args, **kwargs)

            urllib3.connectionpool.PoolKey.__new__ = staticmethod(patched_poolkey_new)

        _early_log_debug("✅ urllib3-Patches erfolgreich angewendet")
    except Exception as e:
        _early_log_warning("⚠️ urllib3-Patch fehlgeschlagen: %s", e)

    try:
        apply()
        _early_log_debug("✅ apply()-Patch zusätzlich ausgeführt")
    except Exception as e:
        _early_log_warning("⚠️ apply()-Patch fehlgeschlagen: %s", e)

    _setup_early_environment()
    args = parse_arguments()

    global DEBUG_LEVEL, DEBUG_COMPONENTS, QUIET_MODE
    debug_level, debug_components = extract_debug_info(args)
    DEBUG_LEVEL = debug_level
    DEBUG_COMPONENTS = debug_components
    QUIET_MODE = args.quiet

    original_excepthook = sys.excepthook

    def custom_excepthook(t, v, tb):
        try:
            _global_crash_handler(t, v, tb, DEBUG_LEVEL)
        except Exception:
            original_excepthook(t, v, tb)

    sys.excepthook = custom_excepthook

    startup_config = StartupConfig(
        debug_level=DEBUG_LEVEL,
        debug_components=DEBUG_COMPONENTS,
        quiet=QUIET_MODE,
        headless=args.headless,
        url=args.url,
        profile=args.profile,
        model=args.model,
        language=args.language,
        benchmark=args.benchmark,
        safe_mode=args.safe_mode,
        repair_config=args.repair_config,
        check_gpu=args.check_gpu,
        crash_report=True,
        startup_timeout=30.0,
        shutdown_timeout=15.0,
    )

    if args.version:
        _print_version()
        return 0

    if args.sysinfo:
        _log_debug_welcome_info(DEBUG_LEVEL, True, QUIET_MODE)
        return 0

    if "--ai-help" in sys.argv:
        return 0

    if args.check_gpu:
        ok, msg = _check_gpu_health()
        print(f"GPU Health: {msg}")
        return 0 if ok else 1

    if args.benchmark:
        _run_benchmark()
        return 0

    if args.repair_config:
        repairs = _repair_configuration()
        print("Repairs performed:", ", ".join(repairs) if repairs else "None")
        return 0

    if args.check:
        try:
            PlatformUtils.check_platform_dependencies()
            return 0
        except RuntimeError:
            return 1

    if args.test:
        return run_tests()

    configure_logging(DEBUG_LEVEL, DEBUG_COMPONENTS, QUIET_MODE)
    PlatformUtils.setup_platform_environment()

    repairs = _validate_and_repair_environment(DEBUG_LEVEL)
    if repairs and DEBUG_LEVEL >= 1:
        logger.info("🔧 Umgebungsreparaturen: %s", ", ".join(repairs))

    if not hasattr(sys, "_loky_cleanup_registered"):
        atexit.register(_perform_loky_cleanup)
        sys._loky_cleanup_registered = True

    exit_code = 0
    gui_instance = None
    early_return = False

    try:
        if args.headless or args.url:
            exit_code = _run_headless(args, startup_config)
        else:
            if DEBUG_LEVEL >= 3:
                logger.debug("🚀 main: Starte GUI mit Fallbacks...")
            gui_instance = _run_gui_with_fallbacks(startup_config)

            if gui_instance is not None and hasattr(gui_instance, "root"):
                gui_instance._exit_requested = False

                def is_real_exit(gui_obj) -> bool:
                    """Prüft, ob ein echter Exit gewünscht ist.

                    Wird von den `root.quit` / `root.destroy`-Patches
                    verwendet, um zwischen echtem Beenden und
                    versehentlichem Aufruf zu unterscheiden.
                    """
                    global _EXIT_IN_PROGRESS_EVENT
                    import traceback

                    if _EXIT_IN_PROGRESS_EVENT.is_set():
                        return True
                    if getattr(gui_obj, "_exit_requested", False):
                        return True
                    if getattr(gui_obj, "_shutting_down", False):
                        return True
                    controller = getattr(gui_obj, "controller", None)
                    if controller is not None:
                        if getattr(controller, "_shutting_down", False):
                            return True
                        if getattr(controller, "_exit_requested", False):
                            return True
                    ap = getattr(gui_obj, "audio_processor", None)
                    if ap is not None:
                        if getattr(ap, "_shutting_down", False):
                            return True
                        if getattr(ap, "_exit_requested", False):
                            return True
                    try:
                        stack = traceback.extract_stack()
                        current_file = __file__
                        for frame in stack:
                            if (
                                frame.name in ("_destroy_root", "_direct_shutdown")
                                and frame.filename == current_file
                            ):
                                return True
                    except Exception:
                        pass
                    return False

                if DEBUG_LEVEL >= 3:
                    original_quit = gui_instance.root.quit

                    def no_quit():
                        if is_real_exit(gui_instance):
                            gui_instance._exit_requested = False
                            if hasattr(gui_instance, "_shutting_down"):
                                gui_instance._shutting_down = False
                            original_quit()
                        else:
                            logger.critical("🔥 root.quit() blockiert! (Debug-Patch)")

                    gui_instance.root.quit = no_quit

                    original_destroy = gui_instance.root.destroy

                    def no_destroy():
                        if is_real_exit(gui_instance):
                            gui_instance._exit_requested = False
                            if hasattr(gui_instance, "_shutting_down"):
                                gui_instance._shutting_down = False
                            original_destroy()
                        else:
                            logger.critical(
                                "🔥 root.destroy() blockiert! (Debug-Patch)",
                            )

                    gui_instance.root.destroy = no_destroy
                    logger.warning(
                        "✅ root.quit/destroy-Patches aktiviert (Debug-Modus)",
                    )

                    if DEBUG_LEVEL >= 4:

                        def patched_sys_exit(code=0):
                            import traceback

                            logger.critical(
                                "🔥 sys.exit(%s) AUFRUFEN! Stacktrace:\n%s",
                                code,
                                "".join(traceback.format_stack()),
                            )

                        sys.exit = patched_sys_exit

                        def patched_os_exit(code=0):
                            import traceback

                            logger.critical(
                                "🔥 os._exit(%s) AUFRUFEN! Stacktrace:\n%s",
                                code,
                                "".join(traceback.format_stack()),
                            )

                        os._exit = patched_os_exit
                        logger.warning(
                            "✅ sys.exit/os._exit-Patches aktiviert (Debug Level 4)",
                        )

            if DEBUG_LEVEL >= 3:
                logger.debug(
                    "✅ main: GUI-Instanz erhalten: %s",
                    gui_instance is not None,
                )

    except KeyboardInterrupt:
        logger.info("\n🛑 Programm durch Benutzer unterbrochen")
        exit_code = 130

    except SystemExit as e:
        exit_code = e.code if isinstance(e.code, int) else 0
        if DEBUG_LEVEL >= 3:
            logger.debug(
                "⚠️ main: SystemExit abgefangen, Exit-Code: %d",
                exit_code,
            )

    except (OSError, RuntimeError, tk.TclError):
        logger.exception("💥 Schwerer Fehler")
        exit_code = 2

    except Exception:
        logger.exception("💥 Unerwarteter Fehler")
        exit_code = 1

    finally:
        if gui_instance is not None:
            try:
                root_exists = gui_instance.root.winfo_exists()
                if DEBUG_LEVEL >= 3:
                    logger.debug(
                        "🧹 main: Hauptfenster existiert: %s",
                        root_exists,
                    )
                if root_exists:
                    logger.debug(
                        "🔄 main: GUI läuft noch – überspringe Shutdown",
                    )
                    early_return = True
            except (tk.TclError, AttributeError):
                pass

        if not early_return:
            _EXIT_IN_PROGRESS_EVENT.clear()

            if gui_instance is not None:
                with suppress(Exception):
                    shutting_down = getattr(gui_instance, "_shutting_down", False)
                    if DEBUG_LEVEL >= 3:
                        logger.debug(
                            "🧹 main: finally-Block – _shutting_down=%s",
                            shutting_down,
                        )
                    if shutting_down:
                        gui_instance._direct_shutdown()
                        if DEBUG_LEVEL >= 3:
                            logger.debug(
                                "🛑 main: _direct_shutdown() aufgerufen",
                            )
                    elif DEBUG_LEVEL >= 3:
                        logger.debug(
                            "🔄 main: Nur Ressourcenbereinigung",
                        )
            elif DEBUG_LEVEL >= 3:
                logger.debug(
                    "🧹 main: gui_instance ist None – überspringe GUI-Shutdown",
                )

            if DEBUG_LEVEL >= 3:
                logger.debug(
                    "🧹 main: Führe garantierte Ressourcenbereinigung durch...",
                )

            _perform_guaranteed_cleanup(
                timeout=startup_config.shutdown_timeout,
                gui=gui_instance,
            )
            with suppress(Exception):
                _perform_loky_cleanup()

            if DEBUG_LEVEL >= 3:
                logger.debug(
                    "✅ main: Finale Bereinigung abgeschlossen.",
                )

    if early_return:
        return exit_code
    return exit_code


def _force_loky_cleanup_atexit() -> None:
    """Ultimative Notfall-Bereinigung des loky-Executors beim Programmende."""
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
            if DEBUG_LEVEL >= 1:
                print("🧹 Loky-Executor via atexit bereinigt.")
    except (ImportError, AttributeError, OSError) as e:
        if DEBUG_LEVEL >= 1:
            print(f"⚠️ Loky-atexit-Cleanup fehlgeschlagen: {e}")


atexit.register(_perform_loky_cleanup)


def _debug_active_executors():
    import sys
    import threading

    for mod_name, mod in sys.modules.items():
        if hasattr(mod, "_reusable_executor"):
            print(f"Found executor in {mod_name}: {mod._reusable_executor}")
    for t in threading.enumerate():
        if "loky" in t.name or "joblib" in t.name:
            print(f"Active thread: {t.name} (daemon={t.daemon})")


if __name__ == "__main__":
    try:
        if "__file__" in globals():
            script_dir = os.path.dirname(os.path.abspath(__file__))
            if os.getcwd() != script_dir:
                os.chdir(script_dir)
                if DEBUG_LEVEL >= 1:
                    logger.debug("📁 Working directory set to: %s", script_dir)
    except (OSError, RuntimeError) as e:
        logger.debug(
            "Ignored exception while setting working directory: %s",
            e,
            exc_info=True,
        )
    ret = main()
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
    except (ImportError, AttributeError, OSError) as e:
        if DEBUG_LEVEL >= 1:
            logger.warning("⚠️ Loky‑Cleanup fehlgeschlagen: %s", e)
        else:
            logger.debug("Loky‑Cleanup fehlgeschlagen: %s", e, exc_info=True)
    sys.exit(ret)
